local config = {
  str_voice_1200501_1 = "เลิกบ่นได้แล้ว พี่ชาย! น่ารำคาญเหมือนปี่ของคอนนอลลีไม่มีผิด...",
  str_voice_1200501_2 = "ความรุนแรงในอัมบราตันเป็นไปตามกฎของมันเอง ซึ่งแตกต่างจาก \"เกมที่ยุติธรรม\" ที่คนชั้นสูงเล่น เหมือนอย่างที่หมาป่าเงาเคยกล่าวไว้ก่อนหน้านี้ จะยังไงก็ช่างเถอะ",
  str_voice_1200501_3 = "ฉันเกลียดความรุนแรง แต่ก็อดไม่ได้ที่จะอัดพวกที่ชอบขายแบล็กกอฮอล์ให้เด็กที่ยังไม่บรรลุนิติภาวะ",
  str_voice_1200501_4 = "ฉันชอบไปคลุกโคลนแถวอัมบราตันเหมือนกัน แต่ฉันลืมวันเลวร้ายพวกนั้นไปหมดแล้วล่ะ ตอนนี้ฉันแค่อยากสร้างบ้านเกิดของฉันขึ้นมาใหม่เท่านั้น",
  str_voice_1200501_5 = "เกาะเขี้ยวฉลามคือบ้านเกิดของฉัน ฉันไม่ยอมให้พวกอิคลิพไซท์มาทำลายบ้านเกิดหรอก",
  str_voice_1200501_7 = "เราฝ่าฟันอุปสรรคมาด้วยกัน ถ้าไม่นับว่าเป็นพี่เป็นน้องกันแล้วจะเป็นอะไรได้อีก หรือจะให้หาแมวมาเลี้ยงล่ะ",
  str_voice_1200501_8 = "ตอนฉันทำตัวหุนหันก็ต้องห้ามฉันสิ! ต่อยสันกรามคนอื่นไม่ใช่เรื่องใหญ่หรอก แต่มันจะกลายเป็นเรื่องใหญ่ถ้าดันไปสร้างศัตรูไว้มากเกินไป",
  str_voice_1200501_9 = "ฉันชอบแมวนะ แต่ฉันไม่ชอบแมวที่หน้าตาเหมือนชายวัยกลางคน เข้าใจป่ะ เพราะฉะนั้นอย่าบังคับให้ฉันต้องไปทำงานกับหมอนั่นอีกเชียว",
  str_voice_1200501_10 = "อ้า! ได้เวลาพักผ่อนมาเฉยเลย พักกันหน่อยดีไหม บอส ฉันมีกลุ่มแมวที่บ้านอยู่นะ ถ้าไม่ว่าอะไร ไปกับฉันไหมเอ่ย",
  str_voice_1200501_11 = "ขอปัดขนแมวออกจากตัวสักหน่อย แล้วฉันจะยิ้มกว้าง ๆ ให้นะ ก็บอกแล้วไง ฉันน่ะ รักความสงบสุด ๆ",
  str_voice_1200501_12 = "ชีวิตนี้มีอะไรต้องสู้อีกเยอะ...",
  str_voice_1200501_13 = "บอส เห็นแมวฉันไหม มันค่อนข้างขี้อายแล้วฉันก็ไม่รู้ว่ามันไปซ่อนตัวที่ไหนแล้ว",
  str_voice_1200501_14 = "อยากได้ผงเขี้ยวฉลามมาปรุงรสไหม ฉันเพิ่งได้ผงชุดใหม่มาแล้วก็ยังมีอีกเหลือเฟือเลย",
  str_voice_1200501_15 = "บอส วันนี้วันเกิดเหรอ เดี๋ยวฉันจะเต้นระบำเลื่อยฉลองวันเกิดให้!",
  str_voice_1200501_16 = "ไม่มีอะไรทำนี่มันน่าเบื่อชะมัด... ถ้าเกิดฉันมีแมวละก็...",
  str_voice_1200501_17 = "อ้าว เห็นเขี้ยวฉันด้วยเหรอ ไม่ได้ตั้งใจทำให้กลัว ขอโทษทีนะ",
  str_voice_1200501_18 = "ฉันว่าถึงเวลาพาเจ้าแมวทั้งหลายมาออกกำลังกายแล้ว!",
  str_voice_1200501_19 = "กินอะไรเป็นมื้อเย็นดีนะ เฟรนช์ฟรายส์หรือคาพูนส์ดี",
  str_voice_1200501_20 = "เกาะเขี้ยวฉลามอาจเป็นเกาะเล็ก ๆ แต่มันก็เป็นของฉัน ไม่ได้เป็นของลูโมโพลิสหรืออิลลูมินา",
  str_voice_1200501_21 = "กฎเดียวของอัมบราตันคือไม่มีกฎใด ๆ ณ ที่แห่งนั้น คนที่นั่นเป็นพวกหัวรุนแรงมาก...",
  str_voice_1200501_22 = "สร้างเกาะเขี้ยวฉลามขึ้นมาใหม่!",
  str_voice_1200501_23 = "ถ้าฉันเจอหัวหน้าของอิคลิพไซท์ ฉันจะต้อนรับพวกมันด้วยเลื่อยของฉันเอง",
  str_voice_1200501_24 = "หากไม่มีอีสต์วาน สุดท้ายแล้วอัมบราตันก็จะกลายเป็นห้วงความรุนแรงที่แสนอันตราย",
  str_voice_1200501_25 = "กิลด์เหนือเมฆทำให้ฉันสร้างบ้านเกิดขึ้นมาใหม่ได้อีกครั้ง แต่เลดี้บอสเป็นแม่ค้าที่ไม่มีหลักการอะไรทั้งนั้นจริง ๆ...",
  str_voice_1200501_26 = "ซุปผักของโปรดของฉันใส่น้ำมะขามและขนมปังไร้เชื้อล่ะ!",
  str_voice_1200501_27 = "คนที่ระบายอารมณ์ด้วยความรุนแรงอย่างไร้ความหมายเป็นที่น่ารังเกียจที่สุด บางทีคนพวกนั้นอาจกลายเป็นอิคลิพไซท์แล้วก็ได้!",
  str_voice_1200501_28 = "มันบินได้จริง ๆ แฮะ! ของโบราณพวกนี้สุดยอดไปเลย",
  str_voice_1200501_29 = "โว้ว! บอสของโคลอสซัสนี่ ที่นี่คนเพียบเลย จะสู้กันหรือยังไง อย่าเพิ่งสิ ฉันเพิ่งมาวันแรกเองนะ",
  str_voice_1200501_30 = "ฉันหวังว่าจะไม่มีโอกาสได้ใช้พลังนี้",
  str_voice_1200501_31 = "เลื่อยของฉัน พวกมันหมุนเร็วกว่าแต่ก่อนอีกนะ!",
  str_voice_1200501_32 = "เลื่อยศัตรูของเราให้ขาดกระจุยไปเลย!",
  str_voice_1200501_34 = "ที่นี่คือชมรมคนรักแมวหรือเปล่า",
  str_voice_1200501_35 = "อย่างนี้ถือว่าเป็นการป้องกันตัวที่เหมาะสมแล้ว",
  str_voice_1200501_36 = "หวังว่าพวกแมวจะซ่อนตัวได้ทันเวลา",
  str_voice_1200501_37 = "หมุน!",
  str_voice_1200501_38 = "เลื่อยทุกอย่างให้เป็นเสี่ยง ๆ!",
  str_voice_1200501_39 = "แหลกซะ!",
  str_voice_1200501_40 = "เตรียมตัวโดนเลื่อยได้เลย!",
  str_voice_1200501_41 = "ใครน่ะ ใครผลักฉัน!",
  str_voice_1200501_42 = "พวกมันมีฝีมือแค่นี้เอง?",
  str_voice_1200501_43 = "ขอโทษทีนะ ฉันต้องไปแล้ว ลาก่อน!",
  str_voice_1200501_44 = "นึกว่าเป็นเวลาพักของฉันเสียอีก... ไม่เป็นไร ๆ ฉันเข้าใจ...",
  str_voice_1200501_45 = "ฉันว่าเธอเข้าใจคำว่าน่ารักผิดไปแล้วล่ะ",
  str_voice_1200501_46 = "เฮ้! เธอก็ชอบเหมือนกันเหรอ ไม่นะ ช่างมันเถอะ...",
  str_voice_1200501_47 = "หืม... น่าจะแพงอยู่นะ ฉันจะรับไว้ก่อนแล้วกัน",
  str_voice_1200501_48 = "เอ้อ ฉันเอานี่ไปให้แมวได้นี่นา! ขอบใจนะ",
  str_voice_1200501_49 = "อย่าสร้างปัญหา ไม่งั้นฉันจะคิดบัญชีกับเธอ โดยเฉพาะอย่ามาแตะต้องลูก ๆ ของฉันเชียว ไม่อย่างนั้น... มิมิ ไม่ต้องกลัว มาหาปะป๊ามา!",
  str_voice_1200501_50 = "เห็นฉันเมื่อไหร่ก็อย่าตกใจแล้วกัน ผู้คนมากมายในบ้านเกิดของฉันล้วนมีหัวฉลามเหมือนฉันนี่แหละ! แต่นั่นมันก่อนที่อิคลิพไซท์จะแทรกซึมเข้ามาตามชายแดนน่ะนะ... *ถอนหายใจ*",
  str_voice_1200501_52 = "Alchemy Stars เหรอ มันคืออะไรน่ะ...",
  str_voice_1200501_53 = "เฮ้ พี่ชาย!",
  str_voice_1200501_54 = "อ่า... อรุณสวัสดิ์!",
  str_voice_1200501_55 = "ตอนนี้กี่โมงแล้ว",
  str_voice_1200501_56 = "ค่ำคืนนี้เพิ่งเริ่มต้นขึ้นเท่านั้น!",
  str_voice_1200501_57 = "ฮ่า ๆ! ดีเลย ปีใหม่อีกแล้วสินะ",
  str_voice_1300471_1 = "อาจารย์ฮิอิโระพูดถูก คนอย่างเธอก็ \"คง\" มาที่แบบนี้ด้วยตัวเองอยู่แล้ว!",
  str_voice_1300471_2 = "ผู้บัญชาการกองทัพเคยพูดไว้ว่าเธอเป็นคนอ่อนโยน ไม่หรอก ต้องไม่ใช่อาจารย์ฮิอิโระแน่ ฉันไม่เชื่อ... ฮ่า ๆ... อ่ะแฮ่ม ขอโทษทีนะ...",
  str_voice_1300471_3 = "ควาร์เคียมเป็นสิ่งที่ไม่ได้อยู่ในโลกนี้แต่แรก เหมือนไข่มุกที่ถูกคลื่นพัดขึ้นฝั่งไม่ผิดเพี้ยน",
  str_voice_1300471_4 = "ฉันรู้สึกได้ถึงความกระสับกระส่ายของประตูอีกฝั่งหนึ่ง... ดีมากเลย ฉันจะใช้ประโยชน์จากพวกนั้นซะ",
  str_voice_1300471_5 = "สุดท้ายแล้วฉันจะทำให้มันเป็นส่วนหนึ่งกับตัวฉันได้ไหมนะ ควาร์เคียมพร้อมแล้ว แต่ฉันน่ะ...",
  str_voice_1300471_6 = "พลังเต็มขั้นที่ควาร์เคียมปล่อยออกมาช่างน่าเกรงกลัวยิ่งนัก แต่ฉันไม่มีทางเลือกอื่นแล้ว ฉันต้องเรียนรู้วิธีควบคุมมันให้ได้อย่างสมบูรณ์",
  str_voice_1300471_7 = "เธอต้องการอะไรงั้นเหรอ ฉันอาจจะช่วยได้นะ... ถ้าไม่อย่างนั้นฉันจะลองไปขอให้วิเวียนช่วย?",
  str_voice_1300471_8 = "ฉันรู้ว่าตอนนี้เธอรู้สึกยังไง และหลังจากวันนี้ทุกอย่างจะกลับสู่ปกติ แต่ว่านะ ฉันจะไม่มีวันยอมแพ้หรอก!",
  str_voice_1300471_9 = "หลังกลับมายังโลกนี้ ฉันก็นึกขึ้นได้ว่าฉันไม่เหมือนเดิมอีกต่อไปแล้ว... สายตาที่จอมทัพมองฉันก็ดูแปลกไปนิดหน่อย...",
  str_voice_1300471_10 = "บางครั้งฉันก็หลงใหลในทางช้างเผือกนะ บางทีควาร์เคียมอื่น ๆ อาจจะโผล่พรวดออกมาก็ได้",
  str_voice_1300471_11 = "ฉันไม่เคยทำอย่างนี้มาก่อนแต่ก็จะพยายามสุดความสามารถ",
  str_voice_1300471_12 = "การค้นคว้าและการต่อสู้เกี่ยวข้องกันอยู่บ่อยครั้ง อุ๊ย! ...ลืมไปว่าเธอสู้ไม่ได้นี่นะ",
  str_voice_1300471_13 = "ห้ามแตะต้องสิ่งนี้ เพราะว่ามันจะทำให้เสียการควบคุมควาร์เคียมไปง่าย ๆ เลย ถ้ามันเริ่มสั่นคลอนเพราะเธอละก็...",
  str_voice_1300471_14 = "ถึงฉันจะไม่ใช่ผู้เชี่ยวชาญเรื่องโคลอสซัส แต่เธอแน่ใจเหรอว่าวงจรตรงนี้มันต่อกันอย่างถูกต้องแล้วน่ะ",
  str_voice_1300471_15 = "สุขสันต์วันเกิด ผู้บัญชาการกองทัพบอกฉันว่าเป็นวันเกิดเธอ!",
  str_voice_1300471_16 = "วันนี้มีงานวิจัยอะไรจะมอบหมายให้ฉันไหม ถ้าเกี่ยวข้องกับผู้บัญชาการกองทัพด้วยก็จะเยี่ยมยอดไปเลย",
  str_voice_1300471_17 = "เพิ่งตื่นเหรอ หรือว่าเธอยังไม่นอน",
  str_voice_1300471_18 = "คนที่ยังทำงานอยู่ตอนนี้เป็นสหายที่ดีของอิลลูมินา ถ้าไม่ทำงานก็ไปให้พ้นเลย...",
  str_voice_1300471_19 = "เธอมาดูดาวงั้นเหรอ ดาวเทียบกับควาร์เคียมของฉันไม่ได้หรอก!",
  str_voice_1300471_20 = "เราเชื่อว่าสิ่งที่อิลลูมินาทำนั้นเป็นสิ่งที่ถูกต้องสำหรับมวลมนุษยชาติ",
  str_voice_1300471_21 = "เรดีเซล เวรนช์... เราไม่มีอะไรเกี่ยวข้องกับพวกเขาเลย อย่างน้อยผู้บัญชาการกองทัพก็เป็นคนบอกว่าอย่างนั้น",
  str_voice_1300471_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1300471_23 = "พวกมันอันตรายมากแต่ควาร์เคียมก็ไม่สนใจสักนิด มันจะฝังพวกนั้นให้เรียบเลยละ",
  str_voice_1300471_24 = "นี่เธอจะบอกว่าฮิอิโระ... ผู้บัญชาการกองทัพดูแลเทคแคร์ลูกน้อง... โอ๊ย! แก้มฉันแดงจะแย่แล้ว",
  str_voice_1300471_25 = "ไวซ์ไม่มีทางทำเรื่องให้เราผิดหวังหรอก",
  str_voice_1300471_26 = "นางเข้มงวดมากแต่บางครั้งก็อ่อนโยน... อะไรนะ ไม่ได้ถามฉันเรื่องอาจารย์ฮิอิโระหรอกเหรอ",
  str_voice_1300471_27 = "อย่าถามเรื่องไวซ์กับอัมบราตัน หมายเลข 3 ไปมั่วซั่วล่ะ ผู้บัญชาการกองทัพจะโกรธเอาถ้านางรู้เข้า",
  str_voice_1300471_28 = "เรามีพลังใหม่ที่ใช้งานได้ไหม",
  str_voice_1300471_29 = "ที่นี่มีอะไรคุ้มค่าน่าเรียนไหม ไม่เห็นเข้าท่าเลยที่อิลลูมินาส่งฉันมาที่นี่... น-นอกเสียจากว่าอาจารย์ฮิอิโระจะอยู่ที่นี่นะ...",
  str_voice_1300471_30 = "ฉันสัมผัสได้ถึงแบล็กโนว่าใหม่!",
  str_voice_1300471_31 = "ประตูสู่ทะเลแห่งความตายเปิดขึ้นแล้ว",
  str_voice_1300471_32 = "ฉันจะถือว่าเป็นภาระของควาร์เคียม ฉันจะควบคุมพวกมันทั้งหมด!",
  str_voice_1300471_33 = "ฉันพร้อมแล้ว...",
  str_voice_1300471_34 = "ทุกคนพร้อมไหม",
  str_voice_1300471_35 = "ควาร์เคียมชาร์จเต็มแล้ว!",
  str_voice_1300471_36 = "พลังของฉันเป็นที่ต้องการในตอนนี้!!",
  str_voice_1300471_37 = "ควาร์เคียม อวยพรให้สหายของเราด้วย!",
  str_voice_1300471_38 = "หลอมละลายการโจมตีของยุคสมัยแห่งความมืดมิดซะ!",
  str_voice_1300471_39 = "ควาร์เคียม!",
  str_voice_1300471_40 = "หิมะดำ!",
  str_voice_1300471_41 = "ควาร์เคียมกำลังนำทางเรา!",
  str_voice_1300471_42 = "ฟู่ อาจารย์ฮิอิโระดูอยู่หรือปล่า",
  str_voice_1300471_43 = "ตามคาด ฉันทำตามที่นางคาดหวังไว้ไม่สำเร็จ...",
  str_voice_1300471_44 = "คนพวกนี้เลือกโคลอสซัสหรือเลือกเธอกันแน่",
  str_voice_1300471_45 = "โซยาชอบของขวัญของเธอ มันเหมือนของที่เธอเลือกมาแบบสุ่ม",
  str_voice_1300471_46 = "ฉันจะเอาไปให้อาจารย์ฮิอิโระ นางต้องชอบมากแน่!!",
  str_voice_1300471_47 = "นั่นสินะ เธอนี่เป็นคนที่โอบอ้อมอารีเสียจริง",
  str_voice_1300471_48 = "โอ๊ะ ฉันนึกไม่ถึงเลย... ข-ขอบใจนะ",
  str_voice_1300471_49 = "ทะเลแห่งความตายสวยงาม แต่มันก็เป็นสถานที่อันเดียวดาย หากไม่ใช่เพราะฮิอิโระ ฉันคงต้องตัวเปียกซกอยู่ที่นั่นตลอดกาลจนกว่าจะจมน้ำตาย นางเป็นเหมือนแสงสว่างที่ส่องกระจ่างในยามค่ำคืน หรือไม่ก็เหมือนดอกซากุระที่เบ่งบานกลางฤดูหนาว...",
  str_voice_1300471_50 = "ถ้าเป็นไปได้ฉันก็อยากสำรวจความลับของยมโลกด้วยควาร์เคียมเพราะโลกวิญญาณก็เคยเป็นเหมือนเรา บางทีเสียงร้องที่ได้ยินจากเมฆหมอกอาจเป็นเบาะแสเดียวที่เหลืออยู่ของเราก็ได้",
  str_voice_1300471_52 = "Alchemy...Stars",
  str_voice_1300471_53 = "เกิดเรื่องขึ้นแล้ว!",
  str_voice_1300471_54 = "ราตรีสวัสดิ์นะ... เอ่อ ไม่สิ อรุณสวัสดิ์",
  str_voice_1300471_55 = "สวัสดียามบ่าย เห็นอาจารย์ฮิอิโระบ้างไหม",
  str_voice_1300471_56 = "คราวนี้สายัณห์สวัสดิ์ของจริง!",
  str_voice_1300471_57 = "ก็ได้ สุขสันต์วันปีใหม่นะ!",
  str_voice_1300511_1 = "- ฉันดูดุร้ายเหรอ อืม สายตาของฉันทั้งยาวทั้งแหลมคม เอาไว้มองหาเหยื่ออันโอชะไงล่ะ\n- จิ๊บ จิ๊บ จิ๊บ!",
  str_voice_1300511_2 = "- โอ้...\n- เงียบเลย อย่ามากวนฉันตอนฉันตรวจกระสุนสิ ไม่อย่างนั้นได้มีชื่อนายสลักบนกระสุนนั่นแน่\n- จิ๊บ",
  str_voice_1300511_3 = "อย่าเอาฉันไปเทียบกับตัวตลกสองตัวนั่นนะ ลองโยนพวกมันเข้าไปในเมืองหลวงเก่าแล้วลองดูสิว่าจะมีชีวิตอยู่ได้นานเท่าไหร่ พวกซื่อบื้อ!",
  str_voice_1300511_4 = "- ฉันต้องดูแลเพื่อนซี้สุดรักของฉันน่ะ... - เพื่อนซี้สุดรักเหรอ\n- จุ๊ ฉันขัดปืนอยู่",
  str_voice_1300511_5 = "- เราต้องมีเป้าไว้ฝึกเล็งนะ อยากเป็นเป้าให้ฉันไหม\n- แต่ถ้านายทำฉันเจ็บล่ะ\n- เอ่อ นายก็ว่ามาสิ\n- ไร้ความรับผิดชอบชะมัด!",
  str_voice_1300511_7 = "ฉันไม่ได้มองสาวน้อยพวกนั้นนะ ในฐานะมือปืนอาชีพ เป็นไปไม่ได้ที่จะสติหลุดเพราะแค่มองสาว!!",
  str_voice_1300511_8 = "- ถ้าได้คู่หูเป็นสาวสวยตัวสูง ๆ ก็คงจะดีไม่น้อย\n- หนอย พูดว่าไงนะ จิ๊บ!",
  str_voice_1300511_9 = "ฉันคือมือปืนที่ไร้ความปรานีและไม่มีทางทิ้งร่องรอยไว้เบื้องหลังแบบนั้น เข้าใจไหม เป็นความผิดหมอนี่ทั้งหมดเลย",
  str_voice_1300511_10 = "ถ้าเธอไม่ว่าง งั้นก็ให้เราจัดของเองดีไหม",
  str_voice_1300511_11 = "ฉันต้องยิ้มไหม ยิ้มแล้วอาจทำให้เธอกลัวได้นะ แต่เอ๊ะ ช่างเถอะ ถ้าได้ค่าจ้างก็แล้วไป",
  str_voice_1300511_12 = "มองมุมนั้นแล้วฉันเท่ไม่หยอกเลยใช่ไหมล่ะ เป็นภาพแสนเพอร์เฟกต์ของทหารรับจ้างผู้ใจเย็นเลยเนอะ",
  str_voice_1300511_13 = "- มาเล่นเกมกัน คนแพ้จะกลายเป็นมื้อเย็นคืนนี้\n- ล้อกันเล่นใช่ไหม",
  str_voice_1300511_14 = "ที่นี่ห้ามสูบบุหรี่เหรอ แล้วไงต่อ นายอาจโดนแล่หนังไปทำกระเป๋าโทษฐานสะเออะนะ ไอ้หนู",
  str_voice_1300511_15 = "วันเกิดเหรอ สุขสันต์วันเกิดแล้วกัน จระเข้ยิ้มแล้วเธอจะกลัวไหม",
  str_voice_1300511_16 = "เควสต์ใหม่เหรอ",
  str_voice_1300511_17 = "งานน่าเบื่อ",
  str_voice_1300511_18 = "คุณภาพอากาศแย่! แค่ก จิ๊บ",
  str_voice_1300511_19 = "ไปได้แล้ว โคลอสซัสเป็นของเราแล้ว",
  str_voice_1300511_20 = "- คนโหวกเหวกเยอะเกินไป จนบางครั้งก็อยากยิงพวกมันให้ตายหมดเลย\n- เอ่อ... จิ๊บ!",
  str_voice_1300511_21 = "ถ้าเรื่องระเบิดละก็ อันที่ได้มาจากอิลลูมินาน่ะเจ๋งสุดแล้ว มันเบามาก แล้วเสียงก็ดังตู้มต้ามดี",
  str_voice_1300511_22 = "เจ้าตัวร้าย โจมตี!",
  str_voice_1300511_23 = "- ให้หนอนทรายกับพวกมันเลย\n- ให้ชิ้นเล็ก ๆ",
  str_voice_1300511_24 = "ขอให้โชคดีกับการทำให้เราเห็นด้วยกับเธอในเร็ววันนี้ล่ะ ยังไงเธอก็ยังห่างชั้นจากซินซานัก",
  str_voice_1300511_25 = "- คุมะกับเพนจี้ไม่ต้องใช้ปืนหรอกนะ เพราะอาวุธของพวกเขาคือการข่มขวัญ\n- อู้ว จิ๊บ!",
  str_voice_1300511_26 = "คราบจาระบี 10 ปีจุ่มในตะกอนปืนที่ติดมา 5 ปี... อร่อยเหาะ",
  str_voice_1300511_27 = "บ้าจริง ติดอีกแล้ว แย่ชะมัด!",
  str_voice_1300511_28 = "เรายิงแล้วระเบิดอิคลิพไซท์พร้อมมันเลยดีไหม!",
  str_voice_1300511_29 = "ฉันซอร์ค ส่วนนี่เบคค์ เราเพิ่งพนันกันไปว่าอิคลิพไซท์จะเขมือบเธอเมื่อไหร่ อยากลงพนันด้วยกันไหม",
  str_voice_1300511_30 = "พัฒนาความแม่นยำแล้ว!",
  str_voice_1300511_31 = "มาตกแต่งด้วยรูกระสุนสวย ๆ กันดีกว่า",
  str_voice_1300511_32 = "เป้านิ่งอีกกลุ่มสินะ",
  str_voice_1300511_34 = "คนที่คิดว่าการยิงปืนเป็นงานอดิเรกควรหลบไปซะ",
  str_voice_1300511_35 = "ล็อกเป้าหมาย",
  str_voice_1300511_36 = "อยู่ในตำแหน่ง",
  str_voice_1300511_37 = "ยิง!",
  str_voice_1300511_38 = "เข้าฝั่งหนึ่ง ทะลุอีกฝั่งหนึ่ง จิ๊บ!",
  str_voice_1300511_39 = "ตูม! ปัง!",
  str_voice_1300511_40 = "ตาเราแล้ว!",
  str_voice_1300511_41 = "มีใครใจไม่สู้บ้างไหม ตอนนี้เป็นโอกาสหนีเอาชีวิตรอดครั้งสุดท้ายแล้ว",
  str_voice_1300511_42 = "- เป็นไปตามคาดเลย\n- จิ๊บ ๆ!",
  str_voice_1300511_43 = "- เบคค์ มาหลบในกรามฉันเลย\n- ต้องไปแล้ว จิ๊บ!",
  str_voice_1300511_44 = "- เราต้องการเงินเดือนและห้ามขาดไปสักแดงด้วย\n- จิ๊บ!",
  str_voice_1300511_45 = "แค่นี้เองเหรอ",
  str_voice_1300511_46 = "อันนี้ดีแฮะ ฉันชอบ",
  str_voice_1300511_47 = "โว้ว คุ้มค่ากับเวลามาก",
  str_voice_1300511_48 = "ว้าว... ขอบใจมาก จิ๊บ!",
  str_voice_1300511_49 = "ไม่ต้องห่วงเรื่องกระสุนหมดก็ดีอยู่หรอก แต่บางครั้งฉันก็คิดถึงวันวานที่ระหกระเหินไปตามที่ดินรกร้างแล้วคอยเจรจากับพวกขูดเลือดขูดเนื้อนะ... เคล็ดลับการต่อรองเหรอ ไม่มีเคล็ดลับอะไรทั้งนั้น แค่ควักปืนมาวางบนโต๊ะก็เรียบร้อย",
  str_voice_1300511_50 = "- จะทำยังไงเมื่ออิคลิพไซท์กรูกันเข้ามาจนบังแสงอาทิตย์\n- ยิงพวกมันไง จิ๊บ! - ไม่ใช่ ก็ต้องภาวนาให้มีอิคลิพไซท์เพิ่มสิวะ เจ้านกโง่",
  str_voice_1300511_52 = [[
- Alchemy
- Stars! Stars! Stars!]],
  str_voice_1300511_53 = "สวัสดี จิ๊บ!",
  str_voice_1300511_54 = "จิ๊บ ๆ!",
  str_voice_1300511_55 = "ตื่นแล้วเหรอ",
  str_voice_1300511_56 = "เธอนอนแล้วเหรอ",
  str_voice_1300511_57 = "- ปีใหม่เหรอ งั้นสุขสันต์วันปีใหม่นะ\n- จิ๊บ!",
  str_voice_1300521_1 = "อ๊าาา ไม่นะ! ฉันสายแล้ว หรือโทรไปลาป่วยดีนะ คิดข้ออ้างอะไรดี ก่อนหน้านี้เคยบอกว่าปวดฟันไปแล้วด้วยสิ...",
  str_voice_1300521_2 = "รู้จักเอโฮะจากลูโมโพลิสไหม ถ้าฉันทำงานเป็นบ้าเป็นหลังเหมือนนาง สุดท้ายขนของฉันคงต้องร่วงจนหมดตัว ทำงานกับฝ่ายอิลลูมินาจัดการเวลาได้มากกว่าเยอะ!",
  str_voice_1300521_3 = "ฉันไม่ชอบถูกจับได้คาหนังคาเขา อย่ามาตามหาฉันอยู่ตลอดเวลาสิ ฉันรู้สึกผิดเหมือนกันนะ เข้าใจไหม",
  str_voice_1300521_4 = "พวกเธอจัดการได้ใช่ไหม ฉันพกผ้าห่มมาด้วย ขอนอนก่อนนะได้เปล่า",
  str_voice_1300521_5 = "มาแล้วจ้ะ หรือไม่มาดี คิดว่าฉันจะไปไหนล่ะ เฮ้ หยุดตีฉันได้แล้ว!",
  str_voice_1300521_7 = "หวังว่าสหภาพผู้ส่งสารจะให้เวลาพักแก่ฉันในการประเมินของปีนี้นะ!",
  str_voice_1300521_8 = "เดี๋ยวก่อน ฉันว่าฉันมีของให้เธอ... อ้าว คราวนี้หาของไม่เจอแฮะ ไว้คราวหน้าแล้วกัน",
  str_voice_1300521_9 = "ไง เธอมาอีกแล้วเหรอ ฉันคุยกับเธอได้ทั้งวันเลย ถ้าเธอไม่มาจิกให้ฉันทำงานน่ะนะ!",
  str_voice_1300521_10 = "ป็อปคอร์นกรุบกรอบ...",
  str_voice_1300521_11 = "หยุดเลย หยุด ฉันมีงานมากพออยู่แล้ว ฉันยังมีจดหมายนับไม่ถ้วนรอไปตอบอีกนะ!",
  str_voice_1300521_12 = "ไปล่ะนะ... เอ่อ กลับมาแล้ว... ไปของจริงละจ้ะ!",
  str_voice_1300521_13 = "เอ่อ... หัวหน้าของหลานที่เป็นญาติฉันถูกปรับเพราะลงทะเบียนข้อมูลผิดเมื่อวาน ดังนั้นจดหมายฉบับนี้...",
  str_voice_1300521_14 = "อ้า มีเรื่องด่วนมาล่ะ ฉันต้องไปแล้ว ไว้คราวหน้าแล้วกันนะ ขอโทษที!",
  str_voice_1300521_15 = "วันเกิดเหรอ โอ้ งั้นลาหยุดฉลองกันเถอะ!",
  str_voice_1300521_16 = "นี่ฉันมาถึงก่อนเธอเหรอ!",
  str_voice_1300521_17 = "สลิปเปอร์เหรอ ฉันไม่มีเวลาใส่หรอกนะ",
  str_voice_1300521_18 = "อ้า! ฉันไม่ได้อู้งานนะ",
  str_voice_1300521_19 = "เป็นเรื่องปกติที่จะต้องยืนหยัดสู้กับคนอวดดีและไม่ยอมทำตามกฎเกณฑ์!",
  str_voice_1300521_20 = "มีอิสระที่จะทำทุกสิ่งที่ฉันอยากทำเป็นเรื่องดีอยู่หรอก แต่มันไม่ได้ตังค์เนี่ยสิ...",
  str_voice_1300521_21 = "อิลลูมินาเป็นสถานที่แสนยุติธรรม! แค่ทุกคนเหมือนจะมีสามตา... แล้วก็ไม่ปล่อยให้อะไรหลุดรอดสายตาไปได้เลย...",
  str_voice_1300521_22 = "สหภาพผู้ส่งสาร! จดหมายทุกฉบับถึงปลายทางแน่นอน! ไม่งั้นก็...",
  str_voice_1300521_23 = "สู้กับพวกนั้นมันยุ่งยากเปล่า ๆ... ซ่อนตัวแล้วก็หนีกันเถอะ...",
  str_voice_1300521_24 = "เลดี้วิเวียนน่ะเหรอ เธอเยี่ยมสุด ๆ เจ๋งจริง ๆ...แต่ฉันไม่ค่อยวางใจนักหรอก...",
  str_voice_1300521_25 = "งานของเวนดี้เหนื่อยชะมัดยาก เพราะอย่างนี้หล่อนเลยกระตือรือร้นมากยังไงล่ะ เป็นฉันคงขอจรลีไปตั้งนานแล้ว",
  str_voice_1300521_26 = "ฉันทำงานเพื่อหาเลี้ยงชีพเท่านั้น ฉันก็เลยรู้สึกได้กำไรเวลาที่ได้อู้งานไง",
  str_voice_1300521_27 = "เป็นไปได้ด้วยเหรอที่ฉัน... จะไม่ต้องทำงานน่ะ หรือไม่ต้องตอกบัตรเข้างาน...",
  str_voice_1300521_28 = "ก็น่าสนอยู่นะแต่งานมันดูเยอะมากเลย...",
  str_voice_1300521_29 = "หวัดดี ฉันโดฟนะ ถ้าต้องการส่งจดหมายเมื่อไหร่ก็บอกได้เลย ฉันอาจจะไม่ได้ไปหาทันทีแต่ก็จะพยายามสุดความสามารถล่ะ",
  str_voice_1300521_30 = "โอ๊ะ ฉันบินได้เร็วขึ้นแล้ว",
  str_voice_1300521_31 = "ได้เวลาทำงานอีกแล้ว... พวกเธอไปก่อนเลย เดี๋ยวฉันตามไป",
  str_voice_1300521_32 = "ค-คราวหน้านะ คราวหน้าฉันไปแน่นอน!",
  str_voice_1300521_34 = "ไปช่วยหรือหนีดีล่ะ",
  str_voice_1300521_35 = "พระเอกชอบมาตอนจบเสมอ!",
  str_voice_1300521_36 = "ฉันไม่ต้องหนี...",
  str_voice_1300521_37 = "โดฟ ไปกันเถอะ!",
  str_voice_1300521_38 = "นกพิราบในแชโดว์!",
  str_voice_1300521_39 = "ก-ใกล้ขีดจำกัดของฉันแล้ว!",
  str_voice_1300521_40 = "อ-ออกไปให้พ้นนะ!",
  str_voice_1300521_41 = "ไม่นะ... ถ้าฉันเป็นกัปตันก็อู้ไม่ได้แล้วสิ...",
  str_voice_1300521_42 = "เธอทำได้! อดทนหน่อยนะ... เอ๊ะ จบเรื่องแล้วเหรอ",
  str_voice_1300521_43 = "ขอโทษทีนะ เท้าฉัน... รู้สึกจะเต็มไปด้วยตะกั่วอีกแล้ว ฉันขยับไม่ได้เลย...",
  str_voice_1300521_44 = "ฉันไปงีบหลับสบาย ๆ ได้ตรงนั้น...",
  str_voice_1300521_45 = "หวังว่าจะเป็นของที่ช่วยกล่อมฉันหลับได้นะ...",
  str_voice_1300521_46 = "กระต๊าก ไม่เลวเลยนี่นา!",
  str_voice_1300521_47 = "นี่มันยอดไปเลย ถึงขั้นทำให้ฉัํนเก็บไปนอนฝันด้วย!",
  str_voice_1300521_48 = "จ-จากนี้ไปฉันจะไม่เทเธอแล้ว แค่เธอเท่านั้น!",
  str_voice_1300521_49 = "ความขี้เกียจของฉันมันเกินแก้แล้ว... แต่ถึงทำงานหนักไปก็เปลี่ยนอะไรไม่ได้อยู่ดี ตระกูลพิกเคนส์อย่างเราไม่เหมือนเคยแล้ว ถ้าฉันถูกไล่ออกก็.. ก็ซวย จ่ายค่าเช่าบ้านไม่ได้ ฉันควรจะทำงานสักหน่อย",
  str_voice_1300521_50 = "ต้องเป็นตอนนั้นสินะ! หืม ฉันทำอะไรลงไปเนี่ย ฉันยังต้องมีชีวิตต่อไปนะ! แต่ฉันทิ้งพวกเขาไว้อย่างนี้ไม่ได้... แต่ฉันก็ไม่อยากตาย... แต่พวกนั้น...",
  str_voice_1300521_52 = "Alchemy... Stars",
  str_voice_1300521_53 = "เธอมาด้วยเหรอ",
  str_voice_1300521_54 = "ไม่อยากจะเชื่อเลยว่าวันนี้ฉันตื่นได้ตรงเวลาจริง ๆ",
  str_voice_1300521_55 = "อยากนัดเจอกันไหม ฉันไม่ผิดนัดเธอหรอก",
  str_voice_1300521_56 = "อู้งานด้วยกันเถอะ ฉันไม่ทิ้งเธอแน่",
  str_voice_1300521_57 = "ฉันสัญญาว่าตอนปีใหม่จะไม่ผิดนัดเธอ",
  str_voice_1300581_1 = "อัศวินย่อมยึดถือ... ยึดถือ... เอ่อ... ตามกฎ แม้ว่าฉันจะเป็นแค่มือใหม่ แต่ฉันก็เป็นถึงอัศวินเชียวนะ! งั้นฉันก็จะปฏิบัติตามกฎด้วย",
  str_voice_1300581_2 = "ดอว์นฮีลเลอร์เป็นหลักฐานแห่งเกียรติยศ... ฉันสัญญาว่าจะเรียนรู้วิธีใช้และไม่ปล่อยให้มันไปฉีดเสื้อผ้าคนอื่น!",
  str_voice_1300581_3 = "การเรียนรู้ที่วิทยาลัย ฝึกฝนที่อัศวินลูโม นำเสนอเควสต์และเลื่อนตำแหน่งต่าง ๆ... ฉันว่ามีเวลาไม่พอหรอก ฉันไม่มีทางจะทำทุกอย่างได้แน่!",
  str_voice_1300581_4 = "ฉันอาจดูไม่เหมาะกับการต่อสู้แต่ฉันก็ยังปกป้องทุกคนได้ ฉันจะพยายามไม่ตีหัวพวกเธอทุกคน!",
  str_voice_1300581_5 = "จิตใจนิ่งสงบ ดวงตาจ้องมอง ไม่ว่าจะปักธงไว้ที่ไหน ฉันก็จะเก็บมันมาเป็นของตัวเอง เดี๋ยว! เปล่านะ ฉันหมายถึงคอยดูแลให้มันตั้งตรงอยู่เสมอน่ะ",
  str_voice_1300581_7 = "เราอาจจะต่างกันแต่เราทั้งคู่ต่างก็เป็นคนขยันทำงาน... ช-ใช่ไหม",
  str_voice_1300581_8 = "เชื่อเถอะว่าเราจะได้รางวัลสำหรับสิ่งต่าง ๆ ที่เราทำอยู่... ไม่ว่าจะเล็กน้อยแค่ไหนมันก็มีค่า!",
  str_voice_1300581_9 = "คือ... แรงสนับสนุนของเธอที่กระตุ้นให้ฉันขยันขันแข็ง ไหล่ฉันอาจจะแคบแต่ฉันแบกหามได้เยอะนะ!",
  str_voice_1300581_10 = "เวลาที่ล้ำค่ากำลังเสียเปล่า... อย่างนี้นี่เอง แล้วฉันก็ต้องมุ่งมั่นพักผ่อนอย่างเต็มที่ด้วยสินะ!",
  str_voice_1300581_11 = "รู้แล้ว! เธออยากให้ฉันปักธงไว้ตรงนี้เหรอ หา ไม่ใช่เหรอ ไม่ต้องใช้ธงงั้นเหรอ",
  str_voice_1300581_12 = "โว้ว! อย่าทำฉันกลัวแบบนั้นสิ ถ้าเธอคิดจะโผล่มาคราวหน้าก็ช่วยส่งคำร้องมาก่อนดีกว่า",
  str_voice_1300581_13 = "ฉันอาจตื่นตระหนกง่ายแต่คราวนี้ฉันเตรียมตัวมาอย่างดี ฉันจะไม่กลัว... แต่ก็ไม่แน่นะ!",
  str_voice_1300581_14 = "จงเคร่งขรึม ขยันขันแข็ง และไม่ยอมจำนน! หืม... สั้นเกินไปสำหรับคติประจำใจหรือเปล่า",
  str_voice_1300581_15 = "ว-วันนี้คือวันเกิดเธอ ฉันจะฉลองให้เธอเอง ไม่ต้องห่วงนะ ฉันฝึกฝนมาเพียงพอแล้ว!",
  str_voice_1300581_16 = "ได้เวลาทำงานแล้ว ขยันทำงานไปด้วยกันเถอะ!",
  str_voice_1300581_17 = "ออกกำลังกายตอนเช้าดีกว่าจริงด้วย ขอบใจที่แนะนำนะ ฉันจะทำให้ดีที่สุด!",
  str_voice_1300581_18 = "ทุกอย่างต้องเป็นไปตามแผนเพื่อให้เรามีพลังเพียงพอในทุก ๆ วัน เดี๋ยวเราก็ได้พักแล้ว!",
  str_voice_1300581_19 = "เธอนี่สุดยอดไปเลย... เวลานี้แล้วยังฝึกฝนไม่ลดละอีก... ฉ-ฉันยัง... เผลอหลับไม่ได้!",
  str_voice_1300581_20 = "การได้เป็นอัศวินลูโมนั้นเป็นเกียรติอย่างมาก ฉันจะจงรักภักดีตลอดไป!",
  str_voice_1300581_21 = "น่าเสียดายที่ฉันเด็กเกินกว่าจะเข้าร่วมการเปิดบ้านแลกเปลี่ยนกันระหว่างลูโมโพลิสและอิลลูมินาสมัยก่อน!",
  str_voice_1300581_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1300581_23 = "อิคลิพไซท์เป็นศัตรูของทั้งทวีป ลูโมโพลิสควรกวาดล้างพวกมันและรักษาความสงบสุขไว้!",
  str_voice_1300581_24 = "ทำไมเจ้าหัวแดงถึงทำเหมือนฉันเป็นเด็กล่ะ ฉันเป็นอัศวินนะ!",
  str_voice_1300581_25 = "ฉันควรเรียนรู้จากเลดี้ราฟาเอลและทำตัวร่าเริงกับทุกคนในทุก ๆ วัน!",
  str_voice_1300581_26 = "ฉันชอบทำงานหนัก... การทำงานหนักมักจะได้รับรางวัลตอบแทนเสมอ!",
  str_voice_1300581_27 = "สิ่งที่ฉันเกลียด... ฉันเกลียดคนขี้เกียจกับสิ่งน่ากลัว ๆ...",
  str_voice_1300581_28 = "ปราดเปรื่องมาก ฉันรู้สึกได้ถึงความเฉลียวฉลาดของผู้บุกเบิกเลย พวกเขาต้องทำงานหนักเพื่อสร้างโคลอสซัสนี้แน่!",
  str_voice_1300581_29 = "ยินดีที่ได้รู้จัก เป็นเกียรติมากที่... โอ๊ย... ได้มาอยู่ที่นี่... นับจากนี้ไปฉันจะเป็นแนวหน้าและนำทางเธอไปข้างหน้าเอง!",
  str_voice_1300581_30 = "การเติบโตเป็นรางวัลที่ดีที่สุด!",
  str_voice_1300581_31 = "ตอนนี้ฉันมีค่าและเก่งกาจแล้ว!",
  str_voice_1300581_32 = "ฉันเห็นแสงสว่างจากธงเลย!",
  str_voice_1300581_34 = "ธงอยู่กับฉัน!",
  str_voice_1300581_35 = "หืม? ใช้ธงเหรอ ตอนนี้น่ะนะ",
  str_voice_1300581_36 = "ฉ-ฉันเตรียมการมาดี!",
  str_voice_1300581_37 = "ธงแห่งแสงโปรดปกป้องเราด้วย!",
  str_voice_1300581_38 = "นี่คือคำอวยพรยามรุ่งอรุณ!",
  str_voice_1300581_39 = "ขอให้โชคดี!",
  str_voice_1300581_40 = "มุ่งหน้าไปสู่ความหวัง!",
  str_voice_1300581_41 = "ฉ-ฉันจะนำพวกเขาเอง!",
  str_voice_1300581_42 = "โอ้ สุดยอด มันได้ผลจริงด้วย!",
  str_voice_1300581_43 = "เอ๊ะ ฉ-ฉันทำอะไรผิดหรือเปล่า",
  str_voice_1300581_44 = "ฝึกฝนอย่างขยันขันแข็งกันอีกสักวัน!",
  str_voice_1300581_45 = "ฉันแค่ตกใจนิดหน่อย",
  str_voice_1300581_46 = "ฉัน... รับเจ้านี่ไว้ได้จริงเหรอ",
  str_voice_1300581_47 = "มันเป็นของขวัญจากเธอ!",
  str_voice_1300581_48 = "ฉ-ฉันอยากได้จริง ๆ ขอบคุณนะ!",
  str_voice_1300581_49 = "ฉันโชคดีมากเลยที่ได้ติดตามเลดี้กาบริเอลหลังจากที่เป็นอัศวิน เธอใจดีมาก แถมยังสอนฉันเรื่องคุณค่าของการทำงานหนัก!",
  str_voice_1300581_50 = "ในวิกฤติร้ายแรงนั้น ลูโมโพลิสต่างวุ่นวายโกลาหลไปทั่ว โชคดีที่รัตติกาลสีขาวตอบรับคำเรียกของฉันและมอบธงแห่งแสงให้",
  str_voice_1300581_51 = "ฉันจะขยันทำงานตอนที่ฉันยังทำไหว มีผู้คนมากมายได้เสียโอกาสไปบนโลกใบนี้!",
  str_voice_1300581_52 = "Al-alchemy Stars!",
  str_voice_1300581_53 = "ส-สวัสดี!",
  str_voice_1300581_54 = "อรุณสวัสดิ์!",
  str_voice_1300581_55 = "สวัสดียามบ่าย!",
  str_voice_1300581_56 = "สายัณห์สวัสดิ์!",
  str_voice_1300581_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1300591_1 = "มีข่าวลือว่าเธอแอบรวยเงียบ ๆ... อะไรนะ ไม่ได้รวยหรอกเหรอ คนโกหก! ถ้าไม่มีเงินแล้วทำไมทำตัวน่าประทับใจขนาดนี้ล่ะ เหมือนเจ้าหญิงของลูโมโพลิสที่น่าประทับใจเลย ใช่แล้วอ่ะ",
  str_voice_1300591_2 = "กลัวผู้หญิงดุ ๆ ไหม ชอบสาวผมบลอนด์ที่พูดจาจ๊ะจ๋าสินะ... โฮ โฮ...",
  str_voice_1300591_3 = "ทำไมอิคลิพไซท์เก่ง ๆ ถึงมาหาเธอตลอดเวลาเลยละ เป็นเจ้าชายที่ไหนหรือยังไง โคลอสซัสอาจจะเป็นม้าขาวที่มีไว้ให้เธอขี่ก็ได้ ใช่แล้วอ่ะ!",
  str_voice_1300591_4 = "โอ๊ย การโจมตีที่รุนแรงที่สุดมาจาก... ผ-ผ-ผ้าพันคอนี่... ใช่ ผ้าพันคอ ใช่แล้วอะ... มัน อั่ก พันกันไปหมดจริง ๆ... น่ารำคาญชะมัด...",
  str_voice_1300591_5 = "แล้วเราจะหาภูตวาจามาจากไหนล่ะ ถ้าไม่มีภูตวาจาก็เลื่อนตำแหน่งในสหภาพผู้ส่งสารไม่ได้จริง ๆ นะ ใช่แล้วอ่ะ ไม่มีทางฝึกเป็นภูตวาจาเหรอ ให้ฉันจับเองเนี่ยนะ ไม่มีทางเสียล่ะ...",
  str_voice_1300591_7 = "ขอโทษ ฉันบังเอิญทำเข็มทิศพังน่ะ... อันสำรองเหรอ อะไรน่ะ นั่นอันที่ฉันทำพังไปเมื่อสองวันก่อนเหรอ ก็แหม เธอนำทางไม่เป็นหรือไง เธอดูไม่ต้องใช้เข็มทิศจริง ๆ นะ ใช่แล้วอ่ะ",
  str_voice_1300591_8 = "ทำไมมีคนมากมายติดตามเธอล่ะ... ฉันตามมาดู ใช่แล้วอ่ะ ว่าเธอมีอะไรพิเศษนักหนาก็แค่นั้นจริง ๆ นะ!",
  str_voice_1300591_9 = "ฉันอิจฉาคนที่มักจะอยู่ข้างกายเธอเสมอ ทั้ง ๆ ที่เธอไม่ได้มีอำนาจมากมายขนาดนั้น... ก็ได้ ๆ เพราะเธอมีค่ามากเกินไปจริง ๆ ใช่แล้วอ่ะ",
  str_voice_1300591_10 = "แล้วทำไมเธอถึงชอบตกอยู่ในสถานการณ์ที่ถูกอิคลิพไซท์ล้อมล่ะ แน่ใจนะว่าไม่ได้แกว่งเท้าหาเสี้ยนเองน่ะ",
  str_voice_1300591_11 = "แป๊บนะ ขอหาออเดอร์ก่อน เมื่อวานฉันวางไว้ในกล่องนี่นา... เอ๊ะ จำผิดเหรอเนี่ย อุตส่าห์เตรียมไว้...",
  str_voice_1300591_12 = "ฉันชอบ... ทำให้คนบินน่ะ จะได้เห็นว่าปีกของจริงเป็นยังไง... เพราะฉันเองก็ไม่มีปีกเหมือนกัน",
  str_voice_1300591_13 = "อย่ากลืนนะ! นกกระจอก ทำไมคนเราถึงไม่ประกาศออกเสียงไปเลยละ พิลึกจริง ใช่แล้วอ่ะ",
  str_voice_1300591_14 = "ฉันตัวคนเดียวล่ะ ฉันเคยอยู่กับครอบครัวมาก่อน แต่มารู้อีกที... ก็แยกย้ายกันไปหมดแล้ว",
  str_voice_1300591_15 = "ฉันไม่ได้ลืมจริง ๆ นะ ใช่แล้วอ่ะ เมื่อวานฉันเตรียมของขวัญไว้พร้อมแล้วก็... เอ่อ ลืมเอามาเฉย ๆ น่ะ",
  str_voice_1300591_16 = "ยินดีต้อนรับกลับมานะ ฉันอยู่คนเดียวก็ทำอะไรไม่ได้มากเท่าไหร่อยู่แล้ว ฉันก็เลยรอเธอไปเลยดีกว่า",
  str_voice_1300591_17 = "ฉันน่าจะลืมคำสั่งปฏิบัติงานไว้ในห้องนอน... เดี๋ยวนะ เมื่อคืนฉันไปนอนที่ไหนมาเนี่ย",
  str_voice_1300591_18 = "อ๋อ ฉันกำลังเขียนรายการภารกิจ แล้วก็น่าจะต้องทำงานหนักพอสมควร ใช่แล้วอ่ะ",
  str_voice_1300591_19 = "เธอไม่อยากพักผ่อนเหรอ ถามจริง การที่ยังไม่นอนในเวลานี้ก็น่าประทับใจอยู่นะ ใช่แล้วอ่ะ",
  str_voice_1300591_20 = "สหภาพผู้ส่งสารคอยดูแลแม้กระทั่งคนธรรมดาอย่างฉัน ฉันรู้สึกโชคดีจัง ใช่แล้วอ่ะ",
  str_voice_1300591_21 = "ถ้าอยากจะทำงานต่อ ก็แปลว่าต้องทนกับผู้รับผมบลอนด์น่ากลัวคนนั้น... มันน่ากลัวมากนะ ใช่แล้วอ่ะ",
  str_voice_1300591_22 = "เราส่งจดหมายเสมอ ใช่สิ ใช่แล้วอ่ะ",
  str_voice_1300591_23 = "เห็นพวกเขาอ้าปากค้างไหม เขมือบนกกระจอกได้ในคำเดียวแน่เลย ใช่แล้วอ่ะ! *ฟุดฟิด* น่ากลัว...",
  str_voice_1300591_24 = "นาง... ขีปนาวุธทรงไข่งั้นเหรอ ขนฟูจนเหมือนลูกบอลมากกว่ามั้ง",
  str_voice_1300591_25 = "นิสัยของโดฟก็ต้องเทฉันจริง ๆ อยู่แล้ว ใช่แล้วอ่ะ ดูสินางขันแบบนั้นตลอดเวลาเลย",
  str_voice_1300591_26 = "ขอฉันอาศัยอยู่ในที่ปลอดภัยสักครั้งเถอะ... บางครั้งฉันก็อิจฉาพวกที่ไม่เหมือนใครนะ",
  str_voice_1300591_27 = "ฉันรับมือกับสิ่งประหลาด ใช่แล้วอ่ะ ไม่ได้จริง ๆ นะ มันกวนใจแล้วก็น่ากลัวมากเลย...",
  str_voice_1300591_28 = "โคลอสซัสเหรอ เป็นครั้งแรกที่ฉันเห็นเลยนะนี่ คอยาวขาวซีดไร้ขน... แปลกสุด ๆ เลย ใช่แล้วอ่ะ",
  str_voice_1300591_29 = "วู้ว คนแบบเธอนี่แหละถูกใจใช่เลย! ฉันพอจะใช้การได้นะ... เดี๋ยวสิ อย่าทิ้งฉันไว้แบบนี้ ไม่เอาน่า",
  str_voice_1300591_30 = "โว้ว ฉันรู้สึกอะไรของฉันเนี่ย!",
  str_voice_1300591_31 = "เอ่อ ช่วงเวลาแบบนี้ฉันควรพูดอะไรดี",
  str_voice_1300591_32 = "เหมือนทฤษฎีวิวัฒนาการน่ะเหรอ! โอ้ ก็ยังค่อนข้างธรรมดาอยู่นะ",
  str_voice_1300591_34 = "เข้าใจแล้ว เข้าใจแล้ว ฉันมาแล้ว",
  str_voice_1300591_35 = "ฉัน \"จะ\" พยายามให้มาก ๆ ก็อาจจะ",
  str_voice_1300591_36 = "เฮ้ เธอดูไปเรื่อยเลยเหรอ",
  str_voice_1300591_37 = "พยายามต่อไปนะ แล้วพบกัน... ฉันประกันตัวไม่ได้เหรอ",
  str_voice_1300591_38 = "อุ้ย! เกือบไปแล้ว ได้เวลาประกันตัว... ฉันช้าขนาดนั้นเลยเหรอ",
  str_voice_1300591_39 = "นั่นอะไร ไฟเหรอ",
  str_voice_1300591_40 = "นี่มันไฟเจ้าปัญหาชัด ๆ",
  str_voice_1300591_41 = "ให้ฉันนำเหรอ เอาจริงน่ะ ถามจริง",
  str_voice_1300591_42 = "จบแล้วล่ะ ไปเก็บของกันได้ยัง",
  str_voice_1300591_43 = "แพ้ซะแระ... แต่ไม่เป็นไร เรายังรอดมาได้แบบเพอร์เฟกต์!",
  str_voice_1300591_44 = "ก็ได้ ๆ ฉันจะเงียบแล้ว... แน่ใจนะว่าอยากให้ฉันเงียบไปตลอดน่ะ ถ้าฉันเงียบแล้วเธอจะไม่เหงาเหรอ",
  str_voice_1300591_45 = "โว้ว ไปเอามาจากไหนนะนั่น พอมีมันแล้วฉันรู้สึกไม่เข้าพวกนิดหน่อยน่ะ...",
  str_voice_1300591_46 = "เป็นของขวัญที่ดีสำหรับคนปกติอย่างฉันนะนี่ น้ำตาจะไหลแล้ว...",
  str_voice_1300591_47 = "เอ่อ... อันที่จริงฉันก็ไม่ชอบเท่าไหร่ เธอรู้ดีใช่ไหม",
  str_voice_1300591_48 = "ฉันซาบซึ้งใจมากที่เธอดีกับคนธรรมดาอย่างฉันมาก ใช่แล้วอ่ะ...",
  str_voice_1300591_49 = "เธอว่าไงนะ โว้ว! เธอเขียนประวัติให้ทุกคนเลยเหรอ ฟังดูเป็นงานจัง ใช่แล้วอ่ะ... เอ่อ อย่าโกรธนะ แต่รายการ \"สิ่งของที่พัง\" คืออะไรเหรอ",
  str_voice_1300591_50 = "มีคนให้ผ่าพันคอฉันมา นกกระจอกธรรมดาจะได้สิ่งประดิษฐ์ล้ำค่าแบบนั้นมายังไง... ยิ่งพูดยิ่งขลังแฮะ!",
  str_voice_1300591_52 = "ดูสิ Alchemy Stars!",
  str_voice_1300591_53 = "เก๋ใช่ย่อยเลย ใช่แล้วอ่ะ!",
  str_voice_1300591_54 = "อรุณสวัสดิ์นะ ใช่แล้วอ่ะ!",
  str_voice_1300591_55 = "สวัสดียามบ่ายล่ะ ใช่แล้วอ่ะ!",
  str_voice_1300591_56 = "ราตรีสวัสดิ์ ใช่แล้วอ่ะ!",
  str_voice_1300591_57 = "สุขสันต์วันปีใหม่ ใช่แล้วอ่ะ!",
  str_voice_1300741_1 = "ฉันแค่อยากอยู่คนเดียว... ถ้าเป็นไปได้นะ...",
  str_voice_1300741_2 = "กระทั่งดวงอาทิตย์ยังมืดมน พังทลาย และเกิดขึ้นใหม่อีกครั้ง... ครั้งแล้วครั้งเล่า",
  str_voice_1300741_3 = "ภาวนาให้เราหาสันติภาพชั่วนิรันดร์เจอก่อนที่ความมืดจะกลืนกินเราเถอะ...",
  str_voice_1300741_4 = "คำพูดพี่เซการ์ทำให้ฉันสบายใจเสมอ... เหมือนเป็นคำพูดจากปากฉันเองเลย",
  str_voice_1300741_5 = "เธอช่วยให้ฉันได้เติบโตขึ้นมากมาย... เพราะฉะนั้นต้องขอบใจนะ มันทั้งรู้สึกดี... และอบอุ่น",
  str_voice_1300741_6 = "บางทีฉันอาจพบหนทางลืมฝันร้ายไปสักวันหนึ่งก็ได้...",
  str_voice_1300741_7 = "สนใจในตัวฉันเหรอ ขอโทษที่ฉันทำให้เธอผิดหวังนะ",
  str_voice_1300741_8 = "ฉัน... ฉันไม่ควรได้รับความสนใจและความเอาใจใส่ของเธอ... อดีตทิ้งรอยแผลไว้ให้ฉัน...",
  str_voice_1300741_9 = "ขอบคุณ ผู้นำทาง ฉันรู้สึกปลอดภัยตอนอยู่กับเธอเหมือนอยู่กับเซการ์ ถ้าเป็นอย่างนี้ได้ตลอดไปละก็...",
  str_voice_1300741_10 = "พวกนั้นก็เหมือนฉัน... เปลือกปิดสนิท... แล้วแกนกลางในนั้นก็มืดมนและหนาวเหน็บ",
  str_voice_1300741_11 = "ฉันไม่ชอบที่นี่เลย... ขอฉันกลับไปที่มุมของฉันได้ไหม แต่ถ้าเธอยืนกรานละก็...",
  str_voice_1300741_12 = "เซการ์อยู่ไหน ไม่มีอะไรหรอก... แค่ถามเฉย ๆ...",
  str_voice_1300741_13 = "... ตอนนั้นฉันไม่มีทางเลือก... แต่ตอนนี้... มันสายไปแล้วใช่ไหม",
  str_voice_1300741_14 = "พวกนั้น... ต้องเจอการเสื่อมสลายอย่างรวดเร็วหลายต่อหลายรอบ... เลยมีพลังเหลือล้นกว่าฉันเยอะ",
  str_voice_1300741_15 = "...หว้งว่าเธอจะลืมเรื่องราวแย่ ๆ ทั้งหมดที่เกิดขึ้นในวันนี้... และขอให้ความอบอุ่นอยู่เคียงข้างเธอตลอดไป",
  str_voice_1300741_16 = "ใช่ ฉันยังอยู่ตรงนี้ ไม่ไปไหนหรอก",
  str_voice_1300741_17 = "เราเจอกันอีกแล้ว หลังแสงสว่างกลับคืนมา",
  str_voice_1300741_18 = "ภาวนาให้เราแต่ละคนหา... มุมของตัวเองได้ก่อนที่แสงสว่างจะเลือนลางไปก่อน",
  str_voice_1300741_19 = "หลับไม่ลงเพราะชอบฝันร้ายเหมือนกันเหรอ พวกเรานี่เหมือนกันเลยเนอะ",
  str_voice_1300741_20 = "อิลลูมินาดูแลฉัน... แต่ฉันก็สู้เป็นนะ ฉันไม่ต้องการให้ใครมาสงสารเห็นใจ",
  str_voice_1300741_21 = "ตัวฉันเองก็ไม่เข้าใจหรอก ถ้าฉันต้องอธิบายมัน... ฉันก็ไม่พอใจที่ได้เห็นเมืองสีขาวนั่นหรอก",
  str_voice_1300741_22 = "ขออิลลูมินา...จงเจิดจำรัส",
  str_voice_1300741_23 = "เหมือนสิ่งมีชีวิตในฝันร้ายของฉันเลย ถ้าฉันทำลายมันได้ละก็... ฉันก็จะสามารถไถ่บาปได้ไม่มากก็น้อยล่ะ",
  str_voice_1300741_24 = "เซการ์ทำหน้าที่ให้คำปรึกษาทางจิตในอิลลูมินา เพราะเธอ ฉันก็เลยหายเครียด",
  str_voice_1300741_25 = "เพื่อน... ก็ไม่เชิง แต่เบนนี่กับคุโระน่ะ... เป็นสหายคนสำคัญในกองทัพ",
  str_voice_1300741_26 = "อยู่คนเดียวดีกว่า... ฉันชอบมากกว่าเวลาที่รู้สึกปลอดภัย",
  str_voice_1300741_27 = "ฝันร้ายและอดีตที่ไม่ใช่ของฉัน... ฉันเกลียดพวกมันทั้งหมด",
  str_voice_1300741_28 = "มันทำให้ฉันไม่สบายใจ... อาจเป็นเพราะมันสูงเฉียดฟ้าล่ะมั้ง",
  str_voice_1300741_29 = "...เรื่องของฉันเหรอ ...ฉันคือไวท์ดวาร์ฟ ไม่มีอะไรมากไปกว่านั้น ฉัน... ฉันอยากอยู่คนเดียวสักพัก",
  str_voice_1300741_30 = "ฉันอยากแข็งแกร่งขึ้น",
  str_voice_1300741_31 = "...ระดับการพัฒนานี้มีความหมายอะไรจริง ๆ ด้วยเหรอ",
  str_voice_1300741_32 = "เธอเห็นหรือเปล่า เซการ์",
  str_voice_1300741_33 = "อดีตไม่ใช่คำสาปของฉันแต่คำอวยพรจะช่วยให้ฉันเติบโตต่อไป",
  str_voice_1300741_34 = "ฉันช่วยอะไรได้บ้างไหม...",
  str_voice_1300741_35 = "ฉัน... ทนไม่ไหวอีกต่อไปแล้ว...",
  str_voice_1300741_36 = "ต้องระบาย... ออกมา!",
  str_voice_1300741_37 = "จงพังทลายทรุดลงตามแรงโน้มถ่วง",
  str_voice_1300741_38 = "จงยอมจำนนต่อแรงโน้มถ่วงอันทรงพลัง!",
  str_voice_1300741_39 = "อย่ามาให้ฉันเห็นอีก!",
  str_voice_1300741_40 = "ไสหัวไป!",
  str_voice_1300741_41 = "...ฉันเข้าสังคมไม่เก่งจริง ๆ",
  str_voice_1300741_42 = "ระบาย... มามากพอแล้ว...",
  str_voice_1300741_43 = "ฉันไม่รู้สึกเจ็บปวดอีกต่อไปแล้ว... ปล่อยให้มันเป็นไป...",
  str_voice_1300741_44 = "ฉันแค่เหม่อน่ะ เลิกจ้องฉันสักที...",
  str_voice_1300741_45 = "หืม ฉันควรบอกว่า \"ขอบใจ\" ไหม",
  str_voice_1300741_46 = "...น่าสนใจจัง",
  str_voice_1300741_47 = "เธอไม่เห็น... ต้องลำบากเลย...",
  str_voice_1300741_48 = "โอ้ เจ้านั่นทำให้ฉันรู้สึกดีขึ้น...",
  str_voice_1300741_49 = "ขอโทษที่ฉันทำอารมณ์เสียใส่นะ... มันเกินกว่าที่ฉันจะควบคุมได้... เป็นส่วนเกินในจิตใต้สำนึกของฉัน",
  str_voice_1300741_50 = "ฝันร้าย อดีต... รวมถึงความทรงจำที่ไม่ใช่ของฉัน... ทำไมต้องพุ่งเข้ามาหาฉันด้วย สิ่งที่แม่ฉันพูดเป็นเรื่องจริงเหรอ",
  str_voice_1300741_51 = "ยังไงฉันก็จะทะนุถนอมเพื่อนทุกคนที่อิลลูมินาไว้ แต่ฉันต้องหาที่มาของฝันร้ายและความจริงเกี่ยวกับนิทานของแม่ด้วย...",
  str_voice_1300741_52 = "Alchemy... Stars",
  str_voice_1300741_53 = "...เอ่อ...",
  str_voice_1300741_54 = "...อรุณสวัสดิ์",
  str_voice_1300741_55 = "... สวัสดีตอนบ่าย",
  str_voice_1300741_56 = "... สายัณห์สวัสดิ์!",
  str_voice_1300741_57 = "สุขสันต์...วันปีใหม่",
  str_voice_1300801_1 = "ช-ช่วยนั่งลงก่อนได้ไหม... ฉัน... ไม่สิ... ผู้ช่วยของฉันจะชงชาให้ เอาหน่อยไหม",
  str_voice_1300801_2 = "กรี้ด! เธอทำฉันกลัวนะ หนังสือเหรอ ฉัน เอ่อ อ่านแนะแนวการเข้าสังคม 20 ข้อสำหรับสมาชิกอิลลูมินาที่ เอ่อ แชนดราแนะนำให้ฉันอ่านน่ะ...",
  str_voice_1300801_3 = "คาส รถไฟบรรทุกสินค้าในอิลลูมินา... อาจดูหนัก และหน้าตาเหมือนรถโง่ ๆ แต่ว่า... ถ้าเรื่องขุดเหมืองขนาดใหญ่แล้วละก็... มันใช้งานได้ยอดเยี่ยมมากเลยละ",
  str_voice_1300801_4 = "ฉันมี... ผู้ช่วย... กี่คนน่ะเหรอ ย-ยี่สิบสาม นับดูสิ",
  str_voice_1300801_5 = "มันไม่ได้เกี่ยวกับเรื่องพลังการต่อสู้เท่านั้นนะ... ฉัน... อยากพัฒนาทักษะการเข้าสังคมของฉัน ถ้าเป็นไปได้... ถ้าเป็นไปได้ฉันก็อยากมีระดับเดียวกับลิลเลียม...",
  str_voice_1300801_6 = "ฉันคิดถึง... บ้าน... ฉันรู้สึก... เหงาพิลึก... แต่เหล่าผู้ช่วย... ใจดีกันมาก... เหมือนทุกคนที่ห้องทดลองเลย",
  str_voice_1300801_7 = "พวกนั้นมองไม่เห็นฉัน... ไม่เห็น... ฉัน...",
  str_voice_1300801_8 = "มองที่คนอื่นเข้าไปในดวงตา... หายใจเข้าลึก ๆ หายใจเข้า... แตะเนื้อ... ต้องตัวเหรอ อ๊าก! ฉันทำไม่ได้หรอก!!",
  str_voice_1300801_9 = "ถึงฉันจะยัง... กลัวอยู่... แต่ก็เหมือนการสื่อสารกับเธอ... ไม่ได้ยากขนาดนั้น",
  str_voice_1300801_10 = "ยังมีงานให้ทำอยู่... งั้นเราไปอู้สักพักดีไหม... ไม่สิ ไม่ได้!",
  str_voice_1300801_11 = "ขอล่ะ ขออย่าเป็นฉัน ไม่ใช่ฉันเถอะ ไม่ใช่... อ๊าาาา ทีนี้ทำยังไงดีล่ะ",
  str_voice_1300801_12 = "มาจับมือหน่อยสิ... เอ่อ... กับเหล่าผู้ช่วยไงล่ะ!",
  str_voice_1300801_13 = "ลูมิไนต์มาจากการสลายตัวของลูมแอมเบอร์ การขนย้ายพวกมันไม่ใช่เรื่องง่ายเลย...",
  str_voice_1300801_14 = "การเดานิสัยคนอีกคนนั้นยากจะตาย หรือการย่อยหัวข้อบทสนทนาลงมา อ่า...",
  str_voice_1300801_15 = "แฮปปี้เบิร์ธเดย์ทูยู แฮปปี้เบิร์ธเดย์ทูยู... ฟู่ ฉันเหลืออดแล้วนะ!",
  str_voice_1300801_16 = "ความแข็ง... ความแข็งของวัสดุชี้ให้เห็นถึงแรงต้านต่อวัตถุ... อื่น... อ่า เธอนี่เอง!",
  str_voice_1300801_17 = "ม-มื้อเช้าพร้อมแล้ว ผู้ช่วยของฉันทำอาหารเก่งมากเลยนะ",
  str_voice_1300801_18 = "ได้เวลากิน... อาหารเย็นแล้ว! วันนี้ที่โรงอาหารมี.. มะ-เมนูอะไรเหรอ",
  str_voice_1300801_19 = "ได้เวลานอนแล้ว! ไม่อย่างนั้น... จะไม่สูงเอานะ ถึงฉันน่ะ... จะค่อนข้างเตี้ยอยู่แล้วก็ตาม",
  str_voice_1300801_20 = "ความจริงคือกลลวงการรวมศูนย์ของอิลลูมินา... มีข้อดีมากมาย... ในสภาพแวดล้อมปัจจุบัน",
  str_voice_1300801_21 = "เรดีเซล เวรนช์... มีคนแก่และหยาบคายมากมายแต่... เทคนิคประหลาดนั้นต่างก็... ควรค่าแก่การศึกษา",
  str_voice_1300801_22 = "อิลลูมินา... สเป-สเปโร!",
  str_voice_1300801_23 = "อิคลิพไซท์ อย่าเข้ามาใกล้นะ ผู้ช่วยอยู่ไหน ช่วยฉันด้วย!",
  str_voice_1300801_24 = "อันที่จริงฉันเล่นเกมไม่ค่อยเก่ง... แต่กรอนรู กรอนรูจะชวนฉันน่ะ",
  str_voice_1300801_25 = "รถไฟสู่ยมโลกไม่ได้เท่ที่สุดหรอกเหรอ เป็นของคารอนงั้นเหรอ ใครกันน่ะ",
  str_voice_1300801_26 = "ตายแล้ววว... ชอบโมเดลเหมือนกันเหรอ โมเดลล่าสุดของรถไฟสู่ยมโลกสุดยอดไปเลยละ",
  str_voice_1300801_27 = "ชื้นชะมัด! เหล่าผู้ช่วยของฉันขึ้นสนิมหมดพอดี",
  str_voice_1300801_28 = "ว้าวววว! โคลอสซัสนี่!!! ฉัน... ฉันต้องไปบันทึกเรื่องนี้ไว้ ส-สุดเจ๋งเลย",
  str_voice_1300801_29 = "ไม่นะ ไม่ ๆ!... รวบรวมความกล้าไว้สิ ยูนิเมต! ย-ยินดีที่... ได้รู้จักนะ ฉันมาจากฝ่ายบำรุงเครื่องกลอิลลูมินา#$!#%...$...",
  str_voice_1300801_30 = "ผ่าน... การทดสอบ!",
  str_voice_1300801_31 = "เหล่าผู้ช่วย ยิ่งใช้เท่าไหร่ก็จะยิ่งเชี่ยวชาญเท่านั้น",
  str_voice_1300801_32 = "แม้โอกาสจะน้อยจนเกือบไม่มีเลย ฉัน... ก็ต้องทำให้สำเร็จ",
  str_voice_1300801_34 = "ระ... รายงาน!",
  str_voice_1300801_35 = "พวกเราไปต่อได้แล้ว",
  str_voice_1300801_36 = "โครงการได้รับการ... ยืนยันแล้ว",
  str_voice_1300801_37 = "ปฏิบัติการได้เที่ยงตรงมาก",
  str_voice_1300801_38 = "งานสมบูรณ์แบบ",
  str_voice_1300801_39 = "ปฏิบัติการ... ประสานงาน",
  str_voice_1300801_40 = "กลยุทธ์... ผู้เชี่ยวชาญ",
  str_voice_1300801_41 = "การนำผู้อื่นนั้น... ช่างยากเหลือเกิน",
  str_voice_1300801_42 = "ลูมแอมเบอร์อยู่ที่ไหน มันอยู่ไหน",
  str_voice_1300801_43 = "มีคนอยู่ไหม ช่วยฉันด้วย... ช่วยที %*...&&*",
  str_voice_1300801_44 = "ส-สุดยอดเลย! ฉ-ฉลาดสุด ๆ!",
  str_voice_1300801_45 = "ขอบคุณนะ...",
  str_voice_1300801_46 = "ฉันชอบนะ... ฉันไม่น่าพูดแบบนั้นไปเลย... อ่ะแฮ่ม...",
  str_voice_1300801_47 = "ขอบคุณมากกกกนะ...",
  str_voice_1300801_48 = "โอ้ นี่เอง...!! อ่ะแฮ่ม... ขอโทษทีนะ",
  str_voice_1300801_49 = "ฉันลอง... มีปฏิสัมพันธ์กับคนอื่นแล้วแต่มัน... ไม่ไหวเอาเสียเลย ฉันแค่ไม่เข้าใจว่า... ฉันไม่มีเพื่อน ฉันยังไม่รู้ว่าต้องอ่าน... บรรยากาศยังไง โชคดีที่ยังมีเหล่าผู้ช่วยของฉัน",
  str_voice_1300801_50 = "บางที... ฉันก็ยังไม่รู้ด้วยซ้ำ... ว่าต้องสื่อสารกับคนอื่นยังไง... ทุกคนในอิลลูมินา... บอกว่าฉันไม่ควรคิดมากแล้วก็ควรพยายามเป็นตัวของตัวเอง",
  str_voice_1300801_52 = "Alchemy Stars",
  str_voice_1300801_53 = "อันนี้",
  str_voice_1300801_54 = "อรุณสวัสดิ์",
  str_voice_1300801_55 = "$% ขอโทษที กดผิดน่ะ เอ่อ...",
  str_voice_1300801_56 = "อย่างนี้ดีกว่าคุยกันต่อหน้าอีก...",
  str_voice_1300801_57 = "ขอให้โชคดี... ในวันปีใหม่... ปีใหม่น่ะ",
  str_voice_1300821_1 = "เดี๋ยวฉันช่วยเธอจัดการกับหีบให้ อะไรอยู่ในนั้นเหรอ ก็วัสดุหลากหลายอย่างมั้ง ช่างเถอะ ฉันแข็งแรงพอจะหิ้วมันไหวอยู่ ฮิ ๆ!",
  str_voice_1300821_2 = "ครั้งหนึ่งฉันบังเอิญไปชนองค์ราชินีเข้า แล้วพระองค์ก็ตรัสว่าฉันทำแบริเออร์เวทมนตร์อะไรสักอย่างของท่านพัง... ฉันล่ะสงสัยว่าท่านโมโหไหม...",
  str_voice_1300821_3 = "ถ้าต้องการอัญมณีก็ต้องรับน้ำหนักของมันให้ได้... แต่ฉันไม่เคยต้องการเขาที่ใหญ่ขนาดนี้เลย! มันเคยเป็นเขาที่เล็ก ๆ น่ารัก... แต่ตอนนี้...",
  str_voice_1300821_4 = "จ้องมองเข้าไปในแสงสีเขียวถ้าอยากพักสายตา เอ้อ เดี๋ยวนะ! ฉันขอปรับหน่อย แค่เดี๋ยวเดียว",
  str_voice_1300821_5 = "ขอนึกก่อนนะ... อ้า หิมะ ต้นสน และสายลมเดือนพฤษภาคมในนอร์ธแลนด์ ขอจงฟื้นฟูพลังและนำพาความเจริญรุ่งเรืองมาให้เธอ!",
  str_voice_1300821_7 = "ขอร้องล่ะ ถามน้ำหนักเขากับฉันแบบนี้ไม่สุภาพเอาเสียเลย... โอ้ แล้วก็ขอร้องให้ดูแต่ตามืออย่าต้องด้วย!",
  str_voice_1300821_8 = "อยู่กับเธอแล้วก็ดูน่าสนใจดีนะ... ต้องเป็นอย่างนั้นแน่เลย ฮิ ๆ ไม่เป็นไร ฉันแค่ดูเอาละกัน",
  str_voice_1300821_9 = "ฉันมีดาวส่องแสงอยู่บนหน้าผาก... เธอไม่มีเหรอ อันที่จริงตอนเจอกันครั้งแรก ฉันก็อยากให้เธอนะ!",
  str_voice_1300821_10 = "เจ้าพวกนี้ไม่ใช่เขาแต่เป็นกิ่งที่ถอดออกได้ เห็นไหม หืม... ฮ่า! เธอเชื่อมุกฉันใช่ไหมนั่น",
  str_voice_1300821_11 = "เป็นตำแหน่งสำคัญมากจริง ๆ... ไว้คราวหน้าแล้วกันนะ เอ๊ะ ฉันจำเป็นด้วยเหรอ ให้ฉันยืนหรือนั่งล่ะ หรือจะให้ฉัน... เรืองแสง",
  str_voice_1300821_12 = "เกล็ดหิมะใหม่ ๆ... อยากลองชิมไหม มันเย็นและ... ใช่! โนอาห์เป็นคนสร้างมันน่ะ!",
  str_voice_1300821_13 = "ขอร้องล่ะ... อย่าแตะต้องเขาของฉันเลย... พวกมันอันตรายนะ ทั้งฉันและเธอจะตกอยู่ในอันตราย!",
  str_voice_1300821_14 = "งั้นฉันจะทำยังไงดี อย่างนั้นก็ดูดีนะแต่แบบนี้ก็ดูดีเหมือนกัน... จะบ้าตาย!",
  str_voice_1300821_15 = "ของขวัญคือแสงอวยพรสีเขียวงดงาม นี่ไงล่ะ ...มาเถอะ ดูเขาของฉันไว้นะ!",
  str_voice_1300821_16 = "จะไปแล้วเหรอ นักผจญภัย โอ้ ไม่เป็นไรหรอก ฉันจะไปเดี๋ยวนี้แหละ",
  str_voice_1300821_17 = "ตื่นมาตอนเช้าทีไรฉันรู้สึกหนักหัวตลอดเลย... หนักหัวจริง ๆ",
  str_voice_1300821_18 = "ยินดีต้อนรับกลับมา เธอพอจะมีเวลาไหม ฉันอยากถามคำถามอะไรเธอสักหน่อย",
  str_voice_1300821_19 = "หืม... เธอนี่พลังงานเหลือล้นแบบนี้ตลอดเลยเหรอ จัดการตัวเองให้เป็นแบบนั้นได้ยังไงอะ",
  str_voice_1300821_20 = "ปิดบังสมบัติไว้เพื่อป้องกันจากเหตุวุ่นวาย... มันจะได้เปล่งประกายเป็นเวลานานแสนนาน",
  str_voice_1300821_21 = "เมืองมโหฬารสามารถลอยอยู่บนท้องฟ้าได้โดยไม่มีเสาแม้ว่าจะหนักก็ตาม... นั่นมันสุดยอดไปเลย!",
  str_voice_1300821_22 = "ฮิ ๆ... เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง!",
  str_voice_1300821_23 = "อิคลิพไซท์... แย่ชะมัดเลย ถ้าพวกนั้นมาล้อมเธอ เธอต้องหนีนะ!",
  str_voice_1300821_24 = "ระวังอย่าไปชนกับกระจกของเนโพลิสล่ะ ไม่อย่างนั้นนางจะโกรธเอา",
  str_voice_1300821_25 = "ฮิ ๆ... อยู่กับโนอาห์นี่สนุกมากเลย... ฉันไม่จำเป็นต้องกังวลเรื่องกลิ้งสโนว์แมนน้อยไปทั่วแล้วล่ะ!",
  str_voice_1300821_26 = "ฮิ ๆ... เธออาจจะดูไม่ออกนะ แต่... ฉันเป็นช่างเย็บผ้าฝีมือดีเลยละ!",
  str_voice_1300821_27 = "เธอทำสิ่งที่ต้องห้ามไม่ได้นะ ไม่อย่างนั้นจะถูกลงโทษสาหัสเลยละ!",
  str_voice_1300821_28 = "โคลอสซัสใหญ่โตมโหฬาร... มันใหญ่กว่าบ้านของฉันเสียอีก! เธอเคยอยู่ที่นี่ลำพังงั้นเหรอ รู้สึกเหงาบ้างไหม",
  str_voice_1300821_29 = "เป็นนักผจญภัยเล่านิทานเหรอ บังเอิญอะไรแบบนี้! โอ้ ขอโทษทีนะ ฉ-ฉัน... แนะนำตัวเองยังไงดีล่ะนี่",
  str_voice_1300821_30 = "เขา... ใหญ่ขึ้นเหรอ ไม่มีทาง...",
  str_voice_1300821_31 = "หินเรืองแสงเหรอ อ้อ! เขาของฉันไงล่ะ",
  str_voice_1300821_32 = "ดูสิว่าฉันเจออะไร เบย์ลอส!",
  str_voice_1300821_34 = "ฉันม-ไม่ชนคนอื่นหรอก...",
  str_voice_1300821_35 = "เอ่อ... ฉันจะเรืองแสงแล้ว!",
  str_voice_1300821_36 = "ดูได้แต่ห้ามจับเด็ดขาดเลยนะ!",
  str_voice_1300821_37 = "ฉันให้สัญญา แสงสีเขียว!",
  str_voice_1300821_38 = "ขอโชคดีจงสถิตอยู่กับท่าน",
  str_voice_1300821_39 = "อัญมณีเขียว",
  str_voice_1300821_40 = "เบย์ลอส!",
  str_voice_1300821_41 = "อะไรกัน นี่... หืม ตอนนี้ทำยังไงดีล่ะ...",
  str_voice_1300821_42 = "ฝ-ฝีมือฉันจริงเหรอ? ได้ผลเหรอ?",
  str_voice_1300821_43 = "ฉันขอโทษจริง ๆ... ฉันไม่ถนัดเลยสักนิดน่ะ...",
  str_voice_1300821_44 = "อ๊าาา อย่าแตะเขาของฉันนะ!",
  str_voice_1300821_45 = "อยากยกนี่ออกไปเหรอ เอ๊ะ ไม่เห็นจะหนักเลย",
  str_voice_1300821_46 = "ให้ฉันเหรอ ขอบคุณนะ!",
  str_voice_1300821_47 = "อ้าว ให้ฉันเหรอ งั้นฉันจะยกไปแล้วกัน!",
  str_voice_1300821_48 = "ฮิ ๆ... อย่างนี้นี่เอง นี่เป็นของขวัญสินะ ฉันชอบมากเลยละ!",
  str_voice_1300821_49 = "พวกมันจะขยายใหญ่ขึ้นไปเรื่อย ๆ ไม่ได้นะ แต่พวกมันกลับเป็นแบบนั้น... ถ้าพวกมันหนักขึ้นเรื่อย ๆ ล่ะ...",
  str_voice_1300821_50 = "ฉันเคยอาศัยอยู่ในเมืองหินที่ล้อมรอบไปด้วยหิมะและต้นสนสีเขียว ฉันเพิ่งได้เห็นโลกภายนอกหลังมาเจอเธอนี่แหละ!",
  str_voice_1300821_52 = "ฮิ ๆ Alchemy Stars!",
  str_voice_1300821_53 = "อ้า เอ่อ... ถ้างั้น...",
  str_voice_1300821_54 = "อรุณสวัสดิ์ นักผจญภัย!",
  str_voice_1300821_55 = "เธอพอมีเวลาไหม",
  str_voice_1300821_56 = "เธอสนใจเขาเรืองแสงหรือเปล่า",
  str_voice_1300821_57 = "ฮิ ๆ... สุขสันต์วันปีใหม่นะเธอ!",
  str_voice_1400071_1 = "ฉันหวังว่าจะได้เป็นต้นไม้ที่เติบโตบนที่สูงบ้างนะ",
  str_voice_1400071_2 = "โอ้ว้าว ฉันว่าเมื่อคืนฉันฝัน... ถึงกระต่าย...",
  str_voice_1400071_3 = "โอ้ ฉันต้องทำยังไงถึงจะมีชีวิตสงบสุขได้นะ... หรือบางทีตอนนี้ก็สงบสุขแล้ว...",
  str_voice_1400071_4 = "จะไม่มีใครมาขวางฉันได้อีก!",
  str_voice_1400071_5 = "ไม่มีสิ่งใดสำคัญกว่าอิสระแล้ว... ใช่แล้ว ไม่มีอะไรเลย...",
  str_voice_1400071_7 = "ฉันยังไม่ชินกับความใจดีอ่อนโยนของเธอแต่ก็ขอบคุณนะ...",
  str_voice_1400071_8 = "ความโอบอ้อมอารีแบบนี้ชวนให้ฉันนึกถึงบางอย่างเมื่อนานมาแล้ว... ช่างเถอะ มันก็เป็นแค่เรื่องเล่าเก่า ๆ ที่น่าเบื่อน่ะ...",
  str_voice_1400071_9 = "ดีใจที่ได้เจอเธออีกครั้งนะ สูดอากาศบริสุทธิ์หน่อยดีไหม สายลมยามบ่ายน่ะ... โอ้ ขอโทษที ลืมไปว่าเธอไม่ใช่คนที่ชอบถูกสายลมพัดไปมานี่นะ",
  str_voice_1400071_10 = "ดัม ดี ดัม ดี ดัม... อ่ะแฮ่ม!",
  str_voice_1400071_11 = "ฉันชอบที่นี่นะ อากาศสดชื่นดี",
  str_voice_1400071_12 = "ใครจะเป็นคนต่อไปเหรอ ฉันยินดีฟังเสมอ",
  str_voice_1400071_13 = "ขอโทษทีนะ เธอเห็น... เอ่อ ไม่มีอะไรหรอก ขอโทษที่มากวน ฉันจะไปหาเอง...",
  str_voice_1400071_14 = "ขอให้การต่อสู้ของเธอได้รับชัยชนะ",
  str_voice_1400071_15 = "วันนี้วันเกิดเธอเหรอ ขอให้มีความสุขมาก ๆ นะ",
  str_voice_1400071_16 = "ไม่เหมือนยุคของฉันที่มีเรดีเซล เวรนช์เลย แต่ฉันจะพยายามอย่างดีที่สุด",
  str_voice_1400071_17 = "อ้า... สายลมปลอบประโลมใจดีจัง...",
  str_voice_1400071_18 = "สายลมพัดพาเธอกลับบ้าน",
  str_voice_1400071_19 = "ที่นี่วิวดีจัง โดยเฉพาะตอนกลางคืน...",
  str_voice_1400071_20 = "ก็จริงที่ทุกคนต่างโหวกเหวกโวยวายที่นี่ แต่ฉันไม่ว่าอะไรเพราะทุกคนล้วนเป็นคนดี",
  str_voice_1400071_21 = "ในอัมบราตัน คนจนไม่ใช่กลุ่มคนที่แย่ที่สุดแต่เป็นเด็กกำพร้าที่ข้นแค้นต่างหาก",
  str_voice_1400071_22 = "อิสระและไร้ข้อผูกมัด",
  str_voice_1400071_23 = "อิคลิพไซท์มีนิสัยชอบจู่โจมอยู่แล้ว พวกมันเป็นสิ่งมีชีวิตที่เข้าใจง่ายเมื่อเทียบกับวิญญาณของปีศาจ...",
  str_voice_1400071_24 = "เอ่อ เห็นกระต่ายที่ดื่มน้ำมันดีเซลไหม ไม่เห็นเหรอ ฉันอยากถามว่าเขาจะมาสูดอากาศบริสุทธิ์กับฉันไหม",
  str_voice_1400071_25 = "ซินซาเป็นกาวที่เชื่อมเรดีเซล เวรนช์ไว้ด้วยกัน",
  str_voice_1400071_26 = "ถ้าเห็นกระต่ายนั่นก็อย่าไปยุ่งกับมันเลยนะ",
  str_voice_1400071_27 = "ฉันว่าลิเวียตอนนี้ก็เก่งพอสู้กับหมอนั่นโดยไม่ต้องมีใครช่วยเธอแล้วล่ะ",
  str_voice_1400071_28 = "ช่างเป็นที่กว้างใหญ่ที่อยู่อาศัยได้ด้วย แถมยังบินอยู่บนฟ้า ค่อนข้างอุ่นใจเหมือนกัน...",
  str_voice_1400071_29 = "ใบไม้และกลีบดอกไม้ใช้เป็นอาวุธร้ายแรงได้ แต่หัวใจมนุษย์กลับสร้างบาดแผลได้ลึกที่สุด...",
  str_voice_1400071_30 = "คมดาบใบไม้แหลมคมกว่าแล้วล่ะตอนนี้ ขอบใจที่ถามนะ",
  str_voice_1400071_31 = "พลังเป็นรากฐานของอิสระ",
  str_voice_1400071_32 = "ดอกไม้ก็เป็นอาวุธเช่นกัน",
  str_voice_1400071_34 = "นั่นเพื่อนในทีมฉันเหรอ...",
  str_voice_1400071_35 = "โคลเวอร์ประจำที่!",
  str_voice_1400071_36 = "นำทางเลย!",
  str_voice_1400071_37 = "ฉีกเป้าหมาย!",
  str_voice_1400071_38 = "คมดาบ! กวัดไกว!",
  str_voice_1400071_39 = "โคลเวอร์! โจมตี!",
  str_voice_1400071_40 = "บุปผาคมแปล๊บ!",
  str_voice_1400071_41 = "ฉันขอเลือกทีมของฉันเองได้ไหม",
  str_voice_1400071_42 = "กำจัดเป้าหมายแล้ว ฉันขอเวลาเช็ดฝุ่นดำ ๆ ออกจากใบไม้ของฉันหน่อยนะ",
  str_voice_1400071_43 = "ถอนกำลังเดี๋ยวนี้ ดูแลตัวเองด้วย!",
  str_voice_1400071_44 = "ที่นี่ทำให้จิตใจของฉันสงบไปด้วย...",
  str_voice_1400071_45 = "ขอบใจสำหรับของขวัญนะ",
  str_voice_1400071_46 = "ล้ำค่ามากเลย! ฉันขอเก็บไว้ได้ไหม",
  str_voice_1400071_47 = "ขอบคุณ เธอพยายามอย่างหนักจริง ๆ",
  str_voice_1400071_48 = "ฉันอยากได้เจ้านี่มาตลอดเลย! งั้น... ฉันรับไว้ได้จริง ๆ ใช่ไหม",
  str_voice_1400071_49 = "อย่าจับเด็กกำพร้าไปด้วยข้ออ้างว่ารัก มันจะทำให้หัวใจที่เปี่ยมรักกลับกลายเป็นคุกน้ำแข็ง... โชคดีที่ทุกอย่างก็มีจุดเปลี่ยน",
  str_voice_1400071_50 = "มีหลายคนที่เป็นเด็กกำพร้าเหมือนฉัน โชคดีที่ฉันได้พบกับอาจารย์ ผู้ที่เดินทางมาจากตะวันออกไกล...",
  str_voice_1400071_52 = "Alchemy Stars",
  str_voice_1400071_53 = "เฮ้...",
  str_voice_1400071_54 = "อรุณสวัสดิ์",
  str_voice_1400071_55 = "สวัสดียามบ่าย",
  str_voice_1400071_56 = "ราตรีสวัสดิ์",
  str_voice_1400071_57 = "ส-สุขสันต์วันปีใหม่",
  str_voice_1400081_1 = "วันนี้เป็นไงบ้าง ต้องการให้ทุบค้อนหน่อยไหม เฮ้ ล้อเล่นเฉย ๆ น่ะ",
  str_voice_1400081_2 = "ตอนฉันประจำการอยู่ ก็บำรุงรักษาเรือประจำวันไปบ้างแล้วล่ะ เหมือนที่ลูกพี่ซินซาว่าไว้ คนที่ไม่ทำงานจะอดกินอาหาร!",
  str_voice_1400081_3 = "ฉันสงสัยจังว่าลูกพี่ซินซากำลังทำอะไรอยู่ เขาชอบทำเรื่องงี่เง่าชวนให้คนอื่นเป็นห่วงอยู่เรื่อย ถ้าฉันไม่คอยเฝ้าเขาไว้นะ...",
  str_voice_1400081_4 = "ปาฏิหาริย์วิศวกรรมนี่แสนวิเศษชะมัด... ตอนฉันเห็นโคลอสซัสที่ทรงพลังนี้ทำตามคำสังของเธอ ฉัน... เอ่อ ไม่มีอะไร เธอช่างสุดยอดไปเลย!",
  str_voice_1400081_5 = "ฉันไม่ใช่ก้อนกรวดที่ร่วงหล่นอีกต่อไปแล้ว ในค่ำคืนนั้นมีคนส่องทางสว่างให้ฉันขณะที่ฉันพยายามจะหนี... คราวนี้ก็ถึงคราวที่ฉันต้องช่วยแล้ว",
  str_voice_1400081_7 = "เธอน่ะ... เอาชีวิตรอดมาตั้งนานในช่วงเวลานั้นได้ยังไง",
  str_voice_1400081_8 = "ถึงเธอจะไม่ใช่หนึ่งในเรดีเซล เวรนช์ แต่เธอก็ต่างจากพวกขี้ขลาดคนอื่นอยู่นะ ฉันเดาว่าเธอค่อนข้างมีคุณสมบัติเหมาะเป็นหัวหน้า ถึงลูกพี่ซินซาจะเก่งกว่าเธอนิดหน่อยก็เถอะ",
  str_voice_1400081_9 = "ถ้าเธอเป็นคนช่วยฉันวันนั้นแทนลูกพี่ซินซา... บางที... เฮ้อ ไม่มีอะไร!",
  str_voice_1400081_10 = "ฉันต้องเปลี่ยนชิ้นส่วนสำคัญของตลับลูกปืน... แล้วคำนวณความเร็วใหม่... เฮ้ มาอยู่ตรงนี้ตั้งแต่เมื่อไหร่",
  str_voice_1400081_11 = "ฉันทำงานเบื้องหลังดีกว่า... ช่างเถอะ ไหน ๆ เธอก็ยืนกรานแล้ว...",
  str_voice_1400081_12 = "เฮ้! อย่าเหยียบเครื่องมือของฉันสิ ใช่ ฉันกำลังหมายถึงขาข้างขวาของเธอน่ะ",
  str_voice_1400081_13 = "นี่เธอว่างไหม ช่วยฉันถักเปียหน่อยได้เปล่า... วันนี้ผมฉันฟูเกินกว่าจะถักเองได้น่ะ",
  str_voice_1400081_14 = "ผ้าพันคอผืนนี้เป็นสมบัติที่สำคัญที่สุด ก็เลยต้องซักด้วยความระมัดระวัง... เฮ้ ฉันไม่ได้ขอให้เธอซักสักหน่อย!",
  str_voice_1400081_15 = "เธอคาดหวังให้ฉันร้องเพลงวันเกิดให้เหรอ... ฉันเอากล่องดนตรีให้เธอดีกว่า",
  str_voice_1400081_16 = "โย่ เธอมาแล้วเหรอ นึกว่าจะไม่กลับมาแล้วเสียอีก",
  str_voice_1400081_17 = "ฉันจะติดตั้งแสงไฟปลอม ๆ ให้เธอ แต่ฉันว่าคงไม่มีความจำเป็นแล้วละ",
  str_voice_1400081_18 = "เธออยากลองบ้างบางครั้งไหมล่ะ... ช่างเถอะ บางทีการเป็นฝ่ายเทคโนโลยีก็ยากอยู่นะ",
  str_voice_1400081_19 = "บางครั้งแสงสว่างเจิดจ้าก็เลวร้ายยิ่งกว่าค่ำคืนมืดมิดเสียอีก โย่... ก็ไม่เป็นไร",
  str_voice_1400081_20 = "จะขโมยอะไรก็ควรเลือกหน่อยไม่ใช่เหรอ ทำไมคนพวกนั้นถึงชอบเอาขยะกลับมาอยู่เรื่อย...",
  str_voice_1400081_21 = "ได้ยินว่าอิลลูมินาให้ค่ากับเทคโนโลยีวิทยาศาสตร์... อย่าเข้าใจฉันผิดนะ ฉันก็มีความสำคัญมากในเรดีเซล เวรนช์เหมือนกัน!",
  str_voice_1400081_22 = "พักจากการตะโกนบ้าง",
  str_voice_1400081_23 = "ฉันว่าฉันเข้าใจเหตุผลที่อิคลิพไซท์กลัวแสงสว่างแล้วล่ะ",
  str_voice_1400081_24 = "ดูโอดีสิแล้วจะเข้าใจว่าเป็นฝ่ายเทคโนโลยีมันลำบากแค่ไหน เขามักจะโกรธมากที่เขาคิดอะไรไม่เคยออกเลย",
  str_voice_1400081_25 = "ฉันไม่ได้ขอให้เขาช่วยชีวิตฉัน เขาเองนั่นแหละที่อดใจช่วยฉันไม่ได้... แต่ฉันค่อนข้างปลื้มใจในตัวเขานะ",
  str_voice_1400081_26 = "แฮนด์เมดก็คือการศึกษาเทคโนโลยีและจัดสรรชิ้นส่วนหลากหลายอย่าง!",
  str_voice_1400081_27 = "ฉันไม่ชอบผู้ชายไร้ความสามารถและไม่ชอบพวกไร้ประโยชน์ที่เอาแต่พูดแต่ไม่ยอมลงมือทำ! รวมถึงตัวฉันเองด้วย",
  str_voice_1400081_28 = "จะไม่ร่วมมือกับเราจริงเหรอ ถ้าไม่อยากได้โคลอสซัสแล้ว ฉันจะลากมันกลับมากลับเราเอง ฉันพูดจริงนะ!",
  str_voice_1400081_29 = "อย่าเข้าใจฉันผิดไป เรามาเพื่อทดสอบความกล้าหาญของเธอเบื้องหลังลูกพี่ซินซา!",
  str_voice_1400081_30 = "เพิ่มพลังแล้ว!",
  str_voice_1400081_31 = "ระดับสิทธิพิเศษนี่ไม่ใช่ของจริงหรือไง",
  str_voice_1400081_32 = "ฉันจะเป็นแสงสว่างที่เปล่งประกายยามค่ำคืน!",
  str_voice_1400081_34 = "เธอน่าจะเลือกฉันให้เร็วกว่านี้นะ!",
  str_voice_1400081_35 = "สปอตไลท์พร้อมแล้ว!",
  str_voice_1400081_36 = "แถ่นแท้น!",
  str_voice_1400081_37 = "รับประกายแสงสว่างของฉันไปเลย!",
  str_voice_1400081_38 = "กำจัดความกลัวของเธอด้วยแสงซะ!",
  str_voice_1400081_39 = "สว่างพอไหม",
  str_voice_1400081_40 = "แสงสว่างของฉันจะทำให้เธอตาบอด",
  str_voice_1400081_41 = "อาฮะ! ทำตามคำสั่งของฉันเลย!",
  str_voice_1400081_42 = "ฮิ ๆ ยังไงฉันก็มาแล้ว!",
  str_voice_1400081_43 = "อย่ามัวแต่ยืนอยู่ตรงนั้น เจ้าบื้อ วิ่งสิ!",
  str_voice_1400081_44 = "ไม่ต้องห่วงเรื่องความสูงฉัน ห่วงเรื่องโคลอสซัสของเธอแทนไปเถอะ ฮึ่ม!",
  str_voice_1400081_45 = "... อะไรเนี่ย",
  str_voice_1400081_46 = "ว้าววว สุดยอดไปเลยแฮะ!",
  str_voice_1400081_47 = "...ขอให้เป็นของมีประโยชน์",
  str_voice_1400081_48 = "ของขวัญนี้ถูกใจมากเลย รู้ใจจัง",
  str_voice_1400081_49 = "อย่าตัดสินฉันจากแค่ภายนอกสิ ฉันโตมาในลานขยะเลยประกอบอุปกรณ์ทุกอย่างเป็น... อ๋อ ที่นั่นเรียกว่าคลังเก็บรางวัลน่ะ...",
  str_voice_1400081_50 = "ฮึ่ม ถ้าไม่จริงจังละก็ บางทีเรดีเซล เวรนช์ อาจจะยึดยานเข้าสักวัน เฮ้ มาลูบหัวฉันทำไมเนี่ย ฉันซีเรียสอยู่นะ",
  str_voice_1400081_52 = "Alchemy Stars",
  str_voice_1400081_53 = "ได้ยินฉันไหม...",
  str_voice_1400081_54 = "ตื่นหรือยัง",
  str_voice_1400081_55 = "ช่วยมาที่นี่หน่อยได้ไหม",
  str_voice_1400081_56 = "ถ้าเธอยังไม่นอนน่ะนะ...",
  str_voice_1400081_57 = "ถ้าอยากได้คนอวยพร \"สุขสันต์วันปีใหม่\" ก็เชิญป้ายหน้าได้เลย",
  str_voice_1400161_1 = "เวลาตื่นนอนทีไรโลกทั้งใบจะเป็นศัตรูของฉัน อย่าเพิ่งคุยกับฉันสักพักนะ",
  str_voice_1400161_2 = "ถ้าเป็นไปได้ก็อย่าเอาของฟูฟ่องนั่นมาใกล้ฉันนะ",
  str_voice_1400161_3 = "ไม่รู้ว่าฟรานซ์ไปไหนอีกแล้ว ก็ดีแล้วมั้งอย่างนั้นน่ะ",
  str_voice_1400161_4 = "มีคนกลั่นแกล้งปั๊ปปี้เหรอ พาฉันไปที่นั่นเลย ฉันจะให้เจ้านั่นใช้ชีวิตต่อไปโดยปราศจากมือ...",
  str_voice_1400161_5 = "เราต้องตรวจสอบกระสุนให้ถี่ถ้วน พวกมันชอบติดตอนเราจะยิงใส่พวกที่โจมตีสัตว์ตัวเล็ก ๆ...",
  str_voice_1400161_6 = "ฉันมีปืนที่ดีกว่านี้แล้ว ฉันจะมุ่งเป้าไปที่สิ่งมีชีวิตที่น่ารังเกียจเหล่านั้น—พวก Eclipsites ผู้ส่งเสียงดัง และผู้ทรมานสัตว์เล็ก",
  str_voice_1400161_7 = "จะฟูฟ่องหรือไม่ คนที่มากวนฉันจะถูกยิง แล้วก็รวมถึงเธอด้วย",
  str_voice_1400161_8 = "เพื่อน ๆ พวกนี้ชอบให้ฉันเดินตรวจตราอยู่คนเดียว เธอน่ะ! มาแทนที่ฉันซิ",
  str_voice_1400161_9 = "ใครก็ตามที่มากวนฉันตอนหลับจะได้รับการดูแลแบบอิคลิพไซท์ รวมถึงเธอด้วย",
  str_voice_1400161_10 = "ฉันจะงีบสักหน่อย เธอน่ะ! เอาพวกสัตว์ไปซิ อย่ามากวนฉัน",
  str_voice_1400161_11 = "เธออยากให้ฉันตรวจตราเหรอ ก็ได้ ยังไงฉันก็โต้รุ่งทั้งคืนอยู่ดี",
  str_voice_1400161_12 = "เหนื่อยแล้วเหรอ แต่เธอพักตอนนี้ไม่ได้นะ ฉันนอนดึกตลอดเวลาอยู่แล้ว",
  str_voice_1400161_13 = "เจ้าเปี๊ยกน่ารำคาญนี่ถูตัวกับฉันอีกแล้ว! คาฟกา หยุดทำตัวออเซาะได้แล้ว...",
  str_voice_1400161_14 = "นาน ๆ ทีก็ต้องหยุดพักบ้าง ฟรานซ์อยู่ไหนเนี่ย ฟรานซ์ บอกหลายครั้งแล้วไม่ใช่เหรอว่าให้อยู่ใกล้ ๆ ฉันเอาไว้",
  str_voice_1400161_15 = "วันเกิดเธอเหรอ อยากให้ฉันอวยพรด้วยงั้นสิ",
  str_voice_1400161_16 = "ตอนนี้เป็นตอนที่เจ้าพวกตัวฟูจะร่าเริงที่สุด คอยดูพวกนั้นให้ดี อย่าปล่อยให้พวกมันหลุดไปได้ล่ะ!",
  str_voice_1400161_17 = "กล้ามาขัดการนอนของฉันได้ไง! โอ้... เช้าแล้วนี่ เหมือนฉันจะโต้รุ่งอีกแล้วสินะ",
  str_voice_1400161_18 = "ไม่มีใครมาอยู่กะต่อไปเลยเหรอ พวกชอบอู้ทั้งหลายนี่นะ! สักวันฉันจะยิงพวกมันตอนกลางดึกซะ...",
  str_voice_1400161_19 = "ฉันเหนื่อยจะแย่ พอแล้ว ฉันไม่ทำกะนี้แล้ว ฉันจะไปนอน!",
  str_voice_1400161_20 = "ใช่ พวกนั้นเป็นคนดีหมดแหละ แต่บางทีทุกคนก็หละหลวมกันบ้าง! ฉันเป็นคนเดียวที่มาตรวจตรา เห็นรอยใต้ตาดำนี่ไหมล่ะ",
  str_voice_1400161_21 = "คนจากอิลลูมินาพยายามเอาปืนฉันไปศึกษาอย่างหนักเลยละ ฉันยอมให้เอาไปทำแบบนั้นที่ไหนล่ะ พวกนี้หมกมุ่นบ้าบอสิ้นดี!",
  str_voice_1400161_22 = "ปล่อยให้พวกนักเลงนั่นลิ้มรสของการถูกถูตัวจนล้มลงไปกับพื้นเถอะ",
  str_voice_1400161_23 = "ตราบใดที่ฉันมีปืน ฉันจะฆ่าพวกอิคลิพไซท์ที่มาขวางทางฉันจนหมด แล้วก็ส่งพวกมันกลับบ้านเก่าไปตลอดกาล",
  str_voice_1400161_24 = "กิ้งก่าตัวใหญ่นั่น! ไม่อยากจะพูดเลยแต่มันก็น่ารักอยู่นะ... หา อะไรนะ ฉันพูดอะไรเหรอ",
  str_voice_1400161_25 = "ฉันไม่ได้เห็นคู่หูเพนกวินและหมีมานานแล้ว พวกนั้นยังหาเครื่องปรับอากาศอยู่ไหม ถ้ามีโอกาสเดี๋ยวฉันจะให้อะไหล่บางชิ้นกับพวกนั้นไป",
  str_voice_1400161_26 = "ควบคุมตัวเองหน่อย คาฟกา... ฉันจะกลับไปลูบเพื่อนตัวฟูนั่นทีหลัง...",
  str_voice_1400161_27 = "เสียงนั่น! เสียงน่ะ! ทำไมถึงไม่มีเตียงเงียบ ๆ สักเตียงให้นอนเลยในทะเลทรายเรดีเซลอันกว้างใหญ่",
  str_voice_1400161_28 = "สหายผู้นี้ตัวใหญ่ขนาดไหนกันเนี่ย! ว่ากันว่าพวกมันมีความคิดเป็นของตัวเองด้วย ถ้าอย่างนั้นก็ให้มันออกมาตรวจตราไป",
  str_voice_1400161_29 = "ชื่อคาฟกา ฉันมีข้อเสนอสามอย่างคือ อย่าให้ฉันมาเดินตรวจตรา ขออพาร์ทเมนต์ห้องชุดกันเสียงสำหรับคนโสด และไล่สัตว์พวกนั้นไปให้ห่างฉัน!",
  str_voice_1400161_30 = "เร็วขึ้นและแม่นยำขึ้น",
  str_voice_1400161_31 = "ฟรานซ์! ไปเลย!",
  str_voice_1400161_32 = "ใช้กระสุนทรงพลังอีกกันเถอะ!",
  str_voice_1400161_33 = "ยิง! ยิงให้บ้าคลั่งไปเลย!",
  str_voice_1400161_34 = "ไม่ปรานีกับศัตรูหน้าไหน!",
  str_voice_1400161_35 = "กำลังค้นหาศัตรู...",
  str_voice_1400161_36 = "เกาส์ไรเฟิล! เล็ง!",
  str_voice_1400161_37 = "ยิง!",
  str_voice_1400161_38 = "หมดทางซ่อนแล้ว!",
  str_voice_1400161_39 = "สนามไฟฟ้าแรงสูง! ห่ากระสุน!",
  str_voice_1400161_40 = "ยิงระยะใกล้!",
  str_voice_1400161_41 = "ฉันจ้องมองพวกมันเหมือนเหยี่ยว",
  str_voice_1400161_42 = "ง่ายนิดเดียว",
  str_voice_1400161_43 = "เครียดเกินไปแล้ว ฉันไม่เอาด้วยแล้ว...",
  str_voice_1400161_44 = "ที่นี่ไม่มีสัตว์เหรอ เยี่ยมเลย! อ่า แต่ก็ค่อนข้างน่าเบื่อนะ...",
  str_voice_1400161_45 = "ของขวัญให้ฉันเหรอ ก็ได้ ฉันจะรับไว้",
  str_voice_1400161_46 = "ของขวัญนี่ดูดีจังเลย...",
  str_voice_1400161_47 = "น่าจะมีค่ามหาศาลเลยนะ ขอบใจ!",
  str_voice_1400161_48 = "สิ่งนี้เหรอ ว้าว ขอบใจมาก!",
  str_voice_1400161_49 = "เรดีเซล เวรนช์เหรอ ตอนแรกฉันก็ไม่ได้ตั้งใจจะเข้าแก๊งหรอกแต่กิ่งก่าตัวเป้งนั่นทำให้ยากต่อการปฏิเสธน่ะ",
  str_voice_1400161_50 = "อยากรู้เหรอว่าฉันได้ปืนไรเฟิลนี้มาได้ไง เป็นเรื่องที่น่าสนใจนะ แต่ก่อนหน้านั้น ช่วยไล่พวกเพื่อนตัวน้อยที่ชอบเกาะแกะออกไปก่อนได้ไหม",
  str_voice_1400161_51 = "บ้านของฉันเคยเป็นปราสาทน้อย ๆ มาก่อน ไม่ใช่กิ้งก่าตัวใหญ่นี่นะ ถ้าไม่ใช่เพราะอิคลิพไซท์... หืม... ไม่อยากเล่าแล้วล่ะ ฉันจะนอน",
  str_voice_1400161_52 = "Alchemy Stars!",
  str_voice_1400161_53 = "เธออยู่ตรงนั้นไหม",
  str_voice_1400161_54 = "ฉันรู้ยังเช้าอยู่",
  str_voice_1400161_55 = "แต่เธอพอจะมีเวลาไหม",
  str_voice_1400161_56 = "เธอเข้าเวรอยู่เหรอ",
  str_voice_1400161_57 = "คือ ฉันจะพูดแล้วนะ... อ่ะแฮ่ม สุขสันต์วันปีใหม่จ้ะ",
  str_voice_1400351_1 = "บริการของสหภาพผู้ส่งสารไม่มีจำกัด!",
  str_voice_1400351_2 = "ฉันสงสัยอยู่ว่าเธอเอาออร์แกนนั่นเข้ามาในนี้ได้ไง มันใหญ่กว่าประตูอีกนะ!",
  str_voice_1400351_3 = "โยชิคิดว่าเธอน่ารักดี โยชิพูดจริง ๆ นะ ไม่ใช่ฉันหรอก!",
  str_voice_1400351_4 = "อะไรกัน เธอคิดว่าโยชิตอนนี้เก่งกว่าฉันก่อนเลื่อนขั้นอีกเหรอ ฉันทำงานทั้งวันได้ทุกวันเลยนะ แล้วมันทำได้ไหมล่ะ",
  str_voice_1400351_5 = "เห็นแสงสว่างวาบในตาฉันไหม มันแปลว่าเธอทำงานที่ต้องส่งของฉันหมดแล้ว และฉันไม่ต้องทำงานดึกแล้วไง!",
  str_voice_1400351_7 = "บางคนก็ว่าสหภาพผู้ส่งสารประกอบไปด้วยนักสำรวจต่าง ๆ แหงสิ อย่างกับเรามีเวลาว่างเยอะงั้นแหละ!",
  str_voice_1400351_8 = "ฉันแอบยัดกัมมี่จากนอร์ธแลนด์ไปให้เธอด้วย ได้มาจากทริปธุรกิจของฉันน่ะ อย่าเอาไปแบ่งกับคนอื่นล่ะ!",
  str_voice_1400351_9 = "ชีวิตฉันก็มีแต่ทำงาน ชีวิตเธอก็ควรต้องเป็นอย่างนั้นด้วย ถ้าเป็นแบบนั้นเราก็มีอะไรให้คุยกันมากมาย!",
  str_voice_1400351_10 = "- เธอเหม่อแล้วดูน่ารักจัง เอ่อ ได้ยินหรือเปล่า ย-โยชิ เธอต้องเลิกพูดอะไรแปลก ๆ แบบนั้นนะ!\n- ก้า!",
  str_voice_1400351_11 = "ถึงฉันจะไม่เก่งเรื่องแบบนี้ก็เถอะ...",
  str_voice_1400351_12 = "ได้ตัดสินหรือยังว่างานที่มอบหมายให้ฉันทำเป็นยังไง ฉันไม่มีเวลามารอเธอทั้งวันที่นี่หรอกนะ",
  str_voice_1400351_13 = "ตราบใดที่มีจิตใจสูงส่ง ต่อให้ขอบตาคล้ำ ดำบวมยังไง ก็ไม่ต้องสนใจ",
  str_voice_1400351_14 = "อย่าไปสนโดฟจอมขี้เกียจเลย ไม่มีใครเหมือนนางในสหภาพอีกแล้วล่ะ",
  str_voice_1400351_15 = "อวยพรวันเกิดให้สองรอบเลย! หนึ่งคำอวยพรจากฉัน อีกคำอวยพรจากโยชิ!",
  str_voice_1400351_16 = "เหมือนเธอดูยุ่งตลอดเวลาเลย แบบเอโฮะน่ะ",
  str_voice_1400351_17 = "สวัสดียามเย็น โอ๊ะโอ ไม่ต้องห่วงเรื่องนั้นหรอก เอโฮะเพิ่งทักทายโยชิไปน่ะ",
  str_voice_1400351_18 = "ยังไม่สายเกินกว่าที่จะไปเที่ยวกับเอโฮะนะ",
  str_voice_1400351_19 = "ฉันน่าจะเป็นคนเดียวที่ยังไม่นอนในเวลานี้",
  str_voice_1400351_20 = "ให้เราจัดการทุกอย่างเองเถอะ ทุกคนในสหภาพก็เหมือนฉันหมด \"เราทุกคนรักการทำงานหนัก!\"",
  str_voice_1400351_21 = "บางครั้งกิลด์ก็อ่านจดหมายของคนอื่นก่อนโดยไม่ขออนุญาต ขนาดเรดีเซลยังไม่ทำแบบนั้นเลย",
  str_voice_1400351_22 = "สหภาพผู้ส่งสาร! จดหมายทุกฉบับถึงปลายทางแน่นอน!",
  str_voice_1400351_23 = "ผู้ส่งสารจะไม่เกี่ยวข้องในการต่อสู้กับอิคลิพไซท์ ยกเว้นจะได้รับมอบหมายให้สู้",
  str_voice_1400351_24 = "ผู้สูงอายุของสหภาพค่อนข้างใจดีกันทุกคน เป็นเพราะว่าผู้ส่งสารส่วนใหญ่ไม่จำเป็นต้องให้ใครมากำกับดูแล",
  str_voice_1400351_25 = "ผู้ส่งสารที่อยู่เฉย ๆ งั้นเหรอ เธอหมายถึงโดฟแน่เลย ถ้านางยังเป็นแบบนั้นไม่เลิกจะพาลโดนไล่ออกไม่ช้าก็เร็ว",
  str_voice_1400351_26 = "โยชิบอกว่ารสชาติช็อคโกแลตเฮเซลนัท ฟินจนยอมพลีชีพเลยละ",
  str_voice_1400351_27 = "ขอล่ะนะ อย่าไปพูดกับโดฟเรื่องเอโฮะ ห้ามเด็ดขาดเชียว",
  str_voice_1400351_28 = "เอโฮะกับโยชิบินออกไปข้างนอกโคลอสซัสเป็นเพื่อนกันได้เมื่อยามสภาพอากาศไม่ดี",
  str_voice_1400351_29 = "มีจดหมายมาส่งจ้ะ คนน่ารัก!",
  str_voice_1400351_30 = "ฉันขอลองสิ่งที่เพิ่งเรียนมาได้ไหม",
  str_voice_1400351_31 = "เบิกเนตร!",
  str_voice_1400351_32 = "ฉันเป็นคนประเภทที่อาจก่อเรื่องได้นะ!",
  str_voice_1400351_34 = "งั้นก็ต้องทำล่วงเวลาสินะ!",
  str_voice_1400351_35 = "ฉันพร้อม!",
  str_voice_1400351_36 = "สรุปว่าฉันต้องเป็นคนปิดฉากสินะ",
  str_voice_1400351_37 = "โยชิ ไปกับฉันเลย!",
  str_voice_1400351_38 = "สายฟ้าจงคำราม!",
  str_voice_1400351_39 = "ทางสะดวกแล้ว",
  str_voice_1400351_40 = "เคลื่อนย้ายสิ่งกีดขวาง!",
  str_voice_1400351_41 = "ผู้ส่งสารทุกคนเป็นผู้บุกเบิกโดยกำเนิด!",
  str_voice_1400351_42 = "กรงเล็บและขนนกของผู้ส่งสารต้องไม่ถูกดูแคลน!",
  str_voice_1400351_43 = "มันเยอะกว่างานที่ฉันขอจริง ๆ นะเนี่ย",
  str_voice_1400351_44 = "พ่อตัวใหญ่นั่นจำเป็นต้องกระพือปีกตอนออกบินด้วยเหรอ",
  str_voice_1400351_45 = "ขอบใจนะ ถึงมันจะ... เอ่อ... ขอบใจ!",
  str_voice_1400351_46 = "ว้าว! ฉันดีใจจนตัวลอยแล้ว โยชิก็เหมือนกัน",
  str_voice_1400351_47 = "งั้นฉันก็ยินดีรับไว้นะ ฉันชอบทุกอย่างที่เธอให้แหละ!",
  str_voice_1400351_48 = "รู้ตลอดได้ยังไงว่าโยชิชอบอะไรที่สุด",
  str_voice_1400351_49 = "เราส่งของให้ถึงมือเสมอ บริการของสหภาพไม่มีขอบเขต ฉันก็เหมือนกัน ถ้ามีงานซับซ้อนที่อยากเรียกใช้บริการ ก็ติดต่อสาขาใกล้บ้านได้เลย",
  str_voice_1400351_50 = "เพื่อนร่วมงานกับฉันชอบวิ่งไปทั่วทวีป ผ่านเมืองโบราณมืดมิดและทะเลทรายระยิบระยับ ไม่ว่าระยะทางจะไกลแค่ไหนเราก็จัดการให้ได้เสมอ!",
  str_voice_1400351_52 = "Alchemy Stars!",
  str_voice_1400351_53 = "ฟังฉันให้ดี!",
  str_voice_1400351_54 = "เช้าแล้ว! เช้าแล้วนะ! ตื่นสิ!",
  str_voice_1400351_55 = "เที่ยงตรงแล้ว! ก้า!",
  str_voice_1400351_56 = "ฟังฉันนะ! อึก!",
  str_voice_1400351_57 = "สุขสันต์วันปีใหม่เหรอ ถ้าฉันไม่ทำงานล่วงเวลา...",
  str_voice_1400401_1 = "อยากลองชิมป็อปร็อกส์หน่อยไหม ทุกคนในฝ่ายวิทยาศาสตร์ชอบรสนี้มากเลย อ้าว ขอโทษที ฉันให้ผิดอันไป นั่นมันระเบิดน่ะ",
  str_voice_1400401_2 = "เธอเคยเห็นพลุหรือเปล่า ฮึ่ม! ฉันจะทำให้พวกงั่งที่มาวุ่นวายกับฉันกระจุยเหมือนระเบิดไฮโดรเจนแน่",
  str_voice_1400401_3 = "ระเบิดน่ะโรแมนติกจะตาย! ไม่เข้าใจเหรอ งั้นเธอก็คงไม่เข้าใจจิตวิญญาณของเลดี้วัยรุ่นสินะ",
  str_voice_1400401_4 = "ดอกไม้ไฟเหรอ... สวยมากเลย! เธอไม่ได้หวังจะ \"เป็น\" แค่ดอกไม้ไฟหรอกรึ ไม่ต้องห่วง ฉันเชี่ยวชาญเรื่องนี้ดี",
  str_voice_1400401_5 = "ฉันคิดจะสร้างอันใหม่ ๆ ขึ้นมา... เจ้าจิ๋วบอกว่าสีแดงน่ะดี เธออยากให้สึอะไรเบ่งบานเป็นพิเศษไหม",
  str_voice_1400401_6 = "เพื่อนรักเอ๋ย ทำระเบิดทองนี่ตกไว้หรือเปล่า ระเบิดเงินล่ะ หรือชุดระเบิดธรรมดาล่ะ อันที่จริง เก็บเอาไปให้หมดเลยก็ได้นะ!",
  str_voice_1400401_7 = "ป็อปร็อกส์ดีออกใช่ไหม ระเบิดในปากอย่างนี้วิเศษเหมือนระเบิดอย่างอื่นเลยละ!",
  str_voice_1400401_8 = "ช่วงนี้อยากระเบิดอะไรไหม ขนาดเท่าไหร่ก็ได้ จะเป็นแตงโม ตึก หรือลูโมโพลิสก็ได้นะ",
  str_voice_1400401_9 = "โว้ว! จู่ ๆ โผล่มาแบบนั้นได้ไง โธ่! นึกว่าจะตกใจจนหัวใจระเบิดแล้วสิ...",
  str_voice_1400401_10 = "ถ้าฉันไม่ทำอะไร ฉันก็เบื่อแย่เลยสิ ขอไปเล่นกับเจ้าจิ๋วได้ไหม",
  str_voice_1400401_11 = "ฉันมาแล้ว! เริ่มปาร์ตี้ได้เลย!",
  str_voice_1400401_12 = "โซดาเย็นก็ดีนะ ไนโตรกลีเซอรีนเย็นก็ดีเหมือนกัน! หืม ดูคล้องจองกันแฮะ",
  str_voice_1400401_13 = "ดมสิ! กลิ่นหอมหวานของระเบิดพิเศษนี้น่ะ ไม่ต้องห่วง แค่ดมไม่ทำให้ระเบิดหรอก",
  str_voice_1400401_14 = "เธอเอาแว่นตากับกระเป๋าเป้มาด้วยสิ เก็บของแล้วมาสนุกกันเถอะ!",
  str_voice_1400401_15 = "ยื่นมือออกมาแล้วปิดตาซะ! อันหนึ่งของมือซ้าย อันหนึ่งของมือขวา ขอให้สนุกกับระเบิดนะ",
  str_voice_1400401_16 = "กลับมาเข้าทีมแล้วเหรอ ทำไมเราไม่ออกไปจุดดอกไม้ไฟแล้วฉลองหน่อยล่ะ อ้าว ตายแล้ว! จุดไปแล้วนี่นา",
  str_voice_1400401_17 = "ตื่นแล้วเหรอ ฉันเอาอุปกรณ์หลายอย่างไว้บนโต๊ะข้างเตียงเธอด้วยนะ ไม่เห็นเหรอ",
  str_voice_1400401_18 = "กลับมาทันเวลาพอดี อยากลองหนอนทรายไหม ปิ้งเสร็จใหม่ ๆ เลย อืม... กลิ่นหอมมาก",
  str_voice_1400401_19 = "จะนอนแล้วเหรอ อยากให้จุดประทัดก่อนนอนไหม มันจะทำให้หลับสบายนะ!",
  str_voice_1400401_20 = "ที่เรดีเซล ผู้คนได้ไปขับรถเล่นทุกวันและหาอาหารหลายประเภทในทะเลทราย",
  str_voice_1400401_21 = "อ้อ ฉันฝังสมบัติไว้ก่อนไปที่อิลลูมินาน่ะ สงสัยจังว่าพวกนั้นเจอหรือยัง...",
  str_voice_1400401_22 = "ระเบิดให้แหลก!",
  str_voice_1400401_23 = "เธอได้รับระเบิด \"ตูม!\" เธอได้รับระเบิด \"ตูม!\" ทุกคนได้รับระเบิด!",
  str_voice_1400401_24 = "ลูกพี่ชอบพาคนไปเก็บขยะแล้วเอาวัสดุวิจัยกลับมาเยอะมาก!",
  str_voice_1400401_25 = "ฉันกับเจ้าจิ๋วมักจะแยกขยะด้วยกัน... เดี๋ยวนะ หรือว่ามันเป็นการแยกถ้วยรางวัลอย่างที่นางเรียกกันนะ",
  str_voice_1400401_26 = "เหล็กดังก๊องแก๊ง ระเบิดปะทุ และป็อปร็อกส์แตกปุปะ!",
  str_voice_1400401_27 = "ฉันทนชีวิตเงียบงันไม่มีเสียงไม่ได้ มาส่งเสียงกันเถอะ!",
  str_voice_1400401_28 = "ฉันรู้แล้ว โคลอสซัสดูถอดประกอบง่ายนะ พุ่งชนในที่เหมาะ ๆ สักครั้งก็คงแหลกเป็นชิ้น",
  str_voice_1400401_29 = "ยินดีที่ได้รู้จัก! ฉันคือโจแอนนี บูม เอาระเบิดที่ฉันใส่ไว้ในกระเป๋าเธอไปเป็นของขวัญต้อนรับซะสิ",
  str_voice_1400401_30 = "เพิ่มพลังไป \"เต็ม\" เหนี่ยว!",
  str_voice_1400401_31 = "สูตรใหม่!",
  str_voice_1400401_32 = "เราจัดแสดงดอกไม้ไฟได้เลยตอนนี้ วู้วววว น่าตื่นเต้นชะมัด!",
  str_voice_1400401_33 = "คราวนี้ใครจะโชคดีถูกส่งขึ้นฟ้ากันนะ?",
  str_voice_1400401_34 = "ลุยกันเลย!",
  str_voice_1400401_35 = "เราเริ่มนับถอยหลังกันได้แล้ว!",
  str_voice_1400401_36 = "ฉันจะให้เธอได้เห็นดอกไม้ไฟที่เจ๋งที่สุด!",
  str_voice_1400401_37 = "จงระเบิดอย่างยิ่งใหญ่!",
  str_voice_1400401_38 = "แผดเผาและเบ่งบานบนท้องฟ้า!",
  str_voice_1400401_39 = "ตูม! ฟู่! ตูม!",
  str_voice_1400401_40 = "แผดเผาเป็นเถ้าถ่าน! ชาลาลาลา ♪",
  str_voice_1400401_41 = "เอ้า ระเบิดสำหรับพวกเธอคนละลูก",
  str_voice_1400401_42 = "เรียบร้อยดีมาก นี่เป็นการแสดงดอกไม้ไฟที่เยี่ยมมาก!",
  str_voice_1400401_43 = "ผมฉันไหม้แล้ว... โฮ ๆ...",
  str_voice_1400401_44 = "เดาซิว่ามือข้างไหนของฉันถือระเบิดอยู่ โธ่! ก็ต้องสองข้างอยู่แล้วสิ",
  str_voice_1400401_45 = "ไม่เลว!",
  str_voice_1400401_46 = "สนุกมากเลย ดีใจจัง!",
  str_voice_1400401_47 = "เยี่ยมมาก ระเบิดอีกอันกันเถอะ!",
  str_voice_1400401_48 = "อย่างนี้เยี่ยมไปเลย ฉันจะเอาไปเก็บเดี๋ยวนี้ล่ะ!",
  str_voice_1400401_49 = "ครั้งหนึ่งฉันเคยเกือบระเบิดฐานบ้านของเรดีเซล เวรนช์... โว้ว... ใจเย็น! อุบัติเหตุน่ะ ถึงฉันจะค่อนข้างชอบผลลัพธ์ที่ออกมาก็เถอะ...",
  str_voice_1400401_50 = "ของน่าเบื่อเหรอ เพื่อนน่ารำคาญงั้นเหรอ ก็ระเบิดทิ้งไปให้หมดเลย! เธอไม่เห็นด้วยหรือ",
  str_voice_1400401_51 = "ฉันมาจากสายดินประสิวและมีหน้าที่วิจัยเฉพาะทาง ฉันช่วยเหลือทุกคนได้มากเลยละ อันที่จริงฉันก็ทำอย่างเดียวนั่นแหละ ก็คือ ระเบิดของไง!!",
  str_voice_1400401_52 = "Alchemy Stars! ตูม!",
  str_voice_1400401_53 = "ตูม! ออกมาเถอะ!",
  str_voice_1400401_54 = "เห็นดอกไม้ไฟแถวโต๊ะข้างเตียงเธอไหม",
  str_voice_1400401_55 = "เฮ้! ฉันเพิ่งระเบิดบางอย่างไปแหละ",
  str_voice_1400401_56 = "ออกมาจากที่นั่นเลย เร็วเข้า!",
  str_voice_1400401_57 = "งานฉลองปีใหม่ก็คือระเบิดทุกอย่างให้หมด!",
  str_voice_1400411_1 = "ความมุ่งมั่นตั้งใจเป็นนิสัยตามอาชีพของฉัน หวังว่าเธอจะไม่ว่าอะไรนะ เชิญทางนี้เลย",
  str_voice_1400411_2 = "บนผนังด้านหลัง รู้สึกเหมือนมีบางอย่างขาดหายไป อ้อรู้ล่ะ มันเป็นเวอร์ชันรีมาสเตอร์ยุคใหม่ของหญิงสาวบนสะพานแขวน",
  str_voice_1400411_3 = "ทะเลสาบสวอน มหาวิหารหลวง และหอคอยลอยฟ้าบนเขาลัคห์บิน... ฉันควรแนะนำที่ไหนก่อนดี",
  str_voice_1400411_4 = "ฉันจำเรื่องทุกอย่างเกี่ยวกับลูโมโพลิสได้ดี คุ้นเคยกับละแวกทั้งหมดแล้วก็เคารพละอองฝุ่นทุกจุด",
  str_voice_1400411_5 = "ความลับของหญิงสาวผู้สง่างามงั้นเหรอ อยู่ในกระเป๋าเดินทางของฉันทั้งหมดเลย อยู่ดี ๆ เธอจะมาเปิดไม่ได้หรอก ของพวกนี้เป็นความลับเล็ก ๆ ของผู้หญิงน่ะ",
  str_voice_1400411_6 = "เดินผ่านเส้นทางที่สว่างไสวและลืมเลือนอดีตที่มืดมนไปก่อนฟ้าสาง ฉันคือมิสรอตหรือเรียกว่ามิสบลังค์ก็ได้ ยินดีต้อนรับสู่รัตติกาลสีขาว!",
  str_voice_1400411_7 = "ฉันพลาดเส้นผมไปเส้นหนึ่งเหรอ ขออภัยด้วยนะ ฉันต้องคงความสง่างามไว้เสมอแม้ว่าจะทำงานตลอดเวลาก็ตาม",
  str_voice_1400411_8 = "มิสรอตเหรอ ฉันคิดถึงวันวานแล้วสิ บางครั้งฉันก็คิดถึงวันวานที่ผ่านเลยไปแล้วพบว่าชีวิตของฉันมันน่าเหลือเชื่อสิ้นดี",
  str_voice_1400411_9 = "ฉันมีประสบการณ์เกือบทุกเรื่องในลูโมโพลิส แต่ตอนนี้ ฉันรู้สึกว่าเป็นได้แค่ผู้ชม",
  str_voice_1400411_10 = "งั้นเธอก็รู้สินะว่าควรพักผ่อนเมื่อไหร่ ฉันมักจะหาเวลาพักผ่อนเหมือนกัน อยากดื่มกาแฟสุดพิเศษหน่อยไหมล่ะ",
  str_voice_1400411_11 = "ฉันคุ้นเคยกับสถานที่ทั้งหมดนี้เลยละ สรุปแล้วเธออยากไปที่ไหน",
  str_voice_1400411_12 = "อืมม กลิ่นวานิลลาทำให้ได้รสชาติที่เป็นเอกลักษณ์ กาแฟนี่แหละคือคำตอบสุดท้าย",
  str_voice_1400411_13 = "ในฐานะที่เป็นเลดี้มืออาชีพ จึงจำเป็นต้องแสดงท่าทางที่ถูกต้องและลักษณะที่งดงาม",
  str_voice_1400411_14 = "เธอต้องการไกด์ทัวร์ส่วนตัวไหม มีที่ที่อยากไปเที่ยวในรัตติกาลสีขาวไหมล่ะ",
  str_voice_1400411_15 = "ขอให้วันเกิดปีนี้มีความสุขมาก ๆ นะ ไปฉลองกันดีกว่า",
  str_voice_1400411_16 = "วันนี้ฉันพร้อมให้บริการแล้ว! แน่นอนว่ามาพร้อมรอยยิ้มแสนจริงใจด้วยนะ",
  str_voice_1400411_17 = "อรุณสวัสดิ์ เธอสามารถไปได้ทุกเมื่อเลย เราพร้อมสำหรับเธออยู่แล้ว",
  str_voice_1400411_18 = "งานฉันยังไม่เสร็จ กรุณามาทางนี้ด้วยนะ",
  str_voice_1400411_19 = "ไม่ต้องห่วง ฉันจะเป็นไกด์ให้ในความมืดเป็นช่วง ๆ เอง",
  str_voice_1400411_20 = "ฉันเห็นทางไปยังรัตติกาลสีขาวปรากฎขึ้นแล้ว จากนี้ไปแค่คอยดูดินแดนแห่งนี้ก็เพียงพอสำหรับฉันแล้วล่ะ",
  str_voice_1400411_21 = "ความจริงไม่มีไกด์ ผู้ที่ค้นหาความจริงจะมีอาการเหมือนภาวะความทรงจำมืดบอด",
  str_voice_1400411_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1400411_23 = "ไกด์ทัวร์และนักรบจะนำทางไปคนละทางกัน สำหรับพวกเขาแล้ว ฉันก็มีอีกหนึ่งเส้นทางที่ถูกต้องไว้ในใจ",
  str_voice_1400411_24 = "ความมุ่งมั่นของท่านลอร์ดที่มีต่อลูโมโพลิสเป็นผลตอบแทนที่ดีที่สุดสำหรับคนที่เสนอตัวรับใช้ท่าน",
  str_voice_1400411_25 = "เป็นเกียรติของฉันอย่างยิ่งที่ได้ร่วมแบ่งปันชื่อเสียงตระกูลเดียวกันกับคุณผู้หญิงคนนั้น",
  str_voice_1400411_26 = "ฉันขอแนะนำความมั่นคงและวินัยที่มีในกาแฟและชาของเราในทุก ๆ วัน",
  str_voice_1400411_27 = "หวังว่าเธอจะไม่ยุ่งเกี่ยวกับคนที่เสเพลและสิ่งที่ทำให้ขาดระเบียบนะ",
  str_voice_1400411_28 = "ครั้งหนึ่งฉันเคยได้ยินข่าวลือเรื่องเธอกับโคลอสซัสด้วย การได้เจอเธอตอนนี้ถือเป็นเกียรติอย่างยิ่ง",
  str_voice_1400411_29 = "หลงทางเหรอ ฉันอยู่นี่แล้ว ไม่ต้องห่วงนะ",
  str_voice_1400411_30 = "แผนที่นำทางขยับขยายออกไปแล้ว",
  str_voice_1400411_31 = "ฉันคือไกด์ใต้กำแพงสูง",
  str_voice_1400411_32 = "ฉันคือแสงสว่างในเมฆหมอก",
  str_voice_1400411_33 = "ฉันคือตัวจริงในเมืองบริสุทธิ์",
  str_voice_1400411_34 = "เธอต้องการไกด์หรือนักรบล่ะ",
  str_voice_1400411_35 = "นักท่องเที่ยวที่ชอบเดินเรื่อยเปื่อยไปไหนเสียแล้วล่ะ",
  str_voice_1400411_36 = "ถามฉันได้ทุกอย่างเลย!",
  str_voice_1400411_37 = "กรุณามองตรงนี้ นี่เป็นทิวทัศน์ที่โด่งดังมากเลยนะ!",
  str_voice_1400411_38 = "ทุกคน เรามาถึงแล้ว!",
  str_voice_1400411_39 = "กรุณาเข้าแถวเรียงกันนะ",
  str_voice_1400411_40 = "กรุณาอย่าผลักกันนะ",
  str_voice_1400411_41 = "งวดนี้เราได้ไกด์สวยอลังอีกแล้ว!",
  str_voice_1400411_42 = "ฉันไม่เหนื่อยเลย",
  str_voice_1400411_43 = "โอ้ ขอโทษจริง ๆ อ่ะ...",
  str_voice_1400411_44 = "ที่นั่งบนโคลอสซัสถูกจัดเตรียมไว้ให้ทุกคนแล้ว มีอะไรให้ฉันช่วยหรือเปล่า",
  str_voice_1400411_45 = "นี่คืออุปกรณ์ในสำนักงานเหรอ เธอใจดีเกินไปแล้วนะ...",
  str_voice_1400411_46 = "เป็นของสำคัญสำหรับไกด์ทัวร์มืออาชีพจริง ๆ!",
  str_voice_1400411_47 = "เธอนี่ใจดีเกินไปเหมือนเช่นเคย",
  str_voice_1400411_48 = "ยอดเยี่ยมไปเลย หญิงสาวแสนสง่างามต้องการอะไรแบบนี้แหละ!",
  str_voice_1400411_49 = "ฉันจะเติมเต็มหน้าที่ในฐานะไกด์ทัวร์ของลูโมโพลิส แต่กรุณามีสติกันด้วยนะ ไม่อย่างนั้นเธอจะเดินไม่ทันและหลงทางได้",
  str_voice_1400411_50 = "ความรู้เรื่องลูโมโพลิสของฉันแทบไม่ได้มาจากความคุ้นเคยเลย มันคือ... ความทรงจำที่ลืมไม่ลง เมืองนี้ก็เหมือนผู้อยู่อาศัยไม่มีผิด มันดิ้นรนที่จะอยู่รอดต่อไปน่ะ",
  str_voice_1400411_51 = "ตอนนั้นฉันถอดเขี้ยวเล็บออกไปแล้ว ที่ฉันทำอยู่ตอนนี้คือสนุกสนานกับความมั่นคงที่หาได้ยากน่ะ แต่ผู้หญิงก็ยังสนใจความเป็นส่วนตัวอยู่นะ ดังนั้นขอให้เธอรักษาสัญญาว่าี่จะไม่ถามอะไรมากมายด้วย",
  str_voice_1400411_52 = "Alchemy Stars",
  str_voice_1400411_53 = "สวัสดี!",
  str_voice_1400411_54 = "อรุณสวัสดิ์ พร้อมหรือยังเอ่ย",
  str_voice_1400411_55 = "สวัสดียามบ่าย หลับสบายไหม",
  str_voice_1400411_56 = "ลูโมโพลิสตอนกลางคืนก็สนุกสนานได้เหมือนกัน",
  str_voice_1400411_57 = "สวัสดีปีใหม่ ขอให้ปีใหม่มีแต่เรื่องดี ๆ เข้ามาในชีวิตนะ",
  str_voice_1400441_1 = "ช่วยอธิบายหน่อยได้ไหมว่าทำไมเธอถึงยังทำงานไม่เสร็จ ฉันคุยกับเธออยู่นะ โซยา!",
  str_voice_1400441_2 = "ทำรายงานให้จอมทัพห้ามมิให้ผิดพลาดมากเกินไปเด็ดขาด! ให้ตายสิ ทำไมฉันถึงไม่สังเกตจนถึงตอนนี้นะ...",
  str_voice_1400441_3 = "คูรี ไปทักทายทุกคนสิ! เมื่อก่อนเด็กนี่ไม่ขี้อายขนาดนี้นะ",
  str_voice_1400441_4 = "ท่าสวยกว่านี้! คล่องแคล่วกว่านี้! เอ๋ ขอโทษนะ ฉันไม่ได้พูดกับเธอ",
  str_voice_1400441_5 = "เดดไลน์คือแรงจูงใจที่ดีที่สุดสำหรับคนหลาย ๆ คน ฉันปล่อยให้คนพวกนั้นกลับไปสู่นิสัยแย่ ๆ แบบนี้ไม่ได้...",
  str_voice_1400441_6 = "ไม่ต้องห่วง ถึงงานจะซับซ้อนมากขึ้น แต่ฉันก็รับมือได้อย่างเชี่ยวชาญมากขึ้นแล้ว ฉันจะทำให้เสร็จ!",
  str_voice_1400441_7 = "ฉันจัดการเอง นี่เป็นส่วนหนึ่งของงานของฉันในฐานะเจ้าหน้าที่",
  str_voice_1400441_8 = "เอาละ... อยากมาช่วยฉันวางแผนหน่อยไหม ใช้เวลาไม่นานหรอก",
  str_voice_1400441_9 = "อิลลูมินาเป็นบ้านของฉัน ฉันคุ้ยเคยกับทุกอย่างที่นั่น บัดนี้ที่นี่ก็เป็นบ้านของฉันเหมือนกัน...",
  str_voice_1400441_10 = "กำลังไฟฟ้าเป็นยังไงบ้าง นี่คืองานตรวจสอบสำหรับวันนี้... ใช่แล้ว กะของเธอไงล่ะ คืนนี้ฉันต้องไปเขียนรายงานต่อ...",
  str_voice_1400441_11 = "กลับไปใช้ปากกา กระดาษ กับเครื่องพิมพ์ดีดงั้นเหรอ",
  str_voice_1400441_12 = "ลุยกันเลย ทุกวินาทีมีค่า ฉันจะช่วยให้เต็มที่",
  str_voice_1400441_13 = "สนใจปรับปรุงแผนผังบ้านไหม มันจะส่งผลต่อประสิทธิภาพการทำงานอย่างมหัศจรรย์เลยละ",
  str_voice_1400441_14 = "คิดแผนแล้วก็ยังต้องมีคนทำตามแผน ยังไม่ใช่เวลามาผ่อนคลายหรอก",
  str_voice_1400441_15 = "พักผ่อนนอกเวลางานเยอะ ๆ ล่ะ วันนี้เธอควรพักผ่อนนะ เอ้อ แล้วก็สุขสันต์วันเกิดด้วย!",
  str_voice_1400441_16 = "เธอเห็นใครอู้งานบ้างไหม ถ้าเห็นต้องบอกฉันนะ",
  str_voice_1400441_17 = "อรุณสวัสดิ์ เดี๋ยวฉันจัดแจงให้เธอเองนะ ไม่มีปัญหาเลย",
  str_voice_1400441_18 = "ตามตารางแล้ว ใกล้จะถึงเวลาพักแล้วละ",
  str_voice_1400441_19 = "ยังพักผ่อนไม่ได้... เหมือนจะมีข้อผิดพลาดในแผน ฉันตรวจให้ละเอียดอีกทีดีกว่า",
  str_voice_1400441_20 = "ทุกอย่างเกี่ยวกับอิลลูมินาจะถูกจัดระเบียบให้เรียบร้อย ฉันชอบเวลาที่ทุกคนทำตามแผนและทำงานเหมือนเครื่องจักร!",
  str_voice_1400441_21 = "เรดีเซล เวรนช์อยู่รอดมาได้ยังไง ทั้ง ๆ ที่โหดเหี้ยมและไร้เป้าหมายขนาดนั้น...",
  str_voice_1400441_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1400441_23 = "ถ้าไม่มีแผน พวกนั้นก็เป็นแค่ฝูงคนโง่เง่าไร้สติ",
  str_voice_1400441_24 = "ฉันต้องพยายามสองเท่าไม่ว่าจะเป็นการต่อสู้หรือการวางแผนกลยุทธ์ เพื่อให้จอมทัพพึ่งพาฉันได้",
  str_voice_1400441_25 = "ถึงวราธจะวางแผนยึดตำแหน่งจอมทัพมา นางก็ไม่มีทางใช้กลสกปรกเด็ดขาด!",
  str_voice_1400441_26 = "พอได้ติ๊กแผนการที่ต้องทำวันนี้ครบทุกช่องแล้ว ฉันก็รู้สึกดีมากเลยละ",
  str_voice_1400441_27 = "ทุกอย่างต้องเป็นไปตามแผน ต้องรักษาทุกคำสัญญา!",
  str_voice_1400441_28 = "ต้องใช้ระบบองค์กรแบบไหนถึงจะจัดการสิ่งใหญ่โตขนาดนี้ได้กันนะ...",
  str_voice_1400441_29 = "สวัสดี ฉันมีหน้าที่ดูรายละเอียดทั้งหมด กรุณาเชื่อในความสามารถการจัดการของอิลลูมินา ถึงยังไงที่นี่ก็เป็นสนามรบที่ต่างออกไปมาก",
  str_voice_1400441_30 = "เฮ้ คูรีโตแล้วเหรอ",
  str_voice_1400441_31 = "คูรี ตื่น!",
  str_voice_1400441_32 = "อัสนีบาต!",
  str_voice_1400441_33 = "สายฟ้าจงทิ่มแทงเมฆา!",
  str_voice_1400441_34 = "กรุณาสนใจด้วย!",
  str_voice_1400441_35 = "สายฟ้าสั่นไหวในตัวฉัน!",
  str_voice_1400441_36 = "แผนเสร็จสมบูรณ์ พร้อมปะทะ",
  str_voice_1400441_37 = "สายฟ้าแทรกแซง!",
  str_voice_1400441_38 = "เขย่าพสุธา!",
  str_voice_1400441_39 = "ชักดาบ!",
  str_voice_1400441_40 = "ดาบทิ่มแทง! เอานี่ไปกินซะ!",
  str_voice_1400441_41 = "แผนของฉันจะพาเธอไปสู่ชัยชนะ!",
  str_voice_1400441_42 = "ทำตามแผนและชัยชนะจะตามมา!",
  str_voice_1400441_43 = "ถ้าไม่ทำตามแผน ก็ไปไม่ได้ที่จะประสบความสำเร็จ",
  str_voice_1400441_44 = "มีอัปเดตอะไรไหม",
  str_voice_1400441_45 = "รางวัลสำหรับเวลาและความพยายามของฉันเหรอ",
  str_voice_1400441_46 = "คูรีต้องชอบมากแน่เลย!",
  str_voice_1400441_47 = "ดูแพงนะ... แน่ใจนะว่าเธอไม่ได้ซื้อเกินงบน่ะ",
  str_voice_1400441_48 = "ว้าว อยากได้มานานแล้ว ขอบใจนะ",
  str_voice_1400441_49 = "เมืองใต้ดินอาจกว้างขวางพอสำหรับฉันแต่คูรีเหมาะที่จะอยู่บนดินและท้องฟ้าเบื้องบน",
  str_voice_1400441_50 = "ถ้าฉันไม่ได้เป็นส่วนหนึ่งของอิลลูมินา ฉันคงเป็นนักผจญภัยกล้าหาญที่สำรวจทะเลทราย ดินแดนลับ และเมืองหลวงเก่าแล้ว!",
  str_voice_1400441_51 = "ฉันมาจากเมืองเล็ก ๆ ในสหพันธรัฐอิลลูมินา ไม่ใช่เมืองแกนน่อน แต่มัน... ถูกทำลาย...",
  str_voice_1400441_52 = "Alchemy Stars",
  str_voice_1400441_53 = "สวัสดี!",
  str_voice_1400441_54 = "อรุณสวัสดิ์ อยู่หรือเปล่า",
  str_voice_1400441_55 = "สวัสดียามบ่าย เธอพอจะมีเวลาไหม",
  str_voice_1400441_56 = "สายัณห์สวัสดิ์ หวังว่าฉันจะไม่ได้มารบกวนนะ",
  str_voice_1400441_57 = "สุขสันต์วันปีใหม่นะเธอ!",
  str_voice_1400451_1 = "ฉันเชื่อในสัจจะเพียงหนึ่งเดียวเท่านั้น แสงและความมืดมิดต่างก็เป็นรูปแบบหนึ่งของสัจจะ... เมื่อเกิดการทำลายล้างขึ้น สามัญชนจะถูกนำทางไปสู่ความเลวร้ายและเกิดใหม่อีกครั้ง...",
  str_voice_1400451_2 = "กำจัดผิวเน่าออกไป กำจัดเลือดสกปรกออกไป กำจัดความคิดเมินเฉยของฉันออกไปเสีย...",
  str_voice_1400451_3 = "ตะปูเปื้อนสีแดงจากเลือดฉัน ที่ซึ่งกางเขนจะพิพากษาศัตรูของฉัน... และหัวใจของฉันเอง...",
  str_voice_1400451_4 = "มีเพียงความทุกข์ทรมานจากการสูญเสียเลือดอันเจ็บปวดเท่านั้น ถึงจะทำให้ฉันได้รับการล้างบาป",
  str_voice_1400451_5 = "บาปมีอยู่ทุกที่บนโลกนี้ ฉันมีบาปและต้องชดใช้มัน... ไม่ว่าอาจารย์วิกตอเรียจะมีคำสั่งอย่างไรก็ต้องปฏิบัติโดยไร้ข้อโต้แย้ง เงื่อนไข หรือการต่อต้านใด ๆ ทั้งสิ้น",
  str_voice_1400451_6 = "ความตายคือการเปลี่ยนแปลง ไม่ใช่จุดจบ... ความเจ็บปวดเป็นการล้างบาป ไม่ใช่การทรมาน",
  str_voice_1400451_7 = "ไม่ต้องกลัวไป ตะปูนี้เตรียมไว้สำหรับฉัน ดูสิ แบบนี้...",
  str_voice_1400451_8 = "\"นี่เป็นคำสารภาพของฉันต่อความจริง... ปีศาจ กรรม ความโง่เขลา และความโอหังล้วนแต่เป็นบาปของฉัน...\" อ่า ฉันต้องชดใช้บาปของฉัน... สนใจชดใช้ไปด้วยกันไหม",
  str_voice_1400451_9 = "โลกนี้จะสมบูรณ์แบบถ้าฉันเป็นคนเดียวที่ทุกข์ทรมานถึงเท่านี้ แต่เห็น ๆ อยู่ว่าเธอก็กำลังอดทนกับความสิ้นหวังแบบเดียวกันนะ",
  str_voice_1400451_10 = "อยู่ที่นี่แล้วก็เงียบ ๆ ไว้เหรอ ไม่มีปัญหา ฉันทำทุกอย่างที่เธออยากให้ทำได้นะ",
  str_voice_1400451_11 = "นี่เป็นการฝึกฝนประเภทหนึ่งเหรอ หรือ... เป็นหนึ่งรูปแบบการลงทัณฑ์",
  str_voice_1400451_12 = "เลือดเนื้อของฉันถูกแทะเล็ม และจิตวิญญาณถูกกัดกระชากเป็นส่วน ๆ... อ่า... นี่เป็นสัญญาณของความสุขสินะ",
  str_voice_1400451_13 = "ฉันยังจำคำสอนนี้ไม่ได้... ฉันต้องคัดลายมือสัก 1,000 ครั้ง",
  str_voice_1400451_14 = "ฉันต้องสำนึกในบาป... แพกต์ไม่เคารพเลดี้วิกตอเรียเอามาก ๆ ฉันถึงขั้นโจมตีนางไปเลย... ฉันรู้สึกผิดจัง",
  str_voice_1400451_15 = "การเกิดขึ้นมาของฉันเป็นบาปอย่างหนึ่ง ส่วนเธอเป็นสมบัติของโลกใบนี้... ยินดีด้วยนะ",
  str_voice_1400451_16 = "ดวงอาทิตย์ทิ่มแทงฉันด้วยความเจ็บปวด แต่ฉันต้องทนมันให้ได้...",
  str_voice_1400451_17 = "สวัสดี อยากรู้เรื่องทรู ออเดอร์ไหม ทำไมวิ่งหนีล่ะ อ๋อ ฉันยังเลือดไหลอยู่สินะ...",
  str_voice_1400451_18 = "ยังไม่ได้ลงทัณฑ์ครึ่งหนึ่งของวันนี้เลย",
  str_voice_1400451_19 = "มีเพียงตอนที่ฉันถูกความมืดมิดโอบล้อมและจมอยู่ในความไร้ค่าของตนเท่านั้นแหละที่ฉันจะรู้สึกมั่นใจ",
  str_voice_1400451_20 = "ทรู ออเดอร์เป็นบ้านของฉัน เป็นเป้าหมายของฉัน และเป็น... ครอบครัวของฉัน",
  str_voice_1400451_21 = "ฉันเติบโตมาจากที่นั่นแต่กลับไม่เหมาะกับที่นั่น เป็นเหมือนความหายนะในชีวิตของฉันเลย",
  str_voice_1400451_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1400451_23 = "เธอต้องการแค่เลือดเพียงเล็กน้อยไว้กำจัดอิคลิพไซท์ออกไปเท่านั้น",
  str_voice_1400451_24 = "เลดี้วิกตอเรีย กรุณาอภัยให้บาปของฉันที่เกิดเป็นสัตว์ประหลาดน่ารังเกียจด้วย...",
  str_voice_1400451_25 = "ฉันเคยถามเฟาสต์ครั้งหนึ่งว่ากระเป๋าเดินทางสีขาวทำให้ฉันโล่งใจได้ไหม เขาก็บอกว่ายังไม่ถึงเวลา",
  str_voice_1400451_26 = "คำสอน คำสารภาพ และการไถ่บาปทำให้ฉันมั่นใจ... รวมถึงก้อนน้ำตาลขาวด้วยนะ...",
  str_voice_1400451_27 = "คนที่ไม่เชื่อฟังเลดี้วิกตอเรียจะต้องถูกฉีกเป็นชิ้น ๆ และตัดหัวทิ้ง",
  str_voice_1400451_28 = "มันสบายมาก... และกวนใจมาก มันคงดีถ้าพวกนั้นสร้างห้องสารภาพบาปไว้ข้างในได้",
  str_voice_1400451_29 = "ฉันซื่อตรงต่อทรู ออเดอร์ ด้วยศรัทธาของฉันและซื่อตรงต่อเลดี้วิกตอเรีย ฉันตอกคำสาบานที่มิอาจผิดพลั้งเข้าไปในร่างกายแล้ว ทีนี้ก็สารภาพมาซะ! แม้แต่สัตว์ประหลาดก็ควรได้รับการไถ่บาป",
  str_voice_1400451_30 = "เฆี่ยนฉันเลย เวทนาฉันเลยสิ...",
  str_voice_1400451_31 = "เลือดของฉันมันสกปรก ยกโทษให้ฉันเถอะ...",
  str_voice_1400451_32 = "หากเลือดบาปของฉันสามารถชะล้างโลกใบนี้ได้",
  str_voice_1400451_33 = "ความเลื่อมใสของฉันจะนำทางฉันเอง",
  str_voice_1400451_34 = "ตามที่เธอปรารถนา",
  str_voice_1400451_35 = "ฉันพร้อมแล้ว",
  str_voice_1400451_36 = "ความเจ็บปวดเป็นหนทางหลุดพ้นบาป",
  str_voice_1400451_37 = "ฉันทุ่มเทสุดกำลัง...",
  str_voice_1400451_38 = "ฉันเสียสละด้วยทุกสิ่ง...",
  str_voice_1400451_39 = "เดือดดาล...",
  str_voice_1400451_40 = "ช่างโสมม น่ารังเกียจ...",
  str_voice_1400451_41 = "ความจริงจะให้อภัยฉันใช่ไหมนะ",
  str_voice_1400451_42 = "ต่อไปฉันต้องแสวงบุญ... มันเป็นเพียงก้าวแรกเท่านั้น",
  str_voice_1400451_43 = "โธ่ ฉันเศร้าจริง ๆ สัตว์ประหลาดน่าเวทนา...",
  str_voice_1400451_44 = "เธอหลงทางเหรอ ถ้าหลงทางก็ควรสารภาพบาปซะนะ...",
  str_voice_1400451_45 = "ฉันไม่ควรค่าที่จะได้รับหรอก...",
  str_voice_1400451_46 = "ไม่น่าเป็นอย่างนั้น...",
  str_voice_1400451_47 = "เธอต้อง?",
  str_voice_1400451_48 = "ขอบคุณนะ...",
  str_voice_1400451_49 = "พวกนั้นเคยปกป้องฉัน เคารพและยกฉันขึ้นแท่นบูชาครั้งหนึ่งแต่ก็ยังทำร้ายฉัน เกลียดฉันและบังคับให้ฉันเข้าหุบเหวไร้ที่สิ้นสุดด้วย",
  str_voice_1400451_50 = "อิคลิพไซท์ทำร้ายออโรเรียนเหมือนที่ออโรเรียนทำร้ายกันเอง ฉันไม่ใช่ทั้งอิคลิพไซท์และออโรเรียน ฉันเป็นเพียงสัตว์ประหลาดสิ้นหวังและน่ารังเกียจเท่านั้น",
  str_voice_1400451_51 = "ทรู ออเดอร์เป็นที่พักใจของฉัน ฉันไม่จำเป็นต้องเข้าใจหรือคิดอะไร ก็แค่ทำตามความจริงและเคลื่อนที่ไปข้างหน้า",
  str_voice_1400451_52 = "Alchemy Stars",
  str_voice_1400451_53 = "สวัสดี...",
  str_voice_1400451_54 = "อรุณสวัสดิ์... มาถึงตามที่นัดแล้ว",
  str_voice_1400451_55 = "ทำไมเธอไม่มาล่ะ",
  str_voice_1400451_56 = "ฉันรอคอยการลงทัณฑ์ยามค่ำคืนอยู่...",
  str_voice_1400451_57 = "ปีใหม่เป็นดั่งของขวัญ",
  str_voice_1400481_1 = "ทำไมพวกเขาว่ากันว่าชาวอัมบราตันไม่ช่วยเหลือการก่อสร้างลูโมโพลิสล่ะ สองสามปีก่อน พวกเขาคงเสียใจที่พูดแบบนั้นแน่",
  str_voice_1400481_2 = "ถ้าเธอกลัวความเจ็บปวดก็ควรไปเสียตอนนี้จะดีกว่า ฉันต้องมีสมาธิกับการปกป้องโรบิน ดังนั้นเธอก็ต้องดูแลตัวเองไป",
  str_voice_1400481_3 = "ช่วงนี้เธอได้ทำอะไรกับโรบินบ้างไหม? ใช่ การที่เธอคุยกับใครสักคนคงแปลกน่าดู",
  str_voice_1400481_4 = "ฉันเคารพคนระดับล่างเพราะฉันเคยเป็นและยังเป็นพวกเขาอยู่ ถึงเพื่อนบางคนจะไม่เข้าใจก็เถอะ...",
  str_voice_1400481_5 = "ฉันไม่ใช่คนจรจัดที่เลินเล่อและอ่อนแออย่างที่เคยเป็นแล้ว ตอนนี้ไม่มีใครเอาชนะฉันได้ง่าย ๆ อีกต่อไป",
  str_voice_1400481_6 = "อิคลิพไซท์ ภัยธรรมชาติ โจร... ในโลกใบนี้ เธอไม่มีวันรู้เลยว่าจะได้สัมผัสคมดาบเย็นยะเยือกที่คอเมื่อไหร่ แต่ฉันออกเดินทางครั้งนี้โดยไม่หวนกลับแล้วฉันก็จะไม่มีวันเสียใจด้วย",
  str_voice_1400481_7 = "แหม ๆ... ฉันนึกตลอดว่าเธอเป็นคนที่น่าเบื่อที่สุดแต่ก็ไม่เหมือนผู้ชายคนอื่น อย่างน้อยเธอก็เข้าใจอารมณ์ขันของฉันนะ",
  str_voice_1400481_8 = "เยี่ยมเลย แต่ผู้ปกครองไม่สามารถเป็นได้ทั้งราชาและผู้ปกครองที่ฉลาด เธอสามารถเลือกได้เพียงอย่างเดียวเท่านั้น ทำไมไม่ลองเรียนรู้จากเจ้าแห่งเงาของเราล่ะ",
  str_voice_1400481_9 = "เยี่ยมมาก ตามกฎแล้วเราเห็นด้วยกับวิธีการทำสิ่งต่าง ๆ ของเธอนะ หืม เราอาจมีอะไรเหมือนกันก็ได้ เธอสนใจจะเข้าร่วมอัมบราตันบ้างไหม",
  str_voice_1400481_10 = "เธอชอบสั่งสอนฉันแต่ดูเธอเข้าสิ... เธอแค่เล่นสนุกไปเรื่อยหรือเปล่า เราทุกคนต่างก็คล้ายกันมากทั้งนั้น",
  str_voice_1400481_11 = "เอ๊ะ ทำไมให้ฉันคอยดูที่นั่นไว้ล่ะ",
  str_voice_1400481_12 = "ฉันส่งเสื้อผ้าเธอไปร้านซักแห้งแล้ว อย่าไปเชื่อใจมือใหม่ที่พับผ้าตัวเองก็ยังไม่เป็นเชียว",
  str_voice_1400481_13 = "เฮ้ ยังไงฉันก็เป็นผู้หญิงนะ! ฉันก็เรียบร้อยเป็นกับเขาเหมือนกันนะ รู้ไหม...",
  str_voice_1400481_14 = "เวลาไหนที่ถูกอารมณ์เข้าครอบงำจะเกิดหายนะไม่ช้าก็เร็ว... แต่โรบินเป็นข้อยกเว้นน่ะ",
  str_voice_1400481_15 = "ขอให้สนุกนะ! ยังไงก็ไม่มีใครรู้หรอกว่าวันเกิดครั้งต่อไปจะเป็นยังไง",
  str_voice_1400481_16 = "โย่ เจ้านักแงะยาน!",
  str_voice_1400481_17 = "ทำงานกันเถอะ ความตรงต่อเวลาเป็นสิ่งสำคัญนะ ต้องตรงต่อเวลาเสมอ!",
  str_voice_1400481_18 = "โรบินเป็นไงบ้าง ฉันไม่เห็นนางมา 8 นาทีแล้ว นางอยู่ไหน โรบิน!",
  str_voice_1400481_19 = "ตามสัญญานะ ฉันควรออกไปทำหน้าที่เดี๋ยวนี้แต่ฉันต้องทำงานเพิ่มเป็นพิเศษน่ะสิ เจ้าบ้าหัวหน้ากิลด์ไร้ยางอายเอ๊ย!",
  str_voice_1400481_20 = "พวกเหยื่อไม่เข้าร่วมแก๊งเพราะความอยากรู้หรอกนะ พวกมันจ้องจะทำลายน่ะสิไม่ว่า",
  str_voice_1400481_21 = "ตราบใดที่จ่ายเงินและทำตามกฎ... จะเป็นลูโมโพลิสหรือเรดีเซล เวรนช์ก็ปล่อยพวกเขาไปเถอะ...",
  str_voice_1400481_22 = "แชโดว์กำลังจับตาดูเธออยู่",
  str_voice_1400481_23 = "ฉันหวังว่าจะได้ฉีกอิคลิพไซท์เป็นชิ้น ๆ แต่ฉันต้องใจเย็นไว้ก่อน",
  str_voice_1400481_24 = "ชมโรบินเหรอ ล้อกันเล่น ถึงฉันจะอยากชมก็ชมเท่าไหร่ไม่พอหรอก!",
  str_voice_1400481_25 = "หัวหน้ากิลด์ขี้ตืดเหลือเชื่อเลยละ แต่บางครั้งก็เอื้อเฟื้อเผื่อแผ่จนไม่มีขอบเขต",
  str_voice_1400481_26 = "ฉันชอบอะไรเหรอ โรบินไง... อะไรนอกจากโรบินงั้นเหรอ",
  str_voice_1400481_27 = "คนเขลามืดบอด เพื่อนที่ไม่เป็นมืออาชีพ ขี้ขลาดที่ไม่กล้าต่อสู้... คนพวกนี้เป็นฝันร้ายในตัวเองอยู่แล้ว",
  str_voice_1400481_28 = "เราต้องหาทางไปยังอัมบราตัน... เอาไงดีล่ะ เจ้านักแงะยาน เราทำข้อตกลงดีไหม",
  str_voice_1400481_29 = "สวัสดี เธออยากให้ฉันช่วยเหรอ แต่ช่วยได้แค่ชั่วคราวนะ ฉันยังมีงานที่ต้องทำกับกิลด์อีก ไหนรีบว่ามาซิ เธออยากเก็บใครงั้นเหรอ",
  str_voice_1400481_30 = "ฉันใช้เพื่อนของฉันคนนี้เก่งขึ้นเยอะแล้วล่ะ",
  str_voice_1400481_31 = "ฉันรู้สึกเหมือนรวบรวมพลังไว้ได้อีกครั้งหนึ่ง",
  str_voice_1400481_32 = "โรบิน! จากนี้ไปไม่มีใครทำร้ายเราได้แล้วล่ะ",
  str_voice_1400481_33 = "พนันเลยด้วยชื่อเดย์นา ลูกนกตัวจิ๋วได้พุ่งทะยานแน่",
  str_voice_1400481_34 = "เยี่ยม งั้นฉันจะลองต่อสู้เคียงข้างเธอดู",
  str_voice_1400481_35 = "ลับคมดาบเรียบร้อยแล้ว",
  str_voice_1400481_36 = "ฉันหมดความอดทนไปนานแล้วล่ะ...",
  str_voice_1400481_37 = "อย่ามาขอความเห็นใจเชียว!",
  str_voice_1400481_38 = "ถ้ากลัวก็หลับตาซะ!",
  str_voice_1400481_39 = "ฉันขอแค่ห้าวินาทีก็ล้มเธอได้แล้ว",
  str_voice_1400481_40 = "ตอนนี้ฉันจะปล่อยเธอพักให้สบาย",
  str_voice_1400481_41 = "สู้สิ อย่าเป็นตัวถ่วง! โรบินอยู่ไหน",
  str_voice_1400481_42 = "ฉันชินกับชัยชนะแบบนี้แล้ว! ใช่ป่ะ โรบิน",
  str_voice_1400481_43 = "ถ้าคราวหน้าเกิดอะไรแบบนี้ขึ้นกับโรบินอีก ฉันจะไม่ไว้ชีวิตเธอเลย...",
  str_voice_1400481_44 = "ไม่มีปัญหา ฉันจะอยู่จวบจนตอนสุดท้าย!",
  str_voice_1400481_45 = "เอาละ ฉันจัดการเอง แต่ถ้ามีอะไรไม่ชอบมาพากลละก็ ฉันจะเตะก้นเธอ!",
  str_voice_1400481_46 = "มัน... เธอรู้ได้ไง เรื่องบังเอิญเหรอ",
  str_voice_1400481_47 = "สมบัติชิ้นนี้ดีเลยนะ... เธอมีพรสวรรค์ด้านทำธุรกิจนะนี่",
  str_voice_1400481_48 = "เวลามีคนใส่ใจฉันแบบนี้จริง ๆ ฉันรู้สึกเหมือนไม่ใช่ตัวเองเลย...",
  str_voice_1400481_49 = "ฉันกับโรบินต่างใช้ชีวิตผ่านช่วงเวลาของสงครามมา แต่ถึงอย่างนั้นเราก็ต้องระวังการคดโกงอย่างโหดร้ายที่มากับสงครามในตอนนี้ด้วย ขณะที่การโกงทำให้เราโลภ มันก็เหยียบย่ำศักดิ์ศรีและชีวิตของเราด้วย",
  str_voice_1400481_50 = "\"สุดท้ายเราก็จะเป็นเหมือนพวกเขา...\" ปลอบประโลมใจได้ดีจริง ๆ ราวกับว่าความหิวโหยและอคติจะหายไปได้จริง ๆ อย่างนั้นแหละ มีเพียงเด็กไร้เดียงสาเท่านั้นที่จะเชื่ออะไรอย่างนั้น",
  str_voice_1400481_51 = "ตอบแทนบุญคุณทุกครั้งอย่างเผื่อแผ่ให้กับคนที่เรารักและอย่าปรานีกับศัตรูของเรา ฉันกับโรบินไม่ได้พึ่งพากันแล้วแต่เราจะไม่มีวันลืมสิ่งที่เพื่อนและครอบครัวทำไว้ให้เราเลย",
  str_voice_1400481_52 = "Alchemy Stars",
  str_voice_1400481_53 = "เจ้านักแงะยาน!",
  str_voice_1400481_54 = "อรุณสวัสดิ์! เธอตื่นหรือยัง",
  str_voice_1400481_55 = "ฉันตามหาเธออยู่ ทุกคนไปไหนกันหมด",
  str_voice_1400481_56 = "อ้าว! สายัณห์สวัสดิ์",
  str_voice_1400481_57 = "มาฉลองปีใหม่สุดล้ำค่ากันเถอะ",
  str_voice_1400541_1 = "เครื่องดื่มชั้นยอด คือเครื่องดื่มเย็นเจี๊ยบฟรี ๆ ที่ได้รับจากบาร์ในดวงใจ หลังจากทำงานมาทั้งวันไงล่ะ!",
  str_voice_1400541_2 = "การสวมเครื่องแบบเท่ ๆ จะสร้างแรงบันดาลใจให้เธอจริงจังกับงานและภารกิจ นั่นคือสาเหตุที่เธอต้องรีดเครื่องแบบทุกวัน!",
  str_voice_1400541_3 = "ชีวิตจะให้อะไรเราหลายอย่าง ซึ่งเราจำต้องรับมืออย่างจริงจัง ไม่ว่าเราจะล้มเหลวสักกี่ครั้ง เราก็จะมีความกล้าหาญที่จะลองใหม่!",
  str_voice_1400541_4 = "ถ้าเธอตั้งใจให้มากในทุกวัน เธอก็จะโตขึ้นและกลายเป็นบุคคลยอดเยี่ยมในอนาคตอย่างแน่นอน เหมือนกัปตันคาร์ลีนผู้แน่วแน่ ไว้วางใจได้ และเกือบจะสมบูรณ์แบบนะ",
  str_voice_1400541_5 = "เมื่อไหร่เจ้าเมืองจะยอมรับในตัวฉันสักทีนะ... ว่าแต่ฉันควรซ่อมไฟถนนที่ฉันเผลอไปทำพังซะก่อน",
  str_voice_1400541_6 = "เวลาที่ฉันก้าวต่อไปไม่ไหว ฉันจะฟื้นฟูความมั่นใจด้วยการมองดูโคมไฟอันนี้ มันไม่แปลกหรอก มาใกล้ ๆ สิ มองผ่านแสงนี่ไปแล้วเธอจะเข้าใจเอง",
  str_voice_1400541_7 = "ความจริงจังคือบัญญัติอัศวินข้อหนึ่งนะ ฝึกฝนเข้าไว้แล้วเธอจะได้รับเกียรติยศ น่าเสียดายที่พวกขุนนางในลูโมโพลิสไม่เข้าใจเรื่องนี้",
  str_voice_1400541_8 = "บางคนบอกว่าฉันน่ะจริงจังมากไป เหมือนไม้บรรทัดโค้งในมือฉันนี่ไง ทั้งแข็งทื่อและไม่ยืดหยุ่น เธอคิดว่าไง อ้อ ใช่อย่างนั้นจริง ๆ เหรอ",
  str_voice_1400541_9 = "ฉัน... ฉันไม่รู้ว่าทำไมดยุกถึงมอบตำแหน่งที่สำคัญแบบนี้ให้ เป็นเพราะว่าฉันวาดแผนที่พวกนั้นขึ้นมาใหม่รึเปล่านะ",
  str_voice_1400541_10 = "ฮ่าฮ่า เมื่อกี้ฉันยังคิดอยู่เลยว่าจะไปทำงานต่อ ฉันไม่ได้ฝันกลางวันแน่นอน!",
  str_voice_1400541_11 = "ฉันไม่ได้แค่ทำงานเพื่อหาเลี้ยงปากท้อง สำหรับฉัน มันคือภารกิจที่น่ายกย่อง เหมือนกับชีวิตฉันนี่!",
  str_voice_1400541_12 = "เมื่อเริ่มต้นทำงานแล้ว เธอก็ควรตั้งใจนะ ไม่งั้นเธออาจทำอะไรผิดพลาดได้ ทีนี้ก็ลงมือได้แล้ว เร็วเข้า!",
  str_voice_1400541_13 = "ฉันจะปรับปรุงสมาธิของตัวเองได้ยังไง เธอมีวิธีที่ดีกว่านี้ไหม",
  str_voice_1400541_14 = "จดไว้ดีกว่ามาท่องจำเอา ดังนั้นเธอควรพกกระดาษปากกาติดตัวไว้เสมอ... รอเดี๋ยวนะ ฉันจะไปหยิบก่อน",
  str_voice_1400541_15 = "สุขสันต์วันเกิดนะ ฉัน... ฉันอยากให้อะไรเธอสักอย่าง แต่เดือนนี้เงินตึงอ่ะ! รับรองคราวหน้าฉันจะมีอะไรให้เธอแน่!",
  str_voice_1400541_16 = "ตอนนี้ฉันปฏิบัติหน้าที่อยู่ ดูเหมือนว่าทุกอย่างปกติดีนะวันนี้ โคลอสซัสค่อนข้างเสถียร และคงไม่ตกเร็ว ๆ นี้แน่",
  str_voice_1400541_17 = "สดใสหน่อยสิ ได้เวลาทำงานแล้ว!",
  str_voice_1400541_18 = "เป็นอีกหนึ่งวันที่เงียบเชียบและไม่มีเรื่องอะไรเลย... ยินดีด้วย",
  str_voice_1400541_19 = "อ้า! ฉันปฏิบัติหน้าที่อยู่ ...ดูตาฉันสิ ฉันไม่ได้เผลอหลับแน่นอน",
  str_voice_1400541_20 = "ลูโมโพลิสกลายเป็นเมืองใหญ่แถวหน้าประจำทวีปนี้ เพราะว่าเมืองนี้ยึดถือบัญญัติอัศวินไงล่ะ",
  str_voice_1400541_21 = "ฉันได้ยินว่าอิลลูมินามีกฎการบริหารที่มีประสิทธิภาพ ถ้ากฎเหล่านี้ใช้กับลูโมโพลิสได้ละก็...",
  str_voice_1400541_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1400541_23 = "อิคลิพไซท์คือศัตรูชั่วนิรันดร์ของเรา เราต้องกำจัดอิคลิพไซท์ทุกตัวที่เราเจอ!",
  str_voice_1400541_24 = "ฮึ ฉันได้ยินว่าเทวทูตทั้งสี่ได้ทำลายพื้นที่ตัวเมืองลูโมโพลิสอีกแล้ว ต้องวาดแผนที่กันใหม่... อีกแล้ว... ฮึ...",
  str_voice_1400541_25 = "นายท่านรับมือกับงานด้านการปกครองได้ละเอียดรอบคอบมาก ฉันจะทำให้ดีที่สุดเพื่อให้เขาได้พักบ้างเป็นครั้งคราว",
  str_voice_1400541_26 = "ฉันชอบคนที่จริงจังนะ โดยเฉพาะคนที่ทำงานหนัก ตั้งใจเต็มที่!",
  str_voice_1400541_27 = "ถ้าลูโมโพลิสเสื่อมอำนาจลงวันใด ก็ต้องเป็นเพราะพวกขุนนางนี่แหละ...",
  str_voice_1400541_28 = "ที่นี่กว้างขวางจังเลย เหมือนกับลูโมโพลิสขนาดย่อมเลย แถมลอยในอากาศได้ด้วย...",
  str_voice_1400541_29 = "ทุกสิ่งที่เธอได้รับคือพรของชีวิต ฉันชื่อนาดีน ผู้ที่ทำให้ลูโมโพลิสสว่างสดใสด้วยโคมไฟในมือของฉัน",
  str_voice_1400541_30 = "แสงนี้ส่องสว่างขึ้นกว่าเดิม",
  str_voice_1400541_31 = "ยกโคมไฟขึ้นสูง แล้วศัตรูของเธอจะต้องพ่ายแพ้",
  str_voice_1400541_32 = "แสงของโคมไฟจะส่องสว่างในค่ำคืนที่ยาวนาน",
  str_voice_1400541_33 = "ในที่สุดฉันก็... สามารถยืนเฝ้ายามในค่ำคืนที่ยาวนานได้แล้ว",
  str_voice_1400541_34 = "ฉันหวังพึ่งเธอนะ!",
  str_voice_1400541_35 = "แสง... รวบรวม...",
  str_voice_1400541_36 = "โคมไฟได้รับการจุดแล้ว",
  str_voice_1400541_37 = "แสงสว่างจะเป็นใหญ่ตลอดไป!",
  str_voice_1400541_38 = "ใต้แสงของโคมไฟ!",
  str_voice_1400541_39 = "โปรดรักษาเรา!",
  str_voice_1400541_40 = "แสงสว่าง! ปราบศัตรูเลย!",
  str_voice_1400541_41 = "โปรดตามโคมไฟนี้ไป",
  str_voice_1400541_42 = "รัตติกาลสีขาวชั่วนิรันดร์!",
  str_voice_1400541_43 = "โคมไฟของฉันกำลังจะดับ...",
  str_voice_1400541_44 = "สิ่งใหม่ ๆ ที่ต้องเรียนรู้ ก็ควรไปเรียนรู้ในที่แห่งใหม่",
  str_voice_1400541_45 = "ขอบใจมากสำหรับของขวัญ",
  str_voice_1400541_46 = "ว้าว ฉันชอบจังเลย! ขอบใจนะ",
  str_voice_1400541_47 = "นี่ให้ฉันจริงเหรอ!",
  str_voice_1400541_48 = "ฉันต้องให้อะไรเธอเป็นการตอบแทน ฉันสัญญา!",
  str_voice_1400541_49 = "ฉันก็แค่คนธรรมดา ดังนั้นฉันก็มีแค่ความสามารถอย่างคนธรรมดา พวกความจริงจัง มุ่งมั่น แล้วก็ตั้งใจ",
  str_voice_1400541_50 = "เป็นอัศวินมันต้องปากหนักเข้าไว้ ไม่ว่าจะข่าวดีหรือข่าวร้ายก็ควรเก็บไว้ในใจ ไม่ใช่เล่าไปเรื่อยเปื่อย",
  str_voice_1400541_51 = "แม้แต่ลูโมโพลิสก็ยังมีเงามืด นั่นคือสาเหตุที่เราต้องมีผู้คุ้มภัยยามราตรี... อ๋อ นั่นเป็นแค่ตำนาน น่าจะ มั้งนะ...",
  str_voice_1400541_52 = "Alchemy Stars!",
  str_voice_1400541_53 = "สวัสดี!",
  str_voice_1400541_54 = "อรุณสวัสดิ์!",
  str_voice_1400541_55 = "เธอยุ่งอยู่รึเปล่า",
  str_voice_1400541_56 = "เธอพักผ่อนอยู่หรือเปล่า",
  str_voice_1400541_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1400571_1 = "เฮ้อ... ทำไมฉันถึงผมยุ่งน่ะเหรอ เพราะถ้ามัวตัดแต่งทรงมันก็ยุ่งยากไง แต่จับแล้วรู้สึกดีนะ อยากจับดูไหมล่ะ",
  str_voice_1400571_2 = "งานของหน่วยข่าวกรองมันช่างน่าเบื่อและจุกจิก จนบางครั้งก็ถือเป็นงานยากเลยแหละ แต่ก็มีข้อดีเหมือนกัน เช่น... เอ่อ ฉันจะเล่าความลับของไวซ์ให้เธอฟังเพื่อแลกกับปลาแห้งนะ",
  str_voice_1400571_3 = "ไม่ได้! ฉันจะไม่ทำเด็ดขาดถ้ามาบังคับให้ฉันทำ เพราะฉันไม่ชอบทำอะไรเหมือนที่คนอื่นเขาทำกันทุกคน แมวก็เป็นอย่างนี้กันหมดไม่ใช่เหรอ",
  str_voice_1400571_4 = "อ๊ะ ไม่นะ ฉันต้องทำยังไงเนี่ย ท่าทางฉันจะมีพลังมากขึ้นอีกแล้ว",
  str_voice_1400571_5 = "ฉันน่ะอ่อนแอมาก แต่ยูมินี่ตรงกันข้ามเลย ฉันรู้ว่ายูมิคอยปกป้องฉันอยู่... แม้ว่าเราจะไม่สามารถพบกันได้ก็ตาม",
  str_voice_1400571_6 = "ไปนอนซะฟิลิชี พอเธอตื่นขึ้น ก็จะได้เห็นปลาแห้งมากมายกองเต็มห้องไปหมด เหมียว จะไม่มีอิคลิพไซท์หรอก เหมียว และไม่มีอิคลิพส์ด้วย เหมียว",
  str_voice_1400571_7 = "หืม? ในรายงานจิตวิทยาของฉันมีเรื่องเกี่ยวกับยูมิแล้วก็เรื่องที่ฉันคลั่งไคล้ในการนอนอยู่ด้วย เฮ้... เรื่องนั้นฉันรู้ตัวดีนะโอเค? เพราะยังไงฉันก็เป็นแมวนะ",
  str_voice_1400571_8 = "เธอคิดว่าจะติดสินบนฉันด้วยปลากระป๋องราคาถูกได้เหรอ แล้วก็คาเวียร์ถูก ๆ เนี่ยนะ เธอนี่เข้าใจล้อเล่นจัง",
  str_voice_1400571_9 = "เมื่อกี้ยูมิเผยตัวแล้วเหรอ? เธอเป็นเด็กที่โดดเดี่ยวนะ ถ้าได้เจอกัน ก็ช่วยทำดีกับเธอหน่อย ส่วนกับฉัน\nอยากจะปฏิบัติยังไงก็ได้",
  str_voice_1400571_10 = "แสงอบอุ่น อุณหภูมิเย็นสบาย และสภาพแวดล้อมสมบูรณ์แบบ... ฉันขี้เกียจจัง ฉันไม่อยากทำอะไรเลยทั้งนั้น เหมียว",
  str_voice_1400571_11 = "ถึงฉันจะไม่ปฏิเสธเธอ แต่ฉันก็ไม่ชอบเอาตัวไปยุ่งกับปัญหานะ เหมียว",
  str_voice_1400571_12 = "เธอเห็นหมวกฉันไหม เหมียว อ๊ะ ไม่นะ ฉันลืมอีกแล้ว เหมียว!",
  str_voice_1400571_13 = "การรักษาสุขอนามัยเป็นเรื่องสำคัญ เหมียว อย่าลืมล้างมือแล้วก็บ้วนปากบ่อย ๆ นะ เหมียว และถ้าเป็นไปได้ ก็เว้นระยะห่างทางสังคมด้วย เหมียว",
  str_voice_1400571_14 = "เอ้านี่ มันคือปริศนาเรื่องความปรารถนา เหมียว เธอทายถูกไหมว่าฉันอยากได้อะไร เหมียว",
  str_voice_1400571_15 = "อ้อ อยากให้ฉันร้องเพลงสุขสันต์วันเกิดให้ฟังเหรอ เหมียว แค่ท่อนเดียวพอนะ แฮปปี้เบิร์ธเดย์ทูยู...",
  str_voice_1400571_16 = "เวลาบ่าย ๆ เป็นอะไรที่ดีงามนะ ถ้าฉันได้งีบสักนิดคงจะดีมากเลย เหมียว! เอ่อ ฉันไม่ได้คิดจะทิ้งงานนะ เหมียว!",
  str_voice_1400571_17 = "หา? ไม่เคยเห็นเรื่องบ้า ๆ บอ ๆ ตอนเช้าเหรอ เหมียว ก็วิเวียนไงล่ะ ไม่อยากเชื่อเลยว่าเธอจะตั้งเวลาปลุกฉัน 10 โมง บ้าบอชะมัดเลย เหมียว",
  str_voice_1400571_18 = "ได้เวลาอธิบายงานอีกแล้ว เหมียว แต่ฉันยังไม่ได้ทำอะไรเลยนะ เหมียว",
  str_voice_1400571_19 = "ง่วงจัง... ฉันตาลอยแล้วนะ เหมียว... ง่ำ ง่ำ ปลาเต็มไปหมด เพียบเลย เหมียว...",
  str_voice_1400571_20 = "ทุกคนที่อิลลูมินาจริงจังกับงานมากไปนะ เหมียว พวกเขาควรจะอู้บ้าง เหมียว!",
  str_voice_1400571_21 = "ฉันอิจฉาสัตว์ที่มีปีกมากเลย เหมียว โดยเฉพาะพวกที่มีขนนกบางเบาเนี่ย คิคิ!",
  str_voice_1400571_22 = "ขออิลลูมินาจงเจิดจำรัส เหมียว...",
  str_voice_1400571_23 = "เธอบอกว่าเป็นอิคลิพไซท์เหรอ พวกนั้นตัวเหม็นนะ เหมียว แล้วก็ไม่ค่อยสนใจสุขอนามัยส่วนตัวด้วย เหมียว",
  str_voice_1400571_24 = "จุ๊ๆ! เก็บเสียงของคุณไว้ หัวหน้าวิเวียนหลับไปแล้ว เธอคงเหนื่อยจากงานแล้วล่ะ เหมียว",
  str_voice_1400571_25 = "หางของเจ้าหน้าที่ชาโรนา... มันไม่ใช่ของเล่น แต่ฉันอดไม่ได้น่ะ เหมียว!",
  str_voice_1400571_26 = "ฉันจะปล่อยให้เธอลองแอบดูนะ เหมียว! ปลาแห้งทองคำในตำนาน สมบัติล้ำค่าของฉัน เหมียว!",
  str_voice_1400571_27 = "อะไรนะ เหมียว ฉันต้องวิ่ง 800 เมตรเหรอ ฉันนึกภาพไม่ออกแน่นอน ให้ฉันวิ่ง 100 เมตรยังแทบจะไม่ไหวเลย เหมียว",
  str_voice_1400571_28 = "กว้างขวางจังเลย! เธอช่วยจัดห้องให้ฉันห้องหนึ่งด้วยได้ไหม เหมียว ฉันขอห้องที่มีผ้าห่มนุ่ม ๆ ปูบนพื้นนะ เหมียว",
  str_voice_1400571_29 = "หา แนะนำตัวเหรอ เราข้ามไปเลยได้ไหม เหมียว มันวุ่นวายเกินไปนะ ฉันแค่อยากจะงีบสักหน่อย เหมียว เมื่อคืนฉันทำงานจนดึกและฉันก็... ง่วง... เกินกว่า... จะ...",
  str_voice_1400571_30 = "เหมียววู้วู้... ฉันแข็งแกร่งขึ้นอีกครั้งแล้ว!",
  str_voice_1400571_31 = "มันมีวิธีอื่นที่อู้ได้อีกไหม เหมียว",
  str_voice_1400571_32 = "ฉันอยากจะเดินเหินได้อย่างปราดเปรียวและฟังเสียงอื่น",
  str_voice_1400571_33 = "ความฝันที่สวยงามกำลังจะเริ่มต้นขึ้น เหมียว ปล่อยให้ฟิลิชีนอนสักพักเหมียว",
  str_voice_1400571_34 = "*หาว* เริ่มรึยัง เหมียว",
  str_voice_1400571_35 = "อยู่ดี ๆ ฉันก็ง่วงขึ้นมา",
  str_voice_1400571_36 = "เฮ้อ หนังตามันหนักจัง...",
  str_voice_1400571_37 = "เหมียว! หยุดก่อน! อย่าขยับ ให้ฉันพักก่อน เหมียว",
  str_voice_1400571_38 = "เหมียว! พวกเธอทุกคนช่างโง่เง่าจัง เหมียว",
  str_voice_1400571_39 = "เสร็จแล้วฉันจะพักหน่อยนะ",
  str_voice_1400571_40 = "นี่มันจบแล้ว เหมียว!",
  str_voice_1400571_41 = "เอาละ ๆ ฉันทำได้ ๆ",
  str_voice_1400571_42 = "หา พวกนั้นแพ้แล้ว",
  str_voice_1400571_43 = "อุ๊ย! เราแป้กน่ะ",
  str_voice_1400571_44 = "อื้อหือ ถ้าฉันได้งีบสักแป๊บก็คงจะดีเนอะ",
  str_voice_1400571_45 = "อืม เอ้อ ปล่อยให้ฟิลิชีนอนสักพักนะ เหมียว",
  str_voice_1400571_46 = "เหมียว เธอก็มีของขวัญให้ยูมิเหมือนกันเหรอ เยี่ยมไปเลย!",
  str_voice_1400571_47 = "หา ฉันควรขอบคุณเหรอ ก็ได้... งั้นก็ขอบใจละกันนะ",
  str_voice_1400571_48 = "เหมียว! เราอยากได้แบบนี้มาตั้งนานแล้ว เยี่ยมไปเลยมะ-เหมียว",
  str_voice_1400571_49 = "ถ้าฉันจะภาวนาและตั้งใจทำงานให้เต็มกำลังแล้วยังไงล่ะ มันจะช่วยอะไรได้เหรอ ฉันว่าฉันนอนซะเลยดีกว่า เหมียว",
  str_voice_1400571_50 = "ที่จริงแล้วฉันหวังเล็ก ๆ นะ เหมียว... ครั้งหนึ่งเคยมีแมวที่คอยอยู่เป็นเพื่อนฉัน และฉันก็หวังแค่ว่ามันจะกลับมาหาฉัน เหมียว",
  str_voice_1400571_51 = "ถ้าเป็นความต้องการของฟิลิชี ยังไงก็ต้องเป็นฉัน ยูมิ คอยป้องกันไม่ให้เธอต้องทนทุกข์และคอยเติมเต็มความปรารถนาของเธอ... ฉันทำเพื่อเธอได้ทุกอย่าง ยกเว้นไปพบเธอด้วยตัวเอง",
  str_voice_1400571_52 = "Alchemy Stars เหมียว",
  str_voice_1400571_53 = "เหมียว...",
  str_voice_1400571_54 = "หาว หาว... ฉันตื่นแล้ว เหมียว...",
  str_voice_1400571_55 = "ปลาแห้ง... ปลาแห้ง...",
  str_voice_1400571_56 = "เหมียว! น่ารำคาญจัง! เธอหายหัวไปไหนเนี่ย",
  str_voice_1400571_57 = "โอ้โห! นี่ปีใหม่แล้วเหรอ เหมียว",
  str_voice_1400681_1 = "บุคคลที่กล้าหาญอย่างฉันไม่จำเป็นต้องหลอกล่ออะไรใคร อย่างเช่นแกล้งตายหรอก... ถ้าเป็นเรื่องในวัยเด็กล่ะนับไหม ก็ต้องไม่นับสิ!",
  str_voice_1400681_2 = "ถ้าซินซาจอมเซ่ออยากคว้าตัวเธอ ก็เตะที่หัวเข่าเขาเลย แบบนี้ไง ฮะชึบ! ได้ผลทุกครั้ง",
  str_voice_1400681_3 = "ทะเลทรายเนี่ย ถ้าไม่ร้อนจัดก็เย็นจัด คนที่ไม่มีเสื้อขนเป็ดอย่างเธอคงอยู่ไม่รอดถึงสามวันหรอกใช่ไหม จิ๊ ๆ ๆ...",
  str_voice_1400681_4 = "ทำไมฉันถึงหมกมุ่นอยู่กับความเร็วลมน่ะเหรอ เห็นปีกสั้น ๆ และทรงพลังของฉันไหม ยังไม่เข้าใจอีกเหรอ ลองมองดี ๆ สิ เข้ามาใกล้ ๆ!",
  str_voice_1400681_5 = "นี่คืออุปกรณ์เดินทางสามชิ้นของฉัน เสื้อกันหนาวขนเป็ดรักษาอุณหภูมิแบบเบาบางพิเศษ แว่นกันลมของเด็กไม่ไปโรงเรียน แล้วก็เจ็ตแพ็กสุดไฮเทค! เจ๋งไปเลยใช่ไหมล่ะ",
  str_voice_1400681_6 = "ไม่สำคัญหรอกว่ามันจะอันตรายรึเปล่า เพราะยังไงก็หันหลังกลับหรือหนีกลางคันได้! สิ่งสำคัญที่สุดคือความสามารถที่จะออกบินเมตรแรกให้ได้ แล้วก็ความกล้าที่จะรับการท้าทาย!",
  str_voice_1400681_7 = "หืม อยากจับปีกฉันดูไหม มาเถอะ จับดูเลยถ้าไม่กลัวมันฟาดเอา ไม่มีอะไรต้องกลัวหรอก หนักสุดก็แค่โดนโบกสลบเอง",
  str_voice_1400681_8 = "เข้ามาใกล้อีกสิ ไม่ต้องกลัว... ฉันจะทำอะไรเธอน่ะเหรอ ฉันทำอะไรก็ได้ตามใจอยู่แล้ว เธอคิดว่าจะต้านทานได้ไหมล่ะ ฮิฮิ!",
  str_voice_1400681_9 = "ไม่ต้องกลัว ทีนี้ก็เดินวางมาดตามฉันมาได้เลย! ฉันจะสอนบทเรียนให้ทุกคนที่กล้ามารังแกเธอเอง ส่วนฉันก็ ฮิฮิ เอ่อ เราสนิทกันนะ!",
  str_voice_1400681_10 = "ฉันเบื่อจนขนแทบร่วงแล้วเนี่ย! มาเล่นกับฉันหน่อย! อะไรเนี่ย ขนนกที่ร่วงจากตัวฉันตอนเคลื่อนที่กับตอนที่ไม่ได้ทำอะไร มันเหมือนกันได้ยังไง",
  str_voice_1400681_11 = "อ้า ใช่เลย เป็นอย่างที่คิดไว้ เธอมีดวงตาหยั่งรู้ ที่นี่คือเขตแดนของฉันนับแต่นี้ไป วะฮะฮ่า!",
  str_voice_1400681_12 = "เธอหมุนตัวให้ฉันดูหน่อยได้ไหม ...นี่เธอไม่มีขนหางสักเส้นเลยจริง ๆ อ่ะ... ไม่หนาวเหรอ",
  str_voice_1400681_13 = "รอให้ฉันสูบลมเจ็ตแพ็กก่อน... ยังไงน่ะเหรอ ก็เป่าลมเข้าไปน่ะสิ! ...เป่าลมเข้าไปแล้วก็เติมเชื้อเพลิง",
  str_voice_1400681_14 = "เราควรทำไงเวลาที่เจอศัตรูน่ะเหรอ ก็พุ่งใส่ก่อนเลย ถ้ามีอะไรผิดพลาด ยังไงก็หันหลังกลับได้เสมอ!",
  str_voice_1400681_15 = "วันนี้วันเกิดเธอเหรอ เดี๋ยวนะ... ดูสิ ฉันขนร่วง เอ้านี่ เธอเอาไปเล่นสิ",
  str_voice_1400681_16 = "อ้าว! เธอกลับมาจนได้! ร่าเริงหน่อยแล้วก็โบกมือที่อ่อนเปลี้ยให้ฉันที",
  str_voice_1400681_17 = "ตื่นแล้วเหรอ เอ้านี่ ฉันมั่นใจว่าเธอต้องตื่นแน่นอนหลังจากที่ฉันจัดให้เธอสองข้าง... สองข้างอะไรน่ะเหรอ ก็นวดหัวเข่าไง!",
  str_voice_1400681_18 = "หนอนทรายแห้งแสนโอชะ กิ้งก่าแห้ง ไส้เดือนแห้งก็มี! อยากชิมไหมล่ะ ฮิฮิ ลองดูสิ",
  str_voice_1400681_19 = "นอนไม่หลับเหรอ เดี๋ยวฉันพัดให้เอง! ...แค่พัดเฉย ๆ อย่ากลัวให้มากเลยน่า",
  str_voice_1400681_20 = "ฮิ ๆ สหภาพผู้ส่งสารนี่เจ๋งมากเลย! ถึงจะทำงานในระดับเล็ก ๆ แต่ก็ทำได้ทุกอย่าง!",
  str_voice_1400681_21 = "ชิ ถ้าผู้รับเป็นคนของเรดีเซล เวรนช์แล้วทำไมล่ะ แค่เล่น ๆ นิดเดียวพวกเขาจะถึงกับสูญเสียจิตวิญญาณไปเลยรึ",
  str_voice_1400681_22 = "สหภาพผู้ส่งสารจัดให้ได้เสมอ!",
  str_voice_1400681_23 = "อิคลิพไซท์นี่น่ากลัวไหม หืม ฉันเอาตัวรอดได้แน่ตราบใดที่พวกมันมีหัวเข่า!",
  str_voice_1400681_24 = "โดฟปล่อยให้ฉันรอเก้ออีกแล้ว! วันหนึ่งนะ ฉันจะจับนางถอนขนให้หมดตัวเลย!",
  str_voice_1400681_25 = "เธอเสียงดังอึกทึกมาก แล้วก็มีภูตวาจา จัดส่งด้วยความเร็วสุดพิเศษ และขนร่วงเยอะเลยด้วย เท่มาก",
  str_voice_1400681_26 = "ฉันชอบเก็บขนนก บินที่ความเร็วลม แล้วก็เล็งที่หัวเข่า!",
  str_voice_1400681_27 = "ฉันเกลียดอะไรเมือก ๆ ที่สุด! แค่คิดว่ามันจะมาติดขนก็อี๋แล้ว!",
  str_voice_1400681_28 = "โคลอสซัสก็เป็นภูตวาจาไม่ใช่เหรอ ต่างกันตรงไหนล่ะ อ้อ มันไม่มีชีวิต... แปลกเนอะ",
  str_voice_1400681_29 = "ใช่แล้วละ ฉันคือมิสไซล์วิถีโค้งความเร็วสูงที่บินข้ามทะเลทราย รู้จักกันในชื่อความเร็วแสงควงสว่าน พนักงานส่งสารที่น่ารักและกล้าหาญ สาวน้อย เวนดี้!",
  str_voice_1400681_30 = "ตัวฉันที่ว่องไวและแข็งแกร่งขึ้น!",
  str_voice_1400681_31 = "ว้าว! ฉันนี่น่าทึ่งจังเลย",
  str_voice_1400681_32 = "ลมอ่อน ๆ กำลังแปรเปลี่ยนเป็นพายุเฮอร์ริเคนย่อม ๆ!",
  str_voice_1400681_33 = "ฉันพร้อมที่จะท้าทายทวีปนี้แล้ว!",
  str_voice_1400681_34 = "ให้ฉันช้าลงกว่านี้ไหม",
  str_voice_1400681_35 = "ความเร็วลม เรียบร้อย!",
  str_voice_1400681_36 = "ฉันจะทำให้ดูว่าความเร็วลมมันเป็นยังไง!",
  str_voice_1400681_37 = "ลงจอดที่ความเร็วลม!",
  str_voice_1400681_38 = "ความเร็วลมมันมีเยอะแยะมากจนฉันไม่รู้จะเรียกว่าอะไรแล้ว!",
  str_voice_1400681_39 = "ลูกเตะความเร็วลม!",
  str_voice_1400681_40 = "โจมตีที่ความเร็วลม!",
  str_voice_1400681_41 = "เธอจะตามการโจมตีที่เร็วดุจลมของฉันทันไหม",
  str_voice_1400681_42 = "ความเร็วลมเพื่อชัยชนะ!",
  str_voice_1400681_43 = "เจอลมเข้าไปซะ ฉันเกือบต้องแกล้งตายแน่ะ!",
  str_voice_1400681_44 = "เธอจะให้ฉันนำส่งอะไรล่ะ ฉันส่งได้ทุกที่เลย",
  str_voice_1400681_45 = "ให้ของนี้มาทำไมเหรอ จะให้เอาไปส่งที่ไหนเหรอ",
  str_voice_1400681_46 = "ฮ่าฮ่าฮ่า รู้แล้วสินะว่าต้องทำไง",
  str_voice_1400681_47 = "งั้นฉันก็เป็นผู้รับเหมือนเดิมเหรอ",
  str_voice_1400681_48 = "ได้รับของขวัญแล้วล่ะ ชอบมากเลย เย้ เย้",
  str_voice_1400681_49 = "ค้นหาผู้รับมันง่ายออกนะ คนที่อาศัยอยู่ในทะเลทรายมีตั้งมากมาย ก็แค่ไล่ตามไปทีละคน... จนกว่าผู้รับจะหนีไปหมดไงล่ะ ฮ่าฮ่า",
  str_voice_1400681_50 = "ภูตวาจามักเป็นสัตว์ที่ฝึกให้เชื่องแล้ว ฉันน่ะยังไม่มีหรอก... ฉันควรไปจับมาสักตัวไหมนะ ฮิฮิฮิ เข้ามาใกล้ ๆ สิ ไม่ต้องกลัว...",
  str_voice_1400681_51 = "เคยเห็นฝูงของอิคลิพไซท์ไหม ฉันอยู่ที่นั่นตอนที่ยังเป็นมือใหม่ รู้ใช่ไหมว่านกขยันจะได้หนอนไปกิน ช่วยไม่ได้ที่ฉันดันเกิดมาเก่งสุด ๆ",
  str_voice_1400681_52 = "Alchemy Stars!",
  str_voice_1400681_53 = "ฉันจะไปตามหาเธอเดี๋ยวนี้เลย!",
  str_voice_1400681_54 = "นี่เธอยังง่วงอยู่เหรอ",
  str_voice_1400681_55 = "มาสิ! มาด้วยความเร็วลมเลย!",
  str_voice_1400681_56 = "ฉันจะไปตามหาเธอ ไม่ต้องกลัวนะ",
  str_voice_1400681_57 = "วู้ฮู้! สุขสันต์วันปีใหม่!",
  str_voice_1400831_1 = "กำลังตอบคำถาม กำลังแปลและแปลงสาร กำลังตอบกลับ ลิลเลียมคือร่างโคลนของลิลิน ไม่ใช่หุ่นยนต์แต่เป็นหญิงรับใช้",
  str_voice_1400831_2 = "กำลังตอบ ตั้งโปรแกรมโหมดการพูดหมายเลข 1 กำลังแปลและแปลงสาร... แค่ว่าบุคลิกของหมายเลข 1 จะแข็งกร้าวกว่าน่ะสิ",
  str_voice_1400831_3 = "กำลังแปลและแปลงสาร กรุณาปฏิบัติต่อหมายเลข 1 ในฐานะหญิงรับใช้ทั่วไป และมอบหมายงานให้เธอด้วย กรุณาปฏิบัติต่อหมายเลข 2 ในฐานะหญิงรับใช้จอมอู้ และมอบหมายงานให้เธอเยอะ ๆ เลย",
  str_voice_1400831_4 = "การเปิดเผยข้อมูล บุคลิกภาพที่ตั้งโปรแกรมจะถูกจารึกไว้ในลิลเลียม และบันทึกไว้ในโหมดการคิดแบบตายตัว การละเว้นได้รับอนุญาตตามการอนุญาตที่กำหนด",
  str_voice_1400831_5 = "กำลังเปิดเผยข้อมูล หมายเลข 1 การอนุญาตตัดสินใจระดับ 1 การรักษาความลับระดับ 3 ฐานข้อมูลระดับ 3 ล็อกทฤษฎีวิวัฒนาการระดับ 2",
  str_voice_1400831_6 = "- การแนะนำ ลิลเลียมหมายเลข 2 ฐานข้อมูลระดับ 4 ล็อกทฤษฎีวิวัฒนาการระดับ 1\n- กำลังแปล โก๊ะเล็กน้อย ไม่เคยเรียนรู้",
  str_voice_1400831_7 = "กำลังแปลและแปลงสาร กรุณาอย่ากังวล หากหมายเลข 1 ได้รับบาดเจ็บ สามารถรักษาหรือหาตัวทดแทนได้",
  str_voice_1400831_8 = "กำลังเปิดเผยข้อมูล ลิลเลียมเข้าใจดีแล้ว คำสั่งสูงสุดคือให้ปกป้องลิลิน คำสั่งสูงสุดรองลงมาคือปกป้องคุณ",
  str_voice_1400831_9 = "กรุณาอย่าแปลกใจ หมายเลข 1 สามารถงดเว้นอุปนิสัยที่โปรแกรมไว้ได้ตามการตัดสินใจของเธอเอง รายงานเพิ่มเติม หมายเลข 1 ต้องการที่จะมีการสื่อสารที่ลึกซึ้งยิ่งขึ้นกับคุณ",
  str_voice_1400831_10 = "ตรวจพบความอ่อนแอ... การตรวจพบเสร็จสมบูรณ์ อนุมัติคำสั่ง ลิลเลียมจะรับใช้คุณและพร้อมใช้งานแล้ว",
  str_voice_1400831_11 = "กำลังเปลี่ยนสถานะ กำลังแปลและแปลงสาร หมายเลข 1 หญิงรับใช้เลื่องชื่อ พร้อมสำหรับการต้อนรับแขกเสมอ",
  str_voice_1400831_12 = "ดวงตา: ว่าง คำตอบ: หมายเลข 1 จะดูแลดวงตาอย่างดี กรุณาอย่ากังวล",
  str_voice_1400831_13 = "หมายเลข 1 ทำความสะอาดห้องเสร็จเรียบร้อยแล้ว ปัดฝุ่นละเอียดครบทุกเม็ด",
  str_voice_1400831_14 = "คำอธิบายการเปิดใช้ตัวเอง มีลิลเลียมอื่น ๆ นอกจากหมายเลข 1 และ 2",
  str_voice_1400831_15 = "เรียกใช้งาน 0522 เข้ามาใกล้ ๆ หน่อย นายท่าน เรียกใช้งาน: โปรโตคอลสุขสันต์วันเกิด สุขสันต์วันเกิดนะ",
  str_voice_1400831_16 = "ยินดีต้อนรับกลับมา นายท่าน คำกล่าว: เสิร์ฟชาดำแล้ว",
  str_voice_1400831_17 = "อรุณสวัสดิ์ นายท่าน กำลังสร้างคำกล่าว อาหารเช้าพร้อมแล้ว",
  str_voice_1400831_18 = "ยินดีต้อนรับกลับมา นายท่าน กำลังถาม: คุณต้องการรับประทานอาหารเย็นหรือของหวาน",
  str_voice_1400831_19 = "คุณต้องเหนื่อยแน่เลย นายท่าน กำลังถาม: คุณอยากอาบน้ำตอนนี้เลยไหม",
  str_voice_1400831_20 = "อนุมัติคำสั่ง การตัดสินใจระดับ 3 คือเพื่อปกป้องอิลลูมินา บุคคลที่อนุมัติคำสั่ง ได้แก่ ไรน์ฮาร์ต",
  str_voice_1400831_21 = "กำลังยืนยันคำสั่ง อนุมัติ ปลดล็อกแล้ว ลิลเลียมหมายเลข 4 เพื่อติดตามทรู ออเดอร์",
  str_voice_1400831_22 = "เพื่อ... เกียรติภูมิของลิลิน",
  str_voice_1400831_23 = "กำลังตอบ กำลังลบคำสั่ง ความสำคัญระดับ 4 กำลังปฏิเสธคำสั่ง ความสำคัญระดับ 3",
  str_voice_1400831_24 = "การกำหนดเป้าหมาย นักวิจัยบ้าคลั่ง อันตรายระดับ 2 อย่าอยู่กับเธอตามลำพัง",
  str_voice_1400831_25 = "การกำหนดเป้าหมาย แมวขาว ความเสี่ยงข้อมูลรั่วไหลปานกลาง อันตรายระดับ 2",
  str_voice_1400831_26 = "กำลังตอบ ลิลเลียมชอบกิจกรรมทำความสะอาดและอุปกรณ์โลหะน้ำหนักเบาเยอะ ๆ",
  str_voice_1400831_27 = "การอนุญาตตัดสินใจระดับ 1 อนุญาตให้ \"ไม่ชอบ\" กำลังตอบ หมายเลข 1 ไม่ชอบปลา",
  str_voice_1400831_28 = "กำลังตัดสินใจ ตรวจพบสัญญาณการเชื่อมต่อ ชุดคลื่นเดียวกัน กำลังติดตาม ล้มเหลว กำลังทำการตรวจสอบติดตามตัวตน",
  str_voice_1400831_29 = "กำลังยืนยันคำสั่ง อนุมัติ หมายเลข 1 กำลังเปลี่ยนสถานะ หญิงรับใช้ นายท่าน นี่คือข้อความสำหรับคุณ ลิลเลียมจะกลายเป็นพลังงานเพื่อปกป้องคุณ",
  str_voice_1400831_30 = "กำลังตัดสินใจ เพิ่มความสามารถแล้ว",
  str_voice_1400831_31 = "เพิ่มความแข็งแกร่งแล้ว ยกระดับการอนุญาต",
  str_voice_1400831_32 = "กำลังสร้างคำกล่าว ผู้กำกับฐานข้อมูลปลดล็อกแล้ว",
  str_voice_1400831_33 = "- กำลังแนะนำเจ้านาย ลิลิน\n- หมายเลข 2 รายงานตัวเข้าปฏิบัติหน้าที่",
  str_voice_1400831_34 = "กำลังเปลี่ยนสถานะ ผู้ปฏิบัติการ",
  str_voice_1400831_35 = "โจมตี พร้อม",
  str_voice_1400831_36 = "เซฟโหมด ปิด",
  str_voice_1400831_37 = "โหมด ทำลายภูมิภาค",
  str_voice_1400831_38 = "- คำสั่ง ทำลายภูมิภาค\n- รับทราบ!",
  str_voice_1400831_39 = "โหมด ปกป้อง",
  str_voice_1400831_40 = "โหมด ขับไล่",
  str_voice_1400831_41 = "กำลังเปลี่ยนสถานะ ผู้บัญชาการ",
  str_voice_1400831_42 = "ภารกิจเสร็จสิ้น เปลี่ยน",
  str_voice_1400831_43 = "ภารกิจล้มเหลว เปลี่ยน",
  str_voice_1400831_44 = "กำลังถาม วันนี้อากาศดีมาก มีอะไรให้ฉันช่วย",
  str_voice_1400831_45 = "กำลังตัดสินใจ ไอเทมเกรดธรรมดา",
  str_voice_1400831_46 = "ตัวแทนหมายเลข 1 กำลังรับของขวัญที่ถูกใจ",
  str_voice_1400831_47 = "คำกล่าวเกินจริง ดูธรรมดาอยู่",
  str_voice_1400831_48 = "ลิลเลียม หมายเลข 1 ชอบของขวัญของคุณ",
  str_voice_1400831_49 = "กำลังสร้างคำกล่าว ลิลเลียมสามารถพูดได้ปกติในฐานะหญิงรับใช้ แต่จากการสำรวจพบว่า โหมดการพูดหมายเลข 1 ได้รับความนิยมในหมู่ลูกค้า",
  str_voice_1400831_50 = "กำลังเปิดเผยข้อมูล หมายเลข 1 เคยเป็นหญิงรับใช้ธรรมดาเมื่อตอนที่เธอตื่นขึ้นมา เธอพบเจ้านายลิลินที่เมืองใต้ดินหมายเลข 28 กำลังปลดล็อกคำสั่งสูงสุด",
  str_voice_1400831_51 = "กำลังแนะนำ ฟีเจอร์ทั่วไปของลิลเลียม: กระบวนการ คำสั่ง ไม่มีการชักจูง... กำลังแปล: ความคิด ภารกิจ ไม่สามารถฝ่าฝืนคำสั่งได้",
  str_voice_1400831_52 = "Alchemy Stars",
  str_voice_1400831_53 = "นายท่าน",
  str_voice_1400831_54 = "อรุณสวัสดิ์ นายท่าน",
  str_voice_1400831_55 = "คุณอยากดื่มชายามบ่ายหรือไม่",
  str_voice_1400831_56 = "กำลังแปลและแปลงสาร ลิลเลียมต้องการคุณ",
  str_voice_1400831_57 = "ขอให้คุณมีความสุขในวันปีใหม่นะ นายท่าน",
  str_voice_1400861_1 = "ดาเมจที่สร้างโดยดาบพิธีกรรมจะแปลงเป็นการรักษาผู้อื่น มันขัดแย้งแต่ก็จริงแท้ใช่ไหมล่ะ",
  str_voice_1400861_2 = "ฉันมักยอมรับคำร้องขอจากพิธีกรงานศพตามแต่โอกาส เพื่อกล่าวคำลาให้กับผู้ที่จากไปและปลอบโยนญาติมิตรของพวกเขาที่กำลังโศกเศร้า ใคร ๆ ก็มักบอกว่าฉันเหมาะสมกับหน้าที่นี้อย่างมาก",
  str_voice_1400861_3 = "ฉันทำได้ดีมาก ดังนั้นกรุณาปล่อยให้ฉันจัดการเถอะ ฉันเพียงแค่ต้องทำให้ทุกคนลงนอนในท่าที่สงบใช่ไหม",
  str_voice_1400861_4 = "ฉันเพียงแค่เปลี่ยนความโศกเศร้าให้เป็นความแข็งแกร่ง เพื่อให้ฉันสามารถทำทุกสิ่งที่สามารถทำได้เพื่อช่วยเหลือผู้ที่ยังมีชีวิตอยู่",
  str_voice_1400861_5 = "แด่ผู้ที่ถูกลืมในสนามรบ ชื่อของพวกเธอจะไม่ถูกลืม เนื่องจากผู้คนจะภาวนาให้ พวกเขาจะภาวนาให้กับความตายของผู้ที่ทอดทิ้งเธอ",
  str_voice_1400861_6 = "ฉันหวงแหนความทรงจำของผู้ตาย แสดงความโศกเศร้าเพื่อพวกเขา ยกย่องคุณประโยชน์ของพวกเขา และขับร้องจากหัวใจให้เกียรติยศในอดีตของพวกเขาเพื่ออนาคตที่ดียิ่งขึ้น!",
  str_voice_1400861_7 = "ปลายด้านหนึ่งเป็นหนามแหลม ส่วนปลายอีกด้านหนึ่งเป็นเถาวัลย์ดอกไม้ที่ไร้พิษภัย ไม่ต้องห่วง เพราะฉันจะเบนด้านที่ถูกต้องไปทางเธอตามธรรมชาติ",
  str_voice_1400861_8 = "ฉันจะจดจำใบหน้า ความเมตตา ความอบอุ่น และคุณสมบัติของเธอที่จะไม่มีวันจางหายเอาไว้ เธอจะอยู่ในหัวใจของฉันตลอดไป",
  str_voice_1400861_9 = "ฉันนำเถาวัลย์ดอกไม้มาให้เธอ เถาวัลย์พวกนี้มีดอกไม้สีขาวที่ฉันชอบมาก ขอให้มันนำความอบอุ่นมาให้เธอต่อไปในขณะที่ฉันยังมีชีวิตอยู่",
  str_voice_1400861_10 = "นี่คือเกมง่าย ๆ เรามาทายกันไหมว่าใครจะได้จากไปเป็นคนต่อไป เธอควรภาวนานะถ้ารู้สึกไม่สบายใจ...",
  str_voice_1400861_11 = "ฉันอยากปลูกเถาวัลย์ดอกไม้ในที่ไกลโพ้นใต้แสงตะวัน ฉันหวังว่ามันจะนำแสงอาทิตย์มาสู่เงามืดได้ แม้มันจะสั้นนิดเดียวก็ตาม",
  str_voice_1400861_12 = "แน่นอนว่าฉันจะวางดาบในมือลง เพื่อเห็นแก่มารยาท ฉันจะภาวนาก่อนโจมตี",
  str_voice_1400861_13 = "เด็กน้อยผู้น่าสงสาร ฉันเห็นเธอตัวสั่นเทา จงตามหาฉัน แล้วฉันจะทำให้มันหยุดลง",
  str_voice_1400861_14 = "เธอไม่คิดว่ามันง่ายกว่ากันมากที่จะแก้ไขปัญหาทุกอย่างด้วยรอยยิ้มเหรอ",
  str_voice_1400861_15 = "วันนี้เป็นวันสำคัญ มาฉลองวันสำคัญที่ไม่มีสิ่งใดเทียบได้ในวันนี้ขณะที่เธอยังมีชีวิตอยู่",
  str_voice_1400861_16 = "ยินดีต้อนรับกลับมา ถ้าเธอต้องการ ฉันจะภาวนาให้เธอนานขึ้นอีกนิด",
  str_voice_1400861_17 = "อรุณสวัสดิ์ ฉันดีใจจังที่ได้เห็นหน้าเธอทันทีหลังจากที่ตื่น",
  str_voice_1400861_18 = "โปรดสำรวจชีวิตจำกัดของเธอได้ตามสบาย โอบกอดความเป็นจริงของสิ่งที่อยู่ในหัวใจก่อนที่จะล้มตัวนอน",
  str_voice_1400861_19 = "นอนไม่หลับเหรอ เรื่องใหญ่นะนั่น เธอต้องการให้ฉันช่วยปิดตาให้ไหม",
  str_voice_1400861_20 = "ฉันให้อภัยทุกอย่าง และเชื่อสุดหัวใจว่ารัตติกาลสีขาวเป็นตัวแทนของแสงสว่าง แม้สิ่งเดียวที่ฉันจะได้รับกลับคืนมาอาจเป็นแค่การไม่ถูกลืมเท่านั้น",
  str_voice_1400861_21 = "ไม่ได้ว่านะ แต่โดยมารยาททางตำแหน่งแล้ว เธอบอกฉันได้ไหมว่าต้องพูดจาแบบไหนเพื่อความจริง",
  str_voice_1400861_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1400861_23 = "ฉันภาวนาให้อิคลิพไซท์ที่น่าสงสารพวกนั้น ฉันภาวนาให้พวกมันตายไปเร็ว ๆ",
  str_voice_1400861_24 = "ขอให้ฉันได้แสดงความเสียใจจากหัวใจ ในวิธีที่เข้าใจได้ง่าย ฉันขอโทษที คือพวกนี้มันน่ารักมากจริง ๆ",
  str_voice_1400861_25 = "“หวังว่าเธอจะพูดอะไรที่แตกต่างจากที่เธอพูดเกี่ยวกับพ่อของฉันที่งานศพของฉัน” นั่นคือสิ่งที่เธอเคยพูดกับฉัน",
  str_voice_1400861_26 = "สิ่งที่ฉันชอบก็คือสนามหญ้าหลังฝนตก ต้นไม้เล็ก ๆ งอกขึ้นมาจากพื้นดิน และแสงสว่างที่ส่องทะลุลงมาจากรูบนหลังคา",
  str_voice_1400861_27 = "ที่จริงแล้ว ฉันเกลียดจดหมายลับและคนทรยศ",
  str_voice_1400861_28 = "บรรยากาศที่เคร่งขรึมและเส้นสายที่ชัดเจนทำให้ฉันนึกถึงโถงรำลึก... ฉันรู้สึกผ่อนคลายมากตอนอยู่ที่นั่น",
  str_voice_1400861_29 = "ขอบคุณนะที่ชวน โปรดเรียกฉันว่ายูริอาห์ คำภาวนาของฉันไร้ซึ่งอคติใด ๆ เพราะยังไงซะ ฉันก็ต้องมีมารยาทในระดับที่เหมาะสมเพื่อแสดงความเคารพต่อชีวิตและความตาย",
  str_voice_1400861_30 = "ฉันจะภาวนาเสมอ",
  str_voice_1400861_31 = "ขอให้คำภาวนาของฉันจงมีพลังมากยิ่งขึ้น",
  str_voice_1400861_32 = "การรอดพ้นและความไว้วางใจเพิ่มมากขึ้น",
  str_voice_1400861_33 = "จนกว่าเหตุการณ์ที่ฉันหวังไว้จะมาถึง",
  str_voice_1400861_34 = "เข้าร่วมพิธีเหรอ",
  str_voice_1400861_35 = "กรุณาตั้งใจฟังด้วย",
  str_voice_1400861_36 = "ฉันมีอะไรจะประกาศ",
  str_voice_1400861_37 = "นี่คือสุนทรพจน์",
  str_voice_1400861_38 = "ขอให้ความตายจงอยู่ห่างจากพวกเธอทุกคน",
  str_voice_1400861_39 = "ภาวนา",
  str_voice_1400861_40 = "ไว้อาลัย",
  str_voice_1400861_41 = "รับหน้าที่ประกอบพิธีเหรอ",
  str_voice_1400861_42 = "จบแล้ว ขอบใจนะที่มา",
  str_voice_1400861_43 = "นี่ได้เวลา... ที่จะกล่าวลา...",
  str_voice_1400861_44 = "เธอน่ารักจังเลย เพื่อเป็นการตอบแทน ให้ฉันออกไปส่งนะ",
  str_voice_1400861_45 = "อันนี้เอาไว้วางหน้าหลุมศพฉันเหรอ",
  str_voice_1400861_46 = "ของขวัญนี้เหมือนพรจากฟ้าเลย",
  str_voice_1400861_47 = "ฉันจะเอาไปไว้ในที่ที่ฉันจะหลับใหลไปตลอดกาลนะ",
  str_voice_1400861_48 = "เพราะเธอแท้ ๆ เลยนะ ฉันจะมองเห็นคุณค่าของชีวิตตลอดไป",
  str_voice_1400861_49 = "เถาวัลย์ดอกไม้จะเหนี่ยวรั้งความหวังอันยิ่งใหญ่ของฉันเอาไว้... นี่คือสาเหตุที่ฉันต้องรักษากิริยามารยาท เพื่อให้ฉันสามารถอดทนและเลือกที่จะให้อภัยผู้อื่นได้",
  str_voice_1400861_50 = "ให้ฉันเล่าวีรกรรมของเธอให้ฟังก่อนนะ ครั้งหนึ่งเธอเคยถือจดหมายฉบับหนึ่งที่จะส่งเธอไปยังสนามรบโดยไม่รู้ตัว",
  str_voice_1400861_51 = "ในวันนั้น ฉันได้ไว้อาลัยให้กับอดีตด้วยความเศร้าโศกอย่างสุดซึ้ง ฉันได้อำลาความทุกข์ทนที่แปดเปื้อน และต้อนรับชีวิตใหม่ที่มีอิสรภาพและความสบายใจ",
  str_voice_1400861_52 = "Alchemy Stars",
  str_voice_1400861_53 = "สวัสดี",
  str_voice_1400861_54 = "อรุณสวัสดิ์",
  str_voice_1400861_55 = "นี่ก็เที่ยงแล้ว เธอเป็นไงบ้าง",
  str_voice_1400861_56 = "สายัณห์สวัสดิ์ ฉันซื้อดอกไม้สีขาวมา",
  str_voice_1400861_57 = "สุขสันต์วันปีใหม่! ขอให้มีชีวิตยืนยาวนะ",
  str_voice_1500181_1 = "นี่เธอฟังอัลบั้มล่าสุดของบาร์บาร่ารึยัง มันแย่มากจนน่าเอาไปโยนทิ้งในเตาเผาเลย วงนี้มันขยะชัด ๆ!",
  str_voice_1500181_2 = "เธออยากคุยกับฉันจริง ๆ เหรอ ก็ได้ เธอชอบดนตรีประเภทไหนล่ะ เธอควรคิดให้ดีก่อนนะ ฉันจะไม่ยุ่งเกี่ยวกับคนที่ไร้รสนิยมเด็ดขาด",
  str_voice_1500181_3 = "อยากรู้เรื่องราวของพลังนี้ใช่ไหมล่ะ พลังดิบนี่แหละที่หลุดจากความควบคุมได้ง่ายมาก\nใคร ๆ ก็เลยพากันอยู่ห่าง... ซึ่งเข้าทางฉันพอดีเลย! ฮ่าฮ่าฮ่าฮ่า!",
  str_voice_1500181_4 = "กำเนิดดั่งดวงอาทิตย์ มรณะราวกับพายุ! สั่นสะท้านเบื้องหน้าดวงอาทิตย์ที่หลอมละลายทุกสิ่ง!",
  str_voice_1500181_5 = "ว่ามาเลย จะไปที่ไหนต่อ ฉันอยากจับไอ้พวกเวรนั่นมาเผาให้มันไหม้เกรียมเต็มทนแล้ว!",
  str_voice_1500181_6 = "เจ้าแห่งพลัง อย่าตกเป็นทาสมัน ไม่ว่ายังไง ฉันคือผู้กำกับชะตาชีวิตตัวเอง",
  str_voice_1500181_7 = "ตัวตลกพวกนั้นของเธอนี่น่าสนใจดีเหมือนกันนะ พวกเขาทำให้ฉันนึกถึงเจ้าตัวตลกซินซาเลย",
  str_voice_1500181_8 = "น่าสนใจแฮะ... ฉันมองเห็นไฟที่ลุกโชนตลอดเวลาในดวงตาของเธอเหมือนกัน บางทีไฟของเธออาจสุ่มเสี่ยงกว่าของฉันก็ได้...",
  str_voice_1500181_9 = "ดินแดนที่จมน้ำแห่งนี้จำเป็นต้องมีดวงอาทิตย์ดวงใหม่ แต่มันจะไม่ใช่ฉันหรอก บางทีอาจเป็นเธอก็ได้...",
  str_voice_1500181_10 = "ฉันเบื่อ! ใครเอากีตาร์ฉันไป แบบนี้เตรียมตัวถูกเผาได้เลย...",
  str_voice_1500181_11 = "เวทีกลางเหรอ ฮึ่มมม ความเด่นมันต้องเป็นของฉันตลอดสิ",
  str_voice_1500181_12 = "ผู้ทำลายอย่างฉัน จะเป็นผู้ปกป้องได้ด้วยเหรอ",
  str_voice_1500181_13 = "ได้เวลาเมทัลแล้ว! มาร็อกกันเลยทุกคน!",
  str_voice_1500181_14 = "อย่ารบกวนเวลาฉันเล่นดนตรีสิ!",
  str_voice_1500181_15 = "ปาร์ตี้ัวันเกิดแบบเมทัลไหมล่ะ",
  str_voice_1500181_16 = "โอ้ นี่เธอคิดว่าจะควบคุมฉันได้งั้นเหรอ",
  str_voice_1500181_17 = "หา ฉันนึกว่าเธอเรียบร้อยไปแล้วเสียอีก",
  str_voice_1500181_18 = "เอาจริงเหรอ เธอจะให้ฉันทำแบบนี้เนี่ยนะ",
  str_voice_1500181_19 = "กลางคืนมันเงียบเกินไป ใช้ไม่ได้หรอก! ต้องมีร็อกแอนด์โรลเรียกขวัญกำลังใจกันหน่อย!",
  str_voice_1500181_20 = "แม้ว่าวงนี้จะมีแต่คนแปลกแยก ตัวตลก แล้วก็พวกโง่ แต่ก็มีแค่พวกเขาเท่านั้นที่ยอมรับฉันและดนตรีของฉัน",
  str_voice_1500181_21 = "พวกผู้เฒ่าในลูโมโพลิสก็เหมือนเพลงคลาสสิกของพวกเขานั่นแหละ ทั้งราบเรียบ ทั้งไม่ยืดหยุ่น",
  str_voice_1500181_22 = "เมทัลตลอดกาล!",
  str_voice_1500181_23 = "อิคลิพไซท์ที่ไหม้ดำเป็นหนึ่งในสิ่งล้ำค่าที่สุดในโลกเลย",
  str_voice_1500181_24 = "เจ้าโง่นี่ก็เป็นตัวตลกซะเอง พวกเดียวกันทั้งนั้น",
  str_voice_1500181_25 = "โจนามีรสนิยมด้านการต่อสู้และดนตรีดีนะ ฉันชอบเธอ!",
  str_voice_1500181_26 = "โลกนี้มันน่ารังเกียจก็เพราะมีเมทัลไม่พอนี่แหละ!",
  str_voice_1500181_27 = "ขอโทษนะ ฉันไม่คุยกับคนที่ไม่ชอบเมทัล",
  str_voice_1500181_28 = "มันต้องดีแน่เลยถ้าได้จัดคอนเสิร์ตบนหัวมัน!",
  str_voice_1500181_29 = "เธอใช่ไหม หืมม เธอน่าจะทำอะไรที่น่าสนใจให้ฉันดูได้ เพื่อประโยชน์ของตัวเอง อย่าทำให้ฉันผิดหวังนะ ไม่งั้น...",
  str_voice_1500181_30 = "ต้องการ... พลัง... เพิ่มอีก...",
  str_voice_1500181_31 = "ถอยไป ถ้าเธออยากมีชีวิตรอด",
  str_voice_1500181_32 = "พายุสีทอง สวยไหมล่ะ",
  str_voice_1500181_33 = "ดวงอาทิตย์ดวงสุดท้ายจะไม่มีวันตกดิน!",
  str_voice_1500181_34 = "ฉันทำอะไรก็ได้แล้วเหรอตอนนี้",
  str_voice_1500181_35 = "เธอกล้าจ้องแสงสว่างที่ทำให้ตาพร่ามัวนี่ไหมล่ะ!",
  str_voice_1500181_36 = "เธอแน่ใจเหรอว่าต้องไปไกลขนาดนั้น",
  str_voice_1500181_37 = "ใช้เวลาแป๊บเดียวเท่านั้นแหละ!",
  str_voice_1500181_38 = "มอดไหม้ในแสงแดดที่แผดเผา!",
  str_voice_1500181_39 = "เธอต้องตายตรงนี้แหละ!",
  str_voice_1500181_40 = "พายุ! สุริยะ!",
  str_voice_1500181_41 = "ขอโทษที่ให้รอนะทุกคน!",
  str_voice_1500181_42 = "ยัง ยังร็อกไม่พอ! เอาอีก เอาอีก!",
  str_voice_1500181_43 = "ฮ่า! เข้าท่าแฮะ... ศัตรูที่แข็งแกร่ง",
  str_voice_1500181_44 = "ฉันอยากทำลายเปียโนนั่้นเป็นบ้าเลย",
  str_voice_1500181_45 = "แม้จะพยายามเอาใจฉันก็ไม่มีประโยชน์หรอก",
  str_voice_1500181_46 = "เธอคือ... แฟนหมายเลขหนึ่งของฉันเหรอ",
  str_voice_1500181_47 = "เยี่ยม สนใจตั๋วคอนเสิร์ต VIP ไหม",
  str_voice_1500181_48 = "พรสวรรค์นี้พิสูจน์ว่าเรามีอะไรที่เหมือนกันเยอะมาก!",
  str_voice_1500181_49 = "คนเขาวิจารณ์ดนตรีของฉันแล้วยังไงล่ะ ผู้เฒ่าผู้แก่กับกฎเกณฑ์ของพวกเขามันตายไปหมดแล้ว ฉันไม่เปลืองลมหายใจไปกับพวกนั้นหรอก",
  str_voice_1500181_50 = "ฉันรู้ว่าซินซาคาดหวังอะไรจากฉัน ไม่ใช่แค่ไฟป่าลามป่าที่ทำให้ศัตรูมอดไหม้ แต่เป็นแสงนำทางด้วยเช่นกัน ฉันไม่รู้และไม่สนใจหรอกว่า ฉันจะทำได้ตามที่เขาคาดหวังรึเปล่า",
  str_voice_1500181_51 = "ความแข็งแกร่งที่แท้จริงคือสิ่งเดียวที่สามารถทำให้ได้รับความเคารพนับถือจากเรดีเซล อย่างไรก็ดี เธอได้แสดงให้ฉันเห็นถึงความเป็นไปได้อีกอย่างหนึ่ง วันหนึ่งฉันอาจทำได้อย่างที่พี่ชายคาดหวังในตัวฉันก็ได้",
  str_voice_1500181_52 = "Alchemy! Stars!",
  str_voice_1500181_53 = "เธออยู่ไหนเนี่ย?",
  str_voice_1500181_54 = "ยังนอนอยู่อีกเหรอ ได้เวลาลุกแล้ว!",
  str_voice_1500181_55 = "ทำไรอยู่เนี่ย ถ้าว่างก็มานี่แป๊บนึงสิ",
  str_voice_1500181_56 = "การแสดงจะเริ่มแล้ว ล้างหน้าล้างตาซะ!",
  str_voice_1500181_57 = "พายุลูกใหม่กำลังมา!",
  str_voice_1500701_1 = "สู้เพื่อไปอะไรน่ะเหรอ ช่างเป็นคำถามที่งี่เง่าจริง ๆ... ฉันก็ต่อสู้เพื่อตัวเองไงล่ะ คิดว่าสู้เพื่อผลไม้สีทองที่ไม่มีอยู่ในสวนรึไง",
  str_voice_1500701_2 = "ฉันไม่ต้องการอาวุธ ฉันต้องการแค่ปีกกับกรงเล็บของฉันเท่านั้น ขอให้เปลวไฟแห่งเส้นทางนองเลือดของฉันจงเผาผลาญทุกสิ่ง หรือไม่ก็เดินหน้าและทำลายทุกสิ่งด้วยตัวฉันเอง",
  str_voice_1500701_3 = "ผู้ที่ควรแบกรับความเดือดดาลของมังกรก็ควรรับไป เหมือนกับผู้ที่ต้องทนทุกข์ก็ย่อมได้รับความทุกข์ไป นี่ไม่ใช่ข้ออ้างที่จะรบกวนเจ้าแห่งเงา",
  str_voice_1500701_4 = "การพิพากษาเหรอ เสียงของพวกเขานี่แหละที่หนวกหูเกินไป พวกเขาอยากจุดไฟโลหิตของฉันให้เดือด เพราะหวังให้ฉันทำลายทุกสิ่ง แต่ขอโทษที ฉันไม่ทำหรอก",
  str_voice_1500701_5 = "อย่าเข้าใจฉันผิดนะ ความเกลียดชังที่ไหลวนอยู่ในหัวใจฉันไม่เกี่ยวข้องอะไรกับความเกลียดชังที่ฉันอยากระบายออกมา เพราะยังไง ยิ่งเราแข็งแกร่งขึ้นเท่าไหร่ เราก็จะตามืดบอดมากขึ้นเท่านั้น",
  str_voice_1500701_6 = "ความมืดมิดและโลหิตไม่ใช่อะไรนอกจากภาพลวงตา เพราะทั้งความเกลียดชังและความรักต่างก็แหลกเป็นผุยผง และมังกรที่กลับมาก็ได้ตกหลุมพรางนั้น",
  str_voice_1500701_7 = "สิ่งเดียวที่ไหลเวียนอยู่ในสายเลือดของมังกรคือความเกลียดชัง แต่ฉันตัดสินใจตามอารมณ์ของตัวเองเสมอมา เธอจะเข้าใจในอีกไม่ช้า",
  str_voice_1500701_8 = "เธออยากรู้ไหมว่าฉันปิดตาข้างขวาเอาไว้ทำไม บางทีฉันน่าจะถอดผ้าปิดตานี้ออกให้เธอดูนะว่า มันรู้สึกยังไงที่อัดแน่นไปด้วยความเกลียดชัง",
  str_voice_1500701_9 = "น่ารักนะเนี่ย ไม่ต้องคิดมากเรื่องจะทำอะไรให้ฉันหรอก แค่ยอมเชื่อฟังฉันแต่โดยดี... หรือไม่ก็มาเถียงกับฉันแบบไม่จบไม่สิ้น",
  str_voice_1500701_10 = "มังกรไม่เคยหลับ เวลาที่เธอปิดตา เธอจะมอบพลังให้ผู้อื่นประหารเธอ",
  str_voice_1500701_11 = "เด็กไม่รู้หัวนอนปลายเท้าแบบเธออยากพิชิตใจฉันเหรอ งั้นก็พิสูจน์เลยว่าฉันคิดผิด ตอนนี้เลย",
  str_voice_1500701_12 = "ให้คนที่โง่เขลาแบกรับภาระแห่งโชคชะตาและคำสาป อืมม ฟังดูน่าสนใจไม่เบาเลยนะ",
  str_voice_1500701_13 = "ที่สุดแล้วเราทุกคนจะต้องถูกความโง่เขลาของเราเองกลืนกิน จนกว่าวันนั้นจะมาถึง ก็ต้องดิ้นรน ดิ้นรนอย่างที่เราควรทำ",
  str_voice_1500701_14 = "อะไรรึ ฉันบังเอิญอารมณ์ดีอยู่เสียด้วย... ไม่สิ เธอควรพยายามทำให้ฉันมีความสุขมากขึ้น",
  str_voice_1500701_15 = "เธอคาดหวังอะไรล่ะ สุขสันต์วันเกิดเหรอ ...น่ารักดีแต่ทำไมปัญหาเยอะขนาดนี้",
  str_voice_1500701_16 = "อ้อ ฉันรู้แล้ว มีเด็กอยู่ที่นี่",
  str_voice_1500701_17 = "เฮ้ เด็กน้อยผู้น่ารัก มาจับมือกับฉันสิ การดิ้นรนของเธอจะเป็นการทักทายที่ดีนะ ว่าไหม",
  str_voice_1500701_18 = "ดูเธอจะกลับมาอยู่ข้างฉันตลอดเลย... แม้ว่าจะน่าเสียดายที่ฉันไม่ใช่คนพิเศษ",
  str_voice_1500701_19 = "ชั่วโมงนี้ไม่ค่อยมีคนน่าสงสารตื่นหรอกนะ... ไปอยู่เป็นเพื่อนเด็กน้อยคนนั้นไป ซันสโตน",
  str_voice_1500701_20 = "ตัวเลือกที่ดีที่สุดสำหรับฉันคือกลับไปที่อัมบราตันกับเจ้าแห่งเงา แล้วนั่นก็คือสิ่งที่ฉันทำ",
  str_voice_1500701_21 = "จากหุ่นเชิดของรัตติกาลสีขาวสู่หุ่นเชิดของอิลลูมินา... ไม่นะ ฉันคิดว่าตำแหน่งที่นั่นหรูหรามากกว่า",
  str_voice_1500701_22 = "มังกรเฝ้าดูเธออยู่นะ",
  str_voice_1500701_23 = "บางครั้งฉันคิดนะว่าคงไม่เลวที่จะรับบทบาทแห่งความมืดมิดและหันมาเป็นศัตรูกับเธอ",
  str_voice_1500701_24 = "เขาคือบุคคลพิเศษที่ควรค่าต่อความเคารพนับถือ นั่นคือสาเหตุที่ฉันจะทำตามความคาดหวังของเขาที่มีต่อตัวฉันให้ลุล่วง",
  str_voice_1500701_25 = "นึกภาพออกไหมว่าเธอมีสายเลือดเดียวกันกับฉัน เธอไม่รู้ด้วยซ้ำว่าฉันมีตัวตนอยู่",
  str_voice_1500701_26 = "มีอะไรเย้ายวนใจไปกว่าการต่อต้านและการดิ้นรนของคนโง่อีกไหม",
  str_voice_1500701_27 = "ฉันรู้สึกคลื่นไส้เมื่อใดก็ตามที่นึกถึงน้องสาวที่น่าขันและโง่เขลา ผู้ร้ายที่เป็นต้นเหตุของทุกสิ่ง",
  str_voice_1500701_28 = "โทษที เมื่อกี้ฉันรู้สึกถึงความผูกพันอะไรสักอย่างกับมังกรขาวตัวนี้ขึ้นมา แต่ตอนนี้ฉันแค่อยากสับมันให้เป็นชิ้น ๆ",
  str_voice_1500701_29 = "สิ่งเดียวที่เธอจำเป็นต้องรู้ก็คือภาพที่สะท้อนในดวงตาของฉัน คือบ้านเกิดที่ปกคลุมด้วยหมอกมรณะ ส่วนชื่อของฉัน เธอจะรู้เองเมื่อเวลาผ่านไป...",
  str_voice_1500701_30 = "บริสุทธิ์ ด้วยความปรารถนาล้วน ๆ",
  str_voice_1500701_31 = "สายเลือดที่สาบสูญไม่มีความหมายอะไรกับฉัน",
  str_voice_1500701_32 = "เพลิงมังกรเหรอ เมื่อกี้แค่ถอนหายใจเฉย ๆ",
  str_voice_1500701_33 = "ในที่สุดแล้ว บ้านเกิดก็จะกลายเป็นทุ่งโล่งที่มีแต่เถ้าถ่าน",
  str_voice_1500701_34 = "เผชิญกับความเกลียดชังของเธอ",
  str_voice_1500701_35 = "พอได้แล้ว",
  str_voice_1500701_36 = "อย่าได้ยั้ง ลุยเลย",
  str_voice_1500701_37 = "ส่งพวกมันลงนรกเลย ซันสโตน",
  str_voice_1500701_38 = "งั้นก็ได้ ขยี้ทุกสิ่งให้เป็นผุยผง!",
  str_voice_1500701_39 = "คร่ำครวญ!",
  str_voice_1500701_40 = "อันตรธาน",
  str_voice_1500701_41 = "ฉันได้ก้าวออกมาจากความเกลียดชังแล้ว แต่ฉันคิดถึงมันมากเลย",
  str_voice_1500701_42 = "ถ้าชนะแล้วยังไงต่อ",
  str_voice_1500701_43 = "แปลว่าจะพ่นวาจาแห่งการล้างแค้นออกมาแล้วใช่ไหม",
  str_voice_1500701_44 = "ดีมาก มันช่วยปลอยโยนจิตใจฉันได้... แต่ว่ามันก็ยังไม่พอ",
  str_voice_1500701_45 = "อะไรกันเนี่ย ...ขนาดซันสโตนยังไม่อยากสัมผัสเลย",
  str_voice_1500701_46 = "สีหน้าลังเลของเธอยังจะน่ารักกว่าของขวัญนี้เสียอีก",
  str_voice_1500701_47 = "ซันสโตน เอาของขวัญของเด็กคนนี้ไปให้พ้น",
  str_voice_1500701_48 = "สีหน้าแบบนี้ของเธอก็เพียงพอแล้วที่จะทำให้ฉันชอบ",
  str_voice_1500701_49 = "แค่จ้องหน้าเธอสองครั้ง ก็ทำให้ฉันคิดแล้วนะว่าฉันควรปรากฏตัวต่อหน้าเธอและบอกไปเลยไหมว่าเราไม่ได้แสวงหาอะไรนอกจากเรื่องตลก",
  str_voice_1500701_50 = "การแก้แค้นกับผู้บริสุทธิ์ไม่มีผลใด ๆ ต่อการกำจัดความเกลียดชังนี้ที่กระจายอยู่ในแก่นแท้ของโลหิตของฉัน แต่ผู้ที่ฉันหวังจะล้างแค้นโดยตรงไม่มีตัวตนอยู่อีกต่อไปแล้ว",
  str_voice_1500701_51 = "โลหิต ความทรงจำ กระแสความแค้นที่ไหลวน และการสั่งสมของประวัติศาสตร์ ทุกอย่างเกี่ยวพันกันอยู่ในตัวตนของมังกร และมันก็น่ารังเกียจเป็นที่สุด",
  str_voice_1500701_52 = "Alchemy และ Stars",
  str_voice_1500701_53 = "เด็กน้อย",
  str_voice_1500701_54 = "เช้าแล้ว เข้ามาทักท้ายฉันสิ",
  str_voice_1500701_55 = "ก่อนอื่นบอกฉันก่อนว่าเธออยู่ไหน",
  str_voice_1500701_56 = "มาอยู่เป็นเพื่อนซันสโตนนะ",
  str_voice_1500701_57 = "นี่ปีใหม่แล้วเหรอ มาสิ ทำท่าดีอกดีใจให้ดูหน่อย",
  str_voice_1500761_1 = "ไม่มีมนุษย์คนไหนที่พิเศษกว่าใคร เพราะทุกคนล้วนมีอดีตและความลับ ฉันชอบที่ทุกคนเหมือนกันหมด ส่วนออโรเรียน... มันคืออะไรกันแน่",
  str_voice_1500761_2 = "คำโกหกกับความจริงไม่ค่อยแตกต่างกันเท่าไหร่หรอก มันไม่มีขอบเขตด้วยซ้ำ เวลาฉันพูดว่า \"ประโยคนี้เป็นคำโกหก\" มันไม่มีความหมายเลยไม่ว่าจะจริงหรือเท็จ",
  str_voice_1500761_3 = "ถ้าเธออยากรู้เรื่องทะเลลึกอันลึกลับ ก็แค่ปีนขึ้นไปบนลูโมโพลิสและนอนในห้องโถงเพื่อไปยังที่แห่งนั้นสิ",
  str_voice_1500761_4 = "กะลาสีผู้กล้า อย่าได้คิดว่าหนวดพวกนี้คือเกาะเชียวนะ ถ้าพวกเธอดูไม่ออกว่าอันไหนจริงอันไหนเท็จ มันจะอันตรายมากทีเดียว",
  str_voice_1500761_5 = "คอยระวังมอนสเตอร์ที่อยู่ตามทะเลลึกเอาไว้ให้ดี พวกมันจะขึ้นมาที่ผิวน้ำและโจมตีเรือที่แล่นผ่านมา เพื่อจะดักจับกะลาสีคนที่มันชอบแค่สองสามคนเท่านั้นเอง",
  str_voice_1500761_6 = "นักสังเกตการณ์พเนจรอย่างฉันพยายามไม่เข้าไปข้องเกี่ยวด้วยเสมอ แต่ฉันมักพบว่าตัวเองช้าไปหนึ่งก้าวทุกทีเวลาที่ฉันอยากแทรกแซง... ดังนั้นฉันจำเป็นต้องแข็งแกร่งกว่านี้",
  str_voice_1500761_7 = "มันสะดวกดีไหมล่ะที่สามารถบอกได้ทันทีว่าใครพูดความจริงหรือเปล่า ถ้าเธอบอกได้ว่าอันไหนข้อมูลจริง... เธอคงไม่ \"ปฏิเสธ\" ใช่ไหม",
  str_voice_1500761_8 = "ฉันสามารถซุกซ่อนความจริงไว้ในคำโกหกได้เสมอ และฉันหวังตลอดว่าคนที่ฟังฉันอยู่จะบอกได้ว่าที่จริงแล้วฉันคิดอะไรอยู่ เธอเชื่อฉันไหมล่ะ คือเธอดูค่อนข้างใสซื่อน่ะ",
  str_voice_1500761_9 = "ไม่ต้องกังวลและอย่าได้กลัวไป ไม่ว่ายังไง มอนสเตอร์ที่มีหนวดน่ารัก ๆ แบบนั้นก็หวังว่ากะลาสีผู้กล้าทุกคนจะได้เห็นดวงอาทิตย์ขึ้นเหนือผืนน้ำทะเล",
  str_voice_1500761_10 = "วันนี้จะมีกิจกรรมอย่างหนึ่งจัดขึ้นที่อัมบราตัน และฉันจะเสียดายมากเลยถ้าเธอไม่ไป... อย่าบอกนะว่าเธอคิดจะไปจริง ๆ",
  str_voice_1500761_11 = "ความรู้สึกนี้คืออะไรนะ ดูเหมือนฉันจะสัมผัสได้ถึงความไว้ใจของเธอ ฉันรู้สึกได้เพราะความรักเหรอกะลาสีผู้กล้า",
  str_voice_1500761_12 = "เพียงแค่แตะที่หนวดพวกนั้นก็อันตรายแล้ว เหมือนกับการที่เธอไปแตะต้องมังกรของลีโอนา เธอก็จะได้รับบาดเจ็บ",
  str_voice_1500761_13 = "วันหนึ่งที่นี่ก็จะจมน้ำไปเหมือนกัน เธอควรหนีไปกับฉันก่อนที่มันจะเกิดขึ้นนะ",
  str_voice_1500761_14 = "ฉันต้องไปจากที่นี่ ไม่งั้นจะมีผู้หนึ่งที่น่ากลัวไล่ตามฉันมาทัน ไม่ต้องรอฉันนะ ลาก่อน",
  str_voice_1500761_15 = "วันนี้คือวันที่ทะเลลึกจะให้สิ่งที่ทุกคนวาดหวัง คำขอของฉันคือการได้อยู่เคียงข้างเธอ ส่วนเธอล่ะ",
  str_voice_1500761_16 = "ยินดีต้อนรับกลับมานะ กะลาสีผู้กล้า ทะเลลึกได้ทำนายการมาถึงของเธอไว้แล้ว",
  str_voice_1500761_17 = "ฉันดีใจมากที่เจอเธอ แต่เธอมาเร็วเกินไป ฉันว่าจะแอบหนีไปตอนที่เธอไม่อยู่น่ะ",
  str_voice_1500761_18 = "แสงที่กะพริบระยิบระยับกำลังจะหายไป แล้วเธอล่ะ เธอยังอยากอยู่ที่นี่กับฉันไหม",
  str_voice_1500761_19 = "ป่านนี้แล้วเธอยังอยู่อีก! เธอยังอยากไปทะเลลึกกับฉันไหม ฉันรู้แล้วว่าตอนนี้...",
  str_voice_1500761_20 = "ฉันพบความบันเทิงในหลายรูปแบบมากขึ้นด้วยซ้ำในสภาพแวดล้อมที่มีความวุ่นวาย ยังไม่นับว่ามีมนุษย์ที่ฉันรักอยู่ที่นั่นเยอะแยะเลยด้วยนะ",
  str_voice_1500761_21 = "ความเสแสร้งมันเป็นศิลปะ เกาะสีขาวเล็ก ๆ นั่นก็ใช้อยู่ แต่ก็ไม่รู้อะไรเกี่ยวกับเรื่องนี้เลย",
  str_voice_1500761_22 = "หนวดพวกนั้นรอเธออยู่",
  str_voice_1500761_23 = "แม้แต่ทะเลลึกก็มีสิ่งที่ไร้ความหมายราวกับฝุ่นผง... อย่างเช่นอิคลิพไซท์ไงล่ะ",
  str_voice_1500761_24 = "คนเลี้ยงหมาไว้ใจความภักดีของสปีชีส์อื่นได้ยังไงนะ เพราะหมากระดิกหางได้งั้นเหรอ",
  str_voice_1500761_25 = "ทำไมมังกรสายโหดตัวนั้นถึงได้ดูขี้เกียจตลอดเวลา น่าคิดป่ะ",
  str_voice_1500761_26 = "วันที่ฝนตกฟ้าครึ้ม หนังสือโบราณ และเรื่องราวจาก \"การเดินทางของนักผจญภัย\" ทายสิว่าฉันชอบเล่มไหน",
  str_voice_1500761_27 = "ฉันไม่ชอบอะไรที่น่าเบื่อ รวมถึงคำโกหก... ฉันก็เลยพูดความจริงไป",
  str_voice_1500761_28 = "นี่เรียกว่าโคลอสซัสเหรอ มอนสเตอร์น่ะพบได้ทั่วไปในทะเลลึก ดังนั้นมันอาจจะมาจากทะเลลึกก็ได้",
  str_voice_1500761_29 = "ยินดีที่ได้รู้จักนะ ฉันเป็นนักต้มตุ๋น แล้วก็... เรียกฉันว่าเคลเคนแล้วกัน กรุณาอย่าเชื่อคำพูดของฉันนะ รวมถึงสิ่งที่ฉันพูดอยู่นี้ด้วย อย่าเชื่ออะไรที่ฉันพูดทั้งนั้น",
  str_voice_1500761_30 = "ฉันไม่รู้สึกถึงพัฒนาการเลย",
  str_voice_1500761_31 = "คำโกหกของฉันพัฒนาขึ้นแล้วนะ น่าเสียดายที่นี่ก็เป็นคำโกหกเหมือนกัน",
  str_voice_1500761_32 = "เมื่อหมอกรวมตัวกลายเป็นน้ำ นิยายก็กลายเป็นความจริง",
  str_voice_1500761_33 = "ประตูเงียบเปิดออก เผยให้เห็นทะเลลึก",
  str_voice_1500761_34 = "เธออยากจะโกหกใครเหรอ",
  str_voice_1500761_35 = "หมอกมันหนามากพออยู่แล้ว",
  str_voice_1500761_36 = "ที่เธอเห็นคือความจริงเหรอ",
  str_voice_1500761_37 = "ตำนานโบราณจะตื่นขึ้นใหม่ ณ บัดนี้!",
  str_voice_1500761_38 = "ขอให้เธอได้เห็นทะเลลึกในสักวัน!",
  str_voice_1500761_39 = "จุ๊ ๆ",
  str_voice_1500761_40 = "มันสายไปแล้ว",
  str_voice_1500761_41 = "ดูเหมือนเธอจะ... ไว้ใจฉันนะ เซอร์ไพรส์มากเลย",
  str_voice_1500761_42 = "ขอโทษจริง ๆ เราล้มเหลว",
  str_voice_1500761_43 = "นี่ฉันต้องรับผิดชอบกับคำพูดของเธอด้วยเหรอ...",
  str_voice_1500761_44 = "ฉันดีใจจริง ๆ นะที่ได้เจอเธอ ฉันพูดจากใจเลยนะแน่นอน",
  str_voice_1500761_45 = "เธอก็ควรมอบตัวเองให้ฉัน",
  str_voice_1500761_46 = "ถ้าฉันบอกว่าไม่ชอบ ก็คงเป็นการโกหก",
  str_voice_1500761_47 = "ขอบใจนะ ฉันจะทะนุถนอมเธอ",
  str_voice_1500761_48 = "เธอนี่ช่าง...",
  str_voice_1500761_49 = "ในอัมบราตัน หนวดพวกนี้จะปรากฏออกมาเองเวลาฝนตก ตราบใดที่เสื้อคลุมของเธอเปียกและเปิดออกที่มุมกว้าง 50 องศาหรือมากกว่านั้น มันก็จะมาปรากฏข้าง ๆ เธอ",
  str_voice_1500761_50 = "มอนสเตอร์ที่กล่าวถึงในบันทึกโบราณได้รับความรู้สึกของมนุษย์มา แต่มันเกิดเป็นบ้าไปหลังจากที่ขึ้นฝั่ง เพราะมันไม่รู้ว่าจะมีชีวิตรอดบนแผ่นดินได้ยังไง",
  str_voice_1500761_51 = "เมื่อเร็กเกอร์อาละวาดไปทั่วดินแดน มอนสเตอร์ที่ถูกหนวดจับได้ต้องการหลีกเลี่ยงวิกฤติ แต่ก็ต้องพบว่าพวกมันไม่มีที่ให้ไป ในที่สุดพวกมันทั้งหมดก็ถูกเจ้าแห่งเงากลืนกิน",
  str_voice_1500761_52 = "Alchemy Stars",
  str_voice_1500761_53 = "กะลาสีผู้น่ารัก",
  str_voice_1500761_54 = "นี่มันสายแล้วไม่ใช่เหรอ",
  str_voice_1500761_55 = "อรุณสวัสดิ์ เธอน่าจะตื่นได้แล้วนะ",
  str_voice_1500761_56 = "พระอาทิตย์เพิ่งขึ้นเอง",
  str_voice_1500761_57 = "เราจะต้อนรับปีใหม่กันพรุ่งนี้",
  str_voice_1500781_1 = "ได้โปรด... รักษาระยะห่างจากฉันด้วย... น่าจะดีกว่า เพราะฉันกลัวจะเผลอซัดเธอล้มน่ะ... โทษที",
  str_voice_1500781_2 = "ขอโทษที ฉันคิดว่าเธอควรจะดูแลตัวเองได้... เรื่องนั้นฉันไม่ค่อยเก่ง... และคงช่วยอะไรไม่ได้เลย",
  str_voice_1500781_3 = "เธอ... เธอได้เจอเดย์นาบ้างรึเปล่าช่วงนี้ หล่อนทั้งอบอุ่นและเป็นมิตร ดูแลคนอื่นอยู่เสมอเลย... ไม่มีอะไรหรอก ฉันแค่อยากให้แน่ใจ",
  str_voice_1500781_4 = "ไม่ว่าฉันจะกลายเป็นอะไร ฉันก็ไม่สนใจหรอกว่าคนอื่นจะคิดยังไงกับฉัน... มันจะไม่สำคัญเลยตราบใดที่พวกนั้นอยู่ห่างจากฉัน... เอ่อ ทำไมฉันดูเหมือนเดิมเลยละ",
  str_voice_1500781_5 = "ฉันไม่ใช่เด็กที่อ่อนแอและไร้พลังเหมือนเมื่อก่อนอีกต่อไป ตอนนี้ฉัน... เธอควรอยู่ให้ห่างจากฉันจะดีกว่านะ... อย่าเข้ามาใกล้เกิน",
  str_voice_1500781_6 = "ฉัน... ฉันรู้ว่า ฉันต้องพึ่งพาความแข็งแกร่งของตัวเองเพื่อแก้ไขความเกลียดชังของฉันในสักวัน... หรือไม่ก็ตอนนี้เลย",
  str_voice_1500781_7 = "ขอโทษนะ... ตอนแรกฉันคิดว่าเธอน่ะหยาบคายเหมือนผู้คนข้างนอก... แต่ที่จริงแล้วเธอดีกว่าพวกเขามากเลย... อย่างน้อยเธอก็รู้จักรักษาระยะห่าง",
  str_voice_1500781_8 = "คือ... ฉันคิดว่าเธอคือบุคคลที่ทรงพลังมาก และฉันรู้ว่าเธอจะยิ่งทรงพลังมากกว่านี้อีก ดังนั้น...\nเธออยากไปหาเดย์นาแล้วเรียนรู้จากนางไหมล่ะ?",
  str_voice_1500781_9 = "เราเหมือนกันในหลายด้านเลยนะ... ฉันคิดว่าเดย์นาก็ต้องเห็นด้วย ว่าแต่... เธอคิดเรื่องที่จะมายังอัมบราตันรึยังล่ะ",
  str_voice_1500781_10 = "...เธอแทบไม่ได้พักผ่อนเลย... ฉันจะไม่ยอมให้ใครมารบกวนเธอ... นอกจากจะเป็นเดย์นา",
  str_voice_1500781_11 = "แล้วเธอจะให้ฉันคอยดูไหมล่ะ ฉันเข้าใจนะ สบายใจได้ ฉันเคยทำมาก่อนแล้ว",
  str_voice_1500781_12 = "ขอโทษที ฉันไม่รู้ว่าจะรับมือกับอาวุธที่แหลมคมแบบนี้ยังไง แล้วฉันก็ไม่สามารถ... ลงมือทำได้เวลาที่ฉันต้องเผชิญหน้ากับใคร",
  str_voice_1500781_13 = "... ถ้าฉันมีพลังละก็... ฉันจะสามารถยุติทุกอย่างได้",
  str_voice_1500781_14 = "เธอว่างไหม ไม่นานมากหรอก... ที่จริงแล้วฉันแค่อยากถามเธอว่าเดย์นาอยู่ที่ไหน...",
  str_voice_1500781_15 = "เอ่อ ฉันขอให้เธอมีความสุขในวันเกิดนะ... ขอโทษด้วยที่ฉันยังไม่ได้หาของขวัญมาให้เธอเลย... และฉันก็บังเอิญพังร้านไปแล้ว",
  str_voice_1500781_16 = "ฉันทำงานล่วงเวลาที่กิลด์ด้วยนะ... บอกล่วงหน้าแล้วกันถ้าเธอจะให้ช่วยอะไร",
  str_voice_1500781_17 = "... เร็วเกินไปที่จะควบคุมมัน... ฉันแนะนำให้เราอย่าอยู่ใกล้กัน",
  str_voice_1500781_18 = "ฉันเสร็จธุระเรื่องกิลด์แล้วนะ มีร้านอะไรที่เธออยากไปไหม... เดย์นากับฉันจะไปเป็นเพื่อน",
  str_voice_1500781_19 = "ฉันว่าคืนนี้ราตรีสวัสดิ์ก่อนดีกว่า... เหมือนที่ฉันได้ยินบ่อย ๆ ไง",
  str_voice_1500781_20 = "แม้แต่ในสถานที่แบบนั้น... เรากลับค่อย ๆ พบสถานที่ที่เรียกว่าเป็นของเราเอง",
  str_voice_1500781_21 = "สภาพแวดล้อมที่อยู่อาศัยก็ดีกว่าในลูโมโพลิสนะ... แต่ทั้งฉันและเดย์นาต่างก็ไม่อยากกลับไปที่นั่นอีกครั้งหรอก",
  str_voice_1500781_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1500781_23 = "ฉันจะฆ่าอิคลิพไซท์ที่ฆ่าพ่อกับแม่ของฉันด้วยตัวเอง",
  str_voice_1500781_24 = "เดย์นาก็เหมือนครอบครัวของฉัน... ฉันไม่ได้เรียกเธอว่าพี่จริง ๆ หรอก แต่ว่า... เธอสำคัญกับฉันมากกว่าพี่แท้ ๆ เสียอีก",
  str_voice_1500781_25 = "ฉันรู้สึกขอบคุณมากที่คุณเชโอลดูแลฉัน แต่ฉันหวังว่าคราวหน้าเธอจะไม่เข้าใกล้ฉันขนาดนั้นอีก... มันอึดอัดนิดหน่อยน่ะ",
  str_voice_1500781_26 = "...สิ่งที่ฉันชอบ... ถ้าฉันจะบอกว่า... บอกว่าฉันชอบเดย์นาได้รึเปล่า?",
  str_voice_1500781_27 = "ฉันไม่ชอบอะไรที่เข้าใกล้ฉันแบบกะทันหัน... และฉันก็เกลียดอิคลิพไซท์",
  str_voice_1500781_28 = "โคลอสซัสนี้... ดูขาวสะอาดมากเลย... เหมือนที่แห่งหนึ่งที่เราเคยอยากไปกัน",
  str_voice_1500781_29 = "ฉันชื่อโรบิน... ขอโทษนะ ช่วยอย่าเข้ามาใกล้ฉันได้ไหม... เพราะนี่เราคือครั้งแรกที่เราเจอกัน ฉันคิดว่าเราควรถอยหลังสองเมตรก่อน แล้วค่อยแนะนำตัวกันอีกทีนะ",
  str_voice_1500781_30 = "ฉันเข้าใกล้... เป้าหมายของฉันรึยัง",
  str_voice_1500781_31 = "อ้อ... พลังเขารวบรวมกันแบบนี้นี่เอง",
  str_voice_1500781_32 = "เดย์นา ฉันแข็งแกร่งขึ้นแล้ว...",
  str_voice_1500781_33 = "ฉันไม่สนใจหรอกนะว่าฉันจะปกคลุมไปด้วยโคลน... ตราบใดที่ฉันได้รับพลังมากขึ้น",
  str_voice_1500781_34 = "ต้องเอาท่อมาด้วย",
  str_voice_1500781_35 = "การวัดสำเร็จเรียบร้อย",
  str_voice_1500781_36 = "ฉันรออีกหน่อยก็ได้",
  str_voice_1500781_37 = "ฉันหยุดไม่ได้... แม้เธอจะร้องขอความเมตตาก็ตาม",
  str_voice_1500781_38 = "นี่เป็นข้อยกเว้น ตั้งใจดูให้ดี!",
  str_voice_1500781_39 = "หลบไป",
  str_voice_1500781_40 = "อย่าเข้ามาใกล้ฉัน!",
  str_voice_1500781_41 = "ฉันต้องต่อสู้เหรอ ... พาเดย์นาไปด้วยดีกว่า",
  str_voice_1500781_42 = "ความรู้สึกแห่งชัยชนะ... ทางที่ดีควรทำตัวให้ชินเข้าไว้",
  str_voice_1500781_43 = "ฉันแพ้... แต่ว่า... ฉันไม่อยากให้เดย์นารู้",
  str_voice_1500781_44 = "ม-มันมองฉันอยู่เหรอ มันเห็นเดย์นารึเปล่า",
  str_voice_1500781_45 = "ไม่เป็นไรจริง ๆ เหรอที่จะรับของขวัญชิ้นนี้...",
  str_voice_1500781_46 = "อะไรกัน!? นี่... เธอรู้เหรอว่าฉันชอบอะไร",
  str_voice_1500781_47 = "ฉันจะรับไว้เงียบ ๆ ล่ะ เงียบ ๆ เลยนะ",
  str_voice_1500781_48 = "นี่มัน... ขอบคุณนะ ขอบคุณจริง ๆ",
  str_voice_1500781_49 = "ในช่วงหลายปีที่ผ่านมา... อาจเป็นเพราะสิ่งต่าง ๆ เป็นเรื่องยากมากจนทำให้ผู้คนไม่แยแส ต่อสู้กัน และเหยียบย่ำกัน",
  str_voice_1500781_50 = "ความหิวโหยและการแบ่งแยกจะไม่หายไปด้วยความไว้ใจที่ไร้เดียงสา เราทุกคนรู้ดี และพึ่งพาความแข็งแกร่งของเราเองเท่านั้นที่จะมีชีวิตอยู่รอด...",
  str_voice_1500781_51 = "เธอได้รับภาระแห่งความเกลียดชังของฉันไปแล้ว... แต่ฉันต้องแก้ไขเรื่องนี้ด้วยตัวเอง ฉันจะให้เธอมาเกี่ยวข้องเรื่องนี้ไม่ได้... เดย์นากับความเกลียดชังช่างไม่เหมาะกันเลย",
  str_voice_1500781_52 = "...Alchemy Stars",
  str_voice_1500781_53 = "อ่ะแฮ่ม ว่าไงนะ...",
  str_voice_1500781_54 = "อรุณสวัสดิ์...",
  str_voice_1500781_55 = "อ่ะแฮ่ม บังเอิญจังเลย...",
  str_voice_1500781_56 = "เธอยังไม่นอนเหรอ",
  str_voice_1500781_57 = "สุขสันต์วันปีใหม่ เธออยากฉลองไหมล่ะ",
  str_voice_1500841_1 = "ฉันจะเล่าเรื่องตลกเกี่ยวกับการไถ่โทษให้ฟัง เวลาเธออยากให้คนอื่นมาตกหน้าผาหรือถูกเนรเทศให้ไปอยู่ในดินแดนรกร้างแทนตัวเอง มันไม่สำคัญหรอกว่ามันต้องเป็นผู้บริสุทธิ์รึเปล่า ขอแค่มีเขาก็พอ",
  str_voice_1500841_2 = "ต้องยกความดีความชอบให้ภรรยาของเขา ชวาตส์ถึงได้ประสบความสำเร็จอยู่ทุกวันนี้... อืม... ถึงแม้ว่าเขาจะดูเหมือนถึงวัยใกล้ลงโลง แต่จริง ๆ แล้วเขาไม่ได้แก่ขนาดนั้น",
  str_voice_1500841_3 = "ปีศาจตนแรกเกิดขึ้นจากคทาที่สามารถเผาปีศาจให้เป็นเถ้าถ่านได้ จึงเป็นความจริงที่ว่ามันควรเป็นผู้เฝ้าประตูนรก",
  str_voice_1500841_4 = "บัลลังก์เก่าแก่นี้ไม่ใช่สิ่งที่ควรยึดครอง แต่เป็นสัญลักษณ์ของความเคารพ มันจะกลายเป็นของใหม่หลังจากถูกเผาด้วยไฟ",
  str_voice_1500841_5 = "ผู้ที่วางแผนลวงทั้งวันจะไม่กล้าทำอะไรบุ่มบ่าม และผู้ที่กดขี่รวมถึงหาผลประโยชน์จากผู้ที่ต่ำต้อยกว่าก็ไม่มีวันถึงจุดสิ้นสุด นั่นก็เพราะว่าพวกมันรู้ว่าแชโดว์คอยเฝ้าดูอยู่นั่นเอง",
  str_voice_1500841_6 = "ตอนฉันกลับมาที่นี่ ตำนานแห่งอัมบราตันได้กลายเป็นเรื่องที่บอกเล่าต่อกันมา ผู้นำและแชโดว์เริ่มเข้าควบคุมดินแดนแห่งนี้ทุกหย่อมหญ้าแล้ว",
  str_voice_1500841_7 = "ความยุติธรรมที่ฉันปกป้องไม่เหมือนกับที่ออกมาจากปากเธอ มันอาจยุ่งเหยิง แต่ก็ไม่สามารถบิดเบือนได้ เธอยังไม่มีความสามารถที่จะเข้าใจมันหรอก",
  str_voice_1500841_8 = "เธอเติบโตขึ้นโดยไม่มีการปกป้องจากพ่อแม่ เหมือนกันกับฉัน แต่วันหนึ่งเธอจะพบว่าการจมอยู่ในโคลนตมมันเกินกว่าจะทานทนได้",
  str_voice_1500841_9 = "เธอทำอะไรได้มากกว่ากันเยอะถ้าเป็นผู้นำทาง\nแต่การเรียนรู้จากประสบการณ์และความเสี่ยงที่ยานจะตกมักมาด้วยกันเสมอ...\nตามฉันมาสิ สำหรับเธอคงง่ายกว่ากันมาก",
  str_voice_1500841_10 = "อย่าดื้อดึงไปเลย ไม่นะ คือจริง ๆ... เธอควรมาหาฉันตอนที่เธอไม่ยุ่ง เราจะได้เล่นหมากรุกกัน แล้วฉันจะเล่าตำนานต่าง ๆ ให้ฟัง",
  str_voice_1500841_11 = "ฉันชินแล้วที่ต้องใช้ชีวิตในเงามืด... ก็ได้ ฉันว่ามันคงไม่จำเป็นแล้วแหละ... จะให้ฉันนั่งอยู่นี่น่ะเหรอ",
  str_voice_1500841_12 = "การเคลื่อนที่ทุกครั้งควรทำโดยคำนึงถึงความสมบูรณ์แบบ ดังนั้นเธอต้องคิดอย่างรอบคอบก่อนที่จะลงมือ",
  str_voice_1500841_13 = "ฉันหวังว่าเธอจะรู้นะว่าอะไรดีสำหรับเธอ แชโดว์ก็มองดูเธออยู่ด้วยเช่นกัน",
  str_voice_1500841_14 = "ฉันเจอปัญหาแน่นอนถ้าพวกนั้นรู้เข้าว่าฉันอยู่ที่นี่...",
  str_voice_1500841_15 = "วันเกิดเธอเหรอ เนื่องจากนี่เป็นวันพิเศษ ไปบ้านฉันสิ แล้วรับไอเทมสักชิ้นสองชิ้นจากคอลเลคชั่นของฉันได้เลย",
  str_voice_1500841_16 = "ยินดีต้อนรับกลับมา เนื่องจากโชคชะตาได้มอบความรับผิดชอบนี้ให้กับเธอ ฉันเชื่อว่าเธอเตรียมพร้อมที่จะลงมือแล้ว",
  str_voice_1500841_17 = "ดีมาก เธอมาได้ถูกเวลาพอดี เหมือนกับที่เงาจะมาถึงก่อนเสมอเลย",
  str_voice_1500841_18 = "ถ้าเธอเหนื่อยก็นั่งพักสักครู่ก่อน แล้วเราค่อยเริ่มกัน",
  str_voice_1500841_19 = "คนหนุ่มสาววันนี้ดูจะชอบตื่นตัวในช่วงเวลานี้กันนะ... อืมม... พวกนี้ซ่อนตัวอยู่ในความมืดเนอะ",
  str_voice_1500841_20 = "เหมือนที่เรารู้นั่นแหละ อัมบราตันมีหน้าที่รับผิดชอบในการดูแลออเดอร์ครึ่งหนึ่งของลูโมโพลิส",
  str_voice_1500841_21 = "บอกพวกคนที่มาจากอิลลูมินาให้เลิกเสียเวลาผูกรถเข็นไว้ด้านหน้าของตัวม้าได้แล้ว",
  str_voice_1500841_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1500841_23 = "พวกนี้คือสิ่งมีชีวิตที่ไม่รู้จักความจริง ดังนั้นเธอไม่จำเป็นต้องแสดงความเมตตาเวลาต่อสู้เพื่อความอยู่รอด",
  str_voice_1500841_24 = "คนที่ดูแก่ ๆ คนนี้ชอบทำอะไรน่ารำคาญในเวลาแปลก ๆ เสมอ อย่างเช่นโกงเวลาเล่นหมากรุกอะไรอย่างนี้",
  str_voice_1500841_25 = "ชายเลือดร้อนคนนั้นควรรู้นะว่าเขาจำเป็นต้องสั่งการให้ได้ก่อนที่จะเปลี่ยนสถานการณ์ได้",
  str_voice_1500841_26 = "ฉันมีตู้เก็บของที่เต็มไปด้วยชิ้นงานชั้นเอกในห้องของฉัน",
  str_voice_1500841_27 = "ผู้ที่ไว้ใจไม่ได้ ผู้ที่ขาดความชอบธรรม และผู้ที่หยาบโลน คนจำพวกนี้ไม่สมควรมีตัวตนอยู่",
  str_voice_1500841_28 = "ฉันได้ยินว่าโคลอสซัสเป็นที่พักพิงรูปแบบหนึ่ง รวมทั้งเป็นเครื่องพิสูจน์ภารกิจบางอย่างอีกด้วย",
  str_voice_1500841_29 = "ละทิ้งความใคร่รู้ของเธอไปก่อน สิ่งเดียวที่เธอต้องรู้ก็คือว่าฉันเป็นวิญญาณแห่งอดีตที่ยังคงหลอกหลอนในอัมบราตันต่อไป และเป็นคนสุดท้ายที่ผู้คนจากลูโมโพลิสอยากจะเผชิญหน้า",
  str_voice_1500841_30 = "ยิ่งฉันแข็งแกร่งขึ้นเท่าไหร่ อะไร ๆ ก็น่าเบื่อขึ้นเท่านั้น",
  str_voice_1500841_31 = "เพื่อแชโดว์ นี่มันล้ำลึกกว่าเดิมอีกนะ",
  str_voice_1500841_32 = "เช่นเดียวกับทุกครั้ง อัมบราตันจะอภัยโทษให้เธอ",
  str_voice_1500841_33 = "ฉันจะกลายเป็นแชโดว์...",
  str_voice_1500841_34 = "มาร่วมมือกันเถอะ",
  str_voice_1500841_35 = "ถ้ามีอะไรต้องแลก แล้วยังไงล่ะ",
  str_voice_1500841_36 = "ทุกสิ่งจะต้องจบสิ้นลง!",
  str_voice_1500841_37 = "ต่อต้านจนกว่าเธอจะถูกลากไปลงหลุม!",
  str_voice_1500841_38 = "ผงาดขึ้นมาให้ได้ก่อนที่จะถูกความมืดมิดกลืนกิน!",
  str_voice_1500841_39 = "สัมผัสความแข็งแกร่งของฉันซะ!",
  str_voice_1500841_40 = "จงก้มหัวให้กับฉัน!",
  str_voice_1500841_41 = "ได้สิ ฉันจะรับคำสั่งนี้",
  str_voice_1500841_42 = "ชัยชนะเป็นของทุกคน",
  str_voice_1500841_43 = "ความพ่ายแพ้ไม่มีค่า ต่างจากการทบทวนตนเอง",
  str_voice_1500841_44 = "เยี่ยมเลย หลายคนสามารถใช้ชีวิตที่นี่ได้ด้วยตัวตนใหม่",
  str_voice_1500841_45 = "ไม่ต้องสนใจหรอก เพราะเธอจะไม่ได้อะไรกลับคืนจากฉันทั้งนั้น",
  str_voice_1500841_46 = "ใช่แล้ว ฉันรู้สึกได้เลยว่านี่มันมีค่ามากแค่ไหน",
  str_voice_1500841_47 = "ถึงแม้ว่าจะไม่จำเป็น แต่ฉันจะพิจารณามอบอะไรสักอย่างให้เธอเป็นการตอบแทน",
  str_voice_1500841_48 = "ฮ่าฮ่า! ฉันจะเก็บไว้อย่างดีในตู้เก็บของของฉันเลย",
  str_voice_1500841_49 = "เงามืดแห่งความวุ่นวายไม่เคยสะท้อนอะไรออกมา มันได้แต่ขยายเครือข่ายไปทั่วอัมบราตันเหมือนกับใยแมงมุม เพื่อคงไว้ซึ่งความเรียบร้อยในอัมบราตัน",
  str_voice_1500841_50 = "ก่อนที่ลูโมโพลิสจะถูกแบ่งแยก ความมืดมิดมีอำนาจควบคุมเมืองนี้อย่างมาก ผู้คนจะไม่สนใจอะไรที่ไม่เกี่ยวข้องกับตนเอง",
  str_voice_1500841_51 = "ตรวจสอบให้แน่ใจว่ามีเงินทุนมากพอ ช่วยเหลือและรับเลี้ยงเด็กยากจนและเด็กกำพร้า และสอนให้พวกเขารู้จักต่อสู้กับโชคชะตาของตัวเอง นี่คือวิธีปลูกฝังความสงบเรียบร้อยแบบใหม่ภายใต้เงามืด",
  str_voice_1500841_52 = "Alchemy Stars",
  str_voice_1500841_53 = "ความรับผิดชอบที่หนึ่ง",
  str_voice_1500841_54 = "จำไว้ว่าต้องลงมืออย่างรวดเร็ว",
  str_voice_1500841_55 = "เธอเตรียมพร้อมเต็มที่รึยัง",
  str_voice_1500841_56 = "เหตุผลที่ความมืดมิดปริศนาซ่อนตัวอยู่ในความสงบเรียบร้อย",
  str_voice_1500841_57 = "ไปฉลองปีใหม่",
  str_voice_1500881_1 = "ฉันไม่สามารถถอดถุงมือนี้ออกได้ เพราะมันอาจทำร้ายใครเข้า... เอ่อ เพราะว่า... มือฉันมีแต่ขนแข็ง ๆ น่ะ",
  str_voice_1500881_2 = "เลิกจ้องฉันซะทีได้ไหม ไม่ใช่ว่าฉันจะเปลี่ยนแปลงไปซะหน่อยถ้าเธอจ้องฉันต่อไปเรื่อย ๆ... ฉันไม่ใช่กิ้งก่าประเภทที่เปลี่ยนลวดลายได้นะ",
  str_voice_1500881_3 = "คนที่เรดีเซล เวรนช์มักรวมตัวกันเพื่อจัดงานเลี้ยง แต่ฉันมักจะอยู่ตามมุมห้อง... จนกว่าฉันจะบังเอิญตื่นเต้นขึ้นมานั่นแหละ",
  str_voice_1500881_4 = "รูปโฉมของฉันมีอะไรผิดปกติงั้นเหรอ ...แต่กิ้งก่าขนปุยทุกตัวในทะเลทรายก็หน้าตาแบบนี้นะ... เอ๋? เธอไม่เคยได้ยินมาก่อนเลยเหรอ",
  str_voice_1500881_5 = "ฉันใช้พลังของกิ้งก่าขนปุยเวลาที่ฉันตื่นเต้นขึ้นมา และเวลาเกิดขึ้นจริง ๆ ฉันจะรู้สึกได้ถึงเลือดที่เดือดพล่าน ทำให้ฉันมีพละกำลังอย่างมาก",
  str_voice_1500881_6 = "เรียกความกล้าหาญของเธอออกมา และอย่าได้กลัวความยากลำบาก! ไม่ว่าฉันจะอยากทำอะไรหรือมองหาอะไร ฉันก็แค่พุ่งเข้าโจมตีและขว้างระเบิดมือ... อ้อ โทษที! บังเอิญฉันตื่นเต้นไปหน่อยน่ะ",
  str_voice_1500881_7 = "ฉันไม่ใช่เด็ก ๆ แล้ว! ...ดังนั้นจึงไม่เป็นไร... ฉันต่อสู้ได้ อีกอย่างฉันก็มีระเบิดเพียบเลยด้วย ฉันขี่มอเตอร์ไซค์ก็ได้ด้วยนะ",
  str_voice_1500881_8 = "เธอไม่มีความสุขเหรอ หืมม... ทำไงดี... อื้ม รู้แล้ว ฉันให้ยืมหางเอาไหมล่ะ ...เอ๋? นี่เธอไม่สนใจจริง ๆ เหรอเนี่ย",
  str_voice_1500881_9 = "ที่จริงแล้วถุงมือแบบนี้ค่อนข้างไม่สะดวกเลยนะ วันนึงถ้าฉันสามารถ... ช่างเถอะ แค่ได้อยู่ข้าง ๆ เธอแบบนี้ก็เพียงพอแล้ว",
  str_voice_1500881_10 = "ฉันเอาระเบิดมือรุ่นปรับปรุงมาให้ดูได้ไหม เดี๋ยวก่อนนะ ฉันจะค่อย ๆ เอาออกมา เพราะว่าถ้าห่วงดันติดถุงมือฉันขึ้นมาละก็ งานงอกแน่",
  str_voice_1500881_11 = "ถ้าฉันบังเอิญทำอะไรเสียหายหลังจากที่ตื่นเต้นขึ้นมา... ฉันก็ขอโทษด้วยนะ ฉันจะชดใช้คืนให้!! เธอรับชำระด้วยระเบิดมือไหม",
  str_voice_1500881_12 = "เฮ้อ... กะแล้วเชียว ฉันล้มเหลวอีกครั้งหนึ่งแล้ว... ถ้าเผื่อว่า... เธอจะรอสักครู่ให้ฉันลองอีกทีได้ไหม ใช้เวลาไม่นานหรอก...",
  str_voice_1500881_13 = "แผลพวกนี้บางส่วนก็ทำตัวเองน่ะ เพราะว่า... หางฉันไม่ยอมเชื่อฟังเลยเวลาฉันอยู่นิ่ง ๆ",
  str_voice_1500881_14 = "ฉันรับมือไม่ค่อยเก่งเวลาอยู่ในที่ที่คนเยอะ ๆ... ฉันจะขี้อายมากถ้ามีคนมองจ้องฉัน...",
  str_voice_1500881_15 = "ฉันได้ตัดสินใจแล้วว่าจะฉลองให้เธอวันนี้! ฉันได้พยายามที่สุดแล้วที่จะทำตัวกล้าหาญ! ขอให้เธอมีคืนวันที่เต็มไปด้วยความสุขนะ!",
  str_voice_1500881_16 = "ยินดีต้อนรับกลับมา! ฉันยืนเฝ้ายามอยู่ที่นี่และไม่ได้ไปไหนเลย",
  str_voice_1500881_17 = "เดี๋ยวนะ! ฉันแปะพลาสเตอร์ก่อน... เธอเอาสักอันไหม มันช่วยป้องกันไม่ให้บาดเจ็บได้นะ",
  str_voice_1500881_18 = "ย-อย่ามองนะ! ฉันยังจัดระเบียบหางอยู่เลย... ว่าแต่ เอ่อ ขนแข็ง ๆ นี่ดูประหลาดไหม?",
  str_voice_1500881_19 = "ฉันมองเห็นได้อย่างชัดเจนในเวลากลางคืน ดังนั้นไม่ต้องกังวล... อ๋อใช่ ที่นี่ไม่ค่อยมืดแฮะ",
  str_voice_1500881_20 = "มันไม่ยากขนาดนั้นที่จะมาเป็นส่วนหนึ่งของเรดีเซล เวรนช์ เธอเพียงแค่ต้อง เอ่อ ต้องรู้วิธีทำตัวให้สนุกสนาน",
  str_voice_1500881_21 = "ฉันไปมาแล้วหลายต่อหลายที่ แต่ฉันได้ยินว่าลูโมโพลิสอยู่บนท้องฟ้า... แล้วคนเขาไปกันยังไงเนี่ย...",
  str_voice_1500881_22 = "ขอให้มีความสุขในขณะที่... ในขณะที่อะไรแล้วนะ",
  str_voice_1500881_23 = "ฉันมองเห็นของสีดำ ๆ ได้อย่างชัดเจน พาฉันไปด้วยสิถ้าเธอกลัว แล้วฉันจะทำให้ดีที่สุด!",
  str_voice_1500881_24 = "ฉันทำมอเตอร์ไซค์พังอีกไม่ได้นะ เพราะฉันเพิ่งซ่อมมาเมื่อไม่นานนี้เอง เจ้าจิ๋วต้องโกรธฉันมากแน่เลย",
  str_voice_1500881_25 = "เพราะฉันตั้งใจว่าจะเข้าร่วมกับเรดีเซล เวรนช์ให้ได้ เจ้านายฉันสัญญากับแม่ของฉันไว้ว่าจะดูแลฉันให้ดี",
  str_voice_1500881_26 = "เอ๋? นี่เธอ... ถามว่าฉันชอบอะไรเหรอ ฉันชอบอะไรที่ดูเท่ ๆ น่ะ",
  str_voice_1500881_27 = "ท-ทำไมถึงมีเนื้อกิ้งก่าแห้งด้วยนะ ... *สะอื้น* ฉันไม่มีทางกินได้แน่นอน...",
  str_voice_1500881_28 = "โคลอสซัสนี่ทรงพลังมากเลย! ฉันจะเป็นเหมือนมันได้ไหมนะถ้าฉันพยายามให้มากขึ้นอีกนิด",
  str_voice_1500881_29 = "ฉ-ฉันชื่อแม็กกี้... เอ่อ แม้จะมีหลายอย่างที่ฉันไม่เก่ง แต่ฉันจะรวบรวมความกล้า... เพื่อเอาชนะให้ได้",
  str_voice_1500881_30 = "ฉันเริ่มตื่นเต้นแล้ว!",
  str_voice_1500881_31 = "หางฉันกระดิกไม่หยุดเลย...",
  str_voice_1500881_32 = "ฉันกลายเป็นกิ้งก่ายักษ์แล้ว!",
  str_voice_1500881_33 = "ฉันอยากจุดระเบิดทุกอย่างเลย!",
  str_voice_1500881_34 = "ฉันจำเป็นต้องรวบรวมความกล้า!",
  str_voice_1500881_35 = "ด้วยพลังแห่งกิ้งก่าขนปุย!",
  str_voice_1500881_36 = "ฉันพร้อมมาตั้งนานแล้ว!",
  str_voice_1500881_37 = "ก็แค่ระเบิดน่า มาเถอะ!",
  str_voice_1500881_38 = "โจมตี! เอาระเบิดให้พวกมันกินเลย!",
  str_voice_1500881_39 = "จุดไฟในโพรง!",
  str_voice_1500881_40 = "ระเบิดให้สิ้นซากเลย!",
  str_voice_1500881_41 = "น่ากลัวมากเลย... แต่เลือดของฉันนี่เดือดพล่านด้วยความตื่นเต้นเลยนะ!",
  str_voice_1500881_42 = "การต่อสู้จบแล้วเหรอ ฉันขอสงบสติอารมณ์ก่อน...",
  str_voice_1500881_43 = "ฉันยังมีความกล้าที่จะจัดอีกรอบ...",
  str_voice_1500881_44 = "ห-หางฉันไม่ได้มีไว้โชว์นะ...! แล้วมันก็ไม่ได้น่ามองอะไรเลยด้วย เอาจริง ๆ",
  str_voice_1500881_45 = "เอิ่มม... ฉ-ฉันไม่เอาได้ไหม",
  str_voice_1500881_46 = "นี่มัน!! นี่มัน... ฉันจะขอบคุณยังไงดีเนี่ย!",
  str_voice_1500881_47 = "ฉันจะรับไว้ อืมม... ขอบใจนะ?",
  str_voice_1500881_48 = "ขอบใจนะ! นี่มันดูเท่และทรงพลังมากเลย!",
  str_voice_1500881_49 = "ทุกคนที่เรดีเซล เวรนช์แต่งตัวกันโหด ๆ ทั้งนั้นเลย ฉันอยากกลมกลืนกับคนอื่น ก็เลย... เปลี่ยนหมดเลยน่ะ ฉันบอกไม่ถูกด้วยซ้ำว่าฉันคิดผิดแค่ไหนที่ทำลงไป...",
  str_voice_1500881_50 = "ระเบิดรุ่นปรับปรุงของฉันไม่ได้ทรงพลังมากหรอกนะ ปกติแล้ว แต่มันจะเพิ่มพลังขึ้นอย่างมากกกกก เวลาที่ฉันเอามาใช้กับ \"พลังกิ้งก่าขนปุย\"!",
  str_voice_1500881_51 = "เดิมทีฉันแค่ตามหาปะป๊า แต่ก็ไม่ได้เรื่องอะไร ฉันก็เลยตามน้ำไป เพื่อเดินทางไปที่ไหนสักแห่งที่ไกลยิ่งขึ้น",
  str_voice_1500881_52 = "Alchemy... Stars?",
  str_voice_1500881_53 = "ขอโทษที",
  str_voice_1500881_54 = "อรุณสวัสดิ์ เธอว่างรึเปล่า",
  str_voice_1500881_55 = "อยากเล่นกันไหม ฉันตื่นเต้นมากเลย!",
  str_voice_1500881_56 = "เธอ... หนาวบ้างไหม เวลากลางคืนน่ะ",
  str_voice_1500881_57 = "สุขสันต์วันปีใหม่ ฉันต้อง... เอาชนะจุดอ่อนของฉันให้ได้",
  str_voice_1500901_1 = "โอ้โห ฉันชอบรสชาติจังเลย... มาระเบิดอิคลิพไซท์ทิ้งกันเถอะ... กิ้ง-ก่า ฟาดฟัน ที่งด-งาม! เลือดอุ่น ๆ ได้ไหลท่วม... คอยระวังศัตรูด้านหลังเธอด้วยนะ!",
  str_voice_1500901_2 = "ตั้งตารออยู่ใช่ไหม ใช่ไหม อัลบั้มใหม่ของฉันชื่อว่า \"รักทุกวัน น้ำมันเครื่อง\" อัลบั้มมาพร้อมกับภาพถ่ายพิเศษของฉันในชุดว่ายน้ำ",
  str_voice_1500901_3 = "อิคลิพไซท์กระจัดกระจายไปหมด อันตรายซุ่มซ่อนอยู่ทุกที่ เตรียมเลื่อยวงเดือนกับประแจไว้ให้พร้อม! การต่อสู้อะไรเหรอ บาร์บาร่าพูดถึงคอนเสิร์ตต่างหาก!",
  str_voice_1500901_4 = "ครั้งหนึ่งฉันเคยร้องมากกว่า 600 เพลงที่งานไฟรี่ซัพพอร์ตสามวันติดกันโดยไม่หลับไม่นอน...",
  str_voice_1500901_5 = "เธอคิดว่าฉันน่ากลัวเหรอ อ๊ะ ไม่นะ! ฉันเป็นไอดอลที่สมบูรณ์แบบ เป็นเด็กสาววัยรุ่นที่ใสซื่อและน่ารัก เธอต้องดูฉันผิดไปแน่เลย ต้องใช่แบบนั้นแน่",
  str_voice_1500901_6 = "ดนตรีช่วยเยียวยาได้! ความฝันของฉันคือได้เป็นไอดอลและนำความรักความอบอุ่นมาสู่โลกนี้ด้วยดนตรีของฉัน!",
  str_voice_1500901_7 = "เฮ้ เธอจะมามีทแอนด์กรีทของฉันไหม แค่ซื้ออัลบั้ม เธอก็จะได้รับบัตรมาร่วมมีทแอนด์กรีทแล้ว!\nคนที่อยู่ท้ายแถวต้องระวังจะถูกอิคลิพไซต์จับกินนะ",
  str_voice_1500901_8 = "ถ้าเธอจะมา ฉันจะจองที่นั่งสบาย ๆ ติดเวทีให้เธอเลย ที่นั่งสำหรับสมาชิกโดยเฉพาะเลยนะ!",
  str_voice_1500901_9 = "พูดว่า \"ประแจ!\" ด้วยนะ เพราะฉันจะต้องรักรูปที่ถ่ายคู่กับเธอมากแน่นอน! ฉันจะไม่ลืมรอยยิ้มของเธอเลย!",
  str_voice_1500901_10 = "ฉันอยากจะแต่งเพลงให้เรดีเซล เวรนช์ ธีมก็คือ \"ทะเลทรายป่าเถื่อน\" ฉันควรชวนใครมาเป็นแขกพิเศษบ้างดี",
  str_voice_1500901_11 = "ถ้าฉันทำได้ดี ฉันอาจเพิ่มฐานแฟนเพลงได้ด้วยนะ! ฉันจะตั้งใจทำงานเพื่อรักษาตำแหน่งนักร้องที่ได้รับความนิยมสูงสุดของเรดีเซล!",
  str_voice_1500901_12 = "หา? ทำไมเธอถึงหยุดร้องเชียร์ล่ะ ไม่ต้องสนใจผู้รุกรานพวกนั้นหรอก คอนเสิร์ตยังต้องเล่นต่อไป!",
  str_voice_1500901_13 = "ฉันดีใจมากเลยที่เธอมา! ช่วยกรุณาอย่าตายนะ แล้วก็กลับมาดูคอนเสิร์ตรอบวันพรุ่งนี้ด้วย!",
  str_voice_1500901_14 = "เป็นไอดอลต้องบริหารจัดการสีหน้าท่าทางได้อย่างไร้ที่ติ เอาเลยนะ ยิ้มได้!",
  str_voice_1500901_15 = "แฮปปี้เบิร์ธเดย์ทูยู แฮปปี้เบิร์ธเดย์ทูยู มาจัดการอิคลิพไซท์พวกนั้นกันเถอะ!",
  str_voice_1500901_16 = "คอนเสิร์ตจะเริ่มแล้ว!",
  str_voice_1500901_17 = "โอ้... อ่ะแฮ่ม... โด-เร-มี-ฟา หา? นี่ฉันวอร์มเสียงอยู่!",
  str_voice_1500901_18 = "ยกมือหน่อย! ฉันอยากสัมผัสอารมณ์ของพวกเธอ!",
  str_voice_1500901_19 = "วู้ฮู้! ♪ ใครที่กล้ามาแทรกแซง ทักทายเลื่อยวงเดือนของฉันหน่อย!",
  str_voice_1500901_20 = "พวกคุณชาวเรดีเซล เวรนช์น่ารักกกกกที่สุดในโลกเลย!",
  str_voice_1500901_21 = "หา? ที่ลูโมโพลิสมีคณะประสานเสียงด้วยเหรอ แล้วก็มีนักดนตรีอาชีพด้วยเนี่ยนะ เธอห้ามเปลี่ยนใจนะ ผู้นำทาง!",
  str_voice_1500901_22 = "เรดีเซล เวรนช์! แสดงพลังให้ดูหน่อย!",
  str_voice_1500901_23 = "ไม่มีอิคลิพไซท์ที่คอนเสิร์ตของฉัน คนที่ทำคอนเสิร์ตเปรอะเปื้อนจะต้องได้รับบทเรียน",
  str_voice_1500901_24 = "มีใครไปคอนเสิร์ตเรจินามารึเปล่า ไม่เป็นไรหรอก บาร์บาร่า เปล่าว่าอะไรทั้งนั้น",
  str_voice_1500901_25 = "เจ้าจิ๋วคือคู่หูที่ดีที่สุดของฉันเลย! ทั้งการจัดเวที ลำโพง และไมโครโฟน ฝีมือเธอทั้งนั้น",
  str_voice_1500901_26 = "อาหารเมนูปลานี่อร่อยจังเลย โดยเฉพาะซาชิมิเนี่ย น่าเสียดายนะที่ฉันไม่ค่อยได้กิน",
  str_voice_1500901_27 = "ไอดอลที่สมบูรณ์แบบมีความรักมากพอสำหรับทุกสิ่ง และบาร์บาร่าหมายความว่าทุกสิ่งอย่างจริงจัง! แม้กระทั่งเสียงที่หนวกหูของเรจินา!",
  str_voice_1500901_28 = "ที่ไหนเหมาะสุดที่จะตั้งเวทีล่ะ ที่ท่าเรือเหรอ หรือบนสะพาน ฉันสับสนมากกกกเลย!",
  str_voice_1500901_29 = "ยู้ฮู! มาถึงความรักของ Rediesel คู่รักสุดฮอตและเป็นไอดอลของทุกคน Barbara! ♥ เสียงดังไม่พอ! ให้ฉันได้ยิน!",
  str_voice_1500901_30 = "ส่องแสง ♥ และเปล่งประกาย!",
  str_voice_1500901_31 = "มาร็อกแอนด์โรลในหัวใจกันเถอะ!",
  str_voice_1500901_32 = "ดนตรี! ความหลงใหล! จุดไฟให้ทะเลทราย!",
  str_voice_1500901_33 = "เพลงของบาร์บาร่าจะอยู่กับพวกเธอตลอดไป!",
  str_voice_1500901_34 = "หลงใหล ธรรมชาติ ความผูกพัน ความรัก!",
  str_voice_1500901_35 = "คุณ! พร้อม! รึยัง!",
  str_voice_1500901_36 = "ดนตรี! สัมผัสจังหวะเลย!",
  str_voice_1500901_37 = "เลื่อยหัวใจ!",
  str_voice_1500901_38 = "ร็อกแอนด์โรลจ้าพี่น้อง!",
  str_voice_1500901_39 = "ลาลาลา... ปั๊มปาดัมป่าม...",
  str_voice_1500901_40 = "ตกหลุมรัก!",
  str_voice_1500901_41 = "ขอเสียงหน่อย!",
  str_voice_1500901_42 = "เอาอีกเหรอ ฉันจัดให้!",
  str_voice_1500901_43 = "ไม่ว่าฉันจะล้มกี่ครั้ง ฉันก็จะลุกขึ้นได้เองและก้าวเดินต่อไป",
  str_voice_1500901_44 = "ฉันจัดคอนเสิร์ตที่นี่ได้ไหม",
  str_voice_1500901_45 = "ของขวัญทั้งหมดสำหรับฉัน ควรมอบให้เอเจนต์ได้เลย",
  str_voice_1500901_46 = "ฉันจะรับของขวัญของเธอไว้เงียบ ๆ แล้วกัน",
  str_voice_1500901_47 = "งั้นฉันจะมอบรูปถ่ายพร้อมลายเซ็นให้เธอเป็นการตอบแทนนะ",
  str_voice_1500901_48 = "ไม่ได้หรอก ไอดอลเขาห้ามมีความสัมพันธ์แบบรักใคร่ แต่ว่า...",
  str_voice_1500901_49 = "แน่นอนว่าฉันเคยผ่านช่วงเวลาที่เจ็บปวดมาแล้ว และฉันก็ได้ดนตรีนี่แหละช่วยชีวิตเอาไว้ ตอนนี้ฉันก็เลยอยากช่วยทุกคนด้วยดนตรีเหมือนกัน!",
  str_voice_1500901_50 = "เส้นทางการมาเป็นไอดอลมันยากและยาวนาน แต่ฉันจะไม่ยอมแพ้ แสดงในทะเลทรายไปกับคณะเดินทางเพื่อสร้างฐานแฟนเพลงของฉัน เพียงแค่ได้เห็นรอยยิ้มครั้งเดียว ฉันก็ยินดีปรีดามากแล้ว",
  str_voice_1500901_51 = "เพราะความตั้งใจจริงของฉันและทักษะที่น่าประทับใจในฐานะไอดอล บาร์บาร่าจึงมีแฟนเพลงเพิ่มขึ้นมากมาย แต่ยัยเรจินานั่นก็พยายามแซงหน้าฉันตลอด!",
  str_voice_1500901_52 = "Alchemy Stars!",
  str_voice_1500901_53 = "สวัสดี!",
  str_voice_1500901_54 = "อรุณสวัสดิ์! ตื่นเต้นหน่อยสิ!",
  str_voice_1500901_55 = "สวัสดี! แสดงอารมณ์ออกมาหน่อย!",
  str_voice_1500901_56 = "คอนเสิร์ตแห่งความรักจะเริ่มขึ้นแล้ว!",
  str_voice_1500901_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1600011_1 = "เรื่องด่วนรึเปล่า เธอดูไม่เหมือนมาธุระอะไรที่เป็นทางการเลยนะ... ถ้าอย่างนั้นฉันขออนุญาตขอตัวก่อนนะ",
  str_voice_1600011_2 = "เรื่องที่เธอพูดถึงอยู่นี่มันสำคัญมากขนาดนั้นรึเปล่า เธอ... เข้ามาใกล้ฉันมากเกินไปนะ...",
  str_voice_1600011_3 = "การมีวินัยในตนเองเป็นคุณสมบัติที่ยิ่งใหญ่ คือฉันจะถามว่า เธอช่วยอย่าจับกระจกหรือกลีบดอกไม้ได้ไหม",
  str_voice_1600011_4 = "ครั้งหนึ่งนานมาแล้ว นาร์ซิสซัสสีขาวมักจ้องมองไปที่ทะเลสาบกระจกเงา... แล้วดอกไม้อีกชนิดหนึ่งไปไหนล่ะ มันดอกอะไรนะ",
  str_voice_1600011_5 = "ดอกไม้แห่งนอร์ธแลนด์กับกระจก สองโลกที่กลับมาเชื่อมโยงกันอีกครั้ง ด้านไหนที่เป็นของจริง",
  str_voice_1600011_6 = "นาร์ซิสซัสสีขาวบานเต็มที่อีกแล้ว เราคือสองภาพคู่แฝดในกระจก และเราจะมีชีวิตอยู่ต่อไปจากนิทานโบราณ และสานต่อเรื่องราวของเราต่อไป",
  str_voice_1600011_7 = "ถ้ามันไม่ได้เกิดขึ้นตามธรรมชาติ งั้นมันก็จะกลายเป็นการดิ้นรนสำหรับเราทั้งคู่ นั่นใช่สิ่งที่เธอคาดหวังรึเปล่า",
  str_voice_1600011_8 = "เธออาจได้รับความชอบพอจากฉันขึ้นมาบ้าง แต่ไม่มีอะไรมากกว่านั้น แบบนั้นเธอพอใจรึเปล่าล่ะ",
  str_voice_1600011_9 = "ถ้าวันหนึ่งเราได้พบกับตัวของเราเองอีกครั้ง ฉันหวังแค่อย่างเดียวว่าเธอจะอยู่ในความทรงจำใหม่ล่าสุดของฉันด้วย",
  str_voice_1600011_10 = "ในวันที่ผ่อนคลาย แม้แต่ท้องฟ้าก็ยังสีฟ้าสดกว่าปกติ!",
  str_voice_1600011_11 = "ดูจากสีหน้าเธอแล้ว ฉันรู้สึกว่าฉันคงปฏิเสธเธอไม่ได้",
  str_voice_1600011_12 = "รักษาระยะห่างและระวังสิ่งที่เธอพูดหรือทำด้วยนะ ถ้าทำได้แบบนั้น น้องสาวฉันคงยอมรับเธอมากขึ้นอีกนิด",
  str_voice_1600011_13 = "อย่าบอกนะว่าเธอจะให้ฉันช่วยเอ่ยชมเธอให้เขาฟัง... ขอคิดดูก่อนนะ",
  str_voice_1600011_14 = "ฉันรู้สึกไม่สบายใจนิดหน่อย... เหมือนหินก้อนเล็ก ๆ ตกลงทะเลสาบน่ะ",
  str_voice_1600011_15 = "วันนี้ไม่มีอะไรพิเศษ เราแค่ทำตัวแบบเดิม มีความสุขไปกับสันติและความเงียบ",
  str_voice_1600011_16 = "หืมม เธอมีธุระที่เกี่ยวกับฉันรึเปล่า",
  str_voice_1600011_17 = "อ้า! เข้าใจแล้ว ความแข็งแกร่งของเธอ …เธอเป็นคนตื่นเช้า",
  str_voice_1600011_18 = "ฉันได้ยินเสียงเธอกลับมา ฉันเลยไม่อยากทำให้เป็นเรื่องใหญ่ แค่นั้นแหละ",
  str_voice_1600011_19 = "มันค่อนข้างชัดเจนนะว่าเธอรบกวนฉัน... ถ้างั้นก็นอนพักให้เร็วขึ้นหน่อย",
  str_voice_1600011_20 = "นอร์ธแลนด์คือที่เดียวที่เราจะอยู่รอดได้ โดยเฉพาะพี่สาวของฉัน...",
  str_voice_1600011_21 = "ตามคำสั่งขององค์ราชินี ฉันจะดูแลลูโมโพลิสอย่างดีด้วยกระจกของฉัน",
  str_voice_1600011_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1600011_23 = "ไม่จำเป็นต้องให้ความเห็นใด ๆ สารธรรมดา ๆ แต่อันตรายพวกนั้นไม่มีโอกาสล่วงล้ำเข้าสู่นอร์ธแลนด์ได้อย่างแน่นอน",
  str_voice_1600011_24 = "เธอเปรียบเสมือนนอร์ธแลนด์ในตัวเอง และให้ที่พักพิงแก่ทุกสิ่งที่บริสุทธิ์เสมอ นี่คือสาเหตุที่ฉันชื่นชมเธอด้วยเหมือนกัน",
  str_voice_1600011_25 = "แม้ว่าเธอจะโหวกเหวกไปสักหน่อย แต่ราชินีก็ได้บอกแล้วว่ามันเป็นเรื่องดี เพราะเธอทำให้พระราชวังนอร์ธแลนด์มีสีสัน",
  str_voice_1600011_26 = "ดอกไม้ขาว เวลาพักผ่อน กลิ่นสะอาดสดชื่น ...และพี่สาวของฉัน",
  str_voice_1600011_27 = "ฉันไม่ชอบอะไรที่ไม่สะอาด แค่พูดถึงก็ขยะแขยงแล้ว",
  str_voice_1600011_28 = "มันยากที่จะเจอสีขาวบริสุทธิ์แบบนี้ ฉันบอกได้เลยว่าเธอหวงแหนมันมาก",
  str_voice_1600011_29 = "อย่าแสดงพฤติกรรมหยาบคาย และอย่าบ่นนะว่านิคินิสไม่เตือน ทุกอย่างที่อยู่ภายนอกนอร์ธแลนด์มันบ้าคลั่งมาก",
  str_voice_1600011_30 = "ฉันกำลังรอให้ดอกไม้บานเพิ่มอีก",
  str_voice_1600011_31 = "อะไรชัดเจนกว่ากัน อดีตหรืออนาคต",
  str_voice_1600011_32 = "โชคชะตาของสองโลกจะต้องเชื่อมโยงกัน!",
  str_voice_1600011_33 = "ในที่สุดฉันก็ข้ามมิติไกลโพ้นได้แล้ว",
  str_voice_1600011_34 = "ทำให้เสร็จสิ้นไป",
  str_voice_1600011_35 = "ดอกไม้นอร์ธแลนด์เริ่มเบ่งบานแล้ว",
  str_voice_1600011_36 = "เธอไม่ต้องเตือนฉันหรอกน่า",
  str_voice_1600011_37 = "เหี่ยวเฉาแล้วก็เบ่งบาน",
  str_voice_1600011_38 = "นี่คือดอกไม้บานแห่งสวรรค์ ต้อนรับฤดูใบไม้ผลิ",
  str_voice_1600011_39 = "ขอจงมีความสงบและความเงียบ",
  str_voice_1600011_40 = "มันควรจะสงบสุขและเงียบสงัดตั้งแต่แรกแล้ว",
  str_voice_1600011_41 = "พูดเพียงครั้งเดียว และครั้งเดียวเท่านั้น ที่นอร์ธแลนด์เราทำกันแบบนี้",
  str_voice_1600011_42 = "นี่ไม่ใช่ผลลัพธ์สมบูรณ์แบบที่เธอต้องการใช่ไหม",
  str_voice_1600011_43 = "อึ๋ย เสื้อผ้าเปื้อนดินหมดเลย",
  str_voice_1600011_44 = "เธอชอบนาร์ซิสซัสสีขาวรึเปล่า ฉันจะให้เธอดูต่ออีกหน่อยแล้วกันนะ",
  str_voice_1600011_45 = "ฉันไม่ควรคาดหวังอะไรจากเธอเลย... ฮึ่มม",
  str_voice_1600011_46 = "ที่จริงมันก็ไม่เลวใช่ไหม งั้นฉันเอานะ",
  str_voice_1600011_47 = "มันคือของขวัญที่คาดการณ์ไว้แล้ว ฉันก็เลยไม่ได้ตั้งตารอ",
  str_voice_1600011_48 = "นี่มัน... ค่อนข้างดีนะคราวนี้ ยังไงก็ขอบคุณแหละมั้ง",
  str_voice_1600011_49 = "ฉันสูญเสียความทรงจำและความโหยหาไปพร้อมกัน จากนั้นมาฉันก็ไม่สนใจโลกภายนอกอีกเลย",
  str_voice_1600011_50 = "กาลเวลาไม่อาจหวนคืน เฉกเช่นดอกไม้ที่ร่วงหล่นหรือความรักของฉัน",
  str_voice_1600011_51 = "ชาวนอร์ธแลนด์ปกป้องความลับของโลกนี้เอาไว้ ความทรงจำเรื่องนาร์ซิสซัสสีขาวที่ผนึกแน่นจะเป็นคำเตือนสุดท้ายของทวีปแห่งนี้",
  str_voice_1600011_52 = "Alchemy Stars",
  str_voice_1600011_53 = "หา... เธออยู่ที่ไหน",
  str_voice_1600011_54 = "...อรุณสวัสดิ์",
  str_voice_1600011_55 = "เธอไม่ต้องสนใจมากนักหรอก แค่...",
  str_voice_1600011_56 = "ช่างมันเถอะถ้าเธอกำลังจะไปพัก...",
  str_voice_1600011_57 = "ฉันว่าฉันก็จะอวยพรให้เธอสุขสันต์วันปีใหม่แหละนะ",
  str_voice_1600041_1 = "โอ้ย รู้กันแค่เราสองคนนะ บอกฉันซิว่าใครดังกว่ากัน ฉันหรือเจ้าตัวใหญ่นั่น หา? เป็นไปไม่ได้! ทุกคนตาบอดกันหมดรึไง เพนกวินน่ะน่ารักกว่าเห็น ๆ จริงไหม",
  str_voice_1600041_2 = "มีใครอยู่ไหม! ช่วยด้วย!! อ๋อ เธอนั่นเอง เอาเนื้อสัตว์มาให้กระป๋องหนึ่งซิ เอาอาหารให้คุมะเร็ว ๆ เลย ไม่งั้นเขาจับฉันกินเป็นอาหารแก้ขัดเพราะความหิวแน่นอน!",
  str_voice_1600041_3 = "ฮึ่ม เรื่องไม่จบสวยแน่ถ้าเธอประเมินเราต่ำเกินไป เราเป็นทหารรับจ้างที่มีชื่อเสียงเล็กน้อยในทวีปแห่งนี้ อ่ะแฮ่ม โดยเฉพาะก่อนที่จะเกิดอุบัติเหตุระเบิดนั่น...",
  str_voice_1600041_4 = "ทำไมเราถึงสร้างสระว่ายน้ำบนยานโคลอสซัสไม่ได้นะ! คุมะโตขึ้นเรื่อย ๆ เลย และเขาก็เริ่มตัวใหญ่เกินกว่าจะคลานเข้าไปในคูลเลอร์เพื่อคลายร้อนแล้ว...",
  str_voice_1600041_5 = "- ร้อนมากเลย!\n- อ๋อ! ฉันเข้าใจแล้ว! ยังไงก็ตาม ต้องลุกก่อน! ลุกสิเจ้าโง่ตัวขาว! พระเจ้า ฉันชักจะร้อนแล้วสิตอนนี้...",
  str_voice_1600041_6 = "- ฉันเบื่อมาก! เธออยากเอาระเบิดมาเล่นเป็นลูกเบสบอลกับฉันไหมล่ะ มันน่าตื่นเต้น \"อย่างสุด ๆ\" เลยนะ!\n- ก็ได้ ฉันจะเล่น\n- เธอทำอะไรน่ะ ถอยไปห่าง ๆ ฉันเลยนะ! เดี๋ยวก่อน!!!",
  str_voice_1600041_7 = "หืม? เธอสนใจการเต้นของเรางั้นเหรอ เธอมีรสนิยมที่ดีอย่างน่าแปลกใจเลย! ถ้าเธออยากมาเป็นนักเรียนของฉันด้วยความจริงใจ บางทีฉันอาจสอนเธอได้นะ ฮิฮิ!",
  str_voice_1600041_8 = "นี่รสชาติค่อนข้างดีเลยนะ เอ้า ลองกินสิ",
  str_voice_1600041_9 = "ฮึ ฉ-ฉันไม่รู้จะทำยังไงกับเธอดี บางทีฉันน่าจะอนุญาตให้เธอลูบไล้ขนนกที่นุ่มแน่นของฉันได้... แต่อย่าลูบไปผิดทางนะ!",
  str_voice_1600041_10 = "เฮ้! ทำไมใจลอยแล้วล่ะ เราโดดงานไปเที่ยวเล่นด้วยกันสักแห่งดีไหม",
  str_voice_1600041_11 = "หาที่งีบหลับดีกว่า พุงเจ้านี่นุ่มสบายมากเลย ทำตามฉันนะ... คร่อกฟี้...",
  str_voice_1600041_12 = "ย-อย่าจิ้มพุงฉันเซ่!",
  str_voice_1600041_13 = "อ้าว... ฉันแค่กระโดดนิดเดียว พื้นถึงกับแตกเลยเหรอ",
  str_voice_1600041_14 = "เราไม่ได้อ้วน เรากินดีอยู่ดี ใช่แล้ว ก็เพราะทหารรับจ้างเงินดีไงล่ะ",
  str_voice_1600041_15 = "มาเถอะ มาจัดงานวันเกิดกัน! แดนซ์! เอ้าแดนซ์!",
  str_voice_1600041_16 = "โย่ว! มาสนุกด้วยกันเถอะ!",
  str_voice_1600041_17 = "มีอะไรกินตอนเช้าเนี่ย มีไอศกรีมไหม",
  str_voice_1600041_18 = "วันนี้เธอมาช้า อาหารอยู่ไหนล่ะ",
  str_voice_1600041_19 = "เอิ้ก! ฉันอยากกินอาหารอีกชุดน่ะ",
  str_voice_1600041_20 = "อยู่แถวนี้ ฉันเดินไปไหนมาไหนได้โดยไม่มีใครมาบอกฉันว่าต้องทำอะไร ดีมากเลยนะ",
  str_voice_1600041_21 = "พี่ ๆ ของฉันในเรดีเซล เวรนช์ช่างรู้วิธีสร้างความสนุกสนานเสียจริง! ฉันจะไปเที่ยวเล่นกับพวกเขาเหมือนกันเมื่อสถานการณ์ปกติในสักวัน!",
  str_voice_1600041_22 = "ขั้วโลก!",
  str_voice_1600041_23 = "ฉันกินไม่ได้ น่ารำคาญจัง",
  str_voice_1600041_24 = "ฉันไม่เข้าใจแม่สาวคาฟกานั่นเลย! ฉันขอให้เธอมอบอาหารให้เรา แต่เธอกลับไล่เราออกมาเฉยเลย! ผู้หญิงเนี่ยนะ!",
  str_voice_1600041_25 = "ผงเขี้ยวฉลามของคอร์กอนน่ากินมาก! แต่ว่ามีไม่ค่อยเยอะน่ะสิ...",
  str_voice_1600041_26 = "เวลาฉันได้ลงนอนบนก้อนน้ำแข็งหลังเลิกงาน มันรู้สึกเหมือน... สวรรค์เลย",
  str_voice_1600041_27 = "ร้อนมาก! ฉันจะละลายแล้ว!",
  str_voice_1600041_28 = "มันเป็นสถานที่แปลกประหลาดที่มีคนมากมายหลายประเภท และเครื่องปรับอากาศก็ทำให้เย็นฉ่ำจริง ๆ",
  str_voice_1600041_29 = "โย่ว วู้ว ฮา! คู่หูที่่แข็งแกร่งที่สุดในทวีปนี้มาแล้ว! เรื่องต่อสู้ให้เราจัดการเถอะ เตรียมอาหารให้เราให้เพียงพอก็แล้วกัน!",
  str_voice_1600041_30 = "ฉันสูงขึ้นแล้ว!",
  str_voice_1600041_31 = "ฉันแข็งแกร่งขึ้นแล้ว และขนของฉันก็เงางามขึ้นด้วย!",
  str_voice_1600041_32 = "รู้สึกดีมากเลย!",
  str_voice_1600041_33 = "ฮิฮิ ทีนี้เราก็คงกระพันแล้วนะคู่หู!",
  str_voice_1600041_34 = "อย่าถ่วงเรานะ!",
  str_voice_1600041_35 = "คุมะ! เตรียมยิง!",
  str_voice_1600041_36 = "เธอต้องเล็งให้ดีก่อน!",
  str_voice_1600041_37 = "- มาแล้ว!\n- เดี๋ยว! เอ๊ย",
  str_voice_1600041_38 = "- เอานี่ไปด้วย!\n- ฉันไม่สนใจแล้ว...",
  str_voice_1600041_39 = "ฉันว่าเธอคงไม่คิดว่าจะมีการซุ่มโจมตีสินะ!",
  str_voice_1600041_40 = "ระเบิดเลย!",
  str_voice_1600041_41 = "เราต้องต่อสู้กันก่อน!",
  str_voice_1600041_42 = "ไม่มีการต่อสู้ครั้งไหนที่เราชนะไม่ได้!",
  str_voice_1600041_43 = "เราพลาดแล้ว... เวรจริง...",
  str_voice_1600041_44 = "ฉันอยากได้เบียร์เย็น ๆ",
  str_voice_1600041_45 = "อันนี้กินได้รึเปล่า",
  str_voice_1600041_46 = "คุมะ! ดูสิว่าฉันได้อะไรมา!",
  str_voice_1600041_47 = "นี่มันล้ำค่ามาก มีงานให้เราทำไหม",
  str_voice_1600041_48 = "ไชโย! เธอกินอาหารกระป๋องสุดล้ำค่าของฉันได้กระป๋องหนึ่งนะ",
  str_voice_1600041_49 = "- แดนเหนือ! แดนเหนือ! เธอยังไม่เคยไปใช่ไหม มันต่างจากที่นี่มากเลย ฉันอยากพาเธอไปชมทิวทัศน์ที่นั่นจัง ใช่ไหมคุมะ\n- ใช่ ๆ",
  str_voice_1600041_50 = "อดีตไม่สำคัญหรอก ตราบใดที่ฉันกับคู่หูสามารถกินอาหารได้มากเท่าที่เราอยากจะกิน\nฉันหวังให้การเดินทางครั้งนี้ของฉันกับคุมะไม่มีวันจบลง เฮ้อ พูดไปก็อายตัวเอง... เฮ้ ย-อย่าหัวเราะสิ!",
  str_voice_1600041_51 = "- เธออยากเห็นไหมว่าเมื่อก่อนฉันหน้าตาเป็นยังไง ขนของฉันไม่ใช่สีนี้ และฉันก็เคยทำเสียงกุ๊ก ๆ ประหลาด ๆ ด้วยนะ\n- เสียงน่าเกลียดมากเลย",
  str_voice_1600041_52 = [[
- Alchemy?
- Stars!!]],
  str_voice_1600041_53 = "อ้าว! ฉันตามหาอยู่เลย",
  str_voice_1600041_54 = "อรุณสวัสดิ์! วันนี้วันดีนะ",
  str_voice_1600041_55 = "เธอก็มาด้วยเหรอ",
  str_voice_1600041_56 = "เลิกนอนได้แล้ว มาช่วยฉันนี่!",
  str_voice_1600041_57 = "- ปีใหม่เหรอ\n- ปีนี้ต้องเป็นปีที่ดีแน่นอน! สุขสันต์วันปีใหม่นะ!",
  str_voice_1600051_1 = "มาดื่มชากับเพื่อนใหม่และสนุกไปกับช่วงเวลาสุดท้ายของชีวิตด้วยกันไหม",
  str_voice_1600051_2 = "ฉันมัดเชือกกับจิตวิญญาณของเธอ แล้วมาเต้นรำกันให้สุดเหวี่ยงที่งานเลี้ยงน้ำชายามบ่ายของเราดีไหมล่ะ มาเถอะ!",
  str_voice_1600051_3 = "อ๋อ กรงเล็บจักรกลนี่น่ะเหรอ ไม่ต้องกลัว ไม่เจ็บเลยสักนิด อย่างน้อยก็ไม่เคยมีใครบ่นนะ!",
  str_voice_1600051_4 = "โอ้ เสียงคร่ำครวญรื่นหูแบบนี้ มันคือของเล่นและเครื่องชูใจของฉันนะ! ทั้งพ่อทั้งสองสาวของฉัน ไม่มีใครเข้าใจน้ำเสียงที่เป็นท่วงทำนองนี้เลย... ส่วนเธอล่ะ",
  str_voice_1600051_5 = "บ้านของขุนนางผู้สูงส่งมีสวนหลังบ้านด้วย สวนหลังบ้านที่ถูกลืมมีหลุมศพเก่าอยู่ ลึกลงไปในหลุมศพที่ชื้นแฉะ มีสตรีผู้หนึ่งหลับใหลอยู่ และในรอยยิ้มของสตรีผู้นั้น... หือ เธอเห็นอะไร",
  str_voice_1600051_6 = "โลงหินที่ปิดตายได้เปิดออกแล้ว จงทำตามความกระหายและแรงปรารถนา ยื่นมือออกมาจากลำคอของเธอ แล้วหยิบผลไม้หอมหวานนั่นซะ...",
  str_voice_1600051_7 = "ดูจากแววตาของเธอแล้ว... เธอต้องการอะไรเหรอ หรือว่าจะเป็น... เธออยากเป็นส่วนหนึ่งของครอบครัวใหญ่นี้ และมาเป็นสมาชิกราชวงศ์นี้งั้นเหรอ",
  str_voice_1600051_8 = "ก็ได้ ฉันอนุญาตให้เธอเข้ามาใกล้ฉัน แต่ถ้าเธอขีดข่วนกระโปรงฉันแม้แต่นิดเดียว ฉันกระทืบหน้าเธอแน่ ตกลงใช่ไหม",
  str_voice_1600051_9 = "เวลาจ้องตาฉัน... สีหน้าของเธอหมายถึงความกลัวหรือความตื่นเต้น โอ๊ะ อยากให้ฉันเดาเหรอ",
  str_voice_1600051_10 = "\"เมื่อใดที่ดวงดาวและดวงจันทร์มืดลง แมงมุมสีดำจะโผล่ขึ้นมาจากหลุมศพเพื่อกลืนกินผู้อยู่อาศัยที่หลงทาง...\" คนโง่แบบไหนกันที่เขียนเรื่องน่าขำแบบนี้",
  str_voice_1600051_11 = "ฉัน... เธออยากให้ฉันอยู่ที่นี่เหรอ เธอรู้ใช่ไหม เขาลือกันว่าฉันน่ะคือฝันร้ายจากหลุมศพ",
  str_voice_1600051_12 = "เมื่อกี้เธอสัมผัสตัวฉันใช่ไหม ถ้าเป็นมีอา เธอคงร้องไห้",
  str_voice_1600051_13 = "ฉันอยากได้ชาดำ... แล้วก็ขนม... ชา... กับขนม...",
  str_voice_1600051_14 = "ถ้าฉันยิ้มแบบนี้ ฉันจะเหมือนบาบายาก้าใช่ไหม อืม... ยังไงเธอก็หน้าเหมือนฉันอยู่แล้วแหละนะ",
  str_voice_1600051_15 = "ขอโทษทีที่โผล่มาดื้อ ๆ แบบนี้! เธอบอกว่าฉันควรเป็นคนที่ลงมือทำเรื่องนี้... ก็คือ ฉลองวันเกิดให้เธอน่ะ",
  str_voice_1600051_16 = "เธอมาสายนะ ไปไหนมา",
  str_voice_1600051_17 = "ไม่รู้รึไงว่า \"ไม่ควร\" รบกวนฉันตอนเช้าตรู่ขนาดนี้!?",
  str_voice_1600051_18 = "เดี๋ยวนะ นี่เธอ... คิดว่าฉันจะพูดต้อนรับเหรอ ถ้างั้นก็... ย-ยินดีต้อนรับนะ",
  str_voice_1600051_19 = "ได้เวลารับประสบการณ์สยองขวัญสุดรื่นรมย์แล้ว เราไปดู... แมงมุมดำกันดีไหม",
  str_voice_1600051_20 = "เธอคิดจริง ๆ เหรอว่าฉันเหมาะกับที่นี่ ปราสาทขาวนั่นน่ะเหรอ เธอต้องเพี้ยนไปแล้วแน่นอน...",
  str_voice_1600051_21 = "เครื่องจักรพวกนี้... นักวิจัยพวกนั้นคงสนุกสนานกันสุดชีวิตแน่เลย ฉันก็ซาบซึ้งแหละนะ",
  str_voice_1600051_22 = "แชโดว์ทอดตัวอยู่เบื้องล่าง",
  str_voice_1600051_23 = "อิคลิพไซท์เหรอ โอ้! พวกนี้แหละคือของเล่นที่ฉันชอบจับมาทรมาน",
  str_voice_1600051_24 = "น้องสาวที่น่าสงสาร ถ้าเราได้พบกันซึ่งหน้า ฉันอยากรู้ว่าสีหน้าของเธอจะเป็นยังไง ฮ่า",
  str_voice_1600051_25 = "ถึงแม้ว่าส่วนมากแล้วเธอจะครอบครองร่างนี้ แต่เธอก็ยอมให้ฉันเอาไปใช้นะถ้าฉันตื๊อหนัก ๆ",
  str_voice_1600051_26 = "อะไรนะ เธออยากเอาใจพวกเรางั้นเหรอ แล้วชาดำกับขนมของเราล่ะอยู่ไหน",
  str_voice_1600051_27 = "เธอคิดยังไงกับฉันล่ะ น่ารำคาญไหม อะไรนะ ฉันนึกว่าเธออยากคุยเรื่องนี้จริง ๆ เสียอีก",
  str_voice_1600051_28 = "ฉันได้กลิ่นที่ทำให้ฉันไม่มีความสุขลอยมาจากที่ไหนสักแห่งในนี้...",
  str_voice_1600051_29 = "เข้ามาสิ ใกล้อีก เจ้าภาพขุนนางของเธอเชิญให้เธอเข้าร่วมปาร์ตี้น้ำชาครั้งนี้ เธอกับฉันกำลังสนุกกันมากเลยที่ได้ใช้เวลาร่วมกันที่ปาร์ตี้น้ำชาครั้งนี้",
  str_voice_1600051_30 = "เธอสนใจในตัวฉันจริง ๆ ใช่ไหมล่ะ",
  str_voice_1600051_31 = "ใช่แล้ว น้องสาวที่รัก เราไม่ใช่คนเดิมอย่างที่เคยเป็นอีกต่อไปแล้ว...",
  str_voice_1600051_32 = "จงก้มหัวลงต่อหน้าฉัน! ฉันจะกลืนกินจิตวิญญาณของเธอ!",
  str_voice_1600051_33 = "ฉันจะรอเธออยู่ในรังรักแห่งการลงโทษ คาร์ลีน!",
  str_voice_1600051_34 = "มาเล่นกับฉันได้ไหม",
  str_voice_1600051_35 = "รสชาติดีกว่าขนมอีก...",
  str_voice_1600051_36 = "อื้อหือ น้ำลายไหลเลยฉัน...",
  str_voice_1600051_37 = "ร่ำไห้! กรีดร้อง! โอ้ จิตวิญญาณนี่ช่างมีท่วงทำนองดีจัง!",
  str_voice_1600051_38 = "โอ้ กลิ่นอายแห่งความกลัวช่างเย้ายวนเหลือเกิน!",
  str_voice_1600051_39 = "ไม่มีทางหนีพ้น!",
  str_voice_1600051_40 = "ลงโทษ!!",
  str_voice_1600051_41 = "สวนสนุกในนรก ที่เป็นของฉันคนเดียว!",
  str_voice_1600051_42 = "โอ้ ฉันจะเชือดเธอตามคำขอเลย",
  str_voice_1600051_43 = "ปวดใจ! กับความ-น่า-เบื่อ!!!",
  str_voice_1600051_44 = "คือ... ที่จริงแล้วฉัน... ไม่ชอบกระโปรงสีเข้มตัวนี้เลย",
  str_voice_1600051_45 = "แสดงให้เห็นความจริงใจหน่อย ไม่งั้นฉันจะฉีกเธอเป็นชิ้น ๆ",
  str_voice_1600051_46 = "น่ารักจังเลยที่เธอพยายามเอาใจฉัน",
  str_voice_1600051_47 = "นี่เธอพยายามจะหาเรื่องให้ฉันแสดงด้านร้ายออกมาเหรอ",
  str_voice_1600051_48 = "ถ้าทำดีมาก ๆ... ฉันจะให้เธอแสดงความขอบคุณในคราวหน้า",
  str_voice_1600051_49 = "ฉัน... ฉันหวังว่าเราคงไม่ได้ทำให้เธอกลัวนะ มันก็จริงที่เราเป็นแมงมุมดำผู้กลืนกินวิญญาณที่คนในลูโมโพลิสเขาพูดถึงกันอยู่... มันคือความลับที่เธออยากเผยออกมาจริง ๆ...",
  str_voice_1600051_50 = "มันเกิดขึ้นเมื่อไหร่น่ะเหรอ เมื่อตอนที่พ่อยังคงรักฉันอยู่ แม่ก็ยังคงรักฉันอยู่ น้องสาวฉันก็เป็นเด็กขี้แย... และสงครามก็ยังไม่เริ่มต้นขึ้น",
  str_voice_1600051_51 = "เขาตั้งใจที่จะฝังความลับของลูโมโพลิสไปกับฉัน... แต่วันหนึ่งพวกเขาจะกลับมาเอาคืน... รอไว้เลย ท่านพ่อที่รักของฉัน...",
  str_voice_1600051_52 = "Al-che-my Stars",
  str_voice_1600051_53 = "เธอน่ะ มานี่ซิ!",
  str_voice_1600051_54 = "ฉันต้องการอะไรบางอย่างจากเธอ!",
  str_voice_1600051_55 = "นี่เธอ... เธออยู่รึเปล่า",
  str_voice_1600051_56 = "เธอทำอะไรอยู่น่ะ",
  str_voice_1600051_57 = "ฮ่า ปีใหม่เหรอ จริงดิ",
  str_voice_1600101_1 = "อะไรกัน อารมณ์เสียอีกแล้วเหรอ ดูนี่! กระต่ายมาปลอบใจแล้ว รู้สึกดีขึ้นรึยัง",
  str_voice_1600101_2 = "ฉันคอยดูแลโลกเล็ก ๆ ที่ถูกละเลยมาตลอด วันหนึ่งความแข็งแกร่งของโลกใบนั้นอาจเป็นกุญแจสำคัญที่ช่วยชีวิตเราก็ได้",
  str_voice_1600101_3 = "เธอนี่ทั้งไม่ระวังและไม่รับผิดชอบเลยนะ... เธอคิดว่าแค่ตัวสูงและก็ไว้เคราแล้วจะเป็นผู้ใหญ่ได้งั้นเหรอ เธอเข้าใจผิดแล้ว!",
  str_voice_1600101_4 = "โลกใบจิ๋วร้อนรนไปกันใหญ่แล้ว ทำให้ผู้คนโดยรอบได้รับอันตรายเมื่อใดก็ตามที่มีอะไรไขว้เขว! ราชินีบอกฉันว่าฉันต้องใช้ความพยายามมากกว่านี้และเรียนรู้ที่จะควบคุมพลังนี้ให้ได้!",
  str_voice_1600101_5 = "กล่องลูกกวาดของฉันจะกลายเป็นโลงศพของศัตรูในอีกไม่ช้า พลังของฉันน่ากลัวมาก! อ๊ะ แย่แล้ว...",
  str_voice_1600101_6 = "ในโลกนี้จะมีเทพนิยายเกิดขึ้นอีกมาก ซึ่งจะเต็มไปด้วยชีวิตจากความฝันของทุกคนมากยิ่งขึ้น! เหมือนเทพนิยายที่เพิ่งสร้างสรรค์ขึ้นมาใหม่นี้ที่กล่าวถึงการเดินทางของเรา!",
  str_voice_1600101_7 = "เหล่าเอลฟ์ทำงานให้กับองค์ราชินี และก็เป็นหน้าที่ของฉันที่จะบันทึกเรื่องราวของนอร์ธแลนด์ อยากแอบดูหน่อยไหมล่ะ",
  str_voice_1600101_8 = "ฉันกำลังสร้างกระท่อมลูกกวาดอยู่ เธอคิดว่าหน้าต่างควรเป็นรสอะไรดี นี่เป็นประเพณีของนอร์ธแลนด์เลยนะ",
  str_voice_1600101_9 = "นี่เธอถามความเห็นฉันเหรอ ฉันนึกว่าเธอเห็นฉันเป็นแค่เด็กเล็ก ๆ ซะอีก... ฉันปลื้มจัง!",
  str_voice_1600101_10 = "เอาฟืนกองนั้นออกซะ วัสดุติดไฟทั้งหมดเป็นของต้องห้ามที่นี่ หา! ฉันไม่สนใจ! มัน-ก็แค่-สิ่งต้องห้าม!",
  str_voice_1600101_11 = "ว่าไง มาฟังนิทานก่อนนอนเหรอ มีเรื่อง \"มนุษย์หิมะตัวน้อยกับดาวสิบสองดวง\", \"กระท่อมของเอลฟ์\", \"ลูกของมังกร\" แล้วก็อีกมากมาย ชอบเรื่องไหนล่ะ",
  str_voice_1600101_12 = "เธออยากดูมายากลไหมล่ะ ดูนี่ อะไรอยู่ในกระเป๋าฉันนี่... ชะแว้บ! ลูกกวาดไง!",
  str_voice_1600101_13 = "เธออยากเป็นเอลฟ์ประเภทไหนล่ะ ฉันสามารถพรรณนาตัวเธอในเนื้อเรื่องได้ตามที่เธอชอบเลยนะ!",
  str_voice_1600101_14 = "เลือกสิ่งของจากกระเป๋าของฉันสิ แล้วนำไปมอบให้คนที่เธอห่วงใย!",
  str_voice_1600101_15 = "สุขสันต์วันเกิดนะ อยากได้ตุ๊กตาหิมะ ลูกอม หนังสือเทพนิยาย หรือต้นกล้าดีล่ะ",
  str_voice_1600101_16 = "ยินดีต้อนรับกลับมา! เธอต้องเหนื่อยแน่เลย กินลูกกวาดเติมพลังก่อนสิ!",
  str_voice_1600101_17 = "ว้าว อรุณสวัสดิ์ ฉันคิดว่าเมื่อวานนี้ฉันฝันถึงเรือบรรทุกลูกกวาดแหละ... แล้วเธอล่ะ",
  str_voice_1600101_18 = "ไปหาที่อุ่น ๆ ที่เราสามารถนั่งกินลูกกวาดแล้วก็อ่านเรื่องราวต่าง ๆ ได้กันเถอะ",
  str_voice_1600101_19 = "หา อะไรเหรอ เธอนอนไม่หลับ? อยากฟังนิทานก่อนนอนไหมล่ะ",
  str_voice_1600101_20 = "นอร์ธแลนด์ ก็เหมือนกับป่าเขาในเทพนิยาย ที่มีสัตว์ในตำนานมากมายหลายประเภทอาศัยอยู่",
  str_voice_1600101_21 = "หืมม... ฉันไม่เคยไปที่อื่นมาก่อนเลย แต่ฉันรู้เรื่องราวของกระท่อมใต้ดินในเรื่องนี้!",
  str_voice_1600101_22 = "มันสร้างขึ้นตอนสิ้นฤดูหนาว",
  str_voice_1600101_23 = "ไอ้นี่ก็ปรากฏในเนื้อเรื่องด้วยนะ น้ำทะเลสีดำที่คืบคลานมาที่นี่ทีละน้อยน่ะ!",
  str_voice_1600101_24 = "โนอาห์ตัวน้อยน่ารักมาก! ขนาดเทพนิยายยังกล่าวถึงเธอเลย เรื่องนั้นฉันอ่านให้เธอฟังใช่ไหมล่ะ",
  str_voice_1600101_25 = "น้องสาวของฉันชอบจ้องมองกระจกแบบเงียบ ๆ เหมือนนาร์ซิสซัสสีขาวในเรื่อง",
  str_voice_1600101_26 = "นิทาน ลูกอม ห่อลูกอม ขนมปังขิงโฮมเมด... ฉันชอบหลายอย่างเลย",
  str_voice_1600101_27 = "หืมม... ฉันไม่ชอบอะไรที่ฉันอธิบายไม่ถูกน่ะ คือฉันไม่สามารถบันทึกได้ แล้วก็ไม่สามารถพูดถึงมันได้",
  str_voice_1600101_28 = "โคลอสซัสดูคล้ายมังกรยักษ์ในเทพนิยายมากกว่านะ ไม่เหมือนมังกรตัวไหนที่ฉันเคยเจอมาก่อนเลย!",
  str_voice_1600101_29 = "เธอดูเหมือนจะผ่านอะไรมามาก เธอจะว่าอะไรไหมถ้าฉันจะให้เธอเป็นตัวเอกในเรื่องราวของฉัน มันอาจกลายเป็นเรื่องที่ขายดีในนอร์ธแลนด์ก็ได้!",
  str_voice_1600101_30 = "กระเป๋าของฉันเกือบเต็มแล้ว!",
  str_voice_1600101_31 = "มันเกิดขึ้นแล้ว! เกิดขึ้นแล้ว! พาเหรดครั้งใหญ่กำลังจะเริ่มต้นแล้ว!",
  str_voice_1600101_32 = "มาร่วมการเดินทางอันน่าทึ่งครั้งนี้เลย!",
  str_voice_1600101_33 = "ความหวังของทุกคนเขียนเอาไว้ในเทพนิยายแล้วด้วยล่ะ!",
  str_voice_1600101_34 = "ส่วนประกอบสำหรับเรื่องใหม่!",
  str_voice_1600101_35 = "เอลฟ์! เพื่อเกียรติยศแห่งองค์ราชินี!",
  str_voice_1600101_36 = "มาสร้างความวุ่นวายกันเถอะ!!",
  str_voice_1600101_37 = "เพื่อดินแดนแห่งเทพนิยาย!",
  str_voice_1600101_38 = "เป็นการเริ่มต้นของความฝันอันแสนวิเศษอีกครั้ง!",
  str_voice_1600101_39 = "เราต้องเห็นคุณค่าของหนังสือนะ!",
  str_voice_1600101_40 = "การทำลายล้างเป็นสิ่งต้องห้าม!",
  str_voice_1600101_41 = "มารวมตัวกันเถอะ ชาวเอลฟ์!",
  str_voice_1600101_42 = "เยี่ยมเลย ฉันจะได้เอาไปเขียนในเรื่องของฉันได้!",
  str_voice_1600101_43 = "เฮ้อ! แบบนี้ไม่สนุกเลย...",
  str_voice_1600101_44 = "ฉันสอนมายากลให้เอาไหม ก่อนอื่นจะเสกกล่องกันก่อน จากนั้นก็เอาลูกกวาดใส่ลงไป",
  str_voice_1600101_45 = "เธอลืมแล้วเหรอ ฉันคือผู้สร้างสรรค์นะ!",
  str_voice_1600101_46 = "นี่คือสิ่งที่ฉันสร้างขึ้นมาไม่ได้! ขอบคุณมากนะ!",
  str_voice_1600101_47 = "ให้ฉันเสกอะไรให้เธอเป็นการตอบแทนไหมล่ะ",
  str_voice_1600101_48 = "ว้าว! ฉันมีความสุขมากเลย ขอบคุณนะ! ขอบคุณมาก! ขอบคุณ!",
  str_voice_1600101_49 = "พี่เลี้ยงลิตาคือครอบครัวเพียงคนเดียวที่เหลืออยู่ของฉัน เธอมักเล่าเรื่องราวตอนเด็กให้ฉันฟังเสมอ มีแต่เรื่องอันตรายทั้งนั้นเลยนะ ฉันเกือบตายไปแล้วด้วย!",
  str_voice_1600101_50 = "แม่กับพ่อไปเดินทางไกลอยู่บ่อย ๆ ฉันได้ยินว่าพวกท่านไปยังที่ไกลแสนไกล ใช่ แล้วพวกท่านก็จะปีนภูเขาหิมะน้ำแข็งด้วยนะ อยากรู้จังว่าพวกท่านจะได้เจอเอลฟ์น้ำแข็งบ้างรึเปล่า",
  str_voice_1600101_51 = "บทที่ไม่ควรปรากฏในเทพนิยายก็ควรถูกลบออกไปซะ... เทพนิยายต้องจบลงด้วยดีเสมอ เรื่องราวของเราก็เหมือนกัน ทุกอย่างต้องจบลงด้วยดี!",
  str_voice_1600101_52 = "Alchemy และ Stars",
  str_voice_1600101_53 = "อ้าว สวัสดี!",
  str_voice_1600101_54 = "โอ้ว... อรุณสวัสดิ์",
  str_voice_1600101_55 = "ฉันมีลูกกวาดจะแบ่งให้เธอ",
  str_voice_1600101_56 = "คือฉันนอนไม่หลับ...",
  str_voice_1600101_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1600111_1 = "ฉันต่อสู้ไปเพื่ออะไรน่ะเหรอ ฉันอิ่มเอมกับความขุ่นเคืองของโลหิตและไฟ แต่ฉันเกรงว่านั่นจะไม่ใช่คำตอบที่เธอต้องการ",
  str_voice_1600111_2 = "ดาบเพลิงสีฟ้าของฉันรื่นเริงไปกับความกลัวของศัตรู แต่สำหรับปีกและเกล็ดมังกรของฉันมันไม่เหมือนกัน เพราะพวกที่มีความชั่วร้ายไม่สามารถจับต้องมันได้",
  str_voice_1600111_3 = "ความเดือดดาลของมังกรมีความคล้ายคลึงหลายอย่างเมื่อเทียบกับทักษะการต่อสู้ที่ฮิอิโระได้ฝึกฝนจนชำนาญ\nทั้งคงกระพัน อันตรายถึงตาย และไร้ความปรานีอย่างสิ้นเชิง\nแต่ถึงอย่างไร ก็ยังเทียบกับจอมทัพไม่ติดอีกหลายขุม...",
  str_voice_1600111_4 = "ฉันจะตัดสินราชาโบราณและเศษซากที่ไม่สะอาดนั่น! เธอไม่ควรมีส่วนเกี่ยวข้องกับของพวกนั้นนะ!",
  str_voice_1600111_5 = "หัวใจของมังกรเต็มไปด้วยความต้องการสังหารที่เก็บกักเอาไว้ อย่าได้ถามว่าทำไมฉันถึงไม่แสดงความเมตตาออกมาเลย เพราะนั่นคือคำจารึกที่หลุมศพของผู้อ่อนแอ",
  str_voice_1600111_6 = "แสงสว่างและเงามืดทำให้เกิดสองด้านของมังกรที่แท้จริง ซึ่งไม่ว่าจะเป็นหรือตายก็จะคำรามอย่างน่าอัศจรรย์! เลือดแห่งการล้างแค้นได้ผงาดขึ้นแล้ว",
  str_voice_1600111_7 = "ใช่แล้ว มีสิ่งอื่นนอกเหนือจากการแก้แค้นที่ยังคงไหลเวียนอยู่ในเลือดของฉัน ขอบคุณนะที่ทำให้ฉันตระหนักในเรื่องนี้ บุคคลสุดท้ายที่ทำได้แบบนี้ก็คือจอมทัพ",
  str_voice_1600111_8 = "ฉันรู้ว่าเนเมซิสและกรอนรูคิดยังไงกับฉัน แต่... อย่างน้อยฉันก็ไม่อยากให้เธอคิดแบบเดียวกัน",
  str_voice_1600111_9 = "เธอนำความหวังมาสู่หัวใจที่เหนื่อยอ่อนดวงนี้ และตอนนี้ฉันก็อยากทำแบบเดียวกันให้เธอ เธอต้องทำได้! เพื่อนร่วมชาติของฉัน!",
  str_voice_1600111_10 = "อันตรายจะเกิดขึ้นเมื่อเราไม่ระมัดระวัง มังกรยักษ์จะลืมตาข้างนึงเสมอเวลาที่มันนอนหลับ",
  str_voice_1600111_11 = "เธอนี่กินเก่งไม่เบาเลยนะ ฉันหวังว่าความกล้าหาญของเธอก็จะท่วมท้นแบบนี้เหมือนกัน",
  str_voice_1600111_12 = "มีอะไรก็ว่ามา ฉันต้องไปทำธุระ มีเวลาไม่มาก",
  str_voice_1600111_13 = "เธอลืมวิธีทักทายคนอื่นแล้วหรือไง เลิกตัวสั่นแล้วก็ยืนนิ่ง ๆ ได้แล้ว!",
  str_voice_1600111_14 = "เธออยากพัฒนาตัวเองเหรอ ดีมาก ฉันจะออกแบบแผนการฝึกฝนให้เธอเอง\nพรุ่งนี้มาที่ห้องฉันตอน 6 โมงเช้านะ!",
  str_voice_1600111_15 = "ฉันควรพูดอะไรสักอย่างกับผู้ที่ไม่ยอมแพ้ในการต่อสู้ ดังนั้นมานั่งกับฉันตรงนี้สิ เพื่อนร่วมชาติของฉัน!",
  str_voice_1600111_16 = "เธอมาแล้ว ทันเวลาพอดี มาหาอะไรทำกันเถอะ เดี๋ยวพอวางแผนและตัดสินใจได้ว่าจะโจมตีเมื่อไหร่ก็ค่อยออกไปนะ",
  str_voice_1600111_17 = "ดีมาก เธอควรใช้เวลาฝึกฝนให้คุ้มค่านะ จะเสียเวลาไม่ได้ มาเริ่มกันเดี๋ยวนี้เลย",
  str_voice_1600111_18 = "ฮึกเหิมเข้าไว้! นี่ยังไม่ถึงเวลาพักผ่อนนะ!",
  str_voice_1600111_19 = "เธอต้องพักผ่อนให้เพียงพอถึงจะแข็งแกร่งขึ้นได้ ไปนอนเถอะ ฉันจะอยู่เฝ้ายามที่นี่เอง",
  str_voice_1600111_20 = "ตอนที่ฉันหลงทาง อิลลูมินาได้แสดงให้ฉันเห็นถึงความเชื่อใหม่ ๆ ที่่ช่วยชีวิตฉันไว้ไม่ให้ถูกความเกลียดชังกลืนกิน",
  str_voice_1600111_21 = "เผ่าของฉันเป็นหนี้เมืองที่ลอยอยู่นั่น สิ่งที่เหลืออยู่คือความผิดหวังและความเกลียดชังที่ไม่อาจอธิบายได้",
  str_voice_1600111_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1600111_23 = "ความเกลียดและการทำลายล้างศัตรูคือความจริงที่ไม่มีข้อกังขาของชีวิต",
  str_voice_1600111_24 = "เธอกล้าหาญและแข็งแกร่ง เธอยืนหยัดในความมุ่งมั่นของตัวเอง ขณะเดียวกันก็ไม่เคยเสียกระบวนเพราะความมุ่งมั่นนั้น ฉันเทียบเธอไม่ติดเลยด้วยซ้ำ",
  str_voice_1600111_25 = "ฉันมองไม่เห็น \"ความมุ่งมั่น\" ของเธอ ฉันอยากรู้จังว่าแมวขี้เกียจจะคิดเรื่องอะไรบ้าง",
  str_voice_1600111_26 = "นอกจากการฝึกฝนแล้ว... นี่คือตราสัญลักษณ์ประจำเผ่าของฉัน มันมอบความแข่งแกร่งให้กับฉัน",
  str_voice_1600111_27 = "ฉันไม่ค่อยสนใจเรื่องหางหรอก ที่ฉันเกลียดจริง ๆ ก็คือระบบที่คดโกงและกฎเกณฑ์ที่โหดเหี้ยม",
  str_voice_1600111_28 = "เธอได้จ้องมองโคลอสซัสนี้บ้างไหม เหมือนที่ฉันชอบจ้องมองตราสัญลักษณ์ประจำเผ่าของฉันน่ะ",
  str_voice_1600111_29 = "เธอไม่เคยเห็นออโรเรียนที่งดงามเท่าฉันเลยเหรอ ก็ได้ ฉันไม่โทษเธอหรอก เพราะอย่างเรานี่ก็มีไม่เยอะจริง ๆ แม้แต่ในอดีตก็เถอะ ชาโรนายินดีรับใช้",
  str_voice_1600111_30 = "วิชาดาบของฉันบริสุทธิ์ยิ่งกว่าเดิมเสียอีก",
  str_voice_1600111_31 = "สายเลือดที่สาบสูญของเผ่าเรากำลังเดือดพล่าน!",
  str_voice_1600111_32 = "เปลวไฟแห่งการล้างแค้นได้รับการจุดขึ้นแล้วที่ดาบของฉัน และในดวงตาของฉัน",
  str_voice_1600111_33 = "ปราสาทเก่าของราชาที่ร่วงโรยจะถูกนำมาหลอมเป็นโลงศพเหล็กอย่างแน่นอน!",
  str_voice_1600111_34 = "ยกมือขึ้น!",
  str_voice_1600111_35 = "ฉันต่อสู้ในร่างจริงของฉันได้ไหม",
  str_voice_1600111_36 = "ฉันต้านไว้ไม่ไหวแล้ว...",
  str_voice_1600111_37 = "มังกรตัวนั้นได้คาดโทษประหารให้กับเธอ!",
  str_voice_1600111_38 = "บดขยี้ในแสงสว่างและเงามืด",
  str_voice_1600111_39 = "ลมหายใจมังกร!",
  str_voice_1600111_40 = "อันตรธาน!",
  str_voice_1600111_41 = "ผู้ที่คัดค้านควรคัดค้านซะเดี๋ยวนี้",
  str_voice_1600111_42 = "ตกต่ำลงสู่ชีวิตแห่งการฆ่า... แต่มันกลับรู้สึกน่ายินดีอย่างไม่น่าเชื่อ",
  str_voice_1600111_43 = "เธอ... ฉันจะต้องเอาคืนให้ได้สักวัน... เธอคู่ควรต่อการล้างแค้นของฉัน!",
  str_voice_1600111_44 = "ฉันเห็นความพยายามของเธอแล้ว ตอนนี้พักก่อนก็แล้วกัน",
  str_voice_1600111_45 = "นี่มัน... โอเค ยังไงก็ขอบคุณนะ",
  str_voice_1600111_46 = "ช่างคิดและน่าชื่นชมมากเลย! ขอบคุณนะ!! เพื่อนร่วมชาติของฉัน!!",
  str_voice_1600111_47 = "ขอบคุณนะที่ทุ่มเกินร้อยเพื่อฉันอีกแล้ว",
  str_voice_1600111_48 = "เพื่อนร่วมชาติของฉัน ฉันจะหวงแหนมิตรภาพนี้เอาไว้ตลอดไป!",
  str_voice_1600111_49 = "ถ้าเผ่าของฉันกลับมา ทุกอย่างที่เธอเห็นอยู่ตอนนี้จะกลายเป็นเศษซากและไม่ควรค่าที่จะพูดถึงอีกต่อไป แต่นั่นแค่การคาดการณ์เฉย ๆ นะ อดีตไม่สามารถเปลี่ยนแปลงได้...",
  str_voice_1600111_50 = "ครอบครัวมังกรคือพยานหลักฐานของยุคแห่งบาปและความโหดเหี้ยม แต่ประวัติศาสตร์ของรัตติกาลสีขาวปฏิเสธที่จะยอมรับในเรื่องนี้ ฉันไม่รู้เหมือนกันว่าตัวเองจะไปอยู่ที่ไหน ถ้าไม่ได้พบกับอิลลูมินาและจอมทัพ...",
  str_voice_1600111_51 = "ว่ากันว่าไฟมังกรจะทำลายทุกสิ่ง รวมถึงความทรงจำและประวัติศาสตร์ของเราด้วย น่าสนใจนะ เหมือนกับที่มดกลัวประกายไฟ คนบาปพวกนี้รับรู้เรื่องราวต่าง ๆ ได้อย่างเกินคาดและน่าอัศจรรย์ขนาดนี้เลยเหรอ",
  str_voice_1600111_52 = "Alchemy Stars!",
  str_voice_1600111_53 = "เพื่อนร่วมชาติของฉัน",
  str_voice_1600111_54 = "เวลาไม่คอยท่านะ ไปกันได้แล้ว",
  str_voice_1600111_55 = "หมดเวลาพักกลางวันแล้ว ฮึกเหิมเข้าไว้!",
  str_voice_1600111_56 = "เวลาใกล้หมดแล้ว ฉันจะพูดให้กระชับนะ",
  str_voice_1600111_57 = "ยินดีด้วย! ปีใหม่มาถึงแล้ว!",
  str_voice_1600191_1 = "คำทำนายสำเร็จแล้ว เราต้องถวายเครื่องบูชาแด่พระเจ้าแห่งสัจธรรม เรียกตัวเนลส์มาก่อนที่เขาจะสำนึกผิดอีกครั้ง",
  str_voice_1600191_2 = "คัมภีร์แห่งความจริงนั้นสมบูรณ์แบบ น่าเสียดายที่ผู้พิพากษากับศาลที่เขาสวามิภักดิ์ไม่ได้สนใจมันเลย",
  str_voice_1600191_3 = "ขายวิญญาณรึ เปล่าหรอก ฉันแค่เอาวิญญาณพวกคนไร้บ้านไปส่งให้ประชาชาติแห่งความจริงน่ะ",
  str_voice_1600191_4 = "เราจำเป็นต้องเสียสละเพิ่มอีกก่อนที่จะเข้าสู่ดินแดนแห่งความจริงได้ แน่นอนว่าเราเชื่อใน \"ความจริง\" ที่แตกต่างกัน",
  str_voice_1600191_5 = "ความหิวกระหายในน้ำทิพย์แห่งชีวิตนั้นเชื่อกันว่าเป็นคุณสมบัติที่ดี แน่นอนว่าการหมกมุ่นที่มากเกินไปย่อมนำไปสู่จุดจบอันรุนแรง",
  str_voice_1600191_6 = "ฟังนะ สุ้มเสียงที่ถูกฝังเพราะบาปของมันจะปรากฏขึ้นมาใหม่ และล้มลงสู่พื้นดินอีกครั้งราวกับดวงอาทิตย์สีแดง จากนี้ไปจะไม่มีผู้ใดที่ไม่ได้รับการช่วยเหลือ!",
  str_voice_1600191_7 = "\"ฉันมีด้านนี้ด้วยเหรอ\" แบบนี้ฉันถือเป็นคำชมได้ไหมเนี่ย",
  str_voice_1600191_8 = "ฉันควรพาเธอไปดูทิวทัศน์ยามค่ำคืนนะ บางทีเธออาจชอบก็ได้ ผู้คนในวัยเยาว์จะรู้สึกตื่นเต้นไปในความมืดเป็นปกติอยู่แล้ว และแสวงหาหนทางที่จะมีชัยตลอดเวลา",
  str_voice_1600191_9 = "อารมณ์มันรุนแรงขึ้นแล้ว นี่ใช่ไหมที่เธอต้องการ กำแพงมีหูนะรู้ไหม และนี่อาจทำให้เกิดความริษยาขึ้นได้ถ้าเธอไม่ระวัง",
  str_voice_1600191_10 = "ฉันมองเห็นได้ว่าเธอพยายามแล้ว ปล่อยให้ฉันจัดการทุกอย่างที่นี่เองเถอะ... ตราบใดที่เธอสามารถก้าวตามรอยเท้าฉันได้ในท้ายที่สุด การอดทนชั่วครู่จะไม่ส่งผลเสียหรอก...",
  str_voice_1600191_11 = "เธอดูสนใจสัตว์ดึกดำบรรพ์เป็นพิเศษเลยนะ... ไม่เป็นไรหรอก ช่วย... ใช้เวลากับฉันเพิ่มขึ้นทีนะ",
  str_voice_1600191_12 = "ฉันค่อย ๆ สอนเธอได้นะ แต่จนกว่าจะถึงเวลานั้น เธอต้องตั้งใจให้มากเพื่อเอาใจฉัน",
  str_voice_1600191_13 = "อยากฟังเรื่องหลักการแห่งความจริงไหมล่ะ เราอุทิศตนให้กับการสอนสั่งด้วยความอดทนเสมอ...",
  str_voice_1600191_14 = "อยากฟังอะไรพิเศษ ๆ ไหมล่ะ เรื่องราวเกี่ยวกับบุคคลอมตะที่ไม่แก่และไม่ตายน่ะ...",
  str_voice_1600191_15 = "ฉันขออวยพร คนรุ่นเยาว์ มาดื่มน้ำทิพย์ถ้วยนี้ที่ฉันปรุงให้และมีตัวตนอยู่ร่วมกับฉันไหมล่ะ",
  str_voice_1600191_16 = "คนเรามักจะรู้สึกเฉื่อยชาที่เวลาเที่ยงตรงเสมอแหละ... แน่นอนว่าเธอไม่ต้องกังวลเรื่องฉันหรอก",
  str_voice_1600191_17 = "สำหรับสิ่งมีชีวิตบางชนิด นี่คือเวลาพักผ่อนแล้ว... เธออยากมากับฉันไหมล่ะ",
  str_voice_1600191_18 = "เมื่อฉันค่อย ๆ ตื่นขึ้นมา ฉันมักรู้สึกอยากดื่มด่ำกับ... คำทักทายที่อบอุ่นของเธอสักแก้วน่ะ",
  str_voice_1600191_19 = "ป่านนี้ยังไม่นอนอีก ท่าทางเธอก็เป็นวิหคราตรีเหมือนกันนะ",
  str_voice_1600191_20 = "เธอควรเข้าใจนะว่าความจริงคือหนทางสู่อนาคต และการนำทางที่ถูกต้องจะนำมาซึ่งเสถียรภาพ",
  str_voice_1600191_21 = "ความดีและความชั่วร้ายคือโฉมหน้าแห่งลูโมโพลิสที่มันแสดงให้ผู้คนได้เห็น และวันแห่งการพิพากษาจะเผยความจริงที่โหดร้ายออกมา",
  str_voice_1600191_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1600191_23 = "เมื่อฉันยืนยันว่าพวกเขาก็ถูกสร้างขึ้นมาด้วยโลกนี้เหมือนกัน ฉันรับรู้ได้ถึงความจริงจากทั้งสองฝ่าย",
  str_voice_1600191_24 = "เฟาสต์เป็นผู้เผยแพร่ความคิดชั้นเลิศ เขาไม่ได้อยู่ในบังคับบัญชาของฉันเมื่ออยู่ต่อหน้าความจริง",
  str_voice_1600191_25 = "ฉันไม่ได้เกลียดคนดื้อดึงนะ สำหรับฉันแล้ว มันเหมือนพูดคุยกับก้อนหิน และฉันก็ชอบมากเลย",
  str_voice_1600191_26 = "น้ำทิพย์แห่งชีวิต หนังสือโบราณ และอาวุธที่เรียกว่า \"เรลิก\"... พวกนี้ฉันชอบมากเลย",
  str_voice_1600191_27 = "ไม่มีอะไรที่ฉันเกลียดจริง ๆ หรอก เพราะความจริงย่อมยอมรับความเท่าเทียมทั้งปวง",
  str_voice_1600191_28 = "สำหรับฉันแล้ว มันคือไม้ท่อนใหญ่ ๆ ที่เชื่อมต่อการเข้าถึง เช่นเดียวกับแก่นดึกดำบรรพ์ที่ใกล้ชิดกับรากเหง้า",
  str_voice_1600191_29 = "คนเขาก็มีความรู้สึกและความทรงจำของตัวเองอยู่ในสายเลือด... อื้ม ก่อนหน้านี้ฉันอยากรู้ \"รสชาติ\" ของเธอจริง ๆ",
  str_voice_1600191_30 = "นี่คือพลังชีวิตที่สดใหม่!",
  str_voice_1600191_31 = "ฉันพบแล้ว หนทางที่จะก้าวพ้นขีดจำกัดของชีวิต...",
  str_voice_1600191_32 = "ฉันจะต้องกลายเป็นบุคคลที่สูงส่งยิ่งขึ้น...",
  str_voice_1600191_33 = "ในนามแห่งราชินีโลหิต ฉันจะเข้าสู่ท้องพระโรงสีเลือดอันยิ่งใหญ่...",
  str_voice_1600191_34 = "ความจริงจะมีผลกระทบล้ำลึกยิ่งกว่านั้น",
  str_voice_1600191_35 = "ฉันเพียงแค่ต้องการโอกาส",
  str_voice_1600191_36 = "ทำตามคำแนะนำ...",
  str_voice_1600191_37 = "สีเลือด! หนาม! เรเควียม!",
  str_voice_1600191_38 = "จงเป็นพยานปาฏิหาริย์!",
  str_voice_1600191_39 = "จงฟังความจริง!",
  str_voice_1600191_40 = "จงสัมผัสความจริง!!!",
  str_voice_1600191_41 = "หลบไปซะ ไม่งั้นเจ็บตัวแน่",
  str_voice_1600191_42 = "รสชาติแห่งชัยชนะนั้นดีพอ ๆ กับชีวิตที่สดใหม่",
  str_voice_1600191_43 = "ฉันง่วงแล้ว ไว้พอจะมั่นใจขึ้นมาบ้างแล้วค่อยปลุกฉันนะ",
  str_voice_1600191_44 = "การได้เห็นเธอมีชีวิตอยู่เท่านั้นที่ทำให้ฉันมีความสุขได้...",
  str_voice_1600191_45 = "เธอเอาของเล่นใหม่มาให้ฉัน น่ารักจังเลย อุตส่าห์คิดถึงกัน",
  str_voice_1600191_46 = "เธอนี่รู้ใจฉันจริง ๆ เลยว่าฉันชอบอะไร อะไรนะ เธออยากได้รางวัลเหรอ",
  str_voice_1600191_47 = "แน่นอนว่าฉันจะรับไว้ นี่คือการเสียสละที่สำคัญของเธอ...",
  str_voice_1600191_48 = "เพื่อเป็นรางวัล ฉันจะเตรียมอะไรพิเศษ ๆ ให้เธอนะ...",
  str_voice_1600191_49 = "การอยู่ร่วมกันของเกียรติยศแห่งชัยชนะและการมีอยู่ของผู้ล่า แม้เพียงเล็กน้อยก็จะต้องได้รับการป้องกันไม่ให้เกิดขึ้นได้... แต่ฉันคิดว่ามันอาจยากเกินกว่าที่เธอจะเข้าใจ",
  str_voice_1600191_50 = "สายเลือดเป็นเพียงแค่สิ่งกระตุ้นที่นำทางฉันไปสู่เส้นทางแห่งการแสวงหา มันต้องมีความหมายสิที่ความจริงได้มอบพรแห่งความเป็นอมตะและความเสื่อมสลายให้กับฉัน",
  str_voice_1600191_51 = "แวมไพร์เหรอ เปล่าเลย ฉันไม่ได้เกิดมาเป็นแวมไพร์ มันคือพรสวรรค์ ตำราสีดำได้เปลี่ยนสิ่งนี้ให้เป็นเสียงกระซิบ ก้องกังวานอยู่ในหูของเหล่าผู้ที่ได้รับเลือก",
  str_voice_1600191_52 = "Alchemy Stars",
  str_voice_1600191_53 = "เอ่อ...",
  str_voice_1600191_54 = "ฉันควรพูดว่าอรุณสวัสดิ์ใช่ไหม",
  str_voice_1600191_55 = "สวัสดียามบ่าย เธอควรผ่อนคลายสักหน่อยนะ",
  str_voice_1600191_56 = "รู้สึกง่วงเหรอ",
  str_voice_1600191_57 = "ปีใหม่นี้เป็นของเธอนะ",
  str_voice_1600251_1 = "ฮึ่ม... ความเดียวดายของจิตวิญญาณและศิลปะที่แท้จริงคือสิ่งที่น้อยคนจะสามารถเข้าใจได้ ศิลปินทั้งหมดล้วนเปลี่ยวเหงา และฉันก็ทำงานกับคนอื่น ๆ ได้ไม่ดีเสียด้วย...",
  str_voice_1600251_2 = "อ๊าก ฉันยุ่งมากเลย อยากดูละครเพลงเหรอ? ชวนคนมาเยอะแยะเลย? จริงเหรอเนี่ย?\nถ้าอย่างนั้น ฉันจะยกเว้นให้สักครั้งแล้วแสดงอีกรอบนะ",
  str_voice_1600251_3 = "มีคนร้องเรียนเรื่องเสียงดังจากเรางั้นเหรอ ใครกันที่บ่นว่าเพื่อนยากของฉันเสียงดัง ต้องเป็นคนทั่วไปที่มีรสนิยมย่ำแย่แน่นอนเลย",
  str_voice_1600251_4 = "ดูนี่ เพียงแค่ฉันตะโกนว่า \"สัมผัสความน่ากลัวของรถไฟจากนรก!\" แล้วเพื่อนยากของฉันก็จะรีบพุ่งออกมา เธออยากเห็นไหมล่ะ",
  str_voice_1600251_5 = "ความสงบสุขจะยังคงหลบหนีฉันได้ตลอดไป มันคือคำสาปอันไร้ที่สิ้นสุด และเป็นเทศกาลเฉลิมฉลองของความเปลี่ยวเหงา...",
  str_voice_1600251_6 = "ตั้งใจหน่อยสิ! นี่คือการแสดงที่ยิ่งใหญ่ที่สุดของฉันเลยนะ! คารอน รถไฟสู่ยมโลก และจิตวิญญาณนับไม่ถ้วนที่กระหายอยากชมการแสดงที่เต็มไปด้วยชีวิต ได้กลับมาจากนรกแล้ว!",
  str_voice_1600251_7 = "โปรดรอสักครู่... นี่น้ำชาและขนมของเธอ ผู้ชมที่รัก กรุณากลับสู่ที่นั่งของท่าน!",
  str_voice_1600251_8 = "เธอหนีไปคนเดียวอย่างรวดเร็วและไกลมาก ทำไมเธอไม่พาฉันไปด้วย เธอก็รู้ว่าฉันจะอยู่ข้างเธอเสมอ ไม่ว่าเธอจะเป็นอะไรหรือทำอะไร...",
  str_voice_1600251_9 = "คืนวันที่ฉันได้อยู่กับจอมทัพเป็นช่วงเวลาที่ฉันมีความสุขที่สุดในชีวิต และฉันรู้สึกว่าฉันได้รับการไถ่บาป... พอฉันได้มาเจอกับเธอ คัมภีร์แห่งโชคชะตาก็สมบูรณ์",
  str_voice_1600251_10 = "\"บรรดาผู้ที่มาถึงจุดสิ้นสุดของโชคชะตา ต่างดิ้นรน ตะโกน จงแสดงให้เห็นใบหน้าที่เต็มไปด้วยความตื่นตระหนก... \" อืม ตรงนี้แปลกไปหน่อย",
  str_voice_1600251_11 = "เปิดม่านแห่งค่ำคืนที่มืดมิดด้วยความเพ้อฝัน แล้วฉันจะนำทางเธอไปสู่แสงสว่าง ฉันยืนอยู่ที่นี่ตลอดไปเลยได้ไหม",
  str_voice_1600251_12 = "สิ่งเดียวที่ฉันต้องการก็คือรถไฟสู่ยมโลก สหายคนอื่น ๆ... ฉันไม่มีก็ได้",
  str_voice_1600251_13 = "ผู้คนจะทิ้งฉันไปด้วยเหตุผลที่แตกต่างกันเสมอ พากันลงเมื่อถึงสถานีที่เป็นจุดหมายของตนเอง...",
  str_voice_1600251_14 = "รถไฟสู่ยมโลกดูจะชอบเธอมาก ถ้าอย่างนั้น ฉันจะจองที่ไว้ให้เธอบนเวทีนะ!",
  str_voice_1600251_15 = "นี่คือคืนเปิดตัวสำหรับการแสดงของฉัน และเธอก็คือตัวเอก! ไม่ต้องอาย เต้นเลย! ฮ่าฮ่า!",
  str_voice_1600251_16 = "รถไฟปีศาจยินดีรับใช้",
  str_voice_1600251_17 = "จริงเหรอ เธอตื่นแต่เช้าตรู่เพื่อจัดเตรียมเวทีให้ฉันด้วยความประณีตโดยเฉพาะเลยเนี่ยนะ",
  str_voice_1600251_18 = "เราขึ้นเวทีถัดไปกันแล้ว! มาสิ! มาด้วยกัน!",
  str_voice_1600251_19 = "เธอมาทันเวลาพอดี รถไฟปีศาจกำลังจะออกเดินทาง ขึ้นได้เลยถ้าเธออยากไปยังอีกฟากหนึ่ง!",
  str_voice_1600251_20 = "โชคชะตาของเราผูกพันอยู่กับอิลลูมินา เรามาที่นี่สองครั้งแล้ว และตอนนี้มันก็เป็นที่ที่เราจะเรียกว่าบ้านไปชั่วนิรันดร์",
  str_voice_1600251_21 = "การไล่ตามไม่ใช่อะไรนอกจากการแสดงถึงการระแวดระวังของคนเรา สิ่งที่กำหนดไว้แล้วไม่จำเป็นว่าต้องเป็นความจริง",
  str_voice_1600251_22 = "ขออิลลูมินา...จงเจิดจำรัส!",
  str_voice_1600251_23 = "เราผู้กลับมาจากนรก จะต้องพบกับความกลัวของเราแบบซึ่งหน้า",
  str_voice_1600251_24 = "ฉันไม่กล้าออกความเห็นเรื่องเธอหรอก เพราะว่าฉันแพ้จริง... แต่ถ้าเป็นเรื่องการควบคุมรถไฟแล้วละก็...",
  str_voice_1600251_25 = "การดูแลทุกอย่างให้เรียบร้อยและออกเดินทางไปตามถนนที่เปลี่ยวเหงาโดยไม่ลังเล นี่คือลักษณะของคนที่เกิดมาเพื่อเป็นผู้นำ",
  str_voice_1600251_26 = "เวทีที่เปลี่ยวเหงา ชีวิตที่อิสระ และการเดินทางด้วยรถไฟร็อกแอนด์โรล พวกนี้คือสิ่งที่ฉันหลงรัก!",
  str_voice_1600251_27 = "ไม่มีพื้นที่ให้พวกบ้าไร้รสนิยมในชีวิตของศิลปินหรอก",
  str_voice_1600251_28 = "เหมือนกับฉันแล้วก็รถไฟสู่ยมโลก โคลอสซัสนี้คือคู่หูของเธอใช่ไหม",
  str_voice_1600251_29 = "ฉันคือผู้ควบคุมเรือข้ามฟากแห่งจิตวิญญาณชั่วร้ายและยมโลก ฉันไม่ใช่โครงกระดูกแห่งนรกหรือสาวกแห่งแสงสว่าง ฉันคือคารอน และฉันเดินทางไปอย่างไร้ความหวาดกลัวในโลกที่เปื้อนไปด้วยโลหิต",
  str_voice_1600251_30 = "เร่งหน่อย!",
  str_voice_1600251_31 = "เรากำลังจะไปถึงแม่น้ำสติกซ์",
  str_voice_1600251_32 = "รถไฟสู่ยมโลกได้ออกเดินทางแล้ว!",
  str_voice_1600251_33 = "นี่คือรถไฟของคนตาย! ฮ่าฮ่า!",
  str_voice_1600251_34 = "ฉันไม่เคยคิดเลยว่าจะมีโอกาส...",
  str_voice_1600251_35 = "เอาเสียงนกหวีดแสบแก้วหูไปฟังซะ!",
  str_voice_1600251_36 = "เดินหน้าเต็มกำลัง!",
  str_voice_1600251_37 = "มุ่งหน้าสู่นรก! กำลังเดินทาง!",
  str_voice_1600251_38 = "คนตาย! จะต้องหลีกไป!",
  str_voice_1600251_39 = "ทดสอบพลัง!",
  str_voice_1600251_40 = "สัญญาณเพลิงนรก!",
  str_voice_1600251_41 = "ส่องไฟมาที่ฉัน! ตัวเอกจะขึ้นเวทีล่ะ!",
  str_voice_1600251_42 = "เรามาจากนรก การแพ้นั้นจึงเป็นไปไม่ได้",
  str_voice_1600251_43 = "วิ่งเลย! จับมือฉัน!",
  str_voice_1600251_44 = "เธออยากดูองก์ต่อไปของละครไหม เถอะน่า อยากดูก็บอกมา!",
  str_voice_1600251_45 = "ฉันคิดว่าครั้งล่าสุดที่ฉันได้รับของขวัญคือเมื่อศตวรรษที่แล้ว...",
  str_voice_1600251_46 = "โหหห! นี่คือของขวัญจากดวงวิญญาณของพี่น้องเหรอ",
  str_voice_1600251_47 = "การให้ของขวัญช่างเป็นฉากที่ซึ้งเหลือเกิน!",
  str_voice_1600251_48 = "วิเศษมากเลย นี่คือของขวัญจากเพื่อนรักของฉัน!",
  str_voice_1600251_49 = "จะเกิดอะไรขึ้นถ้าเธอถูกเข้าใจผิดและต้องห่างเหินกับเพื่อนเก่า ปล่อยให้แต่ละวันหมดไปกับการดื่มไวน์โดยไม่ต้องกังวลเรื่องคนอื่นจะดีกว่านะ",
  str_voice_1600251_50 = "ฉันจะไม่มีวันลืมใบหน้าของแม่ฉันที่อยู่เบื้องหลังหน้าต่างนั่น... ฉันสามารถมองดูแม่ได้โดยไม่รู้สึกเลยว่าเวลาได้ดำเนินไปเรื่อย...",
  str_voice_1600251_51 = "ครอบครัวของฉันเคยตามใจฉันมาก แต่ตอนนั้นพวกเขาไม่เข้าใจว่ารถไฟสู่ยมโลกก็เป็นครอบครัวของฉันเหมือนกัน การตัดสินใจที่เกิดขึ้นในเวลาที่ยากลำบากนั้นคือโชคชะตาที่วางแผนต่อต้านพวกเรา...",
  str_voice_1600251_52 = "Alchemy...Stars!",
  str_voice_1600251_53 = "สวัสดีเพื่อน ๆ ของฉัน!",
  str_voice_1600251_54 = "ช่างเป็นยามเช้าที่งดงาม!",
  str_voice_1600251_55 = "ช่วยตั้งใจด้วย!",
  str_voice_1600251_56 = "ได้เวลาแสดงแล้ว!",
  str_voice_1600251_57 = "นี่... นี่คือเสียงของปีใหม่!",
  str_voice_1600261_1 = "ชีวิตที่เกิดมาในโลงศพที่ลุกเป็นไฟ เร่ร่อนในดินแดนรกร้าง ดูแขนขาที่พิกลพิการนั่นสิ ไม่มีความยุติธรรมเอาเสียเลย ไม่มีความหมายอะไรทั้งนั้น",
  str_voice_1600261_2 = "ฉันเคยเห็นมันเผาผลาญอารยธรรมจนสิ้นซากมาแล้ว ใช่ เจ้าสิ่งที่อยู่ใต้เท้าของเธอนั่นแหละ เธออาจมีความสามารถในการชำระล้างบาปจริง ๆ ก็ได้นะ",
  str_voice_1600261_3 = "ไม่ต้องมาปลอบใจฉันเลย เพราะว่าฉันไม่ได้เศร้าอะไร อย่ามาให้ความสนใจฉันแบบผิวเผินเหมือนคนอื่น ๆ ขอร้องว่าอย่า ปล่อยฉันไว้คนเดียวก็พอ",
  str_voice_1600261_4 = "ผิวและใบหน้าของฉันหายดีแล้ว ฉันคือสิ่งมีชีวิตที่สวนทางกับกระแสน้ำ ถึงอย่างนั้นก็เถอะ ร่างกายที่พังทลายแล้วครั้งหนึ่งของฉันจะมีรอยร้าวไปตลอดกาล...",
  str_voice_1600261_5 = "วันสิ้นโลกได้ทำร้ายฉัน เหมือนกับหนามไผ่ที่ตอกเข้าสู่ซอกเล็บ แม้กระทั่งตอนนี้ มันก็ยังกดแน่นอยู่ในอก เว้นแต่ว่ามันจะดันจากด้านในออกสู่ด้านนอก...",
  str_voice_1600261_6 = "ปะป๊า หม่าม้า... แม้ร่างกายของฉันจะบอบช้ำอย่างหนักด้วยบาดแผลและความเจ็บปวด แต่ตอนนี้ฉันมีเหตุผลที่จะต่อสู้ต่อไปแล้ว... ได้โปรดเก็บกอดฉันไว้ต่อไป จนกว่าจะถึงวันที่เราได้กลับมาพบกันอีก...",
  str_voice_1600261_7 = "อยากฟังเรื่องเก่า ๆ ไหม ว่าฉันตายยังไงและลงนรกไปได้ยังไง",
  str_voice_1600261_8 = "ในอกของฉันคือบ่อน้ำ มันคือคุกแห่งเปลวไฟที่เผาผลาญชั่วนิจนิรันดร์ สร้างความเจ็บปวดลึกเข้าไปถึงกระดูก เธอรู้ไหมว่าอะไรที่ล็อกอยู่ภายใน เธออยากฉีกมันให้เปิดออกแล้วดูข้างในไหมล่ะ",
  str_voice_1600261_9 = "เข้ามาใกล้ ๆ สิ นอนแนบอกของฉัน ได้ยินไหม นั่นคือเสียงของเปลวไฟในอดีต... เอาละ ถอยไปซะ ก่อนที่เธอจะตกนรกไปด้วย",
  str_voice_1600261_10 = "ฉันอยู่ในสถานะที่ไร้ตัวตนอีกแล้ว ไม่นะ นี่อาจเป็นสถานะปกติของชีวิตก็ได้ เหมือนกับที่ป้า ๆ น้า ๆ บางคนชอบอยู่ในกรงเล็ก ๆ บางทีฉันอาจถูกกำหนดว่าต้องมาคุดคู้ในนี้แล้วก็คุยกับตัวเองก็ได้",
  str_voice_1600261_11 = "ฉัน... ฉันไม่ได้ต่อต้านการอยู่ที่นี่หรอกนะ สายตาของเธอไม่เหมือนของคนอื่น ๆ เพราะมันไม่ได้ให้ความรู้สึกเสแสร้งสุดทิ่มแทง",
  str_voice_1600261_12 = "คงจะดีนะถ้าฉันได้อยู่ในถังนี่ตลอดไป... ฉันจะได้ไม่ต้องได้ยินเสียงโอดครวญหรือกรีดร้องนั่นอีก",
  str_voice_1600261_13 = "อีกหนึ่งงานที่น่าเบื่อ... ฉันหวังว่าจะไม่มีใครคอยมาคุมนะ...",
  str_voice_1600261_14 = "มีใครพูดอะไรรึเปล่า... หรือว่าฉันได้ยินเสียงไปเองอีกแล้ว",
  str_voice_1600261_15 = "ถ้างั้นวันนี้ก็คือวันที่เธอจะเกิดใหม่สินะ... มันจะเจ็บรึเปล่า ถ้าไม่เจ็บก็จะเยี่ยมมากเลย",
  str_voice_1600261_16 = "เธอมาที่นี่อีกแล้ว เธอมาตรงเวลาเสมอเลย ไม่เหมือนความตายที่จู่ ๆ ก็มาแบบไม่เตือนล่วงหน้า",
  str_voice_1600261_17 = "นี่มีวันใหม่อยู่เบื้องหน้าฉันอีกแล้วเหรอ เป้าหมายของการได้รับประสบการณ์ทั้งหมดนี้คืออะไรกันนะ...",
  str_voice_1600261_18 = "คุกแห่งเปลวไฟสงบลงเล็กน้อยแล้วในตอนนี้... แต่ยังคงมีเสียงที่รุนแรงกว่าตามมาอีก",
  str_voice_1600261_19 = "ในชั่วโมงนี้... ผู้ที่ควรนอนหลับก็นอนหลับอยู่ และผู้ที่ควรตื่นก็ตื่นแล้ว... ฉันเจ็บหน้าอกจัง",
  str_voice_1600261_20 = "มันคือดินแดนที่เกิดขึ้นใหม่อีกครั้งในเปลวไฟ... มันเป็นสีขาว เหมือนกับที่มันเป็นในความทรงจำของฉัน",
  str_voice_1600261_21 = "ก่อนที่ทุกสิ่งจะจบลง ฉันจำได้ว่าเห็นคน ๆ หนึ่งสวมชุดยาว... ฉันไม่ได้เอ่ยปากขอบคุณให้ทันเวลา...",
  str_voice_1600261_22 = "รัตติกาลสีขาว... ขอเทิดทูน",
  str_voice_1600261_23 = "สิ่งที่มาจากนรก... ควรหวนคืนสู่นรก",
  str_voice_1600261_24 = "ฉันเผาชุดของป้าและกิ่งไม้โดยไม่ตั้งใจ... มันคงทำให้เธอลำบากใจมาก... ฉันเสียใจ",
  str_voice_1600261_25 = "มันคือเสียงฟ้าร้องและฟ้าผ่า... แต่แววตาของเธอนั้น... บอกฉันว่าทุกอย่างปกติดี",
  str_voice_1600261_26 = "ฉันชอบนะ... แต่ฉันไม่เข้าใจ... คงจะดีมากถ้าฉันได้ปล่อยใจให้ลอยไปชั่วครู่โดยไม่คิดเรื่องใดทั้งสิ้น",
  str_voice_1600261_27 = "ฉันไม่เข้าใจ... ความหมายของการมีตัวตนอยู่คืออะไร อะไรคือ... ความหมาย",
  str_voice_1600261_28 = "พลังงานภายในโคลอสซัสและเปลวไฟแห่งนรกที่นี่มัน... คุ้น ๆ อยู่นะ",
  str_voice_1600261_29 = "ฉันชื่ออูริเอล ฉันก็แค่เผาชีวิตไปอย่างไร้จุดหมายน่ะ เธอจะลองมอบเป้าหมายให้ร่างกายของฉันก็ได้นะ แต่ว่าอย่าหวังอะไรมาก",
  str_voice_1600261_30 = "ยังคงใช้ความพยายามที่ไร้ประโยชน์อยู่",
  str_voice_1600261_31 = "ค-ความเจ็บปวด... มันเริ่มควบคุมไม่ได้...",
  str_voice_1600261_32 = "นี่คือพลังหรือคำสาป!?",
  str_voice_1600261_33 = "อย่ามองฉันแบบนั้น! นี่มันนรกนะ!!",
  str_voice_1600261_34 = "ทุกคน ออกไปห่าง ๆ ฉัน",
  str_voice_1600261_35 = "ขุมนรกเต็มแล้ว",
  str_voice_1600261_36 = "อกฉันจะระเบิดแล้ว",
  str_voice_1600261_37 = "หายนะจะเป็นที่ประจักษ์อีกครั้ง...",
  str_voice_1600261_38 = "เส้นทางที่จะนำไปสู่นรกขุมใหม่...",
  str_voice_1600261_39 = "จงรับการชำระให้บริสุทธิ์",
  str_voice_1600261_40 = "ไปยังความว่างเปล่า...",
  str_voice_1600261_41 = "ฉันเกรงว่าแม้แต่เถ้าถ่านก็จะไม่เหลือ...",
  str_voice_1600261_42 = "ฉันอิจฉาดวงวิญญาณที่ได้รับการปลดปล่อยจัง",
  str_voice_1600261_43 = "เป็นไปได้ไหมว่าจะมีนรกที่ใหญ่กว่าซึ่งมีนรกอยู่ข้างในอีกที",
  str_voice_1600261_44 = "ไม่กลัวพลังของนรกเหรอ น่าประทับใจ...",
  str_voice_1600261_45 = "... เธอให้ของนี่แก่ฉันทำไมเหรอ",
  str_voice_1600261_46 = "เอ๊ะ ดูน่าสนใจนะ",
  str_voice_1600261_47 = "ขอโทษที นี่... ฉันไม่แน่ใจว่าฉันชอบน่ะ",
  str_voice_1600261_48 = "โอ้ว จะว่าไป... ฉันก็ชอบนะ ขอบใจมาก",
  str_voice_1600261_49 = "ฉันเกิดมาในโลงศพที่มีไฟลุกไหม้ และเดินเร่ร่อนอยู่ในดินแดนอันว่างเปล่านี้ ตอนนี้ฉันอาศัยอยู่ในกรงที่เรียกว่ารัตติกาลสีขาว",
  str_voice_1600261_50 = "เราทั้งหมดอาจจะตายไปแล้วในวันที่สงครามเริ่มต้นขึ้นก็ได้ และทุกอย่างที่เราเห็นก็คือฟองอากาศก่อนที่ดวงวิญญาณของเราจะถูกทำลายไป แบบนั้นคงน่าเบื่อแย่เลย",
  str_voice_1600261_51 = "ฉันไม่เคยมองย้อนกลับไป เพราะฉันเคยตายไปแล้ว หนึ่งครั้ง สองครั้ง ไม่สิ นับไม่ถ้วนเลยละ ฉันกลายเป็นหนึ่งเดียวกับนรก ไม่เคยอยู่ห่างจากนรกเลย",
  str_voice_1600261_52 = "Alchemy... Stars",
  str_voice_1600261_53 = "เฮ้...",
  str_voice_1600261_54 = "เฮ้... เธออยู่รึเปล่า",
  str_voice_1600261_55 = "เธอ... เธอพอมีเวลาไหม",
  str_voice_1600261_56 = "ดึกแล้ว แต่เธอยังอยู่เหรอเนี่ย...",
  str_voice_1600261_57 = "ปีใหม่... ที่ไม่สุขสันต์",
  str_voice_1600271_1 = "ได้ยินเสียงเรียกจากหัวใจฉันไหม ยังไงก็หนีไม่พ้น ฉันจะรักษาสายสัมพันธ์นี้เอาไว้",
  str_voice_1600271_2 = "ฟ้าร้องกับฟ้าผ่านี่ทำให้หลายคนกลัว และคนจำนวนมากก็ปฏิเสธที่จะฟังคำพูดจากภายใต้หน้ากากของฉัน แต่เธอไม่เหมือนคนอื่นนะ ผู้นำทาง",
  str_voice_1600271_3 = "...เธอไม่จำเป็นต้องกังวลเรื่องความภักดีของฉันหรอก ถึงแม้ว่าฉันจะเคยทรยศคนมากมายในอดีต ถ้าคาร์ลีนได้ตัดสินใจแล้วว่าจะเชื่อใจเธอ งั้นฉันเองก็จะไม่มีความคิดที่จะไม่ซื่อสัตย์เป็นเรื่องธรรมดา",
  str_voice_1600271_4 = "ฉันจำอะไรบางอย่างได้จากในอดีต แต่มันไม่ใช่เรื่องราวเหมือนมิคาเอล นอกจากนี้ตอนนี้ยังไม่ใช่เวลาที่เหมาะจะคุยกันด้วย",
  str_voice_1600271_5 = "เสียงฟ้าร้องดังขึ้นยิ่งกว่าเดิม กึกก้องอยู่ในศีรษะและร่างกายของฉัน อย่างไรก็ดี หนทางข้างหน้าของฉันนั้นชัดเจนกว่าที่เคย และฉันจะไม่ลังเลเหมือนเมื่อก่อนอีกต่อไปแล้ว",
  str_voice_1600271_6 = "ฉันจะใช้พลังของฉันเพื่อรักษาความเรียบร้อยและเปลี่ยนแปลงโลกด้วยกฎระเบียบ มันต้องเป็นแบบนี้นับจากนี้ไปและในอนาคต ฉันดีใจนะที่เธอเดินมาตามเส้นทางนี้ด้วยกันกับฉันจนถึงตอนนี้ ขอบคุณนะ",
  str_voice_1600271_7 = "ฉันเข้าใจว่ามันไม่ง่ายเลยที่จะสร้างความสัมพันธ์กับใครสักคนที่พูดไม่ได้ ฉันจะหวงแหนมันเอาไว้นะ",
  str_voice_1600271_8 = "ขอบคุณสำหรับความพากเพียรนะ ผู้นำทาง โปรดอภัยให้ฉันด้วยถ้าเสียงจากหัวใจของฉันจะมีขึ้นมีลงไปบ้างในบางครั้ง เพราะนี่เป็นแค่การดึงเอาความทรงจำบางส่วนจากอดีตกลับคืนมา",
  str_voice_1600271_9 = "ฉันอยากมีปฏิสัมพันธ์ให้มากกว่านี้นะ แต่ฉันอาจไม่สามารถทำสำเร็จภายใต้สถานะปัจจุบันของฉัน... เท่านี้ฉันก็โชคดีมากแล้วที่เธอสามารถฟังถ้อยคำที่ไร้เสียงของฉันได้ ดังนั้นฉันจะไม่ขออะไรมากไปกว่านี้",
  str_voice_1600271_10 = "ฉันควรช่วยเพิ่มความสดใสให้เจ้าคนนี้ไหม... อ๋อ ขอโทษที ฉันลืมไปว่าเธอก็ได้ยินฉันเหมือนกัน",
  str_voice_1600271_11 = "ควบคุมดูแล ตรวจสอบปรับปรุง แก้ไขให้ถูกต้อง แล้วก็ดำเนินการ ให้ฉันเริ่มงานเมื่อไหร่ล่ะ",
  str_voice_1600271_12 = "ผู้ที่มีโชคชะตาเดียวกันกับฉันเท่านั้นที่สามารถได้ยินเสียงนี้",
  str_voice_1600271_13 = "หืมม? เมื่อกี้ฉันทำสมาธิอยู่เลยไม่เห็นเธอน่ะ ขอโทษที",
  str_voice_1600271_14 = "เธอไม่กลัวที่จะเข้าใกล้ฉันเหรอ ...หรือว่าเธอก็เหมือนกับราฟาเอลที่ไม่กลัวไฟฟ้าช็อต",
  str_voice_1600271_15 = "วันนี้เป็นวันสำคัญสำหรับเธอ ดังนั้นมาฉลองกันเถอะ เธอสนใจอะไรล่ะ",
  str_voice_1600271_16 = "สวัสดี ผู้นำทาง มีคำสั่งใหม่ ๆ บ้างไหม",
  str_voice_1600271_17 = "อรุณสวัสดิ์ ฉันได้ทำทุกอย่างตามที่เธอสั่งให้ฉันทำตอนที่เธอเข้านอนแล้ว กำลังรอคำสั่งใหม่ ๆ อยู่นะ",
  str_voice_1600271_18 = "ผู้นำทาง ไม่ต้องห่วงเพราะว่าฉันเตรียมพร้อมอยู่แล้ว และฉันก็พร้อมรับคำสั่งของเธอได้ทุกเมื่อ",
  str_voice_1600271_19 = "สายัณห์สวัสดิ์ แล้วก็ไม่ต้องห่วงนะ เพราะฉันพร้อมรับคำสั่งของเธอตลอดเวลาอยู่แล้ว... ฉันจำได้ว่าฉันควรกล่าวราตรีสวัสดิ์",
  str_voice_1600271_20 = "ฉันจะซื่อตรงต่อเส้นทางของฉัน ความภักดีต่อลูโมโพลิสของฉันถือกำเนิดมาจากสิ่งนี้",
  str_voice_1600271_21 = "ฉันขอบคุณสำหรับการปฏิบัติของราฟาเอล และต่อความช่วยเหลือของอิลลูมินา... ตลอดช่วงการเกิดใหม่ของฉัน",
  str_voice_1600271_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1600271_23 = "ออกคำสั่งมาได้เลย แล้วฉันจะกำจัดสิ้นซาก",
  str_voice_1600271_24 = "ดูเธอจะไม่ได้ยินฉันนะ แต่เปลวไฟนามธรรมของเธอดูจะแผ่วไปในเวลานั้น",
  str_voice_1600271_25 = "เธอคือคนจากอิลลูมินาที่แสวงหาพลัง ความรู้สึกนี้... คุ้นเคยอยู่นะ... นั่นอาจเป็นคำที่ฉันพยายามนำมาอธิบายอยู่ก็ได้",
  str_voice_1600271_26 = "ถ้าฉันชอบอะไร ก็แปลว่าฉันคิดว่ามันน่าสนใจ",
  str_voice_1600271_27 = "ฉันได้ร่ำลาทุกสิ่งที่ฉันรังเกียจไปแล้ว ฉันจะไม่มองย้อนกลับไป",
  str_voice_1600271_28 = "ผู้นำทาง โคลอสซัสนี้ใหญ่โตมโหฬารมาก ดังนั้นอย่าเที่ยวไปจอดมั่วซั่วนะ",
  str_voice_1600271_29 = "ฉันชื่อมิคาเอล ผู้ควบคุมฟ้าผ่าและสายฟ้าเงียบงัน ไม่ว่าเธอจะได้ยินฉันหรือไม่ การแนะนำตัวของฉันก็ได้สิ้นสุดลงแล้ว ได้เวลาลงมือทำงาน",
  str_voice_1600271_30 = "อะไรบางอย่างของฉันมันแตกต่างไปจากเดิม",
  str_voice_1600271_31 = "ฉันไม่จำเป็นต้องสนใจเรื่องที่ไม่สำคัญ",
  str_voice_1600271_32 = "พลังสายฟ้าของฉันเพิ่มมากขึ้น",
  str_voice_1600271_33 = "จงสั่นกลัวต่อหน้ามิคาเอล!",
  str_voice_1600271_34 = "ฉันจะจบทุกสิ่งอย่างรวดเร็ว",
  str_voice_1600271_35 = "ฟ้าผ่ากับฟ้าร้องของฉันพร้อมแล้ว",
  str_voice_1600271_36 = "นำทางฉันด้วย",
  str_voice_1600271_37 = "เธออยากแข่งท่ามกลางฟ้าร้องฟ้าผ่าแบบนี้น่ะเหรอ",
  str_voice_1600271_38 = "ให้เสียงฟ้าร้องที่กึกก้องฉีกเธอให้เป็นชิ้น ๆ เลย!",
  str_voice_1600271_39 = "ไม่มีใครหลบหนีได้",
  str_voice_1600271_40 = "ฟังเสียงฟ้าร้องคำรามนั่นสิ!",
  str_voice_1600271_41 = "ใครก็ได้ช่วยตามฉันให้ทันได้ไหม",
  str_voice_1600271_42 = "ชัยชนะที่คู่ควรกับพลังทำลายล้างของฉัน",
  str_voice_1600271_43 = "ร่างนี้... ยังไม่ทรงพลังพออีกเหรอ",
  str_voice_1600271_44 = "มีโอกาสไม่มากที่คนเราจะได้กลับมาพบกับสหายเก่าก่อน หรือที่จะได้เป็นทีมเดียวกันอีกครั้ง",
  str_voice_1600271_45 = "...เอ่อ... คือ... โอเค...",
  str_voice_1600271_46 = "โอ้ ดูเหมือนฉันจะชอบแบบนี้นะ...",
  str_voice_1600271_47 = "ขอบคุณนะที่ให้ของขวัญฉันตั้งมากมาย",
  str_voice_1600271_48 = "ฉันชอบมาก ฉันชอบอันนี้ ฉันอยากได้ ข-ขอบคุณนะ...",
  str_voice_1600271_49 = "ฉันแตกต่างจากสมาชิกครอบครัวคนอื่นมาตลอดตั้งแต่เด็กนั่นแหละ เธออาจเคยได้ยินเรื่องของครอบครัวทรอยมาก่อน ซึ่งก็คือสัญลักษณ์ของกลยุทธ์และเครื่องเป่า... ฉันคือสาเหตุว่าำทำไมจึงดูผิดที่ผิดทางอยู่เสมอ",
  str_voice_1600271_50 = "ฉันได้ขึ้นไปและได้รับพลังของฉันในวันฝนตก... เปล่าเลย พูดให้ชัดก็คือ มันเกิดขึ้นหลังจากที่ฉันถูกหลอกและถูกหักหลัง แต่ฉันไม่เกลียดเขาหรอกนะ แค่ผิดหวังในความอ่อนแอของตัวเองเท่านั้น",
  str_voice_1600271_51 = "ในท้ายที่สุด ฉันก็ได้เกิดใหม่โดยอาศัยการตายของฉัน หลายคนได้ช่วยฉันเอาไว้ และฉันก็ได้ตอบแทนพวกเขาด้วยการกระทำของฉัน แต่พันธะที่สูญหายไปไม่สามารถเรียกคืนกลับมาได้ และฉันก็ได้แต่เดินต่อไปตามเส้นทางของตัวเอง",
  str_voice_1600271_52 = "Alchemy Stars",
  str_voice_1600271_53 = "เธอได้ยินฉันไหม",
  str_voice_1600271_54 = "อรุณสวัสดิ์ ฉันรอเธออยู่",
  str_voice_1600271_55 = "สวัสดี ฉันมีคำสั่งใหม่ ๆ",
  str_voice_1600271_56 = "เธอตัดสินใจหยุดพักหรือยัง",
  str_voice_1600271_57 = "แด่เธอผู้ที่มีพันธะกับฉัน สุขสันต์วันปีใหม่นะ",
  str_voice_1600281_1 = "อ้อ ขอโทษที ฉันอีกแล้วเหรอ?! หา? แค่ทักทายธรรมดาเหรอ",
  str_voice_1600281_2 = "อ้า เมื่อไหร่ฉันจะได้เป็นฝ่ายสนับสนุนที่ทุกคนไว้ใจอย่างไม่มีเงื่อนไขสักทีนะ... อาจจะพรุ่งนี้มั้ง!",
  str_voice_1600281_3 = "อยากรู้ว่าฉันกำลังทำอะไรน่ะเหรอ มันก็ไม่ใช่เรื่องใหญ่นักหรอก แค่กระสุนน้ำมนต์... แต่ฉันไม่แน่ใจว่ามันจะช่วยรักษาหรือทำให้เจ็บกันแน่",
  str_voice_1600281_4 = "ดูยาใหม่ที่ัฉันพัฒนาสิ มันจะต้องเป็นประโยชน์อย่างแน่นอนครั้งนี้ ฮ่า ฉันเรียกมันว่ากระสุนรักษาเปี่ยมฤทธา",
  str_voice_1600281_5 = "คาร์ลีนนน... เธออยู่ไหน... วันนี้เธอยังไม่ได้สั่งงานอะไรฉันเลยนะ! ทำไมเธอถึงได้ลืมตลอดเลยเนี่ย",
  str_voice_1600281_6 = "อู้วว... พวกนี้คือจดหมายขอบคุณจากผู้คนที่ฉันได้รักษาไงล่ะ! ตลอดเวลาหลายปีที่ผ่านมา ฉันสะสมไว้ได้แค่สองสามฉบับเท่านั้นเอง แต่ฉันก็ยังซาบซึ้งทุกทีที่ได้อ่าน...",
  str_voice_1600281_7 = "เอ่อ ฉันขออะไรเธอสักอย่างได้ไหม ราฟาเอล ช่วยมาอาสาทดลองทางคลีนิกของฉันหน่อยนะ เฮ้ ทำไมถอยหลังไปล่ะ",
  str_voice_1600281_8 = "เฮ้... นี่คือแขนที่ฉันตัดมาจากคนไข้โดยไม่ได้ตั้งใจเมื่อคราวก่อน... เธอช่วยเอาไปคืนคนไข้ให้ทีได้ไหม คิคิ...",
  str_voice_1600281_9 = "มีใครต้องการพบแพทย์รึเปล่า ใคร? ที่ไหน? ราฟาเอลกับซาเวียร์ #5 ของเธอ พร้อมลงมือแล้ว! ตอนนี้ทุกคนปลอดภัยแล้ว คิดว่านะ",
  str_voice_1600281_10 = "วันว่างอีกหนึ่งวัน ฉันสำคัญกับทุกคนมากเลย ดังนั้นฉันจะทำให้พวกเขาผิดหวังไม่ได้... ฉันน่าจะอยู่ทำงานจนดึกและเตรียมอะไรใหม่ ๆ อีกครั้งนะ",
  str_voice_1600281_11 = "ให้ฉันจัดการเอง! ฉันว่าฉันน่าจะจัดการได้ ไม่สิ ฉันต้องจัดการได้แน่นอน! รอยยิ้มเวลาทำงานของเซนต์จอห์น เปิดใช้งาน!!",
  str_voice_1600281_12 = "มีใครตามหาฉันรึเปล่า ใช่เธอไหม เธอบาดเจ็บรึเปล่า",
  str_voice_1600281_13 = "ทุกคนใจดีกันมากเลยนะ! พากันบอกว่าฉันต้องพักผ่อนให้มากขึ้นตลอดเลย...",
  str_voice_1600281_14 = "เขี้ยวของฉันงอกขึ้นอีกแล้ว... ทำไม... โอ้ ทำไมมีแต่ฟันฉันที่โต",
  str_voice_1600281_15 = "สุขสันต์วันเกิด! ฉันเตรียมกระสุนน้ำมนต์ 108 ชิ้นไว้ให้เธอโดยเฉพาะเลย ขอให้เธอมีคืนวันที่เต็มไปด้วยความสุขนะ",
  str_voice_1600281_16 = "อ้าว เธอกลับมาแล้ว!",
  str_voice_1600281_17 = "อรุณสวัสดิ์! วันนี้ฉันมีพลังใจล้นเหลือเลย เธอไม่มีเหรอ มา ๆ ให้ฉันยื่นมือเข้าช่วยนะ",
  str_voice_1600281_18 = "ไม่สำคัญหรอก! ฉันยังคงรับคนไข้ได้อีก เธอดีไหมล่ะ เธอต้องการการรักษารึเปล่า",
  str_voice_1600281_19 = "เธอต้องนอนหลับให้เพียงพอถึงจะมีพลังใจล้นเหลือได้ เธอได้พักผ่อนเพียงพอรึเปล่า ให้ฉันช่วยนะ",
  str_voice_1600281_20 = "ลูโมโพลิสนี่เจ๋งมากเลย ฉันได้รับการยอมรับในยามที่ฉันไม่มีที่ไป อีกอย่าง พวกเขาก็สนับสนุนงานวิจัยของฉันด้วย!",
  str_voice_1600281_21 = "อิลลูมินาก็ยอดเยี่ยมเหมือนกัน ฉันเคยเล่นมิสไซล์กับทุกคนที่นั่นตอนเป็นนักเรียน",
  str_voice_1600281_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1600281_23 = "น่าเสียดายที่ไม่มีทางช่วยพวกเขาได้... มีทางเลือกเดียวเท่านั้นคือต้องกำจัดซะ",
  str_voice_1600281_24 = "ฉันน่าจะได้ไปอยู่กับเธอในตอนนั้นนะ ถึงแม้กาบริเอลจะพูดตลอดว่าเธอไม่สนใจ แต่ก็นั่นแหละ...!",
  str_voice_1600281_25 = "มิคาเอลาตัวน้อยดูดีขึ้นมากเลยนะเดี๋ยวนี้... ตอนแรกเธอทำให้ทุกคนกลัวจริง ๆ",
  str_voice_1600281_26 = "ฉันจะทำงานวิจัยทางการแพทย์ของฉันต่อไป ฉันจะทำการสำรวจและทดลองต่อไปด้วยความหวังว่าจะพบวิธีการรักษาทุกคนในสักวัน!",
  str_voice_1600281_27 = "เราไม่สามารถช่วยเหลือคนไข้ได้... การช่วยคนไข้ไม่ได้เป็นเรื่องที่น่าหงุดหงิดที่สุดเลย...",
  str_voice_1600281_28 = "อ๋อ ฉันเคยเห็นโคลอสซัสมาก่อน! ลุคสีขาวของเธอดูดีมากเลย",
  str_voice_1600281_29 = "ฉันชื่อราฟาเอล ฉันจะช่วยเธอทุกวิถีทางที่ฉันทำได้ ยินดีที่ได้รู้จักนะ!",
  str_voice_1600281_30 = "โอ้ โฮ่ โฮ่ โฮ่!",
  str_voice_1600281_31 = "ขอบคุณนะ! เธอคือบุคคลผู้มีปัญญาอย่างแท้จริง!",
  str_voice_1600281_32 = "นี่คือราฟาเอลรุ่นปรับปรุง!!",
  str_voice_1600281_33 = "ฉันจะทำทุกวิถีทางเพื่อให้สมศักดิ์ศรีของจอห์น",
  str_voice_1600281_34 = "เฮ้ ทุกคน! ฉันอยู่นี่",
  str_voice_1600281_35 = "รอฉันด้วย! แป๊บเดียว",
  str_voice_1600281_36 = "เอิ่มม... ก็ได้ มั้งนะ",
  str_voice_1600281_37 = "ยิงมิสไซล์ทั้งหมด ฉันไม่ได้พูดเล่นนะ!!",
  str_voice_1600281_38 = "ยิงกระสุนน้ำมนต์!",
  str_voice_1600281_39 = "วู้ฮู้!!",
  str_voice_1600281_40 = "วารีศักดิ์สิทธิ์เกลื่อนไปหมดเลย!",
  str_voice_1600281_41 = "ราฟาเอลกำลังทำภารกิจสำคัญนี้ด้วยความสงบเยือกเย็น",
  str_voice_1600281_42 = "มีฉันอยู่ที่นี่ ไม่มีใครได้รับบาดเจ็บแน่นอน ไชโย!",
  str_voice_1600281_43 = "ขอโทษที ขอให้ฉันได้ลองอีกครั้งนะ แค่ครั้งเดียว ขอร้องงง!",
  str_voice_1600281_44 = "หวังว่าฉันจะไม่ได้รับคำร้องเรียนอีกนะ! ฉันขอโทษที่สร้างปัญหา...",
  str_voice_1600281_45 = "โอ้ว แปลว่าฉันก็รับของขวัญได้เหมือนกันเหรอ",
  str_voice_1600281_46 = "โอ้ ดีจังเลย ขอบใจนะ!",
  str_voice_1600281_47 = "ขอบคุณมากนะ! ฉันมีความสุขจัง",
  str_voice_1600281_48 = "นี่คือ...? ฉันขอได้ไหม?? โว้ว...",
  str_voice_1600281_49 = "ในอดีตมันยากมาก โดยเฉพาะวันที่ต้องเร่ร่อนไปกับอาจารย์... โอ้ ยกโทษให้ฉันด้วย! ฉันไม่ควรบอกเธอเรื่องแบบนี้",
  str_voice_1600281_50 = "เธอเคยได้ยินเกี่ยวกับตระกูลจอห์นที่โด่งดังมากไหม ถ้าไม่ใช่เพราะเรา ไม่รู้จะมีคนตายไปกี่คน... หา ไม่เคยได้ยินเรื่องนี้เลยเหรอ",
  str_voice_1600281_51 = "เจ้านาย ฉันได้เติบโตขึ้นแล้ว ฉันได้เจอคนดี ๆ มากมาย และตอนนี้ฉันก็สามารถช่วยเรื่องการรักษาได้แล้วด้วยนะ ทีนี้ก็ดูฉันอย่างใกล้ชิดจากข้างบนได้เลย...",
  str_voice_1600281_52 = "Alchemy Stars!",
  str_voice_1600281_53 = "เธอเป็นอะไรรึเปล่า",
  str_voice_1600281_54 = "เธอตื่นอยู่หรือเปล่า",
  str_voice_1600281_55 = "เร็วเข้า! มาดูสิ!",
  str_voice_1600281_56 = "ตื่นก่อน! อย่าเพิ่งนอน!",
  str_voice_1600281_57 = "วู้ฮู้! สุขสันต์วันปีใหม่!",
  str_voice_1600381_1 = "ความพินาศของสนามทดสอบทำให้ฉันนึกถึงผลลัพธ์ของยุคที่ผ่านไปแล้วว่าน่าเหลือเชื่อขนาดไหน ฉันเคยทำพลาดไปแล้วจริง ๆ แต่ความล้มเหลวคือบ่อเกิดของความสำเร็จใช่ไหมล่ะ",
  str_voice_1600381_2 = "โศกนาฏกรรมทั้งหลายในโลกนี้ไม่ใช่ธุระอะไรของฉัน และฉันก็ไม่อยากแสร้งทำเป็นเห็นใจด้วย ที่จริงแล้วอิลลูมินาเป็นสถานที่ที่สนุกสนานไม่เบาไม่ใช่เหรอ",
  str_voice_1600381_3 = "พาหนะของฉันเป็นเรลิกจากเมื่อนานมาแล้ว เป็นสิ่งที่สร้างขึ้นได้โดยไม่คำนึงถึงกระบวนการและต้นทุนเลยแม้แต่น้อย ฉันแจ็กพอตแตกจริง ๆ!",
  str_voice_1600381_4 = "ฉันไม่ผูกติดกับกฎ ฉันเดิมพันชีวิตในฐานะนักวิจัยว่าฉันจะต้องหาคำตอบให้ได้",
  str_voice_1600381_5 = "เธออยากนับชัยชนะของฉันเหรอ คือไม่ว่าจะเป็นเกมการแข่งขันอะไร คะแนนของฉันก็ขึ้นนำบนกระดานคะแนนอยู่ดี",
  str_voice_1600381_6 = "บัลลังก์เป็นอนุสรณ์แห่งยุคสมัยอันห่างไกล และเฉพาะผู้ที่ \"เข้าใจ\" ความลับในนั้นก่อนเท่านั้นจึงจะมีสิทธิ์ใช้งานมันได้",
  str_voice_1600381_7 = "งานของฉันคือเคลียร์ด่านต่าง ๆ และไม่มีสิ่งอื่นใดที่เกี่ยวข้องกับฉันใช่ไหมล่ะ เพราะยังไง ทุกคนก็มีด่านของตัวเองต้องเคลียร์อยู่แล้ว",
  str_voice_1600381_8 = "ปล่องภูเขาไฟขนาดยักษ์ในอาณาจักรแห่งนั้นเป็นภาพที่น่าตื่นตาจริง ๆ ฉันหวังว่าฉันจะมีเวลาไปดูสักหน่อย แต่ดูเหมือนว่าสถานที่แห่งนั้นจะมีคนจรไปยึดครองเต็มไปหมดแล้ว",
  str_voice_1600381_9 = "เราทั้งหมดต่างก็เป็นเด็กที่ถูกอารยธรรมทอดทิ้ง... เธอไม่รู้อะไรเกี่ยวกับยุคนั้นจริง ๆ เหรอ เอ้อนะ ก็ไม่น่าแปลกใจหรอก เพราะยังไงเรื่องพวกนั้นก็ไม่มีบันทึกไว้ในวรรณกรรมที่เปิดเผยต่อประชาชน",
  str_voice_1600381_10 = "ทหารม้าผู้แน่วแน่ กลยุทธ์ที่ไม่มีทางผิดพลาด ความกล้าแกร่งทางทหารที่ดิบเถื่อน! เราจะต่อสู้กันตามชายหาด... ฮึ ฉันกลับมาใช้นิสัยแย่ ๆ อีกแล้ว ต้องไม่ลืมว่านี่ฉันอายุเท่าไหร่แล้วล่ะ!",
  str_voice_1600381_11 = "ในฐานะนักวิจัย เธอควรมองจากด้านนอกเข้าไปมากกว่า มันอาจทำให้เธอมีมุมมองที่แตกต่างออกไป",
  str_voice_1600381_12 = "เกมต่าง ๆ ที่นี่ก็ไม่ได้แย่ขนาดนั้นด้วย อย่างเช่นการควบคุมโคลอสซัส... อะไรนะ มันไม่ใช่เกมเหรอ",
  str_voice_1600381_13 = "มันน่าทึ่งจริง ๆ นะที่ว่าถ้ามีจิตใจที่ปลอดโปร่ง คนเราก็สามารถสร้างความรู้สึกแปลกใหม่ให้กับโลกภายนอกได้",
  str_voice_1600381_14 = "ดันเจี้ยนใน \"โลก\" ได้รับการอัปเดตแล้ว อยากรับความท้าทายไหมล่ะ",
  str_voice_1600381_15 = "นี่คือตั๋วเข้าชิงถ้วยจักรพรรดิของเธอ! เอาชนะฉันสิ แล้วบัลลังก์ของฉันจะเป็นของเธอ",
  str_voice_1600381_16 = "ดูสิว่าใครมา... เจ้าขี้แพ้!",
  str_voice_1600381_17 = "ไม่ต้องพูดกันแล้ว มาเป่ายิงฉุบเลย ฮ่า เธอแพ้แล้ว",
  str_voice_1600381_18 = "ตัดสินใจได้แล้วเหรอว่าจะท้าทายฉันยังไง เจ้าขี้แพ้!",
  str_voice_1600381_19 = "สดใสหน่อยน่า สำหรับนักวิจัย เกมมันเพิ่งเริ่มต้นเท่านั้น!",
  str_voice_1600381_20 = "อิลลูมินาคือสวรรค์ของนักวิจัย เราจะพัฒนาอะไรเจ๋ง ๆ ได้มากยิ่งกว่านี้อีก เดี๋ยวเธอก็เห็นเอง",
  str_voice_1600381_21 = "ยัยราฟาเอลที่ลูโมโพลิส ส่งมานั่นเป็นนักวิจัยที่ใช้ได้เลยนะ แต่เธอยังไม่ใกล้เคียงมาตรฐานของฉันหรอก",
  str_voice_1600381_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1600381_23 = "การวิจัยที่ยืดเยื้อในเรื่องนี้จะต้องหยุดเอาไว้ชั่วคราว... คราวหน้าฉันจะระวังให้มากกว่านี้",
  str_voice_1600381_24 = "จอมทัพคนปัจจุบันเก่งที่สุด บางครั้งฉันคิดว่าเธอคือบอสในเกมมากกว่า",
  str_voice_1600381_25 = "เจ้าขี้แพ้! ขี้อวดมากเลยนะสำหรับคนที่อายุแค่นี้ เขาน่ะเทียบกับฉันไม่ได้หรอกถ้าว่ากันเรื่องทักษะการควบคุมเครื่องจักรกล",
  str_voice_1600381_26 = "สิ่งที่ฉันชอบเหรอ ก็มีเกม การวิจัย เครื่องจักรกลเก่า ๆ แล้วก็บัลลังก์แชมเปี้ยน",
  str_voice_1600381_27 = "ฉันมั่นใจว่าโลกจะต้องเป็นสถานที่ที่ไม่น่าอยู่อย่างแน่นอนถ้าไม่มีเกมสนุก ๆ!",
  str_voice_1600381_28 = "เทคโนโลยีจักรกล เทคโนโลยีชีวภาพ เทคโนโลยีออโรเรียน... โคลอสซัสอาจเป็นงานสร้างสรรค์ที่สมบูรณ์แบบก็ได้นะ",
  str_voice_1600381_29 = "เธอมีออร่าที่เหมือนกันกับฉัน เราเคยเจอกันมาก่อนรึเปล่า หรือว่าเธอได้ลงแข่งถ้วยจักรพรรดิมาก่อนไหม ถ้าอย่างนั้นเธอต้องรู้จักฉันแน่นอน",
  str_voice_1600381_30 = "เรียบร้อย! เฮ้อ!",
  str_voice_1600381_31 = "พลังสูงสุดของยุคแห่งความหวาดกลัวได้ตื่นขึ้นแล้ว!",
  str_voice_1600381_32 = "ไม่มีใครลากฉันลงจากบัลลังก์นี้ได้!",
  str_voice_1600381_33 = "จงเสียใจที่มาสู้กับฉัน!",
  str_voice_1600381_34 = "ที่หนึ่งกับที่สองคะแนนต่างกันมหาศาลเลย!",
  str_voice_1600381_35 = "ให้ฉันได้สนุกบ้างสิ!",
  str_voice_1600381_36 = "สถิติใหม่กำลังจะเกิดขึ้นแล้ว!",
  str_voice_1600381_37 = "เริ่มแข่งได้!",
  str_voice_1600381_38 = "อยากเข้ามาลองไหมล่ะ",
  str_voice_1600381_39 = "เมก้าช็อก!",
  str_voice_1600381_40 = "สกิลจักรกล!",
  str_voice_1600381_41 = "เริ่มแข่งแล้ว! ฉันเชียร์อิลลูมินา!",
  str_voice_1600381_42 = "สนุกเนอะ! อีกรอบเถอะ อีกรอบเถอะ!",
  str_voice_1600381_43 = "มีกฎแบบนี้ด้วยเหรอ โธ่เว้ย...",
  str_voice_1600381_44 = "ในที่สุดเธอก็ตัดสินใจได้แล้วเหรอ ฉันเล่นกับโคลอสซัสของเธอได้ไหมล่ะ",
  str_voice_1600381_45 = "ให้ฉันเดานะ มันคือเกมใหม่หรือการ์ดเสริมพลังใช่ไหม",
  str_voice_1600381_46 = "ฉันไม่เคยเห็นอะไรน่าตื่นเต้นขนาดนี้ที่อิลลูมินาเลย!",
  str_voice_1600381_47 = "ให้ฉันทายนะ เธอคิดวิธีการเล่นแบบใหม่ขึ้นมาได้ใช่ไหม",
  str_voice_1600381_48 = "เธอก็รู้นี่ว่าฉันชอบเล่นอะไร!",
  str_voice_1600381_49 = "พลังนี้ดูจะไม่สามารถปกป้องยุคที่สร้างมันขึ้นมาได้ และตอนนี้ที่ฉันได้ค้นพบมันอีกครั้ง มันจะปกป้องยุคของเราได้เหรอ",
  str_voice_1600381_50 = "บางทีวันหนึ่งยุคนี้ก็อาจล่มสลายในแบบเดียวกันกับจักรวรรดิโบราณทั้งหลายก็ได้ แต่การแข่งขันเหล่านี้จะยังคงมีต่อไปจนกว่าจะได้ผู้ชนะ",
  str_voice_1600381_51 = "ความทรงจำของฉันเกี่ยวกับการทดลองนี้ไม่ได้รับผลกระทบใด ๆ แต่ฉันไม่อยากแบ่งปันความรู้ที่ไร้ประโยชน์นี้กับเธอ ดูจากสีหน้างุนงงของเธอแล้ว ฉันบอกได้เลยว่าเธอยังอยู่ในช่วงที่ไม่มีประสบการณ์",
  str_voice_1600381_52 = "Alchemy Stars!",
  str_voice_1600381_53 = "เร็วเข้า!",
  str_voice_1600381_54 = "เร็วเข้า! การแข่งขันจะเริ่มแล้ว!",
  str_voice_1600381_55 = "ตรงเวลาเป๊ะ มาต่อสู้กันเลย!",
  str_voice_1600381_56 = "อย่าเพิ่งง่วงล่ะ!",
  str_voice_1600381_57 = "ผ่านมาได้หนึ่งปี นี่มาอีกปีแล้ว!",
  str_voice_1600601_1 = "ไม่ต้องอาย มาทักทายกันสิ เรามีหัวรบ ซองกระสุน ปลอกกระสุน อ๋อ นี่คือแขนหุ่นยนต์ในชุด \"มรณะ\" ไงล่ะ! ออกแบบโดยฝ่ายเทคนิคเรดีเซล เวรนช์เลยนะ ทำยังไงน่ะเหรอ เธอไปถามเจ้าจิ๋วดูได้เลย",
  str_voice_1600601_2 = "ไม่มีใครปฏิเสธเงินหรอกนะเด็กน้อย นี่มันแค่งาน และด้วยมนุษยธรรมแล้วฉันก็ชอบจบชีวิตใคร ๆ อย่างรวดเร็ว จะได้แน่ใจว่าไม่มีการทนทุกข์โดยไม่จำเป็น",
  str_voice_1600601_3 = "แนวคิดของฉันน่ะเหรอ ช่วยคนที่อ่อนแอแล้วก็สตรี โดยเฉพาะเด็ก ๆ ฉันไม่เคยหันปืนไปทางพวกเขาเลย",
  str_voice_1600601_4 = "มาเลย ได้เวลาถอดถุงมือกันแล้ว ฮ่า! ล้อเล่นน่ะ ฉันไม่ถอดกุญแจมือหรอก มันเป็นเอกลักษณ์ของฉันน่ะ",
  str_voice_1600601_5 = "ระวังนะเด็กน้อย กระสุนของฉันรวดเร็วพอที่จะส่งคนลงหลุมได้เลย",
  str_voice_1600601_6 = "มาเลย! ได้เวลาเตะก้นคนเล่นแล้ว ที่ฉันอวดเก่งได้ ก็เพราะว่าว่าฉันเก่งไงล่ะ เด็กน้อยเอ๋ย",
  str_voice_1600601_7 = "ฉันไม่ชอบต่อสู้... แต่บางทีเราก็ไม่มีทางเลือก ฮึ อย่าให้ฉันต้องเก็บกระสุนไว้สำหรับเธอเลยนะเด็กน้อย",
  str_voice_1600601_8 = "ก่อนตาย ฉันอยากเมาให้พับข้างถนนที่ไหนสักแห่ง จากนั้นก็จะมีใครไม่รู้ผ่านมาแล้วก็ เปรี้ยง! จัดการฉันตรงนั้นเลย นัดเดียวทะลุหัวใจ",
  str_voice_1600601_9 = "ฉันไม่ชอบยุ่งเรื่องของคนอื่นหรอกนะ ปกติแล้ว แต่เธอคือคนพิเศษ ไม่ว่าจะเกิดอะไรขึ้นกับเธอ อย่าไปใส่ใจมัน เวลาจะทำให้ทุกอย่างราบรื่นเอง",
  str_voice_1600601_10 = "ใจเย็นน่า... เธอควรดื่มด่ำกับเวลาพักผ่อนอย่างพอเหมาะ เรื่องงานเอาไว้ทีหลังก็ได้",
  str_voice_1600601_11 = "ถ้าเธอจ่ายค่าตัวให้ฉันมากพอ... อ่ะแฮ่ม ได้เลย ฉันจะทำให้",
  str_voice_1600601_12 = "ปัง! ฉันทำให้เธอตกใจใช่ไหมล่ะ? ฮ่าฮ่า!",
  str_voice_1600601_13 = "เพื่อความสุภาพ ฉันว่าฉันควรจับมือกับเธอสินะ... เธออยากจับแขนกลข้างไหนของฉันล่ะ",
  str_voice_1600601_14 = "ประกาศจับอาชญากรเหรอ แม้แต่ฉันยังอยากได้ค่าหัวตัวเองเลยเนี่ย",
  str_voice_1600601_15 = "เฮ้ เด็กน้อย วันนี้วันเกิดเธอนะ เยี่ยมไปเลยใช่ไหมล่ะ มันคือวันแห่งโชคลาภที่ควรฉลองนะ",
  str_voice_1600601_16 = "รีบลงมือกันเถอะ ฉันไม่ได้ออกเรี่ยวออกแรงมานานแล้ว พยายามตามฉันให้ทันนะเด็กน้อย",
  str_voice_1600601_17 = "ได้กินอาหารเช้านาน ๆ เป็นการเริ่มต้นวันที่สมบูรณ์แบบทีเดียว ยิ่งถ้าได้ชาสักถ้วยด้วยนะ",
  str_voice_1600601_18 = "ใครทำเสียงอึกทึกครึกโครมเนี่ย?! ทำไมผู้ที่ชื่นชอบในดนตรีต้องไม่หลับไม่นอนเวลาประมาณนี้ทุกทีเลยอ่ะ",
  str_voice_1600601_19 = "เธออยากได้เครื่องดื่มเหรอ? ใส่น้ำแข็ง ใส่เกลือด้วย หรือเอาแค่น้ำผลไม้กล่องสำหรับเด็กล่ะ?",
  str_voice_1600601_20 = "เรดีเซล เวรนช์คือกองขยะที่คนบ้าและอันธพาลมารวมตัวกัน แน่นอนว่าฉันก็คือหนึ่งในนั้น",
  str_voice_1600601_21 = "ลูโมโพลิสนี่ยอดเยี่ยมเลย! พวกเขาชอบเอามรดกของโลกเก่ามาใช้กันมั่วซั่ว พวกที่หน้าตาดีในหมู่อัศวินลูโมก็เยอะด้วย",
  str_voice_1600601_22 = "ใช้ชีวิตให้เต็มที่ แล้วปล่อยให้มันเป็นไป",
  str_voice_1600601_23 = "อิคลิพไซท์เหรอ สัตว์น่าสงสารที่อาศัยพลังความมืดเพื่อความอยู่รอด ควรรีบกล่อมนอนให้เร็วยิ่งกว่านี้",
  str_voice_1600601_24 = "เรจินากับบาร์บาร่าเหรอ เอ้อ เลือกยากนะเพราะฉันชอบทั้งดนตรีร็อกแล้วก็สาวสวย ๆ",
  str_voice_1600601_25 = "แม้ว่าบร็อคจะเป็นคนทึ่มที่ชอบเล่นกีฬาใช้กำลัง แต่ก็ถือว่าเขาเป็นคนธรรมดาทั่วไปในเรดีเซล เวรนช์",
  str_voice_1600601_26 = "การสังเกตการณ์และการเดินเล่นช่วยทำให้ฉันจิตใจสงบได้ แล้วออโรเรียนทำไมเหรอ พวกนั้นก็แค่ทรายในทะเลทรายเท่านั้น",
  str_voice_1600601_27 = "บรรยากาศที่ตึงเครียดเตือนให้ฉันนึกถึงเหงื่อเหนียว ๆ จะบังคับตัวเองให้มากมายขนาดนั้นทำไมกัน",
  str_voice_1600601_28 = "มันคืองานสร้างสรรค์ที่งดงามมาก ขอที่ให้ฉันเพียงแค่มุมเดียวเท่านั้น แล้วฉันก็จะสามารถบอกลาความขาดแคลนและความหิวโหยได้",
  str_voice_1600601_29 = "อย่าขยับนะ ไม่งั้นกระสุนนี่ทะลุหัวเธอโดยไม่ทันรู้ตัวแน่! ฉันล้อเล่นน่า! ฉันชื่อโจนา มือปืนธรรมดา ๆ ที่บังเอิญผ่านมาเท่านั้นแหละ บอกลาสิ่งธรรมดาที่น่ารำคาญในชีวิตไปได้เลย เรามานั่งคุยกันอย่างสงบเถอะนะ",
  str_voice_1600601_30 = "อย่ากระโตกกระตาก",
  str_voice_1600601_31 = "นัดเดียว ตรงเป้าพอดี!",
  str_voice_1600601_32 = "ความสามารถพิเศษของฉันคือการยิงปืน",
  str_voice_1600601_33 = "มาสิ ฟังเสียงซิมโฟนีของการยิงปืนนี่เลย!",
  str_voice_1600601_34 = "จัดการพวกมันเลยเด็ก ๆ!",
  str_voice_1600601_35 = "ล็อกเป้าหมายและบรรจุกระสุน",
  str_voice_1600601_36 = "เล็งเป้า",
  str_voice_1600601_37 = "กินลูกตะกั่วซะ!",
  str_voice_1600601_38 = "ลาก่อนสหาย",
  str_voice_1600601_39 = "สิ่งดี ๆ ต้องมาเป็นคู่",
  str_voice_1600601_40 = "อย่าให้ใครเหลือรอด",
  str_voice_1600601_41 = "เตรียมโลงศพให้ศัตรู",
  str_voice_1600601_42 = "เหอะ ก็ไม่อะไรมากนะ",
  str_voice_1600601_43 = "คอยระวังจะถูกซุ่มยิง",
  str_voice_1600601_44 = "ฉันเกือบลืมไปแล้วว่ายังมีอะไรต้องทำอีก ฉันจะจบเรื่องนี้อย่างรวดเร็ว",
  str_voice_1600601_45 = "โอ้? ...หืมม นี่มันสดใหม่ไม่เบาเลยนะ",
  str_voice_1600601_46 = "ขอบใจนะ! ฉันจะทะนุถนอมอย่างดี",
  str_voice_1600601_47 = "กระสุน แก้วไวน์ แล้วก็ของขวัญของเธอ",
  str_voice_1600601_48 = "แลกเปลี่ยนได้เท่าเทียมดี ของขวัญนี้มีค่าเท่ากับเบียร์เย็น ๆ สักแก้วนะ!",
  str_voice_1600601_49 = "ชีวิตเหรอ ฉันไม่มีความคาดหวังอะไรพิเศษในชีวิตหรอก... พรุ่งนี้ก็แค่อีกวันหนึ่ง ฉันไม่สนใจหรอกว่าฉันจะอยู่ที่ไหน ตราบใดที่ฉันยังมีอะไรกิน",
  str_voice_1600601_50 = "ชีวิตมือปืนยังไงก็จบในการดวล ก็เห็นอยู่ว่าปืนของฉันเร็วกว่าเสมอ ฝังครูฝึกของฉันเองกับมือ แล้วก็เอาปลอกกระสุนโปรยเต็มพื้นให้เขาด้วย",
  str_voice_1600601_51 = "ฉันยอมให้โชคชะตาลากฉันไปโน่นมานี่อยู่ตลอด แล้วก็ยอมอยู่ในที่ที่ฉันถูกลากไป ถ้าถามถึงอะไรดี ๆ อย่างน้อยเรดีเซล เวรนช์ก็คือที่ที่ฉันอยู่ได้อย่างสบายตัวสบายใจที่สุด",
  str_voice_1600601_52 = "Alchemy Stars",
  str_voice_1600601_53 = "ผู้นำทาง",
  str_voice_1600601_54 = "อ้าว อรุณสวัสดิ์",
  str_voice_1600601_55 = "มานี่สิ ได้เวลาวาดลวดลายกันแล้ว",
  str_voice_1600601_56 = "ส่งเสียงซิ ฉันจะได้รู้ว่าเธอยังมีชีวิตอยู่",
  str_voice_1600601_57 = "ทีนี้ก็นั่งลง ปีใหม่แล้วนะ",
  str_voice_1600771_1 = "ฉันไม่เคยเห็นโคลอสซัสที่้สมบูรณ์แบบขนาดนี้มาก่อนเลย ดูราวกับว่า... โชคชะตาได้ลั่นวาจาแล้ว",
  str_voice_1600771_2 = "ตั้งแต่ที่โคลอสซัสลอยขึ้นไปบนฟ้าและมองลงมายังผู้มีชีวิต ฉันก็รู้เลยว่าโลกได้เปลี่ยนไปแล้ว",
  str_voice_1600771_3 = "โชคชะตาได้นำสหายมาให้เธอหลายคน เธอจะปลอดภัยจนกว่าโชคชะตาจะทอดทิ้งเธอไปนั่นแหละ ส่วนตอนนี้ไม่ต้องกังวลหรอก",
  str_voice_1600771_4 = "ในอนาคตฉันเห็นรัตติกาลสีขาวที่ยังคงสลัว ฉันหวังว่าฉันจะคิดผิด",
  str_voice_1600771_5 = "จำไว้ว่า ออโรราคือแกนกลางของเรา มันจะเอาชนะภัยคุกคามสูงสุดให้กับเรา",
  str_voice_1600771_6 = "นอร์ธแลนด์คือสหายของฉัน... และของเธอด้วยเช่นกัน ฤดูใบไม้ผลิจะมาเมื่อฤดูหนาวสิ้นสุดลง",
  str_voice_1600771_7 = "ดูเหมือนว่าตอนนี้เธอจะเป็นอิสระแล้ว เธอเล่าเรื่องอดีตของเธอให้ฉันฟังได้ไหม เธอมาเจอโคลอสซัสนี้ได้ยังไง",
  str_voice_1600771_8 = "ที่อยู่ของฉันในนอร์ธแลนด์เรียกว่าพระราชวังเหมันต์ เป็นวังที่สร้างอยู่บนยอดเขา ทิวทัศน์ที่นั่นงดงามมาก",
  str_voice_1600771_9 = "เธออาจเป็นบุคคลที่ฉันรออยู่ก็ได้ คนที่จะทำให้ทวีปนี้มีอนาคต",
  str_voice_1600771_10 = "ในฐานะผู้ครองนครแดนเหนือ ฉันมีเวลาเถลไถลไม่มาก มันทำให้ฉันนึกถึงเก้าอี้ยาวของฉันในพระราชวังเหมันต์",
  str_voice_1600771_11 = "เวลาที่เธอค้นหาโชคชะตาของตัวเอง ฉันช่วยดูแลโคลอสซัสให้เธอได้นะ",
  str_voice_1600771_12 = "สถานการณ์ตอนนี้แตกต่างจากตอนที่ฉันอยู่ในนอร์ธแลนด์อย่างมาก โชคยังดีที่ฉันสามารถรับมือได้อย่างง่ายดาย",
  str_voice_1600771_13 = "โคลอสซัสนี้อาจไม่ใช่หนึ่งเดียวในโลกนี้ มันไม่ได้อยู่ลำพัง เธอ...ก็เช่นกัน",
  str_voice_1600771_14 = "บางที... ฉันก็สามารถได้ยินสิ่งที่โคลอสซัสพูด ดูเหมือนว่าเขาเองก็มีความต้องการที่จะแสดงความคิดของตัวเองออกมาเหมือนกัน",
  str_voice_1600771_15 = "ฉันจำวันเกิดตัวเองไม่ได้หรอก... แต่ฉันก็ยังอยากอวยพรให้เธอมีความสุขในวันเกิดนะ",
  str_voice_1600771_16 = "วันที่สงบเงียบ เหมือนตามปกติของนอร์ธแลนด์",
  str_voice_1600771_17 = "มาสิ มาอาบแสงแดดนี่กับฉัน",
  str_voice_1600771_18 = "การได้พักบ้างนาน ๆ ทีจะช่วยเธอเตรียมตัวสำหรับอนาคต ดื่มชาสักถ้วยสิแล้วก็พักสักนิด",
  str_voice_1600771_19 = "ฉันชินแล้วที่อยู่ดึก ๆ นั่นคือการเสียสละที่ฉันต้องทำในฐานะราชินีแห่งแดนเหนือ เธอควรพักได้แล้วล่ะ",
  str_voice_1600771_20 = "เราได้แช่แข็งโชคชะตาของเราเอาไว้บนเทือกเขาที่ไร้รากเหง้า ความเปลี่ยนแปลงอาจจะกำลังมาก็ได้...",
  str_voice_1600771_21 = "ลูโมโพลิสก็เหมือนนอร์ธแลนด์ที่ไม่มีหิมะ ลัทธิอนุรักษ์นิยมก็เหมือนกับเทือกเขาที่มีหิมะปกคลุมของพวกเขา ถ้าหิมะถล่มขึ้นมา หายนะแน่นอน",
  str_voice_1600771_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1600771_23 = "ใครกันนะที่พวกอิคลิพไซท์เรียกกันว่าแม่",
  str_voice_1600771_24 = "มันมีเหตุผลนะที่นิคินิสเป็นคนเย็นชาเหลือเกิน เธอไม่รู้หรอกว่านางผ่านอะไรมาบ้าง",
  str_voice_1600771_25 = "ถึงแม้ว่าคาร์ลีนจะเป็นชนชั้นสูง แต่เธอก็ไม่หยิ่งยโส เธอเกิดมาเพื่อลูโมโพลิสที่แท้จริง",
  str_voice_1600771_26 = "ชาจากแดนใต้ แสงอาทิตย์ในฤดูหนาว ถ้าโลกเป็นแบบนี้เรื่อยไป บางทีแม้แต่ฉันก็อาจมีความสุขกับมันก็ได้",
  str_voice_1600771_27 = "ความสงสัยคือศัตรูชั่วนิรันดร์ของเรา แม้แต่อิคลิพไซท์ก็ยังมาเป็นที่สองรองจากนั้น",
  str_voice_1600771_28 = "มันมาจากอดีต แต่ก็เต็มไปด้วยเทคโนโลยีที่ล้ำยุค มันกุมความลับเอาไว้มากมาย...",
  str_voice_1600771_29 = "ฉันคือผู้ครองนครแดนเหนือ ไม่ต้องแปลกใจ โชคชะตาได้นำทางให้ฉันมายังโคลอสซัสลำนี้เพื่อให้เราได้พบกัน",
  str_voice_1600771_30 = "พลังที่แท้จริง...ได้ถือกำเนิดแล้ว",
  str_voice_1600771_31 = "น้ำแข็งคือเครื่องมือปกป้องของฉัน",
  str_voice_1600771_32 = "นอกจากนี้น้ำแข็งยังเป็นคมดาบแห่งออโรราอีกด้วย",
  str_voice_1600771_33 = "น้ำแข็งที่นอร์ธแลนด์คือเพื่อนของเรา",
  str_voice_1600771_34 = "จัดการได้โดยง่าย",
  str_voice_1600771_35 = "ออโรรา นายท่าน...",
  str_voice_1600771_36 = "พลังแห่งความหนาวสุดขั้ว!",
  str_voice_1600771_37 = "เรื่องนี้จะจบลงเมื่อน้ำแข็งละลาย",
  str_voice_1600771_38 = "อะไรที่ควรเกิดขึ้นก็จะเกิดเอง",
  str_voice_1600771_39 = "คมดาบแห่งออโรรา",
  str_voice_1600771_40 = "การพิพากษาขั้นสูงสุด",
  str_voice_1600771_41 = "มุ่งหน้าสู่ชัยชนะกันเถอะ",
  str_voice_1600771_42 = "บันทึกชัยชนะอีกครั้ง",
  str_voice_1600771_43 = "อุปสรรคนาน ๆ ครั้ง ไม่ต้องสนใจหรอก",
  str_voice_1600771_44 = "เธอยังต้องไปอีกไกล อย่ายอมแพ้",
  str_voice_1600771_45 = "ขอบคุณนะ แต่เธอไม่จำเป็นต้องคิดอะไรมากขนาดนี้ก็ได้",
  str_voice_1600771_46 = "โอ้ นี่คือสิ่งที่ฉันอยากได้อยู่เลย ขอบคุณนะ",
  str_voice_1600771_47 = "เธอคงตั้งใจคิดเรื่องนี้มากเลยสินะ ขอบคุณนะ",
  str_voice_1600771_48 = "ดูเหมือนเธอจะใช่บุคคลที่ฉันเลือกไว้จริง ๆ ด้วย...",
  str_voice_1600771_49 = "นอร์ธแลนด์มีธรรมเนียมที่เก่าแก่ที่สุด ทูตจากดินแดนต่าง ๆ อันไกลโพ้นต้องพบว่ามันยากที่จะทำความคุ้นเคยเป็นแน่",
  str_voice_1600771_50 = "การเอาชนะสงครามในแดนไกล ผู้บัญชาการจะต้องวางแผนกลยุทธ์ให้ดี เราต้องพึ่งพาปัญญาของเรา เพราะนั่นคือหนทางเดียวที่เราจะเอาชนะอิคลิพไซท์ได้",
  str_voice_1600771_51 = "ฉันไม่ได้รู้ทุกอย่าง หรือกล้าแกร่งไปซะทุกอย่าง แต่ฉันพยายามอย่างที่สุดที่จะปกป้องประชาชนของฉัน ฉันทำแบบนั้นเสมอ และฉันก็จะทำแบบนั้นต่อไป เราต้องตั้งมั่นเมื่อเผชิญหน้ากับภัยคุกคามสูงสุด",
  str_voice_1600771_52 = "Alchemy Stars",
  str_voice_1600771_53 = "สวัสดี ผู้นำทาง",
  str_voice_1600771_54 = "สายลมแห่งการลุกตื่นกำลังพัดมา",
  str_voice_1600771_55 = "ช่วยตอบฉันที ผู้ที่ฉันเฝ้ารอ",
  str_voice_1600771_56 = "ไม่จำเป็นต้องกลัวความมืดหากมีฉันอยู่ที่นี่",
  str_voice_1600771_57 = "ฤดูกาลต่าง ๆ ได้เวียนมาจนครบวัฏจักรแล้ว",
  str_voice_1600891_1 = "การมีความรับผิดชอบหมายความว่าผู้ที่อยู่ในตำแหน่งสูง ๆ ควรก้าวออกมาปกป้องประชาชน พวกเขาควรเข้มงวดกับตนเองและมีพลังที่สมกับตำแหน่งของพวกเขา",
  str_voice_1600891_2 = "ฉันมีเส้นทางของตัวเอง ดังนั้นฉันจะไม่กลายเป็นแบบเขา เขาไม่มีศัตรูอื่นใดนอกจากศัตรูของประชาชน และไม่มีครอบครัวที่ไหนนอกจากกฎหมาย",
  str_voice_1600891_3 = "นี่ฉันไขว้เขวเพราะเสียงของคนตายเหรอ แต่ทุกย่างก้าวที่ฉันเดินในตอนนี้ก็เป็นตัวแทนความตั้งใจของฉัน และมีพื้นฐานอยู่บนความเป็นจริง",
  str_voice_1600891_4 = "ฉันจะทำให้ดีที่สุดเพื่อทบทวนการกระทำและความเสียใจของฉัน ฉันจะพัฒนาต่อไปด้วยหัวใจที่เต็มไปด้วยความหวัง ในขณะที่ฉันยังคงรับรู้ถึงความเจ็บปวดได้",
  str_voice_1600891_5 = "ถ้าเธอถามฉันเรื่องเงามืดที่ลอยอยู่ใต้ผิวน้ำสีทอง ฉันบอกได้เลยว่ามันคือสิ่งที่กำลังรอให้ฉันเผยความอ่อนแอออกมา และลากฉันลงไปกลืนกินในน้ำ",
  str_voice_1600891_6 = "ฉันจะฝังผู้ที่ควรได้รับการฝัง ฉันจะละทิ้งความปรารถนาเพื่อให้ฉันไม่จำเป็นต้องหลบหนีอีกต่อไป ฉันจะเดินทางไปให้ไกลแสนไกลเท่าที่นิรันดร์กาลจะยอมให้ฉันไป โดยการเดินตามทิศทางของดาวประกายพรึก",
  str_voice_1600891_7 = "ตามกฎหมายเรื่องการพิจารณาคดี เธอมีสิทธิ์ที่จะอุทธรณ์ถ้ามีมูลคดีที่หนักแน่น... ไม่ต้องกังวล ฉันไม่ได้บอกว่าเธอได้ละเมิดกฎหมายการพิจารณาคดีเข้าให้แล้วสักหน่อย",
  str_voice_1600891_8 = "ไปเถอะ ถ้าเธอยืนยันที่จะนำตัวเองไปพบกับอันตราย ฉันจะไม่ยับยั้งเธอ... แต่ช่วยให้ฉันไปกับเธอด้วยเถอะนะ มันจะปลอดภัยกว่ามาก",
  str_voice_1600891_9 = "ทุกย่างก้าวที่เธอเดินตอนนี้จะช่วยส่งเสริมการรอดพ้นของเธอ ดังนั้นจงก้าวเดินต่อไป ไม่ต้องกังวลว่าอะไรอยู่ข้างหน้า เพราะดวงอาทิตย์จะขึ้นจากด้านหลังของเธอ",
  str_voice_1600891_10 = "เธอยังอยู่รึเปล่า ฉ-ฉันพักที่นี่สักเดี๋ยวได้ไหม ฉันไม่คิดว่าฉันจะทนได้อีกนานนัก ฉันจะพักสักครู่นะ",
  str_voice_1600891_11 = "อย่าคาดหวังอะไรจากฉันมาก เพราะว่าฉันไม่ได้มีอะไรจะเลี้ยงตัวเองมากนัก ฉันมีแค่เลือดเนื้อ รวมถึงจิตวิญญาณกับความทรงจำ",
  str_voice_1600891_12 = "ฉันจะรับผิดชอบเฉพาะหน้าที่ที่ฉันจดจำได้เท่านั้น ฉันเพียงแค่ต้องตัดสินใจว่าจะไปต่อหรือเปล่า",
  str_voice_1600891_13 = "คทานี้ยาวเกินไปสำหรับฉัน แต่ฉันจะใช้จนกว่ามันจะพัง",
  str_voice_1600891_14 = "เธอควรมีบ้านไว้ในใจเสมอและเปิดใจให้กว้าง... เรื่องนี้มีคนสอนฉันมา และฉันก็เห็นด้วยนะ",
  str_voice_1600891_15 = "การเกิดไม่ได้นำมาซึ่งความสุขเสมอไป แต่ยังไงฉันก็เอาแอปเปิลมาให้เธอนะ ฉันหวังว่าเธอจะชอบ",
  str_voice_1600891_16 = "เธอชอบมาปรากฏตัวใกล้ฉันตลอดเลย ซึ่งฉันคิดว่าช่างมีน้ำใจทีเดียว",
  str_voice_1600891_17 = "อรุณสวัสดิ์ ฉันทำนายเอาไว้เมื่อเช้าว่าวันนี้เราจะได้เห็นดาวประกายพรึกบนฟ้าเหนือศีรษะเรา",
  str_voice_1600891_18 = "แสงอาทิตย์เริ่มหายไป ให้ฉันสร้างแสงสว่างที่นี่... มันคือมุกของผู้พิพากษาสูงสุด ตลกดีไหม",
  str_voice_1600891_19 = "เธอดูเหนื่อยนะ อย่าบังคับตัวเองให้ทำงานหนักมากนักเลยเวลาที่เหนื่อยล้า พักผ่อนบ้าง",
  str_voice_1600891_20 = "ออเดอร์ผงาดขึ้นพร้อมกับดวงอาทิตย์ เพื่อให้เราทั้งหมดได้มีชีวิตรอดหลังตะวันตกดิน",
  str_voice_1600891_21 = "ถ้าตัดเรื่องสถานะของฉันออกไป ฉันก็ยังสงสัยนะว่าเราจะรู้ได้ยังไงว่าความจริงไม่ได้เป็นเรื่องนามธรรม หรือเป็นรูปแบบของการหลบหนี",
  str_voice_1600891_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1600891_23 = "มันอาจเป็นพรอะไรสักอย่างก็ได้ที่มีจิตใจว่างเปล่า เนื่องจากโลกนี้จะแตกต่างไปจากเดิมมากทีเดียวเมื่อเธอมีความตระหนักรู้ของตัวเอง",
  str_voice_1600891_24 = "ฉันชื่นชมคุณยูริอาห์ที่มีความแข็งแกร่งและอิสรภาพ รวมทั้งความกล้าหาญของเธอในการละทิ้งทุกอย่างไปหมด",
  str_voice_1600891_25 = "ท่าทางที่สงบนิ่งของคุณคาร์ลีนทำให้เธอมีทางเลือกในชีวิตมากขึ้นซึ่งแตกต่างไปจากของฉัน",
  str_voice_1600891_26 = "ฉันเลือกดาบแห่งการหยิบยืมมาเป็นอาวุธของฉัน ฉันชอบมันมากเลย",
  str_voice_1600891_27 = "ฉันเกลียดพวกที่มีนิสัยเห็นแก่ตัว หยิ่งยโส และอวดดีมาตั้งนานแล้ว",
  str_voice_1600891_28 = "แม้ว่ามันจะเป็นเรลิกแห่งอดีต แต่มันต้องมีความสำคัญต่อเธอมาก ๆ เลยแน่นอน",
  str_voice_1600891_29 = "ยินดีที่ได้รู้จักนะ ฉันชื่ออิริดอน ผู้พิพากษาสูงสุดแห่งลูโมโพลิส ถ้าเธอมีคำร้องที่สมเหตุสมผล ก็ให้ฤดูใบไม้ผลิและผืนป่าตอบรับความปรารถนาที่ปรากฏวับวาบในสายฟ้าเงียบงันได้เลย",
  str_voice_1600891_30 = "ฉันยอมรับความกดดัน",
  str_voice_1600891_31 = "ห่อหุ้มก้อนหินและขัดมันให้เป็นไข่มุกเลย",
  str_voice_1600891_32 = "สายฟ้าและฟ้าแลบจะวับวาบในความมืด",
  str_voice_1600891_33 = "ฉันกำลังรอดาวประกายพรึก",
  str_voice_1600891_34 = "ความเงียบสงัด",
  str_voice_1600891_35 = "ได้เวลาพิพากษาแล้ว",
  str_voice_1600891_36 = "เวลาของเธอหมดแล้ว",
  str_voice_1600891_37 = "ฮึ การแก้ต่างของเธอไม่มีมูลความจริง",
  str_voice_1600891_38 = "ปล่อยให้ฟ้าร้องฟ้าผ่าเงียบลง และให้พายุสงบลงก่อน",
  str_voice_1600891_39 = "แยกส่วน!",
  str_voice_1600891_40 = "นี่คือคำตัดสินของฉัน",
  str_voice_1600891_41 = "ด-เดี๋ยว ฉันเดินเร็วขนาดนั้นไม่ได้หรอก!",
  str_voice_1600891_42 = "เก็บของซะ ได้เวลาไปกันแล้ว",
  str_voice_1600891_43 = "ฉันยังไปต่อได้อีก...",
  str_voice_1600891_44 = "ถ้าเวลาเอื้ออำนวย... วันนี้ฉันจะเล่าเรื่องราวเกี่ยวกับสิ่งต่าง ๆ ที่อยู่ใต้น้ำให้ฟัง",
  str_voice_1600891_45 = "ฉันจะรับไว้เป็นการส่วนตัว แต่ฉ้นก็ยังสับสนอยู่เล็กน้อย",
  str_voice_1600891_46 = "ขอบคุณนะ ฉันจะรับความตั้งใจดีของเธอเอาไว้",
  str_voice_1600891_47 = "ไม่มีใครเข้าใจผิดหรอก ด้วยความสัมพันธ์ของเราแล้ว",
  str_voice_1600891_48 = "ขอบคุณนะสำหรับความใส่ใจและความอ่อนโยนเหมือนเคย",
  str_voice_1600891_49 = "ให้ความเจ็บปวด ปัญหา ความเศร้าโศก และการร่ำไห้ทั้งหมดของฉันคงซุกซ่อนอยู่ใต้น้ำต่อไป เพื่อไม่ให้มันขัดขวางการกระทำของฉัน แม้ว่ามันจะกระจัดกระจายออกไปก็ตาม",
  str_voice_1600891_50 = "ฉันขังตัวเองด้วยกุญแจมือที่ไม่อาจหลบหนีได้ มันก็เหมือนหนองน้ำกับผืนป่าสีทอง และเงามืดที่ฉันกลัว",
  str_voice_1600891_51 = "เพราะครั้งหนึ่งขาทั้งสองของฉันเคยได้รับบาดเจ็บสาหัส เพื่อให้ยืนขึ้นได้อีกครั้ง ฉันต้องเย็บมันกลับคืนที่ด้วยเส้นด้ายสายฟ้า แค่รอดมาได้นี่ก็เกินพอแล้ว",
  str_voice_1600891_52 = "Alchemy Stars",
  str_voice_1600891_53 = "สวัสดี",
  str_voice_1600891_54 = "อรุณสวัสดิ์",
  str_voice_1600891_55 = "ฉันกวนเธอรึเปล่า",
  str_voice_1600891_56 = "สายัณห์สวัสดิ์ ฉันหวังว่าคืนนี้พระจันทร์จะสวยนะ",
  str_voice_1600891_57 = "ปีใหม่มาถึงแล้ว ฉันขอให้เธอมีความสุขนะ",
  str_voice_1300461_1 = "- โคลอสซัสจะรีบไปไหน\n- เพราะถ้าท่านผู้นำทางตื่นสาย\n- อาหารฟรีจะเย็นเสียก่อน♪",
  str_voice_1300461_2 = "- โอ้♪\n- ผู้นำทางผู้งามสง่าและน่าทึ่ง♪ - จงอย่าได้ก้มหัว♪\n- หัวล้านของเธอ - เริ่มลามแล้วนะจ๊ะ♪",
  str_voice_1300461_3 = "- เธอมาหาพวกเราอีกแล้ว\n- อีกแล้ว!\n- ดูซิ โผล่มาอยู่ได้\n- เธอต้องยังโสดอยู่แน่เลย! เธอโสดใช่ไหมหืม?",
  str_voice_1300461_4 = "- ดูแลอย่างดีโดยชนชั้นสูง หวงแหนอยู่ในมือพวกเขา!\n- แต่ไม่อาจมอบให้ใครอื่นได้\n- โอ้ ช่างไม่อาย เธอช่างไม่อายจริง ๆ♪",
  str_voice_1300461_5 = "- โอ้! - พวกเธอผู้เลวทราม! ♪\n- คู่แข่งที่รักยิ่งของเรา... ♪ - เราจะเหยียบย่ำพวกเธอให้เหมือนแมลง! ♪",
  str_voice_1300461_6 = "- จะสนใจทำไมนัก\n- จะรีบร้อนเพื่ออะไร\n- เรามันก็แค่คนผ่านมาและผ่านไป♪ ผู้นำทางพวกมันสู่นรก♪",
  str_voice_1300461_7 = "- ชาวอุษาวิทยาลัย♪\n- ทุกคนช่างโง่สุดใจ♪\n- แต่พวกขุนนางลูโมโพลิส♪\n- พวกนี้โง่ยิ่งกว่าโง่สุดชีวิต♪",
  str_voice_1300461_8 = "- ยิ่งตัวสูงเติบใหญ่ - ยิ่งโง่เข้าไป♪\n- ยิ่งแก่เท่าไหน ยิ่งโง่เข้าไป♪\n- แต่ไม่ต้องกลุ้มใจ เพราะเธอนั้นเยาว์วัยและเตี้ยกว่าใคร♪",
  str_voice_1300461_9 = "- โอ้♪\n- ขุนนางนี่ช่างน่าเบื่อ♪\n- พวกเขาไม่เหมือนกับเธอเลยไง♪\n- ทั้งน่ารักและใสใส♪\n- อย่าลืมว่าไร้สมองอีกด้วย♪",
  str_voice_1300461_10 = "- สถานที่น่าเบื่อ\n- มีแต่ขุนนางที่น่าเบื่อ\n- พวกเขาฆ่าเวลายังไง♪\n- ไปนอนดีกว่าไหม♪",
  str_voice_1300461_11 = "- ให้เราร้องเพลงหรือ\n- เธอน่ะคิดมากไป\n- วิเศษไปเลย",
  str_voice_1300461_12 = "- เธอยังฟังไม่พออีกเหรอ\n- เธอชอบขนาดนั้นเลยเหรอ",
  str_voice_1300461_13 = "- ถ้าเธอไม่มีอะไรทำ♪\n- ทำไมไม่โกนหัวซะล่ะ♪\n- โกนให้เกลี้ยงเลยนะ♪\n- จะได้นอนเท่บนเตียงไงล่ะ♪",
  str_voice_1300461_14 = "- สี่ขาจากที่ไกล\n- สองขาใกล้ ๆ\n- เธอเป็นตัวอะไร ท่านผู้นำทางรึไง\n- เละเทะมากเลยพวกนี้!",
  str_voice_1300461_15 = "- ได้เวลาแล้ว♪\n- เวลาที่เราจะจุดเทียนให้เธอ!",
  str_voice_1300461_16 = "- เธออีกแล้ว!\n- เธอกลับมาอีกแล้ว!\n- ยังมีชีวิตและดิ้นรน",
  str_voice_1300461_17 = "- ยิ่งเธอตื่นเร็วแค่ไหน\n- ยิ่งหัวล้านไวแค่นั้น\n- ทำไมไม่พักต่ออีกล่ะ\n- ทำไมขยันขนาดนั้น",
  str_voice_1300461_18 = "- เธอมา\n- เธอไป\n- แต่หน้าเธอนั้น\n- มันเหมือนเมื่อก่อนเลยไง!",
  str_voice_1300461_19 = "- ดึกดื่นทำไมไม่นอน\n- มันบังเอิญมีแรงใจ\n- หรือว่าแค่หลับไม่ลง",
  str_voice_1300461_20 = "- เล็กน้อยเท่านั้น...\n- แต่เราก็ยังภูมิใจ!\n- เท้าของเราแตะพื้นดิน\n- แต่ในใจลอยไปในหมู่เมฆขาว!",
  str_voice_1300461_21 = "- พวกเขาเห็นความจริงหรือยัง\n- ด้วยตาที่ถูกปิดบัง",
  str_voice_1300461_22 = "ขอเทิดทูนรัตติกาลสีขาว♪",
  str_voice_1300461_23 = "- ฝนตกขี้หมูไหล♪\n- คนอะไรมาพบกัน♪",
  str_voice_1300461_24 = "- คาร์ลีนไม่ได้สอนบทเรียนให้หรือ\n- ยังไม่ได้รับบทเรียนอีกหรือ\n- บทเรียนล้ำค่าเลยนะเออ!",
  str_voice_1300461_25 = "- เพื่อนรักที่สุดของเรา\n- ที่สอนเรามาอย่างดี\n- ให้เป็นคนอ่อนโยนและเมตตา\n- เพื่อจะเอ่ยคำลา!",
  str_voice_1300461_26 = "- อย่าได้อวดดีไป\n- รู้จักมีสติสักหน่อย\n- ไม่ได้หรือไง หรือไม่ยอมทำ",
  str_voice_1300461_27 = "- พวกผู้ใหญ่ไร้ประโยชน์\n- ไม่หัดดูตัวเองในกระจกเหรอ\n- ไม่เห็นเหรอว่าตัวเองเป็นใคร",
  str_voice_1300461_28 = "- นี่โคลอสซัสของเธอหรือ\n- ใหญ่โตนะนั่น\n- แถมซีดเซียวด้วยนะเออ",
  str_voice_1300461_29 = "- เพื่อนรักเอ๋ย\n- จากลูโมโพลิส เราร้องเรียก\n- ริมฝีปากเราหวานเจี๊ยบ\n- คำพูดคำจาของเราก็เช่นกัน\n- ใช่เลยแหละ!",
  str_voice_1300461_30 = "เราคือกัปตันของเราเอง♪",
  str_voice_1300461_31 = "พวกผู้ใหญ่ร้องเพลงบ่อยขึ้น",
  str_voice_1300461_32 = "จนกว่าพวกเขาจะจากไป♪",
  str_voice_1300461_33 = "- ทิ่มแทงพวกมันให้ทะลุ\n- บดขยี้วิญญาณของพวกมัน!",
  str_voice_1300461_34 = "ให้เราช่วยร้องประสานเสียงไหม",
  str_voice_1300461_35 = "โอ้ เธอรอไม่ไหวแล้วเหรอ",
  str_voice_1300461_36 = "งั้นเรามาร้องเพลงกันเลย!",
  str_voice_1300461_37 = "- โอ้♪\n- เพลงรักแห่งสีดำขาว♪",
  str_voice_1300461_38 = "- เหนือศิลาหน้าหลุมศพ♪\n- พวกเขาทะยานขึ้นไป♪",
  str_voice_1300461_39 = "ช่างน่าเบื่อ♪",
  str_voice_1300461_40 = "ช่างตลก♪",
  str_voice_1300461_41 = "- โอ้\n- เจ้างั่งที่อยู่ตรงนั้น♪\n- ช่างน่าเกลียดจังเลย♪",
  str_voice_1300461_42 = "- เธอยังไม่ได้รับบทเรียนอีกหรือ\n- บทเรียนล้ำค่าเลยนะเออ!",
  str_voice_1300461_43 = "- กลับบ้าน!\n- กลับบ้าน!\n- หันหัวกลับบ้านมือเปล่า!",
  str_voice_1300461_44 = "- ฝนหยุดตกรึยัง\n- ดวงอาทิตย์เผยตัวออกมาจากหลังม่านเมฆรึยัง\n- เธอทำหน้าที่ได้อีกครั้งรึยัง",
  str_voice_1300461_45 = "- ของขวัญจากเธอเหรอ\n- ถ้าเธอเรียกนี่ว่าของขวัญ",
  str_voice_1300461_46 = "- เอ้อ นี่สิของขวัญ!\n- นี่สิของขวัญ!",
  str_voice_1300461_47 = "- เธอเลือกของขวัญแบบนี้เหรอ\n- จริงเหรอ",
  str_voice_1300461_48 = "- เธอพยายามมากเลย\n- ต้องขอบคุณให้ได้ล่ะ!",
  str_voice_1300461_49 = "- พวกขุนนาง♪\n- ฉ้อฉล♪\n- โง่เขลา♪\n- น่าเบื่อ♪\n- คำพูดไร้ความหมายของพวกเขา ทำให้ทุกคนพากันนอนกรน!",
  str_voice_1300461_50 = "- การต่อสู้ที่ดุเดือด\n- การแสดงกลยุทธ์การซ้อมที่ทรงพลัง\n- ต่อสู้ให้เหมือนพ่อไก่ในสนามรบ!",
  str_voice_1300461_51 = "- ปิแอร์มีรอยยิ้มเสมอ\n- ดีแอนจะเป็นอัศวินที่แข็งแกร่ง\n- คาราคือผู้ปกป้องของเรา\n- นีเอลอ่านหนังสือทั้งวัน\n- ยังไม่เห็นความแตกต่างอีกเหรอ",
  str_voice_1300461_52 = "Alchemy Stars♪",
  str_voice_1300461_53 = "สวัสดี ท่านอาจารย์ผู้นำทาง♪",
  str_voice_1300461_54 = "- อรุณสวัสดิ์♪\n- เธอตื่นรึยัง\n- ยังอยากนอนต่อเหรอ",
  str_voice_1300461_55 = "- สวัสดีตอนบ่าย♪\n- เธอว่างรึเปล่า",
  str_voice_1300461_56 = "- สายัณห์สวัสดิ์♪\n- ดูแลเส้นผมของเธอด้วยนะ♪",
  str_voice_1300461_57 = "- สุขสันต์วันปีใหม่♪\n- ขอให้เป็นปีที่ดีนะ♪",
  str_voice_1300531_1 = "โอ้ บ้าเอ๊ย บอส รอยยิ้มของเธอทิ่มแทงใจฉันจังเลย! ช่วยเอากระเป๋าตังค์ออกมาแล้วแสดงให้ทุกคนเห็นทีว่า ฉันโชคดีแค่ไหนที่ได้รับใช้เธอนะบอส!",
  str_voice_1300531_2 = "บอสที่รัก สัตว์พวกนี้น่ารักมากเลย คุ้มค่ากับเงินของเธออย่างแน่นอน! ฉันได้แต่หวังว่าชาติหน้าฉันจะได้เป็นปั๊ปปี้ของบอสนะ!",
  str_voice_1300531_3 = "มาดูสิว่าฉันมีอะไรในเป้! ถ้าไม่ตรงกับความพึงพอใจของเธอ ฉันยังขายเวลาของฉันให้เธอได้อีกนะวันนี้ ราคาเท่านี้เองบอส!",
  str_voice_1300531_4 = "มาหาฉันนะถ้าเธออยากได้อะไร ฉันไม่ใช่ผู้ที่ไร้พลังอีกต่อไปแล้ว ไม่ว่าจะอาวุธหรือโล่ ฉันจะให้ราคาที่ยุติธรรมกับเธอเสมอ!",
  str_voice_1300531_5 = "หนึ่งร้อยไนท์เทียมยอมหันหน้า หนึ่งพันไนท์เทียมยอมอ้าปาก หนึ่งหมื่นไนท์เทียมก็... โอ้โห ไอเลิฟยูจุ๊บ ๆ ทั้งหมดราคายุติธรรมนะ ไม่ต้องกังวล",
  str_voice_1300531_7 = "บอสที่รัก ไม่ต้องสนใจนะที่ฉันพูดมากขนาดนี้ มันแค่เพราะว่าฉันเก็บความรักที่มีต่อเธอไว้ไม่ไหว โดยเฉพาะเวลาที่เธอเปย์ไง!",
  str_voice_1300531_8 = "บอส ฉันซาบซึ้งกับน้ำใจของเธอจัง ฉันหวังว่าฉันจะได้อยู่เคียงข้างเธอนะ โดยเฉพาะเวลาที่เธออยากซื้อ ซื้อ แล้วก็ซื้อ!",
  str_voice_1300531_9 = "ฉันก็ไม่ค่อยมีอะไรจะให้เธอฟรี ๆ หรอก ยกเว้นความภักดีที่ไม่มีวันสิ้นสุดของฉัน เรื่องนี้ฉันสัญญาได้เลย!",
  str_voice_1300531_10 = "เวลาเป็นเงินเป็นทอง... แต่ตราบใดที่ฉันอยู่กับบอสที่รัก ฉันก็รู้ว่าเธอจะจ่ายคืนให้ฉัน!",
  str_voice_1300531_11 = "บอสที่รัก ถ้าให้ทองฉันแสนเหรียญ ฉันจะเป็นปั๊ปปี้ตัวน้อยของเธอ ฉันอยากกระดิกหางให้เธอดูเลยนะถ้าฉันทำได้!",
  str_voice_1300531_12 = "บอส ค่าบริการ ค่าสั่งงาน ค่าความคิดถึง... ได้เวลาเปย์แล้ว!",
  str_voice_1300531_13 = "มีอีกชุดใหญ่เลย! ฉันจะขายอะไรและขายให้ใครต่อไปดีนะ",
  str_voice_1300531_14 = "หืม ฉันรู้สึกถึงอะไรบางอย่าง... มันคือสัตว์ตัวเล็ก ๆ เหรอ ไม่นะ! มันก็ยังเป็นเงินอยู่ดี!",
  str_voice_1300531_15 = "บอสที่รัก สุขสันต์วันเกิด! เค้ก ของขวัญ และคำอวยพรของเธอ รวมเป็นทองแค่แสนเหรียญเท่านั้นเอง!",
  str_voice_1300531_16 = "บอส! ในที่สุดเธอก็กลับมาแล้ว! นี่ฉันเตรียมบิลเก็บเงินไว้เรียบร้อยแล้วตอนที่เธอไม่อยู่!",
  str_voice_1300531_17 = "อรุณสวัสดิ์ บอส! วันนี้อากาศดีนะ เดี๋ยวฉันเอาบิลเก็บเงินของเมื่อวานให้ดู",
  str_voice_1300531_18 = "บอส รับอาหารไหม ขนมล่ะ หรือรับความบันเทิงหน่อยดี?",
  str_voice_1300531_19 = "บอส เธอไปนอนพักหน่อยดีไหม ไม่งั้นตัวเลขจะเริ่มพอกพูนขึ้นอีกนะ",
  str_voice_1300531_20 = "เรดีเซล เวรนช์ มีชื่อเสียงมาก! ตลาดที่ยังไม่พัฒนานี่ทำให้ฉันกระเป๋าตุงทุกวันเลย!",
  str_voice_1300531_21 = "พวกผู้แสวงหาความจริงไม่เข้าใจแนวคิดนั้นจริง ๆ ใช่ไหมที่ว่า \"ของฟรีนั่นแหละที่ราคาแพงที่สุด\" น่าสมเพชอ่ะ",
  str_voice_1300531_22 = "จ่ายมา!",
  str_voice_1300531_23 = "มีแต่พวกจะขอฟรี... นี่รู้กันบ้างรึเปล่าว่าเงินทองน่ะมีค่าแค่ไหน",
  str_voice_1300531_24 = "ทักษะที่ดีมันมีค่ามากนะ ฉันก็เลยต้องรักษาความสัมพันธ์ที่ดีกับเธอเอาไว้ อันนั้นมันแน่นอน!",
  str_voice_1300531_25 = "พวกที่ไม่ใช่สัตว์ แต่แกล้งทำตัวเป็นสัตว์ แล้วก็มีหัวสัตว์เนี่ยนะ เหลือเชื่อเลย!",
  str_voice_1300531_26 = "ให้ฉันแนะนำตัวก่อนนะ ฉันชอบสัตว์น่ารัก ๆ เงินทอง แล้วก็สิ่งของล้ำค่า",
  str_voice_1300531_27 = "ได้รับออเดอร์สอบถามแล้ว ฉันจะตอบให้นะ ฉันรังเกียจความโลภ",
  str_voice_1300531_28 = "ฉันใช้สายตาพ่อค้าของฉันบอกได้เลยว่า โคลอสซัสที่ทรงพลังนี้เป็นเกียรติกับเธอมากเลย และต้องแพงแน่นอน!",
  str_voice_1300531_29 = "ฮ่าฮ่า! บอสใหม่มาแล้ว! บอสที่รัก จะรับอะไรดีล่ะ ฉันมีทุกอย่างที่เงินซื้อได้เลยนะ!",
  str_voice_1300531_30 = "ยังหาเงินเพิ่มได้อีก!",
  str_voice_1300531_31 = "ทั้งหมดก็เพื่อบอสที่รักของฉันอยู่แล้ว!",
  str_voice_1300531_32 = "ทักษะการขายเท่ากับกำไร",
  str_voice_1300531_34 = "ตามคำสั่งของบอส!",
  str_voice_1300531_35 = "การโจมตีสุดโหดใช่ไหม รอแป๊บนะ!",
  str_voice_1300531_36 = "เธอเตรียมเงินให้ฉันพร้อมรึยัง",
  str_voice_1300531_37 = "จ้างฉันสิบอส แล้วฉันจะกัดใครก็ได้ตามที่สั่งเลย!",
  str_voice_1300531_38 = "โจมตีด้วยราคา! ไม่คืนเงิน!",
  str_voice_1300531_39 = "ดูนี่สิบอส!",
  str_voice_1300531_40 = "โอ้โห ดาบสวยนะนั่น!",
  str_voice_1300531_41 = "ทุกคนต้องจ่าย ไม่มีใครหนีไปได้♪",
  str_voice_1300531_42 = "นี่คือบิลเก็บเงินค่าชัยชนะ!",
  str_voice_1300531_43 = "โธ่เอ๊ย อย่าเศร้าไปเลย ฉันลดให้นิดหน่อยโอเคป่ะล่ะ...",
  str_voice_1300531_44 = "ขนมเรดีเซล อิกัวนาเสียบไม้... รับหนึ่งที่นะ",
  str_voice_1300531_45 = "คราวหน้าเธออาจให้อะไรที่มีมูลค่ามากกว่านี้กับฉันมั้งนะ?",
  str_voice_1300531_46 = "นี่มันล้ำค่ามากเลยจริง ๆ ฉันอยากได้จากเธอเพิ่มอีกจังเลย!",
  str_voice_1300531_47 = "รอยยิ้มของบอสมีค่ามากกว่าของขวัญชิ้นนี้นะ",
  str_voice_1300531_48 = "บอส ขอบคุณนะที่เตือนฉันเสมอเลยว่าฉันไม่สามารถตีราคามิตรภาพของเราได้",
  str_voice_1300531_49 = "ระวังนะ เงินจะดึงความชั่วร้ายออกมา... แต่ฉันไม่ทำตัวแบบนั้นหรอก ดังนั้นเธอไม่ต้องกังวลเวลาจ่ายเงินให้ฉันเลย",
  str_voice_1300531_50 = "เอาปั๊ปปี้มาเลี้ยงสิถ้าเธอเหงา สัตว์น่ะไม่เหมือนคนนะ มันซับซ้อนน้อยกว่ากันมาก... หรือเธอจะเลี้ยงฉันก็ได้!",
  str_voice_1300531_52 = "Alchemy Stars!",
  str_voice_1300531_53 = "บอสที่รักของฉัน!",
  str_voice_1300531_54 = "ยามเช้าที่งดงาม สำหรับเธอโดยเฉพาะเลยบอส!",
  str_voice_1300531_55 = "ยามบ่ายที่สวยงาม สำหรับเธอโดยเฉพาะเลยบอส!",
  str_voice_1300531_56 = "ช่วงค่ำสบาย ๆ แล้วก็บิลเก็บเงินของเธอ สำหรับเธอโดยเฉพาะเลยบอส!",
  str_voice_1300531_57 = "สุขสันต์วันปีใหม่! รวมแล้วหนึ่งหมื่นเหรียญทองนะ!",
  str_voice_1400731_1 = "- แยกแพตตี้กับแพตซี่ไม่ออกเหรอ งั้นจำแบบนี้\n- แพตซี่ชอบจิ้มตูด\n- แพตตี้ชอบงับมือ",
  str_voice_1400731_2 = "- ได้เสมอตราบใดที่เรามีอาหาร\n- ไม่มีอะไรต้องกังวลอีก\n- ความรู้สึกเหรอ มันคืออะไรล่ะ\n- รสชาติดีไหม\n- เร็วเข้า! กินให้ดูหน่อย!",
  str_voice_1400731_3 = "- เราคือภูตน้อย\n- ก็เลยมีเขาไงล่ะ\n- เราคือปั๊ปปี้\n- ก็เลยมีหางไงล่ะ\n- เรามีตรีศูล ก็เลยอยากทำร้ายเธอไงล่ะ!",
  str_voice_1400731_4 = "- ฮาวด์ไฟร์ จมูกยื่น\n- เรามีความสามารถพวกนี้เพราะว่าเราเป็นน้องหมา\n- มันก็ปกติไม่ใช่เหรอ\n- อ๋อ ใช่แล้ว เธอไม่รู้หรอกเพราะว่าเธอไม่มีหาง",
  str_voice_1400731_5 = "- ไฟนรกลุกโชน ลุกโชน ลุกโชน♪\n- ไฟนรกลุกโชน หนีเร็วปั๊ปปี้♪",
  str_voice_1400731_6 = "- ประตูนรกเปิดแล้ว - ที่จริงก็เปิดตั้งนานมาแล้วนะ\n- แต่เราคือผู้เฝ้าประตู - เราจะไม่ปล่อยให้ใครออกไป ถ้าผู้นั้นไม่ควรได้ออกไป!",
  str_voice_1400731_7 = "- ให้เราทรมานเธอเถอะ! \n- ไม่ได้ให้ต่อรอง!\n- ตอนที่เราจับอีสต์วานมาทรมาน...\n- เขาก็ไม่ได้พูดอะไรมากเหมือนกัน!",
  str_voice_1400731_8 = "- แพตตี้กับแพตซี่ไม่สามารถแยกจากกันได้\n- ไม่งั้นหัวใจของเราจะหยุดเต้น\n- แล้วปั๊ปปี้ล่ะ\n- ทำให้หัวใจของปั๊ปปี้หยุดเต้นด้วยสิ!",
  str_voice_1400731_9 = "- กลัวตกนรกเหรอ - ถ้าตกลงไปละก็...\n- แค่เรียกชื่อพวกเรา เราจะเปิดประตูแล้วพาออกมาเอง",
  str_voice_1400731_10 = "- เบื่อมาก\n- เราทำอะไรสนุก ๆ กันดีล่ะ\n- วิ่งเลย ปั๊ปปี้ วิ่ง เราไล่ตามมาแล้ว! ว่ะฮะฮ่า!",
  str_voice_1400731_11 = "- เราคืออะไร\n- เธอมีโอกาสอีกครั้งที่จะตอบให้ถูกต้อง!\n- ใช่แล้ว เราคือภูตน้อยผู้เฝ้าประตู! ว่ะฮะฮ่า!",
  str_voice_1400731_12 = "- มาเริ่มเล่นซ่อนหากันได้แล้ว\n- สาม สอง หนึ่ง!\n- เราเจอเธอแล้ว! วะฮะฮ่าฮิ้ววววู้!",
  str_voice_1400731_13 = "- แพตซี่มีหาง\n- แพตตี้ก็มีหางด้วยเหมือนกัน\n- แล้วหางของอีสต์วานล่ะอยู่ไหน\n- ฉันไม่เคยเห็น",
  str_voice_1400731_14 = "- ก่อนอื่น จุดไฟฮาวด์ไฟร์!\n- จากนั้นก็ชูคราดของภูตน้อย!\n- สุดท้าย คือไล่ตามปั๊ปปี้!",
  str_voice_1400731_15 = "- เราอยากฉลองกับเธอในวันนี้!\n- เล่นซ่อนหาเหรอ\n- ล่าสมบัติเหรอ\n- เอาหางไปผูกกับลาเหรอ มาเถอะ มาเล่นกัน!",
  str_voice_1400731_16 = "- ระวังน้องหมาน่ารัก ๆ\n- เข้ามาได้เลย!\n- และพอเข้ามาแล้ว เราก็จะวิ่งไล่ให้นรกแตกเลย!",
  str_voice_1400731_17 = "- ปั๊ปปี้มาแล้ว!\n- ตื่นแล้วเหรอ\n- ไม่เห็นหางเลยดูไม่ออก\n- น่าสงสารจัง",
  str_voice_1400731_18 = "- หิว - อยากกินอีก\n- ลูกหมาที่เป็นเนื้อ - เราก็กินได้นะ",
  str_voice_1400731_19 = "- ง่วงจัง... - ปั๊ปปี้มานี่!\n- ยังไงต่อดี - เล่นกับปั๊ปปี้ดีกว่า",
  str_voice_1400731_20 = "- มีคนเคยบอกว่า\n- ที่นั่นมีชีวิตแบบที่เราตามหา\n- เราไม่ได้สนใจเรื่อง \"ชีวิต\" มากนักหรอก\n- สิ่งที่เรา \"ตามหา\" สำคัญกว่า!",
  str_voice_1400731_21 = "- สีขาว... \n- ลอยอยู่บนฟ้า...\n- สถานที่สะอาด ๆ ที่มีอาหาร!\n- สถานที่ที่บุคคลผู้นั้นอยากไป...",
  str_voice_1400731_22 = "น้องหมาเฝ้าดูเธออยู่นะ!",
  str_voice_1400731_23 = "- อิคลิพไซท์มีรสชาติน่ารังเกียจมากสำหรับพวกเขา\n- พวกนี้อยู่รวมกันแล้วน่าสะพรึงกลัวมาก\n- แค่สองสามตัวน่ะไม่เป็นไร - กำจัดให้หมดเลย!",
  str_voice_1400731_24 = "- เรากินเพื่อน ๆ เราไม่ได้... \n- แต่ก็ยังวิ่งไล่พวกเขาได้อยู่!\n- โดยเฉพาะอีกากระพือปีกนั่น...\n- นั่นแหละคือเพื่อนที่น่าวิ่งไล่ให้สนุกไปเลย!",
  str_voice_1400731_25 = "- บุคคลหน้าเศร้าผู้นั้น...\n- รักหมาจริง ๆ!\n- เขาอาจไม่แสดงอารมณ์ออกมามากนัก... \n- แต่เขาเป็นคนดีนะ!",
  str_voice_1400731_26 = "- เราชอบกินอาหาร\n- วิ่งไล่คนอื่น\n- หางของเรา แล้วก็เขาปีศาจ... \n- อ้อ แล้วก็คนรักหมา!",
  str_voice_1400731_27 = "- คนที่เกลียดหมาน่ะเป็นคนไม่ดี!\n- ทนกลิ่นเลือดไม่ได้!",
  str_voice_1400731_28 = "- เยี่ยมเลยแบบนี้!\n- ข้างในกว้างขวางมาก!\n- เราวิ่งเล่นกันได้... \n- เล่นซ่อนหา...\n- เฮ้ อันนั้นเราแทะได้ไหม\n- ฉันว่าต้องได้แน่เลย!",
  str_voice_1400731_29 = "- แพตตี้... \n- แพตซี่... \n- ปั๊ปปี้!\n- ใครคือปั๊ปปี้\n- ปั๊ปปี้ก็คือน้องหมาของเรา...\n- ใครจะเป็นน้องหมาน่ะ ก็เธออยู่แล้วน่ะสิ! ฮิ้ววว!",
  str_voice_1400731_30 = "- ได้เลยฮาฟฟฟ!\n- พลังของความน่าอร่อย!",
  str_voice_1400731_31 = "- ไฟมันใหญ่ขึ้นนะ!\n- จมูกของเราทำงานได้ดีขึ้น!",
  str_voice_1400731_32 = "- เพิ่มพลังของเหล่าภูตน้อย!\n- เพิ่มพลังแห่งนรก!",
  str_voice_1400731_33 = "- ฉันเห็นแล้ว!\n- ประตูสู่นรก!\n- อยู่นี่เอง!",
  str_voice_1400731_34 = "น้องหมาโจมตี!",
  str_voice_1400731_35 = "เตรียมหางให้พร้อม!",
  str_voice_1400731_36 = "อวดคราดเหรอ",
  str_voice_1400731_37 = "อ้อ เปลวไฟจากนรก เผาพวกมันให้เกรียมเลย!",
  str_voice_1400731_38 = "เปิด... ประตูสู่นรก! ไฟนรก... ลุกท่วม!",
  str_voice_1400731_39 = "- บึ้ม!\n- ฮ่าฮ่า!",
  str_voice_1400731_40 = "ขอแบบสุก ๆ นะ!",
  str_voice_1400731_41 = "- ให้เหล่าภูตน้อยนำทางเธอไป!\n- ไปกันเลย!",
  str_voice_1400731_42 = "ดูของเด็ด ๆ ที่เราเจอสิ!",
  str_voice_1400731_43 = "- เฮ้อ...\n- ไม่สนุกเลย!",
  str_voice_1400731_44 = "เฮ้ เธอได้เอาอะไรดี ๆ มาให้เราสวาปามรึเปล่า",
  str_voice_1400731_45 = "- เอ่อ...\n- กลิ่น อั่ก แย่มาก...",
  str_voice_1400731_46 = "- ใช่เลย!\n- อันนี้กลิ่นดีเลิศมาก!",
  str_voice_1400731_47 = "- ปั๊ปปี้เอาอันนี้มา!\n- ต้องชอบแน่นอน!",
  str_voice_1400731_48 = "- มัน!\n- มัน!\n- ดีงามมาก!",
  str_voice_1400731_49 = "- น้องหมานี่เหมาะจะเล่นซ่อนหามาก!\n- ไม่ว่าเธอจะอยู่ที่ไหน...\n- ตราบใดที่เธอทิ้งกลิ่นเอาไว้... \n- ตราบใดที่เธอยังมีชีวิตอยู่...\n- เราหาเธอเจอแน่นอน!",
  str_voice_1400731_50 = "- เธอหาอาหารได้ตลอดเวลาในอัมบราตัน!\n- เพียงแค่ปล่อยให้คนที่กิลด์จับตัวเธอ\n- จากนั้นก็ตามตื๊อขออาหารจากพวกเขา!\n- พวกเขาต้องเอาอาหารให้เธอโดยไม่มีคำถามใด ๆ!",
  str_voice_1400731_51 = "- นั่นคือตอนที่เรารู้ว่าจะใช้ฮาวด์ไฟร์ได้ยังไง\n- อาหารปรุงสุกทำให้กระเพาะปั่นป่วนน้อยกว่านะ\n- แม้แต่สิ่งมีชีวิตตัวจิ๋วก็รอดได้\n- ตราบใดที่พวกมันมีความแข็งแกร่งและแรงใจที่จะผ่านไปให้ได้!",
  str_voice_1400731_52 = [[
- Alchemy!
- Stars!!]],
  str_voice_1400731_53 = "โย่! ปั๊ปปี้!",
  str_voice_1400731_54 = "- อรุณสวัสดิ์!\n- โฮ่ง!",
  str_voice_1400731_55 = "- อาหารกลางวัน\n- มื้อพิเศษ!",
  str_voice_1400731_56 = "- ค่ำแล้ว!\n- มาเล่นกันเถอะ!",
  str_voice_1400731_57 = "- มีความสุข!\n- ในปีจอ!",
  str_voice_1400791_1 = "งานของเจ้าหน้าที่สรรพากรไม่ได้ยากอะไรหรอก ที่ฉันต้องทำก็แค่เก็บไนท์เทียมแล้วก็ทำบันทึก เป็นอะไรที่ฉันทำได้ดี ฉันก็เลยทำได้เร็วมาก",
  str_voice_1400791_2 = "ใคร ๆ มักบอกว่าฉันน่ะไร้อารมณ์ความรู้สึก แต่ฉันคิดว่าจิตวิญญาณคือที่มาของดวงชะตาของคนเรานะ นี่ฉันยังไม่ได้ทำให้ทุกคนเห็นถึงโชคชะตาของฉันอย่างชัดเจนรึไง",
  str_voice_1400791_3 = "มูลค่าของสิ่งต่าง ๆ กำหนดโดยมาตรฐานการวัด สำหรับตอนนี้ เจ้าเมืองสำคัญกว่า ส่วนกัปตันทหารก็สำคัญน้อยกว่า สถานการณ์ของพวกเขาจะกลับกันหลังจากผ่านไปสามปี",
  str_voice_1400791_4 = "ตระกูลเก่าแก่ทั้งหมดจะต้องเสื่อมถอยไปในที่สุด แต่ตำนานแห่งการตัดสินที่ยุติธรรมของพวกเขาจะยังคงอยู่... อย่างน้อยนั่นคือสิ่งที่สะท้อนในการกระทำของฉัน",
  str_voice_1400791_5 = "ตราชูแห่งความยุติธรรมเป็นสิ่งที่ขับเคลื่อนด้วยศรัทธา ด้วยเกณฑ์มาตรฐานเป็นความเชื่อ ผู้คนจะถูกวัดจากการถามคำถาม ไม่มีถูกและผิด มีเพียงระดับความสำคัญเท่านั้น",
  str_voice_1400791_6 = "ผู้ที่ตัดสินคนอื่นได้ใช้หลักการพิจารณาคดีแบบเดียวกันรึเปล่า ฉันเชื่อว่าคำตอบคือใช่ แบบนั้นเท่านั้นดวงตามนุษย์จึงจะตัดสินได้ว่ามีความยุติธรรมอย่างแท้จริง...",
  str_voice_1400791_7 = "ฉันมักสงสัยเรื่องคุณค่าของการที่ฉันพูดคุยกับเธอที่นี่... อย่าสนใจฉันเลย ฉันทำไปเพราะความเคยชินเท่านั้นแหละ",
  str_voice_1400791_8 = "ฉันรู้สึกได้อย่างชัดเจนว่าเธอมีค่าต่างกัน นี่อะไร...โบนัสเหรอ อะไรที่ทำให้เธอแตกต่างจากคนอื่น",
  str_voice_1400791_9 = "บางครั้ง อยู่ดี ๆ ฉันก็มีความรู้สึกอยากจ่ายสิบไนท์เทียมให้เธอนะ แปลกไหมล่ะ แต่ฉันเข้าใจนะ ก็เหมือนที่ฉันเข้าใจว่าเธอมีความหมายกับฉันยังไง",
  str_voice_1400791_10 = "เธอกังวลเรื่องเวลารึเปล่า พักผ่อนไปเถอะ เวลาว่างมันดีต่อใจ ซึ่งจะช่วยสร้างมูลค่านะ",
  str_voice_1400791_11 = "เธอเรียกตัวฉันมาทำไมเหรอ ฉันไม่ค่อยเข้าใจ แต่ฉันจะประเมินมูลค่าของฉันที่มีต่อเธอดู",
  str_voice_1400791_12 = "ฉันขอโทษนะ คือฉัน... ฉันจะช่วยอะไรไม่ได้เลยถ้าไม่มีเครื่องมือวัด",
  str_voice_1400791_13 = "เธอเข้าใจไหมว่าสิ่งต่าง ๆ ส่วนใหญ่ในโลกนี้ ไม่มีอะไรถูกหรือผิดหรอก มีแค่ระดับความสำคัญเท่านั้นเอง",
  str_voice_1400791_14 = "อย่าได้ประเมินค่าให้สูงหรือต่ำจนเกินไป... พูดมักง่ายกว่าทำ",
  str_voice_1400791_15 = "ทุกคนเห็นคุณค่าของวันเกิด มาฉลองกัน ฉลองในราคาหนึ่งร้อยไนท์เทียมเลย",
  str_voice_1400791_16 = "ยินดีต้อนรับกลับมา นี่คือเวลาที่ดีที่สุดที่จะทำงาน... เธอจะสามารถทำได้อย่างน้อยสิบไนท์เทียม",
  str_voice_1400791_17 = "อรุณสวัสดิ์ ฉันแนะนำให้เธอออกกำลังกายในปริมาณเท่ากับสามไนท์เทียม โดยมูลค่าที่เธอได้รับจะเพิ่มเป็นสองเท่าเลยนะ",
  str_voice_1400791_18 = "เธอช่วยสละเวลาสรุปกิจกรรมของแต่ละวันที่มีมูลค่าหนึ่งไนท์เทียมได้ไหม",
  str_voice_1400791_19 = "ฉันจะไม่คะยั้นคะยอให้เธอพักผ่อนนะ ไม่ว่าเธอจะเลือกทำอะไร มันก็มีมูลค่าตราบใดที่มันเป็นความตั้งใจของเธอเอง",
  str_voice_1400791_20 = "เครื่องวัดนี่เราได้มาจากลูโมโพลิส มันขาดไม่ได้เลยแหละสำหรับภารกิจนี้ และมีความสำคัญต่อทั้งครอบครัวอย่างมากเลย",
  str_voice_1400791_21 = "ฉันก็อยากวัดมูลค่าของความจริงที่คนพวกนั้นพูดถึงนะ",
  str_voice_1400791_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1400791_23 = "น่าเสียดายที่อิคลิพไซท์ทั่วไปสิบตัวก็ยังรวมไม่ได้ถึง 1 ไนท์เทียมด้วยซ้ำ",
  str_voice_1400791_24 = "เลดี้ดยุกช่วยฉันไว้มาก แต่เธอดูจะไม่ชอบเมื่อฉันจ่ายไนท์เทียมให้เธอ",
  str_voice_1400791_25 = "ฉันไม่เข้าใจ เธอตัดสินเองตามความศรัทธาในทองคำของเธองั้นเหรอ",
  str_voice_1400791_26 = "ฉันชอบทำอะไรน่ะเหรอ ก็ตรวจสอบเครื่องวัด ไล่ดูสมุดบัญชี แล้วก็แปลงค่าต่าง ๆ ดู",
  str_voice_1400791_27 = "บุคคลที่มีความยุติธรรมไม่ควรประเมินอะไรตามความชอบของตัวเอง... แต่ฉันไม่เก่งเรื่องการจัดการอะไรที่คลุมเครือ",
  str_voice_1400791_28 = "มันคือวัตถุหายากที่ไม่สามารถวัดได้โดยใช้ตราชูแห่งความยุติธรรม",
  str_voice_1400791_29 = "ยินดีที่ได้รู้จัก ฉันมีหน้าที่วัดสิ่งต่าง ๆ แต่มูลค่าของเธอน่ะเป็นไปตามประสิทธิภาพของเธอ ไม่ใช่การวัดของฉัน",
  str_voice_1400791_30 = "ตอนนี้ฉันวัดอะไร ๆ ได้อย่างแม่นยำมากขึ้นแล้ว",
  str_voice_1400791_31 = "ศักยภาพของฉันได้เพิ่มขึ้นแล้ว",
  str_voice_1400791_32 = "มันคือการตัดสินที่้ชัดเจนมากกว่าเดิม",
  str_voice_1400791_33 = "ฉันจะนำความยุติธรรมกลับคืนมาจากเหล่าทวยเทพ!",
  str_voice_1400791_34 = "ฉันเข้าใจ เพิ่มน้ำหนักขึ้นนะ",
  str_voice_1400791_35 = "การเทียบมาตรฐานเสร็จสมบูรณ์",
  str_voice_1400791_36 = "ช่วยยืนยันน้ำหนักถ่วงที",
  str_voice_1400791_37 = "การตัดสินของฉันจะเป็นที่ประจักษ์แก่ทุกคน...",
  str_voice_1400791_38 = "เผชิญคำตัดสินจากสิ่งมีชีวิตทั้งหมด",
  str_voice_1400791_39 = "เท่าเทียม",
  str_voice_1400791_40 = "ก็แค่",
  str_voice_1400791_41 = "เพื่อการตัดสินที่ยุติธรรม",
  str_voice_1400791_42 = "ควรมีการตัดสินที่ยุติธรรม",
  str_voice_1400791_43 = "นี่คือผลลัพธ์ของความผิดพลาดที่เล็กน้อย...",
  str_voice_1400791_44 = "การแสดงออกถึงความตั้งใจจริงนั้นเป็นไปตามความเท่าเทียมกัน เธออยากได้อะไรเป็นการตอบแทนล่ะ",
  str_voice_1400791_45 = "ฉันจะยอมรับไว้เพราะคุณค่าของมัน",
  str_voice_1400791_46 = "ขอบคุณนะ สิ่งนี้จะเป็นสิ่งที่มีคุณค่า",
  str_voice_1400791_47 = "บางทีก็น่าจะเพิ่มคุณค่าทางจิตใจเข้าไปยังคุณค่าของตัวมันด้วยนะ",
  str_voice_1400791_48 = "ขอบคุณนะ ฉันจะใช้ทุกอย่างที่มีเพื่อตอบแทนเธออย่างเต็มที่",
  str_voice_1400791_49 = "การเพิกเฉยและการใช้ประโยชน์มีอยู่ด้วยเหตุผล คล้ายกับความสามารถและอาวุธ ซึ่งอย่างน้อยก็ช่วยให้ฉันอยู่รอดได้ดีขึ้น",
  str_voice_1400791_50 = "เป็นที่ยอมรับกันทั่วไปที่จะใช้เหตุผลเป็นเกณฑ์ในการตัดสิน แต่ความจริงก็คือว่าเราไม่กล้าใช้อารมณ์แทน เพราะเราไม่สามารถควบคุมมันได้อย่างเหมาะสม",
  str_voice_1400791_51 = "การไม่ได้รับผลกระทบจากอารมณ์ช่วยให้ฉันตัดสินใจได้อย่างยุติธรรมมากขึ้น ฉันเศร้าใจกับความอยุติธรรมของแม่ ตอนที่แม่บอกว่าฉันเป็นสัตว์ร้ายที่ไร้อารมณ์ความรู้สึก",
  str_voice_1400791_52 = "Alchemy Stars",
  str_voice_1400791_53 = "เริ่มสอบสวนได้",
  str_voice_1400791_54 = "อรุณสวัสดิ์ เธอควรรักษาไนท์เทียมที่เธอถือไว้ให้ดี",
  str_voice_1400791_55 = "สวัสดีตอนบ่าย เธอมีโอกาสที่จะเพิ่มมูลค่าตัวเองแล้ว",
  str_voice_1400791_56 = "สายัณห์สวัสดิ์ โปรดทำการตัดสินใจด้วย",
  str_voice_1400791_57 = "สุขสันต์วันปีใหม่",
  str_voice_1400811_1 = "การประกวดขวัญใจเหรอ ฮึ่ม! ใครจะมาเทียบฉันได้ในเรื่องของ... อะไรนะ!? ฉันได้คะแนนโหวตน้อยสุดเหรอ!?",
  str_voice_1400811_2 = "ช่ายยยแล้ว! ฉันจะเป็นคนที่เอาชนะซินซา และก้าวขึ้นเป็นหัวหน้าเรดีเซล เวรนช์! สถิติปัจจุบันของฉันเหรอ อืม... แพ้ 728 ครั้ง เสมอ 3 ครั้ง และไม่เคยชนะเลย",
  str_voice_1400811_3 = "ฉันพยายามสุดตัวที่จะทำความสะอาดรถเปิดประทุนทั้งหมด เพียงเพื่อที่จะได้รับตำแหน่ง \"ที่หนึ่งด้านความสะอาด\"... แล้วมันก็กลายเป็นเรื่องหลอกลวง! แต่ถึงอย่างนั้นฉันก็ยังแฮปปี้นะ...",
  str_voice_1400811_4 = "172... 173 ฮ่าฮ่า! ฉันจับอิคลิพไซท์ใส่ถุงได้ 173 ตัวแล้ววันนี้! แล้วเธอล่ะ",
  str_voice_1400811_5 = "การพัฒนาระดับการศึกษาก็เป็นส่วนสำคัญของการเพิ่มความแข็งแกร่งให้มากขึ้น โอดีสอนฉันเอาไว้ แต่เธอกลับประกาศให้ฉันจบการศึกษาภายในไม่ถึงหนึ่งสัปดาห์เลยอ่ะ... ยังงี้ฉันจะยังใช่อัจฉริยะอยู่ไหม",
  str_voice_1400811_6 = "ฉันคุ้นเคยกับความล้มเหลวดี และมันไม่กัดกินหัวใจฉันอีกต่อไปแล้ว การผลีผลามยอมรับความท้าทายด้วยความหลงใหล ไม่ว่าจะมีโอกาสแค่ไหน... นั่นแหละตัวฉัน! แบบนั้นแหละคือชีวิตของบร็อค!",
  str_voice_1400811_7 = "จากวันนี้เป็นต้นไป เราคือครอบครัว! ไม่ต้องกังวล ฉันจะคอยดูแลเธอเสมอ!",
  str_voice_1400811_8 = "ให้ฉันสอนว่าอะไรสร้างลูกผู้ชาย ฟังนะ สิ่งสำคัญที่สุดในชีวิตของลูกผู้ชายคือ เครื่องเทอร์โบ ทางวิ่ง และผงโปรตีน!",
  str_voice_1400811_9 = "ทำไมต้องกังวล เธอทำได้ดีมาก ปล่อยให้ปัญหาของพรุ่งนี้เป็นของพรุ่งนี้ แค่ใช้ชีวิตในปัจจุบันให้เต็มที่ก็พอแล้ว",
  str_voice_1400811_10 = "เบื่อจัง เบื่อสุด ๆ ตัวแข็งเป็นกระดานแล้ว มาเริ่มวอร์มอัพกันก่อน... ฮัดเช่ย!",
  str_voice_1400811_11 = "ตาดีมาก! ฉันคือคนที่พึ่งพาได้ที่สุดในเรดีเซล เวรนช์",
  str_voice_1400811_12 = "ช่าย ฉันน่ะกลัวความสูง... แต่ไม่ใช่อะไรที่... ใช่แล้ว นอกจากนี้ฉันยังกลัวแมลงหน่อย ๆ ด้วย!",
  str_voice_1400811_13 = "ฉันได้สเปรย์พ่นสีมาอีกขวดแล้ว อันนี้เรืองแสง ตอนนี้เราสามารถทำให้รถเปิดประทุนแปลงโฉมใหม่ได้แล้ว",
  str_voice_1400811_14 = "ลูกผู้ชายตัวจริงนอนในทะเลทราย แต่ในถุงนอน ไม่ใช่ในทราย",
  str_voice_1400811_15 = "ว้าว! วันนี้วันเกิดเธอนี่! ที่จริงแล้วของฉันก็... เดี๋ยวซิ วันเกิดฉันเมื่อไหร่นะ",
  str_voice_1400811_16 = "ล้า-ลาลา... ลาลา-ล้า... เรดีเซลยามเช้า... ทหารคุ้มกันลูโมออกลาดตระเวนแล้วเหรอ หนีเร็ว!",
  str_voice_1400811_17 = "มาวิ่งตอนเช้ากันไหม ผู้นำทาง ฉันคือนักวิ่งฝีเท้าเร็วที่สุดในเรดีเซล เวรนช์เลยนะ ฉันวิ่งได้เร็วกว่ารถของเธอซะอีก!",
  str_voice_1400811_18 = "ฉันหิวจังเลย... ไม่เอาหนอนทรายเป็นอาหารเย็นแล้วนะขอร้อง... แหวะ",
  str_voice_1400811_19 = "*กรนคร่อก* ศัตรูโจมตีเหรอ! ไม่ แต่ว่า! ฉันไม่ได้ทำหน้าที่เฝ้ายามวันนี้!",
  str_voice_1400811_20 = "เรดีเซล เวรนช์กำลังเฟื่องฟูภายใต้การนำของรองหัวหน้าหน่วย ซึ่งก็คือ \"ฉัน\" เอง เฮ้ แต่อย่าบอกซินซานะว่าฉันพูดแบบนั้น",
  str_voice_1400811_21 = "คาราวานที่ทำงานให้ลูโมโพลิสคือแกะที่จะต้องถูกเชือด... ถ้าฉันไปเจอพวกนั้นได้ทุกวันก็ดีน่ะสิ!",
  str_voice_1400811_22 = "เรดีเซล เวรนช์! ปราบอิคลิพไซท์และลูโมโพลิส!",
  str_voice_1400811_23 = "ฆ่าอิคลิพไซท์เหรอ เหมือนขโมยลูกอมจากเด็กทารกเลย!",
  str_voice_1400811_24 = "เธอว่าโจนาเหรอ อ๊ะ ไม่นะ ฉันเพิ่งจดจำฝันร้ายได้เรื่องหนึ่ง... อ๊ากกกกก!!!",
  str_voice_1400811_25 = "ความสัมพันธ์ของฉันกับเรจินามาถึงจุดตกต่ำ ตอนที่ฉันบอกเธอว่าเสียงเครื่องยนต์เทอร์โบเป็นดนตรีที่ไพเราะที่สุด",
  str_voice_1400811_26 = "แข็งแกร่งขึ้น ผู้ชายควรแข็งแกร่งขึ้น ต้องมีกล้ามมีอะไร! ไม่ใช่เป็นไม้เสียบผี!",
  str_voice_1400811_27 = "ฉันเกลียดทหารลูโม... ผมเงิน สูง และหล่อ... หล่อกว่าฉัน เชอะ!",
  str_voice_1400811_28 = "เจ้านี่น่ะ ใหญ่เบ้งเลยนะ! ยังกับทำมาเพื่อฉันโดยเฉพาะเลย! หืม? ของเธอเหรอ เธอเอาให้ฉันไม่ได้เหรอ",
  str_voice_1400811_29 = "เร็วเหมือนเปลวไฟ รุนแรงเหมือนพายุ คนทรยศที่เกิดจากกังหัน! ฉันคือบร็อคหนึ่งเดียวคนนี้ พร้อมรับใช้ โอดีจดให้ฉันหน่อย",
  str_voice_1400811_30 = "รู้สึกดีมากเลย!",
  str_voice_1400811_31 = "ได้เวลาจริงจังแล้ว!",
  str_voice_1400811_32 = "ว้าวววววว! พลังแผ่ซ่านไปทั่วร่างฉันเลย!",
  str_voice_1400811_33 = "พุ่งสุดตัว!",
  str_voice_1400811_34 = "เร็วเข้า เร็ว!",
  str_voice_1400811_35 = "ได้เวลาแล้ว!",
  str_voice_1400811_36 = "เธอลองบินโดยอาศัยกำปั้นของฉันสิ!",
  str_voice_1400811_37 = "ปลดปล่อย!",
  str_voice_1400811_38 = "ไปซะ!",
  str_voice_1400811_39 = "ความเร็วสูงสุด!",
  str_voice_1400811_40 = "รวมเกียร์!",
  str_voice_1400811_41 = "ฉันเป็นกัปตันเหรอ ก็ใช่น่ะสิ!",
  str_voice_1400811_42 = "ฉันทรงพลังมากเลยด้วยนะวันนี้!",
  str_voice_1400811_43 = "ฮึ่ม! ฉันไม่อยากเชื่อเลย... มาอีกรอบเถอะ!",
  str_voice_1400811_44 = "ย-อย่าจับอันนั้น! เฮ้อ ปัทโธ่! พังเลย... ท่าไม่ดีแล้วแฮะ",
  str_voice_1400811_45 = "หืมมม ของขวัญให้ฉันเหรอ",
  str_voice_1400811_46 = "เยี่ยมเลย!",
  str_voice_1400811_47 = "นี่... นี่... ธ-เธอ-เธอ-เธอ... ฉัน-ฉัน-ฉัน...",
  str_voice_1400811_48 = "ฉ-ฉันซาบซึ้งใจจริง ๆ... โฮ โฮ...",
  str_voice_1400811_49 = "อดีตของฉันเหรอ ตอนนี้ฉันจำอะไรเกี่ยวกับอดีตของฉันไม่ค่อยได้แล้ว ไม่มีเรดีเซล เวรนช์คนไหนที่มีอดีต มีแต่ปัจจุบัน",
  str_voice_1400811_50 = "อาจจะมี... การเข้าใจผิดสักอย่าง หรือมีคำอธิบายเรื่องทั้งหมดนี่นะ ยังไงก็ตาม ข้ออ้างพวกนั้นไม่สามารถเยียวยารอยแผลในใจของฉันได้หรอก ความรุนแรงคือคำตอบของทุกสิ่งสำหรับฉัน",
  str_voice_1400811_51 = "ฉันคิดว่า ตอนที่ฉันและลูกน้องของฉันเดินทางไปทั่วดินแดนรกร้างด้วยรถเปิดประทุนพาวเวอร์บอลของเรา ฉันแน่ใจเพียงสิ่งเดียวเท่านั้น ฉันไม่เคยเสียใจที่ได้เข้าร่วม เรดีเซล เวรนช์ เลย",
  str_voice_1400811_52 = "Alchemy Stars",
  str_voice_1400811_53 = "ผู้นำทาง",
  str_voice_1400811_54 = "อรุณสวัสดิ์ อยากฝึกฝนไหมล่ะ",
  str_voice_1400811_55 = "อีกเดี๋ยวฉันจะไปท้าทายซินซา!",
  str_voice_1400811_56 = "เจ๋งไปเลย! มากับฉันไหม",
  str_voice_1400811_57 = "ปีหน้าฉันจะต้องชนะ! เอ๊ะ ปีใหม่แล้วเหรอเนี่ย",
  str_voice_1400911_1 = "เราต่างติดอยู่ในวังวนแห่งโชคชะตา ค่อย ๆ ขับเคลื่อนหนทางของเราไปข้างหน้า วังวนนั้นพาเราเวียนว่ายไปโดยไม่สนว่าเราพร้อมหรือไม่",
  str_voice_1400911_2 = "ขอโทษจริง ๆ นะ ฉันไม่ควรพูดอะไรแบบนั้นเลย... แต่ตอนที่ฉันไม่ได้เล่นเครื่องดนตรีของฉัน ฉันก็ไม่มีที่ไหนให้ซ่อนตัวแล้วฉันก็จะเริ่มจำอะไรได้...",
  str_voice_1400911_3 = "บางครั้งฉันก็ต้องเลิกเล่นตอนแสดงอยู่เพราะตัวสั่นขึ้นมากะทันหัน... แต่เธอก็ไม่เคยดุฉันเลย ฉันซาบซึ้งใจมากเลยนะ",
  str_voice_1400911_4 = "ขนาดตอนที่ฉันพยายามไม่นึกถึงมัน ความกลัวก็ยังซุกซ่อนหลอกหลอนฉันในรูปแบบของความฝันอยู่ มันไม่ยอมให้ฉันได้พักเลย...",
  str_voice_1400911_5 = "อดีตก็เป็นเหมือนเส้นด้ายที่พันเกี่ยวข้อมือและคอของฉันไว้ ตอนที่ฉันรู้ตัวขึ้นมาในท้ายที่สุดว่าควรปลดด้ายออกก็ทำไม่ได้เสียแล้ว เพราะไม่รู้ว่าจะแก้ด้ายยังไง",
  str_voice_1400911_6 = "ฉันชอบฝันถึงวันที่ฉันตกลงไปในความมืดซึ่งไร้ทางออก จวบจนวันนี้ฉันก็ยังเป็นดั่งใบไม้ร่วงหล่นที่ไม่รู้ทิศทางและไม่รู้ว่าจะอยู่หรือจะไปดี...",
  str_voice_1400911_7 = "ถ้าเธอตัดสินใจได้แล้วก็ควรไปเสีย อย่าหันหลังกลับมา จงทิ้งฉันเอาไว้ในอดีตให้คอยเฝ้ามองต่อไป... แต่ถ้าเธอกลับมาฉันก็จะต้อนรับเธอ...",
  str_voice_1400911_8 = "วันหนึ่งฉันจะต้องดับสูญไป เธอจะคิดถึงฉัน ฉันหวังว่าเธอจะคร่ำครวญกับการสูญสิ้นของฉัน ถึงเธอจะลืมเลือนมันไปแต่ก็ยังดีกว่าไม่มีใครคิดถึงฉันเลย...",
  str_voice_1400911_9 = "ฉันหวังจากใจว่าฉันจะเข้าใกล้ความฝันเข้าไปได้ทุกที... มันคงเหมือนดั่งสายลมอ่อนโยน ละอองหมอก เส้นทางตรงดิ่งหรือทางส่องสว่าง เหมือนเธอไง...",
  str_voice_1400911_10 = "ฉันจะเล่นให้ดีขึ้น ฉะนั้นอยู่ก่อนและอย่าไปไหน อย่าเพิ่งรีบไป...",
  str_voice_1400911_11 = "เธอจะทิ้งฉันไหม เธอเป็นเหมือนนกท่ามกลางหมู่เมฆหรือห่านที่กำลังอพยพกันล่ะ... ฉันสัญญาว่าจะไม่สร้างปัญหาให้เธอ... ดังนั้นได้โปรดอยู่ต่อเถอะนะ",
  str_voice_1400911_12 = "เมื่อวันพรุ่งนี้มาถึง เมฆหมอกดำทมิฬจะกระจ่างใส... ขอความทุกข์ทรมานของเธอจงบรรเทาลง",
  str_voice_1400911_13 = "อย่าร้องไห้เลยนะ... เช็ดน้ำตาออกเถอะ... แล้วปล่อยให้ฉันเลือนลางไป",
  str_voice_1400911_14 = "ฉันรู้ว่าฉันต้องเล่นต่อไป ตราบใดที่ฉันไม่หยุด... น้ำตาของฉันก็อาจจะไม่ไหล",
  str_voice_1400911_15 = "วันเกิดมักจะเป็นอย่างที่คาดคิดไว้เสมอ ขอแสงสว่างที่เธอเห็นในวันแรกที่เกิดมาจงอยู่เคียงข้างเธอทุกช่วงเวลา",
  str_voice_1400911_16 = "ยินดีต้อนรับกลับมา หวังว่าเงาและเสียงของเธอจะอยู่ได้นานกว่านี้หน่อยนะ",
  str_voice_1400911_17 = "ฉันหวังว่าตอนเช้า ๆ จะไม่หนาวเย็นตลอดเวลา แต่จงอบอุ่นให้เหมือนตอนที่ฉันรู้สึกเวลาที่เธอมาถึง...",
  str_voice_1400911_18 = "ฉันได้ยินเสียงเธอมาเป็นเสียงตะกุกตะกัก ภายใต้แสงกระพริบ",
  str_voice_1400911_19 = "ขออภัยจริง ๆ แต่เวลานี้ของทุกวัน... ฉันรู้สึกว่ามันห้ามใจยากตลอดเลย...",
  str_voice_1400911_20 = "ความมืดล้อมลูโมโพลิสจนมุม สร้างบาดแผลนับไม่ถ้วน",
  str_voice_1400911_21 = "ฉันหวังว่าอิลลูมินาจะนำความสงบสุขมาให้ ฉันยังหวังด้วยว่าจะไม่มีสงครามอีก",
  str_voice_1400911_22 = "ขอเทิดทูนรัตติกาลสีขาว...",
  str_voice_1400911_23 = "มันคือ... ความคิดมืดมนที่กวนใจฉัน... เป็นบาดแผลทางจิตใจในอดีตที่ไม่มีวันเลือนหายไป",
  str_voice_1400911_24 = "ฉันได้ยินเสียงเจ็บปวดสั่นไหวจากอดีตที่ไม่เคยพบเห็น ดังมาจากตัวนางที่เป็นสีทอง...",
  str_voice_1400911_25 = "คาร์ลีนแข็งแกร่งมากและนางก็รับมือได้ด้วย หวังว่านาง... จะไม่ทำร้ายตัวเองอีกนะ",
  str_voice_1400911_26 = "ฉันชอบ... การเคียงบ่าเคียงไหล่ การพึ่งพาอาศัย การปกป้อง สันติและความสงบสุขในแบบที่ฉันจดจำมันได้",
  str_voice_1400911_27 = "ฉันไม่อยากเผชิญหน้ากับพวกนั้นเลย... ทั้งฝันร้าย ความเย็นยะเยือก และเขาวงกต... ที่ไม่มีทางออก",
  str_voice_1400911_28 = "ปีกมันใหญ่มากเลย บางทีมันอาจนำความเศร้าโศกไปได้ไกลแสนไกล...",
  str_voice_1400911_29 = "ความเสียใจเป็นโน้ตดนตรีที่มีเสียงเศร้าสลดมาตั้งแต่แรกเริ่มอยู่แล้ว และพวกมันก็ถูกเล่นต่อเนื่องเรื่อยมา... ดีใจที่ได้พบเธอนะ ฉันโคลอี้ เป็นนักดนตรี",
  str_voice_1400911_30 = "เสียงดนตรี... ล่องลอยไปไกล...",
  str_voice_1400911_31 = "ฉันเข้าใจสิ่งที่บทเพลงสื่อออกมานะ...",
  str_voice_1400911_32 = "ถ้าอย่างนั้นฉัน... จะปลดพันธนาการจากมันได้ไหม",
  str_voice_1400911_33 = "บางทีฉันอาจเห็นอย่างอื่นที่แตกต่างไปจากก่อนหน้านี้ได้ด้วย...",
  str_voice_1400911_34 = "ฉันจะเล่น... แฟนตาเซีย",
  str_voice_1400911_35 = "เพลงต่อไปเล่นอะไรดีนะ...",
  str_voice_1400911_36 = "ใส่ความรู้สึกเข้าไปในการแสดง...",
  str_voice_1400911_37 = "นี่เป็น... เสียงเพลงเศร้า",
  str_voice_1400911_38 = "บทเพลงบอกเล่าถึงอดีตที่หลอกหลอน",
  str_voice_1400911_39 = "ฉันอยากขับไล่...",
  str_voice_1400911_40 = "ขับไล่ความเศร้าโศก...",
  str_voice_1400911_41 = "หากมีอะไรที่ฉันทำได้...",
  str_voice_1400911_42 = "ฉันหวังว่ามันจะไม่หายไปในทันที",
  str_voice_1400911_43 = "ถ้าไม่ใช่ฝีมือฉัน... แล้วใครมัดทุกคนล่ะเนี่ย",
  str_voice_1400911_44 = "เอาอย่างนี้... ฉันจะเล่นสักเพลงและตั้งสติตัวเองไปด้วย...",
  str_voice_1400911_45 = "อย่าใช้วาจาสิ... ฉันไม่เข้าใจ...",
  str_voice_1400911_46 = "ฉันชื่นชมของขวัญที่ไม่ได้มาง่าย ๆ เป็นพิเศษ",
  str_voice_1400911_47 = "เธอมีอะไรให้ฉันตลอดเลย...",
  str_voice_1400911_48 = "ล้ำค่าสุด ๆ! ฉันจะทะนุถนอมมันให้พอได้ยังไง",
  str_voice_1400911_49 = "ฉันมักจะพยายามหนีเข้าไปในโลกของดนตรีอยู่เรื่อย... แต่ฉันรู้ว่าทางแก้เดียวคือพูดถึงบาปของตัวเอง อย่างตรงไปตรงมาและไม่มีการปิดบัง...",
  str_voice_1400911_50 = "แม่ไม่แข็งแรงพอที่จะตั้งครรภ์ ถ้าไม่ใช่เพื่อฉัน... นางก็คงสุขสงบกับชีวิตไปแล้ว...",
  str_voice_1400911_51 = "ฉันไม่ได้อยู่เคียงข้างเขาตอนที่เขาต้องเผชิญหน้ากับความกลัวที่ยิ่งใหญ่ที่สุด จวบจนท้ายที่สุดเขาก็ไม่เคยหยุดร้องเรียกฉันเลย...",
  str_voice_1400911_52 = "Alchemy Stars...",
  str_voice_1400911_53 = "เฮ้...",
  str_voice_1400911_54 = "อรุณสวัสดิ์ เธอตื่นแล้วเหรอ",
  str_voice_1400911_55 = "สวัสดียามบ่าย ฉันมีบางอย่างที่หวังว่าเธอจะช่วยได้อยู่...",
  str_voice_1400911_56 = "สายัณห์สวัสดิ์ กรุณาระวังอย่าให้เป็นหวัดล่ะ",
  str_voice_1400911_57 = "ขอให้ปีใหม่ไร้ซึ่งความเศร้าโศกใด ๆ!",
  str_voice_1500091_1 = "อ้า... พลังของดวงอาทิตย์อยู่นี่เอง นั่นมันประตูลับที่ทรู ออเดอร์ล็อกไว้นี่ ฉันเปิดดีไหม อาจมีอะไรน่าสนใจเกิดขึ้นก็ได้",
  str_voice_1500091_2 = "สะสมความโกรธและความกลัวไว้มากเกินไป รอคอยอย่างเงียบงันอยู่ในความมืด... เธออยากรู้เรื่องเพิ่มไหมล่ะ",
  str_voice_1500091_3 = "เสียงแห่งความจริงคือจุมพิต แม่น้ำไหลริน... บทพูดที่เลดี้วิกตอเรียให้ฉันมันน่าสับสนเกินไปแล้วก็จำยากด้วย",
  str_voice_1500091_4 = "เสียงกระซิบหายวับไป... เราเป็นหนึ่งเดียวกันแล้ว มาแบ่งปันความสุขนี้กันเถอะ แล้วฉันจะนำความสุขอันยิ่งใหญ่มาให้เธอ",
  str_voice_1500091_5 = "ศรัทธาที่ยิ่งใหญ่คุ้มค่าพอให้สละทุกอย่าง ไม่ว่าจะเป็นความสงบ สภาพจิตใจ หรือกระทั่งชีวิตและจิตวิญญาณของเรา...",
  str_voice_1500091_6 = "ความจริงนั้นไม่ได้ส่งต่อคำสอนมาสู่ฉัน เพราะฉันได้กลายเป็นหนึ่งในพวกเขาแล้ว... ส่งมือมาให้ฉันแล้วสถานที่ต่อไปของเราจะเป็นสวรรค์",
  str_voice_1500091_7 = "ฉันนับถือศรัทธาและความจริงใจของเธอนะ แต่พวกมันคงสั่นคลอนต่อหน้าความสุขที่แท้จริงแน่นอน ถ้าไม่อยากเชื่อก็เข้ามาใกล้ ๆ",
  str_voice_1500091_8 = "บางครั้งความแตกต่างระหว่างลัทธิที่น่าเคารพของเราก็ห่างกันเพียงแค่เส้นผมเท่านั้น ฮ่า ๆ ฉันขอพูดแค่นี้แหละ เอาไปครุ่นคิดเอาเองนะ",
  str_voice_1500091_9 = "อย่าเข้าใจผิดไป ฉันไม่เคยสู้เพื่อเธอ สำหรับฉันแล้วเธอก็เป็นเพียงความพึงพอใจรูปแบบหนึ่งเท่านั้น... เลดี้วิกตอเรียก็คิดอย่างนั้นด้วย",
  str_voice_1500091_10 = "หวังว่าเธอจะได้ยินเสียงกระซิบจากแสงแดดนะ... ฮ่า ๆ จับเสียงเสแสร้งของฉันได้หรือเปล่า ฉันต้องฝึกเพิ่มสักหน่อยแล้ว",
  str_voice_1500091_11 = "เต็มใจฟังเสียงกระซิบพวกนั้นกับฉันสักทีไหมล่ะ โอ้ น่าสนใจอะไรแบบนี้!",
  str_voice_1500091_12 = "สวัสดี นายสนใจอยากรู้เกี่ยวกับทรู ออเดอร์ไหม",
  str_voice_1500091_13 = "พูดถึงแฟนคลับของฉันแล้ว สมาชิกทุกคนต่างก็ใส่ใจและเป็นหญิงสาวที่น่ารัก แล้วฉันก็ซาบซึ้งในตัวพวกเขามาก",
  str_voice_1500091_14 = "ฉันมีปัญหากับการนอน เพราะนำทางผู้คนให้มานับถือความจริงเพิ่มไม่ได้",
  str_voice_1500091_15 = "ยินดีด้วยที่เธอเพิ่งเกิดใหม่!",
  str_voice_1500091_16 = "เธอตัดสินใจจะเข้าร่วมกับเราแล้วเหรอ?",
  str_voice_1500091_17 = "อธิษฐานตั้งแต่รุ่งสางจนถึงค่ำคืน",
  str_voice_1500091_18 = "ถ้าเธอวิ่งหนีความจริงบนโลกใบนี้ ก็จะถูกล้อมด้วยความมืดมิดและวุ่นวาย ถึงแม้เธอจะเบิกตากว้างอยู่ก็ตาม",
  str_voice_1500091_19 = "ดูสิ ดวงดาวโนวาส่องแสงสว่างบนท้องฟ้าเพื่อเธอเลยนะ... ร่วมมือกับฉันปัดเป่าฝันร้ายที่ดูหมิ่นลัทธินี้กันเถอะ",
  str_voice_1500091_20 = "ทรู ออเดอร์เป็นเหมือนพาหนะที่จะล่องลอยไปยังสวรรค์ด้วยปีกที่บอกลาความไร้ตัวตนไปเสีย",
  str_voice_1500091_21 = "สิ่งมีชีวิตน่าสงสารพวกนั้นไม่สำคัญเท่ากลุ่มที่บินได้หรอก แต่ฉันเคารพพวกมันด้วยความเศร้าอยู่บ้าง",
  str_voice_1500091_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1500091_23 = "ผงธุลีของยุคสมัยก่อนจะถูกชะล้างออกไปในสักวันหนึ่ง",
  str_voice_1500091_24 = "เลดี้วิกตอเรียคือผู้หญิงที่สมบูรณ์แบบที่สุด สรุปนายต้องการเข้าร่วมกับทรู ออเดอร์แน่เหรอ",
  str_voice_1500091_25 = "เกรงว่าเนลส์จะไม่ได้ยินสิ่งที่ฉันพูด แต่ก็ไม่ได้ทำให้เราทำงานด้วยกันแล้วไม่มีความสุขหรอกนะ",
  str_voice_1500091_26 = "ช่วงที่ฉันเดินทางก็ได้เห็นอะไรมามากมาย ตอนนั้นเองที่ความเชื่อของฉันเริ่มเข้มแข็งขึ้น",
  str_voice_1500091_27 = "เพื่อความเป็นจริงแล้ว ฉันจะไม่ชอบทุกอย่างได้ยังไง ถ้าฉันจำเป็นต้องเลือกอะไรก็คงต้องพูดทุกอย่างยกเว้นความจริง",
  str_voice_1500091_28 = "เป็นคำโกหกใหญ่หลวงที่น่าชื่นชม แต่ก็เทียบอะไรไม่ได้เลยกับความจริง",
  str_voice_1500091_29 = "บทเพลงสุขสันต์ละเลงเล่นไปขณะที่ความจริงของอาณาจักรถูกถ่ายทอด ผู้คนที่เชื่อถือควรได้รับของขวัญไถ่บาป ในขณะที่ผู้เสื่อมศรัทธาก็ควรถูกลดทอนเป็นฝุ่นผง ร่วมลัทธิกับเราและมีความสุขไปชั่วนิรันดร์สิ...",
  str_voice_1500091_30 = "ฉันจะถ่ายทอดความจริงใจของเธอ",
  str_voice_1500091_31 = "เสียงในหัวฉันดังขึ้นล่ะ!",
  str_voice_1500091_32 = "เพื่อนร่วมชาติของฉัน กำลังไล่ตามหาความจริง",
  str_voice_1500091_33 = "แรงปรารถนาทั้งปวงคือบาปติดตัว",
  str_voice_1500091_34 = "ไม่มีใครหนีรอดไปได้",
  str_voice_1500091_35 = "ปลดปล่อยพลังโบราณนี้!",
  str_voice_1500091_36 = "ความจริงบอกฉันว่ามันพร้อมแล้ว",
  str_voice_1500091_37 = "นี่เป็นฝันร้ายที่แท้จริง",
  str_voice_1500091_38 = "ฉันจะฉีกผ้าแห่งความเป็นจริงออกมา",
  str_voice_1500091_39 = "ศรัทธาคือนิรันดร์",
  str_voice_1500091_40 = "ความจริงคือทั้งหมด",
  str_voice_1500091_41 = "ฉันจะสาธิตบางสิ่งที่น่าสนใจให้เธอดู...",
  str_voice_1500091_42 = "เพื่อนร่วมลัทธิที่ค้นหาความจริงของฉัน นี่เป็นเพียงแค่จุดเริ่มต้นเท่านั้น...",
  str_voice_1500091_43 = "... ความหงุดหงิดนี้เป็นส่วนหนึ่งของการเตรียมการของเธอเหรอ",
  str_voice_1500091_44 = "เธออยากรู้ไหมว่าอะไรอยู่ในกล่อง เป็นความลับน่ะ",
  str_voice_1500091_45 = "ขอบใจนะ แต่... ถึงฉันจะนำเสนอได้เก่งกว่าเธอก็เถอะ",
  str_voice_1500091_46 = "น่าสนใจ! ก่อนหน้านี้ฉันดูถูกเธอเกินไป",
  str_voice_1500091_47 = "ฮ่า ๆ รู้ทันฉันแล้วงั้นสิ",
  str_voice_1500091_48 = "ขอบใจนะ รับจุมพิตแห่งความยินดีบนมือของเธอเถอะ",
  str_voice_1500091_49 = "มีใครบอกไหมว่าอดีตจะถูกเพลิงบาปทำลาย คนสวมเกราะจะถูกลดทอนลงมาเป็นกระดูกและดาบเงินจะแตกสลาย...",
  str_voice_1500091_50 = "จงปล่อยความเมินเฉยและหยิ่งยโสไป และเอาชนะบททดสอบลาวาและทะเลทรายเพื่อรับคำอวยพรนะ",
  str_voice_1500091_51 = "ฉันเคยไปยังดินแดนนิรันดร์และเห็นชะตาของผู้ที่หักหลังความจริงและผู้คัดค้านกับตาเลย... ถึงฉันจะไม่คิดว่าตัวเองจะลงเอยบนเส้นทางที่เหมือนพวกเขาก็เถอะ ฉันก็ต้องขอศิโรราบให้กับความโอบอ้อมอารีของเลดี้วิกตอเรียชั่วคราว",
  str_voice_1500091_52 = "Alchemy Stars",
  str_voice_1500091_53 = "เพื่อนรักเอ๋ย...",
  str_voice_1500091_54 = "อรุณสวัสดิ์ เพื่อนเอ๋ย",
  str_voice_1500091_55 = "สวัสดียามบ่าย เพื่อนเอ๋ย",
  str_voice_1500091_56 = "ราตรีสวัสดิ์ เพื่อนเอ๋ย",
  str_voice_1500091_57 = "สุขสันต์วันปีใหม่ เพื่อนเอ๋ย!",
  str_voice_1500421_1 = "เขี้ยวเหล็กนี่มีไว้ทำไมเหรอ คนสุดท้ายที่ถามเรื่องนี้ถูกบดหัวเหมือนลูกวอลนัทไปแล้ว มันก็มีไว้บดขยี้อย่างนั้นล่ะ!",
  str_voice_1500421_2 = "ทำไมไม่ตั้งชื่อผู้หญิง ๆ ให้โคลอสซัสล่ะ อย่างนั้นจะได้ไม่ต้องปล่อยให้นางอยู่คนเดียวในสมรภูมิรบ",
  str_voice_1500421_3 = "คิดว่าฉันตลกเหรอ!? มีเพียงพระเจ้าที่รู้ว่าใครรอเราอยู่ในอนาคตเท่านั้น สงครามอยู่รอบตัวเราไม่ได้หายไปไหน",
  str_voice_1500421_4 = "ไม่ต้องฆ่าใครด้วยมีดถ้าปืนทำได้ ฉันจะขอให้กรอนรูหากระสุนเจาะเกราะคราวหลัง และจะได้เป่าพวกมันลงนรก",
  str_voice_1500421_5 = "ยิ่งฝึกเยอะก็ยิ่งตายในสมรภูมิน้อยลง",
  str_voice_1500421_6 = "คนเขาว่ากระสุนไว้ยิงใครก็ได้ น่าเสียดายที่พวกนั้นชอบว่าฉันตลอดเลย ฮ่า!",
  str_voice_1500421_7 = "วันนี้อากาศดีนะ ทำไมไม่มาฝึกข้ามประเทศไปกับฉันล่ะ",
  str_voice_1500421_8 = "ไม่มีใครดูแลเธอได้อย่างยุติธรรมและเท่าเทียมกันในการต่อสู้หรอก ใช้กลยุทธ์สกปรกอะไรก็ได้เพื่อเอาชนะสิ! ฉันแสดงให้ดูก่อนเอาไหม",
  str_voice_1500421_9 = "ไหนดูหน้าตาเธอตอนต่อสู้หน่อย... อะไรเนี่ย ทำได้ดีที่สุดแค่นี้เหรอ ฮ่า! มือใหม่ชัด ๆ!",
  str_voice_1500421_10 = "สุดสัปดาห์นี้เป็นสัปดาห์ที่ดี! เธอจะมาเล่นหมากรุกกับฉันเหรอ ไม่เอาเหรอ งั้นก็ปล่อยให้ฉันเล่นคนเดียวเถอะ",
  str_voice_1500421_11 = "อ่ะฮ้า! เธอต้องการให้ฉันคอยระวังให้เธอ นี่เธอคงเบื่อจะแย่แล้วใช่ไหม",
  str_voice_1500421_12 = "ได้ยินว่าค่ายฝึกทหารใหม่ของอิลลูมินากำลังถดถอยจากที่แย่ ๆ กลายเป็นเลวร้ายสุด ๆ ผู้ฝึกสอนไม่ได้ทำอะไรเลยเหรอ ถ้าเป็นแบบนี้ พวกเขาจะกลายเป็นเป้าหมายในการต่อสู้แน่!",
  str_voice_1500421_13 = "ถ้าเบื่อขนาดนั้นก็ฝึกซ้อมบ้างจะได้ไม่พลาดเวลาคับขัน",
  str_voice_1500421_14 = "เมื่อไม่มีสงคราม ทหารก็ไม่มีประโยชน์ ฉันไม่อยากเป็นปรสิตที่ไม่ได้ทำอะไรเลย",
  str_voice_1500421_15 = "อยากฉลองวันเกิดเหรอ ฝึกพิเศษให้เธอโดยเฉพาะเป็นไง ฉันสัญญาว่าเธอจะรู้สึกเหมือนได้เกิดใหม่เลยละ...",
  str_voice_1500421_16 = "แถวนี้เงียบเกินไปแล้ว ฉันอยากยิงอะไรสักอย่าง!!",
  str_voice_1500421_17 = "ลุกขึ้น จอมขี้เกียจ! ที่นี่ไม่ใช่บ้านแสนสบายอันอบอุ่นของคุณย่านะ!",
  str_voice_1500421_18 = "ผ่านมาวันหนึ่งแล้วยังไม่เจอศัตรูเลย ฉันเบื่อแล้วสิ! ไปหาอิคลิพไซท์มาให้ฉันสู้สักตัวสองตัวซิ!",
  str_voice_1500421_19 = "เวลาล่วงเลยมานานแล้วนับตั้งแต่ที่ฉันได้ฝึกข้ามคืน... ไหน ๆ เธอก็มาแล้ว เรามาฝึกข้ามคืนด้วยกันไหม",
  str_voice_1500421_20 = "พักหลังมานี้อิลลูมินาเน้นไปเรื่องการค้าขาย ส่งนักบัญชีไปออกรบแบบนี้ ก็มีแต่แพ้กับแพ้เท่านั้นเอง",
  str_voice_1500421_21 = "มีอัศวินหัวโบราณจากลูโมโพลิสมาเยอะเลย! พวกนั้นคิดอะไรถึงได้มาขอดวลต่อสู้เนี่ย",
  str_voice_1500421_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1500421_23 = "ผู้บัญชาการช่างน่ารำคาญ เจ้าหน้าที่ก็ไร้ความสามารถ แถมทหารยังทำตามคำสั่งแบบไม่รู้อิโหน่อิเหน่อีก จะคาดหวังอะไรอย่างอื่นได้จากกลุ่มคนที่ผสมกันมั่วแบบนั้นอีกล่ะ",
  str_voice_1500421_24 = "ทำไมฮิอิโระถึงพูดเกี่ยวกับบูชิโด งี่เง่าอ่ะ! เธอควรลอบโจมตีในสงคราม",
  str_voice_1500421_25 = "ถ้ามีโอกาส ฉันจะต้องบอกไรน์ฮาร์ตว่าพักผ่อนมามากพอแล้ว ได้เวลาเตรียมตัวทำสงครามสักที!",
  str_voice_1500421_26 = "สงบสุขเหรอ หึ! ทุกคนซื่อบื้อกันหมดเลย ยังไงก็มีแค่สงครามเท่านั้นที่จะทำให้พวกเขารู้สึกมีค่านะ!",
  str_voice_1500421_27 = "ชะตาสุดท้ายของทหารก็คือสลักชื่อบนกระสุน ไม่อย่างนั้นก็มีแต่ความน่าเบื่อเท่านั้นแหละ",
  str_voice_1500421_28 = "ฉันก็อยากได้โคลอสซัสเหมือนกัน คงดีที่ได้ยิงมิสไซล์ใส่โดม",
  str_voice_1500421_29 = "ได้ยินว่ามีการสู้รบเยอะมากงั้นเรอะ! ฉันคือบาร์ตัน ผู้บัญชาการกองทัพสหพันธรัฐอิลลูมินา ไปจัดการพวกขยะกันเลย!",
  str_voice_1500421_30 = "ไหนขอเอาคืนพวกมันหน่อย!",
  str_voice_1500421_31 = "ดาบฉันคมปลาบขึ้นมาเลย",
  str_voice_1500421_32 = "ทหารเก่าไม่มีวันตายจาก",
  str_voice_1500421_33 = "ฉันคนเดียวก็เท่ากองทัพแล้ว!",
  str_voice_1500421_34 = "รับทราบ!",
  str_voice_1500421_35 = "ล็อกและบรรจุกระสุน",
  str_voice_1500421_36 = "ได้เวลาปาร์ตี้แล้ว!",
  str_voice_1500421_37 = "ฉันจะจบชีวิตแกด้วยดาบกองทัพบาร์ตัน!",
  str_voice_1500421_38 = "มาอาบห่ากระสุนของฉันเสียสิ!",
  str_voice_1500421_39 = "เชอร์แมน - แก้ไขแล้ว!",
  str_voice_1500421_40 = "คว่ำพวกเธอให้หมด!",
  str_voice_1500421_41 = "ตามฉันมาแล้วฆ่าพวกมันให้หมด!",
  str_voice_1500421_42 = "กลุ่มนี้เป็นแค่ขยะที่ฝีมือคนละชั้นกับฉันเลย!",
  str_voice_1500421_43 = "ถอยทัพ แต่เราจะกลับมาแน่!",
  str_voice_1500421_44 = "ฉันเบื่อ เรามาเล่นเกมสงครามกันดีไหม",
  str_voice_1500421_45 = "อ้า ขอบคุณนะ",
  str_voice_1500421_46 = "ไม่เลวนี่ ฉันจะลองพิจารณาใช้ดู",
  str_voice_1500421_47 = "สิ่งนี้มีค่าสุด ๆ ฉันจะรับไว้เอง",
  str_voice_1500421_48 = "ฮ่า ๆ! น่าพอใจพอ ๆ กับการต่อสู้เลย!",
  str_voice_1500421_49 = "สมรภูมิตอนนี้สู้ง่ายมากเมื่อเทียบกับสองสามปีก่อน... ตอนนั้นน่ะเป็นสงครามจริง ๆ! ไว้วันไหนจะเล่าให้ฟังนะ",
  str_voice_1500421_50 = "มีเพียงสงครามที่จะทำให้ฉันได้เป็นผู้บัญชาการกองทัพด้วยอายุเท่านี้ กลับกัน แพ็งโก้ไม่ได้โชคดีนัก บางคนกลับถูกยิงในการต่อสู้ด้วย เธอรู้ไหม",
  str_voice_1500421_51 = "อย่าดูถูกเทวทูตทั้งสี่แห่งลูโมโพลิสนะ สาว ๆ พวกนั้นสู้อย่างกับเสือ ฉันต้องหาวิธีปราบพวกนาง...",
  str_voice_1500421_52 = "Alchemy Stars!",
  str_voice_1500421_53 = "เฮ้ เธออยู่ไหม",
  str_voice_1500421_54 = "อรุณสวัสดิ์!",
  str_voice_1500421_55 = "เธอว่างไหม",
  str_voice_1500421_56 = "เธอนอนแล้วเหรอ",
  str_voice_1500421_57 = "วันปีใหม่แล้ว!",
  str_voice_1500751_1 = "ให้ตายสิ ฉันอยากจะแฮ็กพวกเรดีเซล เวรนช์งี่เง่านั่นจริง ๆ อย่างน้อยเปลี่ยนหนอนทรายไปเป็นมือเช้าตามปกติสิ!",
  str_voice_1500751_2 = "อย่าดูถูกฝ่ายเทคโนโลยีเชียว ฉันกลับหัวกลับหางพื้นได้ถ้าต้องการเลยนะ... เธอก็ยังบินได้งั้นเหรอ งั้นฉันจะหักปีกเธอทิ้ง!",
  str_voice_1500751_3 = "เตี้ยแล้วทำไมเหรอ เรามาคุยกันแบบใจ ๆ ได้ไหม เคยเห็นคนสูงแต่สมองขี้เลื่อยมาก่อนหรือเปล่า ฐานเรดีเซลที่ไหน ๆ ก็น่าจะมีแต่คนแบบนั้น!",
  str_voice_1500751_4 = "สายไฟของฉันมีพลังงานของตัวเอง ดูแรงบิดเข้าสิ มันพับได้ดีกว่าคราเคนทรายข้างนอกเสียอีก",
  str_voice_1500751_5 = "ไม่นะ สายเคเบิลพันกันอีกแล้ว เซ็งโคตร หืม... ทำไมเธอถึงล้ม ฮ่า เข้าใจแล้ว ฉันบอกได้เลยว่าเธองานเข้าแล้ว",
  str_voice_1500751_6 = "ช่องสื่อสารห่วยแตกนี่ของใครกัน ใช่ ฉันแฮ็กสัญญาณมันมา แล้วเธอจะทำไมเหรอ ถ้าไม่แกะรอยสัญญาณกลับมาหาฉันก็หุบปากไปเลย!",
  str_voice_1500751_7 = "คิดว่าโคลอสซัสทำให้เธอเป็นคนสำคัญหรือไง เลิกดัดมันแล้วเอาออกไปข้างนอกกันเถอะ ฉันจะเปลี่ยนมันเป็นเศษเหล็ก!",
  str_voice_1500751_8 = "ฉันน่ะเหรอใจร้าย ฉันเอาแต่เตือนให้เธอจัดการเวลาและกระตุ้นให้เธอเรียนหนัก เธอจะได้ไม่ถูกกลั่นแกล้งเวลาอยู่ที่นั่นตลอดเวลาไง!",
  str_voice_1500751_9 = "ฉันชอบเธอ คนดี ฉันจะสอนให้เธอพูด เพื่อให้เธอโดนตบหน้าอีก",
  str_voice_1500751_10 = "วางสายไฟและตรวจเครื่องสื่อสารแล้ว ขอโทษที่ต้องพูดตรง ๆ นะแต่ทุกคนที่นี่ไร้ประโยชน์มาก กลับกัน... อะไรน่ะ... ทำไมมันพันยุ่งไปหมดอีกแล้วล่ะ คราวนี้มีปัญหาอะไรอีก",
  str_voice_1500751_11 = "ใช่ วันนี้ฉันเจาะระบบช่องสื่อสารทั้งหมดในระยะ 10 ไมล์ให้เธอแล้ว... อะไรนะ ไม่จำเป็นขนาดนั้นเหรอ แต่ฉันทำเสร็จไปครึ่งหนึ่งแล้วนะ...",
  str_voice_1500751_12 = "การถูกขังที่นี่ชวนให้นึกถึงกิ้งก่าห่วยแตกในเรดีเซลกับคำร้องเรียนของเด็กผู้หญิงติ๊งต๊อง... ปวดหัวสิ้นดีเลยละ",
  str_voice_1500751_13 = "พวกมันไม่เห็นเบี้ยวเหมือนสายไฟของฉันเลย... พยายามอีกหน่อยดีไหม เพื่อน",
  str_voice_1500751_14 = "ตัวตลกในทีมมักจะทำลายอุปกรณ์ของพวกเขาเสมอ พวกนั้นไม่มีคำว่า \"ทะนุถนอม\" ในพจนานุกรมตัวเองหรอก",
  str_voice_1500751_15 = "วันนี้ฉันจะสาธิตพลังของช่างเทคนิคให้เธอดู! อยากให้วันเกิดเป็นยังไงล่ะ ตื่นเต้นหรือสนุก?",
  str_voice_1500751_16 = "ฉันรู้ว่าเธอจะกลับมาสองนาทีและสิบห้าวินาทีก่อน นี่คือเทคโนโลยีสื่อสารของอัจฉริยะนะ เข้าใจไหม?",
  str_voice_1500751_17 = "ฉันจะหยุดโคลอสซัสเสียงดังนี่ได้ยังไง ว้าว แล้วตอนนี้ทำไมมันถึงสั่นล่ะ",
  str_voice_1500751_18 = "มีปัญหาอะไรเหรอ ฉันจัดการเอง ง่ายนิดเดียว... อุ๊ย ไม่เอาหรอก เธอจัดการต่อเถอะ!",
  str_voice_1500751_19 = "เธอมาทันเวลาพอดีเลย มีคนมาบ่นที่เครื่องมือสื่อสาร... สหายนั่นอยากสู้กับเธอในเมืองแกนน่อน!",
  str_voice_1500751_20 = "ทำไมถึงเข้าร่วมเรดีเซล เวรนช์เหรอ สรุปง่าย ๆ ไม่ได้หรอก แต่ฉันอยู่มานานแล้วเลยลงเอยด้วยการอยู่ต่อไป",
  str_voice_1500751_21 = "รับเควสต์ที่ค่อนข้างเกี่ยวข้องกับการเจาะระบบสื่อสารอิลลูมินาไหม... มีอะไรต้องกลัวอีกล่ะ แค่หาข้อผิดพลาดในระบบพวกเขาเอง",
  str_voice_1500751_22 = "เรดีเซลอย่างเราไม่มีวันกลัวใครหรอก!",
  str_voice_1500751_23 = "ฉันจะรื้ออิคลิพไซท์ทุกตัวที่เห็นจนไม่เหลืออะไร ไม่ให้เหลือแม้กระทั่งฝุ่นเลย!",
  str_voice_1500751_24 = "บอกบร็อคว่าอย่ามายุ่งกับฉัน เศษขยะกับหัวของเขาเป็นสิ่งเดียวที่ฉันไม่ซ่อมไม่ได้",
  str_voice_1500751_25 = "บอกเขาให้ลองดูถ้าคิดว่าตัวเองเก่งขนาดนั้น! ดูสิว่าเขาใจแคบแค่ไหน ขนาดฉันกับเจ้าจิ๋วทำงานซ่อมทั้งหมดให้เรดีเซลเลยนะนั่น!",
  str_voice_1500751_26 = "เอาละ การติดตั้งทั้งหมดก็ดูใช้งานได้ ไปหาอาหารแคลอรีสูงมาให้ฉันฟื้นพลังหน่อยสิ",
  str_voice_1500751_27 = "บัคน่ะแย่ที่สุดแล้ว ถ้าทำเป็นเมินพวกมันละก็... ฉันจะระเบิดเอา",
  str_voice_1500751_28 = "เฮ้อ โคลอสซัสของเธอนี่ไม่ใช่ขยะเลยนะ... ทุกอย่างข้างในสมบูรณ์แบบแล้วมันก็ใช้งานได้เต็มระบบ เตะตาฉันเข้าแล้วสิ!",
  str_voice_1500751_29 = "โม้ชื่อฉันไปเลย โอดี จากนี้ไปเวลามีใครเลือกที่จะวุ่นวายกับระบบสื่อสารของเธอ พวกมันจะกลัวจนหางจุกตูดเลยละ!",
  str_voice_1500751_30 = "อัปเกรดอุปกรณ์แล้ว ง่ายนิดเดียว",
  str_voice_1500751_31 = "ทำให้เสร็จในไม่กี่วินาทีได้ไหม",
  str_voice_1500751_32 = "ก็เหมือนปกติไม่ใช่เหรอ... ปรับปรุงแล้วน่ะสิ!",
  str_voice_1500751_33 = "เธอช่วยทำตัวให้เป็นประโยชน์หน่อย... ใช่ นั่นคือคำตอบในหนังสือเรียน!",
  str_voice_1500751_34 = "บุกเข้าไปเลย",
  str_voice_1500751_35 = "ไหนบอกซิว่ารอบนี้ใครได้",
  str_voice_1500751_36 = "อะไรมาป่วนพวกมันล่ะเนี่ย",
  str_voice_1500751_37 = "อุ๊ย สายไฟพันกันยุ่งเหยิงอีกแล้ว!",
  str_voice_1500751_38 = "ฉันซ่อมมันให้ทำงานไม่ได้! หา พวกมันพลิกคว่ำเองเหรอ",
  str_voice_1500751_39 = "อย่าขยับ!",
  str_voice_1500751_40 = "การจู่โจมได้ผลเหรอ",
  str_voice_1500751_41 = "เดี๋ยวนะ จะให้ฉันนำเหรอ!?",
  str_voice_1500751_42 = "ฮ่า แค่กองเศษขยะเอง",
  str_voice_1500751_43 = "แต่... ฉันทำให้มันทำงานไม่ได้",
  str_voice_1500751_44 = "มีแค่นี้เหรอที่ต้องทำต่อ... โว้ว จู่ ๆ อย่าลุกมาใกล้ขนาดนั้นสิ!",
  str_voice_1500751_45 = "ดูก็รู้ว่าเธอเลือกของขวัญไม่เก่ง",
  str_voice_1500751_46 = "ดูก็รู้ว่าเธอ... เชี่ยวชาญด้านการเลือกของขวัญมาก!",
  str_voice_1500751_47 = "ฉันกะแล้วว่าเธอจะให้เจ้านี่",
  str_voice_1500751_48 = "เธอเป็นคนมีความสามารถและเข้าใจฉันที่สุด",
  str_voice_1500751_49 = "ไม่มีชิ้นส่วนเครื่องยนต์ไหนที่ฉันซ่อมไม่ได้ ถ้าจะมีก็แค่เศษขยะที่ไร้ประโยชน์โดยสิ้นเชิง!",
  str_voice_1500751_50 = "รถขยะ ปืนขยะ เรดีเซลขยะ... ฉันซ่อมขยะไปนับไม่ถ้วนแล้ว แค่เอาขยะอะไรก็ได้ที่มีมาให้ฉันก็พอ",
  str_voice_1500751_51 = "ฉันเติบโตมากับเทคโนโลยี แลกเปลี่ยนอารยธรรมและการอดทนอดกลั้น... ค-ใครบังอาจหาเรื่อง ฉันจะทำให้พวกมันเสียใจที่เกิดมา!",
  str_voice_1500751_52 = "Alchemy Stars",
  str_voice_1500751_53 = "สวัสดี?",
  str_voice_1500751_54 = "เธอตื่นอยู่หรือเปล่า",
  str_voice_1500751_55 = "มาถากถางกันเถอะ!",
  str_voice_1500751_56 = "เธออยู่บนเตียงเหรอ ฉันไม่เชื่อหรอก!",
  str_voice_1500751_57 = "เก็บไว้แล้วเจอกันปีหน้านะ!",
  str_voice_1500921_1 = "กฎหมายเป็นกฎที่ใช้ปกครองทุกอย่างบนจักรวาล แล้วมันยากที่จะเข้าใจเหตุผลที่ต้องทำตามกฎหมายไหมนะ ที่จริงก็ง่ายนิดเดียว เพราะในนั้นย่อมมีสิ่งที่เราเข้าใจอยู่แล้ว",
  str_voice_1500921_2 = "เจตนาของการโต้แย้งคือการชี้ให้เห็นความผิดพลาดในวิธีการของคนอื่น เป็นคุณสมบัติที่เหนือกว่าซึ่งจำเป็นต้องใช้ตามหลักเป็นบางครั้ง เช่น ปรับทัศนคติของคนหัวรั้นบางคน!",
  str_voice_1500921_3 = "หลักที่ \"1\" เหรอ? ไม่ ไม่ใช่ ฉันหมายถึงคำว่า \"หนึ่ง\" พวกมันต่างกันยังไงเนี่ย? อย่าบอกฉันนะว่าเธอไม่รู้ความแตกต่างระหว่างตัวเลขกับตัวอักษร",
  str_voice_1500921_4 = "ปกติแล้วหินแห่งการล่าไม่ใช่กงล้อแต่เป็นเรลิกในซากโบราณบางแห่ง... แต่ยังไงก็เห็นได้ชัดว่าเป็นกงล้อน่ะ!",
  str_voice_1500921_5 = "ธรรมบัญญัติเป็นดวงประทีปนำทางคุณในความมืด เริ่มจากการค้นหาจิตวิญญาณและไตร่ตรองว่าการดำรงอยู่แบบไหนที่คุณต้องการเป็น!",
  str_voice_1500921_6 = "ดาวตกเป็นเรลิกไร้ชื่อในอดีต กงล้อแห่งขวากหนามถูกเรียกว่า \"หินแห่งการล่า\"... ดึงดันตามล่าฉันตามที่กฎหมายตัดสิน",
  str_voice_1500921_7 = "เอาของไปคืนในที่ที่ควรอยู่ตามขนาดและเรียงตามตัวอักษร... ไม่เป็นไร ฉันทำให้เธอแล้วล่ะ",
  str_voice_1500921_8 = "ไม่มีทาง ทำไมฉันต้องไปกับเธอแค่เพราะเธอสั่งด้วย ตอนที่เธอไม่อยากให้ฉันไป ฉันถึงจะไปด้วย เข้าใจไหม?!",
  str_voice_1500921_9 = "ตามรอยเธอนี่ไม่ง่ายเลย ตอนนี้ฉันต้องหาทางคิดว่าต้องทำอะไรกับเธอ... แล้วฉันจะค่อยเป็นค่อยไปตราบใดที่ฉันยังอยู่!",
  str_voice_1500921_10 = "เธอจะมากับฉันหรือให้ฉันพาเธอมา เธอเลือกสิ หรือไม่งั้นฉันเลือกให้เธอก็ได้... ถ้าเงียบถือว่าตอบ \"ตกลง\" นะ!",
  str_voice_1500921_11 = "เธออย่าวิ่งนำหน้าฉันดีกว่า ไม่อย่างนั้นฉันจะไล่ตามเธอตามสัญชาตญาณ ใช่ อย่าหันหลังให้ฉันเชียว... อย่ามองฉันแต่ก็อย่าหันหน้าหนีด้วยล่ะ!",
  str_voice_1500921_12 = "เธอไม่คิดว่ามันแย่เหรอ ฉันเป็นคนเดียวที่คิดว่าทั้งหมดนี้มันไร้ค่าเหรอ",
  str_voice_1500921_13 = "ทำไมฉันไม่ยอมแพ้งั้นเหรอ เพราะฉันไม่มีวันยอมแพ้ไงล่ะ บอกซิว่ายังมีเหตุผลอะไรอย่างอื่นได้อีกไหม",
  str_voice_1500921_14 = "รู้ว่าอะไรผิดอะไรถูก จงเปิดใจและจริงใจอยู่เสมอ สายตามองแต่อนาคต!",
  str_voice_1500921_15 = "ของขวัญ คำอวยพร และการร้องเพลง... วันนี้ต้องใช้ทุกอย่างเพื่อให้เป็นระเบียบเรียบร้อย!",
  str_voice_1500921_16 = "เราควรทำอะไรสักอย่างไหมในเมื่อเธอกลับมาแล้ว แล้วเธอมักทำอะไรที่นี่",
  str_voice_1500921_17 = "เธอต้องใส่รายละเอียดทุกอย่างในตารางเวลาแล้วแน่เลย! ...ไม่มีทางน่ะ เธอไม่ได้ทำเหรอ",
  str_voice_1500921_18 = "ฉันหัวดื้อมากกว่าที่เธอคิด รอก่อนเถอะสักวันเธอจะต้องหนีฉันตอนที่เจอหน้ากันเลย",
  str_voice_1500921_19 = "เธอควรทำตามตารางเวลาจนถึงตัวที เห็นไหม ตอนนี้น่าจะต้องไปพักผ่อนนะ... ไม่เหรอ ไม่ใช่หรอกเหรอ",
  str_voice_1500921_20 = "ฉันตัดสินใจเข้าร่วมแล้ว ฉันก็ต้องอยู่จนถึงที่สุด ไม่ต้องห่วง ฉันจะช่วยเธอแทนความจริงแล้วกัน",
  str_voice_1500921_21 = "งั้นมุ่งหน้าไปที่เมืองเมฆาเลย ค่อยเป็นค่อยไปนะ มันไม่ใช่เรื่องยากเลย...",
  str_voice_1500921_22 = "ฉันว่ามันควรจะเป็น \"ขอให้ความจริงจงสถิตกับท่าน\"",
  str_voice_1500921_23 = "ว้าว เหลือเชื่อสุด ๆ ไปเลย... เราจะปล่อยให้คนคร่าชีวิตไปง่าย ๆ แบบนี้เลยเหรอ",
  str_voice_1500921_24 = "ตามการตัดสินของสิ่งมีชีวิตขั้นสูงกว่าแล้ว ฉันมาเพื่อ... อะไรนะ ไม่รู้กระทั่งว่าคนนั้นเป็นใครงั้นเหรอ",
  str_voice_1500921_25 = "ไม่เห็นต้องเรื่องเยอะเลย แค่ความเห็นมั่ว ๆ ของฉันก็เปลี่ยนรอยยิ้มของหมอนั่นเป็นหน้าเครียดแล้ว",
  str_voice_1500921_26 = "ความบากบั่นงั้นเหรอ... เดี๋ยวนะ \"ชอบ\" นี่หมายความว่าไง หมายถึงของ งานอดิเรกหรือความเชื่อล่ะ",
  str_voice_1500921_27 = "ไม่ใช่แค่ห่างชั้นจากคำว่าดูดีมากนะ แต่ทั้งไม่มีวินัย ไร้จุดหมาย และไม่มีแรงจูงใจด้วย... ฉันจะไปนับถือคนแบบนั้นได้ยังไง",
  str_voice_1500921_28 = "แหงสิ ฉันรู้ว่าโคลอสซัสคืออะไร มันแปลว่าเธอเป็นเพื่อนคนพิเศษไง ไม่ใช่เหรอ",
  str_voice_1500921_29 = "ฉันควรบอกชื่อของฉันเพียงเพราะว่าเธอถาม? เธอไม่คิดว่าฉันจะโกหกเหรอ แล้วถ้าฉันไม่บอกเธอล่ะ โอ้ เธอไม่สนใจแล้ว เรียกฉันว่า \"แพกต์\" แล้วกัน",
  str_voice_1500921_30 = "เรียบร้อย ต่อไป",
  str_voice_1500921_31 = "สักวันฉันจะกำจัดหินแห่งการล่า... สักวันหนึ่ง!",
  str_voice_1500921_32 = "กฎหมายเทียบเท่ากับความจริง เข้าใจไหม?!",
  str_voice_1500921_33 = "ไม่มีอะไรยิ่งใหญ่จนทำให้หลงทางได้หรอก",
  str_voice_1500921_34 = "เธอให้ฉันมาที่นี่ทำไม",
  str_voice_1500921_35 = "ฉันไม่เคยบอกว่าพร้อมนะ!",
  str_voice_1500921_36 = "แจ้งเธอเหรอ ไม่มีทาง!",
  str_voice_1500921_37 = "บีบบังคับเหรอ ไม่นะ มันจำเป็น!",
  str_voice_1500921_38 = "ทำตามกฎหมายและห้ามหวั่นไหวเด็ดขาด!",
  str_voice_1500921_39 = "หยุด!",
  str_voice_1500921_40 = "เดี๋ยวเราก็จะได้รู้กัน!",
  str_voice_1500921_41 = "ฟังนะ อย่าทำผิดกฎหมายล่ะ",
  str_voice_1500921_42 = "คนที่ทำผิดกฎหมายควรถูกลงโทษ!",
  str_voice_1500921_43 = "ตามพวกเขาไปแล้วอย่าให้หลุดรอดไปได้...",
  str_voice_1500921_44 = "อยากคุยเหรอ ได้สิ ถ้าสัญญาว่าจะไม่โกรธไม่ว่าฉันจะพูดอะไรน่ะนะ",
  str_voice_1500921_45 = "ไม่มีอะไรเล็กหรือใหญ่ไป",
  str_voice_1500921_46 = "ถ้าฉันจำเป็นต้องแสดงออกว่าชอบ มันคงไม่ได้ แบบว่า...",
  str_voice_1500921_47 = "เธอ... คงเอาของขวัญคืนไปไม่ได้... อยู่แล้ว",
  str_voice_1500921_48 = "ใช่ ฉันชอบจริง ๆ นะ เธอว่ามันเป็นไง",
  str_voice_1500921_49 = "การฟื้นคืนชีพแบบถาวรที่แทบจะเป็นอมตะ ย้อนกลับมาเรื่อยไปไม่ว่าจะถูกทิ้งที่ไหน... เป็นหินแห่งการล่าที่ดื้อรั้นจริง ๆ!",
  str_voice_1500921_50 = "เชื่อในกฎหมายง่าย ๆ พึ่งพากันและทำตามคำสั่งเสมอ ยึดมั่นในการตัดสินใจของตัวเอง มั่นคงและขึงขัง นั่นเป็นก้าวแรกของความจริงที่ยิ่งใหญ่!",
  str_voice_1500921_51 = "คนเราใช้ชีวิตและต่อสู้ไปเพื่ออะไรกัน ฉันได้คำตอบในคืนหนึ่งที่ฉันยกหัวขึ้นมาแล้วเห็นดาวส่องแสงสว่างในความมืด",
  str_voice_1500921_52 = "Alchemy Stars!",
  str_voice_1500921_53 = "สิ่งเตือนความจำ",
  str_voice_1500921_54 = "เธอมีเวลาตอบ 3 วินาที",
  str_voice_1500921_55 = "ตอนนี้เธอควรจะถึงนี่ได้แล้ว",
  str_voice_1500921_56 = "แค่มาดูให้แน่ใจว่าเธอนอนอยู่",
  str_voice_1500921_57 = "มาสิ พูดพร้อมกันกับฉันเลย \"สุขสันต์วันปีใหม่\"!",
  str_voice_1600061_1 = "การตัดสินใจจะยากขึ้นเวลามีฝูงคนอยู่ด้วย จิตใจจะกระจ่างแจ้งกว่ามากเวลาที่อยู่คนเดียว",
  str_voice_1600061_2 = "การยืนอยู่กลางศาลยุติธรรมและสภาผู้อาวุโส เราต้องรู้ตำแหน่งของเราให้ดีก่อนจะปฏิบัติตัวได้ถูกต้อง",
  str_voice_1600061_3 = "ถึงฉันจะไม่อยากให้งานเลี้ยงจบลงเร็ว แต่ฉันก็ลังเลที่ต้องเสียค่ำคืนที่แสนวิเศษชวนสมองโล่งมากที่สุดไปมากกว่า",
  str_voice_1600061_4 = "ในอดีตเราต้องมีพลัง ส่วนปัจจุบันก็จำเป็นต้องมีคำสั่ง ฉันไม่อยากจะยอมรับเลยว่าเขาสอนอะไรแบบนี้ให้ฉัน",
  str_voice_1600061_5 = "ความมั่นใจที่ชาวลูโมโพลิสมีให้มันยังคงสดใหม่ แน่นอนว่าความมั่นคงก็ไม่น่าจะอยากทดสอบกับอำนาจหรอก โดยเฉพาะในยุคที่โกลาหลแบบนี้ ฉันมั่นใจว่าแม่ก็จะคิดอย่างนี้เหมือนกัน",
  str_voice_1600061_6 = "แมงมุมดำเหรอ ก็แค่เรื่องเล่าน่าเบื่อที่ใช้ปิดบังความเจ็บปวดในความเป็นจริง ถ้ามันมีจริง หน่วยผู้พิทักษ์ก็คงจับมันไปได้นานแล้ว",
  str_voice_1600061_7 = "ความจริงมักจะเป็นแหล่งกำเนิดของการทรยศ ถึงอย่างนั้นท่านก็ดูแตกต่างจากคนอื่นข้างนอกนั่นฝ่าบาท หม่อมฉันดูคนไม่ค่อยผิดหรอก",
  str_voice_1600061_8 = "ยิ่งน้ำแข็งมีรอยแตกมากเท่าไหร่ก็ยิ่งเปราะบางเท่านั้น ก็เหมือนลูโมโพลิสนั่นแหละ... เธอคงจะดูออกได้ค่อนข้างเร็วเลยละ",
  str_voice_1600061_9 = "การยอมรับร่วมกันและความเคารพเป็นสิ่งที่หาได้ยากที่สุด ฉันมุ่งมั่นผลักดันมรดกตกทอดนั้นไปสู่จุดสูงสุดและหวังว่าเธอจะเป็นพยานรับรู้มัน",
  str_voice_1600061_10 = "ฉันขออนุญาตนะ เธอน่ะยังต้องมีเควสต์ที่ต้องทำให้เสร็จ แต่เธอเล่นไร้แรงจูงใจแบบนี้...\nอ๊าก ยังไงก็ไม่มีใครให้ค่าเธออยู่ดี",
  str_voice_1600061_11 = "ช่างเป็นสถานที่สวยงามมาก หวังว่าผู้บังคับบัญชาจะได้มาเติมเต็มความสวยงามของที่นี่",
  str_voice_1600061_12 = "ความอดทนตอนนี้ไม่ได้แสดงถึงความพึงพอใจในรูปการณ์ปัจจุบัน",
  str_voice_1600061_13 = "มีอะไรอยากปรึกษาฉันไหม ถ้าให้ฉันช่วย ความคิดเธอจะตกผลึกได้กระจ่างขึ้นนะ...",
  str_voice_1600061_14 = "ถ้าเธอดันไปเจอหน่วยผู้พิทักษ์เข้าละก็... หวังว่าราฟาเอลจะไม่สร้างปัญหาให้เธอนะ",
  str_voice_1600061_15 = "วันนี้เป็นวันเกิดเธอ ขอให้เธอแข็งแกร่งขึ้นนะ",
  str_voice_1600061_16 = "ฟังสรุปแล้ว เราจะลงมือเมื่อไหร่",
  str_voice_1600061_17 = "เยี่ยม เตรียมลงมือกันเถอะ",
  str_voice_1600061_18 = "งานส่วนใหญ่ทำเสร็จหมดแล้ว เราต้องรวบรวมรายงาน",
  str_voice_1600061_19 = "พักผ่อนบ้างนะ พรุ่งนี้ต้องมีเรื่องมากมายรอให้เธอจัดการแน่",
  str_voice_1600061_20 = "ลูโมโพลิสจะสร้างอนาคตใหม่ให้ทวีปนี้ เพราะฉะนั้นเราก็ควรทำงานหนักต่อไป",
  str_voice_1600061_21 = "อิลลูมินา พลังที่ต่อสู้กับความมืดมิดถือเป็นพลังสำคัญในแผน",
  str_voice_1600061_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1600061_23 = "อิคลิพไซท์เป็นความมืดมิดที่ฝังรากลึกในโลกใบนี้ พวกมันต้องถูกกำจัดเพื่อช่วยทุกคน",
  str_voice_1600061_24 = "ฉันหวังว่าราฟาเอลจะเลิกเรียกฉันว่าพี่สาวของเธอได้แล้ว ฉันไม่ได้แก่ขนาดนั้น",
  str_voice_1600061_25 = "กาบริเอลทำส่วนของเธอแล้วแต่เธอไม่ค่อยมีแรงบันดาลใจเท่าไหร่ หวังว่าเธอจะทุ่มเททำงานมากกว่านี้",
  str_voice_1600061_26 = "ฉันชอบอะไรเหรอ ก็ง่าย ๆ นะ ศิลปะการสงคราม ดูการแข่งขัน... และขนมรสนม",
  str_voice_1600061_27 = "ฉันไม่ชอบคนที่ไม่รู้จักเวลา กรุณาจำไว้ให้ดีด้วย",
  str_voice_1600061_28 = "โคลอสซัสนี้สมบูรณ์มาก มันอาจจะแบกฉันได้ด้วย... เปล่า ไม่มีอะไรหรอก",
  str_voice_1600061_29 = "ฉันคือคาร์ลีน เดอ ชวาตส์ ผู้พิทักษ์ของลูโมโพลิสและลูกสาวของเจ้าเมืองชวาตส์ หากมีฉันคอยเฝ้าดูอยู่ เมืองอันงดงามนี้จะไม่มีวันซ้ำรอยอดีตอันโหดร้าย",
  str_voice_1600061_30 = "หอกฉันคมเหมือนเคย!",
  str_voice_1600061_31 = "จากนี้ไปจะไม่มีที่ให้ความมืดหลบซ่อนแล้ว",
  str_voice_1600061_32 = "หอกของฉันจะทะลวงฟ้ายามค่ำคืน",
  str_voice_1600061_33 = "ทำตามคำสั่งของฉัน เรามุ่งไปข้างหน้าเท่านั้น!",
  str_voice_1600061_34 = "ฉันพร้อม",
  str_voice_1600061_35 = "การโจมตีครั้งต่อไปจะทิ่มแทงทะลุหัวใจ",
  str_voice_1600061_36 = "เธอไม่เห็นต้องถามทุกรอบเลย!",
  str_voice_1600061_37 = "ความมืดกำลังล่าถอยไป!",
  str_voice_1600061_38 = "เจอบุปผาน้ำแข็งบนท้องนภาเยือกเย็นหน่อยเป็นไง!",
  str_voice_1600061_39 = "จงโบกสะบัด! บุปผาน้ำแข็ง!",
  str_voice_1600061_40 = "ทิ่มแทงศัตรู!",
  str_voice_1600061_41 = "ยังมีโอกาสสู้อยู่ โจมตีด้วยความเร็วเลย!",
  str_voice_1600061_42 = "ชนะอีกแล้ว ตามคาด",
  str_voice_1600061_43 = "อย่าท้อไป ความพ่ายแพ้จะเป็นหลุมศพของเรา",
  str_voice_1600061_44 = "ถ้ามาที่นี่เพียงเพื่อคุยเฉย ๆ ก็จับตาดูนาฬิกาเอาไว้ให้ดีเถอะ",
  str_voice_1600061_45 = "หวังว่าเธอจะไม่ได้ทำลงไปเพราะมีเจตนาแฝงหรอกนะ",
  str_voice_1600061_46 = "ใครจะไปคิดว่าฉันจะได้สิ่งที่ต้องการจากเธอ... ขอบใจนะ",
  str_voice_1600061_47 = "ขอบคุณ ฉันรู้ว่าเธอเจตนาดี",
  str_voice_1600061_48 = "เธอรู้ตลอดเลยว่าฉันต้องการอะไร ขอบคุณนะ",
  str_voice_1600061_49 = "ฉันพยายามทำความรู้จักเขาอยู่... หมายถึงพ่อของฉันที่เป็นผู้ปกครองลูโมโพลิสน่ะ ขอโทษทีนะ แต่ฉันยังไม่ชินกับการเรียกเขาแบบนั้นเพราะอดีตที่ลืมไม่ลง...",
  str_voice_1600061_50 = "แผลเก่าหายช้า ไม่มีใครมุ่งมั่นขุดคุ้ยอดีตของเมืองอีกต่อไปแล้ว ช่วงทศวรรษที่ผ่านมาก็เกิดเรื่องเยอะเกินไป โศกนาฏกรรมบางอย่างได้เกิดขึ้นกับครอบครัวฉันแต่ไม่มีใครยอมบอกความจริงกับฉันเลย...",
  str_voice_1600061_51 = "คืนอันเงียบสงบนี้มีความเย็นยะเยือกอยู่ ตอนนี้ฉันทำได้เพียงใช้ชีวิตเหมือนอดีตอีกครั้งแล้วมองรูปครอบครัวของฉัน ตลกดีไหมล่ะ ไม่หรอก มันเศร้าต่างหาก มีความลับอะไรอยู่ในแกนกลางของเมืองนี้กันนะ...",
  str_voice_1600061_52 = "Alchemy Stars",
  str_voice_1600061_53 = "ขอโทษนะ",
  str_voice_1600061_54 = "อรุณสวัสดิ์",
  str_voice_1600061_55 = "สวัสดียามบ่าย",
  str_voice_1600061_56 = "ถึงมันจะดึกแล้วก็เถอะ",
  str_voice_1600061_57 = "สุขสันต์วันปีใหม่",
  str_voice_1600141_1 = "ลูโมโพลิสที่เก็บรักษาความเชื่อของเราไว้จะไม่มีวันล่มสลาย! ไม่ว่าจะมีวิกฤติดาร์กโอเวอร์อีกมากเท่าไหร่รอเราอยู่ก็ตาม!",
  str_voice_1600141_2 = "ไม่มีชนชั้น ไม่มีระเบียบสังคม... แล้วจะดูแลที่นี่ยังไง ด้วยมิตรภาพและข้อห้ามงั้นเหรอ ไหนมาคอยดูกันเถอะ",
  str_voice_1600141_3 = "ลูโมโพลิสเป็นโนวาใต้ออโรรา เป็นท่าจอดนิรันดร์ เธอจะไม่มีวันเข้าใจความรู้สึกที่ฉันมีให้นางหรอก",
  str_voice_1600141_4 = "พอเจอกับความโอบอ้อมอารีและสมัครสมานสามัคคีที่นี่แล้วก็พาลให้นึกถึงบ้านเล็กน้อย ฉันคิดถึงเวลาที่สงบสุข เวลาที่อยู่กับโจชัว... แล้วไม่ต้องระวังตัวแจตลอดเวลา...",
  str_voice_1600141_5 = "ลูก ๆ ของฉัน... ถ้าพวกเขาตัดสินใจให้คำสัตย์แล้ว ฉันก็หวังเพียงแต่ให้เธอรับผิดชอบสิ่งที่หนักหนาแบบนั้นได้ ถ้าเธอดูแลไม่สำเร็จ ฉันก็จะขยี้เธอให้แหลก",
  str_voice_1600141_6 = "บางครั้งผู้ปกครองชั้นสูงสุดก็ต้องใช้ความโกรธเคืองและแสดงความเมตตากรุณาไปพร้อม ๆ กัน",
  str_voice_1600141_7 = "จงรู้เขาและรู้เราเพื่อไม่ให้ลงเอยด้วยการเป็นคนโง่ปิดหูปิดตา เธอเก่งขึ้นแล้วแต่ก็ยังต้องพัฒนาอีกมาก",
  str_voice_1600141_8 = "เรดีเซล เวรนช์และอิลลูมินาเป็นอันตรายที่ซุกซ่อนอยู่แต่อิคลิพส์... ขอโทษทีนะ มีข้อมูลบางอย่างที่ฉันยังบอกเธอไม่ได้",
  str_voice_1600141_9 = "นี่คือโคลอสซัสในหัวเธอเหรอ เธอดูจะมีรูปแบบเดียวกับนางนะ ชะตาอันเลวร้ายอะไรที่ลากเราทุกคนมาเจอวังวนแห่งความวุ่นวายนี้...",
  str_voice_1600141_10 = "เสบียง การขนส่ง การจัดสรรบุคคล ทัศนวิสัย เส้นทาง วางแผน... วุ่นวายที่สุด เหมือนที่คิดไว้เลย",
  str_voice_1600141_11 = "ฉันไม่ได้ทำข้อตกลงช่วยเธอกับโคลอสซัสนี้เลย ปล่อยให้เป็นโอกาสเทิดทูนบูชาไปแล้วกัน ฉันจะพยายามอดทนเอาไว้",
  str_voice_1600141_12 = "คำพูดก็เหมือนสายลมแต่ก็กลายเป็นคมดาบได้เหมือนกัน... ทำไมถึงเลี่ยงไปใช้กองกำลังทหารทั้งที่ก็กำจัดศัตรูได้ด้วยพลังของคำพูดล่ะ",
  str_voice_1600141_13 = "ผู้ชนะไม่จำเป็นต้องอธิบายชัยชนะของตัวเองและผู้แพ้ก็ไม่ควรหาข้อแก้ตัวด้วย",
  str_voice_1600141_14 = "บางครั้งความหลักแหลมสูงสุดก็คือตอนที่ต้องปกปิดเอาไว้",
  str_voice_1600141_15 = "วันเกิดเธอเหรอ งั้นเธอก็ลาได้หนึ่งวัน",
  str_voice_1600141_16 = "ว่ากันว่าเธอพูดกับมันได้ แล้วฉันพูดได้ไหม...",
  str_voice_1600141_17 = "ยินดีต้อนรับกลับมา อาจารย์ด้านโคลอสซัส",
  str_voice_1600141_18 = "คนที่ควบคุมสิ่งมีชีวิตมหึมาขนาดนั้นได้ต้องพิเศษมากแน่ ๆ",
  str_voice_1600141_19 = "ไม่จำเป็นต้องไปดูกับตาเธอเองทุกอย่างหรอก ให้ฉันจัดการสิ",
  str_voice_1600141_20 = "ไม่ว่าจะเกิดอะไรขึ้น ฉันก็จะปกป้องลูโมโพลิสไว้เพราะเมืองเป็นส่วนหนึ่งในครอบครัวของฉัน",
  str_voice_1600141_21 = "ผู้ป้องกันที่ดีจะปิดบังพลังของตนจากศัตรู นี่เป็นกลยุทธ์ของสหพันธรัฐอิลลูมินา เพื่อป้องกันและโต้กลับ",
  str_voice_1600141_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1600141_23 = "อิคลิพส์เป็นศัตรูที่น่าสยดสยองแต่มันล่มสลายในท้ายที่สุดด้วยอำนาจของลูโมโพลิส",
  str_voice_1600141_24 = "คาร์ลีนต้องขยันให้มากขึ้นถ้านางจะมาอยู่ภายใต้การดูแลของฉัน นี่เป็นโชคชะตาของนาง",
  str_voice_1600141_25 = "อีสต์วานควรรู้ว่าฉันเฝ้ามองเขาอยู่ด้วย... นับเธอแล้วก็มีเราคอยดูอยู่สองคน",
  str_voice_1600141_26 = "ระเบียบเป็นหลักสำคัญของอารยธรรมและครอบครัวเป็นหน่วยพื้นฐานของที่นี่ ถ้าไม่มีสิ่งเหล่านั้นก็ไม่มีประเทศหรอก",
  str_voice_1600141_27 = "ไม่มีอะไรงี่เง่าไปมากกว่าการโต้เถียงกันอย่างไร้สาระแล้ว ต้องปฏิบัติให้ทันเวลาต่างหาก อย่างนี้ถึงจะน่าเชื่อถือ",
  str_voice_1600141_28 = "ความมโหฬารของโคลอสซัส... บางทีเราควรหาที่พิเศษไว้รองรับมันนะ",
  str_voice_1600141_29 = "การแนะนำอย่างเหมาะสมเป็นสัญญาณของมารยาทที่ดี ฉันคือดยุกชวาตส์ ผู้ปกครองลูโมโพลิส เราน่าจะมีอะไรให้คุยกันอีกเยอะ",
  str_voice_1600141_30 = "น่าสนใจ",
  str_voice_1600141_31 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1600141_32 = "ถ้าต้องการเมื่อไหร่ ลูโมโพลิสยินดีต้อนรับเสมอ",
  str_voice_1600141_33 = "ลูโมโพลิสจะนำทางทุกสรรพสิ่ง",
  str_voice_1600141_34 = "ไปทำสงครามกับฉันสิ",
  str_voice_1600141_35 = "ฉันรับได้อีกครั้งเดียว",
  str_voice_1600141_36 = "เริ่มกันเลย!",
  str_voice_1600141_37 = "รับคำจารึกไปซะ!",
  str_voice_1600141_38 = "ฉันจะทำให้ดาวทุกดวงสั่นสะเทือน!!",
  str_voice_1600141_39 = "ดาบแห่งราชัน!",
  str_voice_1600141_40 = "ลูโมโพลิส! ปกป้องเราด้วยเถอะ!",
  str_voice_1600141_41 = "ฉันไม่ได้สู้กับใครมานานมากแล้ว",
  str_voice_1600141_42 = "ข้าเป็นผู้บัญชาการ! เราจะแพ้ได้ยังไง?",
  str_voice_1600141_43 = "สักวันความล้มเหลวเหล่านั้นจะเป็นสัญลักษณ์แห่งความรุ่งโรจน์",
  str_voice_1600141_44 = "หืม... แกนกลางนี้น่าสนใจจริง ๆ",
  str_voice_1600141_45 = "ขอบคุณสำหรับของขวัญ ยกโทษให้ฉันด้วยที่ไม่ได้ตอบแทนอะไร",
  str_voice_1600141_46 = "ของขวัญล้ำค่าอะไรอย่างนี้... ตระกูลชวาตส์ขอรับไว้นะ",
  str_voice_1600141_47 = "นี่... ประเมินค่าไม่ได้เลย",
  str_voice_1600141_48 = "ฉันจะส่งต่อให้ทายาทเพื่อเป็นสมบัติของตระกูล",
  str_voice_1600141_49 = "เธอคงไม่เคยได้ยินเรื่องราวจุดกำเนิดของลูโมโพลิส ฝักฝ่ายของชนชั้นสูงและความลับของตระกูลชวาตส์ทั้งหมดแน่นอน",
  str_voice_1600141_50 = "ฉันใช้เวลาทั้งชีวิตพยายามทำให้ลูโมโพลิสมั่งคั่งอยู่เสมอ... ไม่ใช่แค่เพื่อตัวเองแต่เพื่อผู้คนด้วย จะเชื่อหรือไม่ก็แล้วแต่",
  str_voice_1600141_51 = "โจชัว คาร์ลีน และ... ช่างเถอะ... เราจะพลาดทุกอย่างถ้ามัวแต่คร่ำครวญอยู่",
  str_voice_1600141_52 = "Alchemy Stars",
  str_voice_1600141_53 = "เจ้าแห่งโคลอสซัส",
  str_voice_1600141_54 = "จงดีใจเสียเถิดที่เกิดระเบียบขึ้นมา หากไม่มีระเบียบ เช้านี้ก็คงไม่มีเรา",
  str_voice_1600141_55 = "จงบากบั่นเข้าไว้ ผู้คุมระเบียบ",
  str_voice_1600141_56 = "เธอคงยังไม่นอนสินะ",
  str_voice_1600141_57 = "เก็บคำพูดเอาไว้... เฉลิมฉลองกันเถอะ!",
  str_voice_1600291_1 = "โฮ่ ๆ... ท้องฟ้ามืดมัวมีไว้ให้เราเหม่อมอง... แต่ดวงอาทิตย์ก็มองยากอยู่ดี ถึงจะมีเมฆครึ้มกระจัดกระจายก็เถอะ",
  str_voice_1600291_2 = "กำลังสังเคราะห์ด้วยแสง... ฉันไม่ได้หมายถึงนักเรียนมัธยมนะ! ฉันก็อยู่แล้ว... อุ๊ย ฉันบอกอายุของฉันกับเธอไม่ได้หรอก ไม่งั้นฉันก็คงต้องปิดปากเธอ",
  str_voice_1600291_3 = "วันนี้เสร็จงานแล้ว! ขอบคุณเจ้าหน้าที่พลเคลื่อนเร็ว โอ้! ว่าไปแล้วเขามีทิ้งข้อความไว้ให้ฉันแต่กลับสบถใส่ฉันตลอดเวลาเลย ฮ่า ๆ ๆ ๆ...",
  str_voice_1600291_4 = "กรงขัง... มีไว้เพื่อปกป้องเธอมากกว่ามากักขังฉัน... โฮ่ ๆ ฉันพูดอะไรของฉันเนี่ย...",
  str_voice_1600291_5 = "ฉันเลิกคิดไม่ได้ว่ามีคนหน้าคุ้นมาก ๆ อยู่ที่นี่ อ้อ ฉันไม่ได้หมายถึงเธอ... สำหรับฉันแล้ว เธอคุ้นเสียยิ่งกว่าคุ้นอีก อ่าาา... การใช้ความคิดเป็นการออกกำลังสมองที่เปลืองพลังจริง ๆ...",
  str_voice_1600291_6 = "สายลม ป่าไม้และเวลาพัดผ่านมาจากอดีต... ความทรงจำของฉันคืนกลับมาและบินถลาออกไปจากคุกวิเศษนี่!",
  str_voice_1600291_7 = "เธอดูห่วงใยฉันมากนะ ฉันส่งต่องานทั้งหมดที่คาร์ลีนสั่งมาให้เด็กนั่นหมดแล้ว เราจะได้คุยกันได้ดี ๆ ยังไงล่ะ!",
  str_voice_1600291_8 = "ฉันมีของขวัญให้เธอ! มัน... โฮ่ ๆ มันไม่อยู่นี่แฮะ ขอโทษที ความทรงจำฉันฟั่นเฟือนน่ะ ความจำฉันฟั่นเฟือน...",
  str_voice_1600291_9 = "ฉันคิดมานานแล้วว่า... ถ้าฉันแง้มกรงให้เธอนิดหน่อยก็คงไม่เป็นไรใช่ไหม แต่ถ้าเกิดเหตุการณ์ซ้ำรอยล่ะ... หืม ก่อนหน้านี้เกิดอะไรขึ้นนะ จู่ ๆ ฉันก็ลืมเสียอย่างนั้น",
  str_voice_1600291_10 = "เธอดูไม่ได้ทำอะไรนะนั่น เราใจตรงกันอย่างน่าตกใจเลย",
  str_voice_1600291_11 = "โฮ่ ๆ ที่นี่ก็ไม่แย่นะ ทิวทัศน์สวยแล้วอุณหภูมิเตาปฏิกรณ์ตะวันก็พอดีด้วย มันเหมาะกับ... การนอนที่สุด...",
  str_voice_1600291_12 = "หืม... เมื่อกี้คาร์ลีนบอกให้ฉันทำอะไรนะ ฉันลืมแล้ว",
  str_voice_1600291_13 = "โฮ่ ๆ ต้องการอะไรเหรอ สายลมบอกฉันแล้วว่าเธอจะมา",
  str_voice_1600291_14 = "เธอบอกอะไรกับฉันก็ได้แล้วฉันจะฟัง... เอ๊ะ ฉันฟังจริง ๆ นะ",
  str_voice_1600291_15 = "วันเกิด... หืม... หืม... เราต้องร้องเพลงวันเกิดใช่ไหม แฮปปี้เบิร์ธเดย์ทูยู♪",
  str_voice_1600291_16 = "เธอกลับมาแล้ว! อย่ายุ่งให้มากนักสิ",
  str_voice_1600291_17 = "ดวงอาทิตย์ขึ้นแล้วหรือยัง เธอนี่ขยันทำงานจริง ๆ",
  str_voice_1600291_18 = "คร่อกฟี้... โฮ่ ๆ เกือบเผลอหลับแล้วเชียว ก็ไม่สำคัญหรอกว่าไหม ฉันว่าไม่มีใครรู้หรอก",
  str_voice_1600291_19 = "คร่อกฟี้... เอ๊ะ ไม่มีอะไรหรอก ฉันยังลืมตาอยู่... ฉันยัง... ไม่หลับ...",
  str_voice_1600291_20 = "ลูโมโพลิสดูแลฉันดีมากตอนเพิ่งมาถึงที่นี่ ฉันซึ้งใจในตัวพวกเขาแล้วหวังว่าพวกเขาจะได้เพลิดเพลินกับสันติสุขนะ",
  str_voice_1600291_21 = "คนที่ช่วยฉัน... มาจากอิลลูมินา ฉันจะจำเขาให้ได้... ฉันสัญญา",
  str_voice_1600291_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1600291_23 = "ถ้าเกิดฉันบอกว่าฉันจำวิธีการโกรธได้เพราะสิ่งมีชีวิตนี้ล่ะ เธอจะตกใจหรือเปล่า",
  str_voice_1600291_24 = "ตอนฉันเพิ่งมาถึง เขาก็เป็นแค่เด็กดื้อน่ะ... โฮ่ ๆ ฉันพูดได้แค่นี้แหละ",
  str_voice_1600291_25 = "ราฟาเอลน้อยเก่งกาจด้านการรักษาและการทำงานมาก แต่เรื่องทักษะการทำอาหารของนางนะ... วะฮ่า ๆ",
  str_voice_1600291_26 = "งีบข้าง ๆ เตาปฏิกรณ์ตะวันอุ่น ๆ น่ะดีที่สุดแล้ว ใต้ดวงอาทิตย์แสนสบายด้วย",
  str_voice_1600291_27 = "หืม... ความรู้สึกไม่ชอบเป็นยังไงเหรอ ฉันจำไม่ค่อยได้",
  str_voice_1600291_28 = "โฮ่ ๆ ครั้งแรกที่ฉันเห็น ฉันก็นึกว่ามันเหมือนกรงของฉันนิดหน่อยน่ะ",
  str_voice_1600291_29 = "โฮ่ ๆ เธอคือคนที่เขาลือกันสินะ... ฉันคือกาบริเอล นอกนั้นก็ไม่มีอะไรสำคัญล่ะ... เรายังเหลือเวลาอยู่ด้วยกันอีกมากมายเลย มากเท่าฤดูใบไม้ผลิยามบ่าย...",
  str_voice_1600291_30 = "ทำไมเธอรีบร้อนนักล่ะ",
  str_voice_1600291_31 = "กรง... สั่นสะเทือน",
  str_voice_1600291_32 = "ความทรงจำกำลังเติบโต",
  str_voice_1600291_33 = "กรงหายวับไป...",
  str_voice_1600291_34 = "เสียงดังเอะอะจังเลย!",
  str_voice_1600291_35 = "ฤดูใบไม้ผลิกำลังจะมา",
  str_voice_1600291_36 = "แล้วแต่เธอเลย ท่านทูตของฉัน",
  str_voice_1600291_37 = "เติบโตมาซุกซนตามที่เธอต้องการเลย!",
  str_voice_1600291_38 = "พัดพาออกไป! สายลมฤดูใบไม้ผลิสดชื่น!",
  str_voice_1600291_39 = "โอ้ โทษที?",
  str_voice_1600291_40 = "ยกโทษให้ไม่ได้",
  str_voice_1600291_41 = "โฮ่ ๆ ฉันควรทำตามตัวอย่างบ้างนะ",
  str_voice_1600291_42 = "สิ่งสำคัญที่สุดคือจงมีความสุข",
  str_voice_1600291_43 = "โฮ่ ๆ เราหลงทาง เราควรกลับไปดื่มชาสักแก้วไหม",
  str_voice_1600291_44 = "อยากงีบด้วยกันเหรอ นอนหลับแล้วรู้สึกสบายจริง ๆ นะ! ทำหัวให้โล่งแล้ววูบไปเลย...",
  str_voice_1600291_45 = "ให้ฉันเหรอ ไม่ล่ะ ฉันไม่ได้ไม่ชอบหรอก...",
  str_voice_1600291_46 = "โฮ่ ๆ น่าสนใจจัง รู้สึกสดชื่นขึ้นมาเลย",
  str_voice_1600291_47 = "ขอบใจนะ ของขวัญดีจัง!",
  str_voice_1600291_48 = "โฮ่ ๆ เอ่อ รู้ได้ไงว่าฉันชอบเจ้านี่ที่สุดน่ะ",
  str_voice_1600291_49 = "ฉันเคยเจอสงครามนั้น แต่ฉันไม่รู้หรอกว่าเกิดอะไรขึ้นจริง ๆ มันเกิดขึ้นจริงเหรอ ฉันก็ว่างั้นนะ... ตอนนี้เริ่มปวดหัวนิดหน่อยแล้วสิ",
  str_voice_1600291_50 = "กรงเคยพังมาก่อนหน้านี้... แต่ฉันคิดว่าหลังจากนั้นมีคนเชื่อมมันแล้ว ใครกันนะ เป็นคนที่คุ้นหน้าคุ้นตาน่ะ โอ้ ฉันจำไม่ได้เฉยเลย",
  str_voice_1600291_51 = "อย่าหันกลับไป ไม่มีอะไรนอกจากควันสีเทาเลือนรางและขอบเหล็กหนาวเย็น บางทีเธออาจจะช่วยให้ฉันจำอะไรได้สักวันหนึ่ง...",
  str_voice_1600291_52 = "Alchemy Stars!",
  str_voice_1600291_53 = "อ้าว สวัสดี!",
  str_voice_1600291_54 = "ฉันบังเอิญตื่นขึ้นมาเพราะดวงอาทิตย์ล่ะ!",
  str_voice_1600291_55 = "ฉันชอบพระอาทิตย์ยามบ่ายของวันนี้",
  str_voice_1600291_56 = "เพราะฉันยังไม่นอน...",
  str_voice_1600291_57 = "โฮ่ ๆ สุขสันต์วันปีใหม่!",
  str_voice_1600641_1 = "ชัยชนะที่ยุติธรรมและตรงไปตรงมาเป็นทางเดียวที่จะคว้าชัยอันยิ่งใหญ่ได้ ส่วนพวกชอบแทงข้างหลังก็จะถูกหักหลังในไม่ช้าก็เร็ว",
  str_voice_1600641_2 = "เรดบารอนต้องถูกปลดปล่อยเป็นครั้งคราวเพื่อรักษาสภาพให้ดี",
  str_voice_1600641_3 = "การตรวจสอบโคลอสซัสให้สมบูรณ์อยู่ในรายการถัดไป ฉันน่าจะเป็นหนึ่งคนที่ใช้พลังงานจากมันมากขึ้น",
  str_voice_1600641_4 = "ความกลัวไล่คนอ่อนแอออกไป แต่มันทำให้ฉันแข็งแกร่งขึ้น",
  str_voice_1600641_5 = "พลังและสถานะควรเป็นสิ่งที่รับมา ไม่ใช่ส่งต่อ",
  str_voice_1600641_6 = "เธอก็รู้จุดแข็งของฉันนี่ ฉันจะรับภารกิจที่คนอื่นทำไม่สำเร็จ",
  str_voice_1600641_7 = "คนที่มีอำนาจไม่จำเป็นต้องเก่งกว่าคนอื่น พวกเขาก็แค่ต้องใช้ความกล้าตัดสินใจอะไรยาก ๆ",
  str_voice_1600641_8 = "ความทะเยอทะยานเป็นดั่งลูกบอลติดไฟที่แผดเผาคนอ่อนแอแต่นำทางคนแข็งแกร่งอย่างฉัน",
  str_voice_1600641_9 = "สักวันหนึ่งฉันจะเป็นจอมทัพของอิลลูมินา เมื่อถึงเวลานั้นแล้ว รองแม่ทัพก็น่าจะเป็นไรน์ฮาร์ต... หรือไม่ก็เธอ",
  str_voice_1600641_10 = "ไม่มีภารกิจให้รับเหรอ งั้นเราจะไปทำสมาธิกัน มันก็เป็นการฝึกจิตอย่างหนึ่งนะ",
  str_voice_1600641_11 = "รับทราบ ฉันจะตอบรับคำขอของเธอเพื่อให้เธอสนับสนุนฉันในอนาคต",
  str_voice_1600641_12 = "ผู้บัญชาการกองทัพสามารถปฏิบัติตัวตามสบายได้อย่างผิวเผินแต่ควรจะระวังตัวเอาไว้ในใจ",
  str_voice_1600641_13 = "ไฟรั่วจากริคโทเฟนเหรอ โอ้ เจตนาสินะ ไม่ต้องห่วง ฉันควบคุมได้หมด",
  str_voice_1600641_14 = "การได้ครอบครองอาวุธทรงพลังแต่ไม่มีวิธีใช้ก็เหมือนเด็กถือแท่งทองเดินไปตามถนนที่คนพลุกพล่าน",
  str_voice_1600641_15 = "ฉันจะใช้เรดบารอนตัดเค้กวันเกิดของเธอในครั้งนี้ครั้งเดียว",
  str_voice_1600641_16 = "ระวังไว้เสมอ! มุ่งมั่นตลอดเวลา!",
  str_voice_1600641_17 = "อรุณสวัสดิ์! งานรออยู่!",
  str_voice_1600641_18 = "ยังพอมีเวลาก่อนพัก มาต่อกันเถอะ",
  str_voice_1600641_19 = "ฉันไม่เหนื่อยหรอก ถ้าจำเป็นแล้วฉันอยู่ได้ทั้งวัน",
  str_voice_1600641_20 = "จงซื่อสัตย์และเที่ยงธรรม—นั่นคือสิ่งที่สหพันธ์อิลลูมินาสอนฉัน นั่นเป็นเหตุผลที่ฉันไม่มีวาระซ่อนเร้น",
  str_voice_1600641_21 = "ลูโมโพลิสไม่มีอนาคตเพราะว่าจัดตั้งขึ้นมาจากตระกูลราชวงศ์และสายเลือดของพวกเขา",
  str_voice_1600641_22 = "อิลลูมินา!",
  str_voice_1600641_23 = "อิคลิพไซท์เหรอ ไม่มีอะไรให้กลัวหรอก พวกนั้นเป็นเหมือนรากฐานการพัฒนาตัวเองของฉัน",
  str_voice_1600641_24 = "ถ้าอยากเอาชนะไรน์ฮาร์ตให้ได้ก็ต้องผ่านฉันไปให้ได้ก่อน",
  str_voice_1600641_25 = "วิเวียนเพอร์เฟกต์กับการเป็นลูกน้อง แต่เธอไม่เหมาะที่จะนำ",
  str_voice_1600641_26 = "เมื่อพลังเพิ่มขึ้น สถานะก็เพิ่มขึ้นไปด้วย",
  str_voice_1600641_27 = "พวกต้มตุ๋นน่ารังเกียจควรถูกความยุติธรรมขยี้ให้แหลกแม้ว่าจะช้าไปหน่อยก็ตาม",
  str_voice_1600641_28 = "ถ้าฉันมีโคลอสซัสอยู่ในกองพันละก็... ฉันคงมีกองทัพอากาศแล้ว",
  str_voice_1600641_29 = "ว่าที่จอมทัพของอิลลูมินา วราธมาแล้ว สนับสนุนฉันแล้วเธอจะมีอนาคตที่สดใส",
  str_voice_1600641_30 = "นี่คือพลังที่ฉันสมควรได้รับ",
  str_voice_1600641_31 = "คำราม! ริคโทเฟน!",
  str_voice_1600641_32 = "เร่งความเร็ว! เรดบารอน!",
  str_voice_1600641_33 = "ไม่มีอะไรขวางฉันได้ทั้งนั้น!",
  str_voice_1600641_34 = "ฉันควรเป็นกัปตัน",
  str_voice_1600641_35 = "พุ่งชน! เรดบารอน!",
  str_voice_1600641_36 = "เข้าปะทะ! เรดบารอน!",
  str_voice_1600641_37 = "โหมดโอเวอร์ชาร์จ ทำงาน!",
  str_voice_1600641_38 = "สายฟ้าฟาด! เรดบารอน!",
  str_voice_1600641_39 = "ริคโทเฟน!",
  str_voice_1600641_40 = "เรดบารอน!",
  str_voice_1600641_41 = "ฉันตั้งใจอยู่ในตำแหน่งนี้",
  str_voice_1600641_42 = "ง่ายนิดเดียว",
  str_voice_1600641_43 = "อั่ก แพ้เพราะเครียด...",
  str_voice_1600641_44 = "หืม... ฉันจะควบคุมโคลอสซัสที่ทรงพลังขนาดนั้นได้ไง",
  str_voice_1600641_45 = "ก็นะ เธอไม่เห็นจำเป็นต้องเลย",
  str_voice_1600641_46 = "เยี่ยม ฉันควรพิจารณาความสัมพันธ์ของเราใหม่",
  str_voice_1600641_47 = "ขอบใจนะ ฉันจะจำเอาไว้",
  str_voice_1600641_48 = "ความโอบอ้อมอารีของเธอทำฉันซาบซึ้งใจ ฉันไม่เคยรู้สึกแบบนั้นมานานแล้ว ดังนั้นขอบใจนะ",
  str_voice_1600641_49 = "ฉันคือผู้บัญชาการกองทัพ ไม่ใช่เพราะความสัมพันธ์กับไรน์ฮาร์ตแต่เป็นน้ำพักน้ำแรงที่ฉันลงไปในสมรภูมิรบ",
  str_voice_1600641_50 = "ฉันอาจพลาดการต่อสู้กับอิคลิพไซท์ครั้งสุดท้ายแต่ฉันกำจัดอิคลิพไซท์ที่ร่อนไปมาทั้งหมดได้แล้ว! ความสำเร็จของฉันก็ไม่ต่างอะไรกับผู้บัญชาการกองทัพอื่น ๆ ทั้งสามคนหรอก",
  str_voice_1600641_51 = "บางครั้งฉันก็สงสัยว่าเราแทนที่ไรน์ฮาร์ตได้จริง ๆ หรือไม่ นางเป็นคนช่วยฉันไว้ตอนบาดเจ็บสาหัส...",
  str_voice_1600641_52 = "Alchemy Stars",
  str_voice_1600641_53 = "ผู้นำทาง ตอบรับด้วย!",
  str_voice_1600641_54 = "นี่คือวราธเรียก!",
  str_voice_1600641_55 = "เธอได้ยินฉันไหม",
  str_voice_1600641_56 = "ร้องขอสายพิเศษ เปลี่ยน",
  str_voice_1600641_57 = "ปีใหม่สุขสันต์!",
  str_voice_1600231_1 = "โอ้... ฉันจะทำใจสู้ทักทายคนได้ไหม เฮ้ ไม่ได้ทักทายจริง ๆ หรอก เลิกแตะฉันได้แล้ว!!",
  str_voice_1600231_2 = "มีมุมมืดไหนที่ฉันอยู่กับตัวเองได้บนโคลอสซัสไหม... ฉันไม่อยากให้ใครมาเจอ ฉันยังทำเจ้านั่นไม่เสร็จเลย...",
  str_voice_1600231_3 = "ฉันถือสานะเนี่ย... อะไรนะ อ๋อ ฉัน... ฉันขอโทษ! ฉันแค่เร่ร่อนไปเรื่อยน่ะ...",
  str_voice_1600231_4 = "ทุกคนกลัวกันหมด... ถ้าฉันเลิกกลัวได้สักวันหนึ่ง ฉันอาจไปรู้ความลับของแอนตันเข้า...",
  str_voice_1600231_5 = "ฉันได้ยินอีกแล้ว เสียงกระซิบของแอนตัน! โว้ว! ทำไมเอนมาใกล้ฉันจังเลยละ ฉันไม่ได้ตั้งใจเรียกเธอมานะ...",
  str_voice_1600231_6 = "- คอนนอลลี\n- คอนนอลลีผู้น่าสงสารและแสนเปราะบาง ไม่ต้องกลัวไปนะ ได้ยินเราไหม\n- ฟังเสียงเราไว้นะ เราจะคอยอยู่เป็นเพื่อน\n- เป็น... ความมืดมิดอันอ่อนโยน ฉันไม่ต้องอยู่คนเดียวอีกแล้ว...",
  str_voice_1600231_7 = "เธอ... เธอถามฉันว่า... ใคร... ฉันพูดกับใครเมื่อกี้เหรอ แต่... พวกนั้น... พวกนั้นอยู่ตรงนี้นี่...",
  str_voice_1600231_8 = "เอาละ... แอนตันชอบมากเหมือนกัน... ดูท่าเธอจะเชื่อถือได้นะ...",
  str_voice_1600231_9 = "ฉันคิดเสมอ... ว่าถ้าฉันอยู่กับเธอ ฉันจะไม่รู้สึกกลัวอีกไม่ว่าจะไปไหน งั้น... เธอ... เข้ามาใกล้อีกได้ไหม",
  str_voice_1600231_10 = "เป็นโทนที่แปลกพิลึก... ไม่ใช่ว่ามันชวนให้รู้สึกแย่อะไรหรอก มันทำให้มั่นใจมากกว่า คงไม่ทำให้คนเข้าโรงพยาบาลอีกใช่ไหม เอาละนะ",
  str_voice_1600231_11 = "ท-ทุกคนบอกว่าฉันเหมาะที่จะทำแบบนี้ จริงหรือเปล่า ทำไมรู้สึกเหมือนมีดวงตาจ้องมองฉันเพิ่มขึ้นแล้วล่ะ",
  str_voice_1600231_12 = "ฉันได้รับ... การช่วยเหลือจากคนนั้น... เดย์นา โรบิน และไฮแดรดก็ด้วย...",
  str_voice_1600231_13 = "ทักษะพิเศษของแอนตัน... คือการทำให้ทุกคนหลับใหล จู่ ๆ ฉันก็รู้สึกง่วงมากขึ้นมาเลย...",
  str_voice_1600231_14 = "มัน... สว่างเกินไป ตาจะบอดแล้ว... ไม่นะ ไม่ ฉันต้องกลับไปที่มุม...",
  str_voice_1600231_15 = "- สุขสันต์วันเกิดนะ!\n- สุขสันต์วันเกิด\n- สะ-สุขสันต์วันเกิด... ผู้นำทาง...",
  str_voice_1600231_16 = "เฮ้! เธอ... กลับมาแล้วเหรอ ไม่มีอะไรหรอก...",
  str_voice_1600231_17 = "- ชู่ว! คอนนอลลียังหลับอยู่นะ!\n- ใกล้ได้เวลาเปิดร้านแล้วด้วย ไม่ปลุกเธอจะดีเหรอ",
  str_voice_1600231_18 = "- คอนนอลลี มาเล่นโดมิโน่กับฉันสิ!\n- แอนตัน ฉันทำงาน... โอ้ มีลูกค้าด้วย!",
  str_voice_1600231_19 = "สั่งกาแฟตอนนี้น่ะนะ เอะ-เอสเปรสโซ่เหรอ คืนนี้มีคนตาค้างแน่...",
  str_voice_1600231_20 = "ภายใต้เงาของแอชูไรต์ อัมบราตันผสมผสานระหว่างสันติและความวุ่นวาย... เหตุผลที่มันมีทุกอย่าง",
  str_voice_1600231_21 = "- น่าเบื่อ\n- ไม่สนุก\n- หลอกลวงทั้งหมด\n- หืม...",
  str_voice_1600231_22 = "แชโดว์จ้องมองอยู่...",
  str_voice_1600231_23 = "เจ้าพวก... สิ่งน่ากลัวนั่น... ฉันไม่อยากเห็นพวกมันอีก ไม่มีวัน...",
  str_voice_1600231_24 = "เดย์นาดื่มกาแฟขมไม่ได้... แต่นางก็ยังสั่งมาดื่มทุกครั้ง ฉันชอบแอบใส่ครีมให้นางตลอด",
  str_voice_1600231_25 = "นมร้อนใส่น้ำตาลสามก้อน... อันนี้ของโรบิน นางมักจะเงียบเหมือนลูกแมวเสมอ",
  str_voice_1600231_26 = "- ขนมหวานช็อกโกแลตในตู้เย็นชอบหายไปแบบเงียบ ๆ โดยไม่มีเหตุผลเสมอ ทำไมกันนะ\n- ง่ำ ๆ ๆ อร่อยจังเลย",
  str_voice_1600231_27 = "- นานแสนนานมาแล้วมีร้านคาเฟ่...\n- อ๊าย!\n- เอ๊ะ ฉันไม่ได้เล่าเรื่องผีสักหน่อยนะ!",
  str_voice_1600231_28 = "ใหญ่จังเลย... ตั้งร้านฮอลิเดย์คาเฟ่เพิ่มอีกสองสามร้านได้พอดีเลยนะ... คนเยอะมาก...",
  str_voice_1600231_29 = "เอ่อ เหมือนฉันจะหลงทางแล้ว! ไม่นะ ไม่ใช่แบบนั้นสิ ฉันคือคอนนอลลี ส่วนนี่แอนตันและญาติพี่น้อง... ของมัน... ล่ะมั้ง",
  str_voice_1600231_30 = "ฉันไม่มีความตั้งใจที่จะแข็งแกร่งขึ้นเลย...",
  str_voice_1600231_31 = "เธอเชื่อใจฉันขนาดนั้นจริง ๆ แฮะ...",
  str_voice_1600231_32 = "หลอนเหรอ ไม่นะ ไม่มีทาง ฉันเป็นคนอัญเชิญมันมาเองนะ!",
  str_voice_1600231_33 = "สุดท้ายแล้วความทุกข์และเศร้าโศกจะ... บรรเทาลงด้วยเสียงเพลง",
  str_voice_1600231_34 = "แอนตัน เราต้องลุยแล้วล่ะ...",
  str_voice_1600231_35 = "ฉัน... ฉันได้ยินพวกมัน!",
  str_voice_1600231_36 = "ระเบิด? ตอนนี้?!",
  str_voice_1600231_37 = "ให้ตายสิ! ฉันขอโทษจริง ๆ",
  str_voice_1600231_38 = "แอนตัน สนใจพละกำลังของเธอเป็นหลัก!",
  str_voice_1600231_39 = "น่ากลัวจัง...",
  str_voice_1600231_40 = "ด้วยกันกับครอบครัว...",
  str_voice_1600231_41 = "ฉันจะนำทางพวกเธอทั้งหมดแบบลังเลเอง!",
  str_voice_1600231_42 = "เราชนะจริง ๆ เหรอ ไม่อยากจะเชื่อเลย...",
  str_voice_1600231_43 = "ขอโทษนะ... ฉันควรกลับไปและเฝ้าอยู่ที่มุมดีไหม...",
  str_voice_1600231_44 = "ขอโทษทีนะ... แอนตันไม่ได้ตั้งใจ... ฉันก็ไม่ได้ตั้งใจเหมือนกัน...",
  str_voice_1600231_45 = "... เธอ... เธอไม่ควร...",
  str_voice_1600231_46 = "จริงเหรอ! ฉันรับไว้ได้จริงเหรอ",
  str_voice_1600231_47 = "ว้าว! ของขวัญพวกนี้มาจากคอนนอลลีเหรอ",
  str_voice_1600231_48 = "เอ้า... นี่ก-กาแฟของเธอ เพื่อเป็นการตอบแทนบุญคุณน่ะ",
  str_voice_1600231_49 = "มันชื่อแอนตัน นั่นก็ชื่อแอนตันเหมือนกัน... ทีแรกฉันก็สับสนนะแต่ถ้าฟังดี ๆ จะสังเกตได้ว่าเสียงมันต่างกันนิดหน่อย",
  str_voice_1600231_50 = "พ่อแม่ฉันน่ะ ฉันอยากเจอพวกเขาอีกครั้งแล้วบอกว่าฉันคุยกับแอนตันรู้เรื่องแล้ว คลาริเนตที่ฉันได้เป็นของขวัญก็ถูกเก็บรักษาไว้อย่างดี...",
  str_voice_1600231_51 = "คุณย่า ฉันหวังว่าคุณย่าจะอยู่ที่นี่ด้วย... หือ คนนั้นเหรอ ฉันอยู่ได้โดยไม่มีเขา ฉันไม่สามารถมองตาเขาได้ และไม่ใช่เพราะฉันจืดชืด แอนตันก็ด้วย ไม่มีพวกเราคนไหนทำได้",
  str_voice_1600231_52 = "Al-alchemy Stars",
  str_voice_1600231_53 = "สะ... สวัสดี...",
  str_voice_1600231_54 = "อรุณสวัสดิ์!",
  str_voice_1600231_55 = "สวัสดียามบ่าย! อยากดื่มชายามบ่ายหน่อยไหม",
  str_voice_1600231_56 = "ฉัน... ฉันได้ยินเสียงอะไรประหลาด ๆ ด้วยล่ะ!",
  str_voice_1600231_57 = "สุขสันต์วันปีใหม่...",
  str_voice_1400321_1 = "ถ้ามีปัญหาอะไรก็บอกฉันได้ตามสบายเลยนะ ฉันมีหน้าที่ช่วยเหลือเธออยู่แล้ว",
  str_voice_1400321_2 = "ฉันเป็นสมาชิกของศาลยุติธรรม ถึงฉันจะไม่อยากลงคำตัดสินสุดท้ายก็ตาม... ไม่เป็นไร ฉันไม่ว่าอะไรหรอก ตราบใดที่ฉันได้ทำงานตามที่ฉันศรัทธาน่ะ",
  str_voice_1400321_3 = "อย่างที่ฉันเคยบอกก่อนหน้านี้ กรุณาอย่าจ้องปีกข้างเดียวของฉันเลย สายตาเธอจ้องเขม็งเกินไปแล้วฉันก็ไม่รู้ว่าต้องทำตัวยังไง...",
  str_voice_1400321_4 = "ยิ่งขนเยอะเท่าไหร่ มันก็มีส่วนสำคัญยิ่งขึ้นที่จะรั้งปีกไว้เท่านั้น ฉันต้องคอยระวังเพื่อปกป้องมันไม่ให้เป็นอันตราย",
  str_voice_1400321_5 = "ศรัทธาทำให้ดวงตาฉันสว่างไสวขึ้น สิ่งที่สามัญชนละทิ้งไปมันดูชัดเจนสำหรับฉันเสียเหลือเกิน",
  str_voice_1400321_7 = "เธอเหมือนจะทำแต่สิ่งที่เชื่อถือสินะ ไม่ผูกมัดกับพันธสัญญาและข้อจำกัดอะไร... ฉันอิจฉาความมุ่งมั่นของเธอจัง",
  str_voice_1400321_8 = "คำสอนของเธอชัดเจนและเข้าใจง่าย เหมือนที่อาจารย์พิตต์แมนกล่าวไว้เลย... ฉันไม่ได้รู้สึกแย่อะไรนะ แต่ฉันกลับชื่นชมเลยละ",
  str_voice_1400321_9 = "ฉันมีคำถามนิดหน่อย ไม่มีอะไรน่าห่วงหรอก ฉันแค่สงสัยว่าเธอจะชวนฉันให้ไปด้วยไหม เมื่อทุกอย่างสิ้นสุดลงแล้ว ฉันขอเป็นหนึ่งในคู่หูของเธอด้วยได้ไหม",
  str_voice_1400321_10 = "ที่นี่ก็ไม่มีเหรอ ฉันทิ้งมันไว้ที่นี่ในตอนนั้นแน่นอน...",
  str_voice_1400321_11 = "เธอคาดหวังในตัวฉันมาก... ไม่เป็นไร ฉันจัดการได้และจะไม่ทำให้เธอผิดหวังแน่นอน!",
  str_voice_1400321_12 = "ลูกอมกับยาพิษก็เหมือนกันนั่นแหละ",
  str_voice_1400321_13 = "ปีกข้างเดียวของฉันเป็นสัญลักษณ์ของภารกิจฉัน เป็นของขวัญที่ศรัทธามอบมาให้ฉัน",
  str_voice_1400321_14 = "สำหรับผู้ที่มีความศรัทธา ความทุกข์ทรมานจะเกิดขึ้นชั่วคราวเท่านั้น",
  str_voice_1400321_15 = "วันนี้เองที่โชคชะตาพาเธอมาสู่โลกใบนี้ สุขสันต์วันเกิดนะ",
  str_voice_1400321_16 = "ยินดีต้อนรับ เพื่อนร่วมศรัทธา",
  str_voice_1400321_17 = "ในที่สุดความคลางแคลงจะถูกนำโดยศรัทธา",
  str_voice_1400321_18 = "ไม่เห็นต้องมาดูฉันบ่อยนักเลย มันไม่จำเป็นน่ะ เข้าใจไหม",
  str_voice_1400321_19 = "ไม่มีลำดับความสำคัญระหว่างแสงสว่างและความมืดหรอก มีเพียงคนครึ่ง ๆ กลาง ๆ เท่านั้นที่หมกมุ่นกับความแตกต่างนั้น",
  str_voice_1400321_20 = "หัวใจที่มุ่งมั่นมากมายเป็นสิ่งที่นำความเจริญรุ่งเรืองมาสู่ลูโมโพลิส",
  str_voice_1400321_21 = "หากไม่มีศรัทธาแล้ว สหพันธรัฐอิลลูมินาก็ไม่สามารถเป็นอย่างนี้ได้แน่นอน",
  str_voice_1400321_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1400321_23 = "อิคลิพส์จะต้องถูกทำลาย",
  str_voice_1400321_24 = "ในฐานะตัวแทนศาลยุติธรรม อาจารย์อิริดอนถือกำเนิดขึ้นมาเพื่อปกป้องเกียรติของลูโมโพลิส",
  str_voice_1400321_25 = "หัวใจยุติธรรมของอาจารย์พิตต์แมนไม่ได้มาจากนิสัยของเขาแต่กลับเป็นศรัทธาต่างหาก",
  str_voice_1400321_26 = "ศรัทธาชะล้างทุกอย่างให้บริสุทธิ์และนำชีวิตใหม่มายังโลกใบนี้",
  str_voice_1400321_27 = "ถ้าต้องการคนจับผู้ลบหลู่ก็บอกมานะ ฉันยินดีที่จะมีส่วนร่วม",
  str_voice_1400321_28 = "แต่อารยธรรมที่เก่าแก่และล้ำสมัยจะสูญหายไปเพราะสูญเสียศรัทธาเช่นกัน...",
  str_voice_1400321_29 = "สวัสดี อย่ามัวแต่จ้องปีกข้างเดียวของฉันสิ... มันเขิน ๆ น่ะ",
  str_voice_1400321_30 = "ตอนนี้ฉันบินไปบนท้องฟ้ากว้างใหญ่ได้แล้ว",
  str_voice_1400321_31 = "ฉันจะรับผิดชอบหน้าที่มากขึ้น",
  str_voice_1400321_32 = "ฉันจะกลายเป็น... ผู้แทนแห่งความศรัทธา!",
  str_voice_1400321_34 = "งานใหม่?",
  str_voice_1400321_35 = "ฉันจะใช้พลังแห่งศรัทธาของฉัน",
  str_voice_1400321_36 = "ระวังนะ",
  str_voice_1400321_37 = "ใช้พลังแห่งศรัทธา...",
  str_voice_1400321_38 = "กระจายออกไป! กระจายตัว!",
  str_voice_1400321_39 = "ปีกขนนก!",
  str_voice_1400321_40 = "ชำระล้าง!",
  str_voice_1400321_41 = "เริ่มการพิพากษาอีกครั้ง!",
  str_voice_1400321_42 = "ทุกสิ่งแปรเปลี่ยนเป็นศรัทธาที่ถูกทำนาย",
  str_voice_1400321_43 = "นี่เป็นความต้องการของโชคชะตา...",
  str_voice_1400321_44 = "ปีกเหรอ แน่นอนดูได้สิ แต่อย่าจับนะ",
  str_voice_1400321_45 = "ฉันไม่อยากให้เธอเสียพลังงานกับเจ้านี่",
  str_voice_1400321_46 = "อ้า เจ้านี่ทำใจฉันสงบเลย ขอบคุณนะ",
  str_voice_1400321_47 = "ฉันซาบซึ้งใจกับความคิดที่เธอใส่ลงไปในนี้นะ ขอบคุณสำหรับของขวัญ",
  str_voice_1400321_48 = "ฉันภาวนาให้ได้เจ้านี่พอดีเลย! พระเจ้าคุ้มครอง!",
  str_voice_1400321_49 = "ความทุกข์ของผู้ศรัทธาจบลงแล้ว ถึงคราวผู้ลบหลู่แล้วล่ะ คุณพิตต์แมน ฉันจะไม่มีวันยอมล่าถอยถึงแม้ปีกข้างเดียวจะยังเจ็บปวดก็ตาม",
  str_voice_1400321_50 = "ช่วงวิกฤติดาร์กโอเวอร์ ฉันเสียครอบครัวและปีกไป แต่ก็ได้ศรัทธาช่วยนำทางฉันมาจนถึงทุกวันนี้",
  str_voice_1400321_52 = "Alchemy Stars",
  str_voice_1400321_53 = "คู่หูคู่ศรัทธา",
  str_voice_1400321_54 = "อรุณสวัสดิ์ พระคุ้มครองนะ",
  str_voice_1400321_55 = "ศรัทธาร้องเรียกเธออยู่",
  str_voice_1400321_56 = "สายัณห์สวัสดิ์ ผู้จงรักภักดี",
  str_voice_1400321_57 = "สุขสันต์วันปีใหม่ ปีนี้ศรัทธาของฉันก็ยังไม่แปรเปลี่ยน",
  str_voice_1400851_1 = "การฝากและถอนแต่ละครั้งจะถูกบันทึกไว้เพื่อให้กู้ยืมได้อย่างเหมาะสม",
  str_voice_1400851_2 = "อยากเห็นไหมว่าอะไรอยู่ข้างใน ไม่มีทางซะล่ะ",
  str_voice_1400851_3 = "ฉันไม่เสนอตัวช่วยคนอ่อนแอและไม่ก้มหัวให้คนแข็งแกร่ง ฉันใช้ชีวิตตามกฎนี้แหละ",
  str_voice_1400851_4 = "ปากกาและกระดาษเป็นอาวุธของฉัน เหมือนดาบและโล่ของทหารไงล่ะ",
  str_voice_1400851_5 = "มีพินัยกรรมแสนโลภมากมายในกล่องมาร์มอนของฉัน ชีวิตของคนนับไม่ถ้วนขึ้นอยู่กับมันแล้ว",
  str_voice_1400851_6 = "จะหาบันทึกเพิ่มได้ก็ต้องมีผู้ช่วยตลอดเวลา ใช่ ฉันต้องการนกพวกนั้น",
  str_voice_1400851_7 = "ความเศร้าและความสุขของผู้คนนั้นถูกแยกออกไป เมื่อเธอเข้าใจเหตุนั้น เธอก็เข้าใจกฎของฉัน",
  str_voice_1400851_8 = "ในฐานะพยานแล้ว ฉันต้องดูมีกาละเทศะ เพราะอย่างนั้นฉันเลยซื้อชุดสูท 30 ชุดมาล่ะ",
  str_voice_1400851_9 = "กล่องของฉันเต็มไปด้วยความลับของคนมากมาย ไม่ใช่แค่คนในอัมบราตันแต่รวมถึงชนชั้นสูงจากลูโมโพลิสด้วย",
  str_voice_1400851_10 = "ฉันไม่ค่อยได้พักผ่อนแบบนี้... ฉันปวดคอกับไหล่มาสักพักแล้ว... ควรไปนวดหน่อยล่ะ",
  str_voice_1400851_11 = "อยากพักเหรอ ได้สิ ฉันจะดูแลโคลอสซัสนี่เองแล้วก็จดเอกสารเอา",
  str_voice_1400851_12 = "เธอเคยเห็นนกยิ้มหรือเปล่า",
  str_voice_1400851_13 = "เขาของฉันเหรอ ฉันได้ยินว่ามันเป็นตัวแทนความโลภของปีศาจ และเป็นสุดยอดความโลภที่มนุษย์ทุกคนต่างใฝ่หา",
  str_voice_1400851_14 = "ฉันเป็นพยานรู้เห็นของอันธพาลชนชั้นสูงและอัศวินน่ารังเกียจที่สุดด้วยปากกาของฉัน",
  str_voice_1400851_15 = "ฉันจำประวัติของเธอได้ งั้นก็สุขสันต์วันเกิดนะ",
  str_voice_1400851_16 = "วันแสนสงบสุข ก็แค่ทำงานเอกสารไป",
  str_voice_1400851_17 = "ยามรุ่งสางเป็นเวลาที่เหมาะจะลับคมปากกาของฉันที่สุด",
  str_voice_1400851_18 = "เริ่มสายแล้วแต่ฉันก็ยังต้องรวบรวมบันทึกของวันนี้อีก ฉันยังพักไม่ได้",
  str_voice_1400851_19 = "ฉันต้องเอาบันทึกพวกนี้ใส่ลงในกล่องมาร์มอน ไม่อย่างนั้นฉันจะไม่สบายใจ...",
  str_voice_1400851_20 = "บันทึกที่เหมาะสมสามารถกำจัดความวุ่นวายแถวนี้ได้",
  str_voice_1400851_21 = "เรื่องสกปรกจะต้องถูกบันทึกลงประวัติศาสตร์ ลูโมโพลิสก็ไม่มีข้อยกเว้น",
  str_voice_1400851_22 = "ฉันมาเพื่อเป็นพยาน",
  str_voice_1400851_23 = "พวกนั้นจดบันทึกกันยังไงเหรอ... ถ้าพวกนั้นไม่มีความทรงจำก็น่าเศร้านะ",
  str_voice_1400851_24 = "อีสต์วานแบกภาระไว้มากเกินไป เขาเหมือนกับอีกร่างของอัมบราตัน เป็นเงาของลูโมโพลิสไปตลอดกาล",
  str_voice_1400851_25 = "เชโอลอาจจะเจ้าเล่ห์และเปลี่ยนไปเรื่อย แต่กฎของนางก็ง่าย ๆ ผลประโยชน์สำคัญกว่าทุกสิ่ง",
  str_voice_1400851_26 = "การคัดลายมือสวยเป็นพรสวรรค์จากพระเจ้าที่ดีที่สุดบนโลกใบนี้",
  str_voice_1400851_27 = "ถ้าคนเราไม่มีกฎจะยังมีจิตวิญญาณอยู่ไหม",
  str_voice_1400851_28 = "ดูแล้วมันน่าจะมีความทรงจำจากอดีตอันเนิ่นนาน น่าจะเป็นความทรงจำเรื่องอะไรนะ",
  str_voice_1400851_29 = "ฉันบันทึกประวัติศาสตร์ของอัมบราตัน พร้อมด้วยสันติและความวุ่นวายที่เกิดขึ้นในตรอกมืด ผ่านปลายปากกาและกระดาษ ลงชื่อ เจน พยาน",
  str_voice_1400851_30 = "ฉันจะเขียนบันทึกบทใหม่ล่ะ",
  str_voice_1400851_31 = "การรู้เห็นของฉันชัดเจนมากขึ้น",
  str_voice_1400851_32 = "กล่องมาร์มอนเก็บบันทึกได้เพิ่มขึ้นมากมาย",
  str_voice_1400851_33 = "ฉันเลือกเส้นทางการบันทึกเอกสารที่ไม่สิ้นสุด",
  str_voice_1400851_34 = "ฉันจะเป็นพยานรับรู้การต่อสู้เอง",
  str_voice_1400851_35 = "เตรียมรับมือ",
  str_voice_1400851_36 = "เริ่มกันเลย",
  str_voice_1400851_37 = "ปิดฉากทุกอย่าง!",
  str_voice_1400851_38 = "มันจบแล้ว เจ้าพวกโลภมาก!",
  str_voice_1400851_39 = "แตกสลาย!",
  str_voice_1400851_40 = "ไม่มีใครหนีไปได้ทั้งนั้น!",
  str_voice_1400851_41 = "ฉันจะบันทึกประสิทธิภาพของทุกคนไว้",
  str_voice_1400851_42 = "ได้รับชัยชนะ จดบันทึกไว้แล้ว",
  str_voice_1400851_43 = "ถ้าเรื่องนี้ไม่จดบันทึกลงไปได้ละก็...",
  str_voice_1400851_44 = "ฉันจะบันทึกความจริงตามที่ฉันเห็น",
  str_voice_1400851_45 = "ฉันจะบันทึกของขวัญนี้ลงในหนังสือ",
  str_voice_1400851_46 = "ขอบคุณนะ มันช่วยได้มากจริง ๆ!",
  str_voice_1400851_47 = "ฉันจะตอบแทนเธอ ฉันสัญญา",
  str_voice_1400851_48 = "นี่มัน...! ฉันพูดขอบคุณเท่าไหร่ก็คงไม่พอ...",
  str_voice_1400851_49 = "อีสต์วานและเชโอลชวนฉันเข้าร่วมกับพวกเขา แต่ฉันแค่อยากเป็นคนจดบันทึกสำหรับอัมบราตัน ฉันไม่สนใจเรื่องปกครองเมืองเลยซักนิด",
  str_voice_1400851_50 = "ถ้าเธอสังเกตละก็ ไม่ว่าจะเป็นชนชั้นสูงหรือพลเรือน ทุกคนก็จะมีด้านที่เหมาะกับพวกเขาและอีกด้านที่ไม่เหมาะ",
  str_voice_1400851_51 = "อัมบราตันถูกอิคลิพไซท์โจมตี เป็นผลให้แม่ของฉันถูกฆ่า ผู้คนมากมายเกลียดชังลูโมโพลิสที่เมินเฉยแต่ฉันก็ไม่ได้ไปโกรธเคืองอะไรพวกนั้นหรอก",
  str_voice_1400851_52 = "Alchemy Stars",
  str_voice_1400851_53 = "เธออยู่ตรงนั้นไหม",
  str_voice_1400851_54 = "อรุณสวัสดิ์",
  str_voice_1400851_55 = "สวัสดียามบ่าย",
  str_voice_1400851_56 = "ราตรีสวัสดิ์",
  str_voice_1400851_57 = "สุขสันต์วันปีใหม่",
  str_voice_1600021_1 = "อีกฟากฝั่งของหน้าต่าง พายุฝนดูจะหายไปแล้ว ฉันไม่เคยคิดเลยว่าจะพบเจอความสงบสุขแบบนี้ที่โคลอสซัส",
  str_voice_1600021_2 = "โลกนี้อาจดูเหนือจริง แต่ชีวิตย่อมมีข้อจำกัด เหมือนเธอกับโคลอสซัส และฉันกับดาบยาวเล่มนี้",
  str_voice_1600021_3 = "คนเราต้องเด็ดขาดมากเวลาต้องเลือกระหว่างหนีเสือหรือปะจระเข้ดี แต่... ก็ไม่ใช่ว่าทุกคนจะตัดสินใจได้ ฉันก็ไม่ได้เหมือนกัน",
  str_voice_1600021_4 = "นักสู้ควรมีสติในช่วงเวลานั้นและไม่วอกแวก ฮิอิโระ เธอต้องไม่ชะล่าใจแม้ว่าจะพัฒนาฝีมือแล้วก็ตาม",
  str_voice_1600021_5 = "หัวใจของฉันเต็มไปด้วยเรื่องราววีรบุรุษที่ตายไปแล้ว ความทรงจำภูเขาเมฆาพวกนั้น... ฉันจะไม่ลังเลอีกต่อไป!",
  str_voice_1600021_6 = "ซากุระ ซาคาเอะ พลังที่หายไปชั่วพริบตา และความมุ่งมั่นในการเผชิญหน้ากับความตาย นี่คือทั้งหมดที่ฉันมี",
  str_voice_1600021_7 = "โลกดูฟื้นตัวขึ้นมาด้วยฝนตกปรอย ๆ ในฤดูใบไม้ผลิและหญ้าเขียวขจี ลองมาดูไหม",
  str_voice_1600021_8 = "ความตายไม่น่ากลัว การสละชีพสูญเปล่าต่างหากที่น่ากลัว เธอจะสละชีพตัวเองไปเพื่ออะไรล่ะ",
  str_voice_1600021_9 = "โลกนี้อาจเหนือจริงแต่มีโคลอสซัสนี้กับเธอแล้ว... โลกใบนี้ก็ดูต่างออกไปเลย",
  str_voice_1600021_10 = "ฟู่ จำเป็นต้องพักแล้วสิ ฉันจะถือโอกาสนี้ไปตั้งสมาธิ หวังว่าจะไม่มีใครมารบกวนนะ...",
  str_voice_1600021_11 = "เป็นเกียรติที่ถูกเธอเลือกนะ หวังว่าฉันจะไม่ทำให้เธอผิดหวัง",
  str_voice_1600021_12 = "ซาคาเอะเป็นชื่อดาบเล่มนี้ เขาเป็นเพื่อนฉันมาหลายปีแล้ว",
  str_voice_1600021_13 = "...ในบ้านเกิดของฉัน มักจะมีซากุระเบ่งบานในช่วงเวลาเงียบงันมากมายเสมอ",
  str_voice_1600021_14 = "ทำไมเราไม่หาที่นั่งไว้ทำสมาธิไปพร้อมกันล่ะ มันช่วยบรรเทาอาการล้าได้ ซึ่งมันก็ดีสำหรับการทำงานนะ",
  str_voice_1600021_15 = "ฉันเตรียมถ้วยชาร้อนและซากุระเล็กน้อยสำหรับวันเกิดเธอวันนี้แล้ว และหวังให้เธอมีความสุขนิรันดร",
  str_voice_1600021_16 = "เธอกลับมาแล้ว ทุกอย่างปกติดี",
  str_voice_1600021_17 = "การฝึกฝนสำหรับกองพันจบลงแล้ว ถ้าต้องการอะไรก็บอกได้นะ",
  str_voice_1600021_18 = "ไม่ต้องห่วง ฉันยังอยู่ที่นี่",
  str_voice_1600021_19 = "ได้เวลาพักแล้ว ไม่ต้องห่วงฉัน ฉันจะอยู่ต่ออีกหน่อย",
  str_voice_1600021_20 = "เราซาบซึ้งใจกับอิลลูมินานะ นี่เป็นสถานที่ที่เหมาะให้ฉันกับซาคาเอะพักอาศัยที่สุดแล้วล่ะ",
  str_voice_1600021_21 = "เธออาจเคยได้ยินฉันพูดถึงบ้านเกิด มันอยู่ทางตะวันออกไกลบนทวีปนี้น่ะ",
  str_voice_1600021_22 = "ขออิลลูมินาจงเจิดจำรัส",
  str_voice_1600021_23 = "ออโรเรียนและอิคลิพไซท์เกิดมาตรงข้ามกัน พวกนั้นเผชิญหน้ากันได้ด้วยดาบเท่านั้น",
  str_voice_1600021_24 = "นางชวนฉันไปเป็นตัวแทนอิลลูมินาและฉันก็ติดค้างหนี้นาง ฉันจะไม่มีวันลืมร่างอันทรงพลังของนางได้เลย",
  str_voice_1600021_25 = "ส่วนใหญ่แล้วเราติดต่อกันเพราะธุระทางการ แต่ฉันนับถือทักษะการวางแผนของนางจริง ๆ",
  str_voice_1600021_26 = "การทำสมาธิ มังกรชมพู ซาคาเอะ... สิ่งที่สำคัญสำหรับฉันจะนับว่าเป็นสิ่งที่ฉันชอบได้ไหม",
  str_voice_1600021_27 = "ฉันก็คงไม่บอกว่าไม่ชอบหรอก แต่ฉันก็ไม่ได้เต็มใจจะเป็นเพื่อนกับกลุ่มคนที่ยังไม่ตื่นขึ้นมา",
  str_voice_1600021_28 = "เคยได้ยินตำนานเกี่ยวกับมังกรขาวไหม เหมือนโคลอสซัสนี่เลยละ หวังว่ามันจะไปได้ไกลนะ",
  str_voice_1600021_29 = "ฉันชื่อฮิอิโระ ชีวิตมันเหนือความเป็นจริง โชคชะตาพาเรามาให้พานพบกัน ฉันกับซาคาเอะพร้อมรับใช้เธอแล้ว",
  str_voice_1600021_30 = "ฉันก้าวเข้าไปใกล้... เป้าหมายของฉันอีกก้าว",
  str_voice_1600021_31 = "ฉันต้องสลัดความเห็นแก่ตัวออกไป",
  str_voice_1600021_32 = "จงอย่าเกรงกลัวความตาย เหมือนดอกไม้ฤดูใบไม้ผลิที่แสนอบอวล",
  str_voice_1600021_33 = "ซากุระ ร่วมมือกับฉันไล่ตามบทสุดท้ายของโชคชะตาเราเถอะ!",
  str_voice_1600021_34 = "ไปเปลี่ยนแปลงโชคชะตาด้วยกันนะ",
  str_voice_1600021_35 = "ตั้งสติ",
  str_voice_1600021_36 = "เตรียมดาบให้พร้อม",
  str_voice_1600021_37 = "มุ่งหน้าสู่ความตาย แล้วเราจะอยู่รอด!",
  str_voice_1600021_38 = "พายุซากุระ!",
  str_voice_1600021_39 = "ร่วง!",
  str_voice_1600021_40 = "ลำแสงอาร์ก!",
  str_voice_1600021_41 = "ฉันจะต้องไม่เป็นตัวอัปยศ",
  str_voice_1600021_42 = "การต่อสู้นั้นเป็นไปด้วยความตระหนักรู้อย่างแน่นอน",
  str_voice_1600021_43 = "... ความพ่ายแพ้ไม่ใช่เรื่องน่าอาย",
  str_voice_1600021_44 = "เส้นทางที่ซากุระผลิบานเป็นทางกลับบ้านไปหาความทรงจำของฉัน",
  str_voice_1600021_45 = "ขอบใจนะ ไม่เห็นต้องทำแบบนี้เลย",
  str_voice_1600021_46 = "ของขวัญชิ้นนี้... ช่วยบอกทีว่าฉันจะตอบแทนยังไงได้บ้าง",
  str_voice_1600021_47 = "เธอคงไตร่ตรองเรื่องของขวัญมาดีแล้ว ขอบคุณนะ",
  str_voice_1600021_48 = "เจ้านี่... เอ่อ ฉันชอบมากเลยละ ไม่นะ ฉันรักเลย...",
  str_voice_1600021_49 = "หน้าที่ของฉันคือช่วยเหลือเธอ ตอนที่ฉันอยู่ในอิลลูมินาแล้วรับหน้าที่สำคัญอย่างผู้บัญชาการกองทัพมา ฉันก็ไม่ได้เกิดที่นี่นะ...",
  str_voice_1600021_50 = "ถึงฉันจะยังเด็กตอนจากบ้านเกิดมาแต่ก็เลี่ยงไม่ได้ที่จะมีร่องรอยที่เหลืออยู่สลักแน่นอยู่ในตัวฉัน เหมือนความซื่อตรงและชื่อฉัน...",
  str_voice_1600021_51 = "ชีวิตคาดเดาไม่ได้ ฉันกับซาคาเอะออกมาจากภูเขาเมฆาด้วยกันแต่ฉันกลับได้เข้าร่วมอิลลูมินาคนเดียว... ตอนนี้เธอก็มานี่แล้ว หวังว่าจะไม่มีเซอร์ไพร์สอะไรอีกแล้วนะ...",
  str_voice_1600021_52 = "Alchemy Stars",
  str_voice_1600021_53 = "สวัสดี",
  str_voice_1600021_54 = "อรุณสวัสดิ์",
  str_voice_1600021_55 = "ขอโทษนะ",
  str_voice_1600021_56 = "เริ่มดึกแล้วสิ",
  str_voice_1600021_57 = "สุขสันต์วันปีใหม่",
  str_voice_1500331_1 = "โชคร้ายที่โคลอสซัสไม่มีคู่มือแถมมาให้ด้วย ดังนั้นการใช้งานจริงจึงเป็นหนทางเดียว!\nหืม ฟังดูเหมาะดีแฮะ เพราะว่า.. เพราะ... เดี๋ยวนะ ขอเวลาสักครู่",
  str_voice_1500331_2 = "เปิดใช้งานโคลอสซัสด้วยกันได้ก็แปลว่าเราเกิดมาคู่กัน... ดังนั้นจะมาเกลียดชังเคืองกันเรื่องทำโคลอสซัสเสียหายไปก็ไม่มีเหตุผลเลย... ใช่ไหม",
  str_voice_1500331_3 = "แผนต่อสู้วันนี้... หืม ดังไปเหรอ ขอโทษทีนะ... ฉันคิดว่ายิ่งดังก็ยิ่งดี... ไม่ใช่หรอกเหรอ",
  str_voice_1500331_4 = "ฉันจะไม่ดูถูกตัวเองแล้ว เพราะฉันไขปริศนาได้และพบว่าตัวเองมีค่า ฉันจะไม่ปล่อยให้อดีตมาซ้ำเติมอีก...",
  str_voice_1500331_5 = "ความแข็งแกร่งที่เพิ่มขึ้นจะนำพาชัยชนะมาให้ฉัน... ถึงแม้ว่าฉันจะฝันร้ายไม่เลิกก็ตาม มันก็ห้ามไม่ให้ฉันแกร่งขึ้นไม่ได้หรอก!",
  str_voice_1500331_6 = "ฉันจะรักษาศรัทธาไว้ตลอดไป ศรัทธาที่จะส่องแสงเหมือนออโรราตอนกลางคืน",
  str_voice_1500331_7 = "ทำไมเธอถึงไม่เปิดใช้งานโคลอสซัสล่ะ? พูดง่าย ๆ ก็คือหาวิธีแก้ไขทุกอย่างที่ถูกต้องน่ะ...\nงั้น ฉัน... มาถูกทางแล้วใช่ไหม?",
  str_voice_1500331_8 = "ฉันจำเป็นต้องตื่นตัวเต็มที่ตลอดเวลาสมัยที่ทำเควสต์คนเดียว แต่ตอนนี้ฉันก็มีคู่หูกับเขาแล้วสักที! คู่หูที่ไม่ต้องเสียเงินสักแดง! โอ้... รับอะไรเป็นค่าบริการหน่อยไหมล่ะ",
  str_voice_1500331_9 = "ฉันเดาว่าฉันอยากรู้จักเธอสองคนมากกว่านี้เพราะเราคอยดูแลกันและกันมาสักพักแล้วน่ะ ฉันอวยพรให้พวกเธอมีแต่อะไรดี ๆ นะ!",
  str_voice_1500331_10 = "งานนี้เหลือสิ่งที่ต้องทำอีกเท่าไหร่ล่ะ แค่ทำต่อไปอีกหน่อย... เธอก็ควรได้พักล่ะ เธอควรได้พักจริง ๆ",
  str_voice_1500331_11 = "ฉันจัดการเอง ฉันจัดการได้ทุกอย่างแหละ! แต่ถ้าเธอช่วยฉันได้ก็คงดีนะ!",
  str_voice_1500331_12 = "อยากให้ช่วยไหม ฉันจะช่วยเธอเอง! ยังไงฉันก็ฉันจำ \"ขั้นตอนรับมือเหตุฉุกเฉิน\" มาได้หมดแล้ว",
  str_voice_1500331_13 = "มึนหัวเพราะบินเหรอ ไม่ต้องห่วง! งีบสักงีบเลย ตอนฉันขึ้นมาบนโคลอสซัสครั้งแรกก็มีปัญหาแบบเดียวกันนี่แหละ",
  str_voice_1500331_14 = "มีคนส่องแสงสว่างให้โลกของฉัน เพิ่มสิ่งที่ทำลายไม่ได้ขึ้นมา",
  str_voice_1500331_15 = "ซ่อนมันซะ แล้วปิดไฟ ทีนี้ของขวัญก็พร้อมแล้ว... เอ๊ะ เธออยู่ตรงนั้นตั้งแต่เมื่อไหร่",
  str_voice_1500331_16 = "ยินดีต้อนรับกลับมา! เก่งมาก งั้น... ฉันจะไปพักแล้วรอเข้ากะต่อไป",
  str_voice_1500331_17 = "เธอตื่นแล้วเหรอ ฉันสื่อสารตามที่ลงเวลาไว้เสร็จแล้ว ทีนี้มาคุยกันเถอะว่าตารางวันนี้เป็นไงบ้าง!",
  str_voice_1500331_18 = "อีกอย่าง รายงานโคลอสซัสใกล้เสร็จแล้ว... อาจจะเสร็จก่อนเวลา...",
  str_voice_1500331_19 = "ไม่คิดเลยว่าเธอจะทำงานล่วงเวลาจนถึงป่านนี้... เธอนี่ทุ่มเทมากจริง ๆ!",
  str_voice_1500331_20 = "ระบบที่ยอดเยี่ยมพร้อมโอกาสในการเรียนรู้ที่เท่าเทียมกัน ฉันโชคดีมากที่ได้รับการอุปถัมภ์จากอิลลูมินา",
  str_voice_1500331_21 = "ประสบการณ์ในลูโมโพลิสของฉันสอนอะไรฉันมามาก ถ้าเธอเคยไปมาก่อนอ่ะนะ!",
  str_voice_1500331_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1500331_23 = "ทุกคนมีเหตุผลที่จะจับอาวุธ... ฉันก็เหมือนกัน",
  str_voice_1500331_24 = "แม้ว่าคารอนจะดูเหมือนไร้ระเบียบ แต่เขามีคุณสมบัติที่ดีหลายอย่าง เช่น... อ๊ะ ให้ฉันกลับไปหาเธอเถอะ",
  str_voice_1500331_25 = "ถึงตัวนางเองจะค่อนข้างน่าปวดหัวแต่การวิจัยของนาง... จะทำให้เธอปวดหัวมากกว่าเดิม",
  str_voice_1500331_26 = "เพลงกล่อมเด็กและโน้ตเปียโน... ของพวกนี้ล้วนซับซ้อนมากเลยว่าไหม",
  str_voice_1500331_27 = "ฉันไม่ชอบความล้มเหลว โดยเฉพาะตอน... ที่ฉันเกือบได้ลิ้มรสความสำเร็จแต่สุดท้ายก็ล้มเหลวเพราะความไร้เดียงสา",
  str_voice_1500331_28 = "โคลอสซัสอาจเหมือนเครื่องมือหรืออาวุธสำหรับคนส่วนใหญ่ แต่ฉันรู้สึกว่ามันเหมือนเพื่อนมากกว่า ว่างั้นป่ะ",
  str_voice_1500331_29 = "ฉันไวซ์ไง! จำฉันได้ใช่ไหม โอ้... เยี่ยมเลย! มีอยู่แวบหนึ่งที่ฉันกังวลว่าจะไม่ได้ทำให้ใครประทับใจเลยน่ะ!",
  str_voice_1500331_30 = "ฉันแข็งแกร่งได้อีก!",
  str_voice_1500331_31 = "มีโชคชะตาลึกลับอะไรรอฉันอยู่ภายภาคหน้าอีกไหมนะ",
  str_voice_1500331_32 = "คำอวยพรและความสุขที่ยิ่งใหญ่ที่สุดอยู่ที่นี่แล้วจริง ๆ",
  str_voice_1500331_33 = "มุ่งไปข้างหน้า! ไปสู่อนาคตปริศนา!",
  str_voice_1500331_34 = "ฉันจะพยายามให้มากขึ้น!",
  str_voice_1500331_35 = "พร้อมแล้วและพร้อมมานานแล้วด้วย!",
  str_voice_1500331_36 = "อยากได้คู่มือไปด้วยไหม",
  str_voice_1500331_37 = "ไม่มีอะไรยั้งฉันไว้ได้!",
  str_voice_1500331_38 = "ได้เวลาปิดฉากการต่อสู้ที่ไร้ความหมายแล้ว!",
  str_voice_1500331_39 = "ติดตามเป้าหมาย!",
  str_voice_1500331_40 = "ห้ามแพ้!",
  str_voice_1500331_41 = "ให้นำเหรอ ได้เลย! แน่นอน!",
  str_voice_1500331_42 = "ฮ่า! ไม่ต้องสงสัยเลย!",
  str_voice_1500331_43 = "ถอยทัพก่อนเถอะ... มีชีวิตเพื่อสู้ต่อในวันอื่น",
  str_voice_1500331_44 = "โว้ว! พระเจ้า! อะไรกันนี่ เกมระทึกหัวใจวายหรือไง",
  str_voice_1500331_45 = "ของขวัญให้ฉันเหรอ เนื่องในโอกาสอะไรล่ะ",
  str_voice_1500331_46 = "สร้างไมตรีจิตเหรอ เข้าใจแล้ว!",
  str_voice_1500331_47 = "ขอบใจ! ฉันไม่ได้ไม่ชอบมันหรอก จริง ๆ นะ!",
  str_voice_1500331_48 = "เธอตั้งตาคอยดูของขวัญของฉันที่ให้เธอนะ!",
  str_voice_1500331_49 = "ครั้งหนึ่งฉันอยากเคยเป็นแสงแห่งความหวังที่เจิดจ้าจนกระทั่งฝันสลายไป... ไม่เป็นไร ฉันไม่ได้วางแผนไว้ว่าจะยอมแพ้หรอก ถึงฉันจะเสียพรสวรรค์และความสามารถไปก็ตาม",
  str_voice_1500331_50 = "โชคชะตาอาจโหดร้าย แต่ก็ไม่เคยปราศจากความหวัง ฉันหมายถึง ตอนนี้เธออยู่ที่นี่เพื่อฉันแล้วใช่ไหม เธอสามารถรับฉันเป็นความหวังของเธอได้เช่นกัน ถ้าเธอไม่รังเกียจ...",
  str_voice_1500331_51 = "เธอเคยคิดไหมว่าจะเกิดอะไรขึ้นบนโลกนี้เมื่อความลับทุกอย่างของเรา อิคลิพไซท์ และท้องฟ้าทั่วหล้าถูกเปิดเผยขึ้นมาน่ะ เธอจะยัง... ยึดมั่นในศรัทธาต่อไปไหม",
  str_voice_1500331_52 = "Alchemy Stars!",
  str_voice_1500331_53 = "เธอตรงนั้นน่ะ คู่หูที่ไว้ใจได้ของฉัน",
  str_voice_1500331_54 = "อรุณสวัสดิ์! เธอรู้สึกยังไงบ้าง",
  str_voice_1500331_55 = "เธอไม่ยอมพักเที่ยงใช่ไหมนี่",
  str_voice_1500331_56 = "ทำงานได้ดีมาก!",
  str_voice_1500331_57 = "ฉันรอวันที่จะร่วมงานกับเธอในปีที่จะมาถึงนี้อยู่นะ!",
  str_voice_1500131_1 = "ฉันชอบที่นี่! ฉันจะแกะสลักน้ำแข็งโคลอสซัสเท่าตัวจริงเลย! เดี๋ยวนะ... ที่จริงมันก็ยากไปหน่อย",
  str_voice_1500131_2 = "เรามีหน้าที่ปกป้องสิ่งแวดล้อม! ในนอร์ธแลนด์ การแสวงประโยชน์เช่นนี้จะถูกลงโทษอย่างรุนแรงจากองค์ราชินี",
  str_voice_1500131_3 = "ฉันจะแกะสลักหน้าไวซ์บนก้อนน้ำแข็งขนาดใหญ่เบ้อเร่อ! คิดว่านางจะโกรธหรือเซอร์ไพร์สดีล่ะ",
  str_voice_1500131_4 = "ฉันไม่เคยกอดน้ำแข็งแบบนี้มาก่อนเลย... มันรู้สึก... ต่างออกไป สร้างสโนว์แมนกันเปล่า",
  str_voice_1500131_5 = "ดูสิ! ฉันเห็นสายรุ้งในคริสตัลน้ำแข็งล่ะ... นี่ไม่ใช่ปรากฎการณ์ที่เราเห็นได้ทุกวันนะ",
  str_voice_1500131_6 = "ไปกันเถอะ สโนว์แมน! ไปยังดินแดนแห่งความฝันสีสันสดใส ที่ซึ่งสายรุ้งและแสงตะวันรอเราอยู่",
  str_voice_1500131_7 = "ที่นอร์ธแลนด์มีคนเพ้อฝันอยู่เยอะเลยรู้ไหม แบบ... *อ่ะแฮ่ม* ฉันไม่ได้พูดอะไรเลยนะ!",
  str_voice_1500131_8 = "สนใจดาบใหญ่ของฉันเหรอ เอ้า ฉันจะเอาด้านหลังของมันให้ดูนะ มันก็น่าสนใจเหมือนกัน!",
  str_voice_1500131_9 = "ฉันมีเรื่องเล่ามากมายเลย เรื่องเล่าของคริสตัลน้ำแข็ง เรื่องเล่าของเกล็ดน้ำแข็ง สัญญากับฉันสิว่าเธอจะเก็บเป็นความลับแล้วฉันจะเล่าให้ฟัง",
  str_voice_1500131_10 = "ตอนนี้เรามีเวลาพักผ่อนมากขึ้น อยากเล่นคริสตัลน้ำแข็งกับฉันไหม อย่าลืมทำตัวให้อบอุ่นตลอดเวลานะ!",
  str_voice_1500131_11 = "เหมือนจุดไฟท่อนไม้เพื่อใช้งานเล็ก ๆ น้อย ๆ แต่ฉันก็ไม่ว่าอะไรหรอก ฉันจะคอยจับตาดูว่าเธอจะตั้งใจปกป้องสิ่งแวดล้อมไหม!",
  str_voice_1500131_12 = "อุปกรณ์ตรงนี้กันน้ำหรือเปล่า อยากให้ฉันทำเป็นน้ำแข็งให้เธอคนเดียวเลยไหม",
  str_voice_1500131_13 = "ฉันขอเล่นกับคริสตัลน้ำแข็งได้ไหม ขอแค่ก้อนเล็ก ๆ ก็พอ ฉันสัญญาว่าจะไม่สร้างปัญหาเลย!",
  str_voice_1500131_14 = "ดูสิเรือน้ำแข็ง ต้นสนน้ำแข็ง และร่างย่อน้ำแข็งของ...เธอ!",
  str_voice_1500131_15 = "สุขสันต์วันเกิด และดาว 900 ดวง จากฉันให้เธอ มีความสุขนะ",
  str_voice_1500131_16 = "โย่! ไปผจญภัยบนน้ำแข็งเป็นไง เธอแบกกระเป๋าเป้ไปแล้วฉันจะพาเธอไปด้วย!",
  str_voice_1500131_17 = "อรุณสวัสดิ์! อรุณสวัสดิ์! เช้านี้รู้สึกยังไงบ้าง ฉันรู้สึกดีเลยละ",
  str_voice_1500131_18 = "มาเร็ว! เธอมาตรงเวลาเลย! มาเต้นกับสโนว์แมนตัวจิ๋วหน่อย!",
  str_voice_1500131_19 = "เราทำกองไฟขึ้นมาแล้วกอดก่ายกันได้นะ ฉันจะเล่าเรื่องให้ฟังเรื่องหนึ่ง แล้วเธอก็เล่าอีกเรื่อง",
  str_voice_1500131_20 = "ฉันจำสายรุ้งโค้งและฝนที่ตกลงมาได้เหมือนกับดินแดนที่นุ่มนิ่มเลย!",
  str_voice_1500131_21 = "จากนี้ไปฉันจะได้เห็นสถานที่หลายแห่งเลย! ที่แรกก็เมืองเมฆา จากนั้นก็เมืองใต้ดิน!",
  str_voice_1500131_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง!",
  str_voice_1500131_23 = "พวกสารเลวที่ทำลายสิ่งแวดล้อมน่ะให้อภัยไม่ได้! อย่ากลัวไปเลย! ฉันไม่ปล่อยให้พวกนั้นทำร้ายเธอหรอก!",
  str_voice_1500131_24 = "เคยได้ยินเรื่องราวของลูอิสไหม พวกนั้นสุดยอดไปเลย แถมยังพูดถูกต้องเยอะด้วย!",
  str_voice_1500131_25 = "ทุกครั้งที่ฉันเต้นกับสโนว์แมนจิ๋วของฉัน ฉันรู้สึกได้ว่านางอิจฉานิดหน่อย",
  str_voice_1500131_26 = "ฉันชอบช่วยเหลือคนและฉันชอบทุกสิ่งที่เปล่งประกายระยิบระยับ! ฉันก็เป็นแค่เด็กผู้หญิงธรรมดาอ่ะ",
  str_voice_1500131_27 = "ฉันไม่ได้ไม่ชอบอะไรหรอกแต่ฉันทนการกระทำที่ทำลายสิ่งแวดล้อมไม่ได้! พวกนั้นต้องถูกสั่งสอนให้รู้สำนึก!",
  str_voice_1500131_28 = "ที่นี่เป็นบ้านเธอไม่ใช่เหรอ ฉันรู้สึกได้ถึง... ความโหยหาและความหวังของเธอ...",
  str_voice_1500131_29 = "ฟังให้ดี ต้นสนคือสิ่งสำคัญต่อนอร์ธแลนด์เพราะว่าพวกมันช่วยยับยั้งพายุหิมะ... แต่สำคัญที่สุดคือเวทมนตร์ขององค์ราชินี...",
  str_voice_1500131_30 = "โอ้! ฉันชอบนะ เอาอีก เอาอีก",
  str_voice_1500131_31 = "งานเลี้ยงแห่งหิมะและเวทมนตร์",
  str_voice_1500131_32 = "คริสตัลน้ำแข็งจงเบ่งบาน!",
  str_voice_1500131_33 = "ปล่อยให้คริสตัลน้ำแข็งเปล่งประกายสว่างไสวไปทั่วทั้งกาแลกซีเลย!",
  str_voice_1500131_34 = "ออกไปผจญภัยเหรอ",
  str_voice_1500131_35 = "แช่แข็งพวกมันให้หมด!",
  str_voice_1500131_36 = "เพื่อธรรมชาติผู้ให้กำเนิด!",
  str_voice_1500131_37 = "เอลฟ์แห่งหิมะและสายลม!",
  str_voice_1500131_38 = "โนอาห์มาแล้ว!",
  str_voice_1500131_39 = "สายลมทิศเหนือ!",
  str_voice_1500131_40 = "หิมะทิ่มแทง!",
  str_voice_1500131_41 = "การผจญภัยครั้งใหม่ที่ยิ่งใหญ่! ไปกันเถอะ!",
  str_voice_1500131_42 = "เราทำงานด้วยกันได้ดี!",
  str_voice_1500131_43 = "บ้าจริง... ไม่มีโอกาสได้ใช้บุปผาน้ำแข็งเฉลิมฉลองเลย...",
  str_voice_1500131_44 = "ดวงดาวน้ำแข็งเปล่งประกาย ฉันล่ะสงสัยจริง ๆ ว่าเธอเป็นใคร!",
  str_voice_1500131_45 = "ขอบคุณนะ... แต่แค่นี้เองเหรอ? ไม่มีอะไรน่าสนใจแล้วเหรอ?",
  str_voice_1500131_46 = "อู้! ฉันชอบนะ! ฉันคิดว่าราชินีก็คงชอบเหมือนกัน!",
  str_voice_1500131_47 = "ขอบใจนะ! ฉันจะทะนุถนอมของขวัญทุกชิ้น ไม่ว่าจะโบราณคร่ำครึแค่ไหน ตราบใดที่เธอเป็นคนให้",
  str_voice_1500131_48 = "ชอบสุด ๆ ไปเลย! พูดเท่าไหร่ก็คงพรรณนาไม่ได้ว่าฉันชอบแค่ไหน",
  str_voice_1500131_49 = "ราชินีตรัสว่าฉันเริ่มท่องเที่ยวได้แล้ว ฉันก็เลยแบกกระเป๋าเป้ออกไปแล้วก็พบผู้คนมากมายขณะเดินทาง",
  str_voice_1500131_50 = "เมื่อเนิ่นนานมาแล้ว ผู้คนมากมายได้จากไป วันนั้น เดือนนั้น และปีนั้นท่ามกลางสายรุ้ง",
  str_voice_1500131_51 = "การเดินทางมีแต่อิสระ ความฝัน รอยยิ้ม และสัญญาที่ฉันทำไว้กับทุกคนที่ฉันจดจำไว้ในใจฉันเสมอ",
  str_voice_1500131_52 = "Alchemy Stars!",
  str_voice_1500131_53 = "เพื่อนแสนงดงามของฉัน!",
  str_voice_1500131_54 = "วันใหม่เริ่มขึ้นแล้ว!",
  str_voice_1500131_55 = "สวัสดียามบ่าย! อยากไปผจญภัยกับฉันไหม",
  str_voice_1500131_56 = "เธอพร้อมหรือยัง",
  str_voice_1500131_57 = "มาเถอะพวกเราไปเที่ยวด้วยกันในปีใหม่ที่จะมาถึงนี้!",
  str_voice_1400611_1 = "อารมณ์ของออโรเรียนมหัศจรรย์มาก พวกมันเหมือนเอล์ฟที่มีร่างกายจริง",
  str_voice_1400611_2 = "อยากเรียนรู้วิธีควบคุมอารมณ์เหรอ ไม่จำเป็นหรอก! เธอมีฉันอยู่นี่",
  str_voice_1400611_3 = "เปิดเผยและเป็นตัวของตัวเองเลย ฉันจะสนับสนุนเธอเอง บางครั้งเธอก็ดื้อด้านเหมือนเด็กนั่นเลย...",
  str_voice_1400611_4 = "ยิ่งเราวิจัยเรื่องนั้นต่อไป บางทีเราอาจช่วยเด็กนั่นได้สักวัน...",
  str_voice_1400611_5 = "เอล์ฟไม่ใช่ใช้งานได้แค่ในการต่อสู้แต่ยังช่วยเรารักษาบาดแผลทางจิตใจได้ด้วย...",
  str_voice_1400611_6 = "ขอโทษทีนะ... บางครั้งฉันก็ต้องระบายอารมณ์บ้าง ฉันจะพยายามไม่สร้างปัญหาให้เธอมากนัก",
  str_voice_1400611_7 = "เฮ้! วันนี้อยากเล่าอะไรใหม่ ๆ ให้ฉันฟังไหม ฉันอยู่ตรงนี้เสมอล่ะ",
  str_voice_1400611_8 = "พูดสิ่งที่อยู่ในใจออกมาก็พอ ฉันหาเวลามาให้เธอได้เสมอเพราะมันเป็นงานของฉันน่ะ",
  str_voice_1400611_9 = "มาตรงนี้สิ ฉันสัมผัสได้ถึงอารมณ์ก่อเกิดปัญหาของเธอได้นิดหน่อย อยากให้ลูบหัวไหม",
  str_voice_1400611_10 = "มีแค่เส้นบาง ๆ ที่กั้นระหว่างรู้สึกผ่อนคลายกับความเบื่อเท่านั้น...",
  str_voice_1400611_11 = "ได้เวลาเริ่มช่วงปรึกษาแล้วเหรอ มาสิ มานั่งคุยกันเถอะ",
  str_voice_1400611_12 = "ยินดีต้อนรับกลับมา ผู้นำทาง! ถามฉันได้ตามสบายทุกอย่างเลย!",
  str_voice_1400611_13 = "สวัสดี! อยากคุยไหม",
  str_voice_1400611_14 = "ถ้าเธอรู้สึกย่ำแย่ ก็มาหาฉันได้ตลอดเวลานะ!",
  str_voice_1400611_15 = "สุขสันต์วันเกิด! วันนี้เป็นวันที่สุขสันต์จริง ๆ",
  str_voice_1400611_16 = "โคลอสซัสมีความมั่นคงทางอารมณ์นะ ให้ฉันจัดการเอง! ไม่มีปัญหาจ้ะ",
  str_voice_1400611_17 = "เธอดูดีนะ! หลับสบายมาละสิ",
  str_voice_1400611_18 = "อารมณ์ด้านลบก่อตัวขึ้นเมื่อเธอทำงานมากเกินไป ไปพักสักหน่อยให้อารมณ์ดีขึ้นเถอะ",
  str_voice_1400611_19 = "ถ้าเธอนอนไม่หลับก็มาคุยกับฉันได้เลย!",
  str_voice_1400611_20 = "คนอื่นอาจคิดว่าชีวิตในเมืองใต้ดินของอิลลูมินาดูตึงเครียด แต่อันที่จริงมันเป็นระเบียบเรียบร้อยมาก!",
  str_voice_1400611_21 = "ว่ากันว่าลูโมโพลิสมีวิธีการแก้ไขปัญหาทางอารมณ์แบบเฉพาะตัว ฉันสงสัยจังว่าเป็นแค่ข่าวลือหรือเปล่า",
  str_voice_1400611_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1400611_23 = "อิคลิพไซท์เป็นพวกขี้ขลาด! พวกมันมีแต่ความโกรธเคืองมุ่งร้ายเท่านั้น!",
  str_voice_1400611_24 = "ผู้อำนวยการกรอนรูรู้อะไรมากมายเลย ถึงขั้นศึกษาจิตวิทยาเลยนะ",
  str_voice_1400611_25 = "ไวท์ดวาร์ฟน่ารักมากเลย! เขาอาจจะแก่กว่าฉันแต่เขามีหัวใจเหมือนเด็กจริง ๆ!",
  str_voice_1400611_26 = "ฉันชอบฟัง โดยเฉพาะเวลาคนอื่นมาปรับทุกข์กับฉัน",
  str_voice_1400611_27 = "อารมณ์ด้านลบไม่ดีต่อสุขภาพก็เลยต้องหาทางระบายมันออกมา!",
  str_voice_1400611_28 = "โคลอสซัสก็มีอารมณ์เหมือนกัน ฉันต้องเพ่งสมาธิแล้วฟัง",
  str_voice_1400611_29 = "ไงจ๊ะ! ฉันคือแชนดรา เซการ์ นักจิตวิทยาของทีมและผู้เยียวยาความรู้สึก ยินดีที่ได้รู้จักนะ",
  str_voice_1400611_30 = "อารมณ์รุนแรงขึ้นแล้ว!",
  str_voice_1400611_31 = "ช่วยเหลือกันเพื่อจะได้เติมโตร่วมกัน!",
  str_voice_1400611_32 = "เธอรู้วิธีฝึกฝนพันธมิตรจริง ๆ ด้วยล่ะ",
  str_voice_1400611_33 = "ปลดปล่อยอารมณ์ของเธอออกมา! ปล่อยให้เบ่งบานเหมือนดอกไม้ไฟ!",
  str_voice_1400611_34 = "ยินดีที่ได้รู้จัก!",
  str_voice_1400611_35 = "รวบรวมอารมณ์ไว้เต็มที่แล้ว!",
  str_voice_1400611_36 = "มันเกิดขึ้นแล้ว! เกิดขึ้นแล้วล่ะ!",
  str_voice_1400611_37 = "ปลดปล่อยจิตวิญญาณของฉัน!",
  str_voice_1400611_38 = "เปลวไฟจิตวิญญาณ เตรียมตัว!",
  str_voice_1400611_39 = "ลองลิ้มรสดูสักครั้งเถอะ!",
  str_voice_1400611_40 = "อารมณ์ด้านมืด! จงปลดปล่อย!",
  str_voice_1400611_41 = "ขอทุกคนจงมีอารมณ์ดี!",
  str_voice_1400611_42 = "มันคือกลิ่นชัยชนะอันหอมหวาน!",
  str_voice_1400611_43 = "เธอปล่อยอารมณ์ด้านลบใส่ฉันได้เลยนะ!",
  str_voice_1400611_44 = "มีอะไรกวนใจอยู่เหรอ ฉันขอรับไปเก็บไว้แทนเธอแล้วกัน!",
  str_voice_1400611_45 = "เธอใจดีจังเลย! ขอบใจนะ!",
  str_voice_1400611_46 = "ฉันชอบมากเลย! เธอน่ารักจัง!",
  str_voice_1400611_47 = "เธอชอบให้ของขวัญฉันจังใช่ไหม",
  str_voice_1400611_48 = "ความสุขของฉันเอ่อล้นแล้ว ฮิ ๆ!",
  str_voice_1400611_49 = "ถึงเราจะมีอดีตอันมืดมนและหมองมัว แต่เราจะรับมุมมองด้านลบต่อชีวิตแบบนั้นไปตลอดไม่ได้หรอก ว่าไหม",
  str_voice_1400611_50 = "คุณกรอนรูดูแลฉันดีจริง ๆ และถ้านางไม่ได้สนับสนุนฉัน งานวิจัยของฉันก็คงไม่ได้เป็นไปอย่างราบรื่นหรอก ฉันได้รับพรให้มีเพื่อนที่แสนวิเศษที่สุด",
  str_voice_1400611_51 = "บัดนี้ทุกคนในอิลลูมินาคือครอบครัวฉัน รวมถึงเธอด้วย ผู้นำทาง! หวังว่าฉันจะสร้างอารมณ์ที่แสนวิเศษมากกกกไปด้วยกันได้นะ!",
  str_voice_1400611_52 = "Alchemy Stars!",
  str_voice_1400611_53 = "เฮ้ เธอ!",
  str_voice_1400611_54 = "อรุณสวัสดิ์!",
  str_voice_1400611_55 = "สวัสดียามบ่าย!",
  str_voice_1400611_56 = "สายัณห์สวัสดิ์!",
  str_voice_1400611_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1500361_1 = "เธอดูคุยกับพวกมันได้นะ... สุดท้ายแล้วคนมากมายก็จะโกรธน่ะ อย่าถือสาเลย ไม่มีอะไรหรอก",
  str_voice_1500361_2 = "พูดสิ่งที่อยากพูดสิ ฉันฟังอยู่ ก่อนบอสจะกลับมา ฉันมีเวลามากมายบนโลกใบนี้ไว้เพื่อแกล้งทำเป็นฟังเธอได้",
  str_voice_1500361_3 = "การดำรงอยู่นั้นไร้ความหมาย โดยเฉพาะเมื่อเธอเข้าใจความหมายของมัน เธอไม่เข้าใจเหรอ ก็ไม่แปลก เพราะแม้แต่บอสก็ไม่เข้าใจเหมือนกัน",
  str_voice_1500361_4 = "ก็เหมือนที่เงาทาบทับกัน ความมืดรวมตัวกันแล้วเข้มข้นมากขึ้น... สิ่งนั้นที่ถูกตัดออกแล้วฟื้นฟูขึ้นใหม่กำลังจะล่มสลายลง เธอไม่จำเป็นต้องรู้เรื่องนี้หรอก",
  str_voice_1500361_5 = "ไม่ว่าจะเป็นสุนัขล่าเนื้อหรือหมาป่า ไม่ว่ามันจะเป็นเงาหรือของจริง เธอก็ไม่เห็นต้องไปสนใจเลย... แค่มองมันก็พอ",
  str_voice_1500361_6 = "เห็นพวกมันไหม มันทั้งสวยงาม เงียบงัน และอยู่ทั่วทุกที่ ที่อยู่ข้างหลังเธอก็เหมือนกันแต่ก็แตกต่างโดยสิ้นเชิงด้วย",
  str_voice_1500361_7 = "เธอไม่มีอะไรต้องห่วงหรอกถ้าสงสัยเรื่องความสามารถของฉันน่ะนะ ฉันมีสิ่งสำคัญที่ต้องทำมากกว่าใช้เงาจัดการเธอ",
  str_voice_1500361_8 = "หืม... ฉันว่าฉันเริ่มจะชื่นชมเธอแล้วล่ะ รู้ไหมว่าตอนนี้เงาเธอมีกลิ่นแล้วนะ อย่ามายุ่งกับฉันเชียว ฉันไม่อยากได้กลิ่นนั้น",
  str_voice_1500361_9 = "ฉันไม่อยากยอมรับนะแต่เธอคล้ายพี่ชายมากเลย เธอทั้งคู่ต่างเป็นผู้บังคับเงาและเดินในเงาอย่างอิสระบนโลกที่มีแสงสว่างและความมืด",
  str_voice_1500361_10 = "ว้าว หืม ช่างเถอะ... ฉันเบื่อจังเลย ใครก็ได้ช่วยมาปิดฉากทุกอย่างทีได้ไหม",
  str_voice_1500361_11 = "ถ้าเป็นไปได้ก็กรุณาไปหาคนอื่นมาแทน ขนาดสุนัขล่าเนื้อของฉันยังปฏิเสธไม่ยอมอยู่ที่นี่เลย",
  str_voice_1500361_12 = "ทีนี้อะไรอีกล่ะ เธอมาที่นี่เพื่ออะไรบางอย่างใช่ไหม",
  str_voice_1500361_13 = "ทีนี้น่าเบื่อกว่าที่ฉันคิดว่านะ... เธอเป็นคนคุมที่นี่ไม่ใช่หรือไง ทำอะไรสักอย่างสิ",
  str_voice_1500361_14 = "ออกไปให้พ้น... เงาของฉันรู้สึกร้อนรนใจแล้วฉันก็ไม่สนด้วยถ้าพวกมันกัดเธอ",
  str_voice_1500361_15 = "โธ่ น่ารำคาญชะมัด... ไร้สาระเป็นบ้า บอกฉันมาซิว่าเธอต้องการอะไร",
  str_voice_1500361_16 = "อ้าว กลับมาแล้วเหรอ นึกว่าเธอหายไปแล้วเสียอีก",
  str_voice_1500361_17 = "เธอขยันแล้วไงเหรอ? ก็ไม่เกี่ยวอะไรกับฉันนี่...",
  str_voice_1500361_18 = "จะออกไปข้างนอกหรือเปล่า เร่งมือเลยแล้วก็เลิกเอ้อระเหยสักที",
  str_voice_1500361_19 = "ทำไมยังไม่นอนทั้ง ๆ ที่สุนัขล่าเนื้อของฉันหลับแล้วล่ะ เอาเถอะ... ฉันไม่ได้รอเธอหรอก... เธอจะทำอะไรได้อีก",
  str_voice_1500361_20 = "มีช่วงเวลาที่คนแบบฉันเหมาะกับอัมบราตันเท่านั้น งั้นตอนนี้คนแบบฉันก็ควรอยู่ในอัมบราตันสินะ",
  str_voice_1500361_21 = "ลูโมโพลิส... ใครก็ตามที่อยากไปที่นั่นก็ไปได้แต่ฉันไม่สนใจหรอก",
  str_voice_1500361_22 = "ชิ พวกเงานั่นคอยเฝ้าดูเธออยู่ตลอด",
  str_voice_1500361_23 = "อิคลิพไซท์เหรอ ฉันต้องสนใจพวกมันด้วยเหรอ เงาของฉันรุมล้อมพวกมัน กลืนกินพวกมันจนตาย จบบริบูรณ์",
  str_voice_1500361_24 = "ไม่รู้ไม่สนหรอก ตัวที่อยู่ในอัมบราตันคือหมึก สิ่งที่ควรจะสูญพันธุ์ไปเมื่อนานมาแล้ว",
  str_voice_1500361_25 = "ชิ ไม่รู้ทำไมหนอนตัวยาวต้องกระปรี้กระเปร่าทุกวันด้วย...",
  str_voice_1500361_26 = "ของที่ชอบเหรอ หืม... อาหารรสเผ็ด สุนัขล่าเนื้อ และไม่มีใครมากวนใจฉัน",
  str_voice_1500361_27 = "ฉันไม่ชอบคนที่คิดว่ารู้ดีทุกอย่าง",
  str_voice_1500361_28 = "นี่บ้านของเธอเหรอ ไม่สำคัญหรอก ฉันเคยนอนค้างคืนที่บ้านคนอื่นมาก่อนหน้านี้แล้ว",
  str_voice_1500361_29 = "ฉันไม่คิดว่าเธอจะหาฉันเจอ การแนะนำตัวนี่มันน่ารำคาญชะมัดเลย อ่านนี่เอาเองแล้วกัน",
  str_voice_1500361_30 = "ก็ได้ เธอได้รับการยอมรับแล้ว",
  str_voice_1500361_31 = "พวกนั้นรวมตัวกันที่อีกฟากฝั่งของแสงสว่าง",
  str_voice_1500361_32 = "พวกนั้นจู่โจมกะทันหันเงียบ ๆ",
  str_voice_1500361_33 = "กลืนกินพวกที่เสพติดกับความพึงพอใจอันจอมปลอมซะ!",
  str_voice_1500361_34 = "ฟังฉันนะ ไปหาคนอื่นเถอะ",
  str_voice_1500361_35 = "ฉันคือเจ้านายของเธอ!",
  str_voice_1500361_36 = "ยินดีต้อนรับสู่สีสันแห่งความตาย",
  str_voice_1500361_37 = "แสงสว่างสาดกระจาย!",
  str_voice_1500361_38 = "ฉีกแสงสว่างเป็นส่วน ๆ!!",
  str_voice_1500361_39 = "ฉีก!",
  str_voice_1500361_40 = "เขมือบ!",
  str_voice_1500361_41 = "กัปตัน เอาจริงน่ะ?",
  str_voice_1500361_42 = "พวกนั้นถูกเรียกว่าคนอ่อนแอ",
  str_voice_1500361_43 = "เธอหงุดหงิดเหรอ ขอโทษนะ แต่ฉันไม่สนหรอก",
  str_voice_1500361_44 = "เรื่องมากชะมัด... ยอมแพ้ซะเถอะ ฉันไม่สนอะไรหรอก",
  str_voice_1500361_45 = "โอ้ ว้าว ของขวัญ... ฉันอยากได้มาก \"จริง ๆ\"...",
  str_voice_1500361_46 = "...ฮ่า! เธอเดาถูกงั้นเหรอ ฉันตั้งตาคอยเจ้านี่อยู่เลย",
  str_voice_1500361_47 = "เหอะ ก็ได้ ฉันรับไว้เอง โอ้ มีความสุขชะมัด",
  str_voice_1500361_48 = "เธอรู้ว่าฉันต้องการอะไรเหมือนเคย",
  str_voice_1500361_49 = "ทุกอย่างไม่สำคัญสำหรับฉันเลย อย่างเสื้อผ้าและญาติมิตร ไม่เร็วก็ช้าพวกนั้นก็ต้องจากไป อย่ามาเถียงกับฉันเลยเพราะฉันพูดถูก",
  str_voice_1500361_50 = "พันธะน่ะตลกสิ้นดีเลยละ คนที่อยากให้เธอไล่ตามอะไรบางอย่างผิดธรรมชาติยัดความคิดนี้ใส่หัวเธอแล้วกักขังเธอไว้ในแนวคิดแบบนั้น ขอโทษทีนะแต่ฉันไม่เชื่อหรอก",
  str_voice_1500361_51 = "ฉันจะไม่ขีดฆ่าความเป็นไปได้ที่ฉันจะลงเอยอยู่ในสถานการณ์อันดาษดื่นทั่วไปสักวันหนึ่ง แต่มันก็ไม่ได้มีแนวโน้มแบบนั้น คอยดูไปเถอะ เอกสารก็มีเท่านั้นแหละ เลิกเคาะสักที มันมีแค่นั้น โธ่เอ๊ย!",
  str_voice_1500361_52 = "Alchemy Stars",
  str_voice_1500361_53 = "สวัสดี เธออยู่ไหม",
  str_voice_1500361_54 = "ขนาดสุนัขล่าเนื้อของฉันยังตื่นแล้วเลย",
  str_voice_1500361_55 = "ฉันต้องการให้เธอช่วยบางอย่าง",
  str_voice_1500361_56 = "หลับเหรอ ฉันจะรออีกสองนาที",
  str_voice_1500361_57 = "เชอะ ปีใหม่แล้วไงเหรอ",
  str_voice_1500121_1 = "เฮ้! ฉันไม่ได้แค่สอนคนตลอดเวลานะ ฉันสามารถคุยกับเธอได้ทั้งคืนด้วย! เธอว่าไงล่ะ ผู้ผดุงความยุติธรรมก็มีด้านที่เป็นมิตรด้วยนะ",
  str_voice_1500121_2 = "นี่คือบททดสอบจากอิลลูมินาอันเจิดจำรัส มันน่าปวดหัวจริง ๆ ที่ฉันอยากบอกก็คือ โลกนี้จะเป็นยังไงกันนะถ้าไม่มีคนอย่างฉัน!",
  str_voice_1500121_3 = "ฉันเห็นความยุติธรรมในใจเธอแล้ว มันเปล่งประกายสว่างเชียว อิลลูมินาต้องการคนอย่างเธอ เข้าใจที่ฉันพูดไหม",
  str_voice_1500121_4 = "ถ้าเธอคิดว่ามันเป็นแค่สโลแกนที่ฉันคอยตะโกนก็ผิดมหันต์แล้ว นี่เป็นหลักความเชื่อของฉันที่เหมือนเป็นแนวคิดจวบจนถึงวันที่ฉันตายน่ะ",
  str_voice_1500121_5 = "งดงามมาก... ถ้าเป็นอย่างนี้ต่อไป ฉันจะเหนือกว่าจอมทัพในสามวันแน่! ฉันจะช่วยเธอไม่ให้ขายหน้าเมื่อเกิดเรื่องยังไงนะ...",
  str_voice_1500121_6 = "ฉันต้องรอดเพื่อให้ทุกคนได้ยินเสียงอันทรงพลังกึกก้องในหัวใจของพวกเขา! สหายของเรา เส้นทางสว่างไสวอยู่เบื้องหน้าแล้ว จงเชื่อในความยุติธรรม",
  str_voice_1500121_7 = "ไม่จำเป็นต้องขอบคุณฉันแล้วเพราะเพื่อนควรต้องทำแบบนี้! ฉันหวังด้วยว่าเธอจะดูแลทุกคนในอิลลูมินาเหมือนเป็นครอบครัวเดียวกัน",
  str_voice_1500121_8 = "ไม่จำเป็นต้องกลัว ตราบใดที่เป็นคนยุติธรรม ยืนเคียงข้างฉันแล้วปล่อยให้อิลลูมินาเฉิดฉายลงบนตัวเธอ",
  str_voice_1500121_9 = "ถึงแม้ว่าเราจะไม่มีที่ให้อาศัยอยู่หรือไม่มีใครเข้าใจเรา เราก็ต้องยึดมั่นในศรัทธาต่อไป ยังไงฉันก็เชื่อว่าเธอเป็นคนที่เข้าใจอยู่แล้วล่ะ",
  str_voice_1500121_10 = "เฮ้ อยู่หรือเปล่า? นี่! ความยุติธรรมต้องการเธอนะ หรือว่าเธอซ่อนตัวอยู่ในมุมมืด ทำอะไรที่น่าอายอยู่หรือยังไง?",
  str_voice_1500121_11 = "เข้าใจแล้ว! เธออยากให้ฉันสลักคำว่า \"ยุติธรรม\" ลงบนหน้าหลักใช่ไหม ฉันจะเริ่มแล้วนะ!",
  str_voice_1500121_12 = "หมวกนี้เจ๋งเกินกว่าจะบรรยายได้นะ ว่าไหม! สหายร่วมรบจากตะวันออกไกลมอบให้ฉันมาน่ะ",
  str_voice_1500121_13 = "อาวุธของฉันยาวไปหน่อยเหรอ ไม่ต้องกังวลนะ ดาบนี้เคยตัดสินความยุติธรรมมาแล้ว และมันก็เหมาะกับฉันพอดีเลย",
  str_voice_1500121_14 = "เธอทรงพลังมากและเป็นพันธมิตรที่สมบูรณ์แบบสำหรับฉัน แต่เธอก็ตัดมันทิ้ง",
  str_voice_1500121_15 = "ฉันรู้ว่าเธอทำงานหนักมานาน ดังนั้นเพื่อที่จะฉลองหัวใจที่อิ่มเอมของเธอในวันนี้ สนุกตามที่เธอต้องการได้เลยนะ!",
  str_voice_1500121_16 = "ยินดีต้อนรับกลับมา สหายแห่งความยุติธรรม!",
  str_voice_1500121_17 = "อรุณสวัสดิ์! ฉันรอคอยเธอมาเนิ่นนานแล้ว อดใจรอเริ่มวันใหม่ไม่ได้แล้วสิ!",
  str_voice_1500121_18 = "ฉันรอคอยที่จะต้อนรับเธอกลับมาเสมอ ไม่ว่าเมื่อไหร่ก็ตาม สหายของฉัน!",
  str_voice_1500121_19 = "เยี่ยมยอด! ว่าแล้วว่าเธอจำคำพูดของฉันได้ เธอต้องมาเพื่อปรึกษาความยุติธรรมกับฉันทั้งคืนแน่นอน!",
  str_voice_1500121_20 = "ฉันจะทำทุกอย่างที่ทำได้เพื่อให้อิลลูมินาจงเจิดจำรัส! ฉันจะตั้งสติและคอยเฝ้าดูทุกอย่างตลอดเวลา",
  str_voice_1500121_21 = "ภายนอกดูเหมือนดี แต่ข้างในนั่นปีศาจชัด ๆ เราเห็นความหน้าซื่อใจคดของเมืองลอยนั่นได้ตั้งนานมาแล้ว",
  str_voice_1500121_22 = "ขออิลลูมินาจงเจิดจำรัส! จงปกป้องแกนน่อน!",
  str_voice_1500121_23 = "ฉันไม่ไว้ชีวิตคนที่ฝ่าฝืนความยุติธรรมหรืออิลลูมินาหรอกนะ! พวกมันจะต้องถูกกำจัด!",
  str_voice_1500121_24 = "แข็งแกร่ง ยุติธรรมและเชื่อมั่นในความยุติธรรม ไม่สงสัยเลยว่าไม่มีใครเหมาะที่จะนำอิลลูมินาไปมากกว่าจอมทัพแล้ว",
  str_voice_1500121_25 = "เธอช่วยให้ฉันเข้าใจว่าแม้แต่คนที่มาจากที่ห่างไกลก็ยังมีความยุติธรรมที่พวกเขายืนกรานสู้ น่าประทับใจนะ",
  str_voice_1500121_26 = "ผู้ผดุงความยุติธรรมต้องลงโทษผู้กระทำผิดและกำจัดความชั่วร้ายออกไป ฉันจะทำตามหน้าที่ของฉันและไขปัญหาของคนอื่น!",
  str_voice_1500121_27 = "สิ่งที่ฉันไม่ชอบเหรอ ไม่ต้องห่วง ฉันจะกำจัดทุกสิ่งที่ทำให้ฉันรังเกียจเอง!",
  str_voice_1500121_28 = "ฉันตำหนิโคลอสซัสก่อนฉันจะขึ้นมันมาเสียอีก แต่พอเธอมาอยู่ ทุกอย่างก็เปลี่ยนไปเลย!",
  str_voice_1500121_29 = "เธอดูเป็นคนดีนะ บางทีเราอาจสำรวจความเชื่อเกี่ยวกับความยุติธรรมแต่ละอย่างได้ ฉันหวังว่าจะไม่ต้องฆ่าเธอนะ...",
  str_voice_1500121_30 = "เกียรติยศอมตะ!",
  str_voice_1500121_31 = "รุ่งสางวันใหม่นำมาซึ่งพลังใหม่!",
  str_voice_1500121_32 = "ฉันเข้าไปใกล้จอมทัพมากขึ้นทุกทีแล้ว!",
  str_voice_1500121_33 = "มือเหล็กและดาบคม ไร้ที่ติ!",
  str_voice_1500121_34 = "ผดุงคุณธรรมและลงทัณฑ์ความชั่ว!",
  str_voice_1500121_35 = "เทวทัณฑ์ทิ่มแทงความมืดมิด...",
  str_voice_1500121_36 = "จงเสียใจกับการกระทำ!",
  str_voice_1500121_37 = "ถอยไป เจ้าพวกคนชั่ว!",
  str_voice_1500121_38 = "นี่เป็นโอกาสสุดท้ายที่เธอจะได้กล่าวคำบอกลาแล้ว!",
  str_voice_1500121_39 = "สำเร็จโทษ!",
  str_voice_1500121_40 = "ผดุงความยุติธรรมแล้ว!",
  str_voice_1500121_41 = "ได้เวลาของผู้ผดุงความยุติธรรม!",
  str_voice_1500121_42 = "ความยุติธรรมไม่เคยหายไป!",
  str_voice_1500121_43 = "อย่ามาห้ามฉัน! ฉันจะทำให้พวกนั้นตกต่ำไปพร้อมกับฉัน!",
  str_voice_1500121_44 = "เธอไม่ต้องขอบคุณฉันหรอก ฉันก็แค่ทำตามหน้าที่!",
  str_voice_1500121_45 = "โอ้ น่าสนใจอยู่นะเนี่ย ขอบคุณ",
  str_voice_1500121_46 = "อย่างกับอ่านใจฉันได้อย่างนั้นแหละ! สหายความยุติธรรมของฉันเป็นไปตามคาดเลย!",
  str_voice_1500121_47 = "ไม่ว่ามันจะมีค่าเท่าไหร่ และสำคัญเท่าไหร่ ก็ต้องขอขอบคุณด้วยนะ",
  str_voice_1500121_48 = "สหายของฉัน เธอให้ของขวัญที่มีความหมายกับฉันมากเลย!",
  str_voice_1500121_49 = "ถึงเธอจะต้องอยู่อย่างโดดเดี่ยว แต่ก็จงยึดมั่นในศรัทธาอย่าหวั่นไหว เพราะมันเป็นเสมือนธงและเสาหลัก เป็นดั่งแสงแห่งอิลลูมินาอันเจิดจำรัส",
  str_voice_1500121_50 = "ฉันมีชีวิตอยู่เพื่อทำลายความเสแสร้งและสิ่งสกปรกบนโลกใบนี้! ถึงไม่มีใครเข้าใจฉันเลยก็ไม่สำคัญหรอก",
  str_voice_1500121_51 = "ครอบครัวทิ้งฉันไปจริง ๆ แล้วมันยังไงเหรอ ฉันต้องแบกภาระอะไรงั้นเหรอ ไม่มีหรอก ฉันเลือกเองทั้งนั้นแหละ",
  str_voice_1500121_52 = "Alchemy Stars!",
  str_voice_1500121_53 = "สหายแห่งความยุติธรรม!",
  str_voice_1500121_54 = "แผนของวันเริ่มต้นด้วยยามเช้า!",
  str_voice_1500121_55 = "อย่าลืมระมัดระวังตัวยามบ่ายด้วยล่ะ!",
  str_voice_1500121_56 = "วันนี้ยังมีอะไรให้ทำอีกมากก่อนจะจบวัน!",
  str_voice_1500121_57 = "สุขสันต์วันปีใหม่! เราขอฉลองให้ความยุติธรรม!",
  str_voice_1500211_1 = "เมื่อบาดแผลทั้งหมดถูกกุหลาบแทงจนถลอกต่อเนื่องและสมานตัวแล้ว ความรู้สึกรักอันรุนแรงก็พุ่งออกมาจากร่างกายฉัน!",
  str_voice_1500211_2 = "ฉันรักเธอแต่ฉันรักเด็กนั่นมากกว่า นางเหมือนพุ่มดอกกุหลาบและฉันหวังให้นางโอบล้อมตัวฉันให้แน่นด้วยเถาวัลย์หนามแหลม ไม่มีวันทิ้งฉันไปไหน!!",
  str_voice_1500211_3 = "เราเล่นซ่อนแอบกันอยู่ อยากมาเล่นด้วยกันไหม เอ้อ เราขาดไปคนหนึ่งด้วย... อีกคน...\nพวกนั้นหลุดอ้อมกอดแห่งความรักของฉันไปเมื่อไหร่กัน เจ้าตัวน่ารัก…",
  str_voice_1500211_4 = "สวนแห่งความรักของฉันเติบโตขึ้นมาก ตกลงไปในตาข่ายแห่งความรักเหมือนผีเสื้อไล่ตามแสงไฟและไม่เคยจากไปไหน...",
  str_voice_1500211_5 = "ฉันเห็นความรักของฉันล่องลอยในเส้นใบของดอกไม้แต่ละดอก ฉันจะสร้างกรงที่บอบบางที่สุดให้พวกมัน เหมือนเด็กคนนั้นเลย",
  str_voice_1500211_6 = "มาอยู่กับฉันเถอะ และขอให้อย่าทรยศฉัน เราจะรอดอกไม้เบ่งบานไปด้วยกันในสวนอันอบอุ่นของฉันที่มีรั้วล้อมปกป้องอยู่!",
  str_voice_1500211_7 = "วันนี้อากาศดีนะ ขอจับมือได้ไหม ไม่เป็นไร แค่เดินเล่นรอบสวนน่ะ ฉันไม่วางกับดักเธอด้วยความรักอันหวานชื่นของฉันหรอก...",
  str_voice_1500211_8 = "รั้วของฉันเป็นตัวแทนของความรัก อ้อมกอดและการเสียสละ! นางไม่เข้าใจเจตนาของฉัน เธอเข้าใจไหม เธอเข้าใจใช่ไหม?!",
  str_voice_1500211_9 = "เป็นความรักที่แรงกล้าจริง ๆ! ฉันกลัวว่าเธอจะเป็นคนเดียวที่เข้าใจฉันในโลกใบนี้ เหมือนที่ภูเขาสูงและแม่น้ำไหลรินบรรจบเข้าหากันไง! เข้ามาใกล้กว่านี้สิ ได้เวลาแบ่งปันความลับกับเธอแล้ว...",
  str_voice_1500211_10 = "นางดูกระสับกระส่ายราวกับดอกไม้ป่าที่ขาดการดูแลที่เหมาะสม ฉันสงสัยว่ากรงขนาดเท่าไหร่จะเหมาะกับนางมากกว่า... หืม อ๋อ ฉันพูดกับตัวเองเฉย ๆ",
  str_voice_1500211_11 = "ได้เวลาทำสวนอีกแล้ว ฉันจะเปลี่ยนที่นี่ให้กลายเป็นดินแดนแห่งความปรารถนาที่ร่มรื่นและอากาศถ่ายเท...",
  str_voice_1500211_12 = "อ้าว มาแล้วเหรอ ไม่สงสัยเลยว่าทำไมฉันถึงรู้สึกลมพัดผ่านเมื่อกี้",
  str_voice_1500211_13 = "เธอมีกลิ่นดอกไม้ที่แตกต่างกับดอกไม้ของฉัน... เฉพาะตัวมากเลยละ",
  str_voice_1500211_14 = "ทำไมถึงดูลังเลอยู่ตลอดเวลาเลยล่ะ? เพราะรั้วของฉันไม่สบายมากพอเหรอ...? หา? ฉันคุยกับดอกไม้ของฉันน่ะ",
  str_voice_1500211_15 = "กรุณารับความรักของฉันในวันที่น่าจดจำแบบวันนี้ด้วยเถอะ! จะเป็นความรักที่เธอลืมไม่ลงเลย!",
  str_voice_1500211_16 = "ยินดีต้อนรับสู่สวนแห่งความรักของฉัน ฉันรอเธออยู่นะ",
  str_voice_1500211_17 = "เธอเอาน้ำค้างยามเช้ามาด้วยไหม ดอกไม้น่ารักของฉันอดใจรอที่จะเบ่งบานไม่ไหวแล้ว",
  str_voice_1500211_18 = "อ้าว ยินดีต้อนรับกลับมานะ! ว่าแล้วว่าเธอจะต้องกลับมาหาฉัน มาหาสวนอันอบอุ่นนี่...",
  str_voice_1500211_19 = "ฉันอิจฉาเธอนะ... ดอกไม้ของฉันมักจะไม่มีชีวิตชีวาตอนกลางคืนแต่เธอยังเบ่งบานอยู่เลย",
  str_voice_1500211_20 = "ไม่เลวสำหรับสวนนี้แต่ฉันว่าเด็กคนนั้นน่าจะมาที่นี่ด้วย...",
  str_voice_1500211_21 = "สวนลอยฟ้า สวนในทะเลทราย สวนในหิมะ... เด็กคนนั้นจะอยู่ที่ไหนกันนะ",
  str_voice_1500211_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1500211_23 = "ฉันต้องกำจัดวัชพืชพวกนั้นที่มายุ่มย่ามกับดอกไม้แสนน่ารักของฉันให้หมด...",
  str_voice_1500211_24 = "ฉันจะตามหานางแม้ว่าจะต้องท่องเที่ยวไปทั่วทุกมุมโลกก็ตาม แล้วฉันก็จะปกป้องนาง ดูแลให้นางปลอดภัย",
  str_voice_1500211_25 = "ถ้าเธออยากคุยเรื่องใครสักคนมากกว่าเรื่องเด็กคนนั้น... ฉันว่าเราคุยเรื่องเธอดีกว่า",
  str_voice_1500211_26 = "ดอกกุหลาบแห่งความปรารถนาอันแรงกล้า ฉันชอบไหมน่ะเหรอ ไม่... ไม่ชอบก็บ้าแล้ว!",
  str_voice_1500211_27 = "เอ๊ะ ขนาดเธอยังไม่ทนกับพวกมองไม่เห็น ไม่สนใจความรู้สึกคนอื่นเลย...",
  str_voice_1500211_28 = "ฉันรู้สึกว่าโคลอสซัสเต็มไปด้วยอารมณ์ของเธอ เหมือนดอกไม้ของฉันเลย",
  str_voice_1500211_29 = "เมล็ดที่น่ารักของฉัน ชาวสวนโจลาของเธออยู่นี่แล้ว พร้อมเบ่งบานด้วยความรักและเอาใจใส่ของฉันหรือยัง",
  str_voice_1500211_30 = "ช่างเป็นประสบการณ์ที่ล้ำค่ามาก!",
  str_voice_1500211_31 = "อาณาจักรแห่งรักเบ่งบานขึ้นแล้ว!",
  str_voice_1500211_32 = "ในที่สุดเหล่าแกะหลงทางก็กลับบ้านแล้ว!",
  str_voice_1500211_33 = "นี่แหละคือชีวิตที่วิเศษที่สุดแล้ว!!",
  str_voice_1500211_34 = "มาเถอะ ไปที่สวนนั้นกัน",
  str_voice_1500211_35 = "ความรักของฉันเอ่อล้นแล้ว",
  str_voice_1500211_36 = "โฮ่ ๆ ๆ!",
  str_voice_1500211_37 = "ฉันจะสละทุกอย่างให้เธอ",
  str_voice_1500211_38 = "ในนามของความรัก",
  str_voice_1500211_39 = "เติบโต!",
  str_voice_1500211_40 = "เบ่งบาน!",
  str_voice_1500211_41 = "นั่งเรียงกันเลยนะ ดอกไม้ที่รักของฉัน...",
  str_voice_1500211_42 = "ความรักที่แน่นแฟ้นของฉันจะไปถึงเธอในสักวัน",
  str_voice_1500211_43 = "นี่คือ... การโรยราเป็นอย่างนี้เองเหรอ...",
  str_voice_1500211_44 = "วันนี้อากาศดีนะ เธออยากไปเยี่ยมสวนของเราไหม",
  str_voice_1500211_45 = "น่าเสียดายที่ฉันต้องการความรักของเธอมากกว่านี้",
  str_voice_1500211_46 = "ว้าก! ธ-เธอไปเอาเจ้านี่มาจากไหน!",
  str_voice_1500211_47 = "การเห็นคุณค่านั้นยิ่งใหญ่กว่าความรัก ขอบคุณนะ",
  str_voice_1500211_48 = "โอ้ว! ฉันถูกโอบอุ้มด้วยความรักที่เอ่อล้นของเธอ!",
  str_voice_1500211_49 = "เห็นหรือเปล่า ในสวนที่งดงามของฉัน ดอกไม้ทุกดอกต่างมีชื่อของตัวเอง: คุณวิลเลียม คุณแมรี่... อืมม ฉันจะตั้งชื่อดอกถัดไปว่าอะไรดี",
  str_voice_1500211_50 = "ฉันพานพบกับความช็อก ความโกรธ และความเดียวดายมาแล้ว แต่ตอนนี้ฉันกลับเลิกคิดถึงนางไม่ได้เลย สิ่งเดียวที่ไม่เคยเปลี่ยนแปลงคือความรักนี้ แด่รักนิรันดร",
  str_voice_1500211_51 = "ฉันสร้างรังไข่ที่อบอุ่นและแสนวิเศษที่สุดให้นางไป นางจะตามกลิ่นหอมของความรักกลับบ้านเมื่อไหร่ก็ได้ แล้วฉันก็จะอ้าแขนกว้างต้อนรับนางโดยไม่สนใจอดีตเลย",
  str_voice_1500211_52 = "Alchemy และ Stars",
  str_voice_1500211_53 = "สวัสดี",
  str_voice_1500211_54 = "เช้าแล้วสินะ",
  str_voice_1500211_55 = "เธอก็ต้องมาอยู่แล้วใช่ไหมล่ะ",
  str_voice_1500211_56 = "ฉันคิดถึงเธอตอนกลางคืนตลอด...",
  str_voice_1500211_57 = "ผ่านไปอีกปีแล้ว แต่ความรักของฉันยังไม่จืดจาง",
  str_voice_1400171_1 = "สู้ครั้งต่อไปที่ไหนล่ะ ฉันจะวางแผนหนีเผื่อในกรณีที่เรารับมือความรุนแรงไม่ไหวก่อน!",
  str_voice_1400171_2 = "หืม ดูมีบางอย่างแปลก ๆ ซ่อนตัวเร็ว! ไม่งั้น...",
  str_voice_1400171_3 = "โฮ ๆ... ฉันถูกดุที่ไปค้นทั่่วกระท่อมอีกแล้ว... ฉันแค่ทำวิจัยวัสดุเก่า ๆ เผื่อไว้เท่านั้นเอง...",
  str_voice_1400171_4 = "ฉันกลับมาศึกษาการอำพรางแสงอีกครั้งแล้ว! ถ้ามีมันละก็ เราสามารถหนีจากศัตรูได้ในระยะประชิดเลยละ!",
  str_voice_1400171_5 = "ดูสิ! หัวขุดเจาะล่าสุดล่ะ ฟึบบ! แค่แตะมันฉันก็แทบจะได้กลิ่นดินที่ขุดขึ้นมาใหม่ ๆ แล้ว!",
  str_voice_1400171_6 = "ด้วยพลังขนาดนี้ มันจะเจาะทะลุพื้นดินเหมือนมีดร้อน ๆ ผ่าเนยเลยละ... อืมม... เนย... อาหย่อย...",
  str_voice_1400171_7 = "เธอไม่มีความคิดว่าอันตรายเลย การที่ฉันเน้นกับสมาชิกหน่วย วางแผน คาดเดา และคิดล่วงหน้าเป็นเรื่องสำคัญมากนะ!",
  str_voice_1400171_8 = "ฉันคิดถึงปู่มากเลย ท่านอาจจะยังปกป้องฉันอยู่ก็ได้ เพราะอย่างนั้นฉันเลยมักจะอยู่รอดปลอดภัยไร้อันตราย... หรือเพราะว่ากระต่ายอีกตัวกันนะ",
  str_voice_1400171_9 = "อย่าลืมเส้นทางหลบหนีที่ฉันเคยให้ดูล่ะ แพ้น่ะไม่เป็นไรหรอก ตราบใดที่เธอยังมีชีวิตอยู่ ไว้สู้ในวันอื่นก็ได้",
  str_voice_1400171_10 = "ตกลง เราจะใช้แผน E ละกัน ตอนนี้แผน F...",
  str_voice_1400171_11 = "เอาละ! ฉันจะไปยืนยันกับทางออกฉุกเฉินที่ใกล้ที่สุด!",
  str_voice_1400171_12 = "ส-เสียงอะไรน่ะ อ๋อ! เธอนี่เอง ขอบคุณสวรรค์ ฉันเกือบกระโดดออกจากหน้าต่างแล้วเชียว",
  str_voice_1400171_13 = "อุปกรณ์ที่ฉันสั่งไปจะมาส่งเมื่อไหร่เนี่ย ฉันคงต้องรออย่างเดียวสินะ... รออีก 5 นาที!",
  str_voice_1400171_14 = "ทุกครั้งที่อยู่กับเธอ ฉันรู้สึกปลอดภัย แต่ฉันวางแผนเส้นทางหลบหนีไว้แล้วแหละ!",
  str_voice_1400171_15 = "สุขสันต์วันเกิดนะ ฉันเตรียมงานฉลองไว้ให้เยอะเลยละ อยากฉลองแบบไหนดี เลือกเลย ตั้งแต่ A ถึง J",
  str_voice_1400171_16 = "เธอกลับมาแล้ว! ฉันคิดทางหนีของเราออกแล้ว... เอ๊ะ เราจะไม่หนีหรอกเหรอ?",
  str_voice_1400171_17 = "อรุณสวัสดิ์! มาคุยเรื่องแผนใหม่กันเถอะ อะไรสักอย่างที่ลงท้ายด้วย \"เส้นทาง\" น่ะ",
  str_voice_1400171_18 = "โว้ว! ยินดีต้อนรับกลับมานะ ฉันไม่ได้ทำอะไรน่าสงสัยเลย ไม่เลยสักนิด",
  str_voice_1400171_19 = "ยังไม่พักผ่อนอีกเหรอ นอนไม่หลับเหรอ รู้สึกไม่ปลอดภัยหรือยังไง ฉันขุดหลุมให้เธอได้นะ",
  str_voice_1400171_20 = "ถึงจะไม่มีใครชอบอยู่ใต้เดินก็เถอะ การได้วิ่งไปทั่วก็ยังเป็นสิ่งที่ดีเสมอ!",
  str_voice_1400171_21 = "ฉันได้ยินว่าทุกคนที่อิลลูมินาอาศัยอยู่ในถ้ำขนาดใหญ่ พวกนั้นต้องมีสว่านไฟฟ้าที่ทรงพลังมากแน่นอน!",
  str_voice_1400171_22 = "เกือบหนีไม่รอดแล้ว!",
  str_voice_1400171_23 = "พวกนั้นก็ยังทำให้ฉันกลัวแล้วฉันก็ยังรู้สึกว่าอยากหนี... แต่ตอนนี้ฉันยืนหยัดได้แล้ว!",
  str_voice_1400171_24 = "น่าอายจริง ๆ ที่ต้องบอกว่าฉันลืมหน้าตาเขาไปแล้วเพราะเขามักจะใส่หมวกตลอดเวลา",
  str_voice_1400171_25 = "เจ้าคนตัวเตี้ยนั่นเป็นคนดีอยู่นะ! เขาถึงขั้นช่วยฉันปรับหัวสว่านด้วย!",
  str_voice_1400171_26 = "ฉันชอบอุปกรณ์ขุดใหม่ ๆ หลุมใหม่ ๆ แล้วแผนหลบหนีใหม่ ๆ!",
  str_voice_1400171_27 = "พื้นที่แคบน่ากลัวนะ! มันจะไม่มีช่องเปิดกว้างได้ยังไง!",
  str_voice_1400171_28 = "โคลอสซัสเร็วมากและมหัศจรรย์มากกกกก! แล้ว... ฉันเริ่มขุดหลุมได้หรือยัง",
  str_voice_1400171_29 = "ฉันคือแรบบี้ ปรมาจารย์ด้านการหนี! อย่ากลัวสว่านขนาดใหญ่นี่ไปเลย มันเอาไว้ใช้สร้างทางหนีของเราเท่านั้น",
  str_voice_1400171_30 = "สว่านฉันทรงพลังยิ่งขึ้นแล้ว!",
  str_voice_1400171_31 = "กำลังขุดหลุมแล้ว!",
  str_voice_1400171_32 = "ไชโย! สว่านฉันได้รับการอัปเกรดแล้ว!",
  str_voice_1400171_33 = "ไม่ว่าจะที่ไหนก็ขุดทะลุทะลวงซะ!",
  str_voice_1400171_34 = "ฉันคอยระวังให้เธออยู่!",
  str_voice_1400171_35 = "พร้อมและสามารถ!",
  str_voice_1400171_36 = "กำลังรอคำสั่งเธออยู่!",
  str_voice_1400171_37 = "เธอหนีไม่พ้นหรอก!",
  str_voice_1400171_38 = "แกไม่มีทางหนีแล้ว!",
  str_voice_1400171_39 = "ยืนยันเส้นทาง!",
  str_voice_1400171_40 = "กำจัดสิ่งกีดขวางแล้ว!",
  str_voice_1400171_41 = "ปลอดภัยไว้ก่อนนะ ทุกคน!",
  str_voice_1400171_42 = "เธอหนีจากอาจารย์ผู้เชี่ยวชาญด้านการหนีไม่ได้หรอก!",
  str_voice_1400171_43 = "อย่าเพิ่งตื่นตูม! ตามฉันมา!",
  str_voice_1400171_44 = "ฉันจะบอกความลับให้...จริง ๆ แล้วฉันเตรียมเส้นทางหลบหนีลับไว้แล้วล่ะ",
  str_voice_1400171_45 = "หืมมมม... ขอคิดก่อนนะ... ฉันต้องใช้ยังไงเหรอ",
  str_voice_1400171_46 = "ให้ฉันเหรอ จริงน่ะ ขอบใจนะ!",
  str_voice_1400171_47 = "หืมม! หวังว่าจะใช้ประโยชน์จากมันได้นะ",
  str_voice_1400171_48 = "ตายแล้ว! ฉันอยากได้เจ้านั่นมาตลอดเลย!",
  str_voice_1400171_49 = "กฎการถอยทัพ: หนึ่ง รู้เหตุผลที่ถอยทัพ! สอง วิ่งให้ปราดเปรียวดุจสายลม! สาม ค่อยไปโวยวายกันทีหลัง!",
  str_voice_1400171_50 = "หัวหน้าเราแข็งแกร่งแล้วเราก็มีเพื่อนที่พึ่งพาได้มากมาย ดังนั้นฉันเลยไม่ต้องหนีตัวคนเดียวอีกแล้ว... ไว้ใจฉันเถอะ ฉันจะเฝ้าทางหนีเอง!",
  str_voice_1400171_51 = "ถ้าวิ่งไม่ได้งั้นเหรอ ฉันจะปกป้องเธอเหมือนที่ปู่ปกป้องฉันเลย แต่เธอต้องรอจนกว่าฉันจะสูงขึ้นกว่านี้หน่อยนะ",
  str_voice_1400171_52 = "Alchemy Stars!",
  str_voice_1400171_53 = "ก๊อก ๆ เธออยู่หรือเปล่า",
  str_voice_1400171_54 = "อรุณสวัสดิ์!",
  str_voice_1400171_55 = "อยากออกกำลังกายหน่อยไหม",
  str_voice_1400171_56 = "เธอพักผ่อนอยู่หรือเปล่า",
  str_voice_1400171_57 = "สุขสันต์ปีแห่งหลุม! เห็นที่ฉันทำไว้ตรงนั้นไหม",
  str_voice_1300491_1 = "เบื่อจัง ดวลกับฉันที บอส อะไรนะ จะบอกว่าสาว ๆ พวกนั้นอยากลองเหรอ ไม่ล่ะ ขอบใจ ฉันขอไม่สู้กับผู้หญิงดีกว่า",
  str_voice_1300491_2 = "อิคลิพไซท์ไม่มีอะไรให้กลัวหรอก ฉันฆ่าทุกตัวที่ฉันเห็นเกลี้ยง สมัยที่ฉันยังลำบากน่ะ ฉัน... เดี๋ยว เธอบอกว่าคราวหน้าจะส่งฉันไปสู้ที่แนวหน้าคนเดียวเหรอ",
  str_voice_1300491_3 = "ฉันเรียกเธอว่าบอสตลอด ไม่รู้เลยว่าอีสต์วานจะโมโหหรือเปล่า... ช่างเถอะ พวกเธอสองคนไปสู้ตัดสินเอาก็ได้",
  str_voice_1300491_4 = "มาเถอะ! คนที่ยังไม่เชื่อมาดวลมือเปล่ากับฉันได้นะ! อย่าร้องไห้แล้ววิ่งไปฟ้องแม่ก็แล้วกัน!",
  str_voice_1300491_5 = "ผู้คนมักจะคิดมากกับทุกอย่างเกินไป ความจริงเดียวบนโลกนี้คือไม่เธอล้มฉันได้ ฉันก็ล้มเธอได้ต่างหาก",
  str_voice_1300491_7 = "ไม่ต้องสนใจดาบใหญ่สองเล่มของฉันหรือหมวกเกราะเสือดาวหรอก ฉันกินได้ปกติและมันก็ไม่มาบังสายตาฉันด้วย ทีนี้เลิกถามคำถามชวนหงุดหงิดสักที!",
  str_voice_1300491_8 = "ดาบสองเล่มนี้ไม่ได้แย่ แต่เบาไปสำหรับฉัน เมื่อไหร่ฉันจะได้อาวุธที่ดีขึ้น คมขึ้น และแรงขึ้นล่ะบอส",
  str_voice_1300491_9 = "ชอบหมวกเกราะเสือดาวของฉันไหม เดิมทีมันไม่ใช่แบบนี้แต่ฉันตกแต่งเอาน่ะ โว้ว อย่าแตะนะ! แล้วก็อย่าถูมันด้วย",
  str_voice_1300491_10 = "ยืนไปเรื่อยแบบนี้น่าเบื่อชะมัด... มีใครหรืออะไรให้ฉันซ้อมไหม ถ้าเป็นอย่างนี้ต่อไป คนในกิลด์ต้องทิ้งเราไว้คลุกฝุ่นแน่!",
  str_voice_1300491_11 = "ฉันไม่มีปัญหากับการเฝ้าระวังหรอก แต่อย่าใช้คำว่า \"นั่งเฝ้าบ้าน\" เชียว พอสักที!",
  str_voice_1300491_12 = "ฉันจะบอกอีกครั้งนะว่าฉันไม่ใช่แมวตัวใหญ่ เลิกพยายามมาพิงฉันตลอดเวลาได้แล้ว!",
  str_voice_1300491_13 = "ความรุนแรงเป็นชีวิตของฉัน ฉันไม่มีทางรอดชีวิตในอัมบราตันได้ถ้าไม่มีมัน",
  str_voice_1300491_14 = "คำพูดของบอสเป็นคำสั่งของฉัน โอ้ ฉันไม่ได้หมายถึงเธอนะ ฉันพูดถึงบอสตอนที่อยู่ในอัมบราตันน่ะ",
  str_voice_1300491_15 = "อยากให้ฉันตัดเค้กวันเกิดให้เหรอ",
  str_voice_1300491_16 = "ไหน ๆ เราก็ไม่ได้ทำอะไรแล้ว มาฝึกดาบกันหน่อยเป็นไง",
  str_voice_1300491_17 = "ฉันว่าเราควรล้างหมวกเกราะเสือดาวนี่บ้างเป็นครั้งคราว แต่ฉันสงสัยจังว่าจะมีปัญหาหรือเปล่า",
  str_voice_1300491_18 = "ฉันไม่รู้ว่าเห็นภาพลวงตาหรือเปล่าแต่รู้สึกกระปรี้กระเปร่าขึ้น!",
  str_voice_1300491_19 = "เหมียว... จู่ ๆ ก็รู้สึกว่าอยากร้องแบบนั้นน่ะ",
  str_voice_1300491_20 = "ถึงอัมบราตันจะแย่แค่ไหน แต่มันก็คือบ้านเพียงแห่งเดียวของหลาย ๆ คน",
  str_voice_1300491_21 = "ฉันคงเข้าแก๊งเรดีเซล เวรนช์ไปแล้ว ถ้าไม่ได้เจออีสต์วานน่ะนะ ฮ่า ๆ!",
  str_voice_1300491_22 = "ที่ใดมีแสงสว่าง ที่นั่นย่อมมีเงามืด!",
  str_voice_1300491_23 = "ฉีกให้พวกมันเป็นชิ้น ๆ ให้หมด!",
  str_voice_1300491_24 = "ถ้าไม่มีอีสต์วานก็ไม่มีเซลูซิด แค่นั้นฉันก็ตามเขาไปทุกที่จนสุดขอบโลกแล้ว",
  str_voice_1300491_25 = "เจ้าโง่สองคนเหรอ มือใหม่นี่มีอะไรมากมายให้เรียนรู้จริง ๆ มากมายหลายสิ่งเลย...",
  str_voice_1300491_26 = "เนื้อย่างอร่อย ๆ จะเยียวยาทุกสิ่ง ถ้ายังแก้ไม่ได้ก็กินอีกสักไม้เท่านั้นเอง",
  str_voice_1300491_27 = "ถ้ากล้าก็มาเผชิญหน้ากับฉันสิ มีเพียงคนขี้ขลาดเท่านั้นที่พยายามแทงข้างหลังคนอื่นน่ะ!",
  str_voice_1300491_28 = "คันใหญ่นะเนี่ย ฉันเอาไปขี่รถเล่นถึงลูโมโพลิสได้ไหม",
  str_voice_1300491_29 = "เธอคุมโคลอสซัสนี้อยู่เหรอ ยอดไปเลย! จากนี้ไปฉันจะเรียกเธอว่า \"หัวหน้า\" ฉันมีบอสตัวจริงอยู่นะ แต่การเรียกแบบนี้เป็นวิธีแสดงความเคารพของฉัน!",
  str_voice_1300491_30 = "ได้เวลาแทนที่ดาบสองเล่มนี้แล้ว!",
  str_voice_1300491_31 = "นี่ไม่ใช่โอกาสเพอร์เฟกต์ที่จะฆ่าพวกมันให้หมดเหรอ!",
  str_voice_1300491_32 = "ฉันเป็นนักสู้มือหนึ่งในแก๊งอีสต์วาน!",
  str_voice_1300491_34 = "ตามฉันมาเลย!",
  str_voice_1300491_35 = "ถ้ากล้าก็ดาหน้าเข้ามาเลย!",
  str_voice_1300491_36 = "เตรียมตัวเจ็บตัวซะ!",
  str_voice_1300491_37 = "จงล้มตายไปซะ!",
  str_voice_1300491_38 = "อย่าแม้แต่จะคิดหนีเชียว!",
  str_voice_1300491_39 = "ฟัน!",
  str_voice_1300491_40 = "ฟันอีกรอบ!",
  str_voice_1300491_41 = "ตามฉันให้ทันนะ!",
  str_voice_1300491_42 = "ชนะกล้วย ๆ เลย เด็กน้อย!",
  str_voice_1300491_43 = "อีกรอบ! เฮ้ ฉันบอกว่า \"อีกรอบ\" ไง!",
  str_voice_1300491_44 = "น่าเบื่อชะมัด ฉันต้องการคนมาดวลด้วย!",
  str_voice_1300491_45 = "ฉันอยากให้เธอสู้กับฉันมากกว่าให้เจ้านี่มา",
  str_voice_1300491_46 = "ฉันอยากได้สิ่งนี้มาตลอด! ฮ่า เธอรู้จักฉันดีจริง ๆ",
  str_voice_1300491_47 = "ไม่มีการได้มาโดยปราศจากความเจ็บปวด! บอกฉันสิ คุณต้องการให้ฉันทำอะไร",
  str_voice_1300491_48 = "ตรงตามรสนิยมฉันเลย! ฉันอายเกินจะขอบคุณแล้ว!",
  str_voice_1300491_49 = "หัวเสือดาวคือหมวกนิรภัยของฉัน! ฉันบังเอิญสวมมันแล้วถอดไม่ออกน่ะ บอสแนะนำให้ใช้มันเป็นสไตล์ส่วนตัวไปเลย ทำไมล่ะ ฉันใส่แล้วก็ดูเท่ออก",
  str_voice_1300491_50 = "บอกตามตรงนะ ถึงฉันจะถอดหมวกออกได้ แต่ฉันก็คงไม่ถอดหรอก หน้าฉันมันน่ากลัวกว่ามารยาทของพวกอิคลิพไซท์อีก",
  str_voice_1300491_52 = "Alchemy Stars!",
  str_voice_1300491_53 = "เธอว่างไหม บอส",
  str_voice_1300491_54 = "อรุณสวัสดิ์ บอส!",
  str_voice_1300491_55 = "บอส คุณอยู่ไหน?",
  str_voice_1300491_56 = "บอส เธอยังไม่ได้พักใช่ไหม",
  str_voice_1300491_57 = "สุขสันต์วันปีใหม่! ดื่มกันหน่อย!",
  str_voice_1300221_1 = "น้ำมันดีเซล... ยิ่งเก่ายิ่งหอม ขวดเดียวไม่พอ ขอสอง พอเอาลงท้องสองขวดก็จะอยากได้ขวดสาม",
  str_voice_1300221_2 = "ฉันกับเลื่อยต้องเติมน้ำมันหน่อย เราจะหาน้ำมันดีเซลได้จากที่ไหนเหรอ",
  str_voice_1300221_3 = "ฟิ้ว เกือบไปแล้วสิ ฉันเกือบเสียหมวกไปแล้ว ถ้ามีคนเห็นหน้าฉันละก็...",
  str_voice_1300221_4 = "ฉันได้ยินเสียงเจาะอันคุ้นเคย... แรบบี้นี่! นางอยู่ที่นี่เหรอ...",
  str_voice_1300221_5 = "ฉันอาจจะเคยอ่อนแอและตัวเล็กมาก่อน แต่ตอนนี้ฉันดื่มน้ำมันดีเซลได้แล้วสั่งให้เลื่อยฆ่าทุกคนได้หมด! ทุกคนเลย!",
  str_voice_1300221_7 = "น้ำมันดีเซลพิเศษนี้รสชาติกลมกล่อมอร่อยมาก! อยากดื่มไหม มาเถอะน่า เอาจริงเหรอ แรบบี้ชอบมันมากเลย...",
  str_voice_1300221_8 = "เฮ้ อย่าตัดสินฉันจากความสูงสิ! ฉันล้มผู้ชายตัวใหญ่กว่าฉันหลายเท่าได้ง่าย ๆ เลยนะ เธอพึ่งพาฉันได้ไม่มีปัญหาเลยละ",
  str_voice_1300221_9 = "แปลกจังเลย ทุกอย่างดูต่างออกไปมาก แต่กลับชวนให้ฉันนึกถึงเรดีเซล เวรนช์ หรือว่าฉัน... รู้สึกว่าที่นี่เหมือนบ้านกันนะ",
  str_voice_1300221_10 = "ง่วงจังเลย โอ้ อย่าคิดแม้แต่จะถอดหมวกฉันตอนนอนเชียวนะ...",
  str_voice_1300221_11 = "ยืนอยู่ตรงนั้นเฉย ๆ เหรอ ในนั้นไม่มีอะไรที่ต้องเลื่อยออกเลยหรือไง",
  str_voice_1300221_12 = "มีจุดยุทธศาสตร์อะไรที่เธอสนใจไหมล่ะ อยากให้ฉันไปสำรวจก่อนจะเริ่มไหม โอ้... ไม่ได้จะโจมตีเหรอ น่าเสียดายจัง...",
  str_voice_1300221_13 = "รังนี้ค่อนข้างกว้างแล้วก็มีผ้าห่มอุ่น ๆ ให้ห่มนอนด้วย ถ้าฉันได้เจอแรบบี้บ่อยกว่านี้นะ... อ๊าา แรบบี้น่ะ... นาง... ไม่มีอะไรหรอก!",
  str_voice_1300221_14 = "ใต้หมวกงั้นเหรอ ไม่มีอะไรให้น่าจดจำหรอก จ้องมันอย่างนั้นก็ไม่มีประโยชน์ ฉันไม่ถอดหรอกนะ! ยังไงฉันก็สาบานแล้ว... เพื่อแรบบี้...",
  str_voice_1300221_15 = "ฉันขอตัดเค้กวันเกิดนะ! ทุบเลยไหม จัดไปเลยจ้ะ!",
  str_voice_1300221_16 = "หัวหน้า ตอนนี้เขานิยมอวดกระต่ายกันแล้วเหรอ",
  str_voice_1300221_17 = "หัวหน้า! เข้าใจบ้างไหมเนี่ย",
  str_voice_1300221_18 = "หัวหน้า! กลับมาแล้วเหรอ วันนี้มาทำอะไรที่ยิ่งใหญ่กันเถอะ",
  str_voice_1300221_19 = "น้ำมันดีเซลสักแก้วและขนมปังแห้งสับ อาหารเย็นของฉัน...",
  str_voice_1300221_20 = "เรดีเซล เวรนช์! กลุ่มคนบ้าคลั่ง แต่ฉันชอบพวกเขานะ ฮ่า ๆ ๆ",
  str_voice_1300221_21 = "ฉันเกลียดคนหัวคร่ำครึจากอิลลูมินา แต่เทคโนโลยีพวกเขาอยู่ในระดับที่ต่างออกไปเลยละ ได้ยินว่าพวกนั้นมีเลื่อยไฟฟ้าที่ทรงพลังมากด้วย!",
  str_voice_1300221_22 = "แรบบี้จงเจริญ!",
  str_voice_1300221_23 = "กลุ่มคนโง่ที่งี่เง่ายิ่งกว่าฉันอีก!",
  str_voice_1300221_24 = "สว่านของแรบบี้เจาะเข้ามาในใจฉัน ถ้านางไม่เชื่อละก็ ฉันจะผ่าอกด้วยเลื่อยเพื่อพิสูจน์ โอ้ แรบบี้...",
  str_voice_1300221_25 = "โคลเวอร์กับฉันคืออดีตคู่หูน่ะ แค่นั้นแหละ แต่หล่อนเป็นคนน่าสงสาร...",
  str_voice_1300221_26 = "ง่าย ๆ ฉันรักแรบบี้ การอยู่กับเธอทำให้ฉันมีความสุข ฉันจะไม่ยอมให้ใครมาทำร้ายเธอ",
  str_voice_1300221_27 = "ขาที่อ่อนแรงในสมรภูมิรบก็เหมือนฟืนที่เปียกน่ะ... ไร้ประโยชน์สิ้นดีเลย!",
  str_voice_1300221_28 = "ใหญ่จัง! แข็งแกร่งกว่ากิ้งก่าตัวใหญ่ของเรามากแน่ ๆ...",
  str_voice_1300221_29 = "ไหนบอกมาซิว่าอยากให้ฉันไปผ่าร่างใคร ใครก็ตามที่ดูถูกฉันกับเลื่อยจะต้องจบชีวิตอย่างทุกข์ทรมาน!",
  str_voice_1300221_30 = "รู้สึกเหมือนเลือดขึ้นหน้าเลย!",
  str_voice_1300221_31 = "หมุนไป! เร็วกว่านี้!",
  str_voice_1300221_32 = "น้ำมันดีเซลอีก! เพิ่มพลังอีก!",
  str_voice_1300221_34 = "นับฉันด้วยสิ!",
  str_voice_1300221_35 = "อย่าได้คิดหนีเชียวนะ",
  str_voice_1300221_36 = "ขนาดเลื่อยของฉันยังอดใจรอไม่ไหวเลย!",
  str_voice_1300221_37 = "เลื่อยมันออกเลย เลื่อยมัน!",
  str_voice_1300221_38 = "ไอจะบดขยี้พวกยูให้แหลก!",
  str_voice_1300221_39 = "มาลิ้มรสเลื่อยไฟฟ้าของฉันสิ!",
  str_voice_1300221_40 = "วะฮู้!!",
  str_voice_1300221_41 = "ฮิ ๆ ฉันได้เป็นหัวหน้าแล้ว!",
  str_voice_1300221_42 = "เธอเห็นฉันตอนนี้ไหม แรบบี้",
  str_voice_1300221_43 = "ทุกคนถอยไป! ฉันจะถ่วงพวกมันไว้เอง!",
  str_voice_1300221_44 = "แทนแท๊น! ฉันต้องใช้น้ำมันดีเซลอีก ฮ่า ๆ",
  str_voice_1300221_45 = "เจ้านี่มีไว้ทำอะไรเหรอ",
  str_voice_1300221_46 = "ให้ฉันเหรอ ฉันตามหาเจ้านี่มาตั้งนาน...",
  str_voice_1300221_47 = "มันมีมูลค่ามาก เธอต้องการอะไรจากฉัน หา?",
  str_voice_1300221_48 = "เฮ้ หัวหน้า ดีเซลสักหน่อยไหม",
  str_voice_1300221_49 = "ฉันไม่ใช่กระต่ายนะ... ฉันเลือกที่จะทำเพื่อความรัก มันคงมีปัญหาน้อยกว่านี้ถ้าฉันเป็นพันธุ์เดียวกับเธอ หรือบางทีฉันแค่งี่เง่าไปเอง...",
  str_voice_1300221_50 = "พ่อแม่เหรอ... เคยเจอพ่อแม่ตัวเองไหม ฉันไม่เคยเลย ไม่ใช่นะ... นางไม่ใช่แม่ของฉัน... แค่คนที่ขายฉันเท่านั้นเอง",
  str_voice_1300221_52 = "Alchemy Stars!",
  str_voice_1300221_53 = "น้ำมันดีเซลสักแก้วเป็นไง",
  str_voice_1300221_54 = "ฮ่า ๆ! อรุณสวัสดิ์!",
  str_voice_1300221_55 = "ได้เวลามื้อเที่ยงแล้วเหรอ",
  str_voice_1300221_56 = "ฉันง่วงนอนนิดหน่อย",
  str_voice_1300221_57 = "สุขสันต์วันปีใหม่! ตึ่งโป๊ะ!",
  str_voice_1601051_1 = "3 2 1! เดาซิว่าใคร ถูกต้องแล้ว อีฟเองไงล่ะ! เธอทำอะไรอยู่เหรอ มีอะไรให้ฉันช่วยไหม",
  str_voice_1601051_2 = "ฉันรักพี่ชายฉันมากกว่าอะไรทั้งสิ้น! ถ้ามีใครมาทำร้ายเขาละก็... เอ่อ ขอโทษทีนะ ฉันไม่ปล่อยให้ใครมาทำร้ายเธอเหมือนกัน!",
  str_voice_1601051_3 = "อ้า! ม-มีบางอย่างปลิวอยู่ข้างนอก! ใช่นกหรือเปล่า? ไม่นะ ดูเหมือนโคลอสซัสเลย...\nอ้อ แค่คนส่งสารน่ะ...",
  str_voice_1601051_4 = "ฉันได้ยินเสียงอิคลิพไซท์คำรามเมื่อกี้... ทำให้ฉันนึกถึงสิ่งที่เกิดขึ้นเมื่อตอนนั้น... ไม่นะ ฉันจะปล่อยให้ความกลัวชนะไม่ได้! ฉันจะไม่กลัวอีกต่อไปแล้ว! *แค่ก* ฉันไม่เป็นไรแล้ว เห็นไหม สบายหายห่วงเลย",
  str_voice_1601051_5 = "พลังนั้น... เหมือนกับสายฟ้าที่พุ่งเข้ามาในเส้นเลือดของฉัน มันน่ากลัว แต่เหลือเชื่อ... ฉันรู้สึกเหมือนจะทำอะไรก็ได้! แต่ฉันรู้ดี... ไม่ว่ายังไง ฉันก็จะไม่สูญเสียการควบคุมอีกแล้ว",
  str_voice_1601051_6 = "ฉันจำได้ว่าพี่ชายฉันทรมานเพราะฉันแค่ไหน... ฉันไม่เคยหนีจากความผิดพลาดในอดีตได้เลยแล้วฉันก็ไม่ตั้งใจด้วย... เพราะอย่างนั้นฉันเลยจะทำทุกอย่างที่แบ่งเบาภาระพี่ได้ เริ่มจากงานบ้านก่อนเลย",
  str_voice_1601051_7 = "เธอใจดีจริง ๆ... *แค่ก* ถ้าเธออยากทำอะไรดี ๆ ให้ฉันจริง ๆ แล้วทำไมไม่ไปเข้าเรดีเซล เวรนช์ล่ะ\nฮ่า ๆ ๆ ล้อเล่นน่ะ!",
  str_voice_1601051_8 = "ล่าสุดฉันเป็นเพื่อนกับคนที่ดูแลทั้งฉันแล้วก็เพื่อนคนอื่นดีมากด้วยล่ะ... เดาได้ไหมว่าเป็นใคร ฉันจะบอกใบ้ให้นะ คนที่รู้วิธีขับโคลอสซัสไง!",
  str_voice_1601051_9 = "ถึงพี่ชายฉันจะเป็นคนที่สำคัญที่สุดสำหรับฉัน เธอก็น่าจะเป็นคนที่สองได้... หรือไม่ก็สำคัญเป็นอันดับสองพอ ๆ กับดอว์นล่ะ!",
  str_voice_1601051_10 = "เอ่อ ธ-เธอยุ่งอยู่หรือเปล่า ถ้าไม่ละก็... เล่าเรื่องเธอให้ฉันฟังเพิ่มได้ไหม แล้วบางที... ก็เล่าเรื่องโลกภายนอกด้วย",
  str_voice_1601051_11 = "เธอ... ไว้ใจให้ฉันทำเหรอ ข-ขอบคุณนะ! ฉันสัญญาว่าฉันจะทำให้ดีที่สุดโดยไม่สร้างปัญหา ฉัน... ฉันคิดว่าฉันทำได้นะ",
  str_voice_1601051_12 = "ฉันอยากไปเที่ยวเล่นตรงห้องบังคับการทั้งวันเลย... ข้างนอกนั่นมันสวยมาก",
  str_voice_1601051_13 = "หืม... มีอะไรให้เรียนรู้อีกเยอะแต่กลับมีเวลาเล็กน้อย ฉันควรเริ่มจากตรงไหนดี",
  str_voice_1601051_14 = "ฉันมีความสุขมากเลย ไม่เคยคิดเลยว่าจะได้ใช้ชีวิตแบบนี้",
  str_voice_1601051_15 = "แฮปปี้เบิร์ธเดย์ทูยู! แฮปปี้เบิร์ธเดย์ทูยู!",
  str_voice_1601051_16 = "เธอกลับมาแล้ว... เธอได้ทำอะไรสนุก ๆ หรือเปล่า เล่าให้ฉันฟังได้ไหม",
  str_voice_1601051_17 = "ง่วงจังเลย... เธอตื่นเช้าขนาดนี้เลยเหรอ ล้าชะมัด...",
  str_voice_1601051_18 = "ช่วงนี้พี่ชายยุ่งมากตลอดเลย... หวังว่าพวกเธอทั้งคู่จะพักผ่อนเพียงพอนะ",
  str_voice_1601051_19 = "ฉัน... ฉันต้องนอนแล้ว อย่าลืมรีบเข้านอนนะ...",
  str_voice_1601051_20 = "เรดีเซล เวรนช์ยิ่งใหญ่ที่สุด! มีคนน่าสนใจที่นี่มากมายเลย รวมถึงพี่ชายของฉันด้วย!",
  str_voice_1601051_21 = "ฉันอาจจะไม่ได้มีความทรงจำที่ดีต่ออิลลูมินามากที่สุด... แต่ฉันก็รู้ว่ามันไม่ใช่ความผิดของอิลลูมินา",
  str_voice_1601051_22 = "พี่ชายฉันมักจะพูดว่าไงเสมอนะ ใช้ชีวิตให้เต็มที่ใช่ไหม",
  str_voice_1601051_23 = "ฉันสัมผัสได้ถึงการมีอยู่และเสียงคำรามของมัน แต่ฉันจะไม่อยู่กับพวกมันอย่างแน่นอน ไม่มีทาง...!",
  str_voice_1601051_24 = "ด-เดี๋ยวก่อนสิ ดอว์น! วันนี้ฉันรดน้ำต้นไม้ไปแล้วนะ!",
  str_voice_1601051_25 = "ดอกไม้ไฟของโจแอนนีเจ๋งที่สุด เดี๋ยวนะ ของพวกนั้นไม่ใช่ระเบิดเหรอ?!",
  str_voice_1601051_26 = "สร้างของ ปิกนิก แล้วก็เสื้อผ้าใหม่... เป็นของโปรดฉันทั้งนั้นเลยนี่! โอ้ แล้วก็โคลอสซัสด้วยเหมือนกัน!",
  str_voice_1601051_27 = "ใครก็ตามที่ทำร้ายพี่ชายเป็นคนไม่ดี... รวมถึงฉันด้วย... ใช่ไหม",
  str_voice_1601051_28 = "ฉันชอบขึ้นโคลอสซัสนะ! ฉันเห็นสถานที่วิเศษเยอะมากจากบนนี้!",
  str_voice_1601051_29 = "ขอลองอีกครั้งนะ... ฉ-ฉันชื่ออีฟแล้วก็เป็นน้องสาวของซินซา... *แค่ก* ยินดีที่ได้รู้จัก ฉันรู้ว่าฉันอาจเคยสร้างปัญหาให้ทุกคนมาก่อน... แต่ตอนนี้ฉันดีขึ้นแล้วนะ! แถ่นแท้น! เห็นไหม",
  str_voice_1601051_30 = "ฉันต้องระวังพลังของฉันเอาไว้...",
  str_voice_1601051_31 = "ฉันได้ยิน... เสียงพวกนั้น...",
  str_voice_1601051_32 = "ฉันควบคุมตัวเอง สายฟ้า และฟ้าผ่าได้เก่งขึ้นแล้ว",
  str_voice_1601051_33 = "ฉัน... ฉันต้องปกป้องพี่ชาย!",
  str_voice_1601051_34 = "ฉ-ฉันทำได้แน่!",
  str_voice_1601051_35 = "ตอนนี้ฉันไม่เป็นไรแล้ว!",
  str_voice_1601051_36 = "เราเริ่มกันเลยไหม",
  str_voice_1601051_37 = "เสียงคำรามนั่นคุ้นเคยเหลือเกิน",
  str_voice_1601051_38 = "ผ่านเมฆา",
  str_voice_1601051_39 = "ปรากฎ!",
  str_voice_1601051_40 = "ลุกวาว!",
  str_voice_1601051_41 = "ฉัน? ฉัน... ฉันทำได้!",
  str_voice_1601051_42 = "ฉันทำได้?!",
  str_voice_1601051_43 = "ฉันปกป้องทุกคนไม่สำเร็จ...",
  str_voice_1601051_44 = "ที่นี่สวยงามมาก\nดีกว่าที่ที่ฉันเคยอยู่มากเลยละ",
  str_voice_1601051_45 = "อืม... ขอบคุณนะ",
  str_voice_1601051_46 = "ให้ฉันเหรอ ฉันชอบมากเลย ขอบใจนะ!",
  str_voice_1601051_47 = "มันไม่ใช่สิ่งที่ฉันคิดไว้... แต่ก็ขอบใจนะ!",
  str_voice_1601051_48 = "เธอรู้ตลอดเลยว่าฉันต้องการอะไร!",
  str_voice_1601051_49 = "ตอนที่ฉันกักตัวอยู่ ฉันได้ยินเสียงคำรามของอิคลิพไซท์ทุกคืนแล้วก็หวาดกลัว... แต่คนในเรดีเซล เวรนช์ก็มักจะมาปลอบฉันแล้วเตือนให้รู้ว่าฉันไม่ได้อยู่ตัวคนเดียว...",
  str_voice_1601051_50 = "เธอนี่งี่เง่าจริง ๆ ดอว์น... มันก็เป็นแค่ดอกไม้เท่านั้น เธอบอกว่ามันสำคัญกว่าชีวิตเธอเองได้ยังไง...",
  str_voice_1601051_51 = "พี่ใหญ่ของฉันต้องทนทุกข์ทรมานมากเพราะฉัน... นี่เป็นภาระที่ฉันต้องแบกรับ ไม่ใช่ของเขา ด้วยเหตุนี้ฉันก็เลยจะทุ่มสุดตัวเพื่อปกป้องเขา",
  str_voice_1601051_52 = "Alchemy Stars!",
  str_voice_1601051_53 = "เฮ้ เธอ!",
  str_voice_1601051_54 = "อ-อรุณสวัสดิ์...",
  str_voice_1601051_55 = "หืม... กินอะไรเป็นมื้อเที่ยงเหรอ",
  str_voice_1601051_56 = "เดี๋ยวพักก่อนนะ ตกลงไหม",
  str_voice_1601051_57 = "สุขสันต์วันปีใหม่! ฉันขอให้เธอมีแต่ความสงบสุขและสันติตลอดปีเลย!",
  str_voice_1501041_1 = "เมื่อเทียบกับความเป็นนิรันดร ดอกไม้จะเบ่งบานเพียงชั่วครู่",
  str_voice_1501041_2 = "ชอบนั่งใต้ดวงอาทิตย์ไหม นานมาแล้วตั้งแต่ที่ฉันได้นั่งแบบนั้นน่ะ... ดวงอาทิตย์สัมผัสผิวฉันแล้วเหมือนเวทมนตร์เลย... ถึงบางครั้งฉันจะตกใจเพราะแสงก็เถอะ แต่ก็ความอบอุ่นชวนให้รู้สึกดี",
  str_voice_1501041_3 = "ไม่ต้องห่วงฉันเท่าไหร่หรอก ฉันหูดีมากแล้วฉันก็จำทางเดินได้หมดแล้ว โอ๊ย! ใครมาวางโต๊ะไว้ตรงนี้เนี่ย",
  str_voice_1501041_4 = "พลังไม่มีค่าพอให้ชื่นชมหรอก... ฉันมั่นใจว่ายังจะมีอันตรายบางอย่างที่เราไม่รู้ ยังไงมันก็เป็นพลังของอิคลิพไซท์อยู่ดี",
  str_voice_1501041_5 = "ผู้หญิงคนนั้น... ฉันว่าเธอทำวิจัยได้น่ากลัวที่สุดเท่าที่เคยมีมา แค่คิดก็ทำให้ฉันขนหัวลุกแล้ว...",
  str_voice_1501041_6 = "มีคนอื่นที่เหมือนฉันกับอีฟอยู่บนโลกนี้แน่ พอฉันหาพวกเขาเจอ... ฉันจะหาทางช่วยพวกเขาทุกวิถีทาง",
  str_voice_1501041_7 = "หืม เราสนิทกันมากพอจะเล่าความลับของกันและกันแล้วนะ... ทำไมเธอไม่เริ่มก่อนล่ะ",
  str_voice_1501041_8 = "ขนาดในฝันฉันยังไม่คิดว่าจะมีชีวิตอิสระได้แบบนี้เลย อีฟ ซินซา เรดีเซล เวรนช์น่ะ... ต่างก็เป็นเพื่อนของฉัน รวมถึงเธอด้วย",
  str_voice_1501041_9 = "ดอกไม้มีความหมายพิเศษสำหรับฉันและอีฟ... พวกมันย้ำเตือนถึงเวลาที่เราคุดคู้อยู่ด้วยกันเพื่อให้ความอบอุ่น แต่เราไม่ต้องห่วงเรื่องเหงาอีกต่อไปแล้วล่ะ... ก็ตอนนี้เรามีเธอนี่นะ",
  str_voice_1501041_10 = "เธอหยุดมือเหรอ? ถึงฉันจะมองไม่เห็น แต่ฉันสัมผัสได้",
  str_voice_1501041_11 = "เธอไว้ใจฉันได้เลย แต่ช่วยรดน้ำดอกไม้ของอีฟให้ฉันหน่อยได้ไหม",
  str_voice_1501041_12 = "ว่าไง ฉันเพิ่งชินกับแผนผังของห้องนี้น่ะ",
  str_voice_1501041_13 = "อากาศในโคลอสซัสมันต่างออกไป... อาจเป็นกลิ่นของท้องฟ้าก็ได้นะ",
  str_voice_1501041_14 = "เธออยู่ไหม ไม่สงสัยเลยว่าทำไมจู่ ๆ ถึงมีชีวิตชีวาขึ้นมาเสียอย่างนั้น",
  str_voice_1501041_15 = "ฉันทำพวงดอกไม้มาให้เธอ สุขสันต์วันเกิดนะ",
  str_voice_1501041_16 = "วันนี้มีแผนจะไปไหนไหม?  ไม่เหรอ?  งั้นทำไมเราไม่เดินเล่นสักหน่อยล่ะ แล้วถ้าเป็นไปได้ก็อาบแดดด้วยกัน",
  str_voice_1501041_17 = "อรุณสวัสดิ์ เมื่อแสงยามรุ่งสางส่อง ดวงอาทิตย์ก็ขึ้นมาเฉิดฉายในความมืดยามค่ำคืน สวยงามใช่ไหมล่ะ",
  str_voice_1501041_18 = "ข้างนอกหนาวนะ พยายามอย่าให้เป็นหวัดเชียว",
  str_voice_1501041_19 = "นี่เธอไม่ได้กะจะโต้รุ่งทั้งคืนใช่ไหม ทำไมต้องฝืนตัวเองแบบนั้นด้วย",
  str_voice_1501041_20 = "บ้านของอีฟก็คือบ้านของฉัน ครอบครัวของนางก็เหมือน... ครอบครัวของฉัน",
  str_voice_1501041_21 = "อิลลูมินาเหรอ... ฉันมีแต่ความทรงจำเศร้าโศกที่นั่น",
  str_voice_1501041_22 = "\"ใช้ชีวิตให้เต็มที่!\" วัน ๆ หนึ่งจะผ่านไปโดยไม่มีใครในเรดีเซล เวรนช์กู่ร้องประโยคนั้นออกมาสุดเสียงไม่ได้หรอก",
  str_voice_1501041_23 = "ฉันเคยครอบครองอิคลิพไซท์ที่หุบเขาตาแดงสักพัก น่าประทับใจใช่ไหมล่ะ",
  str_voice_1501041_24 = "สาบานเลยว่าฉันจะหันไปด้านดวงอาทิตย์เสมอ ไม่ว่ามันจะร้อนแค่ไหนก็ตาม",
  str_voice_1501041_25 = "ไม่อยากจะเชื่อว่าซินซาเป็นพี่ชายของอีฟจริง ๆ... ไม่เห็นเหมือนกันสักนิดเดียว!",
  str_voice_1501041_26 = "อีฟชอบดอกไม้ ฉันก็ชอบเหมือนกัน",
  str_voice_1501041_27 = "เสียงเพลิงแผดเผา... พาฉันย้อนกลับไปช่วงเวลาที่เจ็บปวดได้ทุกทีไม่เคยพลาด",
  str_voice_1501041_28 = "งั้นนี่ก็คือโคลอสซัสที่ทนทานต่อพายุเหรอ กลิ่นหอมดีแฮะ",
  str_voice_1501041_29 = "เราเจอกันอีกแล้ว ไหนดูซิว่ามีกฎพื้นฐานด้านความร่วมมือของเราอะไรบ้าง ห้ามบ่นอีฟ ห้ามทำให้นางไม่มีความสุข และห้ามปล่อยให้นางหิว เข้าใจไหม",
  str_voice_1501041_30 = "ฉันแข็งแกร่งขึ้นแล้ว...",
  str_voice_1501041_31 = "ฉันต้องควบคุมพลังนี้ให้ได้...",
  str_voice_1501041_32 = "ดอกไม้บางต้นก็บานได้แค่ครั้งเดียวในชีวิต",
  str_voice_1501041_33 = "นิจนิรันดร์นั้นเพียงชั่วพริบตา",
  str_voice_1501041_34 = "เข้าใจแล้ว",
  str_voice_1501041_35 = "บุปผาเบ่งบาน",
  str_voice_1501041_36 = "คว้าโอกาสไว้!",
  str_voice_1501041_37 = "ทีนี้ไปกันเถอะ!",
  str_voice_1501041_38 = "ลืมช่วงเวลานี้ไปให้หมด",
  str_voice_1501041_39 = "ฉันมาช่วยแล้ว!",
  str_voice_1501041_40 = "มันจบแล้ว",
  str_voice_1501041_41 = "ฉันทำได้หรือเปล่า",
  str_voice_1501041_42 = "ผลลัพธ์ที่ปฏิเสธไม่ได้",
  str_voice_1501041_43 = "อย่าตื่นตูมสิ หายใจลึก ๆ",
  str_voice_1501041_44 = "ฉันจำได้ว่าควรเลี้ยวซ้ายตรงนี้ แล้วก็...",
  str_voice_1501041_45 = "ขอบใจสำหรับของขวัญนะ",
  str_voice_1501041_46 = "เธอเอาใจใส่มากกว่าที่ฉันคิดไว้",
  str_voice_1501041_47 = "ฉันจะทะนุถนอมอย่างดี",
  str_voice_1501041_48 = "จิตใจเราเหมือนจะจูนตรงกัน",
  str_voice_1501041_49 = "แม่ของฉันและผู้หญิงคนนั้น... ต่างก็สนใจแค่การวิจัยและทดลอง แต่ถ้าไม่ใช่เพราะพวกเขา ฉันก็คงไม่ได้เจออีฟ อาจเป็นโชคชะตาก็ได้...",
  str_voice_1501041_50 = "ฉันจะไม่มีวันลืมวันที่อยู่ในห้องทดลองเลย อีฟอยู่ข้างฉันเสมอ... ความใจดีและบริสุทธิ์ของเธอทำให้ฉันรู้สึกว่า บางทีโลกข้างนอกก็อาจจะไม่ได้แย่นักก็ได้... รู้สึกว่าบางทีฉันก็อาจได้นั่งใต้ดวงอาทิตย์อีกครั้ง",
  str_voice_1501041_51 = "อดีตน่ะผ่านมาแล้ว เราไม่ต้องทนทุกข์ทรมานแบบนั้นแล้ว ฉันแค่หวังให้ตอนนี้ไม่มีที่สิ้นสุด... แล้วฉันจะทำทุกอย่างที่จำเป็นเพื่อให้ความต้องการนั้นเป็นจริง",
  str_voice_1501041_52 = "Alchemy Stars",
  str_voice_1501041_53 = "หวัดดี ผู้นำทาง",
  str_voice_1501041_54 = "พระอาทิตย์ออกมาอีกแล้ว...",
  str_voice_1501041_55 = "อย่าลืมกินสิ่งที่ดีต่อสุขภาพนะ",
  str_voice_1501041_56 = "ความเงียบสงัดยามค่ำคืนมักจะทำให้ฉันอารมณ์ดีเสมอ",
  str_voice_1501041_57 = "สุขสันต์วันปีใหม่! เป้าหมายวันปีใหม่ของฉันคือได้เห็นอีฟยิ้มมากกว่านี้! แล้วเธอล่ะ หืม มุ่งมั่นดีแฮะ ฉันมั่นใจว่าเธอทำได้อยู่แล้ว",
  str_voice_1401011_1 = "เงียบเถอะ เห็นศัตรูตรงนั้นไหม เราหนีตอนที่ยังหนีได้ดีกว่า! เดินระวัง ๆ ตอนหนีด้วยล่ะ... รู้ใช่ไหมว่าฉันล้อเล่นเนี่ย",
  str_voice_1401011_2 = "เธอทำของหายเหรอ เฮ้ อย่ามามองฉันสิ! ฉันชอบแกล้งอำเล่นก็จริงแต่ฉันไม่ขโมยของหรอกนะ... เอ้า ฉันถึงขั้นช่วยเธอหาแล้วนะ ถ้ามันช่วยล้างมลทินชื่อฉันได้!",
  str_voice_1401011_3 = "ฉันไม่มีวันล้อเล่นในที่ทำงานแน่ แต่ตอนนี้ฉันไม่ได้ทำงานอยู่ก็เลย... เธอไม่อยากรู้เหรอว่าฉันทำอะไรลงไปน่ะ",
  str_voice_1401011_4 = "ฉันเดาว่าการต่อสู้ครั้งสุดท้ายสร้างปัญหาบางอย่างขึ้นมา... อ้าว นี่ มาได้เวลาเหมาะเลย! ฉันกำลังแก้บัคอุปกรณ์ของเราอยู่ ช่วยฉันตรวจปริมาณหน่อยได้ไหม",
  str_voice_1401011_5 = "ขอบใจที่เชื่อในตัวฉันนะ ฉันจะตั้งใจทำงานต่อไปและทำอย่างสุดฝีมือเลย ทั้งเรื่องงาน \"แล้วก็\" เรื่องแกล้งด้วย",
  str_voice_1401011_6 = "ผู้ส่งสัญญาณที่ดีควรจะต้องอดทน พุ่งประเด็น และพร้อมปรับไปตามสถานการณ์ทุกอย่างเพื่อสื่อสารอย่างรวดเร็วและมีประสิทธิภาพ!",
  str_voice_1401011_7 = "เราขัดขวางเวลาเลิกงานของเธอเพื่อแจ้งข้อความด่วน หนอนผีเสื้อมหึมาปรากฎตัวในห้องของผู้นำทางแล้ว ยิ่งไปกว่านั้น ฉันไม่ได้เป็นคนเอามันไปไว้ในห้องแน่นอน!",
  str_voice_1401011_8 = "เฮ้ ผู้นำทาง ตั้งแต่วันนี้ไปฉันจะเซอร์ไพร์สเธอมากกว่าเดิม เพื่อแสดงให้เห็นว่าฉันใส่ใจมากแค่ไหน",
  str_voice_1401011_9 = "การแกล้งอำดี ๆ ทำให้ความสัมพันธ์ระหว่างคนสองคนแน่นแฟ้นขึ้นได้ แต่ฉันไม่มีทางทำเกินเลยแน่นอน ยังไงฉันก็ไม่อยากให้เธออารมณ์บูดน่ะ!",
  str_voice_1401011_10 = "ฉันเบื่อมากเลยละก็เลยทำปริศนาขึ้นมา ฉันเพิ่งสร้างกับดักไว้ให้เธอ ทายซิว่าอยู่ไหน",
  str_voice_1401011_11 = "ตรงนั้นเอง! ผู้ส่งสัญญาณแอนเซียมายืนประจำที่เพื่อสื่อสารให้ตรงเวลาและแม่นยำ... เดี๋ยวนะ เธอไม่ต้องการให้ฉันทำอย่างนั้นแล้วเหรอ",
  str_voice_1401011_12 = "ฉันมีงานด่วนต้องทำ ไว้จะกลับมาทันทีที่ทำเสร็จแล้วนะ!",
  str_voice_1401011_13 = "เดินมาทางนี้สิ! ถ้าติดกับดักฉันละก็ ฉันไม่ช่วยเธอออกมาหรอกนะ... อ้าว ติดกับแล้วเหรอ",
  str_voice_1401011_14 = "อ้อ เธออยากรู้เหรอว่าข้อความบนหลังเขียนว่ายังไง ฉันไม่บอกหรอกน่า!",
  str_voice_1401011_15 = "สุขสันต์วันเกิด! นี่ของขวัญของเธอ... ฮ่า ๆ ล้อเล่นน่ะ ของขวัญจริง ๆ อยู่ข้างหลังเธอต่างหาก",
  str_voice_1401011_16 = "งานเป็นยังไงบ้าง ถ้าต้องการผู้ส่งสัญญาณก็เรียกหาฉันได้ตลอดเลยนะ!",
  str_voice_1401011_17 = "อรุณสวัสดิ์! อยากส่งข้อความอะไรไหม ไม่แล้วเหรอ แงะ?",
  str_voice_1401011_18 = "สายัณห์สวัสดิ์! จบลงไปอีกวันแล้ว อย่าลืมสรุปทุกอย่างที่ต้องเขียนรายงานด้วยล่ะ!",
  str_voice_1401011_19 = "นี่มันกลางดึกนะ! ดึกขนาดนี้ไม่มีใครตอบข้อความเธอหรอก... เว้นแต่ฉันจะใช้เทคนิคลับอย่างหนึ่งของฉันน่ะ",
  str_voice_1401011_20 = "อิลลูมินาเป็นบ้านของฉันและจะเป็นอย่างนั้นเสมอ ฉันจะทำทุกอย่างเพื่อปกป้องอิลลูมินา",
  str_voice_1401011_21 = "ถ้าฉันไม่ได้อยู่ในอิลลูมินา ฉันก็ต้องอยู่อัมบราตัน ที่นั่นชอบมุกแผลง ๆ ของฉันมากกว่าเยอะ",
  str_voice_1401011_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1401011_23 = "วันที่อิคลิพไซท์ไม่คุกคามแอสตราอีกต่อไปแล้ว... ฉันรู้ว่าวันนั้นจะมาถึง",
  str_voice_1401011_24 = "คุณไวซ์สุดยอดมาก ทั้งแข็งแกร่งและพึ่งพาได้... ฉันอยากเป็นแบบเธอจัง!",
  str_voice_1401011_25 = "ฉันจะบอกความลับอะไรให้ฟัง... ฉันอยากเล่นหางชาโรนามาก ฉันว่ามันน่าจะสนุกดี!",
  str_voice_1401011_26 = "ฉันชอบเพลงเมทัลนะ รู้ไหม ทั้งจังหวะและพลัง... มันทำให้ฉันฮึกเหิมมากเลย!",
  str_voice_1401011_27 = "ฉันทนคนที่ไม่เป็นมืออาชีพไม่ได้ เวลาเธอทำงานก็ต้องตั้งใจทำงานสิ!",
  str_voice_1401011_28 = "แม้ว่าฉันจะรู้อยู่แล้วว่าโคลอสซัสคืออะไร แต่มันก็เหลือเชื่อจริง ๆ",
  str_voice_1401011_29 = "ทดสอบ! ทดสอบ! แอนเซียพูด\nฉันเป็นผู้ส่งสัญญาณหลักของอิลลูมินาและฉันคิดว่าควรติดต่อไปก่อน\nเพราะไม่ได้รับคำสั่งให้ทำงานอะไรจากเธอเลย!",
  str_voice_1401011_30 = "เปิดเสียงให้ดังขึ้น!",
  str_voice_1401011_31 = "การบำรุงรักษาตามตารางของอุปกรณ์สื่อสารเราก็เป็นส่วนหนึ่งของงานเหมือนกัน!",
  str_voice_1401011_32 = "อยากฟังเรื่องที่ฉันทำงานเป็นผู้ส่งสัญญาณไหม น่าสนใจมากนะ!",
  str_voice_1401011_33 = "ได้เวลาเร่งสัญญาณไปดวงจันทร์แล้ว!",
  str_voice_1401011_34 = "ฉันจะจัดการเรื่องการสื่อสารเอง!",
  str_voice_1401011_35 = "เตรียมเสร็จสมบูรณ์!",
  str_voice_1401011_36 = "เตรียมพร้อมคลื่นเสียง!",
  str_voice_1401011_37 = "คลื่นเหนือเสียง!",
  str_voice_1401011_38 = "เขย่ามันให้แหลก!",
  str_voice_1401011_39 = "ช็อก?",
  str_voice_1401011_40 = "อย่าขยับ!",
  str_voice_1401011_41 = "อย่าขาดการติดต่อนะ ทุกคน!",
  str_voice_1401011_42 = "เรียบร้อยดี!",
  str_voice_1401011_43 = "หนี!",
  str_voice_1401011_44 = "สวัสดี ได้ยินฉันหรือเปล่า ได้ยินสิ ฉันได้ยินเธอชัดเจนแจ่มแจ้งเลย!",
  str_voice_1401011_45 = "ของขวัญเหรอ ใช่กล่องของเล่นที่มีตุ๊กตาไหม",
  str_voice_1401011_46 = "ว้าว! ฉันรับไว้ได้จริงเหรอ",
  str_voice_1401011_47 = "อันที่จริงฉันอยากได้กล่องที่มีตุ๊กตาโผล่ออกมาน่ะ เธอรู้เปล่า!",
  str_voice_1401011_48 = "ขอบใจนะ! ทีนี้ให้ฉันตอบแทนบ้างเถอะ!",
  str_voice_1401011_49 = "ฉันไม่ถนัดเป็นนักสู้เท่าไหร่แต่สุดท้ายก็หาเจอว่าฉันเก่งอะไรสักที การสื่อสารไงล่ะ! ในฐานะผู้ส่งสัญญาณ ฉันจะทำให้ทุกคนรู้ข่าวสารตลอดเวลา",
  str_voice_1401011_50 = "ครั้งหนึ่งฉันเคยแอบถอดซองกระสุนจากปืนของเจ้าหน้าที่อิลลูมินาด้วย เขาโมโหมากตอนที่รู้ว่าซองหายไปแต่ไม่มีกระสุนก็ทำอะไรไม่ได้ เขาก็เลยวิ่งหนีออกไปแทน!",
  str_voice_1401011_51 = "ฉันเข้าหน่วยรบพิเศษเป็นครั้งคราว ไม่ว่าสถานการณ์จะอันตรายขนาดไหน ผู้ส่งสัญญาณก็ต้องทำทุกอย่างที่ทำได้เพื่อส่งข้อความไปให้ถึงที่หมายโดยไว!",
  str_voice_1401011_52 = "Alchemy Stars...!",
  str_voice_1401011_53 = "ทดสอบ หนึ่ง สอง สาม!",
  str_voice_1401011_54 = "คุณได้รับข้อความใหม่!",
  str_voice_1401011_55 = "กรุณาตอบ!",
  str_voice_1401011_56 = "สายัณห์สวัสดิ์ ผู้นำทาง!",
  str_voice_1401011_57 = "สุขสันต์วันปีใหม่! หวังว่าเธอจะได้รับข่าวดีเพิ่มขึ้นในปีนี้นะ!",
  str_voice_1501001_1 = "ฉันอยู่ที่นี่เพียงเพราะอยากอยู่ ไม่เกี่ยวอะไรกับเธอเลย คนซื่อบื้อ",
  str_voice_1501001_2 = "เธอเป็นคนซื่อบื้อแต่ก็แตกต่างจากสัตว์เซลล์เดียวพวกนั้น เพราะงั้นเธอก็เลยคุมโคลอสซัสได้ล่ะมั้ง",
  str_voice_1501001_3 = "บางครั้งพยายามคุยดี ๆ กับพวกหัวทื่อนั่นก็ไร้จุดหมาย แค่สั่งคำสั่งพวกนั้นไปก็พอ",
  str_voice_1501001_4 = "ฉันไม่เคยต้องการให้พวกสัตว์เซลล์เดียวมาช่วย ไม่ว่าจะยากขนาดไหนก็ตาม",
  str_voice_1501001_5 = "ได้กลิ่นอันตรายหรือยัง จากนี้ไปเธอต้องระวังเวลามาหาฉัน",
  str_voice_1501001_6 = "เซอร์ไพร์สเหรอ คนซื่อบื้อ นี่แหละพลังที่แท้จริงของฉัน แต่ฉันไม่ได้สนใจอะไรมันเลย",
  str_voice_1501001_7 = "ตระกูลดันเตสมีหน้าที่เฝ้าสุสานแห่งดวงดารามาตั้งแต่โบราณกาล ฉันไม่มีทางเลือกนอกจากรับภารกิจนั้นสืบต่อมา",
  str_voice_1501001_8 = "พลังของฉันมาจากครอบครัว แต่สิ่งที่ฉันพบเจอตอนนี้... จะกลายเป็นพลังอันมีคุณค่าที่เป็นของฉันแต่เพียงผู้เดียว",
  str_voice_1501001_9 = "หลายคนบอกว่าฉันแต่งงานกับสุสาน แต่สักวันหนึ่งฉันจะออกไปด้วยกำลังของฉันหลังภารกิจเสร็จสิ้น",
  str_voice_1501001_10 = "ไม่มีอะไรทำหรือไง คนซื่อบื้อ อยากเปลี่ยนสถานที่หน่อยไหม มานั่งตรงนี้สิ",
  str_voice_1501001_11 = "ทำงานดี ๆ ไม่ได้หรือไง คนซื่อบื้อ ก็ได้ ฉันจะช่วยเธอเอง",
  str_voice_1501001_12 = "ถ้าพวกนั้นรู้อดีตของฉันแล้วมันทำไมเหรอ พวกนั้นก็ทำได้แค่ถอนหายใจเท่านั้นแหละ",
  str_voice_1501001_13 = "หวังว่าเธอจะไม่ถามคำถามตลอดเวลาเหมือนพวกทึ่มนั่นนะ",
  str_voice_1501001_14 = "อย่าเอาฉันไปรวมกับใคร ฉันชอบสันติและความเงียบ... แต่ฉันไม่ได้บอกว่าให้เธอไปนะ",
  str_voice_1501001_15 = "วันเกิด... ฉันไม่ได้ยินคำนั้นมานานมากแล้ว ถ้างั้นก็... สุขสันต์วันเกิดนะ คนซื่อบื้อ",
  str_voice_1501001_16 = "เลิกทักทายฉันตลอดเวลาสักที ไปทำสิ่งที่เธอควรทำไป คนซื่อบื้อ",
  str_voice_1501001_17 = "ตอนเช้ามันมักจะเงียบอยู่เสมอ แต่พอพวกหัวทึ่มนั่นตื่นก็จะเสียงดังโหวกเหวกมาก",
  str_voice_1501001_18 = "เพลิดเพลินไปกับแสงอาทิตย์ยามบ่ายที่เปล่งประกายไปคนเดียวเสียเถอะ คนซื่อบื้อ ฉันจะพักผ่อนแล้ว",
  str_voice_1501001_19 = "ฉันอยากเพลิดเพลินไปกับค่ำคืนสงบสุขนี้ คนซื่อบื้อ อย่าปล่อยให้พวกสัตว์เซลล์เดียวมากวนฉันล่ะ",
  str_voice_1501001_20 = "คนพวกนั้นดูประหลาดแต่โชคดีที่ไม่ได้มากวนฉัน",
  str_voice_1501001_21 = "ไม่ต้องห่วง ฉันไม่บังคับให้พวกนั้นคิดด้วยสมองที่มีขนาดเท่าสัตว์เซลล์เดียวหรอก",
  str_voice_1501001_22 = "งั้นก็ขอความจริงจงสถิตกับท่าน",
  str_voice_1501001_23 = "สิ่งมีชีวิตน่าอนาถที่ไม่สามารถเทียบเคียงได้แม้แต่สัตว์เซลล์เดียวด้วยซ้ำ",
  str_voice_1501001_24 = "เลดี้วิกตอเรียแข็งแกร่งแต่ความสามารถนางก็ยังห่างชั้นเกินกว่าจะแอบดูความลับของสุสานได้",
  str_voice_1501001_25 = "แพกต์หัวรั้นพอ ๆ กับแหวนแข็ง ๆ ของนางนั่นแหละ เรื่องนี้ฉันไม่เหมือนนางหรอก",
  str_voice_1501001_26 = "ค่ำคืนอันเงียบสงบ มันคงไร้ที่ติถ้ามีสายลมพัดผ่านมาเบา ๆ",
  str_voice_1501001_27 = "ทวีปนี้มีสัตว์เซลล์เดียวน่ารำคาญมากเกินไป",
  str_voice_1501001_28 = "มันเป็นเพื่อนที่ตัวใหญ่มากแต่กลับเงียบสนิทตอนบิน มันเป็นผลงานจากอารยธรรมโบราณจริง ๆ",
  str_voice_1501001_29 = "ฉันคือซิคาเร ผู้ดูแลสุสาน ตกใจเหรอ ฉันหวังว่าตำแหน่งคงไม่ทำให้เธอตกใจ",
  str_voice_1501001_30 = "นี่คือพลังที่แท้จริงของฉัน",
  str_voice_1501001_31 = "ฟาเรียตื่นแล้ว",
  str_voice_1501001_32 = "ฉันกักพลังของสุสานไว้แล้ว",
  str_voice_1501001_33 = "บางที... ฉันอาจจะเป็นอิสระจากที่ฝังศพได้",
  str_voice_1501001_34 = "ฉันต้องการแค่ตัวเองเท่านั้น",
  str_voice_1501001_35 = "แสดงตัวเธอออกมาซิ",
  str_voice_1501001_36 = "ฟาเรีย เตรียมตัวนะ",
  str_voice_1501001_37 = "ฟาเรีย เปิดออก!",
  str_voice_1501001_38 = "ฟาเรีย ปลดปล่อย!",
  str_voice_1501001_39 = "ลมหายใจมรณะ",
  str_voice_1501001_40 = "ลาก่อน สัตว์เซลล์เดียว",
  str_voice_1501001_41 = "ฉันไม่ชินกับการสั่งคนอื่น",
  str_voice_1501001_42 = "เธอมีน้ำยาแค่นี้เหรอ",
  str_voice_1501001_43 = "ฉันจะถ่วงพวกมันไว้",
  str_voice_1501001_44 = "อยากเห็นสุสานของจริงไหม คนซื่อบื้อ",
  str_voice_1501001_45 = "เจ้านี่ไม่เตะตาฉันเลย คนซื่อบื้อ",
  str_voice_1501001_46 = "อืมม มันต้องอย่างนี้สิ",
  str_voice_1501001_47 = "ตระกูลดันเตสจะจดจำของขวัญเธอไว้ คนซื่อบื้อ",
  str_voice_1501001_48 = "เธอ... ขอบคุณนะ",
  str_voice_1501001_49 = "ตระกูลดันเตสไม่ได้อยู่ในบังคับบัญชาของทรู ออเดอร์แต่กลับเป็นพันธมิตรกัน เธอต้องดูความแตกต่างออกแน่นอน",
  str_voice_1501001_50 = "ฟาเรีย... เป็นกุญแจสู่สุสานแห่งดวงดาราและผู้พิทักษ์สุสานเป็นคนเดียวที่ควบคุมมันได้ เธอไม่ต้องรู้เรื่องเจ้านี่มากหรอก ไว้ฉันจะอธิบายให้ฟังถ้าจำเป็น",
  str_voice_1501001_51 = "ตั้งแต่ฉันเกิดมา ภารกิจของฉันก็คือเฝ้าสุสานจนกว่าจะตายหรือ... เกิดใหม่",
  str_voice_1501001_52 = "Alchemy Stars",
  str_voice_1501001_53 = "สวัสดี คนซื่อบื้อ",
  str_voice_1501001_54 = "อรุณสวัสดิ์ คนซื่อบื้อ",
  str_voice_1501001_55 = "อ้าว สวัสดีตอนบ่าย...",
  str_voice_1501001_56 = "เริ่มดึกแล้วสิ ฝันดีนะ คนซื่อบื้อ",
  str_voice_1501001_57 = "สุขสันต์วันปีใหม่",
  str_voice_1500981_1 = "ฉันไม่ได้ตั้งใจจะใส่พริกลงไปในเค้กนะ ฉันนึกว่าพริกจะเป็นเชอร์รี่แบบยาวสักอย่างน่ะ",
  str_voice_1500981_2 = "ดอกไม้สีดำพวกนั้น... สวยมากเลย",
  str_voice_1500981_3 = "ฉันไม่เข้าใจว่าเธอจะพูดว่าอะไร แต่... เธอดูมีความสุขนะ ฉันน่าจะต้องหัวเราะไปพร้อมกับเธอ",
  str_voice_1500981_4 = "ฉันจำไม่ได้เลยว่าฉันเป็นใคร ทำไมถึงมาอยู่ที่นี่ สิ่งเดียวที่รู้คือภารกิจของฉันคือผนึกต้นไม้ต้นนั้น",
  str_voice_1500981_5 = "กลิ่นต้องคำสาปรบกวนจิตใจของผู้มาเยือนทุกคน ปั่นหัวพวกเขาให้เป็นคนหมกหมุ่นที่สุดท้ายแล้วจะกลายเป็นสารอาหารของพวกเรา",
  str_voice_1500981_6 = "วิญญาณที่ปั่นป่วนโผบินอยู่ใกล้ต้นไม้ต้องคำสาป พึมพำคำพูดที่เราไม่เข้าใจ ตั้งใจจะปลดเปลื้องสัมผัสของฉันออก",
  str_voice_1500981_7 = "เธอค่อนข้างแตกต่างกับคนอื่น ฉันไม่ได้รู้สึกแบบนี้มานานแล้ว",
  str_voice_1500981_8 = "บางอย่างทำให้ฉันหวนนึกถึงความทรงจำ แต่ไม่มีเรื่องไหนเลยที่มีจุดจบแสนสุข ขนาดฉันเองยังไม่เข้าใจตัวเองในอดีตเลย",
  str_voice_1500981_9 = "หวังว่าเธอจะเป็นสิ่งแรกที่ฉันเห็น ทุกครั้งที่ตื่นนอนมาเป็นฉันคนใหม่",
  str_voice_1500981_10 = "เงียบจังเลย... เหมือนฉันอยู่โดดเดี่ยว...",
  str_voice_1500981_11 = "ทำเหมือนที่เธอเคยทำนั่นแหละ",
  str_voice_1500981_12 = "ฉันอยากมองดอกไม้พวกนั้นเบ่งบานจากศพอีกสองสามครั้ง... แต่อีสต์วานไม่ยอมให้ฉันทำอย่างที่ตั้งใจ",
  str_voice_1500981_13 = "ไม่ต้องห่วง ฉันไม่มีปัญหาสุขภาพหรอก ไม่เคยมีปัญหาเลย",
  str_voice_1500981_14 = "เคเลสไทต์... ฉันว่าฉันมีความทรงจำเกี่ยวกับพวกเขานะ... พวกเขาถูกฝังลึกไว้ในสมองฉันที่ไหนสักที่ ลึกเสียจนฉันควานหาไม่เจอ",
  str_voice_1500981_15 = "สุขสันต์วันเกิด! ขอให้ทุกวันของเธอมีแต่ความสุข",
  str_voice_1500981_16 = "อย่าลืมหาประโยชน์จากช่วงที่ดีที่สุดของวันล่ะ...",
  str_voice_1500981_17 = "อรุณสวัสดิ์ วันนี้ก็ตั้งใจทำงานต่อไปนะ",
  str_voice_1500981_18 = "กลับมาแล้วนี่ เธอลืมอะไรไว้หรือเปล่า",
  str_voice_1500981_19 = "ฉันไม่ต้องนอนหรอก ไม่ต้องห่วง",
  str_voice_1500981_20 = "อัมบราตันน่ะ... มันอันตรายแต่ก็ทำให้ฉันรู้สึกสบายใจ ฉันว่ามันน่าจะเหมาะกับฉันดีนะ",
  str_voice_1500981_21 = "ฉันพบกับคนจากอิลลูมินาอยู่บ้าง พวกเขาดู... เป็นมิตร",
  str_voice_1500981_22 = "อีสต์วานจับตาดูเธออยู่...",
  str_voice_1500981_23 = "สิ่งมีชีวิตเลวร้าย... ที่สำคัญที่สุดคือ... มันไม่มีอารมณ์เลย...",
  str_voice_1500981_24 = "อีสต์วานมีความเห็นอกเห็นใจมาก นั่นเป็นเหตุผลที่เขามีผู้ติดตามมากมาย",
  str_voice_1500981_25 = "มะ... เหมือนว่าเคลเคนจะไม่ชอบคุยกับฉัน",
  str_voice_1500981_26 = "ดอกไม้ที่เบ่งบานจากศพดึงดูดฉัน แต่ฉันไม่แน่ใจว่านี่เป็นอารมณ์ที่คนรู้สึกเวลาชอบอะไรไหม",
  str_voice_1500981_27 = "ฉันไม่โกรธแค้นอะไรทั้งนั้น สำหรับฉันแล้วก็ไม่ได้มีอะไรต่างกันมากมายขนาดนั้น",
  str_voice_1500981_28 = "โคลอสซัส... ฉันว่าฉันคิดถึงคำนี้ คงจะดีมากถ้าฉันได้คุยกับพวกเขา...",
  str_voice_1500981_29 = "ยินดีที่ได้รู้จัก... ฉันชื่อคุสคูตา ฉันมาจากอัมบราตัน... เป็นทางการเกินไปเหรอ",
  str_voice_1500981_30 = "คำสาปรุนแรงขึ้นแล้ว...",
  str_voice_1500981_31 = "ฉันอดกลั้นได้...",
  str_voice_1500981_32 = "พลังคำสาปกำลังจะเอ่อล้น",
  str_voice_1500981_33 = "ร่างกายนี้กำลังหลับใหล",
  str_voice_1500981_34 = "ฉันอยู่นี่",
  str_voice_1500981_35 = "มีสารอาหารเพียงพอ",
  str_voice_1500981_36 = "ถ้าเธอพร้อม ฉันก็พร้อม",
  str_voice_1500981_37 = "สิ่งนี้จะช่วยลดความกังวลของเธอ",
  str_voice_1500981_38 = "ขอดอกไม้อันงดงามจงเบ่งบานในตัวเธอ",
  str_voice_1500981_39 = "หวนคืนสู่ธุลี...",
  str_voice_1500981_40 = "หลับอย่างสงบ",
  str_voice_1500981_41 = "ฉันจะลองดูสักตั้ง",
  str_voice_1500981_42 = "ที่นี่น่าจะมีดอกไม้ทะเลอยู่บ้างแหละน่า",
  str_voice_1500981_43 = "ฉันต้องการร่างใหม่",
  str_voice_1500981_44 = "ฉันจะจับทัวร์ไปโคลอสซัส เธอมีอะไรที่อยากให้ฉันทำไหม",
  str_voice_1500981_45 = "ขอบใจสำหรับของขวัญนะ",
  str_voice_1500981_46 = "มันดูพิเศษมากเลย",
  str_voice_1500981_47 = "เธอเรียกสิ่งนี้ว่า... เครื่องหมายแสดงความนับถือเหรอ",
  str_voice_1500981_48 = "ใจฉันอบอุ่นขึ้นมาเลย...",
  str_voice_1500981_49 = "ฉันจำไม่ได้ว่าตื่นขึ้นมากี่ครั้งแล้ว ต้องเป็นเหตุผลที่ฉันเสียความทรงจำและอารมณ์ไปมากมายแน่ มันพิสูจน์ได้ว่าฉันตายไปแล้วหลายครั้ง",
  str_voice_1500981_50 = "ฉันกำจัดคนได้แบบเงียบกริบเลยละ เพราะอย่างนั้นอีสต์วานเลยให้ฉันรับหน้าที่ประหารคน ฉันตกลงก็เพราะดอกไม้ที่เบ่งบานจากร่างศพพวกนั้นสวยงามดี",
  str_voice_1500981_51 = "ฉันพยายามคุยเรื่องอื่นกับคนแล้วแต่มันก็ดันยากเกินไป ฉันไม่รู้ด้วยซ้ำว่าต้องพูดอะไร",
  str_voice_1500981_52 = "Alchemy Stars",
  str_voice_1500981_53 = "สวัสดี",
  str_voice_1500981_54 = "อรุณสวัสดิ์ วันใหม่เริ่มขึ้นแล้ว",
  str_voice_1500981_55 = "สวัสดียามบ่าย เธอพักอยู่เหรอ",
  str_voice_1500981_56 = "ฝันดีนะ",
  str_voice_1500981_57 = "สุขสันต์วันปีใหม่ หวังว่าเธอจะเริ่มต้นใหม่พร้อมปีใหม่ที่กำลังมาถึงได้นะ",
  str_voice_1500561_1 = "ฟังให้ดีแล้วก็อดทนไว้ล่ะ หลังจากนั้นเธอฆ่าอิคลิพไซท์คนเดียวได้เลย หืม คนเดียวนี่หมายความว่าไงน่ะเหรอ แปลว่าให้เธอสู้กับพวกมันคนเดียวยังไงล่ะ! ง่ายจะตาย",
  str_voice_1500561_2 = "เคล็ดลับใช้ปืนไรเฟิลคือเล็งไปที่หัวพวกมัน ถ้ายิงไม่โดนก็เข้าไปให้ใกล้ขึ้น ถ้ายังไม่ได้ผลอีก... ก็ลองเอาปืนยัดใส่ปากพวกมันดู",
  str_voice_1500561_3 = "ไม่มีเหตุผลอะไรให้ห่วงเกินเหตุ ห่วงให้น้อยลงเพื่อไม่ให้เป็นภาระของเธอจนตาย ดังนั้น... เฮ้ ไอ้หนู เธอมาทำบ้าอะไรอยู่ตรงนี้ ไม่รู้เหรอว่ามีอิคลิพไซท์อยู่แถวนี้ยั้วเยี้ยไปหมด กลับบ้านไป!",
  str_voice_1500561_4 = "ปืนไรเฟิลล่าสัตว์นี้เป็นของวีรบุรุษตัวจริงที่ใช้ลมหายใจสุดท้ายสู้กับอิคลิพไซท์ เลือดที่แห้งอยู่บนปืนเป็นหลักฐานความกล้าหาญของเขา แล้วฉันก็จะไม่มีวันลืมเลย",
  str_voice_1500561_5 = "ฉันชอบพายุหิมะ เวลาหิมะหมุนวนจะบดบังดวงอาทิตย์และท้องฟ้า ฉันจะรู้สึกปลอดภัยกว่ามาก",
  str_voice_1500561_6 = "นักล่าที่ดีต้องตื่นตัวอยู่เสมอและคอยสังเกตอยู่ตลอดเวลา แม้ในพายุหิมะที่มีทัศนวิสัยแย่หรือค่ำคืนมืดสนิท พวกเขาก็จะไม่มีวันสิ้นหนทาง",
  str_voice_1500561_7 = "ส่วนสูง น้ำหนัก เวลาที่ตาย... ฉันบันทึกทุกรายละเอียดจากเนื้อเยื่อที่เสียหายไปจนถึงแผลที่เล็กที่สุดบนตัวศพ ทำไปแล้วเราไม่ได้เรียนรู้แค่ว่าตายยังไง... แต่เราได้เรียนรู้เรื่องชีวิตด้วย",
  str_voice_1500561_8 = "เธอน่าจะลองฝึกสมาธิในพายุหิมะตอนเครียด ๆ ดูนะ มันช่วยทำให้จิตใจโล่งเวลาพ่ายแพ้ให้กับสายลมและหิมะ มีประโยชน์มากกว่าการนอนหลับเสียอีก",
  str_voice_1500561_9 = "นี่เป็นเพียงแค่ที่พักสั้น ๆ ในการเดินทางเร่ร่อนของฉันเท่านั้น มันแปลก ๆ นะ บอกตรง ๆ... ถึงร่างกายของฉันจะเสื่อมลง หัวใจฉันกลับละลายอย่างอบอุ่นราวกับน้ำแข็ง เพราะเธอทั้งนั้นเลย เจ้าหนู",
  str_voice_1500561_10 = "วันนี้เป็นวันที่ดีนะ ที่หายไปก็มีแค่พายุหิมะเจ๋ง ๆ เท่านั้น... หืม มันแปลกเหรอ",
  str_voice_1500561_11 = "ต้องการความช่วยเหลือเหรอ ได้สิ เธอเองก็เคยช่วยฉันเรื่องบันทึกมาก่อน",
  str_voice_1500561_12 = "บางครั้งฉันก็สเก็ตช์ภาพของอิคลิพไซท์เอาไว้ เพื่อทำให้บันทึกน่าสนใจ",
  str_voice_1500561_13 = "สงสัยเรื่องสมุดของฉันเหรอ ฉันไปเจอในซากโบราณเหมือนกันน่ะ ยังสภาพดีอยู่เลยนะ...",
  str_voice_1500561_14 = "สุนัขล่าเนื้อน่ากลัวกว่าหมาป่าอยู่แล้ว... แต่ถ้าเธอเป็นหมีก็คงไม่มีอะไรให้กลัวนักหรอก",
  str_voice_1500561_15 = "สุขสันต์วันเกิด เจ้าหนู อายุมาพร้อมประสบการณ์และวุฒิภาวะนะ",
  str_voice_1500561_16 = "อ้าว วันนี้เราอารมณ์ดีนะ ว่าไหม",
  str_voice_1500561_17 = "อรุณสวัสดิ์ แผนของวันนี้เริ่มตั้งแต่รุ่งสาง",
  str_voice_1500561_18 = "สายัณห์สวัสดิ์ อย่าลืมทานมื้อเย็นให้ครบหมู่นะ",
  str_voice_1500561_19 = "ทำงานดึกขนาดนั้นเลยเหรอ เธอมาคอยดูอิคลิพไซท์หายากตอนกลางคืนหรือเปล่า",
  str_voice_1500561_20 = "ฉันพบว่านอร์ธแลนด์ปลอดภัยกว่าสถานที่อื่น แต่เธอก็จำเป็นต้องฝึกฝนตัวเองให้ทนต่อความหนาวเย็นด้วย",
  str_voice_1500561_21 = "อิลลูมินาไม่ขาดแคลนทหารที่แท้จริงเลย... ถ้ามีโอกาสฉันก็อยากร่วมกลุ่มพวกเขา",
  str_voice_1500561_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1500561_23 = "สิ่งที่ทำให้ผู้คนตัวสั่นคือ การที่อิคลิพไซท์ดูคล้ายกับออโรเรียนมาก...",
  str_voice_1500561_24 = "ลูอิสก็ชอบบันทึกเหมือนกัน ฉันโชคดีที่ไม่ได้เป็นแค่คนเดียวน่ะ",
  str_voice_1500561_25 = "ราชินีปกป้องนอร์ธแลนด์ด้วยอำนาจทั้งหมดของนาง เป็นเกียรติของฉันที่ได้เกิดที่นั่น",
  str_voice_1500561_26 = "ถ้าฉันมีสมุดอีก ฉันจะเขียนสูตรในการทำอิคลิพไซท์เป็นอาหารอย่างถูกต้อง...",
  str_voice_1500561_27 = "อย่ากินเหลือแม้แต่คำเดียว ไม่อย่างนั้นตอนหิวจริง ๆ จะเสียใจเอานะ",
  str_voice_1500561_28 = "ในโคลอสซัสไม่มีอิคลิพไซท์ใช่ไหม เยี่ยมเลย เรื่องนั้นไม่ได้สำคัญอะไรกับฉันหรอกนะ",
  str_voice_1500561_29 = "การหลงทางเป็นโชคชะตาของนักพเนจร มีเพียงความสันโดษเป็นเพื่อนเท่านั้น เธออยากอ่านสมุดของฉันไหม ฉันจดทุกอย่างที่ฉันเคยเห็นไว้ในสมุดด้วย นั่งสิ แล้วฟังเรื่องเล่าของฉัน...",
  str_voice_1500561_30 = "เพื่อนคนเดียวของนักล่าคือความอดทน!",
  str_voice_1500561_31 = "นักล่าผู้ยิ่งใหญ่ต้องอดทน",
  str_voice_1500561_32 = "\"ผู้ที่ต่อสู้กับสัตว์ประหลาดต้องระมัดระวังไม่ให้ตนกลายเป็นสัตว์ประหลาดเสียเอง\"",
  str_voice_1500561_33 = "ตัดสินใจอย่างแน่วแน่แม้จะไม่มีความหวังที่เส้นชัยก็ตาม",
  str_voice_1500561_34 = "เมื่อตัดสินใจแล้วก็อย่าหันหลังกลับ",
  str_voice_1500561_35 = "ใจเย็นไว้ ตั้งสติให้ดี",
  str_voice_1500561_36 = "ล็อกเป้าหมายและบรรจุกระสุน!",
  str_voice_1500561_37 = "ยิงหนึ่งครั้ง สังหารหนึ่งศพ!",
  str_voice_1500561_38 = "จัดมาเลย เธอกับฉัน!",
  str_voice_1500561_39 = "อย่าขยับ!",
  str_voice_1500561_40 = "หลบไปให้พ้น!",
  str_voice_1500561_41 = "ตามฉันมาถ้าไม่อยากเจ็บตัว!",
  str_voice_1500561_42 = "ชนะแล้ว! เอาเครื่องดื่มออกมาสิ!",
  str_voice_1500561_43 = "นักล่าที่มั่นอกมั่นใจเกินไปก็ไม่ต่างอะไรกับเหยื่อของตัวเอง...",
  str_voice_1500561_44 = "งานนักล่าไม่มีค่าพอให้มาคุยกันหรอก ฉันแค่เขียนเรื่องนั้นลงในสมุดน่ะ เห็นไหม",
  str_voice_1500561_45 = "ของขวัญเหรอ เธอใจดีเกินไปแล้ว...",
  str_voice_1500561_46 = "โอ้ ฉันชอบเจ้านี่นะ!",
  str_voice_1500561_47 = "ขอบคุณ ฉันจะต้องตอบแทนเธอแน่นอน",
  str_voice_1500561_48 = "ฉันอยากได้มันมาตลอดเลย...",
  str_voice_1500561_49 = "ถึงตอนนี้ฉันจะแข็งแกร่งขึ้นแล้ว แต่สมัยเด็ก ๆ ฉันเคยตัวเล็กและอ่อนแอ ถึงอย่างนั้นฉันก็เดินตามพ่อฉันไปยังทุ่งหิมะทุกวัน ฉันก็เลยชอบบันทึกการเดินทางยังไงล่ะ",
  str_voice_1500561_50 = "นอร์ธแลนด์มีพายุหิมะ ทะเลทรายเรดีเซลก็มีพายุทราย ชีวิตก็อย่างนี้... ฉันมีอะไรกันนะ ปืนล่าสัตว์ สมุดโน้ต และเสื้อผ้าเก่าขาดรุ่งริ่งหนึ่งชุดไง",
  str_voice_1500561_51 = "ลูอิสพูดถูก สักวันหนึ่ง การเดินทางของนักพเนจรจะต้องจบลงตรงที่มันควรจะเป็น ฉันมักจะจดจำไว้ในใจด้วยความรักเสมอ... แต่ตอนนี้ฉันยังสนุกกับชีวิตนักพเนจรอยู่เลย",
  str_voice_1500561_52 = "Alchemy Stars",
  str_voice_1500561_53 = "เธออยู่ตรงนั้นไหม",
  str_voice_1500561_54 = "ตื่นเช้าจัง เจ้าหนู",
  str_voice_1500561_55 = "บ่ายนี้ได้พักบ้างไหม",
  str_voice_1500561_56 = "แต่เธอพอจะมีเวลาไหม",
  str_voice_1500561_57 = "สุขสันต์วันปีใหม่! ฉันจับบางอย่างมาให้เธอเลยนะ",
  str_voice_1600931_1 = "เธอจะให้ฉันเรียนรู้ตัวเธอไหม ชิลแล็กซ์ ทั้งหมดที่เธอต้องทำคือนอนเฉย ๆ",
  str_voice_1600931_2 = "โคลอสซัสเยี่ยมไปเลยว่าไหม เพราะมัน ฉันก็เลยไม่ต้องปวดหัวแล้วว่าจะงีบที่ไหนดี",
  str_voice_1600931_3 = "ทำไมนักวิจัยวิทยาศาสตร์อิลลูมินาทุกคนถึงอายุน้อย ๆ ทั้งนั้นเลยละ งั้นก็เรียกวิเวียนมาที่นี่เลย",
  str_voice_1600931_4 = "สาวรับใช้ของลิลินเยี่ยมไปเลยว่าไหม ฉันจะหามาสักคนได้เหมือนกันไหมนะ อย่างนั้นฉันจะได้ไม่ต้องหาอะไรกินเองแล้ว",
  str_voice_1600931_5 = "อย่าดูถูกกรอนรูเพราะว่านางตัวเล็กเชียว ทักษะของนางยอดเยี่ยมอย่างไม่ต้องสงสัยเลยละ แต่ที่สำคัญกว่านั้น... หุ่นนางก็ดีกว่าที่ฉันจินตนาการไว้โขเลย!",
  str_voice_1600931_6 = "การปรากฏตัวของเธอสร้างความปั่นป่วนพอตัว แต่ก็คิดไว้แล้วว่าน่าจะเป็นแบบนั้น",
  str_voice_1600931_7 = "ฉันชอบเธอนะ เจ้าหนู ให้ฉันแยกส่วนเธอหน่อยดีไหม",
  str_voice_1600931_8 = "อย่าลืมใจเย็นอยู่เสมอล่ะ อย่างนั้นเธอจะได้เห็นว่าอะไรสำคัญที่สุดในช่วงเวลาที่เร่งด่วนที่สุด",
  str_voice_1600931_9 = "ฉันเพิ่งสร้างห้องทดลองใหม่ในโคลอสซัสของเธอ ฉันจะได้ทำวิจัยชีววิทยาที่ไหนก็ได้ยังไงล่ะ",
  str_voice_1600931_10 = "อากาศดีมากจนฉันอยากหาที่งีบเลย",
  str_voice_1600931_11 = "มีอะไรน่าสนใจก็มาเรียกฉันแล้วกัน ฉันไม่ชอบเรื่องน่ารำคาญกวนใจเล็ก ๆ น้อย ๆ น่ะ",
  str_voice_1600931_12 = "ฉันสงสัยอยู่นะว่าเธอใช้เวลา 17 ปีที่นี่ยังไง ว่างเมื่อไหร่ก็บอกฉันนะ",
  str_voice_1600931_13 = "ที่นี่ไม่มีเครื่องดื่มแอลกอฮอล์เหรอ อัมบราตันเป็นที่เดียวที่ฉันหาเหล้าได้หลังจากเขมือบของปันส่วนหมดแล้ว",
  str_voice_1600931_14 = "ฉันไม่สนหรอกว่าคนอื่นคิดว่าฉันเป็นยังไง ฉันแค่อยากมีความสุขเท่านั้น",
  str_voice_1600931_15 = "สุขสันต์วันเกิด เจ้าหนู เธอว่าไง การทักทายนี้เต็มเปี่ยมไปด้วยความรู้สึกไหม",
  str_voice_1600931_16 = "ถ้ามีใครมาตามหาฉัน บอกไปเลยว่าฉันยุ่งอยู่ บาย",
  str_voice_1600931_17 = "อรุณสวัสดิ์ เจ้าหนู ฉันจะไปนอนต่อล่ะนะ",
  str_voice_1600931_18 = "หมดวันอันแสนสงบสุขแล้ว ถือว่าเป็นข่าวดีนะ",
  str_voice_1600931_19 = "หืม ไม่ยักรู้มาก่อนว่าเธอขยันทำงานมาก",
  str_voice_1600931_20 = "อิลลูมินาอาจจะแข็งแกร่งแต่ก็แข็งทื่อมากเกินไปหน่อย ตราบใดที่มันไม่ส่งผลกับงานวิจัยของฉันก็ไม่สำคัญหรอก",
  str_voice_1600931_21 = "อัมบราตันมีฝูงชนผสมปนเปกัน มันเป็นที่ซึ่งคนจะอยู่รอดได้ด้วยความสามารถเท่านั้น",
  str_voice_1600931_22 = "ขออิลลูมินาจงเจิดจำรัส",
  str_voice_1600931_23 = "สิ่งมีชีวิตที่น่าสนใจและน่าเวทนา ฉันสนใจทฤษฎีวิวัฒนาการของมันมาก",
  str_voice_1600931_24 = "ไม่คิดว่าคารอนตลกเหรอ ถ้ารู้จักกันดีก็น่าจะรู้สึกอย่างนั้นนะ",
  str_voice_1600931_25 = "เนเมซิสเป็นเด็กน่ารักนะ คุ้มค่ากับการแกล้ง",
  str_voice_1600931_26 = "ทุกคนมีคุณค่าเป็นของตัวเอง ฉันพยายามศึกษาเรื่องนั้นอยู่",
  str_voice_1600931_27 = "ฉันนึกว่าพวกนั้นทำทุกอย่างในอิลลูมินาแบบไม่ยืดหยุ่นมากพอแล้ว แต่เหมือนว่าลูโมโพลิสจะแย่ยิ่งกว่าเสียอีก",
  str_voice_1600931_28 = "ฉันเรียกมันว่าของโบราณแล้วผิดตรงไหนล่ะ ของอย่างนี้เป็นสิ่งที่นักวิทยาศาสตร์ทุกคนอยากศึกษาทั้งนั้น",
  str_voice_1600931_29 = "ไม่นึกเลยว่าจะได้เจอเคเลสไทต์ที่ยังมีชีวิตอยู่ เรื่องราวชักจะน่าสนใจขึ้นมาแล้วสิ",
  str_voice_1600931_30 = "การแข็งแกร่งขึ้นไม่ใช่สิ่งเลวร้ายหรอก",
  str_voice_1600931_31 = "ก้าวไปข้างหน้า ไปยังเป้าหมายที่ยิ่งใหญ่กว่า",
  str_voice_1600931_32 = "มันคุ้มค่าจะตาย",
  str_voice_1600931_33 = "ฉันจะต้องรู้ทุกเรื่องให้ได้",
  str_voice_1600931_34 = "ถ้าเธอว่างั้นนะ",
  str_voice_1600931_35 = "พร้อมไหม",
  str_voice_1600931_36 = "สลักไว้ในความทรงจำ",
  str_voice_1600931_37 = "เถ้าถ่านสู่เถ้าถ่าน ธุลีสู่ธุลี",
  str_voice_1600931_38 = "เป็นสักขีพยานแก่ทุกสรรพสิ่ง",
  str_voice_1600931_39 = "คมดาบผ่าทะลวงลำคอ!",
  str_voice_1600931_40 = "สู้ไปก็ไม่มีประโยชน์",
  str_voice_1600931_41 = "ได้เวลาออกกำลังกายแล้ว",
  str_voice_1600931_42 = "ดูท่าฉันจะต้องกลับไปพักนะ",
  str_voice_1600931_43 = "ก็มีบ้าง ไม่ใช่เรื่องร้ายแรงหรอก",
  str_voice_1600931_44 = "สนใจวิจัยของฉันเหรอ?",
  str_voice_1600931_45 = "ไม่เลว",
  str_voice_1600931_46 = "เธอนี่เอาใจใส่เหมือนกันนะ",
  str_voice_1600931_47 = "เธอมีจินตนาการนะ",
  str_voice_1600931_48 = "มันมีประโยชน์สำหรับฉัน ขอบใจนะ",
  str_voice_1600931_49 = "ยังมีอีกหลายเรื่องในโลกที่อธิบายไม่ได้ และการศึกษาเรื่องพวกนั้นคืองานตลอดชีวิตของฉัน",
  str_voice_1600931_50 = "เหตุการณ์ที่เมืองใต้ดินหมายเลข 9 ยังคงหลอกหลอนฉัน ฉันยังเลิกคิดถึงความว่างเปล่าที่มันสร้างขึ้น เวลาที่ฉันถูกหลอมรวมเข้ากับดาบกระดูกพุ่งทะยานไม่ได้เลย",
  str_voice_1600931_51 = "จงมีความสุขกับชีวิตในตอนที่ยังสุขได้ ฉันเห็นด้วยกับคำกล่าวนี้นะแต่ฉันก็ยังสงสัยเรื่องเมืองแกนน่อนอยู่ เพราะฉันคอยจับตาดูทุกส่วนของเมืองแล้วก็เลยได้นั่งผ่อนคลายน่ะ",
  str_voice_1600931_52 = "Alchemy Stars",
  str_voice_1600931_53 = "สวัสดี ไงจ๊ะ",
  str_voice_1600931_54 = "เป็นเช้าที่สดใสจัง!",
  str_voice_1600931_55 = "ได้เวลางีบแล้ว",
  str_voice_1600931_56 = "ได้เวลาเข้านอนแล้ว",
  str_voice_1600931_57 = "สุขสันต์วันปีใหม่ ขอให้สนุกกับวันนี้นะ!",
  str_voice_1600961_1 = "เสื้อผ้าพวกนี้กันน้ำหมดเลย ไม่จำเป็นต้องกังวลว่าจะได้รับผลกระทบจากพลังต่าง ๆ หรอก คงจะมีแค่เส้นผมที่ต้องลำบากหน่อย",
  str_voice_1600961_2 = "ฉันถังแตกแล้ว ฉันควรไปยืมเงินคุณเชโอลเพิ่มอีกหน่อยไหมนะ... แต่นางมักจะเอนตัวพิงกับโต๊ะทำให้ฉันหงุดหงิดอยู่เรื่อยเลย",
  str_voice_1600961_3 = "ชีวิตในอัมบราตันมันลำบาก ฉันเริ่มคิดถึงบ้านที่อิลลูมินาแล้ว",
  str_voice_1600961_4 = "ฉันต้องหากาบริเอลแล้วถามเรื่องปู่ของฉัน...",
  str_voice_1600961_5 = "ช่วงนี้ฉันพบว่าตัวเองใช้สายน้ำอันขุ่นมัวได้เชี่ยวชาญมากขึ้น มันยากที่จะสร้างสมดุลให้ความสามารถของฉันในการควบคุม...",
  str_voice_1600961_6 = "ฉันควรเรียนรู้ผลข้างเคียงที่มาพร้อมกับความสามารถนี้ ปัญหาก็คือไม่มีใครรู้เลยว่ามันใ้ช้งานยังไง ฉันทำอะไรไม่ได้นอกจากนั่งลงแล้วปล่อยให้ความสับสนซึมซับเข้าไปในใจ",
  str_voice_1600961_7 = "เธอเป็นเด็กจริงใจ ฉันสัมผัสได้",
  str_voice_1600961_8 = "ไว้ฉันเลี้ยงกาแฟเธอบ้างนะ... เดาว่าเธอไม่ชอบกาแฟขม ฉันก็เลยเตรียมน้ำตาลมาให้ด้วย",
  str_voice_1600961_9 = "เคยรู้สึกแบบนี้มาก่อนไหม แบบที่ทำให้รู้สึก... ถึงความชั่วร้ายค่อย ๆ รุกล้ำเข้ามาในร่างกายและจิตใจน่ะ\nฉันกลัวว่าฉันจะเสียเวลาทำเรื่องที่ไม่สำคัญมากเกินไปทั้งที่น่าจะใช้พลังให้มีประสิทธิภาพมากกว่านี้!\nอ่า... ไม่สิ ช่างมันเถอะ",
  str_voice_1600961_10 = "ฉันแค่อยากพักผ่อนสบาย ๆ ที่ไหนสักที่น่ะ",
  str_voice_1600961_11 = "ฉันเหรอ ฉันอาจจะทำเสียเรื่องได้นะ เธอพิจารณาให้ดีอีกครั้งเถอะ...",
  str_voice_1600961_12 = "ฉันเปลี่ยนแปลงห้องเพื่อที่มันจะได้มีโครงสร้างที่สมมาตร ตอนนี้อยู่แล้วสบายขึ้นเยอะเลย",
  str_voice_1600961_13 = "ไม่คิดเลยว่าในโคลอสซัสจะกว้างขวางขนาดนี้ ฉันกังวลว่าฉันอาจจะหลงทางเอา...",
  str_voice_1600961_14 = "ฉันเลี้ยงแมวได้ไหม ฉันจะดูแลมันอย่างดีเลย ขอร้องล่ะ",
  str_voice_1600961_15 = "สุขสันต์วันเกิด หวังว่าเธอจะตั้งใจทำงานต่อไปในปีที่จะมาถึงนี้นะ",
  str_voice_1600961_16 = "ได้เวลาทำงานแล้ว ขอดูหน่อยว่ามีงานอะไรให้ทำไหม...",
  str_voice_1600961_17 = "อรุณสวัสดิ์ เธอเป็นคนตื่นเช้าสินะ",
  str_voice_1600961_18 = "ได้เวลาชมสิ่งบันเทิงใจแล้ว เราได้วางแผนอะไรไว้ไหม?",
  str_voice_1600961_19 = "นอนดึกมันไม่ดีหรอกนะ ลองนอนเร็ว ๆ ดูสิ...",
  str_voice_1600961_20 = "ฉันไม่ชอบอัมบราตันแต่ก็ไม่มีทางเลือก... ฉันต้องผ่านที่นี่เพื่อไปลูโมโพลิส",
  str_voice_1600961_21 = "อิลลูมินาเป็นที่ที่ดี มันดีที่ได้เห็นทุกคนทำงานเพื่อเป้าหมายเดียวกัน...",
  str_voice_1600961_22 = "ฉันมาพร้อมสายน้ำอันขุ่นมัว",
  str_voice_1600961_23 = "ทำไมเจ้าพวกนี้ต้องมีจริงด้วยเนี่ย...",
  str_voice_1600961_24 = "อาเรียเป็นเด็กที่โตแล้ว นางเป็นคนพิเศษจริง ๆ ฉันอยากช่วยเธอให้มากที่สุดเท่าที่จะทำได้",
  str_voice_1600961_25 = "ถ้าไม่ใช่เพราะคุณเชโอล ฉันคงไม่รอดในอัมบราตันไปแล้ว",
  str_voice_1600961_26 = "แมวน่ารัก โดยเฉพาะแมวดำ! ฉันชอบดวงตาพวกมัน...",
  str_voice_1600961_27 = "ตอนฉันไปถึงอัมบราตันครั้งแรก ฉันเจอคนเลวหลอกฉันเยอะ แล้วฉันก็ไม่อยากเห็นหน้าพวกมันอีก",
  str_voice_1600961_28 = "อย่างนี้... ฉันควรเข้าและออกลูโมโพลิสได้ตามใจสิ...",
  str_voice_1600961_29 = "ไง รู้จักกาบริเอล คนที่ใช้ชีวิตในลูโมโพลิสไหม...",
  str_voice_1600961_30 = "พลังของน้ำอันมืดดำเพิ่มขึ้นแล้ว",
  str_voice_1600961_31 = "เมล็ดพันธุ์แห่งความวุ่นวายเบ่งบานขึ้นแล้ว",
  str_voice_1600961_32 = "สายตาฉันเบลอขึ้น",
  str_voice_1600961_33 = "เป็นแรงกระตุ้นที่ต้านทานไม่ได้...",
  str_voice_1600961_34 = "ฉันจะพยายามอย่างที่สุด...",
  str_voice_1600961_35 = "ฉันพร้อมเสมออยู่แล้ว",
  str_voice_1600961_36 = "อย่าฝืนสิ...",
  str_voice_1600961_37 = "จงท่วมท้น",
  str_voice_1600961_38 = "จมลงไปยังห้วงอเวจี",
  str_voice_1600961_39 = "ฉันจะช่วยเอง",
  str_voice_1600961_40 = "หวังว่าเจ้านี่จะได้ผลจริง ๆ",
  str_voice_1600961_41 = "ฉันไม่ได้มีคุณสมบัติเป็นกัปตัน",
  str_voice_1600961_42 = "ฟิ้ว... ง่ายกว่าที่คิดไว้นะ",
  str_voice_1600961_43 = "อย่าท้อถอยเกินไปล่ะ เข้าใจไหม",
  str_voice_1600961_44 = "มีอะไรให้ช่วยบ้าง ฉันจะพักสักหน่อย...",
  str_voice_1600961_45 = "โอ้ ขอบคุณนะ",
  str_voice_1600961_46 = "นี่มัน... ขอบคุณนะ",
  str_voice_1600961_47 = "ขอบคุณนะ ฉันมีความสุขมากเลย",
  str_voice_1600961_48 = "รู้ได้ยังไงว่าฉันชอบสิ่งนี้...",
  str_voice_1600961_49 = "ฉันนับถือปู่ของฉัน เลยอยากรู้เหตุผลที่เขากลับบ้านมาช่วยเจ้ากาบริเอลนี่...",
  str_voice_1600961_50 = "ตอนฉันมาที่อัมบราตันครั้งแรกก็มีชีวิตลำเค็ญ เงินทั้งหมดของฉันถูกโกง นึกไม่ออกเลยว่าฉันจะเป็นยังไงถ้าไม่เจอคุณเชโอล...",
  str_voice_1600961_51 = "ฉันต้องแกร่งขึ้นเพื่อควบคุมพลัง แล้วห้ามไม่ให้สัมผัสของฉันถูกมันกลืนกินอีกครั้ง",
  str_voice_1600961_52 = "หืม Alchemy... Stars?",
  str_voice_1600961_53 = "สวัสดี",
  str_voice_1600961_54 = "เป็นเช้าที่สดใสจัง!",
  str_voice_1600961_55 = "อยากพักเที่ยงหน่อยไหม",
  str_voice_1600961_56 = "อย่าลืมนอนเร็ว ๆ นะ",
  str_voice_1600961_57 = "สุขสันต์วันปีใหม่...",
  str_voice_1401021_1 = "ว่าไง ขออนุญาตนะ ถ้าไม่มีอะไรแล้วก็อย่ามายุ่งกับฉันเลย",
  str_voice_1401021_2 = "โคลอสซัสไม่ได้เป็นเพียงสัตว์ประหลาดตัวเดียวที่บินอยู่บนท้องฟ้า เห็นเกาะลอยน้ำนั่นไหม เธอต้องมีเรือเหาะถึงจะไปที่นั่นได้",
  str_voice_1401021_3 = "ฉันไม่ชอบติดต่อผู้คน มีคนน่ารำคาญเยอะเกินไป... เอาเถอะ ทำไมฉันต้องพูดถึงเรื่องนี้ด้วยล่ะ",
  str_voice_1401021_4 = "ตอนฉันอยู่คนเดียว ฉันมีเวลาคิดมากขึ้น แล้วฉันก็ได้คิดอะไรหลาย ๆ อย่างที่ปกติไม่ได้คิดถึงด้วย",
  str_voice_1401021_5 = "เธอเคยไตร่ตรองความหมายของพลังนี้ไหม บางทีฉันก็คิดเกี่ยวกับทุกสิ่งที่เรามี อย่างกับว่าสิ่งเหล่านี้เป็นคำสาปมากกว่าของขวัญ",
  str_voice_1401021_6 = "ชีวิตที่ต้องต่อสู้ไปทั่วไม่น่าสนใจเท่าที่ฉันคิด อาจเป็นเพราะว่าฉันไม่เคยเป็นเด็กชอบสู้จนกระทั่งวันนั้น",
  str_voice_1401021_7 = "เธอเป็นคนดี ฉันชักสนใจชาวเคเลสไทต์แล้วล่ะ แต่ว่าคนอื่น ๆ ยังไงก็เถอะ... โอ๊ะ ฉันไม่ได้หมายถึงแบบนั้น อย่าถือสาเลยนะ",
  str_voice_1401021_8 = "ฉันไม่ได้รู้สึกอะไรมากมายในชีวิต ฉันเลยให้คำแนะนำเธอไม่ได้... แค่ดูแลตัวเองให้มากขึ้นแล้วกัน",
  str_voice_1401021_9 = "ฉันมีเพื่อนไม่กี่คนแต่เราทุกคนเข้าใจกันและกันดีมาก ฉันต้องการอย่างนั้นแหละ",
  str_voice_1401021_10 = "ฟู่... ชีวิตมันง่ายอย่างนี้นี่เอง...",
  str_voice_1401021_11 = "ก็ได้ ฉันไม่รู้ว่าฉันควรต้องทำอะไร แต่ยังไงฉันก็จะทำแล้วกัน",
  str_voice_1401021_12 = "ฉันจะไปพักผ่อนแล้ว ถ้ามีอะไรอยากคุยกับฉันก็ไว้คุยกันทีหลังนะ",
  str_voice_1401021_13 = "เพื่อนตัวเป้งนั่น... เขาชื่อโซรอซใช่ไหม ฉันอยากคุยกับเขานะ",
  str_voice_1401021_14 = "ที่นี่เงียบกว่าที่ฉันเคยอยู่เยอะเลย ฉันไม่ค่อยชินน่ะ",
  str_voice_1401021_15 = "สุขสันต์วันเกิด ฉันไม่ได้ทำอะไรให้เธอเลย แต่แค่มีเจตนาดีก็นับแล้วใช่ไหมล่ะ",
  str_voice_1401021_16 = "อ้าว เธอมาแล้วเหรอ ตอนนี้ยังไม่มีอะไรเกิดขึ้นที่นี่ ฉันก็เลยมีช่วงเวลาที่สบายมากเลยละ",
  str_voice_1401021_17 = "เธอทำงานหนักมากจริง ๆ แต่เธอก็ควรจำไว้ว่าต้องรักษาสมดุลระหว่างงานกับชีวิตที่พอดีกันด้วยนะ",
  str_voice_1401021_18 = "ใจเย็นน่า เธอเลิกงานแล้ว",
  str_voice_1401021_19 = "อยากทำให้ตัวเองล้าจนไม่อยากทำงานเหรอ ยังไงฉันก็ไม่ห้ามเธอหรอก...",
  str_voice_1401021_20 = "อัมบราตันน่ะวุ่นวายแต่ก็เหมาะกับคนนอกรีตอย่างเรา",
  str_voice_1401021_21 = "ฉันไม่ชอบวิธีที่ชนชั้นสูงทำอะไรต่าง ๆ แต่ลูโมโพลิสก็เป็นที่ที่เหมาะกับพวกเขาดี",
  str_voice_1401021_22 = "แชโดว์เฝ้ามอง... ทุกสิ่ง",
  str_voice_1401021_23 = "บางทีพวกมันก็อาจไม่รู้ว่าสู้กับพวกเราทำไมเหมือนกัน",
  str_voice_1401021_24 = "เดย์นาน่ะ... ทำอะไรไม่คิดถึงใจคนอื่น แต่นั่นก็เป็นวิธีที่นางใช้ปกป้องโรบิน",
  str_voice_1401021_25 = "ฉันพูดเวลาที่จำเป็นแต่โรบินมักจะเงียบตลอดเลย",
  str_voice_1401021_26 = "ฉันชอบอะไรน่ะเหรอ เห็นลูกอมในปากของฉันไหม ฉันชอบทุกรสเลยละ",
  str_voice_1401021_27 = "ฉันไม่ชอบคำอวดเก่งใหญ่โตหรือผักชีโรยหน้า เพราะอย่างนั้นฉันเลยไม่ชอบพวกชนชั้นสูงบางคนในลูโมโพลิส",
  str_voice_1401021_28 = "ฉันคิดว่าโคลอสซัสเป็นแค่ตำนาน สุดท้ายแล้วฉันก็ไม่เคยเห็น",
  str_voice_1401021_29 = "ฉันชื่อเทสซา บอกตามตรง การที่เราร่วมมือกันสำคัญอย่างมาก แต่ฉันก็หวังให้เธอจัดการแต่เรื่องตัวเองไป\nแล้วฉันก็จัดการแต่เรื่องของฉัน",
  str_voice_1401021_30 = "เจ๋งอยู่นะนี่",
  str_voice_1401021_31 = "ควบคุมพลังนี้ได้ยากมากเลย",
  str_voice_1401021_32 = "ถ้าฉันหลุดการควบคุมพลัง ก็คงเป็นข่าวร้ายสำหรับศัตรูสิว่าไหม",
  str_voice_1401021_33 = "สายฟ้าพึ่งออกจากมือฉันล่ะ ฮ่า ๆ",
  str_voice_1401021_34 = "ไม่มีทางอื่นแล้ว",
  str_voice_1401021_35 = "เร็วดุจสายฟ้า",
  str_voice_1401021_36 = "ลองกันสักตั้งเถอะ",
  str_voice_1401021_37 = "แบบนี้คงเจ็บนิดหน่อยล่ะนะ",
  str_voice_1401021_38 = "อิเล็กโทรไลซ์!",
  str_voice_1401021_39 = "เบาเกินไป",
  str_voice_1401021_40 = "ฉันจัดการเอง",
  str_voice_1401021_41 = "พยายามสู้สักนิด",
  str_voice_1401021_42 = "แหม เครื่องฉันติดแล้วล่ะ",
  str_voice_1401021_43 = "อย่างนี้สิถึงจะน่าสนใจ",
  str_voice_1401021_44 = "เธอมาทำอะไรที่นี่ อยากชิมกระแสไฟฟ้าสักหน่อยหรือไง",
  str_voice_1401021_45 = "ของดีนะนี่ ฉันรับไว้เอง",
  str_voice_1401021_46 = "ฉันไม่คิดว่าเธอจะเข้าใจฉันจริง ๆ",
  str_voice_1401021_47 = "ฉันจะจำไว้ว่าเธอดีกับฉันมาก",
  str_voice_1401021_48 = "ฉันรู้ว่าเธอรู้ ว่าฉันชอบอ่ะ...",
  str_voice_1401021_49 = "ฉันไม่เคยคิดใช้พลังทำลายใครมาก่อนเลย ยิ่งคนจากลูโมโพลิสยิ่งแล้วใหญ่ บอกตามตรงนะ ฉันไม่เข้าใจความเกลียดชังที่ริชาร์ดพูดถึงเลยละ",
  str_voice_1401021_50 = "คนส่วนใหญ่คิดว่าฉันเกลียดลูโมโพลิสแต่มันไม่ใช่เรื่องจริง ริชาร์ดที่เลี้ยงดูฉันมาเป็นคนเกลียดลูโมโพลิส แต่เขาไม่เคยส่งความเกลียดชังนั้นมาถึงฉันเลย",
  str_voice_1401021_51 = "ฉันต้องการให้พลังนี้ปกป้องตัวฉันจริง ๆ แต่ดูจากที่พลังของฉันเติบโตขึ้นแล้วก็รู้สึกว่างเปล่าอย่างบอกไม่ถูก มีหนทางจบทุกอย่างนี้หรือเปล่า",
  str_voice_1401021_52 = "Alchemy Stars",
  str_voice_1401021_53 = "เฮ้",
  str_voice_1401021_54 = "อรุณสวัสดิ์",
  str_voice_1401021_55 = "เธอติดนิสัยชอบงีบหลับตอนกลางวันเหรอ",
  str_voice_1401021_56 = "ฝันดีนะ หลับให้สบายล่ะ",
  str_voice_1401021_57 = "สุขสันต์วันปีใหม่ หวังว่าทุกคนจะเติบโตขึ้นไม่ทางใดก็ทางหนึ่ง",
  str_voice_1500711_1 = "เพื่อนเหรอ ทำไมถึงคิดว่าฉันต้องการเพื่อนด้วยล่ะ ถึงฉันจะเคยมีเพื่อนคนหนึ่งสมัยเป็นเด็กก็เถอะ...",
  str_voice_1500711_2 = "มันก็ต้องมีค่าคอมอยู่แล้ว เท่าไหร่เหรอ ก็ขึ้นอยู่กับเนื้องานน่ะ",
  str_voice_1500711_3 = "อย่าคิดเชียวว่างานจิปาถะมันง่าย... ฉันต้องรับมือกับคนประหลาดตลอดเวลา อย่างหมอนั่นที่มีหมากับเจ้านั่นที่มีหนวดน่ะ",
  str_voice_1500711_4 = "พลังฉันแข็งแกร่งขึ้นแน่นอน แต่ฉันยังห่างไกลกับการพบความลับในสร้อยนั่น",
  str_voice_1500711_5 = "ไม่มีใครที่งานจิปาถะจะทำงานกู้โลกกับเธอหรอก ดังนั้นเลิกพูดแล้วก็เลิกมองหาได้แล้ว",
  str_voice_1500711_6 = "โลกใบนี้ไม่มีความเท่าเทียม ถ้าที่ไหนมีคนก็ไม่มีความเท่าเทียมหรอก",
  str_voice_1500711_7 = "เธอนี่เป็นเด็กที่แปลกจริง ๆ แต่ฉันก็ไม่ได้ไม่ชอบอะไรเธอหรอก",
  str_voice_1500711_8 = "เธอไม่เหมือนพวกบ้าทางตะวันออกไกลเลย อะไรนะ แปลกที่ฉันชมเธองั้นเหรอ งั้นก็รับคำชมไปสิ",
  str_voice_1500711_9 = "มีไม่กี่คนในอัมบราตันที่เต็มใจสร้างสัมพันธ์กับคนอื่น ทุกคนมีอย่างสองอย่างรั้งเอาไว้เสมอ ทำให้คิดเรื่องอื่นนอกจากการเอาตัวรอดได้ยากมาก",
  str_voice_1500711_10 = "ไม่มีอะไรทำหรือไง หรือยุ่งอยู่จริง ๆ อ่ะ เจ้าหนู",
  str_voice_1500711_11 = "อยากให้ฉันคอยเฝ้าระวังให้เหรอ เข้าใจล่ะ งานจิปาถะก็ต้องทำทุกอย่างนั่นแหละ",
  str_voice_1500711_12 = "พอเลย เธอเห็นมาพอแล้ว หรืออยากลองนี่ดูล่ะ?",
  str_voice_1500711_13 = "ถ้าเธอมีเวลาว่างเยอะนัก ก็ควรไปทำธุระของตัวเอง",
  str_voice_1500711_14 = "ฉันต้องหาความลับของสร้อยคอนี้ให้เร็วที่สุด",
  str_voice_1500711_15 = "วันเกิดเหรอ เธอจ้างงานฉันให้ไปตะโกนอวยพรได้นะ คราวนี้ฟรีไม่คิดค่าใช้จ่าย",
  str_voice_1500711_16 = "เธอมีจิตใจที่ดี เจ้าหนู อยากช่วยฉันทำงานไหมล่ะ ยังไงเธอก็ได้ค่าจ้างอยู่แล้ว",
  str_voice_1500711_17 = "เธอจะหลับอีกนานไหม เจ้าหนู ลุกได้แล้วถ้าเธอต้องทำงานจิปาถะ!",
  str_voice_1500711_18 = "มาเถอะ มาดื่มกับฉัน ฉันเลี้ยงเอง เธอจะดื่มน้ำผลไม้ก็ได้ ฉันไม่สนใจหรอก",
  str_voice_1500711_19 = "เธอนี่เป็นคนมีฝีมือมากจริง ๆ ป่านนี้แล้วยังทำงานหนักอยู่อีก อยากมาดื่มกับฉันไหม",
  str_voice_1500711_20 = "อัมบราตันเป็นสถานที่รวบรวมข่าวที่ดีแล้วก็ไม่มีใครพูดจาไร้สาระด้วย ฉันชอบนะ",
  str_voice_1500711_21 = "ฉันจะเข้าร่วมเรดีเซล เวรนช์หลังเจอความลับของสร้อยคอ ฉันค่อนข้างเอ็นดูคนพวกนั้นน่ะ",
  str_voice_1500711_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1500711_23 = "พวกเศษขยะที่ไม่มีไหวพริบเลยสักนิด ไม่มีค่าพอที่จะพูดถึงหรอก",
  str_voice_1500711_24 = "อีสต์วานดูแลอัมบราตันได้ดีมากจริง ๆ มีเขาอยู่แล้วที่นี่สงบสุขพอสมควรเลยละ",
  str_voice_1500711_25 = "ฉันสงสัยว่าเด็กผู้หญิงผมสีชมพูตัวน้อยคนนั้นเป็นยังไงบ้าง อ่า ช่างมันเถอะน่า ฉันต้องไม่คิดเรื่องนั้นสิ",
  str_voice_1500711_26 = "ชีวิตนี้มีเหล้าให้ดื่มตลอดก็พอแล้ว",
  str_voice_1500711_27 = "ที่นี่มีพนักงานชั่วคราวอยู่ไม่กี่คน แต่ฉันไล่พวกเขาออกไปแล้วเพราะพูดมากเกิน",
  str_voice_1500711_28 = "หมอนี่ตัวใหญ่เกินไป ฉันหาทางอ้อมไปไม่ได้เลย แล้วมันก็มีห้องที่เหมือนกันเยอะเต็มไปหมด",
  str_voice_1500711_29 = "มีอะไรจะว่าจ้างให้ฉันทำไหม เจ้าหนู ขอไม่เอางานยิบย่อยนะ มีงานหลายอย่างที่งานจิปาถะต้องทำมากเกินไปในหนึ่งวัน ฉันก็เลยต้องเรื่องมากหน่อยน่ะ",
  str_voice_1500711_30 = "ไม่เลว",
  str_voice_1500711_31 = "หืม ก็ไม่เห็นมีอะไรนอกจากของเล่นเด็ก",
  str_voice_1500711_32 = "ฉันใกล้เจอ... ความลับของสร้อยคอแล้ว",
  str_voice_1500711_33 = "เลือดสูบฉีด... นานมาแล้วที่ฉันไม่ได้ไฟติดแบบนี้",
  str_voice_1500711_34 = "อ้อ จะเอาแบบนี้ใช่ไหม",
  str_voice_1500711_35 = "คราวนี้แหละ",
  str_voice_1500711_36 = "ระวังนะ!",
  str_voice_1500711_37 = "เผาให้หมด!",
  str_voice_1500711_38 = "เผาทุกอย่างให้เป็นจุณ!",
  str_voice_1500711_39 = "มันจบแล้ว",
  str_voice_1500711_40 = "ช้าเกินไป!",
  str_voice_1500711_41 = "ฉันไม่ชินกับการนำทีม",
  str_voice_1500711_42 = "มันไม่ยากเลยด้วยซ้ำ",
  str_voice_1500711_43 = "แพ้เหรอ ก็เป็นส่วนหนึ่งของชีวิตประจำวันแหละน่า",
  str_voice_1500711_44 = "ถ้าเธอมีอะไรจะพูดก็พูดมาเลย เลิกลีลาได้แล้ว",
  str_voice_1500711_45 = "นี่จะติดสินบนฉันเหรอ",
  str_voice_1500711_46 = "เธอนี่ตามีแววนะเนี่ย",
  str_voice_1500711_47 = "ฉันจะรับไว้ ขอบคุณนะ",
  str_voice_1500711_48 = "นี่มัน! ขอบใจ เจ้าหนู",
  str_voice_1500711_49 = "โลกนี้ไม่เป็นมิตรกับผู้ที่แตกต่าง บางคนก็ถูกปฏิบัติอย่างเลวร้ายแค่เพราะหน้าตา แต่ในอัมบราตันถือว่า็ดีกว่ามาก",
  str_voice_1500711_50 = "จนถึงวันนี้ ช่วงเวลาที่ฉันอยู่ในตะวันออกไกลก็ยังเหมือนเพิ่งผ่านไปไม่นาน คำสอนของอาจารย์ยังดังก้องอยู่ในใจฉัน แล้วก็มีเด็กผู้หญิงผมสีชมพูคนนี้ที่ฉันห่วงใยอย่างประหลาด",
  str_voice_1500711_51 = "สร้อยคอนี้... เป็นสิ่งที่ฉันพกติดตัวมาตั้งแต่จำความได้ เป็นสมบัติของพ่อแม่ฉันและยังเป็นแหล่งพลังของฉันด้วย มีความลับมากมายเบื้องหลังมันแต่ฉันยังไม่รู้อะไรเลย",
  str_voice_1500711_52 = "Alchemy Stars",
  str_voice_1500711_53 = "เฮ้",
  str_voice_1500711_54 = "เธอตื่นเช้าจัง เจ้าหนู",
  str_voice_1500711_55 = "ฉันชอบง่วงตอนกลางวันตลอดเลย",
  str_voice_1500711_56 = "นอนได้แล้ว เจ้าหนู อย่านอนดึกล่ะ",
  str_voice_1500711_57 = "สุขสันต์วันปีใหม่นะ เจ้าหนู คูปองส่วนลดนี่ของเธอ",
  str_voice_1500971_1 = "ช่วยผู้ป่วยเหรอ ก็ผ่านมานานแล้วล่ะ... แถมบางอย่างก็ไม่คุ้มค่าให้ช่วยด้วย",
  str_voice_1500971_2 = "มีดผ่าตัดที่ทำมาจากน้ำแข็งและหิมะ ดังนั้นมันจะไม่สร้างความเจ็บปวดเท่าไหร่เวลาที่แทงเข้าไปในร่างกายของเธอ อยากลองดูสักครั้งไหม",
  str_voice_1500971_3 = "ฉันทำเควสต์อะไรเสร็จบ้างเหรอ ก็เยอะเลย ถ้าอยากรู้ ฉันทดสอบกับเธอได้นะ",
  str_voice_1500971_4 = "สิ่งสำคัญของการผ่าตัดเหรอ น่าจะเป็นการผ่าตัดที่แม่นยำนะ",
  str_voice_1500971_5 = "ฉันอาจจะกลับไปเป็นหมอหลังความมืดมิดในอัมบราตันถอยห่างออกไป ก่อนหน้านั้นฉันจะต้องทำการผ่าตัด ผ่าตัดอัมบราตันน่ะ",
  str_voice_1500971_6 = "ครั้งหนึ่งฉันเคยช่วยผู้คนมากมายด้วยมีดผ่าตัดของฉัน ตอนนี้ฉันหวังว่าจะกลายเป็นมีดผ่าตัดของอัมบราตันและตัดส่วนที่เป็นเนื้อตายของมันทิ้ง",
  str_voice_1500971_7 = "เคเลสไทต์เหรอ น่าสนใจนะ ขอศึกษาร่างกายเธอได้ไหม ฉันอยากรู้ว่าเคเลสไทต์จะมีส่วนสำคัญเหมือนออโรเรียนปกติไหม... ฮ่า ๆ ล้อเล่นน่ะ",
  str_voice_1500971_8 = "ถ้าเธอต้องผ่าตัดก็มาหาฉันได้ ฉันหยุดฝึกวิชาแพทย์แล้ว แต่ทักษะของฉันแม่นยำกว่าแต่ก่อนมาก ทำไมน่ะเหรอ เป็นความลับน่ะ",
  str_voice_1500971_9 = "ยิ่งฉันเห็นผู้ป่วยมากเท่าไหร่ก็ยิ่งรู้ว่าชีวิตเปราะบางมากแค่ไหน อีกทั้งยังเข้าใจวิธีการรักษาหรือการปล่อยให้พวกเขาไปสบายได้ดียิ่งขึ้นด้วย",
  str_voice_1500971_10 = "อยากเรียนรู้อะไรใหม่ ๆ เพราะเธอเอาแต่นั่งเฉย ๆ งั้นเหรอ อยากรู้ไหมว่ากระดูกสันหลังข้อที่สิบสามอยู่ตรงไหน",
  str_voice_1500971_11 = "อยากให้ฉันช่วยเหรอ แต่บอกก่อนนะว่าฉันทำไปเพื่อเจ้าแห่งเงาเท่านั้น",
  str_voice_1500971_12 = "ผ่าหัวใจเหรอ ฟื้นชีพคนจากความตายไม่ได้ง่ายอย่างนั้นหรอก",
  str_voice_1500971_13 = "ช่วยชีวิตคนไม่ขัดกับการฆ่าคนหรอก ทั้งหมดก็เป็นรูปแบบการกระทำตามความเชื่อของคนที่ต่างกันออกไปน่ะ",
  str_voice_1500971_14 = "ผ่าจากมุมที่ดีที่สุด... อ้อ ไม่ต้องห่วงหรอก เส้นเลือดใหญ่เปราะบางมากจนเธอจะผ่ายังไงก็ได้ตามใจเลยละ",
  str_voice_1500971_15 = "สุขสันต์วันเกิด ผู้นำทาง อธิษฐานวันเกิดหรือยัง",
  str_voice_1500971_16 = "เธอดูฟื้นพลังเต็มที่แล้วนะ อย่าลืมล้างมือบ่อย ๆ เพื่อป้องกันไม่ให้ล้มป่วยด้วยล่ะ",
  str_voice_1500971_17 = "ตื่นเช้านั้นดีต่อสุขภาพ ฉันเดาว่ามันก็ดีสำหรับเคเลสไทต์เหมือนกัน",
  str_voice_1500971_18 = "ถึงเวลามื้อเย็นแล้ว อย่าทำงานตอนท้องว่างล่ะ มันเป็นอันตรายได้",
  str_voice_1500971_19 = "ยังทำงานอยู่หรือเปล่า นอนดึกจะเพิ่มความเสี่ยงเสียชีวิตจากกล้ามเนื้อหัวใจตายได้ พักผ่อนได้แล้วนะ",
  str_voice_1500971_20 = "อัมบราตันมีแต่ความอึกทึกครึกโครมและความบ้าคลั่ง เพราะอย่างนั้นเลยต้องผ่าตัดพิเศษยังไงล่ะ",
  str_voice_1500971_21 = "ฝึกฝีมือแพทย์ในลูโมโพลิสก็คงไม่เลว แต่อาจจะน่าเบื่อไปหน่อย",
  str_voice_1500971_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1500971_23 = "ฉันเคยเชื่อว่าช่วยชีวิตทุกอย่างได้ นอกจากอิคลิพไซท์",
  str_voice_1500971_24 = "เขาคงไม่ใช่เซลูซิดถ้าคิดวิธีการอื่นออกนอกจากการต่อสู้...",
  str_voice_1500971_25 = "เจ้าแห่งเงาแสดงให้ฉันเห็นวิธีการใช้ชีวิตแบบใหม่และนำผู้ป่วยใหม่ ๆ มาให้ฉัน",
  str_voice_1500971_26 = "ไฟที่อยู่ในเตาผิงมักจะทำให้จิตใจฉันสงบลงเสมอ ได้เห็นไฟแบบนี้ตอนกลางคืนอันแสนยาวนานก็ช่วยปลอบประโลมจิตใจได้",
  str_voice_1500971_27 = "บาดแผล หนอง เลือดออกก็จี้แผลให้ไหม้ดีกว่า หากรักษาอย่างถูกต้องไม่ได้",
  str_voice_1500971_28 = "มีบาดแผลเก่าบนโคลอสซัสเยอะมาก เธอจะทำความสะอาดมันเมื่อไหร่เหรอ ฉันช่วยได้นะ",
  str_voice_1500971_29 = "ทำไมมาถามฉันล่ะ ฉันเป็นหมอที่สามารถทำการผ่าตัดได้ก็จริงแต่ฉันเปลี่ยนสายอาชีพแล้ว... ตอนนี้ฉันเป็นมือสังหารน่ะ",
  str_voice_1500971_30 = "ฉันควรไปผ่าอะไรสักหน่อย",
  str_voice_1500971_31 = "ฉันคงต้องพัฒนาฝีมือผ่าตัดหน่อยแล้ว",
  str_voice_1500971_32 = "มีดหมอเล่มนี้คมยิ่งกว่าเดิมอีก",
  str_voice_1500971_33 = "ถึงยังไงฉันก็ไม่เคยลืมหน้าที่หมอหรอกนะ",
  str_voice_1500971_34 = "คนไหนเป็นคนไข้ล่ะเนี่ย",
  str_voice_1500971_35 = "เตรียมการผ่าตัด",
  str_voice_1500971_36 = "ไม่ต้องห่วงนะ คนไข้ วางใจได้เลย",
  str_voice_1500971_37 = "เดี๋ยวยาก็ออกฤทธิ์แล้ว!",
  str_voice_1500971_38 = "โรคเรื้อรังจงมลายหายไป!",
  str_voice_1500971_39 = "ดาบน้ำแข็ง แช่แข็ง",
  str_voice_1500971_40 = "ต้องตัดตรงไหนต่อล่ะเนี่ย",
  str_voice_1500971_41 = "เอาละ คราวนี้ฉันจะเป็นหมอผ่าตัดหลัก",
  str_voice_1500971_42 = "การผ่าตัดผ่านไปด้วยดี",
  str_voice_1500971_43 = "การรักษาโรคเรื้อรังต้องใช้เวลา ตอนนี้ยังไม่ใช่เวลาเหมาะสมที่จะรักษา",
  str_voice_1500971_44 = "นี่ฉันกำลังมองหาอะไรอยู่ หัวใจของเธอสินะ",
  str_voice_1500971_45 = "อ่า ขอบใจนะ",
  str_voice_1500971_46 = "หืม ขอบใจมากเลย",
  str_voice_1500971_47 = "ดูดีนะเนี่ย ฉันจะรับไว้ละกัน",
  str_voice_1500971_48 = "ขอบคุณนะ ฉันจะถนอมอย่างดี",
  str_voice_1500971_49 = "บาดแผลที่อิคลิพไซท์ทิ้งไว้บางทีก็รักษายาก สมัยเรียนแพทย์ที่เมืองลูโมโพลิส ฉันต้องใช้ความพยายามอย่างหนักเพื่อจัดการกับพวกมัน ดีนะที่ฝีมือฉันเก่งพอตัว",
  str_voice_1500971_50 = "มีดผ่าตัดของฉันช่วยผู้คนไว้มากมาย แต่ไม่ใช่กับพ่อแม่ของฉัน ถึงอย่างนั้นก็เถอะ มันไม่ได้ผลกับพวกอิคลิพไซท์ ฉันก็เลยต้องใช้มีดอย่างอื่นแทน",
  str_voice_1500971_51 = "โรคเรื้อรังของอัมบราตันไม่มีทางรักษาให้หายด้วยวิธีปกติ มันต้องได้รับการแก้ไขและซ่อมแซมเพื่อรอความหวังใหม่ก่อเกิดขึ้นมา จนกว่าจะถึงตอนนั้นฉันจะทำให้ดีที่สุด",
  str_voice_1500971_52 = "Alchemy Stars",
  str_voice_1500971_53 = "เฮ้",
  str_voice_1500971_54 = "อรุณสวัสดิ์",
  str_voice_1500971_55 = "เฮ้ ผู้นำทาง",
  str_voice_1500971_56 = "สายัณห์สวัสดิ์ เธอยังไม่นอนเหรอ",
  str_voice_1500971_57 = "สุขสันต์วันปีใหม่ ผู้นำทาง",
  str_voice_1500241_1 = "- เคเลสไทต์คือใครเหรอ\n- พวกนั้นคือเผ่าที่แตกต่างจากออโรเรียน",
  str_voice_1500241_2 = "- เคเลสไทต์ต่อสู้เก่งไหม\n- ฉันไม่คิดว่างั้นนะ",
  str_voice_1500241_3 = "- ฟังนะ ฝั่งนี้เป็นอาณาเขตของฉัน\n- โง่ชะมัด",
  str_voice_1500241_4 = "- ฉันเกือบจะเอาชนะนายได้แล้วเชียว\n- เธอไม่ใช่คนเดียวที่เก่งขึ้นหรอกนะ เจ้าเด็กเนิร์ด",
  str_voice_1500241_5 = "- บอกตามตรง ฉันไม่สนใจเรื่องเลื่อนขั้นหรอก แค่ได้สู้ก็พอใจแล้ว\n- เธอน่าจะคิดถึงอนาคตให้มาก ๆ หน่อย",
  str_voice_1500241_6 = "- ฮ่า ฮ่า ฮ่า ฉันเก่งที่สุด!\n- ถึงยังไงฉันก็คือที่สุดของที่สุด",
  str_voice_1500241_7 = "- ถึงเธอจะสู้ไม่ได้ แต่เธอก็นิสัยดี\n- อย่าไปฟังเธอมาก",
  str_voice_1500241_8 = "- ได้เวลาแสดงฝีมือแล้ว คุโระ\n- โชว์ให้เคเลสไทต์ได้เห็นความพ่ายแพ้ซะ",
  str_voice_1500241_9 = "- ฉันไม่มีอะไรทำ... เอ่อ... ไม่มีอะไรให้ฉันทำเหรอ\n- อย่านอนโง่ ๆ อยู่บนเตียงแบบนั้นสิ",
  str_voice_1500241_10 = "- เบื่อชะมัดเลย\n- เงียบ ๆ หน่อย",
  str_voice_1500241_11 = "- มีการต่อสู้ให้ฉันลุยบ้างไหม!\n- มันก็แค่หน้าที่ปกติ",
  str_voice_1500241_12 = "- อย่าแตะต้องของของฉันโดยไม่ได้รับอนุญาตนะ\n- ทำไมล่ะ เธอก็มาใช้ของฉันเหมือนกันนี่นา",
  str_voice_1500241_13 = "- เฮ้ ระหว่างเราคิดว่าใครแข็งแกร่งกว่าเหรอ\n- อย่าลากคนที่ไม่เกี่ยวข้องเข้ามายุ่งสิ",
  str_voice_1500241_14 = "- บางครั้งฉันก็คิดว่าการที่ฉันมาอยู่ในโคลอสซัสมันหรูหรามากเกินไป\n- เธอเริ่มอีกแล้วนะ",
  str_voice_1500241_15 = "- สุขสันต์วันเกิด!\n- เฮ้ ฉันพูดก่อนนะ!\n- เอาไงก็เอาเถอะ",
  str_voice_1500241_16 = "ปกติระหว่างวันเธอมักทำอะไร นี่ฉันเพิ่งฝึกเสร็จมาหมาด ๆ เลย",
  str_voice_1500241_17 = "เธอตื่นเช้ากว่าเจ้าเนิร์ดนั่นอีก",
  str_voice_1500241_18 = "- ฉันรู้สึกคึกมากตอนกลางคืน!\n- สงสัยคงต้องยอมแพ้ให้กับเจ้านกฮูกคืนนี้เสียแล้ว",
  str_voice_1500241_19 = "การนอนหลับที่มีคุณภาพคือหนึ่งในเกณฑ์ของการรักษาสุขภาพที่ดี เพราะฉะนั้นตอนนี้เธอก็ควรไปนอนได้แล้ว",
  str_voice_1500241_20 = "- ฉันรู้สึกยังไงกับอิลลูมินาน่ะเหรอ ไม่รู้สึกอะไรสักนิด เพราะฉันไม่รู้อะไรเลยเกี่ยวกับที่นั่น\n- ความเป็นหนึ่งคือสิ่งที่ทำให้อิลลูมินาดูพิเศษ",
  str_voice_1500241_21 = "- ฉันชอบอัมบราตันมากกว่าลูโมโพลิส มันไม่ค่อยมีอะไรสวย ๆ งาม ๆ\n- เรื่องนี้ฉันเห็นด้วย",
  str_voice_1500241_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1500241_23 = "- ไม่มีใครรู้ว่าพวกเขามาจากไหน\n- ทำไมพวกเขาถึงเลือกออโรเรียน ฉันไม่เข้าใจเลย",
  str_voice_1500241_24 = "- นายพลบาร์ตันเป็นคนกล้าหาญ\n- ฉันจะเอาเขาเป็นแบบอย่าง!",
  str_voice_1500241_25 = "- ไวท์ดวาร์ฟน่ะเหรอ ก็แค่เพื่อนร่วมทางที่น่าเบื่ออีกคน\n- แต่ละคนก็ต่างกันไป",
  str_voice_1500241_26 = "- ฉันชอบต่อสู้และการเอาชนะ\n- ฉันก็ชอบเอาชนะเหมือนกัน",
  str_voice_1500241_27 = "- มีแต่พวกขี้ขลาดเท่านั้นเหละที่ใช้วิธีสู้แบบสกปรก\n- พวกมันไม่มีศักดิ์ศรีเอาซะเลย",
  str_voice_1500241_28 = "- ตัวใหญ่เบ้อเร่อเลย! ต้องแข็งแกร่งมากแน่\n- ฉันตกใจมากที่เห็นตัวเองในอดีต",
  str_voice_1500241_29 = "- หวัดดี ยินดีที่ได้รู้จัก\n- ที่นี่ใครแข็งแกร่งที่สุด โชว์ตัวออกมา!",
  str_voice_1500241_30 = "งั้นก็ดี เตรียมตัว!",
  str_voice_1500241_31 = "ฉันแข็งแกร่งขึ้นแล้ว!",
  str_voice_1500241_32 = "เป็นการตัดสินใจที่มีเหตุผลมาก",
  str_voice_1500241_33 = "- สมบูรณ์แบบ!\n- สมบูรณ์แบบมาก!",
  str_voice_1500241_34 = "รับทราบ!",
  str_voice_1500241_35 = "มาอาละวาดกันเถอะ!",
  str_voice_1500241_36 = "ตัดสินใจเลือกเวลาที่เหมาะสมให้ดีล่ะ",
  str_voice_1500241_37 = "กัดฟันเอาไว้!",
  str_voice_1500241_38 = "- ได้เวลาแล้ว\n- ลุย!",
  str_voice_1500241_39 = "ตูม!",
  str_voice_1500241_40 = "ฮ่าฮ่าฮ่าฮ่าฮ่า!",
  str_voice_1500241_41 = "- ฉันคือกัปตัน!\n- ทำตัวดี ๆ หน่อย",
  str_voice_1500241_42 = "- ง่ายเหมือนปอกกล้วย!\n- ภารกิจสำเร็จ",
  str_voice_1500241_43 = "- มันเผาฉัน!\n- ดีนะที่พวกเรารอดมาได้",
  str_voice_1500241_44 = "- หืม อยากเจอฉันหรือว่าเธอล่ะ\n- ให้ช่วยอะไรไหม",
  str_voice_1500241_45 = "ขอบใจที่เป็นห่วงนะ ผู้นำทาง",
  str_voice_1500241_46 = "นั่นแหละ! รู้ใจฉันจริง ๆ",
  str_voice_1500241_47 = "ไม่เลวนี่ ฉันจะรับไว้ละกัน",
  str_voice_1500241_48 = "ฉันจะรักษาไว้อย่างดี ขอบใจนะ",
  str_voice_1500241_49 = "- เฮ้อ จู่ ๆ ก็นึกถึงช่วงเวลาที่ฉันเข้าร่วมกับอิลลูมินาเป็นครั้งแรก\n- ตอนนั้นเธอดื้อมากเลย\n- ว่าไงนะ!",
  str_voice_1500241_50 = "- การต่อสู้ของเราจบลงด้วยผลเสมอกันมากขึ้นเรื่อย ๆ ถ้ายังเป็นแบบนี้ต่อไป อีกไม่นานฉันต้องเอาชนะเธอได้แน่!\n- ฝันไปเหอะ",
  str_voice_1500241_51 = "- เธอมักไม่รู้สึกถึงอันตรายรอบตัวเวลาต่อสู้ แบบนั้นมันเสี่ยงมากเลยละ\n- ออกไปจากหลังของฉันนะ! ที่เป็นแบบนั้นเพราะว่าฉันไม่ได้สู้ด้วยตัวเองไง",
  str_voice_1500241_52 = "Alchemy Stars!",
  str_voice_1500241_53 = "เฮ้ เธอ!",
  str_voice_1500241_54 = "อรุณสวัสดิ์ วันนี้เธอดูพักผ่อนเต็มอิ่มนะ",
  str_voice_1500241_55 = "หลังจากกินมื้อเที่ยง มันก็แบบหนังท้องตึงหนังตาหย่อน",
  str_voice_1500241_56 = "ถึงเวลาแล้วที่ทหารคนเก่งจะต้องไปนอน",
  str_voice_1500241_57 = "- สุขสันต์วันปีใหม่!\n- ขอให้ปีนี้มีแต่สิ่งดี ๆ\n- เลิกแย่งบทพูดของฉันเสียที!",
  str_voice_1601031_1 = "ดูนาฬิกาทรายน่ารัก ๆ นี่สิ ฉันสร้างเองเลยนะ สวยเปล่า... ฉันทำอะไรได้มากกว่าแค่การสอบสวนนักโทษนะ น่าแปลกใจใช่ป่ะ",
  str_voice_1601031_2 = "อยากเห็นดวงตาที่อยู่ใต้ที่ปิดตานี่เหรอ ไม่เคยมีใครขอแบบนี้มาก่อนเลย... เอาจริงแน่นะ",
  str_voice_1601031_3 = "รู้ไว้ด้วยนะว่าฉันเก่งเรื่องทำให้คนอื่นร้องไห้ แหงสิ ก็ตอนที่ฉันประหารชีวิตผู้คนไง จะเป็นตอนไหนได้อีกล่ะ",
  str_voice_1601031_4 = "คนอื่นมักบอกฉันว่าฉันไม่เข้าใจเรื่องถูกผิด แล้วอะไรคือเรื่องที่ถูกต้องล่ะ มันสำคัญมากนักเหรอที่ต้องขีดเส้นระหว่างความดีและความชั่ว ฉันแค่ทำในสิ่งที่ฉันมีความสุขไม่ได้เหรอ",
  str_voice_1601031_5 = "ฉันคิดว่าโคลอสซัสคือสถานที่ที่น่าสนใจ แต่ที่นี่ดูน่าเบื่อไปหน่อย เธอมีใครที่อยากให้ถูกประหารไหม",
  str_voice_1601031_6 = "ลูกศิษย์มือขวาของฉันจะทำให้เธอต้องตกที่นั่งลำบาก และฉันก็สามารถทำแบบนั้นได้ด้วยไทจุตสึของฉัน",
  str_voice_1601031_7 = "โอ้... ดูเหมือนเธอจะไม่รู้ว่าฉันอันตรายแค่ไหน ถึงกล้าเดินเข้ามาหาฉันแบบนี้...",
  str_voice_1601031_8 = "ฉันชอบทรมานคน แต่ไม่ต้องห่วง... ตอนนี้มีเธออยู่ด้วย ฉันจะทำตัวอ่อนหวานขึ้นหน่อยละกัน",
  str_voice_1601031_9 = "ในเมื่อเธอสงสัยมาก... ฉันก็จะโชว์ของให้ดู... แต่ห้ามจับล่ะ ฉันไม่อยากให้เธอต้องคำสาป",
  str_voice_1601031_10 = "ฉันลืมเหตุผลไปแล้วล่ะ แต่ฉันสามารถรู้สึกได้",
  str_voice_1601031_11 = "ก็เธออยากให้ฉันทำ... ในเมื่อเธอยืนกรานขนาดนี้ ก็ช่วยยืนห่าง ๆ ออกไปหน่อย ฉันจะเอาที่ปิดตาออก",
  str_voice_1601031_12 = "รู้ไหมว่าฉันอยากถามอะไร... วิกตอเรียอยู่ที่นี่รึเปล่า",
  str_voice_1601031_13 = "ใช่แล้วละ ฉันชอบเลือดมาก แต่ก็ไม่ได้แปลว่าฉันไม่อยากมีห้องที่สะอาดและเป็นระเบียบ",
  str_voice_1601031_14 = "ฉันล่ะสงสัยว่าเธอจะทำเสียงแบบไหนในห้องสอบสวน แต่คงไม่ต้องล่ะมั้ง",
  str_voice_1601031_15 = "ของขวัญวันเกิดเหรอ เธออยากไป... เดินชมรอบ ๆ ห้องสอบสวนของฉันไหมล่ะ",
  str_voice_1601031_16 = "กลับมาแล้วเหรอ... เอ่อ เธออยากรู้ว่าฉันมีแผนจะทำอะไรต่องั้นเหรอ ก็งานที่รออยู่ในห้องสอบสวนไงล่ะ",
  str_voice_1601031_17 = "ช่างรื่นรมย์อะไรเช่นนี้... ตื่นมาตอนเช้าก็ได้ยินเสียงกรีดร้องอันไพเราะจากห้องสอบสวนเป็นสิ่งแรก",
  str_voice_1601031_18 = "แม้ว่าฉันจะอยากทำงานต่อ แต่วิกตอเรียบอกว่าการพักผ่อนให้เพียงพอก็เป็นเรื่องสำคัญเหมือนกัน",
  str_voice_1601031_19 = "การสอบสวนตอนกลางคืนมักมาพร้อมกับเรื่องที่น่าประหลาดใจ... หืม? เธอก็นอนไม่หลับเหมือนเหรอ",
  str_voice_1601031_20 = "จริง ๆ แล้ว... ฉันก็ไม่ได้สนใจนักหรอก แต่ไม่ว่าวิกตอเรียจะมีเป้าหมายอะไร มันก็คือเป้าหมายของฉันเหมือนกัน",
  str_voice_1601031_21 = "เมื่อได้เจอกับตาข้างขวาของฉัน แม้แต่พวกที่มาจากลูโมโพลิสก็ต้องกรีดร้องด้วยความเจ็บปวด",
  str_voice_1601031_22 = "งั้นก็ขอให้ความจริงจงสถิตกับท่าน",
  str_voice_1601031_23 = "พวกนั้นไม่สมควรได้รู้สึกเหนื่อยด้วยซ้ำ แค่ประหารพวกมันไปซะ",
  str_voice_1601031_24 = "วิกตอเรียอ่อนไหวและสุภาพเกินไป เรื่องใช้ความรุนแรงต้องยกให้คนอย่างฉันนี่",
  str_voice_1601031_25 = "ฉันควรจัดการเจ้านั่นที่คอยวนเวียนรอบ ๆ วิกตอเรียให้ได้ลิ้มรสหายนะ",
  str_voice_1601031_26 = "เลือด เสียงกรีดร้อง ความเจ็บปวด... วิเศษสุด ๆ!",
  str_voice_1601031_27 = "ทำไมทุกคนถึงต้องคอยตีกรอบฉันด้วย แค่วิกตอเรียคนเดียวก็พอแล้ว",
  str_voice_1601031_28 = "ที่นี่มีหลายห้องจัง... ฉันเอาห้องหนึ่งไว้ใช้สอบสวนได้ไหม",
  str_voice_1601031_29 = "ยุ่งยากชะมัด... ฉันชื่อเอซี่ ปกติฉันมักบอกชื่อตัวเองระหว่างสอบสวน แต่วิกตอเรียบอกฉันว่าการแนะนำตัวคือมารยาททั่วไป...",
  str_voice_1601031_30 = "หา... แค่นั้นอ่ะนะ",
  str_voice_1601031_31 = "มองเข้าไปยังความกลัวที่อยู่ลึกข้างใน!",
  str_voice_1601031_32 = "ดวงตาว่างเปล่ากำลังจับจ้องเธออยู่",
  str_voice_1601031_33 = "จงพบกับนรกมืด!",
  str_voice_1601031_34 = "เสียงกรีดร้องและเลือด...",
  str_voice_1601031_35 = "ดวงตาว่างเปล่า!",
  str_voice_1601031_36 = "เริ่มสอบสวนกันเลยไหม",
  str_voice_1601031_37 = "มองเข้าไปยังหายนะ!",
  str_voice_1601031_38 = "ไม่ว่าใครหน้าไหนก็หนีไม่พ้น!",
  str_voice_1601031_39 = "เจ็บใช่ไหม ร้องออกมาเลย!",
  str_voice_1601031_40 = "ขวัญผวา!",
  str_voice_1601031_41 = "อยากให้ฉันเป็นคนนำเหรอ พวกมันจบเห่แน่",
  str_voice_1601031_42 = "นี่ืคือรสชาติของความกลัว!",
  str_voice_1601031_43 = "ขอโทษนะ วิกตอเรีย...",
  str_voice_1601031_44 = "ชู่ว! สบตาฉันแล้วบอกสิว่าเธอไปทำอะไรมา",
  str_voice_1601031_45 = "ดูเหมือนเธอจะไม่รู้จักฉันดีพอ",
  str_voice_1601031_46 = "รู้ได้ยังไงว่าฉันชอบสิ่งนี้...",
  str_voice_1601031_47 = "นึกไม่ถึงเลยว่าเธอจะคิดแบบนี้ ฉันแปลกใจนะเนี่ย...",
  str_voice_1601031_48 = "ฉันไม่เคยคิดว่านอกจากวิกตอเรียแล้วจะยังมีคนที่เข้าใจฉัน!",
  str_voice_1601031_49 = "ฉันมาจากสายเลือดต้องคำสาป... ใครก็ตามที่จ้องตรงมองดวงตาว่างเปล่าจะต้องจมสู่ความกลัวและความบ้าคลั่ง พ่อแม่ของฉันก็ไม่มีข้อยกเว้น และมันทำให้พวกเขาต้องจบชีวิตไป",
  str_voice_1601031_50 = "วิกตอเรียสร้างที่ปิดตานี้ให้ฉัน มันคือไอเทมที่เอาไว้ใช้ยับยั้งพลังต้องคำสาปของดวงตาว่างเปล่า... เธอยังไม่รู้เรื่องนี้สินะ",
  str_voice_1601031_51 = "ฉันไม่รังเกียจหรอกที่มีพลังแบบนี้ ฉันไม่ถือสาที่ต้องเป็นคนสอบสวนและมือประหาร ถึงยังไงสิ่งที่ทำให้ฉันมีความสุขก็คือ เลือดและเสียงโหยหวน...",
  str_voice_1601031_52 = "Alchemy Stars",
  str_voice_1601031_53 = "เธอทำอะไรอยู่น่ะ",
  str_voice_1601031_54 = "นี่เธอหลับตลอดเวลาที่ฉันอยู่ในห้องสอบสวนเลยเหรอ",
  str_voice_1601031_55 = "การสอบปากคำกระตุ้นต่อมหิวได้ดีเลยละ อยากลองดูไหม",
  str_voice_1601031_56 = "วันนี้เหนื่อยพอแล้ว ราตรีสวัสดิ์",
  str_voice_1601031_57 = "ปีใหม่ งั้นก็แปลว่าว่าฉันจะได้ห้องสอบสวนที่โคลอสซัสเหรอ",
  str_voice_1500991_1 = "แม้ว่าฉันจะต้องเกิดมาพร้อมคำสาป แต่ก็ยังมีเรื่องดี ๆ อยู่บ้าง เพราะคำสาปทำให้ฉันเดินบนหนามได้... อืม พลังของฉันค่อนข้างจะเกี่ยวข้องกับหนาม ทำนองนั้นน่ะ",
  str_voice_1500991_2 = "ฉันไม่รู้สึกว่าดาบเวทมนตร์นี้หนักเลยสักนิด เพราะว่าฉันมีพวกหนามสีดำคอยแบ่งเบาน่ะสิ...หือ? ได้ไงน่ะเหรอ ก็แบบว่า เอ่อ... ไม่รู้จะอธิบายยังไงเหมือนกัน",
  str_voice_1500991_3 = "ดาบเวทมนตร์ตั้งชื่อตามดวงจันทร์ มันมีพลังลึกซึ้ง และฉันไม่อาจแยกจากมันได้ นั่นก็อาจทำให้ฉันลึกซึ้งได้เช่นกัน...",
  str_voice_1500991_4 = "ไม่เป็นไร ฉันจะหาทางทำลายคำสาปก่อนที่พลังของมันจะทำลายฉัน",
  str_voice_1500991_5 = "หนามพวกนี้มีอยู่เพื่อปกป้องตัวมันเอง มันคือหนามแบบเดียวกับที่ปกคลุมดาบเวทมนตร์รึเปล่า ทำไมมันมาพร้อมกับคำสาป แล้วทำไมถึง... ให้พลังกับฉัน",
  str_voice_1500991_6 = "ฉันต่อสู้เพื่ออะไร ฉันอดทนเพื่ออะไร ฉันเริ่มต้นการเดินทางเพื่ออะไร ฉันถามคำถามเหล่านี้กับตัวเองครั้งแล้วครั้งเล่า แต่คำตอบนั้นง่ายมาก ฉันแค่อยากมีชีวิตอยู่ต่อไป...",
  str_voice_1500991_7 = "กรุณาอย่าแตะต้องดาบเวทมนตร์ ฉันไม่อยากให้เธอมีปัญหา ทางที่ดีก็อยู่ให้ห่างด้วย ฉันไม่อยากให้เธอต้องเจ็บตัว",
  str_voice_1500991_8 = "ฉันทำงานเพียงคนเดียวได้ดีที่สุด แต่ก็ไม่เลวนะถ้าจะสร้างสายสัมพันธ์กับคนอื่นแบบนี้...",
  str_voice_1500991_9 = "ฉันไม่กล้าอยู่ใกล้เธอ เพราะฉันหวงแหนเธอ หวังว่าเธอเข้าใจนะ... ฉันอยู่ตรงนี้ ที่ไหนสักแห่ง ที่ไม่ไกลจากเธอ",
  str_voice_1500991_10 = "13, 14, 15... อ้อ ฉันกำลังนับหนามที่อยู่บนร่างกายน่ะ บางทีฉันก็ชอบทำแบบนี้ฆ่าเวลา และสำรวจเจ้าหนามเพลิน ๆ",
  str_voice_1500991_11 = "ปล่อยให้ฉันจัดการเอง ฉันรับมือได้ทุกเรื่อง... เอ้อ แค่ให้ฉันอยู่ที่นี่เองเหรอ... ง่ายกว่างานปกติที่ฉันทำอีก",
  str_voice_1500991_12 = "ฉันต้องดูแลเสื้อผ้าให้ดี ๆ เพราะว่าเหลือตัวสุดท้ายแล้ว... อ้าว ตรงนี้ขาดตั้งแต่ตอนไหนเนี่ย",
  str_voice_1500991_13 = "เพราะคำสาปนั่น ทำให้หนามสีดำงอกขึ้นมาบนตัวฉัน ก็ได้แต่หวังว่ามันจะหยุดเติบโตบ้าง",
  str_voice_1500991_14 = "หนามสีดำบนดาบเวทมนตร์นี้สามารถหักได้ และจะมีหนามใหม่งอกขึ้นมา เหลือเชื่อเลยใช่ไหมล่ะ",
  str_voice_1500991_15 = "ฉันไม่รู้วิธีฉลองวันเกิดของคนอื่น ฉันต้อง... ร้องเพลงแล้วก็ตบมือเหรอ",
  str_voice_1500991_16 = "ได้เวลาทำงานแล้ว ไหนล่ะ ต้องจัดการใคร มันน่ากลัวถึงกับพูดไม่ได้เลยเหรอ",
  str_voice_1500991_17 = "อรุณสวัสดิ์ วันนี้ฉันค่อนข้างสดชื่น พร้อมทำงานสุด ๆ แล้วเธอล่ะ",
  str_voice_1500991_18 = "อย่าวิตกกังวลเรื่องงานนักเลย พักบ้างเถอะ แล้วทุกอย่างจะดีขึ้นเอง",
  str_voice_1500991_19 = "กลางคืนหนาวนะ ระวังเป็นหวัดล่ะ... ส่วนฉันน่ะไม่เป็นไร ชินแล้ว",
  str_voice_1500991_20 = "อัมบราตันเป็นเมืองที่ดี ฉันหารายได้จากการเป็นทหารรับจ้าง",
  str_voice_1500991_21 = "ที่ทรู ออเดอร์อาจมีข่าวกรองเพิ่มเติม แต่ฉันว่ามันดูไม่น่าไว้ใจ...",
  str_voice_1500991_22 = "เหมือนเธอกำลังถูกจ้องมองหรืออะไรทำนองนั้น",
  str_voice_1500991_23 = "อิคลิพไซท์สังหารผู้คนไปจำนวนมาก หวังว่าเธอ รวมถึงพ่อแม่ของฉันจะไม่ต้องเผชิญหน้ากับพวกมัน",
  str_voice_1500991_24 = "คุณคอนนอลลีชวนฉันไปกินกาแฟที่ร้านของเธอ เธอพูดแบบนั้นกับคนอย่างฉัน...",
  str_voice_1500991_25 = "คุณเจนหางานให้ฉัน แถมยังสอนวิธีอ่านสัญญาทหารรับจ้างด้วย เธอเป็นคนดีมากเลย",
  str_voice_1500991_26 = "จริง ๆ แล้ว... ฉันชอบพวกสัตว์ตัวเล็กมากเลย แต่กลัวว่าจะทำร้ายพวกมันโดยไม่ได้ตั้งใจ",
  str_voice_1500991_27 = "ฉันเกลียดร่างกายที่ถูกคำสาป แต่ฉันดันเกลียดดาบเวทมนตร์นี้ไม่ลง...",
  str_voice_1500991_28 = "ความสัมพันธ์ของเธอกับโคลอสซัสก็เหมือนฉันกับดาบเวทมนตร์ที่เชื่อมโยงกันและพึ่งพาอาศัยกัน",
  str_voice_1500991_29 = "อยากจ้างฉันไหม ฉันช่วยต่อสู้ได้นะ คิดค่าแรงถูก ๆ เลย... ฉันสามารถกำจัดได้ทุกอย่างด้วยดาบเวทมนตร์เล่มนี้",
  str_voice_1500991_30 = "พลังของคำสาปรุนแรงขึ้น...",
  str_voice_1500991_31 = "เข้าใจแล้ว ฉันควรยกดาบขึ้นมา",
  str_voice_1500991_32 = "สักวันหนึ่ง ทุกอย่างจะจบลง",
  str_voice_1500991_33 = "แม้ว่าเส้นทางจะเต็มไปด้วยหนามก็ไม่เป็นไร",
  str_voice_1500991_34 = "อย่าลืม... รักษาระยะห่าง",
  str_voice_1500991_35 = "ฉันพร้อม",
  str_voice_1500991_36 = "เธอมานำทางฉันได้เลย",
  str_voice_1500991_37 = "ดาบเวทมนตร์เอ๋ย ขอพลังหน่อย",
  str_voice_1500991_38 = "ตัดหนามเพื่อเปิดเส้นทาง!",
  str_voice_1500991_39 = "เอาหนามไปซะ",
  str_voice_1500991_40 = "ขอให้แสงส่องสว่าง",
  str_voice_1500991_41 = "ว่าไงนะ... อยากให้ฉันเป็นคนนำเหรอ",
  str_voice_1500991_42 = "ยอดไปเลย ครั้งนี้เราชนะ",
  str_voice_1500991_43 = "ฉันรับมือแทบไม่ไหว... โทษทีนะ...",
  str_voice_1500991_44 = "กิจกรรมอื่น ๆ ที่ฉันชอบนอกเหนือจากการถือดาบ... อ๋อ ฉันชอบคุยไง มั้งนะ",
  str_voice_1500991_45 = "เอ่อ... นั่นคงไม่ใช่ค่าจ้างของฉันหรอกใช่ไหม",
  str_voice_1500991_46 = "นี่คือของขวัญสำหรับฉันเหรอ... แน่ใจนะว่าฉันรับไว้ได้",
  str_voice_1500991_47 = "เอ่อ... ขอคิดแป๊บนะว่าจะขอบคุณเธอยังไงดี...",
  str_voice_1500991_48 = "ขอบใจนะ ช่างเป็นของขวัญที่ล้ำค่า ฉันมีความสุขมากเลย",
  str_voice_1500991_49 = "บางคนอาจมีอาการแบบเดียวกับฉันเมื่อนานมาแล้ว นั่นอาจเป็นเหตุผลที่หนังสือโบราณและดาบเล่มนี้ถูกส่งต่อกันมา",
  str_voice_1500991_50 = "สัตว์น้อยแสนน่ารักเคยมาที่ห้องของฉันและเล่นกับฉันเมื่อฉันล้มป่วย แต่พวกมันไม่เคยมาอีกเลยหลังจากที่ฉันได้ดาบเวทมนตร์",
  str_voice_1500991_51 = "ฉันรู้ว่าพ่อแม่ของฉันไม่สามารถอยู่กับฉันได้อีกต่อไปเพราะคำสาป... แต่เรากำลังหาทางแก้ปัญหา สักวันหนึ่งเราจะได้พบกัน",
  str_voice_1500991_52 = "Alchemy Stars",
  str_voice_1500991_53 = "สวัสดี",
  str_voice_1500991_54 = "อืม เธอยังไม่หลับเหรอ",
  str_voice_1500991_55 = "เธอพอจะมีเวลาไหม",
  str_voice_1500991_56 = "นี่ฉันมารบกวนเธอรึเปล่า",
  str_voice_1500991_57 = "ปีนี้ฉันขอให้เธอมีแต่เรื่องดี ๆ",
  str_voice_1300941_1 = "ทุกคนที่โคลอสซัสสุภาพใจดีจัง ไม่มีใครว่าอะไรแม้ฉันจะชอบเหม่อ...",
  str_voice_1300941_2 = "ทำไมฉันถึงไว้ผมสั้นน่ะเหรอ ไม่มีอะไรมาก ผมสั้นมันดูแลง่ายดี...",
  str_voice_1300941_3 = "ฉันไม่ใช่คนพูดมาก ไม่ใช่ว่าไม่อยากคุยหรือว่าโกรธ หรือว่าอะไรทั้งนั้น...",
  str_voice_1300941_4 = "ย-อย่ากลัวกระแสน้ำ มันจะคอยปกป้องเธอ...",
  str_voice_1300941_5 = "ฉันชอบคทาวสันตฤดู แล้วก็ฤดูใบไม้ผลิด้วย... แล้วเธอล่ะ?",
  str_voice_1300941_7 = "ธ-เธออยู่ที่นี่มาตลอดเหรอ ขอบใจนะ แต่ตอนนี้ฉันขออยู่คนเดียว...",
  str_voice_1300941_8 = "เธอ... เธอรู้ว่าฉันไม่มีทางหนาว แต่เธอก็ยังเป็นห่วงฉัน... ใจดีจัง",
  str_voice_1300941_9 = "โทษที ฉันเหม่อไปเหรอ นั่นเพราะว่าฉันสบายใจที่ได้อยู่กับเธอ...",
  str_voice_1300941_10 = "ฉ-ฉันขออยู่คนเดียวได้ไหม ถ้าได้ปล่อยใจสักพักก็น่าจะดี...",
  str_voice_1300941_11 = "ฉ-ฉันเหรอ กำลังกังวลที่ต้องเจอคนจำนวนมากเป็นครั้งแรก... แต่ฉันก็จะทำให้ดีที่สุด",
  str_voice_1300941_12 = "น้ำ... คือสิ่งนุ่มนวลที่คอยปกป้องฉัน เหมือนดั่งพ่อแม่ของฉัน...",
  str_voice_1300941_13 = "อากาศดีนะ... ท-ทำไมเธอไม่นั่งลงและเหม่อลอยไปกับฉันล่ะ...",
  str_voice_1300941_14 = "ฉันไม่หนาว ไม่เป็นไรเลย... ว่าแต่... \"ความหนาว\" นี่มันเป็นยังไงเหรอ",
  str_voice_1300941_15 = "สุขสันต์วันเกิดนะ! ขอให้ลมแห่งฤดูใบไม้ผลิอยู่กับเธอตลอดไป...",
  str_voice_1300941_16 = "เตรียมตัวไปลาดตระเวนได้แล้ว รับรองว่าฉันจะไม่สัปหงก...",
  str_voice_1300941_17 = "ฉันตื่นแต่เช้าทุกวันเพราะต้องไปลาดตระเวน แต่เธอก็ตื่นเช้าด้วยเหมือนกัน...",
  str_voice_1300941_18 = "ใกล้พักแล้วใช่เปล่า",
  str_voice_1300941_19 = "ฉันชินกับการใช้ชีวิตแบบนี้ แต่เธอควรไปพักนะ...",
  str_voice_1300941_20 = "หิมะโปรยปรายและแสงแดดอบอุ่น อยู่ที่นี่แล้วอุ่นใจดีจัง...",
  str_voice_1300941_21 = "น่าจะปรากฏขึ้นในเมืองใหญ่สีขาวนั่นใช่ไหม",
  str_voice_1300941_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง...",
  str_voice_1300941_23 = "พวกผู้บุกรุกนั่นสังหารพ่อแม่ที่บริสุทธิ์ของฉัน... ฉันไม่มีทางยกโทษให้แน่",
  str_voice_1300941_24 = "โนอาห์กับฉันมักคุยกันบ่อย ๆ เรื่องที่อุณหภูมิทำให้เราสับสน... แปลกใช่ไหม",
  str_voice_1300941_25 = "องค์ราชินีให้ฉันเลือกเอง ฉันก็เลยตัดสินใจสานงานต่อจากพ่อแม่",
  str_voice_1300941_26 = "ฤดูใบไม้ผลิที่เงียบสงบ หิมะสีขาวโพลน เหมาะกับการนั่งปล่อยใจให้ล่องลอยไป...",
  str_voice_1300941_27 = "เธอต้องรู้นะว่ามันเป็นสถานที่ที่เสียงดังมากเลย... ฉันล่ะหงุดหงิด",
  str_voice_1300941_28 = "มันขาวราวกับหิมะ... ที่นี่คนเยอะเกินไป แต่ฉันจะพยายามปรับตัวให้ชิน...",
  str_voice_1300941_29 = "ฉันชื่อลีอาห์ ฉันคือพลลาดตระเวนในนอร์ธแลนด์... ขอโทษ ฉันควรพูดยังไงดีกับคนที่เพิ่งเคยเจอ",
  str_voice_1300941_30 = "นี่คือ... พลังเหรอ",
  str_voice_1300941_31 = "แบบว่า... \"ฤดูใบไม้ผลิ\" รู้สึกแบบนี้เหรอ",
  str_voice_1300941_32 = "แบบนี้ฉันสามารถปกป้องเธอได้ดีกว่า",
  str_voice_1300941_34 = "น่าหงุดหงิดชะมัด...",
  str_voice_1300941_35 = "ฤดูใบไม้ผลิ พร้อม!",
  str_voice_1300941_36 = "ไอน้ำพร้อม",
  str_voice_1300941_37 = "ลมหายใจแห่งฤดูใบไม้ผลิ!",
  str_voice_1300941_38 = "จงพบกับพลังแห่งความอ่อนโยน...!",
  str_voice_1300941_39 = "ไอน้ำ... แพร่กระจาย!",
  str_voice_1300941_40 = "ไอน้ำ... ระเหย!",
  str_voice_1300941_41 = "ท-ทำได้เหรอ",
  str_voice_1300941_42 = "ฉัน... ฉันทำได้แล้ว!",
  str_voice_1300941_43 = "ฉันผิดเองที่ทำเธอเจ็บ... ขอโทษนะ...",
  str_voice_1300941_44 = "ตรงนั้น... มันเสียงดังจัง... ฉันไม่ค่อยชินเลย...",
  str_voice_1300941_45 = "ของขวัญให้ฉันเหรอ... อา ขอบใจนะ",
  str_voice_1300941_46 = "ฉันเซอร์ไพรส์นิดหน่อย...",
  str_voice_1300941_47 = "ช่างเป็นของขวัญที่ถูกใจจัง...",
  str_voice_1300941_48 = "เวลามีความสุขฉันควรพูดว่าไง",
  str_voice_1300941_49 = "ฉันรับเอาคทาวสันตฤดูที่องค์ราชินีมอบให้ และสานต่องานของพ่อกับแม่... มันไม่เกี่ยวกับโชคชะตาหรอก แต่เป็น... เพียงสิ่งที่ฉันต้องทำ",
  str_voice_1300941_50 = "อาณาจักรแห่งนอร์ธแลนด์ที่เย็นยะเยือก... อากาศสดชื่น แสงแดดอ่อนโยน และทุ่งหิมะอันกว้างใหญ่ที่ทำให้ฉันต้องนั่งปล่อยใจล่องลอย... ที่นั่นเป็นสถานที่โปรดของฉันในโลกใบนี้",
  str_voice_1300941_51 = "ฉันชินกับการลาดตระเวนคนเดียวท่ามกลางหิมะ บางครั้งก็ฟังนักเดินทางที่ผ่านไปมา พวกเขาชอบพูดถึงสิ่งที่เคยเห็นและได้ยินมา ฤดูใบไม้ผลิหน้าตาเป็นยังไงนะ... ฉันอยากเห็นจัง...",
  str_voice_1300941_52 = "Alchemy... Stars...",
  str_voice_1300941_53 = "ฉันอยู่ที่นี่...",
  str_voice_1300941_54 = "อรุณสวัสดิ์...",
  str_voice_1300941_55 = "ฉันสบายดี... เธอล่ะ",
  str_voice_1300941_56 = "ทำได้ดีมาก ไปพักเถอะ",
  str_voice_1300941_57 = "ฉันขอให้เธอมีความสุขในวันปีใหม่นะ...",
  str_voice_1400951_1 = "ที่นี่กว้างขวางมาก ฉันไม่คิดว่าจะได้เห็นสถานที่ใหญ่กว่านี้อีกไปตลอดชีวิต",
  str_voice_1400951_2 = "คนของฉันให้ความสำคัญกับความน่าเชื่อถือ เธอไม่ต้องกังวลกับเรื่องนี้หรอก",
  str_voice_1400951_3 = "ฉันทำชุดป้องกันนี้เองเลยนะ แถมยังออกแบบเป็นพิเศษเพื่อเพิ่มคุณสมบัติที่มีประโยชน์ด้วย โดยเฉพาะอย่างยิ่งการป้องกันไม่ให้กลิ่นรั่ว",
  str_voice_1400951_4 = "เธออยากได้สิ่งนี้สักขวดบนหางของฉันไหมล่ะ มันจะมีประโยชน์ในยามคับขันมากเลยนะ แต่ว่าเธอต้องดูแลมันดี ๆ หน่อย",
  str_voice_1400951_5 = "ชีวิตของทหารรับจ้างจะค่อนข้างเหนื่อยหน่อย ฉันก็ว่าจะเปลี่ยนอาชีพอยู่เหมือนกัน แต่ยังไม่รู้ว่าจะทำยังไง",
  str_voice_1400951_6 = "มันยากเกินไปที่คนอย่างฉันจะใช้ชีวิตอยู่บนโลกใบนี้ ดีนะที่ในอัมบราตันมีคนดี ๆ มากกว่าที่ฉันคิด แถมยังให้การดูแลฉันเป็นอย่างดีด้วย",
  str_voice_1400951_7 = "หน้ากากน่ะเหรอ ฉันถอดมันไม่ได้อ่ะ ทั้งหมดนี่เป็นชุดเดียวกันหมด ถ้าไม่มีส่วนใดส่วนหนึ่งมันก็จะใช้การไม่ได้",
  str_voice_1400951_8 = "ถ้าเธออยากร่วมมือกันแบบยาว ๆ ละก็ ฉันมีส่วนลดให้ 20% ด้วยนะ ปกติแล้วส่วนลดนี้จะให้แต่พวกลูกค้าเก่าน่ะ",
  str_voice_1400951_9 = "อยากไปอยู่บ้านฉันไหม ถึงจะเล็กแต่ก็สะดวกนะ ถ้าได้อยู่ในสภาพแวดล้อมที่ต่างไปจากเดิมบ้างคงจะดีไม่น้อย",
  str_voice_1400951_10 = "นี่เธอได้พักบ้างรึเปล่า ฉันก็ว่าจะพักเหมือนกัน",
  str_voice_1400951_11 = "กำลังไปแล้วล่ะ รอก่อนนะ",
  str_voice_1400951_12 = "ครั้งล่าสุดฉันเห็นเด็กสองคนขายของที่ตลาดมืด ดูเหมือนว่าช่วงนี้ทุกคนจะมีช่วงเวลาที่ยากลำบาก",
  str_voice_1400951_13 = "ฉันจำได้ว่าเคยเห็นเคเลสไทต์หนึ่งหรือสองคนสมัยที่ฉันยังเด็ก แย่จัง!",
  str_voice_1400951_14 = "ระวังตัวด้วยล่ะ ไม่งั้นเธอได้ตกเป็นเป้าในอัมบราตันแน่",
  str_voice_1400951_15 = "สุขสันต์วันเกิดนะ! การเติบโตขึ้นคือเรื่องที่น่ายินดี",
  str_voice_1400951_16 = "สวัสดี เราจะเอายังไงต่อไป",
  str_voice_1400951_17 = "อรุณสวัสดิ์ วันที่สวยงามก็ต้องเริ่มต้นด้วยนมหนึ่งแก้ว",
  str_voice_1400951_18 = "สายัณห์สวัสดิ์ ฉันขายอุปกรณ์จากตลาดมืด สนใจมาชมหน่อยไหม",
  str_voice_1400951_19 = "คนอายุเท่าเธอควรนอนแต่หัวค่ำ... แต่ฉันไม่บังคับเธอหรอกนะ",
  str_voice_1400951_20 = "ฉันไม่ต้องสนใจสถานะของตัวเองในอัมบราตันเลย ใช้ชีวิตที่นี่ก็ไม่เลวนะ",
  str_voice_1400951_21 = "ฉันเคยไปอิลลูมินาหลายครั้งเพื่อทำธุรกิจ ดูเหมือนว่าที่นั่นจะมีการพัฒนาอย่างรวดเร็ว ผู้คนก็เป็นมิตร",
  str_voice_1400951_22 = "อยากให้ฉันพูดอะไรล่ะ",
  str_voice_1400951_23 = "ฉันจัดการพวกมันมาเกือบสองทศวรรษแล้ว ฉันไม่รู้สึกอะไรแล้วล่ะ ว่าแต่พวกมันทั้งหมดมาจากไหนกันแน่",
  str_voice_1400951_24 = "คุณเพนกวินและคุณคุมะเป็นพวกสร้างความบันเทิงเวลาอยู่ด้วยกัน ฉันสามารถฟังเรื่องตลกของพวกเขาได้ทุกวันเลยละ",
  str_voice_1400951_25 = "คุณคอร์กอนเป็นคนดี ฉันกำลังคิดอยู่ว่าในอนาคตจะย้ายไปที่เกาะของเขาดีไหม",
  str_voice_1400951_26 = "ฉันชอบที่มืด ๆ ชื้น ๆ อุปกรณ์ชุดนี้ตรงตามความต้องการของฉันพอดีเลย",
  str_voice_1400951_27 = "ฉันไม่ชอบถูกรบกวน โดยเฉพาะเมื่ออยู่ที่บ้านน่ะ",
  str_voice_1400951_28 = "เจ้ายักษ์นี่วิเศษไปเลยเนอะ เธอเป็นคนเดียวในโลกที่สามารถควบคุมโคลอสซัสได้ใช่ไหม",
  str_voice_1400951_29 = "สวัสดีี! ยินดีรับใช้เสมอ",
  str_voice_1400951_30 = "ทักษะทางธุรกิจของฉันเชี่ยวชาญมากขึ้นแล้ว",
  str_voice_1400951_31 = "รู้สึกดีจัง ขอบคุณนะ",
  str_voice_1400951_32 = "ถ้าเป็นแบบนี้ฉันก็จะเก็บค่าคอมได้มากขึ้น",
  str_voice_1400951_33 = "ขีดจำกัดมีไว้ทำลาย",
  str_voice_1400951_34 = "ฉันกำลังไป",
  str_voice_1400951_35 = "ฉันมีแผนล่ะ",
  str_voice_1400951_36 = "เธอเข้าใจรึยัง",
  str_voice_1400951_37 = "โอกาสของเรามาถึงแล้ว!",
  str_voice_1400951_38 = "เธอคงไม่อยากสู้ด้วยมีดหรอกนะ",
  str_voice_1400951_39 = "เอานี่ไปซะ",
  str_voice_1400951_40 = "เธอกำลังมองหาอะไร",
  str_voice_1400951_41 = "เอาสิ มาลุยกันเลย",
  str_voice_1400951_42 = "นี่มันง่ายจริง ๆ",
  str_voice_1400951_43 = "ความเก่งกาจของเรายังห่างชั้นเกินไป",
  str_voice_1400951_44 = "ให้ฉันช่วยอะไรไหม ไปหาที่มืด ๆ คุยกันดีเปล่า",
  str_voice_1400951_45 = "เธอใจดีจัง",
  str_voice_1400951_46 = "ของดีนะเนี่ย!",
  str_voice_1400951_47 = "ฉันปลื้มจัง",
  str_voice_1400951_48 = "นั่น... ฉันไม่รู้จะขอบคุณยังไงเลย",
  str_voice_1400951_49 = "แม้ว่าพวกเราทุกคนจะเป็นชาวออโรเรียน แต่ถึงยังไงแต่ละคนก็แตกต่างกันมาก ฉันรู้สึกไม่สบายใจกับร่างกายของตัวเองมานาน แต่ตอนนี้โอเคแล้วล่ะ",
  str_voice_1400951_50 = "ถ้าพูดถึงช่วงเวลาที่น่าประทับใจ... สิ่งที่นึกถึงคือช่วงเวลาที่อัมบราตันถูกล้อมโจมตี ตอนนั้นฉันอายุ 20 แล้วฉันก็นึกว่าจะไม่รอดเสียแล้ว",
  str_voice_1400951_51 = "ช่วงนี้ฉันรู้สึกไม่ค่อยอยู่กับร่องกับรอยเท่าไหร่ ร่างกายของฉันอาจจะยังเด็ก แต่จิตใจของฉัน... บางทีฉันควรเกษียณอายุดีไหมนะ สถานที่ของคุณคอร์กอนก็ดูไม่เลว",
  str_voice_1400951_52 = "Alchemy Stars",
  str_voice_1400951_53 = "สวัสดี",
  str_voice_1400951_54 = "แผนของวันเริ่มต้นด้วยยามเช้า",
  str_voice_1400951_55 = "สวัสดียามบ่าย กินมื้อเที่ยงรึยัง",
  str_voice_1400951_56 = "สายัณห์สวัสดิ์",
  str_voice_1400951_57 = "สุขสันต์วันปีใหม่! อีกไม่นานที่นี่จะต้องมีเรื่องสนุกมากมาย",
  str_voice_1400621_1 = "ทุกครั้งที่มองออกไปจากโคลอสซัส ฉันต้องประหลาดใจกับความกว้างใหญ่ของโลก ทั้งหมดนี้ต้องขอบคุณลีอาห์",
  str_voice_1400621_2 = "ได้ยินมาว่าโลกนี้ใหญ่กว่าทวีปที่เรามองเห็นหลายสิบเท่าจริงเหรอ ฉันอยากเห็นจังว่าหน้าตาของโลกส่วนที่เหลือเป็นยังไง",
  str_voice_1400621_3 = "ฉันเปลี่ยนห้องได้ไหม ปกติรอบตัวฉันมีแต่ต้นไม้เขียวขจีน่ะ",
  str_voice_1400621_4 = "เถาวัลย์พวกนี้มาจากพลังของฉัน พวกมันอยู่กับฉันมานาน จะเรียกมันว่าเพื่อนก็คงไม่ผิด",
  str_voice_1400621_5 = "แปลกไหมที่จะทำตัวเข้มแข็งเพื่อปกป้องเพื่อน ทำไมถึงมีรอยยิ้มเหมือนคนเป็นพ่อเลยละ... นายก็ไม่ได้แก่กว่าฉันมากนี่นา",
  str_voice_1400621_6 = "พ่อของฉันคือผู้พิทักษ์ผืนป่าที่ยอดเยี่ยม หวังว่าสักวันนึงฉันจะเก่งกว่าเขา",
  str_voice_1400621_7 = "ฉันคิดว่าเราเป็นเพื่อนกันแล้วนะ เพราะเราทำงานด้วยกันมานาน",
  str_voice_1400621_8 = "ระหว่างเรามีหลายอย่างที่คล้ายกัน เช่นตำแหน่งที่เราอยู่... คนรอบข้าง แล้วก็...",
  str_voice_1400621_9 = "รู้สึกเป็นเกียรตินะที่มีเพื่อนแบบเธอ ไว้มีโอกาสฉันจะแนะนำให้เธอรู้จักกับทุกคนในป่าลู่ลมล่ะ",
  str_voice_1400621_10 = "เปลือกตาของเธอลืมไม่ขึ้นแล้วมั้งนั่น จะหลับไม่หลับแหล่ ง่วงก็ไปนอนเถอะ",
  str_voice_1400621_11 = "ฉันจะทำทุกอย่างที่ทำได้",
  str_voice_1400621_12 = "ดาบเล่มนี้เหรอ มันอาจทำจากไม้ แต่ว่าคมเหมือนเหล็กเลยละ",
  str_voice_1400621_13 = "ช่วยอยู่ห่าง ๆ ด้วยตอนที่ฉันแกว่งดาบ เผื่อเธอจะโดนลูกหลงจากพวกเถาวัลย์",
  str_voice_1400621_14 = "ห้องแบบนี้... ปรับตัวยากไปหน่อยในช่วงเวลาสั้น ๆ โทษทีนะ ห้องนี้มันก็ดีอยู่หรอก แต่ที่นี่ไม่มีออร่าของธรรมชาติเลย",
  str_voice_1400621_15 = "สุขสันต์วันเกิด ฉันหวังว่าเธอจะชอบของขวัญวันเกิดนะ",
  str_voice_1400621_16 = "นี่คือช่วงเวลาที่สำคัญที่สุดของวัน ออกกำลังกายสม่ำเสมอ แล้วก็อย่าอู้",
  str_voice_1400621_17 = "อรุณสวัสดิ์ เธอดู... เหนื่อย ๆ นะ",
  str_voice_1400621_18 = "สายัณห์สวัสดิ์ ป่าตอนกลางคืนอันตรายมาก อยู่ให้ห่าง ๆ ไว้ล่ะ",
  str_voice_1400621_19 = "ฉันเข้าใจดีว่าเธอรู้สึกยังไง แต่เราไม่มีเวลาพอที่จะทำทุกอย่าง เพราะฉะนั้นการพักผ่อนให้เพียงพอเป็นเรื่องสำคัญ",
  str_voice_1400621_20 = "นอร์ธแลนด์... คือสถานที่ที่ไม่ได้เกี่ยวข้องกับโลกภายนอก และสิ่งที่ต้องแลกมาคือความโดดเดี่ยว",
  str_voice_1400621_21 = "ฉันเคยได้ยินมาว่าผู้คนที่เรดีเซล เวรนช์ มีอิสระเสรีกันสุด ๆ",
  str_voice_1400621_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง!",
  str_voice_1400621_23 = "กลุ่มสิ่งมีชีวิตที่น่าสมเพชและน่ารังเกียจ พวกมันไม่ควรมีชีวิตอยู่",
  str_voice_1400621_24 = "องค์ราชินีมีภาระที่ต้องแบกรับอย่างไร้เทียบเทียม เธอคือผู้พิทักษ์ของนอร์ธแลนด์",
  str_voice_1400621_25 = "ลีอาห์... เธอคือเพื่อนคนสำคัญสำหรับฉัน",
  str_voice_1400621_26 = "สำหรับฉันแล้ว เพื่อนที่ตรงไปตรงมาและจริงใจกับฉันคือเพื่อนที่ดีที่สุด",
  str_voice_1400621_27 = "ฉันไม่อยากใช้เวลากับคนหลอกลวงและคนหน้าซื่อใจคด",
  str_voice_1400621_28 = "โคลอสซัสน่าสนใจจริง ๆ อยากได้มั่งจัง... ฉันปกติไหมที่รู้สึกแบบนี้",
  str_voice_1400621_29 = "ฉันคือซิลวา ผู้พิทักษ์ผืนป่าแห่งป่าลู่ลม ยินดีที่ได้รู้จัก",
  str_voice_1400621_30 = "พลังกำลังก่อตัวขึ้น",
  str_voice_1400621_31 = "นี่คือผลลัพธ์จากการฝึกฝนของฉัน",
  str_voice_1400621_32 = "มุ่งสู่ความแข็งแกร่ง",
  str_voice_1400621_33 = "ฉันจะปกป้องทุกคน",
  str_voice_1400621_34 = "เชื่อมือฉันได้เลย",
  str_voice_1400621_35 = "ฉันจะลุยล่ะนะ!",
  str_voice_1400621_36 = "ว่าไงนะ",
  str_voice_1400621_37 = "ผืนป่า จงอัญเชิญสายลม",
  str_voice_1400621_38 = "สายลม จงทิ่มแทงศัตรู",
  str_voice_1400621_39 = "เถาวัลย์",
  str_voice_1400621_40 = "ดาบวายุ",
  str_voice_1400621_41 = "ฉันจะจัดการเอง",
  str_voice_1400621_42 = "ชัยชนะที่มีค่า",
  str_voice_1400621_43 = "ฉันยังอ่อนประสบการณ์...",
  str_voice_1400621_44 = "ไม่รู้ว่าฉันจะทำอะไรให้เธอได้บ้าง... เอาเถาวัลย์ไปพันเล่นดูหน่อยป่ะ",
  str_voice_1400621_45 = "ของนี่... ฉันเก็บไว้ได้ไหม",
  str_voice_1400621_46 = "ของชิ้นนี้น่าสนใจ",
  str_voice_1400621_47 = "ขอบคุณนะ... ผู้นำทาง",
  str_voice_1400621_48 = "อ่ะแฮ่ม ดีใจที่ได้เป็นเพื่อนกับเธอนะ",
  str_voice_1400621_49 = "ฉันดูพ่อเป็นแบบอย่าง จริง ๆ แล้วพ่อทำให้ฉันเชี่ยวชาญทักษะการต่อสู้ด้วยดาบ แต่ว่าพ่อจากไปเร็วเกินไป ส่วนแม่ก็ทนไม่ไหวที่... ช่างเถอะ ไม่มีอะไร",
  str_voice_1400621_50 = "การจากไปก่อนถึงเวลาอันควรของพ่อกับแม่ ทำให้ฉันแทบคลั่ง เพราะตอนนั้นฉันยังเป็นเด็กอยู่ ลีอาห์เป็นคนที่ช่วยให้ฉันหายจากความชอกช้ำ ถ้าไม่ได้เธอ ฉันก็คงไม่เป็นฉันแบบทุกวันนี้",
  str_voice_1400621_51 = "ฉันรู้สึกเสียดายทุกครั้งที่พูดถึงเรื่องนี้ เมื่อนานมาแล้วฉันคิดว่าลีอาห์เป็นเด็กผู้ชาย เมื่อนึกย้อนถึงช่วงเวลาที่เคยอยู่กับเธอ ฉันก็มักคิดถึงบรรยากาศเหล่านั้น",
  str_voice_1400621_52 = "Alchemy Stars",
  str_voice_1400621_53 = "สวัสดี",
  str_voice_1400621_54 = "อรุณสวัสดิ์ ผู้นำทาง!",
  str_voice_1400621_55 = "มากินมื้อเที่ยงด้วยกันไหม",
  str_voice_1400621_56 = "ฉันจะเข้านอนแล้ว เธอล่ะ",
  str_voice_1400621_57 = "สุขสันต์วันปีใหม่ แต่ละปีช่างผ่านไปไวเหมือนโกหก",
  str_voice_1500871_1 = "ในฐานะชนชั้นสูงแห่งลูโมโพลิส ฉันต้องปกป้องคนอย่างเธอ... เธอไม่อยากได้การปกป้องจากฉันเหรอ ฉันประเมินเธอต่ำไปสินะ",
  str_voice_1500871_2 = "ถ้าไม่มีอะไรทำก็มาฝึกปาลูกดอกกับฉันได้นะ... จะตื่นเต้นอะไรขนาดนั้น ฉันแค่อยากช่วยถือกระดานให้เท่านั้นเอง",
  str_voice_1500871_3 = "งานอดิเรกของฉันเชยมากเลยเหรอ โอเปร่าแบบดั้งเดิมไม่เห็นจะแปลกตรงไหน ในฐานะชนชั้นสูง ฉันควรพิจารณาเรื่องมรดกทางวัฒนธรรมอย่างจริงจัง",
  str_voice_1500871_4 = "ฉันใช้หอกสายฟ้าเป็นอาวุธ เพราะว่าฉันเก่งเรื่องหอก ซึ่งเป็นอาวุธประเภทเดียวที่เหมาะกับสถานะของฉันในฐานะนักรบที่ยอดเยี่ยม",
  str_voice_1500871_5 = "เธอกำลังสงสัยความแม่นยำของหอกสายฟ้าใช่หรือไม่ ไม่ต้องห่วงหรอก ฉันสามารถเจาะอะไรก็ได้ด้วยลูกดอกหรือหอกสายฟ้า แม้แต่ปีกยุงก็ไม่รอด",
  str_voice_1500871_6 = "ระวังด้วยล่ะ สายฟ้ารอบ ๆ ตัวฉันไม่ใช่แค่ของประดับหรอกนะ",
  str_voice_1500871_7 = "ในฐานะชนชั้นสูง ฉันต้องทำตัวให้เหมาะสม ฉันจะยืนหยัดในศักดิ์ศรีของฉัน แต่ฉันจะไม่พยายามสร้างอำนาจสูงสุดเหนือทุกคน รวมถึงเธอด้วย",
  str_voice_1500871_8 = "บางครั้งฉันก็หยิ่งทะนงเกินไป... แต่เป็นเพราะสถานะและความสามารถของฉัน การเปลี่ยนแปลงฉับพลันไม่ใช่เรื่องง่ายสำหรับฉัน อย่าเพิ่งมองฉันผิดไป",
  str_voice_1500871_9 = "ฉันก็ไม่รู้เหมือนกัน... แต่ฉันรู้สึกว่าเป็นตัวของตัวเองเวลาที่อยู่กับเธอ",
  str_voice_1500871_10 = "ต้องพักแล้วเหรอ ในฐานะนักรบชั้นยอดแห่งลูโมโพลิส การมีเวลาว่างมากเกินไปดูจะไม่เหมาะสม แต่ฉันก็อยากพักบ้างนะ",
  str_voice_1500871_11 = "ถ้าต้องทำแบบนั้น ฉันจะแบกรับภาระความรับผิดชอบเอาไว้เอง เชื่อใจฉันได้เลย",
  str_voice_1500871_12 = "ฉันอาจจะห่วงสถานะของตัวเองมากเกินไป แต่ทุกคนเกิดมาไม่เท่าเทียมกันหรอก",
  str_voice_1500871_13 = "คนทั่วไปที่ขาดความสามารถในการตัดสินใจที่ดีก็ควรได้รับการปกป้องไม่ใช่เหรอ",
  str_voice_1500871_14 = "การต่อสู้และการฝึกฝนคือส่วนหนึ่งในชีวิตประจำวันของฉัน ไม่ต้องห่วงหรอก",
  str_voice_1500871_15 = "ฉันจำได้ว่าวันนี้เป็นวันเกิดของเธอ... เธออยากได้อะไรจากฉันล่ะ",
  str_voice_1500871_16 = "เธออยู่นั่นเอง ได้เวลาฝึกประจำวัน ฉันหมายถึง... ฝึกปาลูกดอกแล้วน่ะ",
  str_voice_1500871_17 = "ไม่จำเป็นต้องทักทายหรอก เสียเวลาเปล่า ๆ",
  str_voice_1500871_18 = "ไม่มีคำว่าสายเกินไปสำหรับนักรบ",
  str_voice_1500871_19 = "รูปแบบการนอนหลับที่ดีคือสิ่งจำเป็นสำหรับการรักษาสุขภาพให้แข็งแรง",
  str_voice_1500871_20 = "การปกป้องคนอื่นคือหน้าที่ของชนชั้นสูง นี่คือระเบียบสังคมที่ลูโมโพลิสควรมี",
  str_voice_1500871_21 = "สถานที่ที่ผู้คนเคารพต่อเทคโนโลยีอย่างในอิลลูมินา มีกฎอะไรบ้าง",
  str_voice_1500871_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1500871_23 = "ผู้ที่รบกวนความสงบและสันติของลูโมโพลิส พวกมันจะต้องดับสิ้น",
  str_voice_1500871_24 = "เจ้าเมืองคือคนที่มีความสามารถและคุณธรรม แต่... การเล่นการเมืองเป็นการตัดสินใจที่ถูกต้องเหรอ",
  str_voice_1500871_25 = "คุณคาร์ลีนเป็นลูกของเจ้าเมือง แต่เธอซื่อเกินไป",
  str_voice_1500871_26 = "พูดตามตรง โอเปร่าไม่ใช่งานอดิเรก เพราะว่าตอนนี้มันเป็นส่วนหนึ่งของชีวิตฉันเสียแล้ว",
  str_voice_1500871_27 = "ชนชั้นสูงเหล่านั้นที่ซ่อนตัวอยู่หลังยศตำแหน่ง และใช้ชีวิตอย่างฟุ่มเฟือย เป็นแค่พวกโง่เขลาที่หลอกตัวเอง",
  str_voice_1500871_28 = "โคลอสซัสเป็นเหมือนสายเลือดและตัวตนของนาย เช่นเดียวกับความภาคภูมิใจและความรุ่งโรจน์ของนายในอนาคต",
  str_voice_1500871_29 = "ยินดีที่ได้รู้จัก ฉันชื่อเบเวอร์ลี ครั้งนี้เราจะได้ร่วมมือกัน ในฐานะสมาชิกของทหารคุ้มกันลูโมโพลิส ฉันมีหน้าที่ปกป้องพลเรือนที่นี่ วางใจได้เลย",
  str_voice_1500871_30 = "ไม่มีข้อจำกัด!",
  str_voice_1500871_31 = "ยังพัฒนาได้อีก",
  str_voice_1500871_32 = "นี่คือพลังที่ฉันสมควรได้รับ",
  str_voice_1500871_33 = "หอกทะลุฟากฟ้ายามราตรี...",
  str_voice_1500871_34 = "พร้อมรับคำสั่ง",
  str_voice_1500871_35 = "นำทางฉันไปเลย",
  str_voice_1500871_36 = "ฉันพร้อมยิง!",
  str_voice_1500871_37 = "จงพุ่งทะลวง หอกสายฟ้า!",
  str_voice_1500871_38 = "ไร้ที่ติ!",
  str_voice_1500871_39 = "โจมตีปิดฉาก!",
  str_voice_1500871_40 = "สันติสุขบังเกิดแล้ว!",
  str_voice_1500871_41 = "หลบข้างหลังฉัน!",
  str_voice_1500871_42 = "นี่คือภารกิจของฉัน",
  str_voice_1500871_43 = "ฉันยังแข็งแกร่งไม่พอรึ...",
  str_voice_1500871_44 = "ได้เวลาพักแล้ว... หือ ทำไมฉันเอาหอกออกมาน่ะเหรอ การฝึกต่อสู้ก็ถือเป็นการพัก ไม่เห็นด้วยเหรอ",
  str_voice_1500871_45 = "อืม ฉันจะรับไว้ละกัน",
  str_voice_1500871_46 = "โอ้ ของขวัญนี้สมบูรณ์แบบกับฉันมาก! ขอบคุณนะ",
  str_voice_1500871_47 = "ขอบคุณมากสำหรับการเอาใจใส่ของเธอ",
  str_voice_1500871_48 = "ขอบคุณมากนะ... ฉันต้องใส่ใจเธอให้มากขึ้น",
  str_voice_1500871_49 = "ครอบครัวของฉันเป็นพวกที่โดดเด่นและมีอำนาจ เราได้รับความเคารพจากสามัญชน พวกเรายอมตายเพื่อปกป้องพวกเขา นี่คือความภาคภูมิใจ และความรับผิดชอบที่ครอบครัวของฉันยึดมั่น",
  str_voice_1500871_50 = "ต่างจากชนชั้นสูงที่ใช้ชีวิตอย่างฟุ่มเฟือย ฉันมุ่งมั่นที่จะทำหน้าที่และรักษาความสงบเรียบร้อย... แต่แล้วพวกเขาล่ะ? พวกเขาสมควรได้รับตำแหน่งด้วยรึ",
  str_voice_1500871_51 = "พ่อของฉันบอกว่าไม่ช้าก็เร็วฉันจะต้องพบกับความสูญเสีย เพราะนิสัยเจ้ายศเจ้าอย่างของฉัน ฉันรู้ปัญหานี้มานานแล้ว แต่มันอยู่ในสายเลือดของฉัน มันเลยยากที่จะเปลี่ยน...",
  str_voice_1500871_52 = "Alchemy Stars!",
  str_voice_1500871_53 = "ฉันอยู่นี่",
  str_voice_1500871_54 = "สวัสดี",
  str_voice_1500871_55 = "พักให้เต็มที่",
  str_voice_1500871_56 = "ขอให้เธอมีค่ำคืนที่สงบสุข",
  str_voice_1500871_57 = "ปีใหม่แล้ว มาอธิษฐานกันดีกว่า",
  str_voice_1600301_1 = "คาราวานลูโมโพลิสไหวตัวทัน ตอนนี้พวกนั้นกำลังจัดส่งลังเปล่า เราจะต้องศึกษาเส้นทางการลำเลียงเพื่อยืนยันว่าพวกเขามีสินค้าหรือไม่ก่อนที่เราจะลงมือ",
  str_voice_1600301_2 = "ฟังนะเจ้าหนู ครั้งต่อไป ให้โยนเจ้านี่ลงถังขยะ เข้าใจไหม",
  str_voice_1600301_3 = "หนังสือเหรอ ฉันเอาให้เด็กผู้ชายไปแล้ว ฉันกำลังวางแผนที่จะทดสอบพวกเขาน่ะ เธอใส่แมกกาซีนไว้ในหนังสือใช่ไหม ไม่เป็นไร ฉันจะทดสอบด้วยละกัน!",
  str_voice_1600301_4 = "อยากรู้อะไรก็ว่ามาเลย ทำไมฉันถึงมีชื่อแปลก ๆ ว่าซินซาน่ะเหรอ ชื่อของเธอก็ไม่ธรรมดาเหมือนกันนะรู้ไหม...",
  str_voice_1600301_5 = "อยากเห็นประแจของฉันเหรอ ฉันยอมให้คนที่ไว้ใจได้เพียงไม่กี่คนได้ใช้มัน... หา อ้อ ในกรณีนี้ ความไว้ใจของฉันไม่เกี่ยวข้องกับความยุติธรรมหรืออะไรหรอกนะ ฉันแค่ต้องการคนที่สามารถถือมันได้ก็พอ เพราะว่ามันหนักเป็นตันเลยละ",
  str_voice_1600301_6 = "\"ผู้คนอาจพูดโกหก แต่กำปั้นไม่เคยหลอกลวง เมื่อได้อัดใครสักคน ความจริงก็จะปรากฏ!\" เยี่ยมมาก คำพูดนี้ค่อนข้างติดหู กินใจมาก คารอน",
  str_voice_1600301_7 = "ฉันชอบพูดเสียงดัง ทำไมล่ะ เวลามีความสุขก็ควรหัวเราะ เวลาโกรธก็แค่ด่าออกมา ไม่ถูกเหรอ",
  str_voice_1600301_8 = "ยังไม่มีแผนการต่อสู้อีกเหรอ เหอะ คิดไปลุยไป? ฮ่าฮ่าฮ่า สมกับที่เป็นผู้นำทาง! ปล่อยให้อาวุธตัดสินกลยุทธ์สินะ",
  str_voice_1600301_9 = "ฉันเชื่อใจทุกคนใน เรดีเซล เวรนช์ ด้วยชีวิตของฉัน ส่วนเธอ... ก็ไว้ใจได้เหมือนกัน! แล้วจะมาเข้าร่วมกับเราเมื่อไหร่ดีล่ะ",
  str_voice_1600301_10 = "ช่วยเอาฉันไปขังทีเถอะ ดีกว่าปล่อยให้ฉันนั่งว่างอยู่แบบนี้... ใช่แล้วละ ฉันพูดกับเธอนั่นแหละ",
  str_voice_1600301_11 = "เธอจะให้ฉัน... เฝ้ายามเนี่ยนะ บ้าชะมัด ไม่มีการแข่งขัน ไม่มีการต่อสู้ ยืนอยู่ตรงนี้อ่ะนะ เฮ่อ เอาไงก็เอา เซ็งสุด ๆ",
  str_voice_1600301_12 = "ถ้าเธอไม่สามารถใช้กำปั้นจัดการได้ละก็ ใช้ปืนใหญ่แทนซะก็หมดเรื่อง! ว่าไงนะ ทำไม่ได้เหมือนกันเหรอ งั้นปล่อยให้เป็นหน้าที่ฉันเอง เดี๋ยวจัดให้หนักๆ เลย",
  str_voice_1600301_13 = "กิน นอน ใช้ชีวิต... เราแต่ละคนก็มีการต่อสู้ของตัวเอง การต่อสู้ที่คนอื่นไม่เข้าใจ",
  str_voice_1600301_14 = "เฮ้ เร่งความเร็ว โคลอสซัส! คันเร่งอยู่ไหน เปลี่ยนเกียร์ยังไงเนี่ย",
  str_voice_1600301_15 = "โย่! สุขสันต์วันเกิด ลืมเตรียมของขวัญมาอ่ะ แต่ว่า... เอาละ เด็ก ๆ ออกไปหาอะไรดี ๆ มาให้กับผู้นำทางกันดีกว่า",
  str_voice_1600301_16 = "ต่อสู้เหรอ อากาศเพอร์เฟกต์มากที่จะเหวี่ยงแขนกล",
  str_voice_1600301_17 = "ยังไม่นอนเหรอ ฉันล่ะอิจฉาคนที่หัวถึงหมอนก็หลับ...",
  str_voice_1600301_18 = "ค่ำคืนล่วงเลย ทุกคนต่างหลับใหล เจ้าหนูพวกนั้นคลานออกมาในขณะที่ความมืดครอบงำ!",
  str_voice_1600301_19 = "นอนไม่หลับเหมือนกันเหรอ มาหาอะไรใส่ท้องตอนดึกกันดีกว่า ฉันเลี้ยงเอง!",
  str_voice_1600301_20 = "อย่าตัดสินพวกเราจากรูปลักษณ์ภายนอก ครอบครัวที่เป็นน้ำหนึ่งใจเดียวกันและพึ่งพาได้มีที่เรดีเซล เวรนช์!",
  str_voice_1600301_21 = "ไม่ว่ายังไง ฉันก็ไม่ชอบพวกเจ้าหน้าที่เหล่านั้นเอาเสียเลย พวกเขามีประวัติที่เลวร้ายมากเกินไป...",
  str_voice_1600301_22 = "ใช้ชีวิตให้เต็มที่!",
  str_voice_1600301_23 = "พวกแมลงโง่ ๆ พวกนี้น่ารำคาญชะมัด แถมกินก็ไม่ได้! หวังว่ามาทางไหนก็จะกลับไปทางนั้นนะ...",
  str_voice_1600301_24 = "ฉันจำได้ดีตอนที่เธอยิ้มออกมาอย่างไร้กังวล ตอนนั้นพวกเราต่างก็ไม่รู้ว่าชีวิตจะโหดร้ายแค่ไหน",
  str_voice_1600301_25 = "บางคนไว้ใจได้จริง ๆ แต่รสนิยมทางดนตรี เอ่อ... อ่ะแฮ่ม ช่างเถอะ คิดเสียว่าฉันไม่ได้อะไรละกัน",
  str_voice_1600301_26 = "ปล้นชาวบ้านแล้วก็แข่งรถ ความปรารถนาที่ยิ่งใหญ่ที่สุดในชีวิตเลยละ ฟังดูเกรียนไปไหม ถึงจะเกรียนไปหน่อยแต่ก็ไม่ผิด",
  str_voice_1600301_27 = "เคยเห็นคนโกรธจนจะทุบภูเขาได้ทั้งลูกเปล่า ถ้าใครทำร้ายครอบครัวฉัน รับรอบว่าจบไม่สวยแน่",
  str_voice_1600301_28 = "ว้าว ที่นี่ทั้งสวยแล้วก็สดใส ฉันขออ้างสิทธิ์ของที่นี่ในนามของเรดีเซล เวรนช์ ใครมีปัญหาไหม!",
  str_voice_1600301_29 = "ยินดีต้อนรับสู่ทะเลทรายเรดีเซล เด็กน้อย รู้สึกไหมว่าลมเพิ่งเปลี่ยนทิศ แต่ไม่ต้องห่วง ไม่ใช่พายุทรายหรอก มันเป็นแค่ลมหายใจของภูเขาน่ะ",
  str_voice_1600301_30 = "เครื่องฉันติดแล้ว!",
  str_voice_1600301_31 = "อ่ะฮ่า! บ้าจริง ฉันโอเค!",
  str_voice_1600301_32 = "เร็วขึ้น! เร็วกว่านี้ได้อีก!",
  str_voice_1600301_33 = "ราชาแห่งทะเลทรายมาแล้ว!",
  str_voice_1600301_34 = "เร็วเข้า!",
  str_voice_1600301_35 = "เลือดของฉันกำลังปะทุ!",
  str_voice_1600301_36 = "สู้ที่ไหนดีนะ",
  str_voice_1600301_37 = "พวกแก ทำตัวดี ๆ หน่อย!",
  str_voice_1600301_38 = "เธอหลงทางเหรอ!",
  str_voice_1600301_39 = "แตกสลาย!",
  str_voice_1600301_40 = "รู้สึกมีไฟเต็มเปี่ยม!!",
  str_voice_1600301_41 = "ตามฉันมาเลย!",
  str_voice_1600301_42 = "แจ๋ว! อุ่นเครื่องเสร็จรึยัง",
  str_voice_1600301_43 = "ฮ่าฮ่าฮ่า! รอยแผลเป็นคือสัญลักษณ์ของลูกผู้ชายตัวจริง!",
  str_voice_1600301_44 = "โคลอสซัสน่าเหลือเชื่อมาก... มันต้องยับยั้งใจสุด ๆ ที่จะไม่ปล้นที่นี่!",
  str_voice_1600301_45 = "นี่คือของแทนใจเหรอ",
  str_voice_1600301_46 = "เฮ้! รสนิยมดีนี่ เจ้าหนู",
  str_voice_1600301_47 = "อู้ว! อันนี้ดีกว่าที่ฉันใช้อยู่เสียอีก",
  str_voice_1600301_48 = "ว้าว! กำลังอยากได้เลย ขอบใจมาก!!",
  str_voice_1600301_49 = "ฉัน... ไม่ได้ญาติดีกับพวกอิลลูมินาซักเท่าไหร่ ตอนนี้ฉันไม่อยากพูดถึง แต่อีกไม่นานเธอจะเข้าใจเอง",
  str_voice_1600301_50 = "ชินกับการใช้ชีวิตใน เรดีเซล เวรนช์ รึยัง ถ้ายังก็ไม่เป็นไร เราไม่สนใจหรอก แอสตรามีขนาดใหญ่แต่เล็กมาก มันเล็กจนทะเลทรายเรดีเซลเป็นสถานที่เดียวที่เราเรียกว่าบ้าน!",
  str_voice_1600301_51 = "ใช่แล้วละ อีฟเป็นน้องสาวฉัน เราผ่านช่วงเวลาที่ยากลำบากมาด้วยกัน แต่ช่วงเวลาเหล่านั้นก็ทำให้สายสัมพันธ์ของเราแน่นแฟ้นยิ่งขึ้น หวังว่าโชคจะเข้าข้างเธอเหมือนกัน ผู้นำทาง",
  str_voice_1600301_52 = "Alchemy Stars!",
  str_voice_1600301_53 = "อยู่ไหมเอ่ย เจ้าหนู",
  str_voice_1600301_54 = "ลุกได้แล้ว เจ้าหนู!",
  str_voice_1600301_55 = "ได้เวลาออกเหงื่อแล้ว!",
  str_voice_1600301_56 = "ไปนอนได้แล้ว",
  str_voice_1600301_57 = "สุขสันต์วันปีใหม่! เราจะฝึกให้หนักขึ้นจนกว่านายจะมีซิกแพ็กเป็นของตัวเอง!",
  str_voice_1400671_1 = "โคลอสซัสบินไปที่ชายหาดได้ไหม ได้ยินมาว่าเธอสามารถมองเห็นนางเงือกได้จากชายฝั่ง",
  str_voice_1400671_2 = "ลูโมโพลิสเต็มไปด้วยชนชั้นสูง... เจ้าชายหรือเจ้าหญิงล่ะ",
  str_voice_1400671_3 = "ไม่เคยเห็นออโรเรียนมาก่อนเหรอ ผู้นำทาง ไปมุดอยู่ที่ไหนมาเนี่ย",
  str_voice_1400671_4 = "บางคนบอกว่ามีแม่มดร้ายอยู่ในป่านอร์ธแลนด์ แต่ฉันไม่กลัวเลยสักนิด!",
  str_voice_1400671_5 = "พระราชวังเหมันต์ของราชินีถูกสร้างจากน้ำแข็ง มันสวยมากเลยละ ไว้มีโอกาสจะพาไปนะ!",
  str_voice_1400671_6 = "ได้ยินว่าทางใต้สุดเป็นทะเลทรายร้าง... เมื่อไหร่เธอจะพาฉันไป",
  str_voice_1400671_7 = "อยากรู้เกี่ยวกับอดีตของเธอจัง มันต้องคงเป็นเรื่องราวที่มหัศจรรย์แน่ ๆ เลย",
  str_voice_1400671_8 = "อัศวินโพธิ์ดำและราชินีโพธิ์แดงเป็นเพื่อนฉันเอง ดังนั้นพวกเขาก็คือเพื่อนของเธอด้วยเช่นกัน",
  str_voice_1400671_9 = "ฉันเชี่ยวชาญลูมินาติกส์ได้ยังไงน่ะเหรอ ฉันก็แค่ใช้ไปเรื่อย ๆ ประมาณนั้นมั้ง",
  str_voice_1400671_10 = "จะไปไหนเหรอ อัศวินโพธิ์ดำและราชินีโพธิ์แดง",
  str_voice_1400671_11 = "แค่รออยู่ที่นี่เหรอ ก็ได้ ฉันคิดว่าสองคนนั้นก็คงชอบที่นี่เหมือนกัน",
  str_voice_1400671_12 = "แถวนี้มีห้องสมุดไหม ฉันหวังว่าจะมีเทพนิยายสนุก ๆ ให้อ่านนะ...",
  str_voice_1400671_13 = "มีคนบอกว่าอยู่ ๆ ฉันก็โผล่มา เพราะว่าฉันตัวเตี้ยและเท้าเบา",
  str_voice_1400671_14 = "ฮ็อปสก็อตช์สนุกมาก ฉันเล่นได้เป็นสิบวันแบบไม่หลับไม่นอนเลยละ!",
  str_voice_1400671_15 = "สุขสันต์วันเกิด! ขอหม่ำเค้กหน่อยได้เปล่า",
  str_voice_1400671_16 = "วันนี้ไม่มีอะไรมาก มาหาอะไรสนุก ๆ ทำกันดีป่ะ",
  str_voice_1400671_17 = "อรุณสวัสดิ์ อยากไปเดินเล่นในป่าไหม",
  str_voice_1400671_18 = "วันนี้ฉันจะไปไหนดี",
  str_voice_1400671_19 = "ง่วงจัง... ถึงเวลานอนยัง",
  str_voice_1400671_20 = "ชาวนอร์ธแลนด์ใจดีมาก แม้การใช้ชีวิตที่นี่จะยากไปหน่อย",
  str_voice_1400671_21 = "ลูโมโพลิสทำให้ฉันนึกถึงพวกชนชั้นสูง สงสัยจังว่ามีคนธรรมดาบ้างไหม",
  str_voice_1400671_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1400671_23 = "ช่างเป็นสิ่งมีชีวิตที่น่าเกลียด อัปลักษณ์กว่าราชาในเทพนิยายเสียอีก!",
  str_voice_1400671_24 = "ซิลวาดูห่างเหิน แต่จริง ๆ แล้วเขาใจดี!",
  str_voice_1400671_25 = "ลีอาห์เป็นคนดีจริง ๆ... จนบางครั้งก็ดีเกินไป",
  str_voice_1400671_26 = "ได้ยินว่าในทวีปนี้มีตุ๊กตาตัวเท่าคนจริง ฉันอยากได้อ่ะ...",
  str_voice_1400671_27 = "อย่าพูดดังนักซิ ขนลุกแล้วเนี่ย!",
  str_voice_1400671_28 = "เธอช่วยบอกให้มันพาฉันไปชมรอบๆ ได้ไหม คงได้อารมณ์แบบ \"อลิซท่องแดนมหัศจรรย์\"",
  str_voice_1400671_29 = "นี่โคลอสซัสเหรอ สวัสดี ฉันชื่ออลิซ ไว้จะมาหาบ่อย ๆ นะ",
  str_voice_1400671_30 = "ฉลาดขึ้นแล้ว!",
  str_voice_1400671_31 = "ตัวสูงขึ้นแล้ว!",
  str_voice_1400671_32 = "ไปได้ไกลกว่าเดิมแล้ว!",
  str_voice_1400671_33 = "ขอฉันชมวิวที่ไม่เคยเห็นมาก่อนหน่อย!",
  str_voice_1400671_34 = "มากับฉันสิ!",
  str_voice_1400671_35 = "เอาละ! ฉันพร้อมแล้ว!",
  str_voice_1400671_36 = "ฉันควรทำไหม",
  str_voice_1400671_37 = "นี่แน่ะ!",
  str_voice_1400671_38 = "เปลวไฟ!",
  str_voice_1400671_39 = "อัศวินโพธิ์ดำ!",
  str_voice_1400671_40 = "ราชินีโพธิ์แดง!",
  str_voice_1400671_41 = "ให้ฉันเป็นผู้นำเหรอ",
  str_voice_1400671_42 = "เยี่ยมมาก ทุกคน!",
  str_voice_1400671_43 = "หนีเร็ว ทุกคน...",
  str_voice_1400671_44 = "เธออยากเล่นกับเราเหรอ งั้นมาเริ่มเกมใหม่กัน!",
  str_voice_1400671_45 = "ขอบคุณนะ ผู้นำทาง!",
  str_voice_1400671_46 = "ฉันชอบสิ่งนี้!",
  str_voice_1400671_47 = "ได้รับของขวัญใหม่แล้ว!",
  str_voice_1400671_48 = "น่ารักมาก เห็นแล้วใจบางเลยละ!",
  str_voice_1400671_49 = "หูกระต่ายของฉันเป็นที่นิยมมากในหมู่ชาวบ้าน ถ้าเธออยากลองจับดูก็ได้นะ",
  str_voice_1400671_50 = "ถ้าไม่ใช่เพราะลีอาห์และซิลวา ฉันคงยังอยู่ที่นอร์ธแลนด์",
  str_voice_1400671_51 = "ไม่ต้องกลัวเพื่อนสองคนนี้หรอก พวกเขาช่วยฉันไว้มาก",
  str_voice_1400671_52 = "Alchemy Stars",
  str_voice_1400671_53 = "สวัสดี!",
  str_voice_1400671_54 = "อรุณสวัสดิ์!",
  str_voice_1400671_55 = "สวัสดียามบ่าย",
  str_voice_1400671_56 = "สายัณห์สวัสดิ์",
  str_voice_1400671_57 = "สุขสันต์วันปีใหม่",
  str_voice_1701081_1 = "มีเพียงที่ราบเถ้าถ่านเท่านั้นที่รออยู่ เมื่อความทุกข์ทรมานดับสูญแม้จะเป็นเปลวไฟที่ร้อนแรงที่สุด",
  str_voice_1701081_2 = "ฉันยอมรับพลังแห่งความมืดเพื่อเห็นแก่การปกป้อง ฉันมั่นใจว่าตัวเองจะไม่ถูกครอบงำ แต่ในที่สุดฉันก็กลายเป็นอาวุธที่โหดเหี้ยม",
  str_voice_1701081_3 = "นี่คือการลงโทษ เข้าถึงไม่ได้ ให้อภัยไม่ได้ ไม่สามารถรับรู้ถึงความตายของตนเองได้ และไม่สามารถรับความพินาศได้",
  str_voice_1701081_4 = "นี่คือการชดใช้ ฉันต้องการลืมตาและมองดูสิ่งที่เกิดขึ้นต่อหน้า",
  str_voice_1701081_5 = "เพราะฉันทำลายล้างสิ่งที่ควรปกป้อง ฉันจึงต้องดิ้นรนอยู่ในโคลนที่ร้อนระอุไปชั่วนิรันดร์",
  str_voice_1701081_6 = "ฉันอิจฉาเธอจัง... เธอสงบสติอารมณ์ไว้ได้เสมอ... แต่ฉันยังคงเผาไหม้อย่างไร้จุดหมาย ความภาคภูมิใจและศรัทธาที่ถูกหลอมละลาย",
  str_voice_1701081_7 = "ฉันอุทิศชีวิตเพื่อปกป้องประเทศ ทั้งในฐานะนักล่าและทหาร... แต่แล้วยังไง ฉันกลายเป็นแค่เบี้ยที่ถูกทอดทิ้งอย่างหลีกเลี่ยงไม่ได้",
  str_voice_1701081_8 = "คนบาปไม่มีสิทธิ์ร้องไห้ด้วยความเจ็บปวด ทำได้แค่ต่อสู้ต่อไป...",
  str_voice_1701081_9 = "พอล่ะ... มาพูดถึงเธอกันดีกว่า ฉันอยากจะลืมเรื่องในอดีต",
  str_voice_1701081_10 = "หลุมในจิตใจเต็มไปด้วยเปลวไฟที่ไม่มีวันดับ... แบบนี้เรียกว่านรกได้ไหม",
  str_voice_1701081_11 = "ฉันจะทำอะไรได้นอกจากต่อสู้? ฉันเป็นแค่อาวุธเท่านั้น ดังนั้นคำตอบของฉันคงต้องเป็น \"ไม่มี\"",
  str_voice_1701081_12 = "ยิ่งฉันถลำไปมากเท่าไหร่ หัวใจของฉันก็ยิ่งเย็นชา และเปลวเพลิงก็ยิ่งแผดเผา",
  str_voice_1701081_13 = "วันนั้นเองที่ฉันทำลายทุกอย่างด้วยเปลวเพลิงแห่งความโกรธ",
  str_voice_1701081_14 = "\"ตกลงมา ตกลงมา\" ฉันเห็นพวกเขาตะโกน... แล้วก็หัวเราะ",
  str_voice_1701081_15 = "วันนี้ฉันสบายใจที่ได้อยู่กับเธอ เธออยากให้ฉันทำอะไร บอกมาได้เลย",
  str_voice_1701081_16 = "โชคชะตาช่างใจดีที่ให้ฉันได้มาอยู่ที่นี่หลังจากผ่านไปหลายพันปี",
  str_voice_1701081_17 = "เธอได้ยินไหม เสียงร้องไห้ตอนเช้าที่ดังมาแต่ไกล",
  str_voice_1701081_18 = "ฉันหวังว่าวันนั้นจะมาถึง วันที่พวกเราจะไม่ต้องต่อสู้กัน",
  str_voice_1701081_19 = "พอเถอะ เธอทำมาพอแล้ว การต่อสู้จบลงแล้ว",
  str_voice_1701081_20 = "ฉันแค่ไม่เข้าใจ ทำไม... วีรบุรุษที่ต่อสู้เพื่ออาณาจักรถึงถูกทอดทิ้ง",
  str_voice_1701081_21 = "ฉันอยากไปเที่ยวเมืองต่าง ๆ ที่เธอพูดถึง ดูว่าชาวบ้านอาศัยอยู่ยังไง มีความสุขไหม",
  str_voice_1701081_22 = "เราคือนักรบที่แข็งแกร่งที่สุด",
  str_voice_1701081_23 = "แสงไฟสลัวดับลงแล้ว แต่ฉันยังมีลาวาที่จะกลืนกินทุกสิ่ง มากพอที่จะทำลายล้าง",
  str_voice_1701081_24 = "ความจริงถูกปกปิดเพื่อให้เคลย์มอร์ตัดสินใจ... นั่นแหละที่ทำให้ฉันโมโห!",
  str_voice_1701081_25 = "มิธอสจอมทื่อนั่นไม่รู้ว่าทำไมฉันถึงเผาเธอ และอะไรทำให้ฉันโกรธ",
  str_voice_1701081_26 = "นั่นคือสิ่งที่ออโรเรียนต้องการเหรอ เยี่ยมเลย",
  str_voice_1701081_27 = "ยืนหยัด เดินหน้า เผชิญหน้าศัตรู ต่อสู้ แล้วก็แสวงหาการปลอบประโลมให้กับความสำนึกผิดอีกครั้ง",
  str_voice_1701081_28 = "โคลอสซัสอยู่กับเธอเหรอ ชะตากรรมของมันดูมีความหวังมากกว่าพวกเรา...",
  str_voice_1701081_29 = "ฉันไม่เข้าใจว่าทำไมเธอถึงช่วยฉัน เพื่อให้ฉันชดใช้บาปเหรอ ความทรงจำของ \"นักล่าผู้เงียบงัน\" ควรหายไปนานแล้ว แต่ก็ยังหนีไม่พ้นอยู่ดี...",
  str_voice_1701081_30 = "ยังไม่สามารถจุดไฟได้",
  str_voice_1701081_34 = "ไม่ต้อง ฉันจัดการเอง",
  str_voice_1701081_35 = "อย่าให้ใครเหลือรอด!",
  str_voice_1701081_36 = "ทำลายให้สิ้นซาก!",
  str_voice_1701081_37 = "เผาให้ราบคาบ!",
  str_voice_1701081_38 = "คร่ำครวญ คร่ำครวญ ในขุมนรกอีกครั้ง!",
  str_voice_1701081_39 = "หนี!",
  str_voice_1701081_40 = "กรีดร้อง!",
  str_voice_1701081_41 = "อย่ามายุ่งกับฉัน",
  str_voice_1701081_42 = "ต้องดับ...ไฟ...",
  str_voice_1701081_43 = "ทำไม ทำไมถึงล้มเหลว",
  str_voice_1701081_44 = "ระวังด้วย อย่าเข้าไปใกล้ ฉันจะไปหาเธอเองเมื่อฉันสงบลง",
  str_voice_1701081_45 = "วางไว้ตรงนั้นแหละ",
  str_voice_1701081_46 = "ฉันไม่รู้ว่าจะให้อะไรเธอดี",
  str_voice_1701081_47 = "ขอบใจนะสำหรับน้ำใจ ฉันจะรับไว้",
  str_voice_1701081_48 = "ฉันไม่มีอะไรจะตอบแทน แต่ก็... ขอบคุณนะ",
  str_voice_1701081_49 = "ฉันจำเมืองเถ้าถ่านในคืนฤดูหนาวเหน็บได้ บาปที่จารึกไว้ในใจของฉัน ไม่อาจลบเลือนได้",
  str_voice_1701081_50 = "บางทีชะตากรรมของเราอาจถูกกำหนดไว้แล้วตอนที่เราตัดสินใจเข้าร่วมโปรเจคนั้น... ไม่เอาดีกว่า ฉันจะไม่พูดอะไรมากไปกว่านี้",
  str_voice_1701081_51 = "ฉันเคยคิดว่าโลกนี้กำลังจะถูกทำลาย แต่ตอนนี้ฉันรู้แล้วว่า โลกยังคงหมุนต่อไป โดยไม่สนว่าใครจะอยู่หรือตาย... ฉันนี่โง่ชะมัด",
  str_voice_1701081_52 = "Alchemy Stars",
  str_voice_1701081_53 = "เธออยู่รึเปล่า",
  str_voice_1701081_54 = "อรุณสวัสดิ์",
  str_voice_1701081_55 = "เที่ยงแล้วล่ะ",
  str_voice_1701081_56 = "สายัณห์สวัสดิ์ เอ่อ เธอ...",
  str_voice_1701081_57 = "วันนี้คือวันพิเศษ ในอดีตหรือปัจจุบัน",
  str_voice_1701071_1 = "หืม? อยากได้ความเชี่ยวชาญของฉันเพื่อนำการต่อสู้ครั้งต่อไปเหรอ?",
  str_voice_1701071_2 = "เป็นอะไรไป ปกติเธอก็ใช้งานได้มากขึ้นหลังการฝึกนี่นา",
  str_voice_1701071_3 = "ฉันดูใจร้ายเหรอ ก็ไม่แน่ ฉันอาจสูญเสียมากกว่าแค่ความทรงจำ",
  str_voice_1701071_4 = "ฉันยอมบ้าระห่ำสติหลุด ตราบใดที่สามารถสังหารพวกอิคลิพไซท์ทั้งหมดได้",
  str_voice_1701071_5 = "ไม่ใช่ลางร้าย ไม่ใช่โลงศพจริง... เอ่อ ก็ไม่แน่... หรือฉันลืมไป",
  str_voice_1701071_6 = "อย่ามัวแต่จ้องฉันสิ ทำอะไรสักอย่าง",
  str_voice_1701071_7 = "ฉันสูญเสียความทรงจำบางส่วนไป แต่มันไม่มีผลกับความสามารถในการสังหารอิคลิพไซท์หรอกนะ",
  str_voice_1701071_8 = "อยู่ดี ๆ ก็นึกถึงการทำไร่อยู่ในทุ่งนา... นั่นฉันจริง ๆ เหรอ",
  str_voice_1701071_9 = "ถึงแม้เธอจะยังใช้ดาบไม่ได้ แต่ก็ยังดีที่ใช้โล่ได้",
  str_voice_1701071_10 = "ไหน ๆ ก็ว่างแล้ว ฉันจะร้องเพลงเพราะ ๆ ให้ฟังจากฐานละกัน ทุกคนมักโยกไปมาเวลาฉันเริ่มร้องเพลง",
  str_voice_1701071_11 = "เข้าใจแล้ว ฉันจะรีบไปทันที",
  str_voice_1701071_12 = "กำลังรอคำสั่ง",
  str_voice_1701071_13 = "ฉันดูเซื่องซึมเหรอ นั่นเป็นเพราะฉันยังไม่เคยเจอกับอิคลิพไซท์",
  str_voice_1701071_14 = "หวังว่าพรุ่งนี้ที่นอร์ธวินด์จะเป็นวันที่ดีนะ",
  str_voice_1701071_15 = "นานมากแล้วที่ไม่มีใครฉลองวันเกิด ช่วยรับคำอวยพรจากฉันด้วย \"สุขสันต์วันเกิด!\"",
  str_voice_1701071_16 = "งานของฉันตอนนี้คือปกป้องโคลอสซัส และทำลายศัตรูทั้งหมด แน่นอนว่าพวกมันก็คืออิคลิพไซท์",
  str_voice_1701071_17 = "อรุณสวัสดิ์ เรียกทุกคนบนโซรอซมาวิ่ง 50 รอบ... ไม่เอาด้วยเหรอ ทำตัวมีปัญหาสินะ",
  str_voice_1701071_18 = "ได้เวลาพักสักหน่อยแล้ว แต่อย่าอยู่ดึกเกินไปล่ะ",
  str_voice_1701071_19 = "นี่เธอไม่ได้หลับหรอกเหรอ ฉันเฝ้ากะต่อไปให้ละกัน",
  str_voice_1701071_20 = "ฉันจำได้แค่ว่ารับใช้ชาติกับเพื่อนทหาร... โทษทีนะ เรื่องอื่นจำไม่ได้เลย",
  str_voice_1701071_21 = "แม้ว่าจะมีกองกำลังมากมายในดินแดนแห่งนี้... แต่อย่างที่ฉันเห็น สิ่งต่าง ๆ มีแต่ความวุ่นวายมากขึ้นเรื่อย ๆ",
  str_voice_1701071_22 = "ฉันคือผู้พิทักษ์แห่งแดนเหนือ",
  str_voice_1701071_23 = "มันคือศัตรูที่ยิ่งใหญ่ที่สุดของเรา หวังว่าจะเป็นแค่ศัตรูเพียงคนเดียวสำหรับออโรเรียนทั้งหมด",
  str_voice_1701071_24 = "ฟรีกสันเป็น... ช่างเถอะ ฉันไม่ชอบตัดสินคนอื่น",
  str_voice_1701071_25 = "อยากรู้เพิ่มเติมเกี่ยวกับเฟรย่าเหรอ อืม เธอคือเจ้าหน้าที่ฝึกที่ยอดเยี่ยม\nฉลาดและเป็นที่ชื่นชอบในหมู่ทหาร นั่นคือทั้งหมดที่ฉันรู้",
  str_voice_1701071_26 = "สิ่งที่ฉันชอบเหรอ... ก็พอจะมีอยู่บ้าง",
  str_voice_1701071_27 = "ฉันไม่ชอบอิคลิพไซท์ตัวใหญ่ เพราะอัดให้กระเด็นไปไกล ๆ ยาก",
  str_voice_1701071_28 = "ถ้าตอนนั้นเรามีโคลอสซัสแบบนี้ คงช่วยไว้ได้หลายชีวิต",
  str_voice_1701071_29 = "สวัสดี คำทักทายจากนักล่าผู้เงียบงัน ฉันพร้อมเสมอสำหรับการต่อสู้",
  str_voice_1701071_30 = "ฤดูหนาวที่หนาวเหน็บสามารถเอาชนะความมืดมิดได้",
  str_voice_1701071_34 = "เยี่ยม เตรียมตัวล่า",
  str_voice_1701071_35 = "โอวววว!",
  str_voice_1701071_36 = "ฆ่า! ฆ่าาาาา!",
  str_voice_1701071_37 = "ฉันจะฆ่าแก!",
  str_voice_1701071_38 = "ไม่มีทาง!",
  str_voice_1701071_39 = "ถึงเวลาตายแล้ว!",
  str_voice_1701071_40 = "ช้าเกินไป!",
  str_voice_1701071_41 = "ให้ฉันนำเหรอ กล้าดีนี่...",
  str_voice_1701071_42 = "แฮ่ก แฮ่ก... เราชนะแล้ว... ไม่ต้องห่วง...",
  str_voice_1701071_43 = "เป็นไปไม่ได้... ฉันจะฆ่าแกทิ้ง... ฉันต้องฆ่าแก!",
  str_voice_1701071_44 = "อยากเห็นฉันวิดพื้นหกสูงด้วยนิ้วเดียวเหรอ",
  str_voice_1701071_45 = "... ขอบคุณนะ",
  str_voice_1701071_46 = "ขอบใจมาก",
  str_voice_1701071_47 = "ของนี่น่าจะมีประโยชน์",
  str_voice_1701071_48 = "ขอบคุณนะ เธออาจจะดูไม่ออก แต่ฉันมีความสุขมากเลยละ",
  str_voice_1701071_49 = "ฉันเดาว่าฉันเป็นทหารจากครอบครัวเกษตรกร ฉันจำเพื่อนไม่ค่อยได้ แต่เมื่อฉันลองพยายามนึกถึง ความทรงจำก็ยิ่งแตกสลายมากขึ้น",
  str_voice_1701071_50 = "ฉันจำได้เลือนลางว่าถูกเกณฑ์เข้ากองทัพเพื่อเป็นทหาร และเข้าเฝ้าพระราชา... จากนั้นอิคลิพไซท์ก็บุกเข้ามา เคลย์มอร์จึงได้ชวนฉันเข้าร่วมกับนักล่าผู้เงียบงัน...",
  str_voice_1701071_51 = "เราช่วยกันกอบกู้อาณาจักรให้พ้นจากวิกฤติ แต่ต้องมาถูกขับไล่โดยประชาชนที่หวาดกลัว ถ้าอย่างนั้น... เอาเถอะ... ฉันคิดว่าฉันลืมบางอย่างที่สำคัญมากไป บางอย่างที่มีความหมายกับฉันมาก...",
  str_voice_1701071_52 = "Alchemy Stars",
  str_voice_1701071_53 = "สวัสดี? สวัสดี?",
  str_voice_1701071_54 = "อรุณสวัสดิ์ ให้ฉันเป่าแตรปลุกทุกคนไหม",
  str_voice_1701071_55 = "ถ้าเธอทานเสร็จแล้วก็มาต่อด้วยการฝึกช่วงบ่ายนะ",
  str_voice_1701071_56 = "ได้เวลาพักล่ะ ปิดไฟเลยเดี๋ยวนี้",
  str_voice_1701071_57 = "สวัสดีปีใหม่ มีคนบอกว่าดาบของฉันเป็นลางไม่ดีงั้นเหรอ...",
  str_voice_1701091_1 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว ในป่าที่เต็มไปด้วยต้นสนและต้นไซเปรส มีเมืองสีขาวที่สร้างจากหิน และเจ้าหญิงสวมหนังกวางอาศัยอยู่ที่นั่น",
  str_voice_1701091_2 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว วีรบุรุษห้าคนได้มายังทุ่งหิมะที่เย็นยะเยือก พวกเขาเอาชนะอิคลิพไซท์ที่น่าสะพรึงกลัว แต่พอพระราชา... อา ตรัสถึงเรื่องนี้ทีไร ฟรอสต์ไฟร์มักหัวเสียตลอด",
  str_voice_1701091_3 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว ท่ามกลางค่ำคืนที่มืดมิดในอาณาจักร คนทั้งห้าได้จากอาณาจักรไปยังดินแดนอันไกลโพ้น เพื่อนำดวงจันทร์และดวงดาวกลับมา...",
  str_voice_1701091_4 = "เห็นเพื่อน ๆ ของฉันไหม คนหนึ่งถูกทำให้ดับ คนหนึ่งถูกผนึก คนหนึ่งหลงทาง คนหนึ่งกำลังถือดาบ... ถูกทิ้งไว้ที่นั่น...",
  str_voice_1701091_5 = "เราเป็นแค่หนึ่งในดาวดวงมากมายที่คอยส่องสว่างแก่ผู้คน แต่ทว่าดวงดาวที่เลือนลางนั้นทำได้เพียงยอมรับความอัปยศอดสูเพียงลำพัง",
  str_voice_1701091_6 = "ทำไมฉันชอบเล่าถึงความหลังน่ะเหรอ เหตุผลก็เพราะว่า ฉันเป็นคนมีอดีตน่ะ",
  str_voice_1701091_7 = "ผู้มาเยือนเข้าไปในเมืองหิน แม้ว่าเจ้าหญิงในชุดหนังกวางจะรู้ดีว่ากวางมีความสำคัญมากแค่ไหน แต่เธอก็ไม่สนใจอีกต่อไป",
  str_voice_1701091_8 = "ต่อให้กาลเวลาผ่านพ้นไปนาน... ฉันก็ไปกับเธอไม่ได้ ฉันต้องอยู่กับแสงดาวสลัว... เปล่า ไม่ใช่แบบนั้น\nคำว่า \"ไป\" ไม่ได้หมายถึงเดิน แต่เป็นการเปรียบเทียบน่ะ",
  str_voice_1701091_9 = "จากนี้ไป เธอจะต้องเล่าขานเรื่องราวเหล่านี้ เพราะว่าเธอยังเด็กและจะอยู่ที่นี่หลังจากพวกเราจากไป...\nไม่สิ ว่าไปเรื่องนั้นอาจไม่แน่นอน",
  str_voice_1701091_10 = "โอ้ว ผืนป่า ป่าของฉัน อยากให้ฟังความทุกข์ของฉันหน่อย... เพลงกล่อมเด็กโบราณ แต่ฉันลืมไปแล้วว่าร้องยังไง ก็เลยได้แต่ท่องเอา",
  str_voice_1701091_11 = "อยากฟังเรื่องต่อเหรอ ก็ได้ หลายปีต่อมา เมื่อดวงดาวเลือนลาง",
  str_voice_1701091_12 = "หากดวงดาวกลายเป็นอุกกาบาตแล้วตกลงมา มันอาจทำลายล้างดินแดนที่ห้ำหั่นกันอย่างดุเดือด และนำความสงบสุขกลับคืนมา",
  str_voice_1701091_13 = "ทั้งห้าคนมาถึงทางแยก ใครบางคนพูดขึ้นมาว่า \"นี่คือที่ที่เราต้องแยกกัน\"",
  str_voice_1701091_14 = "วันนั้นฉันเลือกยอมรับการโจมตีของเคลย์มอร์ และยอมรับกับการที่เขาต้องการตัดความสัมพันธ์ทั้งหมด",
  str_voice_1701091_15 = "ไม่มีอะไรพิเศษให้เธอเลย ยกเว้นมงกุฎที่ขึ้นสนิม",
  str_voice_1701091_16 = "มีแต่เธอกับสิ่งมีชีวิตบริสุทธิ์อื่น ๆ เท่านั้นแหละที่เต็มใจเข้าใกล้ฉัน",
  str_voice_1701091_17 = "ฉันเผลอหลับไปนานแค่ไหนเหรอ การได้ทักทายตอนเช้าแบบนี้... ช่างวิเศษจริง ๆ",
  str_voice_1701091_18 = "ท่ามกลางรากที่บิดเบี้ยว วิญญาณที่ไร้หัวใจได้ตื่นขึ้นมา... ไม่เสียใจที่ปลุกฉันใช่ไหม",
  str_voice_1701091_19 = "ในยามราตรี ท่ามกลางความหนาวเหน็บ แสงสลัวแห่งความตาย... สถานที่แห่งนี้คือที่เดียวที่เราจะได้พบกัน",
  str_voice_1701091_20 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว พระราชาทรงเขียนพระราชสาส์นว่า \"จงสังหารและฝังทันที\"",
  str_voice_1701091_21 = "ดินแดนที่เคยมืดมิดไม่ต้องการดวงดาวเพื่อส่องแสงอีกต่อไป",
  str_voice_1701091_22 = "เราคือนักล่าที่มีความอดทนสูง",
  str_voice_1701091_23 = "เราต้องระวังอิคลิพไซท์ แม้ว่าจะไม่เกลียดพวกมัน แต่การทำลายพวกมันย่อมเป็นทางเลือกที่ดี",
  str_voice_1701091_24 = "ฉันเสนอให้ฟรอสต์ไฟร์ออกไป ทำให้เธอโกรธมากจนเผาเสื้อผ้าของฉัน",
  str_voice_1701091_25 = "มันคือความจริงที่รีกัลสร้างปัญหามากกว่าฟรอสต์ไฟร์",
  str_voice_1701091_26 = "นี่ไม่ใช่สิ่งที่ฉันเลือก แต่การเล่าต่อเรื่องราวเหล่านี้เป็นหน้าที่ของฉัน",
  str_voice_1701091_27 = "ฉันไม่รังเกียจ แต่บางครั้งความไม่แยแสของฉันก็ส่งผลกับการตัดสินใจ",
  str_voice_1701091_28 = "ถ้าถามความเห็นฉัน... เธอต้องระวัง อย่าปล่อยให้มันเป็นอาวุธ",
  str_voice_1701091_29 = "เธอเป็นใครเหรอ อ๋อ ฉันเข้าใจแล้ว เรื่องใหม่สินะ กาลครั้งหนึ่งเมื่อนานมาแล้ว\nสายลมที่พัดผ่านผืนป่าที่มัวหมองได้ปลุกเหล่าดวงดาวที่มืดมิด",
  str_voice_1701091_30 = "ยังต้องการสิ่งนี้อยู่ไหม",
  str_voice_1701091_34 = "ได้เวลาล่าแล้ว",
  str_voice_1701091_35 = "ค่ำคืนของนักล่า",
  str_voice_1701091_36 = "แสงจันทร์สาดส่องเหยื่อของฉัน",
  str_voice_1701091_37 = "ออกล่าในความรุ่งโรจน์ของชีวิต",
  str_voice_1701091_38 = "ในค่ำคืนสู่การต้อนรับรุ่งอรุณ",
  str_voice_1701091_39 = "ท่ามกลางต้นไม้",
  str_voice_1701091_40 = "ท่ามกลางผืนป่า",
  str_voice_1701091_41 = "ทำลายล้างศัตรูให้มากที่สุด",
  str_voice_1701091_42 = "ฉันก็แค่ทำตามหน้าที่",
  str_voice_1701091_43 = "เอาอีกที ครั้งนี้ไม่รอดแน่",
  str_voice_1701091_44 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว... ไม่ ฉันไม่ค่อยชอบเล่าสักเท่าไหร่ แต่เรื่องนี้เธอต้องรู้ไว้",
  str_voice_1701091_45 = "นี่อะไรเหรอ",
  str_voice_1701091_46 = "ดูเหลือเชื่อแล้วก็วินเทจหน่อย ๆ",
  str_voice_1701091_47 = "แบบนี้สินะที่เขาเรียกว่า \"ความหวังดี\"",
  str_voice_1701091_48 = "ฉันคงได้ยิ้มเเก้มปริแน่",
  str_voice_1701091_49 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว ดวงดาวทั้งห้าหายตัวไปอย่างเงียบ ๆ เหมือนเรื่องราวที่ถูกเขียนไว้หลังจากที่พวกเขาถือกำเนิดขึ้น... แต่ก็ยังคงมีคำถามที่ว่า \"มีกันแค่สี่คนไม่ใช่เหรอ\"",
  str_voice_1701091_50 = "เพื่อเติมเต็มส่วนที่ขาดหายไปในเนื้อเรื่อง ฟรอสต์ไฟร์มักหัวเสียตลอด ส่วนรีกัลก็เอาแต่นิ่งเงียบ เรควียมไม่เคยยิ้ม และเคลย์มอร์ชอบปฏิเสธข้อเสนอของฉัน แต่ก็ยังหยิบดาบขึ้นมา...",
  str_voice_1701091_51 = "ในที่สุด โครงกระดูกของกวางผู้เล่าเรื่องก็จ้องมองผู้มาเยือนท่ามกลางแสงจันทร์... มันรู้ว่าคนฟังจะเข้าใจทุกอย่างเกี่ยวกับห้าคนนั้น และรู้สึกขอบคุณ",
  str_voice_1701091_52 = "Alchemy Stars...?",
  str_voice_1701091_53 = "กาลครั้งหนึ่งเมื่อนานมาแล้ว...",
  str_voice_1701091_54 = "อ้า... อรุณสวัสดิ์",
  str_voice_1701091_55 = "บ่าย ๆ แบบนี้อากาศดีจัง",
  str_voice_1701091_56 = "ฉันมองเห็นแสงจันทร์ด้วยล่ะ",
  str_voice_1701091_57 = "ฉันคิดถึงวันที่โลกถูกฟื้นฟูขึ้นมาใหม่",
  str_voice_1701101_1 = "แม้ฉันจะเป็นทหารมียศที่จะปฏิบัติตามคำสั่งของเธอในการต่อสู้ แต่ก็อย่าเพิ่งได้ใจไป!",
  str_voice_1701101_2 = "ครั้งหนึ่งฉันเคยถูกเรียกว่านักบุญ แต่ฉันไม่ได้จัดการเรื่องการสารภาพบาปและการชดใช้ เธอต้องไปหาคนอื่นแล้วล่ะ",
  str_voice_1701101_3 = "เอ๊ะ ผู้นำทางอยู่ไหนนะ อ้าว อยู่นั่นเอง กลมกลืนกับคนอื่นมากเลย อย่างกับพื้นหลังแน่ะ",
  str_voice_1701101_4 = "ทำไมเรียกว่าเรเควียมน่ะเหรอ เพราะฉันสามารถมองเห็นวิญญาณน่ะสิ เช่นพวกที่กำลังขี่คอเธออยู่นั่นไง... ล้อเล่นน่ะ ฮ่า ฮ่า",
  str_voice_1701101_5 = "มาอยู่ใกล้ฉันไม่ดูตาม้าตาเรือ... ถ้าโดนแทงเข้า ไม่รู้ด้วยนะ ผู้นำทาง...",
  str_voice_1701101_6 = "นี่ ไปหาอะไรทำดีกว่าไหม ไม่ต้องจับตาดูขนาดนั้นก็ได้ ฉันไม่ไปไหนหรอกน่า",
  str_voice_1701101_7 = "ถ้าไม่มีอะไรทำก็มาซ้อมกับฉันไหมล่ะ อย่ามองแบบนั้นสิ ฉันเคยสังหารหมาป่าด้วยหมัดเดียวมาก่อนนะ... กับอีแค่ผู้นำทางตัวน้อย ๆ ที่น่าสงสาร ไม่ต้องเปลืองแรงมาก",
  str_voice_1701101_8 = "นับยังไงฉันก็ยังไม่ถึง 19 ปี... หรือเธอแค่อยากรู้ว่าจะเกิดอะไรขึ้นกับคนที่ย่างกริลล์ฉันแบบนี้",
  str_voice_1701101_9 = "จริง ๆ แล้ว ถ้าลองคิดดู เธอก็เป็นคนดีเหมือนกัน... ตอบแทนด้วยการเรียกว่า \"ที่รัก\" ดีไหมนะ เห็นด้วยไหม ฉันแค่ล้อเล่นน่า",
  str_voice_1701101_10 = "ลา ลา ลา... ฉันเคยชินกับชีวิตสบาย ๆ แบบนี้ ตอนนี้เธอก็ว่างอยู่เหมือนกัน ฉันมาทำตัวชิล ๆ กับเธอให้เต็มที่ดีไหมนะ",
  str_voice_1701101_11 = "เข้าใจแล้ว เข้าใจแล้ว ปล่อยให้เป็นหน้าที่ของนักบุญผู้เงียบงัน และเฟรย่าผู้ยิ่งใหญ่ \"เรเควียม\" จากนักล่าผู้เงียบงัน เพื่อช่วยเหลือผู้นำทางที่ไร้ประโยชน์ จะให้ทำอะไรล่ะ เอางั้นจริงเหรอ",
  str_voice_1701101_12 = "ชุดดูเบาไปเหรอ พอมาคิดดูแล้ว คาถาของฉันสามารถย่างสดพวกอิคลิพไซท์ได้จากระยะไกล ฉันก็เลยไม่ต้องจัดเต็มเหมือนอาดราส",
  str_voice_1701101_13 = "อยากให้ฉันเรียกเธอเหมือนแมวเหรอ นี่เธอโอเครึเปล่าเนี่ย ตอนนี้ฉันเป็นห่วงสุขภาพจิตของเธอมากเลย",
  str_voice_1701101_14 = "ถ้าฉันได้อัดผู้นำทางที่มาแตะต้องตัวฉัน บางทีพวกเขาอาจจะเรียกฉันว่า \"นักบุญผู้ไร้เทียมทาน\" ก็ได้... น่าสนใจดีนะ หึหึ",
  str_voice_1701101_15 = "สุขสันต์วันเกิด! มาดูสิว่าโตขึ้นแค่ไหนแล้ว! อึ้ย ใกล้เกินไป! คิดอะไรเนี่ยถึงเอาหน้ามาใกล้ฉัน ทะลึ่ง!",
  str_voice_1701101_16 = "วันนี้มีแผนยัง ไม่มีงั้นเหรอ ไม่น่าเชื่อ... อยากฟังแผนฉันไหมล่ะ",
  str_voice_1701101_17 = "อรุณสวัสดิ์ นึกว่าจะนอนถึงบ่ายเสียอีก ยังไงก็สวัสดีตอนเช้านะ",
  str_voice_1701101_18 = "ฉันตัดสินใจแล้วว่าจะช่วยผู้นำทางวางแผนสำหรับวันนี้ ว่าไงนะ\nมันผ่านไปแล้วเหรอ ให้ตายสิ อดช่วยเลย",
  str_voice_1701101_19 = "ก็ได้ งั้นฉันไปพักล่ะ เธอมาเข้ากะแทนได้เลย ผู้นำทาง... ว่าไงนะ ไม่เอาเหรอ พูดแบบนั้นได้ไง",
  str_voice_1701101_20 = "อะไรที่ผ่านไปแล้วก็ให้แล้วกันไป หลังจากหลับไปนาน ฉันก็ไม่ค่อยรู้สึกอะไรกับอดีตที่ผ่านมา... แต่มันก็สนุกดีที่ได้เดินเตร่อยู่ที่นี่แล้วค้นหาเป้าหมายต่อไป",
  str_voice_1701101_21 = "อิลลูมินาและลูโมโพลิสดูเหมือนจะเต็มไปด้วยความน่าเบื่อ... ส่วนนอร์ธแลนด์... ครั้งหน้าอย่าลืมพาฉันไปด้วยนะ",
  str_voice_1701101_22 = "เราเป็นผู้ประนีประนอมแห่งชายแดน!",
  str_voice_1701101_23 = "เกลียดพวกมัน เกลียดมาก\nแม้ว่าฉันจะไม่ใช่คนดีนัก ฉันก็อยากจะอัดหน้าพวกมันจริง ๆ",
  str_voice_1701101_24 = "สิ่งต่าง ๆ ระหว่างฟรีกสันและซินเธียเคยซับซ้อน ได้ยินมาว่าครั้งหนึ่งฟรีกสันเคยทำร้ายเธอด้วย แต่ตอนนี้พวกเขาญาติดีกันแล้ว",
  str_voice_1701101_25 = "อาดราสทรงพลังมาก ไม่ว่าจะเรื่องความแข็งแกร่งหรือเวทมนตร์ เดี๋ยวนะ ผู้นำทาง นี่อิจฉาเหรอ น่ารักนะเราเนี่ย...",
  str_voice_1701101_26 = "ทำไมฉันถึงชอบช็อกโกแลตและขนมหวานอื่น ๆ ไม่ได้ล่ะ! ใคร ๆ เขาก็ชอบกันทั้งนั้น... หุบปากนะ อย่าได้พูดสอดเชียว!",
  str_voice_1701101_27 = "ฉันเกลียดอิคลิพไซท์กับเธอ โอ๋ โอ๋ ไม่ต้องร้องนะ ขอโทษ ๆ... ถ้าเทียบกันแล้ว ฉันชอบเธอมากกว่าล่ะ",
  str_voice_1701101_28 = "ฉันไม่มีความคิดเรื่องอื่นนอกจากการอยู่อย่างสุขสบาย โทษทีนะ",
  str_voice_1701101_29 = "ยินดีที่ได้รู้จัก ฉันชื่อเรเควียม อยู่กับนักล่าผู้เงียบงัน ยังไงฉันก็จะสู้เอง ช่วยไปให้พ้น ๆ ด้วย",
  str_voice_1701101_30 = "ว้าว! นั่นแหละ แบบนั้นแหละ",
  str_voice_1701101_34 = "เอาละ... หลบไป ฉันจะโชว์ให้เธอดูเอง!",
  str_voice_1701101_35 = "อย่าให้ใครเหลือรอด!",
  str_voice_1701101_36 = "สายฟ้าคำราม",
  str_voice_1701101_37 = "เถ้าถ่านสู่เถ้าถ่าน",
  str_voice_1701101_38 = "ตายซะ เจ้าโง่!",
  str_voice_1701101_39 = "เดินหน้า ลุยโลด!",
  str_voice_1701101_40 = "มันยังไม่จบ!",
  str_voice_1701101_41 = "ฉันสัญญาว่าจะไม่ทำให้ผิดหวัง",
  str_voice_1701101_42 = "บอกแล้วว่าสบายมาก ซึ้งเลยละสิท่า",
  str_voice_1701101_43 = "*กระซิก* เป็นไปได้ไง ขอโทษนะ...",
  str_voice_1701101_44 = "หืม นี่เธอมาเพื่อขอบคุณโดยเฉพาะเลยเหรอ",
  str_voice_1701101_45 = "เฮ้ ก็ไม่เลวนี่",
  str_voice_1701101_46 = "นึกไม่ถึงเลยนะเนี่ย ฉันจะรับไว้ละกัน",
  str_voice_1701101_47 = "ขอบใจนะ... เลิกจ้องฉันซะที",
  str_voice_1701101_48 = "โอ้ นี่คือ... เอ่อ ขอบใจนะ ฉันชอบมันมากเลย ใจดีจัง",
  str_voice_1701101_49 = "ขอนึกก่อนนะ อา... ฉันค่อนข้างแน่ใจนะว่า ฉันเกิดมาในครอบครัวที่สมบูรณ์ ฉันก็เลยเพอร์เฟ็กต์ขนาดนี้ไงล่ะ ว่าไหม",
  str_voice_1701101_50 = "มันคืองานที่น่าเบื่อ ไม่ว่าฉันจะเป็นที่ปรึกษาทางศาสนาในกองทัพหรือเจ้าหน้าฝึกหัด ฉันต้องจู้จี้คนที่แก่กว่าเรื่องการสารภาพบาปและปฏิบัติตามกฎทั้งวัน หวังว่าผู้ใหญ่จะทำตัวดี ๆ บ้าง",
  str_voice_1701101_51 = "ไม่รู้ว่าเกิดอะไรขึ้นกับฉัน นี่คือสิ่งที่ฉันเป็นหลังจากทำตามคำแนะนำของเคลย์มอร์ ไม่แย่สักเท่าไหร่ใช่ไหม",
  str_voice_1701101_52 = "ใช่ Alchemy Stars!",
  str_voice_1701101_53 = "เฮ้ ผู้นำทาง",
  str_voice_1701101_54 = "เฮ้ เธอตื่นยัง",
  str_voice_1701101_55 = "ตื่นได้แล้ว ไม่ต้องนอนแล้ว!",
  str_voice_1701101_56 = "อา ง่วงจัง...",
  str_voice_1701101_57 = "ปีใหม่แล้ว ได้เวลาพัก!",
  str_voice_1601111_1 = "อย่ามองตาฉันนะ แบบนี้ไม่น่าใช่หน้าขี้อ้อนแล้วล่ะ...",
  str_voice_1601111_2 = "อืม เธอมีความสามารถแบบนั้น... บางทีเธออาจเข้าใจความเจ็บปวดของฉันก็ได้ ถ้าเป็นงั้นละก็ ฉันคิดว่ามันคงจะดีมาก",
  str_voice_1601111_3 = "ดูเหมือนนายมีความสามารถพิเศษบางอย่าง นายสามารถลบความทรงจำของฉันได้ไหม",
  str_voice_1601111_4 = "ไม่ต้องกลัวคริสตัลของฉันหรอก ฉันจะไม่ปล่อยให้มันทำอันตรายเธอ",
  str_voice_1601111_5 = "คริสตัลที่เหมือนดอกไม้นี่... มันคือคริสตัลสีเลือดอันแรกที่งอกมาจากผิวของฉัน...",
  str_voice_1601111_6 = "ในการต่อสู้ อย่ามาจับคริสตัลของฉันล่ะ ไม่งั้้นมันจะขังเธอไว้",
  str_voice_1601111_7 = "ความศรัทธาเหรอ ไม่ว่าจะเชื่ออะไร การอยู่รอดเป็นเพียงแค่ความฝัน...",
  str_voice_1601111_8 = "อยากรู้อดีตของฉันเหรอ ต่อให้รู้ไปมันก็ไม่มีอะไรเปลี่ยนแปลงหรอก หรือเธอจะบอกว่า... สามารถช่วยฉันได้งั้นเหรอ",
  str_voice_1601111_9 = "ฉันจะมีความสุขแบบคนทั่วไปได้ไหมนะ หรือบางทีฉันความสุขแล้วที่นี่...",
  str_voice_1601111_10 = "เมฆสวยมาก... ดีจังที่ไม่ต้องคิดหรือกังวลเรื่องต่าง ๆ",
  str_voice_1601111_11 = "ทำไมเธออยากให้ฉันยืนอยู่นี่ล่ะ เอาเถอะ ฉันจะทำตามที่บอกละกัน...",
  str_voice_1601111_12 = "ทุกคนไม่เข้าใจกัน เพราะความสุขและความเศร้าของพวกเขาอยู่กันคนละโลก",
  str_voice_1601111_13 = "ไม่... อย่าถามเกี่ยวกับครอบครัวของฉัน ฉันไม่มีอะไรแบบนั้นหรอก...",
  str_voice_1601111_14 = "ถ้าฉันไม่ต้องใช้มันเพื่อต่อสู้ ฉันจะเอาคริสตัลพวกนี้ออกไป ไม่ว่าจะอันตรายแค่ไหนก็ตาม...",
  str_voice_1601111_15 = "โอ้ว... สุขสันต์วันเกิด",
  str_voice_1601111_16 = "สงสัยจังว่าวันนี้เป็นวันอะไร เอาเถอะ มีเธออยู่ใกล้ ๆ ฉันรู้ว่ามันจะไม่น่าเบื่อ",
  str_voice_1601111_17 = "ดวงอาทิตย์สว่างเหลือเกิน... เธอว่าไหม",
  str_voice_1601111_18 = "เย็นแล้วเหรอเนี่ย อืม อ้า...",
  str_voice_1601111_19 = "จบไปอีกวันแล้ว...",
  str_voice_1601111_20 = "วิถีของ ทรู ออเดอร์ จะช่วยฉันได้เหรอ เวลาจะบอกเอง...",
  str_voice_1601111_21 = "ลูโมโพลิสลืมฉันไปแล้ว ฉันก็ไม่ได้คิดถึงมันอีกต่อไป ที่นั่นต้อนรับแต่ชนชั้นสูง...",
  str_voice_1601111_22 = "ขอให้ความจริงจงปกป้องเธอ...",
  str_voice_1601111_23 = "พวกเราถึงคราวซวยแล้วล่ะ... พวกมันถูกล่ามด้วยโซ่ตรวนของมันเองใช่ไหม",
  str_voice_1601111_24 = "บางครั้งเฟาสต์ก็น่ากลัว แต่ถ้าไม่มีเขา ฉันคงกลายเป็นคริสตัลยักษ์ไปแล้ว...",
  str_voice_1601111_25 = "ฉันสามารถรับรู้ได้ถึงความเจ็บปวดของเอซี่ แต่ชีวิตของเธอทำให้ฉันอดอิจฉาไม่ได้จริง ๆ...",
  str_voice_1601111_26 = "กระเป๋าเดินทางสีขาวของเฟาสต์เหลือเชื่อมาก มันรักษาความเจ็บปวดของฉันได้ มันคือของขวัญจากสวรรค์...",
  str_voice_1601111_27 = "แม้ว่ามันจะปกป้องฉันได้ แต่ก็จะกลืนกินฉันเช่นกันกัน... ถ้าเป็นไปได้ ฉันไม่ควรไปยุ่งกับมัน",
  str_voice_1601111_28 = "โคลอสซัสสมชื่อจริง ๆ แต่สิ่งที่ฉันสนใจมากกว่าคือผู้นำทางที่สั่งการโคลอสซัสนี่แหละ...",
  str_voice_1601111_29 = "ฉันชื่อเบริล ไม่ต้องกลัวคริสตัลสีเลือดของฉันหรอก มันไม่ทำร้ายเธอ...",
  str_voice_1601111_30 = "คาเมลเลียสวยกว่าเยอะเลย",
  str_voice_1601111_31 = "มันกำลังแพร่กระจาย",
  str_voice_1601111_32 = "คริสตัลสีเลือดกำลังเบ่งบาน...",
  str_voice_1601111_33 = "ไม่แน่นะ... ฉันอาจจะกำจัดออกไปได้",
  str_voice_1601111_34 = "เธอจะไปกับฉันไหม",
  str_voice_1601111_35 = "คริสตัลกำลังรวมตัว",
  str_voice_1601111_36 = "พวกมันมาแล้ว",
  str_voice_1601111_37 = "สนามพลัง!",
  str_voice_1601111_38 = "คริสตัลสีเลือด!",
  str_voice_1601111_39 = "คริสทาลัส คาเมเลีย",
  str_voice_1601111_40 = "เบ่งบาน!",
  str_voice_1601111_41 = "ไปด้วยกันเถอะ",
  str_voice_1601111_42 = "ชนะเหรอเนี่ย เยี่ยมเลย...",
  str_voice_1601111_43 = "อืม... แพ้ก็คือแพ้...",
  str_voice_1601111_44 = "ขอบคุณที่เป็นห่วง... ตอนนี้ฉันดีขึ้นแล้ว",
  str_voice_1601111_45 = "เธอให้ของนี่มาทำไมเหรอ?",
  str_voice_1601111_46 = "เธอรู้เหรอว่าฉันอยากได้มานานแล้ว...",
  str_voice_1601111_47 = "ขอบคุณนะ...",
  str_voice_1601111_48 = "ไม่คิดเลยว่าเธอจะรู้ใจฉันดีขนาดนี้...",
  str_voice_1601111_49 = "ฉันเคยเป็นชนชั้นสูงของลูโมโพลิส แต่ตอนนี้ฉันไม่สามารถกลับไปเป็นแบบเดิมได้อีกแล้ว",
  str_voice_1601111_50 = "ครอบครัวของพวกวิปริตลักพาตัวฉันมา และฝังคริสตัลสีเลือดนี้ไว้ในร่างกายของฉัน... ฉันไม่ได้เกิดมาพร้อมกับมัน",
  str_voice_1601111_51 = "ถ้าย้อนเวลาได้ ฉันยอมโดนคริสตัลสีเลือดฆ่าตายดีกว่าให้ครอบครัวของฉันเดือดร้อน...",
  str_voice_1601111_52 = "Alchemy... Stars",
  str_voice_1601111_53 = "เธออยู่รึเปล่า",
  str_voice_1601111_54 = "อรุณสวัสดิ์",
  str_voice_1601111_55 = "เที่ยงแล้วล่ะ",
  str_voice_1601111_56 = "ดูเหมือนจะตื่นสายนะ",
  str_voice_1601111_57 = "หวังว่าปีใหม่นี้ฉันจะได้พบใครสักคนที่เข้าใจฉัน",
  str_voice_1601111_58 = "อืม... รู้ไหม...",
  str_voice_1601111_59 = "ยังไงก็... ขอบใจนะ...",
  str_voice_1501131_1 = "ในลูโมโพลิสมีนักดนตรีมากมาย และพวกเขาเล่นดนตรีได้ทุกประเภท แต่ก็ไม่ได้หมายความว่าพวกเขาจะเข้าใจดนตรี",
  str_voice_1501131_2 = "เสียงจากเบื้องบนศักดิ์สิทธิ์ที่สุด ว่าไหม มีแต่ฉันเท่านั้นที่เล่นได้ ฉันก็เลยต้องแชร์ให้กับคนทั้งโลก",
  str_voice_1501131_3 = "เปียโนที่ห้องบังคับการก็ไม่ได้แย่ขนาดนั้นหรอก... เธอเล่นเปียโนบนโคลอสซัสมาสิบเจ็ดปีแล้วเหรอ ได้ข่าวว่าเธอเล่นคู่กับไวซ์ ดูเหมือนว่าเธอจะมีเซนส์ทางดนตรีใช้ได้เลยนะเนี่ย",
  str_voice_1501131_4 = "พระเจ้าได้มอบทาสรับใช้ที่เรียกว่า \"อวตารศักดิ์สิทธิ์\" ให้ฉัน ฉันสามารถสั่งการให้พวกมันบรรเลงเพลงสำหรับเธอได้ทั้งคืน...",
  str_voice_1501131_5 = "ได้ยินมาว่าความสามารถทางจิตของชาวเคเลสไทต์มีพลังมาก เธอไม่รู้สึกเหรอว่าเพลงของฉันเอาแน่เอานอนไม่ได้",
  str_voice_1501131_6 = "ฉันได้ยินเสียงของพระเจ้าอีกครั้ง ช่างไพเราะกว่าดนตรีไหน ๆ บนโลก มันจะนำทางฉันให้พบกับการเคลื่อนไหวที่สุดยอด ไม่คิดงั้นเหรอ",
  str_voice_1501131_7 = "สายตาของฉันไม่เป็นไร ฉันใส่แว่นพวกนี้เพื่อให้ได้ฟีลแบบวาทยกรน่ะ",
  str_voice_1501131_8 = "พลังจิตของเธอแข็งแกร่งมากมาย... บางทีเธออาจจะเป็นวาทยกรที่ดีได้นะ",
  str_voice_1501131_9 = "เห็นริบบิ้นที่มือของฉันไหม มันเป็นโบว์เล็ก ๆ น่ารักดีนะว่าไหม ฉันสอนผูกโบว์สวย ๆ แบบนี้ให้เอาป่ะ ฉันเก่งเรื่องนี้จริง ๆ นะ",
  str_voice_1501131_10 = "อืม... นายไม่ชอบเพลงนี้เหรอ อยากฟังเพลงไหนดีล่ะ \"บ้าน\", \"หวนคืน\" หรือบางที \"การเดินทาง\"?",
  str_voice_1501131_11 = "ดูเหมือนว่าจะเป็นจังหวะเหมาะ ๆ ที่อวตารศักดิ์สิทธิ์ของฉันจะขึ้นเวที ว่าไหม ที่นี่เงียบเกินไป... ฉันจะให้พวกมันเล่นเพลงเพื่อทำให้บรรยากาศครึกครื้นขึ้นสักหน่อย",
  str_voice_1501131_12 = "ห้องที่นี่ยอดเยี่ยมมาก ทั้งกว้างและสว่าง สิ่งสำคัญคือดนตรีอะคูสติกนั่นเยี่ยมมากเลย เหมาะสำหรับการฝึกแต่งเพลงดีนะว่าไหม",
  str_voice_1501131_13 = "ริบบิ้นในมือนี่เหรอ? มันควรจะติดไว้กับไม้บาตองของฉัน ฉันแค่เอามาพันไว้รอบมือแบบนี้น่ะ",
  str_voice_1501131_14 = "การแสดงขึ้นอยู่กับพรสวรรค์ นอกจากวาทยกรต้องมีความเชี่ยวชาญในทฤษฎีดนตรีแล้ว ยังต้องมีความสามารถในการประสานงานกับนักดนตรีด้วย นี่คือเหตุผลที่ทำไมจึงหาตัววาทยกรได้ยากมาก",
  str_voice_1501131_15 = "อ้า! ลืมเตรียมของขวัญให้อ่ะ งั้นอวตารศักดิ์สิทธิ์ของฉันจะร้องเพลงวันเกิดให้ฟังละกันนะ",
  str_voice_1501131_16 = "อีกวันสบาย ๆ... อวตารศักดิ์สิทธิ์ของฉันจะร้องเพลงให้ฟังนะ",
  str_voice_1501131_17 = "ตื่นเช้าดูพระอาทิตย์ขึ้นเหมือนกันเหรอ หรือมาเพื่อฟังเสียงผ่อนคลายของธรรมชาติ",
  str_voice_1501131_18 = "นายคงเหนื่อยหลังจากการทำงานหนักมาทั้งวันสินะ พักสักหน่อยเถอะ... ทำไมไม่ไปที่หอบังคับการแล้วเล่นเปียโนผ่อนคลายหน่อยล่ะ ผู้นำทาง",
  str_voice_1501131_19 = "แรงบันดาลใจชอบมาตอนดึก ๆ ฉันก็เลยมักจะเริ่มแต่งเพลงในตอนค่ำ",
  str_voice_1501131_20 = "ทรู ออเดอร์ ดีกว่าลูโมโพลิสมาก อย่างน้อยมันก็ยอมรับเพลงที่มาจากหลากหลายรูปแบบน่ะว่าไหม",
  str_voice_1501131_21 = "ลูโมโพลิสนั้นสง่าและมีระเบียบสังคม แต่ช่างไม่รู้อะไรเลยเกี่ยวกับเพลง...",
  str_voice_1501131_22 = "ขอความจริงจงสถิตกับท่าน และขอให้เพลงจงสถิตกับเธอเช่นกัน",
  str_voice_1501131_23 = "น่าสงสาร... ถ้าพวกเขาไม่รู้วิธีดื่มด่ำกับเสียงเพลง ก็หมดหวังแล้วล่ะ...",
  str_voice_1501131_24 = "วิกตอเรียรู้เรื่องหลายอย่าง นั่นคือเหตุผลที่ฉันติดตามเธอเพื่อค้นหาความเคลื่อนไหวสุดยอด",
  str_voice_1501131_25 = "ถ้าซิคาเรสามารถปลดปล่อยตัวเองจากข้อจำกัดของกฎเกณฑ์ที่เข้มงวดแบบนั้นได้ อนาคตของเธอจะไร้ขีดจำกัด",
  str_voice_1501131_26 = "ต้องมีเพลงบนแผ่นดินใหญ่ที่สามารถแสดงถึงเสียงที่แท้จริงของพระเจ้าได้ สักวันฉันคงได้เจอ...",
  str_voice_1501131_27 = "กฎและข้อบังคับเท่านั้นที่เป็นบ่อเกิดของความสามัญ เช่น นักดนตรีของลูโมโพลิส ไม่คิดงั้นเหรอ",
  str_voice_1501131_28 = "ได้ข่าวว่าเปียโนควบคุมมัน... ดูเหมือนว่าดนตรีจะทรงพลังมากเลยเนอะ ว่าไหม",
  str_voice_1501131_29 = "ฉันจะนำทางให้เอง! ร่วมมือกันแล้วเราจะเปิดรับเพลงแห่งสวรรค์",
  str_voice_1501131_30 = "ความเคลื่อนไหวนี้เริ่มศักดิ์สิทธิ์",
  str_voice_1501131_31 = "ฟังสิ! มันคือเสียงแห่งสวรรค์",
  str_voice_1501131_32 = "ดาวตก จงฟังคำขอของฉัน!",
  str_voice_1501131_33 = "ดูซะ! ฉันคือวาทยกรศักดิ์สิทธิ์!",
  str_voice_1501131_34 = "เสียงแห่งสวรรค์จะนำทางเรา",
  str_voice_1501131_35 = "ความเคลื่อนไหว... เสร็จสมบูรณ์",
  str_voice_1501131_36 = "อวตารศักดิ์สิทธิ์ เตรียมตัวแสดงได้!",
  str_voice_1501131_37 = "วาทยกรศักดิ์สิทธิ์!",
  str_voice_1501131_38 = "พลังศักดิ์สิทธิ์ บรรเลง!",
  str_voice_1501131_39 = "สัมผัสเสียงสะท้อนแห่งนิรันดร์!",
  str_voice_1501131_40 = "ให้สวรรค์นำทางเธอไป!",
  str_voice_1501131_41 = "ทุกคนตามฉันมา",
  str_voice_1501131_42 = "อีกหนึ่งการแสดงที่สมบูรณ์แบบ!",
  str_voice_1501131_43 = "อวตารศักดิ์สิทธิ์ของฉันจะคุ้มกันการถอยทัพให้เอง...",
  str_voice_1501131_44 = "อยากเห็นฉันเป็นวาทยกรไหม",
  str_voice_1501131_45 = "อ้า ขอบคุณนะ",
  str_voice_1501131_46 = "ว้าว ฉันชอบมากเลย!",
  str_voice_1501131_47 = "เธอให้ของขวัญฉันอีกแล้ว!",
  str_voice_1501131_48 = "ไว้ฉันจะแต่งเพลงเพราะ ๆ ให้นะ",
  str_voice_1501131_49 = "ความเคลื่อนไหวขั้นสุดยอดมีอยู่จริงในโลกนี้ มันแสดงถึงเสียงจากสวรรค์ และฉันจะไม่หยุดจนกว่าจะได้ค้นพบมัน",
  str_voice_1501131_50 = "ในวันนั้น เสียงของพระเจ้าดังกึกก้องไปทั่วร่างฉัน มีอุกกาบาตตกลงมาจากท้องฟ้า ชั่วขณะหนึ่ง การเคลื่อนไหวขั้นสุดยอดได้แวบเข้ามาในหัวใจของฉัน แล้วฉันก็เริ่มออกเดินทางเพื่อค้นหามัน",
  str_voice_1501131_51 = "ลูโมโพลิสไม่เคยรู้ว่าบทเพลงคืออะไร นี่คือเหตุผลที่ฉันไม่ถูกเลือกให้เข้าร่วมกับพวกเขา ฉันเลยอยู่ที่บ้านเกิดจนฉันได้พบเส้นทางของตัวเอง",
  str_voice_1501131_52 = "Alchemy Stars",
  str_voice_1501131_53 = "มาร้องเพลงประสานเสียงกันไหม",
  str_voice_1501131_54 = "เอาเพลงที่ได้ยินแล้วแบบลุกจากเตียงเลยเป็นไง",
  str_voice_1501131_55 = "ช่วงเที่ยงไม่มีการแสดง พักสักหน่อย!",
  str_voice_1501131_56 = "ราตรีสวัสดิ์ บทเพลงเซเรเนดของฉันจะส่งเธอเข้านอนเอง",
  str_voice_1501131_57 = "สุขสันต์วันปีใหม่ พร้อมสนุกกับงานรื่นเริงรึยัง",
  str_voice_1601161_1 = "อืม เราวุ่นวายมากที่นี่... ฉันรู้! ขอจดลงกระดาษก่อน",
  str_voice_1601161_2 = "ฉันสงสัยว่าหลักการเบื้องหลังหิ่งห้อยคืออะไร พวกมันน่าอัศจรรย์มาก",
  str_voice_1601161_3 = "เด็กผู้หญิงรีโวลเวอร์นั่นรู้ว่าต้องทำยังไง สุดท้ายแล้วเธอก็คือคนที่พาฉันมาที่เรดีเซล เวรนช์ น่ะ",
  str_voice_1601161_4 = "ในโลกนี้มีไขควงหลายประเภท... อย่าลืมใช้ให้ถูกอันล่ะ",
  str_voice_1601161_5 = "ความยากลำบากของชีวิตเป็นเหมือนสกรูที่ไขไม่ออก บางครั้งก็ต้องใช้ไขควงที่เหมาะสมเพื่อคลายมันออก",
  str_voice_1601161_6 = "ที่นี่ทำให้ฉันเรียนรู้หลายอย่าง ขอบใจที่คอยช่วยเหลือนะ ตอนนี้ฉันสามารถอัปเกรดอุปกรณ์จักรกลได้แล้ว แต่ฉันยังต้องใช้เหล็กเพิ่มอีก...",
  str_voice_1601161_7 = "ฉันจำได้ว่าอิลลูมินาจัดคลาสพิเศษชายล้วนให้ฉัน สงสัยพวกเขาคงกลัวว่าสาว ๆ จะฟุ้งซ่านเกินไป ฮิ ๆ...",
  str_voice_1601161_8 = "อิลลูมินาหางานในโรงงานชายล้วนให้ฉันทำอยู่พักนึง... นั่นคือช่วงเวลาที่หดหู่ที่สุดในชีวิตของฉันเลยละ",
  str_voice_1601161_9 = "มีแต่คนสนใจเขากับหางของฉัน... ไม่รู้เหมือนกันว่าทำไม",
  str_voice_1601161_10 = "ทำไมชอบมองฉันตลอดเลยละ เอ... อยากเห็นงานของฉันแน่เลย เอาสิ มาดูได้เลย",
  str_voice_1601161_11 = "ฉันอยู่ที่นี่อีกสักพักได้ไหม ในที่สุดก็มีโอกาสได้ศึกษาโครงสร้างของโคลอสซัสแล้ว",
  str_voice_1601161_12 = "โคลอสซัสใหญ่อะไรขนาดนี้เนี่ย... เทคโนโลยีมันล้ำสมัยมาก มันสร้างจากวัตถุดิบชั้นเลิศ!",
  str_voice_1601161_13 = "เมื่อไม่กี่วันก่อนฉันได้รับจดหมายประหลาด... อืม ฉันก็ไม่รู้เหมือนกันว่าต้องทำยังไง",
  str_voice_1601161_14 = "อยากเห็นกล่องเครื่องมือของฉันเหรอ ฉันเรียกว่าอัลเลนน่ะ มันเต็มไปด้วยเครื่องมือที่น่าสนใจทั้งนั้นเลย!",
  str_voice_1601161_15 = "อ้าว! วันนี้เป็นวันเกิดเหรอ งั้นก็ สุขสันต์วันเกิดนะ!",
  str_voice_1601161_16 = "วันนี้มีอะไรให้ซ่อมเยอะแยะเลย การซ่อมบำรุงโคลอสซัสประจำวัน คำขอของเรดีเซล เวรนช์ อีกเพียบ... ยาวเหยียดไม่จบไม่สิ้น",
  str_voice_1601161_17 = "อรุณสวัสดิ์ งานซ่อมของฉันไม่ได้ทำนายตื่นใช่ไหม",
  str_voice_1601161_18 = "เย็นแล้วเหรอเนี่ย เกือบหมดวันแล้ว งานซ่อมยังไม่เสร็จเลย",
  str_voice_1601161_19 = "แผนผังนี้วาดยากมาก... ดูเหมือนคืนนี้ยังอีกยาวไกล",
  str_voice_1601161_20 = "ชีวิตในเรดีเซล เวรนช์ อิสระมาก ถ้าไม่ยอมฝักใฝ่ฝ่ายใด ก็แค่ต้องสู้กัน",
  str_voice_1601161_21 = "สภาพแวดล้อมการทำงานในเมืองใต้ดินอิลลูมินาไม่ใช่แค่ร้อนอย่างเดียวนะ มันอุดอู้อยู่แต่กับการทำงานแบบคร่ำครึ เมื่อไหร่พวกเขาจะหัดพลิกแพลงซะบ้าง",
  str_voice_1601161_22 = "เลพิดอส! เจ๋งไปเลย!",
  str_voice_1601161_23 = "พวกอิคลิพไซท์บ้านั่นต้องถูกซ่อมสมองหน่อยแล้ว",
  str_voice_1601161_24 = "เทคนิคของสาวแว่นนั่นน่าประทับใจมาก แทบจะคิดไม่ออกเลยว่าเธอสอนตัวเองทุกเรื่องได้ยังไง",
  str_voice_1601161_25 = "อยากเข้ากับสาวรีโวลเวอร์เป็นเรื่องง่ายมาก เธอมักยิงจากสะโพก และเธอไม่เคยอายที่เห็นฉัน",
  str_voice_1601161_26 = "เครื่องจักรไม่เคยโกหก มันมักจะตรงประเด็นเสมอ ไม่ว่าจะเรื่องงานหรือเรื่องไหน ๆ",
  str_voice_1601161_27 = "เฮ้อ... หวังว่าทุกคนจะตรงไปตรงมามากกว่านี้ เบื่อกับเบาะแสและคำใบ้พวกนี้แต่ละวันเต็มที",
  str_voice_1601161_28 = "มันดีกว่าเลพิดอสมาก... แต่ก็ยากที่จะควบคุม",
  str_voice_1601161_29 = "นายคือผู้นำทางใช่ไหม ยินดีที่ได้รู้จัก ฉันสามารถซ่อมได้ทุกอย่าง แม้แต่โคลอสซัส",
  str_voice_1601161_30 = "อ้า สิ่งนี้มีชิ้นส่วนมากมายเหลือเกิน!",
  str_voice_1601161_31 = "ได้เวลาอัปเกรดกล่องเครื่องมือแล้ว",
  str_voice_1601161_32 = "ฉันเข้าใจแล้ว!",
  str_voice_1601161_33 = "จิตจักรกล จุดระเบิด!",
  str_voice_1601161_34 = "ถึงตาฉันแล้วเหรอ",
  str_voice_1601161_35 = "รวมร่างสมบูรณ์!",
  str_voice_1601161_36 = "ตื่นแล้วเหรอ ประแจ!",
  str_voice_1601161_37 = "จักรกลโอเวอร์โหลด!",
  str_voice_1601161_38 = "ระเบิดไปเลยพวก!",
  str_voice_1601161_39 = "ลุกขึ้นมา อัลเลน!",
  str_voice_1601161_40 = "ยิงให้น่วม อัดให้หนัก!",
  str_voice_1601161_41 = "สบายหายห่วง!",
  str_voice_1601161_42 = "พวกเธอเหลือเชื่อมากเลย!",
  str_voice_1601161_43 = "จ๊าก... ประแจฉันหัก...",
  str_voice_1601161_44 = "ต้องการอะไรเหรอ ได้สิ แต่ว่ารอก่อนนะ ตอนนี้ฉันกำลังยุ่งอยู่",
  str_voice_1601161_45 = "ขอบใจนะ! ถูกใจมากเลย ฮ่าฮ่า",
  str_voice_1601161_46 = "ไม่รู้ว่าจะขอบคุณยังไงดี...",
  str_voice_1601161_47 = "เธอนี่ชอบมีของมาให้ตลอดเลย",
  str_voice_1601161_48 = "ขอบคุณมาก! ฉันจะตอบแทนยังไงดี",
  str_voice_1601161_49 = "เลพิดอสชอบเสียตลอดเวลา... ถ้าฉันไม่ซ่อมเมื่อสองปีที่แล้ว ป่านนี้คงยังหลับอยู่ในรังโน่นแหละ",
  str_voice_1601161_50 = "ฉันไม่ค่อยดังในหมู่ผู้ชายอิลลูมินา... แปลกมากที่พวกเขาขับไล่ฉันออกมา",
  str_voice_1601161_51 = "ฉันคิดว่าฉันสืบทอดเขาและหางมาจากบรรพบุรุษห่าง ๆ ปู่ทวดของฉันคิดว่าน่าจะเป็นแบบนี้ เขาก็ไม่มีเพื่อนผู้ชายมากเหมือนกัน",
  str_voice_1601161_52 = "Alchemy Stars",
  str_voice_1601161_53 = "เฮ้ เธออยู่ไหม",
  str_voice_1601161_54 = "ตื่น ตื่น วันนี้มีอะไรให้ฉันซ่อมไหม",
  str_voice_1601161_55 = "เฮ้ เที่ยงกินไรดี",
  str_voice_1601161_56 = "โอย! หัวหมุนไปหมดแล้ว พักกันหน่อยเถอะ",
  str_voice_1601161_57 = "ปณิธานปีใหม่นี้ก็คือ เพิ่มความก้าวหน้าในการผลิตเครื่องจักรกลขึ้นอีก 10 จุด!",
  str_voice_1501141_1 = "อยากผูกโบว์ไหม แม้ว่ามันเป็นเครื่องประดับเล็ก ๆ แต่ก็เข้ากับชุดที่เธอใส่อยู่นะเนี่ย",
  str_voice_1501141_2 = "คุ้นเคยกับการค้าของนักล่าเงินรางวัลไหม อันที่จริงมันเกือบจะเหมือนกับของทหารรับจ้างนะ แต่มีระดับความเป็นอิสระที่สูงกว่า เพียงแค่จัดการเป้าหมายแล้วก็รับเงินได้เลย",
  str_voice_1501141_3 = "หิ่งห้อยตัวเล็ก ๆ พวกนี้ที่บินอยู่รอบ ๆ ที่นี่ช่างน่ารักเหลือเกิน จนฉันอดไม่ได้ที่จะใช้มันเป็นเป้าฝึกซ้อม แต่ไม่ต้องกังวล ฉันไม่ทำพวกมันเจ็บหรอก!",
  str_voice_1501141_4 = "ทุกคนบอกว่าฉันมีเสน่ห์ แต่จริง ๆ แล้วก็เป็นเพราะเหล้าเข้าปากน่ะ",
  str_voice_1501141_5 = "แส้ของฉันไม่เพียงแต่ดักจับเป้าหมายเท่านั้น แต่ยังลุกเป็นไฟได้ด้วย ฉันตั้งชื่อแส้นี้ว่า \"คาเรนนีน่า\" อย่าลืมซะล่ะ",
  str_voice_1501141_6 = "เห็นม้าตัวนี้ไหม ชื่อว่าแอนนา เราอยู่ด้วยกันมาตั้งแต่เด็ก แม้แต่ความตายก็พรากเราจากกันไม่ได้",
  str_voice_1501141_7 = "แอนนาของฉัน เป็นม้าตัวใหญ่ เคยตายแล้วเกิดใหม่ แผลบนหน้าผากคือหลักฐานของเรื่องนี้",
  str_voice_1501141_8 = "ทางเดินของโคลอสซัสค่อนข้างกว้าง มันกำลังเรียกร้องหาฉันอยู่!",
  str_voice_1501141_9 = "อยากดื่มกับฉันไหม ชงเหล้าให้ฉันด้วยล่ะ... แต่ถ้าไม่มี เอาน้ำเมาอย่างอื่นก็ได้",
  str_voice_1501141_10 = "ถ้าตอนนี้ไม่มีเรื่องด่วนอะไร มาคิดเกี่ยวกับสิ่งที่เราต้องทำให้สำเร็จและวางแผนง่าย ๆ เช่น เราจะทำยังไงเกี่ยวกับการพัฒนาความสามารถของเธอกัน...",
  str_voice_1501141_11 = "อืม... อยากให้ฉันอยู่ที่นี่เหรอ ถ้าฉันไปไหนมาไหนไม่ได้ ฉันคงจะจิตตกแน่ ๆ",
  str_voice_1501141_12 = "ได้ยินว่ามีผับในทะเลทรายเรดีเซลที่ขายเหล้ารสชาติพิเศษ ว่าง ๆ ไปดื่มกันหน่อยไหม",
  str_voice_1501141_13 = "คอยจับตาดูฉันอยู่ตลอดใช่ไหม อย่าเตลิดใจไปล่ะ... ฉันมีกองทัพแฟนคลับคอยดูแลฉันอยู่",
  str_voice_1501141_14 = "ทุกคนมักบ่นว่าไม่มีประกาศล่ารางวัลในอัมบราตัน... ฮ่า นั่นเพราะว่าฉันเองแหละที่เก็บเรียบ",
  str_voice_1501141_15 = "สุขสันต์วันเกิดนะ จัดปาร์ตี้วันเกิดหน่อยไหม ไม่ต้องห่วง ฉันจะจัดการทุกอย่างให้เอง!",
  str_voice_1501141_16 = "ช่างเป็นวันที่มีความสุขจริง ๆ มาขี่ม้าด้วยกันไหม ถ้าไม่รู้วิธี ฉันจะสอนให้เอง การขี่ม้าคือพื้นฐานสำหรับชนชั้นสูงทุกคน",
  str_voice_1501141_17 = "การตื่นเช้าคือนิสัยที่ดี มันเป็นข้อพิสูจน์ถึงความมีวินัยนะ ผู้นำทาง",
  str_voice_1501141_18 = "มื้อเย็นกับเหล้าแก้วหนึ่ง... ไม่ใช่สำหรับนาย แต่สำหรับฉัน ผู้นำทาง นี่คือสิ่งที่เรียกว่า \"หมวกนอน\"...",
  str_voice_1501141_19 = "อ้อ... ความเหนื่อยล้าเล่นงานฉันซะแล้ว ต้องพักหน่อยล่ะ นายไม่ง่วงเหรอ",
  str_voice_1501141_20 = "แม้ว่าทรู ออเดอร์ จะมีสมาชิกไม่เยอะ แต่พวกเรามีทักษะลับที่ทรงพลัง และสามารถชุบชีวิตคนตายได้...",
  str_voice_1501141_21 = "อัมบราตันคือส่วนผสมของความดีและความชั่วอย่างแท้จริง ถ้าไม่ใช่ที่นั่น ก็คงหาไม่ได้จากที่ไหนแล้วล่ะ...",
  str_voice_1501141_22 = "ขอความจริงจงกักขัง ไม่สิ จงสถิตอยู่กับเธอ",
  str_voice_1501141_23 = "อิคลิพไซท์น่ะเหรอ ในสายตาของฉัน พวกมันก็แค่รางวัลที่มีขา",
  str_voice_1501141_24 = "วิกตอเรียต้องมาจากเชื้อสายที่ทรงพลังแน่เลย ไม่งั้นเธอคงไม่สามารถควบคุมลูมินาติกส์ที่แข็งแกร่งแบบนั้นได้...",
  str_voice_1501141_25 = "แม้ว่าเธอจะไม่ได้เกิดมาในตระกูลที่มีชื่อเสียง แต่ซิคาเรเป็นชนชั้นสูงที่แท้จริง โดยเฉพาะอย่างยิ่งในแง่ความรับผิดชอบของเธอ",
  str_voice_1501141_26 = "ในโลกนี้สิ่งที่ทำให้ฉันยอมละทิ้งฐานะชนชั้นสูงได้ ก็คงจะมีแต่เหล้าดี ๆ นั่นแหละ",
  str_voice_1501141_27 = "เวลามีใครมายุ่งเรื่องของฉัน ฉันอยากจะเอาแส้ไปรัดคอซะ แล้วก็มัดให้แน่น ๆ...",
  str_voice_1501141_28 = "ถึงแม้จะใหญ่ แต่มันก็บินได้ ฉันล่ะสงสัยว่าถ้าแข่งกับแอนนาจะเป็นยังไง",
  str_voice_1501141_29 = "เจเนวีฟ นักล่าเงินรางวัลพิเศษพร้อมรับใช้ อยากให้ฉันทำอะไรล่ะ ผู้นำทาง ถ้าผลตอบแทนสมน้ำสมเนื้อ ฉันยินดีรับฟังเสมอ",
  str_voice_1501141_30 = "ฟู่ววว ฟู่ววว ผ่อนคลายหน่อยไหม",
  str_voice_1501141_31 = "อย่างที่คิดไว้เลย พลังของฉันเพิ่มขึ้นอีกแล้ว",
  str_voice_1501141_32 = "แอนนา ออกรบ!",
  str_voice_1501141_33 = "ฟู่ววว ฟู่ววว จงลุกเป็นไฟ!",
  str_voice_1501141_34 = "กักขังศัตรู!",
  str_voice_1501141_35 = "เพลิงพิชิต! เตรียมตัวซะ!",
  str_voice_1501141_36 = "พร้อมลงมือ!",
  str_voice_1501141_37 = "เผา!",
  str_voice_1501141_38 = "ยอมแพ้ซะ!",
  str_voice_1501141_39 = "ลิ้มรสเปลวไฟซะ!",
  str_voice_1501141_40 = "หายนะในกองเพลิง!",
  str_voice_1501141_41 = "เธอตัดสินใจถูกแล้วล่ะ",
  str_voice_1501141_42 = "ไม่ทำให้ฉันผิดหวังเลยสักนิด",
  str_voice_1501141_43 = "ฉันไม่สามารถกักขังพวกมันได้...",
  str_voice_1501141_44 = "ฉันเผลอไปมัดเธอเหรอ ไม่ต้องห่วงนะฉันไม่ทำเธอเจ็บหรอก",
  str_voice_1501141_45 = "โอ้ ขอบคุณนะ",
  str_voice_1501141_46 = "ขอบคุณนะ ไว้ไปดื่มกัน!",
  str_voice_1501141_47 = "ขอบคุณนะ ฉันจะจำไว้",
  str_voice_1501141_48 = "อ้า หัวใจของฉันตกลงหลุมพรางของเธอแล้ว",
  str_voice_1501141_49 = "เพเทียเบิร์กคือหนึ่งในไม่กี่แห่งที่ยังไม่ถูกทำลายจากวิกฤติดาร์กโอเวอร์ และฉันโชคดีมากที่มีโอกาสได้รู้",
  str_voice_1501141_50 = "ถ้าวิกตอเรียไม่ได้คืนชีพแอนนาที่รักของฉัน ฉันคงไม่ได้เข้าร่วมทรู ออเดอร์",
  str_voice_1501141_51 = "สโมกกี้เคยทำให้ฉันอับอายและทำให้ครอบครัวของฉันบาดเจ็บ ดังนั้นฉันต้องทำทุกวิถีทางเพื่อทำให้เธอคุกเข่า และเอาชนะเธอให้ได้อย่างสมบูรณ์แบบ!",
  str_voice_1501141_52 = "Alchemy Stars",
  str_voice_1501141_53 = "ขอโทษนะ",
  str_voice_1501141_54 = "อรุณสวัสดิ์",
  str_voice_1501141_55 = "สวัสดียามบ่าย",
  str_voice_1501141_56 = "ค่ำคืนอีกยาวนาน",
  str_voice_1501141_57 = "ปีใหม่นี้ เราต้องวางแผนที่ดีที่สุดต่อไป",
  str_voice_1601121_1 = "เปลี่ยนชุดบ้างไหมเนี่ย หรือว่ามีแค่ชุดแบบเดียว 300 ตัว",
  str_voice_1601121_2 = "เลิกกวนฉันด้วยคำถามนู่นนี่นั่นสักที... เธอนี่เหมือนเด็กที่ไม่เข้าใจอะไรเลยหือ!",
  str_voice_1601121_3 = "บางคนบอกว่ารองเท้าของฉันเดินเสียงดังเกินไป... แต่แย่หน่อยนะ ฉันชอบมันมากอ่ะ!",
  str_voice_1601121_4 = "ฉันยิงบอลไฟใส่หิ่งห้อยได้ไหม ยังไงซะพวกมันก็สามารถซ่อมตัวเองได้...",
  str_voice_1601121_5 = "ลองคิดดูสิว่ามันยอดเยี่ยมแค่ไหนที่สามารถหย่อนบอลไฟจากโคลอสซัสได้ โดยเฉพาะตอนที่เรากำลังไล่ล่าอิคลิพไซท์",
  str_voice_1601121_6 = "เห็นแมนติคอร์ที่ลุกเป็นไฟนี่ไหม สวยเนอะ",
  str_voice_1601121_7 = "ฉันเคยสู้กับอิคลิพไซท์ไปพร้อมกับชนชั้นสูงของลูโมโพลิส ฮ่าฮ่า คิดไม่ถึงละสิ ใช่ไหมล่ะ",
  str_voice_1601121_8 = "ไฟจะพ่นออกมาเวลาฉันนอนกรนตอนกลางคืน... อย่าลืมไปเตือนหิ่งห้อยล่ะ!",
  str_voice_1601121_9 = "ฉันคือส่วนหนึ่งของตระกูลแมนติคอร์ ไม่เคยได้ยินเหรอ ช่างเถอะ",
  str_voice_1601121_10 = "เบื่อจัง... มาจุดไฟกันดีกว่า ส่วนหิ่งห้อยไว้ค่อยเก็บกวาดทีหลัง",
  str_voice_1601121_11 = "อยากให้ฉันยืนตรงนี้เพื่อให้คนอื่นมองเหรอ แล้วถ้าใครผ่านมาฉันจุดไฟใส่เลยจะได้ไหม",
  str_voice_1601121_12 = "ดูเหมือนเธออยากได้อะไรซักอย่าง... ฉันล้างหน้าด้วยไฟให้เอาไหม ไม่เจ็บหรอก",
  str_voice_1601121_13 = "ฝึกซ้อมเหรอ ไม่เอาอ่ะ เชื่อฉันสิ พลังแห่งไฟมันเกิดขึ้นจากภายใน",
  str_voice_1601121_14 = "ฉันพบกับเครื่องประดับที่สวยงามในอัมบราตัน เรากลับไปซื้อกันดีไหม",
  str_voice_1601121_15 = "ฉันจุดเทียนฉลองวันเกิดให้นะ",
  str_voice_1601121_16 = "มีแผนต่อสู้สำหรับวันนี้ไหม",
  str_voice_1601121_17 = "แสงอาทิตย์มันแยงตาฉัน ทำไมไม่มีใครปิดม่านเนี่ย",
  str_voice_1601121_18 = "ผ่านไปจะหมดวันแล้ว ฉันยังไม่ได้ทำะไรเลย อิคลิพไซท์สักกะตัวก็ยังไม่ได้เห็น เรื่องสู้กับพวกมันคงไม่ต้องพูดถึง",
  str_voice_1601121_19 = "ฉันชอบกลางคืนมากเลย มันสงบ... แต่ก็น่าเบื่อนิดหน่อยอ่ะนะ",
  str_voice_1601121_20 = "อัมบราตันมีแต่เสียงดังอึกทึก การต่อสู้ไม่หยุดหย่อน แต่ที่นี่ก็เต็มไปด้วยความอิสระราวกับถนนที่ปูไปด้วยโอกาส",
  str_voice_1601121_21 = "ลูโมโพลิสคือสถานที่ที่ชนชั้นสูงหัวเก่าจะได้พบกับความสุข",
  str_voice_1601121_22 = "มีชีวิตอยู่กับปัจจุบัน",
  str_voice_1601121_23 = "น่าสมเพชมาก นับว่าเป็นการอุ่นเครื่องที่ไม่พอ",
  str_voice_1601121_24 = "ถ้าฉันไม่ได้มาที่อัมบราตัน ฉันคงไม่ได้พบกับเทสซา เธอเจ๋งมากเลย ไม่มีอะไรกวนใจเธอได้",
  str_voice_1601121_25 = "ไม่ว่าจะไปไหนก็มีแต่ความขัดแย้ง ดังนั้นจึงต้องมีใครสักคนคอยรักษาความสงบ ในอัมบราตัน คนที่ว่านั้นก็คือ อีสต์วาน",
  str_voice_1601121_26 = "การเดินบนเส้นแบ่งระหว่างความเป็นและความตายนั้นน่าตื่นเต้นกว่าสิ่งอื่นใดในโลก นั่นเป็นเหตุผลที่ฉันชอบการต่อสู้",
  str_voice_1601121_27 = "ยอมตายดีกว่าใช้ชีวิตตามกฎเกณฑ์!",
  str_voice_1601121_28 = "ฉันไม่เคยเห็นอะไรใหญ่โตขนาดนี้มาก่อนเลย... อยากรู้จังว่ามันบินได้ยังไง...",
  str_voice_1601121_29 = "ฉันชื่อสโมกกี้ เธอคือเจ้าของโคลอสซัสนี้เหรอ มีอะไรสนุก ๆ ให้ทำไหม ที่สำคัญ ฉันสามารถจุดไฟได้ไหม",
  str_voice_1601121_30 = "เปลงไฟกำลังลุกโชน",
  str_voice_1601121_31 = "มาหาอะไรใหญ่ ๆ เผาเล่นดีกว่า!",
  str_voice_1601121_32 = "นี่คือพลังที่แท้จริงของฉันล่ะ!",
  str_voice_1601121_33 = "ตามฉันมา แมนติคอร์!",
  str_voice_1601121_34 = "เผาให้ราบคาบ!",
  str_voice_1601121_35 = "ระวังนะ!",
  str_voice_1601121_36 = "ไปเผากันดีกว่า!",
  str_voice_1601121_37 = "เผาเป็นจุณไปซะ!",
  str_voice_1601121_38 = "เปลวไฟ! ทางออกของทุกปัญหาชีวิต!",
  str_voice_1601121_39 = "นี่จะไปไหนเนี่ย",
  str_voice_1601121_40 = "ราตรีสวัสดิ์นะ!",
  str_voice_1601121_41 = "เอาละ ฉันทำได้!",
  str_voice_1601121_42 = "ง่ายเกิ๊น!",
  str_voice_1601121_43 = "โธ่... พลาดจนได้",
  str_voice_1601121_44 = "นี่คิดว่าฉันจะเผาทุกอย่างที่เห็นเหรอ ก็ไม่แน่นักหรอก แต่คงไม่ใช่ที่นี่",
  str_voice_1601121_45 = "ฉันจะรับไว้นะ!",
  str_voice_1601121_46 = "ไม่เลวนี่...",
  str_voice_1601121_47 = "เธอใจดีจัง!",
  str_voice_1601121_48 = "มาเถอะ! เธอกำลังตามหาบางอย่างอยู่ ใช่ไหมล่ะ?",
  str_voice_1601121_49 = "ถ้าฉันไม่กรนเยอะ ฉันคงไม่ได้เจออีสต์วาน...",
  str_voice_1601121_50 = "เห็นเข็มกลัดนี้ไหม ตำนานเล่าว่าทำจากกระโหลกแมนติคอร์ ครอบครัวของฉันส่งต่อให้ฉันน่ะ...",
  str_voice_1601121_51 = "เปลวไฟที่ลุกโชนภายในตัวฉันค่อย ๆ ทำให้ฉันไม่รับรู้ความเจ็บปวด... นั่นคือเหตุผลที่ฉันต้องการตัวกระตุ้นจำนวนมาก!",
  str_voice_1601121_52 = "Alchemy Stars",
  str_voice_1601121_53 = "สวัสดี?",
  str_voice_1601121_54 = "อรุณสวัสดิ์!",
  str_voice_1601121_55 = "เที่ยงแล้วเหรอ",
  str_voice_1601121_56 = "ราตรีสวัสดิ์นะ!",
  str_voice_1601121_57 = "ก็แค่วันธรรมดาอีกวัน ฉันหมายถึง มีอะไรให้ดีใจนักเหรอ",
  str_voice_1601121_58 = "โย่ ผู้นำทาง! อยากเล่นกับไฟไหม สัญญาว่าจะไม่เผาเธอหรอก",
  str_voice_1601121_59 = "ทำไมเธอให้ของมาเยอะแยะเลย ฉันไม่เข้าใจ...",
  str_voice_1401271_1 = "โทษที ขอโทษ ขอเวลาแป๊บนะ...",
  str_voice_1401271_2 = "ฉันไม่ได้ร้องไห้ ฉันแค่ฝันถึงพ่อแม่เมื่อคืน",
  str_voice_1401271_3 = "คนในทะเลทรายเรดีเซลเก็บเศษขยะเพื่อยังชีพ ถ้าไม่อยากเป็นคนดีก็ให้ไปเก็บขยะ ฉันก็คือหนึ่งในพวกนั้นนั่นแหละ",
  str_voice_1401271_4 = "ฉันควรแสดงความกล้าออกมาอีกไหม หลายคนบอกว่าฉันปอดแหก",
  str_voice_1401271_5 = "พ่อฉันบอกว่าบันทึกนี้มาจากลูโมโพลิส มันคือลูมินา อาจเป็นเหตุผลที่ว่าทำไมฉันถึงควบคุมมันได้",
  str_voice_1401271_6 = "ฟื้นคืนชีพ นั่นคือชื่อของจดหมายสีแดง มันยังเป็นคำขอของฉันอีกด้วย...เพื่อคืนชีพพ่อแม่ของฉัน",
  str_voice_1401271_7 = "ที่นี่รู้สึกดีจัง เหมือนอยู่บ้านเลย",
  str_voice_1401271_8 = "พ่อแม่ของฉัน พวกเขาชื่อว่า... เนสลูดอฟ และมาเซโลน่า",
  str_voice_1401271_9 = "พ่อแม่ของฉันยังไม่ตาย วิญญาณของพวกเขายังอยู่กับฉัน... ในจดหมายสีแดงนั่น",
  str_voice_1401271_10 = "โทษที ฉันไม่ได้อู้นะ แค่เบื่อ... ฉันเล่นกับกระดาษไงล่ะ",
  str_voice_1401271_11 = "ฉันอยู่ที่นี่ได้ไหม เกะกะรึเปล่า ไม่เหรอ เยี่ยมเลย...",
  str_voice_1401271_12 = "ในโคลอสซัสมีผีสิงรึเปล่าเนี่ย",
  str_voice_1401271_13 = "ที่นี่มีหนังสือที่จบแบบแฮปปี้เอนดิ้งบ้างไหม",
  str_voice_1401271_14 = "ฉันทำความสะอาดโคลอสซัสด้วยกระดาษ ฉันไม่ได้ทำตัวป่วนใช่ไหม",
  str_voice_1401271_15 = "วันเกิดเหรอ ฉันทำเค้กกระดาษให้กินเอาไหม",
  str_voice_1401271_16 = "วันนี้งานเยอะไหม ถ้าเยอะก็บอกนะ ฉันจะช่วยเอง",
  str_voice_1401271_17 = "อรุณสวัสดิ์ ผู้นำทาง มีอะไรต้องทำไหม",
  str_voice_1401271_18 = "ฉันมาดูท้องฟ้ากลางคืนที่นี่ได้ไหม",
  str_voice_1401271_19 = "โอ้ ผู้นำทาง เธอต้องพักบ้างนะ",
  str_voice_1401271_20 = "ได้ข่าวว่าเลดี้วิกตอเรียทำให้คำขอของทุกคนเป็นจริง นั่นคือเหตุผลที่ฉันเข้าร่วมทรู ออเดอร์",
  str_voice_1401271_21 = "ทะเลทรายที่ัฉันใช้ชีวิตอยู่คือเขตเรดีเซล เวรนช์ แต่ฉันก็ไม่ค่อยได้เห็นมันหรอก",
  str_voice_1401271_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1401271_23 = "ฉันน่าจะเอาเลือดอิคลิพไซท์มาทากระดาษให้เป็นสีแดง",
  str_voice_1401271_24 = "ต้องขอบคุณเจเนวีฟที่ให้ฉันเข้าร่วมทรู ออเดอร์ ฉันชื่นชมหล่อนมาก",
  str_voice_1401271_25 = "คนที่ยิ้มแย้มอยู่เสมอแสดงว่าได้เรียนรู้มาอย่างดี โดยเฉพาะอย่างยิ่งเรื่องของวิญญาณ",
  str_voice_1401271_26 = "โอ้ นานแค่ไหนแล้วที่ไม่ได้เห็นการรวมตัวครั้งยิ่งใหญ่... นานมากแล้วสินะ",
  str_voice_1401271_27 = "นักวิทยาศาสตร์และสิ่งที่พวกเขาเรียกว่าเหตุผลใช่ว่าจะถูกต้องเสมอไป",
  str_voice_1401271_28 = "ใหญ่เบ้อเร่อเลย ไม่มีผีแน่ใช่ไหม",
  str_voice_1401271_29 = "ฉันชื่อพาโซโล่ กระดาษพวกนี้ตามฉันมาที่นี่ คงไม่มีใครรำคาญหรอกเนอะ...",
  str_voice_1401271_30 = "เฮ้ กระดาษเบาขึ้นแล้ว",
  str_voice_1401271_31 = "วังน้ำวนแผ่นกระดาษ...",
  str_voice_1401271_32 = "กระดาษเป็นปึกที่แข็งแกร่งกว่าเกราะไหน ๆ",
  str_voice_1401271_33 = "ฉันใกล้จะคืนชีพพวกเขาได้แล้ว",
  str_voice_1401271_34 = "ให้ฉันเข้าร่วมด้วยสิ...",
  str_voice_1401271_35 = "กระดาษปราบศัตรู",
  str_voice_1401271_36 = "ปล่อยให้เป็นหน้าที่ฉัน!",
  str_voice_1401271_37 = "พลังแห่งกระดาษ!",
  str_voice_1401271_38 = "รู้สึกได้ มันมาแล้ว!",
  str_voice_1401271_39 = "แหลกซะ!",
  str_voice_1401271_40 = "ฉีกกระชากเป็นชิ้น ๆ!",
  str_voice_1401271_41 = "ให้ฉันจัดการเหรอ",
  str_voice_1401271_42 = "ฟู่ เราชนะแล้ว",
  str_voice_1401271_43 = "ทุกคนถอยก่อน ดีกว่ามั้ง",
  str_voice_1401271_44 = "พวกมันจะไม่ทำให้ที่นี่แปดเปื้อน...",
  str_voice_1401271_45 = "ขอบคุณนะ...!",
  str_voice_1401271_46 = "ฉันรับสิ่งนี้ไว้ได้จริง ๆ น่ะเหรอ...",
  str_voice_1401271_47 = "ฉันไม่รู้จะขอบคุณยังไงดี...",
  str_voice_1401271_48 = "ไม่มีใครทำกับฉันแบบนี้มานานแล้ว...",
  str_voice_1401271_49 = "เห็นผิวของฉันไหม การใช้ชีวิตวัยเด็กของฉันในทะเลทรายเรดีเซลทำให้ผิวฉันคล้ำ",
  str_voice_1401271_50 = "ฉันคงไม่ไปจากทะเลทรายเรดีเซลถ้าไม่ใช่เพราะอิคลิพไซท์ และถ้าพ่อแม่ของฉัน... ไม่ต้องตาย",
  str_voice_1401271_51 = "จดหมายสีแดงมีวิญญาณของพ่อแม่ของฉัน บางทีฉันก็ได้ยินพวกเขาเรียกชื่อของฉัน",
  str_voice_1401271_52 = "Alchemy Stars",
  str_voice_1401271_53 = "เฮ้...",
  str_voice_1401271_54 = "อรุณสวัสดิ์...",
  str_voice_1401271_55 = "สวัสดียามบ่าย",
  str_voice_1401271_56 = "ไปพักหน่อยไหม",
  str_voice_1401271_57 = "สุขสันต์วันปีใหม่",
  str_voice_1601221_1 = "นักล่าที่ดีต้องแม่นยำในทุกเรื่องตั้งแต่ภารกิจ ไปจนถึงงานอดิเรก",
  str_voice_1601221_2 = "แว่นของฉันช่วยให้ฉันมองเห็นชัดขึ้น และความรู้ความเข้าใจที่ชัดเจนขึ้นนำไปสู่ผลลัพธ์ที่ดีขึ้น",
  str_voice_1601221_3 = "คุณอยากรู้เกี่ยวกับฉันมั้ย ต้องการทราบข้อมูลเพิ่มเติมเหรอ ความลับของการเป็นนักแม่นปืนของฉัน จ่ายเงินแล้วฉันจะบอกคุณทุกอย่างที่คุณอยากรู้",
  str_voice_1601221_4 = "มีข่าวอะไรมั้ย ฉันยินดีรับฟัง หากเป็นเรื่องของเก่า จะดีมาก",
  str_voice_1601221_5 = "สมบัติที่ล้ำค่ามากที่สุดส่วนมากอยู่ในหัวใจ",
  str_voice_1601221_6 = "รอยแตกของเส้นผม เคลือบฟันที่เสียหาย ฐานที่ไม่สมบูรณ์... ไม่มีสิ่งใดสามารถซ่อนคุณค่าที่แท้จริงของสมบัติที่หายากได้ ไม่ว่าจะเกิดอะไรขึ้น พวกมันจะเป็นสิ่งมหัศจรรย์ที่ประเมินค่าไม่ได้เสมอ",
  str_voice_1601221_7 = "ฉันรู้ทุกอย่าง ฉันเห็นทุกสิ่งที่คุณทำและทุกสิ่งที่คุณทำได้ นั่นเป็นเหตุผลที่ฉันเลือกที่จะยืนที่นี่ ท่ามกลางขุนนางและหายากเช่นคุณ",
  str_voice_1601221_8 = "ฉันต้องการแบ่งเงินรางวัลของวันนี้กับคุณ... ไม่พอเหรอ โทษี ฉันมีเท่านี้แหละ",
  str_voice_1601221_9 = "ฉันคิดจะเปิดร้านขายของเก่า ฉันคิดว่าจะให้ส่วนลดกับคุณ",
  str_voice_1601221_10 = "ผ่านไปแล้ว 5 ชั่วโมง 25 นาที 45 วินาที นับตั้งแต่ฉันได้รับภารกิจสุดท้าย อา... เวลาว่าง สำหรับฉันมันเหมือนกับความฝัน",
  str_voice_1601221_11 = "เธอประกาศภารกิจนี้เหรอ แม้ว่าจะเป็นเธอก็ตาม เธอก็ต้องจ่ายเงินฉันอยู่ดี แต่ฉันจะให้จ่าย 97.6% ส่วนลดเท่านี้เป็นไงบ้าง",
  str_voice_1601221_12 = "ให้นึกถึงฉัน หากต้องการทำงานให้สำเร็จ",
  str_voice_1601221_13 = "โทษทีที่จ้อง... ช่วยไม่ได้น่ะ ฉันคือสไนเปอร์",
  str_voice_1601221_14 = "เธอเอาเทียนไปห่างๆ ได้มั้ย ฉันไม่ชอบไฟ",
  str_voice_1601221_15 = "สุขสันต์วันเกิด นี่ของขวัญจากของสะสมของฉัน",
  str_voice_1601221_16 = "เตรียมตัวให้ดี นี่ืคือเวลาที่ดีที่สุดในการทำภารกิจ",
  str_voice_1601221_17 = "ฉันคงออกไปทักทายลูกค้าของฉันตอนนี้... หากฉันมีร้านค้า...",
  str_voice_1601221_18 = "ฉันได้ยินว่าร้านค้าของอัมบราตันมอบส่วนลดให้อยู่ในตอนนี้",
  str_voice_1601221_19 = "การฟังเสียงติ๊กต๊อกของนาฬิกาพกในคืนที่เงียบสงัดทำให้ฉันหลับสบาย",
  str_voice_1601221_20 = "คุณจะได้รับข้อมูลที่ดีเสมอในอัมบราตัน ภารกิจลับบางอันให้เงินดี",
  str_voice_1601221_21 = "สหพันธรัฐอิลลูมินารู้สึกเหมือนสถานที่ที่สร้างบนแรงศรัทธา...",
  str_voice_1601221_22 = "เฮร่าไม่เคยปิดตาของเธอ",
  str_voice_1601221_23 = "อย่างที่ฉันคิดไว้... ไร้ค่า",
  str_voice_1601221_24 = "ฉันได้ยินมาว่าเชโอลเริ่มต้นจากศูนย์เหมือนกัน บางทีเราควรคุยกัน...",
  str_voice_1601221_25 = "เอโฮะน่ารัก... หากเธอไม่พยายามจะขายอะไรบางอย่างให้ฉัน",
  str_voice_1601221_26 = "เวทมนตร์ของนาฬิกาโบราณที่เงียบสงัด เดินต่อไปทั้งๆ ที่ไม่มีใครได้ยิน...",
  str_voice_1601221_27 = "สีชมพูเหรอ เธอโชคดีที่ฉันถูกสอนมาให้สุภาพ... อย่าให้ฉันเห็นสีนี้อีกนะ",
  str_voice_1601221_28 = "เราย่อตัวลงได้มั้ย มันไม่เข้ากับร้านของฉันถ้าเป็นแบบนี้",
  str_voice_1601221_29 = "ฉันจะช่วยได้อย่างไรบ้าง หากมันเป็นภารกิจเสี่ยงมากได้มาก อัลลัวราพร้อมทำงาน",
  str_voice_1601221_30 = "ขอบคุณ ฉันจะเพิ่มมันเข้าคอลเลกชันของฉัน",
  str_voice_1601221_31 = "ใกล้เข้าไปอีกก้าว",
  str_voice_1601221_32 = "ความสำเร็จขึ้นอยู่กับการคำนวณอย่างระมัดระวัง",
  str_voice_1601221_33 = "ฉันใกล้ทำเป้าหมายสำเร็จแล้ว",
  str_voice_1601221_34 = "โอ้ เธอเลือกฉัน",
  str_voice_1601221_35 = "พร้อมที่จะชม",
  str_voice_1601221_36 = "ชีวิตคือสิ่งมีค่า",
  str_voice_1601221_37 = "ผู้รู้ตัวจริง!",
  str_voice_1601221_38 = "แกไม่มีค่าอะไรเลย!",
  str_voice_1601221_39 = "เอาล่ะ ไหนดูซิ...",
  str_voice_1601221_40 = "คุณกลับไปได้เลย!",
  str_voice_1601221_41 = "หวังว่าจะไม่เสียเวลาฉันนะ",
  str_voice_1601221_42 = "เราทำเงินได้เท่าไร",
  str_voice_1601221_43 = "ทั้งหมดนี้คุ้มเหรอ...",
  str_voice_1601221_44 = "เลิกจ้องฉันได้แล้ว ฉันต้องเลือก ระบุ ประเมินค่า... ฉันยุ่งอยู่ แต่ไม่ได้หมายความว่าฉันไม่สามารถจ้องสมบัติแบบเธอได้",
  str_voice_1601221_45 = "ขอบคุณนะ จะขายเท่าไร",
  str_voice_1601221_46 = "ฉันจะดูแลมันเป็นอย่างดี",
  str_voice_1601221_47 = "ช่างเป็นความรู้สึกที่คุ้นเคย... ขอบคุณมากนะ",
  str_voice_1601221_48 = "ขอบคุณนะ ฉันคิดว่านี่คือของที่ดีที่สุดที่ฉันเคยได้รับมา",
  str_voice_1601221_49 = "ทำไมถึงหลงใหลในของเก่าเหรอ พ่อแม่ของฉันเป็นนักสะสมก่อนที่พวกเขาจะเสียชีวิต ดังนั้นจึงเป็นทั้งของขวัญและสิทธิกำเนิดของฉัน ไม่จำเป็นต้องปลอบใจฉัน ฉันไม่เสียใจกับพวกเขาแล้ว",
  str_voice_1601221_50 = "แน่นอน ตอนเด็กๆ ฉันเต็มไปด้วยความไม่พอใจในทุกสิ่ง แต่ความจริงก็คือ... ผู้คนจะได้เรียนรู้ว่าความรักคืออะไรเมื่อชีวิตดำเนินต่อไป อะไรเหรอ แปลกใจที่ได้ยินฉันพูดแบบนี้เหรอ",
  str_voice_1601221_51 = "สานต่อความรักของพวกเขา ฟื้นความปรารถนาที่จะมีชีวิตอยู่ และตอบแทนผู้ที่ช่วยเหลือ... เป็นสิ่งสำคัญที่สุดสำหรับฉัน เอ่อ การหาเงินด้วย",
  str_voice_1601221_52 = "Alchemy Stars",
  str_voice_1601221_53 = "เธออยากซื้ออะไรมั้ย",
  str_voice_1601221_54 = "อรุณสวัสดิ์ ผู้นำทาง",
  str_voice_1601221_55 = "เธอจะต้องอยากกินมื้อเช้าแบบราชาเพื่อช่วยเหลืองานของวันนี้",
  str_voice_1601221_56 = "ช่วงเย็นเป็นเวลาดีที่จะไปช้อปปิ้ง",
  str_voice_1601221_57 = "สุขสันต์วันปีใหม่ ฉันหวังว่าวันหนึ่งเราจะตระหนักถึงความฝันของพวกเรา",
  str_voice_1601221_58 = "การเล็งเป้าของฉันแม่นขึ้นมากกว่าเก่า",
  str_voice_1601221_59 = "ปณิธานที่ยิ่งใหญ่ที่สุดของนายคืออะไรเหรอ ผู้นำทาง",
  str_voice_1601221_60 = "ผู้นำทาง คุณอยู่รึเปล่า",
  str_voice_1601171_1 = "อย่าปล่อยให้ความล้มเหลวในวันนี้ทำให้คุณผิดหวัง คุณจะผ่านมันไปได้ในที่สุด ชีวิตไม่เคยง่ายเลยเมื่อคุณยังเด็ก แต่คุณจะเห็นว่าไม่มีอะไรง่ายเลยเมื่อคุณมองย้อนกลับไปในทศวรรษต่อมา",
  str_voice_1601171_2 = "ปวดกล้ามเนื้อใช่มั้ย คุณออกกำลังกายมากเกินไปหรือไม่ เย็นนี้ฉันจะหาอะไรดี ๆ ให้คุณกิน ซึ่งน่าจะช่วยคุณได้",
  str_voice_1601171_3 = "อา... ความโง่เขลาของวัยเยาว์ ขี้โวยวาย เอาแต่ใจ คิดว่าเธอคือผู้กอบกู้โลก... แต่สุดท้าย ฉันคิดว่าไม่มีอันตรายอะไรหรอก",
  str_voice_1601171_4 = "เธอคิดว่าฉันพัฒนาขึ้นเหรอ ใช่เลย ฉันฝึกฝนอย่างลับ ๆ มาตลอด ดูเหมือนมันจะได้ผล",
  str_voice_1601171_5 = "อย่าสงสัยในคำพูดของคนชรา ฉันเคยเห็นมากกว่าที่เธอจะจินตนาการได้ ครั้งสุดท้ายที่มีคนมองมาที่ฉันด้วยดวงตาคู่นั้น... มันคือก่อนที่เขาจะสู้ในศึกครั้งสุดท้าย",
  str_voice_1601171_6 = "ไม่มีใครทำอันตรายสหายของฉันได้ ฉันจะไม่ยอมให้พวกเขาลืม... ฉันจะฝังมันลงไปในกะโหลกของมัน",
  str_voice_1601171_7 = "วางแผนกลยุทธ์โดยละเอียด ต่อสู้อย่างกล้าหาญในการต่อสู้ ในฐานะผู้บัญชาการ เธอควรเข้าใจเรื่องนี้เป็นอย่างดี นั่นคือทั้งหมดที่ฉันต้องพูด",
  str_voice_1601171_8 = "หากเธอประหม่าเกินไปในการต่อสู้ ก็แค่คุยกับเพื่อนฝูงและเล่นมุกตลกสักสองสามเรื่อง มันจะช่วยให้เธอผ่อนคลายและทำให้เธอต่อสู้อย่างเต็มศักยภาพ",
  str_voice_1601171_9 = "เธอสั่งกองกำลังของเธอได้ดีมากในการรบครั้งล่าสุด มันทำให้ฉันนึกถึงตัวเองเมื่อตอนยังอยู่ในสโตนฟอร์ซ มีคนแบบเธอในตอนนั้นด้วย",
  str_voice_1601171_10 = "มันไม่ดีต่อสุขภาพที่จะแค่นั่งเล่นที่ฐานตลอดเวลา แต่จะทำอะไรได้บ้าง ลับมีด ทำความสะอาดปืน หรือทำสควอช",
  str_voice_1601171_11 = "เธอย้ายฉันมาที่นี่เหรอ สิ่งเดียวกันนี้เกิดขึ้นเมื่อฉันเกษียณ โชคดีที่ฉันชินกับมันแล้ว",
  str_voice_1601171_12 = "ฉันอาจจะเกษียณแล้ว แต่ฉันก็ยังฝึกฝนอยู่บ้าง คนชั่วก็ไม่หยุดพักถูกมั้ย",
  str_voice_1601171_13 = "การพักผ่อนที่ดีต้องการอาหารที่ดี และเราได้อาหารที่ดีที่สุดในการขนส่ง",
  str_voice_1601171_14 = "เหนื่อยเหรอ ไปพักสิ ร่างกายของเธอบอกว่าถึงเวลาพักแล้ว",
  str_voice_1601171_15 = "สุขสันต์วันเกิด นี่คือเค้กของเธอ ไม่ต้องห่วง ฉันเคยเป็นกุ๊กมาก่อน",
  str_voice_1601171_16 = "แม้ว่าเธอจะสั่งการโคลอสซัส แต่เธอดูเหมือนคนส่งของ...",
  str_voice_1601171_17 = "ยามเช้าจะเป็นตัวกำหนดอารมณ์ของวันนั้น เริ่มต้นวันใหม่ให้ดีด้วยกิจวัตรที่เหมาะสม",
  str_voice_1601171_18 = "กินและพักเมื่อเริ่มดึกแล้ว และเธอจะมีวันพรุ่งนี้ที่ดีกว่า",
  str_voice_1601171_19 = "ไม่หลับเหรอ ออกกำลังกายและอาบน้ำ ตื่นทั้งคืนไม่ใช่สิ่งที่ควรทำ",
  str_voice_1601171_20 = "อิลลูมินารุ่งเรืองเพราะสมาชิกทุกคนทำตามหน้าที่",
  str_voice_1601171_21 = "หืม ลูโมโพลิส ทหารของพวกเขาเหมือนแกะ ไม่เหมือนอิคลิพไซท์...",
  str_voice_1601171_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1601171_23 = "ฉันแค่ต้องการเห็นร่างของพวกมันกองเป็นภูเขาข้างหน้าฉัน",
  str_voice_1601171_24 = "เชื่อมั่นในจอมทัพ เธอนำเราสู่ชัยชนะเสมอ",
  str_voice_1601171_25 = "รีวาย... บางครั้งฉันก็บอกไม่ได้ว่ามันเป็นเขาหรือเธอ",
  str_voice_1601171_26 = "การขนส่งคือส่วนสำคัญ ไม่มีอะไรช่วยเพิ่มกำลังใจได้เหมือนกับอาหารร้อนๆ",
  str_voice_1601171_27 = "ความเฉยเมยสามารถเอาชนะทหารที่แข็งแกร่งที่สุดได้ ออกไปทำงาน",
  str_voice_1601171_28 = "เจ้านี่ใหญ่มาก ฉันดีใจที่ฉันไม่ได้ดูแลมัน",
  str_voice_1601171_29 = "ใจเย็น ฉันวางมือแล้ว เรียกฉันว่าแกรม ถามฉันได้ทุกเรื่องเกี่ยวกับการต่อสู้และการขนส่ง",
  str_voice_1601171_30 = "ฉันรู้ว่าเป็นเด็กอีกครั้ง",
  str_voice_1601171_31 = "ตอนนี้ฉันจะแสดงฝีมือของจริงให้เห็น",
  str_voice_1601171_32 = "ฉันจะสู้จนหยดสุดท้าย",
  str_voice_1601171_33 = "เทพธิดาแห่งชัยชนะยิ้มให้กับฉัน",
  str_voice_1601171_34 = "ไปทำงานกันได้แล้ว",
  str_voice_1601171_35 = "การเตรียมการเข้าสู่กระบวนการแล้ว",
  str_voice_1601171_36 = "รอจนถึงช่วงเวลาสุดท้าย",
  str_voice_1601171_37 = "เวลาของเธอมาถึงแล้ว... ลงมือ",
  str_voice_1601171_38 = "ไฟ! เผามันให้สิ้น",
  str_voice_1601171_39 = "นี่เป็นเพียงแค่การเริ่มต้น...",
  str_voice_1601171_40 = "และนี่คือจุดจบ",
  str_voice_1601171_41 = "ตามฉันมาทุกคน",
  str_voice_1601171_42 = "ทุกวันนี้อิคลิพไซท์อ่อนแอมาก",
  str_voice_1601171_43 = "ฉันจะพาขึ้นไปด้านหลัง ไปได้",
  str_voice_1601171_44 = "ฉันต่อสู้มานานกว่าที่เธอมีชีวิตอยู่ ไม่ ไม่ต้องห่วงฉันหรอก",
  str_voice_1601171_45 = "อืม ให้ฉันทำไม",
  str_voice_1601171_46 = "ขอบคุณ เธอสังเกตฉันได้ดีมาก",
  str_voice_1601171_47 = "นี่คือ... อืม ฉันจะรับมันไว้",
  str_voice_1601171_48 = "ขอบคุณ ฉันสัญญาจะคอยช่วยเหลือเธอเสมอ",
  str_voice_1601171_49 = "บางครั้งการเป็นเจ้าหน้าที่ขนส่งธรรมดาๆ ก็ไม่เลว อย่างไรก็ตาม นี่คือการเริ่มต้นของฉันในกองทัพ และแน่นอนว่ามีวินัยน้อยกว่ามาก",
  str_voice_1601171_50 = "สโตนฟอร์ซ... พ่ายแพ้ในการต่อสู้อย่างดุเดือดเมื่อทศวรรษที่แล้ว เมื่อฉันคิดถึงสหายร่วมรบที่ตายไป ฉันหวังว่าฉันจะตายแทนพวกเขา",
  str_voice_1601171_51 = "การเห็นเพื่อนของฉันตายไปทีละคน ครั้งหนึ่งฉันคิดว่าความตายคือคำตอบสำหรับฉันเหมือนกัน แต่โชคดีคำพูดของเบรนท์ทำให้ฉันมีความหวัง ตอนนี้ฉันมีชีวิตเพื่อฮีโร่ที่จากไป",
  str_voice_1601171_52 = "Alchemy Stars!",
  str_voice_1601171_53 = "พี่น้องร่วมรบเคียงบ่าเคียงไหล่",
  str_voice_1601171_54 = "อรุณสวัสดิ์ หลับสบายมั้ย",
  str_voice_1601171_55 = "ตอนบ่ายคือช่วงเวลาที่ดีที่สุดในการกินอาหาร",
  str_voice_1601171_56 = "นอนหลับอย่างเต็มอิ่มเพื่อเริ่มต้นวันใหม่ที่ดีในเช้าวันรุ่งขึ้น",
  str_voice_1601171_57 = "สุขสันต์วันปีใหม่ ฉันหวังว่าเราจะได้ร่วมกันต่อสู้ในปีถัดไปเหมือนกัน",
  str_voice_1601171_58 = "เพราะฉันจะขึ้นโคลอสซัสไปกับเธอนับจากนี้ ฉันว่าการแนะนำตัวก็เป็นคำสั่ง",
  str_voice_1601171_59 = "ขอบคุณสำหรับของขวัญนะ",
  str_voice_1601171_60 = "เดี๋ยวนี้ฝึกเป็นยังไงบ้าง",
  str_voice_1601171_61 = "สงครามมันโหดร้าย...",
  str_voice_1601171_62 = "ขอถามอะไรหน่อยสิ",
  str_voice_1601191_1 = "ฉันชอบเครื่องจักร ฉันเรียนได้ทั้งวันแต่ยังไม่เก่งนัก รู้จักกลศาสตร์ที่ดีมั้ย ฉันต้องการความช่วยเหลือ...",
  str_voice_1601191_2 = "คุณเก่ง และสั่งการโคลอสซัส คุณสามารถเป็นผู้นำทางที่ดีได้ เรียกฉันว่าเรวี่ หรือจะเรียกรีวี่ รีไว จะเรียกอะไรก็เรียก",
  str_voice_1601191_3 = "เกียร์มีเสียง \"คลิก คลิก\"... โอ้ อัลเทอร์เบลดของฉัน กำลังสงสัยเลยว่าหายไปไหน ฉัน...",
  str_voice_1601191_4 = "อิคลิพไซท์... ฟันหนึ่งครั้งเป็นสองท่อน ฟันสองครั้งเป็นสี่ท่อน และสามครั้งเป็นแปดท่อน...",
  str_voice_1601191_5 = "ดาบของฉันเหรอ เหมือนกับถอนขนนกพิราบ นั่นคือความเบาของมัน ไม่ใช่ว่าฉันเคยถอนขนนกอะไรแบบนั้นมาก่อนหรอกนะ...",
  str_voice_1601191_6 = "อ้า กลิ่นหอมของดอกไม้! อะไรนะ ฉันพูดผิดเหรอ หากเธอเข้าใจดีพอ",
  str_voice_1601191_7 = "เธอดูอายุมากกว่าฉัน หมายความว่าเธอแก่แล้ว ฉันไม่แก่ มั่นคงมั้ย น่าเชื่อถือมั้ย มีประสบการณ์และไว้ใจได้มั้ย",
  str_voice_1601191_8 = "ด้วยผู้นำทาง แม้ว่าจะเข้าใจผิด โซ่ของอัลเทอร์เบลดยังคงอยู่ แปลกมาก",
  str_voice_1601191_9 = "แม้ว่าจะอายุน้อยกว่าเธอ แต่ฉันแข็งแกร่ง โดยเฉพาะด้วยแขนจักรกลนี้ เมื่อการต่อสู้เริ่มขึ้น เธอต้องหลบข้างหลังฉัน",
  str_voice_1601191_10 = "คิดว่าจะสร้างจดแต้มสังหารอิคลิพไซท์ บนอัลเทอร์เบลด แต่มันเยอะเกินไป... นับไม่ไหว เขียนไม่ไหว...",
  str_voice_1601191_11 = "ฉันทำอะไรได้บ้างที่นี่ ก็มี... เช่นวิธีฟันอิคลิพไซท์ได้ดีขึ้น",
  str_voice_1601191_12 = "เมื่อไหร่ฝนจะตก? บอกหน่อยได้มั้ย? ฉันจะได้อาบน้ำฟรี!",
  str_voice_1601191_13 = "เคยฟันอิคลิพไซท์มั้ย แน่นอนว่าไม่... เพราะเธอคือผู้บัญชาการ ครั้งต่อไปฉันจะบอกให้ว่ารู้สึกยังไง",
  str_voice_1601191_14 = "คนแก่สู้เก่งจริงๆ ได้ยินว่าเขาสังหารอิคลิพไซท์ไปมากมาย หากไม่เป็นแบบนั้นฉันก็ไม่มีเหตุผลให้คุยกับเขา",
  str_voice_1601191_15 = "วันเกิดเหรอ...ฉันจะให้ข้าวปั้นรสเผ็ดกับเธอ...",
  str_voice_1601191_16 = "การได้เห็นเธอผู้นำทาง ทำให้ลาดตระเวนตื่นเต้นขึ้นมากสำหรับฉัน",
  str_voice_1601191_17 = "อรุณ เตรียมตัวสำหรับท่าใหม่วันนี้",
  str_voice_1601191_18 = "เธอไม่ควรวิ่งไปมาตอนกลางคืน หากบอสเห็นเธอ เขาจะจับเธอและดุเธอ... ไม่ดีสินะ เธอคือบอสตัวใหญ่สุดเหรอ งั้นไม่ต้องห่วง",
  str_voice_1601191_19 = "อะไรนะ เธอไม่จำเป็นต้องนอนเหรอ เธอจะลาดตระเวนกับฉันมั้ย ฉัน...คิดว่ามันไม่จำเป็น...",
  str_voice_1601191_20 = "ข้อดีเกี่ยวกับอิลลูมินา คือหากใครบางคนตาย คนจำนวนมากจะดูแลลูกหลานของพวกเขา นั่นคือวิถีทางที่ฉันเติบโตมา",
  str_voice_1601191_21 = "ได้ยินว่าคนในอัมบราตันต้องการเงินเพื่อทำอะไรก็ได้ แล้วพวกเขาต้องการเงินเพื่อไม่ทำอะไรมั้ย ไมรู้เหมือนกัน",
  str_voice_1601191_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1601191_23 = "อ้า ไม่พอให้ฉันฟันเลย",
  str_voice_1601191_24 = "วีด้าคล้ายกับฉัน กินซุปอย่างมีความสุข ส่วนฉันมีอิคลิพไซท์ให้ฟัน",
  str_voice_1601191_25 = "คนแก่เสียงดังมาก และมักพูดนั่นนี่เหมือนทหารผ่านศึก ที่จริงแล้วเขาวางมือแล้ว",
  str_voice_1601191_26 = "วันฝนตกและข้าวปั้นรสเผ็ด... ฉันรู้สึกไม่ดี มีกระดาษทิชชู่มั้ย เผ็ด เผ็ด เผ็ด",
  str_voice_1601191_27 = "เห็นหน้าและแขนของฉันมั้ย มันคืออิคลิพไซท์ เมื่อเห็นอิคลิพไซท์ ฉันต้องฟันมัน... เป็นสองท่อน...",
  str_voice_1601191_28 = "เจ้านี่ใหญ่มาก อิลลูมินามีแบบนี้มั้ยฉันก็ไม่รู้ ฉันเพิ่งเคยเห็นเจ้านี่",
  str_voice_1601191_29 = "ฉันคือเรวี่ ฉันแข็งแกร่ง คนอื่นไม่ ดูดาบยักษ์นี่ คนอื่นบอกว่ามันหนัก แต่ฉันเหวี่ยงมันไปมาเหมือนมีดตัดเนย เห็นมั้ย...",
  str_voice_1601191_30 = "เอาอีก",
  str_voice_1601191_31 = "พร้อมที่จะออกศึกเหมือนฟ้าร้องแล้ว",
  str_voice_1601191_32 = "พายุเริ่มรุนแรงขึ้น",
  str_voice_1601191_33 = "หมุน จงกลัวฉัน",
  str_voice_1601191_34 = "ให้ฉันเป็นกัปตัน",
  str_voice_1601191_35 = "ฉันพร้อมแล้ว",
  str_voice_1601191_36 = "ได้เวลาแล้ว",
  str_voice_1601191_37 = "ชาร์จ แกตายซะ",
  str_voice_1601191_38 = "ไม่เคยพอ",
  str_voice_1601191_39 = "ไปกับกระแสลม",
  str_voice_1601191_40 = "และพวกมันทั้งหมด",
  str_voice_1601191_41 = "ฉันสมควรได้รับมัน",
  str_voice_1601191_42 = "สรรเสริญฉันสรรเสริญฉัน!",
  str_voice_1601191_43 = "เราจะเอาชนะมันใครครั้งต่อไป",
  str_voice_1601191_44 = "1, 2, 3, 4, 5... มีใครอีก ลืมแล้ว นับจำนวนศัตรูที่ฉันจัดการ...",
  str_voice_1601191_45 = "ขอบคุณ และยินดี",
  str_voice_1601191_46 = "ฉันรับมันไปได้เหรอ ฉันเขิน...",
  str_voice_1601191_47 = "ผู้นำทาง เธอดีเกินไป",
  str_voice_1601191_48 = "ฉันเขิน อย่ามองฉัน",
  str_voice_1601191_49 = "สู้กับอิคลิพไซท์ที่โรงเรียน และแผลเป็นบนใบหน้านี้ ฉันได้มา แต่เด็กคนอื่นไม่สนใจฉัน พวกเขาบอกว่ามันประหลาดมาก...",
  str_voice_1601191_50 = "ตอนที่ฉันยังเด็ก มันบุกบ้านของฉัน อิคลิพไซท์ พ่อแม่ไปช่วยคนอื่น เพื่อนบ้านช่วยฉัน ฉันเสียมือซ้าย\nไปตอนนั้น",
  str_voice_1601191_51 = "มองแขนฉันเหรอ อิลลูมินาให้ฉันมา... เพราะพ่อแม่ของฉันตายสู้กับอิคลิพไซท์ พวกเขา...ช่วยคนจำนวนมาก",
  str_voice_1601191_52 = "Alchemy Stars",
  str_voice_1601191_53 = "กลับมาแล้ว",
  str_voice_1601191_54 = "อรุณสวัสดิ์ ผู้นำทาง",
  str_voice_1601191_55 = "กินมื้อเที่ยงหรือยัง",
  str_voice_1601191_56 = "ขอให้เธอฝันดี",
  str_voice_1601191_57 = "สุขสันต์วันปีใหม่ ขอให้เธอแข็งแกร่งในปีต่อไป",
  str_voice_1601191_58 = "ฉันมาแล้ว",
  str_voice_1601191_59 = "ทำเสียงแบบนั้นอีกแล้ว ดาบของฉัน...",
  str_voice_1601191_60 = "ฉันแข็งแกร่งขึ้นแล้ว",
  str_voice_1601191_61 = "เธอกำลังทำอะไร",
  str_voice_1601191_62 = "ไปดูโคลอสซัสอีกแล้วเหรอ",
  str_voice_1601151_1 = "เธอถามฉันว่าอิสรภาพคืออะไรใช่ไหม เป็นคำถามที่ดีนะ แต่ก่อนที่ฉันจะตอบ เธอจะไม่ค้นหาคำตอบให้ตัวเองหน่อยเหรอ?",
  str_voice_1601151_2 = "ขอโทษที... ต้องแนะนำตัวกันสินะ เบสซี่คือกวางของฉัน ส่วนโอลีฟกับปาล์มคือนกกาเหว่าของฉัน นอกจากเป็นภูตวาจาของฉันแล้ว ยังเป็นเพื่อนที่จริงใจที่สุดอีกด้วย",
  str_voice_1601151_3 = "เจ้าตัวเล็ก ๆ ที่เรืองแสงอยู่ในกระเป๋าของฉันคือหิ่งห้อย แต่พวกมันไม่เหมือนที่โคลอสซัสนะ พวกมันอยู่กับฉันมาตั้งแต่ตอนที่เราอยู่ในป่าลู่ลม",
  str_voice_1601151_4 = "ในวินาทีที่ยอมรับโชคชะตาของตัวเองด้วยใจสงบ ฉันก็มองเห็นเวลาเลื่อนไหลและพื้นที่ขยายตัว และฉันรู้ดีว่าอิสรภาพได้เปิดประตูรับฉันแล้ว",
  str_voice_1601151_5 = "ได้เห็นฉันแล้วโชคดีเหรอ...? ข่าวลือนี้มีจริงเหรอเนี่ย? ถ้ามันเป็นจริงล่ะก็ ฉันก็อยากมอบโชคนี้ให้เธอนะ",
  str_voice_1601151_6 = "ใช่แล้ว ฉันสื่อสารกับสัตว์และพืชได้ เหมือนที่เธอเชื่อมโยงกับคนอื่นได้ทางโทรจิตนั่นแหละ มันคือพรสวรรค์ตามธรรมชาติของเรา",
  str_voice_1601151_7 = "ถ้าเธอหวังที่จะได้เจอฉัน โปรดกระซิบชื่อฉันไว้ในหัวใจ ธรรมชาติจะนำทางให้ฉันมาอยู่ข้างเธออีกครั้ง",
  str_voice_1601151_8 = "ฉันชวนเบสซี่ไปเดินเล่นด้วยกัน แล้วก็เจอเธอโดยบังเอิญ นั่นอาจเป็นความตั้งใจของเบสซี่ก็ได้... เพราะเจ้ากวางนั่นชอบเธอมากเลย",
  str_voice_1601151_9 = "โอลีฟกับปาล์มร้องเพลงเกี่ยวกับเธออยู่นะ ไม่คิดเลยว่าเธอจะทำให้สองตัวนั้นประทับใจได้ขนาดนี้",
  str_voice_1601151_10 = "ฉันเห็นแสงประกายในดวงตาของเธอที่แตกต่างจากออโรเรียนคนอื่น อยากรู้จังว่าเธอคิดอะไรอยู่นะ?",
  str_voice_1601151_11 = "สภาพแวดล้อมที่นี่เป็นมิตรกว่าที่คาดไว้ และฉันก็ยินดีรับภารกิจนี้จากธรรมชาติ หวังว่าการมาถึงของฉันจะไม่ทำให้เธอผิดหวังนะ",
  str_voice_1601151_12 = "เธออาจไม่เคยสังเกต แต่พลังแห่งธรรมชาตินั้นอยู่เคียงข้างและคอยนำทางให้เธอเสมอ",
  str_voice_1601151_13 = "สายลมบอกเมฆ เมฆบอกฝน ฝนบอกดิน และดินก็บอกกับสายลม... ทุกสิ่งจะพบคำตอบในที่สุด",
  str_voice_1601151_14 = "สวัสดี มีจดหมายถึงลูโมโพลิสบ้างไหม?",
  str_voice_1601151_15 = "สุขสันต์วันเกิด ผ่านไปอีกปี ความเข้าใจในธรรมชาติก็ยิ่งลึกซึ้งขึ้น",
  str_voice_1601151_16 = "ฉันต้องจัดการเรื่องด่วนของสหภาพผู้ส่งสารในบางครั้ง แต่ก็ไม่ได้มีอะไรยากเกิน เธอล่ะเป็นไงบ้าง",
  str_voice_1601151_17 = "ขอโทษที โอลีฟกับปาล์มมักจะร้องเพลงแบบนี้เวลาตื่นนอน พวกเขารบกวนเธอรึเปล่า?",
  str_voice_1601151_18 = "ไปเดินเล่นกันไหม พาเบสซี่ไปด้วย เราจะได้พักผ่อนในป่าลึก",
  str_voice_1601151_19 = "ฉันบังเอิญเจอเธอในฝัน... เธออาจเป็นคนที่นำทางฉันต่อไปจากนี้ก็ได้...",
  str_voice_1601151_20 = "ในอาณาจักรแห่งธรรมชาตินี้ เรามีอิสระที่จะถ่ายทอดความรักและความหวังตามที่ใจเราปรารถนา",
  str_voice_1601151_21 = "สักวันหนึ่งฉันจะหวนคืนสู่นอร์ธแลนด์... กลับสู่ผืนป่าที่อบอุ่น สักวันหนึ่ง...",
  str_voice_1601151_22 = "เธอต้องเชื่อมั่นว่าสหภาพผู้ส่งสารจะนำส่งได้เสมอ",
  str_voice_1601151_23 = "ความวุ่นวายและไร้ระเบียบ... ฉันมั่นใจว่าสิ่งเหล่านั้นไม่ได้เกิดจากธรรมชาติ",
  str_voice_1601151_24 = "องค์ราชินีคือทูตแห่งพลังธรรมชาติ นำทางแก่เด็กน้อยผู้หลงทางทั้งหลาย",
  str_voice_1601151_25 = "ตุ๊กตาหิมะที่มีปีกเหรอ? นั่นทวีตตี้ เธอเป็นเด็กที่เรียบง่ายและจิตใจดี",
  str_voice_1601151_26 = "สรรพสัตว์ทั้งหลายในโลกนี้เกิดขึ้นด้วยเจตจำนงของธรรมชาติ และมีความงดงามในแบบของตัวเอง",
  str_voice_1601151_27 = "ความอบอุ่นที่แม่มอบให้อยู่ในผ้าคลุมผืนนี้ มันปกป้องฉันจากความหนาวเย็น",
  str_voice_1601151_28 = "หิ่งห้อยของฉันกับหิ่งห้อยของเธอ เคเลสไทต์กับออโรเรียน โคลอสซัสกับธรรมชาติ... เราอยู่ในโลกที่วิเศษเหลือเกิน",
  str_voice_1601151_29 = "ฉันรอมานานที่จะได้เจอเธอ ในที่สุดพลังแห่งธรรมชาติก็ได้นำทางให้ฉันมาหาเธอแล้ว ยินดีที่ได้พบกันนะ ฉันชื่อนาโรเซล",
  str_voice_1601151_30 = "ฉันได้ยิน... เสียงเรียกแห่งธรรมชาติ",
  str_voice_1601151_31 = "ฉันได้ยินบทเพลงแห่งสายลม...",
  str_voice_1601151_32 = "ฉันเห็นสายน้ำร่ายรำ...",
  str_voice_1601151_33 = "ได้สัมผัสได้ถึงลมหายใจแห่งอิสรภาพ...",
  str_voice_1601151_34 = "ตามหัวใจเธอไป",
  str_voice_1601151_35 = "ไปกันเถอะเบสซี่",
  str_voice_1601151_36 = "ฉันรอให้เธอนำทางอยู่นะ",
  str_voice_1601151_37 = "ให้ธรรมชาติดำเนินไป",
  str_voice_1601151_38 = "เป็นไปตามธรรมชาติ!",
  str_voice_1601151_39 = "เต้นรำกับสายลม",
  str_voice_1601151_40 = "ป่าหิ่งห้อย!",
  str_voice_1601151_41 = "มากับฉันสิ",
  str_voice_1601151_42 = "นี่คือการชื่นชมที่ธรรมชาติมอบให้เรา",
  str_voice_1601151_43 = "นี่อาจเป็นแผนของธรรมชาติด้วยเช่นกัน...",
  str_voice_1601151_44 = "เธอเคยได้ยินเสียงเรียกแห่งธรรมชาติไหม?",
  str_voice_1601151_45 = "ขอบคุณนะ เธอไม่จำเป็นต้องลำบากเลย",
  str_voice_1601151_46 = "ขอบคุณสำหรับน้ำใจนะ ฉันจะรับไว้",
  str_voice_1601151_47 = "มันมีกลิ่นของธรรมชาติ ฉันชอบจัง",
  str_voice_1601151_48 = "รู้ได้ยังไงเนี่ยว่าฉันชอบอะไร...? ธรรมชาติบอกเธอเหรอ?",
  str_voice_1601151_49 = "ตอนที่ฉันยังเด็กมาก ๆ ฉันได้พบกับเบสซี่ โอลีฟ ปาล์ม และหิ่งห้อยพวกนี้ในป่าลู่ลม ตั้งแต่นั้นมาเราก็ไม่เคยแยกจากกันอีกเลย",
  str_voice_1601151_50 = "เบสซี่ช่วยให้ฉันตระหนักถึงที่ที่ฉันควรอยู่ และภารกิจของฉันในโลกนี้ ฉันต้องทำตามคำแนะนำของธรรมชาติและก้าวต่อไปเพื่อทำให้การเกิดใหม่ของฉันในอาณาจักรแห่งธรรมชาติเป็นอันสมบูรณ์",
  str_voice_1601151_51 = "พ่อแม่รักฉันเหมือนลูกในไส้ แม้ว่าร้านค้าในลูโมโพลิสจะมีเสื้อผ้าหรูหรามากมาย ฉันก็รู้สึกว่าเสื้อผ้าตัดเย็บเองที่แม่ส่งมาให้นี่แหละสวมสบายที่สุดแล้ว",
  str_voice_1601151_52 = "Alchemy Stars",
  str_voice_1601151_53 = "เธออยู่นี่เหรอ?",
  str_voice_1601151_54 = "เริ่มต้นวันใหม่กับธรรมชาติ",
  str_voice_1601151_55 = "เป็นเวลาที่เหมาะกับการผ่อนคลาย",
  str_voice_1601151_56 = "เราจะได้พบกันในความฝัน",
  str_voice_1601151_57 = "ปีใหม่นำมาซึ่งชีวิตใหม่ ซึ่งควรค่าที่จะต้อนรับเสมอ",
  str_voice_1601151_58 = "ตอนที่รู้สึกเหนื่อย เธอไปที่ไหนเหรอ ผู้นำทาง?",
  str_voice_1601151_59 = "เธอชอบดนตรีไหม ผู้นำทาง?",
  str_voice_1601151_60 = "ขอบคุณนะ ผู้นำทาง",
  str_voice_1601211_1 = "หนามไม่เคยทำร้ายผู้คน... มันอยู่อย่างสงบในที่ของมัน แต่คำพูดของคนนี่สิ แทงข้างหลังเราได้เหมือนมีดที่คมกริบเลย แล้วแบบไหนล่ะที่แย่กว่ากัน...?",
  str_voice_1601211_2 = "ฉันคิดฉันจึงเป็นอยู่ ดังนั้นถ้าฉันไม่คิด ฉันก็จะไม่มีตัวตนอยู่อีกต่อไป ตอนนี้ฉันไม่ได้คิดอะไรนะผู้นำทาง เธอยังเห็นฉันอยู่ไหม?",
  str_voice_1601211_3 = "ความยุติธรรมอาจล่าช้า แต่ไม่มีทางปฏิเสธได้ อ๋อ... แต่บางทีก็ล่าช้าจนฉันคิดว่าอาจจะไม่มาแล้ว...",
  str_voice_1601211_4 = "อยากดูเหรียญที่แขวนคอฉันอยู่น่ะเหรอ ได้สิ... ขอแค่อย่ากัดก็แล้วกัน",
  str_voice_1601211_5 = "ความศรัทธาให้การสนับสนุนที่ทรงพลังที่สุดในจินตนาการ อ๋อ แต่บ้านเรือน สะพาน และโบสถ์วิหารก็ต้องมีรากฐานเป็นหินแข็งแกร่งด้วยเหมือนกัน",
  str_voice_1601211_6 = "เธอเห็นเด็กผู้หญิงผมสั้นนั่นไหม? อ๋อ ฉันคุ้นเคยกับเธอมากเลย...",
  str_voice_1601211_7 = "ในท้ายที่สุดการพิพากษาก็จะมาถึงทุกคน โอ้ แต่ถ้าคนชั่วจากไปก่อนที่คำพิพากษาจะมาถึงล่ะ หมายความว่าเขาจะผ่านไปเฉย ๆ งั้นเหรอ",
  str_voice_1601211_8 = "เหล่านักบวชแห่งลูโมโพลิสบอกว่าผู้ที่ไร้ซึ่งศรัทธาก็ไม่ต่างอะไรจากสัตว์ร้าย แต่ฉันก็เชื่อว่าสัตว์ร้ายทุกตัวก็มีวันของตัวเอง...",
  str_voice_1601211_9 = "เธอเคยไปที่ลูโมโพลิสไหม เคยเห็นความสูงส่งกับความจงรักภักดีของคนที่นั่นไหม โอ๊ย มันน่าขำมากเลย...",
  str_voice_1601211_10 = "ฉันชอบอยู่ว่าง ๆ มากกว่าอยู่ยุ่ง ๆ ปล่อยใจให้ล่องลอย... มองดูเหรียญ สัมผัสหนาม...",
  str_voice_1601211_11 = "ทิวทัศน์ที่นี่น่ารื่นรมย์มาก มันทำให้ใจฉันเต็มไปด้วยความคิดนับไม่ถ้วน... ว่าจะจัดการพวกคนชั่วที่ลูโมโพลิสยังไง...",
  str_voice_1601211_12 = "ในสายตาของเทพเจ้าแห่งแสงสว่าง ผู้คนทั้งหมดล้วนเท่าเทียมกัน อ๋อ แต่บางคนก็เท่าเทียมมากกว่าคนอื่นแค่นั้นแหละ",
  str_voice_1601211_13 = "แม้แต่หนามที่แหลมคมที่สุดก็ยังอยู่เคียงข้างดอกไม้ที่สวยงาม ดูเอาเองเถอะ...",
  str_voice_1601211_14 = "ความตั้งใจจริงของเราผลักดันให้เราก้าวไปข้างหน้า... แต่ถ้าไปผิดทางตั้งแต่เริ่มต้น เราจะไม่ออกห่างไปจากเส้นทางที่แท้จริงเหรอ?",
  str_voice_1601211_15 = "สุขสันต์วันเกิด มันเป็นคำพูดเชย ๆ แต่ฉันนึกอะไรที่ดีกว่านี้ไม่ออกแล้ว",
  str_voice_1601211_16 = "เริ่มต้นวันธรรมดาอีกวันหนึ่งนะ เอ่อ ถ้ามันไม่ธรรมดา เราคงไม่อยู่ที่นี่กันใช่ไหมล่ะ",
  str_voice_1601211_17 = "ผู้นำทาง ทำไมใคร ๆ ก็พูดอรุณสวัสดิ์ตลอดเลย ถ้ามันไม่สวัสดิ์ล่ะ?",
  str_voice_1601211_18 = "หลังจากที่ฉันเสร็จงาน ช่วงค่ำก็มีไว้พักผ่อน คนที่ทำงานล่วงเวลานี่น่าสมเพชชะมัดเลย",
  str_voice_1601211_19 = "ความนิ่งงันแห่งราตรี... มันอาจทำให้เราคิดทบทวนอะไรได้ง่ายขึ้นนะ อ้อ มันยังทำให้เราหลับง่ายขึ้นด้วย",
  str_voice_1601211_20 = "ความจริงแท้ในโลกนี้น่ะไม่มีหรอก มีแค่วิญญาณอยู่ที่ลิ้นของคนทรยศเท่านั้น",
  str_voice_1601211_21 = "เหล่านักบวชแห่งลูโมโพลิสบอกว่าความศรัทธานั้นผลักดันให้คนก้าวไปข้างหน้า แต่มันไม่ได้ทำให้ท้องอิ่ม",
  str_voice_1601211_22 = "ขอความจริงจงสถิตกับท่าน ถ้ามันมีอยู่จริงนะ",
  str_voice_1601211_23 = "ถ้าเทพแห่งแสงสว่างสร้างสรรพสิ่งทั้งหลาย... แปลว่าสร้างอิคลิพไซท์ขึ้นมาด้วยงี้หรอ?",
  str_voice_1601211_24 = "สิ่งเดียวที่แพกต์กับฉันมีเหมือนกันก็คือหนาม นอกนั้นก็ไม่มีอย่างอื่นแล้ว",
  str_voice_1601211_25 = "อย่ายอมแพ้—นี่คือคติของเวย์น มันคือหลักการที่เขาใช้ดำเนินชีวิต และเป็นแหล่งกำเนิดของ \"ความสุข\" ของเขา",
  str_voice_1601211_26 = "เขาว่ากันว่าดอกเถาไม้หนามเป็นสัญลักษณ์แห่งความทรมานของโชคชะตา แต่ฉันเชื่อว่ามันเป็นตัวแทนแห่งความยืดหยุ่นของจิตวิญญาณ",
  str_voice_1601211_27 = "ความเชื่อที่ผิด ๆ มักทำให้มีคนมาเลื่อมใส ยิ่งแปลกประหลาดเท่าไร ก็ยิ่งปลุกเร้าให้เกิดความกระตือรือร้นได้มากเท่านั้น",
  str_voice_1601211_28 = "ดูจากด้านนอกมันใหญ่มาก แต่ภายในไม่ค่อยกว้างขวางเท่าไหร่ แต่ที่บินได้นี่ถือว่าน่าสนใจนะ",
  str_voice_1601211_29 = "ฉันชื่อพาโลม่า โชคชะตาทำให้เราได้มาเจอกัน แต่ถ้าเธอคิดดูให้ดี ทั้งหมดนี้อาจเป็นแค่ความบังเอิญก็ได้ ยังไงก็สวัสดีนะ",
  str_voice_1601211_30 = "พลังต้านทานของฉันแข็งแกร่งขึ้น",
  str_voice_1601211_31 = "ตราสัญลักษณ์ของฉัน... มีหนามใหม่งอกออกมาแล้ว...",
  str_voice_1601211_32 = "เส้นทางแห่งหนามได้เผยโฉมออกมาให้ฉันเห็น",
  str_voice_1601211_33 = "อดีตที่เป็นเศษเสี้ยว... ของฉัน",
  str_voice_1601211_34 = "ถึงตาฉันแล้วเหรอ?",
  str_voice_1601211_35 = "ได้เวลาของการเกิดใหม่แล้ว",
  str_voice_1601211_36 = "การเกิดใหม่รออยู่",
  str_voice_1601211_37 = "จงตัดขาด!",
  str_voice_1601211_38 = "ตัดขาดจากวันวาน!",
  str_voice_1601211_39 = "บิดเบี้ยวอยู่ในเถาไม้...",
  str_voice_1601211_40 = "ความสิ้นหวังกลางดงหนาม!",
  str_voice_1601211_41 = "อยากให้ฉันเป็นผู้นำเหรอ? ทำตามที่ใจต้องการเถอะ",
  str_voice_1601211_42 = "เป็นไง... เราชนะแล้ว",
  str_voice_1601211_43 = "วิ่งไปให้เหมือนสายลม!",
  str_voice_1601211_44 = "เรื่องนี้มัน... สำคัญมากจริง ๆ เหรอ?",
  str_voice_1601211_45 = "โอ๊ะ? ไม่เลวเลยนะนี่",
  str_voice_1601211_46 = "น่าสนใจ น่าสนใจมากเลย...",
  str_voice_1601211_47 = "ถือว่านี่เป็นการขอบคุณของฉันนะ",
  str_voice_1601211_48 = "สวยมากเลย... อ่า ขอบคุณนะ!",
  str_voice_1601211_49 = "ขอเทิดทูนรัตติกาลสีขาว... อย่าแปลกใจนะที่ได้ยินฉันพูดอะไรแบบนี้ เพราะยังไงฉันก็เป็นแม่ชีมาก่อน นึกภาพไม่ออกเลยใช่ไหมล่ะ",
  str_voice_1601211_50 = "ลูโมโพลิสให้ที่พักพิงกับประชาชนของตัวเอง อื้ม... แล้วทำไมถึงปล่อยให้พ่อแม่ฉันตายต่อหน้าฉันล่ะ? นี่คือการพิพากษาที่ยุติธรรมของลูโมโพลิสเหรอ? คำพูดนี้ควรไปเน่าหนอนอยู่ในนรกโน่นซะ ฉันไม่สนใจหรอก...",
  str_voice_1601211_51 = "ชีวิตหรูหราของชนชั้นสูงในลูโมโพลิสที่ทุกคนอิจฉา... ถ้าเลือกได้อีกครั้ง ฉันขอเป็นคนธรรมดาดีกว่า",
  str_voice_1601211_52 = "Alchemy Stars",
  str_voice_1601211_53 = "สวัสดี",
  str_voice_1601211_54 = "อรุณสวัสดิ์ ตื่นเช้าจังนะ",
  str_voice_1601211_55 = "ได้เวลาพักกินอาหารกลางวันแล้ว",
  str_voice_1601211_56 = "ขอให้ฝันดีสุด ๆ ไปเลยนะ",
  str_voice_1601211_57 = "สุขสันต์วันปีใหม่ ขอให้สิ่งมหัศจรรย์ที่แท้จริงบังเกิดกับพวกเรานะ",
  str_voice_1601211_58 = "สวัสดี ผู้นำทาง ฉันชื่อพาโลม่า",
  str_voice_1601211_59 = "เธอเห็นเหรียญของฉันบ้างรึเปล่า?",
  str_voice_1601211_60 = "เธอเห็นหญิงสาวผมสั้นคนนั้น ใช่ไหม?",
  str_voice_1601211_61 = "ขอโทษนะ แต่ช่วยบอกได้ไหมว่าคำว่า \"ศรัทธา\" มีความหมายยังไงสำหรับเธอ?",
  str_voice_1601211_62 = "เธอเคยเห็นดอกของเถาไม้หนามรึเปล่า?",
  str_voice_1300651_1 = "ยินดีต้อนวร้าบ! อ๊ะ ไม่สิ ที่นี่ไม่ใช่โรงแรมซากุระเมฆวา! หา? ม่ายเป็นไวรงั้นเหรอ?",
  str_voice_1300651_2 = "คุณชวอบหิมะรึเปล่า? มาปาลูกบอลหิมะสู้กันกับฉันสิ! ม่ายต้องกรัว ฉันมีเพียบเรย!",
  str_voice_1300651_3 = "ผู้นำทาง ฉันนำของขวัญมาโส่งให้คุณ! โอ๊ะ... ฉันใส่ไว้ในหมวกนะ! หายไปไหนแล้วเนี่ย?",
  str_voice_1300651_4 = "อ้าว ขอโทวษนะ! ฉานทำให้คุณกรัวรึเปล่า ลูกบอลสีขาวนี่คือนกน้วยของฉันเอง ไม่ใช่บอลหิมะ!",
  str_voice_1300651_5 = "ฉันปาบอลหิมะเก่งขึ้นแล้วนะ! ฉันจะทำตุ๊กตาหิมะตัวใหญ่ให้หน้าตาหมวนคุณเรย!",
  str_voice_1300651_6 = "คุณชวอบซากุระรึเปล่า ผู้นำทาง ฉันน่ะชวอบมากเรย โดยเฉพาะดอกหิมะกับซากุระ... เวลาบานนี่สวยมั่กเรย!",
  str_voice_1300651_7 = "ผู้นำ-ผู้นำ-ผู้นำทาง! ฉันอยากปรับวิธีการพวดของฉันอะ คุณโช่ยหน่อยได้ม้าย?",
  str_voice_1300651_8 = "ถ้าเจอปวัญหาเมื่อไหร่ บอกมาได้เรยนะ ฉันยินดีที่จะแบ่งเบาภาระ!",
  str_voice_1300651_9 = "ผู้นำทาง เวลามาพักบนภูเขาเมฆวา อย่ารืมบวกฉันนะ! ฉันจะขอลวาพักร้อนไปต้อนรับคุณเอง",
  str_voice_1300651_10 = "ผู้นำทาง เขวียนจวดหมายเสร็จรึยัง ฉันจะเอาไปโส่งให้ และมันจะไปถึงจุดหมายในไม่ช้า",
  str_voice_1300651_11 = "ฉันมาแล้ว! ว้าววว! ที่นี่เหมาะจะปาบวอลหิมะที่สุดเรย!",
  str_voice_1300651_12 = "อะไรนะ? มีจวดหมายติดหางฉันเหรอ...? ว้าว มีจริมด้วย! ขอบคุณนะผู้นำทาง!",
  str_voice_1300651_13 = "นกน้อย ๆ ของฉันบอกว่าพวกมันคิดถึงดอกซากุระที่ภูขาเมฆวา",
  str_voice_1300651_14 = "ผู้นำทาง แถวนี้มีที่หนายให้ฉันไปแช่น้ามพุร้อนได้บ้างเหรอ?",
  str_voice_1300651_15 = "บวอลหิมะลูกนี้สวยม้าย เอาไปเลย แล้วสุขสันต์วันเกิดนะ!",
  str_voice_1300651_16 = "อาวละ พว้อมแล้ว! ฉันมาแล้ว! ฟิ้วววว! จดหมายของคุณอยู่นี่ ช่วยเซ็นชื่อตรงนี้ด้วยค่ะ!",
  str_voice_1300651_17 = "อรุณสวัสดิ์! ผู้นำทาง คุณยังนอนอยู่อีกเหยอ ฉันลุกจากเตียงแร้วนะ!",
  str_voice_1300651_18 = "ยุ่ง ยุ่ง ยุ่งตลอด... เวลานี้ท้วกวันเลย อยากไปแช่น้ามพุร้อนจังง่ะ",
  str_voice_1300651_19 = "ยังไม่หวับอีกเหรอผู้นำทาง? ตาฉันจะปิดอยู่แล้ว ราตรี... สวัสดิ์... คร่อกกก...",
  str_voice_1300651_20 = "ฉันไม่ได้แคร์แต่เรื่องหาเงินหรอกนะ... ฉันอยากเรีวยนรู้วจากผู้ส่วงสารอาวุโสที่เป็นมือโปร!",
  str_voice_1300651_21 = "ฉันชวอบนอร์ธแวนด์! มันเหมือนภูเขาเมฆวาบ้านเกิดฉันเด๊ะเรย",
  str_voice_1300651_22 = "โปรดมั่นใจว่าสหภาพผู้ส่วงสารนำส่งของให้ได้เสมอ!",
  str_voice_1300651_23 = "อิควิปไซ้นิสัยไม่ดี... แต่ถ้าคุณอยากสู้กับพวกมัน มาบอกให้ฉันโช่ยได้นะ!",
  str_voice_1300651_24 = "นาโวเซลน่ะเหรอ? ฉันรักเธอมั่กเรย! ถ้าฉันโตขึ้น ก็อยากจะเป็นเหมือนเธอได้บ้าง!",
  str_voice_1300651_25 = "เปปีเป็นคนดีสวดยวด เธอคอยดูแรพวกเราเสมอ!",
  str_voice_1300651_26 = "แช่น้ามพุร้อนไปด้วย ปาบวอลหิมะไปด้วย แล้วก็ชมซากุระไปด้วย... แน่นอนว่าฉันทำทุกอย่างได้พร้อมกัน!",
  str_voice_1300651_27 = "ส่งจดหมายฉบับนี้ไปที่เวดีเซล เวนช์เหรอ ที่จริงแล้ว... ฉันไม่ค่อยชวอบที่ร้อน ๆ เรยอะ",
  str_voice_1300651_28 = "ว้าว! นกน้อย ๆ ของฉันจะโตได้ขนาดนั้นม้าย?",
  str_voice_1300651_29 = "สวัสดีผู้นำทาง! จวำฉันได้มั้ยคะ? ทวีตตี้ไง มีอะไรให้โช่ยก็บอกได้เรยนะ!",
  str_voice_1300651_30 = "ว้าว! ไม่รู้เลยว่าฉันบวินได้สูงขนาดนั้น!",
  str_voice_1300651_31 = "บวอลหิมะ บวอลหิมะ บวอลหิมะ!",
  str_voice_1300651_32 = "บวอลหิมะของฉันลูกใหญ่ขึ้นเรื่อย ๆ แล้ว!",
  str_voice_1300651_33 = "ฉันเสื้อว่าสำเนียงของฉันเริ่มดวีขึ้นแล้ว!",
  str_voice_1300651_34 = "ฉันมาโช่ยแว้ว!",
  str_voice_1300651_35 = "เตรียมพว้อม ตุ๊กตาหิมะ!",
  str_voice_1300651_36 = "ฉันพว้อมลงมือแล้ว!",
  str_voice_1300651_37 = "ตุ๊กตาหิมะมาแว้ว!",
  str_voice_1300651_38 = "บอลหิมะพรั่งพรู!",
  str_voice_1300651_39 = "มาสนุกกานดีกว่า!",
  str_voice_1300651_40 = "พายุบอลหิมะ!",
  str_voice_1300651_41 = "ขอฉันลวองดูหน่อย!",
  str_voice_1300651_42 = "มานก็เป็นส่วนหนึ่งของงาน! ฮี่ฮี่!",
  str_voice_1300651_43 = "ฉันนึกว่าฉันจะโช่ยได้นะ...",
  str_voice_1300651_44 = "ผู้นำ-ผู้นำ-ผู้นำทาง! ฉันมีแบบสำรวจสหภาพผู้ส่วงสารให้คุณทำ! มีเวลากวอกสักหน่อยมั้ย?",
  str_voice_1300651_45 = "นี่... ให้ฉันจริม ๆ เหรอ",
  str_voice_1300651_46 = "ว้าว! อยากเอากลับไปให้คูมยายดูจัง!",
  str_voice_1300651_47 = "ผู้นำทาง คุณนี่เยี่ยมที่สวดเรย!",
  str_voice_1300651_48 = "วู้ฮู้! นี่คือของขวัญที่เยี่ยมที่สวดที่ฉันเคยได้รับเรยนะ!",
  str_voice_1300651_49 = "ทางตะวันออกไกลมีสถานที่ที่ฉวยงามแห่งหนึ่งเรียกว่าภูเขาเมฆวา ที่ซึ่งเกว็ดหิมะเต้นรำกับดอกซากุระในอากาศ ว้าว คิดถึงบ้านแล้วเนี่ย...",
  str_voice_1300651_50 = "คูมยายดูแลฉันมาตั้งแต่ยังเดว็ก ฉันต้องตั้งใจให้มากที่สุดเพื่อที่จะเป็นผู้ส่วงสารที่ยวดเยี่ยมและทำให้คูมยายภวมใจ!",
  str_voice_1300651_51 = "ฉันอาจจะพูดจาตลกก็จริง แต่ฉันมีพ่วนที่น่ารว้ากเยอะแยะบนแผ่นดินหญ่ายนะ หา? ช่ายสิ คุณเป็นพ่วนที่ดีคนหนึ่งของฉันเหมือนกันนะผู้นำทาง!",
  str_voice_1300651_52 = "Awchemy Stars!",
  str_voice_1300651_53 = "ฉันมาแว้ววว!",
  str_voice_1300651_54 = "อวุณสวัสดิ์ ผู้นำทาง!",
  str_voice_1300651_55 = "มีจวดหมายจะโส่งมั้ย ผู้นำทาง?",
  str_voice_1300651_56 = "ผู้นำทาง เข้านอนเว็ว ๆ นะ โอเครมั้ย?",
  str_voice_1300651_57 = "ถึงจะเป็นปีใหม่ การฟ่างบวอลหิมะก็ไม่เคยเป็นเรื่องเก่า!",
  str_voice_1300651_58 = "ทำรายอยู่อะ ผู้นำทาง?",
  str_voice_1601261_1 = "ตราบใดที่การค้าเป็นไปอย่างอิสระและเท่าเทียม เราก็ควรจะเคารพและปกป้องมัน เอาละ... ฉันสนใจที่จะซื้อโคลอสซัสลำนี้ มาเจรจากันหน่อยมั้ย?",
  str_voice_1601261_2 = "การสนองความต้องการลูกค้าเป็นกฎสำคัญที่นักธุรกิจจะต้องยึดถืออยู่เสมอ แล้วธุรกิจของนายให้อะไรกับลูกค้าบ้างล่ะ? ช่วยบอกฉันที",
  str_voice_1601261_3 = "ทุกสิ่งล้วนต้องอยู่ใต้กฎกติกา ไม่ว่าจะเป็นกฎหมายหรือความไว้วางใจ ไม่ว่าจะอยู่บนดินหรือใต้ดิน นี่คือสัญญาที่ผูกมัดนายไว้กับที่ที่นายเรียกว่าบ้าน",
  str_voice_1601261_4 = "เนื้อหาของสัญญาสามารถแก้ไขได้ถ้าถึงคราวจำเป็นจริง ๆ แต่นายจะต้องกระทำด้วยความจริงใจ มีเจตนาอันดี ซื่อตรง และเปิดเผย ไม่อย่างนั้นก็คงไม่มีใครช่วยนายได้",
  str_voice_1601261_5 = "ฉันรู้ว่านายมองอะไรอยู่ แต่ก็อยากให้รู้ด้วย ว่าการไม่จ้องหางคนอื่นน่ะเป็นมารยาทพื้นฐานที่ควรมีนะ",
  str_voice_1601261_6 = "เจ้านี่คือแฟรงค์ โอ้ เจ้านั่นก็แฟรงค์เหมือนกัน พวกมันเป็นภูตที่น่ารักของฉัน แน่นอน ฉันแยกออกว่าตัวไหนเป็นตัวไหน หือ? นายคิดว่ามันไม่เหมือนสัตว์เลี้ยงงั้นรึ?",
  str_voice_1601261_7 = "ซัพพลายเออร์ชุดดำ... นั่นเป็นฉายาสมัยก่อนของฉัน ฉายาก่อนที่เจ้าแห่งเงาจะรับฉันเป็นลูกบุญธรรม",
  str_voice_1601261_8 = "มีวงการหนึ่งที่ฉันรังเกียจเหลือเกิน... นั่นก็คือสินค้าใต้ดินที่หมุนเวียนอยู่ในเงามืด... ตราบใดที่พวกมันยังอยู่ ฉันก็จะต้องกำจัดมันให้สิ้นซาก",
  str_voice_1601261_9 = "การซื้อกิจการ การเจรจา การเงิน การขาย การตลาด... ฉันช่วยนายเรื่องพวกนี้ได้ หรือนายแค่อยากอ่านนิยายโรแมนติกกันล่ะ? เรื่องนั้นฉันก็ช่วยได้นะ",
  str_voice_1601261_10 = "กำหนดเส้นทางขนส่ง สถานที่ติดต่อ และเวลาเจรจาเรียบร้อย... เฮ้อ ในที่สุดก็ได้พักสักที อยากเห็นหนังสือเล่มโปรดของฉันมั้ย มาอ่านด้วยกันก็ได้นะ",
  str_voice_1601261_11 = "นายต้องการคำปรึกษาทางธุรกิจเรื่องอะไรเหรอ? เอาละ ก่อนอื่น เรามาเซ็นสัญญาที่ทั้งสองฝ่ายพอใจกันก่อนดีกว่า",
  str_voice_1601261_12 = "โอ๊ะ ดูสิว่าใครมา หวังว่าเราจะได้ข้อสรุปในการเจรจาวันนี้นะ",
  str_voice_1601261_13 = "ใช่ ฉันยังยุ่งอยู่ โทษทีนะ ผู้ช่วยฉันไม่อยู่น่ะ คราวหลังอย่าลืมนัดก่อนนะ ใช่ ถึงจะเป็นนายก็เถอะ เคเลสไทต์",
  str_voice_1601261_14 = "การเจรจาจบลงแล้ว มีใครช่วยพาแขกผู้ทรงเกียรติท่านนี้กลับบ้านได้มั้ย?",
  str_voice_1601261_15 = "สุขสันต์วันเกิด! ฉันหยุดงานมาฉลองวันเกิดกับนายน่ะ วันเกิดของเคเลสไทต์จะต้องเป็นกิมมิคที่ยอดเยี่ยมแน่ ๆ",
  str_voice_1601261_16 = "สวัสดี วันนี้เป็นวันที่ดีแต่ก็ยุ่งสุด ๆ นายต้องเข้าประชุมธุรกิจรึเปล่าเนี่ย?",
  str_voice_1601261_17 = "อรุณสวัสดิ์ กาแฟหนึ่งถ้วยกับหนังสือพิมพ์ นี่แหละ กิจวัตรยามเช้าของฉัน",
  str_voice_1601261_18 = "หลังจากทำงานหนักมาทั้งวัน การอ่านหนังสือก่อนนอนเป็นอะไรที่ดีเสมอ อย่าลืมเข้านอนแต่หัวค่ำล่ะ",
  str_voice_1601261_19 = "หืมม...? นาย... นายยังไม่นอนรึ ฉันกำลังอ่านอะไรอยู่? นั่นเป็นความลับทางการค้าน่ะ!",
  str_voice_1601261_20 = "โลกใบนี้เป็นสังคมทุนนิยมแห่งอุดมคติ ที่ซึ่งทุกคนที่ปฏิบัติตามกฎสามารถแสวงหาความมั่งคั่ง",
  str_voice_1601261_21 = "แค่ระบบปันเสบียงอย่างเดียวจะทำให้ผู้คนในอิลลูมินาได้สิ่งที่ปรารถนาจริง ๆ น่ะเหรอ?",
  str_voice_1601261_22 = "เงามืดจะคอยเฝ้ามองเจ้า",
  str_voice_1601261_23 = "การปรากฏตัวของพวกมันทำให้ตลาดการค้าต้องหยุดชะงัก และเกิดความสูญเสียทางการเงินมากมาย",
  str_voice_1601261_24 = "ถ้าเป็นเรื่องธุรกิจ คุณเชโอลก็จะเป็นคนร้ายกาจขึ้นมาทันที... ช่วยไม่ได้น่ะนะ",
  str_voice_1601261_25 = "ด้วยอะไรบางอย่าง กาแฟของคอนนอลลีมักจะทำให้ฉันรู้สึกถึงความหลังที่คุ้นเคยได้เสมอ",
  str_voice_1601261_26 = "อิสรภาพที่อยู่ภายใต้การควบคุมและเสียงของเงินตราที่ไหลเวียน... เอิ่ม... ใครบอกนายน่ะ ว่าฉันสะสมนิยายโรแมนติก?",
  str_voice_1601261_27 = "ความลับอันโสมมยังไงก็ต้องลอยขึ้นมาเด่นชัดในสักวัน แต่ถ้ามันไม่เป็นแบบนั้น ฉันก็จะดำลงไปลากมันขึ้นมาเอง",
  str_voice_1601261_28 = "ถ้านายใช้มันเพื่อการคมนาคม ก็น่าจะทำกำไรได้เยอะอยู่นะ ไม่สนใจตั้งบริษัทขนส่งของตัวเองรึ?",
  str_voice_1601261_29 = "ต้องขออภัยที่ให้คอยนาน ฉัน เบเธล หัวหน้าสำนักงานใหญ่กิลด์แห่งอัมบราตัน ถ้าต้องการคุยกับฉันเรื่องใดก็ตาม กรุณาติดต่อผู้ช่วยเพื่อนัดหมายเวลาเข้าพบด้วย",
  str_voice_1601261_30 = "เป็นการแลกเปลี่ยนที่ยุติธรรมดี",
  str_voice_1601261_31 = "นี่คือ... มือที่มองไม่เห็นอย่างนั้นรึ?",
  str_voice_1601261_32 = "แฟรงค์ดูจะถูกใจนะ",
  str_voice_1601261_33 = "ฉันรอไม่ไหวแล้ว... ที่จะได้เผชิญกับพายุลูกต่อไป!",
  str_voice_1601261_34 = "หวังว่าการร่วมงานของเราจะราบรื่นนะ",
  str_voice_1601261_35 = "สัญญาของเราจะเป็นไปตามที่ตกลงกันไว้",
  str_voice_1601261_36 = "โปรดเซ็นชื่อเดี๋ยวนี้!",
  str_voice_1601261_37 = "ไปเลย ทินดอลล์!",
  str_voice_1601261_38 = "แฟรงค์! การล่าเริ่มขึ้นแล้ว!",
  str_voice_1601261_39 = "เตรียมน้ำตาตกได้เลย",
  str_voice_1601261_40 = "เป็นไงล่ะ! รสชาติน้ำตาของแก!",
  str_voice_1601261_41 = "จัดการทีมงั้นรึ? เอาสิ",
  str_voice_1601261_42 = "บอกแล้วว่างานนี้เรากำไรแน่",
  str_voice_1601261_43 = "ความผันผวนของตลาด... คาดเดายากจริง ๆ...",
  str_voice_1601261_44 = "อืมม... ดูเหมือนนายจะทำสัญญาบางอย่างไว้สินะ",
  str_voice_1601261_45 = "ฉัน... ไม่ต้องจ่ายเงินใช่มั้ย?",
  str_voice_1601261_46 = "ขอบคุณนะ ฉันจะตั้งไว้ในออฟฟิศก็แล้วกัน",
  str_voice_1601261_47 = "ขอบคุณมาก สักวันฉันจะตอบแทนแน่นอน",
  str_voice_1601261_48 = "ฉัน... ถูกใจมากเลยละ ที่จริงแล้วนายเป็นนักเขียนอย่างนั้นรึ?",
  str_voice_1601261_49 = "แม่ของฉันเกิดในลูโมโพลิส ส่วนพ่อของฉันเป็นนักธุรกิจ สิ่งนั้นทำลายพ่อของฉันทั้งร่างกายและจิตใจ... ฉันก็เลยเกลียดวงการนี้เข้ากระดูกดำ",
  str_voice_1601261_50 = "คนบางคนในอัมบราตันเรียกฉันว่าซัพพลายเออร์ชุดดำ ตอนนั้นฉันยังไม่รู้ประสีประสาอะไร และเกือบจะทำให้กิจการของกิลด์เหนือเมฆพังทั้งระบบ",
  str_voice_1601261_51 = "ตอนนั้นฉันทำงานตัวคนเดียว และสุดท้ายก็บาดเจ็บสาหัส... โชคดีที่อีสต์วานรับอุปการะฉันเป็นลูกบุญธรรม ในที่สุดตอนนี้ฉันก็เข้าใจความสำคัญของกฎกติกาแล้ว",
  str_voice_1601261_52 = "Alchemy Stars.",
  str_voice_1601261_53 = "หือ?",
  str_voice_1601261_54 = "ถ้าไม่มีโอกาสทำกำไรรออยู่ จะลุกจากเตียงไปทำไมกันล่ะ",
  str_voice_1601261_55 = "บ่ายนี้งานยุ่งงั้นรึ?",
  str_voice_1601261_56 = "ร้านปิดหมดแล้วละ",
  str_voice_1601261_57 = "ในปีใหม่นี้ ฉันหวังว่าความร่วมมือระหว่างเราจะราบรื่นเช่นนี้ต่อไป",
  str_voice_1601291_1 = "งานใหม่ต้องทำอะไรบ้าง? แล้วต้องส่งเมื่อไหร่เหรอ? วางใจได้เลย ฉันจะรีบจัดการให้เรียบร้อย",
  str_voice_1601291_2 = "อัมบราตันไม่มีกฎหมายบังคับใคร และไม่ต้องจำกติกาการเอาตัวรอดให้ยุ่งยาก สิ่งสำคัญอย่างเดียวก็คือความไว้วางใจ นี่เป็นเหตุผลที่ยังไงฉันก็จะอาศัยอยู่ที่นี่ตลอดไป",
  str_voice_1601291_3 = "เพื่อให้ผู้คนรู้จักเรามากขึ้นและเชื่อมั่นในความแข็งแกร่งของเรา เราจะต้องขยายอิทธิพลกองทหารของเราให้มากกว่านี้... หือ โทษทีนะ ไม่ทันเห็นนายน่ะ",
  str_voice_1601291_4 = "งานมากขึ้นแปลว่าเราต้องมีสมาชิกมากขึ้น... แต่นั่นก็หมายความว่าเราต้องสูญเสียมากขึ้นเช่นกัน เมื่ออยู่ในจุดนี้ ยังไงเราก็ต้องเลือก เพราะงั้นฉันจะเลือกรับงานให้มากขึ้น",
  str_voice_1601291_5 = "มองผ้าคลุมฉันอยู่งั้นเหรอ? ถ้าอยากรู้จริง ๆ ละก็ ฉันเป็นคนวาดและลงสีเองแหละ ถ้านายชอบ หลังเสร็จงานฉันทำผ้าคลุมอีกตัวให้นายได้นะ",
  str_voice_1601291_6 = "ทหารรับจ้างอัคคีขาวเอาตัวรอดในอัมบราตันได้ก็เพราะความน่าเชื่อถือ นี่ทำให้เราแตกต่างจากองค์กรและประเทศชาติที่ถูกชี้นำโดยอำนาจรัฐ",
  str_voice_1601291_7 = "นาย... มองหน้ากากฉันอยู่เหรอ? ฉันสวมมาตั้งแต่เด็กแล้ว นี่เป็นของดูต่างหน้าที่พ่อบุญธรรมทิ้งไว้ให้ฉัน",
  str_voice_1601291_8 = "ฉันเคยรังเกียจธุรกิจใต้ดินมาก... แต่ก็ก้าวข้ามความรู้สึกพวกนั้นมาแล้ว การร่วมมือกับพวกนั้นทำกำไรเยอะกว่ามาก ๆ แล้วคนของฉันก็ต้องการเงินพวกนั้นมาเลี้ยงปากท้อง",
  str_voice_1601291_9 = "ให้ฉันวาดภาพนายมั้ย? อย่าดูถูกฝีมือวาดภาพของฉันเชียวนะ บางครั้งฉันได้ดีลจากแก๊งใต้ดินก็เพราะงานศิลปะนี่ละ",
  str_voice_1601291_10 = "ที่นี่สะอาดเรียบร้อยมากเลย... ขอปล่อยเพื่อนตัวน้อยของฉันออกมาแป๊บนึงได้มั้ย? เอ่อ... ถ้านายไม่กลัวน่ะนะ",
  str_voice_1601291_11 = "ช่วยรอให้ฉันส่งของชุดสุดท้ายเสร็จก่อนได้มั้ย... เอาละ ตอนนี้ฉันทำงานให้นายอย่างเต็มที่ได้แล้ว",
  str_voice_1601291_12 = "ฉันเคารพกฎเกณฑ์ของอัมบราตัน ถึงการซื้อขายบางครั้งมันจะ... ช่างเหอะ นี่แหละเป็นเหตุผลที่ต้องมีกองทหารรับจ้างอย่างฉันอยู่",
  str_voice_1601291_13 = "ฉันเห็นเจ้าตัวเล็กบินไปบินมาแถวนี้ด้วย... นายก็ชอบแมลงเหมือนกันเหรอเนี่ย?",
  str_voice_1601291_14 = "หัวหน้ากองทหารรับจ้างอัคคีขาวดูแลและสนับสนุนฉันมาตลอด ฉันซาบซึ้งในบุญคุณของเขาเหลือเกิน ถ้าไม่มีเขา ก็คงไม่มีฉันในวันนี้",
  str_voice_1601291_15 = "วันนี้เป็นวันเกิดของนาย กองทหารรับจ้างอัคคีขาวและตัวฉันขออวยพรด้วยความจริงใจ",
  str_voice_1601291_16 = "คงทำงานหนักมากสินะ... นายจะต้องแบ่งเวลาทำงานกับพักผ่อนให้พอเหมาะ และถ้าเป็นเรื่องพักผ่อน... นายอยากดูผีเสื้อของฉันมั้ย?",
  str_voice_1601291_17 = "อรุณสวัสดิ์ ฉันดีใจที่ได้เห็นนายตื่นเช้าขนาดนี้ เพราะนั่นแปลว่าเวลานอนของนายไม่เหมือนพวกทหารรับจ้างส่วนใหญ่ และมันก็ดีต่อสุขภาพของนาย",
  str_voice_1601291_18 = "ค่ำคืนมาเยือน... เป็นเวลาเหมาะสำหรับการทำภารกิจ",
  str_voice_1601291_19 = "นี่มันดึกแล้ว นายควรรู้ไว้ว่าสิ่งมีชีวิตบางชนิดก็ไม่ได้เกิดมาเพื่อตื่นในเวลาแบบนี้",
  str_voice_1601291_20 = "อัมบราตันคือเมืองแห่งเสรีภาพ แต่เสรีภาพควรมีขอบเขตรึเปล่า? ทุกวันนี้ก็ยังไม่มีใครตอบได้",
  str_voice_1601291_21 = "ทหารน่ะต่างจากทหารรับจ้างมาก ทั้งคู่ต้องทำตามคำสั่ง แต่การทำตัวให้น่าเชื่อถือสมความไว้วางใจ นั่นเป็นสิ่งที่เราเลือกได้",
  str_voice_1601291_22 = "เงามืด... มันอยู่ทุกหนทุกแห่ง และคอยเฝ้ามองเจ้า",
  str_voice_1601291_23 = "โทษทีนะ ฉันไม่นับว่าอิคลิพไซท์เป็นสิ่งมีชีวิต และศพของมันก็ไม่ทำให้ฉันเสียใจ",
  str_voice_1601291_24 = "อัลลัวราชื่นชอบสิ่งของที่ใช้บอกเวลา ฉันรู้เรื่องนี้มานานแล้ว",
  str_voice_1601291_25 = "อีสต์วาน... ทั้งการคานอำนาจระหว่างแก๊งต่าง ๆ แล้วก็การสื่อสารระหว่างผู้คน ฉันได้เรียนรู้สิ่งต่าง ๆ มากมายจากเขา",
  str_voice_1601291_26 = "แมลงคือผลผลิตจากธรรมชาติเหมือนเหล่าออโรเรียน สิ่งมีชีวิตทุกชนิดควรมีสิทธิ์เป็นอิสระจากดักแด้และเติบโตเป็นผีเสื้อ",
  str_voice_1601291_27 = "ผู้ที่ไม่เคารพชีวิต ไม่สมควรที่จะมีชีวิตอยู่",
  str_voice_1601291_28 = "ฉันรู้มาว่ามันคือส่วนผสมระหว่างจักรกลและชีววิทยา...? ช่างเป็นนวัตกรรมที่ล้ำเลิศจริง ๆ...",
  str_voice_1601291_29 = "สวัสดี ฉันชื่อลุค มีอะไรให้กองทหารรับจ้างอัคคีขาวช่วยมั้ย? วางใจได้ พวกเราทำงานทุกอย่างด้วยความเป็นมืออาชีพ",
  str_voice_1601291_30 = "กองทหารรับจ้างอัคคีขาวแข็งแกร่งขึ้นแล้ว",
  str_voice_1601291_31 = "พวกมันเกาะติดฉันอย่างเงียบงัน",
  str_voice_1601291_32 = "รวมกันเราอยู่!",
  str_voice_1601291_33 = "ชีวิตใหม่... จงเกิดขึ้นอย่างต่อเนื่อง!",
  str_voice_1601291_34 = "ขอบคุณที่ใช้บริการ",
  str_voice_1601291_35 = "ชีวิตคือนิรันดร์!",
  str_voice_1601291_36 = "ทุกอย่างอยู่ในการควบคุมของฉัน!",
  str_voice_1601291_37 = "พลังนี้จะดับลมหายใจของแก!",
  str_voice_1601291_38 = "ปลดปล่อยโซ่ตรวน!",
  str_voice_1601291_39 = "หมอกแห่งความตาย!",
  str_voice_1601291_40 = "กำจัดให้สิ้นซาก!",
  str_voice_1601291_41 = "ฉันจะเป็นกำลังให้ทีม!",
  str_voice_1601291_42 = "นี่คือพลังอันแข็งแกร่งของกองทหารรับจ้าง!",
  str_voice_1601291_43 = "ฉันต้องทำงานให้หนักกว่านี้...",
  str_voice_1601291_44 = "ใช้ที่นี่เป็นสถานที่ติดต่องานของทหารรับจ้างได้เลยนะเนี่ย",
  str_voice_1601291_45 = "ขอบคุณนะ ฉันจะตั้งไว้บนโต๊ะก็แล้วกัน",
  str_voice_1601291_46 = "ไม่ว่าจะต้องออกไปทำงานอะไร ฉันจะพกมันติดตัวไปด้วย",
  str_voice_1601291_47 = "ฉันอยากได้เจ้านี่มาตลอด... ขอบคุณนะ ฉันไม่รู้ว่าจะขอบคุณยังไงดีเลย",
  str_voice_1601291_48 = "ฉันจะรักษามันอย่างดี ขอโอกาสให้ฉันได้ตอบแทนนายด้วยเถอะ",
  str_voice_1601291_49 = "การรอคอยนั้นไม่ใช่เรื่องง่ายเลย ยิ่งถ้ารู้อยู่แก่ใจว่าคนที่รอไม่มีวันกลับมา โชคดีที่ฉันผ่านวันคืนเหล่านั้นมาแล้ว และฉันจะไม่ฝันถึงคืนนั้นอีกต่อไป",
  str_voice_1601291_50 = "นอกจากหัวหน้าจะเป็นพ่อที่แสนวิเศษ เขายังเป็นหัวหน้าที่มากความสามารถ ด้วยการสั่งสอนของเขา ในที่สุดฉันก็เข้าใจอย่างกระจ่าง ว่าคนที่ไม่รักษาคำพูดยังไงก็ไม่มีวันประสบความสำเร็จ",
  str_voice_1601291_51 = "นายอยากรู้ว่าฉันได้ความสามารถมาได้ยังไงงั้นเหรอ? คำตอบง่ายมาก ฉันเคารพชีวิต และชีวิตก็เคารพฉัน ฉันเลือกที่จะอยู่กับทุกชีวิตอย่างสันติ",
  str_voice_1601291_52 = "Alchemy Stars.",
  str_voice_1601291_53 = "สวัสดี",
  str_voice_1601291_54 = "อรุณสวัสดิ์ ฉันเริ่มงานแล้ว นายก็คงทำงานอยู่ใช่มั้ย",
  str_voice_1601291_55 = "เมื่อถึงเวลาเที่ยง นายควรพาตัวเองไปอาบออร่าแห่งธรรมชาติ",
  str_voice_1601291_56 = "ราตรีสวัสดิ์ แมลงของฉันจะช่วยให้นายหลับฝันดี",
  str_voice_1601291_57 = "สุขสันต์วันปีใหม่! ฉันหวังว่าทุกอย่างจะราบรื่นยิ่งขึ้นในปีใหม่นะ",
  str_voice_1500551_1 = "ถ้านายเจอปัญหาอะไรก็มาหาฉันที่ศาลยุติธรรมได้ทุกเมื่อ การพิจารณาคดีคือกระบวนการอันเที่ยงธรรม และฉันก็จะไม่เข้าข้างฝ่ายไหน",
  str_voice_1500551_2 = "เทพแห่งแสงสว่างผู้ยิ่งใหญ่คือผู้สร้างทุกสรรพสิ่งและช่วยให้ทุกชีวิตรอดพ้นจากภัย นี่เป็นความจริงอย่างไม่ต้องสงสัย และมันก็ไม่ยากที่จะเข้าใจ จงจดจำความจริงข้อนี้ไว้",
  str_voice_1500551_3 = "นายอยากเข้าร่วมการพิจารณาคดีของฉันงั้นรึ? ต้องขอโทษด้วย ฉันไม่มีสิทธิ์ทำแบบนั้นหรอก นายจะต้องติดต่อศาลยุติธรรมเพื่อลงทะเบียนและยืนยันตัวตนก่อน กฎก็ต้องเป็นกฎน่ะนะ",
  str_voice_1500551_4 = "เมื่อใดก็ตามที่ฉันกำคทาในมือไว้แน่น เสียงของพ่อก็จะดังก้องในหู \"ผู้ชายตระกูลพิตต์แมนจะอยู่ในสนามรบพร้อมกันสองคนไม่ได้เด็ดขาด\" นั่นเป็นสิ่งที่เขาบอกกับฉันเมื่อในอดีต",
  str_voice_1500551_5 = "ฉันเคยอยู่แนวหน้าและหลั่งเลือดในสนามรบมาก่อน ดังนั้น ฉันจึงเข้าใจอย่างแท้จริง ว่าทุกสิ่งในโลกใบนี้ล้วนมีราคาที่ต้องแลกมา",
  str_voice_1500551_6 = "หือ? ถ้าอยากดูก็ตามสบาย กระดูกจักรกลพวกนี้เป็นอุปกรณ์ที่สั่งทำจากอิลลูมินา ถ้าไม่มีมัน แขนซ้ายของฉันก็คงใช้การไม่ได้",
  str_voice_1500551_7 = "ผู้คนมากมายเลือกที่จะบรรลุเป้าหมายด้วยการเล่นการเมืองแทนที่จะพัฒนาความสามารถของตน แต่ฉันคิดว่านายแตกต่างจากคนพวกนั้น",
  str_voice_1500551_8 = "ถ้าตอนเด็กนายได้เรียนที่อุษาวิทยาลัย ฉันมั่นใจว่านายจะต้องเป็นนักเรียนดีเด่นที่มีผลการเรียนยอดเยี่ยม แน่นอนว่าตอนนี้ก็ยังไม่สายนะ",
  str_voice_1500551_9 = "ฉันชื่นชมท่านผู้พิพากษาสูงสุดยิ่งกว่าใคร และตอนนี้ก็มีนายอีกคน แน่นอนว่าคนรุ่นใหม่จะต้องก้าวไกลกว่าคนรุ่นเก่า! ฉันตื่นเต้นที่จะได้เห็นการเติบโตของนายในอนาคตแล้วสิ",
  str_voice_1500551_10 = "การจับคนร้ายหนีคดีเป็นงานอดิเรกชิ้นโปรดของฉันเลยละ อยากลองบ้างมั้ย? อืมม... ฉันว่านายไปฝึกร่างกายมาก่อนดีกว่า",
  str_voice_1500551_11 = "ตราบใดที่ฉันมีโต๊ะให้อ่านแฟ้มคดี ฉันก็อยู่ได้ทุุกที่ ยานลำนี้กว้างขวางจริง ๆ ลงตัวอย่างสมบูรณ์แบบเลยทีเดียว",
  str_voice_1500551_12 = "ทุกชีวิตล้วนเท่าเทียมภายใต้เทพแห่งแสงสว่าง พวกเราทุกคนล้วนมีโอกาสได้รับความเมตตาจากพระผู้เป็นเจ้า",
  str_voice_1500551_13 = "บันทึกของฉันมีเรื่องราวความอยุติธรรมมากมาย แต่จะกลัวอะไรล่ะ? ยังไงฉันก็จะต้องไขคดีทั้งหมดให้สำเร็จ",
  str_voice_1500551_14 = "ด้วยการชี้นำของเทพแห่งแสงสว่าง พระองค์จะทำให้เราได้เห็นจิตใจของตัวเอง จงเมตตากรุณาต่อผู้อื่นและต่อตนเอง",
  str_voice_1500551_15 = "สุขสันต์วันเกิด ขอเทพแห่งแสงสว่างจงมอบความสุขและปกป้องคุ้มครองผู้ที่ปฏิบัติตามกฎหมายอันศักดิ์สิทธิ์",
  str_voice_1500551_16 = "ได้เวลาทำงานแล้ว ถ้านายอยากคุยเรื่องที่ไม่เกี่ยวกับงาน ช่วยรอให้ถึงเวลาพักก่อนนะ",
  str_voice_1500551_17 = "อรุณสวัสดิ์ นี่เป็นเวลาที่สมองของฉันปลอดโปร่ง ปกติแล้วฉันก็จะใช้โอกาสนี้ขบคิดเพื่อไขคดีที่ยังไม่กระจ่าง",
  str_voice_1500551_18 = "วันนี้กำลังจะจบลง ฉันอยากมีเวลามากกว่านี้จัง",
  str_voice_1500551_19 = "นายก็คิดจะอยู่ดึกเหมือนกันเหรอ? นี่เป็นเรื่องลำบากไม่ว่าสำหรับใครก็ตาม",
  str_voice_1500551_20 = "เช่นเดียวกับเทพแห่งแสงสว่างผู้เป็นนิรันดร์ ลูโมโพลิสจะไม่มีวันพ่ายแพ้!",
  str_voice_1500551_21 = "ทรู ออเดอร์ งั้นรึ? พวกนั้นบังอาจใช้คำว่า \"ความจริง\" มาทำให้ผู้คนสับสน ฉันเกรงว่าเทพแห่งแสงสว่างคงไม่มีวันยกโทษให้พวกเขาหรอก",
  str_voice_1500551_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1500551_23 = "ถ้าเจออิคลิพไซท์ ฉันก็จะกำจัดมันทันที ยังไงพวกมันก็มีความผิด และไม่สมควรได้รับความยุติธรรมใด ๆ",
  str_voice_1500551_24 = "ในตอนนั้น ฉันไม่นึกเลยว่าเธอจะกลายมาเป็นสมาชิกของทรู ออเดอร์...",
  str_voice_1500551_25 = "ท่านผู้พิพากษาสูงสุดเป็นรุ่นพี่ของฉันที่วิทยาลัย และเป็นเจ้านายของฉันที่ศาลยุติธรรม... เธอก้าวนำหน้าฉันเสมอ และฉันก็ไม่อาจตามเธอได้ทัน",
  str_voice_1500551_26 = "พวกเราทุกคนมีตำแหน่งและหน้าที่ของตัวเอง ความงดงามของระเบียบนั้นไม่มีสิ่งใดทดแทนได้",
  str_voice_1500551_27 = "ไม่มีอะไรน่ารังเกียจมากไปกว่าการละเมิดกติกา ระบบ และกฎหมายแล้ว",
  str_voice_1500551_28 = "ขณะนี้บนโคลอสซัสยังไม่มีกฎหมายใด ๆ... ฉันคิดว่าถึงเวลาที่จะร่างมันขึ้นมาแล้วละ",
  str_voice_1500551_29 = "เทพแห่งแสงสว่างคงกำหนดให้เราได้พบกัน... สวัสดี ฉัน เวย์น พิตต์แมน ผู้พิพากษาจากศาลยุติธรรมแห่งลูโม",
  str_voice_1500551_30 = "เป็นการเติบโตที่ยั่งยืน",
  str_voice_1500551_31 = "พละกำลัง... เต็มเปี่ยมในร่างกายของฉัน!",
  str_voice_1500551_32 = "สายฟ้า... กู่ร้องคำรามเพื่อฉัน",
  str_voice_1500551_33 = "ความผิดบาปทั้งมวลจะต้องหมดทางหนี!",
  str_voice_1500551_34 = "ยอดเยี่ยม",
  str_voice_1500551_35 = "จงประจักษ์!",
  str_voice_1500551_36 = "ตั้งสติให้ดี!",
  str_voice_1500551_37 = "แก... มีความผิด!",
  str_voice_1500551_38 = "หมดทางหนีแล้ว!",
  str_voice_1500551_39 = "ประหาร!",
  str_voice_1500551_40 = "จงรับโทษทัณฑ์!",
  str_voice_1500551_41 = "ฉันจะพิพากษาอย่างเป็นธรรม",
  str_voice_1500551_42 = "เพื่อความเที่ยงธรรม!",
  str_voice_1500551_43 = "ฉันยังสืบสวนไม่ละเอียดพอ...",
  str_voice_1500551_44 = "ฉันต้องการที่เงียบ ๆ เพื่อสวดภาวนา",
  str_voice_1500551_45 = "นี่คือ... ของขวัญผูกมิตรงั้นเหรอ?",
  str_voice_1500551_46 = "ขอบคุณนะที่อุตส่าห์มอบของขวัญให้",
  str_voice_1500551_47 = "ขอรับไว้ก็แล้วกัน ขอบคุณมากนะ",
  str_voice_1500551_48 = "ช่างมีประโยชน์จริง ๆ ฉันชอบมากเลย",
  str_voice_1500551_49 = "สมัยก่อนฉันทำได้แค่นอนป่วยอยู่บนเตียงทั้งวัน เทพแห่งแสงสว่างเป็นผู้ส่องแสงแห่งความเที่ยงธรรมให้กับวิญญาณของฉัน และชี้นำฉันให้เผยแผ่ความเที่ยงธรรมของพระองค์ไปทั่วดินแดน... แม้ตอนนี้ฉันจะยังไม่บรรลุปณิธานของพระองค์ก็เถอะ",
  str_voice_1500551_50 = "ฉันไม่มีวันลืมคืนนั้นในอัมบราตัน เพื่อนของฉันตายไปทีละคน ความเหนื่อยล้าทำให้ไม่อาจก้าวเดิน วิญญาณของฉันร่ำไห้เสียใจ... สิ่งเดียวที่ฉันทำได้ก็คือการไขความจริงให้กระจ่าง!",
  str_voice_1500551_51 = "การอ่านแฟ้มคดีทำให้ฉันได้ค้นพบสิ่งที่ไม่คาดฝันเสมอ นอกจากจะทำให้ฉันทำงานได้อย่างมีประสิทธิภาพแล้ว มันยังทำให้ฉันเข้าใกล้ความจริงเบื้องหลังการก่อกบฏ แน่นอนว่าการศึกษาแนวทางพิพากษาคดีของภูมิภาคอื่น ๆ ก็น่าสนใจไม่แพ้กัน",
  str_voice_1500551_52 = "Alchemy Stars!",
  str_voice_1500551_53 = "โปรดระวังตัวด้วย",
  str_voice_1500551_54 = "อรุณสวัสดิ์!",
  str_voice_1500551_55 = "สถานการณ์เป็นยังไงบ้าง?",
  str_voice_1500551_56 = "ท้องฟ้ามืดลงแล้ว",
  str_voice_1500551_57 = "ตั้งแต่ปีใหม่นี้เป็นต้นไป โปรดจงเคารพกฎหมายด้วย",
  str_voice_1601231_1 = "อ-อะไรนะ? ต้องการความช่วยเหลืองั้นเหรอ? ปล่อยให้เป็นหน้าที่ฉันเอง!",
  str_voice_1601231_2 = "ขนมปังสามแผ่นกับชาดำสักแก้วเป็นมื้อเช้า อาหารเซ็ตอิลลูมินาเป็นมื้อกลางวัน แล้วก็พุดดิ้งสองชิ้นกับเครื่องดื่มกระป๋อง... โอ๊ะ... ถ้างั้นฉันว่ามื้อเย็นเป็นแอปเปิลลูกเดียวก็แล้วกัน...",
  str_voice_1601231_3 = "หืม นี่น่ะเหรอ? เครื่องแบบเจ้าหน้าที่พิทักษ์กฎของอิลลูมินาไงล่ะ! มีแต่ผู้ที่ผ่านการสอบฝึกงานเท่านั้นที่มีสิทธิ์ใส่ชุดนี้! แต่... นายจะเลิกจ้องฉันสักทีได้มั้ย!",
  str_voice_1601231_4 = "ระเบียบของเจ้าหน้าที่พิทักษ์กฎ — กฎข้อที่หนึ่ง! ดูแลความปลอดภัยของผู้คนและป้องกันเหตุคุกคามความสงบเรียบร้อย กระบองนี่ไม่ใช่แค่เครื่องประดับเอาไว้ถือเล่นนะ!",
  str_voice_1601231_5 = "ระเบียบของเจ้าหน้าที่พิทักษ์กฎ — กฎข้อที่สอง! ดูแลความเรียบร้อยบนท้องถนนและจัดการกับอุบัติเหตุจราจรทั้งหมด... เอ่อ... กฎจราจรของโคลอสซัสเหรอ? โทษทีนะ ฉันว่าฉันไม่เคยเรียนกฎพวกนั้นเลย...",
  str_voice_1601231_6 = "จรรยาบรรณของเจ้าหน้าที่พิทักษ์กฎ — กฎข้อที่สาม! เมื่อปฏิบัติภารกิจ จงเคารพและปกป้องศักดิ์ศรีของทุกคน... แน่นอนว่าไม่นับอิคลิพไซท์นะ!",
  str_voice_1601231_7 = "เจ้าหน้าที่พิทักษ์กฎจะต้องช่วยเหลือผู้อื่นและผดุงความยุติธรรม และฉันเองก็ต้องคอยช่วยเหลือและดูแลนาย!",
  str_voice_1601231_8 = "ฉันดีใจจริง ๆ ที่ได้ช่วยนาย... ไม่ใช่เพราะมันเป็นหน้าที่อย่างเดียวหรอกนะ!",
  str_voice_1601231_9 = "ช่วยฉันทำภารกิจช่วยเหลือผู้คนในวันนี้ทีสิ! ฉันยังต้องช่วยคนอีกหนึ่งคน... บอกมาเลยว่าต้องการอะไร ตั้งใจคิดให้ดีล่ะ ผู้นำทาง!",
  str_voice_1601231_10 = "เฮ้ เรียกฉันมาแต่ไม่มีอะไรให้ทำเนี่ยนะ! การรอคอยก็คงเป็นส่วนหนึ่งของงานสินะ... เจ้าหน้าที่พิทักษ์กฎคอร์ดี้ เตรียมรอรับคำสั่งอย่างเป็นทางการแล้ว!",
  str_voice_1601231_11 = "ฉันมาแล้ว! คอร์ดี้ เจ้าหน้าที่พิทักษ์กฎแห่งอิลลูมินา รายงานตัว!",
  str_voice_1601231_12 = "เฮ้... อย่าเพิ่งกวนได้มั้ย งานลาดตระเวนประจำวันเป็นงานที่ฉันไม่อยากทำพังนะ!",
  str_voice_1601231_13 = "วางใจได้ ไม่ว่าจะงานเล็กหรือใหญ่ฉันก็รับมือได้หมด... นายคงไว้ใจฉันสินะ!",
  str_voice_1601231_14 = "อาฮะ ฉันฟังอยู่! ไม่ต้องรีบ ค่อย ๆ เล่ามา",
  str_voice_1601231_15 = "สุขสันต์วันเกิด! ปีนี้นายอธิษฐานขออะไรเหรอ? ฉันจะช่วยให้มันเป็นจริง!",
  str_voice_1601231_16 = "อยากให้ฉันทำอะไรต่อล่ะ ผู้นำทาง? งานของเจ้าหน้าที่พิทักษ์กฎน่ะไม่มีวันหมดหรอกนะ!",
  str_voice_1601231_17 = "อรุณสวัสดิ์ ผู้นำทาง! เมื่อคืนหลับสบายดีมั้ย? ทานข้าวเช้ารึยังเนี่ย? อ้าว!? นอนไม่พองั้นเหรอ...?",
  str_voice_1601231_18 = "สวัสดียามเย็น! วันนี้งานยุ่งจังเลยเนอะ!",
  str_voice_1601231_19 = "ได้เวลาเข้านอนแล้ว ทำไมนายถึง... เดี๋ยวนะ... มีงานฉุกเฉินใช่มั้ย!?",
  str_voice_1601231_20 = "โครงสร้างองค์กรของอิลลูมินานั้นซับซ้อนมาก การรักษาความสงบก็เลยอาจจะลำบากในบางครั้ง",
  str_voice_1601231_21 = "ฉันไม่มีปัญหาอะไรกับอัมบราตันหรอกนะ... เอ่อ ที่จริงก็อาจจะมีปัญหานิดหน่อยแฮะ...",
  str_voice_1601231_22 = "ขออิลลูมินา... จงเจิดจำรัส!",
  str_voice_1601231_23 = "รังแกคนอ่อนแอและก่อความไม่สงบในที่สาธารณะ... เตรียมตัวโดนลงโทษได้เลย!",
  str_voice_1601231_24 = "ถ้าผู้บังคับบัญชาไม่เชื่อมั่นในตัวฉัน ฉันก็คงไม่มีโอกาสได้ทำงานในฝัน",
  str_voice_1601231_25 = "ฉันก็ไม่อยากจะพูดอะไรมาก แต่ฉันชอบบางอย่างในตัวเธอ",
  str_voice_1601231_26 = "ฉันอยากช่วยคนอื่นและคำนวณแคลอรี่ของ... โอ๊ะ ไม่นะ ฉันหมายถึง...! เดี๋ยวก่อน... เมื่อกี้นายไม่ได้ยินใช่มั้ย?",
  str_voice_1601231_27 = "พอแผนการที่วางมาอย่างดีล้มเหลวไม่เป็นท่า มันก็น่าโมโหใช่มั้ยล่ะ?",
  str_voice_1601231_28 = "ว้าว วันนี้ยังไม่ได้ทำความสะอาดแผงควบคุมเลยเหรอ...? แล้วขวดอาหารเสริมของนายก็ถูกทิ้งเลอะเทอะไปหมด... เดี๋ยวฉันจัดการให้เอง ผู้นำทาง!",
  str_voice_1601231_29 = "เจ้าหน้าที่พิทักษ์กฎคอร์กี้แห่งอิลลูมินาพร้อมรับใช้ด้วยรอยยิ้มแล้ว! มีอะไรให้ช่วยมั้ย ผู้นำทาง?",
  str_voice_1601231_30 = "ล-เลื่อนขั้นเหรอ? ที่ฉันตั้งใจทำงานอย่างหนัก นายเห็นคุณค่าของมันสินะ?",
  str_voice_1601231_31 = "น-นายไว้ใจฉันจริง ๆ เหรอ?",
  str_voice_1601231_32 = "ขอบคุณนะที่เชื่อใจฉัน! ฉันจะพยายามให้เต็มที่!",
  str_voice_1601231_33 = "รู้สึกได้ถึงการเติบโตของพลังเลยละ!",
  str_voice_1601231_34 = "ได้เวลาออกรบแล้ว!",
  str_voice_1601231_35 = "ร-รอฟังคำสั่ง!",
  str_voice_1601231_36 = "หวาา... มาแล้ว!",
  str_voice_1601231_37 = "เคารพเจ้าหน้าที่พิทักษ์กฎด้วย!",
  str_voice_1601231_38 = "กระบองนี่ไม่ได้เอาไว้ถือสวย ๆ นะ!",
  str_voice_1601231_39 = "สายฟ้าและเปลวเพลิง!",
  str_voice_1601231_40 = "ได้เวลาปฏิบัติการแล้ว! ภารกิจพิเศษ!",
  str_voice_1601231_41 = "เจ้าหน้าที่พิทักษ์กฎแห่งอิลลูมินา พร้อมนำทางแล้ว!",
  str_voice_1601231_42 = "ภารกิจลุล่วง!",
  str_voice_1601231_43 = "ขอโทษนะ... นึกว่าจะช่วยนายได้แท้ ๆ...",
  str_voice_1601231_44 = "เจ้าหน้าที่พิทักษ์กฎแห่งอิลลูมินา พร้อมและยินดีอย่างยิ่งที่จะรับใช้... หวาา! เจ็บจัง...",
  str_voice_1601231_45 = "ถ้าอยากจะขอบคุณฉันจริง ๆ ก็ส่งจดหมายหาแผนกเจ้าหน้าที่พิทักษ์กฎได้เลย!",
  str_voice_1601231_46 = "หา? ตั้งใจเอามาให้ฉันเหรอ...? รู้เลยว่านายตั้งใจเลือกมาอย่างดี!",
  str_voice_1601231_47 = "น้ำใจของนายมีค่ามากกว่าของขวัญชิ้นไหน ๆ อยู่แล้ว",
  str_voice_1601231_48 = "ขอบคุณนะ ฉันชอบมากเลย!",
  str_voice_1601231_49 = "นายสนใจด้วยเหรอ? คนอื่น ๆ เคยหัวเราะเยาะฉัน... แต่ตอนนี้ฉันไม่สนคนพวกนั้นแล้วละ!",
  str_voice_1601231_50 = "การปกป้องคนอ่อนแอและพิทักษ์ความยุติธรรม... นั่นเป็นความฝันของฉันมาตลอด",
  str_voice_1601231_51 = "ถึงฉันจะได้รับมอบหมายให้ต่อสู้ในสนามรบแห่งใหม่ ฉันก็จะพยายามอย่างดีที่สุด... เหมือนที่ผ่าน ๆ มา",
  str_voice_1601231_52 = "Alchemy Stars!",
  str_voice_1601231_53 = "มีอะไรให้ช่วยมั้ย?",
  str_voice_1601231_54 = "สวัสดียามเช้าจากเจ้าหน้าที่พิทักษ์กฎแห่งอิลลูมินา!",
  str_voice_1601231_55 = "สวัสดียามบ่าย มีปัญหาอะไรกวนใจนายรึเปล่า?",
  str_voice_1601231_56 = "ราตรีสวัสดิ์ นายควรได้พักผ่อนนะ",
  str_voice_1601231_57 = "สุขสันต์วันปีใหม่!",
  str_voice_1500151_1 = "- หากต้องการลงทุนในงานศิลปะของแท้ก็มาหาเราได้ หรือจะเรียกใช้บริการอื่น ๆ เพิ่มเติมเราก็มีให้เลือกมากมาย!\n- เราชาร์จค่าบริการพวกนี้รวมไปกับราคาสินค้าแล้ว...",
  str_voice_1500151_2 = "- ฟุดฟิด ฟุดฟิด... ฉันได้กลิ่น... ไนท์เทียม!",
  str_voice_1500151_3 = "- พวกเราไม่ใช่คนผลิตงานศิลปะ!\n- เราคือคนขายงานศิลปะต่างหากเล่า!",
  str_voice_1500151_4 = "- ของเก่าน่าเบื่อที่วางอยู่ตรงนี้ขายไม่ได้ราคาหรอก ให้กินสาดสีเติมความเฟี้ยวให้เปียโนของนายหน่อยมั้ย?\n- ฉันว่าเขาไม่ได้จะขายมันนะ...",
  str_voice_1500151_5 = "- มีแต่คนที่เข้าใจศิลปะอย่างแท้จริงเท่านั้นที่จะเห็นคุณค่าของภาพวาดเก่าแก่พวกนี้ เอาละ... นายชอบรูปไหนล่ะ?\n- แล้วคนแถวนี้เค้าไม่ได้จะมาซื้อเหมือนกัน",
  str_voice_1500151_6 = "- เสื้อผ้าชุดเดิมทุกวัน... ทรงผมดาด ๆ... อยากได้เคล็ดลับการแต่งผมรึเปล่า?",
  str_voice_1500151_7 = "- ในบางครั้ง ไอเดียที่ซับซ้อนและยิ่งใหญ่ก็ต้องแสดงออกในรูปแบบที่เรียบง่ายและตรงไปตรงมากว่านี้...\n- เอาละ เดี๋ยวเรากินอะไรกันดีล่ะ?",
  str_voice_1500151_8 = "- จะเกิดอะไรขึ้นถ้าเราส่งของตามออเดอร์ไม่สำเร็จ? นั่นเป็นความลับทางการค้าของเราเลยนะ! ฉันพูดได้แค่ว่า กินเป็นคนที่ทำของเลียนแบบได้เก่งมาก...\n- นั่นก็คือพูดมาหมดแล้วไม่ใช่หรือไง...",
  str_voice_1500151_9 = "- อมยิ้มที่เดินกลางหิมะมานานเรียกว่าอะไร? ไอติมหวานเย็นไงล่ะ... ไม่ตลกเหรอ? นึกว่ามุกนี้จะใช้ขึ้นเวทีได้แล้วเชียว...",
  str_voice_1500151_10 = "- ถ้านายอยู่นิ่ง ๆ ให้นานกว่านี้อีกนิด...\n- ภาพวาดพวกนี้มันขายตัวมันเองไม่ได้นี่นา...",
  str_voice_1500151_11 = "- กำลังมองหาโอกาสธุรกิจครั้งใหม่อยู่เลย!",
  str_voice_1500151_12 = "- ฮัดเช่ย... กินลืมปิดฝาเจลแต่งผมทุกทีเลยสิน่า...",
  str_voice_1500151_13 = "- อย่ามองเราแบบนั้นสิ งานทหารรับจ้างพวกเราก็รับไหว มีเท่าไหร่ก็ส่งมาได้เลย",
  str_voice_1500151_14 = "- การรู้ภาษาอื่นก็เป็นทักษะที่มีประโยชน์กับจิตรกรระดับโลกนะ... เมี้ยว หา? มุกนี้ก็ยังไม่ผ่านเหรอ?",
  str_voice_1500151_15 = "- สุขสันต์วันเกิด! ไม่ลองชวนเพื่อนคนรวยของนายมาทานมื้อค่ำฉลองวันเกิดด้วยกันล่ะ?\n- แต่ต้องมีเพื่อนก่อนนะ",
  str_voice_1500151_16 = "- อมยิ้มเปปเปอร์มินต์นี่สดชื่นจริง ๆ แถมยังดีต่อสุขภาพด้วย อยากลองมั้ย?",
  str_voice_1500151_17 = "- เดี๋ยว เดี๋ยวก่อน! อย่าเพิ่งมองฉัน! เจลแต่งผมของฉันอยู่ไหน!?",
  str_voice_1500151_18 = "- เดินเล่นกันเถอะ!\n- ...เขาตามไม่ทันแฮะ เราวิ่งเร็วไปงั้นเหรอ?",
  str_voice_1500151_19 = "- อ่า... ธรรมชาติของหมาก็ต้องนอนตอนกลางคืนอยู่แล้ว",
  str_voice_1500151_20 = "- เราชอบทำงานกันเองมากกว่า กิลด์พวกนั้นเรื่องมาก... แถมยังหักค่านายหน้าโหดอีก",
  str_voice_1500151_21 = "- ไม่ว่าจะเป็นเศรษฐีใหม่หรือขุนนางเสแสร้ง สุนทรียะทางศิลปะของคนพวกนั้นก็ซ้ำซากเหมือน ๆ กันหมด",
  str_voice_1500151_22 = "เงามืดจะคอยเฝ้ามองเจ้า...\nรวมถึงโอกาสทางธุรกิจด้วย!",
  str_voice_1500151_23 = "- พวกป่าเถื่อนชั้นต่ำไร้รสนิยม...\n- พวกมันเกิดมาเพื่อถูกใช้เป็นเครื่องมือเท่านั้นแหละ",
  str_voice_1500151_24 = "- อีสต์วาน... จะเรียกว่าเขาเป็นผู้อบรมสั่งสอนเราก็ได้",
  str_voice_1500151_25 = "- ฉันไม่นึกไม่ฝันเลยว่าหญิงสูงศักดิ์สง่างามแบบนั้นจะช่วยพวกเรา!",
  str_voice_1500151_26 = "- สอง สาม สี่ ห้า หก เจ็ด... การนับเลขศูนย์ในบัญชีนี่ยังไงก็ไม่เบื่อ!",
  str_voice_1500151_27 = "- ฉันเกลียดการรับออเดอร์จากทะเลทรายเรดีเซลจริง ๆ... ตอนกลางวันก็ร้อนระอุ ตอนกลางคืนก็หนาวจับใจ",
  str_voice_1500151_28 = "- ดีไซน์ของผนังนี่ทำให้ตาของเราเห็นเหมือนกับว่าพื้นที่มันกว้างขึ้น... หา? ที่จริงมันคือห้องอีกห้องงั้นเหรอ!",
  str_voice_1500151_29 = "- ฮาชิ!\n- กิน\n- พวกเราคือนายหน้าขายงานศิลปะผู้มากพรสวรรค์และทหารรับจ้างพาร์ทไทม์!\n- นายจะพูดว่า \"ทหารรับจ้างผู้มากพรสวรรค์และนายหน้าขายงานศิลปะพาร์ทไทม์\" รึเปล่านะ...",
  str_voice_1500151_30 = "อาวุธของเราดูเหมือนจะแข็งแกร่งขึ้นอยู่ตลอดเวลาเลย!",
  str_voice_1500151_31 = "- มีแรงบันดาลใจขึ้นมาเลยละ!",
  str_voice_1500151_32 = "- ผู้รู้ตัวจริง!",
  str_voice_1500151_33 = "- คุณช่างมีรสนิยมจริง ๆ!",
  str_voice_1500151_34 = "- ยืนยันออเดอร์!",
  str_voice_1500151_35 = "- โหลดกระสุน!",
  str_voice_1500151_36 = "- ฉันเห็นแกแล้ว",
  str_voice_1500151_37 = "- เจอนี่หน่อย!",
  str_voice_1500151_38 = "- เตรียมตัวตาย!",
  str_voice_1500151_39 = "- ไม่เป็นศิลปะเอาซะเลย...",
  str_voice_1500151_40 = "- นี่ละคือความงาม!",
  str_voice_1500151_41 = "- ตราบใดที่เราได้ร่วมมือกันก็ไม่มีปัญหา!",
  str_voice_1500151_42 = "- เอาเลย!\n- ออเดอร์ด่วน ส่งตรงถึงนรก!",
  str_voice_1500151_43 = "- พวกเราหนีไป... เลียแผลก่อนดีกว่า...",
  str_voice_1500151_44 = "- เจ้ายานเก่าลำยักษ์นี่น่าจะขายได้เงินมหาศาลแน่ ๆ!",
  str_voice_1500151_45 = "- ฉันขออมยิ้มเพิ่มดีกว่า",
  str_voice_1500151_46 = "- เป็นรสนิยมที่วิเศษไปเลย!",
  str_voice_1500151_47 = "- ยังไงก็ไม่ดีเท่าได้เกาที่หลังหูหรอก\n- เอาละ มานี่เลย...",
  str_voice_1500151_48 = "- ไม่ต้องคิดเลย เดี๋ยวฉันจะบริการจัดส่งให้เป็นพิเศษเอง!\n- แน่นอนว่าส่งฟรีด้วย",
  str_voice_1500151_49 = "- ทรงผมที่เสยขึ้นสูงเป็นสัญลักษณ์บ่งบอกรสนิยมมาตรฐานสูงสุด! ฉันเพิ่งเสยเพิ่มอีก 3 เซนติเมตร ตอนนี้ฉันสูงเท่ากินแล้วรึยัง? ยังอีกเหรอ!?\n- อีกไกลเลยละ",
  str_voice_1500151_50 = "- ฉันรู้ว่ามันเป็นงานที่ไม่ดี แล้วพรสวรรค์ของกินก็ไม่ได้มีแค่ทำของเลียนแบบหรอกนะ... แต่เราจะหยุดไม่ได้ จนกว่าจะเก็บไนท์เทียมได้มากพอ",
  str_voice_1500151_51 = "- บางครั้งฉันก็ฝันถึงวันเก่า ๆ... ภาพวาดของท้องฟ้าอันงดงาม ผืนผ้าใบที่กางจนสุดผนัง... รูปภาพของพ่อบุญธรรมยังคงชัดเจนในความทรงจำ",
  str_voice_1500151_52 = [[
- Alchemy!
- Stars]],
  str_voice_1500151_53 = "- เฮ้! เรากลับมาแล้ว!",
  str_voice_1500151_54 = "อรุณสวัสดิ์!",
  str_voice_1500151_55 = "- ไปกินข้าวกันเถอะ! อยากกินเนื้อจัง!",
  str_voice_1500151_56 = "- ไปเดินเล่นก่อนนอนกันมั้ย?",
  str_voice_1500151_57 = "- สุขสันต์วันปีใหม่!\n- เอาเถอะ อย่างน้อยก็ขอให้เป็นวันที่มีความสุขนะ",
  str_voice_1601201_1 = "คุณคงอยากรู้เรื่องราวของอัศวินยักษ์ที่อยู่ข้างกายฉันเสมอสินะ จะเรียกเขาว่าปอมเปย์ หรือเรียกว่าอัศวินแห่งแสงสว่างก็ได้",
  str_voice_1601201_2 = "ต้องขอโทษด้วย ฉันไม่ชินเวลาต้องคุยกับคนอื่นน่ะ คุณบอกว่าเราควรทำความรู้จักกันมากกว่านี้ในอนาคตงั้นรึ? ถ้าอย่างนั้นก็ขอความกรุณาด้วย ฉันจะพยายามอย่างเต็มที่",
  str_voice_1601201_3 = "ความสันโดษคือสิ่งที่สมบูรณ์ในตัวมันเอง และทำให้ผู้ยึดถือปฏิบัติต้องเข้มงวดกับตนเองมากขึ้น มีเพียงการอยู่กับตัวเองเท่านั้น ที่ทำให้ฉันได้ล่วงรู้ถึงความปรารถนาในส่วนลึกสุดของจิตใจ",
  str_voice_1601201_4 = "โลกภายนอกลูโมโพลิส... ฉันเคยอ่านเรื่องราวมากมายจากหนังสือหลายเล่ม และสักวันหนึ่งฉันอาจจะได้ออกไปเห็นมันด้วยตาตัวเอง",
  str_voice_1601201_5 = "ตราบใดที่เราพยายาม ก็ไม่มีหนังสือเล่มไหนที่อ่านไม่ออก คุณเข้าใจไหม? สิ่งที่ยากที่สุดก็คือการเข้าใจในตนเอง",
  str_voice_1601201_6 = "แสดงว่าคุณเคยอยู่ตัวคนเดียวมาก่อน... แล้วทำไมหลังจากนั้นคุณถึงมีเพื่อนมากมายขนาดนี้ล่ะ? อย่าเพิ่งเข้าใจผิด ฉันก็แค่สงสัยน่ะ",
  str_voice_1601201_7 = "เมื่อได้มองฝูงชนเหล่านั้นจากเบื้องบน คุณก็จะเข้าใจว่าพวกเขาไม่ได้สนใจกับความสุขและความเศร้าของกันและกันเลยแม้แต่น้อย",
  str_voice_1601201_8 = "คุณควรอ่านเอกสารการศึกษาประวัติศาสตร์ของลูโมโพลิสให้มากกว่านี้นะ เพราะว่า... เราจะได้มีเรื่องคุยกันมากขึ้นไง",
  str_voice_1601201_9 = "ฉันเคยอ่านจากหนังสือว่าคนที่ช่วยเหลือซึ่งกันและกันเขาเรียกว่า \"เพื่อน\" แล้วคุณจะช่วยฉันไหม? แน่นอน... ถ้าคุณอยากให้ช่วย ฉันก็จะช่วยคุณเหมือนกัน",
  str_voice_1601201_10 = "ฉันรู้ว่าการอยู่ในห้องคนเดียวนาน ๆ หลายชั่วโมงมันน่าเบื่อแค่ไหน เวลาฉันเบื่อ ฉันก็จะขอให้ปอมเปย์พาขึ้นไปบนหลังคาเพื่อมองท้องฟ้าและก้อนเมฆ",
  str_voice_1601201_11 = "ช่างเป็นที่ที่เงียบสงบอะไรขนาดนี้ ฉันขออยู่ที่นี่ได้มั้ย? ขอบใจ อย่าพาคนอื่นมาล่ะ",
  str_voice_1601201_12 = "ขอเทิดทูนรัตติกาลสีขาว ฉันรู้ว่าศรัทธาแห่งลูโมโพลิสจะช่วยพวกเราชาวออโรเรียน.. และเคเลสไทต์",
  str_voice_1601201_13 = "การรวบรวมหนังสือที่สาบสูญก็เหมือนการต่อจิ๊กซอว์นั่นแหละ สำหรับฉันแล้วมันก็คือเกมอย่างหนึ่ง",
  str_voice_1601201_14 = "ได้เวลาลงน้ำมันให้ปอมเปย์แล้ว อืมม... ขัดเงานิดหน่อยด้วยก็ดี",
  str_voice_1601201_15 = "เอ่อ... ฉันคงไม่ไปงานปาร์ตี้วันเกิดของคุณ แต่ก็สุขสันต์วันเกิดล่วงหน้านะ",
  str_voice_1601201_16 = "ฉันเจอบทความที่วิเศษมาก ๆ เลย! มันเป็นเรื่องเกี่ยวกับ... โอ๊ะ คุณคงไม่สนใจเรื่องพวกนั้นสินะ",
  str_voice_1601201_17 = "ช่วงนี้ของวันเป็นเวลาที่เมฆบนท้องฟ้าสวยที่สุด อยากออกไปดูหน่อยไหม?",
  str_voice_1601201_18 = "อะไรนะ? ปกติแล้วมื้อเย็นของคุณมีแค่สามเมนูเองรึ? จินตนาการไม่ออกเลยว่ามันจะเป็นยังไง...",
  str_voice_1601201_19 = "สมัยก่อนฉันเองก็อ่านหนังสือติดพันจนลืมนอนเหมือนกัน วันนี้สบายดีไหม?",
  str_voice_1601201_20 = "ศูนย์กลางของโลก จุดสูงสุดของอารยธรรมออโรเรียน... เป็นสถานที่ที่เหมาะกับการใช้ชีวิตของฉันที่สุดแล้ว",
  str_voice_1601201_21 = "ในแดนเหนืออันห่างไกล ภายใต้ท้องฟ้าที่สว่างไสวไปด้วยแสงออโรรา... ทายาทแห่งแสงสว่างจะยังอาศัยอยู่ที่นั่นรึเปล่านะ ใครจะรู้ล่ะ?",
  str_voice_1601201_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1601201_23 = "เจ้าพวกอัปลักษณ์แสนโสมมนั่นน่ะเหรอ แน่นอน ฉันรู้ว่าพวกมันคืออะไร สิ่งมีชีวิตพวกนั้นไม่สมควรมีตัวตนอยู่บนโลกใบนี้",
  str_voice_1601201_24 = "ลอร์ดชวาตส์ เจ้าเมืองผู้นำพาลูโมโพลิสไปข้างหน้าบนหนทางแห่งความเที่ยงธรรม เขาเป็นคนที่ฉันเคารพเทิดทูนที่สุดบนโลกใบนี้",
  str_voice_1601201_25 = "แน่นอน ฉันรู้จักองค์หญิงคาร์ลีน อย่างไรเธอก็เป็นคนรุ่นราวคราวเดียวกับฉันเพียงไม่กี่คนที่มีฐานะใกล้เคียงกัน",
  str_voice_1601201_26 = "ฉันชอบการอ่าน ฉันอ่านได้ทั้งหนังสือ สิ่งของ... หรือแม้แต่ออโรเรียน",
  str_voice_1601201_27 = "กิจกรรมกลุ่มงั้นเหรอ? ฉันไม่เคยลองมาก่อนเลย... น่าจะเพราะฉันไม่ชอบสุงสิงกับคนอื่นเป็นนิสัยอยู่แล้วด้วยละมั้ง",
  str_voice_1601201_28 = "ฉันรู้ว่ามีสิ่งนี้อยู่บนโลก แต่ไม่นึกเลยว่ามันจะตัวใหญ่กว่าปอมเปย์",
  str_voice_1601201_29 = "ฉันจะสืบสานตำนานของอัศวินแห่งแสงสว่างต่อไป... โอ้ คุณคือเคเลสไทต์สินะ ขอเทิดทูนรัตติกาลสีขาว ฉัน เฮดี้ ไบรท์ ขอกล่าวคำทักทายด้วยใจจริง",
  str_voice_1601201_30 = "ฉันไม่รู้เลยว่าตัวเองมีพลังขนาดนี้... เธอทำแบบนั้นได้ยังไง?",
  str_voice_1601201_31 = "ฉันไปต่อ ได้ไกลขึ้นอีกนิดแล้ว",
  str_voice_1601201_32 = "ฉันมองเห็น... เส้นทางของอัศวินแห่งแสงสว่าง",
  str_voice_1601201_33 = "ฉัน จะเปลี่ยนอนาคตให้จงได้",
  str_voice_1601201_34 = "หืมม? ได้สิ ตามที่คุณต้องการเลย",
  str_voice_1601201_35 = "มาเริ่มกันเถอะ",
  str_voice_1601201_36 = "ในที่สุดก็ถึงคราวของฉัน",
  str_voice_1601201_37 = "อัศวินแห่งแสงสว่าง จงปรากฏกาย!",
  str_voice_1601201_38 = "ความมืดไม่อาจหนีพ้นโทษทัณฑ์!",
  str_voice_1601201_39 = "ปอมเปย์ จงอยู่ข้างฉัน!",
  str_voice_1601201_40 = "สัมผัสกับแสงสว่างอันทรงเกียรติ!",
  str_voice_1601201_41 = "ฉันจะจบมันโดยเร็ว",
  str_voice_1601201_42 = "สำหรับอัศวินแห่งแสงสว่าง นี่เป็นเรื่องเล็กน้อยเท่านั้น",
  str_voice_1601201_43 = "ช่างเป็นการต่อสู้ที่น่าอับอายซะจริง ๆ... ฉันไม่ยอมรับเด็ดขาด!",
  str_voice_1601201_44 = "อืมม... เราจะต้องคิดใคร่ครวญเรื่องนี้กันอย่างถี่ถ้วน",
  str_voice_1601201_45 = "นี่อะไรน่ะ...? แน่นอน ฉันรู้ว่ามันคือของขวัญ!",
  str_voice_1601201_46 = "อืมม... ขอบคุณที่ลำบากนะ",
  str_voice_1601201_47 = "นี่จำเป็นต้องมาให้กันต่อหน้าเลยเหรอ? เปล่า ไม่มีอะไรหรอกนะ...",
  str_voice_1601201_48 = "รู้มั้ย... ฉันชอบของขวัญชิ้นนี้พอตัวเลยละ!",
  str_voice_1601201_49 = "บางครั้งความสุขก็ทำให้คนเราตาบอด ฉันเคยคิดว่าทุกคนมีคุณครูส่วนตัว... แล้วฉันก็คิดว่าทุกคนจะเคยชินกับการอยู่ตัวคนเดียว",
  str_voice_1601201_50 = "ปีศาจในความฝันของฉัน เขี้ยวและกรงเล็บอันแหลมคมของพวกมัน... พวกมันเหมือนจริงและน่ากลัวจนแทบจะกลืนกินวิญญาณของฉันไปจนหมด... มีเพียงหนังสือเท่านั้นที่มีพลังพอจะช่วยฉันได้",
  str_voice_1601201_51 = "ฉันฝันร้ายเรื่องนั้นอีกแล้ว แต่คราวนี้ มีอัศวินสวมเกราะสีขาวปรากฏตัวออกมาจากแสงสว่างและขับไล่ความมืดที่อยู่เบื้องหน้า",
  str_voice_1601201_52 = "Alchemy Stars",
  str_voice_1601201_53 = "ฉันรู้...",
  str_voice_1601201_54 = "อรุณสวัสดิ์",
  str_voice_1601201_55 = "ฉันขอให้คุณมีวันที่ดี",
  str_voice_1601201_56 = "ราตรีสวัสดิ์",
  str_voice_1601201_57 = "ในโอกาสปีใหม่นี้ ขอความสงบจงบังเกิดกับคุณ",
  str_voice_1601311_1 = "การใช้ชีวิตโดยปราศจากพิธีกรรมนั้นไม่ต่างจากการเดินทางในค่ำคืนอันมืดมิดโดยไร้แสงดาว... มันจะน่าเบื่อแค่ไหนกันนะ?",
  str_voice_1601311_2 = "ชู่ว… ถ้าทำเสียงดังเกินไป เจ้ากระต่ายข้าง ๆ ผมจะตกใจกลัวนะ",
  str_voice_1601311_3 = "หน้ากระดาษแห่งประวัติศาสตร์มีทั้งความรู้ที่แท้จริงเกี่ยวกับเหตุการณ์ในอดีตและสิ่งที่จะเกิดขึ้นในอนาคต",
  str_voice_1601311_4 = "ถึงทุกวันจะเป็นเหมือนเดิม แต่มันก็ไม่ใช่ว่าจะแย่เสมอไปนี่ คุณต้องรู้ว่ามีเพื่อนร่วมชาติของเรามากมายสละชีวิตเพื่อให้ลูกหลานของเรามีอนาคตที่มั่นคง",
  str_voice_1601311_5 = "โอ๊ะ? มีสมาชิกใหม่ในครอบครัวกระต่ายรึเปล่านะ...? อดทนรอและทำตัวดี ๆ หน่อยนะ เจ้ากระต่ายน้อย ฉันจะเตรียมแคร์รอตหวาน ๆ ให้ทุกคนเดี๋ยวนี้ล่ะ",
  str_voice_1601311_6 = "พลังอันยิ่งใหญ่มาพร้อมความรับผิดชอบที่ยิ่งใหญ่ ผมจะไม่หนีความรับผิดชอบหรือลืมความตั้งใจแต่แรกเริ่ม ความปรารถนาที่จะปกป้องนอร์ธแลนด์ของผมนับวันมีแต่จะเพิ่มพูน",
  str_voice_1601311_7 = "ไม่ต้องเกรงใจขนาดนั้นหรอกครับ ถ้าสงสัยเรื่องอะไรก็ถามผมได้ แล้วผมจะพยายามอย่างเต็มที่เพื่อมอบคำตอบที่น่าพึงพอใจ",
  str_voice_1601311_8 = "ในบางครั้ง นิสัยดี ๆ ของคุณก็ทำให้ผมนึกถึงสหายเก่าที่ไม่ได้พบมาเนิ่นนาน... ผมอยากจะเจอเธออีกครั้งจริง ๆ",
  str_voice_1601311_9 = "การสร้างนิสัยเฉลิมฉลองพิธีการนั้นทำได้ไม่ยาก อย่างเช่น... เราสามารถกำหนดให้วันที่เราเจอกันเป็นโอกาสครบรอบการเป็นเพื่อน",
  str_voice_1601311_10 = "เบื่อหรือเปล่า? ผมเล่าประวัติศาสตร์ของนอร์ธแลนด์ได้นะ นั่นอาจจะมอบความสนุกให้คุณได้สักพัก",
  str_voice_1601311_11 = "โอ๊ะ? การนัดหมายที่เปี่ยมไปด้วยความรู้สึกของพิธีการงั้นรึ ฮะฮะ ผมยินดีช่วยคุณนะ",
  str_voice_1601311_12 = "บางครั้งผมก็ได้ยินขุนเขาและแม่น้ำพูดคุยกับผม เสียงของพวกเขาเนิบช้า แต่น่าหลงใหล",
  str_voice_1601311_13 = "ระวังให้ดีล่ะ แม้แต่กระต่ายขนปุยเหล่านี้ก็กัดคุณได้ถ้าพวกมันโมโห",
  str_voice_1601311_14 = "ทุกคืนวันอันปกติสุขล้วนเป็นสิ่งที่ควรค่าแก่การจดจำ",
  str_voice_1601311_15 = "ผมมีคาถาโบราณมาฝากคุณในวันนี้โดยเฉพาะ—สุขสันต์วันเกิด!",
  str_voice_1601311_16 = "ใช่แล้ว ไม่มีอะไรเกิดขึ้น นี่ล่ะคือความสุขที่เรียบง่ายที่สุด ไม่คิดอย่างนั้นรึ?",
  str_voice_1601311_17 = "ยืดเส้นยืดสายแล้วหายใจลึก ๆ... เราสามารถเริ่มวันอันงดงามได้ด้วยพิธีการที่ง่ายที่สุด",
  str_voice_1601311_18 = "คุณทำงานเสร็จหรือยัง? ผมช่วยจัดพิธีเพื่อชำระดวงวิญญาณของคุณได้นะ?",
  str_voice_1601311_19 = "โอ้... นี่ก็ดึกแล้ว แต่ทำไมคุณยังไม่นอนอีกล่ะ? หรือคุณกำลังทำพิธีกรรมต้องห้ามอยู่?",
  str_voice_1601311_20 = "ผมนึกขอบคุณอย่างสุดใจเสมอ สำหรับทุกวันที่ได้ใช้ชีวิตในดินแดนสีขาวบริสุทธิ์แห่งนี้",
  str_voice_1601311_21 = "ทั้งอิลลูมินาและลูโมโพลิสก็มีวิธีเอาตัวรอดของพวกเขาเอง",
  str_voice_1601311_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1601311_23 = "พวกมันเป็นสิ่งมีชีวิตน่าสมเพชที่ใช้แต่พละกำลัง และไม่สามารถคิดเองได้",
  str_voice_1601311_24 = "ผู้คนมองเห็นแต่ด้านที่แข็งแกร่งขององค์ราชินี แต่ไม่มีใครรู้ว่าเธอต้องยอมสละสิ่งใดบ้างเพื่อปกป้องนอร์ธแลนด์...",
  str_voice_1601311_25 = "นิคินิสเป็นผู้ที่เคารพในตัวขององค์ราชินีอย่างหมดใจไร้ข้อกังขา",
  str_voice_1601311_26 = "ใช่แล้ว... เพราะผมเติบโตในดินแดนที่มีแต่หิมะ ผมจึงเห็นคุณค่าของแสงแดดอันอบอุ่นยิ่งกว่าเดิม",
  str_voice_1601311_27 = "ฮ่าฮ่า อย่าให้ผมได้ยินใครพูดจาไม่ดีถึงองค์ราชินีเชียวนะ",
  str_voice_1601311_28 = "วัตถุขนาดยักษ์ที่ปรากฏในบันทึกทางประวัติศาสตร์ ผมไม่นึกว่าจะได้เห็นของจริงในช่วงชีวิตของตัวเอง",
  str_voice_1601311_29 = "ผมชื่อโนวิโอ ประชาชนแห่งนอร์ธแลนด์ และผมรอคอยคุณมาเป็นเวลานานแล้ว วันนี้อากาศดีมาก ๆ หรือชะตากรรมจะเตรียมตัวต้อนรับการมาถึงของคุณกันนะ?",
  str_voice_1601311_30 = "โอ้? ช่างอบอุ่นจริง ๆ...",
  str_voice_1601311_31 = "เปลวเพลิงแห่งการเยียวยาลุกโชนในใจของฉัน",
  str_voice_1601311_32 = "ประวัติศาสตร์... กำลังอุบัติขึ้นเบื้องหน้าเรา",
  str_voice_1601311_33 = "ช่างเป็นการเติบโตที่น่ารำลึกถึง!",
  str_voice_1601311_34 = "ไปกันเถอะ",
  str_voice_1601311_35 = "ผมพร้อมแล้ว",
  str_voice_1601311_36 = "ผมกำลังรออยู่",
  str_voice_1601311_37 = "ผมต้องการความรู้สึกของพิธีกรรม",
  str_voice_1601311_38 = "คทาแห่งปฐพี โปรดจงมอบพละกำลัง!",
  str_voice_1601311_39 = "ผมอยู่ตรงนี้เสมอ",
  str_voice_1601311_40 = "จงอย่ากลัว",
  str_voice_1601311_41 = "ด้วยความยินดี",
  str_voice_1601311_42 = "ช่างเป็นพิธีที่สมบูรณ์แบบ!",
  str_voice_1601311_43 = "บทแห่งความเสียใจที่ไม่อาจแก้ไขได้...",
  str_voice_1601311_44 = "ผมต้องเรียนรู้ประวัติศาสตร์ของที่นี่เพิ่มเติม",
  str_voice_1601311_45 = "ด้วยความยินดี",
  str_voice_1601311_46 = "ขออภัยที่ทำให้ลำบาก",
  str_voice_1601311_47 = "คุณเตรียมการมานานเลยสินะ?",
  str_voice_1601311_48 = "ผมต้องคิดให้ดีแล้วล่ะ ว่าจะให้อะไรตอบแทน",
  str_voice_1601311_49 = "นอร์ธแลนด์ไม่เคยเปลี่ยนแปลงตั้งแต่วันนั้น ทุกคนนอกจากผมเชื่อว่าผมคือ \"จิตวิญญาณแห่งขุนเขา\"...",
  str_voice_1601311_50 = "เราจะปกป้องคนสำคัญของเราและผืนดินอันสงบสุขนี้ได้อย่างไร? ผมเฝ้าหาคำตอบของคำถามนี้มาเนิ่นนานหลายปีแล้ว",
  str_voice_1601311_51 = "ช่วงเวลาแห่งความสงบนี้เป็นของขวัญล้ำค่าที่สุดสำหรับผม ผมคิดว่าผมรู้วิธีปกป้องนอร์ธแลนด์แล้ว",
  str_voice_1601311_52 = "Alchemy Stars",
  str_voice_1601311_53 = "โอ้?",
  str_voice_1601311_54 = "อา ช่างเป็นเช้าที่แสนวิเศษ",
  str_voice_1601311_55 = "รู้สึกเหนื่อยงั้นรึ?",
  str_voice_1601311_56 = "ถ้าอย่างนั้นก็ราตรีสวัสดิ์",
  str_voice_1601311_57 = "ขอให้คุณพบเจอกับปีที่มีความสุขและแสนสงบ",
  str_voice_1501321_1 = "หืม ชอบรอยที่คอของฉันเหรอ? อย่าจับมันนะ ไม่อย่างนั้นจะโดนฟ้าผ่า! ฮ่า ๆ ๆ คุณเชื่อเหรอ?",
  str_voice_1501321_2 = "ลุ ลา ลา ลุ ลา... ฮิ ๆ คุณชอบเพลงที่ฉันร้องไหม? ต้องกินของหวานนะ เสียงจะได้เพราะ ๆ!",
  str_voice_1501321_3 = "อ้วนก็ดีนะ ฉันไม่เห็นว่ามันมีปัญหาอะไรเลย ฉันก็อ้วนเหมือนกันแต่ก็มีความสุขทุกวัน",
  str_voice_1501321_4 = "ไม่ว่าจะสุขหรือทุกข์คุณก็ยังต้องอยู่ต่อไป แล้วจะทำให้ตัวเองทุกข์ใจไปทำไม? ถูกไหมคนแปลกหน้า?",
  str_voice_1501321_5 = "คนแปลกหน้า ทำไมคุณถึงใช้ลูมินาติกส์ไม่ได้? แล้วทำไมถึงสั่งคนอื่นได้? ช่วยบอกฉันหน่อยเถอะ! นะ ๆ ๆ ฉันสงสัยจนหัวจะระเบิดแล้ว",
  str_voice_1501321_6 = "มันเป็นความจริงที่โหดร้ายของชีวิตที่ต้องลดเวลานอนและเล่นเมื่อคุณโตขึ้น แต่นั่นก็หมายถึงขนมที่มากขึ้นเช่นกัน!",
  str_voice_1501321_7 = "คุณนี่รสนิยมดีจังนะคนแปลกหน้า! ฉันชอบชุดสีแดงที่ฉันใส่!",
  str_voice_1501321_8 = "ชู่ จะบอกความลับให้นะ... ฉันกินเวลาหลับ กินอะไรน่ะเหรอ? ฮิ ๆ นั่นเป็นความลับอีกอย่าง!",
  str_voice_1501321_9 = "ฉันทำเค้กน้ำผึ้งที่เต็มไปด้วยความรักให้คุณ คนแปลกหน้า! เอ๊ะ! เดี๋ยวนะ มันหายไปแล้ว... ฉันกินไปเหรอ?",
  str_voice_1501321_10 = "ฝันกลางวันอยู่เหรอ คนแปลกหน้า? มาร้องเพลงกับฉันไหม? อะแฮ่ม... ลา ลา ลา ลา ลา ลา...!",
  str_voice_1501321_11 = "วิเศษมาก ฉันไม่เคยมาที่นี่เลย! ฉันมองไปรอบ ๆ ได้ใช่มั้ย? ใช่มั้ย?",
  str_voice_1501321_12 = "นอร์ธแลนด์ส่วนใหญ่อากาศหนาวมาก จะป้องกันความหนาวเย็นได้ยังไงถ้าไม่มีขนม?",
  str_voice_1501321_13 = "อย่าเห็นฉันเป็นแค่ขนมหวาน ฉันมีหน้าที่ปกป้องบ้านเกิดของตัวเองด้วย!",
  str_voice_1501321_14 = "ว้าว! ฉันทำลายสถิติ \"ไม่หลับนานที่สุด\" เพราะฉันตื่นเต้นเกินไป!",
  str_voice_1501321_15 = "วันนี้ไม่มีอะไรน่าสนใจเลยยย... ฮิ ล้อเล่น สุขสันต์วันเกิดนะ!",
  str_voice_1501321_16 = "อย่าปล่อยให้ความคิดแบบเดิม ๆ ที่ว่าต้อง \"กินวันละสามมื้อ\" มากวนใจเลย ดูฉันสิ! ฉันกินได้วันละหลายมื้อ!",
  str_voice_1501321_17 = "กลิ่นอะไรน่ะ? อย่าคิดว่าเอาขนมหอม ๆ มายั่วแล้วฉันจะลุกจากเตียงนะ...! ก็ได้ คุณทำสำเร็จ",
  str_voice_1501321_18 = "คุณได้ยินไหม? เตียงนุ่มนิ่มแสนสบายของฉันกำลังเรียกฉันอยู่!",
  str_voice_1501321_19 = "ทำไมยังไม่นอนอีก? นอนบ้างเถอะ ไม่อย่างนั้นคุณจะ... ไม่โตนะ",
  str_voice_1501321_20 = "นอร์ธแลนด์มีน้ำผึ้งที่ดีที่สุดในโลก ดีที่สุด!",
  str_voice_1501321_21 = "ได้ยินว่าพ่อค้าในอัมบราตันจะมุ่งหาเงินโดยไม่คำนึงถึงชีวิต\nของพวกเขา จริงเหรอ?",
  str_voice_1501321_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง แน่นอนอยู่แล้ว!",
  str_voice_1501321_23 = "ถ้าฉันเจออิคลิพไซท์ มันจะเล็งและยิง โดยไม่ถามอะไร!",
  str_voice_1501321_24 = "ราชินีอ่อนโยนมาก เธอช่วยชีวิตฉันและสอนลูมินาติกส์ให้ฉันด้วย",
  str_voice_1501321_25 = "ถึงคุณนิคินิสจะเป็นคนเงียบ ๆ แต่เกมหาคำใบ้ที่ทะเลสาบกระจกเงาของเธอก็เป็นงานที่มีคนมาร่วมสนุกอย่างคึกคักเสมอ!",
  str_voice_1501321_26 = "หืม ฉันได้กลิ่นเค้กน้ำผึ้งที่เพิ่งออกจากเตา!",
  str_voice_1501321_27 = "ฉันจะไม่ออกจากบ้านถ้าไม่ได้ใส่ชุดสวย ๆ",
  str_voice_1501321_28 = "โคลอสซัสบินได้ไกลมาก ๆ แบบ \"ฟิ้ว\" เลยใช่ไหม? เยี่ยมไปเลย!",
  str_voice_1501321_29 = "สวัสดี คนแปลกหน้า คุณอยากไปเยือนนอร์ธแลนด์รึเปล่า? ฉันนำทางให้คุณได้นะ! เรียกฉันว่าโลล่าก็ได้!",
  str_voice_1501321_30 = "ฉันนอนอิ่มเลย!",
  str_voice_1501321_31 = "หืม ฉันอยากกินอีกแล้ว",
  str_voice_1501321_32 = "เราสามารถไปได้ไกลกว่านี้!",
  str_voice_1501321_33 = "ตอนนี้เราปกป้องนอร์ธแลนด์ได้ดีขึ้นแล้วนะ!",
  str_voice_1501321_34 = "เลือกฉันไม่ผิดหวังหรอก!",
  str_voice_1501321_35 = "มา ฉันนอนอิ่มแล้ว!",
  str_voice_1501321_36 = "เมื่อไรจะถึงตาฉัน?",
  str_voice_1501321_37 = "ตื่นเถิด เวทมนตร์แห่งการหลับใหล!",
  str_voice_1501321_38 = "บานสะพรั่ง กุหลาบขาวป่า!",
  str_voice_1501321_39 = "เจอแล้ว!",
  str_voice_1501321_40 = "หยุดวิ่งเดี๋ยวนี้!",
  str_voice_1501321_41 = "ฮิ ๆ รสนิยมดีนะเนี่ย!",
  str_voice_1501321_42 = "ฮิ ๆ ได้เวลางีบยาว ๆ แล้ว!",
  str_voice_1501321_43 = "เค้กน้ำผึ้งเละหมดเลย...",
  str_voice_1501321_44 = "ฉันนั่งดูได้ทั้งวันเลยแหละ!",
  str_voice_1501321_45 = "ว้าว ให้ฉันเหรอ?",
  str_voice_1501321_46 = "ฮี่ ของโปรด!",
  str_voice_1501321_47 = "นี่มัน... ข้าวหน้าน้ำผึ้งงั้นเหรอ?",
  str_voice_1501321_48 = "หอมมม... คุณรู้ใจฉันที่สุดเลย...",
  str_voice_1501321_49 = "สงสัยฉันจะมีพรสวรรค์ในการนอนมาตั้งแต่เด็ก... อย่าล้อสิ! พ่อแม่บอกว่าฉันได้รับพร ถึงกินอิ่มนอนหลับสบาย!",
  str_voice_1501321_50 = "เพื่อหาน้ำผึ้งหวาน ฉันเดินตามทางเข้าไปในป่าเพียงลำพัง ในป่านั่น ฉันพบพุ่มกุหลาบป่าสีขาวราวกับหิมะ",
  str_voice_1501321_51 = "ในวันปีใหม่ของทุกปี ฉันจะไปเข้าเฝ้าองค์ราชินีในพระราชวังเหมันต์พร้อมกับเมนูพิเศษประจำหมู่บ้าน... ไม่ ไม่ใช่เพราะฉันชอบเที่ยวหรอกนะ!",
  str_voice_1501321_52 = "Alchemy Stars!",
  str_voice_1501321_53 = "ลา ลา ลา!",
  str_voice_1501321_54 = "อรุณ... สวัสดิ์...",
  str_voice_1501321_55 = "โอ๊ะ หอมจัง!",
  str_voice_1501321_56 = "ฉันหลับได้อีกนะ!",
  str_voice_1501321_57 = "ปีใหม่แล้ว ขอให้มีความสุขนะ!",
  str_voice_1601331_1 = "ถูกต้อง ฉันเป็นเมด แต่ไม่ใช่เมดของนาย!",
  str_voice_1601331_2 = "ขี่หลังงั้นเหรอ? ไม่มีทาง หลังของฉันมีไว้เพื่อคุณโคบายาชิเท่านั้น!",
  str_voice_1601331_3 = "น่าเบื่อจริง ๆ...! ไม่มีงานบ้านให้ฉันทำเลยเหรอ?",
  str_voice_1601331_4 = "กลัวฉันเนี่ยนะ? มังกรเป็นเผ่าพันธุ์หายากในโลกนี้หรือไงกัน?",
  str_voice_1601331_5 = "อย่าเข้ามาใกล้ฉันนะ! สัญชาตญาณของฉันบอกฉันว่ามันไม่ชอบนาย",
  str_voice_1601331_6 = "หา ยอมแพ้งั้นเหรอ? แต่ฉันยังไม่หนำใจเลย!",
  str_voice_1601331_7 = "คุณโคบายาชิ?! รอก่อนสิคะ ใช่คุณจริง ๆ ด้วย",
  str_voice_1601331_8 = "ฉันเคยชินกับโลกแบบนี้แล้วล่ะ ถึงจะไม่ได้ดีที่สุด แต่อย่างน้อยก็พอทนได้",
  str_voice_1601331_9 = "ยินดีต้อนรับกลับบ้านค่ะ! อาหารพร้อมแล้ว ทานให้หมดนะ ไม่งั้นฉันโกรธจริง ๆ ด้วย!",
  str_voice_1601331_10 = "หาว... โอ๊ะ ไม่นะ ฉันยังมีงานซักรีดต้องทำอีก...",
  str_voice_1601331_11 = "รับทราบ! ฉันเชี่ยวชาญเรื่องงานบ้านอยู่แล้ว!",
  str_voice_1601331_12 = "ที่จริงชุดเดรสนี่เป็นเกล็ดของฉันเองล่ะ ก็เลยไม่ต้องเปลี่ยนทุกวัน!",
  str_voice_1601331_13 = "เฮ้อ อยากยืดเส้นยืดสายจังเลย... ไม่ต้องห่วง ฉันไม่พังที่นี่หรอกน่า",
  str_voice_1601331_14 = "หางของฉันอร่อยสุด ๆ เลยนะ! แต่ทำไมคุณโคบายาชิถึงไม่ยอมกินมันซักทีนะ?",
  str_voice_1601331_15 = "เซอร์ไพรส์! ฉันรู้ว่านี่เป็นวันสำคัญของนายนะ!",
  str_voice_1601331_16 = "อยู่นี่เอง! วันนี้มีแผนอะไรมั้ย?",
  str_voice_1601331_17 = "ช่างเป็นวันที่ดีจริง ๆ! แต่เมดจะต้องเริ่มงานแต่เช้าตรู่น่ะนะ!",
  str_voice_1601331_18 = "เวลาช่างผ่านไปเร็วจริง ๆ...",
  str_voice_1601331_19 = "หวังว่าจะได้ฝันถึงคุณโคบายาชิอีกนะ!",
  str_voice_1601331_20 = "ฉันสามารถเป็นตัวเองได้อย่างเต็มที่ในโลกนี้ เพื่อน ๆ ของฉันจะต้องชอบที่นี่แน่ ๆ!",
  str_voice_1601331_21 = "การต่อสู้และการบาดเจ็บล้มตายที่ไม่สิ้นสุด ไม่ว่าโลกไหนก็น่าสงสารทั้งนั้น",
  str_voice_1601331_22 = "เพื่อคุณโคบายาชิ ฉันจะครองโลกใบนี้ให้ได้!",
  str_voice_1601331_23 = "หา มีเผ่าพันธุ์ที่ต่ำช้าและโอหังกว่ามนุษย์อีกเหรอ?",
  str_voice_1601331_24 = "ฟาฟนีร์? เอ่อ เขาก็เป็นของเขาแบบนั้นแหละ",
  str_voice_1601331_25 = "ชิ แม้แต่เอลมาก็ตามมาที่นี่ด้วยงั้นเหรอ หนีจากเธอไม่พ้นจริง ๆ สินะ...",
  str_voice_1601331_26 = "โชคดีจริง ๆ ที่ฉันแอบเอาผ้าขนหนูของคุณโคบายาชิมาด้วยผืนนึง! มีกลิ่นของเธอด้วย! ขอบคุณนะ!",
  str_voice_1601331_27 = "ฉันเกลียดไข่ที่ไม่มีไข่แดง เพราะมันทำให้เครซัคเพื่อนของฉันต้องตาย!",
  str_voice_1601331_28 = "เขาก็เป็นมังกรเหมือนกันเหรอ? เฮ้ ยังไม่ตายงั้นเหรอ?",
  str_voice_1601331_29 = "ฉันชื่อโทรุ เป็นเมดของคุณโคบายาชิ ขอถามหน่อยสิ คุณรู้มั้ยว่าเจ้านายของฉันอยู่ไหน?",
  str_voice_1601331_30 = "เฮ้ รู้สึกสดชื่นเลยล่ะ!",
  str_voice_1601331_31 = "โฮกก! ฮิฮิ หยอกเล่นน่ะ",
  str_voice_1601331_32 = "อยากเห็นร่างจริงของฉันมั้ยล่ะ?",
  str_voice_1601331_33 = "ฉันได้ยินว่ามีใครรนหาที่งั้นรึ!",
  str_voice_1601331_34 = "เย้! ไปกันเถอะ!",
  str_voice_1601331_35 = "วอร์มอัปเรียบร้อยแล้ว",
  str_voice_1601331_36 = "ร้อนสุด ๆ ไปเลยใช่มั้ยล่ะ?",
  str_voice_1601331_37 = "ไปให้พ้นหน้าฉันได้แล้ว!",
  str_voice_1601331_38 = "จงมอดไหม้ไปกับโลกทั้งใบซะ!",
  str_voice_1601331_39 = "จะหนีทำไมล่ะ?",
  str_voice_1601331_40 = "อีกที! ขออีกที!",
  str_voice_1601331_41 = "ฉันจัดการได้!",
  str_voice_1601331_42 = "ของกล้วย ๆ!",
  str_voice_1601331_43 = "ไม่ เป็นไปไม่ได้...",
  str_voice_1601331_44 = "นี่มันใหญ่กว่าบ้านของคุณโคบายาชิเยอะเลย!",
  str_voice_1601331_45 = "โอ๊ะ ของขวัญเหรอ? ไม่ธรรมดาเลย",
  str_voice_1601331_46 = "โอ้ ยอดเลย!",
  str_voice_1601331_47 = "ขอบคุณ! แต่อย่าหวังว่าฉันจะให้อะไรตอบแทนล่ะ",
  str_voice_1601331_48 = "ใช่แล้ว เพื่อน! ตอนนี้นายเป็นเพื่อนของฉัน!",
  str_voice_1601331_49 = "ฉันอยากออกตามหาวัตถุดิบที่โลกอื่น แต่คงทำพลาดตอนข้ามมิติสินะ",
  str_voice_1601331_50 = "ฉันไม่ได้ต่อสู้มานานแค่ไหนแล้วนะ! อยากกลับมาต่อสู้อีกจังเลย ให้ฉันสู้ด้วยคนนะ!",
  str_voice_1601331_51 = "ฉันว่าฉันได้กลิ่นคันนะ ที่นี่ไม่ใช่โลกที่สงบสุข แล้วฉันก็เป็นห่วงเธอ",
  str_voice_1601331_52 = "Alchemy Stars!",
  str_voice_1601331_53 = "เฮ้!",
  str_voice_1601331_54 = "สวัสดียามเช้า!",
  str_voice_1601331_55 = "ได้เวลาอาหารกลางวันแล้ว!",
  str_voice_1601331_56 = "หาว... ราตรีสวัสดิ์",
  str_voice_1601331_57 = "สุขสันต์วันปีใหม่ คุณโคบายาชิคงจะไม่ทำโอทีวันนี้หรอกนะ จริงมั้ย?",
  str_voice_1601341_1 = "ฉันอยากไปโรงเรียน เพื่อน ๆ ของฉันอยู่ที่นั่น แล้วห้องเรียนก็สนุกมาก ๆ",
  str_voice_1601341_2 = "เหนื่อยจัง... ปิดเครื่องก่อนนะ...",
  str_voice_1601341_3 = "โอ้ โหดร้าย โหดร้ายเหลือเกิน",
  str_voice_1601341_4 = "กินได้รึเปล่าน่ะ? อยากกินจัง",
  str_voice_1601341_5 = "ฉันอยากเล่น! ไปเล่นกันเถอะ!",
  str_voice_1601341_6 = "โทรุบอกว่า ให้อยู่ห่าง ๆ จากคนที่น่ารำคาญ",
  str_voice_1601341_7 = "ผู้คนในโลกนี้น่าสนใจจริง ๆ",
  str_voice_1601341_8 = "วันนี้ก็งานยุ่งอีกแล้วเหรอ? เข้าใจแล้ว",
  str_voice_1601341_9 = "มาเล่นกัน! อย่าหาขออ้างเบี้ยวล่ะ มาเล่นกันนะ!",
  str_voice_1601341_10 = "เจ้ามดตัวน้อยหนึ่งตัว... เจ้ามดตัวน้อยสองตัว...",
  str_voice_1601341_11 = "จะจ้องตาไม่กะพริบเลยล่ะ",
  str_voice_1601341_12 = "ฉันเรียกสายฟ้าได้ ดูสิ ยอดไปเลยใช่มั้ยล่ะ?",
  str_voice_1601341_13 = "หิวจัง... เมื่อไหร่จะได้กินข้าวอีกอะ?",
  str_voice_1601341_14 = "เข้าใจแล้ว เด็กดื้อจะต้องโดนไล่ออกจากบ้าน...",
  str_voice_1601341_15 = "สุขสันต์วันเกิด ฉันขออยู่ด้วยได้มั้ย?",
  str_voice_1601341_16 = "ตารางวันนี้คือเล่นสนุก ที่จริงก็ต้องเล่นสนุกทุกวันล่ะนะ",
  str_voice_1601341_17 = "หวัดดีตอนเช้า หาวว... ง่วงจัง ราตรีสวัสดิ์นะ",
  str_voice_1601341_18 = "มืดจัง ท่านโทรุบอกว่าจะมีแมลงเรืองแสงออกมาตอนกลางคืน อยากจับกินซักตัวจัง มันจะต้องอร่อยแน่ ๆ",
  str_voice_1601341_19 = "พรุ่งนี้จะพาฉันไปเที่ยวไหนเหรอ? รอไม่ไหวแล้วล่ะ!",
  str_voice_1601341_20 = "ทุกคนใจดีแล้วก็อ่อนโยน ใช่ ฉันชอบอยู่กับทุกคน",
  str_voice_1601341_21 = "ขอเป็นเพื่อนกับทุกคนได้มั้ย?",
  str_voice_1601341_22 = "โลกใหม่มีไว้เพื่อยึดครอง",
  str_voice_1601341_23 = "กินไม่ได้ ไม่งั้นปวดท้องแน่",
  str_voice_1601341_24 = "ท่านโทรุดูแลฉัน ฉันชอบท่านโทรุ",
  str_voice_1601341_25 = "คุณโคบายาชิบอกว่าฟาฟนีร์เป็นโอตาคุ โอตาคุคืออะไรเหรอ?",
  str_voice_1601341_26 = "ฉันชอบของสวย ๆ ฉันชอบของน่ารัก",
  str_voice_1601341_27 = "อยู่คนเดียวมันน่าเบื่อ ฉันไม่อยากเบื่อ",
  str_voice_1601341_28 = "มังกรตัวโต! เราจะเป็นเพื่อนกันได้มั้ยนะ?",
  str_voice_1601341_29 = "ฉันชื่อคันนะ ฉันหลงทาง แล้วก็หิวข้าว มีอะไรให้กินมั้ย? ตกลง ฉันจะตามคุณไป",
  str_voice_1601341_30 = "ชาร์จไฟเต็มแล้ว",
  str_voice_1601341_31 = "ฉันใช้พลังมากกว่านี้ได้มั้ย?",
  str_voice_1601341_32 = "ได้เวลาจริงจังแล้ว",
  str_voice_1601341_33 = "เบื่อแล้วล่ะ ไปลงนรกซะ",
  str_voice_1601341_34 = "ฉันจะตั้งใจกว่านี้",
  str_voice_1601341_35 = "พร้อมแล้ว!",
  str_voice_1601341_36 = "ดูสิ ดูสิ",
  str_voice_1601341_37 = "คันนะต้องไม่แพ้",
  str_voice_1601341_38 = "เสียบแทง สังหาร",
  str_voice_1601341_39 = "สายฟ้าจงมา",
  str_voice_1601341_40 = "เปรี้ยงงง!",
  str_voice_1601341_41 = "อย่าซนล่ะทุกคน",
  str_voice_1601341_42 = "ทำได้ดีมาก ทุกคน",
  str_voice_1601341_43 = "ไม่สนุกเลย...",
  str_voice_1601341_44 = "ฉันกำลังว่าง รอคนมาเล่นด้วยกันอยู่น่ะ",
  str_voice_1601341_45 = "ของขวัญ! ฉันชอบของขวัญ!",
  str_voice_1601341_46 = "โอ้ น่ารักมากเลย!",
  str_voice_1601341_47 = "ขอบคุณนะ! มีอีกไหม?",
  str_voice_1601341_48 = "ชอบมาก ๆ เลย! ทั้งของขวัญแล้วก็คุณด้วย!",
  str_voice_1601341_49 = "หลงทางตอนกลับบ้าน สุดท้ายก็เดินไปจนถึงป่า",
  str_voice_1601341_50 = "ได้เห็นอาหารมากมายที่ไม่เคยเห็น น่าสนใจจริง ๆ",
  str_voice_1601341_51 = "ฉันเจอมังกรบินบนฟ้าด้วยล่ะ รู้สึกคุ้น ๆ ก็เลยตามมา",
  str_voice_1601341_52 = "Alchemy Stars",
  str_voice_1601341_53 = "หวัดดี",
  str_voice_1601341_54 = "สวัสดีตอนเช้า",
  str_voice_1601341_55 = "สวัสดีตอนบ่าย",
  str_voice_1601341_56 = "สวัสดีตอนเย็น",
  str_voice_1601341_57 = "สุขสันต์วันเกิด! ขอพรรึยังน่ะ? ฉันน่ะขอไว้ว่า... ไม่ได้สิ โคบายาชิบอกว่าฉันจะต้องไม่ให้คนอื่นรู้",
  str_voice_1501351_1 = "ใช่แล้ว โทรุเปิดประตูมิติระหว่างโลกต่าง ๆ ได้ แต่ฉันทำไม่ได้ เรามาจากคนละฝ่าย แต่ความแข็งแกร่งของฉันไม่แพ้เธอหรอกนะ!",
  str_voice_1501351_2 = "การปรากฏตัวของมังกรจะรบกวนความสงบของโลกนี้ ฉันจึงต้องรีบกลับบ้านให้เร็วที่สุด... แน่นอนว่าต้องกินข้าวให้อิ่มก่อนนะ",
  str_voice_1501351_3 = "ขนมกรุบกรอบเคี้ยวเพลิน? ข้าวหินทราย? ปูยักษ์เนื้อนุ่ม? ไม่เคยได้ยินชื่อของพวกนั้นเลย เร็วเข้า ขอชิมหน่อยสิ!",
  str_voice_1501351_4 = "เพื่อปรับตัวให้เข้ากับโลกใบนี้ ฉันจะต้องเรียนรู้กฎระเบียบของที่นี่ หรือก็คือฉันต้องหางานทำนั่นแหละ",
  str_voice_1501351_5 = "ฉันเรียนรู้ได้ ฉันใช้เวลาเรียนรู้วิธีจัดการไฟล์ไม่นานเลย... อะไรนะ? นั่นเป็นคำชมใช่ไหม?",
  str_voice_1501351_6 = "ฉันเคยมีชื่อว่ามิโกะเซกะ แต่ฉันไม่ต้องการเครื่องสังเวยหรอกนะ แหล่งพลังของฉันคือกฎระเบียบ แถมเครื่องสังเวยพวกนั้นก็จืดสนิท",
  str_voice_1501351_7 = "อาหารอร่อยๆ อย่างเครปเป็นสิ่งสำคัญที่สุดในกิจวัตรประจำวันของฉัน อยากชิมมั้ย? ลองได้นะ",
  str_voice_1501351_8 = "ฉันเครียดเรื่องงานที่บริษัท แต่ในเมื่อได้มาอยู่นี่แล้ว ฉันควรจะสนุกกับชีวิตในโลกนี้สินะ",
  str_voice_1501351_9 = "เสียสละตัวเองเพื่อเป็นผู้นำคนอื่น... นายคือกำลังหลักของครอบครัวเหมือนคุณโคบายาชิเลย แต่อย่าฝืนตัวเองไปล่ะ ฉันก็เก่งเหมือนกัน",
  str_voice_1501351_10 = "เอ่อ จ้องอะไรน่ะ?",
  str_voice_1501351_11 = "เราต้องทำงานแลกข้าว ถึงจะต้องทำโอทีก็เถอะ",
  str_voice_1501351_12 = "เลือกยากจังเลย! ยาสีฟันรสองุ่นหรือสตรอว์เบอร์รี่ดีนะ...?",
  str_voice_1501351_13 = "ตั้งใจอย่างเต็มที่จนกว่าจะเสร็จงาน! จะว่าไป หาร้านเนื้อย่างกันเถอะ",
  str_voice_1501351_14 = "มองอะไรน่ะ? โอ๊ะ ไม่นะ เขาของฉันโผล่ออกมาอีกแล้ว!",
  str_voice_1501351_15 = "เค้กชิ้นใหญ่จัง! วันนี้วันเกิดนายเหรอ?",
  str_voice_1501351_16 = "ท้องร้องไม่หยุดเลย... พอหิวแล้วเครียดจัง",
  str_voice_1501351_17 = "อาหารเช้าของนายเป็นไงบ้าง? ถ้ากินช้าอาหารจะเย็นหมดนะ",
  str_voice_1501351_18 = "ถึงเวลากลางคืนซักที! ฉันควรเข้านอนแต่หัวค่ำ พรุ่งนี้ยังมีงานอีกน่ะ",
  str_voice_1501351_19 = "ยังไม่นอนอีกเหรอ? นายก็มีงานให้ทำเยอะเหมือนกันสินะ...",
  str_voice_1501351_20 = "กฎระเบียบคือสิ่งสำคัญสำหรับฝ่ายปรองดอง เราจะเข้าไปยุ่งเกี่ยวและทำลายวิถีเก่าก่อนของโลกอื่นไม่ได้",
  str_voice_1501351_21 = "มังกรสาวกของฝ่ายเคออสต้องการแต่จะฆ่าฟันและทำลาย... นายไม่ควรไปยุ่งกับพวกนั้น",
  str_voice_1501351_22 = "พิชิต... เดี๋ยวก่อน ไม่ได้ ต้องเรียกว่าปกป้องโลกใหม่!",
  str_voice_1501351_23 = "อิคลิพไซท์น่ะป่าเถื่อนและชั่วช้าเหมือนมังกรฝ่ายเคออส",
  str_voice_1501351_24 = "โทรุเป็นมังกรที่เอาแต่ใจ เพี้ยนแล้วก็ชอบทำอะไรไม่ยั้งคิด... แต่นั่นก็เป็นเหตุผลที่ฉันอิจฉาเธอ",
  str_voice_1501351_25 = "ที่มาสู้ได้ก็เพราะทาคิยะช่วยทำงานแทนฉันน่ะ เขาทำงานหนักมาก ๆ เลย...",
  str_voice_1501351_26 = "ขนมปังครีมชนะใจฉันตั้งแต่แรกชิม! ชอกโกแลตสดก็อร่อยจนเกินห้ามใจ!",
  str_voice_1501351_27 = "ทุกที่มีแต่ความยุ่งเหยิงวุ่นวาย! ฉันต้องจัดระเบียบให้หมด ไม่งั้นคงไม่สบายใจไปทั้งวัน!",
  str_voice_1501351_28 = "โคลอสซัสมีที่ไว้ทำอาหารมั้ย?",
  str_voice_1501351_29 = "เอลมา โจอิ ปัจจุบันทำงานอยู่ที่บริษัทจิโกคุเมะกุริ ซิสเต็ม เอ็นจิเนียริ่ง ยินดีที่ได้รู้จัก! โลกนี้เขาทักทายกันแบบนี้รึเปล่านะ?",
  str_voice_1501351_30 = "พลังแห่งของหวาน!",
  str_voice_1501351_31 = "เติมมานาเต็มแล้ว!",
  str_voice_1501351_32 = "อธิษฐานกับฉันสิ!",
  str_voice_1501351_33 = "พลังเพื่อควบคุมสายน้ำ!",
  str_voice_1501351_34 = "อยู่นี่!",
  str_voice_1501351_35 = "พร้อมแล้ว",
  str_voice_1501351_36 = "ระวังให้ดีเถอะ!",
  str_voice_1501351_37 = "ชำระพวกโสมม!",
  str_voice_1501351_38 = "จงสำนึกบาป!",
  str_voice_1501351_39 = "ไปให้พ้น!",
  str_voice_1501351_40 = "พวกนอกรีต!",
  str_voice_1501351_41 = "มายุติความขัดแย้งกับฉัน!",
  str_voice_1501351_42 = "นึกว่าจะง่ายซะอีก",
  str_voice_1501351_43 = "ฉันต้องย้อนมองส่องตน...",
  str_voice_1501351_44 = "ฉันขออยู่ที่นี่ฟรีได้มั้ย?",
  str_voice_1501351_45 = "ได้ซักที เงินเดือนของเดือนนี้",
  str_voice_1501351_46 = "นี่เป็นโบนัสที่ทำโอทีเหรอ?",
  str_voice_1501351_47 = "ขอบคุณที่คิดถึงกันนะ",
  str_voice_1501351_48 = "ฉันทำเครื่องรางนี่มาให้นาย!",
  str_voice_1501351_49 = "ทั้ง ๆ ที่ฉันอยู่ฝ่ายระเบียบ แต่ฉันก็พังบ้านคุณโคบายาชิไปครึ่งนึงตอนที่เจอกันครั้งแรก แถมยังถล่มภูเขาทั้งลูก ให้ตายสิ ฉันทำอะไรลงไป...",
  str_voice_1501351_50 = "ฉันเกิดจากน้ำ แต่จะทำตัวเป็นสายน้ำไม่ได้ ฉันจะต้องมีจิตใจที่แน่วแน่เพื่อยึดมั่นในอุดมการณ์ของตนเอง...",
  str_voice_1501351_51 = "ฉันอิจฉาพวกที่บินได้อย่างอิสระจริง ๆ อิสรภาพมันก็เป็นเรื่องที่เข้าใจยากนะ",
  str_voice_1501351_52 = "Alchemy Stars",
  str_voice_1501351_53 = "นายอยู่มั้ย PlayerName?",
  str_voice_1501351_54 = "อรุณสวัสดิ์",
  str_voice_1501351_55 = "สวัสดียามบ่าย เป็นไงบ้าง?",
  str_voice_1501351_56 = "มืดแล้วสินะ",
  str_voice_1501351_57 = "สุขสันต์วันปีใหม่! นี่เป็นวันที่จะต้องกินของอร่อยให้เต็มอิ่มเลยนะ",
  str_voice_1501361_1 = "ชื่อจริงของฉันมันอ่านยากอยู่นะ เรียกฉันว่าลูโคอาก็พอ... เป็นอะไรไปน่ะ ไม่อยากเรียกชื่อนั้นเหรอ?",
  str_voice_1501361_2 = "ฉันไม่ใช่ปีศาจนะ! ที่จริงแล้วมันตรงกันข้ามเลย ฉันเคยเป็นเทพมาก่อน... เอ่อ เอาเป็นว่ารู้แค่นี้ก็พอ",
  str_voice_1501361_3 = "เจ้านายคนก่อนของฉันเรียกฉันว่าปีศาจ ไม่รู้เหมือนกันว่าเขาหมายถึงอะไร เธอคิดว่ายังไงล่ะ?",
  str_voice_1501361_4 = "ฉันไม่ชอบทำตัวจริงจัง เพราะมันไม่จำเป็นน่ะ",
  str_voice_1501361_5 = "หน้าที่ของฉันคือการรักษาความสงบของโลก วันหยุดของฉันใกล้จะจบลงแล้วสินะ",
  str_voice_1501361_6 = "ลืมความทรงจำแย่ ๆ และหลีกหนีช่วงเวลาที่ทุกข์ใจ นี่คือวิถีชีวิตและสิทธิพิเศษของฉัน",
  str_voice_1501361_7 = "ในเมื่อเราทำพันธสัญญากันแล้ว ตอนนี้ฉันจะยอมเชื่อฟังเธอก็แล้วกัน แต่ขอบอกไว้ก่อน ว่าฉันกลับคำได้ทุกเมื่อนะ!",
  str_voice_1501361_8 = "เทพเจ้าน่ะ ถ้าอยากยุ่งเกี่ยวกับมนุษย์ก็ทำได้ง่ายนิดเดียว... อ๊ะ ขอโทษนะ ฉันพูดชวนให้เข้าใจผิดใช่มั้ย",
  str_voice_1501361_9 = "ไม่ชอบถูกกอดเหรอ? เข้าใจแล้ว ฉันจะจำเอาไว้",
  str_voice_1501361_10 = "นี่ ได้ยินฉันมั้ย? มีใครอยู่บ้านรึเปล่า?",
  str_voice_1501361_11 = "แหะแหะ เข้าใจแล้ว ระหว่างนี้ฉันจะทำตัวดี ๆ ก็แล้วกัน",
  str_voice_1501361_12 = "ไม่เคยหาเสื้อไซส์พอดีตัวได้เลย น่าหงุดหงิดจริง ๆ...",
  str_voice_1501361_13 = "พวกเด็ก ๆ ก็มาด้วยเหรอ? วิเศษ นี่มันเหมือนทัศนศึกษาเลย!",
  str_voice_1501361_14 = "ว่าไงนะ? ฉันทำอะไรตอนเมาน่ะเหรอ...? อย่าไปเชื่อคำโกหกของโทรุนะ!",
  str_voice_1501361_15 = "สุขสันต์วันเกิด! อยากได้ของขวัญเป็นอะไรล่ะ? ฉันให้เธอได้ทุกอย่างเลยนะ!",
  str_voice_1501361_16 = "สวัสดี เมื่อคืนฉันไม่ได้กวนเธอใช่มั้ย?",
  str_voice_1501361_17 = "เฮ้อ ไม่อยากตื่นนอนเลย...",
  str_voice_1501361_18 = "ตะวันตกดินแล้ว เป็นอีกวันที่ไม่ต้องทำอะไรเลย มีความสุขจัง!",
  str_voice_1501361_19 = "ไม่ง่วงเหรอ? เอาล่ะ งั้นฉันอ่านนิทานก่อนนอนให้ฟังนะ!",
  str_voice_1501361_20 = "ถึงพวกเธอจะมีนิสัยพิลึกในตัวเอง แต่ก็เป็นเด็กดีทุกคนเลยนะ",
  str_voice_1501361_21 = "โลกใบนี้มีกฎเกณฑ์ของมัน บางทีฉันก็ไม่ควรจะเข้าไปยุ่งเกี่ยว",
  str_voice_1501361_22 = "โลกใหม่ให้พิชิต!",
  str_voice_1501361_23 = "เด็ก ๆ พวกนั้นเกิดมาเพื่อรักษาสมดุล แสดงว่าพวกเราเองก็ไม่ต่างกัน",
  str_voice_1501361_24 = "โทรุเป็นคนติดดินมากขึ้นหลังจากที่ได้พบกับโคบายาชิ",
  str_voice_1501361_25 = "คันนะปรับตัวกับที่นี่ได้รึยังน่ะ? เธอเป็นเด็กที่อยากรู้อยากเห็นมาก ๆ ก็เลยต้องคอยดูแลอยู่เรื่อย ๆ น่ะ",
  str_voice_1501361_26 = "ถ้าพูดถึงการพักผ่อนหย่อนใจ ยังไงก็ต้องเป็นโชตะคุงอยู่แล้ว!",
  str_voice_1501361_27 = "ฉันได้กลิ่นเหล้า! ไม่สิ ตอนนี้ฉันจะต้องอยู่ห่างจากมันไว้ให้มากที่สุด...",
  str_voice_1501361_28 = "ขับเจ้านี่ทุกวันคงเบื่อน่าดูเลยสินะ",
  str_voice_1501361_29 = "จากนี้ไปเธอคือเจ้านายของฉัน แค่ชั่วคราวนะ",
  str_voice_1501361_30 = "ชักจะน่าสนใจขึ้นมาแล้วสิ",
  str_voice_1501361_31 = "อยากรู้จักฉันมากกว่านี้มั้ย?",
  str_voice_1501361_32 = "มาสิ ฉันจะบอก \"ความลับ\" ให้ฟัง",
  str_voice_1501361_33 = "เตรียมเผชิญหน้ากับเทพเจ้าได้เลย",
  str_voice_1501361_34 = "มาแล้ว!",
  str_voice_1501361_35 = "ทางนี้สินะ?",
  str_voice_1501361_36 = "ฉันสู้ไม่เก่งซะด้วยสิ",
  str_voice_1501361_37 = "อาจจะเจ็บหน่อยนะ...",
  str_voice_1501361_38 = "เจ้าจะได้ประจักษ์ถึงความรู้แจ้ง",
  str_voice_1501361_39 = "กฎเกณฑ์แห่งจักรวาล",
  str_voice_1501361_40 = "พลังแห่งจักรวาล",
  str_voice_1501361_41 = "ดูโน่นสิ ทุกคน!",
  str_voice_1501361_42 = "ไม่มีแม้แต่คำชมเลยเหรอ?",
  str_voice_1501361_43 = "ประมาทไปแล้ว",
  str_voice_1501361_44 = "ง่วงจัง... ว่ามั้ย?",
  str_voice_1501361_45 = "ขอบคุณนะ ฉันจะรักษามันอย่างดี!",
  str_voice_1501361_46 = "รู้ได้ยังไงน่ะว่าฉันชอบอะไร?",
  str_voice_1501361_47 = "ให้ของขวัญแบบนี้คิดยังไงกับฉันเหรอ?",
  str_voice_1501361_48 = "นี่เป็นสิ่งที่ฉันอยากได้ที่สุดเป็นอันดับสองเลย...!",
  str_voice_1501361_49 = "ฉันมาอยู่นี่ได้ยังไง? ก็ ฉันรู้ว่าโทรุเปิดประตูมิติผิดพลาด ก็เลยตามเธอมาน่ะ",
  str_voice_1501361_50 = "ใคร ๆ ก็จ้องมองฉัน... ฉันดูเด่นขนาดนั้นเลยเหรอ?",
  str_voice_1501361_51 = "ฉันได้ยินคนพยายามอัญเชิญบางอย่างก็เลยแวะมาหาน่ะ ว่าแต่ตอนนั้นเธอจะอัญเชิญอะไรเหรอ?",
  str_voice_1501361_52 = "Alchemy Stars",
  str_voice_1501361_53 = "สวัสดี",
  str_voice_1501361_54 = "อรุณสวัสดิ์",
  str_voice_1501361_55 = "ของีบได้มั้ย?",
  str_voice_1501361_56 = "กลางคืนแล้ว!",
  str_voice_1501361_57 = "สุขสันต์วันปีใหม่! ปีนี้ฉลองต่างจากปีที่ผ่านมาสุด ๆ เลย",
  str_voice_1401371_1 = "พ่อบ้านงั้นเหรอ? คิดจะดูถูกกันรึไง? ฉันไม่รับใช้ใครหรอกนะ",
  str_voice_1401371_2 = "ฉันกำลังเล่นเกมอยู่ ไว้คราวหลังก็แล้วกัน",
  str_voice_1401371_3 = "ความกล้าหาญคือคุณธรรมอันสูงส่ง? ฉันฆ่าคนกล้าพวกนั้นมาเป็นร้อยแล้วล่ะ",
  str_voice_1401371_4 = "ความโลภคือสันดานของมนุษย์ พวกนั้นสนุกที่จะได้ไล่ล่า ไม่ได้สนใจเป้าหมายของการล่าหรอก",
  str_voice_1401371_5 = "ชะตาอันโหดร้ายที่ไม่อาจหลีกหนีหรือต่อต้าน... นี่เป็นคำสาป",
  str_voice_1401371_6 = "ถ้าอาบเลือดของฉันแล้วเจ้าจะได้รับชีวิตอมตะ น่าเสียดายที่ไม่มีใครคู่ควรกับเกียรติอันสูงส่งนั่นหรอกนะ",
  str_voice_1401371_7 = "ฉันเขียนหนังสืออยู่บ้าง ถ้าสนใจก็ลองอ่านดูสิ เพราะดูเหมือนเจ้าจะมีรสนิยมที่ดี",
  str_voice_1401371_8 = "เกมในโลกนี้ก็ใช้ได้นะ นี่ เร็วเข้า อีเวนต์จะเริ่มแล้ว",
  str_voice_1401371_9 = "คนเราก็มีทั้งแบบที่เข้ากันได้และเข้ากันไม่ได้ อย่างหลังเจอกันครั้งแรกก็รู้แล้ว แต่อย่างแรกนี่ต้องใช้เวลาหน่อย",
  str_voice_1401371_10 = "นี่ จะให้ฉันรอไปถึงเมื่อไหร่?",
  str_voice_1401371_11 = "อย่ามาชี้นิ้วสั่งฉันนะ",
  str_voice_1401371_12 = "แน่นอน ฉันไม่ชอบสารรูปของตัวเองตอนนี้หรอก เพราะมันทำให้เข้าใจว่าฉันเหมือนพวกเจ้าน่ะสิ!",
  str_voice_1401371_13 = "โดจินชิเล่มนี้ฉันเขียนไว้สำหรับงานคอมิเก็ตครั้งต่อไปน่ะ ต้องขายดีเป็นเทน้ำเทท่าแน่ ๆ",
  str_voice_1401371_14 = "การตายทำให้เกมมีความหมาย แต่ไม่ใช่ว่าทุกคนจะฆ่าฉันได้หรอกนะ",
  str_voice_1401371_15 = "ถึงกับต้องฉลองวันที่ตัวเองเกิด ชีวิตเจ้านี่มันน่าเบื่อแค่ไหนกันนะ",
  str_voice_1401371_16 = "ใช่ วันใหม่ นับถอยหลังสู่วันที่เจ้าจะต้องตาย",
  str_voice_1401371_17 = "ใส่ใจกับการตรงต่อเวลาจริงนะ สำหรับฉันแล้ว กลางวันมันก็ไม่ต่างจากกลางคืนหรอก",
  str_voice_1401371_18 = "อาหารมื้อดึก? ฉันไม่สนของพวกนั้นหรอก... ว่าไงนะ มีแกงกะหรี่หวานงั้นเหรอ?",
  str_voice_1401371_19 = "ฉันไม่ต้องนอนหลับอยู่แล้ว ถ้าอยากไปนอนก็เชิญ",
  str_voice_1401371_20 = "พึ่งพาไม่ได้เลยจริง ๆ อย่าสร้างปัญหาก็แล้วกัน",
  str_voice_1401371_21 = "ถ้าไม่กวนฉัน ฉันก็ไม่ว่าอะไร",
  str_voice_1401371_22 = "ทำลายโลกใบนี้ให้สิ้น",
  str_voice_1401371_23 = "สำหรับฉัน เจ้ากับไอ้พวกนั้นก็ไม่ต่างกัน แต่ขยะก็ควรนำมารีไซเคิลนะ",
  str_voice_1401371_24 = "ฉันรู้จักกับโทรุมานานแล้ว เราทำอะไรเหมือนๆ กัน",
  str_voice_1401371_25 = "ฉันยอมรับในความแข็งแกร่งของลูโคอา",
  str_voice_1401371_26 = "เจ้าเป็นเผ่าพันธุ์ที่ต่ำต้อยตามธรรมชาติอยู่แล้ว แต่ก็ต้องยอมรับว่าเกมของเจ้าน่าสนใจ",
  str_voice_1401371_27 = "กำจัดผู้บุกรุกและหัวขโมย!",
  str_voice_1401371_28 = "เจ้าหนูผู้น่าสงสาร เจตจำนงเสรีจอมปลอมบนยานจอมปลอม ไม่ต่างจากหุ่นเชิด",
  str_voice_1401371_29 = "ฉันชื่อฟาฟนีร์ ตัวฉันพอจะทนกับนายในโลกน่าเบื่อนี่ได้ แต่อย่าทำให้ฉันโกรธล่ะ",
  str_voice_1401371_30 = "เลเวลอัป",
  str_voice_1401371_31 = "แทบจะอดใจไม่อยู่แล้วล่ะ",
  str_voice_1401371_32 = "ฆ่า ฆ่า ฆ่า",
  str_voice_1401371_33 = "ฉันไม่ได้ยินเสียงอ้อนวอนอีกแล้ว",
  str_voice_1401371_34 = "ถอยไป",
  str_voice_1401371_35 = "หมดเวลาแล้ว",
  str_voice_1401371_36 = "พิธีกรรมเริ่มขึ้นแล้ว",
  str_voice_1401371_37 = "เตรียมชะตาขาดได้แล้ว",
  str_voice_1401371_38 = "ติดตามเป็นเงา!",
  str_voice_1401371_39 = "จงดิ้นรน",
  str_voice_1401371_40 = "อย่าให้ใครรอดไปได้",
  str_voice_1401371_41 = "พวกเจ้าทุกคน รอฟังคำสั่งฉัน",
  str_voice_1401371_42 = "ชิ...",
  str_voice_1401371_43 = "ทำไมพวกมันถึง...",
  str_voice_1401371_44 = "เอาเกมทั้งหมดที่มีมาให้ฉัน",
  str_voice_1401371_45 = "อะไรน่ะ เครื่องบรรณาการรึ?",
  str_voice_1401371_46 = "มีทั้งหมดแค่นี้หรือไง?",
  str_voice_1401371_47 = "ก็ได้ ฉันจะรับไว้",
  str_voice_1401371_48 = "หึ ฉันกำลังรอมันอยู่เลยล่ะ",
  str_voice_1401371_49 = "มีคนเปิดประตูมิติแล้วก็ลากฉันมาที่นี่ ถ้าเดาไม่ผิดก็น่าจะเป็นโทรุล่ะนะ",
  str_voice_1401371_50 = "เพิ่งเจอพวกไร้มารยาทมา แต่ตอนนี้มันตายหมดแล้วล่ะ",
  str_voice_1401371_51 = "ฉันจะถูกฆ่าโดยนักล่ามังกรชื่อซิกฟรีดงั้นเหรอ? เรื่องเหลวไหล",
  str_voice_1401371_52 = "Alchemy Stars",
  str_voice_1401371_53 = "อืมม...",
  str_voice_1401371_54 = "สวัสดียามเช้า",
  str_voice_1401371_55 = "สว่างจริง ๆ",
  str_voice_1401371_56 = "โอ๊ะ กลางคืนแล้วสินะ",
  str_voice_1401371_57 = "นี่ก็ปีใหม่แล้ว อยากโดนคำสาปของฉันไหมล่ะ?",
  str_voice_1601381_1 = "ถ้าคุณพบวัตถุโบราณ ขอแนะนำว่าควรส่งมอบให้ศูนย์วิจัยอิลลูมินา เพราะที่นั่นเป็นที่เดียวที่จะเก็บรักษาสิ่งเหล่านั้นได้ แต่ถ้ามอบให้ฉันได้ก็จะดีที่สุดเลย",
  str_voice_1601381_2 = "แม้ว่าฉันจะเชื่อในวิทยาศาสตร์ แต่มันก็ไม่ใช่ทุกอย่างเสมอไป ตัวอย่างเช่น การค้นหาซากโบราณอันมีค่า บางทีต้องอาศัยดวงล้วน ๆ เลยนะ",
  str_voice_1601381_3 = "วัตถุโบราณน่ะพูดได้ ที่ฉันพูดแบบนี้ก็อย่าเข้าใจไปตามตัวอักษรนะ! ของพวกนี้น่ะ สื่อสารกับเราผ่านร่องรอยที่ทิ้งไว้เบื้องหลัง",
  str_voice_1601381_4 = "ไม่ต้องกลัวนะ แมงมุมน้อยของฉันน่ารักทุกตัว พวกเขาช่วยฉันไว้เยอะตอนที่ศึกษาค้นคว้าซากโบราณ",
  str_voice_1601381_5 = "ผู้สร้างอารยธรรมโบราณที่รุ่งเรืองขนาดนี้หายสาบสูญไปได้ยังไงกันนะ? ทุกวันนี้ฉันก็ยังพยายามหาคำตอบเรื่องนั้นอยู่",
  str_voice_1601381_6 = "การทำงานคือการแก้ปัญหา และสิ่งที่เลวร้ายที่สุดที่จะเกิดขึ้นได้ในระหว่างการแก้ปัญหาก็คือการใช้อารมณ์ แต่แน่นอน ถ้าเลิกงานแล้วก็เต็มที่ได้เลย",
  str_voice_1601381_7 = "เลข \"3\" เป็นเลขคี่และเป็นจำนวนเต็ม เป็นตัวเลขแห่งความสามัคคีและความมั่นคง เป็นตัวแทนของจุดเริ่มต้นและจุดสิ้นสุดโดยสมบูรณ์ในตัวเอง เพราะงั้นเลข \"3\" จึงเป็นเลขนำโชคของฉัน!",
  str_voice_1601381_8 = "คุณอยากรู้จริงเหรอว่าทำไมฉันถึงเล่ากระบวนการความคิดของตัวเองออกมา? ฮ่า ๆ มันเป็นนิสัยเสียที่ฉันเป็นมาตั้งแต่เด็กน่ะ โอ๊ะ คุณว่ามันไม่ใช่เรื่องแย่เหรอ?",
  str_voice_1601381_9 = "ที่จริงฉันไม่ได้สวมหน้ากากตลอดเวลาหรอกนะ มันน่าสนใจขนาดนั้นเชียวเหรอ? เอาเถอะ ฉันว่าเราอย่าเพิ่งคุยกันตอนนี้เลยดีกว่า เอาไว้คุยกันหลังเลิกงาน ตกลงมั้ย?",
  str_voice_1601381_10 = "ฉันคิดออกแล้ว! ถ้าไม่มีอะไรให้ทำมากนัก ทำไมไม่เลิกงานเร็วขึ้นแล้วไปดื่มอะไรกันหน่อยล่ะ? หรือจะกินเนื้อย่างเสียบไม้เผ็ด ๆ ด้วยก็ได้นะ... อร่อยเหาะ!",
  str_voice_1601381_11 = "ขอบคุณที่เชิญฉันมาทำงานวิจัยนะ... หา? ที่นี่ไม่มีอะไรต้องวิจัยงั้นเหรอ? ว้าว งานแบบนี้มีไม่มากแล้วสินะ!",
  str_voice_1601381_12 = "สิ่งที่ฉันต้องการหาไม่ใช่ทั้งทอง หรือเงิน หรือเครื่องเพชรพลอย แต่เป็นสิ่งที่ล้ำค่ากว่านั้นมาก",
  str_voice_1601381_13 = "ใคร ๆ ก็ว่าฉันไม่มีทางเมา แต่นั่นก็ออกจะเกินความจริงไปหน่อยน่ะนะ",
  str_voice_1601381_14 = "แมงมุมเหรอ? อ๊ะ... นั่นแมงมุมสัตว์เลี้ยงตัวน้อยของฉันเอง",
  str_voice_1601381_15 = "วันนี้วันเกิดเธอเหรอ? หลังเลิกงานเดี๋ยวฉันตามไปฉลองด้วยนะ อย่าลืมจองที่เผื่อฉันด้วยล่ะ!",
  str_voice_1601381_16 = "กังวลอะไรเรื่องงานหรือเปล่า? คุยกับฉันได้เสมอนะ ยังไงซะก็ไม่มีอะไรที่ฉันแก้ไขไม่ได้",
  str_voice_1601381_17 = "สวัสดีตอนเช้า! เป็นเวลาดีที่จะเริ่มทำงานนะ",
  str_voice_1601381_18 = "ใช่แล้ว... ฉันเพิ่งทำงานเสร็จน่ะ เดี๋ยวไปดื่มกันไหม?",
  str_voice_1601381_19 = "ที่คนเราอยู่ดึกเกินเที่ยงคืนก็เป็นไปได้สองสาเหตุ: เพราะเขาเลือกที่จะอยู่ดึก หรือไม่ก็จำเป็นต้องอยู่ดึก เธอเป็นคนจำพวกไหนล่ะ?",
  str_voice_1601381_20 = "อิลลูมินาไม่เพียงแต่สอนวิธีการวิจัย แต่ยังให้ฉันมีอิสระในการทำเช่นนั้นด้วย",
  str_voice_1601381_21 = "โอย ฉันไม่เข้าใจความคิดของชาวลูโมโพลิสเลย ถึงพวกเขาจะไม่รู้จักการชื่นชมวัตถุโบราณ ก็ไม่จำเป็นต้องทำลายนี่นา!",
  str_voice_1601381_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1601381_23 = "ฉันจะไม่ยกโทษให้อิคลิพไซท์พวกนั้นที่ทำลายซากโบราณ!",
  str_voice_1601381_24 = "ไม่ว่าจะในด้านการวิจัยหรือการจัดการ ผู้บัญชาการกรอนรูเป็นแบบอย่างของฉันเสมอมา",
  str_voice_1601381_25 = "นอกจากผลการวิจัยแล้ว ฉันไม่เคยเข้าใจการกระทำของมิการ์ดเลย",
  str_voice_1601381_26 = "เครื่องดื่มที่ได้จากการหมักที่ฉันชอบไม่เหมาะกับเด็กหรอกนะ",
  str_voice_1601381_27 = "ก-เกมเหรอ...? ขอโทษนะ ฉันนึกขึ้นได้ว่ายังมีงานต้องทำ เล่นไปเลยไม่ต้องรอฉันนะ",
  str_voice_1601381_28 = "ดูจากการออกแบบตามหลักอากาศพลศาสตร์และพื้นผิวที่เป็นประกาย... ยานลำมหึมานี้ต้องมีเรื่องราวที่น่าทึ่งอยู่เบื้องหลังแน่",
  str_voice_1601381_29 = "รูปร่าง หน้าตา เส้นผม ส่วนสูง สไตล์เสื้อผ้า... ใช่แล้ว คุณเป็นเคเลสไทต์แน่นอน! ฉันชื่อเชอวาน ตื่นเต้นจังที่จะได้ศึกษาเกี่ยวกับคุณ!",
  str_voice_1601381_30 = "ประสิทธิภาพการทำงานของฉันเพิ่มขึ้นอีกครั้ง",
  str_voice_1601381_31 = "ฉันข้ามผ่านห้วงเวลา..",
  str_voice_1601381_32 = "ฉันข้ามผ่านห้วงอวกาศ...",
  str_voice_1601381_33 = "ฉันได้เห็นทุกสิ่งทุกอย่างภายใต้ท้องฟ้า...",
  str_voice_1601381_34 = "รับทราบ!",
  str_voice_1601381_35 = "มาวัดกันเลยว่าปฏิกิริยาของใครจะเร็วกว่ากัน",
  str_voice_1601381_36 = "ถ้าพร้อมแล้วก็ลุยเลย",
  str_voice_1601381_37 = "หมดเวลา! รับไปซะ!",
  str_voice_1601381_38 = "ใยแมงมุม!",
  str_voice_1601381_39 = "ง่ำ!",
  str_voice_1601381_40 = "แมงมุมจุมพิต!",
  str_voice_1601381_41 = "โอเค เข้าใจแล้ว",
  str_voice_1601381_42 = "ขอบคุณนะที่บัญชาการได้เยี่ยมมาก",
  str_voice_1601381_43 = "พบสาเหตุของความพ่ายแพ้",
  str_voice_1601381_44 = "กำลังพูดถึงเรื่องนั้นอยู่เหรอ? ทำไมฉันไม่อธิบายให้ฟังน่ะเหรอ?",
  str_voice_1601381_45 = "นี่เป็นโบราณวัตถุที่เธอให้ฉันเหรอ?",
  str_voice_1601381_46 = "ทำไมถึงรู้ว่าฉันอยากได้อะไร...?",
  str_voice_1601381_47 = "นี่ไม่ใช่สิ่งที่เธอได้มาง่าย ๆ เลย... อะไรนะ? ให้ฉันเหรอ?",
  str_voice_1601381_48 = "เคเลสไทต์นี่เข้าใจความรู้สึกคนอื่นดีจังเลยนะ",
  str_voice_1601381_49 = "ฉันยังจำความลึกลับและความตื่นเต้นในตอนนั้นได้... ที่ปลายสุดของหลุมที่เย็นชื้น ซากโบราณปรากฏแก่สายตาฉันเป็นครั้งแรก",
  str_voice_1601381_50 = "วันเกิดที่น่าจดจำที่สุดน่ะเหรอ...? มีอยู่ปีนึง ผู้ใหญ่หลายคนที่ฉันไม่รู้จักนำดอกไม้มาหาฉัน แต่สิ่งที่พวกเขาเตรียมไว้ให้ฉันไม่ใช่ของขวัญวันเกิด...",
  str_voice_1601381_51 = "ฉันอยากกล้าหาญเหมือนพ่อและมุ่งมั่นเหมือนแม่ เพื่อเห็นแก่จุดประสงค์ที่ฉันรัก แม้ว่าวันหนึ่งจะต้องล้มลง ฉันก็จะไม่เสียใจเลย",
  str_voice_1601381_52 = "Alchemy Stars!",
  str_voice_1601381_53 = "สวัสดี",
  str_voice_1601381_54 = "ได้เวลาทำงานแล้ว",
  str_voice_1601381_55 = "พักผ่อนหน่อยจ้า",
  str_voice_1601381_56 = "เธอยังทำงานอยู่เหรอ?",
  str_voice_1601381_57 = "สวัสดีปีใหม่! นี่คงเป็นเวลาหยุดพักผ่อนใช่มั้ยล่ะ",
  str_voice_1501391_1 = "ฉันได้ยินเสียงกระซิบจากต่างโลก พวกมันไม่ได้มาจากโลกนี้ แล้วยังคอยยั่วยุให้ฉันเปิดประตูให้อีกด้วย...",
  str_voice_1501391_2 = "ฉันอิจฉาจริง ๆ คุณไม่รู้ความลับของโลก ไม่รู้สถานการณ์ของตัวเองแม้แต่น้อย และมีรอยยิ้มบนใบหน้าได้อย่างไร้กังวลในแต่ละวัน",
  str_voice_1501391_3 = "ไปกันเถอะ กัปตัน! หา... ไม่เข้าใจคำนั้นเหรอ? นั่นเป็นคำที่มนุษย์โบราณใช้เรียกผู้นำทางที่ขับเครื่องจักรไงล่ะ!",
  str_voice_1501391_4 = "ดาบของฉันสร้างขึ้นมาเป็นพิเศษและสามารถผสานกับลูมินาธาตุต่าง ๆ เพื่อเพิ่มพลังของมัน อยากลองมั้ยล่ะ?",
  str_voice_1501391_5 = "ชาวเมืองลูโมโพลิสที่บูชาสิ่งลึกลับเหล่านั้นอย่างคลั่งไคล้จะต้องอยู่ภายใต้มนต์สะกด... และฉันต้องปลุกพวกเขา...",
  str_voice_1501391_6 = "ตอนนี้ฉันเป็นหนึ่งเดียวกับโลกและสามารถรับรู้การมีอยู่ของสัตว์ร้ายที่บุกรุกโลกนี้ได้ดีขึ้น",
  str_voice_1501391_7 = "อยากรู้ความจริงเกี่ยวกับโลกงั้นเหรอ? มาเดินบนเส้นทางที่เต็มไปด้วยความประหลาดใจกับฉันสิ...",
  str_voice_1501391_8 = "ถ้าอยากเรียนรู้เพิ่มเติมเกี่ยวกับโลกอื่นและอาณาจักรต่าง ๆ ฉันให้ยืมหนังสือโบราณที่สะสมไว้ก็ได้นะ แต่ห้ามลองใช้คาถาในนั้นเด็ดขาดเลย สัญญาได้มั้ย?",
  str_voice_1501391_9 = "แม้ว่าโลกนี้ไม่ใช่ของจริง แต่เวลาที่อยู่กับเธอนั้นเป็นความจริง",
  str_voice_1501391_10 = "*เหนื่อยหอบ*... หนอย เจ้าหมาอวกาศ เอาขนมฉันคืนมานะ! เอ๋...? ฝันไปเหรอเนี่ย... ดีนะที่คุณเคเลสไทต์ไม่อยู่ตรงนี้ ไม่งั้นผู้ตื่นรู้อย่างฉันอายแย่เลย...",
  str_voice_1501391_11 = "เราต้องยืนเฝ้ายามอีกแล้วเหรอ? คุณคงไม่เคยสัมผัสถึงความตกใจที่ฉันได้เจอ นอนห่มผ้าอุ่น ๆ อยู่ดี ๆ แล้วอีกวินาทีก็โดนลมหนาวกระโชกใส่... อะไรนะ? คุณบอกว่าฉันจะทำอะไรที่นี่ก็ได้ตามใจงั้นเหรอ? ล้อกันเล่นรึเปล่า?",
  str_voice_1501391_12 = "น้ำตาลจะกระตุ้นสมองให้ปล่อยสารกระตุ้นตามธรรมชาติที่ช่วยในการคิด เพราะงั้นฉันจึงมีขนมติดตัวอยู่ตลอด",
  str_voice_1501391_13 = "ดูลายเส้นเกลียวบนลาเต้สิ... มันคงเป็นคำเตือนที่สิ่งลึกลับส่งมาให้เรา",
  str_voice_1501391_14 = "ความกดอากาศลดลงที่ 0.155 หน่วยต่อวินาที โคลอสซัสบินขึ้นแล้วเหรอ?",
  str_voice_1501391_15 = "สุขสันต์วันเกิด! ฉันขอให้เธอสนุกกับช่วงเวลาแห่งความสงบสุขที่เหลืออยู่ในพื้นที่นี้",
  str_voice_1501391_16 = "เธออยู่ที่นี่เอง! สิ่งลึกลับที่ซ่อนอยู่ในเงามืดยังไม่ได้จับตัวเธอ งั้นก็ไปต่อเถอะ",
  str_voice_1501391_17 = "คราวหน้าอย่ามาเช้านักนะ... ฉันยังอยาก... นอนต่ออีกหน่อยอะ...",
  str_voice_1501391_18 = "อำนาจชั่วร้ายกำลังรวมตัวกันในอากาศ ถึงเวลาแล้วเหรอ...?",
  str_voice_1501391_19 = "กลางคืนเป็นเวลาที่ภาพลวงตาแข็งแกร่งขึ้น ฉันยังนอนไม่ได้ ไม่อย่างนั้นฉันจะไม่สามารถปกป้องเคเลสไทต์ผู้อ่อนโยน",
  str_voice_1501391_20 = "ที่ลูโมโพลิสมีความคลุมเครือหลายอย่าง... เธอต้องระมัดระวังตลอดเวลาเมื่ออยู่ที่นั่น ไม่เช่นนั้น เธอจะกลายเป็นเป้าหมาย...",
  str_voice_1501391_21 = "นักเรียนที่อิลลูมินามีความรู้มาก พวกเขาศึกษาเรลิกโบราณมานับไม่ถ้วนและต้องรู้ความลับมากมาย...",
  str_voice_1501391_22 = "ขอเทิดทูนรัตติกาลสีขาว! ถูกต้อง!",
  str_voice_1501391_23 = "อิคลิพไซท์เป็นสิ่งที่สิ่งลึกลับสร้างขึ้น และเป็นสัญญาณว่าพลังลึกลับกำลังเคลื่อนที่...",
  str_voice_1501391_24 = "ประธานฟลอรีนเป็นเพื่อนคนแรกและคนเดียวของฉัน\nที่อุษาวิทยาลัย",
  str_voice_1501391_25 = "เลดี้อูริเอลเชื่อว่าโลกนี้เป็นภาพลวงตาและวันหนึ่งจะต้องถูกทำลาย เธอต้องเป็นหนึ่งในผู้ตื่นรู้แน่นอน",
  str_voice_1501391_26 = "เธอคิดบ้างมั้ยว่าถ้าได้ออกไปทำอะไรสนุก ๆ เพียงลำพังบ้างคงจะสุดยอดไปเลย?",
  str_voice_1501391_27 = "อ่านอะไรอยู่น่ะ? ภาพรวมประวัติศาสตร์ลูโมโพลิส... เอิ่ม... แค่เห็นตัวหนังสือเป็นปึก ๆ ในนั้นฉันก็ตาลายแล้ว...",
  str_voice_1501391_28 = "เทคโนโลยีของเคเลสไทต์ที่สร้างโคลอสซัสได้นี่เจ๋งสุด ๆ เลย... เป็นไปได้มั้ยว่า \"สิ่งลึกลับ\" มอบวิชาให้พวกเขา?",
  str_voice_1501391_29 = "สวัสดี ฉันชื่อเอริก้า ฉันเห็นสายเลือดโบราณของเคเลสไทต์ไหลเวียนอยู่ในเส้นเลือดของเธอ... นี่เป็นการเผชิญกับบทชีวิตที่ลิขิตไว้นานแล้ว หรือเป็นโชคชะตากันแน่นะ?",
  str_voice_1501391_30 = "พลังอันไม่สิ้นสุด",
  str_voice_1501391_31 = "จิตของฉันสอดประสานกับภาพลวงตาของโลกมากขึ้นไปอีกขั้นหนึ่งแล้ว...",
  str_voice_1501391_32 = "ฉันได้ยินเจตจำนงของโลก",
  str_voice_1501391_33 = "สิ่งลึกลับนอกโลกทั้งหลาย พวกเจ้าไม่อาจหลบซ่อนได้อีกแล้ว",
  str_voice_1501391_34 = "ฉันอยากกลับไปนอนแล้ว",
  str_voice_1501391_35 = "อีกนิดเดียวเท่านั้น...",
  str_voice_1501391_36 = "*เฮ้อ* ก็ดี",
  str_voice_1501391_37 = "ปลดปล่อยพลังของเจ้า สายฟ้า!",
  str_voice_1501391_38 = "แฟลชไฟฟ้า",
  str_voice_1501391_39 = "รวมพลัง!",
  str_voice_1501391_40 = "ลำแสงหมุนวน!",
  str_voice_1501391_41 = "อย่าสร้างปัญหาให้ฉันเลย",
  str_voice_1501391_42 = "ไปนอนต่อดีกว่า",
  str_voice_1501391_43 = "ฉันยังตื่นไม่เต็มที่เหรอ?",
  str_voice_1501391_44 = "นี่คือโคลอสซัสเหรอ...? ต้องรีบจับมันตอนที่กัปตันไม่อยู่...\nอ้าว กัปตัน! กลับมาแล้วเหรอ!",
  str_voice_1501391_45 = "นี่เป็นของที่ให้กันเป็นพิเศษเหรอ?",
  str_voice_1501391_46 = "คราวหน้าขอเยอะ ๆ กว่านี้อีกนะ",
  str_voice_1501391_47 = "เป็นของขวัญที่สมกับอารยธรรมโบราณจริง ๆ",
  str_voice_1501391_48 = "นี่เป็นของขวัญที่ดีที่สุดที่ฉันเคยได้รับเลย!",
  str_voice_1501391_49 = "เหตุผลที่ฉันเป็นอัศวินไม่ได้ซับซ้อนหรือยิ่งใหญ่เหมือนอย่างคนอื่นหรอก มันก็เพียงเพราะว่า... คุณปู่บังคับฉันในสิ่งที่เคยคาดหวังในตัวคุณพ่อ",
  str_voice_1501391_50 = "พ่อเคยให้ \"หนังสือต้องห้าม\" กับฉัน ซึ่งมันเปลี่ยนชีวิตของฉันไปเลย เพราะหนังสือนั่น ทำให้ฉันเริ่มสนใจปรากฏการณ์ลึกลับและเรียกสิ่งมีชีวิตลึกลับที่ไม่มีที่อยู่ในโลกปัจจุบันอย่างไม่ทันระวังตัว...",
  str_voice_1501391_51 = "โลกนี้เต็มไปด้วยวิกฤต ใครจะรู้ว่ามีสิ่งลึกลับจำนวนมากมายแค่ไหนที่เฝ้าดูเราและหลบหนีไป ในฐานะผู้ตื่นรู้ วิธีเดียวที่จะช่วยทุกคนได้คือการสำรวจอารยธรรมโบราณและค้นหากุญแจสู่การแก้ปัญหา...",
  str_voice_1501391_52 = "Alchemy Stars!",
  str_voice_1501391_53 = "กัปตัน!",
  str_voice_1501391_54 = "ง่วงอะ",
  str_voice_1501391_55 = "ได้เวลางีบแล้ว",
  str_voice_1501391_56 = "มาเล่นกันเถอะ",
  str_voice_1501391_57 = "ผ่านไปอีกปีสำหรับออโรเรียนแล้วนะ...",
  str_voice_1601401_1 = "เป็นดาบที่ไม่เหมือนใครเลยใช่มั้ย? ดาบเลื้อยเลาะเป็นดาบที่พ่อแม่ฉันสั่งทำเป็นพิเศษ ราคาแพงน่าดูเลยล่ะ ถ้ามองด้านข้างแบบนี้มันดูเหมือนงูเลยเนอะ?",
  str_voice_1601401_2 = "ถ้าเรียกมันว่า \"เจ้างูขาวตัวน้อย\" มันก็ไม่สนใจหรอก มันชื่ออัลบา แต่ถึงจะเรียกชื่อไป ถ้าไม่มีอารมณ์เล่นด้วยมันก็ไม่สนอยู่ดี",
  str_voice_1601401_3 = "ฉันอุทิศชีวิตเพื่อการทำภารกิจ ว่าไงนะ? ภารกิจคราวนี้คือหยุดงานงั้นเหรอ?",
  str_voice_1601401_4 = "ฉันเกลียดคนแข็งแกร่งที่รังแกคนอ่อนแอ... ดังนั้นฉันจะไม่ยอมปิดหูปิดตาตัวเองจากความชั่วร้ายเหล่านั้น ตราบใดที่ยังมีแรงจับดาบ",
  str_voice_1601401_5 = "ถ้าฉันยอมรับชะตากรรมของตัวเองในวันนั้น ฉันก็คงไม่ได้เจอคุณ... ไม่สิ นั่นไม่มีทางเป็นชะตาของฉันหรอก เพราะเทพแห่งแสงสว่างได้พิสูจน์เรื่องนั้นให้ฉันได้ประจักษ์แล้ว",
  str_voice_1601401_6 = "ขอโทษนะ เวลาอัลบาตกใจกลัว *แค่ก* มันจะปล่อย... กลิ่นฉุนออกมา ถ้าสูดเข้าไปเยอะ ๆ คุณก็จะหมดสติ เพราะงั้นฉันควรระบายอากาศหน่อย",
  str_voice_1601401_7 = "พ่อแม่ของฉันยังรอวันที่ฉันจะประสบความสำเร็จอย่างยิ่งใหญ่ เพราะฉะนั้น... ฉันจะไม่มีทางหยุด ฉันจะต้องเก่งในงานทุกอย่างที่ทำ",
  str_voice_1601401_8 = "รู้สึกลื่น ๆ เย็น ๆ ที่คอเหรอ? อ๋า หรือจะเป็นอัลบา? ปกติมันไม่เข้าใกล้คนอื่นเลยนะ... อัลบา ออกมาสิ...",
  str_voice_1601401_9 = "ก่อนออกเดินทาง อย่าลืมตรวจสอบเส้นทาง เก็บข้าวของ แล้วก็อย่าลืมน้ำกับอาหารด้วยล่ะ... หืม ทำไมมองแบบนั้นล่ะ? โทษทีนะ ฉันคงเริ่มจู้จี้แล้วใช่มั้ย...",
  str_voice_1601401_10 = "ถ้าคุณไม่ว่าอะไร ขอฉันฝึกดาบที่นี่สักพักได้มั้ย? ฉันไม่อยากปล่อยให้เวลาผ่านไปโดยเปล่าประโยชน์น่ะ",
  str_voice_1601401_11 = "ที่นี่ก็มีงานสืบสวนเหมือนกันเหรอ? โอ้ ไม่เหมือนกันซะทีเดียวแฮะ... ไม่เป็นไร ในเมื่ออยู่ที่นี่แล้ว ฉันก็จะตั้งใจทำให้ดีที่สุด!",
  str_voice_1601401_12 = "คุณก็ชอบอ่านหนังสือเหมือนกันเหรอ? หวังว่าคงไม่ใช่นิยายรักน่าเบื่อพวกนั้นหรอกนะ",
  str_voice_1601401_13 = "ปากแตกหมดแล้วนะเนี่ย แถมผิวก็แห้งด้วย คุณลืมดื่มน้ำอีกแล้วงั้นเหรอ?",
  str_voice_1601401_14 = "อัศวินที่แท้จริงย่อมไม่มีทางยอมแพ้โดยไม่ต่อสู้ดิ้นรน ฉันบอกตัวเองแบบนี้มาตลอดตั้งแต่เด็ก",
  str_voice_1601401_15 = "สุขสันต์วันเกิด! ฉันรู้ได้ยังไงว่านี่เป็นวันเกิดคุณน่ะเหรอ? ก็คอยสังเกตสิ่งต่าง ๆ รอบตัวอยู่เสมอน่ะสิ...",
  str_voice_1601401_16 = "เราออกกำลังกายและพักผ่อนเพื่อที่จะทำงานหนัก ๆ ไหวไม่ใช่หรือไง?",
  str_voice_1601401_17 = "สิ่งแรกที่ควรทำหลังจากตื่นนอนตอนเช้าก็คือการดื่มน้ำอุ่น ต้องเป็นน้ำอุ่นด้วยนะ ไม่งั้นท้องไส้จะปั่นป่วน",
  str_voice_1601401_18 = "คุณไม่ควรออกกำลังกายหนัก ๆ ในเวลานี้นะ แล้วก็อย่ากินหรือดื่มมากเกินไปล่ะ",
  str_voice_1601401_19 = "ขั้นแรก นอนลงบนเตียง ขั้นที่สอง ปิดอุปกรณ์ความบันเทิง ถ้ายังหลับไม่ลงก็แสดงว่ามีอาการนอนไม่หลับแล้วล่ะ",
  str_voice_1601401_20 = "สถานที่แห่งเดียวที่สืบสานเจตจำนงของเทพแห่งแสงสว่าง... ฉันจะปกป้องลูโมโพลิสอย่างสุดกำลัง!",
  str_voice_1601401_21 = "อิลลูมินาทะเยอทะยานอยู่เสมอ ฉันแค่หวังว่าพวกเขาจะไม่ลืมความตั้งใจแรกเริ่มของตัวเอง",
  str_voice_1601401_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1601401_23 = "อิคลิพไซท์เป็นศัตรูของออโรเรียนทุกคน แม้แต่เทพแห่งแสงสว่างก็ยังอนุญาตให้เราทำลายมัน",
  str_voice_1601401_24 = "ฉันหวังว่าเอริก้าจะเลิกฝันกลางวันได้สักที จะได้ไม่ต้องคอยเป็นห่วงเธอตลอด",
  str_voice_1601401_25 = "คุณเฮดี้ทั้งฉลาดและมีความสามารถ เธอเป็นแบบอย่างของฉันเลยล่ะ",
  str_voice_1601401_26 = "ฉันชอบการพิทักษ์ความยุติธรรมและปกป้องผู้อ่อนแอ แค่นั้นแหละ",
  str_voice_1601401_27 = "ฉันมีสิ่งที่ไม่ชอบมากมาย อย่างนึงที่ทำให้ฉันหัวเสียมากก็คือผู้ที่ทำลายศรัทธา ฟังดูจริงจังไปเหรอ?",
  str_voice_1601401_28 = "มีใครบอกได้ไหมว่าโคลอสซัสเป็นวิทยาการโบราณรึเปล่า? หวังอย่างยิ่งว่าจะไม่ใช่นะ",
  str_voice_1601401_29 = "ขอเทิดทูนรัตติกาลสีขาว! ฉันชื่อฟลอรีน ฉันได้ฟังเรื่องราวเกี่ยวกับตัวคุณมามากมาย แต่ต้องขออภัยด้วย ฉันจะต้องพิสูจน์ให้แน่ชัดก่อนสรุปข้อเท็จจริง",
  str_voice_1601401_30 = "งานหนักย่อมตอบแทนเราอย่างดีแน่นอน",
  str_voice_1601401_31 = "ดาบเลื้อยเลาะเฉียบคมขึ้นอีกแล้ว",
  str_voice_1601401_32 = "ตอนนี้... ฉันทำงานได้เร็วขึ้นกว่าเก่า!",
  str_voice_1601401_33 = "ฉันรอช่วงเวลานี้มานานเหลือเกิน!",
  str_voice_1601401_34 = "ภารกิจจะต้องลุล่วง!",
  str_voice_1601401_35 = "ฉันพร้อมแล้ว",
  str_voice_1601401_36 = "รออยู่เลย",
  str_voice_1601401_37 = "จะไม่มีใครหน้าไหนหนีไปได้!",
  str_voice_1601401_38 = "การพิพากษารอพวกแกอยู่!",
  str_voice_1601401_39 = "อสรพิษสายฟ้า จงตื่นขึ้น!",
  str_voice_1601401_40 = "อสรพิษสายฟ้าพิโรธ!",
  str_voice_1601401_41 = "ขอบคุณที่เชื่อใจกันนะ!",
  str_voice_1601401_42 = "นี่เป็นความรับผิดชอบของฉัน",
  str_voice_1601401_43 = "วางใจได้ ฉันจะไม่ยอมแพ้เด็ดขาด...",
  str_voice_1601401_44 = "คุณเป็นเจ้าของสิ่งนี้จริง ๆ เหรอ...? ดูท่าทางแล้วไม่น่าจะมีความสามารถพอเลยนะ",
  str_voice_1601401_45 = "โอ๊ะ... ไม่ต้องลำบากก็ได้นะ",
  str_voice_1601401_46 = "ว้าว... ตื้นตันจนพูดไม่ออกเลย...",
  str_voice_1601401_47 = "ขอบคุณที่อุตส่าห์ลำบากนะ",
  str_voice_1601401_48 = "ฉันชอบมากเลย! ไว้จะหาโอกาสตอบแทนแน่นอน!",
  str_voice_1601401_49 = "เพื่อดูแลแม่ที่มักจะงุนงงอยู่บ่อย ๆ ฉันต้องเรียนรู้วิธีหุงหาอาหารตั้งแต่ยังเล็ก บอกมาเลยว่าจะให้ทำงานบ้านอะไร ฉันจัดการได้ทุกอย่างไม่มีปัญหา",
  str_voice_1601401_50 = "ครอบครัวฉันไม่ได้มีฐานะร่ำรวยอะไร ก็ไม่คิดฝันว่าจะได้เรียนที่อุษาวิทยาลัย แต่พ่อแม่ก็พยายามอย่างสุดกำลังเพื่อรวบรวมเงินมาเป็นค่าเล่าเรียน...",
  str_voice_1601401_51 = "มันไม่เกี่ยวหรอกว่าจะเรียนจบจากที่ไหนหรือมีผลการเรียนดีแค่ไหน สิ่งเดียวที่พิสูจน์ค่าของคนได้ก็คือการทำงานหนัก การที่ฉันผ่านการประเมินของศาสนจักรและได้เป็นสมาชิกฝ่ายสืบสวนลัทธินอกรีตอย่างเป็นทางการนั้นเป็นเครื่องพิสูจน์ได้อย่างดี",
  str_voice_1601401_52 = "Alchemy Stars!",
  str_voice_1601401_53 = "สวัสดี",
  str_voice_1601401_54 = "คนตื่นเช้าจะได้ประโยชน์มากที่สุดนะ",
  str_voice_1601401_55 = "อย่าลืมดื่มน้ำเยอะ ๆ ล่ะ",
  str_voice_1601401_56 = "อย่านอนดึกเกินไปล่ะ",
  str_voice_1601401_57 = "ฉันมีอะไรจะบอก... เอ่อ... สุขสันต์วันปีใหม่นะ!",
  str_voice_1601411_1 = "ไปกันเลย! ไปไหนน่ะเหรอ? สำรวจดินแดนที่ไม่รู้จักไงล่ะ! อย่าบอกนะว่าไม่สนเลย?",
  str_voice_1601411_2 = "เอาล่ะ ขอแนะนำตัวเลยก็แล้วกัน นี่เบนท์ลี่ย์กับลอมพ์ตี้ โอ้ แยกพวกมันไม่ออกงั้นเหรอ? ดูนะ... เบนท์ลี่ย์คือเจ้าตัวผอม ส่วนลอมพ์ตี้คือเจ้าตัวตุ้ยนุ้ย",
  str_voice_1601411_3 = "แปลกแฮะ ฉันเอาไม้ไปวางไว้ไหนนะ? เมื่อกี้ยังอยู่ตรงนี้เลย... มันจะหายไปได้ยังไงกัน? ว่าไงนะ? มันอยู่แค่—โอ๊ะ อยู่ตรงนี้จริง ๆ ด้วย! ฮ่าฮ่าฮ่า...",
  str_voice_1601411_4 = "อย่าดูถูกกระเป๋าเดินทางของฉันล่ะ ในนี้มีทั้งเครื่องมือ ยา เสบียงอาหาร น้ำ... อ้อ ขอแนะนำให้รู้จักเบนท์ลี่ย์กับลอมพ์ตี้... อุปกรณ์พิเศษของฉัน ฮิฮิ",
  str_voice_1601411_5 = "ฉันมีความคิดเจ๋ง ๆ! ขอผูกรถไว้นอกโคลอสซัสได้มั้ย? มันจะได้บินได้เหมือนกันไง!",
  str_voice_1601411_6 = "ฮ่าฮ่าฮ่า พอได้แล้วน่า...! โอ๊ะ โทษที เบนท์ลี่ย์กับลอมพ์ตี้จั๊กจี้ฉันน่ะ นี่ ทั้งสองตัว ออกไปจากเสื้อฉันเดี๋ยวนี้นะ!",
  str_voice_1601411_7 = "แม่บอกว่าฉันเกิดในรถแวกอนของเรดีเซล เวรนช์ ใคร ๆ ก็คิดว่าเท่ไม่เบาเลย นายคิดว่าไง?",
  str_voice_1601411_8 = "ฉันหามันไปทั่วเลย ตั้งนานแล้วนะ เบนท์ลี่ย์กับลอมพ์ตี้มาซ่อนอยู่กับนายงั้นเหรอ?! แปลกแฮะ ปกติพวกมันไม่ยุ่งกับคนอื่นเลยนะ...",
  str_voice_1601411_9 = "\"หล่าลาล้า! ดูบีดูบีดู!\" นี่ รู้จักเพลงนี้รึเปล่า? เฮ้! นายก็เป็นแฟนเพลงบาร์บาร่าเหมือนกันเหรอ? เอ้า เอาหูฟังไปข้างนึงสิ!",
  str_voice_1601411_10 = "เอ่อ เอิ่ม... นี่ คุยกับฉันหน่อย... ขืนเป็นแบบนี้ไปเรื่อย ๆ ฉันจะไม่ต่างจากโบราณวัตถุที่ฝังอยู่ใต้ดินเลยนะ...",
  str_voice_1601411_11 = "หวัดดี! ขอดูแถว ๆ นี้ได้มั้ย? เดี๋ยวก่อน... ฉันลืมเอาอุปกรณ์สำรวจมา!",
  str_voice_1601411_12 = "หิ่งห้อยในโคลอสซัส... ฉันขอใช้เป็นลูกบอลได้มั้ย? ตอนนี้ฉันอยากเล่นตีลูกบอลน่ะ...",
  str_voice_1601411_13 = "อีกไม่กี่ปีต่อจากนี้ ทุกคนในทวีปจะได้รู้จักรูบี้ นักสำรวจผู้ยิ่งใหญ่!",
  str_voice_1601411_14 = "ฉันเข้าใจว่าการเดินทางต้องใช้เงิน ฉันก็เลยรับภารกิจล่ารางวัลไปด้วยไงล่ะ!",
  str_voice_1601411_15 = "วันนี้วันเกิดนายเหรอ! ฮ่าฮ่า อยากอธิษฐานอะไรมั้ย? ฉันจะทำให้เป็นจริงเพื่อนาย",
  str_voice_1601411_16 = "อืมม... อุณหภูมิ... เรียบร้อย! ความชื้น... เรียบร้อย! ความเร็วลม... เรียบร้อย! วันนี้อากาศเหมาะที่จะออกผจญภัยสุด ๆ!",
  str_voice_1601411_17 = "นี่ เมื่อคืนฉันฝันว่าความฝันของตัวเองเป็นจริงด้วยนะ! แล้วนายล่ะ? ฝันเห็นอะไรดี ๆ บ้างรึเปล่า?",
  str_voice_1601411_18 = "เฮ้ ฉันกำลังบันทึกเรื่องราวการผจญภัยของวันนี้อยู่เลย! หือ? ลายมือฉันอ่านยากงั้นเหรอ? นั่นไม่ใช่เรื่องสำคัญสักหน่อย!",
  str_voice_1601411_19 = "ถ้าอยู่จนดึกดื่นสภาพนายจะดูไม่จืดนะ... เอาล่ะ ถ้าไม่คิดจะนอน งั้นฉันไปนอนก่อนนะ",
  str_voice_1601411_20 = "อิสรภาพ ความสุข และครอบครัวของฉัน... เรดีเซล เวรนช์ จะเป็นบ้านของฉันตลอดไป",
  str_voice_1601411_21 = "อิลลูมินาครอบครองซากโบราณมากมายขนาดนั้นเลยเหรอ?! แต่ฉันว่าชีวิตคนพวกนั้นน่าเบื่อจะตาย",
  str_voice_1601411_22 = "ใช้ชีวิตให้เต็มที่! อย่าให้อะไรมาจำกัดเราได้!",
  str_voice_1601411_23 = "อิคลิพไซท์พวกนั้นขัดขวางการผจญภัยของฉันอยู่เรื่อย ต้องจัดการพวกมันให้รู้สำนึก!",
  str_voice_1601411_24 = "ที่จริง... ฉันอยากให้รูจมีความฝันของตัวเอง แทนที่จะมาตามฉันตลอดเวลาแบบนี้",
  str_voice_1601411_25 = "แปลกหรือไงที่โอดีเป็นหัวหน้าฉัน? ถึงเธอจะอายุน้อยกว่า แต่เป็นคนฉลาดมากเลยนะ",
  str_voice_1601411_26 = "ของที่ฉันชอบก็มีเยอะแยะนะ แต่ถ้าให้เลือกอย่างเดียวล่ะก็ ต้องเป็นการผจญภัยอยู่แล้ว!",
  str_voice_1601411_27 = "ขอแค่ไม่ต้องนั่งกร่อยอยู่ที่บ้าน จะให้ทำอะไรก็ดีทั้งนั้นแหละ!",
  str_voice_1601411_28 = "ได้ขับยานบินมันก็เท่ดีนะ แต่พออยู่บนฟ้าอย่างเดียว นายก็จะพลาดโอกาสสำรวจทวีปแห่งนี้ให้ทั่ว...",
  str_voice_1601411_29 = "หวัดดี ฉันชื่อรูบี้ ความฝันของฉันคือการออกสำรวจทั่วทุกมุมโลก! นายเองก็เดินทางบ่อยงั้นเหรอ? ถ้างั้นเรามีเรื่องให้คุยกันเยอะแยะเลยล่ะ!",
  str_voice_1601411_30 = "เลือดของฉันกำลังเดือดพล่าน!",
  str_voice_1601411_31 = "เป็นความรู้สึกที่ยอดไปเลย!",
  str_voice_1601411_32 = "ลายมือฉันดูสวยขึ้นรึยังนะ?",
  str_voice_1601411_33 = "ความฝันของฉัน... ฉันเข้าใกล้มันอีกก้าวนึงแล้ว!",
  str_voice_1601411_34 = "มีอะไรสนุก ๆ ให้ทำมั้ย?",
  str_voice_1601411_35 = "ถ้าพร้อมแล้วก็ลุยเลย",
  str_voice_1601411_36 = "นายจะไม่ลืมฉันใช่มั้ย?",
  str_voice_1601411_37 = "ไนซ์ช็อต!",
  str_voice_1601411_38 = "วงสวิงสุดแรงเกิด!",
  str_voice_1601411_39 = "ตีได้สวย!",
  str_voice_1601411_40 = "เข้าเป้าเป๊ะ!",
  str_voice_1601411_41 = "เรื่องแค่นี้ง่ายนิดเดียว!",
  str_voice_1601411_42 = "ไหนล่ะเสียงปรบมือ?",
  str_voice_1601411_43 = "อีกรอบ... ขออีกรอบได้มั้ย!",
  str_voice_1601411_44 = "การผจญภัยงั้นเหรอ?! ฉันจะ... หือ นายไม่ได้ไปด้วยงั้นเหรอ?",
  str_voice_1601411_45 = "โอ้... ให้ฉันเหรอ?",
  str_voice_1601411_46 = "ฮ่าฮ่าฮ่า รู้จักฉันดีเหมือนกันนะเนี่ย!",
  str_voice_1601411_47 = "เฮ้ นี่ของแพงนี่นา?",
  str_voice_1601411_48 = "ฉันชอบมาก ๆ เลย!",
  str_voice_1601411_49 = "ฉันอยู่กับเรดีเซล เวรนช์ มาตั้งแต่จำความได้... ต่อสู้ ขับรถ ออกล่า... กินเนื้อเยอะแยะและร้องรำทำเพลงอยู่ตลอดเวลา",
  str_voice_1601411_50 = "ความมุ่งมั่นอย่างเดียวมันไม่พอสำหรับนักผจญภัยหรอก นายต้องมีความรู้และฝีมือ... ฉันเองก็เคยพลาดเรื่องนั้น",
  str_voice_1601411_51 = "พูดตามตรงนะ ตอนที่ฉันบอกลาแม่และสตาร์ทรถ ฉันเองก็เกือบร้องไห้ออกมา แต่ทันใดนั้นฉันก็รู้สึกได้ว่ามีใครอีกคนแอบติดรถมาด้วย",
  str_voice_1601411_52 = "Alchemy Stars!",
  str_voice_1601411_53 = "หวัดดี!",
  str_voice_1601411_54 = "อรุณสวัสดิ์!",
  str_voice_1601411_55 = "เฮ้ หิวข้าวรึยัง?",
  str_voice_1601411_56 = "นี่ก็ดึกแล้วนะ!",
  str_voice_1601411_57 = "สุขสันต์วันปีใหม่! ปีใหม่ทั้งที ไปสำรวจสถานที่ที่ไกลกว่านี้กันดีมั้ย?",
  str_voice_1501421_1 = "นี่ ช่วยหาวัสดุในลิสต์ก่อนการต่อสู้ครั้งต่อไปด้วยนะ อะไรอีกล่ะ... อย่ามองฉันด้วยสายตาแบบนั้นสิ เดี๋ยวทำเสร็จแล้วจะส่งอุปกรณ์รุ่นตัวอย่างให้นะ",
  str_voice_1501421_2 = "อาหารในโคลอสซัสนี่ใช้ได้เลย มีสมดุลทางโภชนาการทุกวัน บางครั้งก็เปิดเป็นบุฟเฟต์... นายควรกินเนื้อและออกกำลังกายให้มากกว่านี้นะ จะได้กำจัดอิคลิพไซท์เองได้ยังไงล่ะ",
  str_voice_1501421_3 = "นี่ไม่ได้อู้อยู่ใช่มั้ย? ทำงานเสร็จรึยัง? อย่าหลบตาฉันสิ... เฮ้!",
  str_voice_1501421_4 = "ตอนแรกที่ฉันได้ดาบยักษ์โชติช่วงมา มันดูเหมือนคีมธรรมดาที่ใหญ่กว่าปกติ ฉันพัฒนามันตั้ง 2 ปีแน่ะ กว่าจะเป็นอย่างทุกวันนี้ ยอดเลยใช่มั้ยล่ะ?",
  str_voice_1501421_5 = "เครื่องจักรของมนุษย์ยุคโบราณน่ะมีแต่ของน่าสนใจสุด ๆ ถ้าวันนึงฉันคิดค้นเครื่องจักรชนิดใหม่ได้ ผู้คนจะต้องยกย่องฉันเป็นยอดนักประดิษฐ์แน่นอน",
  str_voice_1501421_6 = "ด้วยพลังนี้ ฉันก็จะปกป้องรูบี้ได้ดีขึ้น แต่นั่นยังไม่พอ... ฉันอยากจะแข็งแกร่งกว่านี้อีก แกร่งพอที่เธอจะพึ่งพาได้...",
  str_voice_1501421_7 = "ฉันก็แค่ช่วยนายเพราะสงสารหรอกนะ แล้วที่นี่ก็มีวิทยาการน่าสนใจมากมาย... ฉันไม่ได้อยากจะตีสนิทกับนายเลย!",
  str_voice_1501421_8 = "ทำไมจู่ ๆ ถึงเข้ามาใกล้แบบนั้นล่ะ? นี่เป็นระยะปกติของคนเป็นเพื่อนกันงั้นเหรอ? ฉัน–ฉันไม่ได้บอกว่าเราเป็นเพื่อนกันซะหน่อย!",
  str_voice_1501421_9 = "เหนื่อยเหรอ? งั้นก็พักบ้างสิ ไม่เห็นต้องโหมงานหนักแบบนั้นเลย มองอะไรของนายน่ะ? ตกใจที่ฉันเป็นห่วงเรอะ? นี่เห็นฉันเป็นคนยังไงกันน่ะ...",
  str_voice_1501421_10 = "ตื่นเถอะ อย่านอนตรงนี้เลย อย่างน้อยก็ห่มผ้าหน่อย ไม่งั้นจะเป็นหวัดนะ...",
  str_voice_1501421_11 = "อยู่กับนายที่นี่เหรอ? ไม่นึกเลยว่านายจะพูดแบบนั้น... เอาเถอะ ช่วยไม่ได้นะ เดี๋ยวจะอยู่ด้วยก็แล้วกัน",
  str_voice_1501421_12 = "นายจ้องฉันไม่หยุดมาสักพักแล้ว คราวหน้าจะเริ่มคิดเงินแล้วนะ",
  str_voice_1501421_13 = "เห็นรูบี้บ้างมั้ย? เธอชอบไปผจญภัยน่ะ แต่ฉันกลัวว่าจะเกิดเรื่องกับเธอน่ะสิ",
  str_voice_1501421_14 = "เนื้อ♪ เนื้อ♪ เนื้อย่างแสนอร่อย... เย้ย! นาย–เข้ามาตั้งแต่เมื่อไหร่น่ะ?!",
  str_voice_1501421_15 = "เอ้า เอาไปสิ... นี่เป็นเทียนไขที่ร้องเพลงได้เวลาจุดไฟ ล-ลองดูสิ!",
  str_voice_1501421_16 = "มาจนได้นะ! ไปไหนมาตั้งนาน? ฉันไม่ได้คิดถึงนายหรอก! แค่จะหาคนช่วยเฉย ๆ!",
  str_voice_1501421_17 = "โย่ นาน ๆ ทีจะเห็นนายตื่นเช้านะเนี่ย มีอุปกรณ์ให้ซ่อมงั้นเหรอ? ก็ได้ ช่วงนี้ฉันก็ไม่มีอะไรให้ทำเท่าไหร่",
  str_voice_1501421_18 = "หลังข้าวเย็นเป็นช่วงเวลาของความสนุก คนเราต้องบาลานซ์งานกับการพักผ่อนนะ ถึงจะทำงานได้อย่างมีประสิทธิภาพ",
  str_voice_1501421_19 = "การเข้านอนแต่หัวค่ำและตื่นเช้าทำให้ร่างกายแข็งแรง... แค่บอกให้รู้ไว้ ไม่ได้เป็นห่วงหรอกนะ",
  str_voice_1501421_20 = "เรดีเซล เวรนช์ รับฉันเข้ามาและยอมรับฉันอย่างไม่มีเงื่อนไข ที่นั่นคือบ้านของฉัน",
  str_voice_1501421_21 = "พวกลูโมโพลิสชอบคิดว่าเราเป็นพวกเดียวกับพวกนั้น น่าหงุดหงิดจริง ๆ",
  str_voice_1501421_22 = "เพื่อรูบี้!",
  str_voice_1501421_23 = "บางทีคนเรานี่แหละที่น่ากลัวยิ่งกว่าอิคลิพไซท์ ความปรารถนาที่ดำมืดในใจคนนี่ช่างเข้าใจยากเหลือเกิน",
  str_voice_1501421_24 = "รูบี้อยู่ข้างฉันมาตลอดตั้งแต่ยังเล็ก ถ้าไม่มีเธอ ก็คงไม่มีฉันในวันนี้...",
  str_voice_1501421_25 = "โจนาเป็นคนช่วยชีวิตฉันไว้และทุกวันนี้ก็ยังคอยดูแลฉันอยู่ บางทีเธอก็เลี้ยงข้าวฉันด้วยนะ!",
  str_voice_1501421_26 = "ฉันชอบอะไรงั้นเหรอ? ถามอะไรแบบนั้นน่ะ? จะหาเรื่องเซอร์ไพรส์หรือไง?",
  str_voice_1501421_27 = "หวา! อย่าโผล่มาข้างหลังดื้อ ๆ แบบนั้นสิ! หัวใจเกือบวายแน่ะ!",
  str_voice_1501421_28 = "รูบี้คงดีใจมากถ้าเธอมีโคลอสซัสเป็นของตัวเองสักลำ... นายตั้งราคามันไว้เท่าไหร่น่ะ?",
  str_voice_1501421_29 = "ฉันชื่อรูจ นักประดิษฐ์ฝีมือฉกาจของเรดีเซล เวรนช์ ถ้าจะจัดปาร์ตี้ต้อนรับฉัน ช่วยเตรียมเนื้อย่างอย่างดีที่สุดให้ด้วยนะ อะแฮ่ม ว่าแต่... รูบี้อยู่ที่นี่รึเปล่า?",
  str_voice_1501421_30 = "รู้สึกคล่องตัวกว่าเดิมแฮะ...",
  str_voice_1501421_31 = "พลังที่มากขึ้น!",
  str_voice_1501421_32 = "เลือดของฉันกำลังเดือดพล่าน!",
  str_voice_1501421_33 = "ความร้อนแรงนั่น ฉันสัมผัสได้...",
  str_voice_1501421_34 = "จับตาดูฉันให้ดีล่ะ",
  str_voice_1501421_35 = "ล็อกเป้าหมาย!",
  str_voice_1501421_36 = "ล็อกเป้าหมายและบรรจุกระสุน!",
  str_voice_1501421_37 = "ดาบคีมจู่โจม!",
  str_voice_1501421_38 = "เล็ง... เตรียมพร้อม... ยิง!",
  str_voice_1501421_39 = "ได้เวลาเต้นรำแล้ว!",
  str_voice_1501421_40 = "ดาบยักษ์โชติช่วง!",
  str_voice_1501421_41 = "ฉันคือที่หนึ่ง!",
  str_voice_1501421_42 = "เป็นไปตามคาด",
  str_voice_1501421_43 = "ฉันทำไม่สำเร็จ...",
  str_voice_1501421_44 = "อย่าแตะต้องดาบยักษ์โชติช่วงนะ! มันเป็นอาวุธที่ละเอียดอ่อนมาก ๆ",
  str_voice_1501421_45 = "ของขวัญให้ฉันเหรอ? ทำไมล่ะ?",
  str_voice_1501421_46 = "ฉัน... ฉันไม่ได้ชอบของแบบนี้เท่าไหร่หรอกนะ",
  str_voice_1501421_47 = "ก็ดีนะ ฉันจะรับไว้ก็แล้วกัน",
  str_voice_1501421_48 = "ขอบคุณนะ... เอ่อ ลืมที่ฉันพูดไปเถอะ",
  str_voice_1501421_49 = "พ่อแม่? จะมีไปทำไมกัน? ถ้าไม่ใช่เพราะพวกนั้นให้กำเนิดฉัน ฉันก็ไม่อยากจะเกี่ยวข้องอะไรด้วยหรอก คนพวกนั้นทำให้ฉันมีความทรงจำวัยเด็กที่เลวร้ายเกินจะพรรณนา",
  str_voice_1501421_50 = "ฉันไม่ศรัทธาในเทพเจ้าเพราะฉันได้เจอกับคนที่ช่วยชีวิตฉันแล้ว รูบี้ช่วยฉันจากความมืดและพาไปสู่แสงสว่าง ฉันยินดีทำทุกอย่างเพื่อเธอ...",
  str_voice_1501421_51 = "เรดีเซล เวรนช์ ออกจะสบาย ๆ ว่ามั้ย? แม้แต่คนอย่างฉันก็ยังเข้ากับพวกเขาได้ ติดอยู่แค่ว่า... พวกนั้นชอบล้อที่ฉันคอยตามรูบี้ไปทุกที่...",
  str_voice_1501421_52 = "Alchemy Stars!",
  str_voice_1501421_53 = "ว่าไง",
  str_voice_1501421_54 = "วันนี้ตื่นเช้าจังนะ",
  str_voice_1501421_55 = "นี่ก็บ่ายแล้วนะ",
  str_voice_1501421_56 = "ตอนนี้มืดแล้วนะ",
  str_voice_1501421_57 = "ปีใหม่แล้ว แน่นอนว่าจะขาดหม้อไฟไปไม่ได้! ต้องใส่เนื้อเยอะ ๆ ด้วยนะ!",
  str_voice_1601431_1 = "ตราบใดที่ฉันอยู่ที่นี่ จะไม่มีใครบุกรุกเข้ามาได้",
  str_voice_1601431_2 = "นอกจากปฏิบัติหน้าที่ของมิโกะแล้ว ฉันยังเล่นดนตรีและจัดการเอกสารได้ดีอีกด้วยนะ",
  str_voice_1601431_3 = "กระดิ่งรำบวงสรวงของฉันหายไปอันนึง คุณช่วยหาให้หน่อยได้มั้ย?",
  str_voice_1601431_4 = "นั่งสมาธิ สวดภาวนา ทำความสะอาด... ชีวิตของมิโกะช่างน่าเบื่อเสียจริง",
  str_voice_1601431_5 = "เราเชื่อว่ามีเทพเจ้าสถิตอยู่ในทุกสิ่ง ไม่ว่าจะเป็นขุนเขา แม่น้ำ หินผา แมกไม้ เทพเจ้าเหล่านี้ปกป้องเราอยู่ทุกเวลานาที",
  str_voice_1601431_6 = "เขตอาคมของมิโกะจะปกป้องตัวมิโกะเองและทุกสิ่งที่เธอห่วงใย",
  str_voice_1601431_7 = "พลังชำระล้างของฉันจะรักษาบาดแผลของคุณได้มั้ยนะ?",
  str_voice_1601431_8 = "เขตอาคมของฉันต้านทานสิ่งชั่วร้ายได้ภายในขอบเขตของมัน กรุณาอย่าไปไหนไกลเกินไป",
  str_voice_1601431_9 = "ฉันปลดปล่อยพลังทางวิญญาณได้ราบรื่นขึ้นเมื่ออยู่ใกล้คุณ นี่เป็นเพราะพลังพิเศษของเคเลสไทต์หรือเป็นพรที่เกิดจากความเข้าใจระหว่างเรากันแน่นะ?",
  str_voice_1601431_10 = "โอ๊ะ... ท่านผู้นำทางใจลอยอยู่เหรอคะ? ความเกียจคร้านก็เป็นสิ่งชั่วร้ายอย่างหนึ่งนะ ฉันร่ายคาถาชำระล้างให้ดีมั้ย?",
  str_voice_1601431_11 = "อ๊ะ... งานที่นี่แตกต่างจากการฝึกมิโกะมากเลยล่ะ",
  str_voice_1601431_12 = "ท่านผู้นำทาง ต้องการพักผ่อนไหมคะ?",
  str_voice_1601431_13 = "ฉันกำลังจะเริ่มการฝึกมิโกะแล้ว สนใจจะฝึกด้วยกันไหมคะ?",
  str_voice_1601431_14 = "คุณอยากรู้เหรอว่าฉันบูชาเทพเจ้าองค์ไหน? เอ่อ... มิโกะทุกคนมีความลับนะ",
  str_voice_1601431_15 = "สุขสันต์วันเกิดท่านผู้นำทาง! ขอให้ได้พบแต่เพื่อนที่ดีในการเดินทางนะคะ",
  str_voice_1601431_16 = "มิโกะต้องวางตัวให้เพียบพร้อมอยู่เสมอทุกที่ทุกเวลา",
  str_voice_1601431_17 = "สวัสดีตอนเช้า ท่านผู้นำทาง! วันนี้ฉันจะช่วยคุณทำงานนะ",
  str_voice_1601431_18 = "สวัสดีตอนเย็น ท่านผู้นำทาง! วันนี้เป็นยังไงบ้างคะ?",
  str_voice_1601431_19 = "สิ่งชั่วร้ายจะแสดงฤทธิ์เดชมากที่สุดในเวลากลางคืน ท่านผู้นำทาง ต้องการชำระล้างสิ่งชั่วร้ายกับฉันไหม?",
  str_voice_1601431_20 = "ฉันยังคงคิดถึงเมือง ที่ซึ่งฉันชื่นชมปุยเมฆสูงเสียดฟ้าได้",
  str_voice_1601431_21 = "ลูโมโพลิสบูชาพระเจ้าเพียงองค์เดียว ต่างจากศาสนาของฉันนะ",
  str_voice_1601431_22 = "การใช้ชีวิตอิสระก็เป็นความสุขสำราญอย่างหนึ่งเหมือนกัน",
  str_voice_1601431_23 = "ล้อมเชือกป่านให้รอบโคลอสซัสเพื่อสร้างเขตอาคม แล้วสิ่งเหล่านั้นจะกล้ำกรายเข้ามาไม่ได้",
  str_voice_1601431_24 = "คายาโนะเป็นเด็กดีนะ แต่เธอไม่รู้ว่าการสะกดรอยตามเป็นสิ่งที่ไม่เหมาะสม...",
  str_voice_1601431_25 = "เหยาเป็นคนไร้เดียงสาและน่ารัก เหมือนลูกสุนัขตัวน้อย ๆ",
  str_voice_1601431_26 = "ลูกกลม ๆ ที่เปล่งแสงได้พวกนั้นคือหิ่งห้อยเหรอ? น่ารักจังเลยนะ!",
  str_voice_1601431_27 = "โลกนี้ไม่ใช่ที่ของสิ่งชั่วร้าย ฉันควรเผามันให้หมดไปด้วยพลังชำระล้าง",
  str_voice_1601431_28 = "โคลอสซัสเต็มไปด้วยแสงสว่างและปราศจากสิ่งชั่วร้าย ฉันชอบมาก",
  str_voice_1601431_29 = "รินเนะ มิโกะแห่งเกาะเมฆา ตอบรับการเรียกของท่าน กรุณาให้ฉันติดตามและช่วยเหลือท่านในการเดินทางครั้งนี้ด้วยเถอะค่ะ",
  str_voice_1601431_30 = "ขอบคุณที่เชื่อใจ",
  str_voice_1601431_31 = "ตอนนี้ฉันสู้ได้สบายขึ้นแล้ว...",
  str_voice_1601431_32 = "ฉันสัมผัสได้ถึงพลังทางจิตวิญญาณที่ไม่เคยมีมาก่อน",
  str_voice_1601431_33 = "ฉันจะใช้พลังชำระล้างนี้ให้เป็นประโยชน์",
  str_voice_1601431_34 = "เชื่อมือฉันได้เลย",
  str_voice_1601431_35 = "ฉันสวดภาวนาอยู่นี่แล้ว...",
  str_voice_1601431_36 = "โอ้... พลังชำระล้าง",
  str_voice_1601431_37 = "กางเขตอาคม!",
  str_voice_1601431_38 = "ข้าขอสั่งหมอกดำที่ปกคลุม จงสลายไปในบัดดล!",
  str_voice_1601431_39 = "จะมากไปแล้วนะ!",
  str_voice_1601431_40 = "วิญญาณชั่วร้าย จงไปให้พ้น!",
  str_voice_1601431_41 = "ทุกคน โปรดตามฉันมา",
  str_voice_1601431_42 = "ต้องขจัดสิ่งชั่วร้ายให้หมดสิ้น",
  str_voice_1601431_43 = "สิ่งชั่วร้าย พวกมัน...",
  str_voice_1601431_44 = "มีอะไรที่มิโกะช่วยได้บ้าง? ไม่ต้องเขินอายนะ บอกฉันได้เลยว่าคุณต้องการอะไร",
  str_voice_1601431_45 = "ของขวัญให้ฉันเหรอ? คุณช่างเอาใจใส่ดีจริง",
  str_voice_1601431_46 = "รู้ได้ยังไงว่าฉันชอบสิ่งนี้?",
  str_voice_1601431_47 = "ความในใจของคุณ ฉันได้รับรู้แล้วล่ะ...",
  str_voice_1601431_48 = "ฉันจะเก็บของขวัญของคุณไว้ในกล่องเก็บของรักของฉัน",
  str_voice_1601431_49 = "ชีวิตของมิโกะสุดแสนจะน่าเบื่อ หากไม่ได้พบคุณ ฉันคงต้องใช้ชีวิตจำเจไปวัน ๆ ต่อไป",
  str_voice_1601431_50 = "การไม่ไว้วางใจผู้อื่นเป็นที่มาของความเกลียดชังและความขัดแย้ง เป็นหน้าที่ของมิโกะที่จะขจัดความสงสัยและความริษยา",
  str_voice_1601431_51 = "ตั้งแต่ได้ร่วมการเดินทางกับคุณ ชีวิตฉันก็สนุกสนานตื่นตาตื่นใจ มันอาจจะไม่ปลอดภัยและสงบเหมือนที่เกาะเมฆา แต่ฉันไม่รู้สึกรังเกียจเลย",
  str_voice_1601431_52 = "Alchemy Stars",
  str_voice_1601431_53 = "สวัสดี",
  str_voice_1601431_54 = "อรุณสวัสดิ์",
  str_voice_1601431_55 = "สวัสดีตอนบ่าย ท่านผู้นำทาง",
  str_voice_1601431_56 = "ขอโทษที่รบกวนนะ",
  str_voice_1601431_57 = "สวัสดีปีใหม่ ท่านผู้นำทาง ได้โปรดอนุญาตให้ฉันใช้กระดิ่งรำบวงสรวงชำระล้างสิ่งชั่วร้ายทั้งหมด และสวดภาวนาขอให้ปลอดภัยด้วยเถอะค่ะ",
  str_voice_1501441_1 = "โปรดอย่ามองฉันแบบนั้น คุณกำลังทำให้ฉันประหม่านะ...",
  str_voice_1501441_2 = "ฉันคงตายไปนานแล้วหากไม่ได้ท่านมิโกะช่วยไว้ ฉันรู้สึกขอบคุณเธออย่างยิ่ง",
  str_voice_1501441_3 = "ความอาฆาตที่ท่องไปในโลกโลกีย์... วิญญาณเปลี่ยวเหงาที่อยู่รอบตัวข้า... หึหึ... เดี๋ยวก่อน เมื่อกี้ไม่ใช่ฉันนะ...",
  str_voice_1501441_4 = "ฉันมองสิ่งเหล่านั้นเป็นเหมือนอากาศธาตุ แต่ไม่มีใครเชื่อฉันเลย",
  str_voice_1501441_5 = "บางครั้งฉันอาจจะพูดอะไรแปลก ๆ โดยที่ฉันไม่ได้อยากพูดเองนะ สิ่งนั้นต้องการให้ฉันช่วยพูดแทนเขา โปรดเชื่อฉันเถอะ",
  str_voice_1501441_6 = "ฉันจะคิดวางแผนอนาคตของตัวเองเป็นครั้งคราว ตอนนี้ฉันคิดว่าฉันอยากอยู่ที่นี่นะ",
  str_voice_1501441_7 = "ที่นี่แตกต่างจากบ้านเกิดของฉันมากเลย อยู่แล้วรู้สึกผ่อนคลาย ฉันจะรักมากกว่านี้ถ้ามีคนน้อยลง...",
  str_voice_1501441_8 = "ถ้าไม่รังเกียจ ฉันขอวาดรูปคุณได้ไหม? ฉันเคยเรียนวาดรูปมานิดหน่อย จะวาดให้สุดฝีมือเลย",
  str_voice_1501441_9 = "วิเศษจริง ๆ... นอกจากเด็ก ๆ แล้ว คุณคือเพื่อนคนแรกของฉัน ฉันกับสิ่งนั้นไม่ได้แข็งแกร่งเหมือนคนอื่น ๆ ที่นี่หรอก แต่ฉันจะทำทุกอย่างเพื่อคุณ",
  str_voice_1501441_10 = "ท่านผู้นำทางไม่อยู่งั้นเหรอ? งั้นฉันแอบอู้สักหน่อย คงไม่เป็นไรมั้งนะ",
  str_voice_1501441_11 = "ให้ทำงานที่นี่เหรอ? ก็ได้นะถ้าคนมาที่นี่ไม่เยอะ...",
  str_voice_1501441_12 = "รอยคล้ำใต้ตาของคุณแย่ลงกว่าเก่าอีกนะ คุณต้องพักผ่อนให้มาก ๆ...",
  str_voice_1501441_13 = "ผู้นำทางจะออกเดินทางแล้วเหรอ? งั้นฉันจะไปที่ห้องนั่งเล่นละนะ... หา? ฉันก็ต้องไปด้วยเหรอ?",
  str_voice_1501441_14 = "สิ่งเหล่านั้น... โปรดอย่าทำลายมันนะ เพื่อพิธีกรรม... โอ๊ะ! ได้โปรดอย่าทำลาย มันเจ็บจริง ๆ...",
  str_voice_1501441_15 = "สุขสันต์วันเกิด! ฉันเตรียมของขวัญพิเศษไว้ให้คุณแล้ว... ไม่! ไม่ใช่สิ่งนั้นหรอกน่า!",
  str_voice_1501441_16 = "คุณทำงานทั้งวันเลยเหรอ? ขยันจังเลย!",
  str_voice_1501441_17 = "อืม... อรุณสวัสดิ์ ฉันยังอยากนอนต่ออีกหน่อย... ฟี้...",
  str_voice_1501441_18 = "สวัสดีตอนค่ำ คุณทานมื้อเย็นรึยังนะ?",
  str_voice_1501441_19 = "งืม ๆ... ฟู่... ไทยากิ... อร่อยสุด ๆ... เอ๊ะ? ท่านผู้นำทาง? ยังไม่นอนอีกเหรอ?",
  str_voice_1501441_20 = "เมืองโคฟุโจที่อยู่สูงเสียดฟ้า ควบคุมปีศาจและวิญญาณมาหลายปี ก็ยังหนีไม่พ้นชะตากรรม... หึหึหึ..",
  str_voice_1501441_21 = "สมาชิกเรดีเซล เวรนช์ ทุกคนเป็นพวกชอบเข้าสังคมและไม่มีกฎเกณฑ์เลยงั้นเหรอ? น่ากลัวจริง ๆ นะ!",
  str_voice_1501441_22 = "ฉันไม่มีบ้านให้กลับไปอีกแล้ว",
  str_voice_1501441_23 = "สิ่งน่ากลัวพวกนี้มีอยู่ทุกที่ ฉันไม่อยากต่อสู้กับพวกมัน...",
  str_voice_1501441_24 = "โมโมะกับอันสึดูแลฉันมาตลอดเลย",
  str_voice_1501441_25 = "ท่านรินเนะเป็นผู้สูงสง่าอย่างแท้จริง คนต่ำต้อยอย่างฉัน มิบังอาจไปตีเสมอกับเธอหรอก...",
  str_voice_1501441_26 = "ถ้าฉันอยู่คนเดียวได้ สิ่งนั้นก็จะไปทำร้ายคนอื่นไม่ได้",
  str_voice_1501441_27 = "โคฟุโจฉาบหน้าด้วยงานรื่นเริงและความบันเทิงยามค่ำคืน เพื่อแสดงให้เห็นถึงสันติภาพและความมั่งคั่งจอมปลอม น่าขันและน่าสมเพช... หึหึ...",
  str_voice_1501441_28 = "บนโคลอสซัสมีห้องต่าง ๆ มากมาย... น่าจะมีที่สงบ ๆ อยู่บ้างสินะ",
  str_voice_1501441_29 = "สวัสดี ฉันชื่อคายาโนะ กรุณาอย่ากลัวเลยนะ ฉันจะพยายามควบคุม \"สิ่งนั้น\" ให้ดีที่สุด หวังว่าเราจะไม่รบกวนคุณ",
  str_voice_1501441_30 = "ความอาฆาตทวีความรุนแรงขึ้นแล้ว",
  str_voice_1501441_31 = "ฉัน... แข็งแกร่งขึ้นแล้วนะ",
  str_voice_1501441_32 = "ฉันไม่อยากต่อสู้เลย... ฮือ ๆ...",
  str_voice_1501441_33 = "คุณต้องการสิ่งใดอยู่นะ?",
  str_voice_1501441_34 = "ฉันควรจะออกไปสู้มั้ย?",
  str_voice_1501441_35 = "สิ่งนั้น... ควบคุมไม่ได้แล้ว!",
  str_voice_1501441_36 = "ควบคุมได้ยาก... ฮู้!",
  str_voice_1501441_37 = "โปรดซ่อนตัว!",
  str_voice_1501441_38 = "ความอาฆาตรุนแรงเหลือเกิน... หึหึ...",
  str_voice_1501441_39 = "เล็งตรงนี้แหละ!",
  str_voice_1501441_40 = "โปรดอย่าหนี...",
  str_voice_1501441_41 = "วู้... ฉันเข้าสังคมไม่เก่งเสียด้วยสิ",
  str_voice_1501441_42 = "รอดมาจนได้...",
  str_voice_1501441_43 = "ขอโทษนะ... ฉันอ่อนแอเกินไป...",
  str_voice_1501441_44 = "ขอบคุณที่มาหาฉันนะ ฉันมีความสุขมากเลย",
  str_voice_1501441_45 = "ให้ฉันเหรอ? จริงเหรอเนี่ย?",
  str_voice_1501441_46 = "ฉันไม่รู้ว่าจะตอบแทนยังไงดี...",
  str_voice_1501441_47 = "ฉันโชคดีจริง ๆ ที่มีคุณคอยเป็นห่วง!",
  str_voice_1501441_48 = "ขอบคุณนะ... ฉันชอบมากจริง ๆ... ฮู้!",
  str_voice_1501441_49 = "วัยเด็กของฉัน... มันเต็มไปด้วยเรื่องน่าเบื่อและไร้สาระ ไม่มีอะไรน่าฟังหรอก",
  str_voice_1501441_50 = "ทั้งหมดนั้นคือเรื่องราวในอดีตของฉัน ได้โปรดอย่ารังเกียจฉันเลยนะ",
  str_voice_1501441_51 = "หลายคนช่วยชีวิตฉันไว้ รวมทั้งคุณด้วย ได้โปรดอนุญาตให้ฉันอยู่ที่นี่เถอะนะ",
  str_voice_1501441_52 = "เอ่อ... อัลเคมี่สตาร์?",
  str_voice_1501441_53 = "รอสักครู่นะคะ...",
  str_voice_1501441_54 = "อรุณสวัสดิ์ คุณตื่นหรือยัง?",
  str_voice_1501441_55 = "อืมม... ฉันหิวแล้วล่ะ....",
  str_voice_1501441_56 = "ท่านผู้นำทาง นอนรึยังคะ?",
  str_voice_1501441_57 = "ผ่านไปอีกปีแล้ว รวดเร็วจังเลยนะ...",
  str_voice_1600064_10 = "ยังจ้องฉันอยู่อีกเหรอ? เดี๋ยวฉันก็จับนายแช่เป็นก้อนน้ำแข็งหรอก...",
  str_voice_1600064_11 = "ทิวทัศน์งดงามและลมก็เย็นสบาย... ทำให้นึกถึงนอร์ธแลนด์ ถึงอากาศจะหนาวเย็นแต่ก็รู้สึกผ่อนคลาย ไม่เหมือนที่ลูโมโพลิส",
  str_voice_1600064_16 = "นายต้องทำงานและพักผ่อนให้สมดุลกันนะ หยุดพักมานั่งดื่มกาแฟหรือคุยกับเพื่อนบ้างก็ได้",
  str_voice_1600064_17 = "นายตื่นเช้าจังเลยนะ... ขอให้เป็นแบบนี้เรื่อยไป ยอดเยี่ยมมาก",
  str_voice_1600064_18 = "ทิวทัศน์ตอนกลางคืนบนโคลอสซัสสวยดีนะ เอาไว้ฉันจะพานายไปเที่ยวชมลูโมโพลิสตอนกลางคืนบ้าง",
  str_voice_1600064_19 = "ยังไม่นอนอีกเหรอ? คิดอะไรอยู่? เผื่อว่านายไม่รู้... ฉันน่ะเป็นผู้ฟังที่ดีนะ",
  str_voice_1600064_35 = "ไอหมอกจับตัวเป็นก้อนแล้ว",
  str_voice_1600064_36 = "รอปล่อยไม้ตาย",
  str_voice_1600064_37 = "ปิดฉากการต่อสู้!",
  str_voice_1600064_38 = "แช่แข็งวิญญาณด้วยความหนาวที่กัดกิน!",
  str_voice_1600064_39 = "ลมหนาวสะท้าน",
  str_voice_1600064_40 = "งานเลี้ยงแห่งหิมะ",
  str_voice_1600064_44 = "อย่ามัวแต่จ้องฉันสิ",
  str_voice_1600064_58 = "แม้แต่เพื่อนสนิทก็ยังทะเลาะกันในบางครั้ง คนรักก็เช่นกัน จริงรึเปล่า?",
  str_voice_1600064_59 = "นายต้องพักผ่อนบ้างนะ เครียดอยู่ตลอดเวลาจะบั่นทอนสุขภาพจิต",
  str_voice_1600064_60 = "บางครั้งการคิดอะไรนอกเหนือจากสิ่งเดิม ๆ ลองอะไรใหม่ ๆ และมองเรื่องราวจากมุมที่ต่างออกไปก็อาจจะเป็นประโยชน์นะ",
  str_voice_1600064_61 = "อยากรู้จังนะ ว่าสาว ๆ ในซีกโลกอื่นเขาแต่งตัวกันยังไง",
  str_voice_1600064_62 = "ฉันได้ยินมาว่าที่อัมบราตันเปิดกว้างและทันสมัยมาก แต่ถ้าเปิดกว้างเกินไปจนไม่มีขอบเขต ก็จะนำไปสู่ความเสื่อมทรามในที่สุด",
  str_voice_1600064_63 = "ในการลาดตระเวนเราต้องสง่างามและเป็นมิตร สำคัญที่สุดคือต้องให้ผู้คนรู้สึกถึงความปลอดภัย",
  str_voice_1600064_64 = "เช้านี้บนโคลอสซัสร้อนจังเลยนะ",
  str_voice_1600064_65 = "อรุณสวัสดิ์! นายตื่นแล้วเหรอ",
  str_voice_1600064_66 = "วันนี้ตื่นเช้าจังนะ",
  str_voice_1600064_67 = "ดูเหมือนวันนี้นายจะมีงานเยอะใช่มั้ย...",
  str_voice_1600064_68 = "อ่า... อรุณสวัสดิ์",
  str_voice_1600064_69 = "เช้านี้นายได้ยินอะไรไหม?",
  str_voice_1600064_70 = "ตอนนี้ก็เที่ยงแล้วนะ",
  str_voice_1600064_71 = "มื้อเที่ยงวันนี้เป็นยังไงบ้าง?",
  str_voice_1600064_72 = "นายกินมื้อเที่ยงรึยัง?",
  str_voice_1600064_73 = "พระอาทิตย์ตอนเที่ยงยอดเยี่ยมที่สุดเลย!",
  str_voice_1600064_74 = "ถึงเวลานอนแล้วนะ",
  str_voice_1600064_75 = "ถ้านอนไม่หลับ นายจะทำอะไร?",
  str_voice_1600064_76 = "ท้องฟ้าคืนนี้สวยมาก ๆ เลย",
  str_voice_1600064_77 = "นายหลับสบายดีมั้ย?",
  str_voice_1601451_1 = "คัมภีร์วิชานินจาที่หลังฉันนี้ประกอบด้วยวิชานินจาและการฝึกฝนแปลก ๆ มากมาย อยากเห็นไหมล่ะ? โปรดใช้ด้วยความระมัดระวังอย่างยิ่งนะ ไม่งั้นท่านอาจเสียสติโดยสมบูรณ์ได้ ถือว่าเตือนแล้วนะ",
  str_voice_1601451_2 = "อยากรู้ว่าฉันพกอาวุธกี่ประเภทงั้นเหรอ? พูดตรง ๆ นะ นี่เป็นคำถามที่โง่เขลา อย่าไปถามนินจาคนอื่นล่ะ แล้วท่านจะต้องเสียใจอย่างสุดซึ้ง",
  str_voice_1601451_3 = "ท่านไม่คิดเหรอว่าคุไนเป็นชื่อที่น่าสนใจสำหรับอาวุธ? มันฟังดูไม่น่าจะสร้างความเจ็บปวดอะไรเลยนะ",
  str_voice_1601451_4 = "ท่านจะคิดว่าฉันน่าเบื่อไหมนะ? ฮึ ที่จริงก็ไม่เป็นไรหรอก รอยยิ้มทั้งหมดในโลกนี้ได้รับการปกป้องโดยจิตวิญญาณที่น่าเบื่อ ท่านว่าไหมล่ะ?",
  str_voice_1601451_5 = "ริน เบียว โท ฉะ ไค จิน เร็ทสึ ไซ เซ็น! จำเวทเก้าอักขระนี้ไว้ให้ดี!",
  str_voice_1601451_6 = "วิชานินจามีข้อห้ามสามข้อ ข้อแรก หัวใจแห่งความกลัว ข้อสอง หัวใจแห่งความอับอาย และข้อสาม หัวใจแห่งความกังวล ถ้าวางสามข้อนี้ลงได้ ท่านจะพุ่งโจมตีได้ด้วยความเร็วประหนึ่งสายฟ้า",
  str_voice_1601451_7 = "ท่านเคยได้ยินเสียงต้นข้าวที่พลิ้วไหวเวลาสายลมพัดผ่านไหม? กรอบแกรบ ๆ... ตอนเด็ก ๆ ฉันมักจะฟังเสียงนั้นจนหลับไป แต่วันเวลาที่ไร้ความกังวลช่างสั้นเหลือเกิน ท่านว่าไหม?",
  str_voice_1601451_8 = "ฉันประทับใจมากที่ท่านต้องอดทนอยู่ใต้ดินคนเดียวยาวนานถึง 17 ปี… เรื่องนี้มีคุณค่าจนฉันต้องเขียนลงในคัมภีร์วิชานินจา!",
  str_voice_1601451_9 = "ฉันอาจจะยังอยู่ที่นี่เพื่อปกป้องเกาะเมฆา แม้ว่าชาวเมืองทุกคนจะได้พบกับความสงบและความสุขแล้ว หรือนั่นอาจเป็นเวลาที่ฉันจะได้ร่วมเดินทางไปทั่วโลกกับท่านก็ได้นะ?",
  str_voice_1601451_10 = "ไม่ต้องห่วง ฉันคุ้นเคยกับความเหงาและการรอคอยเป็นอย่างดี ฉันจะรายงานให้ท่านทราบทันทีถ้ามีอะไรไม่ชอบมาพากล",
  str_voice_1601451_11 = "ท่านหมายความว่า... ฉันควรอยู่ที่นี่และเฝ้าระวังศัตรูให้ดีใช่ไหม? ไม่จำเป็นเหรอ? อยากให้ฉันทำอะไรที่ตัวเองอยากทำเนี่ยนะ? นั่นเป็นคำขอที่ยากมากเลย",
  str_voice_1601451_12 = "กรุณาอย่าเข้าใจฉันผิดนะ... ฉันซ่อนตัวอยู่ในความมืดเพราะฉันปรารถนาแสงสว่าง",
  str_voice_1601451_13 = "ฉันเชื่อในโชคชะตา มันพาให้ฉันได้มาเดินบนเส้นทางของวิชานินจา และฉันจะไม่มีวันหันกลับไปมองอดีต",
  str_voice_1601451_14 = "ภายใต้หมวกไม้ไผ่ของฉันมียานอนหลับอยู่ แต่มันไม่ได้มีไว้สำหรับคนที่นอนไม่หลับหรอกนะ",
  str_voice_1601451_15 = "วันนี้วันเกิดของท่านเหรอ? ถ้างั้นต้องฉลองแล้ว",
  str_voice_1601451_16 = "ขอแนะนำว่าท่านไม่ควรแอบดูการฝึกฝนวิชานินจาของฉันนะ นอกจากว่าท่านจะอยากเข้าร่วมสำนักของเรา",
  str_voice_1601451_17 = "ท่านตื่นแล้วเหรอ? หลับปุ๋ยเป็นเด็กน้อยเลยนะ ฉันรู้ได้ไงน่ะเหรอ? ท่านจำอาชีพของฉันไม่ได้หรือไง?",
  str_voice_1601451_18 = "นี่คือเวลาที่ครอบครัวทั่วไปมารวมตัวกัน\nเพื่อรับประทานอาหาร",
  str_voice_1601451_19 = "ยังไม่นอนอีกเหรอ? ถ้าท่านไม่ได้ป้องกันตัวเวลาอยู่กับฉัน ท่านคงอยากฝึกวิชานินจาแน่เลย",
  str_voice_1601451_20 = "ผู้ที่อยู่ในวิถีแห่งวิชานินจาจะไม่ถามเฉพาะเจาะจงเรื่องประวัติศาสตร์",
  str_voice_1601451_21 = "ฉันได้ฟังเรื่องเกี่ยวกับสถานที่ที่ชื่ออัมบราตันที่อยู่อีกฟากหนึ่งของทะเล มันคล้ายกับเป็นแหล่งรวมตัวกันของเหล่านินจามากเลย",
  str_voice_1601451_22 = "เงียบ ๆ เข้าไว้ พยายามอย่าพูดอะไรออกมา",
  str_voice_1601451_23 = "ฉันหวังว่าดวงวิญญาณทั้งหลายจะได้พักผ่อนอย่างสงบสุขในที่สุด",
  str_voice_1601451_24 = "อาจารย์ชุบชีวิตฉัน ฉันยินดีทำทุกอย่างเพื่อเป็นการตอบแทน",
  str_voice_1601451_25 = "เหยาเกิดมาในยุคแห่งความวุ่นวาย ทำไมถึงมีรอยยิ้มที่อบอุ่นไร้เดียงสาได้ขนาดนั้นนะ?",
  str_voice_1601451_26 = "ฉันชอบแช่น้ำร้อน คนแบบฉันจะมีกลิ่นติดตัวไม่ได้ ไม่ว่าหอมหรือเหม็น",
  str_voice_1601451_27 = "สงครามมักมาพร้อมกับคำโกหก การทรยศ และการตายจาก แต่ก็มีแค่อาวุธกับความรุนแรงเท่านั้นที่จะยุติสงครามได้",
  str_voice_1601451_28 = "ครั้งหนึ่งฉันเคยได้ยินนักเล่าเรื่องข้างถนนพูดถึงสัตว์ปีกขนาดยักษ์ในเทพนิยาย จะใช่สิ่งนี้รึเปล่านะ?",
  str_voice_1601451_29 = "รุกล้ำค่ำคืนกับสายลม ซ่อนกายในเงามืด ตระเวนลึกเข้าไปบนภูเขาเมฆา พักผ่อนใต้ฟ้าที่เต็มไปด้วยหมู่ดาว ฉันชื่ออาเมะโมริ ขอบคุณล่วงหน้าสำหรับการชี้แนะ",
  str_voice_1601451_30 = "มีข้อมูลเพิ่มขึ้นในคัมภีร์วิชานินจา",
  str_voice_1601451_31 = "ฉันปาอาวุธลับเก่งขึ้นแล้ว",
  str_voice_1601451_32 = "พลังวิชานินจาอันเร้นลับ!",
  str_voice_1601451_33 = "แม้กลางวันแสก ๆ ฉันก็ซ่อนตัวได้",
  str_voice_1601451_34 = "ฉันซ่อนตัวอยู่ในแถว",
  str_voice_1601451_35 = "ถ้าท่านพร้อม ฉันก็พร้อม",
  str_voice_1601451_36 = "ฉันรออยู่นะ",
  str_voice_1601451_37 = "วิชานินจา! จงทะยานสู่นภา!",
  str_voice_1601451_38 = "วิชาลับ! คาถาสะกดเงา!",
  str_voice_1601451_39 = "วิชานินจาจงเจริญ!",
  str_voice_1601451_40 = "ดาบเหล็กกล้าไร้ปรานี!",
  str_voice_1601451_41 = "น้อมรับบัญชา",
  str_voice_1601451_42 = "ชัยชนะเล็ก ๆ ไม่ควรค่าแก่การฉลอง",
  str_voice_1601451_43 = "การซ่อนตัวหรือหลบหนีไม่ใช่เรื่องน่าอาย จงอยู่รอดให้ได้เพื่อกลับมาต่อสู้อีกครั้ง",
  str_voice_1601451_44 = "บอกฉันหน่อย เส้นทางลับอยู่ที่ไหน?",
  str_voice_1601451_45 = "นี่คือของมัดจำสำหรับเควสต์ถัดไปรึเปล่า?",
  str_voice_1601451_46 = "ฉันชอบสิ่งนี้มากทีเดียว",
  str_voice_1601451_47 = "ขอบคุณสำหรับความกรุณาของท่าน",
  str_voice_1601451_48 = "มีแต่อาจารย์เท่านั้นที่เคยมอบของขวัญล้ำค่าแบบนี้ให้ฉัน",
  str_voice_1601451_49 = "ฉันเกิดมาในครอบครัวชาวไร่ชาวนาในช่วงสงครามบนเกาะเมฆา ฉันจึงไม่ได้หลงใหลในศิลปะการต่อสู้ สิ่งเดียวที่ฉันสนใจคือการเก็บเกี่ยวพืชผล",
  str_voice_1601451_50 = "ตอนที่ทหารจุดไฟเผาหมู่บ้านของเรา เปลวเพลิงสีส้มและเลือดสีแดงเข้มที่พื้นผสมปนเปกันต่อหน้าฉัน คนดี ๆ ไม่ได้มีจุดจบที่สงบสุข... นี่น่ะหรือคือโชคชะตาในท้ายที่สุดของพวกเขา?",
  str_voice_1601451_51 = "ดาบของเธอสะท้อนลำแสงสีขาวอันเยือกเย็น วับวาบต่อหน้าฉัน นั่นคือความหวังเพียงหนึ่งเดียว",
  str_voice_1601451_52 = "Alchemy Stars",
  str_voice_1601451_53 = "ได้สิ",
  str_voice_1601451_54 = "อรุณสวัสดิ์",
  str_voice_1601451_55 = "ด้วยความยินดี",
  str_voice_1601451_56 = "ราตรีสวัสดิ์",
  str_voice_1601451_57 = "ขอให้ปีใหม่นำมาซึ่งผลผลิตที่งอกงาม",
  str_voice_1601461_1 = "ฉันไม่ใช่สาวน้อยหน้าโง่นะ! คนที่พูดแบบนี้กับฉันครั้งล่าสุดต้องคุกเข่าให้กับกำปั้นของฉันมาแล้ว อยากลองไหมล่ะ?",
  str_voice_1601461_2 = "โครก... ซาลาเปาลูกเล็ก ๆ... เกี๊ยว... ขนมจีบ... เป็ดย่าง... คิดถึงทุกอย่างเลย!! แต่ฉันต้องเดินทางเพื่อผดุงความยุติธรรมและช่วยผู้ที่เดือดร้อน ดังนั้นฉันคงต้องข่มความอยากเอาไว้ก่อน...",
  str_voice_1601461_3 = "ถ้าเจอปัญหาก็เรียกฉันได้เลย! แต่บอกไว้ก่อนนะว่าคุณจะต้องเจอดีแน่ ถ้าฉันรู้ว่าคุณเป็นต้นเหตุของปัญหาเสียเอง!",
  str_voice_1601461_4 = "ระวังนะ! ปิ่นปักผมของฉันไม่ใช่แค่เครื่องประดับสวยงามอย่างเดียว ถ้าไม่จำเป็นฉันก็ไม่อยากแตะต้องคนชั่วหรอก เข้าใจมั้ย?",
  str_voice_1601461_5 = "ฉันเป็นจอมยุทธ์ก็เพื่อให้ตัวเองก้าวออกมาผดุงความยุติธรรมได้เมื่อยามจำเป็น ถ้าทำไม่ได้แล้วฉันจะเหลืออะไร?",
  str_voice_1601461_6 = "อ๊ะ! ดูสิ! คุณคิดว่าช่วงนี้กล้ามฉันใหญ่ขึ้นบ้างไหม? เสื้อผ้าฉันเริ่มคับแล้วเนี่ย...",
  str_voice_1601461_7 = "มาจ้องฉันทำไม? อยากฝึกวิชาลมปราณเหรอ? ฮ่าฮ่าฮ่า... มันไม่ได้ง่ายขนาดนั้นนะ คุณต้องมีทั้งความอดทน ความยืดหยุ่น และทักษะที่คล่องแคล่ว!",
  str_voice_1601461_8 = "คุณชอบเต้าหู้ผัดพริกเสฉวนไหมล่ะ? ฉันว่าคุณต้องไม่เคยกินแบบที่อร่อย ๆ แน่เลย! เอาไว้ฉันจะทำให้กินนะ รับรองว่าคุณจะแสบร้อนจากภายใน!",
  str_voice_1601461_9 = "นักรบผู้ยิ่งใหญ่มักเดินทางตามลำพัง! แต่ถ้านักรบผู้ยิ่งใหญ่สองคนร่วมมือกัน... มันก็ฟังดูไม่แย่ใช่ไหมล่ะ??",
  str_voice_1601461_10 = "ในเมื่อคุณดูเหมือนจะไม่มีอะไรทำ... อยากออกกำลังกายกับฉันไหมล่ะ? ก่อนอื่นวิดพื้น 100 ครั้ง จากนั้นก็เตะขาสูง 500 ครั้ง...",
  str_voice_1601461_11 = "ให้ฉันเฝ้ายามที่นี่ไหม? ฉันเก่งเรื่องนี้อยู่นะ ไว้ใจได้เลย! หา? เอาที่สบายใจเหรอ? ได้ ๆ!",
  str_voice_1601461_12 = "ฉันฝึกเตะขาสูงอยู่ ถ้ากล้าก็มาต่อยกันเลย!",
  str_voice_1601461_13 = "หัวใจของคนใจคดเนี่ย น่ากลัวกว่าพวกอิคลิพไซท์อีกนะ ว่าไหม?",
  str_voice_1601461_14 = "คุณชอบเสื้อผ้าฉันไหม? ฉันหาให้คุณสักชุดก็ได้นะ",
  str_voice_1601461_15 = "โอ้ว! วันนี้วันเกิดคุณเหรอ? *อะแฮ่ม* ขอให้มีความสุขมาก ๆ ในวันเกิดนะ!",
  str_voice_1601461_16 = "วันนี้ไม่มีความอยุติธรรมเกิดขึ้น ฉันเลยว่างสุด ๆ ฮ่า",
  str_voice_1601461_17 = "โหยยย! จริงดิ? นี่ฉันไปวิ่งกลับมาแล้ว คุณยังนอนอยู่เนี่ยนะ?",
  str_voice_1601461_18 = "อ้าว! ทำไมยังทำงานอยู่อีกล่ะ? ฉันรอจนเบื่อแล้วนะ... ลุกขึ้นมาออกกำลังกายบ้างเถอะ!",
  str_voice_1601461_19 = "นอนหลับให้เต็มที่ ตื่นมาจะได้สดชื่น ทำตามกฎของธรรมชาติเพื่อชีวิตที่ยืนยาวนะ เอาละ ฉันไปนอนแล้ว",
  str_voice_1601461_20 = "ฉันเกิดมาเพื่อเดินทาง ไม่ใช่เพื่อรับใช้ใคร... ฮ่า นี่แหละนักรบตัวจริง!",
  str_voice_1601461_21 = "เรดีเซล เวรนช์ฟังดูเป็นกลุ่มคนที่กล้าหาญนะ แต่ได้ยินว่ามีสมาชิกพิลึก ๆ เยอะเหลือเกิน จริงรึเปล่า?",
  str_voice_1601461_22 = "คุณธรรมและความยุติธรรมชนะทุกสิ่ง!",
  str_voice_1601461_23 = "มอนสเตอร์จิตใจต่ำช้า... เฮ้อ... แค่คิดถึงพวกมันก็จะอ้วกแล้ว! แต่กำปั้นของฉันจัดการพวกมันได้หมดแหละ!",
  str_voice_1601461_24 = "ท่าทางรอยยิ้มจะสังหารอาเมะโมริได้... น่าเสียดายรอยยิ้มที่งดงามแบบนั้นจัง...",
  str_voice_1601461_25 = "มีใครในอัมบราตันที่ไม่รู้จักเจ้าแห่งเงา? ฉันเชื่อว่าเขาก็เป็นนักรบที่แท้จริงเหมือนกันนะ",
  str_voice_1601461_26 = "ฉันหวงแหนปิ่นปักผมอันนี้มากกว่าสิ่งอื่นใด! จะบอกว่าเป็นอาวุธเพียงอย่างเดียวของฉันก็ว่าได้",
  str_voice_1601461_27 = "บางที่เขาทำอาหารแบบไม่ใส่เกลือเลยนะ! ฉันต้องพกพริกป่นติดตัวเลย",
  str_voice_1601461_28 = "วิธีเดินทางข้ามทะเลที่ดีที่สุด... ดีกว่าเรือเป็นไหน ๆ!",
  str_voice_1601461_29 = "ฉันเคยได้ยินเรื่องของคุณมาเยอะเลย วันนี้เป็นเกียรติจริง ๆ! ฉันชื่อเหยา ขอบคุณสำหรับความช่วยเหลือในอนาคตนะ!",
  str_voice_1601461_30 = "ปล่อยให้อากาศไหลผ่านร่างกาย...",
  str_voice_1601461_31 = "พลังลุกไหม้อยู่ที่ปลายนิ้วฉันนี่!",
  str_voice_1601461_32 = "กล้ามเนื้อต้นขาสั่นใหญ่แล้ว!",
  str_voice_1601461_33 = "โอ้ว! นี่ฉันเปิดทวารทั้งหมดของร่างกายเลยเหรอเนี่ย?",
  str_voice_1601461_34 = "แบบนี้ต้องช่วยได้แน่นอน!",
  str_voice_1601461_35 = "หายใจเข้าลึก ๆ...",
  str_voice_1601461_36 = "ชาร์จพลัง...",
  str_voice_1601461_37 = "จุ๊ ๆ... จิตใจต้องสงบเท่านั้นถึงจะชกได้แม่นยำ ฮ่า!",
  str_voice_1601461_38 = "ฟ้าดินประสานเป็นหนึ่ง บุกหน้าเหมือนผ่าลำไผ่!",
  str_voice_1601461_39 = "จงสำแดงพลัง... กระบวนท่าฝนตกในป่าสน!",
  str_voice_1601461_40 = "จงสำแดงพลัง! เพลงหมัดค้อนศิลา!",
  str_voice_1601461_41 = "นี่แหละคือหน้าที่ของจอมยุทธ์!",
  str_voice_1601461_42 = "กลยุทธ์เล็ก ๆ... ไม่จำเป็นต้องพูดถึงหรอก",
  str_voice_1601461_43 = "ฮึ่มม! สาบานเลยว่าฉันต้องแก้แค้นให้ได้!",
  str_voice_1601461_44 = "ว้าว! ที่นี่เหมาะสำหรับการฝึกฝนที่สุดเลย!",
  str_voice_1601461_45 = "โอ้ว! ให้ฉันเหรอ?",
  str_voice_1601461_46 = "ไม่น่าลำบากเลย... ให้ฉันเก็บไว้เหรอ?",
  str_voice_1601461_47 = "แหม... ไม่น่าลำบากเลยจริง ๆ นะเนี่ย!",
  str_voice_1601461_48 = "ขอบคุณนะ ฉันชอบมากเลย!",
  str_voice_1601461_49 = "ความทรงจำของฉันเริ่มเค็มเหมือนน้ำทะเลแล้ว น้ำเค็มเข้าปาก เข้าจมูก เข้าหูฉันหมดเลย...",
  str_voice_1601461_50 = "พ่อแม่อุปถัมภ์บอกว่าฉันสูญเสียความทรงจำไป เมื่อก่อนฉันเป็นคนยังไง? เคยทำอะไร? เคยไปที่ไหน? ไม่มีใครรู้เลย",
  str_voice_1601461_51 = "ไม่นานฉันก็เริ่มฝึกวิชาลมปราณ คือ ฉันหยุดยั้งจอมยุทธ์ไม่ให้ผงาดฟ้าไม่ได้หรอก ใช่แล้ว จอมยุทธ์ที่ว่าก็คือฉันเอง!",
  str_voice_1601461_52 = "Alchemy Stars!",
  str_voice_1601461_53 = "โหหหห!",
  str_voice_1601461_54 = "ได้เวลาออกกำลังกายตอนเช้าแล้วนะ!",
  str_voice_1601461_55 = "ฮือออ... หิวอะ...",
  str_voice_1601461_56 = "รักษาความแข็งแกร่งและสะสมพลังงานไว้!",
  str_voice_1601461_57 = "ขอให้ปีใหม่นี้เต็มไปด้วยความสุขเหมือนเคยนะ!",
  str_voice_1501471_1 = "- ฉันชื่อโมโมะ เป็นคนคุมห้องครัว\n- ฉันชื่ออันสึ เป็นคนทำบัญชี\n- ถึงเราจะเป็นแฝดเหมือน แต่ก็อย่าจำสลับกันนะ!",
  str_voice_1501471_2 = "- ใครเป็นพี่น่ะเหรอ? ก็ฉันน่ะสิ!\n- เอ๊ย! ฉันต่างหาก!\n-... ฉันแน่นอน!",
  str_voice_1501471_3 = "- อันสึต่อราคาทุกเม็ดเลย ขี้เหนียวมาก!\n- โมโมะกระโดดโลดเต้น เหมือนลิงน้อยเลย!",
  str_voice_1501471_4 = "- แถ่นแท้น! เมนูใหม่ ออกจากเตานึ่งสด ๆ ร้อน ๆ เลยค่ะ!\n- ซาลาเปาคานิยะไส้เนื้อ! ถูกใจแค่ไหนบอกให้เรารู้ที!",
  str_voice_1501471_5 = "- อันสึ อิคลิพไซท์พวกนั้นทำอาหารเสียหายหมดแล้ว!\n- โมโมะ สั่งสอนพวกมันด้วยซาลาเปาไส้เนื้อสูตรพิเศษของเราเลย!",
  str_voice_1501471_6 = "- วันนี้ซาลาเปาไส้อะไรเหรอ?\n- ถั่วรวมมิตร!",
  str_voice_1501471_7 = "- คุณลูกค้าผู้มีเกียรติของเรามาบ่อยเชียวนะเดี๋ยวนี้\n- เป็นลูกค้าประจำไปแล้ว!",
  str_voice_1501471_8 = "- ช่วงนี้คุณดูเหนื่อยนะ\n- เราอบคุกกี้ให้กินดีไหม?\n- ฉันจะไปเตรียมของนะ!",
  str_voice_1501471_9 = "- คุณลูกค้าผู้มีเกียรติของเรามาแล้ว! โมโมะ เตรียมอาหารชั้นเลิศมาเลย!\n- รับทราบ! รับรองไม่ผิดหวัง!",
  str_voice_1501471_10 = "- อันสึ ลูกค้าผู้มีเกียรติของเราหลับไปแล้ว!\n- เราจะพลาดโอกาสนี้ไม่ได้นะโมโมะ เอาวาซาบิมาใส่ราเม็งเร็ว!",
  str_voice_1501471_11 = "- คานิยะ ราเม็ง...\n- สาขาโซรอซ...\n- เปิดตัวอย่างเป็นทางการ!",
  str_voice_1501471_12 = "- เราอาจทะเลาะกันบ้าง\n- แต่ไม่มีวันแยกจากกันเด็ดขาด!",
  str_voice_1501471_13 = "- โซรอซมีชีวิตชีวาดีจัง!\n- ผู้คนคับคั่งตลอดเวลา!",
  str_voice_1501471_14 = "- มาจัดงานเทศกาลกันดีกว่า! เทศกาลราเม็งคานิยะ!\n- ต้องให้คนมาลองกินราเม็งรสเลิศของเราเยอะ ๆ!",
  str_voice_1501471_15 = "- คุณลูกค้าผู้มีเกียรติ สุขสันต์วันเกิดจ้า!\n- เราเตรียมบะหมี่อายุยืนไว้ให้คุณ!",
  str_voice_1501471_16 = "- ยังไม่ถึงเวลาอาหารเหรอ?\n- ยังอีกเหรอ?\n- ฉันรอไม่ไหวแล้วนะ!",
  str_voice_1501471_17 = "- อาหารเช้าวันนี้คือทงคตสึราเม็ง!\n- ไม่มีอะไรสู้น้ำต้มกระดูกของเราได้แน่นอน!",
  str_voice_1501471_18 = "- มื้อเย็นวันนี้มีบะหมี่เกาหลี รับประทานคู่กับเกี๊ยวซ่า!\n- อาหารอร่อยช่วยให้นอนหลับสบายนะ!",
  str_voice_1501471_19 = "- ดึกมากแล้วนะเนี่ย!\n- อยากได้ของกินเล่นยามดึกไหมล่ะ?",
  str_voice_1501471_20 = "- อันสึกับฉันเถียงกันบ่อย\n- แต่เราสองคนรู้ว่าคานิยะ ราเม็งยอดเยี่ยมที่สุด!",
  str_voice_1501471_21 = "- สหพันธรัฐอิลลูมินาเหรอ? รู้จักสิ! พวกเขาอยู่ที่เมืองใต้ดิน!\n- พวกเขาจะชอบกินราเม็งไหมนะ?",
  str_voice_1501471_22 = "- คานิยะ ราเม็ง...\nอร่อยที่สุดในโลก!",
  str_voice_1501471_23 = "- อิคลิพไซท์เหรอ? กินได้มะ? อร่อยรึเปล่า? ปรุงยังไงล่ะ?\n- ฉันก็ไม่รู้เหมือนกัน เรามาลองกันเถอะ!",
  str_voice_1501471_24 = "- พนักงานของเราชอบโดดงานบ่อย ๆ\n- ไปแอบตามมิโกะไงล่ะ!",
  str_voice_1501471_25 = "- ลูกค้าที่สวมกี่เพ้าเป็นกันเองมากเลยนะ\n- เธอช่วยเราไล่ตะเพิดพวกที่มาก่อกวนประจำเลย",
  str_voice_1501471_26 = "- ของโปรดของฉันน่ะเหรอ?\n- ก็ต้องคานิยะ ราเม็งอยู่แล้ว!",
  str_voice_1501471_27 = "- ฉันไม่ชอบกินอะไรที่ไม่อร่อย…\n- และคนที่กินทิ้งกินขว้างนี่แหละแย่ที่สุดเลย!",
  str_voice_1501471_28 = "- เมนูบนยานโซรอซวันนี้น่ะเหรอ?\n- ราเม็ง ราเม็ง แล้วก็ราเม็ง!",
  str_voice_1501471_29 = "- ราเม็งหนึ่งชาม!\n- ขอบคุณที่มาอุดหนุนค่ะ!",
  str_voice_1501471_30 = "- ราเม็งแสนอร่อย...\n- จัดไปอีกชามค่ะ!",
  str_voice_1501471_31 = "- น้ำซุปเข้มข้นขึ้น!\n- ใส่เส้นเยอะกว่าเดิม!",
  str_voice_1501471_32 = "- ปรับปรุงหน้าร้าน!\n- ใช่แล้ว!",
  str_voice_1501471_33 = "- เร่งเตาให้สุดเลย!\n- ระวังไหม้ล่ะ!",
  str_voice_1501471_34 = "- เปิดร้านแล้วจ้า!",
  str_voice_1501471_35 = "- ราเม็งของคุณได้แล้วนะ!",
  str_voice_1501471_36 = "- รีบกินให้อร่อยตอนร้อน ๆ สิ!",
  str_voice_1501471_37 = "- เสิร์ฟจ้า!",
  str_voice_1501471_38 = "- ดีลักซ์...\n- ใหญ่พิเศษ...\n- คานิยะ ราเม็ง!",
  str_voice_1501471_39 = "- เปลวเพลิงจู่โจม!",
  str_voice_1501471_40 = "- เอากระทะไปเลย!",
  str_voice_1501471_41 = "- ได้เวลากินราเม็งแล้ว!",
  str_voice_1501471_42 = "- ขอบคุณที่อุดหนุน!\n- ถ้าอร่อยก็บอกต่อเพื่อน ๆ ด้วยนะ!",
  str_voice_1501471_43 = "- บะหมี่น้ำ…\n- หกหมดแล้ว…",
  str_voice_1501471_44 = "- รายงาน! เราเจอห้องครัวแล้ว!\n- ฮิฮิ! เราจะดูแลเรื่องอาหารให้คุณทั้งหมดนับแต่นี้เป็นต้นไป!",
  str_voice_1501471_45 = "- ของขวัญ!\n- ขอบคุณนะคะ!",
  str_voice_1501471_46 = "- นี่มันแพงมากเลยนะ!\n- ให้พวกเราจะดีเหรอ?",
  str_voice_1501471_47 = "- เก็บไว้ตรงไหนดีล่ะ?\n- ไว้ในร้านไง!",
  str_voice_1501471_48 = "- โปรดรับคูปองอาหารฟรีนี้ไว้เถอะค่ะ!\n- เป็นของขวัญตอบแทนจากเรา!",
  str_voice_1501471_49 = "- เราไม่ได้ขายแค่ราเม็งอย่างเดียวนะ!\n- ซาลาเปากับเกี๊ยวก็มี! สูตรเด็ดที่สุดในโลกเลย!",
  str_voice_1501471_50 = "- ในน้ำเต้านี่แหละคือเคล็ดลับของน้ำซุปรสเลิศ!\n- น้ำพุภูเขาเหรอ?\n- อันสึ! อย่าพูดความลับของฉันออกมาแบบนั้น!",
  str_voice_1501471_51 = "- หัวใจหลักของอาหารแสนอร่อยคือความตั้งใจ\n- และความรัก!\n- แล้วก็มิตรภาพที่เหนียวแน่น!",
  str_voice_1501471_52 = "- Alchemy—\n- Stars!",
  str_voice_1501471_53 = "- เปิดร้านอย่างเป็นทางการแล้ว!",
  str_voice_1501471_54 = "- ตื่นค่ะตื่น! อาหารเช้าพร้อมแล้ว!",
  str_voice_1501471_55 = "- คุณลูกค้าผู้มีเกียรติของเรากินอาหารกลางวันหรือยัง?",
  str_voice_1501471_56 = "- เย็นนี้อยากกินอะไรเอ่ย?",
  str_voice_1501471_57 = "- สุขสันต์วันปีใหม่!\n- บะหมี่ชามแรกของปีใหม่พร้อมแล้วนะ!\n- เป็นราเม็งทะเล!",
  str_voice_1201631_1 = "ฝึกสมองกันหน่อย! หมาอะไรชอบไปดูงานแสดงศิลปะ? คำตอบก็คือ Tourdog ไง ผมอยากได้ทุกชิ้นงานมาไว้ที่นี่เลย...",
  str_voice_1201631_2 = "เป็นเรือบินที่ใหญ่ชะมัดเลย! น่าจะเรียกว่าเรือเหาะสิ ทำไมเรียกว่าโคลอสซัสล่ะ?",
  str_voice_1201631_3 = "ผมไม่ติดขัดที่จะสะท้อนความเป็นจริงในผลงานนะ แต่ใส่ความฝันเข้าไปหน่อยก็ดี งานที่ปราศจากความฝันมันจืดชืดเกินไป...",
  str_voice_1201631_4 = "ทำใหม่เหรอ? ไม่มีทาง... ก็ได้ แต่ผมจะได้ค่าจ้างเพิ่มรึเปล่า?",
  str_voice_1201631_5 = "นักวาดต้องการพื้นที่ เพื่อทำงานในอุดมคติให้เสร็จสมบูรณ์อย่างอิสระ...",
  str_voice_1201631_6 = "สีดำที่สดใสและมีชีวิตชีวาเหรอ?... เดี๋ยวจะลองดูนะ",
  str_voice_1201631_7 = "เรื่องราวน่าจะเศร้าหมองแต่ทรงพลัง กล้าหาญ และยิ่งใหญ่…",
  str_voice_1201631_8 = "ฟังนะ เพราะมีผู้อุปถัมภ์ ผมถึงมุ่งเน้นเรื่องเกมกับผู้สนับสนุนต่าง ๆ ได้ ผมคิดว่าชาวลูโมโพลิส... หมายถึงอัมบราตันน่ะ ก็ไม่ได้ตาบอดสนิทหรอกนะ",
  str_voice_1201631_9 = "ที่นอร์ธแลนด์อากาศหนาวมาก แต่ออโรราก็สวยอลังการเหลือเกิน… และนั่นคือจุดเริ่มต้นความฝันสำหรับ Al***my St**s",
  str_voice_1201631_10 = "ทำ Al***my St**s เป็นแอนิเมชัน... ผมต้องร่างคร่าว ๆ ก่อนนะ ไม่สิ! ต้องสรุปเรื่องย่อก่อน",
  str_voice_1201631_11 = "ดูแลสถานที่เหรอ? ได้สิ ผมมีประสบการณ์เรื่องนี้ตอนทำงานพาร์ทไทม์ เป็นโอกาสเหมาะที่จะศึกษาอุปกรณ์ทั้งหลายที่นี่ด้วย...",
  str_voice_1201631_12 = "ผมเชิญชวนผู้สนับสนุนไปอื้อซ่าเลยในช่วงสองสามวันที่ผ่านมา... ตอนนี้แทบไม่มีเงินซื้อเสื้อโค้ทละ เจ้าของเรือเหาะ รบกวนขอยืมเสื้อผ้าหน่อยได้ไหม?",
  str_voice_1201631_13 = "งานวาดบางส่วนก็สวยจนน่าทึ่ง แต่อารมณ์โดยรวมมันไม่เหมาะกับโครงการของเรา คงจะดีถ้าเอาไปใช้งานได้ แต่เราจะไม่ฝืนเด็ดขาด",
  str_voice_1201631_14 = "บางคนก็มาถามหานักลงทุนกับผม... ผมจะไปรู้ได้ไงล่ะ? พวกเขาน่าจะลองไปคุยกับคุณนายเชโอลผู้มั่งคั่งดูนะ",
  str_voice_1201631_15 = "สุขสันต์วันเกิดครับ ผมไม่มีเค้กมาให้ แต่จะวาดให้เดี๋ยวนี้เลยนะ...",
  str_voice_1201631_16 = "วันทำงานที่วุ่นวายกำลังจะเริ่มอีกครั้ง คุณต้องเอาอยู่",
  str_voice_1201631_17 = "คุณตื่นเช้าดีนะ ขยันจัง! การดูแลยานลำนี้คงจะเป็นความฝันของคุณใช่ไหม",
  str_voice_1201631_18 = "ยังทำงานอยู่เหรอ? อย่าลืมหาอะไรกินด้วยล่ะ สุขภาพสำคัญกว่าสิ่งอื่นใดนะ",
  str_voice_1201631_19 = "นี่คุณไม่ได้พักเลยเหรอ? ผมทำอะไรไม่ไหวแล้วเนี่ย… อ่อยย...",
  str_voice_1201631_20 = "อืมมม อัมบราตัน... พวกเราหลายคนมีรสนิยมดีในด้านศิลปะ แต่บางคนก็ขี้อวดไปหน่อย",
  str_voice_1201631_21 = "พวกคนแก่ ๆ ในลูโมโพลิสเข้มงวดมากก็จริง แต่พวกเขาตาถึงในเรื่องความงามนะ เพราะยังไงการหาเงินก็สำคัญมาก",
  str_voice_1201631_22 = "ความสำเร็จย่อมเป็นของผู้ที่ลงมือทำในทันที",
  str_voice_1201631_23 = "ผมว่าเรามีความคิดเห็นเรื่องศิลปะที่แตกต่างกัน...",
  str_voice_1201631_24 = "ทาคิน่ะดูเหมือนจ้องจะเอาเงินอย่างเดียว แต่ที่จริงเขาใส่ใจรายละเอียดและตาถึงมาก ๆ ในเรื่องของความงาม",
  str_voice_1201631_25 = "ฮาชิกับกินเหรอ? พวกนั้นเป็นโจรใจดำที่ชอบเอาภาพวาดมาขาย ถึงจะเจอภาพดี ๆ อยู่บ้างก็เถอะ...",
  str_voice_1201631_26 = "มีนักวาดภาพอยู่ที่นี่เหรอ รีบแนะนำให้ผมรู้จักเร็วเข้า...",
  str_voice_1201631_27 = "ผมเบื่อหน่ายกับพวกที่ไม่เต็มที่กับเรื่องงานศิลปะ",
  str_voice_1201631_28 = "ว้าว ที่นี่มีอุปกรณ์เต็มไปหมดเลย เราอาจจะนำมาใช้กับ Al***my St**s ก็ได้นะ...",
  str_voice_1201631_29 = "คุณวาดภาพเป็นไหม? หรือรู้จักใครที่วาดเป็นบ้าง? ผมชื่อ Tourdog กำลังหาคนมาเข้าร่วมโครงการอยู่ โครงการ Al***my St**s ไงล่ะ...",
  str_voice_1201631_30 = "ผมสัมผัสได้!",
  str_voice_1201631_31 = "ขออะไรก็จัดให้ได้ทั้งนั้น",
  str_voice_1201631_32 = "ใช้เวลาแค่ 3 วินาทีเท่านั้น",
  str_voice_1201631_33 = "ฮ่า! คืบหน้ามากเลย!",
  str_voice_1201631_34 = "ได้เวลาทำงานแล้ว...",
  str_voice_1201631_35 = "ผมมีวัตถุดิบครบหมดแล้ว",
  str_voice_1201631_36 = "ถ้าคุณพร้อม ผมก็พร้อม",
  str_voice_1201631_37 = "ลงมือกันเลย!",
  str_voice_1201631_38 = "ตั้งใจหน่อย!",
  str_voice_1201631_39 = "โอ้! น่ารักจัง!",
  str_voice_1201631_40 = "โชคดีนะ!",
  str_voice_1201631_41 = "ผมทำได้สบายมาก!",
  str_voice_1201631_42 = "ใกล้เป้าหมายเข้าไปอีกก้าวหนึ่งแล้ว!",
  str_voice_1201631_43 = "เอ่อ... ช่วยปลอบใจผมหน่อยสิ...",
  str_voice_1201631_44 = "มาเล่น Al***my St**s กันเถอะ!",
  str_voice_1201631_45 = "ถ้าเป็นภาพวาดสวย ๆ ก็ดีสิ...",
  str_voice_1201631_46 = "ผมจะเพิ่มเข้าไปใน Al***my St**s นะ",
  str_voice_1201631_47 = "เอาไอดีทดสอบเบต้าของ Al***my St**s ไปเลยครับ!",
  str_voice_1201631_48 = "โอ้วววว! แรงบันดาลใจเต็ม ๆ เลย!",
  str_voice_1201631_49 = "ก่อนหน้านี้ผมสำรวจซากโบราณอยู่ แล้วบังเอิญเจออุปกรณ์ชิ้นนั้น ก็เลยเริ่มทำ Al***my St**s",
  str_voice_1201631_50 = "สองสามปีแรกที่ทำเกมมันท้าทายมากจริง ๆ ผมคงยังไม่แข็งแกร่งพอน่ะ... โชคดีที่ต่อมาผมได้รู้จักกับเพื่อนกลุ่มใหม่ เขาช่วยเหลือเยอะมาก แม้แต่ดึงนักลงทุนมาให้ด้วย",
  str_voice_1201631_51 = "ผมได้แรงบันดาลใจจากออโรรา เพราะผมเกิดที่นอร์ธแลนด์ แต่คู่มือเกมนำทางให้ผมมาที่อัมบราตัน",
  str_voice_1201631_52 = "Alchemy Stars",
  str_voice_1201631_53 = "ด้วยความยินดี",
  str_voice_1201631_54 = "ได้เวลาวาดภาพแล้ว!",
  str_voice_1201631_55 = "งีบเหรอ? ผมไม่มีสิทธิพิเศษแบบนั้นหรอก!",
  str_voice_1201631_56 = "ผมทำงานดึกนิดหน่อยน่ะ",
  str_voice_1201631_57 = "ขอให้มีความสุขในวันปีใหม่นะครับ!",
  str_voice_1601481_1 = "เธอขับรถเป็นไหม? ถ้าเธอสนใจที่จะเรียน ฉันสอนเธอได้นะ ฉันเป็นนักขับรถรุ่นเก๋ามาก และมีคนน้อยนักที่จะเอาชนะฉันได้ในการแข่งรถ",
  str_voice_1601481_2 = "เอ่อ เธอดูจะสนิทกับเด็กผู้หญิงที่มาจากทั้งอิลลูมินาและลูโมโพลิสนะ เธอมีดีอะไรอยู่แน่ ๆ ใช่ไหม? ระวังตัวให้ดีล่ะ พ่อคนดัง อย่าทำอะไรที่มันบ้าระห่ำจนเกินไป",
  str_voice_1601481_3 = "ฉันชอบเป็นหมาป่าเดียวดาย ไม่มีใครดึงฉันไว้ และไม่มีใครทำให้ผิดหวังได้... เหงาเหรอ? ไม่เลย ฉันมีดาวเต็มผืนทะเลกับลมแห่งความแห้งแล้งเป็นเพื่อน",
  str_voice_1601481_4 = "ฉันลองขับยานพาหนะมาแล้วทุกชนิด แต่โคลอสซัสที่เหาะได้น่ะเหรอ? นี่เป็นครั้งแรกที่ฉันได้เห็นมันล่ะ ถ้าฉันลองขับดูจะเป็นไง... หือ? เวลาลงจอดมันจะยากหน่อยเปล่า?",
  str_voice_1601481_5 = "เฮ้ ช่วยแสดง \"ความสามารถด้านพลังจิต\" ของเธอให้ฉันดูหน่อยสิ? เธอรู้ไหมว่าฉันกำลังคิดอะไรอยู่ตอนนี้? กลัวเหรอ? แหม น่าเบื่อจัง",
  str_voice_1601481_6 = "ในเมื่อพวกเขาทั้งหมดเรียกเธอว่า \"ผู้นำทาง\" ทำไมเธอไม่ลองมาเป็นผู้นำทางของฉันในแรลลี่เพลิงลุกโชนดูล่ะ? ของฉันเท่านั้น และของฉันแต่เพียงผู้เดียว... ฮ่าฮ่า หน้าเธอแดงก่ำแล้วอ่ะ!",
  str_voice_1601481_7 = "เธอนี่ไม่กลัวที่จะเข้าใกล้ฉันและเป็นกันเองตลอดเลย ไม่เหมือนพวกแอบมองที่คอยจ้องฉันอยู่ไกล ๆ เธอสมควรได้รับรางวัลล่ะ... เข้ามาใกล้ ๆ สิ",
  str_voice_1601481_8 = "ฉันเคยพูดว่าฉันชอบที่จะเป็นหมาป่าเดียวดาย แต่ถ้าเธออยากได้ที่ไปสูดอากาศดี ๆ... ที่นั่งผู้โดยสารของฉันว่างเสมอสำหรับเธอนะ",
  str_voice_1601481_9 = "มันก็นานมาแล้วนะตั้งแต่มีคนเรียกชื่อจริงของฉันว่าซาเฟีย... เธอจะเรียกแบบนั้นอีกครั้งได้ไหม? คิดเสียว่าฉันเมาละกัน",
  str_voice_1601481_10 = "เธอตั้งใจจะปล่อยฉันทิ้งไว้แบบนี้จริง ๆ เหรอ? ฉันจะให้เวลาเธอคิดถึงสถานภาพตัวเองสามวินาที",
  str_voice_1601481_11 = "อยากให้ฉันอยู่ที่นี่เหรอ? น่าเบื่อจะตายไป ทำไมไม่ทำอะไรที่มันสนุก ๆ ด้วยกันล่ะ?",
  str_voice_1601481_12 = "เจ้าพวกโหวกเหวกจากเรดีเซล เวรนช์เป็นตัวแก้เบื่อได้อย่างดีเลย เธอก็เหมือนกัน",
  str_voice_1601481_13 = "มีอะไรใหม่ไหม? อ๊ะ อย่าเก็บไว้คนเดียวสิ! ไม่มีสิ่งใดมีค่าเท่ากับข่าวกรองในโลกนี้อีกแล้ว",
  str_voice_1601481_14 = "เธอต้องการอะไรจากฉันล่ะ? มาวอแวไม่เลิกไม่ทำให้อะไรดีขึ้นหรอก... แต่เธอนี่น่ารักจัง เดี๋ยวฉันจะมองให้เป็นเรื่องอื่น แต่แค่ครั้งนี้เท่านั้นนะ",
  str_voice_1601481_15 = "สุขสันต์วันเกิด! แต่ฉันไม่มีของขวัญให้เธอน่ะสิ เอาตัวฉันมอบเป็นของขวัญแทนได้เปล่า? แค่ล้อเล่นน่า",
  str_voice_1601481_16 = "อยากไปล่าข่าวกรองกับฉันไหม? การสืบสวนแบบจริงจังคือก้าวแรกของการสำรวจใด ๆ ล่ะ",
  str_voice_1601481_17 = "โอ๊ะ? ไม่ต้องตีก้นก็ลุกจากเตียงได้แล้ว? เป็นเด็กดีนะเนี่ย",
  str_voice_1601481_18 = "อ้า ได้เวลาหาสถานที่ชิล ๆ ซะแล้ว สนใจเปล่า? อย่ามัวแต่โอ้เอ้ล่ะ ฉันไม่รอหรอกนะ",
  str_voice_1601481_19 = "ช่างน่าผิดหวังจริง ๆ เลย ฉันก็แค่หวังว่าจะจับเธอมานอนโอ๋ให้เหมือนเด็กน้อย... แต่ในเมื่อเธอตื่นแล้ว... คืนนี้ยังอีกยาวไกลนัก เธอเข้าใจใช่ป่ะ",
  str_voice_1601481_20 = "เรดีเซล เวรนช์คือครอบครัวของฉัน แม้ฉันจะไม่ได้กลับไปหาพวกเขาบ่อยนัก แต่ความผูกพันนี้... ได้ส่งฉันไปให้ไกลยิ่งขึ้น",
  str_voice_1601481_21 = "ประวัติศาสตร์ที่ฉันแบ่งปันกับพวกเขา... ไม่ใช่อะไรที่สามารถเล่าได้หมดในแก้วหรือสองแก้ว",
  str_voice_1601481_22 = "ใช้ชีวิตให้เต็มที่! ก็อาจจะนะ",
  str_voice_1601481_23 = "พวกอิคลิพไซท์เหรอ... ขอแค่พวกสารเลวนั่นไม่เคยมีอยู่",
  str_voice_1601481_24 = "มีแค่โจนาจากพวกเรดีเซล เวรนช์ทั้งหมดที่สามารถดื่มกับฉันได้จริง ๆ ส่วนรอยน่ะเหรอ? เขาควบคุมตัวเองไม่ได้เวลาเมาเลย",
  str_voice_1601481_25 = "ฉันไม่คิดว่ารอยในวันนั้นจะกลายเป็นคนขี้บ่นในวันนี้ได้... เธออย่าได้เอาอย่างเขาเชียวล่ะ",
  str_voice_1601481_26 = "ฉันชอบอะไรน่ะเหรอ? ก็ต้องเด็กผู้ชายน่ารัก ๆ น่ะสิ อย่าห่วงไปน่า ฉันไม่กินเธอหรอก... แค่ยังไม่ต่างหากล่ะ",
  str_voice_1601481_27 = "ฉันได้ยินว่าลูโมโพลิสและอิลลูมินามีกฎระเบียบและข้อจำกัดมากมาย... แค่คิดก็ไม่อยากอยู่แล้ว",
  str_voice_1601481_28 = "โคลอสซัสที่ใหญ่ขนาดนั้นยังรักษาไว้ให้อยู่ในสภาพดีได้... ฉันบอกได้เลยว่าเธอดูแลมันได้ยอดเยี่ยมมาก",
  str_voice_1601481_29 = "อ่ะฮ้า! เธอต้องเป็นเคเลสไทต์ที่พวกเขาพูดถึงแน่เลย ฉันอยากจะบอกว่า หน้าตาน่ารัก ๆ ของเธอมันไม่เข้ากะชื่อโง่ ๆ นี่เลย ไหนเข้ามาใกล้ ๆ หน่อยสิได้เปล่า?",
  str_voice_1601481_30 = "เอาอีก... เอาอีก!",
  str_voice_1601481_31 = "น่าตื่นเต้นจัง~",
  str_voice_1601481_32 = "อย่างกับว่าฉันดื่มไวน์ไปซะหลายขวดเลย...",
  str_voice_1601481_33 = "นี่เป็นครั้งแรกที่ฉันรู้สึกแบบนี้...",
  str_voice_1601481_34 = "เธอเพิ่งจะคิดถึงฉันเดี๋ยวนี้เหรอ?",
  str_voice_1601481_35 = "อย่าปล่อยให้ฉันรอสิ",
  str_voice_1601481_36 = "แมวป่าไม่เคยหลับใหล",
  str_voice_1601481_37 = "ยิงเลย ภาพลวงตาสีคราม!",
  str_voice_1601481_38 = "จุดเยือกแข็ง!",
  str_voice_1601481_39 = "เฮ้ เธอไม่รู้สึกร้อนหรือไง?",
  str_voice_1601481_40 = "ขอเย็น ๆ หน่อย!",
  str_voice_1601481_41 = "ก็ได้ เธอตอบแทนฉันมาก่อนดีกว่า",
  str_voice_1601481_42 = "ฉะนั้นเธอตั้งใจจะตอบแทนฉันยังไงล่ะ?",
  str_voice_1601481_43 = "อีกที! อย่าหยุด!",
  str_voice_1601481_44 = "เราจะไปขี่ยานโคลอสซัสของเธอกินลมกันไหม?",
  str_voice_1601481_45 = "ฉันรู้น่า เธอก็แจกให้ผู้หญิงสวย ๆ เยอะแยะด้วย ใช่ไหมล่ะ?",
  str_voice_1601481_46 = "เธอรู้ใจอยู่ฉันนะ... เธอวางแผนจะทำอะไรกับฉันเอ่ย?",
  str_voice_1601481_47 = "ขอบใจนะ เด็กดี มาใกล้ ๆ หน่อยสิ *จ๊วบ*",
  str_voice_1601481_48 = "ช่างเอาใจใส่จังเลย ฉันจริงจังกับเธอแล้วนะ รู้ไหม? ห้ามหลอกผู้ใหญ่ล่ะ",
  str_voice_1601481_49 = "ฉันเริ่มเล่นปืนตั้งแต่อยู่ในท้องแม่แล้ว! น่าเสียใจตรงที่ฉันหาพยานมายืนยันไม่ได้",
  str_voice_1601481_50 = "เธอนึกถึงสภาพหมดอาลัยตายอยากที่ต้องลากฝีเท้าไปตามทะเลทรายที่ไม่สิ้นสุด โดยหาทางกลับบ้านไม่เจอ... หรือหาตัวเธอเองไม่เจอไหม?",
  str_voice_1601481_51 = "ฉันไม่อยากให้ประวัติศาสตร์ซ้ำรอย... ตอนนี้เรดีเซล เวรนช์คือบ้านของฉันแล้ว และฉันจะปกป้องมันไว้ด้วยวิธีของฉันเอง",
  str_voice_1601481_52 = "Alchemy Stars!",
  str_voice_1601481_53 = "ว่าไง",
  str_voice_1601481_54 = "อรุณสวัสดิ์",
  str_voice_1601481_55 = "ดื่มกับฉันสักแก้วไหม?",
  str_voice_1601481_56 = "อ้าว! สายัณห์สวัสดิ์!",
  str_voice_1601481_57 = "สุขสันต์วันปีใหม่! อยากอวดการเติบโตในปีนี้เหรอ? ฉันจะตั้งหน้าตั้งตารอชมล่ะ!",
  str_voice_1501491_1 = "ความลับของหน่วยพลาธิการ? ไม่มีความลับหรอก... ถ้าจะมี... ก็คือกะเวรที่ยาวนานไม่มีที่สิ้นสุดล่ะมั้ง? เฮอะ? ฟังดูไม่เหมือนความลับของเรดีเซล เวรนช์เหรอ? ฮ่าฮ่าฮ่า... นายพูดถูก",
  str_voice_1501491_2 = "ฉันประกอบ \"สวีทตี้\" ขึ้นจากอะไหล่ที่เก็บมาได้ โดยที่ฉันเองก็ไม่รู้ว่ามันจะใช้งานได้ไหม ฉันแค่โชคดีน่ะ... ชื่อน่ารักเหรอ? อืม เซต้าตั้งให้น่ะ",
  str_voice_1501491_3 = "คาราวานที่อัมบราตันฉลาดขึ้นแล้ว ตอนนี้เราเลยต้องเปลี่ยนกลยุทธ์ล่ะ หือ? นายสนใจเรื่องการวางแผนซุ่มตีเหรอ? นายรู้วิธีอ่านแผนที่ทอพอโลยีไหมล่ะ? ฉันจะสอนนายให้เอง",
  str_voice_1501491_4 = "แม้ว่าฉันจะอยากทำตุ๊กตาของเล่นให้นาย แต่โคลอสซัสนี่เป็นอะไรที่เกินความสามารถของฉันนะ เอาแค่อิคลิพไซท์แตงโมได้เปล่า?",
  str_voice_1501491_5 = "สกิล CQC? ได้เลย แต่นายต้องฟังฉันนะ ตกลงไหม? สาดทรายไปที่ลูกตาของศัตรู จากนั้นก็ลอบโจมตีซะ! มันสำเร็จทุกครั้งเลย! ขี้โกง? ชัยชนะคือเรื่องสำคัญเหนือสิ่งอื่นใดไม่ใช่รึ?",
  str_voice_1501491_6 = "ถ้าคนของนายได้อยู่ที่นี่ในยุคที่เกิดสงครามล่ะก็ วันนี้ทุกสิ่งคงต่างออกไป... นายไม่เข้าใจสิ่งที่ฉันพูดเหรอ? นี่คือ \"ช่องว่างระหว่างวัย\" ที่ผู้คนเขาว่ากันใช่ไหมนะ?",
  str_voice_1501491_7 = "พ่อหนุ่ม นายไม่พิจารณาการเข้าร่วมเรดีเซล เวรนช์อีกครั้งเหรอ? แย่จังเลยนะ ประตูของเราเปิดกว้างสำหรับนายเสมอ",
  str_voice_1501491_8 = "ฉันคือคนที่ผูกติดอยู่กับอดีต ฉันจะปล่อยให้นายไปเป็นฮีโร่กอบกู้โลกแทนละกัน ขนาดแค่ต้องรักษาสิ่งที่มีอยู่ ฉันยังต้องแลกกับทุกอย่างเลย",
  str_voice_1501491_9 = "เอ้อ... เวลาอายุมากขึ้นก็ไม่ใช่เป็นแบบนี้หรอกหรือ? เสียใจกับอดีต... ปล่อยมันไปไม่ได้ แต่การสร้างความทรงจำใหม่กับนายก็ไม่เลวเลยนะ",
  str_voice_1501491_10 = "เฮ้ มีเวลาคุยกันไหม? นายอยากได้ยินเรื่องเกี่ยวกับอิคลิพไซท์เพิ่ม หรืออยากรู้วิธีเอาตัวรอดในทะเลทรายรึเปล่า? อย่าปล่อยฉันไว้คนเดียวที่นี่สิ! ฉันเหงามากเลยนะ!",
  str_voice_1501491_11 = "มาขอให้ใครบางคนอย่างฉันยืนเฉย ๆ อยู่ที่นี่เนี่ยนะ? คนหนุ่มสาวสมัยนี้ช่างประหลาดจริงแฮะ... แต่ไม่เป็นไรล่ะ ฉันจะดูแลนายและแก้ไขปัญหาให้นายเอง",
  str_voice_1501491_12 = "ต่อสู้เหรอ? ฉันยังพอมีฝีมืออยู่ คิดว่านะ แต่หลังของฉัน... โอย สังขารช่างไม่เที่ยงเลย",
  str_voice_1501491_13 = "อยากได้ลูกกวาดเหรอ? ฉันมีในกระเป๋าเพียบเลย ฉันแนะนำรสแมงป่องสีแดงล่ะ!",
  str_voice_1501491_14 = "ซื้ด... หืม? ฮ่าฮ่า! ไม่มีไร ฉันแค่ฝันร้ายเมื่อคืนก่อนน่ะ ไม่มีอะไรหรอก",
  str_voice_1501491_15 = "วันนี้เป็นวันเกิดของนายเหรอ? ต้องจัดใหญ่ล่ะ! เราต้องจัดปาร์ตี้ให้ใหญ่ ๆ เลย!",
  str_voice_1501491_16 = "วันนี้เป็นวันที่ยุ่งอีกแล้ว... ฉันอยากจะอู้จัง... นายก็อย่าหักโหมมากนักล่ะ",
  str_voice_1501491_17 = "รู้ยัง! หายากที่จะเห็นคนหนุ่มสาวตื่นเช้าแบบนี้ อย่างน้อยก็ในที่ของเรา...",
  str_voice_1501491_18 = "วันนี้เป็นไงมั่ง? นายยังกินและนอนเหมือนเดิมแม้ว่าจะมีเรื่องรบกวนนายรึเปล่า",
  str_voice_1501491_19 = "ได้เวลานอนสำหรับเด็กดีแล้ว นอนไม่หลับเหรอ? อยากฟังนิทานก่อนนอนไหมอ่า?",
  str_voice_1501491_20 = "ฉันจะทำทุกสิ่งเพื่อเรดีเซล เวรนช์",
  str_voice_1501491_21 = "อิลลูมินา...? ฉันไม่คุ้นเคยกับมันเท่าไรนะ แต่ฉันรู้เส้นทางเสบียงทั้งหมดเลย",
  str_voice_1501491_22 = "ใช้ชีวิตให้เต็มที่!",
  str_voice_1501491_23 = "ทำไมฉันถึงรู้จักอิคลิพไซท์ดีขนาดนี้งั้นเหรอ? ก็เพราะว่า... มะ-ไม่มีอะไร",
  str_voice_1501491_24 = "แน่ล่ะ แอเชอร์ดูแลตัวเธอเองได้ แต่โปรดจำไว้ว่า เขียนจดหมายกลับมาบ้างสิ ไม่ใช่ส่งมาแต่ข้อมูล",
  str_voice_1501491_25 = "ผู้ชายอย่างซินซาช่างเป็นผู้นำที่ดี บุกไปข้างหน้าและไม่มีวันถอยหลังกลับ",
  str_voice_1501491_26 = "การทำตุ๊กตาของเล่นเป็นการบำบัดที่ดี จริง ๆ นะ! มันแค่น่าอายที่จะบอก...",
  str_voice_1501491_27 = "ฉันเกลียดอะไรเหรอ? เมื่อนายอายุเท่าฉัน นายก็จะรู้เองว่าไม่มีอะไรที่ต้องเกลียดอีกต่อไปแล้ว",
  str_voice_1501491_28 = "โอ้โห! นายดูแลสภาพของโคลอสซัสไว้ได้สุดยอดมาก",
  str_voice_1501491_29 = "เฮ้! ฉันคือรอยแห่งเรดีเซล เวรนช์ ฉันต้องขอโทษด้วยสำหรับปัญหาทั้งหมดที่เจ้าตัวน้อยพวกนั้นสร้างขึ้น อ่ะฮ่าฮ่า! ดีใจที่ได้เจอนายนะ!",
  str_voice_1501491_30 = "อืม อ่า รู้สึกดีมากเลย!",
  str_voice_1501491_31 = "แต่นายไม่ควรจะคาดหวังมากจากชายแก่เช่นฉัน...",
  str_voice_1501491_32 = "อืม... มันทำให้ฉันรู้สึกหนุ่มขึ้นมาอีกครั้ง ก็นิดนึงอ่ะ",
  str_voice_1501491_33 = "ความรับผิดชอบมากขึ้น...?",
  str_voice_1501491_34 = "ทายสิว่าฉันต้องขยันทำงานสักหน่อยแล้ว",
  str_voice_1501491_35 = "เรียกหาฉันได้ทุกเมื่อเลย",
  str_voice_1501491_36 = "อ้าว นายต้องการอะไร?",
  str_voice_1501491_37 = "อืม... ขอดูก่อน...",
  str_voice_1501491_38 = "ได้เวลาเติมกลูโคสกันหน่อยแล้ว",
  str_voice_1501491_39 = "เอาไปกินซะ!",
  str_voice_1501491_40 = "นั่นมันน่ากลัวมากเลย... เปล่าซะหน่อย!",
  str_voice_1501491_41 = "ตาฉันเหรอ? จริงอ่ะ? ก็ได้...",
  str_voice_1501491_42 = "เนี่ย ฉันก็ได้พยายามสุด ๆ แล้ว",
  str_voice_1501491_43 = "เจ้าหนู นายไม่เป็นไรนะ?",
  str_voice_1501491_44 = "ให้ฉันดัดแปลงโคลอสซัสของนาย แล้วเพิ่มฟังก์ชันใหม่ ๆ เข้าไปให้นายไหม?",
  str_voice_1501491_45 = "ตกลง ก็ได้ ครั้งต่อไปอย่าทำตัวเป็นคนแปลกหน้าอีกนะ",
  str_voice_1501491_46 = "โอ๊ะ? นี่มันเป็นของล้ำค่าล่ะ นายแน่ใจที่จะมอบให้ฉันเหรอ?",
  str_voice_1501491_47 = "นายควรเก็บไว้เพื่อมอบให้คนที่นายใส่ใจนะ รู้ไหม...?",
  str_voice_1501491_48 = "ฉันควรจ่ายตอบแทนให้นายล่ะ นายอยากได้อะไรเอ่ย? ขอมาได้ทุกอย่างเลย...",
  str_voice_1501491_49 = "เด็กพวกนั้นเป็นพวกเอาใจยาก แล้วก็ซนเอาเรื่องด้วย แต่พวกเขาเป็นคนดีนะ ฉันปกป้องพวกเขาเกินไปเหรอ? เอ้อ... ก็อาจจะนะ... นิดหน่อยเองน่า",
  str_voice_1501491_50 = "เอ่อ ซินซาได้กลายมาเป็นผู้นำที่ดีแล้วจริง ๆ... อ้อ แล้วนายล่ะ อยากอ่านกลอนที่เขาแต่งตอนเป็นเด็กไหม? น่ารักดีนะ!",
  str_voice_1501491_51 = "เหตุผลที่เข้าร่วมเรดีเซล เวรนช์น่ะเหรอ? เอ่อ ใครบางคนพูดว่า \"มาสร้างครอบครัวใหญ่ที่มีความสุขด้วยกัน\" อย่างคนโง่เถอะ... ฉันก็เลยเข้าร่วมเหมือนคนโง่ไง",
  str_voice_1501491_52 = "Alchemy Stars!",
  str_voice_1501491_53 = "พักนี้เป็นไงมั่ง?",
  str_voice_1501491_54 = "อรุณสวัสดิ์ พ่อหนุ่ม!",
  str_voice_1501491_55 = "อย่าลืมทานอาหารเที่ยงนะ!",
  str_voice_1501491_56 = "คนเราต้องพักผ่อนให้อิ่มตอนกลางคืน จะได้ตัวโตและแข็งแรง",
  str_voice_1501491_57 = "สุขสันต์วันปีใหม่ เคเลสไทต์!",
  str_voice_1601501_1 = "คนอย่างฉัน จะให้เชื่อฟังก็ได้ แต่ไม่ใช่กับทุกคน นั่นทำให้ฉันเป็นคนขวางโลกรึเปล่า?",
  str_voice_1601501_2 = "มหัศจรรย์มากเลยนะที่น้ำไหลออกมาจากดวงตาได้ด้วย ฉันน่ะชอบน้ำตามากเลย แต่ใคร ๆ ก็บอกว่าน้ำตาเป็นสิ่งที่แสดงถึงความเศร้าเสมอ... ความเศร้านี่เป็นความรู้สึกที่ไม่ดีเหรอ?",
  str_voice_1601501_3 = "ในโลกนี้มีแม่ ๆ ตั้งมากมายหลายคน... แล้วแม่ของฉันเป็นคนพิเศษรึเปล่า?",
  str_voice_1601501_4 = "ฉันท้องร้องใหญ่แล้ว นี่เหรอคือความหิว? ความรู้สึกนี้มหัศจรรย์มาก เหมือนมีคนพูดออกมาจากในร่างกายฉันเลย",
  str_voice_1601501_5 = "ผู้นำทางจะกลัวไหมถ้าฉันมีรูปลักษณ์แบบเดิมน่ะ? ตอนนี้ฉันเข้าใจเรื่องความกลัวแล้ว... ฉันไม่อยากทำให้ใครกลัว",
  str_voice_1601501_6 = "ฉันเป็นใคร? ฉันมาจากไหน? ฉันจะไปไหน? ผู้นำทาง คำถามพวกนี้จะทำให้เธอปวดหัวเหมือนที่ฉันเป็นไหมเนี่ย?",
  str_voice_1601501_7 = "ผู้นำทางบอกเสมอว่าฉันไม่ต้องเชื่อฟังใคร แต่ฉันเลือกที่จะฟังเขา และฉันอยากให้ผู้นำทางบอกฉันว่าต้องทำอะไรบ้าง",
  str_voice_1601501_8 = "เมื่อไรก็ตามที่ผู้นำทางมองฉัน ฉันจะเผลอเอามือไปจับหูโดยไม่รู้ตัว แปลกจัง! ยังกับคาถาวิเศษแน่ะ... อ๋อ! นั่นน่ะเหรอที่เรียกว่าอาย?",
  str_voice_1601501_9 = "ฉันได้รับความรู้สึกนี้จากผู้นำทางที่ฉันอยากเรียนรู้มานานแล้ว ผู้นำทาง นี่ใช่ความรักจากแม่ไหม?",
  str_voice_1601501_10 = "อยู่นี่นะ ฉันน่ะเก่งงานแบบนี้มากเลย ฉันเคยอยู่แต่กับบ้านแล้วก็ดูแลบ้านให้แม่กับเมย์ด้วย",
  str_voice_1601501_11 = "เข้าใจแล้ว คำสั่งใดก็ตามจากผู้นำทางจะต้องลุล่วง",
  str_voice_1601501_12 = "บางทีฉันก็คิดถึงเมย์ขึ้นมานะ ฉันเดาว่าเมย์คงกำลังตัดแต่งขนให้แมวสีขาวของเธออยู่ เมย์ไม่ชอบให้ขนแมวพันกัน",
  str_voice_1601501_13 = "... อวัยวะที่สำคัญที่สุดคือหัวใจหรือสมองเหรอ?",
  str_voice_1601501_14 = "ฉันควรทำยังไงดี? ถ้าไม่มีคำสั่งให้ปฏิบัติตาม ฉันก็ไม่รู้จะทำอะไรน่ะ",
  str_voice_1601501_15 = "วันเกิดคือวันที่ยิ่งใหญ่ ฉันขอให้เธอมีความสุขนะผู้นำทาง",
  str_voice_1601501_16 = "ฉันฝึกหายใจอยู่ สูดเอาอากาศเย็น ๆ แล้วไป จากนั้นก็ผ่อนลมหายใจอุ่น ๆ ออกมา",
  str_voice_1601501_17 = "พอรุ่งสาง โลกก็กลับมามีชีวิตอีกครั้ง ฉันก็เลยกลับมามีชีวิตอีกครั้ง... นี่ฉันพูดอะไรผิดอีกรึเปล่า?",
  str_voice_1601501_18 = "อย่าลืมล้างหน้าแปรงฟันด้วยนะ ขอโทษที ฉันชินที่ต้องพูดแบบนี้ในเวลานี้น่ะ",
  str_voice_1601501_19 = "ฉันยังไม่ชินกับการหลับตานอนในเวลากลางคืนเลย... เธอรู้สึกเหมือนฉันไหมผู้นำทาง?",
  str_voice_1601501_20 = "ฉันเป็นสมาชิกของทรู ออเดอร์ ทุกวันฉันภาวนาเพื่อความจริง",
  str_voice_1601501_21 = "ฉันได้ยินเรื่องนอร์ธแลนด์มาจากในหนังสือนิทาน เธอรู้จักไหม หนังสือที่เด็ก ๆ ชอบอ่านกันน่ะ",
  str_voice_1601501_22 = "ขอความจริง... จงสถิตกับท่าน",
  str_voice_1601501_23 = "หลายคนขอให้ฉันช่วยจัดการกับพวกนั้น เขาเรียกพวกมันว่าอิคลิพไซท์",
  str_voice_1601501_24 = "เมย์คือน้องสาวของฉัน... ฉันควรดูแลเธอไม่ว่าจะมีคำสั่งจากแม่หรือไม่มีก็ตามใช่ไหม?",
  str_voice_1601501_25 = "ท่านหญิงวิกตอเรียเป็นคนชวนฉันมาที่ทรู ออเดอร์ ฉันจะฟังทุกอย่างที่เธอพูด",
  str_voice_1601501_26 = "การชอบอะไรสักอย่างมันรู้สึกยังไงเหรอ? มันจะทำให้ฉันมีความสุขไหม?",
  str_voice_1601501_27 = "ฉันรู้จักความรู้สึกไม่ชอบ ฉันรู้สึกได้เวลาที่ฉันต้องดิ้นรนทำงานอะไรสักอย่างให้สำเร็จ",
  str_voice_1601501_28 = "บ้านหลังใหญ่แล้วก็รถอีกคัน",
  str_voice_1601501_29 = "ในที่สุด! ฉันรอคำสั่งจากผู้นำทางมาตั้งนานแล้ว เธอไม่มีคำสั่งให้ฉันเหรอ? เควสต์ก็ไม่มีด้วย?",
  str_voice_1601501_30 = "ฉันรู้สึกมีความสุขจัง",
  str_voice_1601501_31 = "ความรู้สึกตึงเครียด",
  str_voice_1601501_32 = "เหมือนได้เปลี่ยนชิ้นส่วนไปหลายชิ้น",
  str_voice_1601501_33 = "นี่มันใช้ได้เลยนะ ฉันชอบมากเลย",
  str_voice_1601501_34 = "โอเค เข้าใจแล้ว",
  str_voice_1601501_35 = "ฉันพร้อมแล้ว",
  str_voice_1601501_36 = "ฉันรอคำสั่งคุณอยู่",
  str_voice_1601501_37 = "จะคลื่นจะลมอะไรก็มาได้เลย",
  str_voice_1601501_38 = "ที่นี่คือถิ่นของฉัน",
  str_voice_1601501_39 = "เคียวสีเลือดนี่คมมากเลยนะ",
  str_voice_1601501_40 = "ไม่เคยพลาดเป้าหมายแม้แต่ครั้งเดียว",
  str_voice_1601501_41 = "ฉันเป็นหัวหน้า เข้าใจแล้ว",
  str_voice_1601501_42 = "รายงาน! ฉันทำเควสต์สำเร็จแล้ว",
  str_voice_1601501_43 = "ฉันจะไม่ยอมแพ้ ฉันจะพยายามต่อไป",
  str_voice_1601501_44 = "มันมีอารมณ์ความรู้สึกไหม?",
  str_voice_1601501_45 = "ของขวัญธรรมดาทั่วไปให้ฉัน ขอบคุณนะ",
  str_voice_1601501_46 = "ของขวัญที่น่ารักให้ฉัน ขอบคุณนะ",
  str_voice_1601501_47 = "เข้าใจแล้ว… ฉันไม่ควรแสดงความคิดเห็นเรื่องของขวัญสินะ",
  str_voice_1601501_48 = "ฉันชอบมากเลย ขอบคุณนะผู้นำทาง",
  str_voice_1601501_49 = "แม่สั่งให้ฉันดูแลเด็กน้อยที่มีชื่อว่าเมย์... เด็กน้อยร้องไห้เวลาที่ไม่มีใครดูแล ฉันจำไม่ได้ว่าเคยมีใครดูแลฉันบ้างรึเปล่า",
  str_voice_1601501_50 = "ก่อนหน้านั้น ฉันคิดว่าแม่นี่เป็นชื่อ หลังจากนั้นฉันถึงได้รู้ว่าแม่ก็คือ... แค่แม่เฉย ๆ",
  str_voice_1601501_51 = "แม่ไม่อยู่บ้าน เมย์ก็ไม่อยู่เหมือนกัน ฉันทำงานเสร็จไปหมดแล้วแต่ก็ไม่มีใครกลับมา ฉันก็เลยเปลี่ยนชิ้นส่วนทั้งหมดของฉัน 502 ครั้ง",
  str_voice_1601501_52 = "Alchemy... Stars",
  str_voice_1601501_53 = "สวัสดี",
  str_voice_1601501_54 = "ขอให้เป็นเช้าที่สดใสนะผู้นำทาง",
  str_voice_1601501_55 = "เที่ยงแล้ว เธอหิวหรือยังผู้นำทาง?",
  str_voice_1601501_56 = "สวัสดีตอนค่ำ",
  str_voice_1601501_57 = "ปีใหม่นี่แตกต่างจากอดีตเสมอเลยเหรอ?",
  str_voice_1601511_1 = "ลูกแกะสีดำนั่นชื่อไอแซค ขนร้อน ๆ ของเขาน่ากลัวมาก... นี่! นายฟังอยู่หรือเปล่าเนี่ย",
  str_voice_1601511_2 = "นายรู้จักเด็กพวกนั้นที่ลูโมโพลิสไหม? ชื่ออะไรกันบ้างนะ? กุ๊กไก่? เอ้ก-อี๊-เอ้ก-เอ้ก? ไม่สิ! ไม่ใช่... อย่าให้ฉันเจออีกทีนะ ไม่งั้นฉันจับมาร้องเพลงกล่อมเด็กของฉันจริง ๆ ด้วย!",
  str_voice_1601511_3 = "ทำไมอีกาถึงเหมือนกับโต๊ะ? นายไม่รู้คำตอบเหรอ? อืมม... ทำไมล่ะ? หัวจะปวดเฟ่ย!",
  str_voice_1601511_4 = "หาว... ช่วงนี้ฉันง่วงบ่อยจังเลย ฉันต้องกำลังโตแน่นอน... ใช่แล้ว เดี๋ยวฉันก็จะสูงกว่าผู้นำทางแล้ว...",
  str_voice_1601511_5 = "เขาแกะนั่นไม่สามารถเก็บกักพลังที่มากขึ้นได้อีกต่อไปแล้ว ในดวงตาแดง ๆ นั่น ฉันมองเห็นคำโกหกทะลุปรุโปร่งเลย!",
  str_voice_1601511_6 = "เขาแหลม ๆ ฉีกทึ้งม่านแห่งสายัณห์ให้เปิดออก แม็กม่าร้อน ๆ ที่แผดเผาไหลไปตามดินแดนที่แตกระแหง ที่เบื้องลึกในหัวของฉันนี้คือเมล็ดพันธุ์แห่งความจริง!",
  str_voice_1601511_7 = "ฉันคิดว่านายชอบไอแซคมากเลยนะ แต่ฉันปล่อยเขาไปไม่ได้หรอก! เขาช่วยชีวิตฉันไว้! คุณไม่ได้ตั้งใจจะเอาตัวเขาไปเหรอ?",
  str_voice_1601511_8 = "หนึ่งบวกหนึ่งเท่ากับสอง นายกับฉันเมื่ออยู่ด้วยกันก็ยิ่งกว่าสอง ปริศนาคล้องจองนี้มีคำตอบมากมาย มาเถอะน่า อย่างน้อยก็ให้คำตอบฉันสักคำ",
  str_voice_1601511_9 = "ฉันไม่เป็นไร จู่ ๆ ฉันก็รู้สึกมีแรงบันดาลใจขึ้นมา! ต้องแต่งเพลงกล่อมเด็กใหม่สักเพลง! ขอบคุณนะผู้นำทางที่รักของฉัน สำหรับแรงบันดาลใจ",
  str_voice_1601511_10 = "ติ๊กต่อก ได้เวลาวิ่งแล้ว ชะวับชะแว้บ ฟาดลงที่จอ ที่สุดขอบจอใหญ่ มีผู้นำทางยืนอยู่ ข้างหลังผู้นำทางนั้นเป็นใครกัน?",
  str_voice_1601511_11 = "หืมม? ที่นี่มีเนื้อสัตว์ให้กินไหม? อะไรก็ได้ที่ไม่ใช่ลูกแกะ... ไม่มีเลยเหรอ?",
  str_voice_1601511_12 = "ฉันไม่มีอะไรนอกจากเพลงกล่อมเด็ก... เพลงกล่อมเด็กของฉันทำให้ฉันร่ำรวย! ฮ่า ฮ่าฮ่าฮ่าฮ่า!",
  str_voice_1601511_13 = "แบ๊ะ... ทำไมทำหน้างั้นล่ะ? นี่คือภาษาของไอแซค เพื่อแสดงความเคารพต่อไอแซค แบ๊ะพร้อมกับฉันสิ",
  str_voice_1601511_14 = "ฉันไม่ใช่คนเพี้ยนนะ! แฮ่ก แฮ่ก... ฝันร้ายอีกแล้ว ฉันหวังว่าฉันไม่ได้ทำให้นายกลัวนะ หาว... ฉันต้องนอนต่ออีกหน่อย",
  str_voice_1601511_15 = "สุขสันต์วันเกิด! เดี๋ยวฉันเอาแม็กม่ามาเตรียมการแสดงดอกไม้ไฟให้ดูนะ!",
  str_voice_1601511_16 = "นายยุ่งอะไรได้ทุกวันเนี่ย? หืมม... น่าเบื่อ... หาว... ฉันร้องเพลงกล่อมเด็กให้ฟังเอาไหม?",
  str_voice_1601511_17 = "หาว... อืมม การนอนนี่มันสบายจริง ๆ... วันนี้ไม่ค่อยมีอะไร งั้นฉันนอนต่ออีกนิดแล้วกัน",
  str_voice_1601511_18 = "แถ่นแท้น! นี่คือเวลาอาหารเย็นที่รอคอย! ค่ำคืนนี้เราจะกินเนื้อสัตว์หรือว่าเนื้อสัตว์กันล่ะ?",
  str_voice_1601511_19 = "มีคนไม่หลับไม่นอนในชั่วโมงที่สมบูรณ์แบบนี้! หาว... ช่างเถอะ ฉันไม่เห็นอะไรทั้งนั้น",
  str_voice_1601511_20 = "สมาชิกของทรู ออเดอร์บางคนเข้าใจเพลงกล่อมเด็กได้จริง ๆ ซะด้วย ดีกว่าที่อื่น ๆ เยอะเลย",
  str_voice_1601511_21 = "ลูโมโพลิส... ลูโมโพลิส! หนาวเย็น... ห่วงใย! รังเกียจกันไป... ปล่อยฉันนะ! ไม่ ฉันไม่มีวันกลับไปที่นั่น! ไม่มีวัน!",
  str_voice_1601511_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1601511_23 = "อิคลิพไซท์กับพวกเรามีแรงดึงดูดเข้าหากันเหมือนแม่เหล็กสองชิ้น... เป็นชะตาชีวิตของเราที่ต้องตามหาและทำลายซึ่งกันและกัน ฮ่าฮ่าฮ่าฮ่า!",
  str_voice_1601511_24 = "ไม่มีใครรู้จักฉันดีไปกว่าวิกตอเรีย พี่สาวของฉัน ใช่แล้ว! ฉันต้องแต่งเพลงกล่อมเด็กเพลงใหม่ให้เธอ!",
  str_voice_1601511_25 = "เฟาสต์ยิ้มแย้มเสมอ แต่พูดตรง ๆ ฉันไม่คิดว่าเขาจะเข้าใจเพลงกล่อมเด็กของฉันเลยสักนิด",
  str_voice_1601511_26 = "หือ? นายต้องถามคำถามนี้จริง ๆ น่ะเหรอ? ฉันชอบเพลงกล่อมเด็กน่ะสิ อะไรอีกน่ะเหรอ? ชอบนอนมั้งฉันว่า",
  str_voice_1601511_27 = "สองคนนั้นไม่ยอมฟังเพลงกล่อมเด็กของฉัน แย่ที่สุดเลย... นี่ อย่าบอกนะว่านายก็เป็นหนึ่งในนั้นด้วย!",
  str_voice_1601511_28 = "หาว...โคลอสซัสเหรอ? เตียงเคลื่อนที่... ฉันจะนอนหลับได้ดีขึ้นไหม? หาว...",
  str_voice_1601511_29 = "นี่ ผู้นำทาง หาว... เอ้อ! นายมาถึงนี่เพื่อฟังเพลงกล่อมเด็กของฉันใช่ไหม? เยี่ยมมาก เยี่ยมมาก เยี่ยมมาก!",
  str_voice_1601511_30 = "มาดูเลย! ฮ่าฮ่าฮ่า!",
  str_voice_1601511_31 = "ใช่แล้ว! ฉันเพิ่งแต่งเพลงกล่อมเด็กเพลงใหม่ขึ้นมา!",
  str_voice_1601511_32 = "เป็นความรู้สึกที่วิเศษมาก!",
  str_voice_1601511_33 = "พลังที่ไม่อาจเก็บกักควบคุม!",
  str_voice_1601511_34 = "หืมม? ใกล้จบแล้วเหรอ?",
  str_voice_1601511_35 = "อย่าลืมปลุกฉันนะ ตกลงไหม?",
  str_voice_1601511_36 = "ฉันนอนไปแล้ว",
  str_voice_1601511_37 = "ไอแซค ไปกันต่อเถอะ!",
  str_voice_1601511_38 = "เดี๋ยวจะสั่งสอนให้!",
  str_voice_1601511_39 = "ระเบิดแม็กม่า!",
  str_voice_1601511_40 = "เขมือบให้หมดเลยเจ้าแม็กม่า!",
  str_voice_1601511_41 = "หัวหน้าเหรอ? ฮ่าฮ่าฮ่า แปลว่าทุกคนจะฟังฉันสิ!",
  str_voice_1601511_42 = "ฉันขอกลับไปนอนได้ไหม?",
  str_voice_1601511_43 = "น่าเบื่อ... น่าเบื่อ น่าเบื่อ และน่าเบื่อ!",
  str_voice_1601511_44 = "ฉันยิ้มให้เขา แต่เขาไม่ได้ยิ้มตอบ กระจกนี่สะท้อนได้น่าสนใจมาก",
  str_voice_1601511_45 = "หาว... หืมม ฉันจะรับไว้เอง",
  str_voice_1601511_46 = "วู้ฮู้! ขอบใจนะ!",
  str_voice_1601511_47 = "หืมม? ได้สิ เดี๋ยวฉันรับไว้เอง",
  str_voice_1601511_48 = "เยี่ยมเลย!",
  str_voice_1601511_49 = "ในความเห็นฉัน คนพวกที่ไม่มีจุดประสงค์อะไรเลยในชีวิตนี่แปลกเกินไปนะ ความหมายของชีวิตควรได้รับการกำหนดมาตั้งแต่เกิดไม่ใช่เหรอ?",
  str_voice_1601511_50 = "ผู้ชายคนนั้นสัญญาว่าฉันจะได้ผจญภัย มันกลายเป็นการเดินทางครั้งแรกของฉัน... เอ้อออ... จากนั้นเขาก็ผลักไสฉัน อัปยศ! อัปยศ!",
  str_voice_1601511_51 = "การใช้ชีวิตแบบคนเร่ร่อนไม่ได้เลวร้าย แต่พี่วิกตอเรียได้เตรียมเตียงนอนแสนสบายไว้ให้ฉันแล้ว!",
  str_voice_1601511_52 = "Alchemy Stars...",
  str_voice_1601511_53 = "ฮ้าววววว...",
  str_voice_1601511_54 = "อรุณสวัสดิ์ ลูกแกะของฉัน",
  str_voice_1601511_55 = "อาหารอร่อย ๆ พร้อมแล้ว!",
  str_voice_1601511_56 = "ในที่สุดก็ได้เวลานอนสักที...",
  str_voice_1601511_57 = "ปีใหม่อันหอมหวาน ปีใหม่อันแสนวิเศษ ปีใหม่ก็ต้องมีเพลงกล่อมเด็กใหม่ ๆ! โย่!",
  str_voice_1501521_1 = "คุณมองฉันทำไม? มองไปทางอื่นเลยนะ ไม่งั้นเถาวัลย์ของฉันจะทิ่มเข้าให้! คุณไม่กลัวเหรอ? งั้นคราวหน้าฉันต้องลองอย่างอื่นซะแล้ว...",
  str_voice_1501521_2 = "รอยเย็บของฉันน่ะเหรอ? ฮ่าฮ่า แต่ละอันไม่เหมือนกันด้วยนะ สวยไหมล่ะ? เชิญคุณลองได้เลยนะ",
  str_voice_1501521_3 = "นั่นไง นั่นไงมิสเตอร์โบที่น่ารักของฉัน... อ๋อ! อย่าเข้าในผิดนะ ฉันคุยกับมิสเตอร์โบของฉันอยู่ คุณไม่เห็นเจ้าก่อนขนปุยนี่หรือไง?",
  str_voice_1501521_4 = "ขนที่มิสเตอร์โบผลัดออกมานี่เยี่ยมที่สุดเลยนะ เอาไปทำด้ายได้อย่างเหนียวเลย หรือคุณคิดว่าฉันเอาด้ายจากไหนมาเย็บผ้ากันล่ะ?",
  str_voice_1501521_5 = "คุณคิดว่าตำแหน่งของฉันในทรู ออเดอร์คืออะไรงั้นรึ? เดี๋ยวก่อน! ฉันยังไม่พร้อม... ไว้คราวหลังค่อยเล่าให้ฉันฟังนะ",
  str_voice_1501521_6 = "คุณเข้าใจไหมว่าเด็กที่ทำตัวดีเขาได้รับคำชมกันทั้งนั้น? แค่ก ๆ... ตาคุณแล้ว คุณควรพูดอะไรดีนะ? หืมม... ฉันว่าคุณยังไม่เข้าใจแฮะ",
  str_voice_1501521_7 = "ผู้นำทาง คุณไม่พูดกับฉันมา 68 วินาทีแล้วนะ ฉันอยู่ข้าง ๆ คุณนี่แต่คุณไม่มีอะไรจะพูดกับฉัน... คุณรำคาญฉันเหรอ?",
  str_voice_1501521_8 = "หืมม... ฉันไม่เป็นไร แค่คิดถึงปัญหาที่จริงจังเฉย ๆ มิสเตอร์โบของฉันควรเรียกคุณว่าคุณลุงหรือคุณตาดีล่ะ?",
  str_voice_1501521_9 = "จุ๊ ๆ... ฉันมีความลับสุดยอดจะบอกให้คุณรู้ ฉันสะสมหนวดแมวไว้ในกระเป๋าไปใบนี้เต็มเลย จะได้โชคดีไง!",
  str_voice_1501521_10 = "ฉันไม่เคยขี้เกียจแม้กระทั่งในเวลาว่าง ผู้นำทาง สัญญากับฉันสิ! อย่าลืมนะว่าฉันอยู่ที่นี่",
  str_voice_1501521_11 = "นี่คือเควสต์ใหม่สำหรับฉันเหรอ? คนเขาจะชอบฉันกันไหมถ้าฉันทำได้สำเร็จ?",
  str_voice_1501521_12 = "ทำไมเมื่อกี๊คนที่เดินผ่านไปต้องชายตามองฉันด้วยล่ะ? เขาต้องมีปัญหากับฉันแน่เลย...",
  str_voice_1501521_13 = "มิสเตอร์โบ หยุดนะ! เจ้าตัวน้อยนี่ชอบวิ่ง ฉันเป็นห่วงจะแย่",
  str_voice_1501521_14 = "น้องสาวตัวเล็กนั่นยิ้มให้ฉัน... ฉันทำยังไงดี?",
  str_voice_1501521_15 = "มีคนอวยพรวันเกิดคุณตั้งหลายคน... ฉันอิจฉาจังเลย...",
  str_voice_1501521_16 = "มิสเตอร์โบของฉันชอบนอนตอนกลางวัน แล้วของคุณล่ะ? อ๋อ... คุณไม่มีลูกเลยหรอ? น่าสงสารจัง",
  str_voice_1501521_17 = "มิสเตอร์โบของฉันตื่นเช้า คนเป็นแม่อย่างฉันก็ต้องตื่นให้เช้ายิ่งกว่า ไม่มีเวลาคุยเล่นแล้ว ฉันต้องเตรียมอาหารเช้าให้มิสเตอร์โบ",
  str_voice_1501521_18 = "อย่าลืมล้างหน้าแปรงฟันก่อนเข้านอนนะ! ใครสอนฉันมาน่ะเหรอ? เรื่องนั้นไม่สำคัญหรอก",
  str_voice_1501521_19 = "ทำไมคุณถึงชอบเดินไปเดินมาตอนกลางคืน เหมือนมิสเตอร์โบของฉันไม่มีผิดเลย?",
  str_voice_1501521_20 = "ทรู ออเดอร์คือบ้านของฉันและบ้านของมิสเตอร์โบ ความจริงคือสิ่งที่เราพักพิงได้เสมอ",
  str_voice_1501521_21 = "ฉันได้ยินว่าลูโมโพลิสยอมรับความจริงไม่ค่อยได้ แปลกจังเลย!",
  str_voice_1501521_22 = "ขอความจริงจงสถิตกับท่าน ฮ่าฮ่า",
  str_voice_1501521_23 = "อิคลิพไซท์โจมตีฉันทันทีเมื่อไรก็ตามที่พวกมันเห็นฉันเข้า ฉันว่าพวกมันเกลียดฉันแน่นอน... ฉันไม่สนใจหรอก ฉันเกลียดพวกมันมากกว่าซะอีก",
  str_voice_1501521_24 = "เลนอร์... ถ้าปราศจากความรู้สึก เธอก็ไม่ใช่อะไรนอกจากตุ๊กตาธรรมดา อย่าไปเสียเวลากับเธอเลย",
  str_voice_1501521_25 = "ถ้าฉันโด่งดังได้เหมือนคุณเจเนวีฟก็ดีสิ... แค่ก ๆ... เมื่อกี๊คุณไม่ได้ยินอะไรทั้งนั้น!",
  str_voice_1501521_26 = "นี่คุณหลงรักใครอยู่รึเปล่า? ฉันช่วยจับคุณสองคนเย็บติดกันได้นะ ฮ่าฮ่า",
  str_voice_1501521_27 = "อ้าว! ขนมิสเตอร์โบพันกันอีกแล้ว โทษทีนะ หม่าม้าทำให้หนูผิดหวัง หม่าม้าขอโทษทีจ้ะ!",
  str_voice_1501521_28 = "โคลอสซัสชอบฉันรึเปล่า? ถ้ามันชอบฉัน ฉันก็จะชอบมันกลับคืน",
  str_voice_1501521_29 = "ฮ่าฮ่าฮ่า ฉันนึกว่าผู้นำทางเป็นรูปร่างอะไรสักอย่างที่น่าประทับใจซะอีก เขาเองก็หนีไม่พ้นจากเงื้อมมือของฉันเหมือนกัน หืออ? อะไรนะ? คุณมาหาฉันเหรอ?",
  str_voice_1501521_30 = "ฉันดีใจมากเลย",
  str_voice_1501521_31 = "ใกล้เข้ามาแล้ว... ใกล้เข้ามายิ่งกว่าเดิมแล้ว!",
  str_voice_1501521_32 = "ความรู้สึกนี้... นี่คือความจริงเหรอ?",
  str_voice_1501521_33 = "เถาวัลย์กำลังโต",
  str_voice_1501521_34 = "แค่ก ๆ... ฉันว่าก็น่าจะได้นะ",
  str_voice_1501521_35 = "เถาวัลย์นี่กลับมามีชีวิตแล้ว",
  str_voice_1501521_36 = "เราจะทำเชือกหรือทำแส้กันดี?",
  str_voice_1501521_37 = "เด็กดื้อ เตรียมตัวโดนทำโทษได้เลย!",
  str_voice_1501521_38 = "ดอกไม้ดอกใหญ่ให้คุณ",
  str_voice_1501521_39 = "น่ารำคาญมาก!",
  str_voice_1501521_40 = "เดินทางปลอดภัยนะ!",
  str_voice_1501521_41 = "ฉัน... ฉันไม่กลัวหรอก",
  str_voice_1501521_42 = "เมื่อกี๊ฉันเป็นยังไงบ้าง? เยี่ยมไปเลยใช่ไหม?",
  str_voice_1501521_43 = "ไม่นะ นี่ไม่ใช่ความผิดฉัน...",
  str_voice_1501521_44 = "อื้ม... ที่นี่ดูสนุกแฮะ",
  str_voice_1501521_45 = "นี่มันงานอะไรกัน?",
  str_voice_1501521_46 = "ของขวัญให้ฉันเหรอ?",
  str_voice_1501521_47 = "ขอบคุณนะ... ปู! นั่นปูใช่ไหม?",
  str_voice_1501521_48 = "ฉันจะเย็บติดไว้ในกระเป๋าเลย",
  str_voice_1501521_49 = "หมาม้าของมิสเตอร์โบก็คือเมย์ แม่ของเมย์น่ะเหรอ? ฉันจำไม่ได้แล้วว่าหน้าตาเป็นยังไง",
  str_voice_1501521_50 = "ตอนที่ฉันเห็นเจ้าตัวน่าสงสารนั่น ฉันคิดขึ้นมาได้ทันที... ฉันอาจไม่ใช่เจ้าตัวน้อยที่น่ารักของใคร แต่ฉันมีเจ้าตัวน้อยที่น่ารักเป็นของตัวเองได้!",
  str_voice_1501521_51 = "ฉันไม่ต้องการการยอมรับจากแม่ของฉันอีกต่อไปแล้ว การยอมรับจากทรู ออเดอร์เป็นเรื่องจริงแท้และศักดิ์สิทธิ์โดยไม่ต้องสงสัย เป็นสิ่งที่ฉันอยากได้มาตลอด",
  str_voice_1501521_52 = "Alchemy Stars",
  str_voice_1501521_53 = "ฮ่าฮ่าฮ่า!",
  str_voice_1501521_54 = "ใช่ ใกล้สว่างแล้ว",
  str_voice_1501521_55 = "ครึ่งวันก็คือครึ่งวัน",
  str_voice_1501521_56 = "เอ้อ มืดแล้วเนี่ย",
  str_voice_1501521_57 = "เย็บ ๆ ปะ ๆ ปีใหม่มาถึงแล้ว สุขสันต์วันปีใหม่!",
  str_voice_1601531_1 = "การเริ่มสงครามเป็นเรื่องง่าย แต่การจบมันนั้นไม่ง่ายเลย บอกฉันสิ PlayerName เธอเตรียมใจแล้วรึยัง?",
  str_voice_1601531_2 = "ไม่มีใครรับประกันชัยชนะได้จนกว่าสงครามจะสิ้นสุดลงจริง ๆ สิ่งเดียวที่เราทำได้คือต้องมุ่งมั่นเข้าไว้",
  str_voice_1601531_3 = "จำไว้ว่า จงอย่าหลงทาง ความจริงมักซ่อนอยู่หลังม่านเสมอ",
  str_voice_1601531_4 = "ถ้าสงสัยในตัวฉันก็มาถามฉันตรง ๆ ได้เลย สิทธิพิเศษนี้ไม่ใช่แค่สำหรับเธอเท่านั้น แต่สำหรับทุกคนในอิลลูมินาด้วยเช่นกัน",
  str_voice_1601531_5 = "พยายามก้าวข้ามขีดจำกัดและพัฒนาตนเองอย่างต่อเนื่อง ผู้ที่มีจิตใจเข้มแข็งและเปี่ยมคุณธรรมเท่านั้นจึงจะได้รับการชื่นชมนับถือ",
  str_voice_1601531_6 = "ไม่ต้องกลัวแผลเป็นพวกนี้หรอก PlayerName มันคือเหรียญตราแห่งเกียรติยศสำหรับทหารอย่างฉัน ฉันมั่นใจว่าเธอเข้าใจดี ว่าความเจ็บปวดทางกายนั้นเล็กน้อยมากเมื่อเทียบกับบาดแผลในจิตใจ",
  str_voice_1601531_7 = "ฉันเชื่อว่าการฝึกฝนทางทหารของอิลลูมินาจะช่วยให้เธอพัฒนาตัวเองได้อย่างรวดเร็ว แต่ถึงอย่างนั้น ความรวดเร็วก็ไม่ใช่สิ่งที่ดีเสมอไป",
  str_voice_1601531_8 = "กำลังอ่านหนังสือกลยุทธ์อยู่เหรอ? ไหนดูซิ... อืมม บทวิเคราะห์บางส่วนก็ถูกต้องดี แต่วิธีการค่อนข้างจะล้าสมัยไปหน่อย ฮ่าฮ่า ตอนนี้ฉันบอกได้แค่นี้แหละนะ ถ้าอ่านจบแล้วฉันก็ยินดีอธิบายให้ฟังเพิ่มเติม",
  str_voice_1601531_9 = "ทหารต้องไว้ใจสหายร่วมรบของตัวเอง ส่วนผู้นำก็ต้องแยกแยะคำโกหกให้ได้... เมื่อเธอเก่งทั้งสองอย่างแล้ว เธออาจเข้าใจความรู้สึกของฉันก็ได้",
  str_voice_1601531_10 = "เด็กหนุ่มที่มีแรงทะเยอทะยานสูงอย่างเธอไม่ควรผัดวันประกันพรุ่งหรือใช้โอกาสสิ้นเปลือง",
  str_voice_1601531_11 = "นาน ๆ ทีฉันจะได้หยุดงานนะเนี่ย ไหนดูซิว่าช่วงนี้เธอทำอะไรอยู่",
  str_voice_1601531_12 = "ไม่มีทหารคนไหนไร้ความสามารถหรอก มีแต่นายพลที่ไร้ฝีมือ เธอคงเข้าใจสิ่งที่ฉันพยายามจะสื่อใช่มั้ย",
  str_voice_1601531_13 = "เมื่อรู้สึกแย่ ก็ต้องกินให้สะใจ! ท้องคือสมองที่สองของเรา และเราต้องดูแลมันให้ดี",
  str_voice_1601531_14 = "โทษสำหรับทหารหนีทัพของอิลลูมินานั้นรุนแรงมาก เธอรู้ไหมว่าทำไม? เพราะการหนีไม่เคยใช่วิธีแก้ปัญหา ความล้มเหลวในการแก้ปัญหาไม่ใช่เรื่องน่าอาย แต่การหลบหนีน่ะใช่ เธอเห็นด้วยไหม?",
  str_voice_1601531_15 = "สุขสันต์วันเกิด! ในเมื่อเธอแก่ขึ้นอีกปีแล้ว เธอก็ควรเน้นการฝึกให้หนักขึ้นด้วย",
  str_voice_1601531_16 = "หิวข้าวงั้นเหรอ? ยังอยู่ในวัยกำลังโตสินะ! กินข้าวผัดอีกสิจะได้แข็งแรง!",
  str_voice_1601531_17 = "สวัสดีตอนเช้า! ฉันทำให้ตกใจรึเปล่า? ประโยคแรกที่เราพูดทุกเช้าจะต้องเสียงดังฟังชัด ขอฉันฟังคำตอบของเธอหน่อย!",
  str_voice_1601531_18 = "นี่ก็เริ่มดึกแล้ว แต่ก็ยังมีเวลาอีกมากในการทำงาน",
  str_voice_1601531_19 = "จงทำสิ่งที่ถูกต้องในเวลาที่เหมาะสม คนขยันไม่จำเป็นต้องสละเวลานอน",
  str_voice_1601531_20 = "พื้นเพและอดีตไม่ใช่เรื่องสำคัญ ตราบใดที่หัวใจยังเชื่อมั่นในสิ่งเดียวกับอิลลูมินา ทุกคนก็สามารถบรรลุศักยภาพของตัวเองได้ที่นี่",
  str_voice_1601531_21 = "ฉันไม่เห็นด้วยกับวิธีที่ลูโมโพลิสปฏิบัติต่อผู้คน แต่เราก็ยังเรียนรู้บางอย่างจากพวกนั้นได้",
  str_voice_1601531_22 = "เพื่อสหายร่วมอุดมการณ์ของฉัน บ้านเกิดของฉัน และอิลลูมินาอันเจิดจำรัส!",
  str_voice_1601531_23 = "อิคลิพไซท์เป็นศัตรูกับเรามาโดยตลอด แต่ถ้าให้พูดตรง ๆ สิ่งต่าง ๆ มันไม่เคยง่ายเหมือนที่ตาเห็นอยู่แล้ว",
  str_voice_1601531_24 = "นิสัยหมกมุ่นกับแผนงานและตารางเวลาของวิเวียนนั้นไม่เหมาะกับการต่อสู้เท่าไหร่ แต่ก็มีประโยชน์กับงานพลาธิการอย่างดีเยี่ยม",
  str_voice_1601531_25 = "ฉันไม่เคยเกรงกลัวความทะเยอทะยานของวราธเลย ตรงกันข้ามด้วยซ้ำ เธอเป็นเครื่องย้ำเตือนให้ฉันพัฒนาตัวเองต่อไป",
  str_voice_1601531_26 = "ฉันไม่อินกับอาหารหรู ๆ เท่าไหร่ อาหารที่กินแล้วสบายใจอย่างข้าวผัดหม้อใหญ่ ๆ นี่แหละ เติมเต็มทั้งความหิวและจิตวิญญาณ",
  str_voice_1601531_27 = "ถึงทหารหนีทัพผู้น่ารังเกียจทั้งหลาย โลกใบนี้มันไม่ได้หมุนรอบพวกนายคนเดียวหรอกนะ",
  str_voice_1601531_28 = "อืม โซรอซทั้งแข็งแกร่งและกว้างขวาง เหมาะสำหรับการขนส่งทางทหาร",
  str_voice_1601531_29 = "PlayerName เธอคือสมบัติอันมีค่าสำหรับทุกคนในแอสตรา แสดงให้ฉันเห็นหน่อยสิ ว่าเธอทำอะไรได้อีกบ้าง",
  str_voice_1601531_30 = "ยังไม่จบเท่านี้หรอก!",
  str_voice_1601531_31 = "พลังนี้ ไม่ใช่ของฉันเพียงคนเดียว",
  str_voice_1601531_32 = "ใช่แล้ว จงแข็งแกร่ง และแข็งแกร่งขึ้นอีก!",
  str_voice_1601531_33 = "หอกที่รักของฉันจะลุกโชนเพื่อฉัน!",
  str_voice_1601531_34 = "โฮ่? เป็นทหารแต่กลับมาสั่งผู้บัญชาการอย่างฉันงั้นรึ?",
  str_voice_1601531_35 = "เวลาไม่เคยคอยใคร!",
  str_voice_1601531_36 = "ขอดูฝีมือสั่งการของเธอหน่อยสิ!",
  str_voice_1601531_37 = "แกจะได้เห็นพลังที่แท้จริงของฉัน!",
  str_voice_1601531_38 = "ขอให้นี่เป็นจุดจบ",
  str_voice_1601531_39 = "ทะลวงฝ่าทุกสิ่ง!",
  str_voice_1601531_40 = "มาหอกของฉัน!",
  str_voice_1601531_41 = "ให้ฉันนำทีมงั้นรึ? ถึงจะมักง่ายไปหน่อย แต่ก็ตัดสินใจได้ฉลาดมาก",
  str_voice_1601531_42 = "เราจะต้องชนะ!",
  str_voice_1601531_43 = "สู้ต่อไป และเดินหน้าต่อไป!",
  str_voice_1601531_44 = "นี่เป็นฐานทัพที่สมบูรณ์แบบเลยล่ะ!",
  str_voice_1601531_45 = "ฉันไม่ได้จริงจังอะไรกับของนอกกายหรอก แต่ยังไงก็ขอบคุณนะ",
  str_voice_1601531_46 = "อา ขอบคุณที่นึกถึงกันนะ",
  str_voice_1601531_47 = "ขอบคุณนะ ฉันจะใช้มันให้เกิดประโยชน์",
  str_voice_1601531_48 = "ไม่เอาน่า อย่าลำบากมาเอาใจฉันขนาดนั้นเลย",
  str_voice_1601531_49 = "ฉันเองก็ไม่ต่างจากทหารอิลลูมินาคนอื่นนักหรอก การต่อสู้คือหน้าที่ของฉัน นับตั้งแต่วันแรกที่ฉันปรากฏตัวในสนามรบ ก็ไม่มีสิ่งใดหยุดยั้งหอกของฉันจากการฟาดฟันศัตรูได้",
  str_voice_1601531_50 = "วราธเคยเป็นเพื่อนร่วมชั้นเรียนของฉัน แต่นั่นไม่เกี่ยวอะไรกับการเลื่อนตำแหน่งของเธอ ความสามารถของเธอเป็นที่ประจักษ์ต่อสายตาทุกคนอยู่แล้ว นั่นตอบคำถามที่นายสงสัยได้รึเปล่า?",
  str_voice_1601531_51 = "ฉันเลื่อนตำแหน่งให้ชาโรนากับฮิอิโระเป็นผู้บัญชาการกองทัพก็เพราะความสามารถอันโดดเด่นของพวกเธอ โอกาสมีอยู่เสมอสำหรับผู้ที่คู่ควร แต่น้อยคนนักที่จะได้ประโยชน์จากมันจริง ๆ",
  str_voice_1601531_52 = "Alchemy Stars!",
  str_voice_1601531_53 = "เตรียมตัวให้พร้อม!",
  str_voice_1601531_54 = "สวัสดีตอนเช้า",
  str_voice_1601531_55 = "หวัดดี!",
  str_voice_1601531_56 = "สวัสดีตอนค่ำ",
  str_voice_1601531_57 = "เธอต้องพยายามให้เต็มที่ ปณิธานปีใหม่ของเธอถึงจะเป็นจริง",
  str_voice_1601541_1 = "ฮิฮิ... เอ่อ ไม่มีอะไรหรอก ฉันนึกขึ้นมาได้ว่า ตอนเราเจอกันครั้งแรกฉันนึกว่านายเป็นผีหรือตัวประหลาดอะไรซักอย่าง... เฮ้อ ไม่รู้ตัวเลยนะเนี่ยว่ามันผ่านมานานมาแล้ว",
  str_voice_1601541_2 = "นายคิดว่าฉัน... เปลี่ยนไปรึเปล่า? ที่จริงฉันก็ตกใจอยู่บ่อย ๆ เวลามองตัวเองในกระจก แต่ก็รู้สึกได้ถึงพลังอันเต็มเปี่ยมในตัว นั่นเป็นเรื่องดีสำหรับเราใช่มั้ย? ใช่แล้ว ฉันพูดว่าเรา!",
  str_voice_1601541_3 = "ความสงบสุขของแอสตราคงอยู่ได้ไม่นานหรอก แม้แต่ในตอนนี้ พวกเราก็ถูกดึงให้พัวพันกับเรื่องวุ่นวายอยู่ตลอด แต่ไม่ต้องห่วงนะ PlayerName ฉันจะอยู่เคียงข้างนายเสมอ!",
  str_voice_1601541_4 = "บางครั้งก็ดูเหมือนว่า ยิ่งฉันรู้อะไรมากเท่าไหร่ ก็ยิ่งไม่รู้อะไรเลย...เดี๋ยวนะ ฉันพล่ามอะไรไร้สาระออกไปเนี่ย? นี่ฉันเริ่มเหมือนนายเข้าไปทุกทีแล้วแฮะ!",
  str_voice_1601541_5 = "ในเมื่อฉันแข็งแกร่งขึ้น ก็แปลว่าฝีมือทำอาหารของฉันดีขึ้นด้วยใช่ไหมเนี่ย? ว่าแต่ PlayerName อยากกินอะไรล่ะ? บอกมาได้เลย!",
  str_voice_1601541_6 = "พวกเราไม่เหมือนอิคลิพไซท์ เราแสวงหาพลังอำนาจเพื่อปกป้องผู้คนที่ต้องการเรา ในเมื่อฉันศรัทธาในตัวเอง ดังนั้น นายก็ช่วยเชื่อมั่นในตัวฉันด้วยนะ!",
  str_voice_1601541_7 = "ฉันแปลกใจเหมือนกันที่ได้รู้ว่าตัวฉันเหมาะกับอะไรมืด ๆ ด้วย... ฉันหมายถึงเสื้อผ้าน่ะ! นายว่าสีไหนฉันใส่แล้วดูดีกว่ากัน ดำหรือขาว?",
  str_voice_1601541_8 = "ช่วงนี้ฉันหัดเล่นดนตรีด้วยล่ะ จะเครื่องอะไรอีกล่ะ? ก็ต้องเปียโนอยู่แล้ว! มาเล่นด้วยกันมั้ย?",
  str_voice_1601541_9 = "ฉันคงเปลี่ยนไปแล้วจริง ๆ ฉันเป็นคนโลภมากกว่าเดิม เพราะตอนนี้ฉันมีคนให้ปกป้องมากขึ้น รวมทั้งนายด้วย เพราะฉะนั้น ฉันว่าฉันพอใจกับความโลภแบบนี้ล่ะนะ",
  str_voice_1601541_10 = "เอาล่ะ ฉันพักผ่อนพอแล้ว ฉันรู้ว่าฉันควรพักผ่อนให้มาก ๆ เพื่อตัวฉันเอง แต่เรายังมีงานต้องทำนะ โอเคมั้ย?",
  str_voice_1601541_11 = "แน่นอน ฉันช่วยได้อยู่แล้ว แต่ตรงนี้ไม่มีอะไรให้ซ่อมนี่... นายจะให้ฉันพักที่นี่งั้นเหรอ?",
  str_voice_1601541_12 = "แผนการที่ละเอียดถี่ถ้วนและการฝึกฝนอย่างขยันขันแข็งจะส่งผลดีในที่สุด! ว่าแต่นายจะส่งแผนสำหรับเดือนหน้าได้เมื่อไหร่?",
  str_voice_1601541_13 = "วันหยุดเหรอ? อะแฮ่ม มันก็ใช่ว่าจะเป็นไปไม่ได้นะ ฉันเองก็ตั้งตารออะไรสนุก ๆ เหมือนกัน แต่เราต้องสรุปงานให้เสร็จก่อน เดี๋ยวฉันขอไปดูงบค่าใช้จ่ายก่อนนะ!",
  str_voice_1601541_14 = "เสร็จงานตามแผนรึยัง? อะไรนะ? นายเขียนแผนสำหรับโคลอสซัสแต่ไม่มีแผนสำหรับอีราเวลเหรอ? อย่าละเลยหน้าที่ของนายสิ PlayerName!",
  str_voice_1601541_15 = "สุขสันต์วันเกิด! หวังว่าฉันจะได้เห็นนายตั้งใจทำงานอย่างขยันขันแข็งไปอีกปีนะ ฮิฮิ",
  str_voice_1601541_16 = "อย่าทำงานหนักเกินไปล่ะ บางทีก็ต้องปล่อยวางบ้าง สมดุลระหว่างงานกับชีวิตส่วนตัวเป็นเรื่องสำคัญนะ",
  str_voice_1601541_17 = "อรุณสวัสดิ์! นี่คือตารางงานของวันนี้ ช่วยเซ็นรับทีสิ PlayerName!",
  str_voice_1601541_18 = "เฮ่อ เสร็จซักที! นายยังทำงานอยู่เหรอ? มีอะไรให้ช่วยมั้ย?",
  str_voice_1601541_19 = "ยังไม่นอนอีกเหรอ? เจอปัญหาอะไรรึเปล่า? ไม่ต้องกังวลนะ ให้ฉันช่วยเอง",
  str_voice_1601541_20 = "อิลลูมินาอาจมีความลับที่ฉันไม่รู้ แต่ฉันมั่นใจว่ามันจะต้องไม่ใช่การสมคบคิดกันทำเรื่องเลวร้ายแน่นอน เรื่องแบบนั้นไม่มีทางเกิดขึ้นในอิลลูมินาอยู่แล้ว!",
  str_voice_1601541_21 = "ฉันเคยคิดว่าเรดีเซล เวรนช์เป็นแค่กลุ่มคนที่สิ้นหวัง ตอนนี้ฉันรู้แล้วว่าพวกเขาเป็นคนน่ารักจริง ๆ",
  str_voice_1601541_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1601541_23 = "ฉันเองก็ไม่ได้ชอบการฆ่าฟันหรอกนะ แต่สำหรับอิคลิพไซท์มันก็ไม่มีวิธีอื่นแล้ว",
  str_voice_1601541_24 = "เขาไม่ใช่นักสู้ที่เก่งกาจอะไร แต่เป็นคนฉลาด กล้าหาญ แล้วก็ขยันมาก ๆ... หมายถึงอะไรงั้นเหรอ? อ๋อ ฉันแค่พูดถึง... เพื่อนที่ดีของฉันคนนึงน่ะ",
  str_voice_1601541_25 = "คาร์ลีนเป็นคนฉลาด สุขุม แล้วก็เป็นผู้ใหญ่อยู่เสมอ แต่พอมาตอนนี้ฉันถึงได้รู้ ว่าจริง ๆ เธอจงใจปกปิดด้านที่ไร้เดียงสาของเธอเอาไว้",
  str_voice_1601541_26 = "ดอกรุ่งอรุณสีขาว ดอกซากุระสีชมพู น้ำปั่นริมทะเล และเค้กน้ำผึ้งกลางหิมะ... เดี๋ยวนี้มีหลายอย่างเลยที่ฉันชอบ",
  str_voice_1601541_27 = "สิ่งที่ฉันรับไม่ได้ในอดีต ตอนนี้ดูจะไม่แย่ขนาดนั้นแล้ว... แสดงว่าฉันเป็นผู้ใหญ่ขึ้นงั้นเหรอ?",
  str_voice_1601541_28 = "โซรอซเริ่มให้ความรู้สึกเหมือนอยู่บ้าน ฮิฮิ ฉันคงไม่ได้คิดแบบนั้นคนเดียวใช่มั้ย?",
  str_voice_1601541_29 = "ทำไมนายมองฉันแบบนั้นล่ะ? ฉันเปลี่ยนไปขนาดนั้นเลยเหรอ? ไม่ต้องห่วงนะ ฉันคือไวซ์คนเดิม สาบานเลย!",
  str_voice_1601541_30 = "พลังที่เยือกเย็นกว่าเดิม!",
  str_voice_1601541_31 = "ตั้งใจทำงาน ก้าวไปให้ไกล!",
  str_voice_1601541_32 = "การตัดสินใจในวันนี้จะตอบแทนเราอย่างดีในอนาคต!",
  str_voice_1601541_33 = "ในที่สุด ศักยภาพในตัวฉันก็ตื่นขึ้น!",
  str_voice_1601541_34 = "ฉันจะทุ่มเทให้มากกว่านี้!",
  str_voice_1601541_35 = "ส่งฉันไปเลย!",
  str_voice_1601541_36 = "จะมัวเสียเวลาไม่ได้!",
  str_voice_1601541_37 = "ได้เวลาแล้ว! เจอนี่เป็นไง!",
  str_voice_1601541_38 = "อีกไม่นานก็จบแล้ว!",
  str_voice_1601541_39 = "ขอทีเดียวเน้น ๆ ก็พอแล้ว!",
  str_voice_1601541_40 = "โจมตี ศรน้ำแข็ง!",
  str_voice_1601541_41 = "เหมือนทุกทีนะ นายนำไปเลย!",
  str_voice_1601541_42 = "นี่ล่ะ การรบที่สมบูรณ์แบบเหมือนในตำรา!",
  str_voice_1601541_43 = "ไม่เป็นไรนะ เรายังมีโอกาสหน้า!",
  str_voice_1601541_44 = "หืมม ขอดูงานที่ต้องทำวันนี้หน่อยนะ... ซ่อมบำรุงโคลอสซัส... ซื้อของชำ... วางแผนงานรายวัน... อา เป็นวันที่ยุ่งวุ่นวายอีกวันสินะ!",
  str_voice_1601541_45 = "อ้าว ของขวัญจากเพื่อนเก่านี่!",
  str_voice_1601541_46 = "นายได้มาจากไหนเนี่ย? ขอบคุณมากนะ!",
  str_voice_1601541_47 = "ไม่ต้องใจดีกับฉันขนาดนั้นก็ได้นะ!",
  str_voice_1601541_48 = "ว้าว ฉันอยากได้มานานแล้ว... ขอบคุณนะ!",
  str_voice_1601541_49 = "ถ้านายไม่ช่วยฉันจากใต้ดินในตอนนั้น ฉันก็คงไม่ได้มาอยู่ตรงนี้แล้ว... เราเป็นคู่หูที่เยี่ยมไปเลย นายว่ามั้ย?",
  str_voice_1601541_50 = "ความทรงจำพวกนั้นเคยเลือนหายไปในส่วนลึกของจิตใจฉัน... แต่ตอนนี้ จู่ ๆ ฉันก็นึกถึงมันได้อย่างชัดเจนอีกครั้ง หัวสมองที่ว่างเปล่า มีแต่เสียงแหลมเสียดแทงในหู... ฉันไม่อยากเชื่อเลยว่าตัวเองเคยมีชีวิตแบบนั้น",
  str_voice_1601541_51 = "การผจญภัยของพวกเราในแอสตราเป็นอะไรที่น่าตื่นเต้นจริง ๆ! แต่ไม่มีเลยซักครั้ง ที่ฉันคิดว่าเราจะแพ้ให้กับความยากลำบากและอันตราย ฉันอยากจะท่องโลกกับนายให้มากกว่านี้อีก ถ้าเป็นไปได้น่ะนะ",
  str_voice_1601541_52 = "Alchemy Stars!",
  str_voice_1601541_53 = "เป็นไงบ้าง PlayerName?",
  str_voice_1601541_54 = "สวัสดีตอนเช้า นายตื่นหรือยัง?",
  str_voice_1601541_55 = "กินมื้อเที่ยงรึยังเนี่ย?",
  str_voice_1601541_56 = "สวัสดีตอนเย็น นายต้องเหนื่อยแน่เลย ทำอะไรมาทั้งวันแบบนี้",
  str_voice_1601541_57 = "เริ่มต้นปีใหม่อีกปีแล้ว มาพยายามไปด้วยกันเถอะนะ!",
  str_voice_1601551_1 = "อย่าบอกนะว่านายกลัวฉัน? บนโคลอสซัสมีคนที่หัวเป็นจระเข้แล้วก็คนที่มีหางเป็นหมาเดินไปเดินมาอยู่ทุกวัน แล้วดันมามองฉันเป็นตัวประหลาดเนี่ยนะ!",
  str_voice_1601551_2 = "ทหารใหม่ปีนี้แย่ที่สุดเท่าที่ฉันเคยฝึกมาเลย! เด็ก ๆ ที่เติบโตขึ้นมาในยามสงบน่ะ ไม่ระแวดระวังอันตรายอะไรเลยสักนิด!",
  str_voice_1601551_3 = "ทำไมถึงยืนจ๋อยก้มหน้าก้มตาเป็นเต่าแบบนั้น! สนามรบไม่มีกระดองให้นายซุกหัวหลบหรอกนะ! ยอมรับความเป็นจริงได้แล้ว!",
  str_voice_1601551_4 = "ฉันลองใช้อาวุธมาก็มากในช่วงหลายปีที่ผ่านมา แต่ไม่มีอะไรรู้สึกดีไปกว่าดาบคู่ที่ประกอบกันได้เล่มนี้",
  str_voice_1601551_5 = "การลอบโจมตีน่ะอาจจะได้ผลดี แต่เดี๋ยวนี้ฉันรู้สึกว่ามันไม่ใช่ทางของฉันซะแล้ว เพราะยังไงสู้กันซึ่งหน้าฉันก็จัดการพวกมันได้สบาย ๆ อยู่ดี อยากลองมั้ยล่ะ?",
  str_voice_1601551_6 = "ฉันเพิ่งมาคิดได้ ว่าเราไม่มีทางควบคุมพลังในตัวเราได้อย่างแท้จริงหรอก ถ้าเรายังเอาชนะตัวเองไม่ได้ โชคดีนะที่ฉันเอาชนะตัวเองได้เรียบร้อยแล้ว ฮ่าฮ่าฮ่าฮ่า",
  str_voice_1601551_7 = "ฉันจำได้ว่านายคุ้นเคยกับทหารของฉันหลายคนใช่ไหม? ดีแล้ว เออใช่ ไวท์ดวาร์ฟน่ะไม่ค่อยพูด แต่เขาไม่เคยทำให้ฉันผิดหวังในสงครามเลย",
  str_voice_1601551_8 = "นายคือคู่ต่อสู้คนเดียวที่คู่ควรกับฉันในเกมจำลองสงคราม",
  str_voice_1601551_9 = "นายมีพรสวรรค์ในการเป็นผู้นำกองทหาร แต่อย่าถือเป็นคำชมนะ พรสวรรค์ตามธรรมชาติไม่ใช่เรื่องที่น่ายกย่อง ฉันอยากเห็นความอดทนและความตั้งใจที่จะต่อสู้ของนายมากกว่า!",
  str_voice_1601551_10 = "นี่ ฉันเล่นเกมสงครามในหัวเสร็จไปตั้งสามเกมแล้วนะ ทำไมถึงใช้เวลานานขนาดนี้?",
  str_voice_1601551_11 = "ฮ่า เดี๋ยวนี้หัดมาขอฝึกซ้อมด้วยตัวเองแล้วงั้นเรอะ? พัฒนาขึ้นเหมือนกันนี่",
  str_voice_1601551_12 = "นั่นเรียงความเหรอ? ของแบบนี้จะช่วยให้นายชนะการต่อสู้ได้ยังไง? ฉันว่านายไปวิ่งแทนดีกว่า อย่างน้อยจะได้มีโอกาสวิ่งหนีจากศัตรูที่ทรงพลังได้!",
  str_voice_1601551_13 = "การมีเพื่อนอยู่ทุกที่ไม่ได้ทำให้นายเดินทางสะดวกขึ้นหรอกนะ ยิ่งรู้จักคนมากก็ยิ่งมีโอกาสขัดแย้งกันมากขึ้น เตรียมใจไว้ให้ดีล่ะ แล้วก็อย่าหาว่าฉันไม่เตือนนะ",
  str_voice_1601551_14 = "ถามว่า \"ผมจะทนกับเรื่องน่าเบื่อได้ยังไง\" งั้นเรอะ? ฮ่าฮ่าฮ่า แล้วคิดว่าฉันทนได้หรือไง ก็แค่ช่วงนี้ฉันไม่ค่อยมีเวลามาเจอเรื่องน่าเบื่อ มันก็เท่านั้นเอง!",
  str_voice_1601551_15 = "วันนี้วันเกิดนายเหรอ? มาเถอะ ไปเยี่ยมแนวหน้าให้เลือดมันสูบฉีดหน่อยดีกว่า!",
  str_voice_1601551_16 = "เฮ้อ ทำไมผู้บัญชาการยังต้องมานั่งทำงานเอกสารโง่ ๆ อีกล่ะเนี่ย?",
  str_voice_1601551_17 = "นายตื่นเช้านะ เพราะนายอยากฝึกกับฉันหรือไง? บอกมาก็ได้น่า...",
  str_voice_1601551_18 = "ในที่สุดก็มีเวลาว่างซักที! มาฝึกฟันดาบก่อนนอนกันเถอะ อยากเรียนมั้ย? มาฝึกด้วยกันสิ!",
  str_voice_1601551_19 = "ยังไม่นอนเหรอ? อย่าเอาแต่เหม่อสิ มาดวลกับฉันก่อน!",
  str_voice_1601551_20 = "ฉันไม่รู้เหมือนกันว่าพวกตำแหน่งสูง ๆ วางแผนอะไรกันอยู่ แต่ตราบใดที่ฉันยังอยู่กับอิลลูมินา ก็ไม่มีใครขัดขวางฉันในการชนะศึกได้",
  str_voice_1601551_21 = "พวกเรดีเซล เวรนช์ เอาแต่กิน ดื่ม แล้วก็นอน มัวแต่ใช้ความสามารถไปกับเรื่องไร้สาระ พวกนั้นควรเอาพลังมาให้ฉันมากกว่า",
  str_voice_1601551_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1601551_23 = "อิคลิพไซท์ก็เป็นได้แค่ขยะที่ไร้จิตใจ... เหอะ พวกมันเอาความกล้าจากไหนมาต่อต้านเรากันนะ?",
  str_voice_1601551_24 = "ในบรรดาผู้บัญชาการ มีแค่ฮิอิโระคนเดียวที่สะดุดตาฉัน นี่ ไม่ต้องคิดอะไรแปลก ๆ เลยนะ ฉันหมายถึงฝีมือการต่อสู้น่ะ!",
  str_voice_1601551_25 = "วราธชอบการต่อสู้อย่างยุติธรรม แต่สงครามน่ะไม่มีของแบบนั้นหรอก ไร้เดียงสาเกินไปมั้ย?",
  str_voice_1601551_26 = "เห็นมั้ย? ฉันคือนักสู้ที่เกิดมาเพื่อสนามรบ! การต่อสู้คือสิ่งเดียวที่ทำให้ฉันรู้สึกว่าตัวเองมีชีวิต!",
  str_voice_1601551_27 = "อ่านหนังสือพิมพ์แล้วก็นั่งดื่มชาทั้งวันมันจะได้อะไรขึ้นมา? อย่าให้ฉันไปอยู่ตรงนั้นเลย ฉันไม่ได้มี \"วาสนา\" ขนาดนั้นหรอกนะ!",
  str_voice_1601551_28 = "โคลอสซัสของนายยังไม่เคยเปลี่ยนเลย ไม่มีแม้แต่ \"เครื่องประดับ\" อย่างรอยกระสุน เอางี้ เดี๋ยวฉันเริ่มจากการใช้ดาบขูดให้เป็นไง?",
  str_voice_1601551_29 = "ไม่ได้เจอกันสองสามวันก็ลืมฉันแล้วงั้นเรอะ? เอาเถอะ คราวหน้าถ้าเราได้เจอกันในสนามรบ ฉันจะแสดงร่างที่แท้จริงให้นายได้เห็นเอง! กลัวขึ้นมาแล้วงั้นเรอะ? ฮ่าฮ่าฮ่า!",
  str_voice_1601551_30 = "ฉันยังแข็งแกร่งขึ้นได้อีก! แน่นอน!",
  str_voice_1601551_31 = "นี่ล่ะ ที่ฉันต้องการ!",
  str_voice_1601551_32 = "ให้สู้ต่ออีกร้อยปีก็ยังไหว ฮ่าฮ่าฮ่าฮ่า!",
  str_voice_1601551_33 = "ใครจะเป็นรายต่อไปดีล่ะ?!",
  str_voice_1601551_34 = "สนามรบอยู่ไหนเรอะ?",
  str_voice_1601551_35 = "เฮ่ย ระวังโดนลูกหลงล่ะ!",
  str_voice_1601551_36 = "ได้เวลาเก็บกวาดแล้ว!",
  str_voice_1601551_37 = "มาใกล้ ๆ แล้วเอานี่ไปกินซะ!",
  str_voice_1601551_38 = "ฮึยย่าาา!",
  str_voice_1601551_39 = "พยัคฆ์ดำจู่โจม!",
  str_voice_1601551_40 = "เข้ามา!",
  str_voice_1601551_41 = "หลบไปให้ไวเลย!",
  str_voice_1601551_42 = "พุ่งโจมตีและจัดการซะตอนที่เหล็กยังร้อน!",
  str_voice_1601551_43 = "ยังไม่ถึงเวลายอมแพ้หรอกนะ!",
  str_voice_1601551_44 = "สนิมจับแล้วงั้นเรอะ? มาฝึกซ้อมกับฉันซักยกสองยกมั้ย?",
  str_voice_1601551_45 = "ใจดีจังเลยนะ!",
  str_voice_1601551_46 = "นี่ล่ะที่ฉันต้องการ ขอบใจนะ!",
  str_voice_1601551_47 = "งั้นฉันไม่เกรงใจล่ะนะ! ฮ่าฮ่า!",
  str_voice_1601551_48 = "หืมม นี่มันของดีนะเนี่ย!",
  str_voice_1601551_49 = "ทหารจำเป็นต้องมีคนคอยกำกับดูแลตลอดเวลาด้วยเหรอ? พวกเราควรรักษามาตรฐานของตัวเองให้สูงอยู่เสมอไม่ใช่หรือไง? ฉันน่ะ ฝึกฝนตัวเองตั้งแต่วันที่สวมหมวกใบนี้แล้ว!",
  str_voice_1601551_50 = "ตอนฉันเจอกับไรน์ฮาร์ตครั้งแรกนายน่าจะหัดเดินอยู่เลยมั้ง ฉันคิดถึงวันเวลาเหล่านั้นจริง ๆ ก่อนที่พวกกรรมาธิการนั่นจะเข้ามายุ่มย่ามกับเธอ",
  str_voice_1601551_51 = "ฉันเคยบอกไปนานแล้วว่าทหารจะหนีจากการรบไม่ได้เด็ดขาด ไม่ว่าศัตรูอยู่ที่ไหน เราก็จะมุ่งหน้าไปที่นั่น! สิ่งนี้ล่ะ ที่พาฉันมายืนตรงจุดนี้ได้!",
  str_voice_1601551_52 = "Alchemy Stars!",
  str_voice_1601551_53 = "นี่ พูดอะไรหน่อยสิ",
  str_voice_1601551_54 = "สวัสดีตอนเช้า!",
  str_voice_1601551_55 = "เที่ยงแล้วเหรอ?",
  str_voice_1601551_56 = "สวัสดีตอนเย็น!",
  str_voice_1601551_57 = "คำอธิษฐานในปีใหม่ของฉันก็คือการกำจัดอิคลิพไซท์ให้สิ้นซาก!",
  str_voice_1601561_1 = "สุภาพบุรุษควรเป็นฝ่ายเริ่มทักทายผู้หญิงก่อนนะ รู้มั้ย... นี่! ฟังอยู่รึเปล่า? สุภาพบุรุษต้องฟังเรื่องที่ผู้หญิงพูดด้วยนะ",
  str_voice_1601561_2 = "สำหรับน้ำชายามบ่ายในวันนี้ ฉันอยากดื่มชาดำมะลิแล้วก็ทานสโคนไร้น้ำตาล หืม? นายอยากให้ฉันทำเองงั้นเหรอ? แล้ว แล้วมันทำยังไงล่ะ... ช่างเถอะ ฉันหมดอารมณ์ดื่มน้ำชาแล้ว",
  str_voice_1601561_3 = "ฉันกำลังถือ \"พาราซอล\" ไม่ใช่ \"ร่ม\" ซักหน่อย! มันต่างกันยังไงงั้นเหรอ? เฮ่อ ให้ตายสิ... นี่ฉันคงต้องเรียนรู้การให้อภัยสามัญชนผู้เบาปัญญาด้วยสินะ",
  str_voice_1601561_4 = "หืม? นายคิดว่าฝีมือต่อสู้ของฉันดีขึ้นงั้นเหรอ? แน่นอน! ระวังให้ดีล่ะ อีกไม่นานฉันจะยึดครองอัมบราตันให้ได้เลย!",
  str_voice_1601561_5 = "ฮ่าฮ่าฮ่า แรงบันดาลใจในการออกแบบอาวุธกำลังโลดแล่นเลยล่ะ! ก็บอกแล้ว เรื่องนี้ฉันน่ะเป็นอัจฉริยะ!",
  str_voice_1601561_6 = "ตอนนี้ฉันเป็นทั้งนักออกแบบเครื่องแต่งกาย นักชื่นชมอัญมณี แล้วก็นักผลิตอาวุธมืออาชีพ ได้เวลาพิชิตสายงานอื่นแล้ว! ว่าแต่จะเลือกทางไหนดีนะ... อ๊ะ รู้แล้ว การวิจัยเคเลสไทต์ไงล่ะ!",
  str_voice_1601561_7 = "ในเมื่อตอนนี้ฉันเป็นแฟชั่นดีไซเนอร์ผู้มีชื่อเสียง ดังนั้นฉันออกแบบเสื้อผ้าให้นายได้สบาย ๆ แต่ขอเตือนอย่างเป็นมิตรไว้ก่อนนะ ในสถานการณ์แบบนี้ นายควรจะต้องตอบว่า \"ช่างเป็นเกียรติจริง ๆ\" เข้าใจมั้ย!",
  str_voice_1601561_8 = "ตอนนี้เรา... เป็นเพื่อนสนิทกันแล้วใช่มั้ย? อย่าเข้าใจผิดล่ะ ฉันก็แค่ไม่อยากเปลืองความรู้สึกไปกับพวกโง่ ๆ ที่ไม่เข้าใจความรู้สึกคนอื่นน่ะ...",
  str_voice_1601561_9 = "PlayerName นายเคยคิดถึงคุณพ่อคุณแม่บ้างรึเปล่า? ไม่มีอะไรหรอก จู่ ๆ ฉันก็คิดถึงคุณแม่ขึ้นมาน่ะ ถ้าแม่ยังอยู่ ฉันคง... พานายไปรู้จักกับเธอ",
  str_voice_1601561_10 = "พาฉันมาที่นี่แล้วก็เมินฉันเนี่ยนะ... เสียมารยาทที่สุด! อะไรกัน? ฉันทำอะไรผิดงั้นเหรอ... แต่ฉันไม่สนหรอก! แล้วฉันก็จะไม่ขอโทษด้วย ถ้านายไม่ยอมอธิบาย!",
  str_voice_1601561_11 = "ทำไมนายถึงพาฉันมาในที่ซอมซ่อแบบนี้ด้วย... เอ๋ ฉันไม่ได้เกลียดที่นี่ย่ะ ตาทึ่ม! ในเมื่อนายพาฉันมาแล้ว น-นายห้ามละสายตาจากฉันเด็ดขาดนะ!",
  str_voice_1601561_12 = "\"เด็กหนุ่มคนหนึ่งคืนชีพอีกครั้งหลังจากถูกฝังมานานถึง 17 ปี...\" เนี่ยนะที่นายเรียกว่าเรื่องสยองขวัญ? เดี๋ยวนี้สามัญชนเขาชอบแบบนี้กันหรือไง?",
  str_voice_1601561_13 = "อี๋ ก้อนดำ ๆ นั่น... เรดีเซลบาร์บีคิวไม่ใช่เหรอ? ของแบบนี้ขนาดหมายังไม่กินด้วยซ้ำ! อย่ามาบังคับให้ฉัน... หวาาา... เอ๊ะ เอ่อ ที่จริงก็ไม่เลวแฮะ",
  str_voice_1601561_14 = "ลุงอีสต์วานคอยแต่ชวนให้พ่อกลับคืนวงการอีก... คือว่านะ พ่อของฉันก็เป็นแค่ตาแก่เนิร์ด ๆ ที่เอาแต่อยู่บ้าน เขาเก่งขนาดนั้นเลยเหรอ?",
  str_voice_1601561_15 = "นี่เป็นแค่ของเหลือจากงานการกุศลน่ะ ไม่ใช่ของขวัญวันเกิดสำหรับนายหรอกนะ! เอ่อ... ส-สุขสันต์วันเกิดนะ",
  str_voice_1601561_16 = "นายทำอะไรอยู่น่ะ? เอ่อ ฉันไม่ได้อยากรู้เรื่องของนายหรอกนะ! ก็แค่ แค่... ลืมมันไปเถอะ ฉันไม่บอกนายหรอก",
  str_voice_1601561_17 = "นี่นายยังหลับอยู่เหรอ? ฉันไม่มีทางปลุกนายหรอกนะ... หือ? ยังนอนอยู่อีกเหรอเนี่ย? ตื่นได้แล้ว!",
  str_voice_1601561_18 = "นี่ก็ดึกแล้วนะ นายยัง... ทำงานอยู่งั้นเหรอ? ไม่มีอะไร ฉันก็งานยุ่งเหมือนกัน ไม่ได้เหงาหรอกนะ",
  str_voice_1601561_19 = "หวาา! นายนี่เอง! ตาบื้อ ฉันเกือบหัวใจวายตายกลางดึกแล้วไง! นึกว่าเจอผีซะแล้ว...",
  str_voice_1601561_20 = "อัมบราตันเป็นถิ่นของฉันเอง หืม? ไม่ใช่เพราะพ่อฉันคอยช่วยหรอกนะ...",
  str_voice_1601561_21 = "ลูโมโพลิสงั้นเหรอ? ทำไมนายถึง... อยากไปที่นั่นล่ะ? ถ้าอยากไปจริง ๆ ฉันให้นายค้างที่คฤหาสน์ของตระกูลสักสองสามวันได้นะ",
  str_voice_1601561_22 = "ฉันจะคอยเฝ้ามองนายเอง!",
  str_voice_1601561_23 = "ฉันไม่สนหรอกว่ามันเป็นอิคลิพไซท์! กล้าดียังไงถึงมาหือกันฉัน! รับรองว่าจบไม่สวยแน่!",
  str_voice_1601561_24 = "อะแฮ่ม... ฉันต้องยอมรับว่าเบเธลน่ะเก่งพอ ๆ กับฉันเลย อืมม... แต่อีกไม่นานเดี๋ยวฉันก็เก่งกว่าเธอแล้ว รับรองว่าเก่งกว่าเป็นหมื่นเท่าเลยล่ะ!",
  str_voice_1601561_25 = "พอซานาเอะทำตัวเลิ่กลั่กแล้วน่ารักมากเลย... เอ๋? ฉ-ฉันไม่เคยแกล้งเธอซะหน่อย! คิดว่านะ...",
  str_voice_1601561_26 = "ฉันมีของชอบอยู่หลายอย่าง บางอย่างนายอาจจะไม่เคยรู้จักด้วยซ้ำ",
  str_voice_1601561_27 = "ฉันเนี่ยนะกลัวผี? ไร้สาระ ฉันออกจะชอบเรื่องผี แล้วทำไมฉันถึงจะ... เหวอออ นั่นอะไรน่ะ ใช่ผีรึเปล่า?",
  str_voice_1601561_28 = "โคลอสซัส... ยอดไปเลย! อะแฮ่ม ขอเวลาฉันอีกหน่อย เดี๋ยวฉันสร้างอีกลำได้แน่ ๆ!",
  str_voice_1601561_29 = "นายคือ PlayerName งั้นเหรอ? หึ นึกว่าคนที่ใคร ๆ ก็พูดถึงอย่างนายจะโดดเด่นกว่านี้เสียอีก ฉันชื่อนีน่า แอนเดอร์เซน การที่เราได้พบกันน่ะ นับเป็นเกียรติของนายแล้วนะ",
  str_voice_1601561_30 = "ทุกคน มองฉันสิ!",
  str_voice_1601561_31 = "แรงบันดาลใจ... จงบังเกิด!",
  str_voice_1601561_32 = "อาวุธชั้นยอดถือกำเนิดขึ้นอีกชิ้นแล้ว",
  str_voice_1601561_33 = "ฉันจะพึ่งพา... แต่พลังของตัวเองเท่านั้น!",
  str_voice_1601561_34 = "นายก็ไม่ได้โง่นี่นา",
  str_voice_1601561_35 = "พร้อมแล้ว!",
  str_voice_1601561_36 = "ฉันต้องรออีกนานแค่ไหนเนี่ย?",
  str_voice_1601561_37 = "เจ้าพวกโง่เง่า!",
  str_voice_1601561_38 = "จะโชว์คอลเลกชันให้ดูก็แล้วกันนะ",
  str_voice_1601561_39 = "หนวกหูชะมัด!",
  str_voice_1601561_40 = "พวกแกนี่มัน... งี่เง่าที่สุดเลย!",
  str_voice_1601561_41 = "ทุกคนทำตามฉันนะ เข้าใจมั้ย?",
  str_voice_1601561_42 = "เราต้องชนะอยู่แล้ว มีฉันอยู่ทั้งคน จริงมั้ย?",
  str_voice_1601561_43 = "ไม่มีใครเอาชนะฉันได้!",
  str_voice_1601561_44 = "หวังว่าบนนี้จะมีที่สำหรับดื่มน้ำชายามบ่ายนะ",
  str_voice_1601561_45 = "เอ๊ะ นี่คือสิ่งที่สามัญชนเขาชอบกันงั้นเหรอ?",
  str_voice_1601561_46 = "งั้น... ฉันรับไว้ก็ได้",
  str_voice_1601561_47 = "อย่าได้ใจไปล่ะ ฉันไม่ได้บอกว่าชอบซักหน่อย!",
  str_voice_1601561_48 = "นายรู้จริง ๆ ด้วยว่าฉันชอบอะไร... ข-ขอบคุณนะ",
  str_voice_1601561_49 = "อย่าดูถูกฉันล่ะ ฉันเป็นถึงทายาทตระกูลใหญ่แห่งลูโมโพลิสเชียวนะ ทำไมฉันถึงไม่อาศัยอยู่ในลูโมโพลิสน่ะเหรอ? ก็... เรื่องมันยาวน่ะ",
  str_voice_1601561_50 = "ฉันไม่เข้าใจเลย ทำไมทุกคนถึงชื่นชมเบเธลในฐานะผู้สืบทอดอัมบราตันคนต่อไป... ฉันเองก็เป็นหัวกะทิของอุษาวิทยาลัยเหมือนกันนะ!",
  str_voice_1601561_51 = "พ่อนี่งี่เง่าจริง ๆ ฉันเคยคิดมาตลอดว่าเขาเป็นคนที่เข้าใจฉันมากกว่าใครในโลก แต่กลายเป็นว่าเขาไม่เข้าใจสิ่งที่ฉันต้องการแม้แต่นิดเดียว... ช่างมันเถอะ ฉันจะคว้าสิ่งที่ต้องการมาด้วยมือฉันเอง!",
  str_voice_1601561_52 = "Alchemy Stars!",
  str_voice_1601561_53 = "PlayerName!",
  str_voice_1601561_54 = "อรุณสวัสดิ์",
  str_voice_1601561_55 = "นี่นายจะไม่ทักทายยามบ่ายกับฉันเลยเหรอ?",
  str_voice_1601561_56 = "สายัณห์สวัสดิ์",
  str_voice_1601561_57 = "สุขสันต์วันปีใหม่! ขอให้ความปรารถนาทุกอย่างเป็นจริงในวันปีใหม่นี้ คำอธิษฐานของฉันน่ะเหรอ... ความลับจ้ะ!",
  str_voice_1501571_1 = "เอ่อ... คือ... อย่างที่คุณเห็น ฉันเป็นเมด ตัวฉัน...ซักรีดเสื้อผ้าได้ ทำอาหารได้ แล้วก็... ถ้าต้องการ ฉันก็เล่านิทานจากตะวันออกไกลให้คุณฟังก่อนนอนได้นะ",
  str_voice_1501571_2 = "- เจ้าคนชื่อ PlayerName นี่พึ่งพาได้จริง ๆ น่ะเหรอ?\n-ฉันรู้สึกว่า... อ๊ะ! คุณผู้นำทาง? คุณมาตั้งแต่เมื่อไหร่คะ? เอ่อ นี่มานาเอะ พี่สาวฉันเองค่ะ...",
  str_voice_1501571_3 = "มานาเอะเป็นห่วงฉันมาก ๆ แล้วเธอก็คอยปกป้องฉันอยู่เสมอ... ทุกอย่างเป็นความผิดของฉันเองที่ ฉันมันไม่มีประโยชน์... อ๊ะ แต่ฉันจะพยายามให้มากกว่านี้ค่ะ! อย่าไล่ฉันออกเลยนะคะ!",
  str_voice_1501571_4 = "-ก่อนมาทำงานที่แอสตรา... ฉันไม่เคยคิดเลยว่าจะต้องมากังวลเรื่องอิคลิพไซท์\n-จะมีใครจ่ายค่าชดเชยที่ต้องให้ฉันมาปวดหัวได้มั้ยเนี่ย?",
  str_voice_1501571_5 = "-นี่เป็นความฝันรึเปล่า... เหมือนว่าช่วงนี้ฉันจะหกล้มน้อยลงแฮะ...\n-อื้ม อื้ม ซานาเอะโตขึ้นแล้วสินะ",
  str_voice_1501571_6 = "-ตั้งแต่เราได้เจอนาย ซานาเอะก็เป็นผู้ใหญ่ขึ้น บางที ซักวันหนึ่ง เธออาจจะไม่ต้องพึ่งฉันแล้วก็ได้\n-มานาเอะ... อย่าพูดแบบนั้นเลยนะ ได้โปรดเถอะ...",
  str_voice_1501571_7 = "ง่ำ ง่ำ ตับห่านย่างนี่มันอร่อยจริง ๆ... หวา คุณก็อยู่ที่นี่งั้นเหรอ?! เอ่อ ฉัน... ฉันไม่ได้กินอะไรหรอก... แค่จินตนาการไปเรื่อยน่ะ แหะแหะ",
  str_voice_1501571_8 = "คุณผู้นำทาง ฉันอยากจะ... ขอบคุณจริง ๆ ค่ะ! เพราะว่า... เพราะว่าฉันไม่เคยทำงานที่ไหนได้นานเลย",
  str_voice_1501571_9 = "โอ คุณผู้นำทาง... เจ้าชายในตำนานผู้ขี่มังกรขาวและเหยียบย่างบนเมฆหลากสีสันเพื่อพาฉันกลับบ้าน...",
  str_voice_1501571_10 = "-นี่ นายน่ะ! หูหนวกหรือไง?! จะให้ซานาเอะรอถึงเมื่อไหร่กัน?\nอ่า... พี่คะ อย่าพูดกับคุณผู้นำทางแบบนั้นสิ! หวาา... ขอโทษค่ะ! ฉันรอได้... จริง ๆ นะ",
  str_voice_1501571_11 = "-เอ๋...? ย... ยินดีรับใช้ค่ะ!\n-อะแฮ่ม อันดับแรก เรามาคุยเรื่องเงินเดือนให้เคลียร์กันก่อนดีกว่า",
  str_voice_1501571_12 = "เอิ่ม... พวกนกที่บินอยู่ในโคลอสซัส... เรียกว่าหิ่งห้อยใช่มั้ยคะ? อยากรู้จังว่ามันจะรสชาติยังไง... หืม? ฉันกินไม่ได้เหรอคะ? โอ๊ะ... ขอโทษค่ะ! นี่ฉันกำลังจะขโมยอาหารของคุณผู้นำทางโดยไม่ได้รับอนุญาตสินะ",
  str_voice_1501571_13 = "ที่จริงแล้ว... เมดไม่ใช่งานแรกของฉันหรอกค่ะ ฉันเคยขายหนังสือพิมพ์ ทาสี แล้วก็ใช้แรงงานที่ท่าเรือ... แต่ก็ไม่เคยทำที่ไหนได้นานเลย",
  str_voice_1501571_14 = "-ฟู่... ฉันจะใช้หนี้หมดเมื่อไหร่กันนะ...\n-นี่ PlayerName ได้เวลาขึ้นเงินเดือนแล้วมั้ง?",
  str_voice_1501571_15 = "-เอ่อ... วันนี้วันเกิดของคุณใช่มั้ยคะ? สุขสันต์วันเกิดนะคะ!\n-ส่วนของขวัญวันเกิดต้องรอให้ฉันได้เงินเดือนก่อนนะ",
  str_voice_1501571_16 = "เอ่อ... สวัสดีค่ะ ทำไม... ทำไมถึงมองฉันแบบนั้นล่ะคะ? อ่า... ฉันยังทำงานน้อยไปเหรอคะ?",
  str_voice_1501571_17 = "เอ่อ... คือ... คุณผู้นำทาง ได้เวลาตื่นนอนแล้วค่ะ อาหารเช้า... พร้อมแล้วนะคะ",
  str_voice_1501571_18 = "หลังจากทำงานทั้งวัน... ค-คุณคงจะเหนื่อยมากเลย! ให้ฉันอุ่นนมสักแก้วดีมั้ยคะ?",
  str_voice_1501571_19 = "-โอ... คุณผู้นำทาง มีอะไรที่ฉันพอจะช่วยได้บ้างมั้ยคะ?\n-ทำไมยังอยู่แถวนี้อีกล่ะ? กลับห้องไปได้แล้ว!",
  str_voice_1501571_20 = "-เกาะเมฆา... เป็นสถานที่ที่สวยเหลือเกิน\n-แต่ส่วนที่เหลือ ก็พูดยากนะ",
  str_voice_1501571_21 = "-ขอบคุณนะ อัมบราตัน ที่ยอมรับฉันอย่างที่ฉันเป็น...\n-อืมมม แต่ที่นั่นก็ไม่ได้มีแต่คนดีหรอกนะ",
  str_voice_1501571_22 = "-ทำงาน... หาเงิน... ใช้หนี้...\n-แล้วก็กินของอร่อย ๆ",
  str_voice_1501571_23 = "-อิคลิพไซท์... น่ากลัวมาก ๆ เลย แล้วพวกมันก็กินคนด้วย... น่ากลัวเหลือเกิน!\n-ฉันอยู่นี่แล้ว ไม่ต้องกลัว!",
  str_voice_1501571_24 = "เลดี้เบเธล... เป็นคนใจดีมาก ๆ เลย! แล้วเธอก็ช่วยฉันหางานด้วยล่ะ",
  str_voice_1501571_25 = "มานาเอะอยู่เคียงข้างฉันเสมอ ช่วยฉันเวลาตกที่นั่งลำบาก... ถ้าไม่มีเธอ ฉันก็คงมาไม่ได้ไกลขนาดนี้",
  str_voice_1501571_26 = "เอ... สิ่งที่ฉันชอบเหรอคะ? อ่า เรื่องนั้น... ฉันชอบ... ชอบ... การกิน แบบนั้นนับเป็นสิ่งที่ชอบได้มั้ยคะ?",
  str_voice_1501571_27 = "-คนโกหก พวกสารเลว ไปให้พ้นเลยนะ!\n-... ชู่ว คุณผู้นำทางไม่ใช่คนแบบนั้นหรอก... คิดว่านะ",
  str_voice_1501571_28 = "-โคลอสซัส... มันเดินทางไปที่เกาะเมฆาได้เร็ว?\n-ตอนนี้ยังไม่ใช่เวลาที่จะกลับไปหรอกนะ",
  str_voice_1501571_29 = "โอ๊ย! เจ็บจัง... เอ๋? ขอโทษค่ะ ฉันไม่ได้ตั้งใจจะชนคุณ! ฉ-ฉันชื่อ... ซานาเอะ ให้ฉันอุ้มคุณไปหาหมอมั้ยคะ?",
  str_voice_1501571_30 = "คราวนี้... ทุกอย่างจะต้องเป็นไปด้วยดี...",
  str_voice_1501571_31 = "พลังที่พวยพุ่ง... ราวกับข้าวสวยร้อน ๆ",
  str_voice_1501571_32 = "ฉันไม่ต้องอดอยากอีกต่อไปแล้ว...",
  str_voice_1501571_33 = "พี่น้องรวมใจ!",
  str_voice_1501571_34 = "หา... ฉ-ฉันเหรอ?",
  str_voice_1501571_35 = "หวาาา เท่านี้ก็น่าจะดีพอแล้ว...",
  str_voice_1501571_36 = "เอ่อ เรื่องนั้น ฉัน...",
  str_voice_1501571_37 = "ช่วยฉันที มานาเอะ!",
  str_voice_1501571_38 = "เอาล่ะ ไปให้พ้น ๆ ได้แล้ว!",
  str_voice_1501571_39 = "ย้ากกก!",
  str_voice_1501571_40 = "อยากหนีงั้นเหรอ? ไม่มีทางหรอกน่า!",
  str_voice_1501571_41 = "ทำไงดีล่ะ...?",
  str_voice_1501571_42 = "ฟู่... ในที่สุดก็ชนะจนได้...",
  str_voice_1501571_43 = "ไม่นะ... ฉันโดนไล่ออกแน่เลย...",
  str_voice_1501571_44 = "-แถวนี้มีงานอะไรให้ทำรึเปล่าคะ?\n-เอางานแบบที่มีค่าจ้างนะ",
  str_voice_1501571_45 = "-นี่มัน... สำหรับฉันเหรอคะ?\n-ระวังโดนหลอกล่ะ",
  str_voice_1501571_46 = "-ขอบคุณค่ะ...\n-นายนี่ใจกว้างดีนะ",
  str_voice_1501571_47 = "-คุณใจดีกับฉันเหลือเกิน...\n-เก็บความคิดสกปรกนั่นไว้กับตัวเองเลยนะ",
  str_voice_1501571_48 = "-ฉันรักเธอนะ! ฉันชอบเธอที่สุดเลย!\n-อย่างี่เง่าน่า เธอหมายถึงของขวัญต่างหาก",
  str_voice_1501571_49 = "ตอนฉันตกที่นั่งลำบาก... ฉันก็ได้พบกับผู้หญิงผมสีชมพู ถ้าไม่ได้เธอช่วยไว้ ฉันก็คงไม่มีทางนั่งเรือมาที่แอสตราได้...",
  str_voice_1501571_50 = "-ตอนที่พ่อกับแม่ของเราเสีย... ลุงฮันสึเกะก็รับฉันไปเลี้ยง\n-เจ้าบ้านั่นนิสัยแย่สุด ๆ! ติดคุกไปแบบนั้นน่ะดีแล้ว",
  str_voice_1501571_51 = "-มานาเอะเป็นพี่สาวฝาแฝดของฉันเองค่ะ... หืม? พวกเราดูไม่เหมือนกันเหรอคะ?\n-ตานายมีปัญหารึเปล่าเนี่ย?",
  str_voice_1501571_52 = "Alchemy Stars!",
  str_voice_1501571_53 = "อ๊าาาาาา!",
  str_voice_1501571_54 = "อ-อรุณสวัสดิ์ค่ะ",
  str_voice_1501571_55 = "โอ๊ะ.. สวัสดียามบ่ายค่ะ!",
  str_voice_1501571_56 = "ราตรีสวัสดิ์ค่ะ...",
  str_voice_1501571_57 = "สุขสันต์วันปีใหม่ค่ะ... หืม? ให้พูดอย่างอื่นด้วยเหรอคะ? อ่าา...",
  str_voice_1601581_1 = "ที่นี่ช่างน่าทึ่งจริง ๆ...",
  str_voice_1601581_2 = "โอเค เตรียมออกไปข้างนอกกันเถอะ",
  str_voice_1601581_3 = "ได้เวลาประชุมคิดกลยุทธ์รึยังล่ะ?",
  str_voice_1601581_4 = "อืมม...",
  str_voice_1601581_5 = "ถ้าเกิดเรื่องอะไรก็บอกฉันได้เลยนะ",
  str_voice_1601581_6 = "เอาไงต่อดีล่ะ?",
  str_voice_1601581_7 = "ดีใจที่ได้เจอนะ",
  str_voice_1601581_8 = "โลกใบนี้... น่าสนใจจริง ๆ",
  str_voice_1601581_9 = "ฉันเริ่มคิดถึงกาแฟดี ๆ สักแก้วแล้วสิ...",
  str_voice_1601581_10 = "เอาล่ะ มาเริ่มกันเถอะ",
  str_voice_1601581_11 = "ได้เลย เข้าใจแล้ว",
  str_voice_1601581_12 = "สำหรับฉัน จะอยู่ที่ไหนก็ไม่ใช่ปัญหาหรอก ยังไงมันก็ไม่ต่างกันเท่าไหร่... อืมม คิดซะว่าทำตามธรรมเนียมของคนที่นี่ก็แล้วกัน",
  str_voice_1601581_13 = "พร้อมรึยัง?",
  str_voice_1601581_14 = "แล้วแต่นายเลย",
  str_voice_1601581_15 = "สุขสันต์วันเกิด",
  str_voice_1601581_16 = "ไม่มีปัญหา ฉันพร้อมแล้ว",
  str_voice_1601581_17 = "อรุณสวัสดิ์",
  str_voice_1601581_18 = "ต้องพยายามมากกว่านี้อีกหน่อย",
  str_voice_1601581_19 = "วันนี้นอนพักหน่อยเถอะ",
  str_voice_1601581_20 = "ก็ดีนะ...",
  str_voice_1601581_21 = "จะพูดยังไงดีล่ะ...",
  str_voice_1601581_22 = "โชว์ไทม์!",
  str_voice_1601581_23 = "อิคลิพไซท์...\nคือศัตรูที่เราต้องกำจัด...",
  str_voice_1601581_24 = "เยี่ยมมาก...",
  str_voice_1601581_25 = "บราโว่",
  str_voice_1601581_26 = "ของที่ชอบเหรอ?\nถ้าต้องเลือก ก็คงจะเป็น \"ทุกอย่าง\"",
  str_voice_1601581_27 = "ของที่ไม่ชอบที่สุด?\nตอบว่า \"ก็แล้วแต่สถานการณ์\" ได้มั้ย?",
  str_voice_1601581_28 = "โคลอสซัสเป็นสถานที่ที่แปลกจริง ๆ",
  str_voice_1601581_29 = "โค้ดเนมโจ๊กเกอร์ ฉันมาเพื่อขโมยหัวใจของนาย",
  str_voice_1601581_30 = "ไม่เลว",
  str_voice_1601581_31 = "แน่นอน",
  str_voice_1601581_32 = "ฉันคิดว่าตัวเองแข็งแกร่งขึ้นแล้ว",
  str_voice_1601581_33 = "อาร์เซ็น จงปรากฏกาย!",
  str_voice_1601581_34 = "ไปกันเถอะ!",
  str_voice_1601581_35 = "เอาล่ะนะ!",
  str_voice_1601581_36 = "ฉันขอล่ะนะ!",
  str_voice_1601581_37 = "เจอนี่หน่อยเป็นไง!",
  str_voice_1601581_38 = "นี่ล่ะ!",
  str_voice_1601581_39 = "ยอมแพ้ซะ!",
  str_voice_1601581_40 = "เช็กเมท!",
  str_voice_1601581_41 = "ฉันจัดการเอง",
  str_voice_1601581_42 = "เป็นไปตามแผน",
  str_voice_1601581_43 = "ต้องมาแพ้ที่นี่เหรอเนี่ย...",
  str_voice_1601581_44 = "ว่าไง?",
  str_voice_1601581_45 = "ฉันจะรักษามันอย่างดี",
  str_voice_1601581_46 = "ถ้างั้น... จะขอรับไว้ก็แล้วกันนะ",
  str_voice_1601581_47 = "ขอบคุณ",
  str_voice_1601581_48 = "ขอบคุณนะ... ไม่สิ—เป็นเกียรติอย่างยิ่งเลยล่ะ",
  str_voice_1601581_49 = "ถ้าได้มาเยือนสถานที่ที่ไม่คุ้นเคย มันก็อดคิดถึง \"วันนั้น\" ไม่ได้หรอก...",
  str_voice_1601581_50 = "เราจะลงมือก็ต่อเมื่อทุกคนเห็นด้วยเป็นเอกฉันท์",
  str_voice_1601581_51 = "ฉันก็มีชื่อจริงเหมือนกัน แต่ในเมื่อนายเห็นฉันในแบบนี้ ก็เรียกฉันด้วยโค้ดเนมเถอะ",
  str_voice_1601581_52 = "Alchemy Stars!",
  str_voice_1601581_57 = "สุขสันต์วันปีใหม่",
  str_voice_1601581_58 = "มันจบแล้ว!",
  str_voice_1601591_1 = "ถ้าจะทำความเข้าใจโลกนี้ เราก็ควรเรียนรู้จากคนของที่นี่",
  str_voice_1601591_2 = "ฉันว่าการแต่งตัวของฉันน่าจะทำให้คนอื่นเข้าใจผิด คิดว่าฉันเป็นพวกก้าวร้าว",
  str_voice_1601591_3 = "อยากรู้จัง ว่าคนที่นี่ใช้ชีวิตกันยังไง",
  str_voice_1601591_4 = "เราต้องประเมินสถานการณ์อย่างรอบคอบ จากนั้นจึงลงมืออย่างมีเหตุผล",
  str_voice_1601591_5 = "เมื่อตั้งเป้าหมายแล้ว ก็ต้องมุ่งหน้าอย่างไม่หยุดยั้งเพื่อเป้าหมายนั้น! ใช่แล้ว มีแค่ตัวเราเองเท่านั้นที่จะไขว่คว้าสิ่งที่เราต้องการได้",
  str_voice_1601591_6 = "ถึงเราจะมีเป้าหมายแตกต่างกัน แต่ความมุ่งมั่นที่ผลักดันพวกเราคือสิ่งเดียวกัน",
  str_voice_1601591_7 = "ร่าเริงหน่อยสิ คู่หู!",
  str_voice_1601591_8 = "ถ้าเจอสิ่งที่ไม่เข้าใจ ก็จงใช้สมองคิดให้ออก และเปลี่ยนประสบการณ์ทั้งหมดให้เป็นความรู้!",
  str_voice_1601591_9 = "ตอนนี้ฉันตื่นเต้นกับโลกใบนี้ยิ่งกว่าเดิมอีกนะ อย่างเช่น... เอ่อ ที่นี่มีอะไรคล้าย ๆ กับโรงเรียนบ้างมั้ย?",
  str_voice_1601591_10 = "โทษทีนะ ฉันกำลังตั้งใจคิดอะไรอยู่น่ะ",
  str_voice_1601591_11 = "ได้เลย!",
  str_voice_1601591_12 = "โคลอสซัสนี่มีพร้อมทุกอย่างจริง ๆ",
  str_voice_1601591_13 = "ตอนนี้พี่สาวของฉันจะสบายดีมั้ยนะ",
  str_voice_1601591_14 = "ต้องทำความสะอาดที่กว้างขนาดนี้คงเหนื่อยน่าดูสินะ",
  str_voice_1601591_15 = "สุขสันต์วันเกิด! ถึงฉันจะอยู่ต่างโลก แต่การอวยพรวันเกิดก็ยังทำให้ฉันมีความสุขอยู่ดีนะ!",
  str_voice_1601591_16 = "ไม่ว่าจะเป็นการต่อสู้หรือใช้ชีวิต ข้อมูลคือสิ่งสำคัญเสมอ!",
  str_voice_1601591_17 = "อรุณสวัสดิ์ นี่เช้าวันใหม่แล้วนะ",
  str_voice_1601591_18 = "ฉันรู้ว่าเวลานี้ใคร ๆ ก็ง่วงกัน แต่ช่วยตื่นก่อนนะ เอากาแฟสักแก้วมั้ย?",
  str_voice_1601591_19 = "นี่ก็ดึกแล้วนะ... ไปนอนเถอะ",
  str_voice_1601591_20 = "นายควรพักบ้างนะ ไปกินของหวานกันมั้ย?",
  str_voice_1601591_21 = "โลกใบนี้กับโลกของเรามีหลายอย่างที่คล้ายกัน",
  str_voice_1601591_22 = "เอาล่ะ ได้เวลาทำงานแล้ว!",
  str_voice_1601591_23 = "เหมือนฉันเคยเห็นพวกอิคลิพไซท์ในฝันมาก่อนเลย",
  str_voice_1601591_24 = "โจ๊กเกอร์เป็นหัวหน้าที่พึ่งพาได้จริง ๆ! ใช่ จะบอกว่าเขาเป็นคนสำคัญของพวกเราก็ไม่ผิด",
  str_voice_1601591_25 = "สำหรับพวกเรา แฟนท่อมธีฟส์คือที่ที่เป็นของเราอย่างแท้จริง",
  str_voice_1601591_26 = "ฉันอยากไปเที่ยวไกล ๆ สักที่! แต่ต้องรอให้สอบเสร็จก่อนนะ",
  str_voice_1601591_27 = "ของที่ไม่ชอบงั้นเหรอ? อืมม แทนที่จะใช้มันเป็นข้ออ้างในการหลีกเลี่ยงอะไรบางอย่าง ฉันเลือกที่จะโฟกัสข้อดีของสิ่งนั้นมากกว่า เป็นแนวคิดที่สร้างสรรค์ดีใช่มั้ยล่ะ?",
  str_voice_1601591_28 = "อยากรู้จังว่าโคลอสซัสสร้างขึ้นด้วยเทคโนโลยีแบบไหน?",
  str_voice_1601591_29 = "ฉันชื่อควีน ยินดีที่ได้รู้จัก ถ้าอยากให้ช่วยอะไรก็บอกได้เลยนะ",
  str_voice_1601591_30 = "ฉันแข็งแกร่งขึ้นแล้วอย่างนั้นเหรอ?",
  str_voice_1601591_31 = "เราเป็นทีมที่ยอดเยี่ยม!",
  str_voice_1601591_32 = "ใช่แล้ว ทุกอย่างไปได้สวย!",
  str_voice_1601591_33 = "ลุยกันเถอะ โยฮันน่า!",
  str_voice_1601591_34 = "รับรองว่าไม่ผิดหวังแน่!",
  str_voice_1601591_35 = "พร้อมเสมออยู่แล้ว!",
  str_voice_1601591_36 = "ไม่ต้องยั้งมือแล้ว!",
  str_voice_1601591_37 = "จงตื่นขึ้นมา!",
  str_voice_1601591_38 = "กำปั้นเหล็กพิพากษา!",
  str_voice_1601591_39 = "ตอนนี้ล่ะ!",
  str_voice_1601591_40 = "ฉันจัดการเอง!",
  str_voice_1601591_41 = "ตาฉันแล้วเหรอ?",
  str_voice_1601591_42 = "เยี่ยมเลย ไปกันต่อเถอะ!",
  str_voice_1601591_43 = "ฉันไม่ยอมจบแค่นี้หรอกนะ...",
  str_voice_1601591_44 = "โคลอสซัสช่างน่าหลงใหลจริง ๆ ไม่ว่าจะในแง่ประวัติศาสตร์หรือสถาปัตยกรรม",
  str_voice_1601591_45 = "ไม่เลว...",
  str_voice_1601591_46 = "นี่ให้ฉันเหรอ?",
  str_voice_1601591_47 = "ขอบคุณนะ! ดีใจจัง",
  str_voice_1601591_48 = "ให้ฉันจริง ๆ เหรอ...? ขอบคุณนะ ฉันดีใจมากเลย!",
  str_voice_1601591_49 = "ของที่ไม่มีในตำราเรียนนี่น่าตื่นเต้นอย่างที่คิดไว้จริง ๆ!",
  str_voice_1601591_50 = "\"เคเลสไทต์คนสุดท้าย\" เหรอ? ทำไมมันทำให้ฉันนึกถึงธนาคารนะ...",
  str_voice_1601591_51 = "โคลอสซัสนี่เหมือนเป็นสิ่งที่มาจากเกมเลยแฮะ... อืมม เกม... เดิมพัน... การพนัน... ซาเอะ...!",
  str_voice_1601591_52 = "Alchemy Stars!",
  str_voice_1601591_57 = "สุขสันต์วันปีใหม่! ขอให้สมหวังในสิ่งที่ตั้งใจนะ!",
  str_voice_1601591_58 = "ยกโทษให้ไม่ได้!",
  str_voice_1501601_1 = "ว่าไงนะ? โอ๊ะ นายก็มาเดินเล่นเหมือนกันเหรอ?",
  str_voice_1501601_2 = "นี่คือโคลอสซัสงั้นเหรอ?\nได้มองแผ่นดินจากบนฟ้าก็เป็นประสบการณ์ที่พิเศษจริง ๆ",
  str_voice_1501601_3 = "โลกนี้ไม่ต้องกังวลเรื่องค่าเดินทางซะด้วย... ยอดไปเลยแฮะ",
  str_voice_1501601_4 = "น้ำในโลกนี้รสชาติเยี่ยมจริง ๆ...\nสู้น้ำก๊อกในโลกของฉันได้เลยล่ะ",
  str_voice_1501601_5 = "ยังไงชาสาหร่ายกับขนมหวานก็เป็นคู่ที่ลงตัวที่สุด",
  str_voice_1501601_6 = "พอนั่งทีไร หางบนชุดของฉัน\nก็ดูจะเกะกะอยู่ตลอดเลย...",
  str_voice_1501601_7 = "ที่นายเรียกตัวเองว่าเคเลสไทต์คนสุดท้าย มันก็เหมือนกับที่ฉันเรียกตัวเองว่าดาวรุ่งแห่งอนาคตของญี่ปุ่นนั่นแหละ",
  str_voice_1501601_8 = "โคลอสซัสนี่กว้างจริง ๆ อยากขอยืมห้องนายมาใช้เป็นสตูดิโอจัง",
  str_voice_1501601_9 = "โลกใบนี้มีอะไรที่ฉันไม่เคยเห็นเยอะมาก แรงบันดาลใจหลั่งไหลมาไม่หยุดเลยล่ะ!",
  str_voice_1501601_10 = "การออกแบบภายในของที่นี่... เป็นความชอบส่วนตัวของนายงั้นเหรอ?",
  str_voice_1501601_11 = "ให้ฉันจัดการเอง!",
  str_voice_1501601_12 = "ฉันรักโลกใบนี้นะ อยากจะบันทึกทุกอย่างไว้บนผืนผ้าใบเลย",
  str_voice_1501601_13 = "โคลอสซัสมีทุกสิ่งเพียบพร้อมจริง ๆ...\nคราวหลังช่วยพาฉันทัวร์ได้มั้ย?",
  str_voice_1501601_14 = "นายไม่คิดค่าอาหารงั้นเหรอ? ยอดไปเลย!",
  str_voice_1501601_15 = "สุขสันต์วันเกิดนะ\nขอให้ชีวิตของนายเต็มไปด้วยความงดงาม\nในปีใหม่ที่จะมาถึง",
  str_voice_1501601_16 = "ประสบการณ์จากที่นี่จะเป็นแรงบันดาลใจให้กับภาพวาดของฉัน",
  str_voice_1501601_17 = "อรุณสวัสดิ์ ใกล้ถึงเวลาอาหารเช้าแล้วใช่มั้ย?\nก่อนอื่นเลยฉันอยากชิมอาหารของที่นี่ดู",
  str_voice_1501601_18 = "เดินเล่นตอนกลางคืนเหรอ? เป็นไอเดียที่ดี\nขอเดินด้วยได้มั้ย?",
  str_voice_1501601_19 = "ยังไม่นอนอีกเหรอ? เป็นคนแปลกเหมือนกันนะเนี่ย\nแต่ฉันก็เป็นแบบนั้นเหมือนกัน",
  str_voice_1501601_20 = "ฉันก็อยากสำรวจความลึกลับของโลกใบนี้เหมือนกัน ไปกันเถอะ!",
  str_voice_1501601_21 = "หาง หูแมว เขามังกร...\nผู้สร้างโลกใบนี้\nรสนิยมดีเหมือนกันนี่",
  str_voice_1501601_22 = "มาสิ มาชมการแสดงที่งดงามที่สุดในชีวิตของนาย",
  str_voice_1501601_23 = "รูปร่างของอิคลิพไซท์...\nไม่มีคุณค่าทางศิลปะเลยแม้แต่น้อย",
  str_voice_1501601_24 = "โจ๊กเกอร์เป็นผู้นำที่เชื่อใจได้",
  str_voice_1501601_25 = "การมีพวกพ้องมันก็ไม่ใช่เรื่องแย่หรอก",
  str_voice_1501601_26 = "การเดินเป็นอะไรที่ดีนะ ช่วยลดค่าเดินทางได้เยอะเลย",
  str_voice_1501601_27 = "ของที่ฉันไม่ชอบ...?\nฉันไม่อยากยุ่งเกี่ยวกับคนที่ไม่เข้าใจศิลปะ",
  str_voice_1501601_28 = "ฉันสัมผัสความงามจากภายนอกของโคลอสซัสได้",
  str_voice_1501601_29 = "ฟ็อกซ์แห่งแฟนท่อมธีฟส์ จอมโจรแห่งจิตใจ\nมีเรื่องอยากให้ฉันช่วยใช่มั้ย?",
  str_voice_1501601_30 = "การใช้ดาบกับพู่กันก็มีบางส่วนคล้ายกันอยู่",
  str_voice_1501601_31 = "เหมือนว่าฉันจะแข็งแกร่งขึ้นนะ",
  str_voice_1501601_32 = "ทุกอย่างไปได้สวย พยายามเข้าล่ะ",
  str_voice_1501601_33 = "สกัดมันไว้ โกเอม่อน!",
  str_voice_1501601_34 = "ได้เวลาที่ฉันจะเฉิดฉายแล้ว",
  str_voice_1501601_35 = "ให้ฉันจัดการเอง",
  str_voice_1501601_36 = "หมดทางหนีสำหรับแกแล้ว",
  str_voice_1501601_37 = "ตื่นได้แล้ว!",
  str_voice_1501601_38 = "เขาคือฉันอีกคนหนึ่ง!",
  str_voice_1501601_39 = "เจอช่องว่างแล้ว!",
  str_voice_1501601_40 = "เชือดเฉือน!",
  str_voice_1501601_41 = "ตัดให้เป็นชิ้น ๆ!",
  str_voice_1501601_42 = "วิเศษ ไปคว้าชัยชนะครั้งต่อไปกันเถอะ",
  str_voice_1501601_43 = "ขอโทษนะ ที่ต้องให้นายเห็นในสภาพแบบนี้...",
  str_voice_1501601_44 = "ฉันกำลังทำอะไรอยู่น่ะเหรอ? สังเกตดูออโรเรียนน่ะสิ",
  str_voice_1501601_45 = "ให้ฉันเหรอ? งั้นก็จะรับไว้แล้วกันนะ",
  str_voice_1501601_46 = "ของขวัญให้ฉันเหรอ?\nโอ้ ยอดไปเลย!",
  str_voice_1501601_47 = "แน่ใจเหรอ? เป็นของขวัญที่งดงามจริง ๆ... ฉันจะรักษามันอย่างดี",
  str_voice_1501601_48 = "ยอดเยี่ยม ยอดเยี่ยมที่สุด!\nนายรู้ใจฉันจริง ๆ ว่าฉันชอบอะไร!",
  str_voice_1501601_49 = "ตราบใดที่ฉันยังได้วาดภาพ ฉันก็ไม่สนหรอกว่าตัวเองจะอยู่ที่ไหน",
  str_voice_1501601_50 = "ช่วงนี้ฉันชอบบริจาคเลือดน่ะ\nใช่ เป็นงานอดิเรกใหม่ของฉันเอง",
  str_voice_1501601_51 = "ฉันว่าวันนี้ซูเปอร์มาร์เก็ตมีลดราคานะ... โอ๊ะ เดี๋ยวนะ ฉันอยู่โลกอื่นนี่นา...",
  str_voice_1501601_52 = "Alchemy Stars!",
  str_voice_1501601_57 = "สุขสันต์วันปีใหม่\nได้มาฉลองที่โลกอื่นก็ไม่เลวนะ",
  str_voice_1501601_58 = "มันจบแล้ว!",
  str_voice_1501611_1 = "งั้นวันนี้เราก็มาพยายามเต็มที่กันเถอะ!",
  str_voice_1501611_2 = "ไวซ์ทำอาหารแปลก ๆ ให้เราทานด้วย แน่นอนว่าฉันกังวลเรื่องรสชาติ แต่ที่กังวลกว่าก็คือฉันไม่รู้ว่าจะอิ่มมั้ย",
  str_voice_1501611_3 = "นี่ นายรู้จักยิมนาสติกลีลารึเปล่า?",
  str_voice_1501611_4 = "หวังว่านายจะเล่าเรื่องของโลกใบนี้ให้ฉันฟังมากกว่านี้นะ",
  str_voice_1501611_5 = "ทุกคนก็คงมีหน้าที่และงานของตัวเองสินะ",
  str_voice_1501611_6 = "นายต้องยืดกล้ามเนื้ออย่างถูกต้องก่อนสู้นะ อยากให้ฉันสอนมั้ย?",
  str_voice_1501611_7 = "ฉันดีใจมาก ๆ ที่ได้ทำตามความคาดหวังของคนอื่น และนั่นก็ทำให้ฉันกดดันเหมือนกัน",
  str_voice_1501611_8 = "ที่นี่คือโคลอสซัสสินะ... น่าทึ่งจริง ๆ ที่มันมีสิ่งต่าง ๆ อยู่มากมาย!",
  str_voice_1501611_9 = "ฉันกำลังทำอะไรอยู่น่ะเหรอ...?\nคงเรียกว่าเหม่ออยู่นั่นแหละ!",
  str_voice_1501611_10 = "การออกกำลังทำให้จิตใจปลอดโปร่งได้เหมือนกันนะ\nอยากยืดกล้ามเนื้อด้วยกันมั้ย?",
  str_voice_1501611_11 = "ฉันจะพยายามช่วยนายเอง!",
  str_voice_1501611_12 = "คนเรามีสองกระเพาะ กระเพาะนึงสำหรับของหวาน อีกกระเพาะนึงสำหรับจานหลัก\nไม่ว่าจะโลกไหน นี่ก็ยังเป็นความจริงอยู่ดีนะ",
  str_voice_1501611_13 = "สิ่งที่ฉันได้เห็นที่นี่อาจเป็นแรงบันดาลใจในการแสดงของฉันก็ได้",
  str_voice_1501611_14 = "อย่าลืมดื่มน้ำให้เพียงพอตอนฝึกซ้อมล่ะ",
  str_voice_1501611_15 = "สุขสันต์วันเกิด!",
  str_voice_1501611_16 = "พักดื่มชาสักหน่อยมั้ย",
  str_voice_1501611_17 = "อรุณสวัสดิ์! อยากมาออกกำลังกายกับฉันมั้ย?",
  str_voice_1501611_18 = "นายเหนื่อยมาทั้งวันแล้ว พักให้เต็มที่เถอะนะ",
  str_voice_1501611_19 = "นอนดึกมันไม่ดีนะ\nนี่ฉันเองก็ต้องนอนแล้วเหมือนกัน",
  str_voice_1501611_20 = "ฉันชื่นชมในความพยายามนะ!",
  str_voice_1501611_21 = "ถ้าเป็นการต่อสู้ล่ะก็ ฉันจริงจังและเต็มที่เสมอ!",
  str_voice_1501611_22 = "ไปเลย ไปเลย!",
  str_voice_1501611_23 = "อิคลิพไซท์...\nพวกมันท่าทางดุร้ายจัง...",
  str_voice_1501611_24 = "ฉันจะพยายามทำตัวให้เป็นประโยชน์ของทุกคนนะ!",
  str_voice_1501611_25 = "โมน่าแปลงร่างเป็นรถได้ด้วยนะ! มันเป็นเรื่องปกติของโลกนี้งั้นเหรอ?",
  str_voice_1501611_26 = "ของชอบเหรอ?\nก็ต้องอาหารอร่อย ๆ อยู่แล้ว! แต่ก่อนการแข่งขันครั้งสำคัญ ฉันต้องควบคุมตัวเองให้ได้...",
  str_voice_1501611_27 = "ของที่ไม่ชอบ?\nคงจะเป็นช่วงชีวิตที่ตกต่ำล่ะมั้ง",
  str_voice_1501611_28 = "นายสื่อสารกับโคลอสซัสได้งั้นเหรอ?\nเหลือเชื่อจริง ๆ",
  str_voice_1501611_29 = "โค้ดเนมไวโอเล็ต\nฉันจะพยายามพัฒนาตัวเองให้เก่งขึ้นเพื่อทุกคน",
  str_voice_1501611_30 = "ฉันแข็งแกร่งขึ้นแล้ว!",
  str_voice_1501611_31 = "ฉันจะไม่ทำให้นายผิดหวัง!",
  str_voice_1501611_32 = "ฉันจะทำให้เต็มที่!",
  str_voice_1501611_33 = "เซนดริลลอน จงเริงระบำ!",
  str_voice_1501611_34 = "ลุยกันเลย!",
  str_voice_1501611_35 = "ฉันจัดการเอง!",
  str_voice_1501611_36 = "งดงามราวกับผีเสื้อ!",
  str_voice_1501611_37 = "คว้าชัยชนะด้วยมือฉันเอง!",
  str_voice_1501611_38 = "เพอร์โซน่า จงเริงระบำ!",
  str_voice_1501611_39 = "ตั้งสติไว้!",
  str_voice_1501611_40 = "ได้เวลาสำนึกตัวแล้ว!",
  str_voice_1501611_41 = "พร้อมแล้ว!",
  str_voice_1501611_42 = "ฉากจบอันงดงาม!",
  str_voice_1501611_43 = "ฉันจะล้มเหลวไม่ได้...",
  str_voice_1501611_44 = "เราจัดงานฉลองบนโคลอสซัสได้มั้ย?",
  str_voice_1501611_45 = "ฉันจะรับไว้นะ!",
  str_voice_1501611_46 = "ของขวัญให้ฉันเหรอ? ดีใจจัง!",
  str_voice_1501611_47 = "ขอบคุณนะ!",
  str_voice_1501611_48 = "ฉันรับของขวัญที่ดีแบบนี้ได้จริง ๆ เหรอ?",
  str_voice_1501611_49 = "ฉันยินดีทำทุกอย่าง เพื่อให้ความฝันเป็นจริง!",
  str_voice_1501611_50 = "ฉันเพียงคนเดียวเท่านั้นที่มีสิทธิ์เลือก!",
  str_voice_1501611_51 = "ฉันจะเดินหน้าต่อไปกับเซนดริลลอน... ร่วมกันเป็นหนึ่งเดียว!",
  str_voice_1501611_52 = "Alchemy Stars",
  str_voice_1501611_57 = "สุขสันต์วันปีใหม่!\nปีนี้ก็เต็มที่เหมือนเดิมนะ!",
  str_voice_1501611_58 = "เพอร์เฟกต์สกอร์!",
  str_voice_1501621_1 = "ฉันไม่ใช่แมวนะ! ฉันชื่อโมน่า!",
  str_voice_1501621_2 = "ฉันคิดว่าที่นี่น่าทึ่งจริง ๆ",
  str_voice_1501621_3 = "ฉันยังไม่ชินกับโลกนี้เท่าไหร่ เพราะงั้นเรื่องนำทางฉันจะยกให้เป็นหน้าที่นายก็แล้วกัน",
  str_voice_1501621_4 = "การปกปิดตัวตนเป็นหลักการทำงานของแฟนท่อมธีฟส์อยู่แล้ว",
  str_voice_1501621_5 = "หวังว่าเราจะได้ร่วมงานกันนะ!",
  str_voice_1501621_6 = "เอาล่ะ ไปกันเลย!",
  str_voice_1501621_7 = "ในฐานะแฟนท่อมธีฟส์ ฉันจะต้องรักษาทัศนคติ \"ช่วยคนอ่อนแอ ไม่หวาดกลัวคนมีอำนาจ\" เอาไว้",
  str_voice_1501621_8 = "ถ้าอยากแข็งแกร่งแบบฉัน นายก็ต้องฝึกให้หนักขึ้น!",
  str_voice_1501621_9 = "เมี้ยว สมบัติวิบวับ!\nหา? ฝันไปหรอกเหรอ?",
  str_voice_1501621_10 = "ถ้าเอาแต่เมินฉันแบบนี้ งั้นฉันจะงีบแล้วนะ",
  str_voice_1501621_11 = "โอ๊ะ ตาฉันแล้วเหรอ?",
  str_voice_1501621_12 = "ฉันสัญญาว่าคราวนี้จะทำงานให้ดี นายก็เตรียมรางวัลให้พร้อมด้วยล่ะ\nซาชิมิทูน่าอ้วน ๆ ก็ดีนะ",
  str_voice_1501621_13 = "พอรู้ตัวว่ากำลังบินอยู่บนฟ้า ก็รู้สึกตื่นเต้นขึ้นมาเลยล่ะ",
  str_voice_1501621_14 = "ได้สัมผัสวัฒนธรรมที่ต่างออกไปและเปิดหูเปิดตาให้กว้างขึ้นมันก็เป็นเรื่องดี แถมยังทำให้ฉันมีเสน่ห์ยิ่งกว่าเดิมด้วย",
  str_voice_1501621_15 = "สุขสันต์วันเกิด! หวังว่านายจะดูแลฉันต่อไปเรื่อย ๆ นะ!",
  str_voice_1501621_16 = "เมี้ยว! ฉันสบายดีเหมือนทุกครั้งนั่นแหละ!",
  str_voice_1501621_17 = "นอนหลับสบายมั้ย? เอาล่ะ งั้นวันนี้เรามาตั้งใจทำงานกันเถอะนะ!",
  str_voice_1501621_18 = "วันเวลาผ่านไปเร็วจริง ๆ ยังเหลืองานให้ทำอีกมั้ย?",
  str_voice_1501621_19 = "ไปนอนพักหน่อยเถอะ!",
  str_voice_1501621_20 = "แฟนท่อมธีฟส์ทำภารกิจลุล่วงอย่างสง่างามเสมอ",
  str_voice_1501621_21 = "อื้ม ถูกใจฉันเลยล่ะ!",
  str_voice_1501621_22 = "เริ่มการต่อสู้กันเถอะ!",
  str_voice_1501621_23 = "อิคลิพไซท์... เราต้องสืบข้อมูลพวกมันให้ละเอียด",
  str_voice_1501621_24 = "ฉันเป็นคนฝึกพวกแฟนท่อมธีฟส์เองล่ะ ไม่มีงานไหนที่พวกเขาทำไม่ได้!",
  str_voice_1501621_25 = "แฟนท่อมธีฟส์นี่เท่ไปเลยใช่มั้ยล่ะ? แหงอยู่แล้ว\nเพราะฉันเป็นคนเลือกสมาชิกเองกับมือนี่นะ",
  str_voice_1501621_26 = "สิ่งที่ชอบเหรอ?\nถ้าพูดถึงคนล่ะก็ อธิบายยังไงดีล่ะ...? ก็มีอยู่สองสามคนนะ...",
  str_voice_1501621_27 = "สิ่งที่ไม่ชอบ? พวกที่ล้อเลียนคนที่ขยันทำงานอย่างหนักล่ะมั้ง?",
  str_voice_1501621_28 = "โคลอสซัสลำใหญ่ขนาดนี้บินขึ้นฟ้าได้ยังไงกันนะ?",
  str_voice_1501621_29 = "เป็นเกียรติของนายแล้วที่ได้เจอฉัน!",
  str_voice_1501621_30 = "เสน่ห์ของฉันแรงกว่าเดิมอีกนะเนี่ย!",
  str_voice_1501621_31 = "นี่ล่ะความแข็งแกร่งของฉัน!",
  str_voice_1501621_32 = "เชื่อมือฉันได้เลย!",
  str_voice_1501621_33 = "ซอร์โร โจมตี!",
  str_voice_1501621_34 = "ตาฉันล่ะ!",
  str_voice_1501621_35 = "ฉันพร้อมแล้ว!",
  str_voice_1501621_36 = "เสียใจตอนนี้ก็สายไปแล้ว!",
  str_voice_1501621_37 = "เพอร์โซน่า จงปรากฏกาย!",
  str_voice_1501621_38 = "จงดูความมุ่งมั่นของฉันให้ดี!",
  str_voice_1501621_39 = "ตื่นได้แล้ว!",
  str_voice_1501621_40 = "ลาขาด ชาตินี้อย่าเจอกันอีกเลย!",
  str_voice_1501621_41 = "ฉันจะออกคำสั่งแล้วนะ!",
  str_voice_1501621_42 = "ยินดีด้วยนะทุกคน!",
  str_voice_1501621_43 = "มันจบแล้วสินะ...",
  str_voice_1501621_44 = "นี่ โคลอสซัสแปลงร่างแบบฉันได้รึเปล่า?",
  str_voice_1501621_45 = "โอ๊ะ ขอบคุณนะ",
  str_voice_1501621_46 = "ให้ฉันเหรอ? ขอบคุณนะ!",
  str_voice_1501621_47 = "จริงเหรอ? ขอบคุณนะ ดีใจจัง!",
  str_voice_1501621_48 = "ให้ฉันจริง ๆ เหรอ? เย่!",
  str_voice_1501621_49 = "ถ้าเรื่องทุกอย่างนี่จบลง ฉันว่าจะจัดปาร์ตี้ฉลองชัยชนะ",
  str_voice_1501621_50 = "ถึงความทรงจำของฉันคลุมเครือ แต่ฉันก็เลือกที่จะพิสูจน์ตัวเองด้วยการกระทำ! นี่ล่ะที่ทำให้ฉันเป็นที่หนึ่งเหนือใคร ๆ!",
  str_voice_1501621_51 = "ฉันไม่รู้ว่าตัวเองเริ่มมีผู้คนรายล้อมอยู่ตลอดเวลาตั้งแต่เมื่อไหร่ สมัยที่ยังอยู่ตัวคนเดียว ฉันก็จินตนาการภาพแบบนี้ไม่ออกเหมือนกัน",
  str_voice_1501621_52 = "Alchemy Stars!",
  str_voice_1501621_57 = "สุขสันต์วันปีใหม่! ฉันตั้งใจว่าปีใหม่นี้จะฝึกนายให้หนักขึ้น เตรียมตัวให้ดีล่ะ!",
  str_voice_1501621_58 = "เก็บกวาดเรียบร้อย!",
  str_voice_1601641_1 = "ฉันดีใจมากที่ตัวเองเลือกที่จะออกมาจากลูโมโพลิส ถ้าฉันพึงพอใจกับการเป็นลูกสาวท่านเจ้าเมืองแล้วตระเวนอยู่แต่ในลูโมโพลิสเท่านั้น ฉันคงไม่มีวันค้นพบด้านนี้ของตัวเอง",
  str_voice_1601641_2 = "การพิจารณาความดีและความชั่วของดาบนั้นช่างไร้ประโยชน์ เพราะดาบจะเป็นอันตรายหรือไม่ ก็ขึ้นอยู่กับมือที่ถือดาบนั้น",
  str_voice_1601641_3 = "แอสตราควรให้ทุกเชื้อชาติอารยธรรมร่วมกันเป็นเจ้าของ จัดการ และสรรค์สร้าง ซึ่งรวมถึงออโรเรียนและเคเลสไทต์",
  str_voice_1601641_4 = "จงรับผิดชอบต่อหน้าที่แม้จะเป็นเรื่องเพียงเล็กน้อย จงอย่าเกินขอบเขตแม้จะเป็นเรื่องเพียงน้อยนิด",
  str_voice_1601641_5 = "บางครั้งอำนาจจิตที่แข็งแกร่งก็เพียงพอที่จะควบคุมพลังของตนเองและเปลี่ยนแปลงความเป็นจริงได้ นี่คือความหมายของ \"จิตที่ควบคุมกาย\"",
  str_voice_1601641_6 = "หนทางยาวไกลและเต็มไปด้วยขวากหนาม แต่เราต้องไม่ยอมแพ้ แม้ทางข้างหน้ามีหมอกทึบปกคลุม แต่ตาของเราต้องแยกแยะให้ชัดเจน",
  str_voice_1601641_7 = "แสงสามารถเป็นเกราะป้องกันได้ เช่นเดียวกับที่ลูโมโพลิสครอบครอง ไม่แน่ว่าสักวันหนึ่ง แสงสว่างที่ฉันมี จะกลายเป็นเกราะปกป้องทุกคน และปกป้องเธอ...",
  str_voice_1601641_8 = "สายเลือดอาจกำหนดพลังในตัวได้ แต่มันใช้ตัดสินความต่ำต้อยและความสูงส่งของคนได้เหรอ? มันให้สิทธิ์ในการบัญชาผู้คนงั้นเหรอ? ฉันว่าไม่นะ",
  str_voice_1601641_9 = "บางครั้งฉันก็สงสัยว่าถ้าเราได้พบกันเร็วกว่านี้ และถ้านายเป็นออโรเรียน เรื่องราวต่าง ๆ จะเปลี่ยนไปยังไงนะ",
  str_voice_1601641_10 = "รู้สึกผ่อนคลายดีจัง... ในระหว่างการเดินทางไกล บางครั้งฉันได้หยุดพัก นั่งนิ่ง ๆ หรือไม่ก็นึกถึงวันเก่า ๆ ที่เคยออกลาดตระเวนในลูโมโพลิส",
  str_voice_1601641_11 = "ฉันจะปกป้องที่นี่ให้เหมือนกับที่เคยปกป้องลูโมโพลิส เพราะโคลอสซัสคือบ้านของนาย และเราก็เป็นเพื่อนร่วมทางที่เดินเคียงข้างกัน",
  str_voice_1601641_12 = "เชื้อราที่ชื่อว่า \"ความเสื่อม\" ปนเปื้อนไปทั่วลูโมโพลิสแล้ว และไม่สามารถขจัดได้หากไม่พบแหล่งที่มา",
  str_voice_1601641_13 = "อนาคตของลูโมโพลิสคืออนาคตของออโรเรียนทุกคน อารยธรรม ความเจริญรุ่งเรือง ความมั่งคั่ง และมรดกที่สืบทอด ยืนหยัดมานับพันปีและจะไม่มีวันเสื่อมคลาย",
  str_voice_1601641_14 = "สายเลือดวีรบุรุษนั้นอาจสำคัญ แต่การตัดสินใจของพวกเขาในยามวิกฤตสำคัญยิ่งกว่า ทายาทวีรบุรุษอาจรักตัวกลัวตาย ในขณะที่ผู้ที่นิรนามอาจเป็นนักรบ",
  str_voice_1601641_15 = "ฉันหวังว่าวันนี้ในปีหน้า เราจะยังได้ฉลองวันเกิดของนายด้วยกันแบบนี้นะ",
  str_voice_1601641_16 = "การจะจัดการเรื่องราชการให้ดีนั้น นายต้องค่อย ๆ ดึงเส้นด้ายที่เป็นต้นตอของปมปัญหาที่ซับซ้อนออกมา แล้วความยุ่งเหยิงเหล่านั้นจะคลี่คลายลง",
  str_voice_1601641_17 = "เมื่อนายตื่นนอนตอนเช้าและมีแสงแดดสาดส่องมาถึงบนเตียง นายจะอารมณ์ดีไปทั้งวัน",
  str_voice_1601641_18 = "ทำงานมาทั้งวันแล้ว นายคงจะเหนื่อยมากนะ พักผ่อนสักนิดด้วยการฟังเพลงคลาสสิกดีมั้ย?",
  str_voice_1601641_19 = "ทำงานตอนดึก ๆ ไปพร้อมกับเค้กกะทิสตรอว์เบอร์รี ก็ได้บรรยากาศดี ๆ ไปอีกแบบ",
  str_voice_1601641_20 = "ลูโมโพลิสนั้นเก่าแก่และมั่นคง แต่อีกด้านหนึ่งของสันติสุขอย่างยั่งยืนนี้ คือเงามืดที่เติบโตอย่างเงียบ ๆ ภายใต้แสง",
  str_voice_1601641_21 = "การใช้เหตุผลมากจนเกินไปจะทำให้คนเราสูญสิ้นความรู้สึก ฉันเกรงว่าถ้าอิลลูมินาเดินบนเส้นทางนี้ไกลเกินไป พวกเขาจะกลายเป็นเครื่องจักรที่ไร้หัวใจ",
  str_voice_1601641_22 = "ขอเทิดทูนรัตติกาลสีขาว โปรดส่องสว่างนำทางข้างหน้าด้วยเถิด!",
  str_voice_1601641_23 = "แสงสว่างและความมืดไม่อาจอยู่ร่วมกันได้ เมื่อสิ่งหนึ่งเลือนลับ อีกสิ่งหนึ่งจะรุ่งโรจน์",
  str_voice_1601641_24 = "ในฐานะเจ้าเมือง ภาระหน้าที่ของชวาตส์นั้นยิ่งใหญ่และยุ่งยากเหลือประมาณ จนฉันเกรงว่าเขาจะต้องประนีประนอมในบางครั้ง",
  str_voice_1601641_25 = "เมื่อก่อนตอนที่ฉันกับไวซ์เป็นเพื่อนร่วมชั้นกัน ฉันไม่เคยสนใจเธอเลย แต่นักเรียนจากต่างแดนที่ไม่โดดเด่นในตอนนั้น อาจมีชื่อเสียงมากกว่าฉันในอนาคตก็ได้",
  str_voice_1601641_26 = "หากปราศจากความสงบเรียบร้อยของประชาชน อารยธรรมจะล่มสลาย นำมาซึ่งมหันตภัยที่เลวร้ายยิ่งกว่าภัยพิบัติทั้งปวง",
  str_voice_1601641_27 = "ความสามารถที่ทรงพลังไม่ใช่สิ่งที่น่ากลัว สิ่งที่น่ากลัวคือการไม่มีสำนึกรับผิดชอบและหลักการที่สอดคล้องซึ่งกันและกัน ทั้งสองนี้ไม่อาจขาดอย่างใดอย่างหนึ่ง ไม่เช่นนั้นจะเกิดหายนะอย่างหลีกเลี่ยงไม่ได้",
  str_voice_1601641_28 = "สักวันหนึ่ง โคลอสซัสอาจกลายเป็นสัญลักษณ์ของออโรเรียนคู่กับเมืองลูโมโพลิส",
  str_voice_1601641_29 = "คาร์ลีน เดอ ชวาตส์ อยู่ที่นี่แล้ว ไม่ต้องห่วงหรอกนะ ความเยือกเย็นไม่ได้ไปจากฉัน เป็นเพียงชั่วขณะที่ฉันเลือกเปลวไฟที่โชติช่วง",
  str_voice_1601641_30 = "เปล่งประกายยิ่งขึ้น!",
  str_voice_1601641_31 = "หอกปะทุไฟ!",
  str_voice_1601641_32 = "ความสว่างไสวเป็นของเรา",
  str_voice_1601641_33 = "แสงสว่างอยู่กับจิตวิญญาณ",
  str_voice_1601641_34 = "หอกของฉันเป็นส่วนหนึ่งของนาย",
  str_voice_1601641_35 = "พร้อมโจมตี",
  str_voice_1601641_36 = "โจมตีพิชิตให้ได้",
  str_voice_1601641_37 = "แสงสว่าง จงเจิดจ้า!",
  str_voice_1601641_38 = "ภายใต้หอกนี้ จะไม่มีเงามืด!",
  str_voice_1601641_39 = "พิฆาตศัตรูให้สูญสิ้น",
  str_voice_1601641_40 = "ไม่จำเป็นต้องเมตตา",
  str_voice_1601641_41 = "นายเลือกได้ฉลาดมาก",
  str_voice_1601641_42 = "การนำทัพไปสู่ชัยชนะเป็นหน้าที่ของผู้บัญชาการ",
  str_voice_1601641_43 = "ถ้ารู้ว่าไม่ชนะ ก็ถอยมาตั้งหลักก่อน",
  str_voice_1601641_44 = "โคลอสซัสบินได้ยอดเยี่ยมจริง ๆ ถ้านำไปใช้ลาดตระเวนอาณาเขตล่ะก็...",
  str_voice_1601641_45 = "ขอบคุณสำหรับน้ำใจนะ",
  str_voice_1601641_46 = "นายเป็นคนที่เข้าใจฉันจริง ๆ...",
  str_voice_1601641_47 = "เจตนาดีของนาย ฉันเข้าใจอย่างถ่องแท้",
  str_voice_1601641_48 = "ขอเทิดทูนรัตติกาลสีขาว ฉันจะไม่มีวันลืมของขวัญที่นายให้มา",
  str_voice_1601641_49 = "ลูมินาช่างวิเศษจริง ฉันคิดว่าตัวเองทำได้แค่ควบคุมน้ำแข็ง ไม่เคยคิดเลยว่าจะใช้หอกเพลิงในการต่อสู้ได้ด้วย",
  str_voice_1601641_50 = "โลหิตไม่มีชนชั้นวรรณะ จึงเป็นเรื่องน่าขันที่จะใช้มันตัดสินความสูงส่งและต่ำต้อย ผู้มีอำนาจปกครองต้องมีความสามารถ จึงจะได้รับความไว้วางใจจากทุกคน",
  str_voice_1601641_51 = "บางครั้งฉันฝันเห็น ท่ามกลางความมืดมิด แสงสว่างในดวงตาของทุกคนถูกบดบัง แต่ฉันยังคงเดินหน้าต่อไปพร้อมกับคบเพลิงในมือ",
  str_voice_1601641_52 = "Alchemy Stars",
  str_voice_1601641_53 = "เพื่อนร่วมทาง",
  str_voice_1601641_54 = "เริ่มต้นวันใหม่แล้วนะ",
  str_voice_1601641_55 = "นี่ก็เที่ยงแล้วนะ",
  str_voice_1601641_56 = "และแล้วก็จะจบลงอีกหนึ่งวัน",
  str_voice_1601641_57 = "ฉันรู้สึกเป็นเกียรติที่ได้เดินทางกับนาย หวังว่าในปีต่อไปเราจะยังคงก้าวไปข้างหน้าด้วยกัน",
  str_voice_1501651_1 = "อุปกรณ์ขับเคลื่อนเป็นรากฐานของหุ่นยนต์ไดนามิก ต้องคำนึงถึงวัสดุพลังงาน อัตราส่วนการแปลง โครงสร้าง และการส่งสัญญาณ โอย มันซับซ้อนไปหมด",
  str_voice_1501651_2 = "อยากรู้จังว่าชาวเคเลสไทต์มีนักวิทยาศาสตร์บ้างหรือเปล่า ถ้าไม่อย่างนั้นพวกเขาจะดูแลรักษาโคลอสซัสที่น่ามหัศจรรย์ลำนี้ยังไง เอ่อ... ฉันพูดอะไรที่ไม่ควรพูดหรือเปล่าเนี่ย?",
  str_voice_1501651_3 = "วัตถุของชาวเคเลสไทต์มีอะไรแปลก ๆ หลายอย่าง คราวก่อนฉันพยายามวาดภาพหน้าตรงของหิ่งห้อย แต่วาดทั้งวันทั้งคืนก็ไม่สำเร็จ...",
  str_voice_1501651_4 = "การออกแบบโครงร่างก็เป็นศิลปะอย่างหนึ่ง! ไวซ์พูดถูก และยังเหนือกว่าการวาดภาพธรรมดา เพราะมันต้องอาศัยความแม่นยำ",
  str_voice_1501651_5 = "หุ่นยนต์ไดนามิกไม่เพียงแต่มีประโยชน์ในการต่อสู้เท่านั้น แต่ยังใช้ในการสำรวจ การขุดค้น และการก่อสร้างได้อีกด้วย พวกเขาจะเป็นเครื่องจักรที่สำคัญในอนาคตของสหพันธรัฐอิลลูมินา",
  str_voice_1501651_6 = "ผู้นำทาง ฉันทำความเข้าใจพิมพ์เขียวที่ออกแบบใหม่แล้วนะ! คราวก่อนฉันคำนวณผิดไป แต่คราวนี้น่าจะไม่มีปัญหาแล้ว อีกไม่นานหุ่นยนต์ไดนามิกที่สมบูรณ์แบบก็จะ...",
  str_voice_1501651_7 = "คุณอยากออกแบบร่างงั้นเหรอ? ฉันมีวงเวียนกับไม้บรรทัดซึ่งเป็นมรดกตกทอดของครอบครัว ไวซ์เคยมาขอยืม ฉันยังไม่ให้เธอยืมเลยนะ...",
  str_voice_1501651_8 = "ผู้นำทาง ไม่ซ่อมแซมโคลอสซัสครั้งใหญ่หน่อยเหรอ? หรือปรับปรุงนิดหน่อยก็ยังดีนะ ไม่ต้องกังวล ฉันช่วยคุณได้เต็มที่ในด้านวิศวกรรม",
  str_voice_1501651_9 = "อืม... หุ่นยนต์ไดนามิกตัวนี้ใกล้หมดสภาพแล้วล่ะ พอจะมีเทคโนโลยีเคเลสไทต์ที่ซ่อมมันได้บ้างไหม?",
  str_voice_1501651_10 = "มานั่งเล่นแล้วงีบหลับในหุ่นยนต์สักพักไหม? ไม่มีใครอยู่เลย... เอ่อ คือ... ฉันไม่ได้อู้งานนะ!",
  str_voice_1501651_11 = "ปัญหาด้านวิศวกรรมยกให้เป็นหน้าที่ฉันเถอะ เพราะงานด้านอื่นฉันเป็นได้แค่ลูกมือเท่านั้น ให้คำแนะนำไม่ได้ด้วยซ้ำ แบบนี้จะดีเหรอ?",
  str_voice_1501651_12 = "ได้ยินว่าคุณเคยไปมาแล้วหลายที่ เคยเจออะไรแปลกใหม่ที่น่าสนใจบ้างไหม? เช่นแร่สีเขียวจากนอร์ธแลนด์ หรือเลือดหนอนทรายจากทะเลทรายเรดีเซล...",
  str_voice_1501651_13 = "นักวิทยาศาสตร์เป็นบุคลากรที่สำคัญที่สุด พวกเขาเป็นจิตวิญญาณขององค์กร เหมือนกับเครื่องยนต์ของหุ่นยนต์ไงล่ะ!",
  str_voice_1501651_14 = "ใครกันนะที่คิดค้นการวิ่งระยะไกลและการว่ายน้ำ? สองอย่างนี้น่าจะถูกกำจัดทิ้งไปเหมือนกับการออกแบบที่ผิดพลาด!",
  str_voice_1501651_15 = "วันเกิดก็ต้องให้ของขวัญใช่มั้ยล่ะ คุณอยากได้อะไรเหรอ? โมเดลหุ่นยนต์ดีมั้ย?",
  str_voice_1501651_16 = "ผู้นำทาง วันนี้เขียนกำหนดการทำงานหรือยัง? ถ้าไม่วางแผนให้ดี งานคุณจะยุ่งเหยิงจนควบคุมไม่ไหวนะ",
  str_voice_1501651_17 = "คุณตื่นเช้าจังเลย ต้องการปรับแต่งโคลอสซัสสักหน่อยไหม?",
  str_voice_1501651_18 = "บางครั้งก็ต้องหยุดพักบ้างนะ เช่น นอนเล่นบนเปลญวนสักพักนึงก็ได้...",
  str_voice_1501651_19 = "กลางดึกเป็นเวลาที่เหมาะกับการคำนวณและร่างแบบนะ! ถ้ามีแรงบันดาลใจด้วยก็ยิ่งดีเลย",
  str_voice_1501651_20 = "อิลลูมินาได้รวบรวมนักวิทยาศาสตร์ชั้นนำของแอสตราไว้ทั้งหมด ฉันโชคดีมากที่ได้รับคำแนะนำจากพวกเขา",
  str_voice_1501651_21 = "การทำงานของช่างเครื่องเรดีเซล เวรนช์บางคนนั้นน่าทึ่งมาก ทั้ง ๆ ที่ไม่มีทฤษฎีทางวิทยาศาสตร์เลย แต่ก็ซ่อมสิ่งต่าง ๆ ได้โดยอาศัยแค่ประสบการณ์",
  str_voice_1501651_22 = "ขออิลลูมินาจงเจิดจำรัส! ฉันจะต้องสร้างหุ่นยนต์ไดนามิกตัวนั้นให้สำเร็จ!",
  str_voice_1501651_23 = "โครงสร้างร่างกายของอิคลิพไซท์คล้ายกับเครื่องจักรที่ซับซ้อนบางประเภท ใครเป็นคนสร้างพวกมันขึ้นมานะ...",
  str_voice_1501651_24 = "หากไม่มีเจ้าหน้าที่วิทยาการกรอนรู ฉันคงยังติดแหง็กอยู่กับแบบร่างของหุ่นยนต์ ไม่เป็นชิ้นเป็นอันแม้แต่น็อตตัวเดียว",
  str_voice_1501651_25 = "เรื่องการขับและควบคุมรถไฟ หัวหน้าคารอนเป็นอัจฉริยะเลยล่ะ แต่เรื่องอื่นในชีวิตประจำวัน... แค่ก ๆ ทำใจให้ชินก็โอเค",
  str_voice_1501651_26 = "ต่อให้ฉันมีไอคิวมากกว่านี้สิบเท่า ก็ไม่สามารถประดิษฐ์อะไรที่สบายแบบเปลญวนได้! ถ้าไม่ต้องสร้างหุ่นยนต์เนี่ยนะ ฉันจะนอนเปลวันละ 20 ชั่วโมงเลย",
  str_voice_1501651_27 = "คนที่ล้อเลียนคนอื่นในที่สาธารณะ ต้องจับไปโยนใส่ในเตาหลอม",
  str_voice_1501651_28 = "โครงสร้าง ระบบ และวัสดุส่วนประกอบของโคลอสซัส ล้ำหน้าเทคโนโลยีปัจจุบันไปไกลมาก อยากรู้จริง ๆ ว่าอัจฉริยะท่านใดอยู่เบื้องหลังการออกแบบนี้...",
  str_voice_1501651_29 = "ถึงฉันจะมีหน้าที่ขุดอุโมงค์ แต่ที่จริงฉันเป็นวิศวกรนะ! หุ่นยนต์ไดนามิกตัวนี้เป็นผลงานของฉันเอง แต่มันเป็นต้นแบบที่ยังไม่สมบูรณ์ อย่าแตะต้องเด็ดขาด! อ้อ อีกอย่าง ฉันชื่อเซียล",
  str_voice_1501651_30 = "พลังเทคโนโลยีของฉันแข็งแกร่งขึ้นแล้ว",
  str_voice_1501651_31 = "อัปเดตระบบแล้ว",
  str_voice_1501651_32 = "เสริมโครงสร้างอีกขั้น",
  str_voice_1501651_33 = "ฉันรู้สึกเปี่ยมไปด้วยพลังงาน",
  str_voice_1501651_34 = "จะให้ช่วยขุดอุโมงค์งั้นเหรอ?",
  str_voice_1501651_35 = "สติกซ์ เตรียมพร้อม",
  str_voice_1501651_36 = "ลูกศรสุริยะอยู่ในโหมดสแตนด์บาย",
  str_voice_1501651_37 = "ลูกศรสุริยะ ยิง!",
  str_voice_1501651_38 = "ลูกศรสุริยะ กระหน่ำทุกพื้นที่!",
  str_voice_1501651_39 = "ไม่สิ้นหนทาง! ยิง!",
  str_voice_1501651_40 = "โหลดเต็มพิกัด! ยิง!",
  str_voice_1501651_41 = "ฉันจะเป็นเครื่องยนต์ให้ทีมเอง!",
  str_voice_1501651_42 = "ง่ายยังกับขันสกรูให้แน่น!",
  str_voice_1501651_43 = "ฉันขุดอุโมงค์หลบหนีไว้แล้ว...",
  str_voice_1501651_44 = "โครงสร้างของโคลอสซัสลำนี้มีเอกลักษณ์ไม่เหมือนใคร ต้องวัดและศึกษาให้ละเอียด",
  str_voice_1501651_45 = "ฉันจะเก็บมันไว้ในห้องนะ",
  str_voice_1501651_46 = "ว้าว! ให้ฉันเหรอ? ฉันจะเก็บไว้นะ!",
  str_voice_1501651_47 = "ขอบคุณมากนะ ฉันจะตอบแทนด้วยอะไรดีล่ะ?",
  str_voice_1501651_48 = "เยี่ยมเลย! ฉันจะสร้างหุ่นยนต์ให้คุณตัวนึงดีมั้ย?",
  str_voice_1501651_49 = "หุ่นยนต์ส่วนขาไม่เข้ากับเซ็ตที่ใส่อยู่ มันเป็นชิ้นส่วนจากโครงการที่ล้มเหลว",
  str_voice_1501651_50 = "พ่อแม่ของฉันเป็นคนงานธรรมดา แต่พวกเขาสนับสนุนให้ฉันเป็นวิศวกร ซึ่งก็เป็นทางเลือกที่ถูกแล้วล่ะ",
  str_voice_1501651_51 = "ถ้าไม่ใช่เพราะความขี้เล่น ฉันคงทำหุ่นยนต์ที่สมบูรณ์แบบสำเร็จไปตั้งนานแล้ว",
  str_voice_1501651_52 = "Alchemy Stars",
  str_voice_1501651_53 = "คุณอยู่ตรงนี้ ใช่ไหม?",
  str_voice_1501651_54 = "ตอนเช้าต้องไขลานตัวสำคัญให้แน่นนะ!",
  str_voice_1501651_55 = "แม้แต่เครื่องจักรยังต้องงีบหลับหลังมื้อเที่ยง",
  str_voice_1501651_56 = "หยุดงานไว้ชั่วคราวก็ได้นะ",
  str_voice_1501651_57 = "ปีใหม่อีกปีแล้ว... ฉันควรจะเร่งออกแบบหุ่นยนต์ให้คืบหน้า",
  str_voice_1601661_1 = "ฮึ่ม รอเดี๋ยวเถอะนะ! วันไหนที่ฉันกับไคโลแข็งแกร่งขึ้นมา เราจะแก้แค้นทุกคนที่เคยดูถูกฉันเลย!",
  str_voice_1601661_2 = "หา? นายอยากรู้ว่าแมวจรคุยอะไรกัน เวลารวมตัวกันตอนกลางคืนน่ะเหรอ? ไม่รู้จะดีกว่านะ เพราะมันเกี่ยวข้องกับการยึดครองแอสตราน่ะ...",
  str_voice_1601661_3 = "\"เห็ดโกโก้พิษ สัตว์มหัศจรรย์ที่หน้าตาเหมือนเห็ด พวกมันจะเกิดภาพลวงตาที่แสนสบายหลังจากกินช็อกโกแลตเข้าไป จากนั้นก็ยกฝูงไปโจมตีร้านขายขนมหวานในเมือง\" ฉันว่าอาจารย์แต่งเรื่องเองแหงเลย",
  str_voice_1601661_4 = "ผิวของฉันเรียบเนียนกว่าที่เคย ทั้งนุ่มทั้งเด้งเลยตอนนี้ แต่ไม่ต้องอิจฉาฉันหรอกนะ PlayerName ฉันจะแบ่งผลิตภัณฑ์บำรุงผิวให้นายเอง นี่ทำจากสารสกัดจากร่างกายไคโลเลยนะ",
  str_voice_1601661_5 = "เตือนภัย! เตือนภัยขั้นสูงสุด! ฉันตรวจจับสัญญาณอันตรายได้! สัตว์มหัศจรรย์กำลังมา มันอยู่ข้างหลังฉันนี่เอง อ้าว PlayerName นี่นา",
  str_voice_1601661_6 = "ไคโลจะตัวสีน้ำเงินขาวเวลาที่มันสงบ และจะกลายเป็นสีดำแดงเมื่อมีสิ่งเร้า แต่ว่าฉันเคยเห็นมันกลายเป็นสีรุ้งวิบวับเหมือนแสงไฟนีออนด้วย มันแปลว่าอะไรนะ? หรือว่าฝันไปกันแน่?",
  str_voice_1601661_7 = "ไคโลส่ายก้นไปมา แล้วก็กระโดดสองสามครั้ง มันพยายามจะบอกอะไร? นี่มันโกรธฉันเหรอ?",
  str_voice_1601661_8 = "อ๋ออออ ฉันนี่โก๊ะจังเลย แปลว่าที่จริงแล้ว คุณเพนกวินกับคุณหมีขั้วโลกนี่เป็นชาวออโรเรียนใช่ไหม?! แล้วคุณจระเข้คนนั้น... ฉันว่าการสำรวจสัตว์มหัศจรรย์ของฉันได้เริ่มต้นขึ้นแล้ว...",
  str_voice_1601661_9 = "น่าเศร้าจังเลยนะ PlayerName ที่นายต้องอยู่ตัวคนเดียว เอาเป็นว่า... ฉันรับเลี้ยงนายดีไหม? ฉันเป็นเจ้านายที่มีความรับผิดชอบนะ และจะดูแลนายเป็นอย่างดีเลย",
  str_voice_1601661_10 = "ฮึ่ยยยย เจ้าบื้อไคโล กับตาบื้อ PlayerName! เลิกจ้องหน้าฉันได้แล้ว!!",
  str_voice_1601661_11 = "ให้ผู้หญิงน่ารัก ๆ มาทำงานเป็นคนรับใช้ แถมต้องยืนยิ้มให้ลูกค้าทั้งวัน เอาเปรียบกันเกินไปแล้วนะอาจารย์ เพิ่มเบี้ยเลี้ยงให้ฉันซะดี ๆ",
  str_voice_1601661_12 = "ฉันเกลียดคนที่ดูถูกฉัน และเกลียดคนที่ดูถูกอาจารย์ของฉันมากยิ่งกว่า!",
  str_voice_1601661_13 = "ว้ากกกก!!! ท-ทำไมมาหลอกให้ฉันตกใจแบบนั้นล่ะ?",
  str_voice_1601661_14 = "ฉันรู้ดีว่าตัวเองน่ารักแค่ไหน เลิกลูบหัวฉันได้รึยังเนี่ย?",
  str_voice_1601661_15 = "สุขสันต์วันเกิดแด่... วันนี้วันคล้ายวันเกิดนายเหรอ?! ต้องบันทึกไว้ใน \"การผจญภัยของนักสัตว์มหัศจรรย์วิทยา\" ซะแล้ว",
  str_voice_1601661_16 = "สวัสดีตอนเช้า สวัสดีตอนบ่าย และสวัสดีตอนเย็น เป็นไง ฉันทักทายเผื่อไว้ทั้งวันเลย!",
  str_voice_1601661_17 = "นี่มันยังเช้าเกินไป ฉันต้องกลับไปนอนต่อก่อน ไม่งั้นฉันจะไม่โต",
  str_voice_1601661_18 = "ได้เวลาอาหารเย็นแล้ว! นายชอบสาหร่ายไหม? ฉันแบ่งให้ก็ได้",
  str_voice_1601661_19 = "หาาา... ชิ่วว! หาวอยู่ดี ๆ ก็จามเฉยเลย แง่ม ๆ...",
  str_voice_1601661_20 = "เราคือทีมผู้เชี่ยวชาญที่เป็นมืออาชีพและวางใจได้ เราอุทิศตนเพื่อการศึกษาและคุ้มครองสัตว์มหัศจรรย์",
  str_voice_1601661_21 = "ขอโทษที ฉันชอบแต่สัตว์มหัศจรรย์อย่างเดียว ไม่สนใจออโรเรียนเลยน่ะ",
  str_voice_1601661_22 = "จับมา พัฒนา แล้วปล่อยไป!",
  str_voice_1601661_23 = "อิคลิพไซท์นี่สืบพันธุ์ยังไงเหรอ? ประชากรพวกมันไม่เคยลดลงเลย เป็นไปได้ไหมว่าพวกมันสืบพันธุ์แบบไม่อาศัยเพศ?",
  str_voice_1601661_24 = "ชายวัยกลางคนที่ไม่มีงาน ชีวิต หรือแม้แต่การแสดงตัวตน อาจารย์นี่เป็นคนโกหกทั้งเพ!",
  str_voice_1601661_25 = "ถึงรุ่นพี่ของฉันจะเป็นปลาหมึกแปลก ๆ แต่เธอก็เป็นผู้หญิงที่นิสัยดีนะ",
  str_voice_1601661_26 = "ฉันชอบแก้วที่ส่องประกาย ลูกกวาด และอัญมณี แต่สิ่งที่ฉันชอบที่สุดก็คือสัตว์มหัศจรรย์",
  str_voice_1601661_27 = "นี่! PlayerName! อย่าทำเป็นเฉยชากับฉันสิ!",
  str_voice_1601661_28 = "ฉันอยากเพิ่มห้องฟักไข่ ห้องอนุบาล ห้องฝึกฝน แล้วก็สุสานสำหรับสัตว์มหัศจรรย์บนยานโคลอสซัส",
  str_voice_1601661_29 = "ใช่แล้ว ฉันคือผู้ดูแลสัตว์มหัศจรรย์ในตำนาน และนี่ก็คือไคโล คู่หูของฉัน ฮึ่ม นายกลัวรึยังล่ะ?",
  str_voice_1601661_30 = "ตอนนี้ฉันแข็งแกร่งขึ้นแล้ว! แต่ท่าทางไคโลจะยังเหมือนเดิม",
  str_voice_1601661_31 = "ผิวฉันสัมผัสได้ถึงความวิเศษ!",
  str_voice_1601661_32 = "อ๊ะ สัญชาตญาณของฉันรู้สึกซาบซ่านไปหมดแล้ว!",
  str_voice_1601661_33 = "แปลงร่างและเกิดใหม่! พัฒนาเลย ฟีญ่า!",
  str_voice_1601661_34 = "หา? นี่ควรเป็นทีมที่มีหกคนไม่ใช่เหรอ?",
  str_voice_1601661_35 = "พร้อมแล้ว พร้อมแล้ว พร้อมแล้ว!",
  str_voice_1601661_36 = "เจอดีแน่!",
  str_voice_1601661_37 = "ไปเลยไคโล ใช้แผน A!",
  str_voice_1601661_38 = "ไคโล เปลี่ยนเป็นแผน B!",
  str_voice_1601661_39 = "มาช่วยหน่อย!",
  str_voice_1601661_40 = "พลังแห่งมิตรภาพ!",
  str_voice_1601661_41 = "ฮิฮิ แน่นอน ฉันควรเป็นกัปตัน!",
  str_voice_1601661_42 = "ปฏิบัติการสำเร็จ!",
  str_voice_1601661_43 = "ฉัน... ฉันเกลียดความรู้สึกนี้!!",
  str_voice_1601661_44 = "พื้นผิวแบบนี้... นี่ไคโลน้ำหนักขึ้นเหรอ?",
  str_voice_1601661_45 = "ให้ฉันจริง ๆ เหรอเนี่ย?",
  str_voice_1601661_46 = "หืมม PlayerName อย่าบอกนะว่านายชอบ...",
  str_voice_1601661_47 = "ว้าว! ของขวัญนี่นา!",
  str_voice_1601661_48 = "งู้ยยยยย!! นายนี่ดีกับฉันจังเลย!",
  str_voice_1601661_49 = "ฉันยังจำได้ ข้อความที่เขียนไว้ในบทนำของหนังสือ \"สารพัดสัตว์พิสดารสุดน่ารัก\" เขียนไว้ว่า \"แด่ผู้อ้างว้างและไร้ที่พึ่งพา อย่าจองจำตัวเองด้วยความคิดในเชิงลบเลย เปิดตาและเปิดใจรับโลกภายนอกเถิด ในโลกนี้ยังมีสิ่งมีชีวิตนับไม่ถ้วนที่เหมือนกับเจ้า แต่ก็แตกต่างกันอยู่บ้าง\"",
  str_voice_1601661_50 = "เฮ้อ! อาจารย์เนี่ย เป็นคนไม่น่าไว้ใจที่สุดเท่าที่ฉันเคยเจอมาเลย ส่วนรุ่นพี่ฉันก็เป็นผู้หญิงประหลาดอีก หรือว่าคนปกติเขาไม่อยากเป็นนักสัตว์มหัศจรรย์วิทยากันนะ? นี่ฉันเลือกอาชีพผิดรึเปล่า...",
  str_voice_1601661_51 = "\"เคารพในนิสัยและความปรารถนาของสัตว์มหัศจรรย์ และอย่ายัดเยียดความคิดของตัวเองให้กับพวกมัน\" คนเราต้องเข้าใจเรื่องนี้จริง ๆ นะถึงจะเข้ากับสัตว์พวกนี้ได้ เรื่องนี้ฉันเองก็ไม่ได้เข้าใจอย่างถ่องแท้ จนกระทั่งเมื่อไม่นานนี้เอง",
  str_voice_1601661_52 = "Alchemy Stars",
  str_voice_1601661_53 = "ฉันชื่อฟีญ่า!",
  str_voice_1601661_54 = "อรุณสวัสดิ์",
  str_voice_1601661_55 = "สวัสดีตอนบ่าย สวัสดีตอนบ่าย!",
  str_voice_1601661_56 = "ราตรี—*หาว* สวัสดิ์",
  str_voice_1601661_57 = "ปีใหม่แล้ว! ปีใหม่! สุขสันต์วันปีใหม่!!",
  str_voice_1601671_1 = "ภาพนิมิตที่ชัดเจนสามารถดึงเราลงสู่ห้วงอารมณ์ที่แรงกล้าได้ สิ่งที่น่าตื่นเต้นและเย้ายวนยิ่งกว่านั้นก็คือ ภาพนิมิตเหล่านั้นทำให้เราเชื่อมโยงกับทุกสิ่งที่เรารู้จักได้...",
  str_voice_1601671_2 = "เสียงฟองคลื่นแตกซ่าเมื่อกระทบข้างเรือ เสียงลมหลอกหลอนที่พัดมากระทบรอยแยกที่ตัวเรือ เสียงปาฏิหาริย์ที่รอการสังเวย พลุ่งพล่านเข้ามาหาฉัน เรียกร้องที่จะได้รับการเผยให้เป็นที่ประจักษ์",
  str_voice_1601671_3 = "ฉันคุ้นเคยกับกลิ่นอายแห่งความสิ้นหวังเป็นอย่างดี เพราะฉันเองก็เคยเป็นหนึ่งในนั้นมาก่อน",
  str_voice_1601671_4 = "ไพ่บางใบพบหนทางท่ามกลางความคิดที่กระจัดกระจายจำนวนมหาศาล และคนโง่เขลาที่ไม่สามารถยอมรับไพ่ที่ตัวเองได้รับก็จะแสดงความหยาบช้าออกมา",
  str_voice_1601671_5 = "สถานการณ์เริ่มร้อนแรงขึ้น ไพ่นี้จะทำให้ศัตรูสั่นเทา",
  str_voice_1601671_6 = "เสียงเพลงบรรเลงแห่งความแค้นที่ผสมปนเปกัน ไพ่เงาวับที่สับไปมา ฮึ กลิ่นทองคำช่างอบอวลยิ่งนัก",
  str_voice_1601671_7 = "ปาฏิหาริย์ที่เราเรียกว่ามายากลนี้ โดยแก่นแท้ก็คือการพนันระหว่างนักมายากลกับอุปกรณ์ในการแสดงของเขานั่นเอง คุณต้องบังคับร่างกายให้จดจำวิธีเล่นที่ถูกต้องให้ได้",
  str_voice_1601671_8 = "ความรู้สึกแปลก ๆ นี้คืออะไรกัน? มันเริ่มยากขึ้นเรื่อย ๆ ที่จะทำสีหน้านิ่งเฉย และดูเหมือนแผ่นหลังของฉันจะเริ่มมีเหงื่อซึมออกมา... เข้าใจแล้ว ต้องมีศัตรูจำนวนมากอยู่แถวนี้แน่นอน",
  str_voice_1601671_9 = "ขอโทษที ฉันเหงื่อออกซะแล้ว แค่ยืนจ้องนายอยู่ตรงนี้ ฉันก็ถึงกับต้องเผยไพ่ในมือ",
  str_voice_1601671_10 = "ฉันไม่ชอบเวลาที่ตัวเองเหม่อลอย ความคิดที่ล่วงล้ำเดินทางไปมาได้ตามใจชอบในหัวฉัน มุ่งหน้าไปสู่ความทรงจำในช่วงเวลาต่าง ๆ ที่ฉันพยายามจะละทิ้งไป",
  str_voice_1601671_11 = "ที่พักอาศัยแห่งนี้สงบเงียบมาก มันทำให้คนเรารู้สึกอึดอัด หรือว่าฉันควรจะถอดศีรษะออกซะ... ไม่สิ คนเราถอดศีรษะออกไม่ได้",
  str_voice_1601671_12 = "ฉันไม่สนใจสิ่งเปราะบางใด ๆ นอกจากมายากลเท่านั้น สิ่งเหล่านั้นเยาะเย้ยฉัน เพราะฉันเยาะเย้ยมัน",
  str_voice_1601671_13 = "การแสดงมายากลคือการนำเสนอที่สะดุดตา ซึ่งมีรากฐานอยู่บนทักษะเฉพาะทาง และภาพอันตระการตา ภาษาน่ะเหรอ? ถ้าเน้นที่ภาษามากจนเกินไป ผู้ชมจะสับสน และผู้ฟังจะเข้าสู่ห้วงแห่งความมืดมิด",
  str_voice_1601671_14 = "การหมุนผ่านของเวลาทำให้เราโกรธขึ้งที่ไม่อาจทำอะไรได้ ในขณะที่มีแต่ความจริงเท่านั้นที่จะให้ความหมายทุกประการตามที่เราถวิลหา... ถ้อยความสุดท้ายเช่นนี้จะทำให้ภารกิจของวิกตอเรียครบถ้วนสมบูรณ์อย่างแน่นอน ใช่หรือไม่?",
  str_voice_1601671_15 = "สุขสันต์วันเกิด วันนี้นายอยากชมการแสดงอะไรล่ะ?",
  str_voice_1601671_16 = "วันนี้ฉันจะดำดิ่งเข้าสู่โลกแห่งมายากลอันน่าพิศวงที่เต็มไปด้วยความลึกลับและไร้เหตุผล",
  str_voice_1601671_17 = "กาแฟดำนี่ดีที่สุดจริง ๆ ถ้าฉันถือถ้วยไว้ในมือนิ่ง ๆ ได้นะ",
  str_voice_1601671_18 = "สู่แรงบันดาลใจที่พลิ้วไหวสุดไขว่คว้า... คุณจะยอมจำนน และเลื่อนไหลเข้าสู่จิตใจผมในเวลานี้หรือไม่?",
  str_voice_1601671_19 = "เป็นอีกค่ำคืนหนึ่งที่ได้มายากลช่วยเอาไว้ เราไปนอนกันไหม?",
  str_voice_1601671_20 = "ทั้งชื่อเสียงและไพ่ของฉัน ต่างก็ได้รับมาจากผู้หญิงคนนั้น",
  str_voice_1601671_21 = "นายรู้ไหมว่าที่ไหนในโลกนี้ที่วัฒนธรรมทางด้านอาหารล้ำหน้าที่สุด? ฉันอาจจะไปเยี่ยมเยือนสักหน่อย",
  str_voice_1601671_22 = "ขอความจริงจงสถิตกับท่าน",
  str_voice_1601671_23 = "ฉันเกลียดสิ่งมีชีวิตทางชีวภาพที่ขาดความงดงาม... พวกมันอาจไม่ใช่สิ่งมีชีวิตทางชีวภาพเลยก็ได้",
  str_voice_1601671_24 = "เรนโบว์รับภาระต่าง ๆ ไว้อย่างที่ฉันไม่สามารถรับได้",
  str_voice_1601671_25 = "ครั้งหนึ่งเราเคยไว้ใจซึ่งกันและกันทั้งในยามหัวเราะและร้องไห้ จนกระทั่งหน้าที่รับผิดชอบทำให้เราต้องตกเป็นผู้ถูกจองจำ",
  str_voice_1601671_26 = "ฉันไม่ติดขัดอะไรที่จะแสดงให้เด็ก ๆ ชม เพราะเด็ก ๆ ทำให้ฉันรู้สึกสบายใจ",
  str_voice_1601671_27 = "ถ้าน้ำหนักขึ้น ความยืดหยุ่นในการแสดงของฉันจะลดลง และอุปกรณ์ประกอบการแสดงทั้งหมดก็จะต้องปรับขนาดให้ใหญ่ขึ้น",
  str_voice_1601671_28 = "ยานนี้บินได้ แต่ลอยน้ำไม่ได้",
  str_voice_1601671_29 = "สวัสดีผู้ชมที่รัก ผมชื่อเจโน่ นักมายากลและกัปตันเรือมรกต โปรดคอยติดตามชม เพราะการพบกันครั้งนี้เป็นแค่บทนำของการแสดงที่กำลังจะมาถึง",
  str_voice_1601671_30 = "เป็นกลที่ดีมาก",
  str_voice_1601671_31 = "เปลี่ยนเป็นอะไรใหม่ ๆ",
  str_voice_1601671_32 = "ไพ่แห่งต้นกำเนิดรับพร",
  str_voice_1601671_33 = "นี่คือขีดจำกัดสูงสุดแล้วเหรอ?",
  str_voice_1601671_34 = "ฉันเข้าใจแล้ว",
  str_voice_1601671_35 = "อุปกรณ์พร้อมแล้ว",
  str_voice_1601671_36 = "อยากดูมายากลไหมล่ะ?",
  str_voice_1601671_37 = "ดูให้ดีนะ!",
  str_voice_1601671_38 = "สุดยอดการแสดง!",
  str_voice_1601671_39 = "ขอเสียงให้ฉันหน่อย!",
  str_voice_1601671_40 = "สัมผัสเสียงร้องที่กึกก้อง!",
  str_voice_1601671_41 = "ขอบคุณที่รอคอย",
  str_voice_1601671_42 = "แค่การแสดงแบบมาตรฐาน",
  str_voice_1601671_43 = "ฉันน้ำหนักขึ้นรึเปล่านะ...",
  str_voice_1601671_44 = "โคลอสซัสลำนี้จะถือว่าเป็นปาฏิหาริย์ก็ได้ แต่ก็ยังมีปาฏิหาริย์ที่ใกล้ตัวคุณยิ่งกว่านั้น",
  str_voice_1601671_45 = "รางวัลเหรอ? ขอบคุณนะ",
  str_voice_1601671_46 = "ของขวัญล้ำค่าแบบนี้...",
  str_voice_1601671_47 = "ฉันรู้สึกประหม่าจัง",
  str_voice_1601671_48 = "ฉันจะช่วยอะไรนายได้บ้าง?",
  str_voice_1601671_49 = "ฉันเคยขี่เกลียวคลื่นและดูพระอาทิตย์ขึ้นกับเอลวิส... เขายังคอยลากฉันออกจากบ้านไปพบเพื่อนใหม่ ๆ อีกด้วย เราเคยทำอะไรพวกนี้ด้วยกัน เมื่อนานมาแล้ว",
  str_voice_1601671_50 = "แม่กับพ่อพาฉันมาอยู่บนเรือมรกตเพื่อหนีจากวิกฤตดาร์กโอเวอร์ แต่ตอนนั้นเรือยังไม่ได้เป็นของฉันหรอก",
  str_voice_1601671_51 = "ฉันออกมาจากเรือมรกตเพื่อเดินทางไปทั่วทวีปโดยไม่ได้บอกพ่อแม่ หรือชายผู้ที่สอนมายากลให้ฉัน และสุดท้ายก็ได้พบกับผู้หญิงคนนั้น",
  str_voice_1601671_52 = "Alchemy Stars",
  str_voice_1601671_53 = "คุณผู้ชมที่รัก",
  str_voice_1601671_54 = "ได้เวลาตื่นจากความฝันแล้ว",
  str_voice_1601671_55 = "สวัสดีตอนบ่าย ฉันควรเตรียมตัวขึ้นแสดงได้แล้ว",
  str_voice_1601671_56 = "ทุกอย่างเงียบสงบแล้ว ไปนอนเถอะ",
  str_voice_1601671_57 = "สุขสันต์วันปีใหม่! หวังว่าฉันจะไปถึงศักยภาพสูงสุด และพัฒนาข้ามขีดจำกัดได้นะ",
  str_voice_1501681_1 = "สวัสดีค่ะท่านผู้ชม ขอเสียงหน่อย! อ้าว? ทำไมฉันไม่ได้ยินเสียงอะไรเลยล่ะคะ? มีใครอยากอาบน้ำเย็น ๆ บ้างไหม? อะควอบลาสเตอร์ในมือฉันช่วยได้นะ",
  str_voice_1501681_2 = "ว้า นี่คุณขมวดคิ้วเหรอ? มาเล่นน้ำกับฉันสิถ้ามีเรื่องเศร้าใจ! มาเถอะ จินตนาการดูสิ... ว่านี่คือทะเลกว้าง และเรากำลังดำผุดดำว่ายกันไปขณะลอยตัวอยู่บนเกลียวคลื่น...",
  str_voice_1501681_3 = "ฉันไปฝึกการเปล่งเสียงมาแล้ว! แบบที่ให้เราพูดจาได้ชัดเจนและอ่อนหวานยิ่งขึ้นน่ะ ฮิฮิ ฉันไปฝึกเพราะอยากให้ผู้ชมการแสดงของเราได้ยินคำพูดของฉันอย่างชัดเจน",
  str_voice_1501681_4 = "ฉันห้ามตัวเองไม่ได้เลย! ฉันอยากเอาน้ำมาฉีดให้คนทั้งโลก และมอบความเย็นสดชื่นให้เท่าที่ฉันจะทำได้!",
  str_voice_1501681_5 = "ฮู้วว! ฉันรู้สึกเหมือนตัวเองสร้างเรือไปตั้งมากมายแล้วล่ะ! ไม่ใช่แค่เรือลำใหญ่ยักษ์อย่างเรือมรกตเท่านั้นนะ ยังมีเรือหุ้มเกราะ เรือตกปลา เรือเดินสมุทร... ฮิฮิ ที่พูดนี่คือโมเดลนะ",
  str_voice_1501681_6 = "ฉันชื่อเรนโบว์ หัวหน้าผู้ดูแลเรือมรกต ฉันพร้อมที่จะออกเดินทางอยู่เสมอ! เรื่องดำน้ำ หาปลา ซ่อมบำรุงเรือมรกตประจำวัน ฉันทำได้หมด! ขอแค่สั่งมาเท่านั้น!",
  str_voice_1501681_7 = "ท่านผู้ชมคะ ได้เวลาพักครึ่งแล้ว! ตั้งใจฟังนะ ดีมาก! ฉันเห็นสายตาที่รอคอย กับรอยยิ้มที่ผ่อนคลายของพวกคุณแล้ว!",
  str_voice_1501681_8 = "คุณอยากเข้าฟรีเหรอ? ด-ได้สิ!! ให้ฉันคำนวณค่าจ้างเดือนนี้ก่อนนะ ถ้าฉันฟรีค่าตั๋วให้คุณ... หืมม! ค-คุณไม่ได้ยินอะไรทั้งนั้นนะ!!",
  str_voice_1501681_9 = "ความสัมพันธ์ระหว่างเรามันใช่อย่างที่ฉันคิดรึเปล่า? ค-คุณต้องพูดแบบนี้กับทุกคนแน่เลยใช่ไหม?",
  str_voice_1501681_10 = "ไม่ปรบมือเลยเหรอคะ? แหม เป็นฉันก็เคว้งนะคะ ถ้าพวกคุณไม่ให้ความร่วมมือ",
  str_voice_1501681_11 = "ไม่ต้องทำแค่อุ่นเครื่องกับประกาศชื่อนักแสดงแล้วใช่ไหม? น-ในที่สุดฉันก็ได้รับอนุญาตให้ขึ้นแสดงจริงเต็มรูปแบบแล้วเหรอ!? ว้าว... คุณนี่ดีกับฉันจังเลย!!",
  str_voice_1501681_12 = "ละครสัตว์นี่หายนะมากเวลาฝนตก เราต้องเก็บอุปกรณ์ให้หมด แถมยังต้องดูแลลำโพงขนาดใหญ่ที่เปียกน้ำด้วย... จะว่าไปแล้ว ฉันเองก็ซ่อมของพวกนั้นเก่งเหมือนกันนะ!",
  str_voice_1501681_13 = "ใคร ๆ ก็พูดว่าฉันได้รับความนิยมชมชอบเพื่อให้ฉันมีความสุข! ฉันไม่มีวันถอดใจหรอก ฉันอยากอยู่กับคณะละครสัตว์ต่อไปเพื่อเรียนรู้จากวิศวกรทางทะเลคนนั้น!",
  str_voice_1501681_14 = "ฉันเพิ่งซ่อมถังน้ำเสร็จ เป็นไงบ้างคะ? สวยไหม? ฮิฮิ ฉันก็ว่างั้นนะ! แต่มันยังรั่วไปทั่วเลย...",
  str_voice_1501681_15 = "สุขสันต์วันเกิด!! วันนี้ฉันจะอยู่เป็นเพื่อนคุณเอง ไม่ว่าคุณจะทำอะไร!",
  str_voice_1501681_16 = "สวัสดีค่ะ! วันนี้อยากจับปลากับฉันไหม? ใช้แหเหรอ? ไม่ ๆ! จับปลาด้วยมือเปล่าสนุกกว่ากันเยอะเลย!",
  str_voice_1501681_17 = "อรุณสวัสดิ์ค่ะ! ฉันว่าเมื่อกี้ฉันเห็นเรือเดินสมุทรสวย ๆ อยู่นะ! หืม? อ๋อ นั่นแค่เรือส่งสารลำเล็ก ๆ เหรอคะ?",
  str_voice_1501681_18 = "วันนี้ไม่มีการแสดง จะทำอะไรดีล่ะเนี่ย? วางแผนกิจกรรมช่วงเย็นดีไหม? ไม่จำเป็นหรอก ปล่อยให้เป็นไปตามธรรมชาติแล้วกัน",
  str_voice_1501681_19 = "ทำไมคุณยังไม่นอนล่ะ? กำลังรอให้ฉันบอกให้ไปนอนอยู่ใช่ไหม? ได้เลย ถ้างั้นก็ไปนอนซะนะคะ!",
  str_voice_1501681_20 = "เรือมรกตนี่ยอดเยี่ยมที่สุดเลย! รองลงมาก็คือเรือที่ฉันจะสร้างขึ้นมาในอนาคต! โอ๊ะ ฉันลืมโซรอซไปอีกลำ...",
  str_voice_1501681_21 = "ดูเหมือนชาวอิลลูมินาจะพกพาอุปกรณ์ที่น่าสนใจติดตัวตลอดเลย ฉันอยากไปที่นั่นในสักวัน!",
  str_voice_1501681_22 = "ฉันจะปกป้องคุณเสมอค่ะ!",
  str_voice_1501681_23 = "ฉันต้องปราบศัตรูแบบนี้อีกกี่ตัวเนี่ย?",
  str_voice_1501681_24 = "หัวหน้าคณะละครสัตว์เจโน่อาจเย็นชาและไม่สุงสิงกับใครเป็นพิเศษ แต่ถ้าคุณได้คุยกับเขาอีกนิด... ฮิฮิฮิ",
  str_voice_1501681_25 = "สักวันหนึ่ง ฉันจะเป็นวิศวกรทางทะเลชั้นเลิศได้เหมือนอย่างอาจารย์... ใช่ไหมคะ?",
  str_voice_1501681_26 = "ฉันสนุกกับชีวิตของตัวเองตอนนี้มากเลยล่ะ! ฉันรักผืนน้ำ รักคณะละครสัตว์ และชอบมากที่ตัวเองเป็นคนช่างสงสัยใคร่รู้แบบนี้!",
  str_voice_1501681_27 = "ถ้ามีอะไรที่ฉันไม่ชอบ ก็สภาพอากาศแห้ง ๆ นี่แหละ... และฉันก็ไม่ค่อยชอบคนน่าเบื่อด้วยค่ะ",
  str_voice_1501681_28 = "ซ-โซรอซ ยานลำใหญ่ยักษ์!! เฮ้อ... ทำไมฉันไม่เกิดมาเป็นเคเลสไทต์นะ? จะได้คุยกับโซรอซรู้เรื่อง...",
  str_voice_1501681_29 = "สวัสดี! เป็นไงกันบ้างคะ? ฉันชื่อเรนโบว์ คนเดียวที่ได้รับมอบหมายให้เป็นผู้ดูแลเรือมรกต! สมาชิกใหม่ของคณะละครสัตว์น่ะเหรอ? นั่นเป็นแค่งานเสริมของฉันค่ะ!",
  str_voice_1501681_30 = "สาดกระจาย!",
  str_voice_1501681_31 = "แรงดันน้ำพุ่งสูงขึ้น!",
  str_voice_1501681_32 = "น้ำพุร้อน!",
  str_voice_1501681_33 = "คลื่นลูกใหญ่!",
  str_voice_1501681_34 = "ฉันได้ร่วมขบวนทัพเรือรบแล้ว!",
  str_voice_1501681_35 = "ฉันพร้อมเสมอ!",
  str_voice_1501681_36 = "ให้ฉันยิงได้แล้ว!",
  str_voice_1501681_37 = "เรนโบว์มาแล้ว!",
  str_voice_1501681_38 = "ระเบิด! น้ำสาดกระจาย!",
  str_voice_1501681_39 = "เพิ่มแรงดัน!",
  str_voice_1501681_40 = "ระเบิดแรงดัน!",
  str_voice_1501681_41 = "อาาา! พร้อมค่ะ!",
  str_voice_1501681_42 = "โชคดีที่ชนะ!",
  str_voice_1501681_43 = "ฉันไม่มีวันยอมแพ้หรอก...",
  str_voice_1501681_44 = "โคลอสซัสดูแห้ง ๆ นะ สาดน้ำสักหน่อยดีไหม?",
  str_voice_1501681_45 = "ฉันจะรับไว้นะ!",
  str_voice_1501681_46 = "ฮิฮิ ฉันจะเก็บไว้ในกระเป๋านะ",
  str_voice_1501681_47 = "นี่... คุณแสดงน้ำใจกับฉันเหรอ?",
  str_voice_1501681_48 = "ฉ-ฉันรับของขวัญนี้ไว้ได้ใช่มั้ย?",
  str_voice_1501681_49 = "ฉันแทบจะเติบโตมาในน้ำเลยนะ ฉันเคยตามพ่อแม่ออกทะเลไปจับปลาตอนเด็ก ๆ แล้วก็ถือปืนที่พ่อทำให้ เที่ยววิ่งเล่นไปทั่ว ฮ่าฮ่าฮ่า",
  str_voice_1501681_50 = "ไม้กระดานหมายเลข 1 กับเบ็ดตกปลาหมายเลข 2 คือเพื่อนรักของฉัน ตอนที่อยู่ในทะเลตามลำพังหลังจากสูญเสียพ่อแม่ไป ก็ไม่รู้เหมือนกันว่าจะทำยังไงถ้าไม่มีสองสิ่งนี้",
  str_voice_1501681_51 = "หัวหน้าคณะละครสัตว์คนก่อนหน้านี้ คือผู้ที่ช่วยชีวิตฉันเอาไว้! เฮ้อ ฉันไม่ได้สนใจจะเรียนวิชามายากลเลยนะ ขนาดเขาก็บังคับฉันไม่ได้",
  str_voice_1501681_52 = "Alchemy Stars!!",
  str_voice_1501681_53 = "อ้าว สวัสดีค่ะ คุณผู้ชมตัวน้อย!",
  str_voice_1501681_54 = "อรุณสวัสดิ์! เวลานี้เหมาะจะจับปลาที่สุดเลยนะ!",
  str_voice_1501681_55 = "สวัสดีตอนบ่าย! วันนี้ร้อนมากเลย!",
  str_voice_1501681_56 = "ฉันมีแสดงคืนนี้!",
  str_voice_1501681_57 = "สุขสันต์วันปีใหม่! ฉันจะทำการแสดงต่อไป แล้วก็ตั้งใจทำตามเป้าหมายที่จะเป็นวิศวกรทางทะเลให้ได้ในปีนี้!",
  str_voice_1600384_10 = "นี่นายทำอะไรอยู่? ถ้าเป็นแบบนี้ต่อไป ฉันจะเบื่อแน่นอนเลย PlayerName มองมาทางนี้!",
  str_voice_1600384_11 = "หา? นี่เราเล่นเกมคล้าย ๆ อควาเรียมสมมุติกันอยู่เหรอ? งั้นฉันเป็นปลาในตู้นะ ส่วนนายก็เป็นคนดูที่อยู่อีกฝั่งของกระจกไง... ฮี่ฮี่ ฟังดูน่าสนใจดีนะ!",
  str_voice_1600384_16 = "ได้เวลาตรวจสอบกลยุทธ์ด้านศักยภาพแล้ว หืมม นาย *มาที่นี่* เพื่อเล่นเกมกับฉันใช่ไหม?",
  str_voice_1600384_17 = "บ้าชะมัด ฉันเล่นเกมทั้งคืนจนจะผ่านอยู่แล้วเชียว!!\nแต่ฉันต้องไปที่ห้องปฏิบัติการวิจัยและแจ้งผลการค้นคว้าที่ได้มาเมื่อวานตอนบ่าย...",
  str_voice_1600384_18 = "ฉันลองทำอาหารเมนูที่พูดถึงในเกมแล้วนะ อะแฮ่ม ผลลัพธ์ก็คือ... ฉันควรให้เรื่องพวกนั้นอยู่ในโลกของเกมก็พอแล้ว",
  str_voice_1600384_19 = "นายก็ยังออนไลน์อยู่เหมือนกันเหรอ? ว้าว! เวลานี้เหมาะที่จะเพิ่มแรงค์เลยนะ!",
  str_voice_1600384_35 = "กรอนรูคนใหม่ ไฉไลกว่าเก่า!",
  str_voice_1600384_36 = "ฉันมาแล้ว!",
  str_voice_1600384_37 = "แตะที่ปุ่มนี้เพื่อปล่อยสกิลอัลติเมท!",
  str_voice_1600384_38 = "เลเวล - สูง - สุด!",
  str_voice_1600384_39 = "เสร็จฉันแน่!",
  str_voice_1600384_40 = "แกแพ้แล้ว!",
  str_voice_1600384_44 = "ชอบสกินใหม่ของฉันไหมล่ะ? ฮี่ฮี่ ขอบคุณนะ",
  str_voice_1600384_58 = "ปลานั่นตามนายต้อย ๆ ยังกับลูกสมุนตามตัวเอกในเกมเลย ยังไงนะ? แปลว่าคราวนี้นายเป็นคู่หู ส่วนฉันเป็นตัวเอกงั้นเหรอ?",
  str_voice_1600384_59 = "เข้ามาใกล้ ๆ ได้ไหม? ใกล้อีก ใกล้อีก... ระวัง! ใกล้มากสุดได้แค่นี้แหละ ไม่งั้นเดี๋ยวสลับที่กันแน่ อยากรู้ไหมล่ะว่าในนี้มันเป็นยังไงบ้าง?",
  str_voice_1600384_60 = "ไม่ว่าเกมจะเล่นยากแค่ไหน เล่นไปหลาย ๆ รอบเดี๋ยวก็ผ่าน ถ้าใครยินดีที่จะใช้เวลามากกว่านั้น ก็จะได้รับ \"รางวัลสมบูรณ์แบบ\" ก็ง่ายนะ... นายไม่คิดว่ามันง่ายขนาดนั้นเหรอ? คือ มันก็ยังง่ายกว่าอะไรหลาย ๆ อย่างในโลกแห่งความจริงไม่ใช่หรือไง?",
  str_voice_1600384_61 = "ถึงชุดนี้จะเผยเรือนร่างของฉันมากไปหน่อย ฉันคิดว่าถ้าใส่ไปที่ห้องปฏิบัติการวิจัย คนแรกที่จะหน้าแดงต้องเป็นยูนิเมตแน่นอน",
  str_voice_1600384_62 = "สำหรับฉันแล้ว การทำวิจัยก็ง่ายเหมือนเล่นเกมนี่แหละ เพราะว่าทั้งสองอย่างมีวิธีการที่ชัดเจน ใช่แล้ว คำถามที่มีคำตอบย่อมรับมือได้ง่ายกว่าเสมอ",
  str_voice_1600384_63 = "บางครั้งฉันก็กลับไปเล่นเกมที่เล่นจบไปนานแล้ว... อาจเป็นเพราะฉันยังคิดถึงความพยายามที่เล่นจนจบในตอนนั้น หรืออารมณ์ความรู้สึกที่ลงทุนไปกับมันอยู่น่ะ",
  str_voice_1600384_64 = "อรุณสวัสดิ์...",
  str_voice_1600384_65 = "อรุณสวัสดิ์! นายชอบทะเลไหม?",
  str_voice_1600384_66 = "อรุณสวัสดิ์! วันนี้ฉันจะไปที่สนามทดสอบกับเชอวาน!",
  str_voice_1600384_67 = "อรุณสวัสดิ์! ฉันเริ่มทำงานแล้วนะ",
  str_voice_1600384_68 = "ทิ้งข้อความไว้นะถ้านายต้องการอะไร! ถ้าฉันไม่ตอบ แปลว่าฉันทำงานอยู่",
  str_voice_1600384_69 = "ทายซิว่าฉันจะกินอะไรกลางวันนี้?",
  str_voice_1600384_70 = "อ้าว! สวัสดีตอนบ่าย! ฉันลองเล่นเกมแนวใหม่แล้วนะ!",
  str_voice_1600384_71 = "เที่ยงนี้ฉันต้องพักผ่อนให้เพียงพอ",
  str_voice_1600384_72 = "ฉันควรทำอะไรในช่วงพักตอนบ่ายวันนี้ดี?",
  str_voice_1600384_73 = "ช่วงเวลานี้มาถึงอีกแล้ว!",
  str_voice_1600384_74 = "ฮี่ฮี่ อาหารเย็นเมื่อกี้สุดวิเศษไปเลย!",
  str_voice_1600384_75 = "บ้าเอ๊ย บ้าเอ๊ย บ้าเอ๊ย ช่างมันเหอะ! ฉันแพ้แล้ว!",
  str_voice_1600384_76 = "*ฮึก ๆ* ...เนื้อเรื่องในเกมที่ฉันเพิ่งเล่นจบไปมันซึ้งมากเลย...",
  str_voice_1600384_77 = "ทุกคืนก่อนนอน นายคิดเรื่องอะไรเหรอ?",
  str_voice_1501301_1 = "มีคดีหนึ่งที่โจทก์และครอบครัวถูกพิพากษาให้เนรเทศ ทั้งหมดเป็นเพราะเขาเรอต่อหน้าผู้พิพากษาขณะนำเสนอคดี เขาเสียชีวิตในการเนรเทศซึ่งเปิดการไต่สวนผู้พิพากษา สงสัยว่ามีคนตายเพราะเรอเดียวกี่คน?",
  str_voice_1501301_2 = "จำนวนเซลล์ที่มีอยู่มีอิทธิพลต่อความรุนแรงของคำตัดสินของผู้พิพากษา แม้ว่าจะสร้างปัญหาในการดำเนินการตามกระบวนการยุติธรรม แต่อย่างน้อยฝ่ายหนึ่งฝ่ายใดฝ่ายหนึ่งก็ยอมถอยออกมาอย่างพึงพอใจ",
  str_voice_1501301_3 = "ชาว Caelestites ใช้ความสามารถทางจิตของตนเมื่อตัดสินผู้อื่นหรือไม่? หรือจะใช้เพื่อป้องกันตัวเองระหว่างพิจารณาคดี? แม้ว่าถ้าทุกอย่างเกิดขึ้นในใจ ก็ไม่จำเป็นต้องมีคำพูด",
  str_voice_1501301_4 = "หากพบว่าหิ่งห้อยของคุณเป็นสิ่งมีชีวิต สิ่งนั้นจะไม่ทำให้คุณรู้สึกผิดที่ตกเป็นทาสของพวกมันหรือ คุณจะเป็นการละเมิดกฎหมาย! ขึ้นศาลเดี๋ยวนี้!",
  str_voice_1501301_5 = "ไม่รู้จักกฎหมาย? ไม่เป็นไร ฉันสามารถท่องอะไรก็ได้ที่คุณจำเป็นต้องรู้ แต่จะมีประโยชน์หรือไม่นั้นขึ้นอยู่กับคุณทั้งหมด",
  str_voice_1501301_6 = "นั่นอะไร? คุณคิดว่ากฎหมายบางข้อของเราใช้ไม่ได้จริงหรือ นั่นถือเป็นเรื่องปกติ เมื่อพิจารณาว่าคนในลูโมโปลิสสนใจแค่การเขียนกฎหมายเท่านั้น ไม่ได้บังคับใช้",
  str_voice_1501301_7 = "หากคุณจำเป็นต้องพิจารณาคดีบนเรือยักษ์ใหญ่ ฉันสามารถกรอกได้ทุกบทบาทที่คุณต้องการ ไม่ว่าจะเป็นผู้พิพากษา อัยการ และทนายความ! ฉันสามารถทำให้คุณชนะได้เสมอ โอ้ แต่ฉันจะปล่อยให้การดำเนินคดีกับคุณแน่นอน",
  str_voice_1501301_8 = "คุณสังเกตไหมว่าชื่อเรื่องยิ่งดีก็ยิ่งฟังดูผิด? ตัวอย่างเช่น \"ขุนนางผู้ใจดี\" \"อัศวินผู้ภักดี\"... หรือ \"ลูโมโปลิส หัวใจของอารยธรรม\"",
  str_voice_1501301_9 = "หลังจากที่ได้เห็นความลับอันชั่วร้ายทั้งหมดที่ซ่อนอยู่ในเงามืด บางครั้งฉันก็หวังว่า Lumopolis จะตกลงมาจากหอคอยงาช้างและตกลงสู่โลกเบื้องล่าง",
  str_voice_1501301_10 = "คุณผูกพันกับยักษ์ใหญ่นี้อย่างไร? โดยมรดกหรือโดยสัญญาที่มีผลผูกพันทางกฎหมาย? หิ่งห้อยได้รับการปกป้องเป็นรายบุคคลหรือไม่? อ๊ะ คำถามมากมาย... บางทีฉันควรจะปรับคุณและเรียกมันว่าวัน?",
  str_voice_1501301_11 = "คุณต้องการให้ฉันเป็นประธานในการพิจารณาคดีที่นี่? ไม่มีโอกาส! โอ้... คุณไม่ต้องการอะไรตอนนี้เหรอ? ยอดเยี่ยม! ตอนนี้ฉันสามารถคิดกฎหมายใหม่สำหรับยักษ์ใหญ่ได้...",
  str_voice_1501301_12 = "ถ้าเราต้องการตัดสินใจเกี่ยวกับกฎหมายบนเรือยักษ์ใหญ่ เราต้องทำอะไรให้ถูกต้องเสียก่อน ถือว่าเป็นสิ่งมีชีวิตหรืออาณาเขตหรือไม่? มันสำคัญมากนะรู้ไหม!",
  str_voice_1501301_13 = "กรณีที่ฉันภูมิใจมากที่สุดคือตอนที่ฉันช่วยคู่สามีภรรยาที่ทะเลาะกันให้ช่วยชีวิตแต่งงานของพวกเขาจากการหย่าร้างที่รีบร้อน แต่สำหรับการเสียเวลาของฉัน ฉันยอมให้ทั้งสองฝ่ายจ่ายค่าปรับเป็นจำนวนมหาศาลอยู่ดี",
  str_voice_1501301_14 = "เป็นไปไม่ได้ที่กฎหมายจะกล่าวถึงทุกสถานการณ์ที่เป็นไปได้ นั่นคือเหตุผลที่เราอาศัยแบบอย่างหรือความคิดของเราเองในการตัดสินในบางครั้ง นี่เป็นส่วนหนึ่งของการที่ Lumopolis ก้าวทันเวลา",
  str_voice_1501301_15 = "เนื่องจากอายุของคุณยังไม่ได้รับการจดทะเบียนในบันทึกอย่างเป็นทางการของ Lumopolis คุณสามารถแกล้งทำเป็นว่าเด็กเท่าที่คุณต้องการตลอดชีวิตที่เหลือของคุณ ยังไงก็ขอให้มีความสุขมากๆ ในวันเกิดนะ",
  str_voice_1501301_16 = "ไม่ว่าจะฝนตกหรือแดดออก ก็เป็นวันที่ดีสำหรับการทดลองใช้เสมอ! อันที่จริง ฉันเพิ่งนึกขึ้นได้—ฉันหมายถึง, จำได้—บทความกฎหมายใหม่และต้องการทดสอบดู",
  str_voice_1501301_17 = "ยังเร็วไปเล็กน้อยสำหรับการทดลองใช้ คุณว่าไหม หากคุณมีเอกสารพร้อม คุณก็ออกไปได้ วันนี้ฉันหยุดพัก",
  str_voice_1501301_18 = "การทดลองที่ชอบธรรมและข้อสรุปที่ชอบธรรมนั้นยิ่งใหญ่และทั้งหมด... แต่ไม่มีอะไรที่ชอบธรรมไปกว่ากาแฟดำร้อนๆ สักแก้วในตอนเย็น!",
  str_voice_1501301_19 = "ฉันเอาชนะ ฉันยังเริ่มไตร่ตรองถึงวิธีการสร้างความยุติธรรมและความเสมอภาคด้วยกฎหมาย... ดูเหมือนว่าฉันต้องพักผ่อนบ้าง",
  str_voice_1501301_20 = "ชาวเมืองลูโมโปลิสต้องดิ้นรนและทำงานหนักเพื่อเมืองของตน ในขณะที่พวกขุนนางนั่งบนบัลลังก์ของตน",
  str_voice_1501301_21 = "สถานที่ที่ไม่มีระเบียบที่เหมาะสำหรับสัตว์เท่านั้น แต่อย่างน้อยนิตยสารของพวกเขาก็ไม่ได้แย่ไปกว่าครึ่ง!",
  str_voice_1501301_22 = "ไวท์ไนท์ขึ้นสูง! ลูโมโปลิสจงเจริญ จงเจริญเถิด บรรดาขุนนางทั้งหลาย สิ่งนั้นจะนำพาเราไปสู่ความเจริญรุ่งเรือง! บ.",
  str_voice_1501301_23 = "สิ่งมีชีวิตที่ไม่เข้าใจกฎหมายเป็นสิ่งที่น่าสมเพช ถึงวาระที่จะเป็นจำเลยและไม่เคยถูกดำเนินคดี",
  str_voice_1501301_24 = "หากฉันพบจุดจบ อย่างน้อยฉันก็สามารถไว้วางใจหัวหน้าผู้พิพากษา Irridon ได้ เธอ... แตกต่าง",
  str_voice_1501301_25 = "ฉันมองเห็นตัวเองในอดีตทุกครั้งที่มองคีด... คิดว่าฉันควรร่วมทีมกับพวกเขาไหม? ด้วยฉันเป็นหัวหน้าทีม เราสามารถนำความยุติธรรมมาสู่คนทั้งโลกได้!",
  str_voice_1501301_26 = "เสียงค้อนทุบเป็นเสียงของความยุติธรรม... และฟังดูยอดเยี่ยมเป็นพิเศษเมื่อคุณเอามันมาใส่หัวใครซักคน!",
  str_voice_1501301_27 = "ฉันมีสิ่งเดียวที่จะพูดกับคนที่เข้าใจกฎหมาย แต่พอใจที่จะพูดเกี่ยวกับมันแทนที่จะรักษามันไว้: \"ได้โปรดจบชีวิตของคุณอย่างถูกต้อง\"",
  str_voice_1501301_28 = "Soroz ละเมิดมาตรา 1 ของกฎหมาย Lumopolis Clear Skies ซึ่งฉันเพิ่งเขียนเอง ขออภัย แต่ฉันจะต้องยึดยักษ์ใหญ่ของคุณ",
  str_voice_1501301_29 = "การรักษาความยุติธรรมและกฎหมายมาพร้อมกับราคา และการชดใช้ราคานั้น... การเริ่มต้นกับคนอื่นจะดีที่สุดเสมอ! นั่นเป็นเหตุผลที่ฉันมาที่นี่เพื่อให้แน่ใจว่าคุณไม่ใช่หนึ่งในนั้น!",
  str_voice_1501301_30 = "ถึงเวลากฎหมายใหม่!",
  str_voice_1501301_31 = "การตัดสินของฉันไม่เคยผิด",
  str_voice_1501301_32 = "คำตัดสินที่รวดเร็ว",
  str_voice_1501301_33 = "ฉันเป็นกฎหมาย",
  str_voice_1501301_34 = "ฉันจะเป็นพยานให้กับคุณ",
  str_voice_1501301_35 = "เตรียมตัวให้พร้อมสำหรับการพิจารณาคดี",
  str_voice_1501301_36 = "คัดค้าน!",
  str_voice_1501301_37 = "นั่ง!",
  str_voice_1501301_38 = "เพิ่มขึ้นทั้งหมด!",
  str_voice_1501301_39 = "ศาลอยู่ในเซสชั่น!",
  str_voice_1501301_40 = "คำสั่ง!",
  str_voice_1501301_41 = "ฉันจะเป็นประธานในฐานะผู้พิพากษา",
  str_voice_1501301_42 = "ความยุติธรรมถูกเสิร์ฟ",
  str_voice_1501301_43 = "ศาลสั่งพักงาน",
  str_voice_1501301_44 = "สั่งเลย สั่งเลย! ฉันจะจัดให้มีการทดลองใช้ที่นี่ในไม่ช้านี้!",
  str_voice_1501301_45 = "คุณต้องการติดสินบนฉัน ... ด้วยสิ่งนี้?",
  str_voice_1501301_46 = "อา... ฉันได้รับการคุ้มครอง",
  str_voice_1501301_47 = "สินบนเป็นสิ่งผิดกฎหมาย คราวหน้าอย่าลืม!",
  str_voice_1501301_48 = "คุณได้รับการสนับสนุนจากผู้พิพากษาคนนี้!",
  str_voice_1501301_49 = "ฉันท่องจำหนังสือกฎเกณฑ์ทั้งเล่มเมื่ออายุเพียง 5 ขวบ นั่นเป็นวิธีที่ฉันสามารถเริ่มเรียนได้เร็ว",
  str_voice_1501301_50 = "ย้อนกลับไปในตอนนั้น พวกเขาบอกว่าฉันอาจจะเป็นเด็กอัจฉริยะ หรือทนายความในอนาคตที่น่ากลัวที่สุดที่พวกเขาเคยเห็น",
  str_voice_1501301_51 = "ฉันเคยเป็นคนที่รู้ถูกผิด แต่หลังจากวันนั้น... ฉันเลือกที่จะหลับตาปิดหู เมื่ออยู่ไกลใจก็ห่าง.",
  str_voice_1501301_52 = "Alchemy Stars",
  str_voice_1501301_53 = "เป็นพยาน!",
  str_voice_1501301_54 = "ศาลเปิดเร็ว ๆ นี้ สวัสดีตอนเช้า.",
  str_voice_1501301_55 = "ศาลอยู่ในช่วงพัก สวัสดีตอนบ่าย.",
  str_voice_1501301_56 = "ศาลสั่งพักงาน ราตรีสวัสดิ์.",
  str_voice_1501301_57 = "ปีใหม่ทำให้ฉันมีโอกาสใหม่ในการรับใช้ความยุติธรรมให้กับคุณ",
  str_voice_1601701_1 = "รอยยิ้มของคุณทำให้ฉันนึกถึงเด็กคนหนึ่ง ดังนั้น ถ้าทำได้ ยิ้มให้มากที่สุด เพราะฉันสาบานว่าจะทำทุกอย่างเพื่อปกป้องรอยยิ้มนั้น",
  str_voice_1601701_2 = "แม้แต่สนามรบที่โหดเหี้ยมที่สุดก็ยังเบ่งบานด้วยชีวิตใหม่สักวันหนึ่ง โบสถ์เก่าที่ทรุดโทรมของเราก็ไม่มีข้อยกเว้น",
  str_voice_1601701_3 = "ผู้คนมักจะฝากความหวังไว้ในอนาคต แต่ถ้าไม่มีอนาคตสำหรับเราล่ะ?",
  str_voice_1601701_4 = "สันติภาพผ่านการประนีประนอมไม่สงบเลย สันติสุขที่ได้รับจากการดิ้นรนเท่านั้นที่จะคงอยู่",
  str_voice_1601701_5 = "โดยการอยู่ลึกเข้าไปในเงามืดของสงครามเท่านั้นที่สามารถเข้าใจน้ำหนักและความโหดร้ายของมันได้อย่างแท้จริง",
  str_voice_1601701_6 = "แม้ว่าฉันจะดูถูกคนไร้ยางอายที่ไม่มีศรัทธาหรือมโนธรรม แต่ฉันรู้ลึกๆ ว่าฉันก็ไม่ต่างจากพวกเขา",
  str_voice_1601701_7 = "PlayerNameบางทีการดำรงอยู่ของคุณอาจเป็นสัญญาณแห่งความหวังสำหรับ Aurorian ทั้งหมด",
  str_voice_1601701_8 = "หากสิ่งต่างๆ ผิดพลาด เพียงแค่มีศรัทธาในสิ่งที่โชคชะตารอคุณอยู่ และถ้าสิ่งต่าง ๆ เป็นไปตามแผนที่วางไว้ อย่าลืมเวลาที่คุณเดินผ่านความมืดมิด",
  str_voice_1601701_9 = "หวงแหนช่วงเวลาอันมีค่าของความสงบสุขเหล่านี้ เพลิดเพลินไปกับพวกเขา ลิ้มรสพวกเขา และชื่นชมพวกเขา... ร่วมกับเรา",
  str_voice_1601701_10 = "สำหรับทหารรับจ้าง การผ่อนคลายอาจทำให้เสียชีวิตได้... ต้องการให้ข้ายิงเหนือหัวคุณสักสองสามรอบเพื่อปลุกคุณให้ตื่นไหม?",
  str_voice_1601701_11 = "คุณต้องการให้ฉันทำเช่นนี้? ฮิฮิฮิ... เจ้าดูจะพึ่งพาข้าเหมือนเด็กๆ",
  str_voice_1601701_12 = "อืม? คุณต้องการบอกอะไรฉันไหม ไม่ต้องห่วง ฉันจะพร้อมรับฟังเสมอ",
  str_voice_1601701_13 = "เราอาจสูญเสียครอบครัวไปในอดีต แต่อนาคตยังอีกยาวไกล และเราจะได้รับโอกาสในการสร้างครอบครัวใหม่",
  str_voice_1601701_14 = "ความสัมพันธ์ของคุณกับยักษ์ใหญ่คืออะไร? คุณเป็นครอบครัวหรืออาจจะเป็นเพื่อนสนิท? การเป็นเพื่อนสนิทกับใครสักคนอาจเป็นอันตรายได้...",
  str_voice_1601701_15 = "สุขสันต์วันเกิด, PlayerName. เด็กๆ ขอให้ฉันส่งข้อความจากพวกเขา: \"สุขสันต์วันเกิด และเราหวังว่าเราจะได้เล่นด้วยกันตลอดไป!\"",
  str_voice_1601701_16 = "แน่ใจนะว่าให้ฉันรอ... คุณไม่ต้องการให้คนอื่นประทับใจใช่ไหม?",
  str_voice_1601701_17 = "เพิ่งตื่นเหรอ หรือคุณไม่เคยจากไป?",
  str_voice_1601701_18 = "วันนี้งานดี! คุณต้องการนมอุ่นสักแก้วเพื่อช่วยให้คุณผ่อนคลายหรือไม่?",
  str_voice_1601701_19 = "ไปพักผ่อนเถอะ เรามีเวลาทั้งหมดในโลก",
  str_voice_1601701_20 = "\"การอยู่รอดของผู้ที่เหมาะสมที่สุด\" เป็นวิธีที่โลกทำงานสำหรับผู้ใหญ่ แต่เด็ก ๆ สมควรที่จะมีชีวิตอยู่และเล่นเหมือนเด็กไร้เดียงสาที่พวกเขาเป็น",
  str_voice_1601701_21 = "อัมบราตัน? ฉันคิดว่าฉันคงไม่รังเกียจที่จะซื้อเสื้อผ้าแฟชั่นล่าสุดถ้าฉันมีโอกาส",
  str_voice_1601701_22 = "คิดให้รอบคอบก่อนที่จะกระตุ้นความโกรธของเลือดเรเวน",
  str_voice_1601701_23 = "สิ่งมีชีวิตที่ไร้ศรัทธาเช่นสุริยุปราคาไม่มีที่ใดในโลกนี้",
  str_voice_1601701_24 = "คาสต้าเป็นเด็กดี ขอแค่เธอไม่ต้องแบกรับอะไรมากมาย...",
  str_voice_1601701_25 = "สักวันเราจะได้พบกันอีก แอนทาเรส ฉันรู้ว่าเราจะ",
  str_voice_1601701_26 = "ฉันได้ยินมาว่าคุณมีเสื้อผ้าใหม่จาก Umbraton อยู่กับคุณ! ฉันเดาว่าพวกเขาจะเหมาะกับฉัน ...",
  str_voice_1601701_27 = "เก็บสิ่งเหล่านั้นให้ห่างจากฉัน คุณคงทำตัวให้ห่างเหินได้ดี",
  str_voice_1601701_28 = "มันคงเป็นเรื่องยากที่จะเลี้ยงยักษ์ใหญ่ของคุณให้โตได้ขนาดนี้... เดี๋ยวก่อน คุณหมายความว่ามันเลี้ยงดูคุณ?",
  str_voice_1601701_29 = "คนไม่จำเป็นต้องบูชาแสง คุณสามารถเป็นแสงสว่างของคุณเองได้ ตราบใดที่คุณต่อสู้เพื่อสิ่งที่ถูกต้อง",
  str_voice_1601701_30 = "แบบนี้ก็รู้สึกดี!",
  str_voice_1601701_31 = "ว้าว ฉันรู้สึกว่องไวขึ้นมาก!",
  str_voice_1601701_32 = "ตอนนี้มีบางอย่างที่แตกต่างออกไปใช่ไหม",
  str_voice_1601701_33 = "การต่อสู้เป็นของฉัน!",
  str_voice_1601701_34 = "ทางเลือกที่ดี!",
  str_voice_1601701_35 = "จะรออะไรอยู่ล่ะ?",
  str_voice_1601701_36 = "หมดทางหนีแล้ว!",
  str_voice_1601701_37 = "ฉันไม่เสียกระสุนใส่คุณ",
  str_voice_1601701_38 = "โชคร้ายที่วิ่งเข้ามาหาฉัน",
  str_voice_1601701_39 = "ช็อกและเดือดดาล!",
  str_voice_1601701_40 = "ฉันอยู่ยงคงกระพัน!",
  str_voice_1601701_41 = "ฉันจะนำคุณไปสู่ชัยชนะอีกครั้ง!",
  str_voice_1601701_42 = "เฮ้ ไม่มีอะไรนอกจากการเล่นของเด็ก!",
  str_voice_1601701_43 = "เอ่อ... เดาว่าฉันได้อ่อน",
  str_voice_1601701_44 = "อืม? คุณต้องมีอะไรจะพูดแน่ๆ เพราะคุณจ้องมาที่ฉันแบบนั้น",
  str_voice_1601701_45 = "นี่สำหรับฉันเหรอ? เอ่อ ฉันหมายถึง... ขอบคุณ",
  str_voice_1601701_46 = "น่าสนใจ... ฉันจะไม่ลืมสิ่งนี้",
  str_voice_1601701_47 = "โอ้คุณไม่ควรมี! ขอขอบคุณ.",
  str_voice_1601701_48 = "ฉันแทบรอไม่ไหวที่จะแสดงสิ่งนี้ให้เด็ก ๆ ได้เห็น!",
  str_voice_1601701_49 = "ศีลธรรมและจริยธรรมทั้งหมดได้ตายลงใน Euphoria เป็นเวลานานมากแล้ว แต่อย่างน้อยที่สุด ฉันต้องการให้คริสตจักรแห่งนี้คงไว้ซึ่งความรู้สึกบางอย่างว่าโลกที่ดีควรจะเป็นเช่นไร",
  str_voice_1601701_50 = "ฉันกำลังตัดสินใจเพื่อเด็กๆ อยู่เสมอ เพราะฉันไม่ต้องการให้พวกเขาเดินตามรอยเท้าของฉัน",
  str_voice_1601701_51 = "Antares เพื่อนสนิทของฉัน... มิตรภาพของเธอทำให้ฉันมีความสุขชั่วชีวิต และการตายของเธอด้วยมือของฉันเองทิ้งความโศกเศร้าไปชั่วชีวิต",
  str_voice_1601701_52 = "Alchemy Stars",
  str_voice_1601701_53 = "เราเจอกันอีกแล้วนะ!",
  str_voice_1601701_54 = "วันนี้คุณดูอารมณ์ดี",
  str_voice_1601701_55 = "คุณมีพลังตลอดทั้งวันหรือไม่?",
  str_voice_1601701_56 = "มันเริ่มช้า เด็กที่ตื่นอยู่จะไม่สูงขึ้นเลย",
  str_voice_1601701_57 = "สวัสดีปีใหม่, PlayerName. ฉันหวังว่าเราจะสามารถเฉลิมฉลองวันนี้ด้วยกันหนึ่งปีจากนี้เช่นกัน",
  str_voice_1501711_1 = "พูดตามตรง ฉันรู้สึกสบายใจในการใช้ชีวิตใน Euphoria เพราะไม่ต้องคิดอะไรนอกจากการเอาตัวรอด",
  str_voice_1501711_2 = "อ้อ คุณไม่จำเป็นต้องระวังฉัน ฉันดึงอะไรแบบนั้นกับเนโกะยาชิกิเท่านั้น นอกจากนี้ เป้าหมายของฉันก็ไร้ที่ติ",
  str_voice_1501711_3 = "การต่อสู้คือการรักษาผู้คนและสถานที่ที่คุณรักไม่ให้ถูกพรากไปจากคุณ",
  str_voice_1501711_4 = "ชักปืนช้าเกินไปเท่ากับมอบชีวิตให้ศัตรู เชื่อฉัน ฉันจะไม่มีวันปล่อยให้สิ่งนั้นเกิดขึ้น",
  str_voice_1501711_5 = "งานนี้ได้พัฒนาทักษะของฉันในฐานะทหารรับจ้าง ขอบคุณมากสำหรับสิ่งนั้น ดูเหมือนท่านหญิงลัคจะยังไม่ยอมแพ้ข้า",
  str_voice_1501711_6 = "ไม่ว่าฉันจะใช้ชีวิตแบบไหนในอนาคต ฉันจะไม่มีวันลืมความรู้สึกของการต่อสู้—ความรู้สึกของการมีชีวิต",
  str_voice_1501711_7 = "ฉันมีความมั่นใจเต็มเปี่ยมในโชคของฉัน เพราะฉันได้พบคุณเสมอ",
  str_voice_1501711_8 = "คุณสามารถ... สัมผัสได้ถึงความไว้วางใจของฉันในตัวคุณ? มหัศจรรย์.",
  str_voice_1501711_9 = "ช็อกโกแลตแท่ง... สำหรับฉัน? คุณจำได้ไหมว่าฉันสาบานกับสิ่งนั้นใช่ไหม ยังไงก็ขอบคุณ!",
  str_voice_1501711_10 = "ความสงบแบบนี้สามารถทำให้คนเกียจคร้านได้ และความเกียจคร้านนำไปสู่ความพึงพอใจซึ่งทำให้คนอ่อนแอ วางใจเถอะว่ามันจะไม่เกิดขึ้นกับฉัน",
  str_voice_1501711_11 = "ฉันแค่ต้องให้คุณปลอดภัยใช่ไหม ไม่ต้องกังวล การปกป้องผู้อื่นคือความสามารถพิเศษของฉัน! อืม? ฉันเข้าใจอะไรผิดไปหรือเปล่า",
  str_voice_1501711_12 = "การสูญเสียขาขวาของฉันไม่ได้เลวร้ายไปทั้งหมด รู้ไหม? อย่างน้อยตอนนี้ ทุกย่างก้าวที่ฉันทำก็ถูกคิดออกอย่างสมบูรณ์",
  str_voice_1501711_13 = "พอลลักซ์? ฉันไม่จำเป็นต้องคอยดูแลเธอตลอดเวลา ใจเราสัมพันธ์กัน เราจึงรู้ดีว่าเกิดอะไรขึ้นกับคนอื่นดีกว่าใครๆ",
  str_voice_1501711_14 = "ฉันรู้สึกว่าฉันจะทำอะไรก็ได้เมื่ออยู่กับคุณ นี่คือสิ่งที่รู้สึกเหมือนได้รับความไว้วางใจหรือไม่?",
  str_voice_1501711_15 = "สุขสันต์วันเกิด. ฉันมีบางอย่างให้คุณ เอ่อ ฉันจะไม่ตื่นเต้นกับมันมากเกินไป",
  str_voice_1501711_16 = "กินข้าวหรือยัง ฉันต้องรักษาระดับน้ำตาลในเลือดให้สูงก่อนการต่อสู้ ไม่อย่างนั้นมันอาจจะสร้างปัญหาได้",
  str_voice_1501711_17 = "ฉันเคยชินกับท้องฟ้าที่มีเมฆมาก ในที่สุดฉันจะมีโอกาสได้เห็นดวงอาทิตย์ด้วยหรือไม่?",
  str_voice_1501711_18 = "ฉันไม่รบกวนคุณใช่ไหม ขออภัย ฉันยังคงหักขาเทียมใหม่นี้",
  str_voice_1501711_19 = "ไม่ต้องห่วง ฉันยังอยู่ ฉันจะอยู่ในมุมมองของคุณจนกว่ารุ่งอรุณจะมาถึง",
  str_voice_1501711_20 = "ด้วยคนเพียงสองคน Raven's Blood สามารถแกะสลักสนามหญ้าของตัวเองใน Euphoria ค่อนข้างน่าประทับใจใช่มั้ย",
  str_voice_1501711_21 = "ผู้ชาย Corax จาก Umbraton นั้นดูน่าเชื่อถือมาก ฉันเดาว่าที่นั่นอาจมีบุญบ้าง",
  str_voice_1501711_22 = "คิดให้รอบคอบก่อนที่จะกระตุ้นความโกรธของเลือดเรเวน",
  str_voice_1501711_23 = "เอ๊ะ ของพวกนี้ไม่ต่างจากเป้าหมายที่บูธยิงปืนของสวนสนุกมากนัก",
  str_voice_1501711_24 = "เราหยุดใช้คำพูดเพื่ออธิบายความสัมพันธ์ของเรามานานแล้ว สิ่งเดียวที่ต้องการคือฉันจะยืนเคียงข้างเธอเสมอ",
  str_voice_1501711_25 = "เขาอาจไม่ยอมรับ แต่เห็นได้ชัดว่าเขาทำเพื่อเรามากมาย อย่าบอกนะว่าฉันพูดแบบนั้น!",
  str_voice_1501711_26 = "ถ้าคุณเชื่อใจฉันมากขนาดนี้... ฉันไม่ต้องการเงินจากคุณ",
  str_voice_1501711_27 = "งานยุ่งยาก... ฉันทำเมื่อถูกถาม แต่ไม่ใช่เพราะฉันอยากทำ",
  str_voice_1501711_28 = "ให้โบยบินไปบนฟ้าอย่างอิสระถึงขนาดที่ใหญ่โตอย่างยักษ์นี้... บอกไม่ได้ว่าไม่หึง",
  str_voice_1501711_29 = "ฉันไม่ใช่มืออาชีพ แต่คุณจะไม่ผิดหวังกับทักษะของฉัน อย่างแรกเลย: คุณควรจ่ายให้ฉันสำหรับค่าทักษะของฉัน",
  str_voice_1501711_30 = "อืม รู้สึกดีมาก",
  str_voice_1501711_31 = "บอกคุณทักษะของฉันเป็นเรื่องจริง",
  str_voice_1501711_32 = "มาพูดถึงการขึ้นเงินเดือนกันดีไหม?",
  str_voice_1501711_33 = "ชัยชนะเป็นที่มั่น",
  str_voice_1501711_34 = "คุณ... ต้องการให้ฉันทำงานเป็นทีมหรือไม่?",
  str_voice_1501711_35 = "ตำแหน่งที่ดีที่สุดปลอดภัย",
  str_voice_1501711_36 = "พวกเขารอคำสั่งจากท่านอยู่",
  str_voice_1501711_37 = "ใบนี้ไม่ได้มีไว้สำหรับโชว์เท่านั้น",
  str_voice_1501711_38 = "ฉันเกลียดการย้ายเป้าหมาย",
  str_voice_1501711_39 = "ลูกยิงที่สมบูรณ์แบบ",
  str_voice_1501711_40 = "ทุบพวกมันให้หมด!",
  str_voice_1501711_41 = "มาด้นสดและปรับตัวกันเถอะ",
  str_voice_1501711_42 = "อย่างที่ฉันคาดไว้",
  str_voice_1501711_43 = "เลดี้ลัคไปเที่ยวพักผ่อน...",
  str_voice_1501711_44 = "ดูเหมือนวันนี้ Lady Luck จะจับตาดูฉัน",
  str_voice_1501711_45 = "นี่คือโบนัสของฉันหรือไม่? ขอบคุณ.",
  str_voice_1501711_46 = "เด็ก ๆ จะรักสิ่งนี้ ขอขอบคุณ.",
  str_voice_1501711_47 = "Lady Luck บอกคุณไหมว่านี่คือสิ่งที่ฉันโปรดปราน?",
  str_voice_1501711_48 = "นี่ทำให้ฉันคาดหวังของขวัญชิ้นต่อไปของคุณมาก ไม่กดดันแน่นอน",
  str_voice_1501711_49 = "พอลลักซ์เป็นมากกว่าเพื่อนหรือสมาชิกในครอบครัวมาเป็นเวลานานแล้ว ฉันไม่เคยมีความปรารถนาที่จะเป็นฮีโร่เลย แต่ฉันจะทำทุกอย่างเพื่อปกป้องเธอ... แม้กระทั่งกลายเป็นวายร้าย",
  str_voice_1501711_50 = "ตอนแรกฉันไม่รู้หรอกว่าฉันโชคดีแค่ไหน แต่นั่นอาจไม่ได้เลวร้ายขนาดนั้น เมื่อคุณเริ่มพึ่งพาความโชคดีแบบนี้ คุณจะรู้ได้อย่างรวดเร็วว่าโชคร้ายมาพร้อมกับความเท่าเทียมกันเสมอ",
  str_voice_1501711_51 = "พวกเขาบอกว่ามันง่ายสำหรับคนที่จะเสพติดความขมขื่นของความทุกข์ยาก และฉันก็เหมือนกัน ชีวิตแห่งความขัดแย้งเหมาะกับฉันได้ดี โอ้ แต่สำหรับบุหรี่ ฉันกับพอลลักซ์ สาบานไว้นานแล้ว",
  str_voice_1501711_52 = "Alchemy Stars",
  str_voice_1501711_53 = "เธออยู่ตรงนั้นไหม",
  str_voice_1501711_54 = "อย่าลืมงดอาหารเช้า",
  str_voice_1501711_55 = "กลางวันแดดจ้าเกินไป",
  str_voice_1501711_56 = "อีกวันที่สงบสุข ราตรีสวัสดิ์.",
  str_voice_1501711_57 = "สวัสดีปีใหม่. ดูเหมือนเราจะผ่านพ้นไปอีกปีได้อย่างปลอดภัย",
  str_voice_1601721_1 = "ในฐานะนักแสดง สิ่งสำคัญที่สุดอย่างหนึ่งที่ต้องเรียนรู้คือการจัดการภาพลักษณ์ของคุณ ดังนั้นการข้ามมื้ออาหารสองสามมื้อที่นี่และที่นั่นเมื่อฉันเงินเหลือน้อยก็ไม่เป็นไร! มันเป็นพื้นฐานการอดอาหาร!",
  str_voice_1601721_2 = "ถ้ามีโอกาสก็อยากอยู่ใกล้ทะเล อาหารทะเลที่นั่นราคาถูกมาก ลองนึกถึงปูทั้งหมดที่หาได้ในราคาไม่กี่ Nightium... ยัม!",
  str_voice_1601721_3 = "เราไปเดินเล่นกันไหม ขอแว่นกันแดดกับหมวกหน่อยเถอะ เผื่อว่าเราจะบังเอิญเจอปาปารัซซี่... ฉันไม่อยากเห็นหน้านิตยสารซุบซิบไปเดินเล่นกับชาวเคเลสไทต์",
  str_voice_1601721_4 = "ว้าว เป็นไปตามคาด อีกฉากที่อัศจรรย์ถ่าย! กระดานเรื่องราวโดยรวมก็ยอดเยี่ยมเช่นกัน หนังเรื่องนี้จะทำได้ดีมาก ขอลายเซ็นเทปก่อน!",
  str_voice_1601721_5 = "มาถ่ายรูปกัน! โอ้ คุณดูแข็งไปหน่อย การถ่ายภาพกับคนดังในอนาคตคือโอกาสครั้งหนึ่งในชีวิต มาลองยิ้มกันอีกครั้ง!",
  str_voice_1601721_6 = "คุณต้องลงทุนในธุรกิจนี้ต่อไป คุณไม่สามารถตัดมุมเมื่อพูดถึงใบหน้าของคุณ คนฉลาดรู้ว่าฉันกำลังพูดถึงอะไร!",
  str_voice_1601721_7 = "ฉันไม่อยากจะเชื่อเลยว่าฉันต้องใช้เวลานานขนาดนี้กว่าจะได้รู้ว่าตัวเองสามารถเป็นผู้กำกับที่ยอดเยี่ยมได้ ฉันแทบรอไม่ไหวที่จะกำกับภาพยนตร์ที่นำแสดงโดยตัวเอง!",
  str_voice_1601721_8 = "ไปดูหนังด้วยกันไหม ฉันกำลังคิดสยองขวัญ ไม่ต้องห่วง ฉันดูมาหมดแล้ว ฉันจะบอกคุณล่วงหน้าหากมีเรื่องน่ากลัวเกิดขึ้น",
  str_voice_1601721_9 = "ฉันเพิ่งนึกได้บางอย่าง... คุณเป็นคนหล่อจริงๆ อยากทำหนังด้วยกันไหม? ด้วยรูปลักษณ์และความสามารถโดยธรรมชาติของฉัน เราสามารถสร้างผลงานได้อย่างแท้จริง!",
  str_voice_1601721_10 = "คุณดูยุ่งมาก ฉันจะซ้อมบทในขณะที่คอยเป็นเพื่อน เดี๋ยวก่อน... ต้องมีข้อผิดพลาด ฉันเป็นนักแสดงที่มีเครดิตดี แล้วทำไมฉันถึงมีแค่บรรทัดเดียวล่ะ?",
  str_voice_1601721_11 = "เป็นสถานที่ที่ดี ฉันจะจำมันไว้ เราสามารถถ่ายทำที่นี่ในวันหนึ่ง",
  str_voice_1601721_12 = "ไปช้อปปิ้งด้วยกันไหม? ปล่อยให้การเจรจาต่อรองกับฉัน ฉันใช้เวลาประมาณ 200 Nightium สำหรับ Cellulo เท่านั้น รู้ไหม?",
  str_voice_1601721_13 = "คุณรู้ไหมว่าอะไรอร่อยและทำให้คุณอิ่มแบบไม่เหมือนใคร? ป๊อปคอร์น. ฉันแทบขาดใจเมื่อมาที่อัมบราตัน ฉันมักจะกินป๊อบคอร์นที่เหลือของคนอื่นที่โรงหนังเพื่อกันไม่ให้หิว",
  str_voice_1601721_14 = "ไม่มีอะไรผิดปกติกับการเล่นพิเศษ! แม้ว่าคุณจะมีฉากเดียวหรือหนึ่งบรรทัด แต่ก็ยังเป็นการแสดงเหมือนเดิม ฉันจริงจังกับทุกบทบาทเสมอ",
  str_voice_1601721_15 = "ฉันใช้เวลาค่อนข้างมากในการถ่ายทำโปรเจ็กต์พิเศษนี้สำหรับวันเกิดของคุณ! ปิดไฟแล้วมาดูพร้อมกัน!",
  str_voice_1601721_16 = "*หาว* นั่นคุณเหรอ? ดื่มกาแฟสักแก้วไหม? เมื่อคืนฉันตื่นนอนอีกครั้งเพื่อซ้อมบทของฉัน",
  str_voice_1601721_17 = "คุณตื่นเช้า ฉันหวังว่าคุณคงไม่ว่าอะไรหรอกถ้าฉันได้นอนอีกสักสองสามชั่วโมงเพื่อความงาม...",
  str_voice_1601721_18 = "ฉันกำลังออกไปตอนนี้ ชั่วโมงนี้มีปาปารัสซี่ไม่เยอะ",
  str_voice_1601721_19 = "ว้าว นอนดึกด้วยเหรอ ยอดเยี่ยม! ซ้อมบทของฉันกับฉัน!",
  str_voice_1601721_20 = "Alleywood ของ Umbraton เป็นที่ซึ่งนักแสดงและผู้กำกับกลุ่มหนึ่งได้เริ่มต้นอาชีพการงานของพวกเขา!",
  str_voice_1601721_21 = "คุณรู้ไหม มีบางอย่างที่น่าดึงดูดใจเกี่ยวกับทะเลทรายเรดีเซล ฉันชอบถ่ายสารคดีกับคนที่นั่นสักวันหนึ่ง!",
  str_voice_1601721_22 = "ฉันกำลังมองคุณผ่านเลนส์กล้อง",
  str_voice_1601721_23 = "บางคนควรจะคิดออกว่าจะนำ Eclipsites มาใส่ในภาพยนตร์ได้อย่างไร ด้วยรูปแบบทั้งหมดที่พวกเขาทำ",
  str_voice_1601721_24 = "คุณ Kleken มักใช้คนรู้จักเพื่อจัดคอนเสิร์ตเล็กๆ ให้ฉัน พวกเขาไม่จ่ายมาก แต่ฉันก็รู้สึกขอบคุณเหมือนกัน",
  str_voice_1601721_25 = "เดย์น่าเป็นคนแรกที่จำฉันได้ในฐานะคนพิเศษที่ถูกระเบิดในภาพยนตร์เรื่อง \"The Battle of Umbraton\"!",
  str_voice_1601721_26 = "โลกดูแตกต่างออกไปมากผ่านเลนส์กล้อง",
  str_voice_1601721_27 = "ปาปารัสซี่น่ารำคาญจริงๆ! แฟนคนก่อนถูกลือว่าขว้างไข่ใส่ฉันมากกว่าสิบฟอง!",
  str_voice_1601721_28 = "ว้าว! ค-ฉันสามารถอยู่ในที่ที่...งดงามได้จริงหรือ?",
  str_voice_1601721_29 = "ฉันชื่อลิลิกา ผู้กำกับ-นักแสดงยอดเยี่ยมแห่ง Umbraton! ผลงานชิ้นโบแดงของฉันยังอยู่ระหว่างดำเนินการ แต่ฉันให้ลายเซ็นคุณก่อน",
  str_voice_1601721_30 = "ฉันรู้สึกเป็นแรงบันดาลใจจริงๆ!",
  str_voice_1601721_31 = "เป็นความคิดที่ดีที่จะลงทุนในตัวฉัน",
  str_voice_1601721_32 = "เพียงแค่คุณรอ! ฉันถูกกำหนดให้เป็นดารา",
  str_voice_1601721_33 = "ความสง่างามเป็นสิ่งจำเป็นสำหรับนักแสดง!",
  str_voice_1601721_34 = "ว้าว. แดดแรงมาก!",
  str_voice_1601721_35 = "กล้องพร้อม!",
  str_voice_1601721_36 = "โพสท่าเสร็จยัง?",
  str_voice_1601721_37 = "อุ๊ย! เปิดรับแสงน้อยเกินไป methinks!",
  str_voice_1601721_38 = "การกระทำ!",
  str_voice_1601721_39 = "ไปซะ เซลลูโล!",
  str_voice_1601721_40 = "ตัด! ถ่ายใหม่ครั้งนี้!",
  str_voice_1601721_41 = "ถึงเวลาของฉันที่จะส่องแสง!",
  str_voice_1601721_42 = "วันนี้ไม่มีมันฝรั่งต้ม มาฉลองกันเถอะ!",
  str_voice_1601721_43 = "ไม่ต้องกังวล. อย่างน้อยเราก็ไม่ได้อกหัก",
  str_voice_1601721_44 = "ฉันกำลังประเมินยักษ์ใหญ่ผ่านเลนส์กล้องของฉัน มีสถานที่ถ่ายทำดีๆมากมาย!",
  str_voice_1601721_45 = "ฉันแค่ไม่รู้จะพูดอะไร มีลายเซ็นที่นี่!",
  str_voice_1601721_46 = "คุณรู้ได้อย่างไรว่าฉันกำลังเก็บเงินไว้เพื่อสิ่งนี้!",
  str_voice_1601721_47 = "คุณรู้วิธีเอาใจผู้หญิงอย่างแน่นอน!",
  str_voice_1601721_48 = "ฉันจะไม่ลืมคุณเมื่อฉันรวยในอนาคต",
  str_voice_1601721_49 = "อาหารทะเลมีราคาแพงมากเมื่อโตขึ้น พ่อแม่ของฉันสามารถจ่ายได้เฉพาะในวันเกิดของฉันเท่านั้น เมื่อฉันได้รับค่าตอบแทนสำหรับบทบาทนี้แล้ว ฉันจะพาพวกเขาไปเลี้ยงอาหารทะเลขนาดใหญ่ที่อัมบราตัน!",
  str_voice_1601721_50 = "นี่คือกล้องที่พ่อแม่ให้ไว้ตอนฉันยังเด็ก ฉันรู้ว่ามันเก่า แต่มีบางอย่างที่ยอดเยี่ยมเกี่ยวกับพื้นผิววินเทจที่จับได้ ฉันชอบใช้มันในการถ่ายภาพสิ่งของในชีวิตประจำวัน สงสารม้วนฟิล์มมีราคาแพง",
  str_voice_1601721_51 = "ฉันเป็นคนพิเศษ ถูกกินข้างถนน เป็นลมแดดจากการแต่งตัวในชุดหนาๆ ฉันเคยถูกพัดขึ้นไปบนท้องฟ้ามาก่อน แต่การทำหนังทำให้ฉันมีความสุข ฉันไม่เคยคิดว่ามันเป็นงานหนัก",
  str_voice_1601721_52 = "Alchemy Stars",
  str_voice_1601721_53 = "มีอะไรเหรอ",
  str_voice_1601721_54 = "หาว—ฉันยังง่วงอยู่",
  str_voice_1601721_55 = "ตื่นมาหิวเลย ฉันควรกินอะไร",
  str_voice_1601721_56 = "วันใหม่เพิ่งเริ่มต้น!",
  str_voice_1601721_57 = "เรามาชวนทุกคนมาทำวิดีโอปีใหม่กันดีไหม?",
  str_voice_1601731_1 = "ฉันแค่สงสัยว่าคุณชอบอะไรในแง่ของดอกไม้? ฉันได้รับคำแนะนำจากพ่อค้าจากเกาะคลาวด์ และถ้าคุณไม่ว่าอะไร ฉันต้องการตกแต่งโต๊ะอาหารใหม่ด้วยดอกไม้ที่ถอนออกมาใหม่",
  str_voice_1601731_2 = "แม้ว่าฉันจะยกย่องคุณอย่างมาก แต่ก็ไม่สามารถพูดเช่นเดียวกันกับเจ้านายที่เข้มงวดของฉันได้ เขาจะบอกว่าคุณยังมีอะไรอีกมากที่ต้องเรียนรู้ แต่ไม่ต้องกังวล—ฉันจะช่วย",
  str_voice_1601731_3 = "ฉันไม่ใช่ผู้อ่านใจ ฉันแค่คาดการณ์ว่าเจ้านายของฉันและแขกของพวกเขาจะต้องการอะไร แล้วเตรียมการอย่างพิถีพิถันสำหรับพวกเขา นี่เป็นข้อกำหนดพื้นฐานของพ่อบ้านที่รับใช้ครอบครัว Andersen",
  str_voice_1601731_4 = "ตอนนี้มันเงียบลงมากจนฉันกำจัด Eclipsites ที่อยู่ใกล้เคียงออกไปได้แล้ว คุณรู้สึกอย่างไรที่ได้พาฉันเดินเล่นสบาย ๆ ?",
  str_voice_1601731_5 = "ตารางเวลาที่เข้มงวดเป็นสิ่งสำคัญอย่างยิ่ง เวลาที่เสียไปไม่สามารถย้อนคืนมาได้ ดังนั้นการปรับเทียบนาฬิกาพกจึงเป็นสิ่งแรกที่ฉันทำในตอนเช้า",
  str_voice_1601731_6 = "การควบคุมสถานการณ์ ไม่ว่าจะในสนามรบหรือในธุรกิจ ส่วนใหญ่ขึ้นอยู่กับประสบการณ์ คุณมีความสามารถที่แท้จริง ฉันยินดีที่จะแบ่งปันสิ่งที่ฉันได้เรียนรู้",
  str_voice_1601731_7 = "แค่ครู่เดียว เสื้อผ้าของคุณฉีกขาด... อาจดูเหมือนไม่มาก แต่เราดูแลสิ่งที่ยิ่งใหญ่ได้ก็ต่อเมื่อเราดูแลสิ่งเล็กๆ น้อยๆ ก่อนเท่านั้น เดี๋ยวจะเย็บให้ค่ะ",
  str_voice_1601731_8 = "ฉันตัดสินใจทำอาหารเพราะฉันมีเวลาว่าง มันเหมาะกับเพดานปากของคุณหรือไม่? โอ้ มีจุดเนยอยู่ที่มุมปากของคุณ ให้ฉันเช็ดมันออก",
  str_voice_1601731_9 = "สุภาพบุรุษต้องรู้วิธีการเต้น และฉันคาดหวังมากจากเพื่อนของนีน่า ดี? คุณกำลังรออะไรอยู่? ที่นี่. มือบนเอวของฉัน เอาล่ะ.",
  str_voice_1601731_10 = "ที่นี่อากาศหนาว และฉันไม่อยากให้คุณเป็นหวัด ถ้าคุณไม่ว่าอะไร ฉันจะพาคุณกลับห้อง ฉันได้เตรียมเตียงของคุณพร้อมผ้าปูที่นอนใหม่และวางน้ำหอมปรับอากาศแล้ว",
  str_voice_1601731_11 = "ขอบคุณสำหรับการเชื้อเชิญที่ดีของคุณ แต่ฉันเพิ่งสังเกตเห็นฝุ่นเมื่อเช็ดราวจับด้วยผ้าเช็ดหน้าของฉัน ให้ฉันทำความสะอาดสถานที่ก่อน",
  str_voice_1601731_12 = "คุณค่อนข้างจะบาดเจ็บได้ง่าย โปรด. นั่งลงในขณะที่ฉันทำความสะอาดบาดแผลของคุณ",
  str_voice_1601731_13 = "ฮะ? ฉันขอโทษ ฉันไม่ค่อยเข้าใจ โปรดอย่าตีความสภาพความเหน็ดเหนื่อยในปัจจุบันของฉันผิดไป ฉันแค่ใช้เวลาว่างที่หายากนี้เพื่อพักผ่อนสักหน่อย ฉันขอโทษที่ทำให้คุณกังวล",
  str_voice_1601731_14 = "ในฐานะพ่อบ้านของครอบครัว Andersen ฉันถือว่ามันเป็นภารกิจในชีวิตของฉันที่จะพัฒนาตัวเองให้ดียิ่งขึ้นต่อไปในทิศทางของความสมบูรณ์แบบ และฉันก็อยู่ไกลจากมัน",
  str_voice_1601731_15 = "สุขสันต์วันเกิด! ฉันได้เตรียมงานเลี้ยงตอนเย็นเพื่อเป็นเกียรติแก่วันเกิดของคุณ ซึ่งได้รับเชิญให้เพื่อนสนิทของคุณทุกคน ถ้าคุณไม่รังเกียจ มาแต่งตัวให้เหมาะสมกันดีกว่า",
  str_voice_1601731_16 = "ฉันเข้าใจว่าคุณยุ่ง แต่ฉันต้องเตือนคุณถึงความส าคัญของเวลาอาหารปกติ ดูแลตัวเองนะ.",
  str_voice_1601731_17 = "คุณต้องการลองบลูเบอร์รี่และราสเบอร์รี่ชีสเค้กหรือซูเฟล่วานิลลาสำหรับดื่มชาตอนเช้าไหม",
  str_voice_1601731_18 = "ฉันขอแนะนำให้อาบน้ำเพราะคุณค่อนข้างเหนื่อย? ฉันได้รับอิสระในการใช้น้ำร้อนแล้ว",
  str_voice_1601731_19 = "ความสำคัญของการพักผ่อนที่เหมาะสมไม่สามารถพูดเกินจริงได้ คุณอาจพบว่าตัวเองมีประสิทธิผลเพิ่มขึ้นเป็นสองเท่าในเวลากลางวัน ถ้าคุณดูแลความต้องการของคุณตอนนี้",
  str_voice_1601731_20 = "สิ่งที่ฉันได้ทำเพื่ออาจารย์ผู้มีเกียรติของฉันไม่ได้ใกล้เคียงกับการชำระหนี้ของความกตัญญูที่ฉันเป็นหนี้",
  str_voice_1601731_21 = "ไม่มีอันตรายใดๆ เกิดขึ้นกับอาจารย์หรือนางสาวนีน่าบนนาฬิกาของข้าพเจ้า ไม่ว่าในอัมบราตัน ลูโมโพลิส หรือที่ใดก็ตาม",
  str_voice_1601731_22 = "ทุกคนที่กล้าวางแผนต่อต้านพวกแอนเดอร์เซ็นจะต้องพินาศต่อหน้าต่อตาฉัน",
  str_voice_1601731_23 = "ฉันไม่สามารถทนต่อการมีอยู่ของสิ่งมีชีวิตที่สกปรกเช่น Eclipsites ในโลกนี้",
  str_voice_1601731_24 = "จิตใจของนางสาวนีน่าบริสุทธิ์และใจดี ฉันจะรักษาชีวิตของเธอไว้กับตัวฉัน",
  str_voice_1601731_25 = "แม้ว่าบางครั้งการขาดการประสานงานของเสน่ห์อาจเป็นเรื่องน่าเป็นห่วง แต่น.ส.นีน่าก็ชอบเธอมาก",
  str_voice_1601731_26 = "มีอะไรที่ทำให้ดีอกดีใจมากกว่าความรู้สึกของทุกสิ่งที่เรียบร้อย เป็นระเบียบเรียบร้อย และอยู่ในลำดับที่เหมาะสมหรือไม่?",
  str_voice_1601731_27 = "บางคนสามารถทนต่อความยุ่งเหยิงเช่นนี้ในห้องของพวกเขาได้อย่างไร? ฉันแค่ไม่เข้าใจ",
  str_voice_1601731_28 = "Colossus ได้รับการจัดวางอย่างโอ่อ่าอย่างแท้จริง เว้นแต่จะมีผู้คนมาเรื่อยๆ จำเป็นต้องทำความสะอาดอย่างสม่ำเสมอ",
  str_voice_1601731_29 = "เป็นเกียรติที่ได้พบคุณ ฉันชื่อ Minos และถึงแม้ว่าฉันจะยังคงเป็นพ่อบ้านพิเศษของครอบครัว Andersen แต่โปรดมั่นใจว่าฉันจะพยายามอย่างเต็มที่เพื่อช่วยคุณ",
  str_voice_1601731_30 = "ฝึกฝนฝึกฝนความสามารถ",
  str_voice_1601731_31 = "ฉันยังต้องไปอีกไกล",
  str_voice_1601731_32 = "ฉันต้องบอกว่าความรู้สึกแปลกใหม่",
  str_voice_1601731_33 = "ฉันจะทำให้ดีที่สุดเพื่อตอบแทนความไว้วางใจของคุณ",
  str_voice_1601731_34 = "เข้าใจแล้ว",
  str_voice_1601731_35 = "ฉันรอคำสั่งของคุณ",
  str_voice_1601731_36 = "ให้ข้าไปส่งไหม?",
  str_voice_1601731_37 = "เรามาจบเรื่องนี้กันโดยเร็ว",
  str_voice_1601731_38 = "อย่ากลัวเลย ฉันจะกล่อมคุณให้นอนหลับโดยใช้วิธีการที่อ่อนโยนที่สุด",
  str_voice_1601731_39 = "เวลาที่จะหายไป",
  str_voice_1601731_40 = "สกปรก",
  str_voice_1601731_41 = "วางใจทิ้งงานให้ฉัน",
  str_voice_1601731_42 = "ดีที่ฉันไม่ได้เปื้อนเสื้อผ้า",
  str_voice_1601731_43 = "ฉันเสียใจ. ฉันคำนวณผิดอย่างมาก",
  str_voice_1601731_44 = "ฉันทำความสะอาดแก้วน้ำที่บาร์อย่างละเอียดแล้ว คุณจึงไม่ต้องกังวลกับการใช้งาน",
  str_voice_1601731_45 = "นี่เป็นเรื่องที่คุณคิดมาก",
  str_voice_1601731_46 = "ฉันไม่อยากจะเชื่อเลย... ฉันจะเก็บมันไว้อย่างดี",
  str_voice_1601731_47 = "คุณเป็นคนใจกว้างต่อความผิด",
  str_voice_1601731_48 = "คุณค้นพบการตั้งค่าของฉันอย่างรวดเร็ว",
  str_voice_1601731_49 = "เขาบนหัวของฉันไม่ได้หักไปเอง แต่เป็นผลจากการที่พี่เลี้ยงของฉัน... ไม่เป็นไร มันเป็นอดีตไปแล้ว ปล่อยให้อดีตยังคงผ่านไป คุณอยากจะเติมความสดชื่นให้ตัวเองด้วยชามินต์และมะนาวไหม?",
  str_voice_1601731_50 = "เราต้องดูแลรูปร่างหน้าตาให้ดีอยู่เสมอ ฉันจำได้ว่าครั้งหนึ่งฉันล้มเหลวในการขจัดคราบเลือดออกจากตัวเองโดยสิ้นเชิงและทำให้นางสาวนีน่าตกใจจนเธอปฏิเสธที่จะเข้าใกล้ฉันเป็นเวลานานมาก มันทำลายหัวใจของฉันจริงๆ",
  str_voice_1601731_51 = "การเป็นพ่อบ้านไม่ได้มีอะไรมากไปกว่าการรีดผ้า ทำความสะอาด ทำอาหาร ให้ความบันเทิงแก่แขก กำจัดสุริยุปราคาที่อยู่ใกล้เคียง เช่นเดียวกับการข่มขู่ผู้ล่วงประเวณีเป็นครั้งคราว",
  str_voice_1601731_52 = "Alchemy Stars",
  str_voice_1601731_53 = "เป็นอะไรไปล่ะ",
  str_voice_1601731_54 = "ชายามเช้าพร้อมแล้ว",
  str_voice_1601731_55 = "คุณต้องการอะไรเป็นอาหารกลางวัน?",
  str_voice_1601731_56 = "ถึงเวลาพักผ่อนแล้ว",
  str_voice_1601731_57 = "สวัสดีปีใหม่! ฉันต้องไปเตรียมงานเลี้ยงปีใหม่แล้ว",
  str_voice_1401691_1 = "ยินดีต้อนรับครับท่าน! นายยินดีต้อนรับ!\nไม่ไม่ไม่. “ยินดีต้อนรับครับนาย!” เสียงดีขึ้นนิดหน่อย...\nเอ่อ ฉันยังหาประโยคเกี่ยวกับการยอมรับภารกิจอยู่",
  str_voice_1401691_2 = "เฮ้-o! ดวงตาของฉันเพียงคนเดียวก็ทะลุม่านแห่งราตรี ไม่มีใครสามารถไปถึงส่วนสูงของฉันได้ ฉันไม่สามารถทำอะไรที่คนอื่นทำได้! ... ไม่นะ ฉันร้องเพลงผิด",
  str_voice_1401691_3 = "Swashbuckling เป็นงานที่เจ๋งที่สุด เป็นเจ้าเมือง? เผด็จการเกินไป เป็นชาโดว์ลอร์ด? น่ากลัวเกินไป เป็นราชินี? แฟนตาซีเกินไป เป็นเจ้าหญิง? น่าเบื่อเกินไป ฉันรู้จักพวกเขาไหม แน่นอนว่าไม่! แต่ฉันสามารถบอกคุณได้ว่า swashbucklers ดีที่สุด",
  str_voice_1401691_4 = "ฉันใกล้จะบรรลุอาชีพในฝันในฐานะนักต้มตุ๋นแล้วหรือยัง? ใช่! คุณช่วยฉันไปไกลกว่านั้นมากตามถนนสายนั้น",
  str_voice_1401691_5 = "คุณอยากรู้วิธีไปถึงกิลด์ไหม? วิธีที่เร็วที่สุดคือเหมือนกาบิน เดินตรงไปข้างหน้า เห็นกำแพงนั่นไหม? ข้ามมันไป โอ้คุณต้องการไปรอบ ๆ หรือไม่? ฉันเสียใจ. แค่ซ้อนลังสองสามลังถ้าคุณเตี้ยไปหน่อย",
  str_voice_1401691_6 = "เจ้าชู้ผู้ห้าวหาญหายตัวไปในยามค่ำคืน โดยไม่ทิ้งร่องรอยใด ๆ เลยในถนนที่มีแสงจันทร์ส่องถึงในเมืองโบราณ... สิ่งที่เหลืออยู่เป็นเพียงเสียงสะอื้นขอบคุณของชาวเมืองที่ยากจนซึ่งเพิ่งรอดชีวิตมาได้ อืม วันหนึ่งฉันจะทำสำเร็จด้วยได้ไหม โอ้? เราเคยทำกันแล้ว?",
  str_voice_1401691_7 = "มีอะไรผิดปกติกับปลายผมของฉันหรือไม่? สีมันซีดลงไม่ใช่เหรอ? ไม่นะ. เพิ่งรู้ว่ายาย้อมผมมันไม่ดี! เดี๋ยว ปลายผมดำเหมือนเดิม แล้วคุณมองมาที่ฉันทำไม?",
  str_voice_1401691_8 = "มีสาวแก่ที่เท่และเท่มากมายเหลือเกิน ฉันมีอะไรมากมายให้เรียนรู้จากพวกเขา และคุณเองก็เท่มาก Caelestite ที่กล้าเผชิญอันตรายของโลก",
  str_voice_1401691_9 = "คุณต้องการให้ฉันช่วยสร้างกล้ามเนื้อ ให้ยืมการ์ตูนเรื่องตลกของฉัน หรือปรับปรุงความรู้สึกแฟชั่นของคุณ...? ไม่มีเลย? ไม่เป็นอะไร. ฉันยังคงพยายามอย่างเต็มที่เพื่อปกป้องคุณ แม้ว่าจะต้องเสียค่าธรรมเนียมก็ตาม",
  str_voice_1401691_10 = "ฉันยุ่งมาก คุณรู้ไหม เช้านี้ฉันโดดเรียนเพื่ออ่านหนังสือการ์ตูน และจากนั้นอีกครั้งในตอนบ่ายเพื่อตรวจดูภารกิจใหม่ คืนนี้ฉันกำลังฝึกหลักสูตรพิเศษกับเพื่อนสาวที่อายุมากกว่าของฉัน ฉันรู้สึกทึ่งกับความจริงที่ว่าตอนนี้ฉันยังยืนอยู่ตรงนี้อย่างอดทนได้",
  str_voice_1401691_11 = "ยามยืนเป็นงานง่ายสำหรับฉัน อย่าบอกนะว่าอยากให้ฉันยืนดูเธออยู่ตรงนี้? ดีแล้ว ให้ฉันดูว่าคุณมีความคล้ายคลึงอะไรกับ swashbucklers...",
  str_voice_1401691_12 = "เมื่อฉันลดปีกหมวกลง แสดงว่าฉันกำลังจะทำ! ระวังสภาพแวดล้อมของคุณเพราะฉันอาจปรากฏขึ้นข้างๆคุณได้ทุกเมื่อ",
  str_voice_1401691_13 = "ฉันสามารถหางานทำที่ท่าเรือได้เมื่อเริ่มงานเท่านั้น พวกเขาไม่เคยเกลียดชังพลังอันเหลือเชื่อของฉัน! แต่ฉันเคยชินกับการหยิบจานที่เปราะบางและถ้วยกาแฟ",
  str_voice_1401691_14 = "ไม่มีใครต้องการมอบหมายอะไรให้ฉันเหรอ? หึ! คุณได้ยินเรื่องไร้สาระมาจากไหน? ฉันแน่ใจว่ามันเป็นแค่ความเข้าใจผิดเท่านั้น! ฉันยอมรับภารกิจมากมาย รู้ไหม \"ทำลายผลิตภัณฑ์ที่หมดอายุ\" \"ส่งลังเบียร์ 30 กล่องให้พวกสเปียโรว์ในคราวเดียว\" อะไรทำนองนั้น!",
  str_voice_1401691_15 = "สุขสันต์วันเกิด! Super Sadie Swashbuckler 666 นำเสนอความโชคดีและโชคลาภในแบบของคุณ",
  str_voice_1401691_16 = "หึ! ไม่มีคำทักทายอีกต่อไป มาที่นี่และเก็บเสียงของคุณไว้ ฉันไม่ต้องการให้ใครรู้ว่าเรากำลังโดดเรียน",
  str_voice_1401691_17 = "สวัสดีตอนเช้า! ขอให้ทุกคนเป็นผู้ใหญ่และตื่นแต่เช้าตรู่และนอนดึก",
  str_voice_1401691_18 = "อย่าลืมกินให้ดี หมอบอกว่าผักสร้างกล้ามเนื้อ สวรรค์ช่วยฉันด้วย ฉันทนผักไม่ไหว",
  str_voice_1401691_19 = "นักต้มตุ๋นมีเรื่องที่จะพูดเกี่ยวกับความสมดุลระหว่างชีวิตและการทำงานของคุณ: นอนหลับให้มากขึ้น! โอ้ฉันล้อเล่นใคร ฉันทำมันขึ้น",
  str_voice_1401691_20 = "สถานที่ที่ยอดเยี่ยมสำหรับนักต้มตุ๋นอย่างฉัน",
  str_voice_1401691_21 = "ลูโมโปลิส? ไม่เป็นไรฉันเดา พวกเขาไม่ปล่อยการ์ตูนเรื่องใหม่ออกมาเกือบเพียงพอที่นั่น",
  str_voice_1401691_22 = "เงาของคนเจ้าชู้กำลังเฝ้าดูคุณอยู่!",
  str_voice_1401691_23 = "ถ้ามีหนังสือการ์ตูนมากเท่ากับ Eclipsites ยกเว้น เอ่อ หนังสือการ์ตูนก็ดี และ Eclipsites ก็แย่",
  str_voice_1401691_24 = "Allura เป็นผู้หญิงที่น่าทึ่งและสอนฉันมากมายเกี่ยวกับการเป็นหนุ่มเจ้าชู้ที่กล้าหาญ ฉันมองไปที่เธอจริงๆ",
  str_voice_1401691_25 = "Areia เป็นคนที่มอบไม้เบสบอล Coolster ให้ฉัน และสอนฉันมากมายเกี่ยวกับการเป็นฮีโร่ที่ห้าวหาญ ฉันเคารพเธอจริงๆ",
  str_voice_1401691_26 = "สิ่งที่ชอบ? หนังสือการ์ตูน แฟชั่น เครื่องประดับระยิบระยับ เพื่อนรุ่นพี่ของฉัน ถึงแม้ว่าพวกมันจะไม่ใช่ \"สิ่งของ\" ก็ตาม",
  str_voice_1401691_27 = "ฉันเกลียดเวลาที่มีคนทำกับฉันเหมือนเป็นคนโง่ แม้ว่าฉันจะทำเรื่องโง่ๆ ก็ตาม! ทั้งสีชมพู ผัก และวันฝนตก",
  str_voice_1401691_28 = "คุณรู้ไหมว่าอะไรทำให้ Colossus เย็นลง? ถ้าฉันสามารถใช้เป็นอาวุธของนักสู้สวอชบัคเลอร์หรือเป็นอุปกรณ์ขนส่งของนักสวอชบัคเลอร์แบบพิเศษได้",
  str_voice_1401691_29 = "ทักทายกับ Super Sadie Swashbuckler 666 ผู้ท้าชิงอันดับ 1 แห่งอนาคตใน Umbraton ทั้งหมด! อนาคตทำไม? ฉันจะบอกเธอภายหลัง.",
  str_voice_1401691_30 = "ฉันได้รับการควบคุมความแข็งแกร่งของฉัน!",
  str_voice_1401691_31 = "Coolster เติบโตเร็วขึ้นทุกวัน!",
  str_voice_1401691_32 = "ตอนนี้ฉันเย็นลงแล้วหรือยัง?",
  str_voice_1401691_33 = "ฉันจะเป็นเจ้าชู้ตัวจริงให้ได้!",
  str_voice_1401691_34 = "ฉันต้องทำงานร่วมกับผู้อื่นจริงหรือ? ไม่เป็นอะไร.",
  str_voice_1401691_35 = "คูลสเตอร์รอไม่ไหวแล้ว!",
  str_voice_1401691_36 = "ตอนนี้? คุณหมายถึงตอนนี้?",
  str_voice_1401691_37 = "Super Sadie Swashbuckler 666 พร้อมจู่โจม!",
  str_voice_1401691_38 = "ปล่อยให้ความรักของฉันเผาไหม้!",
  str_voice_1401691_39 = "ระดับสวิง!",
  str_voice_1401691_40 = "ปัง",
  str_voice_1401691_41 = "ฉันจะเก่งเท่ารุ่นพี่!",
  str_voice_1401691_42 = "คุณช่วยชมเชยฉันได้ไหม",
  str_voice_1401691_43 = "นี่คือสิ่งที่จะเกิดขึ้นเมื่อคุณไม่เรียน...?",
  str_voice_1401691_44 = "ฉันอยู่บนนกตัวใหญ่ที่บินได้ไกล ขับโดยมัคคุเทศก์ตัวน้อยที่เป็นมิตร",
  str_voice_1401691_45 = "ขอบคุณครับ",
  str_voice_1401691_46 = "ไม่มีทาง! จริงๆแล้วคุณ...",
  str_voice_1401691_47 = "ขอบคุณ! ฉันรักมัน! ผมรักมัน!",
  str_voice_1401691_48 = "ง-คุณอยากเป็นคนบ้าอะไรกับฉันไหม?",
  str_voice_1401691_49 = "พ่อแม่ของฉันทำงานในลูโมโปลิส ดูเหมือนว่าพวกเขาจะชอบที่นั่น ฉันไม่สามารถบอกคุณได้มากเกี่ยวกับสถานที่นี้ เพราะฉันจำอะไรไม่ได้มากตั้งแต่ตอนที่ฉันอาศัยอยู่ที่นั่นตอนยังเป็นเด็ก",
  str_voice_1401691_50 = "อะไรทำให้ฉันอยากเป็นเจ้าชู้เป็นอย่างแรก? เรื่องราวเริ่มต้นตั้งแต่ตอนที่ฉันโดดเรียน และ Miss Allura ดึงฉันไปพูดคุยเกี่ยวกับพฤติกรรมของฉัน ใช่ พวกสวอชบัคเลอร์ไม่สามารถประพฤติตัวไม่ดีได้ คุณเห็นไหม",
  str_voice_1401691_51 = "ก้าวแรกสู่การเป็น swashbuckler? เรียนรู้วิธีควบคุมพลังและสร้างความไว้วางใจกับเพื่อนร่วมชาติของคุณ นั่นคือสิ่งที่ Areia สอนฉันอยู่ดี เธอเจ๋งจริงๆ",
  str_voice_1401691_52 = "Alchemy Stars",
  str_voice_1401691_53 = "ว่าไง",
  str_voice_1401691_54 = "คุณขึ้น? ฉันพยายามจะหลุดออกไปจากที่นี่",
  str_voice_1401691_55 = "เที่ยงไม่ใช่เวลาที่ดีที่สุดสำหรับการแกว่งไกว",
  str_voice_1401691_56 = "อยากอ่านการ์ตูนแต่ก็เหนื่อย...",
  str_voice_1401691_57 = "สวัสดีปีใหม่! คุณคิดว่าฉันมีโอกาสค่อนข้างดีที่จะได้เป็นนักต้มตุ๋นที่ประสบความสำเร็จในปีนี้หรือไม่?",
  str_voice_1600254_10 = "เป็นอะไรกับความเงียบ? ทักษะการแสดงของฉันถูกบดบังจนลืมปรบมือหรือเปล่า?",
  str_voice_1600254_11 = "อยากให้ฉันแสดงละครเพื่อคุณไหม หรี่ไฟลง เอ่อ เดี๋ยวก่อน... ปล่อยให้สปอตไลท์สองอัน—อันหนึ่งอยู่กับฉัน และอีกอันหนึ่ง แน่นอน อยู่ที่ผู้ชมคนเดียวของฉัน",
  str_voice_1600254_16 = "ความดีและความชั่วร้ายสามารถเป็นศิลปะได้อย่างเท่าเทียมกัน วันนี้คุณชอบอันไหนมากกว่ากัน?",
  str_voice_1600254_17 = "เครื่องแต่งกาย การแต่งหน้า การนำเสนอ? สมบูรณ์แบบ! ไฟ? เราไม่ต้องการแสงเมื่อมีแสงแดดยามเช้าที่เป็นธรรมชาติที่สุด!",
  str_voice_1600254_18 = "สวัสดีตอนเย็นเพื่อน! โปรดทราบว่าช่างกล้องกำลังบันทึกอยู่",
  str_voice_1600254_19 = "มาเลย! ปล่อยให้ตัวเองตกอยู่ในค่ำคืนที่เงียบสงัดและมืดมิด และคุณจะได้รับแรงบันดาลใจที่คุณต้องการอย่างแน่นอน",
  str_voice_1600254_35 = "กล้องพร้อม",
  str_voice_1600254_36 = "ไฟกับฉัน!",
  str_voice_1600254_37 = "ให้เราคำรามและทำให้สถานที่นั้นมีชีวิตชีวา!",
  str_voice_1600254_38 = "มาถึงจุดไคลแม็กซ์!",
  str_voice_1600254_39 = "ช่วงการแสดงที่สมบูรณ์แบบเป็นของฉันที่จะสั่ง",
  str_voice_1600254_40 = "ไม่ นี่คือสคริปต์ของคุณ!",
  str_voice_1600254_44 = "อืม? คุณต้องอยากได้โปสเตอร์พร้อมลายเซ็นของฉันใช่ไหม",
  str_voice_1600254_58 = "ฉันใส่เฉพาะชุดราตรีที่ตัดเย็บแบบพิเศษและสวยงามนี้ในโอกาสที่เป็นทางการและมีชื่อเสียงที่สุดเมื่อฉันเป็นนักแสดง แน่นอนว่ามีข้อยกเว้นเช่นตอนนี้",
  str_voice_1600254_59 = "โครงการใดของฉันที่เราจะดูในวันนี้ อันที่จริง การเลือกนั้นยาก ดังนั้น... เรามาดูกันให้หมด!",
  str_voice_1600254_60 = "คุณมีเรื่องราวมากมายที่จะบอก... PlayerNameมาเปลี่ยนเรื่องราวชีวิตของคุณให้เป็นละครกันเถอะ! เราสามารถขี่ Other End และแสดงได้ทั่วโลก!",
  str_voice_1600254_61 = "\"สิ่งเดียวที่เลวร้ายยิ่งกว่าการถูกพูดถึงคือ การไม่ถูกพูดถึง...\" การอยู่รอดของศิลปินคืออะไร เว้นแต่การหลีกเลี่ยงความขุ่นเคืองอันเลวร้ายของความเฉยเมยที่เป็นที่นิยม?",
  str_voice_1600254_62 = "ศิลปินที่มีความสามารถสามารถสร้างสิ่งมหัศจรรย์จากบทธรรมดาที่สุดได้ ไม่เชื่อฉัน? ดีมากฉันจะแสดงให้คุณเห็น",
  str_voice_1600254_63 = "PlayerName, ผู้ชมที่เข้าใจฉันไม่เหมือนใคร, มันเยี่ยมมากที่คุณอยู่ที่นี่! ตอนนี้เรามาทบทวนผลงานการถ่ายทำของอัจฉริยะด้านศิลปะการแสดง Charon the Acheron Ferryman!",
  str_voice_1600254_64 = "สวัสดีตอนเช้าเพื่อนรักและผู้สนับสนุนของฉัน!",
  str_voice_1600254_65 = "การนอนในเช้าที่ง่วงนอนมักจะทำให้ฝันที่แปลกประหลาดที่สุด",
  str_voice_1600254_66 = "ตอนเช้าก็สวยงามในวันที่เต็มไปด้วยงาน เช่นเดียวกับวันที่เต็มไปด้วยการพักผ่อน!",
  str_voice_1600254_67 = "ฉากที่ 1 ฉากที่ 1!",
  str_voice_1600254_68 = "สวัสดีตอนเย็นเพื่อน",
  str_voice_1600254_69 = "ฉันชอบที่จะดูหนังของฉันซ้ำในตอนเย็น",
  str_voice_1600254_70 = "เหตุใดแรงบันดาลใจจึงหลบเลี่ยงฉัน...?",
  str_voice_1600254_71 = "“ราตรีสวัสดิ์ เด็กน้อยที่รักของฉัน”",
  str_voice_1600254_72 = "เฮ้! คุณไม่ควรเป็นคนบอกราตรีสวัสดิ์กับฉัน!",
  str_voice_1600254_73 = "มุมกล้องที่ประจบมากที่สุดของฉัน? ทั้งหมด 360 องศา",
  str_voice_1600254_74 = "ดูสิ่งที่เรามีที่นี่ ฉันสมบูรณ์แบบและเธอเกือบจะสมบูรณ์แบบ",
  str_voice_1600254_75 = "มีบางอย่างที่มีเสน่ห์มากเกินไปบางที",
  str_voice_1600254_76 = "ฉันต้องการถ้าเป็นไปได้อย่าปิดม่านในการมีส่วนร่วมในชีวิตของคุณ",
  str_voice_1600254_77 = "โลกที่ไม่ธรรมดาไม่ต้องการความเข้าใจจากคนที่เป็นกลาง",
  str_voice_1601751_1 = "ฉันเห็นคุณกำลังจ้องมอง PlayerName. พวกเขาไม่เจ็บ ผ้าพันแผลและอวัยวะเทียมเหล่านี้เป็นอุปกรณ์ที่จำเป็นสำหรับหุ่นยนต์ต่อสู้ และไม่ใช่ผลจากการได้รับบาดเจ็บในการต่อสู้",
  str_voice_1601751_2 = "ความรู้สึกของป๊อปร็อคแตกในปากของฉันค่อนข้างทำให้ดีอกดีใจ ฉันคิดว่านี่คือสิ่งที่คุณหมายถึงเมื่อคุณพูดถึง \"ความรู้สึก\" PlayerName.",
  str_voice_1601751_3 = "ศัตรูตัวเดียวที่ฉันไม่มีวันเอาชนะได้คือความง่วงเหงาหาวนอนนี้... แต่ก็อย่างที่ Yingel พูดเสมอว่า \"สู้ให้หนัก พักผ่อนให้เต็มที่\" หาว...",
  str_voice_1601751_4 = "ข้อต่อที่ขาของฉันอาจส่งเสียงดังเอี๊ยดอ๊าดราวกับว่าต้องใช้น้ำมัน แต่เมื่อฉันใส่ Luminatics เข้าไป ฉันก็สามารถกระโดดข้ามระยะทางมหาศาลได้ราวกับว่ามันเป็นสปริงที่ทรงพลัง",
  str_voice_1601751_5 = "ลูกบาศก์มีความสำคัญต่อฉันพอๆ กับหิ่งห้อยสำหรับเธอ PlayerName. คุณเข้าใจไหม?",
  str_voice_1601751_6 = "ตัวที่มีเฟืองนาฬิกาอยู่ด้านหลังคือ \"01\" ตัวที่มีปีกคือ \"10\" และตัวที่มีรัศมีรอบหัวคือ \"11\" จริงๆแล้วมันค่อนข้างง่ายที่จะแยกแยะ Cubes ออกจากกัน คุณว่ามั้ย?",
  str_voice_1601751_7 = "ฉันเข้าใจว่าการฝึกต้องโหดร้ายในบางครั้ง เนื่องจากการขาดคุณสมบัติและแม้แต่ความตายก็เป็นผลมาจากความพ่ายแพ้อย่างหลีกเลี่ยงไม่ได้ แต่สิ่งเหล่านี้จะไม่เกิดขึ้นตราบเท่าที่ฉันอยู่ในสนามรบ",
  str_voice_1601751_8 = "สวัสดี, PlayerName... ดูเหมือนว่าคุณจะไม่ได้ยินฉัน ในกรณีนั้น... คุณได้ยินฉันไหม",
  str_voice_1601751_9 = "ช่วยดูอะไรหน่อยได้ไหมครับ? ดูเหมือนว่าผ้าพันแผลของฉันจะไปติดอยู่ที่ข้อต่อขาของฉัน...",
  str_voice_1601751_10 = "พะ...เข้าใจแล้ว งานของฉันตอนนี้คือฟื้นพลัง",
  str_voice_1601751_11 = "ขอให้สนุกกับการทำงานปัจจุบันของคุณ PlayerName. คุณสามารถฝากเรื่องเร่งด่วน เช่น การฝึกพิเศษและกะเวรให้ฉันได้",
  str_voice_1601751_12 = "ฉันตรวจพบว่าคุณกำลังหยุดพัก โปรดเข้าร่วมฉันในเครื่องจำลองสำหรับการฝึกอบรมเพื่อเราจะได้สัมผัสกับความตื่นเต้นของการต่อสู้",
  str_voice_1601751_13 = "คุณบอกว่าคุณต้องการสอน Cubes ของฉันเล่นดนตรี? แต่ฉันไม่เชื่อว่าเราจะหาอุปกรณ์ที่เหมาะสมในอิลลูมินาได้... ขอโทษนะ? คุณต้องการใช้แผงควบคุมบน Colossus เพื่อสอนพวกเขาหรือไม่? เข้าใจแล้ว.",
  str_voice_1601751_14 = "ฉันเหนื่อยง่าย แต่การพักผ่อนสั้นๆ ในห้องชะงักงันคือทั้งหมดที่ฉันต้องการเพื่อฟื้นพลัง ขอเวลาฉันอีกสักหน่อย ได้โปรด",
  str_voice_1601751_15 = "สุขสันต์วันเกิด, PlayerName.",
  str_voice_1601751_16 = "ขอบคุณพระเจ้าที่เธอยังมีชีวิตอยู่และมีสุขภาพที่ดี... หืม? สิ่งที่ฉันพูดไปรบกวนคุณหรือเปล่า?",
  str_voice_1601751_17 = "กลิ่นของฝนลอยอยู่ในอากาศ และหิ่งห้อยเจ็ดตัวก็บินผ่านไป... ฉันหมายถึงอรุณสวัสดิ์",
  str_voice_1601751_18 = "คุณสังเกตเห็นบางสิ่งที่ไม่เหมือนใครเกี่ยวกับผิวของฉันหรือไม่? เมื่อพระอาทิตย์ตกดิน ร่างกายของฉันก็เริ่มส่องแสงจางๆ",
  str_voice_1601751_19 = "นอนไม่หลับ? คุณสามารถลองนอนในห้องโถงของฉันได้... แต่ฉันไม่คิดว่าเราทั้งคู่จะเข้าไปข้างในได้",
  str_voice_1601751_20 = "ฉันเป็นลูกของอิลลูมินาทั้งหมด เพื่อรับใช้อิลลูมินาคือจุดประสงค์ของฉัน",
  str_voice_1601751_21 = "เมืองที่ลอยอยู่บนท้องฟ้า? ฟังดูแตกต่างจากที่ปลายทางของ Sean อธิบายไว้บ้าง คุณต้องพาฉันไปที่นั่นเพื่อที่ฉันจะได้ตรวจสอบได้",
  str_voice_1601751_22 = "ขออิลลูมินาจงเจิดจำรัส",
  str_voice_1601751_23 = "การต่อสู้กับ Eclipsites เป็นเพียงกระบวนการที่ทำเป็นประจำ เนื่องจากผลลัพธ์จะเหมือนกันเสมอ",
  str_voice_1601751_24 = "บุคลิกของ Yingel ไม่ต่างจากพ่อของฉัน แต่ฉันรู้ว่า Yingel สามารถรับรู้ถึงอารมณ์ต่างๆ มากมาย",
  str_voice_1601751_25 = "ฌอนแตกต่างจากฉัน บางทีการประจำการในเขตสงครามจะทำให้พลังของเขาออกมาเต็มที่?",
  str_voice_1601751_26 = "โปรดให้ป๊อปร็อคมากขึ้นเพื่อเป็นรางวัลสำหรับชัยชนะของฉัน",
  str_voice_1601751_27 = "ขอโทษนะ มันยากสำหรับฉันที่จะยกกำลังใจขึ้นเมื่อฝนตก ขาของฉันรู้สึกหนักขึ้นมาก",
  str_voice_1601751_28 = "คุณใช้เวลาสิบเจ็ดปีในการนอนที่นี่? ฉันเข้าใจแล้ว... ดังนั้น Colossus จึงเป็นเพียงห้องที่ชะงักงันขนาดมหึมา",
  str_voice_1601751_29 = "ต่อสู้กับ Cyborg Axelia รายงานตัว ถ้าการต่อสู้คือทางเลือกสุดท้ายของคุณ ให้ฉันเป็นอาวุธที่ทรงพลังที่สุดของคุณ",
  str_voice_1601751_30 = "ตอนนี้ฉันเข้าใจอย่างสมบูรณ์แล้ว",
  str_voice_1601751_31 = "ฝึกง่ายๆ ไม่มีอะไรมาก",
  str_voice_1601751_32 = "ด้วยการฝึกฝนทำให้เกิดพลัง",
  str_voice_1601751_33 = "โปรดทดสอบความแข็งแกร่งของฉันในการต่อสู้จริง",
  str_voice_1601751_34 = "น้อมรับบัญชา",
  str_voice_1601751_35 = "Axelia อยู่ในโหมดสแตนด์บาย",
  str_voice_1601751_36 = "สาม...สอง...หนึ่ง...",
  str_voice_1601751_37 = "ขออภัยในความล่าช้า.",
  str_voice_1601751_38 = "เชื่อมือฉันได้เลย",
  str_voice_1601751_39 = "ฉันจะปกป้องทุกคน",
  str_voice_1601751_40 = "มันยังไม่จบ.",
  str_voice_1601751_41 = "เช่นเดียวกับในการฝึกอบรม",
  str_voice_1601751_42 = "ชัยชนะคือผลลัพธ์เดียวที่เป็นไปได้",
  str_voice_1601751_43 = "*ไอ* ประสบการณ์ที่ไม่เคยมีมาก่อน...",
  str_voice_1601751_44 = "เริ่มปฏิบัติหน้าที่ยาม...ไม่พบอันตรายในพื้นที่",
  str_voice_1601751_45 = "กรุณาวางไว้ตรงนั้น",
  str_voice_1601751_46 = "นี่เป็นวิธีสร้างความสัมพันธ์ที่ดีหรือไม่?",
  str_voice_1601751_47 = "เก็บมันไว้อย่างดี Cubes",
  str_voice_1601751_48 = "ฉันจะดูแลเรื่องนี้อย่างดี",
  str_voice_1601751_49 = "มันเป็นโปรแกรมฟอสเฟอรัสที่ทำให้ฉันเข้าใจโลก สำหรับ \"พ่อแม่ที่แท้จริง\" ของฉัน... ขอโทษด้วย แต่ฉันไม่มีไฟล์ความทรงจำเกี่ยวกับพวกเขา",
  str_voice_1601751_50 = "เมื่อผิวหนังของข้าพเจ้าขาดออกจากกัน ข้าพเจ้าประสบกับความตายในรูปแบบที่แท้จริงที่สุด ในความคิดของฉัน คนที่ให้ชีวิตฉันคือพ่อแม่ของฉัน ไม่ว่าฉันจะเกิดใหม่กี่ครั้งก็ตาม",
  str_voice_1601751_51 = "Algol มอบ The Cubes ให้ฉันเป็นของขวัญ พวกเขาไม่เพียงแต่ช่วยฉันในชีวิตประจำวันเท่านั้น พวกเขายังช่วยฉันในการต่อสู้ด้วย",
  str_voice_1601751_52 = "Alchemy Stars",
  str_voice_1601751_53 = "หาว...",
  str_voice_1601751_54 = "อรุณสวัสดิ์",
  str_voice_1601751_55 = "สวัสดียามบ่าย",
  str_voice_1601751_56 = "ฝันดี.",
  str_voice_1601751_57 = "หาว...สวัสดีปีใหม่",
  str_voice_1501761_1 = "ถ้าฉันสามารถเป็นเหมือนคุณจอห์นและนำทีมแพทย์ผู้เชี่ยวชาญที่ช่วยเหลือผู้คนทั่วแอสตร้าได้ ยังมีผู้คนมากมายในโลกที่ต้องทนทุกข์และต้องการการรักษา!",
  str_voice_1501761_2 = "การสางผมของเลดี้ราฟาเอลมักจะใช้เวลามากเสมอ... อย่ามองฉันแบบนั้น! ฉันไม่เคยบอกว่าฉันไม่สนุกกับมัน!",
  str_voice_1501761_3 = "แม้ว่าโอกาสรอดชีวิตของผู้ป่วยจะน้อยนิด แต่ฉันก็ไม่ยอมแพ้! เช่นเดียวกับหมอเหล่านั้นที่ไม่ยอมเลิกกับฉัน",
  str_voice_1501761_4 = "ฉันต้องการช่วยชีวิตผู้ป่วยทั้งหมดของฉันจากความเจ็บปวดจากการเจ็บป่วย แต่เพื่อให้บรรลุเป้าหมายนั้น ฉันต้องทำงานให้หนักที่สุดเท่าที่จะทำได้",
  str_voice_1501761_5 = "การฝึกร่างกายและลูมิเนติกส์มีความสำคัญต่อสุขภาพ แต่คุณไม่สามารถละเลยการฝึกจิตใจได้",
  str_voice_1501761_6 = "ฉันทำงานอย่างหนักตลอดเวลาเพื่อเฝ้ารอโอกาสเช่นนี้ เพื่อตระหนักถึงศักยภาพสูงสุดของฉัน! ขอบคุณที่เชื่อในตัวฉัน ฉันจะไม่ทำให้คุณผิดหวัง!",
  str_voice_1501761_7 = "ตอนนี้เราเป็นเพื่อนกันแล้ว ฉันก็มีหน้าที่ดูแลให้คุณมีสุขภาพที่ดีอยู่เสมอ! ถ้าคุณรู้สึกแย่กับสภาพอากาศ อย่าลังเลที่จะบอกฉัน โอเค?",
  str_voice_1501761_8 = "\"สมดุลระหว่างการทำงานและการพักผ่อน\" คุณว่าไหม? เฮ้อ... แม้ว่าฉันจะบอกคนอื่นแบบเดียวกันนี้อยู่เรื่อยๆ แต่บางครั้งฉันก็ทำตามคำแนะนำของตัวเองได้ยาก ขอบคุณสำหรับการเตือน ฉันจะพยายามหาเวลาพักผ่อนให้มากขึ้น",
  str_voice_1501761_9 = "ฉันก็เลยพักผ่อนเยอะๆ อย่างที่คุณแนะนำ...และตอนนี้ประสิทธิภาพในการทำงานของฉันก็ทะลุเพดานแล้ว! วิธีนี้ได้ผลดีกว่าการดึงคนที่นอนอยู่ตลอด ขอบคุณสำหรับคำแนะนำ!",
  str_voice_1501761_10 = "ออกไปพักผ่อนบ้าง? ดีมาก งั้นฉันจะไปศึกษาตำราแพทย์ของฉันบ้าง เวลาของฉันมีค่ามากสำหรับฉัน ดังนั้นฉันจึงต้องใช้เวลาทุกวินาทีให้มีค่า!",
  str_voice_1501761_11 = "มีคนต้องการการดูแลทางการแพทย์ที่นี่หรือไม่! นั่นอะไร? คุณแค่ต้องการให้ฉันยืนอยู่ที่นี่? ฉันเดาว่า... แต่สิ่งนี้ควรจะพัฒนาทักษะของฉันในฐานะแพทย์ได้อย่างไร?",
  str_voice_1501761_12 = "อย่าลืมเข้ารับการตรวจสุขภาพเป็นประจำ! ยิ่งคุณพบปัญหาสุขภาพเร็วเท่าไหร่การรักษาก็ง่ายขึ้นเท่านั้น!",
  str_voice_1501761_13 = "อะไรในโลกที่ทำให้เลดี้ราฟาเอลเชื่อว่าเธอสามารถซ่อมแซมหิ่งห้อยที่เสียหายได้ด้วย Holy Water Shell... ขอโทษนะ ฉันจะไปทำความสะอาดทันที",
  str_voice_1501761_14 = "การต่อสู้ครั้งต่อไปของเราจะราบรื่นยิ่งขึ้น เพราะฉันพัฒนาตัวเองอยู่เสมอ!",
  str_voice_1501761_15 = "สุขสันต์วันเกิด! โปรดรับเวชภัณฑ์ชุดนี้ คุณไม่มีทางรู้ว่าคุณจะต้องทำการปฐมพยาบาลเมื่อใด!",
  str_voice_1501761_16 = "ระวังสุขภาพร่างกายของคุณอยู่เสมอ มันเป็นสิ่งเดียวที่คุณมี!",
  str_voice_1501761_17 = "สวัสดีตอนเช้า! ถ้าวันนี้คุณมีภารกิจอะไรให้ทำ โปรดพาฉันไปด้วย ฉันรู้ว่าฉันมีประโยชน์กับทีมมาก!",
  str_voice_1501761_18 = "สวัสดีตอนเย็น! คุณก็ยุ่งทั้งวันเหมือนกัน ใช่ไหม? ฉันฝังจมูกไว้ในตำราแพทย์ตั้งแต่เช้า!",
  str_voice_1501761_19 = "เริ่มจะสายแล้ว คุณควรพักผ่อนโดยเร็ว ผม? ฉันไม่เหนื่อยเลย! นอกจากนี้ ยังมีเวลาให้ฉันฝึกวิชาลูมินาติกส์ด้วย!",
  str_voice_1501761_20 = "Lumopolis คือบ้านเกิดของฉัน และเป็นแหล่งความรู้ทางการแพทย์ทั้งหมดของฉัน เป็นสถานที่ที่สนับสนุนฉันและเป้าหมายของฉันมาโดยตลอด",
  str_voice_1501761_21 = "ผู้คนใน Umbraton เป็นอย่างอื่น ทุกครั้งที่ฉันไปที่นั่น ถนนจะเต็มไปด้วยรอยช้ำและเลือดจากการสู้รบ!",
  str_voice_1501761_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1501761_23 = "วิธีที่ดีที่สุดในการรักษา Eclipsites... คือปราศจากความเมตตา!",
  str_voice_1501761_24 = "เลดี้ราฟาเอลอาจดูบุ่มบ่ามไปบ้างในบางครั้ง แต่ฉันรับรองกับคุณว่าเธอเป็นหมอที่เก่งมาก!",
  str_voice_1501761_25 = "เลดี้คาร์ลีนต้องผ่านอะไรมามากมายเพื่อที่จะแข็งแกร่งเหมือนตอนนี้ เธอเป็นนักสู้จริงๆ ใช่ไหม",
  str_voice_1501761_26 = "ให้อาหารนก รดน้ำต้นไม้ ทำความสะอาดห้อง... นี่เป็นเพียงงานอดิเรกเล็กน้อยที่ Lady Raphael แนะนำให้ฉันทำ!",
  str_voice_1501761_27 = "ฉันทนไม่ได้กับชีวิตที่น่าเบื่อและอิ่มเอิบ มันบั่นทอนความทะเยอทะยานของคน ๆ หนึ่งและขโมยแรงจูงใจในการปรับปรุงตนเอง",
  str_voice_1501761_28 = "ยักษ์ใหญ่ดูเหมือนจะเป็นสิ่งมีชีวิต... ซึ่งหมายความว่ามันสามารถป่วยหรือบาดเจ็บได้ เช่นเดียวกับพวกเราที่เหลือ เมื่อเป็นเช่นนี้จะรักษาอย่างไร?",
  str_voice_1501761_29 = "ฉันชื่อ เบเร็ตต้า แพทย์ภาคสนาม และฉันได้รับคำสั่งให้ให้การสนับสนุน คุณเป็นผู้รับผิดชอบ Colossus นี้หรือไม่? มีใครบาดเจ็บไหม? พาฉันไปหาพวกเขา แล้วฉันจะรักษาพวกเขาทันที!",
  str_voice_1501761_30 = "ความคืบหน้าใด ๆ เป็นข่าวที่ยอดเยี่ยม!",
  str_voice_1501761_31 = "เยี่ยมมาก ได้เวลาทำงานหนักขึ้นแล้ว!",
  str_voice_1501761_32 = "ทิ้งทุกอย่างไว้ที่ฉัน!",
  str_voice_1501761_33 = "ฉันจะตอบสนองความเชื่อของคุณที่มีต่อฉันอย่างแน่นอน",
  str_voice_1501761_34 = "จะพยายามเต็มที่นะ!",
  str_voice_1501761_35 = "เตรียมตัวให้พร้อม!",
  str_voice_1501761_36 = "อุปกรณ์ทางการแพทย์ผ่านการฆ่าเชื้อ พร้อมใช้งาน!",
  str_voice_1501761_37 = "ส่องแสง Borealis Plume!",
  str_voice_1501761_38 = "ความพยายามทั้งหมดของฉันคือช่วงเวลานี้!",
  str_voice_1501761_39 = "แค่สะกิดเบาๆ อย่าขยับ!",
  str_voice_1501761_40 = "นี่เป็นส่วนสำคัญในการรักษาของคุณ!",
  str_voice_1501761_41 = "เอาล่ะ ปล่อยให้ฉันทำ!",
  str_voice_1501761_42 = "ใช่! ชัยชนะ!",
  str_voice_1501761_43 = "ฉันไม่กลัวความล้มเหลวหรืออะไรทั้งนั้น...แต่มันก็ยังเจ็บอยู่ดี",
  str_voice_1501761_44 = "ฉันหวังว่าทักษะการต่อสู้และความเชี่ยวชาญทางการแพทย์ของฉันจะพัฒนาต่อไปแบบนี้ทุกๆ วัน!",
  str_voice_1501761_45 = "ฉันสามารถใช้สิ่งนี้เพื่อพัฒนาทักษะทางการแพทย์ของฉันได้ไหม...",
  str_voice_1501761_46 = "ฉันรักมัน! ขอบคุณมาก!",
  str_voice_1501761_47 = "สิ่งนี้ถูกนำไปใช้ประโยชน์อย่างแน่นอน!",
  str_voice_1501761_48 = "คุณรู้จริง ๆ ว่าฉันชอบอะไร Navigator! ขอบคุณมาก!",
  str_voice_1501761_49 = "ในฐานะแพทย์ภาคสนาม งานของฉันไม่เพียงแต่สนับสนุนพันธมิตรของฉันเท่านั้น แต่ยังต้องลดความเสี่ยงที่เกี่ยวข้องกับการสู้รบอื่นๆ ให้มากที่สุด เพื่อที่จะทำหน้าที่ของฉันให้ดีที่สุด ฉันต้องทำงานไม่หยุดและพัฒนาตัวเองอยู่เสมอ!",
  str_voice_1501761_50 = "เมื่อก่อนฉันป่วยหนัก แต่ทีมแพทย์ที่นำโดยคุณจอห์นช่วยชีวิตฉันไว้ แผลเป็นรูปกากบาทบนหน้าผากของฉันไม่ใช่แค่ของที่ระลึกจากการผ่าตัดครั้งนั้น เป็นหลักฐานที่แสดงถึงฝีมือและความเมตตาของแพทย์ที่ช่วยฉันไว้",
  str_voice_1501761_51 = "แม้ว่าฉันจะถูกส่งไปยังที่ต่างๆ ที่ต้องการความช่วยเหลือบ่อยๆ แต่ฉันก็ยังเลือกที่จะดูแลเลดี้ราฟาเอลด้วยความสมัครใจ เธอเป็นหมอที่มีพรสวรรค์มาก และฉันรู้ว่าฉันสามารถเรียนรู้ได้มากมายจากการอยู่เคียงข้างเธอ",
  str_voice_1501761_52 = "Alchemy Stars",
  str_voice_1501761_53 = "สวัสดี!",
  str_voice_1501761_54 = "วันใหม่ควรเริ่มต้นด้วยการออกกำลังกายตอนเช้าเสมอ!",
  str_voice_1501761_55 = "สวัสดีตอนบ่าย! คุณทานอาหารกลางวันที่ดีและดีต่อสุขภาพแล้วหรือยัง?",
  str_voice_1501761_56 = "ยังตื่นอยู่เหรอ?",
  str_voice_1501761_57 = "สวัสดีปีใหม่! ฉันหยุดครึ่งวันเพื่อฉลองปีใหม่! ทำไมแค่ครึ่งวัน? ดังนั้นฉันสามารถใช้อีกครึ่งหนึ่งเพื่อติดตามการฝึกซ้อมทั้งหมดของฉันสำหรับวันนี้ได้แน่นอน!",
  str_voice_1601771_1 = "หืม คุณกำลังจ้องมองมาที่ฉัน? ฮะ ให้ฉันแสดงให้คุณเห็นว่าไอดอลที่แท้จริงเป็นอย่างไร! *ไอ* เดี๋ยวก่อน ฉันต้องกินยาแก้ไอสักหน่อยเพื่อป้องกันคอ",
  str_voice_1601771_2 = "เดาว่าต้องใช้เวลานานแค่ไหนกว่าที่ฉันจะดูดีได้ทุกวัน ครึ่งชั่วโมง? ล้อเล่นรึเปล่า!? แค่ครึ่งชั่วโมงก็แทบจะทำผมได้แล้ว!",
  str_voice_1601771_3 = "เรามีสไตล์ที่คล้ายกันจริงๆ! ฉันคิดว่าไมโครโฟนที่ฉันปรับแต่งเองก็มีเอกลักษณ์เฉพาะตัวเช่นกัน! อยากลองไหม โอ้ แต่เป็นทองคำบริสุทธิ์ ... คุณสามารถยกมันได้หรือไม่?",
  str_voice_1601771_4 = "อา-อา-อา! อุ๊ย อุ๊ย! น่าสนใจแค่ไหน ฉันคิดว่าช่วงเสียงของฉันเพิ่มขึ้นด้วยความช่วยเหลือของคุณ PlayerName!",
  str_voice_1601771_5 = "ฝีเท้าของฉันรู้สึกเบาลง เหมือนเป็นหนึ่งเดียวกับเสียงดนตรี มันเป็นความรู้สึกที่สวยงามและกลมกลืน! PlayerName, คุณต้องการที่จะเต้นรำกับฉัน?",
  str_voice_1601771_6 = "ความรู้สึกนี้... ใช่! ขอขอบคุณ, PlayerName! การแสดงตอนกลางคืนของฉันจะราบรื่นขึ้นมากตอนนี้!",
  str_voice_1601771_7 = "ให้ฉันบอกคุณเป็นความลับ! ถ้ามีใครเล็งปืนมาที่คุณ ตราบใดที่คุณนับในใจอย่างเงียบๆ และข้ามเลขเจ็ดทั้งหมด กระสุนจะไม่โดนคุณ! มันเป็นความจริง!",
  str_voice_1601771_8 = "มีโบว์ที่ส้นรองเท้าของฉัน โบว์ประดับด้านหน้าเสื้อผ้าของฉัน และโบว์ที่ชายกระโปรงของฉัน... ฉัน... ฉันแค่ชอบธนูจริงๆ! คุณชอบพวกเขาด้วยไหม PlayerName?",
  str_voice_1601771_9 = "ถ้าเธอต้องการ... ไม่นะ! คือ...ถ้าว่างก็ไปดูยอดผมสิ เป็นรูปหัวใจ!",
  str_voice_1601771_10 = "ฉันเข้าใจแล้ว... นี่คือความรู้สึกของความเหงา ฉันไม่ค่อยพบว่าตัวเองอยู่ในสถานะดังกล่าว แต่มันก็น่าสนใจที่จะได้สัมผัสกับความเงียบอย่างท่วมท้นต่อหน้านานๆ ครั้ง",
  str_voice_1601771_11 = "แม้ว่าฉันจะยืนอยู่ที่นี่เพียงลำพัง... แม้ว่าฉันจะยืนอยู่ที่นี่เพียงลำพัง ฉันก็ยังจะตะโกนบอกทุกคนที่อยู่ตรงหน้าว่า ฉันชอบโลกนี้! ฉันชอบทุกคน! ฉัน... ฉันชอบตัวเอง เพราะฉันสามารถมอบความสุขและความสุขให้กับทุกคนได้!",
  str_voice_1601771_12 = "คุณสังเกตเห็นกระสุนในเส้นผมของฉันหรือไม่? แน่นอนว่าการออกแบบนั้นสวยงาม แต่มันช่วยฉันได้มาก ทุกครั้งที่โยนออกไป มันจะตกลงไปที่พื้นโดยหันไปทางที่ถูกต้อง ฉันคิดว่ามันกำลังบอกฉันว่าเราควรเผชิญกับชีวิตในแง่บวกทุกวัน",
  str_voice_1601771_13 = "มันวิเศษมากที่ได้อยู่บนเวทีพร้อมกับผู้คนมากมายที่เฝ้าดูฉัน! พวกเขาให้ความกล้าหาญและพละกำลังกับฉันมาก เหมือนกับ... เหมือนกับเพื่อนตัวน้อยคนพิเศษของฉัน!",
  str_voice_1601771_14 = "มาร์ชเมลโล่! โอ้ มาร์ชเมลโล่! ฮะ? ไม่ ฉันไม่อยากกินมาร์ชเมลโลว์! Marshmallow เป็นชื่อของสุนัขตัวเล็กสีขาวข้างๆ ฉัน! ฮิฮิ ดูเหมือนหมาในโฆษณาที่ฉันชอบตอนเด็กๆ เป๊ะเลย!",
  str_voice_1601771_15 = "ฉันหวังว่าคุณจะมีความสุขในวันเกิด... แต่ฉันหวังว่าคุณจะมีความสุขทุกวันเช่นกัน!",
  str_voice_1601771_16 = "สวัสดี สวัสดี! คืนนี้คุณจะมาแสดงของฉันไหม ได้! ถือว่านี่คือคำเชิญอย่างเป็นทางการ!",
  str_voice_1601771_17 = "สวัสดีตอนเช้า! ฉันได้เริ่มการฝึกใช้เสียงสำหรับวันนี้แล้ว! ฉันหวังว่าฉันจะสามารถส่งกำลังใจที่ดีให้กับทุกคนด้วยเพลงที่ยอดเยี่ยม!",
  str_voice_1601771_18 = "ตอนนี้ฉันเหนื่อยนิดหน่อย...แต่ทุกคนตะโกนว่า \"อังกอร์\" ดังนั้น... ฉันไปต่อได้!",
  str_voice_1601771_19 = "ขอบอกความลับหน่อย... เหตุผลที่ฉันออกไปเที่ยวกลางคืนบ่อยๆ ก็เพราะฉัน... อยากเป็นฮีโร่ให้เด็กๆ เหลียวมอง!",
  str_voice_1601771_20 = "งานส่วนใหญ่ของฉันเกิดขึ้นใน Umbraton ดังนั้นบางครั้งฉันจึงชอบไปที่อื่นเพื่อให้ผู้คนจำนวนมากขึ้นได้ยินฉันแสดงสด",
  str_voice_1601771_21 = "ลูโมโพลิส? นักดนตรีกับไอดอลก็เหมือนสองสายพันธุ์! โดยสิ้นเชิง!",
  str_voice_1601771_22 = "บทเพลงและสีสันอันตระการตากำลังเฝ้าดูคุณอยู่!",
  str_voice_1601771_23 = "ใครก็ตามที่ไม่เห็นคุณค่าของความงามและรู้วิธีทำลายสิ่งต่าง ๆ เท่านั้น ให้ฉันตอบ!",
  str_voice_1601771_24 = "บรั่นดีเป็นผู้หญิงที่ทุ่มเทและเป็นมืออาชีพมาก!",
  str_voice_1601771_25 = "Lady Sheol ฉลาดจริงๆ! ฉันมักจะรู้สึกว่าฉันสามารถเรียนรู้สิ่งต่าง ๆ มากมายจากวิธีคิดของเธอเกี่ยวกับสิ่งต่าง ๆ",
  str_voice_1601771_26 = "ฮะ? ป้ายของฉัน? ฮิฮิ มันคือรางวัลทั้งหมดที่ฉันเคยได้รับ",
  str_voice_1601771_27 = "ได้เวลาชั่งน้ำหนักหลังจากกินมะระมาทั้งสัปดาห์... อ๊ะ! น้ำหนักของฉันไม่เปลี่ยนแปลงเลยสักนิด!",
  str_voice_1601771_28 = "อืม ฉันรู้ Soroz เป็นเหมือน Marshmallow ของคุณใช่ไหม?",
  str_voice_1601771_29 = "เฮ้! ฉันโกลดี้! คุณ PlayerName, ขวา? ฉันดีใจที่ได้พบเธอในโลกที่ระยิบระยับ งดงาม และอ่อนโยนใบนี้!",
  str_voice_1601771_30 = "ว้าว! อัศจรรย์!",
  str_voice_1601771_31 = "ฉันรู้สึกเหมือนกำลังจะบิน!",
  str_voice_1601771_32 = "ลาลาลา!",
  str_voice_1601771_33 = "ตอนนี้ฉันยอดเยี่ยมยิ่งกว่าเดิม!",
  str_voice_1601771_34 = "เข้าใจ!",
  str_voice_1601771_35 = "การเตรียมการเสร็จสมบูรณ์!",
  str_voice_1601771_36 = "ดีไป!",
  str_voice_1601771_37 = "เสียงของฉันเต็มไปด้วยพลัง!",
  str_voice_1601771_38 = "โน้ตสูงสุด!",
  str_voice_1601771_39 = "บลอสซั่ม!",
  str_voice_1601771_40 = "ส่องแสง!",
  str_voice_1601771_41 = "ทุ่มสุดตัว!",
  str_voice_1601771_42 = "ฉันมีความสุขมาก!",
  str_voice_1601771_43 = "อย่า...อย่าเพิ่งท้อ!",
  str_voice_1601771_44 = "อยู่ที่ไหนก็สร้างฝันใหม่ได้!",
  str_voice_1601771_45 = "อะไรนะ... ดีใจจัง!",
  str_voice_1601771_46 = "ฉันจะตอบแทนคุณด้วยการแสดงพิเศษ!",
  str_voice_1601771_47 = "ความรู้สึกขอบคุณนี้...ท่วมท้น!",
  str_voice_1601771_48 = "ของขวัญจากเธอ... ฉันจะเก็บมันไว้ตลอดชีวิต!",
  str_voice_1601771_49 = "ฉันเกิดมาในครอบครัวที่แสนจะธรรมดา เมื่อฉันยังเด็ก ฉันคิดว่าดาราทั้งหมดที่ฉันเห็นในทีวีอยู่ในอีกโลกหนึ่ง... และสุนัขมาร์ชเมลโล่ในโฆษณานั้นด้วย",
  str_voice_1601771_50 = "วันนั้นฉันถูกจับเป็นตัวประกัน? มันไม่ได้เลวร้ายทั้งหมด... หลังจากนั้นฉันกลายเป็นคนขี้กลัวเล็กน้อย แต่ฉันยังได้รับความสามารถที่ยอดเยี่ยมเช่นนี้ด้วย",
  str_voice_1601771_51 = "ฮิฮิ! คุณชอบที่จะเห็นฉันบนเวทีไหม ขอบคุณมาก! ฉันชอบคนที่ฉันอยู่บนเวที แต่ฉันชอบคนที่ฉันอยู่นอกเวทีด้วย",
  str_voice_1601771_52 = "Alchemy Stars!",
  str_voice_1601771_53 = "สวัสดี!",
  str_voice_1601771_54 = "สวัสดีตอนเช้า! คุณกำลังทำอะไรอยู่?",
  str_voice_1601771_55 = "สวัสดีตอนบ่าย! อย่าลืมรักษาความชุ่มชื้นให้ตัวเอง!",
  str_voice_1601771_56 = "หากคุณต้องการให้เสียงของคุณอยู่ในสภาพดีเยี่ยม อย่าลืมนอนแต่หัวค่ำ!",
  str_voice_1601771_57 = "สวัสดีปีใหม่! ฉันควรจะเรียนสเต็ปการเต้นเพิ่มเติมในปีนี้ใช่ไหม?",
  str_voice_1601781_1 = "*หาว* เฟียอยู่ไหน? ลูกศิษย์ตัวน้อยน่ารักของฉันอยู่ที่ไหน ต้องนวดไหล่! ฉันคิดว่าการนอนคว่ำจะไม่ดีต่อคอและไหล่ของฉัน...",
  str_voice_1601781_2 = "ขอโทษด้วยกับเรื่องนั้น, PlayerName. สัตว์มหัศจรรย์หลั่งบ่อย ฉันหวังว่าคุณจะไม่เป็นภูมิแพ้หรืออะไร ฉันจะให้เฟียไปทำความสะอาด อะไร คุณจะทำมัน? นั่นเป็นสิ่งที่ดีมากสำหรับคุณ! เริ่มจากการโกยขี้จากทราย...",
  str_voice_1601781_3 = "เป็นเรื่องหยาบคายที่จะถามอายุของใครก็ตาม ดังนั้นคุณต้องจำไว้เสมอว่าฉันอายุสิบแปดตลอดไป แต่คุณสามารถถามฉันเกี่ยวกับเรื่องอื่นๆ ได้ เช่น สารคัดหลั่งของสัตว์มหัศจรรย์ชนิดใดที่เหมาะกับผิวคุณที่สุด",
  str_voice_1601781_4 = "ฉันทำของเล่นนี้ขึ้นมาเป็นพิเศษจากขนนกที่ร่วงหล่นของนกเค้าแมวลูทูมิตามรสชาติของสัตว์ร้าย Furball น้อยรักมัน! Fia กล้าดียังไงมาเรียกฉันว่าขี้เหนียวเพราะมัธยัสถ์?",
  str_voice_1601781_5 = "ฉันเข้าใจว่าผู้คนมีความคิดและทัศนคติที่แตกต่างกันเกี่ยวกับสัตว์ร้าย แต่ฉันหวังว่าหนังสือของฉันจะทำให้ผู้คนจำนวนมากตกหลุมรักสิ่งมีชีวิตเล็กๆ เหล่านี้และเข้าใจวิถีทางของพวกมัน",
  str_voice_1601781_6 = "การเดินทางของฉันยังไม่สิ้นสุด ฉันแน่ใจว่ามีสัตว์มหัศจรรย์ที่ฉันยังไม่เคยเห็น ฉันอยากจะเห็นพวกเขาด้วยตาของฉันเอง",
  str_voice_1601781_7 = "ฉันเห็นว่าคุณสนใจสัตว์ร้ายเหมือนกัน ทำไมคุณไม่มาเป็นลูกศิษย์ของฉัน ฉันจะเสิร์ฟให้อีก... ฉันหมายถึงนักเรียน",
  str_voice_1601781_8 = "ถ้าคุณชอบสัตว์มหัศจรรย์ด้วย ครั้งหน้าอยากไปเที่ยวในแอสตร้ากับฉันไหม ฉันจะให้เครดิตคุณเป็นผู้ช่วยในหนังสือของฉัน ไม่ต้องห่วง ไม่ใช่ว่าฉันหวังจะได้แรงงานฟรี ค่าพาหนะ หรืออะไรทำนองนั้น...",
  str_voice_1601781_9 = "เด็กผู้หญิงคนหนึ่งซึ่งเป็นญาติของคุณเคยช่วยฉันเรียนรู้วิธีสื่อสารกับสัตว์ร้าย บางครั้งคุณทำให้ฉันนึกถึงเธอ... ฉันสงสัยว่าคุณสองคนเกี่ยวข้องกันหรือไม่?",
  str_voice_1601781_10 = "ง่วงนอน? มานอนกับฉันที่ Little Furball มันจะไม่รังเกียจ",
  str_voice_1601781_11 = "ฉันแค่ต้องนั่งเฝ้าอยู่ตรงนี้ใช่ไหม? ฉันจะแปรงเจ้าตัวน้อยเหล่านี้ในระหว่างนี้",
  str_voice_1601781_12 = "อาชู! เมื่อเร็ว ๆ นี้ฉันจามบ่อยมาก บางทีมีหญิงสาวข้างนอกนั่นกำลังคิดถึงฉันอยู่?",
  str_voice_1601781_13 = "ด้วยใบหน้าที่เหมือนฉัน ไอดอลคงตกงานถ้าฉันสามารถร้องเพลง เต้น หรือแสดงได้! พวกเขาควรจะขอบคุณฉันที่ได้เป็นฤาษี",
  str_voice_1601781_14 = "ความแข็งแกร่งของตัวละคร? นั่นคือสิ่งที่คุณคนหนุ่มสาวต้องไตร่ตรอง สำหรับคนแก่อย่างฉัน การเผชิญหน้ากับความจริงคือหนทางรอด",
  str_voice_1601781_15 = "คุณไม่ชอบของขวัญของฉันเหรอ มันคือฟันน้ำนมจาก Peko Rabbit! หายากสุดๆ!",
  str_voice_1601781_16 = "เฮ้ คุณเห็นต้นฉบับของฉันไหม หวังว่าจะไม่มีใครกินมันนะ...",
  str_voice_1601781_17 = "คุณตื่นเช้า จะต้องดีที่ยังเด็กและเต็มไปด้วยพลัง",
  str_voice_1601781_18 = "ฉันหิว... คุณเห็น Fia ไหม? ทำไมเด็กฝึกงานของฉันถึงไม่มาที่นี่พร้อมกับมื้ออาหารของฉัน?",
  str_voice_1601781_19 = "มาให้ฉันพาคุณออกไปและแสดงให้คุณเห็นสัตว์มหัศจรรย์ที่ออกหากินเวลากลางคืนของโลก",
  str_voice_1601781_20 = "นักสัตววิทยาเป็นกลุ่มที่แปลก แต่เราทุกคนรักสัตว์",
  str_voice_1601781_21 = "ไม้บรรทัดที่ชาญฉลาดรู้ว่าสิ่งแวดล้อมและระบบนิเวศมีความสำคัญต่อการพัฒนาเพียงใด",
  str_voice_1601781_22 = "หน้าที่ของฉันคือค้นหาสัตว์ร้ายและเรียนรู้ความลับของพวกมัน",
  str_voice_1601781_23 = "Eclipsites น่าเกลียดและน่าเบื่อ ดังนั้นฉันจึงไม่สนใจพวกมัน",
  str_voice_1601781_24 = "มันทำให้ฉันเสียใจที่ถูกเด็กฝึกงานคนโปรดของฉันเข้าใจผิด ผู้ซึ่งเรียกฉันว่าคนโกหกทุกวัน... *สะอื้น*",
  str_voice_1601781_25 = "ชิราเป็นเด็กที่เข้มแข็ง เธอจะสวมเสื้อคลุมเพื่อปกป้องสัตว์ร้าย!",
  str_voice_1601781_26 = "แอลกอฮอล์เป็นแรงบันดาลใจทั้งวรรณกรรมและศิลปะ เครื่องดื่มไม่กี่อย่างช่วยให้น้ำผลไม้สร้างสรรค์ไหลออกมาเสมอ!",
  str_voice_1601781_27 = "หึ! ใครเอาหนังสือของฉันไป! พวกเขาไม่เรียบร้อย!",
  str_voice_1601781_28 = "ฉันขอยืมเรือนกระจกได้ไหม สัตว์มหัศจรรย์บางชนิดต้องการสภาพแวดล้อมที่อบอุ่นกว่านี้เพื่อความอยู่รอด",
  str_voice_1601781_29 = "การทำความเข้าใจกับสัตว์ร้ายเป็นหนึ่งในหลายวิธีในการเรียนรู้เกี่ยวกับโลกนี้ ต้องการเห็นสถานที่ท่องเที่ยวที่น่าทึ่งของสิ่งมีชีวิตที่คุณไม่เคยเห็นมาก่อนหรือไม่?",
  str_voice_1601781_30 = "ฉันคิดว่าสิ่งมีชีวิตเล็ก ๆ เหล่านี้ได้พาคุณไปแล้ว",
  str_voice_1601781_31 = "อย่าเอาฉันไปพัวพันกับอะไรที่ซับซ้อน!",
  str_voice_1601781_32 = "ความโปรดปรานยากที่จะตอบแทน",
  str_voice_1601781_33 = "จิตใจของเราต้องเป็นหนึ่งเดียวเพื่อตระหนักถึงศักยภาพของเรา",
  str_voice_1601781_34 = "ไม่มีอะไรมากที่ฉันสามารถทำได้",
  str_voice_1601781_35 = "ตาคุณ.",
  str_voice_1601781_36 = "Furball ตัวน้อย ช่วยฉันด้วย!",
  str_voice_1601781_37 = "ลูกขนตัวน้อย ฟาดกรงเล็บ!",
  str_voice_1601781_38 = "*หาว* พวกนายเข้าใจแล้ว",
  str_voice_1601781_39 = "ฉันเหนื่อยแล้ว.",
  str_voice_1601781_40 = "ทำไมเรื่องนี้ยังไม่จบ?",
  str_voice_1601781_41 = "ได้โปรดเมตตา",
  str_voice_1601781_42 = "ฉันสบายดีเหมือนเมื่อก่อน...",
  str_voice_1601781_43 = "ฉันยอมแพ้!",
  str_voice_1601781_44 = "คุณต้องการ Lutumi Owl เพื่อทำให้คุณนอนหลับหรือไม่? หากคุณเป็นโรคนอนไม่หลับเรื้อรัง มีบริการเสริมการสะกดจิตการนอนหลับด้วย",
  str_voice_1601781_45 = "มาครั้งหน้า!",
  str_voice_1601781_46 = "คุณเป็นคนหนุ่มสาวที่ใจดีอะไรอย่างนี้",
  str_voice_1601781_47 = "ฉันยินดีจะรับมันไว้",
  str_voice_1601781_48 = "*สะอื้น* ฉันสะเทือนใจจนแทบจะร้องไห้ในวินาทีนี้",
  str_voice_1601781_49 = "ฉันได้สัมผัสกับสัตว์ร้ายเมื่อตอนที่ฉันยังเด็ก แต่เนื่องจากธุรกิจครอบครัวของฉัน ฉันได้ทำสิ่งที่ทำร้ายพวกมันในอดีต แผลเป็นและปีกที่เหลืออยู่ของฉันคือราคาที่ฉันต้องจ่ายสำหรับการละเมิดเหล่านั้น",
  str_voice_1601781_50 = "สัตว์มหัศจรรย์เป็นสิ่งมีชีวิตที่เรียบง่าย ไร้เดียงสา ปราศจากการหลอกลวงที่ชาวออโรเรียนมักจะเจอ ฉันช่วยเจ้า Furball ตัวน้อยไว้ และมันตัดสินใจร่วมเดินทางกับฉันขณะที่ฉันท่อง Astra คอยปกป้องฉันตลอดทาง ไม่เหมือนเด็กฝึกงานสองคนนั่นที่ตะคอกใส่ฉันทั้งวัน... เฮ้อ",
  str_voice_1601781_51 = "ไม่ใช่ว่าฉันไม่ไว้ใจคุณ เป็นเพียงว่าฉันไม่รู้มากเกี่ยวกับสายเลือดของฉัน ฉันเคยอ่านเกี่ยวกับโอโรโบรอสในหนังสือโบราณเท่านั้น และฉันยังคงพยายามคิดว่าฉันเชื่อมโยงกับมันได้อย่างไร หากคุณสนใจในตัวฉันมาก ต้องการช่วยฉันค้นหาโอกาสในการขายหรือไม่",
  str_voice_1601781_52 = "Alchemy Stars",
  str_voice_1601781_53 = "อ๊ะ!",
  str_voice_1601781_54 = "เธอตื่นเช้านะเนี่ย",
  str_voice_1601781_55 = "ต้องการที่จะงีบหลับด้วยกัน?",
  str_voice_1601781_56 = "การเข้านอนเร็วเป็นกุญแจสำคัญในการคงความอ่อนเยาว์",
  str_voice_1601781_57 = "สวัสดีปีใหม่! ฉันทำถุงมือจากขนของ Little Furball สำหรับคุณและลูกศิษย์สองคนของฉัน",
  str_voice_1601781_58 = "ฉันจะรอคุณข้างหน้าเฟีย",
  str_voice_1601781_59 = "ฉันเป็นครูที่ดีจริงๆ ใช่ไหม",
  str_voice_1501801_1 = "การรวบรวมข้อมูลมีความสำคัญมาก นกกระจาบใส่หมวกของฉัน บลานช์รับผิดชอบลูโมโพลิส นกพิราบสีเทาซินเดอร์รับผิดชอบดูแลลูโมโพลิสตอนล่าง และชาโดว์หนูของฉันรับผิดชอบดูแลอัมบราตัน",
  str_voice_1501801_2 = "คุณคิดว่าเกียร์ของฉันดูหนัก? อา ขอบคุณ แต่ฉันดูแลตัวเองได้ หากคุณต้องการเป็นนักข่าวอิสระ สิ่งเหล่านี้คือพันธมิตรที่ขาดไม่ได้ในสายงาน",
  str_voice_1501801_3 = "ฉันรู้ว่าคุณหมายถึงอะไร ตอนนี้คุณไม่ชอบที่นี่ใช่ไหม คุณมีความคิดมากมายที่ยังไม่ได้รับรู้ใช่ไหม? ฮะ? คุณปฏิเสธหรือไม่ จริงหรือ ฉันไม่เชื่อคุณ",
  str_voice_1501801_4 = "ว้าว ฉันรู้สึกว่ากระเป๋าของฉันเบาขึ้นในทันใด! สิ่งนี้จะทำให้สิ่งต่าง ๆ ง่ายขึ้นมาก... ขอบคุณ PlayerName.",
  str_voice_1501801_5 = "บลานช์พบแรงจูงใจ ซินเดอร์พบอาวุธสังหาร และชาโดว์พบพยาน... ใช่แล้ว! ฉันรู้แล้วว่าใครคือฆาตกร! รายงานพิเศษจะออกเร็วๆ นี้!",
  str_voice_1501801_6 = "ว้าว ความเร็วในการเขียนของฉันทะลุเพดานแล้ว! ฉันต้องบอกบรรณาธิการของฉันเกี่ยวกับเรื่องนี้ทันที เฮ้ บางทีฉันอาจจะได้เป็นพนักงานเขียนเร็วๆ นี้ก็ได้!",
  str_voice_1501801_7 = "นี่เป็นครั้งแรกที่มีคนพูดแบบนี้กับฉัน คุณไม่ได้พยายามที่จะติดสินบนฉันใช่ไหม ถึงกระนั้น ฉันจะไม่หยุดรายงานการผจญภัยทั้งหมดของคุณตามความจริง!",
  str_voice_1501801_8 = "ฉันต้องการเขียนคุณสมบัติพิเศษเกี่ยวกับคุณ เอิ่ม... ฉันหมายถึง นั่นคือสิ่งที่บรรณาธิการขอ... ฉันเพิ่งรู้เกี่ยวกับมันเอง",
  str_voice_1501801_9 = "คุณ... อืม ที่จริงฉัน... หายใจ บรั่นดี ที่จริงฉันแค่อยากจะถามว่ามันโอเคไหมที่เราจะทำแบบนี้? นักข่าวและผู้ให้สัมภาษณ์ของเธอ?",
  str_voice_1501801_10 = "ฉันจะจดทุกสิ่งที่คุณทำในสายตาของฉัน คุณกลัว? อะฮ่าฮ่าฮ่า—ไม่ ฉันไม่ได้หัวเราะ",
  str_voice_1501801_11 = "เอาล่ะ นี่เป็นโอกาสที่หายาก! ไม่มีใครมารบกวนฉัน และบรรณาธิการของฉันก็หายใจไม่ทั่วท้องเกี่ยวกับกำหนดเวลา... ได้เวลาทำงานทั้งหมดของฉันจากสัปดาห์ที่แล้วให้เสร็จ!",
  str_voice_1501801_12 = "นักข่าวชั้นหนึ่งไม่เคยลังเลแม้แต่วินาทีเดียว แม้อยู่กลางสมรภูมิรบ",
  str_voice_1501801_13 = "คุณอยากรู้เกี่ยวกับกระเป๋าของฉันไหม มีลีดและทรัพยากรล้ำค่าทุกประเภทอยู่ในนั้น—สมบัติล้ำค่าที่นักข่าวควรภาคภูมิใจ ฮะ? แค่อยากรู้ว่าหน้าตาเป็นยังไง!?",
  str_voice_1501801_14 = "ฟังนะ เมื่อคุณไล่ตามเบาะแสและผ้าคลุมของคุณกำลังจะปลิว ก็แค่ทำในสิ่งที่ฉันทำ—ลดปีกหมวกลง สวมแว่นกันแดด และติดกระดุมเสื้อโค้ท",
  str_voice_1501801_15 = "สุขสันต์วันเกิด! วันนี้คุณต้องมีความสุขมากใช่ไหม? คุณได้รับของขวัญอะไร และจากใคร?",
  str_voice_1501801_16 = "ผู้ให้สัมภาษณ์คนนั้นพูดความจริงหรือไม่? ฉันได้ตรวจสอบข้อเท็จจริงทั้งหมดแล้วหรือยัง? โอ้! สวัสดี ฉันทำงานหนักเช่นเคย!",
  str_voice_1501801_17 = "นกของฉันออกไปกินเศษขนมปังข้างถนนทุกเช้า แต่ทำไมพวกเขาถึงเลือกถนนสายนี้เสมอ? เรื่องนี้ต้องสอบสวน...",
  str_voice_1501801_18 = "สวัสดีตอนเย็น. ฉันกำลังเตรียมตัวสำหรับการถ่ายทำในวันพรุ่งนี้ ฟิล์ม: เช็ค ฝาครอบเลนส์: เช็ค หลอดไฟ: เช็ค...",
  str_voice_1501801_19 = "ฉันไม่คิดว่าคุณจะเคยต่อสู้กับบางสิ่งบางอย่าง เช่น การไม่ผ่านช่วงทดลองงาน ใช่ไหม ยังไงก็ตามคุณควรพักผ่อนบ้างนะ",
  str_voice_1501801_20 = "Umbraton มีบางสิ่งที่ตอบสนองทุกความต้องการ ไม่ว่าจะเป็นประเด็นทางสังคมที่คุณสนใจหรือเรื่องอื่นๆ ที่คุณสนใจเกี่ยวกับ Aurorian",
  str_voice_1501801_21 = "Lumopolis... ฉันไม่รู้ว่าพวกเขามีนักข่าวอยู่ที่นั่นด้วยหรือเปล่า",
  str_voice_1501801_22 = "บลานช์ ซินเดอร์ และชาโดว์กำลังเฝ้าดูคุณอยู่!",
  str_voice_1501801_23 = "พวกเขาดูไม่น่าสนใจเป็นพิเศษ",
  str_voice_1501801_24 = "วิคคือคนที่ฉันอยากสัมภาษณ์มาก...สักวันฉันจะต้องได้!",
  str_voice_1501801_25 = "ลิลิก้าก็เหมือนฉัน! เราต่างมุ่งมั่นไล่ตามความฝัน",
  str_voice_1501801_26 = "เป็นความจริงหรือไม่ที่ Vice และ Carleen มีความโน้มเอียงไปในทางที่แตกต่างกันเมื่อตอนที่พวกเขาอยู่ในโรงเรียน? หืม ได้ ฉันจะหยุดถาม",
  str_voice_1501801_27 = "ฉันไม่เข้าใจจริงๆ ว่าผู้นำเหล่านั้นกำลังคิดอะไรอยู่... ดูเหมือนว่าพวกเขาจะอยู่ในโลกอีกใบที่แยกจากความเป็นจริงโดยสิ้นเชิง และพวกเขาก็เลี้ยงดูคนรุ่นใหม่ด้วยคำโกหก!",
  str_voice_1501801_28 = "Soroz สามารถสื่อสารกับคุณเท่านั้น? โอ้... คุณช่วยอะไรฉันหน่อยได้ไหม? เห็นแล้วอยากให้ช่วยแปลให้เราสัมภาษณ์หน่อยค่ะ คุณรู้ได้อย่างไรว่าฉันจะถาม",
  str_voice_1501801_29 = "ฉันชื่อ Brandy เป็นนักข่าวฝึกหัดจาก The Daily Scoop คุณ PlayerName? เยี่ยม ในที่สุดฉันก็ได้พบคุณ! คุณคือขุมทรัพย์ที่ใหญ่ที่สุดของหัวข้อข่าวใน Astra ทั้งหมด!",
  str_voice_1501801_30 = "ฉันสามารถเขียนได้เร็วขึ้นแล้ว!",
  str_voice_1501801_31 = "ใจของฉันรู้สึกโล่งมาก!",
  str_voice_1501801_32 = "ฉันเข้าใจทุกอย่างแล้ว!",
  str_voice_1501801_33 = "A-ฉันทำงานเต็มเวลาแล้วหรือยัง?",
  str_voice_1501801_34 = "ฉันต้องเขียนทั้งหมดนี้ลงไป",
  str_voice_1501801_35 = "แรงบันดาลใจของฉันกำลังไหล!",
  str_voice_1501801_36 = "คุณพร้อมสำหรับการนี้หรือไม่?",
  str_voice_1501801_37 = "นี่คือความรู้สึกของการต่อสู้!",
  str_voice_1501801_38 = "ความจริงแล้ว พลัง!",
  str_voice_1501801_39 = "กล้องพร้อม!",
  str_voice_1501801_40 = "การกระทำ!",
  str_voice_1501801_41 = "ฉันจัดการเอง",
  str_voice_1501801_42 = "ฮ่าๆ ฉันรู้แล้ว!",
  str_voice_1501801_43 = "ขอโทษนะ...",
  str_voice_1501801_44 = "ฮา! มีเรื่องราวอยู่ที่นี่ที่ไหนสักแห่ง...",
  str_voice_1501801_45 = "ขอบคุณ! ฉันรักมัน!",
  str_voice_1501801_46 = "ว้าว! ฉันจะใส่มันในกระเป๋าของฉัน!",
  str_voice_1501801_47 = "เดี๋ยวก่อน ฉันอายนิดหน่อย...",
  str_voice_1501801_48 = "*สะอื้น* PlayerName...",
  str_voice_1501801_49 = "ฉันเริ่มอ่านหนังสือพิมพ์และนิตยสารเมื่อตอนที่ฉันยังเป็นเด็ก แม้ว่าตอนนั้นฉันจะสนใจแค่คอลัมน์ซุบซิบ แต่ฉันเรียนรู้ที่จะอ่านและเขียนจากเกร็ดข่าว",
  str_voice_1501801_50 = "สงครามทำให้ฉันรู้ว่าชีวิตมีอะไรมากกว่าเรื่องซุบซิบ แม้แต่ฉันก็ไม่รู้ว่าฉันจะให้คำจำกัดความของข่าวได้อย่างไร...",
  str_voice_1501801_51 = "พ่อแม่ของฉันต้องการให้ฉันเรียนการค้าขาย แต่ฉันคิดว่าการสัมภาษณ์และการเขียนเป็นทักษะที่ฉันจะต้องฝึกฝนไปตลอดชีวิต อืม... มันจะดีกว่าจริงๆ ถ้าฉันสามารถเป็นพนักงานประจำที่งานปัจจุบันของฉันได้",
  str_voice_1501801_52 = "Alchemy Stars!",
  str_voice_1501801_53 = "สวัสดี ฉันชื่อบรั่นดี",
  str_voice_1501801_54 = "สวัสดีตอนเช้า. ฉันมาถึงโต๊ะทำงานแล้ว",
  str_voice_1501801_55 = "สวัสดีตอนบ่าย! ถือโอกาสนี้หาอะไรกินกันเถอะ!",
  str_voice_1501801_56 = "ใช่ วันนี้ฉันยังร่างไม่เสร็จ",
  str_voice_1501801_57 = "สวัสดีปีใหม่, PlayerName. แม้ว่าข่าวของปีที่แล้วจะไม่ค่อยดีนัก ตราบใดที่ฉันบันทึกทุกอย่างอย่างตรงไปตรงมาและมีคนให้ความสนใจกับมัน... ฉันรู้ว่าปีหน้าจะดีกว่านี้",
  str_voice_1600773_1 = "คุณเคยสังเกตไหมว่าในที่ที่ท่วงทำนองไหล แม้กระทั่งทิวทัศน์ที่ไม่สำคัญและไม่สำคัญที่สุด ก็เริ่มเปล่งประกายราวกับเพชรพราวเมื่อต้องแสงอาทิตย์?",
  str_voice_1600773_2 = "อะไรทำให้เพลงที่ดี? ท่วงทำนองที่หรูหราหรือเนื้อเพลงที่หรูหรา? Caelestite ทุกอย่างเกี่ยวกับหัวใจ",
  str_voice_1600773_3 = "ชีวิตของแต่ละคนก็เหมือนบทเพลงที่มีเอกลักษณ์เฉพาะตัว โอ้? คุณต้องการที่จะรู้ว่าเพลงชีวิตของฉันเป็นอย่างไร? บางทีคุณอาจตอบคำถามนั้นให้ฉันได้",
  str_voice_1600773_10 = "มาเลย อย่าให้เสียเวลาเว้นวรรคกันเลย นั่งหน้าเปียโนนี้ แล้วเราจะใช้ดนตรีคุยกันเกี่ยวกับอนาคต",
  str_voice_1600773_11 = "วันของนักร้องหญิงเป็นอย่างไร? บางทีการใส่ชุดนี้จะช่วยให้คุณเข้าใจ อืม? คุณเรียกสิ่งนี้ว่า... คอสเพลย์? ถ้าอย่างนั้นก็แสดงว่าคุณเป็นแฟนฉันแล้วใช่ไหม?",
  str_voice_1600773_12 = "ไม่ว่าคุณจะทำสายกีตาร์พัง เปียโนของคุณเสีย หรือกลองของคุณเป็นรู ขอให้มีศรัทธาว่าดนตรีไพเราะไม่มีวันตาย",
  str_voice_1600773_13 = "มีเพียงเพลงที่คุณเล่นเท่านั้นที่สามารถปลุก Colossus ที่หลับใหลได้ ไม่ ไม่ใช่แค่ยักษ์ใหญ่... อืม ยังเร็วเกินไปที่จะพูดถึงเรื่องนี้หรือไม่?",
  str_voice_1600773_14 = "คุณสังเกตเห็นความเศร้าในการร้องเพลงของฉัน? มักพูดกันว่าอารมณ์ของเราสะท้อนออกมาในเพลงของเรา และตอนนี้ฉันเห็นว่ามันเป็นความจริง... จุ๊ๆ ได้โปรดเก็บเรื่องนี้ไว้ระหว่างเราด้วย",
  str_voice_1600773_16 = "เพลงของนักร้องซุกซนดังไปทั่วทุ่งหิมะที่ว่างเปล่า ฟังเสียงของพวกเขาที่ละลายแม้กระทั่งหิมะ",
  str_voice_1600773_17 = "อืม? คุณตื่นแล้ว ฉันรู้แล้ว เพลงเบาๆ มีประสิทธิภาพมากกว่าในการปลุกผู้คนให้ตื่น",
  str_voice_1600773_18 = "เมื่อค่ำคืนมาเยือนนอร์ธแลนด์ ทุกครอบครัวจะฮัมเพลงบัลลาดเพลงเดียวกัน...♪",
  str_voice_1600773_19 = "ทำไมคุณยังขึ้น? ก็ได้ ถ้าคุณยืนยันที่จะเป็นผู้ชมรอบดึกของฉัน",
  str_voice_1600773_35 = "วงดนตรีของนอร์ธแลนด์อยู่ในตำแหน่ง",
  str_voice_1600773_36 = "ได้เวลาเริ่มการแสดงแล้ว",
  str_voice_1600773_37 = "เพลงนี้มอบให้ชาวออโรเรียนทุกคน",
  str_voice_1600773_38 = "ฝังท่วงทำนองนี้ไว้ในหัวใจของคุณ",
  str_voice_1600773_39 = "ตีคอร์ด!",
  str_voice_1600773_40 = "เสียงธารน้ำแข็ง!",
  str_voice_1600773_44 = "ผู้ฟัง มาส่งความหวังผ่านบทเพลงกันเถอะ",
  str_voice_1600773_58 = "เช้า ฉันรอคุณอยู่",
  str_voice_1600773_59 = "จิบชาเพื่อเริ่มต้นวันที่เงียบสงบ...",
  str_voice_1600773_60 = "เช้านี้คุณได้ยินเสียงนกร้องไหม?",
  str_voice_1600773_61 = "เมื่อคืนคุณฝันถึงคุณหรือเปล่า?",
  str_voice_1600773_62 = "เช้าวันใหม่ผ่านไปในพริบตา ใช้ประโยชน์สูงสุดจากมัน",
  str_voice_1600773_63 = "\"เกล็ดน้ำแข็งระยิบระยับเมื่อต้องแสงอาทิตย์ยามเช้า...\"",
  str_voice_1600773_64 = "มันเป็นวันใหม่ วันนี้ฉันจะมีชีวิตแบบไหน?",
  str_voice_1600773_65 = "สวัสดีตอนบ่ายผู้ฟังของฉัน",
  str_voice_1600773_66 = "ครึ่งหนึ่งของวันนี้ผ่านไปแล้ว คุณรู้สึกอย่างไร?",
  str_voice_1600773_67 = "อย่าลืมว่า Northland จะเป็นบ้านของคุณเสมอ",
  str_voice_1600773_68 = "เธอจะเข้าใจเอง เมื่อเวลานั้นมาถึง",
  str_voice_1600773_69 = "ชิ้นส่วนของคุณกระจัดกระจายอยู่ในเศษเสี้ยวของอนาคต",
  str_voice_1600773_70 = "การล้างแค้นไม่ใช่เหตุผลที่จะต่อสู้",
  str_voice_1600773_71 = "หากคุณตั้งใจจริงที่จะก้าวเข้าสู่สนามรบ ก่อนอื่นคุณต้องค้นหาสิ่งที่คุณต้องการปกป้อง",
  str_voice_1601781_99 = "ฉันฝึกแทมบูรีนมานานเพื่อให้เก่ง ฉันหวังว่าฉันจะไม่ทำให้ทุกคนผิดหวัง!",
  str_voice_1601031_99 = "เพลงคอนเสิร์ตจะฟังดูดีกว่าเสียงกรีดร้องในห้องสอบสวนได้อย่างไร?",
  str_voice_1601481_99 = "คุณจะตอบแทนฉันอย่างไรหลังจากการแสดง?",
  str_voice_1601161_99 = "ฉันขอชิ้นส่วน Wandering Colossus สักสองสามชิ้นเป็นของที่ระลึกหลังการแสดงได้ไหม",
  str_voice_1600021_99 = "สำหรับฉันแล้ว การแสดงก็เป็นการฝึกประเภทหนึ่งที่สามารถฝึกฝนนิสัยใจคอของฉันได้",
  str_voice_1601771_99 = "ฉันหวังว่าการร้องเพลงของฉันจะทำให้ทุกคนมีแรงบันดาลใจและเข้มแข็ง!",
  str_voice_1601811_1 = "ฉันไปทะเลกับ Lin Guildmaster หลายครั้ง มันสวยงามมากบนเกลียวคลื่น คุณสามารถใส่ความคิดของคุณในด้านใดด้านหนึ่งและเพลิดเพลินไปกับสถานที่ท่องเที่ยวได้อย่างสุดใจ",
  str_voice_1601811_2 = "แมวสามตัวนี้อยู่กับฉันมาหลายปี พวกเขาเป็นส่วนหนึ่งของฉัน—เราแยกกันไม่ออก",
  str_voice_1601811_3 = "หากคุณต้องการ เพื่อนสาว ฉันยินดีที่จะบอกคุณเพิ่มเติมเกี่ยวกับประวัติศาสตร์ ขนบธรรมเนียม และประเพณีของหลงโจว",
  str_voice_1601811_4 = "ความทุกข์ยากใด ๆ ในชีวิตคือการเดินทางที่คุ้มค่ากับเพื่อน ๆ เช่นคุณ",
  str_voice_1601811_5 = "ในช่วงครึ่งแรกของชีวิต ฉันไม่มีใครหยุดได้และเป็นวีรบุรุษ ในขณะที่ในช่วงครึ่งหลัง ฉันล่องลอยไปเหมือนแหน แต่สิ่งที่มัน? ไม่มีใครสามารถตัดสินใจได้ว่าฉันต้องอยู่ที่ไหน และไม่มีใครทำให้จิตใจของฉันไม่สงบได้",
  str_voice_1601811_6 = "เอาล่ะ เอาล่ะ! ชื่อเสียงเป็นเพียงฝุ่นผงในสายลม—ฉันยังไม่แก่ และฉันยังสามารถสั่งเปลวไฟสีแดงในมือเพื่อกำจัดความชั่วร้ายทั้งหมดได้!",
  str_voice_1601811_7 = "คุณอยู่ในช่วงเวลาของชีวิต เพื่อนหนุ่ม ทำให้นึกถึงอดีต...ไปเดินเล่นคุยกันไหม?",
  str_voice_1601811_8 = "ฉันได้รับประโยชน์อย่างมากจากการได้พบคุณ เพื่อนหนุ่ม - ได้เห็นความกว้างใหญ่ของโลก เหนือผืนฟ้าที่อยู่เหนือหลงโจว",
  str_voice_1601811_9 = "เมื่อฉันยังเด็กฉันก็เหมือนกับคุณ ฉันหวังว่าคุณจะเดินหน้าต่อไปในอนาคตและไล่ตามดวงดาว",
  str_voice_1601811_10 = "ช่วงนี้เดินทางท่องโลกมาซะนานเลยอดคิดถึงบ้านเกิดไม่ได้...",
  str_voice_1601811_11 = "เป็นเกียรติที่ได้รับความไว้วางใจจากคุณ เพื่อนของฉัน",
  str_voice_1601811_12 = "เมื่อลมพัด มันทำให้ฉันนึกถึงฤดูใบไม้ร่วงที่บ้านเกิดของฉันเสมอ",
  str_voice_1601811_13 = "คุณสามารถเล่นกับแมวของฉันได้ทุกเมื่อที่คุณต้องการ พวกเขาเรียกว่า Yixin, Yimeng และ Yinuo ไม่ต้องกังวล พวกเขารู้ว่าคุณเป็นเพื่อนของฉันและจะไม่ทำร้ายคุณ",
  str_voice_1601811_14 = "รถเข็นของฉันดูเหมือนจะส่งเสียงแปลกๆ เมื่อเร็วๆ นี้ อาจจะเป็นจินตนาการของฉัน? พูดตามตรงฉันไม่สามารถชินกับมันได้",
  str_voice_1601811_15 = "ฤกษ์ดีวันไหน. ฉันขอให้คุณมีสุขภาพที่ดีและประสบความสำเร็จในทุกสิ่งที่คุณมุ่งมั่น",
  str_voice_1601811_16 = "เมื่อคุณรู้สึกงุนงงกับบางสิ่ง เพียงหลับตาและทำสมาธิสักครู่",
  str_voice_1601811_17 = "การอาบแสงยามเช้าทำให้จิตใจสงบ",
  str_voice_1601811_18 = "การเรียนรู้ที่จะผ่อนคลายหลังจากทำงานมาทั้งวันก็เป็นวิธีที่ดีในการปรับปรุงประสิทธิภาพ",
  str_voice_1601811_19 = "เมื่อทุกอย่างเงียบลง คุณก็สามารถเคลียร์ใจของคุณได้",
  str_voice_1601811_20 = "ไม่ว่าฉันจะมีประสบการณ์มากเพียงใด ฉันก็จะรักดินแดนที่ฉันจากมาเสมอ",
  str_voice_1601811_21 = "Astra มีสถานที่ท่องเที่ยวมากมายที่ฉันยังไม่เคยเห็น เป็นสถานที่ที่มีมนต์ขลังอย่างแท้จริง",
  str_voice_1601811_22 = "แม้ว่าเราจะต้องเดินทางหลายพันไมล์ เราจะปกป้องภูเขาและแม่น้ำของหลงโจว!",
  str_voice_1601811_23 = "ที่ใดมีแสงสว่าง ที่นั้นย่อมมีความมืด",
  str_voice_1601811_24 = "แม้ว่า Lin Guildmaster จะดูทรงตัวในตอนนี้ แต่เขาต้องทนทุกข์ทรมานมากเมื่อเขายังเด็กเนื่องจากความประมาท",
  str_voice_1601811_25 = "Liqing แมวคิตตี้? ยุ่งกับเขาเป็นเรื่องสนุก บางทีฉันไม่ควรพูดแบบนั้นกับหมอของฉันจริงๆ...",
  str_voice_1601811_26 = "เครื่องลายครามที่ผลิตในหลงโจวมีความประณีต เป็นหนึ่งในสิ่งที่ฉันชอบ",
  str_voice_1601811_27 = "อาจเป็นเพราะประสบการณ์ของฉันในทะเล แต่การได้เห็นปลาทำให้ความทรงจำที่ไม่พึงประสงค์กลับคืนมา",
  str_voice_1601811_28 = "มันคือ... สิ่งที่น่าเกรงขาม",
  str_voice_1601811_29 = "ฉันเคยเป็น Zhong Xu แม่ทัพใหญ่แห่งจักรวรรดิ Zhao ใน Longzhou แต่ตอนนี้ฉันเป็นเพียงคนพเนจรโดดเดี่ยว อย่าพูดถึงอดีตเลย จากนี้ไป ฉันจะไปกับคุณ",
  str_voice_1601811_30 = "เปลวไฟลุกโชนอยู่ในใจฉัน",
  str_voice_1601811_31 = "พลังของฉันกลับคืนมาแล้ว",
  str_voice_1601811_32 = "ยอดเยี่ยม! สุดยอดจริงๆ!",
  str_voice_1601811_33 = "ความกล้าหาญ เหมือนกันเลย!",
  str_voice_1601811_34 = "ฉันรอมานาน",
  str_voice_1601811_35 = "พร้อมที่จะไป.",
  str_voice_1601811_36 = "ฉันรู้สึกท็อปฟอร์ม",
  str_voice_1601811_37 = "ตอนนี้! พินาศ!",
  str_voice_1601811_38 = "เปลวเพลิงจะมอดไหม้เป็นเถ้าถ่าน!",
  str_voice_1601811_39 = "Yixin, ถึงตาคุณแล้ว!",
  str_voice_1601811_40 = "สนามรบไร้ความปรานี",
  str_voice_1601811_41 = "ฉันจะทำตามความคาดหวังของคุณ",
  str_voice_1601811_42 = "ชัยชนะอยู่ใกล้แค่เอื้อม",
  str_voice_1601811_43 = "ที่ใดมีชีวิต ที่นั่นย่อมมีความหวัง อย่ายอมแพ้.",
  str_voice_1601811_44 = "ไม่ต้องกังวลเกี่ยวกับฉัน ฉันชอบที่นี่.",
  str_voice_1601811_45 = "ฉันซาบซึ้งในน้ำใจของคุณ เพื่อนหนุ่ม",
  str_voice_1601811_46 = "ฉันขอบคุณสำหรับความรอบคอบของคุณเพื่อนหนุ่ม",
  str_voice_1601811_47 = "ของขวัญที่หรูหราที่สุด คุณค่อนข้างใจกว้าง",
  str_voice_1601811_48 = "ฉันยอมรับด้วยความยินดีอย่างยิ่ง",
  str_voice_1601811_49 = "ฉันเคยต่อสู้ในแนวหน้าเพื่อนำเกียรติยศมาสู่ประเทศชาติ นำกองทหารของฉันไปทั่วทั้งทวีปเพื่อสงบศึก มองย้อนกลับไปฉันยังเด็กและเต็มไปด้วยชีวิตชีวา...",
  str_voice_1601811_50 = "ระหว่างทางไป Ji ฉันช่วยกองคาราวานตระกูล Lin ที่ถูกปล้นและได้รู้จักกับ Lin Guildmaster รู้จักกันมาสิบกว่าปีแล้ว",
  str_voice_1601811_51 = "เมื่อฉันออกจาก Yangjing ฉันไม่ได้นำสิ่งของติดตัวไปมากนัก มีเพียงแมว Dragon Li ตัวน้อยสามตัวนี้เท่านั้น ตราบใดที่ฉันยังมีความคิดเกี่ยวกับชาติของฉันอยู่ในใจ ฉันจะไม่ปรารถนาความพอใจในที่อื่นใดในโลก ไม่ว่าสิ่งนั้นจะยิ่งใหญ่เพียงใด",
  str_voice_1601811_52 = "Alchemy Stars",
  str_voice_1601811_53 = "สวัสดีเพื่อนหนุ่ม",
  str_voice_1601811_54 = "แสงแห่งรุ่งอรุณเริ่มทอแสง",
  str_voice_1601811_55 = "นี่คือช่วงเวลาที่ดวงอาทิตย์ส่องแสงเจิดจ้าที่สุด",
  str_voice_1601811_56 = "ดึกมากแล้วเพื่อนสาว",
  str_voice_1601811_57 = "ปีใหม่มาแล้ว ฉันขอให้คุณดี",
  str_voice_1601821_1 = "คุณต้องการที่จะรู้ว่าสิ่งที่อยู่ข้างหน้า? มันคือคลื่นใต้น้ำ แนวปะการังที่อันตราย สึนามิที่จะกลืนกินทุกสิ่ง แต่ฉันเลือกทางนี้เองและจะเดินตามไปให้สุดทาง",
  str_voice_1601821_2 = "การสร้างเรือไม่ใช่เรื่องง่าย ต้องอาศัยความร่วมมืออย่างเป็นระบบของอู่ต่อเรือ ท่าเรือ และผู้พิทักษ์ป่า คุณสั่งให้คนต่อสู้ซึ่งต้องมีการประสานงานระหว่างกลุ่มต่างๆ นั่นก็ไม่ใช่เรื่องง่ายเช่นกัน",
  str_voice_1601821_3 = "ไม่จำเป็นต้องทักทายซ้ำซาก ฉันไม่สนใจพวกเขา ฉันมาหาคุณเพื่อสร้างมิตรภาพ",
  str_voice_1601821_4 = "ทาน้ำมันพายแล้วเรือจะพายเร็วขึ้น ให้แผนที่การเดินเรือแก่นักเดินเรือ แล้วเรือก็จะหาทางไปได้เอง",
  str_voice_1601821_5 = "ฉันไม่รู้ว่าคุณมีรัฐธรรมนูญที่แข็งแกร่งเช่นนี้ น่าประทับใจที่ท่านไม่เมาเรือและอาเจียนในพายุรุนแรงเหมือนที่เจอเมื่อกี้ พรุ่งนี้จะพาไปแข่งเรือน่าจะตื่นเต้นกว่านี้ อืม? ทำไมคุณถึงวิ่งหนี?",
  str_voice_1601821_6 = "คุณได้รับบาดเจ็บ อืม ที่นั่น คุณคิดว่าฉันหนาวเกินไป? จากนั้นถอดเสื้อผ้าออก ฉันเพิ่งทำงานกลางแดดเสร็จ และมือของฉันก็อุ่น พวกมันร้อนพอที่จะช่วยถูครีมกับคุณได้",
  str_voice_1601821_7 = "ว่างเมื่อไหร่จะพาออกทะเลล่าวาฬมีเขาในตำนาน คุณต้องการที่จะไปตอนนี้? ไม่ ฉันต้องส่งเรือออกไปสำรวจล่วงหน้า ฉันจะโทรหาคุณเมื่อฉันจัดการเรียบร้อยแล้ว",
  str_voice_1601821_8 = "คุณปล่อยให้ปลาสัตว์เลี้ยงของฉันเป็นอิสระ? จากนั้นคุณสามารถแทนที่มันด้วยการเป็นสัตว์เลี้ยงตัวใหม่ของฉัน",
  str_voice_1601821_9 = "ฉันดูแปลกไปไหม? อาจเป็นเพราะฉันเพิ่งตำหนิผู้ใต้บังคับบัญชาหลายคนที่โง่เขลา อย่าไป คุณไม่ใช่ลูกน้องของฉัน! ไม่ต้องสนใจฉัน แค่... ยืนตรงนั้น อยู่เคียงข้างฉัน.",
  str_voice_1601821_10 = "เมื่อคุณขึ้นเรือของฉัน คุณต้องเชื่อฟังคำสั่งของฉัน หรือคุณจะเดินบนกระดาน",
  str_voice_1601821_11 = "พวกเขาบอกว่าหากคุณต้องการขอบคุณผู้อื่น คุณควรตอบแทนความกรุณาด้วยรอยยิ้ม ขอบคุณที่เชิญฉัน. *ยิ้ม*",
  str_voice_1601821_12 = "ใครๆ ก็บอกว่าทะเลนั้นปั่นป่วนและไร้ความปรานี แต่การเผชิญหน้ากับทะเลนั้นง่ายกว่าการเผชิญหน้ากับผู้คน",
  str_voice_1601821_13 = "แม้ว่าจะมีวิธีที่เร็วกว่านี้... อยากจับปลาใหญ่ต้องอดทน",
  str_voice_1601821_14 = "เมื่อเร็ว ๆ นี้คุณรู้สึกแย่เล็กน้อย คุณต้องการให้ฉันปลอบใจคุณไหม โธ่ อย่าเพิ่งน้อยใจไป เห็นได้ชัดว่าฉันถือว่าคุณเป็นเพื่อนของฉัน แต่ฉันไม่สามารถพาตัวเองไปพูดเรื่องน่าเบื่อเหล่านั้นได้",
  str_voice_1601821_15 = "ฉันขอให้คุณมีชีวิตยืนยาวเหมือนสัตว์ประหลาดในทะเล",
  str_voice_1601821_16 = "คุณเบื่อไหม? ฉันไม่",
  str_voice_1601821_17 = "อยากเห็นทะเลตอนเช้าไหม?",
  str_voice_1601821_18 = "ความงามของโลกเปรียบได้กับพระอาทิตย์ตกเหนือมหาสมุทร",
  str_voice_1601821_19 = "อย่าออกไปข้างนอกตอนกลางคืน หากคุณพบ Eclipsite คุณจะทำเสร็จแล้ว",
  str_voice_1601821_20 = "อาณาจักรของ Ji มีเงื่อนไขการขนส่งทางทะเลที่ไม่เหมือนใคร ด้วยเหตุนี้ เราจึงสามารถพัฒนาอุตสาหกรรมการค้าขั้นสูงได้",
  str_voice_1601821_21 = "Astra เป็นแหล่งรวมอาหารพิเศษที่ไม่เหมือนใครนับไม่ถ้วน ฉันเชื่อว่าทั้งสองทวีปจะได้รับประโยชน์จากการค้าและการแลกเปลี่ยนวัฒนธรรมอย่างสม่ำเสมอ",
  str_voice_1601821_22 = "การเดินทางรอบโลกและโต้ตอบกับนานาประเทศคือจุดประสงค์ของกิลด์ของเรา",
  str_voice_1601821_23 = "พวกมันน่าขยะแขยงพอๆ กับแนวปะการังที่บางที่สุด",
  str_voice_1601821_24 = "ฉันถูกรับเลี้ยงโดยผู้อาวุโสของตระกูลหลิน เขาเป็นที่ปรึกษาของฉันเช่นเดียวกับครอบครัวของฉัน สักวันหนึ่งฉันต้องแสดงให้เขาเห็นถึงความกตัญญูกตเวทีอย่างเต็มที่",
  str_voice_1601821_25 = "ครอบครัวของฉัน? แม่ตาย พ่อหนี คุณต้องการทราบอะไรอีก ฉันไม่ได้โกรธ. จริง ๆ ฉันไม่ ฉันสัญญา.",
  str_voice_1601821_26 = "ก๋วยเตี๋ยวหอยแม่น้ำ...อร่อย.",
  str_voice_1601821_27 = "ฉันไม่ชินกับอาหารหวานและมันเยิ้มหรือของแห้ง",
  str_voice_1601821_28 = "คุณคิดว่ายักษ์ใหญ่นี้สามารถแล่นในทะเลได้หรือไม่?",
  str_voice_1601821_29 = "ฉัน Mu Yuebai กัปตันของ Shadowind ถ้าคุณไม่ต้องการอะไร อย่ามารบกวนฉัน",
  str_voice_1601821_30 = "เหมือนปลาอยู่ในน้ำ",
  str_voice_1601821_31 = "ฟ้าใส เส้นทางชัดเจน",
  str_voice_1601821_32 = "ฉันยังทำได้ดีกว่านี้อีก",
  str_voice_1601821_33 = "ขอให้เราแล่นไปบนลมแรงและคลื่นแตก",
  str_voice_1601821_34 = "รับทราบ",
  str_voice_1601821_35 = "น้ำขึ้น",
  str_voice_1601821_36 = "กระแสน้ำแรง.",
  str_voice_1601821_37 = "ฝนตกหนัก กวาดเข้า!",
  str_voice_1601821_38 = "ทะเลนั้นไร้ขอบเขตและมีทุกอย่างอยู่ในมือ",
  str_voice_1601821_39 = "อยู่ในหลักสูตร",
  str_voice_1601821_40 = "ล้างโลกให้สะอาด",
  str_voice_1601821_41 = "ฉันจะไม่ทำให้ผิดหวัง",
  str_voice_1601821_42 = "พระจันทร์ขึ้นเหนือทะเลแล้ว",
  str_voice_1601821_43 = "ฉันไม่รู้จะปลอบใจคุณยังไง",
  str_voice_1601821_44 = "โครงสร้างของยักษ์ใหญ่นี้คล้ายกับของเรือ ขอให้ตั้งใจศึกษาให้ดี",
  str_voice_1601821_45 = "ทำไมของขวัญ? นี่เป็นพื้นฐาน",
  str_voice_1601821_46 = "ดีมาก. ขอขอบคุณ.",
  str_voice_1601821_47 = "อ๋อ... ไม่เป็นไร ฉันว่า",
  str_voice_1601821_48 = "ขอบคุณมาก. อันนี้ถูกใจผมมาก",
  str_voice_1601821_49 = "ฉันเกิดมาพร้อมกับหางอสรพิษ คนส่วนใหญ่รู้สึกกลัวเมื่อเห็น โอ้? ไม่ได้กลัว แต่แค่สงสัย?",
  str_voice_1601821_50 = "Ancestral Bone Dagger นี้มอบให้ฉันโดยผู้อาวุโสของตระกูล Lin สองครั้ง ครั้งแรกเมื่อฉันเกิดและอีกครั้งเมื่อพ่อของฉันจากไป",
  str_voice_1601821_51 = "นามสกุลของฉันคือ Lin แต่ต่อมาฉันเปลี่ยนเป็น Mu ทำไม อย่างไรก็ตาม ให้ฉันแสดง Shadowind ให้คุณดูก่อน ฉันปรับปรุงระบบพลังงานของมันเมื่อไม่นานมานี้...",
  str_voice_1601821_52 = "Alchemy Stars",
  str_voice_1601821_53 = "อากาศดีเหมาะแก่การล่องเรือ",
  str_voice_1601821_54 = "อยู่นี่ไง. ฉันจะไปทานอาหารเช้าตอนนี้ บาย.",
  str_voice_1601821_55 = "บ่ายนี้ร้อนจัง ฉันกำลังจะไปอาบน้ำ. บาย.",
  str_voice_1601821_56 = "ดึกแล้ว... ฉันไปนอนแล้ว บาย.",
  str_voice_1601821_57 = "สุขสันต์วันปีใหม่",
  str_voice_1501831_1 = "อย่ามาลูบหัวฉัน! หยาบคายกับรุ่นพี่ได้ยังไง!? ฉันอายุเท่าไหร่? อายุสิบสองปี... แต่ฉันยังเป็นรุ่นพี่เธอนะ!",
  str_voice_1501831_2 = "คุณยังคงเติบโต ใช้เวลานี้วันละครั้งเพื่อเสริมโภชนาการของคุณ เงิน? ฉันไม่สนใจเรื่องแบบนั้น! พูดเรื่องเงินอีกแล้วกูจะโกรธ!",
  str_voice_1501831_3 = "ลูกแมวตัวนี้? Tinytail ไม่ใช่แค่แมว แต่เป็นพี่ชายของฉัน เขาเกียจคร้านและตะกละ ดังนั้นเขาจึงไม่สามารถพัฒนาร่างเป็นออโรเรี่ยนได้หลังจากเวลานี้—อุ๊ย อุ๊ย อุ๊ย! โอเค ฉันจะไม่เรียกคุณด้วยชื่อเล่นของคุณ!",
  str_voice_1501831_4 = "ฉันรู้สึกเบามาก! ใช่! ตอนนี้ฉันกระโดดขึ้นไปบนเคาน์เตอร์ได้แล้ว มาดูกันว่าที่นี่มีอะไรบ้าง...",
  str_voice_1501831_5 = "วันนี้ฉันอ่านหนังสือใหม่ 5 เล่ม และจำทุกอย่างในนั้น ฉันฉลาดใช่มั้ย! อืม... แต่คุณก็ต้องขอบคุณสำหรับสิ่งนี้เช่นกัน",
  str_voice_1501831_6 = "ว้าว... อืม! ด้วยความกระตือรือร้นในการได้ยินและการมองเห็นของฉัน จู่ๆ ฉันก็รู้สึกเหมือนได้ลิ้มรสสมุนไพรทุกชนิดในคราวเดียว และเขียนใบสั่งยาใหม่นับไม่ถ้วน! คุณต้องทดสอบยาของฉันในภายหลัง!",
  str_voice_1501831_7 = "ฉันพบผลไม้ที่อร่อยมากเมื่อวันก่อน คุณลองดูก็ได้... อา Tinytail! ทำไมกินหมด!?",
  str_voice_1501831_8 = "อยากสัมผัสหางของฉันไหม อืม... ฉันว่าไม่เป็นไร... ฉันจะยกเว้นให้นายเท่านั้น!",
  str_voice_1501831_9 = "จริง ๆ หลายคนไม่ชอบพวกเราที่เป็นศัตรูกัน พวกเขาคิดว่าเราป่าเถื่อนและต่ำทราม แต่, PlayerNameเมื่อฉันอยู่กับคุณ... ไม่ ไม่ ไม่! ช่างเถอะ!",
  str_voice_1501831_10 = "ฮึ มันน่าเบื่อที่ต้องอยู่ข้างในตลอดเวลา! พาฉันออกไปข้างนอกเพื่อหาสมุนไพรใหม่!",
  str_voice_1501831_11 = "ฉันอยู่นี่! มีอะไรผิดปกติ? ฮะ? คุณไม่ป่วยเหรอ ฉันเป็นหมอที่ยุ่งมาก! อย่าโทรหาฉันโดยไม่มีเหตุผล... อืม น่าจะพอรับได้นะ...",
  str_voice_1501831_12 = "ทำไมคุณถึงกินอาหารขยะนี้อีกครั้ง ฉันจะเอามันออกไป! ...อร่อยมาก! ฉันเป็นผู้ใหญ่แล้ว! ไม่เป็นไรสำหรับฉันที่จะกัดสองสามครั้ง!",
  str_voice_1501831_13 = "ฉันมีความรู้มากใช่ไหม ยาของฉันได้ผลใช่ไหม คุณรู้เรื่องของคุณ! อะแฮ่ม... ชื่อเสียง ความมั่งคั่ง ยศฐาบรรดาศักดิ์นั้นไม่สำคัญ... แต่ยกย่องข้าอีกหน่อยก็ไม่เสียหาย",
  str_voice_1501831_14 = "สงสัยเกี่ยวกับขนาดสมุนไพรของฉัน? คุณไม่สามารถสัมผัสมันได้ทุกเมื่อที่คุณต้องการ! เป็นของสำคัญในการจ่ายยาและต้องถูกต้องและสะอาดตลอดเวลา",
  str_voice_1501831_15 = "สุขสันต์วันเกิด! วันนี้คุณสามารถลูบท้องของ Tinytail ได้ ฉันให้คุณอนุญาตแทนเขา",
  str_voice_1501831_16 = "อา บ่ายนี้แดดแรงมาก ฉันง่วง...",
  str_voice_1501831_17 = "ยุ่ง ยุ่ง ยุ่ง... อยู่นี่ไง! โปรดช่วยฉันย้ายสมุนไพรไปที่นั่น อย่าขี้เกียจ!",
  str_voice_1501831_18 = "ช่วงนี้ขยันทำงาน..แต่อย่านอนดึกนะ",
  str_voice_1501831_19 = "ว้าว! ทำไมยังขึ้นอยู่!? ให้ฉันช่วยทำงานให้เสร็จ เข้านอนตอนนี้!",
  str_voice_1501831_20 = "ดังที่อาจารย์บุกล่าวไว้ว่า \"อย่าวางใจหมอที่ขาดความเมตตากรุณา และอย่าวางใจหมอที่ขาดความสัตย์ เพราะขาดความสัตย์จริง ก็ไม่มีความน่าเชื่อถือ\"",
  str_voice_1501831_21 = "ผู้คนในลูโมโปลิสแต่งตัวประหลาดมาก ราวกับว่าพวกเขาทั้งหมดเปล่งประกายระยิบระยับ",
  str_voice_1501831_22 = "รักษาคนเจ็บ ช่วยชีวิตคน!",
  str_voice_1501831_23 = "Eclipsites ในน้ำนั้นน่ากลัวกว่าบนพื้นดินมาก! เหตุการณ์นั้นทำให้ฉันกลัวมาก ฉันชอกช้ำ...",
  str_voice_1501831_24 = "Zhong Xu เป็นเพียงคนแก่ที่มีหมอกหนา แต่เชื่อฉันเถอะ ข้างนอกเขาอดทน ข้างในอบอุ่น",
  str_voice_1501831_25 = "อาจารย์ไม่เห็นด้วยกับการที่ฉันไปบอกทุกคนว่าฉันเห็น... แต่ฉันเป็นลูกศิษย์ของ Bucunzi! หมอที่เก่งที่สุดในโลก!",
  str_voice_1501831_26 = "นั่นข้าวฉันได้กลิ่นเหรอ...? อืม ขอฉันดูหน่อยสิ!",
  str_voice_1501831_27 = "มีเพียงเด็กน้อยเท่านั้นที่มีอาหารที่พวกเขาเกลียด ว-นี่มันอะไรกันเนี่ย? คุณเอาพริกเขียวจานหนึ่งมาให้ฉันทำไม!?",
  str_voice_1501831_28 = "ฉันจะรักษาโซรอซได้อย่างไร ช่างกล.... ระบบ... อืม... ฉันไม่เข้าใจสิ่งนี้เลย!",
  str_voice_1501831_29 = "ฮึ่ม! คุณต้องมีพรสวรรค์บางอย่างเพื่อหาตัวเองเป็นหมอที่มีชื่อเสียงเช่นฉัน ฉันชื่อ Liqing ฉันมาที่นี่เพื่อรักษาอาการป่วยของคุณ!",
  str_voice_1501831_30 = "ฉันโตขึ้นอีกหน่อยไหม...?",
  str_voice_1501831_31 = "ฮะ? ประสาทรับกลิ่นของฉันดีขึ้น!",
  str_voice_1501831_32 = "ต่อมรับรสของฉันรุนแรงขึ้น!",
  str_voice_1501831_33 = "ฉันคิดว่าฉันยังสูงขึ้นเรื่อยๆ!",
  str_voice_1501831_34 = "ให้ฉันจัดการเอง!",
  str_voice_1501831_35 = "คู่ที่สมบูรณ์แบบ!",
  str_voice_1501831_36 = "การรักษาขั้นสุด!",
  str_voice_1501831_37 = "กลืนสิ่งนี้!",
  str_voice_1501831_38 = "สิ่งที่ดีที่สุดจากธรรมชาติเท่านั้น!",
  str_voice_1501831_39 = "จุดมุ่งหมาย-!",
  str_voice_1501831_40 = "กินยาของคุณ!",
  str_voice_1501831_41 = "ติดตามกันนะครับทุกคน!",
  str_voice_1501831_42 = "ฮึ่ม! หลีกเลี่ยงไม่ได้!",
  str_voice_1501831_43 = "โอ๊ย โอ๊ย โอ๊ย...",
  str_voice_1501831_44 = "อ๊ะ! คุณกลัวฉัน!",
  str_voice_1501831_45 = "มันอร่อยไหม?",
  str_voice_1501831_46 = "คุณมีรสนิยมดี!",
  str_voice_1501831_47 = "นี่สำหรับฉันอีกแล้วเหรอ? H-น่าอายจัง...",
  str_voice_1501831_48 = "คุณรู้ได้อย่างไรว่าฉันชอบสิ่งนี้ ... ?",
  str_voice_1501831_49 = "ฉันกินยาของมาสเตอร์บูโดยไม่ได้ตั้งใจ ซึ่งแตกต่างจากปีศาจทั่วไป และจากนั้นฉันก็กลายเป็นออโรเรียนโดยบังเอิญ ฉันโชคดี ฉันอาจตายได้!",
  str_voice_1501831_50 = "เพื่อเป็นค่ายาที่กินเข้าไป ฉันจึงมาเป็นลูกศิษย์ของอาจารย์ แต่ฉันก็ค่อยๆ เริ่มเข้าใจความสุขและความรับผิดชอบที่มาพร้อมกับการเป็นหมอ",
  str_voice_1501831_51 = "แต่ช่วงเวลาดีๆ นั้นอยู่ได้ไม่นาน ความจริงของการแอบลงจากภูเขาของฉันก็ถูกเปิดเผยในไม่ช้า อาจารย์อาจใจร้ายเมื่อตีสอนลูกศิษย์! แต่ฉันเองก็มีความฝันที่ไม่อาจละทิ้งได้",
  str_voice_1501831_52 = "Alchemy Stars!",
  str_voice_1501831_53 = "อ๊ะ!",
  str_voice_1501831_54 = "แผนของวันเริ่มต้นตั้งแต่รุ่งสาง!",
  str_voice_1501831_55 = "ไม่มีอะไรรับประกันวันที่มีประสิทธิผลเหมือนท้องอิ่ม!",
  str_voice_1501831_56 = "ย่าาาา...เลยเวลานอนไปแล้ว...",
  str_voice_1501831_57 = "สวัสดีปีใหม่! คุณควรเติบโตอย่างแข็งแกร่งต่อไปและเป็นผู้ใหญ่และน่าเชื่อถือเหมือนฉัน!",
  str_voice_1601841_1 = "เด็กอีกคนกำลังตามหาฉันอยู่เหรอ? ไม่ว่าพวกเขาต้องการอะไร บอกพวกเขาว่าพวกเขาอยู่ตามลำพัง ไม่ต้องกังวล ฉันเชื่อใจพวกเขา ไม่ใช่เรื่องใหญ่ ไม่ต้องเครียด!",
  str_voice_1601841_2 = "...ห๊ะ? เมื่อกี้คืออะไร? ฉันหลงทางในหนังสือเล่มนี้และไม่ได้ยินคุณ เอาเลย ฉันจะฟังคุณในขณะที่อ่าน เอ่อ... ใช่... ฉันสัญญาว่าฉันจะฟัง",
  str_voice_1601841_3 = "คุณเตรียมทรัพยากรทั้งหมดเหล่านี้ไว้ที่นี่เพื่อให้เราใช้ฟรีหรือไม่? คุณเป็นคนดีจริงๆ Caelesite ตัวน้อย... หรือบางทีฉันควรจะพูดว่าพวกเราทุกคนชอบที่จะเอาเปรียบคุณมากเกินไป",
  str_voice_1601841_4 = "ฉันชอบประสบการณ์ใหม่ๆ การเดินทาง การอ่าน การสำรวจสิ่งที่ไม่รู้จัก ปรัชญา - ประสบการณ์ที่สดใหม่และกระตุ้นทำให้ฉันรู้สึกมีชีวิตชีวา ในทางกลับกัน ความเบื่อหน่ายก็เหมือนความตายที่มีชีวิต",
  str_voice_1601841_5 = "ฉันไปที่ Eraveil ครั้งหนึ่งก่อนที่คุณจะเริ่มสร้างมันขึ้นมาใหม่ ความสับสน ความอ้างว้าง ความเงียบงัน... การทำลายล้าง มันทำให้ฉันสงสัย—อะไรคือความก้าวหน้า?",
  str_voice_1601841_6 = "งูหลามศักดิ์สิทธิ์ทำให้ฉันรู้สึกแปลกๆ เมื่อเร็วๆ นี้ จะอธิบายยังไงดี...? อืม. ให้ฉันจริงจังอย่างไม่เคยมีมาก่อนสักครั้ง เป็นความรู้สึกว่าการเดินทางมาที่นี่ของเราไม่ได้สูญเปล่า",
  str_voice_1601841_7 = "ฉันขอขอบคุณทัศนคติที่เป็นกลางของคุณและคุณไม่สนับสนุนอุดมการณ์ของฝ่ายใดฝ่ายหนึ่ง ความโกลาหล ชนชั้น เผด็จการ อนุรักษนิยม... ไม่จำเป็นต้องบุ่มบ่ามหลอกตัวเอง",
  str_voice_1601841_8 = "คุณไม่จำเป็นต้องมีส่วนร่วมในละครตลอดเวลา ลองนั่งเอนหลังและสนุกกับการดูมันแฉกับฉัน คุณไม่รู้หรอกว่าละครแห่งชีวิตจะน่าขบขันขนาดไหน ฉันรู้ว่าคุณจะต้องรักมันอย่างแน่นอน",
  str_voice_1601841_9 = "มาบอกฉันถึงสิ่งที่คุณเห็นและได้ยินเมื่อเร็วๆนี้ ช่วงนี้คุณไม่ได้ทำอะไรเลย? ชีวิตเคยน่าเบื่อ? อย่าพูดอย่างนั้น ฉันชอบเกร็ดเล็กเกร็ดน้อยของคุณ",
  str_voice_1601841_10 = "อืม... ฉันเบื่อที่จะอ่านหนังสือ พาฉันไปทำอะไรที่น่าสนใจ",
  str_voice_1601841_11 = "คุณต้องการให้ฉันอยู่ที่นี่ไหม ใช้ได้. แล้วจะมาอ่านต่อ...เวิร์คไหม? ใช่ ใช่ ฉันจะคอยจับตาดูสิ่งต่างๆ",
  str_voice_1601841_12 = "ฉันดูเหมือนไม่ใช่คนจาก Rediesel Wrench เหรอ? ฉันเห็นด้วยกับคุณที่นั่น ฉันยังไม่พบฝ่ายที่เหมาะกับฉันอย่างแท้จริง และฉันชอบแบบนั้น",
  str_voice_1601841_13 = "บางครั้งฉันมีลิ้นแหลมคม? อืม... ใครจะรู้? แหลมหรือเบา เสียงของฉันจะดังซ้ำก็ต่อเมื่อมีเสียงสะท้อนในห้อง ผู้ฟังระวัง...",
  str_voice_1601841_14 = "ความสัมพันธ์... ฉันไม่ค่อยสนใจพวกเขาเท่าไหร่ แต่ฉันรู้สึกเศร้าเล็กน้อยเมื่อเจอจดหมายที่ไม่มีผู้รับที่สามารถโยนทิ้งไปได้",
  str_voice_1601841_15 = "เป็นวันเกิดของคุณ ดังนั้น... ฉันขอให้คุณปราศจากความสับสนในอนาคต",
  str_voice_1601841_16 = "คุณขยันมาก ให้ฉันสังเกตวิธีการทำงานของคุณ",
  str_voice_1601841_17 = "สวัสดีตอนเช้า. ฮอว์คเพิ่งกลับมา หากมีข่าวอะไรที่น่าสนใจ ฉันจะนำมาแบ่งปันให้คุณทราบอย่างแน่นอน",
  str_voice_1601841_18 = "สวัสดีตอนเย็น. ผ่านไปอีกหนึ่งวันในพริบตา เวลาผ่านไปไวแค่ไหน",
  str_voice_1601841_19 = "...ห๊ะ? คาเลสไทต์น้อย เจ้ายังอยู่ไหม? จังหวะเหมาะ! ในขณะที่ทุกคนหลับใหล เรามามีเวลาส่วนตัวกันเถอะ",
  str_voice_1601841_20 = "เมื่อเทียบกับกลุ่มอื่น ๆ Courier Union เป็นสถานที่ที่ค่อนข้างอบอุ่น",
  str_voice_1601841_21 = "บางครั้งฉันอยากให้ผู้คนจาก Rediesel Wrench คิดก่อนที่จะลงมือทำ",
  str_voice_1601841_22 = "Courier Union ส่งมอบ... เกือบตลอดเวลา",
  str_voice_1601841_23 = "Eclipsites... พวกมันมาจากไหนและมีจุดประสงค์อะไร?",
  str_voice_1601841_24 = "Kya เป็นสาวน้อยที่เรียบง่ายและน่ารัก ฉันชอบเธอมาก! และเธอทำได้ดีมากในงานของเธอ",
  str_voice_1601841_25 = "ไม่ต้องกังวล. ถ้าพรุ่งนี้ท้องฟ้าจะถล่ม ตราบใดที่นาร็อกเซลยังยืนอยู่ เราก็ไม่เป็นไร",
  str_voice_1601841_26 = "ฉันชอบอ่านหนังสือในขณะที่เคี้ยวขนมตับบดแสนอร่อย",
  str_voice_1601841_27 = "อย่าใช้ชีวิตไปกับงานที่น่าเบื่อ ถ้าคุณทำ คุณจะกลายเป็นคนน่าเบื่อไปเอง",
  str_voice_1601841_28 = "Colossus นี้แตกต่างจากใน Rediesel Wrench วัฒนธรรม Caelestite นั้นลึกซึ้งสวยงามจริงๆ...",
  str_voice_1601841_29 = "ฉันชื่อเยรียา คุณสามารถตัดพิธีการกับฉัน คุณกังวลเกี่ยวกับสหายทั้งสองของฉันหรือไม่? ไม่ต้องกลัว—เหมือนฉัน พวกเขาชอบสำรวจสิ่งใหม่ๆ มากกว่าการต่อสู้",
  str_voice_1601841_30 = "อืม มันรู้สึกดีมาก",
  str_voice_1601841_31 = "ฉันดูเหมือนจะได้รับที่แข็งแกร่งขึ้น",
  str_voice_1601841_32 = "จิตใจภายในของฉันคือเซน",
  str_voice_1601841_33 = "ฉันรู้สึกถึงความรู้ที่หลั่งไหลเข้ามาในจิตใจของฉัน",
  str_voice_1601841_34 = "ได้สิ...",
  str_voice_1601841_35 = "กริมัวร์!",
  str_voice_1601841_36 = "เมื่อไหร่ก็ตามที่คุณพร้อม",
  str_voice_1601841_37 = "ลำโพง!",
  str_voice_1601841_38 = "แสงลวงตา!",
  str_voice_1601841_39 = "เหยี่ยว!",
  str_voice_1601841_40 = "หลามศักดิ์สิทธิ์!",
  str_voice_1601841_41 = "ฉัน? กัปตัน?",
  str_voice_1601841_42 = "นี่มันน่าเบื่อ",
  str_voice_1601841_43 = "ทีนี้ก็น่าสนใจ...",
  str_voice_1601841_44 = "อืม... มันสามารถทำอะไรที่น่าสนใจได้เหรอ?",
  str_voice_1601841_45 = "ขอบคุณ",
  str_voice_1601841_46 = "ใช้ได้ ใช้ได้",
  str_voice_1601841_47 = "ขอฉันดูหน่อย!",
  str_voice_1601841_48 = "ค่อนข้างพิเศษจริงๆ...อยากได้อะไรตอบแทน?",
  str_voice_1601841_49 = "ฉันเกิดใน Rediesel Wrench และพ่อแม่ของฉันเป็น... ฉันรู้สึกขอบคุณสำหรับความอดทนของพวกเขาแม้ว่าบุคลิกของฉันจะตรงกันข้ามก็ตาม",
  str_voice_1601841_50 = "พรสวรรค์ด้าน Luminatics ของฉันเกิดขึ้นโดยบังเอิญ พ่อแม่ของฉันเริ่มรู้ว่าการติดอยู่ในทะเลทรายกำลังรั้งฉันไว้ ดังนั้นเมื่อถึงเวลา ฉันจึงออกเดินทาง",
  str_voice_1601841_51 = "ตอนแรกฉันชอบการเดินทาง แต่ยิ่งเห็นก็ยิ่งสับสน... ฉันเริ่มสงสัยว่า \"ชีวิตนี้เกิดมาเพื่ออะไร\"",
  str_voice_1601841_52 = "Alchemy Stars",
  str_voice_1601841_53 = "สวัสดี",
  str_voice_1601841_54 = "เป็นเวลาที่เหมาะสำหรับการอ่านหนังสือ",
  str_voice_1601841_55 = "พักผ่อนหน่อยจ้า",
  str_voice_1601841_56 = "พระจันทร์ดับ.",
  str_voice_1601841_57 = "ความรู้ไม่เพียงแค่สะสมตามธรรมชาติตามอายุเท่านั้น อย่าลืมว่าเส้นทางที่คุณเดินอยู่ภายใต้สองเท้าของคุณเอง",
  str_voice_1501851_1 = "คุณกำลังถืออะไรอยู่? มันดูพิเศษมาก... อะแฮ่ม แต่ในฐานะคนส่งของที่เดินทางไปทั่วทวีป ฉันเห็นหมดแล้ว",
  str_voice_1501851_2 = "ถนนสายนั้นอยู่ใกล้มาก แต่ไม่มีบันทึกบนแผนที่สหภาพ ดังนั้นฉันจึงใช้ไม่ได้ อืม... แต่เราวิ่งเป็นวงกลม บางทีฉันควรจะฟังคุณเพียงครั้งเดียว",
  str_voice_1501851_3 = "นี่จัดตลาดนัดประจำปีเหรอ? อยากดูจริงๆ... ไม่สิ! ฉันต้องส่งจดหมายเหล่านี้โดยไม่ชักช้าแม้แต่นิดเดียว!",
  str_voice_1501851_4 = "ฉันเป็นสมาชิกของ Courier Union ซึ่งหมายความว่าฉันจะยืนด้วยสองขาของตัวเองเสมอ แม้ว่าฉันจะล้ม... อุ๊ย! ไม่นะ อย่าช่วยฉันเลย... ฉันลุกเองได้",
  str_voice_1501851_5 = "จากมุมมองทางประวัติศาสตร์ ซากปรักหักพังก็เหมือนกับเรือขนส่งที่ส่งข้อมูลเกี่ยวกับอารยธรรมและวัฒนธรรมโบราณมาให้เรา อย่าเมินฉัน! ฉันอ่านหนังสือขนาดใหญ่พอสมควรแล้ว",
  str_voice_1501851_6 = "ฉันได้ยินมาว่าก่อนที่จะก่อตั้ง Courier Union ชาว Aurorians ส่งไปรษณีย์ด้วยการขี่ม้าหรือวิ่ง มันคงเป็นเรื่องยากมาก...",
  str_voice_1501851_7 = "ปลากระป๋องเรดดีเซลผัดพริกเกลือ ? คนกินกันจริงหรือ!? ฉันจะไม่อย่างแน่นอน! คุณแนะนำเป็นอย่างยิ่ง? อืม... ฉันว่าจะลองกัดดูสักครั้ง...",
  str_voice_1501851_8 = "ถ้ามีอะไรดีๆ เกิดขึ้นกับฉัน ฉันจะเขียนถึงคุณได้ไหม ฉันอยากส่งรอยยิ้มบนใบหน้าไปให้นายนะ ฮิฮิ",
  str_voice_1501851_9 = "การเขียนเป็นรูปแบบการสื่อสารที่โรแมนติกมาก งั้น... คุณช่วยเขียนจดหมายถึงฉันได้ไหม คุณสามารถเขียนอะไรก็ได้ที่คุณชอบ",
  str_voice_1501851_10 = "ฉันหวังว่าฉันจะมีความทรงจำที่สมบูรณ์แบบ... ถ้าฉันทำได้ ฉันจะไม่ทำผิดพลาดโง่ๆ วันนี้ฉันไม่ได้ส่งของบางอย่างไปยังที่อยู่ผิด! ฉันหมายถึง ฉันได้รับจดหมายคืนก่อนที่จะสายเกินไป!",
  str_voice_1501851_11 = "ข่าวใดที่คุณต้องการให้ฉันส่งต่อ? ฉันจะส่งตรงเวลา!",
  str_voice_1501851_12 = "ส่งจดหมายของคุณมาให้ฉัน และวางใจได้ ฉันจะไม่ทำหาย! แต่จดหมายของคุณ... ไม่ ฉันจะไม่แอบดูจริงๆ... อืม...",
  str_voice_1501851_13 = "ฉันอยู่ในอันดับสุดท้ายของการจัดอันดับการจัดส่งของเดือนนี้... PlayerName, คุณต้องการส่งจดหมายหรือไม่? ฉันจะจ่ายค่าไปรษณีย์ให้ด้วย ขอแค่ให้ฉัน!",
  str_voice_1501851_14 = "แผนที่สหภาพบอกให้ตรงไป แต่มีกำแพงอยู่ข้างหน้าและถนนทางซ้าย ฉันควรทำอย่างไรดี? ฉันสามารถ... ปีนข้ามกำแพง?",
  str_voice_1501851_15 = "สุขสันต์วันเกิด! ให้ฉันส่งความปรารถนาดีและของขวัญทั้งหมดของคุณเป็นการส่วนตัว!",
  str_voice_1501851_16 = "ฉันนำคำทักทายจากภูเขาอันไกลโพ้นและสายลมอ่อนๆ",
  str_voice_1501851_17 = "ต้องการส่งจดหมายกับฉันไหม",
  str_voice_1501851_18 = "การได้รับจดหมายจากเพื่อนที่ไม่ได้เจอกันนานจะทำให้คุณมีความสุขไหม?",
  str_voice_1501851_19 = "โปรดให้ฉันส่งดวงดาวที่สวยงามไปสู่ความฝันของคุณ",
  str_voice_1501851_20 = "Courier Union เป็นองค์กรที่ยอดเยี่ยมและเป็นสะพานเชื่อมการสื่อสารที่สำคัญสำหรับผู้คน",
  str_voice_1501851_21 = "แต่ละสถานที่มีเอกลักษณ์เฉพาะของตัวเอง ฉันหวังว่าวันหนึ่งจะสำรวจทุก ๆ ตารางนิ้วของทั้งทวีป",
  str_voice_1501851_22 = "Courier Union—ปลอดภัย ตรงเวลา และเป็นความลับ",
  str_voice_1501851_23 = "แม้ว่า Eclipsites ต้องการส่งจดหมาย ฉันก็จะไม่ส่งไปให้พวกเขา",
  str_voice_1501851_24 = "ฉันไม่รู้ว่าคนอย่าง Dove เข้ามาใน Courier Union ได้อย่างไร... ทุกครั้งที่ฉันเห็นเธอ เธอเดินเตร่ไปรอบๆ",
  str_voice_1501851_25 = "Naroxel เป็นผู้อาวุโสและผู้จัดการที่น่านับถือ เธอเป็นแบบอย่างของฉัน!",
  str_voice_1501851_26 = "การตรงต่อเวลาเป็นคุณธรรมที่ยิ่งใหญ่ที่สุด",
  str_voice_1501851_27 = "ฮึ่ม... สายอีกแล้ว... อย่าเป็นอย่างนั้นได้ไหม?",
  str_voice_1501851_28 = "มันไม่ง่ายเลยที่จะส่งจดหมายมาที่นี่!",
  str_voice_1501851_29 = "สวัสดี! Courier Kya นำจดหมายล่าสุดของคุณมาให้คุณแล้ว! กรุณาตรวจสอบอย่างระมัดระวัง!",
  str_voice_1501851_30 = "ข้อความที่ได้รับ.",
  str_voice_1501851_31 = "ต้องวิ่งให้เร็วกว่านี้!",
  str_voice_1501851_32 = "ฉันเห็นทั้งหมด ฉันได้ยินทั้งหมด",
  str_voice_1501851_33 = "ส่งของสำเร็จอีกราย!",
  str_voice_1501851_34 = "อยู่สิ!",
  str_voice_1501851_35 = "ฉันพร้อม",
  str_voice_1501851_36 = "กำลังรอคำแนะนำ",
  str_voice_1501851_37 = "ส่งทางอากาศ!",
  str_voice_1501851_38 = "คุณได้รับจดหมาย!",
  str_voice_1501851_39 = "อย่าลืมลงชื่อ!",
  str_voice_1501851_40 = "โจมตีส่ง!",
  str_voice_1501851_41 = "ฉันจะจัดการเรื่องนี้!",
  str_voice_1501851_42 = "ฉันต้องการส่งความสุขนี้ให้กับทุกคน!",
  str_voice_1501851_43 = "*สูดจมูก* ฉันหวังว่าจะไม่มีใครรู้เรื่องนี้",
  str_voice_1501851_44 = "ตรวจดูแผนที่...ต้องจดจำทุกตารางนิ้วของสิ่งนี้",
  str_voice_1501851_45 = "เอิ่ม...ขอบคุณครับ",
  str_voice_1501851_46 = "ฉันขอได้ไหม ฉันชอบมันมาก!",
  str_voice_1501851_47 = "เซ็น!",
  str_voice_1501851_48 = "ช่างเป็นของขวัญที่ยอดเยี่ยม! ขอบคุณมาก!",
  str_voice_1501851_49 = "ฉันมาจากหมู่บ้านห่างไกลชื่อ Faar ที่... ก็... ไกลจนแทบไม่มีใครมาเยี่ยม เมื่อฉันยังเป็นเด็ก โลกนี้กว้างใหญ่เท่าฟาร์ในสายตาของฉัน",
  str_voice_1501851_50 = "มรกตเป็นครูของฉัน เธอเป็นแรงบันดาลใจให้ฉันเข้าร่วม Courier Union และกลายเป็นผู้จัดส่ง",
  str_voice_1501851_51 = "ประสบการณ์ที่น่าจดจำที่สุดของฉันจนถึงตอนนี้... คงต้องเป็นตอนที่ฉันเจอเด็กกลุ่มหนึ่งซึ่งล้อมรอบด้วย Eclipsites ขณะที่ฉันกำลังส่งของ!",
  str_voice_1501851_52 = "Alchemy Stars",
  str_voice_1501851_53 = "ดิงดอง!",
  str_voice_1501851_54 = "เป็นเช้าที่สดใสและสวยงาม",
  str_voice_1501851_55 = "ทำไมคุณไม่พักผ่อนในช่วงบ่ายนี้",
  str_voice_1501851_56 = "จดเหตุการณ์วันนี้ก่อนเข้านอน",
  str_voice_1501851_57 = "ปีใหม่เป็นช่วงเวลาที่ยุ่งที่สุดสำหรับฉัน แต่ฉันก็มีความสุขเช่นกันที่ได้ส่งคำอวยพรจากทุกคนถึงพวกเขา!",
  str_voice_1601861_1 = "ช่างเป็นวันที่แสนดี! ฉันจะออกไปเดินเล่นและงีบหลับเมื่อฉันกลับมา แต่เก้าอี้นั่งเล่นนี้สบายเกินไป อืม ฉันจะข้ามการเดินเล่นและไปงีบทันที",
  str_voice_1601861_2 = "ฉันต้องทำงานให้เสร็จอย่างมีประสิทธิภาพในขณะที่ฉันตื่นอยู่",
  str_voice_1601861_3 = "ต้องการทราบความลับหรือไม่? ฉันถนัดซ้าย แต่ฉันมักจะใช้มือขวาทุกครั้งที่ทำได้เพื่อหลีกเลี่ยงการทำร้ายใครโดยไม่ตั้งใจ",
  str_voice_1601861_4 = "ฉันรู้สึกมีพลัง! ฉันสงสัยว่าเป็นเพราะฉันโตขึ้นหรือเปล่า",
  str_voice_1601861_5 = "งานที่ Hall of Justice นั้นยาก แต่ฉันทำได้ดีกว่าที่เคยเป็นมาก ท้ายที่สุด ฉันจะปล่อยให้ตัวเองเป็นภาระของเพื่อนร่วมงานไม่ได้ ได้ไหม?",
  str_voice_1601861_6 = "หัตถ์เทวะมีพลังมากยิ่งขึ้น ฉันต้องระมัดระวังมากขึ้นเมื่อใช้มือซ้าย",
  str_voice_1601861_7 = "คุณเป็นคนใจดีมาก PlayerName. คุณจะบอกฉันถ้าคุณต้องการอะไรใช่ไหม",
  str_voice_1601861_8 = "โอ้ คุณอยากลองเก้าอี้เลานจ์ของฉันไหม ครอบครัวของฉันสร้างมันขึ้นมาเพื่อฉัน มันนุ่มและสบายมาก",
  str_voice_1601861_9 = "ฉันดีใจที่ได้รู้จักคุณ PlayerName. และในฐานะที่คุณเป็นเพื่อนที่ฉันไว้ใจ ครอบครัวแคมป์เบลจะคอยช่วยเหลือคุณเสมอ",
  str_voice_1601861_10 = "หากคุณเคยเบื่อ ลองงีบหลับเพื่อฆ่าเวลา",
  str_voice_1601861_11 = "คุณไม่กลัวฉันเผลอหลับไปกระทันหันเหรอ?",
  str_voice_1601861_12 = "ฉันรักอาหารหวาน แต่นอนไม่หลับถ้าฉันมีมากเกินไป คุณก็อย่าลืมดูปริมาณน้ำตาลของคุณด้วย คุณไม่ต้องการที่จะจบลงด้วยการเป็น Caelesite ขนาดใหญ่พิเศษ",
  str_voice_1601861_13 = "ฮะ? สมุดบันทึกของฉันอยู่ที่ไหน ฉันมักจะบันทึกเวลาที่ฉันตื่นขึ้นทุกวัน มันช่วยฉันมากปัญหา",
  str_voice_1601861_14 = "ความฝันของฉันอยู่ได้ไม่นาน แต่ฉันจำมันได้ชัดเจนเสมอ ฉันจะจดไว้ในสมุดถ้าพวกเขาน่าสนใจพอ",
  str_voice_1601861_15 = "สุขสันต์วันเกิด, PlayerName.",
  str_voice_1601861_16 = "ดีใจที่ได้เจอนะ",
  str_voice_1601861_17 = "เป็นเรื่องดีที่ได้เห็นคุณเป็นสิ่งแรกหลังจากตื่นนอน",
  str_voice_1601861_18 = "ฉันชอบช่วงเวลาหลังพระอาทิตย์ตกดิน เป็นเวลาที่เหมาะสมที่สุดที่จะเพลิดเพลินไปกับความเงียบสงบ",
  str_voice_1601861_19 = "ดึกมากแล้ว... ปกติเวลานี้ผมคงจะหลับ คุณจะทำอะไร?",
  str_voice_1601861_20 = "ฉันเชื่อว่าขนบธรรมเนียมและประเพณีของ Lumopolis จะสืบทอดต่อไปหลายชั่วอายุคน",
  str_voice_1601861_21 = "ชีวิตของสมาชิก Rediesel Wrench เหมือนกับบางอย่างจากหน้าเรื่องราวการผจญภัยใช่ไหม?",
  str_voice_1601861_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1601861_23 = "ฉันเคยเจอ Eclipsite ตัวเล็กน่ารักไม่มีพิษมีภัยมาก่อน ดูเหมือนว่าเขาจะเป็นหนึ่งในคนพิเศษ",
  str_voice_1601861_24 = "เลย์... ฉันขอบคุณเขามาก คนอื่นรำคาญฉันเพราะสภาพของฉัน แต่เขาช่วยฉันได้มาก",
  str_voice_1601861_25 = "ดูเหมือนมาติเยอจะคิดว่าฉันทำให้คนอื่นเดือดร้อน แต่ฉันก็จะทำงานหนักต่อไป",
  str_voice_1601861_26 = "ฉันมีงานอดิเรกอะไร...ก็ฉันชอบอ่านหนังสือ ความลึกลับโดยเฉพาะ",
  str_voice_1601861_27 = "ฉันเกลียดการถูกปลุกให้ตื่นจากการหลับใหล หมายความว่าต้องหาเวลานอนให้ทัน",
  str_voice_1601861_28 = "ช่างใหญ่โตมโหฬารเสียนี่กระไร... ข้าคิดว่านี่เป็นเพียงสิ่งที่ข้าสามารถฝันถึงเท่านั้น",
  str_voice_1601861_29 = "ฉันดีใจที่เราได้เป็นเพื่อนกัน แต่มันรบกวนคุณไหมที่ฉันตื่นแค่สี่ชั่วโมงต่อวัน?",
  str_voice_1601861_30 = "หัตถ์เทวะของข้าเปล่งประกายด้วยอัจฉริยภาพ",
  str_voice_1601861_31 = "พลังพลุ่งพล่านไปทั่วร่างกายของฉัน",
  str_voice_1601861_32 = "ตอนนี้ฉันสามารถต่อสู้กับอาการง่วงนอนได้ดีขึ้น",
  str_voice_1601861_33 = "หัตถ์เทวะมีพลังมากกว่าที่เคย",
  str_voice_1601861_34 = "ฉันสัญญาว่าจะไม่หลับ",
  str_voice_1601861_35 = "ขอบแสงศักดิ์สิทธิ์",
  str_voice_1601861_36 = "แสงศักดิ์สิทธิ์จะดับความชั่วร้ายทั้งหมด",
  str_voice_1601861_37 = "อลังการขั้นเทพ!",
  str_voice_1601861_38 = "ไม่มีที่ซ่อนภายใต้แสง!",
  str_voice_1601861_39 = "แสงศักดิ์สิทธิ์ ไหล!",
  str_voice_1601861_40 = "แสงศักดิ์สิทธิ์ ส่องแสง!",
  str_voice_1601861_41 = "ขอบคุณที่เชื่อในตัวฉัน",
  str_voice_1601861_42 = "พระหัตถ์ศักดิ์สิทธิ์จะกวาดสิ่งกีดขวางออกไป",
  str_voice_1601861_43 = "ฉันยังไม่สามารถควบคุมหัตถ์เทวะได้",
  str_voice_1601861_44 = "ฮะ? คุณต้องการฉันสำหรับบางสิ่งบางอย่าง? แล้วอย่ามองฉันแบบนั้น ฉันตื่นแล้ว!",
  str_voice_1601861_45 = "ขอบคุณนะ PlayerName!",
  str_voice_1601861_46 = "ช่างเป็นของขวัญที่ช่างคิด",
  str_voice_1601861_47 = "ฉันชื่นชมความคิด",
  str_voice_1601861_48 = "คุณจำได้! โอ๊ย ตื้นตันใจมาก",
  str_voice_1601861_49 = "ในฐานะทายาทของครอบครัว ฉันมีทั้งหัตถ์เทวะและตำแหน่ง ฉันไม่ได้เป็นโรคลมหลับในตอนเด็ก และทุกคนคิดว่าฉันปกติ",
  str_voice_1601861_50 = "แพทย์ไม่สามารถรักษาโรคลมหลับของฉันได้ แต่ฉันสามารถตื่นนอนได้สี่ชั่วโมงทุกวัน ดังนั้นฉันจึงต้องทำทุกอย่างให้เสร็จภายในสี่ชั่วโมงนั้น มันไม่ใช่เรื่องใหญ่อะไรขนาดนั้น",
  str_voice_1601861_51 = "ถ้าเพียงแต่ฉันสามารถเก็บ Eclipsite ตัวเล็ก ๆ ไว้เป็นสัตว์เลี้ยงได้... แต่ฉันเดาว่าคงเป็นไปไม่ได้ที่นี่ใน Lumopolis อืม เป็นความคิดที่ดี",
  str_voice_1601861_52 = "Alchemy Stars",
  str_voice_1601861_53 = "อ้าว สวัสดี!",
  str_voice_1601861_54 = "อรุณสวัสดิ์",
  str_voice_1601861_55 = "อา เที่ยงแล้ว",
  str_voice_1601861_56 = "สายัณห์สวัสดิ์",
  str_voice_1601861_57 = "สวัสดีปีใหม่, PlayerName!",
  str_voice_1601891_1 = "หลายคนเย้ยหยันความคิดเรื่องความยุติธรรม แต่ไม่ใช่เรื่องที่ต้องหัวเราะเยาะ อย่างน้อยสำหรับผู้ตัดสิน Lumopolis ต้องเป็นมาตรฐานเดียวของเรา",
  str_voice_1601891_2 = "ฉันกังวลกับสิ่งที่อยู่ข้างในหรือสิ่งที่ใช้งานได้จริงมากกว่ารูปลักษณ์ภายนอก ผู้คนมักเพ่งเล็งและชี้นิ้วมาที่ฉันในการแต่งตัวและอาวุธของฉัน โดยกล่าวหาว่าฉันดูเหมือนคนจากอิลลูมินา คุณคิดอย่างไร?",
  str_voice_1601891_3 = "ความทุกข์ส่วนใหญ่ของโลกเกิดจากความอยุติธรรม ฉันรู้ว่าฉันไม่สามารถเปลี่ยนแปลงข้อเท็จจริงนั้นได้ แต่ฉันจะทำทุกอย่างที่ทำได้เพื่อกำจัดความอยุติธรรมในที่ที่ฉันเห็น",
  str_voice_1601891_4 = "ถ้าเป็นไปได้ ฉันไม่อยากทำงานร่วมกับคนอื่น ไม่ ไม่ใช่ว่าฉันไม่ชอบเพื่อนของคุณ ฉันแค่ทำงานคนเดียวอย่างมีประสิทธิภาพมากขึ้น",
  str_voice_1601891_5 = "ถ้าฉันจะเข้มงวดกับคนอื่น ฉันก็ต้องเข้มงวดกับตัวเองด้วย การบังคับใช้ความยุติธรรมเรียกร้องความเต็มใจที่จะลงโทษตนเองสำหรับการกระทำผิดของเราโดยปราศจากความเมตตา ฉันหวังว่าคุณจะแนะนำฉันทุกครั้งที่ทำได้",
  str_voice_1601891_6 = "ฉันขอโทษที่ฉันทำให้คุณเข้าใจผิด ฉันไม่อยากทำงานร่วมกับคนอื่นเพราะความล้มเหลวของตัวเอง ในที่สุดฉันก็มีความกล้าที่จะยอมรับว่า",
  str_voice_1601891_7 = "หากคุณเหนื่อย ฉันสามารถชงชาหอมและของหวานให้คุณได้ ฉันปลูกดอกไม้และผลไม้เอง... ขอโทษนะ ฉันตื่นเต้นไปหน่อยเมื่อพูดถึงต้นไม้ของฉัน",
  str_voice_1601891_8 = "ผู้คนมักพูดว่าฉันควรพูดคุยกับเพื่อนอย่างเป็นกันเอง อะแฮ่ม... ฮ-ทำไงดี ผู้พิพากษา—ไม่ ฉันทำไม่ได้ ลืมที่ฉันพูด",
  str_voice_1601891_9 = "ฉัน Leyn ขอสาบานที่จะรับใช้เคียงข้างคุณในฐานะอัศวินของคุณ ข้าพเจ้าจะปฏิบัติตามคำสั่งของท่านทุกข้อตราบเท่าที่คำสั่งนั้นไม่ขัดต่อความยุติธรรม ฉันขอมอบความภักดีสูงสุดให้กับคุณ—โอ้ จริงจังเกินไปไหม? S-ขอโทษ ไม่รู้จะเป็นแบบอื่นยังไง...",
  str_voice_1601891_10 = "คุณกำลังหลับอยู่หรือเปล่า? ผ้าห่มอยู่ไหน...อา อยู่นั่น โอ้ ขอโทษที่ทำให้คุณตื่น แต่ถ้าเหนื่อยมากก็นอนพักได้ ใช้ได้.",
  str_voice_1601891_11 = "เลย์ มารายงานตัว ถ้าคุณต้องการอะไรก็พูดอย่างนั้น โอ้ คุณแค่อยากจะคุยกับฉันเหรอ ถ้านั่นคือสิ่งที่คุณต้องการก็ช่างมันเถอะ",
  str_voice_1601891_12 = "ด้วยความพยายามที่จะขยายขอบเขตอันไกลโพ้น ฉันได้อ่านนิยายนักสืบและแฟ้มคดี นิยายสืบสวนทุกวันนี้ไร้สาระมากขึ้นเรื่อยๆ...แต่มันสนุกมาก",
  str_voice_1601891_13 = "ฉันขอโทษอย่างยิ่ง. คุณโดนจ้องเพราะคุณออกไปเดินเล่นกับฉัน บางคนบอกว่าฉันเป็นที่นิยมในหมู่ผู้หญิง แต่ฉันไม่ชอบ ฉันขอโทษสำหรับปัญหาพิเศษ",
  str_voice_1601891_14 = "ขออภัยถ้าฉันก้าวข้ามไป แต่ฉันมีความคิดบางอย่างที่ฉันต้องการจะแสดง ใจเย็นๆ มันไม่เกี่ยวอะไรกับงานของฉันในฐานะผู้พิพากษา ก็แค่นั้นแหละ ในฐานะอัศวินของคุณ ฉันอยากให้คุณทานอาหารว่างระหว่างมื้อให้น้อยลง",
  str_voice_1601891_15 = "สุขสันต์วันเกิด! ฉันขอถามว่าคุณชอบคุกกี้ไหม ถ้าไม่ฉันสามารถเปลี่ยนเป็นอย่างอื่นได้",
  str_voice_1601891_16 = "สวัสดีและยินดีต้อนรับการกลับมา! ไม่มีเวลาให้เสียเปล่า ดังนั้นโปรดมอบหมายงานให้ฉัน",
  str_voice_1601891_17 = "สวัสดีตอนเช้า. ผู้คนจะพร้อมที่สุดในตอนเช้า ดังนั้นจึงเป็นเวลาที่ดีที่จะรับมือกับงานที่ยากๆ",
  str_voice_1601891_18 = "ดึกแล้ว คุณควรเตรียมตัวเข้านอนได้แล้ว ฉันสามารถทำงานที่คุณทำค้างไว้",
  str_voice_1601891_19 = "อ้าว ตื่นยัง? หากคุณมีงานด่วนที่ต้องดูแล ฉันพร้อมช่วยเหลือ",
  str_voice_1601891_20 = "ฉันเป็นผู้พิพากษา ฉันจึงวิจารณ์ลูโมโปลิสไม่ได้ เพราะการช่วยให้ลูโมโปลิสเติบโตเป็นส่วนหนึ่งของงานของฉัน",
  str_voice_1601891_21 = "ฉันชื่นชมการใช้งานจริงของอิลลูมินา แต่ฉันไม่เห็นด้วยที่พวกเขาเน้นระเบียบวินัยมากกว่าความยุติธรรม",
  str_voice_1601891_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1601891_23 = "Eclipsites ดูเหมือนจะมีอยู่เพื่อโจมตี Aurorians เท่านั้น นั่นทำให้พวกเขาเป็นศัตรูของฉัน",
  str_voice_1601891_24 = "ทีน่าต้องนอนพักผ่อนเยอะๆ แต่เธอจริงจังกับงาน นั่นก็เพียงพอแล้วสำหรับฉัน",
  str_voice_1601891_25 = "บร็อค... ฉันรู้สึกขอบคุณเขามาก แต่ฉันก็ไม่อยากเจอเขาอีกจริงๆ",
  str_voice_1601891_26 = "เวลาว่างฉันชอบรดน้ำดอกไม้ ซ่อมนาฬิกาโบราณ ทำอาหารอร่อยๆ... อ่า ช่วงเวลาแห่งความสุข",
  str_voice_1601891_27 = "ฉันทนไม่ได้กับความอยุติธรรม... หรือพริกที่ซ่อนอยู่ในสลัด",
  str_voice_1601891_28 = "ยักษ์ใหญ่เป็นสิ่งก่อสร้างลึกลับ... แม้ว่าฉันจะคิดว่ามันเป็นเหมือนสมาชิกในครอบครัวสำหรับคุณ",
  str_voice_1601891_29 = "ขอให้เป็นวันที่ดี. ฉันชื่อลีน ผู้พิพากษาลูโมโปลิส ฉันจะต่อสู้เพื่อความยุติธรรมต่อไปแม้ที่นี่ ฉันหวังว่าคุณจะให้อภัยถ้าฉันทำให้ขุ่นเคืองใจ",
  str_voice_1601891_30 = "เป็นขั้นเป็นตอน.",
  str_voice_1601891_31 = "การทำงานหนักให้ผลตอบแทน",
  str_voice_1601891_32 = "ฉันรู้วิธีก้าวหน้าแล้ว!",
  str_voice_1601891_33 = "นี่คือความตั้งใจของฉัน",
  str_voice_1601891_34 = "เข้าใจแล้วครับ",
  str_voice_1601891_35 = "ฉันพร้อมเสมอ.",
  str_voice_1601891_36 = "สำหรับคุณเพื่อความยุติธรรม",
  str_voice_1601891_37 = "นี่คือทั้งหมดที่ฉันมี!",
  str_voice_1601891_38 = "ฉีกความดาร์ก!",
  str_voice_1601891_39 = "ไม่มีทางหนี!",
  str_voice_1601891_40 = "จงรับโทษทัณฑ์เดี๋ยวนี้!",
  str_voice_1601891_41 = "ให้ฉันจัดการเอง",
  str_voice_1601891_42 = "พวกเราชนะ! กรุณาตรวจสอบสปอยล์",
  str_voice_1601891_43 = "รั้งท้าย! ฉันจะจับด้านหลัง!",
  str_voice_1601891_44 = "ฉันอยู่ในโหมดสแตนด์บาย คุณมีคำสั่งใด ๆ ?",
  str_voice_1601891_45 = "คุณไม่จำเป็นต้อง...",
  str_voice_1601891_46 = "โอเค ขอบคุณ...",
  str_voice_1601891_47 = "ของขวัญอื่น? นี่มันมากเกินไป...",
  str_voice_1601891_48 = "ขอบคุณ...ขอบคุณ",
  str_voice_1601891_49 = "วัยเด็กของฉัน...ไม่มีความสุขเลย ยังไม่รู้ว่าจะจัดการกับพ่อแม่ยังไงดี ดังนั้นฉันจึงหนีและเข้าร่วมกับกองทัพ เมื่อพูดถึงเรื่องนี้ ฉันก็ไม่ได้เป็นอะไรมากนอกจากเป็นคนขี้ขลาด",
  str_voice_1601891_50 = "ฉันรักชีวิตในกองทัพ แต่พบว่าการเมืองและความสัมพันธ์ทั้งหมดยากที่จะควบคุม และในตอนนั้น ฉันไม่มีความมั่นใจที่จะเปลี่ยนแปลงสิ่งต่างๆ บางทีฉันอาจโชคดีที่ได้พบกับบร็อค",
  str_voice_1601891_51 = "Brock เป็นคนที่ช่วยฉันเปลี่ยนวิธีคิดให้เป็นเชิงรุกมากขึ้น ฉันทำงานอย่างหนักเพื่อที่จะเป็นผู้พิพากษา จากนั้นฉันก็ร่วมมือกับทีน่า และแน่นอน ฉันมาที่นี่เพื่อร่วมเดินทางไปกับคุณด้วย",
  str_voice_1601891_52 = "Alchemy Stars!",
  str_voice_1601891_53 = "สวัสดี",
  str_voice_1601891_54 = "อรุณสวัสดิ์",
  str_voice_1601891_55 = "สวัสดียามบ่าย",
  str_voice_1601891_56 = "สายัณห์สวัสดิ์",
  str_voice_1601891_57 = "สวัสดีปีใหม่! ฉันหวังว่าจะได้ดูแลคุณต่อไปในปีหน้า ใครจะไปคาดคิดว่าฉันจะพูดแบบนี้?",
  str_voice_1501901_1 = "คุณกำลังสวมใส่อะไรในโลกนี้? ลืมมันไป ฉันไม่สามารถคาดหวังกับคุณมากเกินไป รสนิยมคือการผสมผสานระหว่างธรรมชาติและการเลี้ยงดู และเป็นที่แน่ชัดว่าคุณไม่มีทั้งสองอย่าง",
  str_voice_1501901_2 = "ฉันไม่ส่งต่องานให้ Pittman เพราะความเกียจคร้าน เป็นเพราะฉันไม่สามารถทำตามงานที่น่าเบื่อเหล่านั้นได้ เวลาของฉันใช้ไปกับการศึกษาและการไตร่ตรองดีกว่า",
  str_voice_1501901_3 = "แน่นอนว่าฉันไม่ชอบคนธรรมดา หึหึ... แต่คงถูกใจทุกคนไม่ได้หรอกมั้ง? ชอบทุกคนเหมือนกันกับการชอบไม่มีใคร",
  str_voice_1501901_4 = "แม้แต่ราชวงศ์ก็ไม่ได้รับการอนุมัติจากฉันหากพวกเขาไร้ความสามารถ ฉันชอบคนที่มีความสามารถจริงๆเท่านั้น ตราบใดที่พวกเขาไม่ใช่คนธรรมดาสามัญ",
  str_voice_1501901_5 = "ฉันรักสิ่งที่สวยงาม ใครๆ ก็บอกว่าความสวยสำคัญน้อยกว่าความสามารถ แต่ฉันโชคดีที่มีทั้งสองอย่าง",
  str_voice_1501901_6 = "ฉันเชื่ออย่างจริงใจว่าการประสบความสำเร็จผ่านการทำงานหนักเป็นสิ่งที่น่ายกย่องที่สุด น่าเสียดายที่ฉันสามารถประสบความสำเร็จได้โดยไม่ต้องทำงานหนัก",
  str_voice_1501901_7 = "น่าแปลกที่ฉันคิดว่าตัวเองมีรสนิยมดี ฉันต้องลงเอยด้วยบางสิ่งที่ส่งผลต่อสติปัญญาของฉัน",
  str_voice_1501901_8 = "คุณมีงานมากเกินไปและไม่สามารถทำให้เสร็จได้? ที่นี่ฉันจะแสดงให้คุณเห็นว่าจะทำอย่างไร มองลึกเข้าไปในตัวคุณแล้วถามว่าฉันจะทิ้งงานนี้ไปให้ใคร",
  str_voice_1501901_9 = "ใครบอกคุณว่าฉันใส่ชุดเด็กผู้หญิงตอนเด็ก? D-อย่ากล้าพูดถึงมันอีก! คุณอยากรู้จริงๆเหรอ? ทั้งหมดเป็นเพราะแม่ของฉัน... คุณรู้ว่าฉันหมายถึงอะไร...",
  str_voice_1501901_10 = "เจอกันอีกแล้ว ดีใจจัง ...อะไร? รอยยิ้มของฉันเสแสร้งเกินไปหรือเปล่า?",
  str_voice_1501901_11 = "คุณแค่อยากจะมองมาที่ฉันตลอดเวลา ใช่มั้ย? Tch ถ้าคุณต้อง ไปเถอะ จ้องหน้าข้าอย่างสง่าผ่าเผย",
  str_voice_1501901_12 = "ฉันไม่สามารถพูดได้อย่างแน่นอนว่าเงินสามารถซื้อความสุขได้หรือไม่ แต่ฉันมีเงินและฉันก็มีความสุข",
  str_voice_1501901_13 = "เส้นทางสู่ความสำเร็จนั้นยากลำบาก ต้องอาศัยความก้าวหน้าทีละขั้น สำหรับคุณ ฉันหมายถึง ฉันกำลังนั่งรถม้า",
  str_voice_1501901_14 = "เฮ้ ฉันกำลังคุยกับคุณ คุณควรรู้สึกเป็นเกียรติ ตอบ ตอนนี้เลย",
  str_voice_1501901_15 = "Caelestites มีวันเกิดด้วยเหรอ? ช่างน่าสนใจเสียนี่กระไร...เช่นนั้นข้าขอแสดงความยินดีด้วย",
  str_voice_1501901_16 = "มันร้อนมาก! พวกเราขุนนางต้องไม่มีกลิ่นเหงื่อ ฉันกำลังจะไปอาบน้ำ.",
  str_voice_1501901_17 = "การได้ดื่มด่ำกับกลิ่นหอมของหยดน้ำค้างยามเช้านั้นดีต่อจิตใจ ไม่ใช่ว่าคุณจะเข้าใจ",
  str_voice_1501901_18 = "สมบัติที่แท้จริงจะเปล่งประกายแม้ในความมืด ไม่แปลกใจเลยที่ฉันไม่เห็นคุณตอนกลางคืน",
  str_voice_1501901_19 = "กล้าดียังไงมานอนพร้อมกันกับฉันไม่ได้ ฉันเกลียดความคิดที่ว่าเรามีอะไรที่เหมือนกัน!",
  str_voice_1501901_20 = "ขุนนางรวบรวมความยุติธรรม Lumopolis ครองโลก",
  str_voice_1501901_21 = "อะไร มีกลุ่มอื่นในโลกนี้อีกไหมนอกจากพวกขุนนาง?",
  str_voice_1501901_22 = "ขอเทิดทูนรัตติกาลสีขาว!",
  str_voice_1501901_23 = "การอาบน้ำหนึ่งพันครั้งไม่สามารถชำระล้างกลิ่นเหม็นของ Eclipsite ได้",
  str_voice_1501901_24 = "ฉันจะไม่บอกว่า Irridon เป็นเพื่อนที่ดี แต่เธอเป็นหนึ่งในคนไม่กี่คนที่ควรค่าแก่การเคารพของฉัน",
  str_voice_1501901_25 = "Pittman มีความกระตือรือร้น มีความยุติธรรมสูง และเป็นประโยชน์ต่อฉันมาก",
  str_voice_1501901_26 = "แม้แต่วัตถุธรรมดาที่สุดก็มีเสน่ห์ยิ่งขึ้นเมื่อประดับด้วยอัญมณีสีเขียว",
  str_voice_1501901_27 = "หึ สกปรก ฆ่าเชื้อสิ่งนี้!",
  str_voice_1501901_28 = "นี่เป็นสถานที่ที่ยอดเยี่ยม เพื่อให้มันเป็นอย่างนั้น ฉันจึงห้ามไม่ให้คนธรรมดาเข้าไป",
  str_voice_1501901_29 = "ฉันคือ Matthieu ผู้ตัดสินที่อายุน้อยที่สุดในประวัติศาสตร์ ฉันมีรสชาติที่ดีที่สุดและพรสวรรค์ที่ไร้จุดสิ้นสุด บูชาฉันถ้าคุณต้องการ แต่อย่าหวังว่าเราจะได้เป็นเพื่อนกัน",
  str_voice_1501901_30 = "ฉันแข็งแรง.",
  str_voice_1501901_31 = "อัญมณีเปล่งประกาย",
  str_voice_1501901_32 = "ยังสวยกว่า.",
  str_voice_1501901_33 = "ฉันนี่แหละ แสงสว่าง!",
  str_voice_1501901_34 = "คุณอาจจะเชียร์",
  str_voice_1501901_35 = "แสงลงมาแล้ว",
  str_voice_1501901_36 = "ดูสง่าราศีของครอบครัวฉันสิ",
  str_voice_1501901_37 = "รัศมีศักดิ์สิทธิ์!",
  str_voice_1501901_38 = "รู้สึกถึงการแตกของแส้!",
  str_voice_1501901_39 = "ฉันพบว่าคุณมีความผิด!",
  str_voice_1501901_40 = "ยื่นกฎหมาย!",
  str_voice_1501901_41 = "ฉันต้องการอีกครั้ง?",
  str_voice_1501901_42 = "ฉันเคยชินกับชัยชนะ",
  str_voice_1501901_43 = "เป็นไปไม่ได้...",
  str_voice_1501901_44 = "ยักษ์ใหญ่นั้นยอดเยี่ยมมาก มันจะดีกว่าถ้ามีขุนนางอาศัยอยู่ในนั้น",
  str_voice_1501901_45 = "คุณเรียกสิ่งนี้ว่าของขวัญหรือไม่?",
  str_voice_1501901_46 = "ฉันประเมินคุณต่ำไป",
  str_voice_1501901_47 = "รสเลิศอะไรปานนั้น.",
  str_voice_1501901_48 = "ฉันจะยอมรับมัน",
  str_voice_1501901_49 = "ครอบครัวของฉันออกแบบเสื้อผ้าหรูหรา พวกเขาพูดว่าเสื้อผ้าทำให้ผู้ชาย และยิ่งผู้ชายธรรมดามากเท่าไหร่ ความจริงก็ยิ่งมากขึ้นเท่านั้น คุณเป็นตัวอย่าง",
  str_voice_1501901_50 = "ใช่แล้ว ฉันเป็นเด็กอัจฉริยะในตำนานของ Dawn Academy ฉันได้เป็นผู้ช่วยครูตอนอายุ 10 ขวบ และเป็นผู้พิพากษาที่อายุน้อยที่สุดเมื่ออายุ 15 ปี ร่วมเชียร์และปรบมือได้ตามสบาย",
  str_voice_1501901_51 = "ทำงานก็ไม่มีอะไรท้าทายฉัน ที่น่ารำคาญมีอย่างเดียวคือคู่หูของฉัน...",
  str_voice_1501901_52 = "Alchemy Stars",
  str_voice_1501901_53 = "อ๊ะ!",
  str_voice_1501901_54 = "ช่างเป็นวันที่สมบูรณ์แบบที่จะไม่ทำงานเลย",
  str_voice_1501901_55 = "วันนี้เหงื่อไม่ออก",
  str_voice_1501901_56 = "ไม่มีอะไรดีไปกว่าการอาบน้ำ",
  str_voice_1501901_57 = "น่าแปลกที่การฉลองปีใหม่ทำให้คุณดูดีขึ้น",
  str_voice_1601484_10 = "หาว... ฉันเหนื่อย. ฉันจะไปงีบ ถ้าลูกค้าท่านใดว่างมารับผมนะครับ และถ้าฉันจับได้ว่าคุณหย่อนยาน... คุณก็รู้ว่าอะไรจะเกิดขึ้น",
  str_voice_1601484_11 = "พ่อแม่ของฉันเคยบอกฉันว่านักล่าที่ดีนั้นเก่งในการพรางตัวและความอดทน เลยต้องแต่งตัวแบบนี้มารอที่นี่ มันน่าเบื่อแม้ว่า",
  str_voice_1601484_16 = "ลูกค้าของเราใกล้จะมาถึงแล้ว โฟกัส ไม่งั้นฉันจะไม่รับผิดชอบ ถ้ากระสุนเฉียดแก้มคุณ",
  str_voice_1601484_17 = "ฉันจะลงโทษคุณอย่างไรที่มาสาย? อืม... ฉันน่าจะใช้เธอเป็นเก้าอี้นะ?",
  str_voice_1601484_18 = "เอาล่ะ ได้เวลาสรุปสำหรับวันนี้แล้ว ทำไมคุณถึงรีบร้อนเช่นนี้? มีวันที่ร้อนแรงรอคุณอยู่หรือไม่?",
  str_voice_1601484_19 = "ที่รัก คุณมาทำอะไรที่นี่เวลานี้ คุณมาหาฉันไหม",
  str_voice_1601484_35 = "คุณรู้ว่าต้องทำอะไรใช่ไหม?",
  str_voice_1601484_36 = "อย่างจริงจัง จริงจัง...",
  str_voice_1601484_37 = "ปิดล้อมสถานเดียว!",
  str_voice_1601484_38 = "ไม่มีทางหนี!",
  str_voice_1601484_39 = "อย่าเพิ่งขยับ",
  str_voice_1601484_40 = "นี้จะไม่เจ็บ",
  str_voice_1601484_44 = "ออกไปกับฉันในงานต่อไปของฉัน",
  str_voice_1601484_1 = "ฉันไม่ชอบใช้เวลานานเกินไปในที่เดียว เอเจนซี่นี้มันเป็นแค่เรื่องตลกเท่านั้น",
  str_voice_1601484_2 = "ยิ่งฉันดื่มมากเท่าไหร่ฉันก็ยิ่งดีขึ้นเท่านั้น ต้องการดูด้วยตัวคุณเอง? เยี่ยมมาก ยืนตรงนั้นแล้ววางกระป๋องนี้บนหัวคุณ",
  str_voice_1601484_3 = "ปืนนี้ไม่ดีเท่า Eye of the Lynx แต่ก็ไม่เลว ฉันจะให้คุณเล่นกับมันเมื่อฉันทำที่นี่ คุณไม่ต้องการ?",
  str_voice_1601484_12 = "ท่อนบนนี้คับไปหน่อย ฉันเลยปลดกระดุมออกสองสามเม็ด อะไร ทำไมจะไม่ล่ะ? เอาเถอะ อธิบายให้ละเอียดหรือว่าฉันจะเข้าใจได้อย่างไร?",
  str_voice_1601484_13 = "เมื่อแลกเปลี่ยน Intel คุณต้องรู้คุณค่าของสิ่งที่คุณมี แน่นอนว่าการมีปืนช่วย",
  str_voice_1601484_14 = "อืม. โอเค คุณรู้วิธีที่จะชนะใจฉัน คุณมีคุณสมบัติไม่เพียงพอที่จะทำหน้าที่เป็นผู้ช่วยของฉัน ถ้าคุณพยายามมากกว่านี้ ฉันอาจจะให้รางวัลคุณด้วยซ้ำ",
  str_voice_1601484_58 = "ได้เวลาตื่นแล้ว! สายแล้ว!",
  str_voice_1601484_59 = "อยากไปขี่ไหม?",
  str_voice_1601484_60 = "งานที่หน่วยงานนั้นสนุกสนานอย่างน่าประหลาดใจ",
  str_voice_1601484_61 = "เราควรทานอะไรเป็นมื้อเที่ยง?",
  str_voice_1601484_62 = "บ่ายๆ ร้อนๆ แบบนี้",
  str_voice_1601484_63 = "ฉันเบื่อ. มีอะไรน่าสนใจเกิดขึ้นบ้าง?",
  str_voice_1601484_64 = "ทำไมเราไม่ดื่ม",
  str_voice_1601484_65 = "คุณยังตื่นอยู่ไหม Caeleste ตัวน้อย?",
  str_voice_1601484_66 = "ตอนเย็น. คุณกำลังคิดอะไรอยู่?",
  str_voice_1601484_67 = "ฉันทำทุกอย่างด้วยตัวเองแม้กระทั่งงาน ชีวิตก็น่าเบื่ออย่างอื่น",
  str_voice_1601484_68 = "เครื่องดื่มเล็กน้อยทำให้ทุกอย่างดีขึ้น",
  str_voice_1601484_69 = "หึหึ แน่นอนคุณสามารถทนต่อการล้อเล่น?",
  str_voice_1601484_70 = "ฉันมีเป้าหมายเดียวคือปกป้องครอบครัวที่ฉันพบ",
  str_voice_1601484_71 = "พุทโธ่. ฉันคิดว่าฉันอาจจะตกหลุมรักคุณ",
  str_voice_1601911_1 = "บางครั้งเศษเสี้ยวของความทรงจำที่หายวับไปแวบเข้ามาในความคิดของฉัน อ้อยอิ่งอยู่เพียงไม่กี่วินาที—ไม่สามารถเข้าใจได้ นับประสาอะไรกับการรักษาไว้ เช่นเดียวกับดอกไม้ไฟ พวกเขาทะยานขึ้นและระเบิด จากนั้นก็จางหายไปอย่างไร้ร่องรอย",
  str_voice_1601911_2 = "ฉันไม่ใช่หมาจรจัด! ฉันไม่ใช่สัตว์ประหลาด! ฉัน—ขอโทษ เมื่อกี้ฉันฝันร้าย",
  str_voice_1601911_3 = "ฉันจงใจซ่อนตัวอยู่ที่มุมหนึ่งของงานปาร์ตี้ ส่วนใหญ่มาจากความเกียจคร้าน การเข้าสังคมเป็นสิ่งที่น่าเบื่อ แต่ฉันบอกได้เลยว่ามีคนสนใจคุณ คุณไม่สังเกตเหรอ? ลืมมันไปซะ คุณจะรู้สึกได้เองในที่สุด",
  str_voice_1601911_4 = "ฉันต้องการความแข็งแกร่งทางจิตใจเพื่อควบคุมเปลวไฟของฉันอย่างเหมาะสม คุณสามารถสั่งการทุกคนในการต่อสู้ได้ตลอดเวลา ฉันคิดว่าจิตใจของคุณต้องแข็งแกร่งมาก",
  str_voice_1601911_5 = "โลกนี้มีความอาฆาตพยาบาทมากเกินไป ฉันได้เห็นและประสบกับสิ่งเหลือเชื่อมากมาย สิ่งที่สอนฉันว่าโลกนี้มีความมืดมิดอยู่พอสมควร",
  str_voice_1601911_6 = "แน่นอนว่าความทรงจำบางอย่างเจ็บปวด แต่ฉันก็ไม่รีบร้อนที่จะลืมมัน หากคุณรวบรวมชิ้นส่วนต่างๆ เข้าด้วยกันและใช้ความรู้สึกบางอย่างท่ามกลางความโกลาหล คุณอาจพบคำตอบที่คุณต้องการ",
  str_voice_1601911_7 = "แม้ว่าฉันจะดูแตกต่างจากคนส่วนใหญ่ แต่ฉันคิดและรู้สึกเหมือนกับคนอื่นๆ ฉันเชื่อว่าเธออาจจะเข้าใจฉัน เพราะเธอและฉันมีกลิ่นที่เหมือนกัน",
  str_voice_1601911_8 = "ฉันมีของขวัญสำหรับคุณ. ฉันทำตะเกียงที่เผาไหม้ช้านี้ด้วยตัวเอง มันแค่มีไฟอยู่ข้างใน แต่ฉันหวังว่ามันจะให้แสงสว่างและความอบอุ่นแก่คุณในความมืด",
  str_voice_1601911_9 = "อย่ากังวล หูของฉันหายดีแล้ว คุณสามารถสัมผัสมันได้... ไม่เป็นไร ฉันค่อนข้างชอบให้คุณสัมผัส",
  str_voice_1601911_10 = "วันนี้ฉันรู้สึกเบื่อนิดหน่อย ทำไมเราไม่เล่นซ่อนหา คุณรู้วิธีการเล่น? ฉันสามารถสอนคุณได้ถ้าคุณต้องการ โอ้คุณรู้หรือไม่? ที่น่าตื่นตาตื่นใจ! เพิ่งรู้เมื่อวานเหมือนกัน",
  str_voice_1601911_11 = "ไม่ว่าคุณจะต้องออกไปทำอะไร ให้รู้ว่าฉันจะอยู่เคียงข้างคุณเพื่อปกป้องคุณ ไม่ว่าที่ไหนหรือเมื่อไหร่ ฉันจะอยู่ที่นั่นเสมอ Hati ผู้ภักดีของคุณ",
  str_voice_1601911_12 = "ฉันคุ้นเคยกับการทำสิ่งต่างๆ ด้วยตัวเอง แต่หลังจากได้พบคุณ ฉันรู้สึกว่าการมีคู่ชีวิตก็ไม่เลวเหมือนกัน การมีคุณช่วยฉันก็ไม่รู้สึกว่าน่ารำคาญเกินไป",
  str_voice_1601911_13 = "เด็กหลงทางจุดไฟเพื่อค้นหาความทรงจำที่หายไป แต่ไม่รู้ว่าแม้แต่เปลวไฟที่จางที่สุดก็สามารถจุดไฟที่เผาผลาญโลกได้",
  str_voice_1601911_14 = "ฉันเชื่อในสัญชาตญาณของตัวเองมากกว่าที่ฉันเชื่อในกฎเกณฑ์ทางสังคม กฎมักจะซับซ้อนเสมอ นั่นเป็นเหตุผลที่ฉันเชื่อว่าสัญชาตญาณสามารถช่วยให้เราหาคำตอบได้เร็วขึ้น",
  str_voice_1601911_15 = "สุขสันต์วันเกิด! แล้วเราจะมีบาร์บีคิวเนื้อชิ้นโตล่ะ?",
  str_voice_1601911_16 = "ถ้ามีอะไรที่คุณอยากทำ ก็ลงมือทำเลย อย่าโง่เขลา",
  str_voice_1601911_17 = "ลองตื่นเช้ามาอาบแดด มันจะทำให้ร่างกายของคุณรู้สึกอบอุ่นและสบายตัว",
  str_voice_1601911_18 = "คุณมีสตูว์สำหรับมื้อค่ำหรือไม่? กินเนื้อมากขึ้นและคุณจะมีแรงมากขึ้นในการเผชิญหน้าชีวิต",
  str_voice_1601911_19 = "มาใช้เวลายามค่ำคืนอย่างสงบสุขข้างกองไฟกันเถอะ",
  str_voice_1601911_20 = "Umbraton เป็นสถานที่ที่ซับซ้อนมาก แม้ว่าบ่อยครั้งจะดูเหมือนไม่มีอะไรเลยนอกจากมุมมืด แต่ก็ยังมีแสงสว่างเป็นครั้งคราว",
  str_voice_1601911_21 = "Lumopolis เป็นสถานที่ที่มืดมนที่สุดในโลก ฉันเกลียดมัน.",
  str_voice_1601911_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1601911_23 = "Eclipsites น่าขยะแขยงพอ ๆ กับขุนนางแห่ง Lumopolis",
  str_voice_1601911_24 = "Grimme มักจะพูดพล่ามเกี่ยวกับเรื่องนี้หรือเรื่องนั้น แต่ก็ไม่เลวเพราะพวกเขาเต็มใจที่จะพูดคุยกับใครก็ได้",
  str_voice_1601911_25 = "ฉันเดาว่าคุณอาจพูดว่า Istvan เป็นเหมือนผู้พิทักษ์ของฉัน ถ้าไม่มีเขา ฉันคงไม่มีฉันในวันนี้",
  str_voice_1601911_26 = "คุณมีหนังสือพิมพ์ใหม่ ๆ หรือไม่? ฉันได้ไขปริศนาทั้งหมดในข้อนี้แล้ว!",
  str_voice_1601911_27 = "วันนี้งดผักจะดีไหม? โดยเฉพาะกะหล่ำปลีแดง—มันแย่มาก...",
  str_voice_1601911_28 = "ปรากฎว่ามีสถานที่ในโลกที่เต็มไปด้วยแสงสว่างและความอบอุ่นจริงๆ...",
  str_voice_1601911_29 = "อย่าปล่อยให้รูปลักษณ์ของฉันทำให้คุณกลัว อย่าผลักไสฉันเพียงเพราะรูปร่างหน้าตาของฉัน ฉันเป็นแค่ชาวออโรเรียนธรรมดาๆ ฉันชื่อฮาติ ถ้าไม่เป็นไรมาเป็นเพื่อนกันเถอะ",
  str_voice_1601911_30 = "เปลวไฟ!",
  str_voice_1601911_31 = "ตอนนี้ฉันแข็งแกร่งขึ้นแล้ว!",
  str_voice_1601911_32 = "ปล่อยให้ทุกอย่างเผาไหม้",
  str_voice_1601911_33 = "เปลวไฟสีน้ำเงินเผาไหม้ตลอดไป",
  str_voice_1601911_34 = "คุณสามารถไว้วางใจฉัน",
  str_voice_1601911_35 = "เปลวไฟสีน้ำเงินสั่นไหว",
  str_voice_1601911_36 = "คุณต้องการที่จะฉีกเป็นชิ้นเล็กชิ้นน้อย?",
  str_voice_1601911_37 = "ไฟไหม้ลาม!",
  str_voice_1601911_38 = "ไปเลย!",
  str_voice_1601911_39 = "วิญญาณฟ้าลุกโชน!",
  str_voice_1601911_40 = "ชนแล้วไหม้!",
  str_voice_1601911_41 = "ได้!",
  str_voice_1601911_42 = "กลิ่นหอมแห่งชัยชนะ!",
  str_voice_1601911_43 = "นี่มัน...ห่วย",
  str_voice_1601911_44 = "ฉันรู้สึกแบบนี้ เหมือนไม่มีอะไรเลวร้ายเกิดขึ้นที่นี่ มีแต่เรื่องดีๆ",
  str_voice_1601911_45 = "อืม คุณสามารถทิ้งไว้ที่นี่",
  str_voice_1601911_46 = "ช่างเป็นของขวัญที่ยอดเยี่ยม",
  str_voice_1601911_47 = "ฉันควรจะพูดว่า...ขอบคุณ",
  str_voice_1601911_48 = "เป็นของขวัญที่วิเศษมาก ขอบคุณ",
  str_voice_1601911_49 = "ฉันไม่เคยพบพ่อของฉันเลย... เขาเสียชีวิตก่อนฉันเกิด ทิ้งไว้เพียงจี้นี้ สิ่งเดียวที่ฉันระลึกถึงเขา",
  str_voice_1601911_50 = "ฉันจำได้ว่าแม่ของฉันมักจะกังวลและยุ่งมาก และฉันก็พยายามเรียกร้องความสนใจจากเธอให้มากขึ้น มองย้อนกลับไปตอนนี้ฉันยังเด็กมาก ฉันพนันได้เลยว่าผู้ใหญ่ทุกคนจะทนฉันไม่ได้...",
  str_voice_1601911_51 = "ฉันมีเพื่อนไม่มาก อาจเป็นเพราะรูปลักษณ์ของฉัน ฉันไม่เคยพยายามทำอะไรไม่ดีกับใคร แต่ดูเหมือนว่าความโชคร้ายจะติดตามฉันไป",
  str_voice_1601911_52 = "Alchemy Stars",
  str_voice_1601911_53 = "คุณอยู่ที่นี่ด้วยเหรอ?",
  str_voice_1601911_54 = "เกา เกา... เฮ้ ลุกขึ้น",
  str_voice_1601911_55 = "เราสตูว์เนื้อเป็นมื้อกลางวันได้ไหม",
  str_voice_1601911_56 = "คุณทานอาหารเย็นเรียบร้อยหรือยัง?",
  str_voice_1601911_57 = "ฉันหวังว่าสิ่งที่น่าจดจำอย่างแท้จริงจะเกิดขึ้นในปีใหม่",
  str_voice_1501931_1 = "อืม-อืม-อืม! ท่วงทำนองแบบกะทันหันเป็นสิ่งที่สวยงามที่สุดและเป็นอิสระจากทั้งหมด ไม่ว่าจะร้องกี่ครั้ง ท่วงทำนองที่เขียนบนโน้ตเพลงก็ยังเหมือนเดิมเสมอ",
  str_voice_1501931_2 = "ต้องขอบคุณหอกนี้ที่ฉันสามารถลงโทษอาชญากรได้อย่างมั่นคง",
  str_voice_1501931_3 = "ครอบครัวของฉันเป็นเจ้าของคฤหาสน์ทั่วโลก คุณอยากไปเที่ยวพักผ่อนกับฉันไหม อ่า... แต่หลังจากช่วงทดลองงานของฉันสิ้นสุดลงเท่านั้น แน่นอน!",
  str_voice_1501931_4 = "ฉันต้องดูแลหอกนี้เป็นพิเศษเพื่อให้คงความคมไว้ตลอดเวลา",
  str_voice_1501931_5 = "น้ำสามารถสร้างเสียงดนตรีที่ไพเราะที่สุด ด้วยเสียงที่ชัดเจนของการไหลที่นุ่มนวล ความลังเลใจทั้งหมดก็มลายหายไป",
  str_voice_1501931_6 = "ร้องเพลงท่ามกลางกระแส! ให้พลังที่พลุ่งพล่านนำทางผู้เชื่ออิสระทุกคนไปสู่อีกด้านหนึ่งของคลื่นลูกใหม่!",
  str_voice_1501931_7 = "ฉันเล่นเครื่องดนตรีได้หลายอย่าง แต่... ในฐานะมือสมัครเล่นเท่านั้น คุณคิดว่าอะไรเหมาะกับฉันมากกว่ากันระหว่างชีวิตนักดนตรีกับผู้พิพากษา?",
  str_voice_1501931_8 = "ฉันชื่นชมไลฟ์สไตล์ของคุณ ใช้ชีวิตอย่างอิสระและเป็นอิสระ บางทีวันหนึ่งฉันอาจเดินทางไปทั่วโลกเหมือนคุณ",
  str_voice_1501931_9 = "ฉันมีความรักและเคารพพ่อแม่มาก แต่นั่นไม่ได้หมายความว่าฉันเต็มใจที่จะใช้ชีวิตตามที่พวกเขาจัดให้ อย่างน้อยตอนนี้ ฉันก็ยังไม่เสียใจกับการเลือกของฉัน",
  str_voice_1501931_10 = "อืม จู่ๆ ก็ไม่มีอะไรทำ และรู้สึก... สูญเสียอย่างน่าประหลาด",
  str_voice_1501931_11 = "คุณมีงานใหม่ให้ฉันไหม ฮะ? คุณต้องการให้ฉันอยู่ที่นี่เท่านั้นหรือ ฮิฮิ ฉันคิดว่าการได้อยู่ใกล้นายก็เป็นงานที่สำคัญเหมือนกันนะ!",
  str_voice_1501931_12 = "แม้ว่าข้าพเจ้าจะจัดการกับคดีที่อยู่ในความดูแลของข้าพเจ้าตามแนวทางที่พบในหนังสือที่น่าเชื่อถือที่สุด แต่ข้าพเจ้าก็ไม่สามารถแก้ไขทุกปัญหาได้ แน่นอน ดูเหมือนว่าฉันยังมีอะไรให้เรียนรู้อีกมาก!",
  str_voice_1501931_13 = "ลองคิดดูสิ ฉันไม่ได้ไปดูละครเวทีมานานแล้ว ฉันสงสัยว่าช่วงนี้มีโปรดักชั่นใหม่ที่ได้รับความนิยมบ้างไหม?",
  str_voice_1501931_14 = "ทำไมคุณถึงจ้องมองมาที่ฉัน เสื้อผ้าหน้าผมรุงรังเกินไปหรือเปล่า...? อืม ดูเหมือนจะไม่เป็นอะไร บางทีฉันอาจจะเครียดเกินไปจริงๆ ได้โปรด อย่าใส่ใจเลย",
  str_voice_1501931_15 = "สุขสันต์วันเกิด! ฉันคิดทำนองเอง...คุณชอบไหม?",
  str_voice_1501931_16 = "คุณต้องการความช่วยเหลือจากฉันไหม ฉันจะต้องจัดการคดีนี้ก่อน โปรดรอสักครู่!",
  str_voice_1501931_17 = "เตรียมพร้อมรับวันใหม่! พระอาทิตย์ส่องแสงบนหัวของคุณ! หากไม่ลุกตอนนี้ นกอาจมาทำรังได้!",
  str_voice_1501931_18 = "อา นี่เป็นช่วงเวลาที่ผ่อนคลายที่สุดของวัน ฉันขอเปิดเพลงให้คุณฟังได้ไหม",
  str_voice_1501931_19 = "สายไปแล้ว! มีอะไรเร่งด่วนที่คุณต้องการถามฉัน? อืม? คุณหมายถึง... คุณแค่หิว?",
  str_voice_1501931_20 = "ขุนนางบางคนของ Lumopolis เชื่อว่าพวกเขาไม่ควรมีปฏิสัมพันธ์กับสามัญชน อย่างไรก็ตาม ฉันเชื่อว่านี่เป็นความคิดที่หยิ่งยโสโดยสิ้นเชิง",
  str_voice_1501931_21 = "Umbraton แตกต่างจาก Lumopolis มาก แต่ฉันคิดว่าฉันชอบมัน",
  str_voice_1501931_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1501931_23 = "Eclipsites เป็นตัวอย่างของความโกลาหล พวกเขาทั้งหมดได้ก่อความโหดร้ายในรูปแบบใดรูปแบบหนึ่ง",
  str_voice_1501931_24 = "เซนัสสอนฉันถึงวิธีการต่อสู้ ในฐานะผู้สอน เขาเป็นคนที่ควรค่าแก่การชื่นชมอย่างปฏิเสธไม่ได้",
  str_voice_1501931_25 = "บางครั้งมาติเยอก็จ้องมาที่ฉันอย่างกะทันหัน เป็นไปได้ไหมว่าท่วงทำนองที่ฉันฮัมมีผลอย่างมากต่อเขา?",
  str_voice_1501931_26 = "ฉันชอบของที่มีรูปทรงสี่เหลี่ยม—สามารถวางซ้อนกันได้อย่างเป็นระเบียบ และความรู้สึกนี้ทำให้ผ่อนคลายอย่างเหลือเชื่อ!",
  str_voice_1501931_27 = "อาชญากรเป็นสิ่งมีชีวิตที่น่าขยะแขยงที่สุดในโลก และนั่นคือเหตุผลที่ฉันอยากทำหน้าที่ในนามของความยุติธรรม",
  str_voice_1501931_28 = "Colossus นั้นงดงามมาก แต่ไม่มีใครรู้สึกเหงาเมื่ออยู่ที่นี่คนเดียวหรือ?",
  str_voice_1501931_29 = "ฉันชื่อคริสเตน และในฐานะผู้พิพากษาคุมประพฤติ ฉันอยู่ในกระบวนการเรียนรู้วิธีการทำงานที่มีประสิทธิภาพมากขึ้นทุกวัน แน่นอน หากมีกรณีที่ไม่คาดฝันเกิดขึ้น คุณสามารถขอความช่วยเหลือจากฉันได้",
  str_voice_1501931_30 = "คุณหวังว่าจะให้ฉันแข็งแกร่งขึ้นไหม?",
  str_voice_1501931_31 = "คลื่นใต้น้ำกำลังเพิ่มขึ้น",
  str_voice_1501931_32 = "รุ่งอรุณจะมาถึงในที่สุด—",
  str_voice_1501931_33 = "ให้ฝนตกหนักพาคุณไป!",
  str_voice_1501931_34 = "พร้อมแล้วรอเลย!",
  str_voice_1501931_35 = "หอกของฉันขัดเงาและทรงตัว",
  str_voice_1501931_36 = "สนใจที่จะทดสอบพลังหอกของฉันหรือไม่?",
  str_voice_1501931_37 = "ต้านกระแส!",
  str_voice_1501931_38 = "น้ำเชี่ยวไหลเชี่ยว!",
  str_voice_1501931_39 = "เต้นไปกับเกลียวคลื่น!",
  str_voice_1501931_40 = "กระชาก!",
  str_voice_1501931_41 = "น้ำจะพัดพาสิ่งกีดขวางออกไป",
  str_voice_1501931_42 = "ความยุติธรรมครองชัยชนะ!",
  str_voice_1501931_43 = "ฉันห่างเหินไปหน่อย เมื่อเร็วๆ นี้...",
  str_voice_1501931_44 = "โปรดแบ่งปันเรื่องราวที่น่าสนใจเกี่ยวกับยักษ์ใหญ่กับฉัน! ฉันจะตั้งใจฟังทุกคำ!",
  str_voice_1501931_45 = "ขอบคุณ นี่เป็นของขวัญที่ดีมาก",
  str_voice_1501931_46 = "มันเป็นสิ่งที่ฉันต้องการ ขอบคุณ",
  str_voice_1501931_47 = "ของขวัญชิ้นนี้มาจากใจจริง ๆ ฉันจะถนอมมันไว้เสมอ",
  str_voice_1501931_48 = "ฉันรักมัน! ฉันจะขอบคุณได้อย่างไร",
  str_voice_1501931_49 = "ครูฝึกสอนเสียงของฉันเชื่อว่าฉันมีพรสวรรค์ด้านเสียงที่ดีและจะกลายเป็นนักร้องที่มีชื่อเสียงได้อย่างแน่นอนในสักวันหนึ่ง อย่างไรก็ตาม ฉันไม่สามารถทนต่อการฝึกที่เข้มงวดเช่นนี้ได้ และฉันก็ไม่ชอบเพลงซ้ำๆ",
  str_voice_1501931_50 = "ตอนที่ฉันอยู่ที่สถานศึกษา ฉันมักจะแก้ปัญหาข้อขัดแย้งระหว่างเพื่อนร่วมชั้น ค่อยๆ กลายเป็น \"คนกลาง\" ในสายตาของทุกคน",
  str_voice_1501931_51 = "หลังจากเรียนจบฉันประสบความสำเร็จในการเป็นผู้พิพากษาทดลอง แม้ว่างานจะยากกว่าที่ฉันคาดไว้ แต่ฉันก็จะทำงานหนักต่อไป!",
  str_voice_1501931_52 = "Alchemy Stars!",
  str_voice_1501931_53 = "สวัสดี!",
  str_voice_1501931_54 = "สวัสดีตอนเช้า! เมื่อคืนคุณนอนยังไง?",
  str_voice_1501931_55 = "สวัสดีตอนบ่าย. มันเป็นวันที่ดีใช่มั้ย?",
  str_voice_1501931_56 = "จบงานวันนี้แล้ว!",
  str_voice_1501931_57 = "สวัสดีปีใหม่. ฉันหวังว่าเราทุกคนจะได้รับผลลัพธ์ที่ดียิ่งขึ้นในปีหน้า",
  str_voice_1601921_1 = "ใช้ดาบของคุณเพื่อขยายพรมแดน ใช้มือของคุณเพื่อปลอบประโลมจิตใจของผู้คน น่าเสียดายที่บางคนเชื่อตรงกันข้าม",
  str_voice_1601921_2 = "ฉันคุ้นเคยกับการติดธงของกองทหารของเราในการสู้รบ ตราบใดที่อัศวินของฉันยังเห็นฉันยืนอยู่ในสนามรบ พวกเขารู้ว่าชัยชนะอยู่ใกล้แค่เอื้อม",
  str_voice_1601921_3 = "ยักษ์ใหญ่นั้นงดงามมาก บางทีมันสมควรได้รับธงของมันเองเพื่อแสดงให้โลกเห็นถึงสง่าราศีและอำนาจของมัน",
  str_voice_1601921_4 = "หากคุณมีคำถามใดๆ เกี่ยวกับชีวิตในสนามรบ โปรดอย่าลังเลที่จะถามฉัน เราไม่ควรกลัวที่จะยอมรับคำแนะนำ—เพื่อที่จะเติบโต คุณต้องมีที่ปรึกษาที่มองเห็นศักยภาพที่แท้จริงของคุณ",
  str_voice_1601921_5 = "ขอเตือนให้ตรวจสอบเสบียงของ Colossus เป็นประจำ คุณไม่มีทางรู้ว่าจะเกิดอะไรขึ้น",
  str_voice_1601921_6 = "เป้าหมายของฉันชัดเจนเสมอ ฉันอยากเป็นอัศวินที่เป็นแบบอย่างที่ปกป้องผู้คนและต่อสู้เพื่อสันติภาพ",
  str_voice_1601921_7 = "ตื่นมาคอเคล็ด? ให้ฉันช่วยคุณออก เอาล่ะเสร็จแล้ว ไม่ต้องกังวลกับมัน! ฉันได้ดูดพิษจากบาดแผลของสหายของฉันมากกว่าหนึ่งครั้ง!",
  str_voice_1601921_8 = "อา ดวงตาที่ไร้เดียงสาแบบนี้... คุณดูเหมือนผู้ชายบางคนของฉัน ซึ่งแน่นอนว่าทำให้ฉันอยากปกป้องคุณ แต่ฉันจะไม่ทำเพราะคุณต้องเติบโตด้วยตัวเอง ระวัง! จับตาดูถนนให้ดี!",
  str_voice_1601921_9 = "หากฉันทำผิดพลาดประการใด โปรดแจ้งให้เราทราบอย่างตรงไปตรงมา ไม่มีอะไรต้องห้ามระหว่างเพื่อน มิตรภาพของเราแข็งแกร่งขึ้นผ่านการสื่อสารที่ซื่อสัตย์เท่านั้น",
  str_voice_1601921_10 = "เมื่อเผชิญกับความทุกข์ยาก อย่าลังเลที่จะขอความช่วยเหลือจากฉัน ฉันมีสติปัญญาและความกล้าหาญมากมาย",
  str_voice_1601921_11 = "คุณต้องการให้ฉันประจำการที่นี่ไหม ไม่มีปัญหา! เชื่อฉันเถอะว่าจะไม่ผิดพลาดแม้แต่ครั้งเดียว",
  str_voice_1601921_12 = "ปัญหาอะไรรุมเร้าคุณ? เราจะพยายามอย่างดีที่สุดเพื่อช่วยคุณแก้ไขปัญหาดังกล่าว โอ้ เสื้อผ้าของคุณขาดวิ่น ปล่อยให้ฉัน. ฉันมักจะช่วยตัดเย็บเสื้อผ้าของอัศวิน",
  str_voice_1601921_13 = "การเรียนรู้ทักษะใหม่เป็นสิ่งที่น่ายกย่อง อย่ากลัวที่จะล้มเหลว ขอแค่คุณมุ่งมั่นและพากเพียรต่อไป คุณจะสำเร็จแน่นอน",
  str_voice_1601921_14 = "ชัยชนะที่ได้มานั้นไม่ใช่เรื่องยาก ยึดจุดอ่อนของศัตรูและใช้มันต่อสู้กับพวกเขา",
  str_voice_1601921_15 = "ขอให้อนาคตของคุณเต็มไปด้วยความคิดสร้างสรรค์และความมหัศจรรย์",
  str_voice_1601921_16 = "งานวันนี้คืบหน้ายังไงบ้าง? คุณต้องการความช่วยเหลือจากฉันไหม",
  str_voice_1601921_17 = "วันนี้คุณจัดแผนสำหรับวันนี้แล้วหรือยัง? ฉันหวังว่าคุณจะมีทุกอย่างภายใต้การควบคุม",
  str_voice_1601921_18 = "วันนี้คุณทำทุกอย่างเสร็จแล้วหรือยัง?",
  str_voice_1601921_19 = "สายแล้ว. พักผ่อนให้เพียงพอและอย่าปล่อยให้ความเหนื่อยล้าส่งผลต่อประสิทธิภาพของคุณ",
  str_voice_1601921_20 = "Lumopolis มีกำหนดจะเปลี่ยนแปลงบางอย่าง",
  str_voice_1601921_21 = "อิลลูมินามีทหารไม่กี่คนที่อาจจะดีพอที่จะเข้าร่วมกลุ่มอัศวินไอรอนธอร์น",
  str_voice_1601921_22 = "อัศวินเหล็ก!",
  str_voice_1601921_23 = "ต่อสู้เพื่อกำจัด Eclipsites ทั้งหมด จนกว่าลมหายใจสุดท้ายของคุณ",
  str_voice_1601921_24 = "โจเซฟเป็นต้นแบบของความเห็นอกเห็นใจและความอดทน และเป็นสะพานเชื่อมที่สำคัญระหว่างฐานที่มั่น Lumo กับคนทั่วไป",
  str_voice_1601921_25 = "เลดี้คาร์ลีนแตกต่างจากขุนนางที่คดโกงเหล่านั้น วันหนึ่งแสงอันบริสุทธิ์และชอบธรรมของเธอจะส่องมายังลูโมโพลิส",
  str_voice_1601921_26 = "อาวุธที่เชื่อถือได้สร้างความแตกต่างในการต่อสู้",
  str_voice_1601921_27 = "ดวงตาที่ละโมบรับรู้โลกเพียงผิวเผิน และมองไม่เห็นความงามที่อยู่ภายใน",
  str_voice_1601921_28 = "งดงามและประณีต เป็นงานที่น่าพิศวง",
  str_voice_1601921_29 = "กัปตันลีโอแห่งอัศวินไอรอนธร ตามคำสั่งของคุณ ในการต่อสู้ ความสงบและความเด็ดขาดคือกุญแจสู่ชัยชนะ ฉันหวังว่าคุณจะไม่ทำให้ฉันผิดหวัง",
  str_voice_1601921_30 = "ศักยภาพไร้ขีดจำกัด",
  str_voice_1601921_31 = "อย่ายอมแพ้.",
  str_voice_1601921_32 = "ไม่เคยลังเล",
  str_voice_1601921_33 = "ฉันไม่สามารถหัก",
  str_voice_1601921_34 = "จู่โจม.",
  str_voice_1601921_35 = "เตรียมพร้อมสำหรับการต่อสู้",
  str_voice_1601921_36 = "ถ้าพร้อมแล้วก็ลุยเลย",
  str_voice_1601921_37 = "ระเบิดมรณะ!",
  str_voice_1601921_38 = "ดาบของฉันเหมือนสายฟ้า!",
  str_voice_1601921_39 = "ชาร์จเต็มแรง!",
  str_voice_1601921_40 = "ครอบงำทั้งหมด!",
  str_voice_1601921_41 = "ทำตามคำสั่งของฉัน",
  str_voice_1601921_42 = "การต่อสู้ที่น่าพอใจ",
  str_voice_1601921_43 = "อยู่ในความสงบ.",
  str_voice_1601921_44 = "ฉันต้องการปกป้องสถานที่นี้",
  str_voice_1601921_45 = "เล่นดี.",
  str_voice_1601921_46 = "คุณมีรสนิยม",
  str_voice_1601921_47 = "ขอบคุณสำหรับของขวัญนะ",
  str_voice_1601921_48 = "คุณรู้จักฉันดี",
  str_voice_1601921_49 = "แม้ว่าฉันจะเคยเป็นสมาชิกของชนชั้นสูงของลูโมโปลิส แต่ในความเป็นจริง ฉันไม่เคยเป็นขุนนางที่แท้จริงมาก่อนที่ฉันจะถูกเนรเทศด้วยซ้ำ",
  str_voice_1601921_50 = "หลังจากที่ครอบครัวของฉันพังพินาศ ฉันถูกเนรเทศไปยัง Twilight และกลายเป็นเพียงสามัญชนนิรนามในเมืองชายแดน",
  str_voice_1601921_51 = "ฉันสร้างอัศวินไอรอนธอร์นด้วยตัวเอง โดยดูดซับอัศวินสำรวจส่วนใหญ่ในทไวไลท์ หลังจากเอาชนะฝูง Eclipsite ได้หลายครั้ง ชื่อเสียงของอัศวินเหล็กหนามก็เลื่องลือไปทั่วเมือง",
  str_voice_1601921_52 = "Alchemy Stars",
  str_voice_1601921_53 = "สวัสดี",
  str_voice_1601921_54 = "ยกโทษให้ฉันมาสาย",
  str_voice_1601921_55 = "ทุกอย่างเป็นไปได้ด้วยดี?",
  str_voice_1601921_56 = "อย่าลืมพักผ่อนแต่เนิ่นๆ",
  str_voice_1601921_57 = "สวัสดีปีใหม่! ยินดีต้อนรับสู่อนาคตด้วยกัน ก้าวหน้าด้วยความกล้าหาญและความมั่นใจอันไร้ขอบเขต",
  str_voice_1601991_1 = "ฉันใช้เวลาส่วนใหญ่ในห้องสงครามเพราะงานของฉัน อย่างไรก็ตาม หลังจากที่อยู่ในสภาพแวดล้อมที่มืดมนและคับแคบเช่นนี้มาเป็นเวลานาน ก็อดไม่ได้ที่จะโหยหาท้องฟ้าสีครามสดใส",
  str_voice_1601991_2 = "โดยปกติเมื่อฉันอยู่คนเดียว ฉันจะเล่นเกมตามสถานการณ์ในหัวของฉัน บางครั้งฝ่ายตรงข้ามเป็นคนแปลกหน้าและบางครั้งก็เป็นตัวฉันเอง",
  str_voice_1601991_3 = "Aoha เป็นนกจับแมลงที่บินมาที่ปลายนิ้วของฉันอย่างเชื่อฟัง เต็มไปด้วยสติปัญญาและความเมตตา มันอยู่เคียงข้างฉันมาหลายปี",
  str_voice_1601991_4 = "ฉันไม่ได้ตั้งไรเฟิลซุ่มยิงโดยไม่มีเหตุผลที่ดี แต่เมื่อฉันเล็งไปที่ศัตรู ฉันมักจะยิงโดนเป้าหมายเสมอ",
  str_voice_1601991_5 = "แผนก็เหมือนกับเกมหมากรุก ซึ่งทุกการเคลื่อนไหวจะส่งผลต่อการดำเนินการในขั้นต่อไป ดังนั้นการวางแผนที่ดีจึงต้องเว้นที่ไว้ให้ผิดพลาดเสมอ",
  str_voice_1601991_6 = "คุณต้องโฟกัสร่างกายของคุณทั้งหมดเมื่อถ่ายภาพ ระวังอย่าหายใจเข้า เพราะอาจส่งผลต่อการยิงของคุณ เมื่อคุณเข้าใจสิ่งนี้แล้ว คุณก็สามารถเป็นมือปืนที่คู่ควรได้เช่นกัน",
  str_voice_1601991_7 = "คุณต้องการทราบว่าการทำงานให้กับคณะกรรมการนั้นน่าเบื่อและน่าเบื่อหน่ายหรือไม่? หลายคนคิดอย่างนั้น แต่การวางกลยุทธ์เป็นสิ่งที่น่าสนใจสำหรับฉันมาโดยตลอด",
  str_voice_1601991_8 = "บางครั้งฉันก็รู้สึกว่าอาโอฮาเหมือนกับฉัน การเชื่อฟังและความเปราะบางของมันคือส่วนหน้า ความกล้าหาญและความมุ่งมั่นเต้นอยู่ในหัวใจดวงเล็กๆ ของมัน",
  str_voice_1601991_9 = "อดีตของเราคล้ายกันมาก ในฐานะที่เป็นบุคคลที่ค่อนข้างโดดเดี่ยวและมีความรับผิดชอบไม่รู้จบ ฉันเข้าใจว่าคุณรู้สึกอย่างไร ฉันยินดีรับฟังหากคุณต้องการใครสักคนที่จะพูดคุยด้วย",
  str_voice_1601991_10 = "คุณเหนื่อยไหม? การปล่อยวางบ้างสามารถช่วยเปลี่ยนความคิดของคุณได้ แต่ถ้าคุณรู้สึกเหนื่อย คุณควรพักผ่อนจริงๆ",
  str_voice_1601991_11 = "การได้เห็นสถานที่เดียวกันกับคุณนั้นยอดเยี่ยมมาก",
  str_voice_1601991_12 = "วิกฤตการณ์ทำให้เรามีโอกาสที่จะจัดกลุ่มใหม่ เราเพียงแค่ต้องสงบสติอารมณ์และค้นหาสาเหตุของปัญหา",
  str_voice_1601991_13 = "ทุกคนมีหลักการของตัวเองที่ดำเนินชีวิตตาม และของฉันคือการมุ่งเน้นไปที่ภาพรวม เมื่อจำเป็นต้องชั่งน้ำหนักตัวแปรหลายตัว ฉันจะดูสถานการณ์โดยรวมเสมอ",
  str_voice_1601991_14 = "ทั้งการโต้กลับและการป้องกันของศัตรูจะถ่ายทอดข้อมูลอันมีค่าเกี่ยวกับพฤติกรรมของพวกมัน ดังนั้นทุกการโจมตีจึงมีความหมาย",
  str_voice_1601991_15 = "ถ้าคุณมีคำอวยพรวันเกิด อย่าพูดออกมาดังๆ อย่างไรก็ตาม สุขสันต์วันเกิด!",
  str_voice_1601991_16 = "ฉันจะทำอะไรให้คุณได้บ้าง? หรือบางทีฉันควรจะพูดว่า... ดีใจที่ได้พบคุณ",
  str_voice_1601991_17 = "สวัสดีตอนเช้า. ฉันเพิ่งแต่งตัวเสร็จ วันนี้ฉันดูเป็นอย่างไร",
  str_voice_1601991_18 = "ในยามพลบค่ำ แสงตะวันลับขอบฟ้ายามพลบค่ำ คุณอยากเดินเล่นกับฉันไหม",
  str_voice_1601991_19 = "มันดึกแล้ว แต่อย่างใดฉันยังตื่นอยู่",
  str_voice_1601991_20 = "เทคโนโลยีใหม่ทั้งหมดของ Illumina มีไว้เพื่อปกป้องผู้คน",
  str_voice_1601991_21 = "ประแจ Rediesel หละหลวมเกินไป พวกเขาควรให้ความสำคัญกับการจัดการตนเองมากขึ้น",
  str_voice_1601991_22 = "ขออิลลูมินาจงเจิดจำรัส",
  str_voice_1601991_23 = "ตราบใดที่ยังมีคนที่ทนทุกข์ภายใต้การกดขี่ของ Eclipsites ฉันจะพยายามทำงานหนักขึ้นเสมอ",
  str_voice_1601991_24 = "Axelia เป็นเด็กที่เติบโตมาโดยถูกทอดทิ้ง สิ่งนี้ทำให้เธอเข้าใจอารมณ์ที่แท้จริงได้ยาก",
  str_voice_1601991_25 = "ความไร้เดียงสาไม่ใช่เรื่องเลวร้าย อย่างน้อยในกรณีของฌอน ดูเหมือนว่าจะเป็นลักษณะนิสัยที่น่ารักเป็นพิเศษ",
  str_voice_1601991_26 = "ฉันชอบชีสหวานและนมสด อืม... มันธรรมดาเกินไปหรือเปล่า?",
  str_voice_1601991_27 = "ฉันเกลียดความรู้สึกที่มีน้ำอัดลมอยู่ในคอ บางครั้งก็ทำให้ฉันสะอึกเหมือนคนบ้า",
  str_voice_1601991_28 = "การมีอยู่ของ Colossi พิสูจน์ศักยภาพที่ยากจะหยั่งถึงของเทคโนโลยี คุณจะไม่เห็นด้วยไหมว่านี่เป็นสิ่งที่ควรค่าแก่การพิจารณา?",
  str_voice_1601991_29 = "ฉันชื่อ อิงเกล ในฐานะหัวหน้าเจ้าหน้าที่ข่าวกรองของ Illumina's Science Council ฉันสามารถจัดหากลยุทธ์ในสนามรบให้คุณได้ โดยที่คุณถือว่าฉันเป็นเพื่อนที่ไว้ใจได้",
  str_voice_1601991_30 = "นี่เป็นส่วนหนึ่งของแผนของฉันด้วย",
  str_voice_1601991_31 = "อืม... ปืนอาจจะลั่นก็ได้นะ ระวังด้วย",
  str_voice_1601991_32 = "กระสุนนี้ได้รับการดัดแปลงหรือไม่?",
  str_voice_1601991_33 = "ไม่จำเป็นต้องลังเลอีกต่อไป",
  str_voice_1601991_34 = "ฉันอยู่ที่นี่",
  str_voice_1601991_35 = "บรรจุกระสุนแล้ว",
  str_voice_1601991_36 = "ล็อกเป้าหมาย",
  str_voice_1601991_37 = "ช็อตสวย!",
  str_voice_1601991_38 = "ฟาดเรียบ!",
  str_voice_1601991_39 = "ปล่อยให้กระสุนบิน!",
  str_voice_1601991_40 = "เป๊ะเว่อร์!",
  str_voice_1601991_41 = "สั่งของได้เก่งมากค่ะ",
  str_voice_1601991_42 = "มันเป็นส่วนหนึ่งของแผนทั้งหมด",
  str_voice_1601991_43 = "คงต้องวางแผนกันใหม่...",
  str_voice_1601991_44 = "ฉันจะทำให้ Aoha บินอย่างระมัดระวัง ฉันไม่อยากสร้างปัญหากับยักษ์ใหญ่ของคุณ",
  str_voice_1601991_45 = "นี้สำหรับฉัน? ขอบคุณ",
  str_voice_1601991_46 = "ฉันชอบเวลาที่คุณเอะอะโวยวายใส่ฉัน",
  str_voice_1601991_47 = "ฉันเห็นว่านี่เป็นหลักฐานยืนยันการอนุมัติของคุณ",
  str_voice_1601991_48 = "ฉันจะเก็บสมบัตินี้ไว้พร้อมกับของริบอื่นๆ",
  str_voice_1601991_49 = "เมื่อฉันอายุสี่ขวบ พ่อแม่ของฉันฝากฉันไว้กับศาสตราจารย์ Ulysses ก่อนออกเดินทางไปสนามรบ หลังจากนั้นไม่นาน ข่าวร้ายก็มาถึงว่าพวกเขาสละชีวิตเพื่ออิลลูมินา",
  str_voice_1601991_50 = "ครั้งหนึ่งฉันเคยได้รับคำชมมากมาย แต่นั่นไม่ใช่เพราะความสามารถของฉันได้รับการยอมรับ พวกเขาหวังเพียงให้ฉันได้รับผิดชอบอนาคตของอิลลูมินา",
  str_voice_1601991_51 = "เพื่อเป็นรางวัลสำหรับการผ่านการทดสอบ ศาสตราจารย์ได้มอบอุปกรณ์จับแมลงที่ฉันตั้งชื่อว่า Aoha ให้กับฉัน ฉันรู้ว่ามันไม่ใช่แค่ของขวัญที่ไร้เดียงสา นอกจากนี้ยังทำหน้าที่เป็นเครื่องเตือนใจให้ระมัดระวังในเรื่องต่าง ๆ ...",
  str_voice_1601991_52 = "Alchemy Stars",
  str_voice_1601991_53 = "สวัสดี",
  str_voice_1601991_54 = "อรุณสวัสดิ์ หลับสบายมั้ย",
  str_voice_1601991_55 = "สวัสดีตอนบ่าย PlayerName",
  str_voice_1601991_56 = "อ้าว ค่ำแล้ว",
  str_voice_1601991_57 = "สวัสดีปีใหม่! ฉันหวังว่าฉันจะได้พบคุณในเวลานี้ในปีหน้าเช่นกัน",
  str_voice_1502001_1 = "สิ่งมีชีวิตทั้งหมดมีข้อมูลมากมายเกี่ยวกับตัวเอง ด้วยความเฉลียวฉลาดที่เพียงพอ เราสามารถวิเคราะห์รูปแบบพฤติกรรมและแรงจูงใจของสิ่งมีชีวิต และแม้แต่ทำนายได้ในระดับหนึ่ง",
  str_voice_1502001_2 = "หืม...หืม? คุณโทรหาฉันไหม ไม่ ฉันไม่ได้หลับ ฉันแค่สังเกตคุณและคนอื่นๆ บนยักษ์ใหญ่นี้",
  str_voice_1502001_3 = "Caelestites มีความสามารถทางจิตที่ Aurorians ไม่มี ความสามารถนี้ไม่เพียงแต่มีประโยชน์ในการต่อสู้เท่านั้น แต่ยังมีประโยชน์อย่างมากในการรวบรวมข้อมูลอีกด้วย",
  str_voice_1502001_4 = "อย่าปล่อยให้ความรู้ที่มีอยู่ทำให้คุณเข้าใจผิด ในฐานะเจ้าหน้าที่ข่าวกรอง ฉันไม่ค่อยมีส่วนร่วมในการต่อสู้ แต่นั่นไม่ได้หมายความว่าฉันไม่เก่งในเรื่องนี้",
  str_voice_1502001_5 = "เจ้าหน้าที่ข่าวกรองควรตั้งเป้าหมายที่จะหลีกเลี่ยงการสู้รบที่ไม่จำเป็นทุกครั้งที่ทำได้ แต่ถ้าเป็นคำสั่งของคุณ ฉันจะไม่ปฏิเสธ",
  str_voice_1502001_6 = "ฉันคิดว่าคุณคงรู้ถึงความสามารถและข้อจำกัดของฉัน... ดังนั้น โปรดให้คำสั่งใด ๆ ที่คุณเห็นสมควรแก่ฉัน แล้วฉันจะนำข่าวกรองที่จะนำเราไปสู่ชัยชนะมาให้คุณ",
  str_voice_1502001_7 = "คำบอกเล่าไม่สามารถใช้เป็นปัญญาได้ ข้อมูลต้องได้รับการยืนยัน... ตัวอย่างเช่น ฉันเพิ่งเริ่มเข้าใจว่าคุณเป็นคนแบบไหนหลังจากได้รู้จักคุณ",
  str_voice_1502001_8 = "ในสนามรบ อาวุธและสติปัญญาก็ไม่สำคัญไปกว่าความเชื่อใจ เมื่อก่อนตอนเป็นแมวมองผมทำคนเดียวไม่เข้าใจความหมายของความไว้เนื้อเชื่อใจ แต่ตอนนี้ ต่างออกไป",
  str_voice_1502001_9 = "คุณต้องการดูสมุดบันทึกของฉันไหม อืม... คุณสามารถดูได้เฉพาะส่วนที่ไม่เกี่ยวข้องกับข้อมูลที่เป็นความลับของ Illumina และคุณไม่สามารถเปิดเผยเนื้อหาในบันทึกของฉันแก่บุคคลภายนอกได้ คุณไม่ได้รับอนุญาตให้ขีดเส้นขยุกขยิกเช่นกัน",
  str_voice_1502001_10 = "คุณยังไม่พักผ่อนเหรอ PlayerName? ถ้าอย่างนั้น ผมขอใช้เวลาว่างนี้จัดระเบียบข่าวกรองที่เพิ่งรวบรวมมา",
  str_voice_1502001_11 = "คุณขอความช่วยเหลือจากฉัน... ฉันมีประสบการณ์ไม่มากนัก แต่ถ้าคุณให้ข้อมูลโดยละเอียดเกี่ยวกับงานนี้ได้ ฉันจะพยายามทำให้ดีที่สุด",
  str_voice_1502001_12 = "นี่คือปลาสัตว์เลี้ยงของฉัน Bubble ซึ่งฉันพบในหนองน้ำใกล้กับ Dark Zone คุณสามารถสัมผัสได้หากต้องการ วางใจได้ มันเป็นเพียงสิ่งมีชีวิตธรรมดาและไม่ได้เป็นอันตรายแต่อย่างใด",
  str_voice_1502001_13 = "กรุณาอย่ายุ่งกับโน๊ตบุ๊คของฉัน มันไม่ได้เป็นเพียงเครื่องมือสำหรับบันทึกข่าวกรอง แต่ยังเป็นอาวุธอีกด้วย",
  str_voice_1502001_14 = "ทุกการกระทำทิ้งร่องรอยไว้ ไม่ว่าคุณจะพยายามปกปิดอย่างไร ความฉลาดจะไม่หายไปในอากาศ การสังเกตอย่างรอบคอบเพียงเล็กน้อยและทุกอย่างก็กระจ่าง",
  str_voice_1502001_15 = "ตามสติปัญญาของฉัน วันนี้เป็นวันเกิดของคุณ สุขสันต์วันเกิด. ทุกคนที่ทราบข้อมูลนี้จะต้องรอคุณด้วยคำอวยพรที่อบอุ่น",
  str_voice_1502001_16 = "ยินดีต้อนรับกลับ. ปัญญาถูกจัดตารางงานแล้ว กรุณาดู",
  str_voice_1502001_17 = "สวัสดีตอนเช้า. ดูเหมือนว่าคุณเป็นคนที่ขาดงานไม่ได้",
  str_voice_1502001_18 = "สวัสดีตอนเย็น. ใกล้จะถึงเวลาพักแล้ว คุณจึงไม่จำเป็นต้องบังคับตัวเองให้ทำงานต่อไป และไม่มีเหตุผลใดที่คุณไม่ควรพักผ่อนเป็นครั้งคราว",
  str_voice_1502001_19 = "ดึกมากแล้ว...ยังไม่นอนอีกเหรอ?",
  str_voice_1502001_20 = "สหพันธ์อิลลูมินาเป็นสถานที่ที่มีอยู่เพื่อความสุขของทุกคน อย่างน้อยนั่นคือสิ่งที่ฉันเชื่อ",
  str_voice_1502001_21 = "Northland อยู่ใกล้กับ Dark Zone เช่นกัน แต่มีภูเขาและ Beacon คอยปกป้อง ความสงบสุขสบายเช่นนี้ช่างน่าอิจฉาเสียจริง",
  str_voice_1502001_22 = "ขออิลลูมินาจงเจิดจำรัส",
  str_voice_1502001_23 = "ไม่ว่าคุณจะพบตัวเองที่ไหน Eclipsites เป็นสิ่งมีชีวิตที่นำปัญหาและอันตรายมาให้ โปรดระวัง.",
  str_voice_1502001_24 = "จอมพลเป็นผู้นำที่เชื่อถือได้ นี่คือข้อสรุปที่ฉันได้หลังจากการสังเกตอย่างรอบคอบ",
  str_voice_1502001_25 = "บางครั้งฉันพบว่าตัวเองถูกบังคับให้บ่นกับผู้บัญชาการบาร์ตัน ฉันหวังว่าเขาจะใจเย็นลงอีกหน่อย",
  str_voice_1502001_26 = "ฉันชอบเลี้ยงปลา—คุณแปลกใจไหม นี่คือสิ่งที่เกิดขึ้นเมื่อคุณขาดสติปัญญา",
  str_voice_1502001_27 = "ความเชื่อที่มืดบอดไม่ใช่เรื่องดี อาจส่งผลต่อการตัดสินใจของผู้บัญชาการ",
  str_voice_1502001_28 = "ความฉลาดเกี่ยวกับ Colossi ใน Illumina นั้นหายาก... คุณจะให้ฉันไปดูรอบๆ ไหม?",
  str_voice_1502001_29 = "Caelestite บิน Colossus ... คุณคือคนนั้นจริงๆ อนาโตลี เจ้าหน้าที่ข่าวกรองแห่งสหพันธ์อิลลูมินา ยินดีช่วยเหลือคุณ กรุณาให้คำสั่งของคุณ",
  str_voice_1502001_30 = "การสะสมประสบการณ์การต่อสู้เป็นวิธีการรวบรวมสติปัญญา",
  str_voice_1502001_31 = "อัพเกรดความแม่นยำของข่าวกรอง",
  str_voice_1502001_32 = "แผนการต่อสู้ใหม่ได้ถูกร่างขึ้น",
  str_voice_1502001_33 = "แผนพร้อมที่จะดำเนินการ",
  str_voice_1502001_34 = "เข้าใจแล้ว",
  str_voice_1502001_35 = "กลยุทธ์ใหม่ที่วางแผนไว้สำเร็จ",
  str_voice_1502001_36 = "ถ้าพร้อมแล้วก็ลุยเลย",
  str_voice_1502001_37 = "ทำลายกระบวนทัพของศัตรู",
  str_voice_1502001_38 = "แฝงเร้นซ่อนเร้นในเงามืด",
  str_voice_1502001_39 = "จุดอ่อนอยู่ที่",
  str_voice_1502001_40 = "โอกาสของเรามาถึงแล้ว",
  str_voice_1502001_41 = "น้อมรับบัญชา",
  str_voice_1502001_42 = "ชัยชนะที่หลีกเลี่ยงไม่ได้",
  str_voice_1502001_43 = "สติปัญญาของเราบกพร่อง...ถอยไปก่อน",
  str_voice_1502001_44 = "ไม่ต้องกังวลเกี่ยวกับฉัน ฉันแค่สังเกตคนอื่น ๆ และรวบรวมข้อมูล",
  str_voice_1502001_45 = "ขอบใจสำหรับของขวัญนะ",
  str_voice_1502001_46 = "คุณ... ศึกษาความชอบของฉันโดยเฉพาะแล้วหรือยัง?",
  str_voice_1502001_47 = "เมื่อคุณเลือกของขวัญให้ผู้อื่น สิ่งของที่คุณเลือกจะสะท้อนถึงรสนิยมและความชอบของคุณเองด้วย",
  str_voice_1502001_48 = "ขอบคุณ ฉันชอบของขวัญชิ้นนี้มาก",
  str_voice_1502001_49 = "ไม่มีใครเกิดมาเป็นเจ้าหน้าที่ข่าวกรอง ฉันเริ่มต้นจากการเป็นแมวมอง สะสมประสบการณ์และฝึกฝนตัวเองจนในที่สุดฉันก็เป็นฉันในทุกวันนี้",
  str_voice_1502001_50 = "การเลี้ยงปลาเลี้ยงเป็นงานที่ต้องใช้เวลามาก ซึ่งต้องให้อาหารอย่างสม่ำเสมอ ทำความสะอาดสาหร่ายสีเขียวจากตู้ปลา และให้ความสนใจกับสุขภาพของปลาอย่างสม่ำเสมอ... อย่างไรก็ตาม Bubble มีสุขภาพดีอยู่เสมอ อาจเป็นเพราะมันอาศัยอยู่ใน คืนนิรันดร์ก่อน",
  str_voice_1502001_51 = "การไว้วางใจใครสักคนหมายความว่าคุณเต็มใจที่จะมอบความปลอดภัยและแม้แต่ชีวิตของคุณให้กับบุคคลอื่น ไม่สำคัญว่าคุณจะเป็นทหารราบธรรมดาหรือเจ้าหน้าที่ข่าวกรอง",
  str_voice_1502001_52 = "Alchemy Stars",
  str_voice_1502001_53 = "สวัสดี PlayerName",
  str_voice_1502001_54 = "อรุณสวัสดิ์",
  str_voice_1502001_55 = "สวัสดี",
  str_voice_1502001_56 = "เริ่มมืดแล้ว...",
  str_voice_1502001_57 = "สวัสดีปีใหม่, PlayerName. ในปีใหม่ โปรดให้ฉันรวบรวมข่าวกรองสำหรับคุณและให้ความช่วยเหลือเกี่ยวกับ Colossus",
  str_voice_1602011_1 = "ฉัน... ฉันไม่ได้ใส่ชุดสีแบบนี้มานานแล้ว มันดูดีกับฉันไหม? ฮี่ฮี่ น่าอายเล็กน้อย",
  str_voice_1602011_2 = "ไม่จำเป็นต้องเอาชีวิตคู่ต่อสู้มาสู้หรอก จริงไหม? ใช่ ฉันเข้าใจว่านักรบผู้ยิ่งใหญ่เท่านั้นที่มีสิทธิพิเศษในการเลือกความเห็นอกเห็นใจ และฉันยังห่างไกลจากสิ่งนั้น...",
  str_voice_1602011_3 = "ว้าว คนเยอะเต็มถนนเลย พวกเขากำลังทำอะไร? ฉันจะจัดลำดับความสำคัญของงานให้เสร็จ! แต่ฉันหวังว่าพระอาทิตย์จะยังคงส่องแสงเมื่อฉันทำเสร็จแล้ว...",
  str_voice_1602011_4 = "เมื่อตอนที่ฉันยังเด็ก ฉันรู้สึกหดหู่และหมดหนทางไม่ว่าจะพยายามมากแค่ไหน... ตอนนี้ฉันต่อสู้เพื่อเป้าหมายของตัวเองเท่านั้น และในใจฉันก็ง่ายขึ้นมาก",
  str_voice_1602011_5 = "ชื่อเรื่องเป็นสิ่งที่ยอดเยี่ยมมาก พวกเขาสามารถใส่กุญแจมือคุณหรือให้พลังที่ไร้ขีด จำกัด แต่อย่าไปยึดติดกับมัน...",
  str_voice_1602011_6 = "ถ้าก่อนหน้านี้ฉันกล้าหาญเหมือนตอนนี้... ไม่ มันไม่มีประโยชน์ที่จะไตร่ตรองเรื่องเหล่านี้ สิ่งสำคัญคือการปกป้องสิ่งที่คุณหวงแหนในตอนนี้ใช่ไหม?",
  str_voice_1602011_7 = "ฉันแตกต่างจากเมื่อก่อน ไม่รู้สึกต่ำต้อยหรือควบคุมตัวเองไม่ได้...ก็จริง! งั้นเชื่อใจฉันอีกหน่อยได้ไหม?",
  str_voice_1602011_8 = "ได้โปรดอย่าประกันตัวฉันตลอดเวลา ไม่ มันไม่ลำบาก ก็แค่... ฉันคิดว่าฉันควรจะปกป้องเธอ",
  str_voice_1602011_9 = "ให้ฉันบอกความลับแก่คุณ: บางครั้งมือของฉันก็สั่นในการต่อสู้ รบกวนขอความกล้าหน่อยได้มั้ยคะ? โอ้มือของคุณอบอุ่นจริงๆ ...",
  str_voice_1602011_10 = "เลือกช่อดอกกุหลาบ ♪ สำหรับพ่อกับแม่ที่รักของฉัน ♪... ขออภัย! แถวนี้เงียบเกินไปจนชินแล้ว... เฮ้อ เห็นยังอยู่คนเดียว...",
  str_voice_1602011_11 = "ไม่ต้องกังวล หายใจเข้าลึกๆ... หายใจเข้า หายใจออก... อะแฮ่ม ไม่มีปัญหา ฉันจัดการงานได้ ฉันได้สิ่งนี้!",
  str_voice_1602011_12 = "ไม่ว่าคนอื่นจะว่าอย่างไร ฉันจะเป็นน้องสาวของคาร์ลีนเสมอ เช่นเดียวกับ... ลูกสาวของโจชัว ไม่มีเกียรติยศอันต่ำต้อยใดที่สามารถทำลายสายสัมพันธ์ของครอบครัวได้",
  str_voice_1602011_13 = "ฉันมี... เพื่อนคนหนึ่งชื่อ บาบา ยากะ ที่เคยค่อนข้างโหด แต่เดี๋ยวนี้ไม่แล้ว อย่าตกใจถ้ามีโอกาสพบเธอ โอเค?",
  str_voice_1602011_14 = "ฉันขูดหัวเข่าของฉันในการฝึกซ้อมและมันเจ็บ ... อะไรนะ? ไม่สิ เป็นแค่แผลเนื้อเท่านั้น! ฉันมีน้ำตาคลอเบ้า? *สูดจมูก* ไม่ ฉันไม่...",
  str_voice_1602011_15 = "สุขสันต์วันเกิด. ดีใจที่ได้เติบโต",
  str_voice_1602011_16 = "คุณควรออกไปข้างนอกทุกครั้งที่คุณว่าง ถนนสวยในตอนกลางวัน",
  str_voice_1602011_17 = "สวัสดีตอนเช้าและเป็นเช้าที่วิเศษมาก ดูแลชาตอนเช้า?",
  str_voice_1602011_18 = "เริ่มมืดแล้ว... ไม่เป็นไร ฉันชินกับความมืดแล้ว",
  str_voice_1602011_19 = "ดึกดื่นขนาดนี้ยังยุ่งอยู่อีกเหรอ? ฉันเดาว่ามันเหมือนกันสำหรับทุกคนที่มีภาระหน้าที่ที่สำคัญ",
  str_voice_1602011_20 = "แม้ว่าฉันจะทำได้เพียงเฝ้าดูบ้านของฉันจากที่ไกลๆ แต่ฉันก็จะยังคงปกป้องมันด้วยกำลังทั้งหมดของฉัน",
  str_voice_1602011_21 = "Umbraton เป็นสถานที่ที่ดี ผู้คนจาก Lumopolis ควรมาเยี่ยมชมบ่อยขึ้น",
  str_voice_1602011_22 = "White Night up high... ฮ่าๆ นั่นทำให้ความทรงจำกลับมา",
  str_voice_1602011_23 = "คุณเกลียด Eclipsites? แล้ว Eclipsites ที่กลายเป็น Aurorians ล่ะ?",
  str_voice_1602011_24 = "คาร์ลีนกับแม่... ฉันหวังว่าเราจะทำได้เสมอ—ไม่ ไม่เป็นไร",
  str_voice_1602011_25 = "ชื่อชวาร์ตษ์ไม่สำคัญพอที่ฉันจะอยู่ภายใต้เงาของเขาต่อไป",
  str_voice_1602011_26 = "เพลิดเพลินกับชาดำของอัศวินในร้านกาแฟเล็กๆ คนเดียวในยามบ่าย... เหมาะเป็นอย่างยิ่ง",
  str_voice_1602011_27 = "ไม่เป็นไร จัดการตัวเองได้หลายอย่างไม่เดือดร้อนคนอื่น...",
  str_voice_1602011_28 = "ที่นี่คนแน่นมาก...มีทั้งคนที่ฉันอยากเจอและคนที่ไม่อยากเจอ",
  str_voice_1602011_29 = "สวัสดี ให้ฉันดูว่าฉันจะแนะนำตัวเองอย่างไร... เวโรนิก้า? ไม่ เรียกฉันว่าเมีย เมียหลวงควรทำ",
  str_voice_1602011_30 = "ต้องหมั่นฝึกฝน...",
  str_voice_1602011_31 = "ฉันคิดว่าฉันเชี่ยวชาญแล้ว!",
  str_voice_1602011_32 = "ฉันเป็นอัศวิน... ฉันไม่ได้อ่อนแอ!",
  str_voice_1602011_33 = "ถ้าฉันมีอำนาจเร็วกว่านี้...",
  str_voice_1602011_34 = "ฉันจะทำให้ดีที่สุด...!",
  str_voice_1602011_35 = "ฉันพร้อมแล้ว!",
  str_voice_1602011_36 = "โปรดอย่ากลัว...",
  str_voice_1602011_37 = "พบกับพลังของฉัน!",
  str_voice_1602011_38 = "พบกับตัวตนที่แท้จริงของฉัน!",
  str_voice_1602011_39 = "เอานี่ไปกินนี่ซะ!",
  str_voice_1602011_40 = "ไม่มีอะไรรั้ง!",
  str_voice_1602011_41 = "ทุกคน...ตามฉันมา!",
  str_voice_1602011_42 = "ว-เราชนะ... เราชนะแล้ว!",
  str_voice_1602011_43 = "ถอนหายใจ ยังไม่ดีพอ...",
  str_voice_1602011_44 = "ทักทาย. คุณเป็นอย่างไรเมื่อเร็ว ๆ นี้? เฮ้ ฉันไม่ได้พูดแบบนั้นมาพักนึงแล้ว",
  str_voice_1602011_45 = "ขอบคุณ",
  str_voice_1602011_46 = "เฮ้ นี่มันอะไรกัน...",
  str_voice_1602011_47 = "มีอะไรงั้นเหรอ?",
  str_voice_1602011_48 = "แค่เธอรู้จักฉันดี...",
  str_voice_1602011_49 = "\"เวโรนิกา\" ลูกสาวคนโตของลอร์ดเมืองลูโมโปลิส...และจุดด่างพร้อยของตระกูลชวาร์ตษ์ นั่นคือประวัติศาสตร์ของชุดนี้",
  str_voice_1602011_50 = "“บาบา ยากะ” แมงมุมสีดำรูปร่างคล้ายอสุรกาย เธอไม่ตาย แต่รวมร่างกับ Mia กลายเป็นฉันอย่างที่คุณเห็นตอนนี้",
  str_voice_1602011_51 = "ฉันยังเป็นเมียหลวง...และเป็นได้แค่เมียหลวง แต่นั่นไม่ใช่นามแฝงที่คนอื่นตั้งให้ฉัน เป็นทางที่ฉันเลือกเอง",
  str_voice_1602011_52 = "Alchemy Stars",
  str_voice_1602011_53 = "ขอโทษทีนะ...",
  str_voice_1602011_54 = "ชาดำหอมมาก...",
  str_voice_1602011_55 = "สวัสดีตอนบ่าย. ฉันไม่ได้ก้าวก่าย ฉัน...?",
  str_voice_1602011_56 = "อืม สวัสดีตอนเย็น...",
  str_voice_1602011_57 = "สวัสดีปีใหม่. ถนอมมันด้วยการใช้เวลากับคนที่รัก",
  str_voice_1602021_1 = "ฝนกำลังตก. ลูกสาวคนโตของฉันชอบฝนและวิธีที่เม็ดฝนทำให้ดอกไวโอเล็ตเด้งขึ้นและลง ...เธอเข้าใจยาก",
  str_voice_1602021_2 = "ขณะที่ฉันมองดู Lumopolis อันกว้างใหญ่ ฉันถามตัวเองว่าฉันสมควรที่จะเป็นผู้นำผู้คนในนั้นหรือไม่ ฉันต้องกระตุ้นตัวเองอยู่เสมอเพื่อปกครองดินแดนนี้ซึ่งแสดงถึงความศักดิ์สิทธิ์",
  str_voice_1602021_3 = "ฉันเป็นนักสนทนาที่ดีจริงๆ แม้ว่าจะมีไม่กี่คนที่มีโอกาสพูดคุยกับฉัน อย่างไรก็ตาม คุณเป็นหนึ่งในข้อยกเว้น",
  str_voice_1602021_4 = "Eclipsites นำมาซึ่งความมืด แต่รุ่งอรุณใกล้เข้ามา เราจะบดขยี้พวกเขาจนไม่เหลือซาก",
  str_voice_1602021_5 = "สงครามอยู่ที่จุดสูงสุด ยิ่งเราเข้าใกล้ชัยชนะมากเท่าไหร่",
  str_voice_1602021_6 = "อำนาจคือแก่นสารของการเป็นผู้นำ ฉันจะใช้พลังนั้นเพื่อนำทุกคนไปสู่ชัยชนะในสงคราม",
  str_voice_1602021_7 = "ในฐานะผู้ปกครอง จำเป็นต้องชัดเจนในความโกลาหล",
  str_voice_1602021_8 = "ฉันชอบอ่านตำราประวัติศาสตร์มากกว่า ฉันยินดีที่จะใช้เวลาว่างสักสองสามชั่วโมงเพื่ออ่านหนังสือคลาสสิกที่มีชื่อเสียงบางเล่ม",
  str_voice_1602021_9 = "บางคนคิดว่าฉันตามใจลูกมากเกินไป แต่อนาคตยังอีกยาวไกล ดังนั้นมันจึงคุ้มค่าถ้าสิ่งนี้จะช่วยให้พวกเขาหลีกเลี่ยงปัญหาได้",
  str_voice_1602021_10 = "เราไม่สามารถบรรลุสิ่งที่สำคัญด้วยทัศนคติที่ไม่เป็นทางการและกล้าหาญ ถ้าฉันไม่รับผิดชอบเหมือนคุณ เรื่องมากมายในลูโมโปลิสคงยุ่งเหยิง",
  str_voice_1602021_11 = "เวลาและความสนใจของฉันถูกรับประกันจริง ๆ สำหรับเรื่องเล็กน้อยเช่นนี้หรือไม่?",
  str_voice_1602021_12 = "แม้จะยังเด็กมาก แต่ Carleen ก็แสดงความเฉลียวฉลาดเกินวัย แม้ว่าเธออาจไม่รู้ตัว แต่ในฐานะพ่อ ฉันภูมิใจในตัวเธอ",
  str_voice_1602021_13 = "แน่นอนว่าการโจมตีสำคัญกว่าการป้องกัน การโจมตีที่รุนแรงสามารถครอบงำศัตรูที่ขี้ขลาดและเปิดเผยความเปราะบางมากขึ้น",
  str_voice_1602021_14 = "น่าเสียใจที่ทุกคนที่อยากได้บัลลังก์ต้องพบกับ—หรือจะพบกับ—การล่มสลายในท้ายที่สุดโดยไม่มีข้อยกเว้น เนื่องจากความรุ่งโรจน์ของราชวงศ์ชวาร์ตษ์จะคงอยู่ตลอดไป",
  str_voice_1602021_15 = "สุขสันต์วันเกิด. พรนี้มาจากทั้งฉันและ Lumopolis",
  str_voice_1602021_16 = "นั่นแหละ. อย่าลืมลาดตระเวนดินแดนของคุณให้บ่อยขึ้น",
  str_voice_1602021_17 = "คุณยังเร็วพอที่จะดื่มชากับฉัน",
  str_voice_1602021_18 = "ยืดเหยียดร่างกายและผ่อนคลายจิตใจเพื่อปรับปรุงประสิทธิภาพการทำงานของคุณ",
  str_voice_1602021_19 = "โดยปกติจะเป็นตอนที่ฉันทบทวนวาระการประชุมสำหรับวันพรุ่งนี้",
  str_voice_1602021_20 = "ภายใต้การนำของฉัน ลูโมโพลิสจะเปิดรับอนาคตที่รุ่งเรืองและสดใสยิ่งขึ้น",
  str_voice_1602021_21 = "ไม่ต้องสงสัยเลยว่าความมั่นคงและความเจริญรุ่งเรืองใน Umbraton เป็นประโยชน์ต่อ Lumopolis",
  str_voice_1602021_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1602021_23 = "Eclipsites กำลังโจมตีทุกที่เป็นจำนวนมาก ผู้บงการที่ซ่อนอยู่อยู่เบื้องหลังแผนการนี้อย่างแน่นอน",
  str_voice_1602021_24 = "โจชัวเป็นคนทำให้ฉันเป็นอย่างที่ฉันเป็น ไม่ใช่เลือกเธอ",
  str_voice_1602021_25 = "ตราบใดที่เวโรนิกาสามารถชี้นำไปสู่เส้นทางที่ถูกต้องได้ เธอจะสร้างความแตกต่าง",
  str_voice_1602021_26 = "ชาวออโรเรียนทุกคนควรจะชอบแสงแดด นั่นเป็นเหตุผลที่ฉันชอบวันที่มีแดด",
  str_voice_1602021_27 = "การให้ความเมตตาแก่ศัตรูในสนามรบก็เท่ากับการไม่แสดงความเมตตาต่อตนเอง ใช่หรือไม่?",
  str_voice_1602021_28 = "ให้ฉันวางหนังสือประวัติศาสตร์เกี่ยวกับ Colossus เพื่อช่วยให้คุณเข้าใจประวัติศาสตร์ของ Lumopolis",
  str_voice_1602021_29 = "เรา Schwartzes เคารพทุกคนที่แสดงภูมิปัญญาและความมั่งคั่ง เนื่องจากคุณได้รับการพิสูจน์แล้วว่าเป็นคนพิเศษ คุณจึงได้รับสิทธิ์ที่จะพูดคุยกับฉัน",
  str_voice_1602021_30 = "อำนาจมาพร้อมกับสิทธิอำนาจ",
  str_voice_1602021_31 = "ตั้งหน้าตั้งตารอรุ่งสาง",
  str_voice_1602021_32 = "มันเป็นรุ่งสาง",
  str_voice_1602021_33 = "ความชอบธรรมจะนำทาง Lumopolis!",
  str_voice_1602021_34 = "การตัดสินใจที่ถูกต้อง",
  str_voice_1602021_35 = "พร้อมที่จะไป!",
  str_voice_1602021_36 = "จะรออะไรอยู่ล่ะ?",
  str_voice_1602021_37 = "ชั่วคืนและวันไม่สิ้นสุด!",
  str_voice_1602021_38 = "Aurora Aeterna ใต้แสง!",
  str_voice_1602021_39 = "แสงแห่งไวท์ไนท์!",
  str_voice_1602021_40 = "ฟันดาบของอธิปไตย!",
  str_voice_1602021_41 = "ฉันจะเป็นผู้นำการเดินขบวน!",
  str_voice_1602021_42 = "ชัยชนะเป็นสิ่งที่แน่นอนและคาดหวัง",
  str_voice_1602021_43 = "ฉันไว้ชีวิตพวกเขาครั้งนี้",
  str_voice_1602021_44 = "อย่าประมาทดินแดนเล็กๆ แห่งนี้ เพราะแสงสว่างและอนาคตที่ไม่มีวันสิ้นสุดจะเกิดขึ้นที่นี่",
  str_voice_1602021_45 = "ตกลงฉันจะยอมรับมัน",
  str_voice_1602021_46 = "คุณต้องการอะไรตอบแทน?",
  str_voice_1602021_47 = "ฉันจะถนอมสิ่งนี้",
  str_voice_1602021_48 = "ฉันเป็นเจ้าของสมบัตินับไม่ถ้วน แต่ของขวัญชิ้นนี้ไม่เหมือนใคร",
  str_voice_1602021_49 = "Joshua มาจากรากเหง้าของพลเรือน ดังนั้น House Schwartz จึงห้ามการแต่งงานของเรา อย่างไรก็ตาม ฉันตัดสินใจแล้วว่าเธอคือคนๆ นั้นและเต็มใจที่จะพยายามอย่างเต็มที่",
  str_voice_1602021_50 = "การเป็นพ่อมีผลกับฉันมากกว่าการเป็นผู้ว่าราชการในภายหลัง เมื่อฉันเริ่มตระหนักถึงความหมายที่แท้จริงของความรับผิดชอบ",
  str_voice_1602021_51 = "การคุกคามของ Eclipsites ได้ทำลายความสงบสุขที่เราเคยมี เพื่อลูโมโปลิส เพื่อคนที่ไร้หนทาง เพื่อครอบครัวของฉัน ฉันต้องเดินขบวนเข้าสู่สนามรบ",
  str_voice_1602021_52 = "Alchemy Stars!",
  str_voice_1602021_53 = "เป็นอย่างไรบ้าง",
  str_voice_1602021_54 = "รุ่งอรุณจะชำระล้างทั้งหมด",
  str_voice_1602021_55 = "เป็นเวลาเที่ยงวัน ได้เวลาพัก",
  str_voice_1602021_56 = "มันสายแล้วนะ.",
  str_voice_1602021_57 = "อย่าลังเลที่จะเยี่ยมชม Lumopolis ในช่วงปีใหม่",
  str_voice_1502031_1 = "จากการตอบคำทำนายของคุณ ฉันแน่ใจว่าคุณเป็นคนที่หัวเราะเมื่อมีความสุข นอนหลับเมื่อเหนื่อยล้า และท้องร้องเมื่อหิว! อะไร คุณหมายถึงทุกคนเป็นเช่นนั้น?",
  str_voice_1502031_2 = "โทนสีเป็นแบบธรรมดาบน Colossus เรามาวาดลวดลายสีสันกันดีไหม? ทำไมจะไม่ล่ะ? มันไม่ใช่กราฟฟิตี ฉันสัญญา!",
  str_voice_1502031_3 = "เฮ้ ทำอะไรอยู่? นั่นอะไรน่ะ เสียงที่ดังของฉันทำให้คุณตกใจ มาได้อย่างไร? คุณกำลังทำอะไรลับๆ อยู่หรือเปล่า? ฮี่ฮี่ ไม่บอก!",
  str_voice_1502031_4 = "คุณดูเหนื่อย คุณมีคืนที่ยากลำบากหรือไม่? ฉันจะเล่าเรื่องให้คุณฟังได้อย่างไร \"ถ้ำลึกลับที่กลืนกินผู้คนได้ทั้งตัว\" จะทำให้คุณตื่นตาตื่นใจได้ในพริบตา!",
  str_voice_1502031_5 = "การมีความอดทนเท่า Jeriah มีพลังเหมือน Bethlehem ฉลาดเหมือน Mother นั่นเป็นเรื่องง่ายๆ!",
  str_voice_1502031_6 = "คุณกำลังเล่นเกมอะไร มันยากไหม? ฉันอยากลอง เราสองคนไม่น่าจะมีปัญหาอะไร!",
  str_voice_1502031_7 = "ตลาดจะเต็มไปด้วยสินค้ามากมายในสุดสัปดาห์นี้ ฉันอยากไปมาก! ไปเที่ยวกันเมื่อว่าง!",
  str_voice_1502031_8 = "เมื่อวานมีคนชวนฉันไปงานเลี้ยง แต่ฉันไม่ไปเพราะคุณไม่ไป แม้ว่าฉันจะชอบไอเดียการปาร์ตี้ แต่มันก็ไม่สนุกเลยถ้าไม่มีคุณ",
  str_voice_1502031_9 = "ช่วงนี้ฉันยุ่งมากกับการทำ Dreamcatcher คงจะฝันหวานน่าดู ฉันใช้ด้ายสีต่างๆ มากมายด้วย! ฉันจะมอบให้คุณเมื่อฉันทำเสร็จแล้ว!",
  str_voice_1502031_10 = "ครั้งที่แล้วคุณอ่านไม่สำเร็จ ดังนั้นฉันจึงตัดสินใจให้คุณอ่านฟรีในครั้งนี้ อะไรคุณไม่ต้องการมัน? แต่ครั้งนี้ได้ผลแน่นอน!",
  str_voice_1502031_11 = "สวัสดี ฉันมาที่นี่เพื่อสังสรรค์! ฉันจะเล่าเรื่องให้คุณฟังถ้าคุณอารมณ์ไม่ดี!",
  str_voice_1502031_12 = "ฉันเพิ่งทานสลัดผลไม้ที่อร่อยมากในคาเฟ่ สตรอเบอร์รี่สีแดง ส้มเขียวหวาน สับปะรดสีเหลือง... มันเหมือนกับจานสีของจิตรกร!",
  str_voice_1502031_13 = "คุณทำปากกาหายหรือไม่? ขอทำนายหน่อย... เอ่อ น่าจะอยู่ตู้ทางทิศตะวันตกเฉียงใต้นะ! อะไรนะ ยังหาไม่เจอ?",
  str_voice_1502031_14 = "สิ่งที่เราได้เห็นในตลาดครั้งล่าสุดอีกครั้งคืออะไร? โอ้ ใช่ ลูกโป่ง พวกเขาสวยมาก",
  str_voice_1502031_15 = "ว้าว เป็นวันเกิดของคุณแล้ว! มาจัดปาร์ตี้สุดยิ่งใหญ่กันเถอะ!",
  str_voice_1502031_16 = "วันนี้มีอะไรน่าสนใจเกิดขึ้นกับคุณไหม? โปรดแจ้งให้เราทราบ!",
  str_voice_1502031_17 = "สวัสดีตอนเช้า! มีงานสำคัญสำหรับวันนี้หรือไม่? ให้ฉันอ่านให้คุณ!",
  str_voice_1502031_18 = "เฮ้ มันมืดข้างนอก ไปชมวิวตอนกลางคืนกัน",
  str_voice_1502031_19 = "หนังสือทำนายของฉันชี้ให้เห็นว่าวิญญาณจะตื่นตัวมากขึ้นในตอนเย็น ดังนั้นฉันจึงตัดสินใจนอนทั้งคืน!",
  str_voice_1502031_20 = "ดินแดนทางเหนืออาจจะหนาวหน่อยแต่ช่างฝันราวกับเทพนิยาย",
  str_voice_1502031_21 = "Lumopolis สวย แต่ก็รู้สึกอึดอัดเหมือนหนังสือเรียนที่น่าเบื่อ",
  str_voice_1502031_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1502031_23 = "เอาเลย เราต้องอ่านวิธีหลีกเลี่ยง Eclipsites โดยสิ้นเชิง",
  str_voice_1502031_24 = "Miss Jeriah เจ๋งมาก อดทน และทรงพลัง ฉันจะทำอย่างไรให้เป็นเหมือนเธอ?",
  str_voice_1502031_25 = "ราชินีเบธเลเฮมช่างน่าประทับใจและงดงามยิ่งนัก ฉันไม่สามารถละสายตาไปได้ทุกครั้งที่เจอเธอ",
  str_voice_1502031_26 = "ฉันได้แต่งเรื่องใหม่ที่น่าตื่นเต้นขึ้นหลายเรื่อง อยากได้ยินไหม",
  str_voice_1502031_27 = "ทำไมผู้คนถึงหลอกหลอนฉัน มันน่ารำคาญ ฉันจะไม่หลอกใครเว้นแต่ฉันจะมาผิดเวลา... ฮี่ฮี่",
  str_voice_1502031_28 = "ถ้ามีเพียง Colossus ที่ใหญ่กว่าที่จะรองรับทุกคน เราคงมีปาร์ตี้ที่แท้จริง!",
  str_voice_1502031_29 = "ลูกบอลคริสตัลเรืองแสงเมื่อ Jakine ผู้ลึกลับ Divination Master เดินเข้ามา การเผชิญหน้าจะเป็นอย่างไร คอยติดตาม!",
  str_voice_1502031_30 = "เฮ้!",
  str_voice_1502031_31 = "สบายมาก!",
  str_voice_1502031_32 = "ฉันสุดยอดมาก!",
  str_voice_1502031_33 = "ฉันน่าทึ่งมาก!",
  str_voice_1502031_34 = "สวัสดีทุกคน!",
  str_voice_1502031_35 = "พร้อมเริ่มการทำนาย",
  str_voice_1502031_36 = "เวลาสำหรับการทำนาย",
  str_voice_1502031_37 = "ลูกบอลคริสตัล!",
  str_voice_1502031_38 = "ครอบคลุมแล้ว!",
  str_voice_1502031_39 = "สำเร็จตามคำทำนาย",
  str_voice_1502031_40 = "รู้สึกถึงอนาคต",
  str_voice_1502031_41 = "ไหวสิ!",
  str_voice_1502031_42 = "ทำนายฝัน!",
  str_voice_1502031_43 = "ดูดวงไม่สำเร็จ...",
  str_voice_1502031_44 = "ยิ่งใกล้ฟ้ายิ่งแม่นจริงไหม?",
  str_voice_1502031_45 = "โอ๊ะ! ขอบคุณ!",
  str_voice_1502031_46 = "ว้าว ของขวัญชิ้นนี้ยอดเยี่ยมมาก!",
  str_voice_1502031_47 = "เอาล่ะ ของขวัญอีกชิ้น!",
  str_voice_1502031_48 = "สุดยอด! ฉันรักมัน!",
  str_voice_1502031_49 = "แม่ของฉันก็เป็นปรมาจารย์ด้านการทำนายเช่นกัน และเธอก็เป็นซอสที่ยอดเยี่ยม! นี่ เอ่อ หนังสือทำนาย... เธอทิ้งฉันไว้กับสิ่งนี้",
  str_voice_1502031_50 = "Miss Jeriah เป็นครูของฉัน ดูสิ Whisper ดูเหมือนคนตายไปแล้วสำหรับ Sacred Python ของ Miss Jeriah ไม่ใช่หรือ มันไม่...?",
  str_voice_1502031_51 = "สถานที่ที่ฉันชอบไป? ก่อนหน้านี้คือ Lake Mirror, Northland Pine และ World's Spine... พวกเขาไม่พลุกพล่าน แต่ฉันสามารถสำรวจความลับของ Luminatics ได้ที่นั่น",
  str_voice_1502031_52 = "Alchemy Stars",
  str_voice_1502031_53 = "สวัสดี!",
  str_voice_1502031_54 = "อรุณสวัสดิ์!",
  str_voice_1502031_55 = "เที่ยงเป็นช่วงเวลาที่ยุ่งที่สุดของวัน",
  str_voice_1502031_56 = "เอาล่ะ ได้เวลานอนแล้ว",
  str_voice_1502031_57 = "เป็นช่วงเวลาที่มีชีวิตชีวาและมีความสุขที่สุดของปีอีกครั้ง มาเต้นรำและหัวเราะอย่างมีความสุขกันเถอะ!",
  str_voice_1602041_1 = "ฉันจะคิดถึงชาดำของ Lumopolis แน่นอน แต่ใครจะรู้ล่ะ? บางทีฉันอาจจะสะดุดกับชาอื่นที่ดีพอๆ กับที่อื่น ไม่สามารถรอเพื่อดูว่ามีอะไรอยู่ที่นั่น",
  str_voice_1602041_2 = "สภาพอากาศที่เปียกชื้นทำให้ทุกอย่างเหนียวเหนอะหนะ นั่นเป็นเหตุผลที่ฉันชอบอากาศที่มีแดด มันทำให้ทุกอย่างดูเป็นระเบียบ",
  str_voice_1602041_3 = "เด็กคนนั้น คนที่คุณเรียกว่ามีอา เธอแสดงความรู้สึกไม่เก่งนัก แต่ดูเหมือนเธอจะเปิดใจให้คุณเสมอ",
  str_voice_1602041_4 = "ดาบที่ยอดเยี่ยมคุณไม่คิดเหรอ? ไม่ใช่แค่การแสดงเท่านั้น ฉันจะจับมันไว้ให้แน่นและยืนหยัดเพื่อผู้คนให้ได้มากที่สุด",
  str_voice_1602041_5 = "คุณคิดว่าฝีมือดาบของฉันพัฒนาขึ้นไหม? ฮ่าๆ ฉันคิดว่าฉันเริ่มจะฟื้นคืนความหลงใหลที่เคยมี เพราะครั้งหนึ่งฉันเคยไล่เลี่ยกับใครบางคน...",
  str_voice_1602041_6 = "ความปรารถนาของฉันตั้งแต่อดีตจนถึงปัจจุบันคือการปกป้องทุกคนเสมอมา ไม่ใช่แค่ครอบครัวของฉัน ไม่ใช่แค่เพื่อนที่มาจากบ้านเกิดของฉัน...",
  str_voice_1602041_7 = "เพลงเบาๆ เบาๆ ช่วยสร้างบรรยากาศที่กลมกลืนกัน ลองเปิดเพลงสักสองสามเพลงในครั้งต่อไปที่เรามีแขกรับเชิญไหม?",
  str_voice_1602041_8 = "สิ่งที่ฉันรักมากกว่าสิ่งอื่นใดคือการได้เห็นผู้คนยิ้ม คุณต้องยิ้มให้มากขึ้นด้วย PlayerName. เด็กที่ชอบหัวเราะจะมีความโชคดีในชีวิตมากขึ้น",
  str_voice_1602041_9 = "โลกภายนอกแตกต่างจาก Lumopolis ในหลาย ๆ ด้าน ฉันควรตั้งจุดหมายต่อไปที่ใด คุณมีคำแนะนำอะไรดีๆ PlayerName?",
  str_voice_1602041_10 = "ดื่มน้ำน้ำผึ้งสักแก้ว—มันได้ผลอย่างมหัศจรรย์ในการบรรเทาความเหนื่อยล้าที่คุณไม่สามารถจะดื่มได้ เด็กดีควรเชื่อฟังผู้ใหญ่เสมอ",
  str_voice_1602041_11 = "แม้ว่าฉันจะไม่เหลวไหลเมื่อต้องจัดการเรื่องสำคัญ แต่สำหรับยักษ์ใหญ่นี้... ฉันยังไม่มีประสบการณ์มากนัก แต่เนื่องจากนี่เป็นคำขอของคุณ ในฐานะผู้อาวุโสของคุณ ฉันจะทำให้ดีที่สุด",
  str_voice_1602041_12 = "แม้ว่าโลกจะดูสิ้นหวังในบางครั้ง แต่ก็มีผู้คนพยายามทำให้โลกนี้น่าอยู่ขึ้นเสมอ และฉันเชื่อว่าคุณคือหนึ่งในนั้น",
  str_voice_1602041_13 = "สิ่งที่แม่หวังอย่างแท้จริงคือการได้เห็นลูก ๆ ออกจากรังและบินไปสู่ท้องฟ้าที่กว้างขึ้น คุณได้ทำอย่างนั้นแล้ว ฉันภูมิใจในตัวคุณ และฉันรู้ว่าแม่ของคุณก็เช่นกัน",
  str_voice_1602041_14 = "อดีตเป็นเหมือนการเดินทางที่ยอดเยี่ยม ฉันหยุดที่บางสถานีระหว่างทาง และหลังจากชมทิวทัศน์แล้วก็ได้เวลาไปต่อ",
  str_voice_1602041_15 = "PlayerNameฉันมั่นใจว่าคุณจะหล่อขึ้นเมื่อเวลาผ่านไป สุขสันต์วันเกิด!",
  str_voice_1602041_16 = "ตั้งหน้าตั้งตาทำงานให้หนักเข้าไว้!",
  str_voice_1602041_17 = "สวัสดีตอนเช้า! คุณทานอาหารเช้าแล้วหรือยัง?",
  str_voice_1602041_18 = "อย่าดื่มชาตอนดึก คุณอาจจะนอนไม่หลับ",
  str_voice_1602041_19 = "มันดึกแล้ว คุณคงจะเหนื่อย ดูแลตัวเองดีๆ นะ.",
  str_voice_1602041_20 = "ฉันรักทุกคนใน Lumopolis อย่างสุดซึ้ง นั่นคือเหตุผลที่ฉันเลือก... ที่จะจากไปก่อน",
  str_voice_1602041_21 = "Rediesel Wrench... ฟังดูเป็นสถานที่ที่น่าสนใจมาก!",
  str_voice_1602041_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1602041_23 = "ฉันเกลียดการกระทำที่บ้าบิ่นและชั่วร้ายมากกว่าเกลียดสุริยุปราคา",
  str_voice_1602041_24 = "เขายังเปลี่ยนไปอย่างมากในช่วงหลายปีที่ผ่านมา กาลเวลาได้ทิ้งรอยแผลลึกไว้บนตัวเขา...",
  str_voice_1602041_25 = "ตอนนี้ Carleen สามารถดูแลตัวเองได้แล้ว... เธอแข็งแรงกว่าที่ฉันเคยคิดไว้เสียอีก สิ่งนี้ทำให้ฉันโล่งใจมาก",
  str_voice_1602041_26 = "ฉันชอบการจัดห้อง สภาพแวดล้อมที่เป็นระเบียบสามารถเยียวยาจิตวิญญาณได้",
  str_voice_1602041_27 = "ไม่ชอบอะไร...? ถ้าต้องรู้จริงๆ มันคือผักชี มันมีกลิ่นแปลก ๆ",
  str_voice_1602041_28 = "แม้ว่า Colossus จะงดงามมากจริงๆ แต่การเพิ่มของตกแต่งที่ดูอบอุ่นก็ช่วยให้บรรยากาศมีชีวิตชีวามากขึ้นได้",
  str_voice_1602041_29 = "จุ๊ๆ ได้โปรดอย่าเรียกฉันว่าเลดี้โจชัวอีก เราไม่เห็นด้วยที่จะเก็บเป็นความลับ? จากนี้ไป เรียกฉันว่า โจชัว ได้ไหม",
  str_voice_1602041_30 = "ฉันแข็งแกร่งขึ้น!",
  str_voice_1602041_31 = "ฉันรู้สึกเหมือนฉันจำอะไรบางอย่างได้",
  str_voice_1602041_32 = "พลังในตัวฉันพลุ่งพล่าน...",
  str_voice_1602041_33 = "ดาบมีไว้เพื่อปกป้องทุกคน!",
  str_voice_1602041_34 = "เราสามารถทำได้ด้วยกัน",
  str_voice_1602041_35 = "แสงของดาบทำให้เรามีความสุข",
  str_voice_1602041_36 = "ไฟแห่งการคำนวน!",
  str_voice_1602041_37 = "คำสอนอันศักดิ์สิทธิ์โปรดนำทางฉัน!",
  str_voice_1602041_38 = "แสงนำทางอันศักดิ์สิทธิ์...เฉิดฉาย!",
  str_voice_1602041_39 = "ใบมีดเรืองแสง!",
  str_voice_1602041_40 = "ลูเซนท์แดนซ์!",
  str_voice_1602041_41 = "ให้ฉันเป็นผู้นำทาง",
  str_voice_1602041_42 = "ให้และคุณจะได้รับ",
  str_voice_1602041_43 = "ลองอีกครั้ง",
  str_voice_1602041_44 = "การยืดเส้นยืดสายแบบนี้นานๆ ครั้งจะช่วยให้ร่างกายและจิตใจผ่อนคลายได้!",
  str_voice_1602041_45 = "ถ้าอย่างนั้น...",
  str_voice_1602041_46 = "นี่เป็นของขวัญที่รอบคอบมาก",
  str_voice_1602041_47 = "ช่างเป็นของขวัญที่น่ารัก",
  str_voice_1602041_48 = "ของขวัญชิ้นนี้...ค่อนข้างจะคาดไม่ถึง!",
  str_voice_1602041_49 = "อุดมคติอันยิ่งใหญ่ทำให้ฉันกล้าที่จะเอื้อมไปให้ถึงท้องฟ้า มีเพียงความอยากเท่านั้นที่ยังคงอยู่—ฉันไม่มีความปรารถนาที่จะหลงระเริงกับความสงสัยในตัวเอง",
  str_voice_1602041_50 = "คนส่วนใหญ่ดูถูกความรักระหว่างผู้สูงศักดิ์กับสามัญชน ฉันไม่ต้องการให้พระองค์เผชิญการต่อต้านมากขึ้นในการปกครองในอนาคตเพราะเหตุนี้",
  str_voice_1602041_51 = "ถ้ามีโอกาส ฉันหวังว่าจะได้ไปเยี่ยมหลุมฝังศพของเธอ ท้ายที่สุด ดูเหมือนว่าจะมีสายใยที่มองไม่เห็นระหว่างเรา... ใช่ มันเป็นสายใยแห่งโชคชะตาที่เชื่อมโยงเรา",
  str_voice_1602041_52 = "Alchemy Stars",
  str_voice_1602041_53 = "สวัสดี!",
  str_voice_1602041_54 = "อรุณสวัสดิ์!",
  str_voice_1602041_55 = "สวัสดียามบ่าย",
  str_voice_1602041_56 = "เริ่มสายแล้ว!",
  str_voice_1602041_57 = "สวัสดีปีใหม่. ปีนี้ทำงานหนักเหมือนปีที่แล้ว!",
  str_voice_1502051_1 = "พบจุดที่ถูกแดดเผาในทะเลทราย Rediesel หรือไม่? คุณต้องดูแลผิวของคุณให้ดียิ่งขึ้น ให้ฉันพาคุณไปสปาที่ดีที่ฉันรู้จัก",
  str_voice_1502051_2 = "เพื่อที่จะเป็นมัคคุเทศก์ออนไลน์ตลอด 24 ชั่วโมง ฉันได้ก้าวข้ามความต้องการการนอนหลับและสามารถให้บริการคุณได้ตลอดเวลา",
  str_voice_1502051_3 = "ความหมายของมิตรภาพ? เมื่อใดก็ตามที่คุณต้องการ ฉันจะไปหาคุณโดยเร็วที่สุด",
  str_voice_1502051_4 = "คุณต้องการที่จะเข้าร่วมบอล? เต้นกับเธอน่าจะสนุกดี แต่ก่อนอื่น ฉันต้องไปเตรียมชุดใหม่ก่อน",
  str_voice_1502051_5 = "ความผันผวนทางอารมณ์อาจส่งผลต่อหน้าที่การเป็นผู้ปกครองของฉัน แต่ชาสามารถช่วยให้อารมณ์ของฉันคงที่ได้ ที่นี่ฉันทำถ้วยให้คุณด้วย",
  str_voice_1502051_6 = "เมืองยามค่ำคืนมีอันตรายซ่อนอยู่เสมอ แต่คุณไม่ต้องกังวล ภารกิจของฉันคือทำให้คุณปลอดภัย",
  str_voice_1502051_7 = "ทุกช่วงเวลาใน Lumopolis มีความงามที่ไม่เหมือนใคร โปรดให้ฉันไปกับคุณในการเดินทางครั้งต่อไปที่นั่น",
  str_voice_1502051_8 = "การทำงานให้เสร็จไม่มีที่ติเป็นกฎข้อเดียวที่ฉันยึดถือ ซึ่งหมายความว่าฉันต้องสงบสติอารมณ์ตลอดเวลา แม้ว่าฉันจะอยู่กับคุณก็ตาม",
  str_voice_1502051_9 = "ถ้าฉันใส่เสื้อผ้าเข้านอนได้อย่างเดียว ฉันจะเลือกน้ำหอม ทำไมคุณดูประหลาดใจมาก? คุณแปลกใจกับคำตอบของฉันไหม หรือวันนี้คุณไม่ชอบน้ำหอมของฉัน",
  str_voice_1502051_10 = "เด็กหนุ่มควรใส่ใจกับรูปร่างหน้าตาของพวกเขาด้วย ฉันสามารถช่วยคุณเลือกชุดที่สมบูรณ์แบบได้ ถ้าคุณต้องการ",
  str_voice_1502051_11 = "การปกป้องคุณตลอดการเดินทางเป็นความรับผิดชอบและเป็นเกียรติของฉัน และฉันจะรับใช้คุณด้วยทุก ๆ ออนซ์ของฉัน",
  str_voice_1502051_12 = "คุณต้องการที่จะได้ยินข่าวลือล่าสุด? ฉันเป็นองคมนตรีในช่องทางพิเศษของข้อมูล คุณก็รู้",
  str_voice_1502051_13 = "ในฐานะไกด์ ฉันจะอยู่เคียงข้างคุณเสมอเพื่อให้แน่ใจว่าคุณจะถึงที่หมายอย่างปลอดภัย",
  str_voice_1502051_14 = "เมื่อใดก็ตามที่คุณสวมเสื้อผ้าใหม่ คุณจะรู้สึกเหมือนได้เกิดใหม่อีกครั้ง ทุกอย่างใหม่หมด และคุณสามารถลืมทุกสิ่งที่เกิดขึ้นในอดีตได้",
  str_voice_1502051_15 = "โอ้ ยังเด็กและยังตื่นเต้นมากในวันเกิดของใครคนหนึ่ง... ฉันหวังว่าคุณจะยังเด็กตลอดไป",
  str_voice_1502051_16 = "วันนี้คุณไม่ต้องการให้ฉันไปกับคุณหรือ แน่นอนฉันเป็นห่วงคุณ คุณทำให้ฉันรู้สึกว่าคุณหลงทางมาก",
  str_voice_1502051_17 = "วันใหม่ได้เริ่มขึ้นแล้ว คุณมีแผนสำหรับวันนี้หรือไม่? ฉันได้เตรียมตารางการท่องเที่ยวสำหรับคุณแล้ว",
  str_voice_1502051_18 = "ฉันไม่ได้วางแผนที่จะเข้านอนเร็วๆ นี้ มันยังถือว่าเร็วสำหรับฉัน เพราะยังไม่รุ่ง",
  str_voice_1502051_19 = "เวลากลางคืนเป็นเวลาที่วิเศษที่สุด คุณสนุกกับการทำภารกิจในตอนกลางคืนมากเท่ากับที่ฉันทำหรือไม่?",
  str_voice_1502051_20 = "บางคนบอกว่าลูโมโปลิสเป็นถ้ำแห่งความเสื่อมทรามที่ซ่อนอยู่ภายใต้ม่านแห่งความศักดิ์สิทธิ์ แต่ไม่ว่ายังไงก็ตาม ฉันจะต้องปกป้องมันจนถึงที่สุด",
  str_voice_1502051_21 = "Umbraton เป็นสถานที่ที่น่าสนใจ แม้จะดูวุ่นวายแต่ความจริงแล้วก็มีกฎเกณฑ์และระเบียบของมันเอง",
  str_voice_1502051_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1502051_23 = "Eclipsites ที่เคยคร่าชีวิตข้า... ครั้งนี้ ข้าจะไม่ปล่อยพวกมันไว้พร้อมกับชีวิต",
  str_voice_1502051_24 = "คุณอยากรู้ไหมว่าความปรารถนาของฉันคืออะไร? นอกจากการปกป้อง Lumopolis แล้ว สิ่งที่ฉันต้องการคือตามหาเธอให้เจอ",
  str_voice_1502051_25 = "นาดีนเป็นเด็กที่ขยันมาก อันที่จริง วิธีการทำงานที่ไม่ไร้สาระของเธอค่อนข้างเหมือนกับของฉันเลย",
  str_voice_1502051_26 = "การเดินบนถนนในตอนกลางคืน สูดกลิ่นหอมของกาแฟและชา เป็นวิธีที่ฉันชอบในการผ่อนคลาย",
  str_voice_1502051_27 = "ผู้ที่ปฏิเสธคำสั่งจะไม่นำอะไรมาให้เรานอกจากปัญหาตลอดการเดินทางของเรา",
  str_voice_1502051_28 = "มันไม่ง่ายเลยที่จะชี้แนะเพื่อนตัวใหญ่ให้ไปในทิศทางที่ถูกต้อง",
  str_voice_1502051_29 = "สวัสดี ฉันชื่อคุณบลองก์ ไกด์ที่ไว้ใจได้ของคุณ คุณสามารถเรียกฉันว่า Guardian of Lumopolis ก็ได้ ฉันจะทำงานทุกอย่างที่คุณมอบหมายให้ฉันอย่างสมบูรณ์แบบ เพื่อให้แน่ใจว่าทุกความต้องการของคุณได้รับการตอบสนอง",
  str_voice_1502051_30 = "ยอดมาก",
  str_voice_1502051_31 = "ฉีดน้ำหอมหน่อย.",
  str_voice_1502051_32 = "สวมใส่เป็นเดรส",
  str_voice_1502051_33 = "เข้าร่วมบอล",
  str_voice_1502051_34 = "มากันครบทุกคนหรือยัง?",
  str_voice_1502051_35 = "ภารกิจเสร็จสิ้น.",
  str_voice_1502051_36 = "ผู้พิทักษ์แห่งรัตติกาล!",
  str_voice_1502051_37 = "ของขวัญเพื่อระลึกถึงการพบกันครั้งแรกของเรา",
  str_voice_1502051_38 = "ฉันทุ่มเทเพื่อให้บริการคุณ",
  str_voice_1502051_39 = "ส่วนผสมที่ลงตัว",
  str_voice_1502051_40 = "พันธมิตรที่น่าเกรงขาม",
  str_voice_1502051_41 = "ทุกคนโปรดติดตามฉัน",
  str_voice_1502051_42 = "การเดินทางที่แสนสบาย",
  str_voice_1502051_43 = "ฉันรู้สึกเหนื่อยนิดหน่อย...",
  str_voice_1502051_44 = "ฉันสามารถนั่งที่นี่และเพลิดเพลินกับทิวทัศน์ที่สวยงามตลอดทั้งคืน",
  str_voice_1502051_45 = "ขอบคุณสำหรับการรับรู้ของคุณ",
  str_voice_1502051_46 = "นี่เป็นเพียงสิ่งที่ฉันต้องการ",
  str_voice_1502051_47 = "ความกรุณาของคุณไม่มีค่า",
  str_voice_1502051_48 = "คุณมีรสนิยมดี. นี้เหมาะกับฉันไปที",
  str_voice_1502051_49 = "วิธีที่ดีที่สุดในการแสดงความสำเร็จของคุณเมื่อคุณอายุมากขึ้นคือไม่ต้องมีเสื้อผ้าใหม่ๆ ในตู้เสื้อผ้า แต่ให้ยังสามารถใส่เสื้อผ้าเก่าเมื่อสิบปีที่แล้วได้ ซึ่งหมายความว่าคุณยังคงรูปร่างที่อ่อนเยาว์อยู่เสมอ",
  str_voice_1502051_50 = "ทำไมฉันถึงเรียกตัวเองว่า Guardian of Lumopolis? ไม่ใช่แค่สิ่งที่ฉันเรียกตัวเองว่า—นี่คือการกำหนดของโชคชะตา",
  str_voice_1502051_51 = "ฉันสบายดี ฉันแค่ต้องแน่ใจว่าเมคอัพของฉันไม่ติด... ใช่ ฉันยืนยันได้จากแสงสะท้อนในดวงตาของ Eclipsites",
  str_voice_1502051_52 = "Alchemy Stars",
  str_voice_1502051_53 = "สวัสดี",
  str_voice_1502051_54 = "ชาหรือกาแฟ?",
  str_voice_1502051_55 = "วันนี้คุณอยากไปไหน",
  str_voice_1502051_56 = "ถ้านอนไม่หลับก็มาหาฉันได้ตลอดนะ",
  str_voice_1502051_57 = "ขอแสดงความยินดีในวันปีใหม่! ฉันหวังว่าคุณจะทำภารกิจทั้งหมดให้สำเร็จในอนาคต",
  str_voice_1602061_1 = "ไฮ~ ฉันนำผลไม้มาให้คุณบ้าง—ดูเหมือนว่ามันเป็นพันธุ์ใหม่ที่พัฒนาขึ้นมา ฉันไม่แน่ใจว่ามันจะอร่อยหรือเปล่า แต่คุณลองชิมมันเถอะ ขณะที่มันยังสด!",
  str_voice_1602061_2 = "อย่าหยุดไล่ตามความฝันของคุณ! ทุกคนมีความฝันของตัวเอง แต่เฉพาะผู้ที่มีความกล้าในการบรรลุความฝันเหล่านั้นเท่านั้นที่จะชนะในวันนั้น!",
  str_voice_1602061_3 = "อ๋า, กาแฟที่นี่น่าตายเลย! ฉันชอบลองรสชาติต่าง ๆ จากสถานที่ต่าง ๆ มาก เหมือนกับชีวิตนี้เต็มไปด้วยความใหม่ ๆ และความตื่นเต้นที่ไม่มีที่สิ้นสุด!",
  str_voice_1602061_4 = "ฉันรู้สึกจริงๆว่าการเป็นผู้ประกอบการนั้นน่าสนใจมาก ถึงแม้ว่าคนหนึ่งอาจพบกับความยากลำบากและความผิดหวังอย่างไม่มีที่สิ้นสุด แต่ความรู้สึกที่สำเร็จและเสรีที่คนหนึ่งได้รับนั้นก็เหมือนกับไม่มีอะไรแล้ว!",
  str_voice_1602061_5 = "เฮ้อ, ฉันรู้สึกเหนื่อยบ้าง... ขอรับแก้วน้ำผลไม้หน่อยได้ไหม? ฉันยังไม่เคยลองรสชาตินี้มาก่อนเลย และฉันชอบสัมผัสความรู้สึกใหม่ๆ!",
  str_voice_1602061_6 = "ฉันจะบริหารธุรกิจขนาดใหญ่อย่างไร? ปรัชญาในการดำเนินธุรกิจของฉันนั้นง่ายมาก: ถ้าคุณจะทำอะไร ก็ทำให้ถูกต้อง ไม่มีเหตุผลในการยอมแพ้ในสิ่งใดกลางคัน",
  str_voice_1602061_7 = "หวัดดี! ฉันรู้สึกว่าคุณเสียใจมากเมื่อเร็ว ๆ นี้... มีอะไรเหรอ? มีใครปฏิเสธคุณหรือเปล่า? อย่าวิตกกังวลเกี่ยวกับความคิดเห็นของคนอื่น ๆ นะ แค่เป็นตัวของคุณเองเถอะ!",
  str_voice_1602061_8 = "สภาพอากาศวันนี้ดีมากเลย! เราทำไมไม่ออกไปสำรวจนิดนึง? เราอาจพบสิ่งใหม่ๆ! ฉันเพิ่งเห็นคุณและคิดว่าจะขอให้คุณออกมา...",
  str_voice_1602061_9 = "เอิ่ม, ฉันหลับไปหรือเปล่า? เมื่อคืนฉันตื่นอ่านรายงาน... หวา! เสื้อโค้ทนี้เป็นของคุณหรือเปล่า? คุณใส่ให้ฉันเมื่อคืนเหรอ? ฮืม—ไม่มีหรอก, แน่นอนว่าฉันไม่ได้เขิน!",
  str_voice_1602061_10 = "เมื่อพูดถึงทุน ฉันคิดว่ามันเหมือนดาบสองคม หากคุณต้องการให้เกิดประโยชน์สูงสุด คุณต้องเข้าใจวิธีการใช้มันอย่างถูกต้อง",
  str_voice_1602061_11 = "คุณต้องการให้ฉันอยู่ใช่ไหม? แน่นอน ฉันไม่ได้มาที่นี่บ่อยครั้ง ทุกอย่างที่นี่มีความสดชื่น และอากาศก็ชื่นชื่นจริงๆ ซึ่งเป็นสิ่งที่ช่วยเสริมสำหรับฉันเมื่อต้องตัดสินใจเรื่องธุรกิจสำคัญๆ",
  str_voice_1602061_12 = "ทุนเป็นรากฐานของทุกกิจการ! เราสามารถสร้างโอกาสมากขึ้นให้ตัวเองได้เฉพาะเมื่อมีทุนเพียงพอ!",
  str_voice_1602061_13 = "การลองสิ่งใหม่ ๆ และเรียนรู้เกี่ยวกับประเพณีและประเพณีของสถานที่ต่าง ๆ สามารถช่วยให้เราเข้าใจโลกได้ดียิ่งขึ้น",
  str_voice_1602061_14 = "บอกฉันเรื่องน่าสนใจที่เกิดขึ้นกับคุณในวันนี้ได้ไหมคะ? ฉันอยากจะเห็นโลกผ่านสายตาของคุณจริง ๆ — อาจจะเป็นแรงบันดาลใจใหม่ในธุรกิจสำหรับฉัน!",
  str_voice_1602061_15 = "ไฮ~ สุขสันต์วันเกิดนะเพื่อนสนิท! ปีนี้คุณปรารถนาอะไร?",
  str_voice_1602061_16 = "วันนี้เราจะทำอาหารค่ำสร้างสรรค์กันเถอะ! ไปเลย มอบให้รสนิยมของคุณผจญภัย!",
  str_voice_1602061_17 = "อรุณสวัสดิ์! วันนี้เป็นอีกวันหนึ่ง! มาสำรวจโอกาสใหม่ ๆ และความเป็นไปได้ที่ไม่มีที่สิ้นสุดที่มันนำเสนอให้เรา ด้วยกันเถอะ!",
  str_voice_1602061_18 = "คุณทำงานทั้งวันเลยนะ น่าสงสาร พักผ่อนและผ่อนคลายนิดหน่อยน่ะนะ เอ๊ะ?",
  str_voice_1602061_19 = "ดึกแล้ว... ฉันจะไปพักตอนนี้ ไม่งั้นพลังงานของฉันอาจจะไม่พอรับมือกับงานทั้งวันพรุ่งนี้",
  str_voice_1602061_20 = "อัมบราตันเป็นสถานที่ที่เต็มไปด้วยโอกาสและความท้าทาย แต่น่าเสียดายที่แม่ของฉันอาศัยอยู่ที่นั่น...",
  str_voice_1602061_21 = "อิลลูมินาเป็นที่ยอดเยี่ยม - เทคโนโลยีและนวัตกรรมทั้งหมดเหมาะสมสำหรับผู้ประกอบการอย่างฉันเลย",
  str_voice_1602061_22 = "เงามืดจะคอยเฝ้ามองเจ้า",
  str_voice_1602061_23 = "อิคลิพไซท์ใด ๆ ที่พยายามมายุ่งกับธุรกิจของฉัน จะต้องต้องมาตอบต่อฉัน!",
  str_voice_1602061_24 = "ซินซาเป็นคนดีจริงๆ... บางทีฉันควรพิจารณาลงทุนในโครงการเพิ่มเติมในทะเลทรายเรดดีเซล...",
  str_voice_1602061_25 = "บ็อปเปอร์เป็นผู้ช่วยเล็กๆ ที่น่าเชื่อถือ ต้องซื่อสัตย์ ฉันก็ตกใจที่เห็นออโรเรียนที่จริงใจและซื่อสัตย์อยู่ในทะเลทรายเรดดีเซล",
  str_voice_1602061_26 = "ฉันชื่นชอบการค้าขาย ด้วยตัวแปรและความท้าทายทั้งหมด... มันเป็นเพียงในตัวแปรเหล่านั้นที่คุณสามารถค้นหาโอกาสทางธุรกิจ",
  str_voice_1602061_27 = "ฉันไม่สามารถทนกับคนที่เสมอเพียงยืนยันให้ใช้ชีวิตในกฎข้อบังคับที่เข้มงวดของตัวเอง ฉันหมายความว่า ไม่เอาน่า... น่าเบื่อ!",
  str_voice_1602061_28 = "เอาล่ะ นี่คือสินทรัพย์ที่คุณมีค่าที่สุดใช่ไหม? เอ๊ะ? โคลอสซัสคือครอบครัวของคุณเหรอ?! แนวคิดแปลกๆเนี่ย...",
  str_voice_1602061_29 = "เฮ้ย! ฉันคือ Lorelei นักธุรกิจที่ยอดเยี่ยม! ฉันมักมองหาโอกาสทางธุรกิจเสมอ ดังนั้นเมื่อไรก็ตามที่ฉันมีโอกาสได้ทำงานกับคุณ ฉันก็รู้สึกตื่นเต้นมาก!",
  str_voice_1602061_30 = "ขอบคุณสำหรับการลงทุนของคุณ",
  str_voice_1602061_31 = "เกมเริ่มต้นแล้ว",
  str_voice_1602061_32 = "ยังคงความแข่งขัน",
  str_voice_1602061_33 = "แสงเปลวไฟ!",
  str_voice_1602061_34 = "ยินดีที่ได้ทำธุรกิจกับคุณ",
  str_voice_1602061_35 = "โอกาสเ knocking!",
  str_voice_1602061_36 = "ไม่เสี่ยงไม่ได้กำไร!",
  str_voice_1602061_37 = "เปิดร้าน!",
  str_voice_1602061_38 = "ทุนคือพลัง!",
  str_voice_1602061_39 = "พลังของตลาด!",
  str_voice_1602061_40 = "สร้างรายได้!",
  str_voice_1602061_41 = "ทำงานร่วมกันกับฉันและคุณสามารถรับส่วนแบ่งประโยชน์!",
  str_voice_1602061_42 = "นั่นคือสิ่งที่ฉันเรียกว่าผลตอบแทนที่ดีจากการลงทุน",
  str_voice_1602061_43 = "ตลาดเป็นสัตว์ที่หลากหลาย...",
  str_voice_1602061_44 = "ฉันสามารถนั่งผ่อนคลายและอ่านรายงานธุรกิจประจำวันของฉันที่นี่ได้หรือไม่?",
  str_voice_1602061_45 = "ต้องการเริ่มต้นอะไรกับฉันไหม?",
  str_voice_1602061_46 = "คุณเก่งมากในการดึงดูดความสนใจของผู้คน",
  str_voice_1602061_47 = "ขอบคุณที่คิดถึงฉันเสมอ",
  str_voice_1602061_48 = "ขอบคุณครับ/ค่ะ ฉันชอบมันมาก!",
  str_voice_1602061_49 = "ความน่าเชื่อถือเป็นมุมมองสำคัญในความร่วมมือ และฉันยินดีที่จะแบ่งปันรายละเอียดเกี่ยวกับการเติบโตและพื้นหลังของฉันให้คุณทราบ นี่เป็นวิธีเดียวที่เราสามารถสร้างความสัมพันธ์ที่มั่นคงอยู่บนความเชื่อมั่นต่อกัน!",
  str_voice_1602061_50 = "ฉันขอโทษในทุกสิ่งที่คุณต้องผ่านมา แต่บางครั้งฉันอิจฉาคุณที่โตขึ้นคนเดียวและเสรีอย่างสมบูรณ์",
  str_voice_1602061_51 = "แทนที่จะเรียกฉันว่าผู้ประกอบการ ฉันยินดีที่คุณใช้ชื่อที่ฉันชอบคือ นักล่าฝัน ฉันต้องการที่จะสร้างตัวตนในโลกนี้และบรรลุความฝันของฉันด้วยความพยายามของตัวเอง",
  str_voice_1602061_52 = "Alchemy Stars",
  str_voice_1602061_53 = "สวัสดีครับ",
  str_voice_1602061_54 = "อรุณสวัสดิ์! วันนี้คุณมีแผนจะทำอะไรหรอ?",
  str_voice_1602061_55 = "งานทำไปด้วยความราบรื่นหรือไม่?",
  str_voice_1602061_56 = "ยังคงขึ้น?",
  str_voice_1602061_57 = "ในปีใหม่นี้ ฉันหวังว่าคุณจะลองทำสิ่งใหม่ ๆ ที่คุณสนใจมากขึ้น และสนุกกับชีวิตอิสระในทุก ๆ วัน!",
  str_voice_1602071_1 = "เอาเข้าใจเถอะเพื่อน คุณเครียดเกินไป! ชีวิตสั้น ไม่ต้องเสียใจเรื่องเล็กน้อย! พลังงาน ความหลงใหล และสาวสวยๆ—นั่นแหละความหมายของชีวิต!",
  str_voice_1602071_2 = "นอกจากที่จะเป็นบ้านของอาหารที่ดีแล้ว ร้านอาหารหรูยังเป็นสถานที่ที่สมบูรณ์แบบในการพบกับผู้หญิงที่มีเสน่ห์อายุมากขึ้น สองประเด็นนี้เพียงพอที่จะทำให้พวกเขาเป็นสถานที่ที่คุ้มค่าในการพักผ่อนในความเห็นของฉัน",
  str_voice_1602071_3 = "เจ็บปวดจริง ๆ! ฉันเหลือขวดเวอร์มัทที่นี่เมื่อวานนี้ แต่ทำไมมันหายไปวันนี้? มันเกิดขึ้นยังไงนะ... รอสักครู่—ฉันดื่มมันหมดหรือเปล่า? อาจเป็นเพราะเหตุนี้ที่หัวฉันปวดมาก...",
  str_voice_1602071_4 = "แน่นอนว่าทุกคนมีอดีต และในกรณีของฉัน... คำว่า \"การขอโทษ\" อาจเป็นคำที่ดีที่สุดในการบรรยายท่าทีของฉันต่อทุกสิ่งที่ฉันผ่านมา",
  str_voice_1602071_5 = "ผู้ชายต้องการจุดเปลี่ยนเพื่อประสบการณ์การเติบโตที่แท้จริง เช่น เหตุการณ์ที่น่าจดจำ หรือไม่อย่างนั้น... อาจเป็นเพราะความรักที่ไล่ตามแต่ไม่สำเร็จ",
  str_voice_1602071_6 = "แม้แต่แมลงวันก็ปรารถนาท้องฟ้าและดวงอาทิตย์ หลังจากพบกับคุณ หัวใจของฉันรู้สึกวุ่นวายบ้าง แต่อย่าเข้าใจผิด ฉันไม่คิดว่าคุณน่าสนใจเท่านั้น",
  str_voice_1602071_7 = "แม้ว่าพวกเขาจะอายุมากขึ้นกว่าฉันถึงยี่สิบปี แต่ยังมีผู้หญิงที่สุขุมอยู่ทั่วทุกมุม ทุกคนเต็มไปด้วยประสบการณ์และเสน่ห์ สนใจที่จะคบค้างกับคนหนึ่งใช่ไหม? งั้นก็พอละกัน—มากับฉันแล้วเราจะไปหาผู้หญิงสำหรับตัวเองกัน!",
  str_voice_1602071_8 = "อืมม... คุณมีกลิ่นเหมือนเด็กน้อยที่เหงื่อออก นี่เอาขวดน้ำหอมนี้ไปลองใช้สักครั้งสิ ไม่ต้องขอบคุณเลย ถูกต้อง",
  str_voice_1602071_9 = "ฉันไม่มีคุณสมบัติให้รัก... และฉันก็ไม่สามารถรักอย่างแท้จริง คนบอกว่าฉันไม่เอาชีวิตความเป็นจริง... แน่นอนฉันตกลงกับพวกเขาอย่างสิ้นเชิง",
  str_voice_1602071_10 = "คุณทำอะไรอยู่ที่นี่ยืนเหมือนคนบ้าหรือ? ไม่มีใครขอเข้ามาเดทกับคุณเหรอ? เสียดายจริง ๆ อยากเรียนรู้เรื่องการจัดการเวลาบ้างไหม? มาดูอาจารย์ทำงานกันเถอะ",
  str_voice_1602071_11 = "ฉันต้องการให้คุณจ่ายเงินเดือนให้ฉันเป็นรายชั่วโมง ใช่ 10,000 Nightium ต่อชั่วโมง นั่นคือราคามิตรภาพ เอิ่ม... ดูเหมือนว่าสถานการณ์ทางการเงินของคุณจะไม่อยู่ในสถานะที่ดีที่สุด ดังนั้นฉันคิดว่าฉันจะช่วยคุณในตอนนี้",
  str_voice_1602071_12 = "เฮ้ คุณไม่รู้หรือว่าการทำตัวกับฉันเหมือนฉันเป็นคุณลุงของคุณนี่หยาบคายหรือ? ทำไมคุณไม่เรียกฉันว่าบิ๊กซีน่า? คุณคิดว่ามันฟังไม่ดีหรือ? นั่นทำให้ฉันเสียใจจริงๆ นะเด็กน้อย แค่เรียกฉันว่าซีน่าก็พอละ",
  str_voice_1602071_13 = "สิ่งอำนวยความสะดวกมากมายในรีสอร์ทถูกออกแบบอย่างรอบคอบโดยข้าพเจ้าเองเพื่อให้แน่ใจว่าแขกทุกท่านจะได้สัมผัสประสบการณ์ที่ไม่ซ้ำใครและน่าจดจำ...",
  str_voice_1602071_14 = "คุณทำให้ฉันตกใจ! คุณสามารถทำเสียงนิดหน่อยได้มั้ยเวลาคุณเข้ามาอย่างเงียบๆ ครั้งหน้า? ฉันเพิ่งคิดเรื่องการเปลี่ยนห้องน่าเบื่อนี้ให้กลายเป็นสิ่งที่น่าทึ่งมาก",
  str_voice_1602071_15 = "สุขสันต์วันเกิด! ฉันหวังว่าคุณจะเป็นผู้ชายที่รับผิดชอบและมี CHARACTER ในปีใหม่",
  str_voice_1602071_16 = "ทำไมคุณจ้องผมอย่างนั้นล่ะ? ผมของฉันทรุดร่วงหรือ? อาจจะต้องไปหาช่างตัดผมดูแลทรงผมของฉัน...",
  str_voice_1602071_17 = "ฉันขอแนะนำให้คุณลองทานเอกส์เบเนดิกต์ในมื้อเช้า มันอุดมไปด้วยคุณค่าทางโภชนาการและอร่อย!",
  str_voice_1602071_18 = "คืนนี้ยังเยาว์! ฉันต้องรีบไปนัดเดท!",
  str_voice_1602071_19 = "คนรุ่นใหม่ไม่ควรทำงานหนักเกินไป! มาเที่ยวกันในคืนนี้กันเถอะ!",
  str_voice_1602071_20 = "หลังจากท่องทั่วทวีปทั้งหมด ฉันก็ตัดสินใจที่จะกลับไปยังบ้านเกิดของฉัน นั่นเป็นเวลาที่ฉันพบกับพวกเขา - เรดีเซล เวรนช์",
  str_voice_1602071_21 = "ฉันใช้เวลานานในลูโมโพลิสและได้รับการดูแลจากคนหลายคนที่มีใจบุญที่นั่น",
  str_voice_1602071_22 = "ใช้ชีวิตในขณะนี้",
  str_voice_1602071_23 = "อิคลิพไซท์อาจจะไม่ฉลาด แต่พวกเขาแข็งแรงมาก",
  str_voice_1602071_24 = "ซินซาไม่ใช่คนที่รอบคอบมาก แต่เราก็ยังคบกันได้",
  str_voice_1602071_25 = "คุณอยากรู้เรื่องราวของฉันกับบ็อปเปอร์ใช่ไหม? ฉันคิดว่าคุณอาจจะพูดว่าเธอเหมือนลูกสาวของฉันเลย, ฮ่า",
  str_voice_1602071_26 = "ฉันชอบลองน้ำหอมใหม่ ๆ ถึงแม้บางครั้งอาจจะดีหรือไม่ดีก็ตาม แต่นั่นก็เป็นส่วนหนึ่งของความสนุก",
  str_voice_1602071_27 = "คนที่ไม่พยายามที่จะดูดีทำให้ฉันรู้สึกไม่สบายใจ",
  str_voice_1602071_28 = "โซรอซและฉันเป็นนกชนิดเดียวกัน สุดท้ายแล้วเราทั้งคู่สามารถบินได้",
  str_voice_1602071_29 = "ยินดีต้อนรับสู่รีสอร์ทของฉัน ในฐานะผู้ดูแลที่นี่ หน้าที่ของฉันคือการตั้งใจให้คุณมีเวลาที่ดี โอ้ ฉันเกือบลืมแนะนำตัวเอง... คุณสามารถเรียกฉันว่า Cena",
  str_voice_1602071_30 = "เราทุกคนต้องการพื้นที่ให้หายใจ",
  str_voice_1602071_31 = "ลำธารในเมืองเกิดของฉันก็เฉียบพลันปรากฏในใจ...",
  str_voice_1602071_32 = "แม่น้ำแห้งไหลอีกครั้ง",
  str_voice_1602071_33 = "ในลำธารเงินที่คลอเขา แมลงปอยู่เต้นทั้งวัน—",
  str_voice_1602071_34 = "เชื่อมั่นในฉัน",
  str_voice_1602071_35 = "พวกเขาอยู่กับฉัน",
  str_voice_1602071_36 = "ไม่มีใครสามารถหยุดฉันได้",
  str_voice_1602071_37 = "แมลงหนอนน้ำเต้า, ตื่นจากฝันของคุณ! ระลอกคลื่นเกิดขึ้น!",
  str_voice_1602071_38 = "เต้นรำเถอะ แมลงปอย, เต้นรำ! ปล่อยให้ทุกอย่างหายไป!",
  str_voice_1602071_39 = "มีสิ่งดีๆ อยู่เสมอในทุกเรื่อง!",
  str_voice_1602071_40 = "ฉันไม่พลาดจังหวะเลย!",
  str_voice_1602071_41 = "ฉันรอไม่ไหวแล้วครับ",
  str_voice_1602071_42 = "นั่นเป็นเพียงการอุ่นตัวเท่านั้น",
  str_voice_1602071_43 = "ฉันคิดว่าฉันดื่มมากเกินไปคืนที่แล้ว...",
  str_voice_1602071_44 = "คุณผู้ชายที่ดีควรให้ความสำคัญกับการแต่งกายเสมอ แม้กระทั่งอยู่ที่บ้าน",
  str_voice_1602071_45 = "ขอบคุณที่ยอมรับความยุ่งยากครับ/ค่ะ",
  str_voice_1602071_46 = "ว้าว, คุณจริงๆ รับรู้เรื่องที่ฉันเป็นอยู่นะ",
  str_voice_1602071_47 = "คุณต้องการให้ฉันช่วยอะไรคะ?",
  str_voice_1602071_48 = "หากฉันให้คำแนะนำเกี่ยวกับการนัดหาคู่ให้คุณเป็นการตอบแทนล่ะเหรอ?",
  str_voice_1602071_49 = "ฉันเกิดขึ้นในหมู่บ้านในหุบเขา Denuo และตอนนี้ฉันกลับมาที่นี่เพื่อบริหารรีสอร์ท... ฉันคิดว่าชีวิตก็เป็นแบบนี้บ้างครั้ง",
  str_voice_1602071_50 = "ฉันอาศัยอยู่ในลูโมโพลิสมาหลายปีและค่อย ๆ ยอมแพ้ให้กับอิทธิพลของวัฒนธรรมและกติกามารยาททางสังคม บางทีนี่เป็นเหตุผลที่คุณคิดว่าฉันดูแตกต่างจากลูกหลานเรดีเซล เวรนช์ที่เป็นแนวโน้มปกติ",
  str_voice_1602071_51 = "คุณอยากรู้ว่าทำไมฉันถึงกลับมาที่นี่ใช่ไหม? ฉันคิดว่าฉันเพียงแค่เบื่อหลังจากท่องเที่ยวเกือบทั้งหมดคอนทิเนนต์แอสตรา และเบื่อกับการล่องลอยตามกระแสน้ำ",
  str_voice_1602071_52 = "Alchemy Stars",
  str_voice_1602071_53 = "ไฮ~",
  str_voice_1602071_54 = "อรุณสวัสดิ์",
  str_voice_1602071_55 = "สวัสดีตอนบ่าย",
  str_voice_1602071_56 = "วันนี้ไม่มีนัดเดทหรอ?",
  str_voice_1602071_57 = "สุขสันต์วันปีใหม่! เปิดวันพิเศษแบบนี้ คุณคิดยังไงกับการมาสนุกกับฉันบ้าง?",
  str_voice_1502081_1 = "ดูนะครับ ทุกคนเพียงแค่ติดตามแผนก็พอ โอเคนะ? ไม่ต้องกระทำอย่างกระตือรือร้น... ว่าไง? มีใครได้ยินฉันบ้างเหรอ?! สวัสดี...?!",
  str_voice_1502081_2 = "ทุกคนมักจ้องมองหางของฉันเสมอ - มีคนบอกว่าอยากทำอาหารจากกิ้งก่าด้วย และพวกเขาก็พูดว่า \"หางกิ้งก่าจะขึ้นใหม่หลังจากถูกตัดออกใช่มั้ย?\" ฉันตื่นตระหนกและวิ่งหนี แต่พวกเขาก็หัวเราะ... นี่มันไปไกลเกินไปใช่มั้ย?!",
  str_voice_1502081_3 = "คุณเห็นดอกไม้ที่ Eve ส่งให้ฉันไหม? จำกระถางต้นไม้ที่อยู่บนริมหน้าต่างนั่นไหม? ฮัดเช่ย! ขอโทษนะ ความแพ้เกี่ยวกับน้ำมูกของฉันเริ่มมีปัญหาเมื่อเร็วๆนี้...",
  str_voice_1502081_4 = "กิ้งก่ายักษ์คือเพื่อนสุดที่รักของฉัน มันทำตามที่ฉันสั่งเสมอ คุณเพื่อนใหญ่ของคุณเป็นนกที่ดีหรือไม่? ถ้ามันไม่สบาย อาจจะต้องการให้ตรวจสอบอย่างละเอียด...",
  str_voice_1502081_5 = "คุณต้องระวังทรัพย์รวดเร็วในทะเลทราย แน่นอน ด้วยฉันคุณจะปลอดภัยเสมอ แต่คุณอาจพบตัวเองในความอันตรายเมื่ออยู่คนเดียว!",
  str_voice_1502081_6 = "กับดักผู้พิทักษ์แน่นอนมีพลังมาก ใช่ครับ คุณสามารถใช้กับปีศาจอิคลิพไซท์ แต่กับดักเหล่านี้ยิ่งใช้กับคนที่ไม่ดีมากขึ้น...",
  str_voice_1502081_7 = "PlayerName คุณฟังทุกอย่างที่ฉันพูดโดยไม่พยายามขัดขวาง... ดังนั้นคุณและฉันเป็นเพื่อนสนิทกันแล้ว!",
  str_voice_1502081_8 = "ฉันก็โกรธเหมือนกันนะคุณรู้ไหม? เช่นเมื่อคนขโมยขนมของฉัน, ล้อเล่นฉัน, พยายามก่อกวนเรดีเซล เวรนช์, หรือ... ไม่สนใจฉันเลย...",
  str_voice_1502081_9 = "อย่าโทษฉันที่เดินช้าเกินไปนะ... ดูสิเถิด หางของฉันยาวมาก ถ้าฉันไม่ระวัง ฉันอาจจะทำให้อะไรหกล้มนะ!",
  str_voice_1502081_10 = "อย่าเสียใจนะ ตอนนี้ นะ หืม... นี่พวกคุณ... หลับไปแล้วเรอะ? อืมม... คงจะง่วงหลับบ้างเหมือนกัน มาพักผ่อนกัน... ด้วยกัน...",
  str_voice_1502081_11 = "PlayerName คุณต้องการให้ฉันอยู่ตรงนี้เพื่อให้คุณสามารถเห็นฉันเมื่อคุณต้องการใช่มั้ย? ฉันมีความสุขมาก...",
  str_voice_1502081_12 = "อย่าพยายามล่อลวงฉันด้วยขนมกิ้งก่าเลย... มันเป็นสิ่งเดียวที่ฉันไม่สามารถทนตัวได้",
  str_voice_1502081_13 = "ฉันต้องเพิ่มความเร็วในการเขียนแผน... ฉันรู้ว่าวันหนึ่ง ทุกคนจะปฏิบัติตามแผนของฉันอย่างสมบูรณ์แบบ และเราจะมีปัญหาน้อยลงในที่นี่!",
  str_voice_1502081_14 = "บะ-บอส! ไฟไหม้ที่ไหนครับ?! ผมเอาตัวดับเพลิงมาแล้ว... โอ้โห! ทุกอย่างเป็นความฝันงั้นเหรอ... ผมไม่ได้ทำให้คุณตกใจใช่ไหมครับ?",
  str_voice_1502081_15 = "สุขสันต์วันเกิด! ฉันทำเค้กรสกิ้งก่าให้คุณนะ! อย่าลืมกินขณะที่มันยังดีอยู่เลย!",
  str_voice_1502081_16 = "เอ๊ะ คุณไม่ได้เห็นเรื่องนั้นเมื่อกี๊นี้... ใช่ไหม? ไม่ได้! แน่นอนว่าฉันไม่ได้ขโมยสูบบุหรี่!",
  str_voice_1502081_17 = "อรุณสวัสดิ์! ฉันกำลังทำตารางงานใหม่ให้คุณ! รอสักครู่นะ—มันจะพร้อมให้คุณในไม่ช้า!",
  str_voice_1502081_18 = "สวัสดีครับ คุณอยากรู้ว่าฉันทำอะไรอยู่หรือเปล่า? ฉันกำลังเขียนไดอารี่... เฮ่! ไม่มีหรอก-ไม่มีหรอก อย่ามาดู!",
  str_voice_1502081_19 = "อืมม... ทำไมยังไม่หลับเหรอ? โอเคเนอะ ถ้าไม่ง่วงก็คุยกันพักนึงได้แล้วล่ะ",
  str_voice_1502081_20 = "ในหัวใจของฉัน เรดีเซล เวรนช์ เป็นบ้านของฉัน",
  str_voice_1502081_21 = "ฉันได้ยินว่าที่นอร์ธแลนด์หนาวจริงๆ... ฉันสงสัยว่าฉันจะมีโอกาสไปดูด้วยตัวเองหรือไม่นะ?",
  str_voice_1502081_22 = "ใช้ชีวิตให้เต็มที่ แต่อย่าลืมควบคุม...",
  str_voice_1502081_23 = "อิคลิพไซท์เป็นสิ่งมีชีวิตที่น่าขนลุกที่สุดในโลก! ฉันหวังว่าฉันจะสามารถ... บดทำลายมันทั้งหมด!",
  str_voice_1502081_24 = "ลอเรไลเป็นบอสที่ยอดเยี่ยม! ฉันขอขอบคุณที่เธอดูแลฉันอย่างดีในสวนสนุก...",
  str_voice_1502081_25 = "Sinsa เป็นเจ้าของร้านที่กล้าหาญและอุตสาหะที่สุดในโลก! ช-ชม. เขาเป็นไอดอลของฉันเลย!",
  str_voice_1502081_26 = "เสือปลาทอดเรดีเซลเป็นอาหารที่อร่อยที่สุดในโลก! ฉันไม่เคยเบื่อที่จะเคี้ยวเสือปลาเล็ก ๆ น้อย ๆ นั่น!",
  str_voice_1502081_27 = "ฉันเกลียดที่ถูกเพิกเฉย แต่ทุกคนยังคงเพิกเฉยฉันเสมอ...",
  str_voice_1502081_28 = "อืมม... มันดูแตกต่างจากกิ้งก่ายักษ์มากเลย แต่ว้าว! เด็กผู้ชาย มันน่าสนใจจริงๆ!",
  str_voice_1502081_29 = "ฉันคือผู้เชี่ยวชาญยุทธวิธีคนประจำของเรดีเซล เวรนช์—บ็อปเปอร์! แต่... ไม่มีใครฟังฉันจริง ๆ... โอ้ ฉันได้ยินว่าคุณนำทางอินทรียักษ์... มันคือตัวใหญ่คนนี้ใช่ไหม?",
  str_voice_1502081_30 = "เราต้องระมัดระวังมากขึ้น",
  str_voice_1502081_31 = "ทรายไหว! มันกลับเป็นสีทอง...",
  str_voice_1502081_32 = "กับดักผู้พิทักษ์ปรับปรุงใหม่และพร้อมที่จะใช้งาน",
  str_voice_1502081_33 = "เรากำลังควบคืบหน้า, กิ้งก่ายักษ์!",
  str_voice_1502081_34 = "ผะ...ผมจะพยายามครับ!",
  str_voice_1502081_35 = "ฉันอยู่ที่นี่",
  str_voice_1502081_36 = "หวา! ลมของทะเลทราย...",
  str_voice_1502081_37 = "เต้นรำ, ทรายไหล!",
  str_voice_1502081_38 = "ทรายหมุน... ปั่นพายุขึ้น!",
  str_voice_1502081_39 = "เปิดประกาย, ทรายทอง!",
  str_voice_1502081_40 = "อวยพรแห่งทราย!",
  str_voice_1502081_41 = "ทุกคน อย่าลืมเอาใจใส่ฉันด้วยนะ...",
  str_voice_1502081_42 = "นี่คือพลังของผู้พิทักษ์",
  str_voice_1502081_43 = "คราวหน้าฉันจะวางแผนให้รอบคอบยิ่งขึ้น",
  str_voice_1502081_44 = "พุงของนกอินทรีตัวใหญ่นี้ใหญ่มาก... มันสามารถรองรับห้องได้เยอะมาก",
  str_voice_1502081_45 = "ขอบคุณนะ... สำหรับของขวัญ",
  str_voice_1502081_46 = "*ร้องไห้* พวกนาย... จำได้ว่าฉันชอบอะไรเหรอ?",
  str_voice_1502081_47 = "ฉันต้องเริ่มวางแผนว่าฉันจะมอบอะไรให้คุณเป็นการตอบแทน...",
  str_voice_1502081_48 = "PlayerName... คุณเป็นคนที่สุดยอด!",
  str_voice_1502081_49 = "ฉันไม่จำได้ว่าพ่อแม่หน้าตาเป็นอย่างไร หรือความทรงจำใด ๆ เกี่ยวกับอดีตของฉัน แต่ไม่เป็นไร ทุกคนที่เรดีเซล เวรนช์เป็นครอบครัวของฉัน และพวกเขาเป็นคนที่สุดยอด!",
  str_voice_1502081_50 = "คุณสงสัยเรื่องตาขวาของฉันใช่ไหม? เมื่อฉันยังเป็นเด็ก ๆ เรดีเซล เวรนช์ถูกประเทศอิคลิพไซท์บุก และฉันได้รับบาดเจ็บในการโจมตีนั้น.",
  str_voice_1502081_51 = "ฉันไม่ใช่ตัวแทนนะ! อย่าฟังความเรื่องเล่าของพวกเขา ฉันเป็นเจ้าหน้าที่ยุทธวิธีที่ผ่านการฝึก! แต่ก็ไม่ได้หมายความว่าใครจะปฏิบัติตามแผนของฉันบ่อยๆ...",
  str_voice_1502081_52 = "Alchemy Stars",
  str_voice_1502081_53 = "สวัสดี!",
  str_voice_1502081_54 = "สวัสดี...",
  str_voice_1502081_55 = "สวัสดีตอนบ่าย",
  str_voice_1502081_56 = "สวัสดีตอนเย็น PlayerName",
  str_voice_1502081_57 = "สุขสันต์วันปีใหม่! ฉันรู้ว่าสิ่งดี ๆ กำลังจะมาถึงเรา!",
  str_voice_1601214_10 = "ความซื่อสัตย์เป็นคุณธรรม แต่บางครั้งอาจถูกเข้าใจผิดเป็นความโหดร้าย ฉันยิ่งชอบที่จะเป็นคนตรงไปตรงมาและทำให้คนอื่นโกรธ มากกว่าที่จะเป็นคนหน้าหนาวใจร้อนที่พยายามทำให้ทุกคนพอใจ",
  str_voice_1601214_11 = "บางคนเป็นคนที่มีความสำคัญในความเสียสละของศีลธรรมที่คาดหวังไว้ แต่กระทำความชั่วร้ายที่แย่กว่าปีศาจอย่างเต็มที่ คุณไม่คิดว่าเป็นอย่างนั้นหรือไม่? ฉันเพียงแค่ชอบเมื่อคนต่ำช้าเช่นนี้ถูกเปิดเผยความจริงที่เป็นอยู่",
  str_voice_1601214_16 = "หนามคมที่สุดคอยปกป้องดอกไม้สวยงามอย่างยิ่ง นี่คือสาระสำคัญของชีวิต ที่ความเจ็บปวดและความงามอยู่ร่วมกัน",
  str_voice_1601214_17 = "คนเชื่อมั่นเหล่านั้นหลงใหลในศรัทธาเท็จของพวกเขาในพระเจ้าแห่งแสง อย่างผู้ลี้ภัยที่สิ้นหวังของความเป็นจริง ค้นหาแสงที่ไม่มีอยู่ในความมืด...",
  str_voice_1601214_18 = "คุณต้องการกับดักฉันที่นี่เหมือนสัตว์เลี้ยงเล็ก ๆ ของคุณหรือ? ฉันไม่ใช่นกที่คุณสามารถเก็บปิดล็อคไว้ได้ง่าย ๆ นาน ๆ แต่ทิวทัศน์ที่นี่ดีจริง ๆ... บางทีฉันคงจะดูสิเสียที.",
  str_voice_1601214_19 = "ฉันพบว่าคุณชอบให้ความช่วยเสริมกับเพื่อน ๆ ของคุณมาก ซึ่งเป็นคุณภาพที่น่าชื่นชมจริง ๆ แต่บางครั้งคุณยังต้องถามตัวเองว่าเขาคุ้มค่ากับการช่วยเสริมหรือไม่",
  str_voice_1601214_35 = "ถ้าคุณไม่สามารถทนต่อความปลอมแปลงและมักห่วงว่าตัวเองไม่ได้เป็นส่วนหนึ่งอย่างแท้จริง นั่นก็เพราะว่าหัวใจของคุณนั้นบริสุทธิ์เกินไปค่ะที่รัก",
  str_voice_1601214_36 = "คนที่คำพูดไม่สอดคล้องกับการกระทำของตัวเองนั้นน่ากลัวที่สุด เพราะพวกเขาทั้งไม่ซื่อสัตย์และไม่น่าเชื่อถือ",
  str_voice_1601214_37 = "คุณมีแผนในวันนี้หรือไม่? หรือคุณเพียงแค่วางแผนให้เวลาผ่านไปเหมือนเคย?",
  str_voice_1601214_38 = "วันนี้จะเป็นวันที่ยากลำบากเนื่องจากดอกหนามบานสะพรั่ง ที่รัก นี่แสดงว่าชะตากรรมกำลังใกล้เข้ามาแล้ว",
  str_voice_1601214_39 = "คุณทานอาหารเย็นหรือยัง? การอดอาหารอย่างบ้าคลั่งก็ไม่สามารถทำให้ศรัทธาของคุณให้ผลผลิต",
  str_voice_1601214_40 = "คือคุณไม่อยากนอนเพราะจิตใจคุณสับสนจากความเชื่อและอุดมการณ์ที่เท็จนั้นหรือเปล่า?",
  str_voice_1601214_44 = "ความพิพากษามาถึงแล้ว",
  str_voice_1601214_58 = "กลับมาที่สิ่งที่คุณรู้จัก",
  str_voice_1601214_59 = "เปิดเผยความปลอมปิอาณาทั้งหมด!",
  str_voice_1601214_60 = "ศรัทธาจะไม่สูญหายเลย",
  str_voice_1601214_61 = "หญ้าในสวนกำลังบาน",
  str_voice_1601214_62 = "มาสนุกกันเถอะ...",
  str_voice_1601214_63 = "ฉันประหลาดใจที่ไม่มีใครไปสักการะโคลอสซัสนี้เลย!",
  str_voice_1601214_64 = "อรุณสวัสดิ์ ผู้นำทาง",
  str_voice_1601214_65 = "อากาศตอนเช้าทำให้ฉันรู้สึกเสรีเสมอ",
  str_voice_1601214_66 = "ฉันจะชดเชยให้คุณผู้นำทาง",
  str_voice_1601214_67 = "อรุณสวัสดิ์ คุณมีแผนการสำหรับวันนี้หรือไม่?",
  str_voice_1601214_68 = "ฉันได้ยินว่าคุณเริ่มออกกำลังกายตอนเช้าเมื่อเร็ว ๆ นี้ใช่ไหม?",
  str_voice_1601214_69 = "ขอโทษสำหรับความไม่สะดวกที่เมย์นำมาให้คุณ, ผู้นำทาง",
  str_voice_1601214_70 = "อาหารเช้าของวันนี้มีรสชาติของลูโมโพลิสเล็กน้อย",
  str_voice_1601214_71 = "คุณจมอยู่ในความสิ้นหวังในเวลากลางคืนหรือไม่?",
  str_voice_1601214_72 = "ความมืดและความเงียบงันห่อหุ้มดินแดน",
  str_voice_1601214_73 = "คุณเคยเห็นต้นหนามบานสะพรั่งหรือไม่?",
  str_voice_1601214_74 = "ความรู้ที่แท้จริงเกิดจากความมืดและความเงียบสงัด",
  str_voice_1601214_75 = "ฉันมีอิสระที่จะทำอะไรก็ได้ที่ฉันต้องการและเข้าร่วมกลุ่มใดก็ได้ที่ฉันเห็นว่าเหมาะสม",
  str_voice_1601214_76 = "ท้องฟ้ามืดลง วงแสงสีแดงเลือด",
  str_voice_1601214_77 = "หากคุณต้องการคำแนะนำ... อยากทราบเพิ่มเติมเกี่ยวกับหนามในมือของฉันไหมคะ?",
  str_voice_1601054_10 = "คุณมีแผนในวันนี้หรือไม่? สภาพอากาศดูดีนอกห้อง—ทำไมเราไม่ออกไปข้างนอกและสนุกกันบ้าง?",
  str_voice_1601054_11 = "ทุกคนที่เรดีเซล เวรนช์ รู้สึกเหมือนครอบครัวสำหรับฉัน... ฮะฮะ คุณก็ทำให้ฉันรู้สึกเช่นนั้นเช่นกัน ผู้นำทาง",
  str_voice_1601054_16 = "โลกนี้ใหญ่มาก - คุณไม่สามารถเสียเวลากับการคิดฝัน! เราจะไปที่ไหนต่อไป? ฉันได้ต้องการไปที่นอร์ธแลนด์มานานแล้ว",
  str_voice_1601054_17 = "ฉันไม่รู้ว่าพี่ชายของฉันและทุกคนที่เรดีเซล เวรนช์ กำลังทำอะไรตอนนี้... ฮืม! ฉันต้องสู้เพื่อช่วยเสียงให้คุณผู้นำทาง",
  str_voice_1601054_18 = "หืมม? คุณกำลังมองหาฉันเหรอ? ฉันเตรียมของทั้งหมดสำหรับปิกนิกแล้ว... เราจะออกเดินทางเมื่อไหร่?",
  str_voice_1601054_19 = "ในที่สุดเจ้าหญิงตื่นตัวจากฝันร้าย และเจ้าชายและทุกคนที่เธอรักอยู่ข้างๆ... จริงด้วย! ฉันชอบจบเรื่องนี้จริงๆ!",
  str_voice_1601054_35 = "เอาล่ะค่ะ ฉันยังคงเป็นเด็กผู้หญิงนะคะ! แน่นอนว่าฉันชอบเสื้อผ้าสวยๆ ทุกชนิดเลยค่ะ! ดังนั้น ผู้นำทาง... มีคำแนะนำอะไรไหมคะ?",
  str_voice_1601054_36 = "หญ้ามีกลิ่นหอม แดดอบอุ่น... ฟู่... รู้สึกเหมือนจะหลับอยู่แล้ว",
  str_voice_1601054_37 = "ฉันรอคุณมานานแล้วนาวิเกเตอร์! เราจะไปเล่นที่ไหนวันนี้คะ?",
  str_voice_1601054_38 = "*หาว* ขอโทษครับ ฉันยังรู้สึกเหมือนเพิ่งตื่นน่ะครับ... พี่ชายฉันบอกว่าถ้าฉันไม่นอนหลับดี ฉันจะไม่โตสูงขึ้น...",
  str_voice_1601054_39 = "สวัสดีตอนเย็น! วันนี้เป็นวันที่วุ่นวาย ฉันชงชาให้คุณแล้ว เนวิเกเตอร์! ดื่มให้หมด!",
  str_voice_1601054_40 = "ยาวววววว... ผู้นำทางครับ คุณเคยนับแกะเวลานอนไม่หลับไหม? หรือเคยนับหิ่งห้อย...? หิ่งห้อยหนึ่งตัว... หิ่งห้อยสองตัว... หิ่งห้อยสามตัว... หิ่งห้อยสี่ตัว...",
  str_voice_1601054_44 = "ถ้าคุณพร้อม ผมก็พร้อม",
  str_voice_1601054_58 = "เริ่มได้!",
  str_voice_1601054_59 = "ฉันต้องปกป้องทุกคน!",
  str_voice_1601054_60 = "กำจัดความเสี่ยง!</span>",
  str_voice_1601054_61 = "อาจจะเจ็บนะ!",
  str_voice_1601054_62 = "คุณไม่ได้รับเชิญ!",
  str_voice_1601054_63 = "ฉันนำดอกไม้สวย ๆ มาด้วย คุณสามารถวางพวกมันรอบ ๆ โคลอสซัสเพื่อให้มันดูสวยขึ้น",
  str_voice_1601054_64 = "ออกมาเล่นกันเถอะ?",
  str_voice_1601054_65 = "คุณแน่ใจหรือว่าคุณไม่ต้องการคิดใหม่เกี่ยวกับการเข้าร่วมกับเรดีเซล เวรนช์?!",
  str_voice_1601054_66 = "ฉันมีความสุขมากเพราะมีพี่ชายของฉัน คุณ และทุกคนอยู่ข้างๆ ฉันตลอดเวลา",
  str_voice_1601054_67 = "ฉันไม่สามารถเสียเวลาได้อีก! ฉันยังมีสถานที่เยอะมากที่อยากไปกับคุณ, นาวิเกเตอร์!",
  str_voice_1601054_68 = "ฉันต้องการความช่วยเสริมจากคุณอีกครั้งในวันนี้, นาวิเกเตอร์!",
  str_voice_1601054_69 = "เอิ่ม... ในที่สุด ฉันกำลังเรียนรู้วิธีการทำอาหารเมื่อเร็ว ๆ นี้ บางทีคุณอาจลองชิมอาหารของฉันเมื่อคุณมีเวลาว่าง?",
  str_voice_1601054_70 = "ฉันยังควบคุมพลังของตัวเองได้ในช่วงนี้ และมันเป็นเพราะคุณนาวิเกเตอร์ที่ช่วยเสมอ!",
  str_voice_1601054_71 = "ไปปิกนิกกับคุณเป็นสิ่งที่ดีที่สุดเลย, นาวิเกเตอร์!",
  str_voice_1601054_72 = "พี่ชายของฉันมักจะพูดว่าเราต้อง \"ใช้ชีวิตให้เต็มที่\" ดังนั้นมาพักงานและไปเล่นกันเถอะ!",
  str_voice_1601054_73 = "คุณชอบชาหรือกาแฟคะ ผู้นำทาง? ฉันจะทำให้คุณก่อนล่วงหน้าก่อนที่จะไปปิกนิกครั้งต่อไป",
  str_voice_1601054_74 = "หืมม? ผู้นำทาง วันนี้ความกระตือรือร้นของคุณหายไปไหน...? ต้องการให้ฉันเล่าเรื่องที่ฉันได้ยินจากพี่ชายของฉันไหม?",
  str_voice_1602091_1 = "จอมพลแห่งสหพันธ์อิลลูมิน่า...ตั้งแต่แรกนี่คือตำแหน่งที่ถูกต้องสำหรับฉัน",
  str_voice_1602091_2 = "การถ่อมตัวไม่ได้หมายความว่าต้องเป็นทาส แต่เพียงฉันเท่านั้นที่สามารถขัดขวางตัวเองได้",
  str_voice_1602091_3 = "ถ้าต้องการเข้าร่วมกองพันของฉัน ให้แสดงให้ฉันเห็นว่าคุณรู้เรื่องการต่อสู้มากแค่ไหน",
  str_voice_1602091_4 = "การเปลี่ยนแปลงตัวเองให้เป็นคนใหม่ไม่ใช่เรื่องง่ายๆ เหมือนการเปลี่ยนชุด แต่ต้องลบล้างร่องรอยของตัวเองในอดีตอย่างสิ้นเชิง",
  str_voice_1602091_5 = "การเปลี่ยนแปลงของเรดบารอนไม่น่าแปลกใจ เป็นการเตือนคนที่มีเจตนาร้ายว่าความยุติธรรมไม่เกี่ยวข้องกับรูปแบบ",
  str_voice_1602091_6 = "พลังแผ่ซ่านไปทั่วร่างฉันเหมือนพายุฟ้าคะนอง คุณพร้อมที่จะสร้างคลื่นกันกับฉันหรือยัง?",
  str_voice_1602091_7 = "ฉันเข้าใจไรน์ฮาร์ตบ้างแล้ว คุณมีศักยภาพที่น่าทึ่ง โชว์ให้ฉันเห็นสิ่งที่คุณมีอีกที่ฉันยังไม่รู้เกี่ยวกับ... เอิ่ม, ฉันหมายถึง ความสามารถของคุณนั่นเอง",
  str_voice_1602091_8 = "คุณสามารถเข้าใกล้ฉันได้ เรดบารอนมองหาเป้าหมายเฉพาะศัตรูเท่านั้น ส่วนคุณเป็นเพื่อนของฉัน",
  str_voice_1602091_9 = "ขอบคุณที่รักษาฉัน แต่โปรดอย่าให้ลูกน้องของฉันรู้เรื่องนี้ ให้เป็นความลับระหว่างคุณและฉันเถอะ โอเค?",
  str_voice_1602091_10 = "ยังมีหลายสิ่งที่ฉันไม่สามารถคิดค้นออกได้ แต่ฉันก็ชินกับความยุ่งยากและวิกฤติที่เกิดจากตำแหน่งนี้",
  str_voice_1602091_11 = "คุณอยากคุยกับฉันเหรอ? งั้นฉันขอเตือนว่าฉันไม่ใช่ผู้บัญชาการวราธเดิมที่คุณรู้จักอยู่หน้าคุณแล้ว ดังนั้นฉันขอแนะนำให้คุณเลือกคำพูดของคุณอย่างระมัดระวัง",
  str_voice_1602091_12 = "ไม่ต้องห่วงเรื่องฉัน เฉพาะภารกิจที่ยากขนาดนี้แสดงว่าพวกเขายังไม่รู้ว่าฉันสามารถทำอะไรได้บ้าง",
  str_voice_1602091_13 = "กองทัพที่ฉันนำทัพเป็นเพียงจุดเริ่มต้นของกองทัพอิลลูมินา ฉันจะเอาชนะคู่ต่อสู้ที่หยิ่งยโสอย่างชัดเจนและน่าเชื่อถือ",
  str_voice_1602091_14 = "ฉันไม่คิดว่าการมีท่าทางเคร่งขรึมเป็นปัญหา ถ้าคุณนำทหารขนาดใหญ่ ฉันคิดว่าคุณคงดูจริงจังยิ่งขึ้น",
  str_voice_1602091_15 = "อายุเพิ่มขึ้นหนึ่งปีแล้ว แต่เธอเติบโตขึ้นและเป็นผู้ใหญ่เพื่อคนรอบข้างหรือยัง?",
  str_voice_1602091_16 = "เลิกเป็นทางการแล้วเรียกฉันด้วยชื่อเถอะค่ะ",
  str_voice_1602091_17 = "โอ้ เวลาผ่านไปเร็วจริง ๆ... ฉันกำลังครุ่นคิดเกี่ยวกับสถานการณ์ และตอนนี้เป็นดอว์นแล้ว",
  str_voice_1602091_18 = "ทำไมฉันไม่เห็นคุณอยู่ในสนามวันนี้ล่ะ? คุณต้องฝึกหนักเพื่อให้มาถึงระดับของฉัน",
  str_voice_1602091_19 = "พักผ่อนหรือ? โทษนะ ตอนนี้ไม่ใช่เวลาสำหรับสิ่งนั้น",
  str_voice_1602091_20 = "ฉันควรจะคาดการณ์ได้ถึงความกระหายพลังและความทะเยอทะยานของความใฝ่หาอำนาจในชั้นชาติชั้น",
  str_voice_1602091_21 = "เมืองที่ลอยนั้นเพียงแค่บริการให้กับชนชั้นสูงแบบเก่า ซึ่งฉันไม่เคยสนใจเลย",
  str_voice_1602091_22 = "ขออิลลูมินาจงเจิดจำรัส!",
  str_voice_1602091_23 = "ฉันจะกำจัดพวกน้อยๆ ที่สกปรกและคลานอยู่ทุกหมู่ให้หมดสิ้น",
  str_voice_1602091_24 = "เพื่อเอาชนะไรน์ฮาร์ต ฉันต้องเอาชนะอุปสรรคทุกอย่างในทางข้างหน้า",
  str_voice_1602091_25 = "\"เฉพาะฮิอิโระเท่านั้นที่สามารถทำได้\" นั่นคือสิ่งที่ทุกคนที่ทำงานร่วมกันกับเธอพูดกัน",
  str_voice_1602091_26 = "การรณรงค์อย่างเพียรไม่ได้เพื่อการเกษียณอย่างสบายๆในวันหนึ่ง แต่เพื่อการเพิ่มความสามารถของตัวเองในกระบวนการนั้น",
  str_voice_1602091_27 = "ฉันจะทำให้คนที่ทำร้ายฉันจากหลังต้องทนทุกข์ก่อนที่ฉันจะตาย",
  str_voice_1602091_28 = "กองพลที่ 4 ต้องการหน่วยที่สามารถบินได้ คุณคิดว่าเพื่อนของคุณสนใจที่จะควบคุมหน่วยนี้ไหม?",
  str_voice_1602091_29 = "ฉัน วราธ เป็นจอมพลใหม่แห่งสหพันธ์อิลลูมินา ถึงแม้ว่าฉันไม่สามารถรับประกันว่าจะอยู่ในตำแหน่งนี้นาน ฉันก็ควรจะแนะนำตัวอย่างเป็นทางการ",
  str_voice_1602091_30 = "ฉันรู้สึกมีพลังไม่รู้จบ!",
  str_voice_1602091_31 = "นี่คือฉัน จงเห็นความแข็งแกร่งที่ไม่มีใครเอาชนะได้ของฉัน!",
  str_voice_1602091_32 = "การเสริมพลังเพิ่มเติมเป็นตัวเลือกเดียว!",
  str_voice_1602091_33 = "พลังที่แท้จริงของฉันยังมากกว่านี้!",
  str_voice_1602091_34 = "คุณมีความพิจารณาดี",
  str_voice_1602091_35 = "เมย์สายฟ้าจงปลดปล่อย!",
  str_voice_1602091_36 = "ได้เวลาแล้ว!",
  str_voice_1602091_37 = "หอกสายฟ้า ทิ่มแทง!",
  str_voice_1602091_38 = "สัมผัสพลังของเสียงฟ้าคำราม!",
  str_voice_1602091_39 = "ฉันไม่สามารถถูกเอาชนะได้!",
  str_voice_1602091_40 = "บุก!",
  str_voice_1602091_41 = "กองทัพอันเกรียงไกร รอคำสั่งของข้า!",
  str_voice_1602091_42 = "มันเทียบเท่ากับการฝึกซ้อมประจำวันของเราเท่านั้น",
  str_voice_1602091_43 = "ตั้งสมาธิและลองอีกครั้ง",
  str_voice_1602091_44 = "คุณจะรังเกียจหากฉันฝึกทหารของฉันที่นี่หรือไม่? ถือเป็นความน่าเสียดายหากปล่อยให้พื้นที่กว้างขวางเช่นนี้เปล่าประโยชน์",
  str_voice_1602091_45 = "ขอบคุณครับ ผู้ใต้บังคับบัญชาของฉันต้องการมันเสียแน่นอน",
  str_voice_1602091_46 = "หืม... บอกฉันสิ คุณคิดออกได้อย่างไรเนี่ย?",
  str_voice_1602091_47 = "คุณนี่ใจดีจริงๆ ขอบคุณนะ",
  str_voice_1602091_48 = "ขอบคุณ! ไม่นึกเลยว่าคุณจะใจดีขนาดนี้",
  str_voice_1602091_49 = "ฉันไม่เคยคิดว่าจะได้ขึ้นสู่ตำแหน่งจอมทัพด้วยวิธีเช่นนี้ แต่ถ้าพิจารณาจากความสามารถเพียงอย่างเดียว ฉันมั่นใจว่าฉันมีคุณสมบัติ!",
  str_voice_1602091_50 = "ฉันไม่เห็นด้วยกับวิธีของไรน์ฮาร์ตที่ชอบปิดบังเรื่อง แต่ด้วยสถานการณ์ที่เป็นอยู่ ฉันเชื่อว่าความทะเยอทะยานส่วนตัวไม่เกี่ยวข้องเมื่อเทียบกับอนาคตของอิลลูมินา",
  str_voice_1602091_51 = "แม้ว่าฉันจะถูกกัดตัวในที่ตัน ฉันก็จะไม่ยอมทนต่อพฤติกรรมที่เป็นอันตรายต่อเพื่อนๆ อิลลูมินัน ออโรเรียนทุกคนมีสิทธิ์ในการมีชีวิตอยู่",
  str_voice_1602091_52 = "Alchemy Stars",
  str_voice_1602091_53 = "ตอบกลับถ้าคุณคัดลอก",
  str_voice_1602091_54 = "ตื่นหรือยัง? เตรียมตัวสำหรับการฝึกฝนเช้านี้เถอะ",
  str_voice_1602091_55 = "คุณไม่สามารถจ้องเทอร์มินอลตลอดเวลาได้",
  str_voice_1602091_56 = "อย่าลืมฝึกซ้อมเช้าพรุ่งนี้นะครับ/ค่ะ",
  str_voice_1602091_57 = "สุขสันต์วันปีใหม่",
  str_voice_1502101_1 = "ขอเทิดทูนรัตติกาลสีขาว ขอให้คุณมีวันที่สงบและไม่มีเหตุการณ์ไม่พึงประสงค์",
  str_voice_1502101_2 = "อย่าทำให้ฉันดูเหมือนเป็นหญิงสาวบริสุทธิ์เมื่อฉันแค่คนธรรมดา มาเยี่ยมชมร้านขายของชำและร้านตัดเสื้อของฉันที่ตลาดในเวลาว่างของคุณเถอะ",
  str_voice_1502101_3 = "ในฐานะบุตรของเทพแห่งแสงสว่าง ฉันมีหน้าที่ต้องปกป้องเพื่อนๆ ชาวออโรเรียนจากอิคลิพไซท์ หน้าที่ของคุณคืออะไร?",
  str_voice_1502101_4 = "ขอบคุณเทพเจ้าแห่งแสงสว่างสูงสุดที่ประทานพลังให้ฉันสามารถหยุดความมืดมิด",
  str_voice_1502101_5 = "เพื่อช่วยออโรเรียนมากขึ้น ฉันต้องกลายเป็นคนที่แข็งแกร่งขึ้น",
  str_voice_1502101_6 = "ฉันจะยืนอยู่หัวหน้ากองทัพออโรเรียนและทำหน้าที่นำทางพวกเขาให้เต็มที่ที่สุด",
  str_voice_1502101_7 = "ฉันเห็นความหวังสำหรับชาวออโรเรียนในตัวคุณ... ไม่ ทำให้ความหวังนั้นสำหรับมิตรสัตว์ทั้งหมด",
  str_voice_1502101_8 = "คุณอยากสวดภาวนากับฉันมั้ย? มันเป็นนิสัยส่วนตัวเอง ฉันหวังว่าจะได้แบ่งปันความศรัทธากับคุณในช่วงพระอาทิตย์ขึ้นหรือตกดิน",
  str_voice_1502101_9 = "อืม... ขอโทษที่พูดคำที่อาจจะไม่เหมาะสม อย่างไรก็ตาม การที่เราทำงานร่วมกันในสนามรบทำให้ฉันมั่นใจว่าคุณเป็นของขวัญจากพระเจ้า",
  str_voice_1502101_10 = "โทษทีที่ให้รอนะ ฉันเพิ่งเล่าเรื่องให้กลุ่มเด็ก ๆ คุณขอใหม่ได้ไหม?",
  str_voice_1502101_11 = "ฉันเป็นทหารด้วย และฉันต้องสละชีวิตเพื่อแผ่นดินที่ปกป้องฉัน",
  str_voice_1502101_12 = "ตั้งแต่วินาทีที่อิคลิพไซท์บุก Twilight เรามีเพียงตัวเลือกเดียวคือการเข้าสู่สนามรบและไม่เคยย้อนกลับ",
  str_voice_1502101_13 = "ชาวออโรเรียนมีสิทธิ์ในการมีชีวิต ตามหลักการของพระเจ้าแห่งแสง การตายโดยไม่ประสงค์ไม่ได้รับอนุญาต",
  str_voice_1502101_14 = "แม้ว่าจะเกิดขึ้นในแดนที่ถูกลืม ก็ยังสามารถได้ยินคำอธิษฐานของเรา เพราะฉันเชื่อมั่นว่าเทพเจ้าแห่งแสงสว่างย่อมอยู่กับฉันเสมอ",
  str_voice_1502101_15 = "สุขสันต์วันเกิด ขอพระเจ้าแห่งแสงสว่างอวยพรคุณ",
  str_voice_1502101_16 = "ยินดีที่ได้พบคุณมาก คุณคิดว่าฉันควรทำอะไรก่อน ปรับปรุงการต่อสู้ด้วยดาบหรือภาวนา?",
  str_voice_1502101_17 = "อรุณสวัสดิ์ ขอพระเจ้าแห่งแสงสว่างปกป้องอาสตรา มาเดินตลาดกับฉันมั้ยเนี่ย",
  str_voice_1502101_18 = "ด้วยความศรัทธาอันแน่นอนของคุณ คุณต้องได้ยินเสียงของพระเจ้าในงานประจำวันของคุณ",
  str_voice_1502101_19 = "ยังไม่หลับเหรอ? โปรดลองอธิษฐานในช่วงเวลาดึกเมื่อเงียบสงบ คุณอาจได้ยินคำเปิดเผยที่ชัดเจนยิ่งขึ้น",
  str_voice_1502101_20 = "อย่างเชิงเทคนิคแล้ว ฉันมาจากลูโมโพลิส แต่คนใน Twilight ไม่สนใจเรื่องประวัติของกันและกัน",
  str_voice_1502101_21 = "นักรบอิลลูมินันมีเป้าหมายเดียวกันกับเรา: ต่อสู้กับอิคลิพไซท์จนถึงลมหายใจสุดท้ายของเรา",
  str_voice_1502101_22 = "ขอเทิดทูนรัตติกาลสีขาว",
  str_voice_1502101_23 = "ผู้ที่ย่ำยีออโรเรียนจะถูกตัดสินโดยเทพแห่งแสงสว่าง",
  str_voice_1502101_24 = "ลีโอเคยเป็นคนที่ภูมิใจและหยิ่งยโส แต่ตั้งแต่กลายเป็นกัปตัน เขามีเป้าหมายเดียวคือการปกป้อง Twilight",
  str_voice_1502101_25 = "โจเซฟเป็นคนมีความเลื่อมใส ฉันมีสิ่งที่ต้องเรียนรู้จากเขาเกี่ยวกับคริสตจักรเยอะเลย",
  str_voice_1502101_26 = "ความปรารถนาใหญ่ที่สุดของฉันคือการให้ทุกคนใน Twilight ได้ใช้ชีวิตอย่างมีความสุขและสมหวัง",
  str_voice_1502101_27 = "แสงเป็นแหล่งกำเนิดของทั้งหมด คนบาปที่ทำให้เทพแห่งแสงสกปรกจะถูกลบล้างเมื่อแสงกลับมา",
  str_voice_1502101_28 = "ขอโทษที่รบกวน แต่อยากทราบว่าบนโคลอสซัสมีห้องว่างให้ฉันไปสวดภาวนาตอนเช้าไหมครับ/ค่ะ?",
  str_voice_1502101_29 = "เทพแห่งแสงสว่างขับไล่ความมืด และประชาชนแห่งแสงสว่างจะส่องสว่างตลอดไป ฉันชื่อโจเซลีน ผู้รับใช้แห่งแสงสว่าง",
  str_voice_1502101_30 = "เทพแห่งแสงสว่างผู้เป็นนิรันดร์!",
  str_voice_1502101_31 = "ฉันไม่กลัวอะไรเลย",
  str_voice_1502101_32 = "ข้าจะทะลวงความมืด",
  str_voice_1502101_33 = "ฉันอุตสาหะในภารกิจอันศักดิ์สิทธิ์ของฉัน!",
  str_voice_1502101_34 = "ฉันไม่กลัวตาย",
  str_voice_1502101_35 = "เล็งสู่ความมืด!",
  str_voice_1502101_36 = "ขอพระเจ้าแห่งแสงสว่างอวยพรเรา!",
  str_voice_1502101_37 = "โอ้ พระเจ้าแห่งแสงสว่าง โปรดนำทางฉันในการต่อสู้!",
  str_voice_1502101_38 = "ฉันจะนำทางการมาของแสงสว่าง!",
  str_voice_1502101_39 = "ไม่มีความเมตตา!",
  str_voice_1502101_40 = "ไม่มีอะไรรั้ง!",
  str_voice_1502101_41 = "ใช่ ฉันชินกับการนำหน้าแนวหน้า!",
  str_voice_1502101_42 = "เทพแห่งแสงสว่างส่องสว่างให้เรา",
  str_voice_1502101_43 = "ความพ่ายแพ้ชั่วคราวจะไม่หยุดเราจากการก้าวหน้า",
  str_voice_1502101_44 = "เด็กกำพร้าจะรักที่นี่อย่างแน่นอน ไม่ต้องห่วง เพราะเป็นเด็กดีทั้งหมด",
  str_voice_1502101_45 = "ขอบคุณ ขอพระเจ้าของความเมตตาอยู่กับคุณ",
  str_voice_1502101_46 = "เซอร์ไพรส์มากที่ได้รับของขวัญนี้เลย!",
  str_voice_1502101_47 = "ขอบคุณครับ/ค่ะ มีอะไรให้ฉันช่วยคุณไหมครับ/ค่ะ?",
  str_voice_1502101_48 = "ขอบคุณค่ะ นี่เป็นของขวัญที่ดีที่สุดที่ฉันเคยได้รับจนถึงตอนนี้!",
  str_voice_1502101_49 = "เกิดขึ้นในพื้นที่ชายแดนของอัสตรา ฉันเข้าใจความสำคัญในการช่วยชีวิตออโรเรียน แม้กระทั่งต้องเผชิญหน้ากับอิคลิพไซท์ในสภาพแวดล้อมที่อันตราย ก็ยังไม่เคยถอยหลังสำหรับประชาชนของพระเจ้าแห่งแสงสว่าง",
  str_voice_1502101_50 = "เด็ก ๆ ที่เกิดใน Twilight เคยเหมือนฉัน คิดว่าเมืองเล็ก ๆ นั้นคือโลกทั้งหมด ฉันจะทำความสามารถในการปกป้องโลกของพวกเขา",
  str_voice_1502101_51 = "อิลลูมินา ลูโมโพลิส... มีคนหลายคนต่อต้านกันเพียงเพราะเกิดในฝ่ายต่างๆ แต่นอกจากอิคลิพไซท์แล้ว ไม่มีศัตรูที่แท้จริง",
  str_voice_1502101_52 = "Alchemy Stars",
  str_voice_1502101_53 = "สวัสดี",
  str_voice_1502101_54 = "เช้านี้ ฉันได้สวดมนต์ขอพรให้คุณแล้ว",
  str_voice_1502101_55 = "สวัสดีตอนบ่าย ขอให้คุณกล้าหาญในวันนี้นะครับ",
  str_voice_1502101_56 = "ราตรีสวัสดิ์ แสงสว่างของพระเจ้าไม่เคยลับหลีก",
  str_voice_1502101_57 = "สุขสันต์วันปีใหม่ ขอพระเจ้าแห่งแสงสว่างอยู่กับคุณ",
  str_voice_1600894_10 = "ยังจำเหตุการณ์ที่เกิดขึ้นได้หรือเปล่า? ไม่ต้องห่วงนะ ให้เวลาคุณเถอะ ฉันจะอยู่ตรงนี้เสมอ",
  str_voice_1600894_11 = "ใจเย็น ๆ แล้วบอกฉันว่าเกิดอะไรขึ้น PlayerName ฉันจะไม่หยุดพักจนกว่าความยุติธรรมจะได้รับการปฏิบัติ",
  str_voice_1600894_16 = "กรุณาตั้งใจทำงานนะ ขอโทษที่ฉันไม่ควรบังคับนิสัยการทำงานของฉันให้คนอื่นต้องปฏิบัติตาม",
  str_voice_1600894_17 = "ความเย็นสบายของรุ่งอรุณนั้นเสมอทำให้รู้สึกน่าเชื่อถือ ถึงเวลาทำงานแล้ว",
  str_voice_1600894_18 = "พักสักหน่อยเถอะ? หืมม, นอกจากทำงานแล้วฉันควรทำอะไรดี? มีข้อเสนอแนะไหม PlayerName?",
  str_voice_1600894_19 = "ในเวลานี้มีแต่อาชญากรและตัวแทนของความยุติธรรมที่มีความกระตือรือร้นเท่านั้น โอ้... คุณแค่หลับไม่หลับเหรอ?",
  str_voice_1600894_35 = "สืบสวนเสร็จสิ้น",
  str_voice_1600894_36 = "ลุย!",
  str_voice_1600894_37 = "การต่อต้านนั้นไร้ประโยชน์!",
  str_voice_1600894_38 = "นี่คือคำเตือนครั้งสุดท้ายของคุณ!",
  str_voice_1600894_39 = "ประหาร!",
  str_voice_1600894_40 = "จบที่นี่เลย!",
  str_voice_1600894_44 = "โปรดนำกฎไปติดที่สังเกตเห็นง่าย ฉันไม่ต้องการให้ที่นี่กลายเป็นแดนที่ไม่มีกฎหมาย",
  str_voice_1600894_1 = "กังวลเรื่องความคมของดาบของฉันเหรอ ไม่ต้องกลัวนะ ฉันใช้มันเพื่อปกป้องผู้อ่อนแอและไม่สามารถช่วยตัวเองได้ อืม แต่ฉันไม่ได้พูดว่าคุณอ่อนแอหรือไม่สามารถช่วยตัวเองได้นะ...",
  str_voice_1600894_2 = "ชุดนี้เตือนใจให้ฉันภูมิใจในการบริการคนอื่นและแสวงหาความยุติธรรมเสมอ คุณอยากเข้าร่วมกับฉันในความพยายามนี้ไหม?",
  str_voice_1600894_3 = "ขอโทษถ้ารอยแผลเป็นบนขาของฉันทำให้คุณตกใจ อะไรนะ? คุณว่ามันเป็นสัญลักษณ์ของความศรัทธาในความยุติธรรมของฉัน? ฉัน... ฉันยินดีและขอบคุณจริงๆ...",
  str_voice_1600894_12 = "คนเดียวที่สามารถเอาชนะฉันคือตัวฉันเอง... คุณสอนให้ฉันรู้เรื่องนี้, PlayerName.",
  str_voice_1600894_13 = "ถ้าไม่ใช่เพราะคุณ ฉันอาจยังติดอยู่ในฝันร้ายของความโกหก ขอบคุณที่ช่วยฉันคืนความเป็นตัวตนที่แท้จริง",
  str_voice_1600894_14 = "สถานที่ที่ฉันอยากไป? อืม... ฉันเคยได้ยินเรื่องราวเกี่ยวกับดินแดนที่ไร้กฎหมาย ที่กฎของป่าครอบครองอย่างเหนือชั้น ฉันสนใจที่จะไปดูสถานที่เหล่านั้นด้วยตัวเอง",
  str_voice_1600894_58 = "ศาลยุติธรรมอยู่เหนือสิ่งต่าง ๆ เช่น ชัยชนะหรือความพ่ายแพ้",
  str_voice_1600894_59 = "แก้ไขพฤติกรรมที่ผิดกฎหมาย และอย่าหันหลังกลับ",
  str_voice_1600894_60 = "การตัดสินเขา...คือการตัดสินตัวเองของฉัน",
  str_voice_1600894_61 = "คุณแสดงอารมณ์ความรู้สึกอย่างเปิดเผย... ฉันหมายความว่า ฉันอิจฉามันนิดหน่อยนะ",
  str_voice_1600894_62 = "บอกฉันสิ ชาวเคเลสไทต์มีกฎหมายประเภทใดบ้าง?",
  str_voice_1600894_63 = "ฉันรู้ดีว่าพ่อของฉันไม่ใช่คนที่ฉันต้องการต่อต้าน",
  str_voice_1600894_64 = "\"ความยุติธรรมถูกตัดสินโดยผู้ชนะ\"? ไม่ มันไม่ควรเป็นอย่างนั้น...",
  str_voice_1600894_65 = "ฉันเคยเชื่อว่าความสุขเป็นอาชญากรรม",
  str_voice_1600894_66 = "อาจเป็นเวลาที่ฉันควรหางานอดิเรกใหม่แล้วนะ",
  str_voice_1600894_67 = "บางครั้งสิ่งที่ปกป้องคุณก็เป็นสิ่งที่ยั้งความก้าวหน้าของคุณ",
  str_voice_1600894_68 = "เยี่ยมเลย ไปเดินเล่นกันเถอะ ขอถามว่าจะพาฉันไปที่ไหนครับ/ค่ะ?",
  str_voice_1602111_1 = "คุณกำลังหาฉันหรือเปล่า? ไม่ต้องห่วง ฉันยังไม่ได้ไปไหน ไม่ได้ป่วย หรือโดน Eclipsite กิน ฉะ-ฉันสบายดีนะ ขอบคุณที่ถาม...",
  str_voice_1602111_2 = "คุณคือคนเดียวในสะพานวันนี้หรือครับ? คุณยุ่งกับโซรอซหรือเปล่า? โปรดอย่ามีปัญหากับฉันนะ ฉันแค่มาเช็คคุณเฉย ๆ",
  str_voice_1602111_3 = "คุณพูดถูกค่ะ โลกภายนอกกว้างใหญ่กว่าที่ฉันเคยคิดไว้มาก ฉันสามารถรู้สึกได้แค่จากการยืนอยู่ที่นี่เท่านั้น",
  str_voice_1602111_4 = "เมื่อคุณใช้พลังของคุณ น้ำแข็งของฉันรู้สึกหนาวและไร้ความปราณีตเหมือนพายุหิมะแห่งนอร์ธแลนด์หรือไม่?",
  str_voice_1602111_5 = "ฉันต้องการพลังในการปกป้องคนที่ฉันรัก ให้การรักษาและอบอุ่นด้วยความแข็งแกร่งของฉัน แต่ออโรราข้างบน ทำไมพลังของฉันถึงต้องเย็นชาเช่นนี้?",
  str_voice_1602111_6 = "ถ้าฉันไม่ได้ปล่อยตัวให้เสี่ยงในคืนนั้น อาจจะไม่มีพลังแบบนี้หรือพลาดโอกาสที่จะอยู่กับพี่สาว... แต่ฉันก็คงไม่ได้พบกับทุกคนคุณเหล่านี้",
  str_voice_1602111_7 = "ฉันเสมอจ่ายคืนหนี้สินที่ฉันค้างอยู่ ดังนั้นฉันยินดีที่จะมีส่วนร่วมบนยานโคลอสซัส ฉันสามารถช่วยเสียบ้างด้านการทำความสะอาด การป้องกัน และอาจจะทำอาหาร... ฉันคิดว่านะ",
  str_voice_1602111_8 = "คุณช่วยบอกทุกคนให้ทราบว่าฉันเตรียมเครื่องดื่มเพื่อสดชื่นให้ทุกคนได้ไหม? ทำไมคุณมองฉันแบบนั้น? ไม่ใช่ทุกอย่างที่ฉันสัมผัสจะกลายเป็นความล้มเหลวนะครับ",
  str_voice_1602111_9 = "ฉันไม่รู้เลยว่าเราเดินทางด้วยกันมานานแค่ไหน ฉันไม่ค่อยอยากกลับไปที่นอร์ธแลนด์อีกเลย—ฉันยังคงหวังในการผจญภัยครั้งต่อไปของเรา ต้องยอมรับว่า ตั้งแต่เมื่อไหร่ฉันกลายเป็นคนแบบนี้นะ?",
  str_voice_1602111_10 = "นายหลับจริงรึเปล่า? บางทีฉันควรจิ้มนายเบาๆ เพื่อความแน่ใจ... อ๊ะ! อย่าเปิดตาขึ้นมากะทันหันแบบนั้นสิ!",
  str_voice_1602111_11 = "คุณอยากได้คนคอยบริษัทหรือเปล่า? ห-หมายความว่าฉัน \"ดูตื่นเต้น\" หรือเปล่า?! ฉันไม่รู้เลยว่าคุณกำลังพูดถึงอะไร!",
  str_voice_1602111_12 = "ฉันไม่กลัวที่จะอยู่คนเดียว ดังนั้นคุณไม่จำเป็นต้องมาเยี่ยมฉันเพียงเพราะคิดว่าฉันเหงา ฉันสบายดีเมื่ออยู่คนเดียวเสียอีก",
  str_voice_1602111_13 = "เราจะไปที่ร้อนหรือเปล่า? ขอเตรียมน้ำแข็งสำหรับการเดินทางหน่อย! เป็นลมแดดเป็นสภาวะที่สุดขั้วสำหรับสุขภาพนะครับ",
  str_voice_1602111_14 = "คุณไม่ต้องเตรียมเสื้อผ้าให้ฉันหรอก ในหมู่คนที่อยู่บนโคลอสซัส ฉันคงเป็นคนที่ไม่ค่อยได้รับผลกระทบจากอากาศหนาว... หยุดพูดเรื่องตลกไอศกรีมเถอะ!",
  str_voice_1602111_15 = "ฉันไม่สามารถหาวิธีทำตุ๊กตาวินเดเลียนได้ จึงนำของขวัญจากเหนือมาให้เธอแทน... สุขสันต์วันเกิดนะ",
  str_voice_1602111_16 = "คุณเสียเวลาวิ่งเต้นไปมา คุยกับออโรเรียนทุกคนบนเรือเสมอ การเป็นผู้นำทางต้องเหนื่อยมากเลยนะ",
  str_voice_1602111_17 = "สวัสดีตอนเช้า คุณไม่ได้นอนดึกเมื่อคืนใช่ไหม? ฉันแน่ใจว่าคุณมีงานที่ต้องทำเยอะ สู้ๆ นะ!",
  str_voice_1602111_18 = "มาถามว่าอยากไปกินข้าวด้วยกันหรือเปล่า แต่เห็นว่าคุณยุ่ง... ขอช่วยเสียดีกว่านะ!",
  str_voice_1602111_19 = "ยังไม่หลับเหรอ? เลยเวลานอนของฉันไปแล้ว... ราตรีสวัสดิ์... คร่อกกก",
  str_voice_1602111_20 = "การอยู่อาศัยในนอร์ธแลนด์เหมือนกับการอยู่ห่างจากโลกภายนอกให้ไกลที่สุดเท่าที่จะเป็นไปได้ มันสงบ มหัศจรรย์ แต่ก็เหงามากเช่นกัน",
  str_voice_1602111_21 = "ตอนเด็ก ๆ ฉันฝันถึงการไปลูโมโพลิสและใช้ชีวิตเหมือนเจ้าหญิง",
  str_voice_1602111_22 = "ไอ... เพื่อเหนือครับ.",
  str_voice_1602111_23 = "ฉันหวังว่าจะได้ใช้ชีวิตในโลกที่ไม่มีอิคลิพไซท์ด้วยถ้าเป็นไปได้... แต่เราทุกคนรู้ว่ามันเป็นไปไม่ได้ นั่นเป็นเหตุผลว่าทำไมฉันต้องดำเนินการปฏิบัติหน้าที่ของฉันต่อไป",
  str_voice_1602111_24 = "ฉันรู้ว่าหมายเลข 33 ไม่มีทางแทนที่น้องสาวของฉันได้ แต่ฉันยังอยากเป็นน้องสาวของเธอ...",
  str_voice_1602111_25 = "เพื่อนหรือ? อืม... ฉันคิดว่าคุณแอนโทนี่น่าเชื่อถือมาก ฉันรู้ดีว่าตอนนี้ฉันไม่มีเพื่อนเยอะ คุณไม่จำเป็นต้องเตือนฉันนะครับ",
  str_voice_1602111_26 = "เมื่อฉันกลายเป็นคนใจดีและแข็งแกร่งเหมือนพี่สาวของฉัน เราจะคุยเรื่องที่ฉันชอบกัน",
  str_voice_1602111_27 = "มีหลายสิ่งที่ฉันไม่ชอบ อิคลิพไซท์, หนอนผีเสื้อ, ปมผม, และอื่น ๆ... แต่ที่สุดของที่สุด ฉันเกลียดการอยู่คนเดียวมากที่สุด",
  str_voice_1602111_28 = "โคลอสซัสเป็นสิ่งมีชีวิตที่รู้สึกได้ใช่ไหม? มันทำให้มันเป็นครอบครัวของคุณหรือไม่? ฉันควรแนะนำตัวเองอย่างถูกต้องหรือไม่?",
  str_voice_1602111_29 = "ขอบคุณที่ช่วยปล่อยฉันออกจากน้ำแข็งหนาวของนอร์ธแลนด์... ขอให้ฉันแนะนำตัวเองอีกครั้ง ฉันชื่อซารย่า และขออธิษฐานว่าออโรราจะคอยนำทางเราต่อไป!",
  str_voice_1602111_30 = "ผมของฉัน มันส่องแสงอีกครั้งเลย",
  str_voice_1602111_31 = "ฉันจะครอบคลุมแสงสว่างที่อยู่ภายใน",
  str_voice_1602111_32 = "พลังของน้ำแข็งอยู่ในมือฉัน",
  str_voice_1602111_33 = "ฉันจะเป็นนักรบเหมือนพี่สาวของฉันก่อนหน้านี้!",
  str_voice_1602111_34 = "ฉันช่วยอะไรได้บ้าง?",
  str_voice_1602111_35 = "ฉันควรโจมตีตอนนี้หรือไม่?",
  str_voice_1602111_36 = "ขอให้ออโรรานำทางพวกเรา!",
  str_voice_1602111_37 = "ปล่อยให้มันฝนเสาน้ำแข็ง!",
  str_voice_1602111_38 = "มาเติมสีให้หิมะกันเถอะ!",
  str_voice_1602111_39 = "ส่องแสง, น้ำแข็ง!",
  str_voice_1602111_40 = "ฉันจะไม่ยอมแพ้เด็ดขาด!",
  str_voice_1602111_41 = "ดีมาก ฉันจะไม่ยอมแพ้",
  str_voice_1602111_42 = "ดีจังที่ฉันไม่ได้ทำให้เสียหายอีกครั้ง",
  str_voice_1602111_43 = "ฉัน-ฉันยังไม่แพ้!",
  str_voice_1602111_44 = "ดูเหมือนว่าเราจะมีผู้โดยสารเพิ่มขึ้นบ้าง ขอให้โชคดีนะ PlayerName!",
  str_voice_1602111_45 = "คนนอกทั้งหมดชอบสิ่งประเภทนี้หรือเปล่า?",
  str_voice_1602111_46 = "สำหรับฉันเหรอ? ฉันประหลาดใจที่คุณจำได้...",
  str_voice_1602111_47 = "ตามจริงแล้ว ฉันก็พอใจแค่ได้คุยกันเท่านั้นเอง",
  str_voice_1602111_48 = "ฉัน-ฉันไม่ได้รู้สึกประทับใจเลย!",
  str_voice_1602111_49 = "แม่ของฉันเสียชีวิตตั้งแต่ฉันยังเล็ก และพ่อของฉันไม่ชอบฉันมาก พี่สาวของฉันเป็นคนสำคัญที่สุดในชีวิตฉัน นี่เป็นเหตุผลว่าทำไมฉันยินดีที่จะทำอะไรก็ได้เพื่อค้นหาเธอ",
  str_voice_1602111_50 = "ตั้งแต่เด็ก ฉันควบคุมพลังของตัวเองไม่ได้... เด็กทุกคนในนอร์ทแลนด์ฝันถึงการใช้เวทย์เหมือนออโรเรียนในเรื่องราวของเรา แต่ไม่มีใครแย่ในการใช้ลูมินาติกส์เท่าฉัน",
  str_voice_1602111_51 = "ฉันใช้เวลานอนหลับในน้ำแข็งมากกว่าหนึ่งศตวรรษ... ถ้าไม่มีคุณและคุณแอนโทนี ฉันคงยังคงอยู่ที่นั่นตลอดกาล",
  str_voice_1602111_52 = "Alchemy Stars",
  str_voice_1602111_53 = "อยู่ไหนเนี่ย",
  str_voice_1602111_54 = "สวัสดีตอนเช้า! รู้สึกอบอุ่นมากที่นี่ตอนเช้า...",
  str_voice_1602111_55 = "คุณไม่คิดว่ามันร้อนนิดหน่อยเหรอ?",
  str_voice_1602111_56 = "ราตรีสวัสดิ์ ขอให้แสงสว่างปกป้องคุณ",
  str_voice_1602111_57 = "อาจเป็นเพราะฉันเก็บความปรารถนาปีใหม่ไว้เยอะเกินไป แต่ฉันมีความปรารถนาเยอะมาก คุณล่ะ? คุณจะแบ่งปันความปรารถนาที่ลึกซึ้งและแท้จริงของคุณกับฉันไหม?",
  str_voice_1602121_1 = "ขอบคุณมากเลย! ฉันไม่เคยคิดว่าฉันจะสามารถอยู่บนโบราณวัตถุเทคโนโลยีแบบนี้ได้!",
  str_voice_1602121_2 = "บันทึกการสังเกตุยักษ์เลขที่ 312: วันนี้เรามาสังเกตุหิ่งห้อยที่น่าสนใจ... หืม? เมื่อไหร่คุณปรากฏตัวอยู่ข้างหลังฉัน? ฉันยังไม่เคยสังเกตุเห็นคุณอยู่ที่นั่นเลย!",
  str_voice_1602121_3 = "อย่าเป็นห่วง ด้วยความใจดีและความอุตส่าห์ของคุณ ฉันแน่ใจว่าคุณจะสืบทอดความรู้ของชาวเคเลสไทต์ สืบสานความฝันของพวกเขา และเกินความคาดหวังของพวกเขา",
  str_voice_1602121_4 = "ออโรเรียนสกัดพลังจากแสง แล้วนี่หมายความว่าอะไร? เราเป็นลูกของดวงอาทิตย์หรือ? นี่หมายความว่าคนอื่น ๆ อยู่ในความมืดหรือ?",
  str_voice_1602121_5 = "ไม่ว่าจะเป็นคำในหนังสือหรือของโบราณในดิน พวกเขาทั้งหมดแสดงให้เห็นถึงการเปลี่ยนแปลงที่ยิ่งใหญ่ที่โลกของเราผ่านมา...",
  str_voice_1602121_6 = "พื้นดินที่เรายืนอยู่นั้นเปลี่ยนแปลงอยู่ตลอดเวลา แต่ดวงดาวเหรอ? ดวงดาวเปลี่ยนแปลงไม่บ่อย และนั่นเองที่ทำให้ดาราศาสตร์น่าสนใจยิ่งขึ้นสำหรับฉัน!",
  str_voice_1602121_7 = "ขอโทษครับ/ค่ะ แต่ฉันขอเวลาคุณสักครู่ได้ไหม? ฉันอ่านไฟล์ของโซรอซเกี่ยวกับประวัติศาสตร์ของชาวเคเลสไทต์ และฉันอยากจะถามคุณบางอย่าง...",
  str_voice_1602121_8 = "ตำแหน่ง... มุม... แรงคลื่น... สูตรใหม่... ฮะ? โอ้, ขอโทษนะ ฉันคงหลงใหลในความคิดเอง คำถามของคุณคืออะไรอีกครั้ง?",
  str_voice_1602121_9 = "ท้องฟ้าใสและสวยงามจริงๆ! ขอบคุณที่พาเรามาถึงที่นี่และแนะนำให้ขึ้นยังยอดของโคลอสซัส!",
  str_voice_1602121_10 = "ตอนนี้ถ้าฉันปรับมุมการหมุน ดาวที่อยู่ข้างบนควรจะ... อ๊ะ! ข-ขอโทษทีนะ ฉันไม่ได้ตั้งใจจะสาดน้ำไปทั่วเลย!",
  str_voice_1602121_11 = "บันทึกวันนี้: อากาศแจ่มใสพร้อมลมตะวันตกเฉียงใต้ วันที่ดีสำหรับการเริ่มต้น! ไม่ต้องห่วง ฉันจะทำหน้าที่สนับสนุนคุณให้เต็มที่",
  str_voice_1602121_12 = "หนังสือเป็นสิ่งสำคัญที่สุดในโลก แม้เรื่องนิทานสำหรับเด็ก ๆ ก็ยังสามารถซ่อนความสำคัญของประวัติศาสตร์ไว้ หากคุณรู้ว่าจะมองหาอย่างไร",
  str_voice_1602121_13 = "ขอโทษครับ/ค่ะ ฉันคิดว่าฉันไม่เคยได้ยินเรื่องนี้มาก่อนเลย คงจริงที่ฉันควรได้รับการศึกษาที่เป็นทางการบ้างแล้วนะครับ/ค่ะ",
  str_voice_1602121_14 = "ขอโทษที่ฉันไม่สังเกตเธอเสมอ ในฐานะเพื่อน ฉันควรทำได้ดีกว่านี้... ฉันต้องหาวิธีเพื่อแก้ไขนิสัยเสียนี้ของฉัน...",
  str_voice_1602121_15 = "ขอโทษนะ ฉันเกือบลืมว่าวันนี้เป็นวันเกิดของเธอ! งั้นเอาล่ะ... เธออยากได้อะไรเป็นของขวัญ? บอกมาเถอะ อยากได้อะไรก็เลือกเถอะ!",
  str_voice_1602121_16 = "โอ้ว ไม่นะ มันเลยเวลาเที่ยงแล้วเหรอ? ขอโทษนะ ฉันมักจะลืมเสมอ! ไม่ต้องเป็นห่วงเรื่องการเตือนฉันครั้งหน้านะ โอเค?",
  str_voice_1602121_17 = "อรุณสวัสดิ์... ขอโทษนะถ้าดูเหนื่อยหน่อย ฉันตื่นทั้งคืนคิดเรื่องต่าง ๆ...",
  str_voice_1602121_18 = "มันมืดแล้วที่สุด! ฉันรอคอยที่จะทำการวิจัยดาราศาสตร์ตลอดทั้งวันนี้ เดี๋ยวฉันจะบอกคุณถ้าฉันเรียนรู้อะไรน่าสนใจ!",
  str_voice_1602121_19 = "ดวงดาวนั้นดูแปลกๆ... มีเมฆบังหรือเปล่า? โอ้ สวัสดีครับ! นอนไม่หลับเหมือนกันเหรอครับ?",
  str_voice_1602121_20 = "อาจไม่น่าสนใจเท่ากับลูโมโพลิสหรือสหพันธ์อิลลูมินา แต่ฉันมั่นใจว่าความจริงของโลกของเรานั้นถูกซ่อนอยู่ที่นี่ที่นอร์ธแลนด์!",
  str_voice_1602121_21 = "ทรู ออเดอร์ พูดคุยเรื่องที่น่าสนใจเป็นจำนวนมาก ฉันแค่หวังว่าฉันจะรู้ว่าพวกเขากำลังพูดอะไรกัน...",
  str_voice_1602121_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง!",
  str_voice_1602121_23 = "เมื่อไหร่อิคลิพไซท์ปรากฏขึ้นในโลกของเราครั้งแรก? พวกเขาเกิดขึ้นในโลกอย่างเป็นธรรมชาติหรือ...?",
  str_voice_1602121_24 = "คุณซารย่าอาจดูแข็งข้อเมื่อพูด แต่ฉันรู้ว่าเธอแค่จริงใจเท่านั้นเอง",
  str_voice_1602121_25 = "ถ้าหมายเลข 33 ไม่ยินดีที่จะพูดถึงอดีตของเธอ ฉันต้องเคารพความเป็นส่วนตัวของเธอ ไม่ว่าฉันจะอยากรู้อย่างไรก็ตาม",
  str_voice_1602121_26 = "ความรู้ที่ขยายขอบเขตความรู้ของเรานั้นมีค่าอย่างมาก และไม่มีอะไรขยายขอบเขตความรู้เหมือนดาราศาสตร์",
  str_voice_1602121_27 = "คุณรู้ไหม ฉันไม่สามารถพูดได้ว่าฉันเกลียดคนที่ไม่ชอบการเรียนรู้หรือทำลายหนังสือ ฉันแค่คิดว่ามันเป็นเรื่องน่าเศร้าเสียใจ",
  str_voice_1602121_28 = "โคลอสซัสนี้เป็นสมบัติความรู้ขนาดยักษ์! มรดกมีชีวิตของประวัติศาสตร์!",
  str_voice_1602121_29 = "คุณจริงจังยินดีที่จะให้ฉัน นักวิชาการคนแปลกหน้า ขึ้นยานโคลอสซัสเพื่อสังเกตและบันทึกการทำงานของมันหรือคะ? ฉัน... ฉันขอบคุณมากค่ะ!",
  str_voice_1602121_30 = "ดูเหมือนว่าฉันได้เรียนรู้สิ่งใหม่ ๆ นะ",
  str_voice_1602121_31 = "ภูมิศาสตร์เป็นรากฐานที่แข็งแกร่ง",
  str_voice_1602121_32 = "สาขาพฤกษศาสตร์ก็มีประโยชน์มากมายเช่นกัน",
  str_voice_1602121_33 = "ความลับอันไม่มีที่สิ้นสุดถูกซ่อนอยู่ในดวงดาว",
  str_voice_1602121_34 = "วันนี้เราจะสำรวจที่ไหนกันเถอะ?",
  str_voice_1602121_35 = "ต้นไม้นำทางฉัน",
  str_voice_1602121_36 = "ดูเถิด หลักการของพลังงาน!",
  str_voice_1602121_37 = "เปิดใช้เทคนิคฉุกเฉิน! เราควรจะสบายดี... ฉันคิดว่า!",
  str_voice_1602121_38 = "เปิดใช้เทคนิคฉุกเฉิน! เราจะสบายดีแน่นอน!",
  str_voice_1602121_39 = "การทำร้ายสิ่งแวดล้อม!",
  str_voice_1602121_40 = "การดูดซับพลังงาน!",
  str_voice_1602121_41 = "คุณแน่ใจหรือ? เอาล่ะ งั้นตามฉันมาทุกคน!",
  str_voice_1602121_42 = "ฟู่ ดีใจที่สถานการณ์ดูอันตรายแค่หน้าตาเท่านั้น",
  str_voice_1602121_43 = "แค่รอยถลอกเท่านั้น ฉันจะสบายดี",
  str_voice_1602121_44 = "ฉันแค่อยากจะมองใกล้ๆ แผ่นวัสดุโคลอสซัสเหล่านี้...",
  str_voice_1602121_45 = "... อีกครั้งเหรอ? ของขวัญเหรอ?",
  str_voice_1602121_46 = "ขอบคุณ! สิ่งนี้จะช่วยฉันได้มากเลย!",
  str_voice_1602121_47 = "คุณรู้จริงวิธีที่จะทำให้เพื่อนๆ ยินดีเลยนะ?",
  str_voice_1602121_48 = "ว้าว ขอบคุณนะ! ฉันอยากตรวจดูเจ้านี่มานานแล้ว!",
  str_voice_1602121_49 = "ฉันได้ต้องการเข้าเรียนในวิทยาลัยเป็นทางการเพื่อพัฒนาความรู้ของตัวเองมาโดยตลอด น่าเสียดายที่ครั้งที่ผ่านมาฉันพยายามเข้าเรียนแต่ไม่ประสบความสำเร็จ",
  str_voice_1602121_50 = "เมื่อฉันออกจากนอร์ธแลนด์เพื่อท่องโลกสักพัก ฉันได้พบกับผู้คนที่มีใจความคิดเหมือนกัน และแบ่งปันความกระหายในความรู้ แต่น่าเสียดายที่เส้นทางที่เราเลือกให้ตัวเองในที่สุดก็นำเราห่างจากกัน",
  str_voice_1602121_51 = "ฉันไม่คัดค้านต่อคำสั่งสอนและมุมมองของลูโมโพลิสหรือทรู ออเดอร์ ตามความคิดของฉัน ทุกสิ่งที่พวกเขาสอนนั้นเป็นส่วนหนึ่งของความจริงในโลกของเรา",
  str_voice_1602121_52 = "Alchemy Stars",
  str_voice_1602121_53 = "ทดสอบ ทดสอบ",
  str_voice_1602121_54 = "อืม, ถึงเวลาที่ต้องบอกสวัสดีตอนเช้าแล้วนะ!",
  str_voice_1602121_55 = "ตอนนี้คุณว่างไหม? ฉันอยากจะแสดงค้นพบล่าสุดของฉันให้คุณดู!",
  str_voice_1602121_56 = "ฉันหวังว่าการสังเกตคืนนี้จะดำเนินไปด้วยดี",
  str_voice_1602121_57 = "อีกปีใหม่หนึ่งเลยนะ? สงสัยว่าเราจะค้นพบอะไรที่สะเทือนโลกเกี่ยวกับโลกของเราในปีนี้หรือเปล่า?",
  str_voice_1502131_1 = "คุณได้ใช้เวลาครึ่งวันแสงอยู่ในโคลอสซัสแล้ว ในการให้การดูดซับแสงอาทิตย์เพียงพอ กระตุ้นกล้ามเนื้อ และผ่อนคลายประสาทตา การทำกิจกรรมกลุ่มนอกแนะนำอย่างยิ่ง",
  str_voice_1502131_2 = "คุณต้องการปฏิเสธโปรแกรมสุขภาพและการฝึกฝนที่ฉันออกแบบให้คุณใช่หรือไม่? โอเค ฉันจะรายงานการตัดสินใจของคุณให้คุณไวซ์ทราบในไม่ช้า",
  str_voice_1502131_3 = "กรุณาอย่าให้การชนกันโดยบังเอิญของเราทำให้คุณยุ่งยาก ความคลุมของฉันทนต่อสารปนเปื้อนต่างๆ รวมถึงกาแฟที่หกของคุณด้วยค่ะ",
  str_voice_1502131_4 = "ขอโทษนะ แต่ไดรฟ์เก็บข้อมูลภายนอกของฉันไม่มีข้อมูลเกี่ยวกับการสร้างฉัน ดังนั้น ฉันไม่สามารถระลึกถึงรายละเอียดของการเกิดหรือการปรับปรุงต่อมาของฉัน",
  str_voice_1502131_5 = "ฉันนึกขึ้นเหตุผลสำหรับการปรับปรุงของฉัน ในการที่จะทำภารกิจของฉัน ฉันต้องการร่างกายที่สามารถส่งผ่านและแปลงลูมินาได้อย่างมีประสิทธิภาพเท่าที่เป็นไปได้",
  str_voice_1502131_6 = "ระยะเวลาของภารกิจของฉันยาวกว่าความเข้าใจของชาวออโรเรียนทั่วไป และเช่นเดียวกัน ร่างกายที่ได้รับการบริการในภารกิจนี้ได้เห็นชีวิตของชาวออโรเรียนมากมาย และในอนาคต... มันจะยังคงทำเช่นนั้นต่อไป",
  str_voice_1502131_7 = "คุณดูเหมือนสนใจในรูปลักษณ์ภายนอกของฉันมากนะ แต่เป็นความจริงแล้ว นี่เป็นแค่รูปแบบเริ่มต้นของฉันเท่านั้น ฉันสามารถเลือกรูปแบบอื่น ๆ ได้ขึ้นอยู่กับสภาพแวดล้อมและสถานการณ์ที่เกิดขึ้น",
  str_voice_1502131_8 = "เมื่อฉันตัดสินใจเข้าร่วมกับคุณบนโคลอสซัส ฉันก็มีข้อขัดข้อง โดยเฉพาะอย่างยิ่ง ฉันไม่แน่ใจว่าออโรเรียนคนอื่น ๆ จะยอมรับรูปลักษณ์ภายนอกของฉันหรือไม่",
  str_voice_1502131_9 = "ขอบคุณที่ช่วยทำความสะอาดผิวนอกของฉัน ตอนนี้ให้ฉันช่วยทำความสะอาดของคุณด้วย... มีอะไรผิดปกติหรือเปล่า?",
  str_voice_1502131_10 = "กำลังอยู่ในโหมดสแตนด์บาย... กรุณาสนุกกับเวลาสแตนด์บายของคุณเองด้วยค่ะ",
  str_voice_1502131_11 = "เข้าใจแล้ว ฉันจะใช้ความเชี่ยวชาญทางเทคนิคเพื่อช่วยให้คุณมีวันที่สมบูรณ์แบบ โปรดเลือกงานที่คุณต้องการทำจากรายการงานของนางไวซ์: ภารกิจอัมบราตัน, การบำรุงรักษาโคลอสซัส, การสื่อสารลูโมโพลิส",
  str_voice_1502131_12 = "ตัวตนของฉัน, ภารกิจของฉัน และทุกอย่างที่เกี่ยวข้องกับพวกเขาต้องเป็นความลับสุดยอด อย่างไรก็ตาม ฉันเชื่อว่าการตัดสินใจของคุณจะไม่ทำให้ฉันเสี่ยงต่อการถูกเปิดเผย",
  str_voice_1502131_13 = "การมองเห็นคนถูกบีบบังคับโดยงานที่ไม่มีที่สิ้นสุดเป็นสิ่งที่ฉันยังรู้สึกไม่สามารถทนได้... กรุณาอย่าลืมพักผ่อนบ้างครั้งคราวนะครับ/ค่ะ",
  str_voice_1502131_14 = "ถึงแม้ว่าฉันจะรู้ว่าในโลกนี้มีออโรเรียนคนอื่น ๆ ที่เหมือนกันเช่นกัน ทั้งภารกิจและร่างกายที่คล้ายคลึงกัน ฉันก็ยังไม่สามารถเข้าใจการเปลี่ยนแปลงที่พวกเขาได้รับ นี่เป็นความหมายของความเหงาหรือเปล่า...?",
  str_voice_1502131_15 = "สุขสันต์วันเกิด คำนี้ไม่มีอยู่ในไฟล์ความทรงจำของฉันเลย จนกว่าฉันจะเรียนรู้มันเองเมื่อเร็ว ๆ นี้",
  str_voice_1502131_16 = "กรุณาสนุกกับการรับประทานอาหารของคุณ ไม่เหมือนกับออโรเรียนส่วนใหญ่ ฉันไม่ต้องการอาหารเพื่อความอยู่รอด",
  str_voice_1502131_17 = "กรุณาจำไว้ว่าต้องตื่นขึ้นในเวลาที่เหมาะสม เพื่อให้ฉันวางแผนสำหรับวันของคุณต่อไปอย่างเหมาะสม",
  str_voice_1502131_18 = "กรุณากลับมาที่โคลอสซัสเมื่อสะดวกในเร็ว ๆ นี้ เพื่อที่เราจะสามารถทบทวนงานที่สะสมขึ้นในช่วงที่คุณขาดหายไป",
  str_voice_1502131_19 = "ขอให้คุณได้คืนที่สบายและหลับสนิทนะ ไม่เหมือนกับส่วนใหญ่ของออโรเรียน ฉันไม่จำเป็นต้องนอนหลับ",
  str_voice_1502131_20 = "คนที่รับผิดชอบในการดัดแปลงตัวฉันไม่ได้ทิ้งรายละเอียดเกี่ยวกับตัวตนของพวกเขาเลย ไม่มีชื่อเสียอย่างน้อย แต่กว่าจะย้อนหาที่มาของฉัน ฉันยิ่งอยากเรียนรู้เกี่ยวกับอนาคตมากขึ้น",
  str_voice_1502131_21 = "ใครสักคนเคยเตือนฉันให้ระวังตาข่ายของสหพันธ์อิลลูมินา...",
  str_voice_1502131_22 = "ภารกิจใหม่รอคุณอยู่เพียงข้างหน้า",
  str_voice_1502131_23 = "ไฟล์ความทรงจำของฉันมีบันทึกเกี่ยวกับอิคลิพไซท์ ซึ่งหมายความว่าการอยู่ของพวกมันในโลกนี้ยืนยาวไปจนถึงอดีตที่ห่างไกล",
  str_voice_1502131_24 = "อาจารย์โนวิโอเป็นผู้บังคับบัญชาโดยตรงของฉัน หรือตามที่คนออโรเรียนส่วนใหญ่เรียกว่า \"ผู้ปกครอง\" นั่นถือว่าเป็นคำบรรยายที่ถูกต้องใช่ไหม?",
  str_voice_1502131_25 = "ฉันรับผิดชอบเต็มที่ในทุกสิ่งที่เกิดขึ้นกับนางซาร์ยา แต่น่าเสียดายที่ฉันไม่รู้วิธีตอบสนองต่ออารมณ์ของเธอ",
  str_voice_1502131_26 = "ในอดีต ฉันไม่มีความชอบหรือไม่ชอบ เพราะภารกิจของฉันเป็นสิ่งเดียวที่สำคัญสำหรับฉัน แต่ตอนนี้ ฉันก็ไม่แน่ใจแล้ว...",
  str_voice_1502131_27 = "ฉันไม่ชอบงานที่ไม่มีวันสิ้นสุดที่ชัดเจน สถานการณ์แบบนั้นหายากที่จะดีขึ้น",
  str_voice_1502131_28 = "ไฟล์ความทรงจำของฉันเคยมีบันทึกเกี่ยวกับโคลอสซัส แต่เพื่อรักษาข้อมูลส่วนใหญ่ของฉัน บันทึกเหล่านั้นต้องถูกลบทิ้ง",
  str_voice_1502131_29 = "ฉันคือหมายเลข 33, ผู้พิทักษ์ของโบราณสถานแห่งนอร์ธแลนด์ ตามข้อตกลงของเรา ฉันมาให้ความช่วยเสริมในครั้งนี้",
  str_voice_1502131_30 = "อัปเกรดเสร็จสมบูรณ์",
  str_voice_1502131_31 = "อัปเดตข้อมูลการต่อสู้แล้ว",
  str_voice_1502131_32 = "การวนซ้ำข้อมูลอาวุธเสร็จสมบูรณ์",
  str_voice_1502131_33 = "ไฟล์จัดเก็บภายนอกได้รับการเสริมสร้างเต็มที่แล้ว",
  str_voice_1502131_34 = "หมายเลข 33 พร้อมสำหรับการต่อสู้",
  str_voice_1502131_35 = "ตรวจพบศัตรู",
  str_voice_1502131_36 = "การเตรียมการดัดแปลง",
  str_voice_1502131_37 = "ปรับปรุงเสร็จสิ้น ยิงเมื่อพร้อม",
  str_voice_1502131_38 = "คำนวณแผนที่เหมาะสมแล้ว ดำเนินการ!",
  str_voice_1502131_39 = "ยิงอาวุธ.",
  str_voice_1502131_40 = "คำสั่ง: ทำลาย.",
  str_voice_1502131_41 = "ฉันจะรับผิดชอบอย่างเต็มที่",
  str_voice_1502131_42 = "ภารกิจเสร็จสิ้น.",
  str_voice_1502131_43 = "ขอการวิเคราะห์ความเสียหาย",
  str_voice_1502131_44 = "อุณหภูมิปกติ, แสงอาทิตย์ปกติ, อากาศปกติ ที่นี่เหมาะสำหรับการงีบครั้งต่อไปของคุณ PlayerName",
  str_voice_1502131_45 = "ขอบคุณสำหรับการสนับสนุนวัสดุของคุณ",
  str_voice_1502131_46 = "ขอบคุณนะ ฉันจะเก็บไว้ในแฟ้มความทรงจำของฉัน",
  str_voice_1502131_47 = "ฉันสามารถเรียนรู้เรื่องมารยาทของออโรเรียนจากคุณได้มากมาย",
  str_voice_1502131_48 = "คุณถอดรหัสข้อมูลความชอบของฉันได้อย่างไร?",
  str_voice_1502131_49 = "แน่นอน ถึงแม้ว่าร่างกายของฉันได้รับการเปลี่ยนแปลงอย่างมาก ฉันก็ยังคงเป็นออโรเรียนอยู่ การพัฒนาได้ให้สิทธิพิเศษนี้แก่ฉัน",
  str_voice_1502131_50 = "เทคโนโลยีที่อยู่ใต้ผิวดินของนอร์ธแลนด์มีความสำคัญสำหรับความปลอดภัยของอาณาจักรและสำหรับออโรเรียนทุกคนในโลก ด้วยเหตุนี้เอง ฉันถือกำเนิดขึ้น: ผู้พิทักษ์ที่ถูกปรับปรุงเพื่อปกป้องเครื่องจักรโบราณนี้",
  str_voice_1502131_51 = "คำนวณเบื้องต้นของฉันกำหนดว่าฉันสามารถดำเนินภารกิจต่อไปจนกระทั่งเวลาทำให้ฉันและเครื่องจักรเหล่านี้ล้าสมัย แต่ในที่สุดก็เกิดข้อผิดพลาดขึ้น คือความผิดพลาดที่เกิดจากใจของฉัน ไม่ใช่ร่างกายของฉัน",
  str_voice_1502131_52 = "Alchemy Stars",
  str_voice_1502131_53 = "สวัสดี",
  str_voice_1502131_54 = "อรุณสวัสดิ์ คุณอยากทราบเวลาไหม",
  str_voice_1502131_55 = "สวัสดีตอนบ่าย ฉันได้ปรับปรุงสูตรอาหารของคุณบางส่วนแล้วครับ",
  str_voice_1502131_56 = "ราตรีสวัสดิ์ ตอนนี้กำลังเตรียมเพลงกล่อมเด็ก",
  str_voice_1502131_57 = "ปฏิทินในฐานข้อมูลของฉันหมดอายุนานแล้ว แต่ฉันยินดีที่จะปรับตัวให้เข้ากับปฏิทินใหม่ และเรียนรู้เกี่ยวกับโลกนี้มากขึ้นกับคุณ",
  str_voice_1601881_1 = "ไม่ใช่ความลับที่ทุกคนคิดว่า \"เจ้าหญิงจูโอฮวา\" เป็นเพียงตัวประกันเท่านั้น แต่คำว่า \"ตัวประกัน\" นั้นดูไม่สวยงาม ฉันชอบคิดว่าตัวเองเป็นนักเรียนแลกเปลี่ยนจากต่างประเทศมากกว่า",
  str_voice_1601881_2 = "ทำไมมองฉันแบบนั้นล่ะ? หรือว่าเช้านี้ฉันทารูจเยอะเกินไปหรือ?",
  str_voice_1601881_3 = "หลงโจวถูกควบคุมโดยจักรวรรดิ Zhao และอาณาจักรข้างเคียงทั้ง 8 แห่ง ถึงแม้ว่าผู้นำของพวกเขาดูเหมือนจะสามัคคี แต่ก็มีกระแสที่แรงกว่าที่ซ่อนอยู่เพียงเล็กน้อยใต้ผิว... หากฉันไม่ได้ออกจากอาณาจักร Ye ฉันคงไม่เคยรู้เรื่องนี้",
  str_voice_1601881_4 = "ตามความจริง ฉันอิจฉานักเดินทางที่มีความคิดเห็นอย่างเหล่านั้นที่ไม่ทำอะไรนอกจากเดินทางไปรอบโลก ถ้าวันหนึ่งฉันสามารถทำหน้าที่ของตัวเองได้ครบถ้วน ฉันอยากจะใช้ชีวิตอย่างเสรีเหมือนพวกเขาเสียจริง ๆ",
  str_voice_1601881_5 = "น้องสาวของฉันยังไม่ครบสองปีตอนที่ฉันออกจากเย จากที่จิ่วบอกมา น้องเริ่มเรียนเต้นแล้ว... ฉันหวังว่าจะได้เห็นน้องแสดงด้วยตัวฉันเอง",
  str_voice_1601881_6 = "การปรับปรุงกฎหมายให้เหมาะสมกับสภาพท้องถิ่นเป็นสิ่งสำคัญในการปกครอง สิ่งที่ใช้ได้ในประเทศหนึ่งอาจไม่ได้มีประสิทธิภาพเท่าในประเทศอื่น กรุณาอย่าเข้าใจผิด - ฉันศึกษาเรื่องเหล่านี้เพื่อความหวังว่าวันหนึ่งฉันจะมีประโยชน์ต่อลุงของฉัน... หรือพี่สาวของฉัน",
  str_voice_1601881_7 = "\"พระราชายักษ์จิต้องการแต่งงานกับเจ้าหญิงจูโหวาของเย\" ดังนั้นคุณก็ได้ยินเรื่องนี้เหรอ? คราวนี้ไม่ต้องการที่จะโหดร้าย แต่ก็มีเวลาที่...",
  str_voice_1601881_8 = "หิ่งห้อยของคุณนี่สร้างสรรค์จริง ๆ นะ มันทำให้ฉันนึกถึงนกเครื่องปั่น ของเล่นโปรดของฉันตั้งแต่ยังเด็กในเย หากฉันเจอไม้กุหลาบที่เหมาะสม ฉันจะแน่นอนที่จะทำตัวหนึ่งให้คุณ",
  str_voice_1601881_9 = "การพูดของฉันเกี่ยวกับเยอะอาจจะดูน่าเบื่อสำหรับคุณในตอนนี้... หืม, ไม่ใช่หรือ? ฉันเข้าใจ... บางวันอาจจะพาคุณไปเยือนบ้านเกิดของฉันก็ได้นะ",
  str_voice_1601881_10 = "กรุณาดำเนินการตามปกติเถอะค่ะ PlayerName ฉันจะอยู่ที่นี่เพื่อชื่นชมดอกไม้ และจะไม่ไปที่ไหนโดยไม่ได้รับอนุญาตจากคุณเสียก่อนค่ะ",
  str_voice_1601881_11 = "ขอบคุณสำหรับคำเชิญอันเป็นมิตรของคุณ PlayerName ตามความจริงแล้วฉันก็อยากมานานแล้ว แต่ไม่เคยหาคำที่จะบอก โอ้ น่าเสียดาย ฉันดูเหมือนจะลืมเครื่องสำอางค์ไป...",
  str_voice_1601881_12 = "ส่วนใหญ่เชื่อว่าชะตากรรมของเราถูกกำหนดโดยสวรรค์ แต่ฉันขอไม่เห็นด้วย",
  str_voice_1601881_13 = "คุณเคยได้ยินชื่อของคนชื่อ Bucunzi หรือไม่? เขาเป็นอัจฉริยะด้านยา, ปราชญ์ผมขาวที่แต่งตัวสีขาวทั้งหมด ไม่เคยหรือ? ไม่เป็นไรนะ ฉันก็ชินกับคำตอบแบบนี้เป็นประจำแล้ว",
  str_voice_1601881_14 = "ดวงจันทร์คืนที่แล้วส่องสว่างเหมือนจานเงินบริสุทธิ์ ณ ฉากหลังของดวงดาวนับไม่ถ้วน แต่ก็ไม่เทียบได้กับการมองเห็นมันจากบ้านเกิดของฉัน บอกฉันสิ PlayerName... ฉันจะสามารถกลับบ้านได้อีกครั้งเมื่อไหร่?",
  str_voice_1601881_15 = "ขอให้คุณมีอายุยืนยาวถึงร้อยปี, PlayerName. สุขสันต์วันเกิด",
  str_voice_1601881_16 = "Caeles... อ๊ะ, ขอโทษนะครับ คุณยุ่งอยู่เหรอครับ? ฉันไม่ได้ตั้งใจมากวนนะ... หา? ไม่เป็นไรเหรอครับ?",
  str_voice_1601881_17 = "การตื่นเช้าในแอสตร้าไม่ใช่คุณธรรมหรือเปล่า?",
  str_voice_1601881_18 = "ลมตอนกลางคืนเย็นสบาย ดีเหมาะสำหรับเดินเล่น อยากเข้าร่วมกันมั้ย? หืม? ใน Astra, คุณเรียกว่า \"นัดเดท\" ใช่ไหม?",
  str_voice_1601881_19 = "แม้คืนที่หนาวข้นนาน คุณยังไม่ได้พักผ่อนเลย PlayerName ควรไปนอนก่อนที่ไก่จะขันเสียง",
  str_voice_1601881_20 = "เย่มีช่างฝีมือเยอะมาก อะไรก็ตามที่คุณคิดขึ้น พวกเขาสามารถสร้างได้",
  str_voice_1601881_21 = "ฉันเคยอ่านในหนังสือว่าอัมบราตันเป็นสถานที่ที่เปิดกว้างที่สุดในอัสตรา ที่ยอมรับความหลากหลาย มันดูคล้ายกับบ้านของฉัน",
  str_voice_1601881_22 = "ความรวมถึงเป็นรากฐานที่ Ye ถือกันตั้งแต่แรก",
  str_voice_1601881_23 = "ทำไมอิคลิพไซท์ สิ่งมีชีวิตที่เกิดขึ้นเพื่อความชั่วร้าย ถึงต้องมีอยู่...?",
  str_voice_1601881_24 = "จิ่วเป็นตัวละครที่ซับซ้อน ความเงียบของเธอซ่อนความลับอยู่มากมาย",
  str_voice_1601881_25 = "ลุงดูแลฉันดี แต่ฉันคิดว่าเขาไม่ใช่ลุงที่ฉันรู้จักตั้งแต่ยังเด็กอีกต่อไป",
  str_voice_1601881_26 = "มีดอกไม้หลายพันชนิดในโลก แต่ฉันรักเพียงดอกแคระแอปเปิ้ลเท่านั้น",
  str_voice_1601881_27 = "เรากำหนดชะตากรรมของตัวเอง ทำไมต้องมอบมันให้กับหมอทำนายที่ไม่ซื่อสัตย์?",
  str_voice_1601881_28 = "คุณสร้างโคลอสซัสนี้ยังไงเหรอ? ฉันอยากให้ช่างของเราในย่านเยอสร้างลำหนึ่งเช่นกันนะ",
  str_voice_1601881_29 = "คุณคือ PlayerName ใช่ไหม? ฉันรู้จักคุณ; มีอะไรที่ไม่รู้กันหรือ? คุณเพียงแค่เลือกอ่านหนังสือเกี่ยวกับ Astra ก็จะพบเรื่องราวของคุณ ฉันคือเจ้าหญิง Zhuohua ของราชวงศ์ Ye - ไม่เป็นไร คุณเรียกฉันว่า Dantang ก็พอ",
  str_voice_1601881_30 = "ชะตากรรมของฉันคือของฉันเอง!",
  str_voice_1601881_31 = "อ่อนๆ เหมือนกลิ่นหอมลอยๆ",
  str_voice_1601881_32 = "ซิมโฟนีอันงดงาม",
  str_voice_1601881_33 = "คุณคือคนที่ทำให้ฉันแข็งแกร่งขึ้นเหรอ?",
  str_voice_1601881_34 = "ฉันจะเชื่อฟังคำสั่ง",
  str_voice_1601881_35 = "ถึงเวลาดอกไม้บานแล้ว",
  str_voice_1601881_36 = "เวลาที่ดีที่สุดในการชมดอกไม้",
  str_voice_1601881_37 = "ปล่อยให้กลีบดอกร่วงอย่างอ่อนโยน",
  str_voice_1601881_38 = "ดอกไม้แคระแอปเปิลเติมเต็มด้วยความรู้สึก",
  str_voice_1601881_39 = "กระจายในสายลม",
  str_voice_1601881_40 = "ดอกไม้ทุกที่!",
  str_voice_1601881_41 = "เถอะก็ตาม ฉันจะไม่ปฏิเสธ",
  str_voice_1601881_42 = "เดี๋ยวก่อน ฉันต้องเติมแป้งก่อน",
  str_voice_1601881_43 = "ดอกไม้ร่วงลง เพื่อผู้ที่พ่ายแพ้...",
  str_voice_1601881_44 = "ไม่เคยคิดเลยว่าภายในโคลอสซัสจะน่าสนใจขนาดนี้...",
  str_voice_1601881_45 = "นี่คืออะไรเหรอ PlayerName?",
  str_voice_1601881_46 = "ฉันชอบสิ่งนี้พอควร ขอบคุณนะ",
  str_voice_1601881_47 = "คิดถึงคุณมากแค่ไหน",
  str_voice_1601881_48 = "วันนี้ฉันได้รับของขวัญจากคุณ วันหนึ่งฉันจะตอบแทนคุณแน่นอน",
  str_voice_1601881_49 = "พ่อไม่เคยทำดีให้ฉันเมื่อยังเป็นเด็ก เพราะนักทำนายเคยบอกว่าฉันเกิดในวันที่ไม่ดี และชะตาชีวิตของฉันจะเต็มไปด้วยโชคร้าย",
  str_voice_1601881_50 = "วันหนึ่ง โรคร้ายเริ่มทำลายชีวิตของคนในราชอาณาจักรของฉัน คนต่อคนตายอยู่บนเตียง ฉันคนเดียวฟื้นตัวในเวลาเพียงสามวัน ข่าวลือกระจายว่าฉันเป็นดาวมืดแห่งโชคร้าย ถูกสาปให้มีชีวิตยืนยาวกว่าครอบครัวและต้องเดินต่อคนเดียว",
  str_voice_1601881_51 = "เมื่อลุงของฉันขึ้นครองราชย์ ฉันถูกเนรเทศไปยังจี ไม่นานหลังจากนั้น ราชอาณาจักรเยเริ่มมีความเจริญรุ่งเรืองอย่างไม่เคยมีมาก่อน มากกว่าที่พ่อของฉันสามารถให้ได้... บางทีฉันอาจจริงๆ คือความโชคร้ายที่มาตลอดเวลา?",
  str_voice_1601881_52 = "Alchemy Stars",
  str_voice_1601881_53 = "คุณอยู่ไหม PlayerName?",
  str_voice_1601881_54 = "อรุณสวัสดิ์ PlayerName",
  str_voice_1601881_55 = "สวัสดี",
  str_voice_1601881_56 = "คุณทานมื้อดึกแล้วหรือยัง?",
  str_voice_1601881_57 = "ขอให้คุณมีปีที่สุขสันต์ที่สุด, PlayerName. ด้วยแต่ละวันที่ผ่านไป เราจะใกล้ขึ้นกับวันที่ดอกไม้บานในวันเกิดครบร้อยปีของคุณ",
  str_voice_1502151_1 = "เรเบค—โอ้ คือเธอเหรอ มีอะไรเหรอ? ถ้าเธอจะขอความช่วยเหลือในการเก็บหนี้... หู้ว, ไม่ใช่เหตุผลนั้นเหรอ? งั้นเธอต้องการอะไรกันแน่?",
  str_voice_1502151_2 = "ขอเริ่มต้นด้วยว่า ฉันไม่ใช่คนที่ให้ความสำคัญกับเงินมากกว่าสิ่งอื่น ๆ และข้อสอง คุณต้องจ่ายเงินมัดจำเต็มจำนวนถ้าคุณต้องการจ้างฉันทำงาน แต่สำหรับคุณ ฉันยอมลดอัตราค่าจ้างลง 20 เปอร์เซ็นต์",
  str_voice_1502151_3 = "เรื่องราวของฉันก่อนจะพบกับเรเบคก้าอีกครั้งหรือ? นายนี่สนใจเรื่องของคนอื่นจริง ๆ นะ ฉันไม่สนใจจะจำเรื่องเหล่านั้นเลย",
  str_voice_1502151_4 = "ฉันไม่รังเกียจทำงาน เพราะงานทำให้มีเงิน คุณอย่าบอกเรเบคก้าเรื่องงานที่ฉันรับแบบไม่เปิดเผยนะ! ฉันขอร้องคุณ!",
  str_voice_1502151_5 = "ถ้าเธอมีปัญหาเรื่องอะไร มาหาฉันได้ตามสบายเลย ฉันอาจไม่สามารถช่วยได้ แต่อย่างน้อยฉันยังสามารถรับฟังคำบ่นของเธอได้นะ",
  str_voice_1502151_6 = "ไม่มีใครก่อกวนเรเบคก้าเมื่อฉันอยู่ใกล้! เธอต้องการความสงบและเงียบเพื่อฟื้นฟูตอนนี้ ดังนั้นถ้าคุณมีอะไรจะพูดกับเธอ คุณต้องเผชิญหน้าฉันก่อน!",
  str_voice_1502151_7 = "คุณอยากทราบเกี่ยวกับวัยเด็กของเรเบกก้าหรือ? ฮ่า ๆ โชคดีในการได้ข้อมูลอะไรจากฉันนะ! แต่ถ้าคุณรู้บางความลับของเธอ... ฉันอาจสนใจในการแลกเปลี่ยนเล็ก ๆ น้อย ๆ นะ",
  str_voice_1502151_8 = "ฉันอยากเป็นพี่สาวที่คู่ควร - ไม่ใช่เพื่อชดเชยอะไร แต่เพียงเพราะฉันอยากเป็น\nวันหนึ่ง ฉันอยากได้ยินเรเบกก้าเรียกฉันว่าพี่สาวของเธออีกครั้ง และเธอจริงใจในสิ่งนั้น",
  str_voice_1502151_9 = "เพื่อนาย, ถ้าคุณบังเอิญถ่ายรูปเรเบคก้าได้ ฉันยินดีจ่ายเงินเยอะให้นะ! เข้าใจกันไหม? อ๋อ, แล้วก็อีกอย่างนึง: อย่าบอกเธอเรื่องนี้เด็ดขาด!",
  str_voice_1502151_10 = "เธอหลบหลีกฉันอีกแล้ว... ฉันทำอะไรผิดรึเปล่า? ฉันใส่ใจไม่พอหรือเปล่า?\nหรืออาจเป็นเพราะฉันต้องจับเธอในช่วงที่เธอไม่ระวังก็ได้...",
  str_voice_1502151_11 = "ตกลง ชี้ให้ฉันเห็นเจ้าขี้แพ้ที่ติดหนี้คุณเงินอยู่ไหน!\nอะไร? ไม่มีใครติดหนี้คุณเลยเหรอ? ทำไมคุณไม่บอกมาก่อนเนี่ย?!",
  str_voice_1502151_12 = "ฉันอยากต่อสู้จังเลย\nโอ้ เฮ้ย คุณมาตรงเวลาเลยนะ!\nไม่ต้องห่วง ฉันแค่อยากฝึกเทคนิคการขู่เข็ญเท่านั้น ไม่มีอะไรอันตรายหรือ - เฮ้ย อย่าวิ่งหนีสิ!",
  str_voice_1502151_13 = "ทำไมฉันยังไม่ยอมยกเลิกการเป็นตัวเก็บหนี้?\nคำถามดี! แน่นอนว่าเพราะฉันต้องการให้เรเบคก้ามีชีวิตที่ดี! เธอเคยผ่านพ้นเรื่องราวมากมายแล้ว... ในฐานะพี่สาวของเธอ นี่เป็นสิ่งที่น้อยที่สุดที่ฉันสามารถทำได้",
  str_voice_1502151_14 = "คุณจะจ่ายให้ฉันทำงานเป็นรักษาความปลอดภัยหรือเลขานุการใช่ไหม? เฮ้ย, อย่ามองฉันแบบนั้นสิ! ฉันไม่ได้หวังจะหาประโยชน์จากคุณหรืออะไร แต่ฉันยังต้องเลี้ยงเรเบกก้านี่นา! ฉันยอมรับค่าจ้างที่ต่ำกว่าก็ได้... มาเถอะ, นี่คือข้อเสนอที่ดี!",
  str_voice_1502151_15 = "... ฉันลืมมานานแล้วว่าต้องทำอะไรในวันเกิด แต่ถ้าเธออยากได้อะไรก็บอกฉันเถอะ!",
  str_voice_1502151_16 = "ยาฮู! งานของคุณเป็นอย่างไรบ้าง? งานของฉันก็ดีเหมือนที่คาดหวังนะ!",
  str_voice_1502151_17 = "เธอตื่นเช้ามากเลย! ตั้งแต่เราอยู่นี่แล้ว ทำไมไม่ไปเจอเรเบคกะฉันบ้างนะ?",
  str_voice_1502151_18 = "ว้าว, คุณไม่ได้ข้ามมื้อเย็นใช่ไหม? นี่ กินบ้างจากของฉันสิ",
  str_voice_1502151_19 = "เฮฮา, งานบางอย่างต้องทำเวลานี้เท่านั้น วางใจฉันเถอะ ฉันรู้เรื่องทั้งหมดเหมือนกัน!",
  str_voice_1502151_20 = "โลกต้องมีความวุ่นวายเล็กน้อย นั่นคือวิธีที่คนอย่างฉันได้งาน—เฮ้ย, นี่ทำให้ฉันดูเหมือนวายร้ายเลยนะ",
  str_voice_1502151_21 = "พวกเขาบอกว่าลูโมโพลิสเป็นที่ที่ปลอดภัยที่สุดในโลก ฉันกำลังคิดหาที่อยู่ให้เรเบคก้าที่นั่น",
  str_voice_1502151_22 = "เรเบคก้าคืออันดับหนึ่งของโลก! ไม่มีคู่แข่ง!",
  str_voice_1502151_23 = "ถ้าการชำระหนี้เป็นส่วนหนึ่งของโลกของเรา ก็เช่นกันกับการฆ่าอิคลิพไซท์",
  str_voice_1502151_24 = "ถึงแม้ว่าเชโอลจะชอบแสดงท่าว่าเธอรู้ทุกอย่าง ฉันรู้สึกว่าวันหนึ่งวันไหนเธอก็จะพ่ายแพ้อย่างหนัก",
  str_voice_1502151_25 = "ดูเหมือนว่าเรเบคก้ายังลำบากในการปล่อยตัวเอง จริง ๆ แล้วไม่ต้องขี้อายขนาดนั้นหรอก!",
  str_voice_1502151_26 = "เรเบคก้า, เรเบคก้า, เรเบคก้า! ฮี่ฮี่ฮี่...",
  str_voice_1502151_27 = "สิ่งเดียวในโลกที่ฉันไม่สามารถทนได้เลยคือการถูกเรเบคก้าไม่ชอบ",
  str_voice_1502151_28 = "คิดว่าฉันจะยืมโคลอสซัสได้หรือเปล่า? การเรียกคืนหนี้น่าจะง่ายขึ้นเยอะ ถ้ามีหนุ่มใหญ่ตัวนี้อยู่ด้วย!",
  str_voice_1502151_29 = "เฮ้! ฉันชื่ออิซ่า และฉันเป็นผู้เก็บหนี้มืออาชีพ พร้อมทั้งเป็นผู้ช่วยทางการแพทย์ของเรเบกก้า ฉันสามารถช่วยคุณจัดการหนี้ใด ๆ อย่างรวดเร็วและง่ายดาย ขอแค่คุณเป็นเจ้าหนี้เท่านั้นนะครับ",
  str_voice_1502151_30 = "โอ้ววว! ฉันรู้สึกดีมากเลย!",
  str_voice_1502151_31 = "ตอนนี้ฉันสามารถรับงานเพิ่มเติมได้แล้ว",
  str_voice_1502151_32 = "เพื่อชีวิตที่เต็มอิ่มและมีความสุข!",
  str_voice_1502151_33 = "ฉันจะไม่โดนคิดว่าเป็นน้องสาวอีกต่อไป!",
  str_voice_1502151_34 = "เวลาทำงานแล้ว",
  str_voice_1502151_35 = "พร้อมสำหรับบทเรียนหรือยัง?",
  str_voice_1502151_36 = "เริ่มที่ไหนดี?",
  str_voice_1502151_37 = "เริ่มต้นจากที่นี่เถอะ!",
  str_voice_1502151_38 = "อยากลองนี่ไหม?",
  str_voice_1502151_39 = "คำตอบของคุณคืออะไร?",
  str_voice_1502151_40 = "ร่วมมือกันเถอะ!",
  str_voice_1502151_41 = "สวัสดี ตอนนี้จ่ายเงินเลย",
  str_voice_1502151_42 = "หนี้อีกหนึ่งถูกเก็บเข้ามาแล้ว!",
  str_voice_1502151_43 = "อ๊อฟ! ลืมสนใจเรื่องนั้นเลย!",
  str_voice_1502151_44 = "เวลาพัก! ไม่มีอะไรเทียบกับรูปของเรเบกก้าที่ทำให้ฉันตั้งใจ!\n... อ๊าก—!!",
  str_voice_1502151_45 = "งั้นคือใครติดหนี้คุณเงิน?",
  str_voice_1502151_46 = "ให้ฉันเหรอ? ขอบคุณ!",
  str_voice_1502151_47 = "ว้าว... ฉันไม่ค่อยจะปฏิเสธนะ!",
  str_voice_1502151_48 = "อ๋อออ! เธอเข้าใจฉันจริง ๆ นะ!",
  str_voice_1502151_49 = "เรเบคก้าและฉันเป็นตัวอย่างที่แสดงให้เห็นว่าคนจริงๆ สามารถถูกสัมผัสจากสิ่งแวดล้อม แม้กระนั้นฉันคิดว่าส่วนที่ลึกที่สุดของวิญญาณเราจะยังคงเหมือนเดิมไม่ว่าจะเป็นอะไร\nคุณคิดยังไงล่ะ?",
  str_voice_1502151_50 = "ฉันไม่ค่อยเหมาะกับการเป็นพี่สาวเท่าไหร่ ฉันรู้เรื่องนี้ดีกว่าใคร แต่ฉันไม่อยากยอมรับเรื่องนี้เลย\nไม่ยอมรับเลย! ฉันจะแพ้คนนั้นได้ยังไง?",
  str_voice_1502151_51 = "ขอบคุณเพราะคุณ ฉันไม่ได้ทำความผิดเหมือนก่อนหน้านี้ ขอบคุณที่ไม่เคยยอมแพ้ และช่วยชีวิตเรเบคก้า\n... ขอบคุณครับ",
  str_voice_1502151_52 = "Alchemy Stars",
  str_voice_1502151_53 = "สวัสดี!",
  str_voice_1502151_54 = "ตื่นยัง?",
  str_voice_1502151_55 = "ความขี้เกียจเล็ก ๆ ไม่เคยทำให้เสียหาย!",
  str_voice_1502151_56 = "ฉันยังตื่นอยู่ คุณล่ะ?",
  str_voice_1502151_57 = "สุขสันต์วันปีใหม่! ลืมเรื่องงานไปวันนี้และสนุกกันเถอะ! ฉันทำชาและขนมข้าวเส้นมา มาไปเจอกับเรเบคกันเถอะ!",
  str_voice_1602141_1 = "ยาพิษของฉันไม่ก่อให้เธอรำคาญใช่ไหม? ไม่ต้องห่วงนะ มันปลอดภัย... ในตอนนี้",
  str_voice_1602141_2 = "เมื่อหมอกพิษปิดบังท้องฟ้า แม้แต่การหายใจยังเป็นสิ่งที่เราหวังไม่ได้... และตอนนั้นฉันก็ไม่มีพลังเลย...",
  str_voice_1602141_3 = "เธอต้องผ่านความเจ็บปวดและความทรยศมากมายหลังจากหนีออกจากบ้าน แต่ไม่ต้องห่วง ฉันจะดูแลเธอให้ดี... ฉันสาบานว่าจะทำ",
  str_voice_1602141_4 = "หน้าที่ของหมอคือการรักษาผู้ป่วย แต่ถ้าฉันบอกว่าฉันไม่ชอบก็เป็นการโกหกนะ\nอย่างไรก็ตาม ฉันยังคิดว่ายิ่งคนป่วยน้อยลงยิ่งดี ฮ่าๆ",
  str_voice_1602141_5 = "พลังของฉันเป็นคำสาปหรือของขวัญจากสวรรค์นะ?\nฉันไม่แน่ใจ แต่ฉันหวังว่าฉันสามารถใช้พวกมันเพื่อทำสิ่งที่ถูกต้อง",
  str_voice_1602141_6 = "อืม... ไม่ต้องห่วง ฉันจะไม่ทำผิดพลาดเหมือนครั้งก่อน ไม่มีทางหลีกเลี่ยงความเจ็บปวดนี้เสียอีก นั่นเอง อาจใช้เวลาหลายปีหรือหลายทศวรรษก่อนที่ร่างกายของฉันจะหายดี...",
  str_voice_1602141_7 = "ฉันเคยฝันถึงเวลาที่ครอบครัวของฉันถูกโจมตีเป็นครั้งคราว แต่ตอนนี้ฉันไม่ได้ฝันเรื่องนั้นมานานแล้ว",
  str_voice_1602141_8 = "สำหรับฉัน คุณก็เหมือนครอบครัวเช่นกัน ถ้าฉันพูดแบบนี้ คุณไม่รู้สึกว่ามันน่ารำคาญใช่ไหม?\nไม่เป็นไรนะถ้าคุณไม่อยากตอบ...",
  str_voice_1602141_9 = "เมื่อเราผ่านความเสียใจ ความเจ็บปวด และการแยกจากกันแล้ว เราจึงสามารถเห็นคุณค่าของชีวิตที่สงบสุข... นั่นเป็นเหตุผลที่ฉันเห็นคุณค่าในทุกๆ ช่วงเวลาของชีวิตของฉันในตอนนี้",
  str_voice_1602141_10 = "ขอบคุณที่อยู่เคียงข้างฉันเสมอ... และไม่ต้องห่วงนะ ตอนนี้ฉันดีขึ้นมากแล้ว\nนอกจากนี้ฉันคิดถึงเธอมากเลย",
  str_voice_1602141_11 = "คุณจับมือฉันอีกครั้งได้มั้ย? ขอบคุณนะ...",
  str_voice_1602141_12 = "ยังมีร่องรอยของพิษเหลืออยู่ในร่างกายของฉัน... แต่ไม่ต้องห่วงเสียใจ มันเจ็บแค่ฉันเอง...",
  str_voice_1602141_13 = "ฉันเปิดคลินิกใหม่ใกล้กับอัมบราตัน... ใช่ค่ะ มีชื่อเดียวกัน คุณอยากจะมาเยี่ยมชมไหม?",
  str_voice_1602141_14 = "คนในอัมบราตันได้รับประโยชน์อย่างไรกันนะ? ทุกคนถูกนับเป็นตัวเลข และครอบครัวกลายเป็นเครื่องมือในการโชว์อำนาจ... ฉันไม่เข้าใจเลย จริง ๆ ไม่เข้าใจเลย...",
  str_voice_1602141_15 = "วันนี้วันเกิดเธอใช่มั้ย? ขอโทษนะ ฉันลืมหาของขวัญให้เธอ... แต่ยังไม่สายเกินไปใช่ไหม?",
  str_voice_1602141_16 = "ฉันรอคุณตลอดเวลานี้...",
  str_voice_1602141_17 = "ฉันไม่รู้เลย... ว่าแสงแดดเช้านี้อบอุ่นขนาดนี้...",
  str_voice_1602141_18 = "การเยี่ยมบ้านเสร็จแล้ว... ตอนนี้ถึงเวลาสำหรับการปรึกษาส่วนตัว",
  str_voice_1602141_19 = "มันดึกแล้ว... แต่ครั้งนี้\"แสง\"จะไม่ค่อยสลายลง",
  str_voice_1602141_20 = "สิ่งสำคัญไม่ใช่ที่คุณอยู่ แต่คือคนที่คุณเลือกใช้ชีวิตด้วยกันใช่ไหม?",
  str_voice_1602141_21 = "อัมบราตัน... ฉันยังไม่สามารถเข้าใจกฎของมัน... และฉันก็ไม่ต้องการเข้าใจเช่นกัน.",
  str_voice_1602141_22 = "ไม่ว่าสิ่งต่าง ๆ จะมืดมิดแค่ไหน ก็ยังมีแสงสว่างซ่อนอยู่ที่ใดที่หนึ่งในเงามืดเสมอ",
  str_voice_1602141_23 = "สัตว์ที่มีสติเรียบง่ายเหล่านั้นไม่มีทางน่ากลัวเท่ากับหัวใจของคนเลย...",
  str_voice_1602141_24 = "เธอเป็นคนธุรกิจพิเศษและยากที่จะอ่านใจ เพิ่มเติมอีกคือ ฉัน... ไม่ชอบเลยที่เธอมองฉันอย่างนั้น",
  str_voice_1602141_25 = "ในฐานะน้องสาวของอีซ่า ที่ฉันต้องการคือให้เธอมีความมั่นคงในชีวิตมากขึ้นเล็กน้อย",
  str_voice_1602141_26 = "ในสายตาของฉัน ไม่มีอะไรมีค่าเท่ากับครอบครัวที่อยู่ด้วยกันอย่างปลอดภัยและสงบสุข",
  str_voice_1602141_27 = "ฉันไม่ชอบอะไรบ้างเหรอ? จริง ๆ แล้วมีเยอะเลยนะ...\nคุณไม่คิดอย่างนั้นใช่ไหม? หรือว่าคุณเพียงมีความรู้สึกดีเกินไปต่อฉันเท่านั้น?",
  str_voice_1602141_28 = "เห็นได้ชัดว่าคุณรักและเป็นห่วงโซรอซเหมือนเป็นสมาชิกในครอบครัวเลย ดีใจที่ได้เห็นสิ่งนี้...",
  str_voice_1602141_29 = "ในที่สุดเราก็ได้เจอกันอีกครั้ง... คราวนี้มาสัญญาใหม่กันเถอะ สัญญาที่ไม่มีใครสามารถทำลายได้",
  str_voice_1602141_30 = "ไม่มีผลข้างเคียงที่เห็นได้",
  str_voice_1602141_31 = "ไม่มีความเจ็บปวดอีกต่อไป...",
  str_voice_1602141_32 = "ฉันสัญญาว่าคุณจะหายขึ้นดีๆ",
  str_voice_1602141_33 = "ไม่มีการคัดค้าน? งั้นเรามาเริ่มกันเถอะ",
  str_voice_1602141_34 = "เวลาให้หมอมาตรวจที่บ้านหรือคะ?",
  str_voice_1602141_35 = "ยอมแพ้ซะเถอะ...",
  str_voice_1602141_36 = "ฉันจะไม่ยอมให้คุณทำร้ายพวกเขา...",
  str_voice_1602141_37 = "แผ่...",
  str_voice_1602141_38 = "แค่นี้ก็น่าจะได้ผลในไม่ช้า",
  str_voice_1602141_39 = "อย่าต่อสู้มัน...",
  str_voice_1602141_40 = "ความเจ็บปวดจะหายไปเร็วๆ นี้...",
  str_voice_1602141_41 = "ถ้าเพื่อปกป้องครอบครัวของฉัน...",
  str_voice_1602141_42 = "ว้า! มีใครบาดเจ็บมั้ย?",
  str_voice_1602141_43 = "ไปต่อไปโดยไม่ต้องคิดถึงฉัน...",
  str_voice_1602141_44 = "มีที่ไหนสำหรับฉันเก็บตัวอย่างพิษเพิ่มเติมไหม? ถ้าได้ขอที่ไม่มีคนเลยนะ",
  str_voice_1602141_45 = "ฉันไม่ได้รับของขวัญมานานแล้ว ขอบคุณนะ",
  str_voice_1602141_46 = "นี่... สำหรับฉันเหรอ? ฉันรับไว้ได้จริง ๆ เหรอ?",
  str_voice_1602141_47 = "ฉันกำลังเริ่มชินกับความใจดีของเธอ...",
  str_voice_1602141_48 = "ขอบคุณนะ ฉันจะ... ทะนุถนอมสิ่งนี้ตลอดไป",
  str_voice_1602141_49 = "ฉันแน่ใจว่าคุณรู้แล้ว แต่ฉันเสียครอบครัวไปนานแล้ว บางครั้งฉันสงสัยว่าชีวิตของฉันจะเป็นอย่างไรหากเหตุการณ์นั้นไม่เคยเกิดขึ้น",
  str_voice_1602141_50 = "ครอบครัวอาจเคยเป็นเพียงความคิดชั่ววูบในใจคุณ แต่ตอนนี้ดูเหมือนว่าคุณมีผู้คนเยอะพอที่คุณคู่ควรเรียกว่าครอบครัวอยู่ด้านข้างคุณ",
  str_voice_1602141_51 = "ฉันเกือบทำความผิดใหญ่\nแต่ถึงอย่างนั้น คุณและพี่สาวของฉันก็ไม่เคยยอมแพ้ในฉัน ถ้าฉันรู้วิธีแสดงความขอบคุณอย่างเหมาะสม แต่ตอนนี้ ข้อความนี้ก็ต้องพอกัน:\nขอบคุณค่ะ",
  str_voice_1602141_52 = "Alchemy... Stars?",
  str_voice_1602141_53 = "สวัสดี",
  str_voice_1602141_54 = "ขอให้ทุกอย่างราบรื่นในวันนี้นะคะ",
  str_voice_1602141_55 = "คิดว่าถึงเวลาพักแล้วหรือ?",
  str_voice_1602141_56 = "ใกล้เวลานอนแล้ว คุณควรพักผ่อนบ้างนะ",
  str_voice_1602141_57 = "สุขสันต์วันปีใหม่ อีกปีผ่านไปเร็วจนฉันเกือบไม่สังเกต\nคำอธิษฐานในปีใหม่ของฉันหรือ? แน่นอน คือการรักษาชีวิตที่สงบสุขในปัจจุบันให้ยืนยาวเท่าที่จะเป็นไปได้",
  str_voice_1600234_1 = "สวัสดีครับ ยังจำฉันได้ไหม? ฉันคือคอนนอลลี ยินดีที่ได้พบคุณอีกครั้ง... โอ้ ฉันสามารถเอามันออกมาได้แล้ว!",
  str_voice_1600234_2 = "มันดูดีบนฉันไหม...? \"ดีมาก\" คุณว่าเหรอ? โอ้ ขอบคุณครับ...",
  str_voice_1600234_3 = "Anton บอกว่าปาร์ตี้น้ำชาพร้อมแล้ว แต่จะมีใครมาบ้างเนี่ย? PlayerName จะมามั้ยนะ...",
  str_voice_1600234_4 = "*ฮัมเพลง*",
  str_voice_1600234_5 = "ข-ขอบคุณที่มาครับ/ค่ะ ฉันมีขนมและกาแฟให้คุณ หากคุณไม่มีปัญหานะ...",
  str_voice_1600234_6 = "ฉันได้ท่วงทำนองใหม่ในหัวหลังจากตื่นจากฝัน... ฉันเล่นให้คุณฟังเมื่อพร้อมได้ไหม?",
  str_voice_1600234_7 = "ฉันฝันว่าแอนตันเคยเป็นคนที่มีพลังมากขึ้นก่อนหน้านี้... แต่ฉันรู้สึกพอใจกับปัจจุบันเนื่องจากความสัมพันธ์กันนั้นมีค่ามากพอสำหรับฉัน",
  str_voice_1600234_8 = "แอนตันกับฉันคุยกันเรื่องอะไรนะ? อืม, เรื่องเกี่ยวกับฉันและคุณ... รอสักครู่, ฉันไม่ควรบอกเรื่องนี้ให้คุณรู้เลย...",
  str_voice_1600234_9 = "ขอโทษนะ แต่ฉันอยากซ้อมทำนองใหม่ มันจะรบกวนคุณไหม? อะไรนะ?! ไม่ คุณไม่จำเป็นต้องหยุดงานเพื่อมาฟังนะ!",
  str_voice_1600234_10 = "สวัสดีตอนเช้าค่ะ คุณอยากดื่มกาแฟไหม? มีชาดำให้เลือกด้วยนะคะ",
  str_voice_1600234_11 = "เวลาผ่านไปแล้ว แต่ถ้าคุณต้องการ ฉันยินดีที่จะทำน้ำชายามบ่ายให้คุณ...",
  str_voice_1600234_12 = "มองดูสีน้ำเงินลึกล้ำแห่งฟ้ายามค่ำคืน มันเหมือนกับก้นมหาสมุทร เวลาไม่มีคุณอยู่ ฉันแน่ใจว่าฉันคงไม่สามารถเผชิญหน้ากับมันคนเดียวได้...",
  str_voice_1600234_13 = "ขอโทษนะ แต่ฉันพร้อมเล่นแล้ว...",
  str_voice_1600234_14 = "พร้อมแล้วหรือ, แอนตัน?",
  str_voice_1600234_15 = "หวังว่านี้จะไม่รบกวนใครนะ",
  str_voice_1600234_16 = "ขอบคุณทุกคนที่ฟังฉันเล่นนะครับ",
  str_voice_1600234_17 = "เสียงของทะเล!",
  str_voice_1600234_18 = "เพลงแห่งวารี!",
  str_voice_1600234_19 = "รอสักครู่! นายวิ่งเร็วไปแล้ว แอนตัน... รองเท้าของฉัน!",
  str_voice_1600234_20 = "ทะเลรู้จักเล่นและฟังเสียงเราเสมอ",
  str_voice_1600234_21 = "แอนตันมีเพื่อนหรือเปล่า? ที่ทะเลหรือที่อื่นๆ?",
  str_voice_1600234_22 = "ที่น่าอัศจรรย์คือดนตรีสามารถสื่อสารได้เยอะมากเลย",
  str_voice_1600234_23 = "ปลาก็ตั้งหูฟังทั้งนั้น แต่ฉันก็ยังอยากได้ผู้ฟังที่แตกต่างบ้างเป็นครั้งคราว...",
  str_voice_1600234_24 = "คลาริเนตของฉัน...! โอ้ ขอบคุณพระเจ้าที่ฉันไม่ทำหายมัน",
  str_voice_1600234_25 = "อะแฮ่ม ขอ-ขอให้ฉันแสดงเดี่ยวหน่อยค่ะ",
  str_voice_1600234_26 = "ชุดนี้ดีสำหรับการเต้นเหรอ? แต่ฉันจะเต้นได้...?",
  str_voice_1600234_27 = "โอ้ว้าว, การเป็นเจ้าภาพปาร์ตี้น้ำชานี่เหนื่อยกว่าการเป็นบริกรคาเฟ่เยอะเลย...",
  str_voice_1600234_28 = "ฉันอยากวิ่งหนี แต่แม้กระทั่งซ่อนตัวในชุดนี้ยังยากเลย!",
  str_voice_1600234_29 = "แม้ว่ามันจะเป็นแค่ความฝัน แต่บทเรียนที่ฉันได้รับจากมันก็ไม่ใช่ภาพลวงตาใช่ไหม",
  str_voice_1600234_30 = "ขอบคุณที่มาเข้าร่วมปาร์ตี้น้ำชาของแอนตันและฉันนะคะ",
  str_voice_1600234_31 = "โอ้, ทำไมต้องเป็นฉันด้วยล่ะ...?",
  str_voice_1600234_32 = "ตลกที่ฉันจะเป็นราชินี!",
  str_voice_1600234_33 = "ฉันต้องซ่อนตัว หาที่พักอาศัยในความมืดที่คุ้นเคย...",
  str_voice_1600234_34 = "ดนตรีมีพลัง... และฉันต้องการให้พวกเขาได้ยินความโกรธของฉัน!",
  str_voice_1600234_35 = "ไม่มีใครมองฉันเลย... ไม่มีใครมองฉันเลย...",
  str_voice_1600234_36 = "แฮ่ก แฮ่ก...",
  str_voice_1600234_37 = "หา?",
  str_voice_1602161_1 = "ความรักและสันติภาพสากลเป็นหลักการสองประการที่ช่างฝีมือเชี่ยวชาญในราชอาณาจักรเยอะยิ่งยืนยัน ประชาชนของเราถูกสอนให้รักและช่วยเสริมกันและกัน และไม่ทำร้ายกัน ปรัชญาที่เรียบง่ายใช่ไหม? แม้แต่เพียงสองคน ก็ไม่ควรยากที่จะปฏิบัติตาม",
  str_voice_1602161_2 = "คุณอยากให้ฉันสร้างอะไรให้ดูวันนี้? วัวทองแดงพ่นไฟ หรือตัวแมงป่องขุดดิน? หรืออาจจะเป็นว่าวที่สามารถลอยขึ้นและตกลงด้วยตัวเอง?",
  str_voice_1602161_3 = "คุณต้องการเรียนรู้วิธีการสร้างนกไขลานเหรอ? ฮ่าๆ คุณไม่คิดว่าคนที่มีความสามารถเหนือชั้นเช่นคุณจะเสียเวลากับเครื่องประดับเล็ก ๆ น้อย ๆ แบบนี้หรือเปล่า?",
  str_voice_1602161_4 = "คุณสนใจในร่มกันแดดแปลกประหลาดของฉันด้วยเหรอ? โอ้ ฉันไม่ตั้งใจนะ! มันคือนวัตกรรมที่ยอดเยี่ยมที่สุดของฉัน: อาวุธที่สามารถสลับระหว่างความสามารถในการโจมตีและป้องกันได้อย่างลื่นไหล!",
  str_voice_1602161_5 = "ถึงแม้ว่าการศึกษาของฉันส่วนใหญ่จะเกี่ยวกับเครื่องจักร แต่ความสนใจของฉันยังขยายไปสู่โลกของสิ่งมีชีวิตด้วย ในความเป็นจริง สามารถพูดได้ว่าสิ่งมีชีวิตทั้งหมดคือแรงบันดาลใจในการคิดค้นของฉัน",
  str_voice_1602161_6 = "คนส่วนใหญ่มักมองข้าเป็นนักประดิษฐ์ที่แปลกประหลาด และกล่าวว่าการกระทำ พฤติกรรม และกระบวนการคิดของข้านั้นไม่ธรรมดาเลย... แต่เจ้าคิดยังไงกันนะ เคเลสไทต์?",
  str_voice_1602161_7 = "คุณอยากเดินเล่นกับฉันไหม? ตั้งแต่ฉันมีร่มพาราซอล คุณไม่ต้องห่วงเรื่องอะไรเลย ไม่ว่าจะเป็นอากาศหรืออิคลิพไซท์",
  str_voice_1602161_8 = "ฉันเข้าใจว่าชาวเคเลสไทต์มีความเชื่อที่คล้ายคลึงกับคนในชาติของฉัน คุณสนใจที่จะมาเยือน Ye เพื่อแลกเปลี่ยนวัฒนธรรมกันหรือไม่?",
  str_voice_1602161_9 = "ตราบใดที่คุณอยู่ในหลงโจว ฉันยินดีที่จะไปควบคู่กับคุณทุกที่ คุณจะมีที่อยู่ใต้ร่มของฉันเสมอ ที่คุณสามารถหลบซ่อนจากลม ฝน และหิมะ",
  str_voice_1602161_10 = "...นั่นเป็นเหตุผลที่ฉันออกแบบอุปกรณ์เพื่อช่วยในการดูแลตัวเอง... หืม? คุณหลับไปหรือเปล่า?",
  str_voice_1602161_11 = "ฉันใช้เวลาและความพยายามมากในการสร้างหุ่นยนต์ให้เป็นเชิงชายควบคุม มันสามารถยืนเฝ้ารักษาความปลอดภัย ถือน้ำ ทำงานเล็ก ๆ น้อย ๆ และแม้กระทั่งสนทนาสนุก ๆ กัน แน่นอนว่ามันไม่สามารถแทนที่ฉันได้!",
  str_voice_1602161_12 = "ถ้าเป็นไปได้ ฉันอยากปรับปรุงชีวิตประจำวันของครัวเรือนทุกหน่วยในเย้ด้วยเครื่องจักรของฉัน",
  str_voice_1602161_13 = "ผู้มาเยือนจากอาณาจักรข้างเคียงบ่อยครั้งกล่าวว่าเยหลงใหลในสินค้าต่างประเทศเกินไป ในความคิดของฉัน การศึกษาค้นคว้าความคิดใหม่มีประโยชน์มากกว่าที่จะติดอยู่ในการแข่งขันเพื่ออำนาจที่ล้าสมัยของแผ่นดินของเรา",
  str_voice_1602161_14 = "อาวุธเวทมนตร์, วัตถุโบราณ, อาวุธเทพ... ใน Longzhou, วัตถุโบราณเหล่านี้มีชื่อเสียงมากมาย และหลายเครื่องกลใหญ่ไม่สามารถเปิดใช้งานได้หากไม่มีพวกเขา",
  str_voice_1602161_15 = "เดาสิว่าฉันมีอะไรให้คุณวันนี้? มันเป็นนกไขลานที่ซับซ้อนมากหรือป่าว หรือเป็นประติมากรรมที่อลังการ? ไม่ใช่ทั้งสอง! สำหรับวันเกิดของคุณ... ฉันนำเสื้อเกราะที่ดีมากมาให้คุณ!",
  str_voice_1602161_16 = "ยังยุ่งอยู่รึเปล่า? ถ้าต้องการอะไร ก็เรียกหาฉันหรือนกไขลานของฉันเถอะ",
  str_voice_1602161_17 = "คุณรู้ไหม... แทนที่จะออกแบบเครื่องเพื่อปลุกคุณขึ้นมา ทำไมไม่ออกแบบอะไรสักอย่างเพื่อทำงานแทนคุณล่ะ?",
  str_voice_1602161_18 = "อืม... วันนี้ทำงานมานานเลยใช่ไหม? อยากไปเดินเล่นสักหน่อยมั้ยคะ?",
  str_voice_1602161_19 = "อีกครั้งเวลานอนเข้ามาหาเราก่อนที่เราจะได้สนุกเพียงพอ น่าเสียดายจริงๆ",
  str_voice_1602161_20 = "ราชอาณาจักรเย่ก่อตั้งขึ้นบนแนวคิดของความรักสากลและฝีมือช่างที่เชี่ยวชาญ มันเป็นแดนแห่งคำสัญญาสำหรับช่างฝีมือที่ยิ่งใหญ่ทั้งหมดของหลงโจว และฉันภูมิใจที่เรียกมันว่าบ้านของฉัน",
  str_voice_1602161_21 = "เอ่ย... คุณจะสามารถใช้ความสัมพันธ์ของคุณแนะนำฉันให้รู้จักกับนักวิจัยที่ยอดเยี่ยมของอิลลูมินาบ้างไหม?",
  str_voice_1602161_22 = "สำหรับช่างฝีมือแท้ ไม่มีอะไรที่เป็นไปไม่ได้!",
  str_voice_1602161_23 = "ฉันสนใจมากในวิธีการจัดการอิคลิพไซท์ของ Astra ไม่ว่าความสามารถเราต้องดึงประสบการณ์ต่าง ๆ เพื่อสามารถเผชิญหน้ากับศัตรูอย่างเหมาะสม",
  str_voice_1602161_24 = "โอ้ ไม่นะ ฉันจะไม่สอนเจ้าหญิงดันตังเรื่องศิลปะเครื่องจักรหรอก สิ่งสุดท้ายที่ฉันต้องการคือให้คนกล่าวหาว่าฉันนำสมาชิกในครอบครัวราชวงศ์เดินทางผิดที่",
  str_voice_1602161_25 = "ฉันชื่นชมนางจิ้วที่เพิ่มความชำนาญในทักษะของเธอ แม้จะต้องเผชิญความยากลำบากในชีวิต ฉันหวังเพียงว่าเธอจะไม่เกี่ยวข้องกับการสมคบกันอีกต่อไป",
  str_voice_1602161_26 = "ฮ่าฮ่าฮ่า พวกเขาบอกว่าฉันสนใจแต่เครื่องจักรเท่านั้น แต่จริงๆ แล้วฉันมีความสนใจในสิ่งต่าง ๆ อีกมากมาย เช่น กวีนิพนธ์ ศิลปะการใช้ดาบ และสิ่งเล็ก ๆ น้อย ๆ ในชีวิต!",
  str_voice_1602161_27 = "ไม่ว่าเครื่องจักรจะซับซ้อนแค่ไหน ก็ยังคงเป็นเครื่องจักร มันจะไม่ทำร้ายใครเว้นแต่ถูกนำไปใช้โดยผู้ที่มีเจตนาชั่วร้าย",
  str_voice_1602161_28 = "ในตอนแรกมี \"คุน\" และ \"เพง\" สองสิ่งมีชีวิตขนาดใหญ่ที่ได้รับวิญญาณจากสวรรค์... อ๋อ, ขอโทษนะครับ ฉันกำลังนึกถึงตำนานจากคัมภีร์โบราณของเราเมื่อกี้เองครับ",
  str_voice_1602161_29 = "อ๊ะ นี่คือโคลอสซัสของเธอเหรอ? ...ไม่ต้องเป็นทางการมาก! เธอสามารถเรียกฉันว่าซวนจิ ได้เลย นะ เธอไม่ว่าใจใช่ไหมถ้าฉันปรับปรุงสิ่งประดิษฐ์ของฉันที่นี่?",
  str_voice_1602161_30 = "เทคโนโลยีที่ยอดเยี่ยมต้องการทักษะที่ยอดเยี่ยม!",
  str_voice_1602161_31 = "ร่มกันแดดของฉันเตรียมพร้อมแล้ว!",
  str_voice_1602161_32 = "ทุกอย่างเชื่อมโยงกันอย่างสมบูรณ์!",
  str_voice_1602161_33 = "ร่มกันแดดของฉันสามารถจัดการกับทุกสิ่งได้!",
  str_voice_1602161_34 = "มีเทคนิคน่าสนใจไหม?",
  str_voice_1602161_35 = "พร้อมดึงกรiggerแล้ว!",
  str_voice_1602161_36 = "พายุฟ้าคะนองภายใต้ร่มของฉัน",
  str_voice_1602161_37 = "แมลงปอเข็ม ปล่อย!",
  str_voice_1602161_38 = "กดปุ่มเพื่อให้ฟ้าผ่าแรงโผล่!",
  str_voice_1602161_39 = "โจมตีต่อเนื่อง!",
  str_voice_1602161_40 = "เปิดใช้งานเต็มรูปแบบ!",
  str_voice_1602161_41 = "เครื่องจักรที่ยอดเยี่ยมต้องการมือที่สามารถ!",
  str_voice_1602161_42 = "เทคนิคที่ยอดเยี่ยมต้องใช้จิตใจที่แยบยล!",
  str_voice_1602161_43 = "ไม่ต้องห่วง นี่เป็นอุปสรรคเล็ก ๆ น้อย ๆ หรอก",
  str_voice_1602161_44 = "ฉันจะเปิดความลับของเครื่องจักรตำนานจากยุคอดีต",
  str_voice_1602161_45 = "ฉันไม่จู้จี้จุกจิก อะไรก็โอเคสำหรับฉัน",
  str_voice_1602161_46 = "ดีเนอะ! มาเป็นเพื่อนกันเถอะ!",
  str_voice_1602161_47 = "ดีใจที่รู้ว่าคุณเป็นห่วงฉันขนาดนี้",
  str_voice_1602161_48 = "ฉันต้องคิดของขวัญขอบคุณที่ดีกว่านี้",
  str_voice_1602161_49 = "โรงเรียนฝีมือที่ฉันเป็นสมาชิกชื่อว่า \"เชียนยุน\" และตรงข้ามกันคือโรงเรียน \"ดีคุน\" โรงเรียนหนึ่งเชี่ยวชาญในการกระทำ ในขณะที่อีกโรงเรียนเชี่ยวชาญในการไม่กระทำ แต่ฉันเชื่อว่าการรวมความรู้จากทั้งสองโรงเรียนเป็นวิธีที่ดีที่สุดในการสร้างความก้าวหน้าที่แท้จริง",
  str_voice_1602161_50 = "ฉันต้องการสร้างโลกที่มีเครื่องจักรที่ไม่มีชีวิตจัดการงานทั้งหมด ด้วยวิธีนี้เราเป็นสิ่งมีชีวิตสามารถมุ่งเน้นในการรักและอดทนต่อกันโดยไม่มีสิ่งขัดขวาง",
  str_voice_1602161_51 = "สิ่งที่น่ากลัวกำลังเกิดขึ้นในราชอาณาจักรเย่ที่ดูเป็นสันติ ซึ่งมีแผนการสมคบที่มาจากที่ที่มีอิทธิพลมากขึ้น ด้วยเหตุผลนี้ ฉันลาออกจากตำแหน่งที่ปรึกษาและเริ่มต้นการค้นหาแหล่งที่มาของความขัดแย้งในราชอาณาจักรของฉัน",
  str_voice_1602161_52 = "Alchemy Stars",
  str_voice_1602161_53 = "โอ้สวัสดี!",
  str_voice_1602161_54 = "อรุณสวัสดิ์!",
  str_voice_1602161_55 = "วันนี้มีอะไรน่าสนใจไหม?",
  str_voice_1602161_56 = "ก็ได้ ถึงเวลานอนแล้วนะ",
  str_voice_1602161_57 = "ฉันสร้างนาฬิกาต้นแบบ - ตัวหนึ่งที่เก็บบันทึกของทุกเวลาสำคัญในปีที่แล้ว หากคุณบอกว่าคุณไม่ต้องการลืมอะไรเลย ให้นาฬิกานี้จดจำให้คุณ ฉันหวังว่าเราจะได้ใช้เวลาดี ๆ ในอนาคตด้วยกัน!",
  str_voice_1501871_1 = "วิธีการทำนายของฉันถูกสร้างขึ้นโดยตัวฉันเอง ฉันเรียกมันว่าการทำนายดวงชะตาด้วย Hexagram สวรรค์ มันต้องใช้ 25 แท่ง: 12 แท่งแทน \"หยิน\", 12 แท่งแทน \"หยาง\", และแท่งสุดท้ายแทนทั้งสอง โดยการวางพวกเขาในท่อนี้แล้วหย่อนพวกเขาออก ฉันสามารถทำนายสิ่งต่าง ๆ ที่จะเกิดขึ้นได้",
  str_voice_1501871_2 = "- ลูกอินทผลัมที่เกิดจากต้นไม้โบราณนั้นอร่อยมาก\n- คนมักจะสงสัยว่า แท่งทองคำหนึ่งจะซื้อเมล็ดพันธุ์ได้เท่าไหร่?\n- ว้าว, สควอกและจับเบอร์, คุณสองคนคิดว่าตัวเองเงียบๆ ใช่ไหม? อย่าถามเลย ฉันหมดตัวแล้ว ถ้าหิว ก็ไปกินหญ้าข้างนอกเถอะ",
  str_voice_1501871_3 = "คุณต้องการฟังเรื่องที่น่าทึ่งหรือไม่? เอ่อม...ลูกชายคนที่ห้าของพระราชามังกร ที่เรียกว่า \"สวนนี่\" เคยเป็นคนที่สงบสุข แต่วันหนึ่งเขาได้เข้าไปวิวาทกับรัฐมนตรีชั้นสูงของศาลาใหญ่ในที่สาธารณะ และยังใช้ความรุนแรงด้วย!",
  str_voice_1501871_4 = "การเป็นผู้ชมที่คุ้มค่าไม่ใช่เรื่องง่าย เพียงแค่มองเห็นเรื่องราวกำลังเกิดขึ้นก็ไม่น่าพอใจ ในขณะที่เข้าไปเกี่ยวข้องกับเรื่องราวก็ทำให้ยากที่จะหลุดพ้น มันเหมือนกับการข้ามแม่น้ำบนสะพานที่ทำจากไม้ตัวเดียว",
  str_voice_1501871_5 = "\"คนรวยอันดับสาม\"? \"เจ้านายของไม้เท้า\"? \"คนจนที่มีปัญญา\"? ใช่ค่ะ ฉันเคยได้ยินเรื่องเกี่ยวกับพวกเขา แต่ฉันไม่สามารถบอกว่ารู้จักพวกเขามากนัก!",
  str_voice_1501871_6 = "การทำนายของฉันไม่เคยเกี่ยวข้องกับโชคชะตา แต่เป็นเรื่องของชีวิตประจำวันของคนธรรมดา โชคชะตากำหนดเรื่องเช่นชีวิตและความตาย; แต่การทำนายความซับซ้อนของชีวิตประจำวันนั้นน่าสนใจมากขึ้น",
  str_voice_1501871_7 = "ฉันยังไม่เคยจนขนาดนี้ในชีวิต! ดูฉันสิ! เสื้อผ้าเต็มไปด้วยรู รองเท้าไม่มีซอล... แม้กระทั่งหมวกยังถูกนกเจาะเป็นชิ้นๆ! คุณต้องมีเหรียญเสริมให้ได้สักหน่อยใช่ไหม?",
  str_voice_1501871_8 = "โอ้ พระเจ้า... ฮีกซาแกรมของคุณค่อนข้างแปลก; ฉันเห็นแมว, สัตว์ที่พบบ่อยในช่วงระหว่างหยินและหยาง แต่ไม่ได้อยู่ในจักรราศี คุณ Caelestite ไม่ใช่หยินหรือหยาง อนาคตของคุณถูกปิดบังด้วยหมอกของการตัดสินใจของคุณ อืม, การได้ยินส่วนที่เหลือจะต้องเสียค่าใช้จ่ายเพิ่มเติมนะครับ",
  str_voice_1501871_9 = "พ่อมังกรกษัตริย์มีลูกชายเก้าคน ซึ่งแต่ละคนมีความแตกต่างกันอย่างมาก ใครจะบอกได้ว่าใครเป็นคนแท้และใครเป็นคนหลอกลวง? ในที่สุด ทุกคนก็มีส่วนหลอกลวงและส่วนแท้อยู่ด้วยกัน",
  str_voice_1501871_10 = "การทำนายต้องการเพียงคนเดียวที่จะระบุอารมณ์ สถานะ และเจตนาของผู้ที่เข้ามาหาพวกเขาอย่างแม่นยำ สิ่งนั้นเพียงอย่างเดียวก็ทำให้ครึ่งหนึ่งของการทำนายฝันเป็นไปได้",
  str_voice_1501871_11 = "คุณต้องการให้ทำนายดวงชะตาให้หรือไม่? ฉันจะไม่เลื่อนการร้องขอจากคุณ หาที่นั่งให้ฉันก่อนนะคะ? คำทำนายของฉันมักจะแม่นยำขึ้นเมื่อฉันนั่งอยู่",
  str_voice_1501871_12 = "ในการให้บริการแก่ผู้ครอง คุณต้องหาเวลาให้กับการพักผ่อน แต่ถ้าท่านลอร์ดที่คุณให้บริการคือตัวคุณเอง คุณก็มีเวลาทั้งหมดในโลกนี้",
  str_voice_1501871_13 = "มีคำพูดเก่าๆว่า \"คนจะไม่รู้ความยาวของการเดินทางจนกว่าจะเดินมัน; คนจะไม่รู้ตัวเองจนกว่าความยากลำบากจะบังคับให้คุณต้องเลือก\"",
  str_voice_1501871_14 = "คุณต้องการทราบว่าเธอมาจากที่ไหนเหรอ? เธอมาจากที่พำนักของวิญญาณท้องฟ้าที่อยู่ในเมฆ โดยห่อหุ้มด้วยหมอกแห่งเช้า และเป็นเงาที่แวววาว",
  str_voice_1501871_15 = "โอ้วันที่สุขสันต์! โชคดีในทุกสิ่ง และขอให้ความปรารถนาของคุณเป็นจริงทั้งหมดนะ!",
  str_voice_1501871_16 = "โอ๊ย! ฉันอยากทักทาย แต่การกักกลืนน้ำตาลทำให้ฉันปวดฟัน...",
  str_voice_1501871_17 = "\"ตื่นได้แล้ว!\"\nหยุดตะโกน! เช้าเกินไป, ฉันยังหลับอยู่...",
  str_voice_1501871_18 = "คืนนี้แห้งแล้ง อย่าปล่อยให้เปลวไฟจากเทียนบินไป ปิดประตู ปิดหน้าต่าง เพราะลมจะพัดเฉพาะด้านนอกเท่านั้น",
  str_voice_1501871_19 = "ทำดีในช่วงวัน แล้วคืนนี้โชคดีจะมาหาคุณ",
  str_voice_1501871_20 = "เมื่อมงกุฎตก การหนีอย่างรวดเร็วดีกว่าการถูกบดโดยซากอาคารถล่ม",
  str_voice_1501871_21 = "โลกกว้างใหญ่ และความอุดมสมบูรณ์มากมาย!",
  str_voice_1501871_22 = "โลกใบนี้มีความลับนับไม่ถ้วน มาเถอะ มาดูว่าโชคชะตามีอะไรรอคุณอยู่!",
  str_voice_1501871_23 = "อิคลิพไซท์? ชั่วช้าจริงๆ",
  str_voice_1501871_24 = "ฉันมีเพื่อนคนหนึ่งชอบตกปลาคนเดียวในแม่น้ำที่หนาวและไหลเวียน โดยสวมเสื้อฟางและหมวกไผ่ บ่อยครั้งท่ายืนเหมือนนกกระเรียน",
  str_voice_1501871_25 = "หนูหยางและหนูหยิน - คู่หูเหมือนกัน อาจคิดว่าฉันกำลังทำนาย แต่จริงๆ แล้ว นี่ควรถือเป็นคำด่า",
  str_voice_1501871_26 = "รูปปั้นน้ำตาลที่พ่อทำขึ้นเป็นที่สุดจริงๆ ใสเหมือนคริสตัล นุ่มนวล และมีรูปทรงที่คิดค้นอย่างชาญฉลาด",
  str_voice_1501871_27 = "จุ๊... กิ้งก่าไม่เงียบได้หรอก แต่พอพูดเยอะเกินไป อืม...",
  str_voice_1501871_28 = "โคลอสซัสนี่เป็นวัตถุหายากจริง ๆ คุณสามารถขายมันเพื่อรับทรัพย์มากมาย!",
  str_voice_1501871_29 = "ฉันคือ หลี่ เทียนเซียน ถามฉันเกี่ยวกับโลก ถามฉันเกี่ยวกับชีวิตของคุณ ถามฉันเกี่ยวกับข่าวสารในวงการ ถามฉันเกี่ยวกับเพื่อนบ้านของคุณ การทำนายของฉันแสดงให้ฉันเห็นทุกอย่าง",
  str_voice_1501871_30 = "รับประกันคืนเงินหากการทำนายของฉันไม่แม่นยำ",
  str_voice_1501871_31 = "ฉันเป็นเพียงแค่ผู้มองเห็น สังเกตโลกทั้งหมดในสายตาของฉัน",
  str_voice_1501871_32 = "ทั้งหมดโลกคือเวที ล้านคน ล้านบทบาท",
  str_voice_1501871_33 = "ชะตากรรมมักถูกกำหนดไว้แน่นอน แต่อยู่ในมือของคนก็มีการเลือกตั้ง",
  str_voice_1501871_34 = "เราทุกคนอยู่ฝ่ายเดียวกันใช่ไหม?",
  str_voice_1501871_35 = "มาให้เราอ่านโชคชะตาของคุณกันเถอะ",
  str_voice_1501871_36 = "เทพ.",
  str_voice_1501871_37 = "ดูเถิด...ปริศนาแห่งจักรวาลนิรันดร์!",
  str_voice_1501871_38 = "ดูไม้เหล่านี้ จับเอาโชคชะตาของคุณ",
  str_voice_1501871_39 = "ทุกอย่างเป็นหนึ่งเดียวกัน",
  str_voice_1501871_40 = "หนึ่งคือทั้งหมด",
  str_voice_1501871_41 = "ฉันจะนำทางให้เอง",
  str_voice_1501871_42 = "ชัยชนะอันมงคล!",
  str_voice_1501871_43 = "ที่มีโชค ก็มีโชคร้ายตามมาด้วย",
  str_voice_1501871_44 = "ทุกข่าวซุบซิบนี้... แย่กว่านกสองตัวนั้นเลย!",
  str_voice_1501871_45 = "ไม่มีความดีที่ทำไปโดยไม่ได้รับรางวัล...",
  str_voice_1501871_46 = "ของขวัญที่น่าคิดถึงจริงๆ ขอบคุณนะ!",
  str_voice_1501871_47 = "ฉันเกือบจะอายที่จะรับมันเลย!",
  str_voice_1501871_48 = "นี่มีค่าเท่ากับน้ำหนักทองคำเลยครับ!",
  str_voice_1501871_49 = "เคยมีหญิงสาวมาจากเมฆ ที่ให้ฉัน \"คัมภีร์เลื่อนขั้นเทพ\" มันเป็นของขวัญมงคลจากสวรรค์หรือเป็นการปลอมแปลงอย่างซับซ้อนเพื่อหลอกฉัน? หรือมันเป็นแค่ม้วนกระดาษชำระที่มีลายสวยงาม?",
  str_voice_1501871_50 = "เขาว่ากิ้งก่านั้นฉลาดและมีความยืนยง เสียงพูดไม่ควรเหยียดนกที่คุณเห็นรอบ ๆ ฉัน - พวกมันรู้มากกว่าที่คุณคิด",
  str_voice_1501871_51 = "- \"เขาเป็นคนโกหก บางครั้งเขาปลอมตัวเป็นชายชรา\"\n- \"บางครั้งเขาปลอมตัวเป็นผู้หญิง\"\n- ฮึ่ม! นกโง่ ๆ หยุดนินทาเรื่องฉันเถอะ! ฉันคือฉัน และฉันไม่อายในตัวตนของฉัน!",
  str_voice_1501871_52 = "Alchemy Stars",
  str_voice_1501871_53 = "อ้าว สวัสดี!",
  str_voice_1501871_54 = "อรุณสวัสดิ์!",
  str_voice_1501871_55 = "เพื่อนกินข้าวรึยังน่ะ?",
  str_voice_1501871_56 = "สายัณห์สวัสดิ์",
  str_voice_1501871_57 = "ขอให้ปีของคุณมีความสุขและเต็มไปด้วยช่วงเวลาแห่งความสุข",
  str_voice_1602181_1 = "ฉันเตรียมรายการส่วนลดเฉพาะสำหรับคุณ ลองมาดูสิ โอ้ และยังมีของขวัญเล็ก ๆ ที่ด้านหลังสำหรับคุณ เนื่องจากคุณเป็นลูกค้าพิเศษสุดของฉัน",
  str_voice_1602181_2 = "ไนท์เทียมในมือฉันเหรอ? คุณมีสายตาที่คมแหลมจริงๆ มันมีค่าความสำคัญอย่างมากสำหรับฉัน... ไม่เป็นไร หากคุณดูเหมือนจะสนใจมันมาก ฉันจะให้คุณมันล่ะ",
  str_voice_1602181_3 = "ฉันใช้เวลาเกือบทั้งชีวิตไปกับการเลือกเฟ้นสินค้าและต่อรองราคา แต่ฟังนะ จงใช้เวลาอันมีค่าของคุณสร้างอนาคตที่สดใสเถอะ",
  str_voice_1602181_4 = "โดยทั่วไป ฉันไม่ค่อยได้รับแขกด้วยตัวเอง แต่คุณมีเสน่ห์พิเศษ... โดยเฉพาะเมื่อเรื่องมาถึงการจ่ายบิล",
  str_voice_1602181_5 = "ทางเลือกที่แตกต่าง นำไปสู่ผลลัพธ์ที่ต่างกัน คตินี้เป็นจริงทั้งในการทำธุรกิจและใช้ชีวิต ฉันให้คุณฟรีไม่คิดเงิน",
  str_voice_1602181_6 = "การคุ้ยค้นและวิ่งเต้นอย่างน่ารักเหมือนหนูน้อย อ๊ะ คุณที่นั่น... คุณเคยเลี้ยงงูเป็นสัตว์เลี้ยงหรือเปล่า?",
  str_voice_1602181_7 = "ฉันเห็นว่าคุณกำลังสับสนและลังเลบ้าง ลูกค้าที่รักของฉัน... ฉันจะแสดงให้คุณเห็นว่าจะเปลี่ยนเงินให้กลายเป็นสิ่งที่น่าตื่นตาตื่นใจที่จะอยู่กับคุณตลอดไป...",
  str_voice_1602181_8 = "หืม? คุณหาสิ่งที่ต้องการได้หรือยัง? ฉันเหรอ? ฮ่าๆ, ลูกค้าน่ารักจริงๆ... ฉันไม่ได้ขายตัวนะ!",
  str_voice_1602181_9 = "พันธมิตรหรอ? ฮ่าๆ คุณสำคัญกว่านั้นมากสำหรับฉันนะ.",
  str_voice_1602181_10 = "ฝันกลางวันอีกแล้วสินะ ลูกค้าที่รัก? ระวังนะ เพราะราคาและโอกาสธุรกิจสามารถเปลี่ยนแปลงได้โดยไม่ต้องแจ้งให้ทราบล่วงหน้า",
  str_voice_1602181_11 = "คุณต้องการให้ฉันเป็นเลขานุการของคุณหรือ? แน่นอนค่ะ ที่รัก! ฉันสามารถใช้เวลาทั้งวันสอนคุณวิธีทำเงินที่แตกต่างกันได้.",
  str_voice_1602181_12 = "ไม่เป็นไรถ้าคุณไม่ซื้ออะไร สุดท้ายแล้วฉันชอบคุยกับลูกค้าของฉัน และบางครั้งโอกาสทางธุรกิจใหม่ๆก็เกิดขึ้นจากการสนทนาของเรา",
  str_voice_1602181_13 = "คุณนั้นซื่อบริสุทธิ์เกินไปนะลูกค้าที่รัก คนที่มีสติธุรกิจควรจะคิดอย่างยืดหยุ่นมากขึ้น",
  str_voice_1602181_14 = "บางคนเรียกฉันว่า \"ลาเคซิสผู้โลภ\"... ฮิฮิ, ฉันเข้าใจว่าทำไมพวกเขาถึงคิดแบบนั้นกับฉัน แต่คุณล่ะ? ฉันเป็นคนแบบไหนในสายตาของคุณ?",
  str_voice_1602181_15 = "สุขสันต์วันเกิด นี่คือของขวัญที่เตรียมไว้เฉพาะให้คุณ รวมถึงคูปองส่วนลดด้วย กับดักของผู้บริโภค? ที่รัก คุณคิดมากเกินไปแน่นอน",
  str_voice_1602181_16 = "ยินดีต้อนรับค่ะ ที่รัก กิลด์เหนือเมฆจะต้อนรับแขกที่มีรสนิยมยอดเยี่ยมเช่นคุณเสมอค่ะ",
  str_voice_1602181_17 = "ว้าว, วันนี้เรารีบร้อนนะคะ? ยังไม่ถึงเวลาทำการ ดังนั้นกรุณารออย่างสุขุมค่ะ.",
  str_voice_1602181_18 = "อาหารกลางวันที่ทำงานหรือ? เปล่านะ วันนี้ฉันเตรียมอะไรที่ดีกว่ามาให้คุณแล้ว...",
  str_voice_1602181_19 = "เข้ามาใกล้ๆ ที่รัก คุณอยากลองที่นอนฟูของกิลด์เหนือเมฆหรือไม่? ตอนนี้พวกเขากำลังมีโปรโมชั่นพิเศษอยู่นะ!",
  str_voice_1602181_20 = "อัมบราตันเป็นดินที่อุดมสมบูรณ์ที่ทั้งธุรกิจและบาปสามารถเจริญเติบโตได้",
  str_voice_1602181_21 = "พวกเขาชอบทำให้ปัญหาเล็ก ๆ น้อย ๆ ดูเหมือนเป็นเรื่องใหญ่ ไม่ใช่หรือ? กิลด์เหนือเมฆ ด้วยกองทัพเรือบินขนาดเล็กของตน ไม่ได้เป็นความข่มขู่ต่อเมืองลอยฟ้านั้นเลย คุณไม่เห็นด้วยหรือ?",
  str_voice_1602181_22 = "แชโดว์จะคอยเฝ้ามองเจ้า",
  str_voice_1602181_23 = "ถ้าพวกเขาสามารถนำมาใช้เพื่อทำกำไรได้ แม้กระทั่งอิคลิพไซท์... ฮ่าฮ่า อย่าบอกฉันว่าคุณคิดว่าฉันจริงจัง?",
  str_voice_1602181_24 = "เพื่อคุณต้องการทราบเกี่ยวกับอีสต์วาน เจ้าแห่งเงาของอัมบราตันหรือ? ฮีฮี คุณจะต้องจ่ายค่าใช้จ่ายสำหรับข้อมูลแบบนั้นนะ",
  str_voice_1602181_25 = "การลงทุนใน Courier Union จริงๆ แล้วเป็นการตัดสินใจทางธุรกิจที่มีคุณค่ามาก สำหรับเหตุผลของฉัน... ฉันจะแบ่งปันมันกับคุณในวันหนึ่งในอนาคต เมื่อถึงเวลาที่เหมาะสม",
  str_voice_1602181_26 = "การหาเงินเป็นเหตุผลที่ฉันมีอยู่ แต่ฉันยิ่งชอบคนที่มีเหตุผลในการใช้จ่ายเงินมากกว่า!",
  str_voice_1602181_27 = "ฉันไม่เคยไม่ชอบการทำธุรกิจ แต่... มีประเภทหนึ่งของธุรกิจที่ฉันไม่ชอบเป็นพิเศษ นั่นคือการค้าขายที่เสียหาย",
  str_voice_1602181_28 = "วันหนึ่งฉันหวังว่าไอเทมที่ยอดเยี่ยมเหมือน Colossus ของคุณจะได้ตกแต่งชั้นวางของที่ Guild ของ Cloudrover",
  str_voice_1602181_29 = "ฉันคือเชโอล ผู้นำของกิลด์ Cloudrover ด้วยความสัมพันธ์ของเรา ไม่มีอะไรจะพูดเพิ่มเติม คุณไม่คิดว่าเป็นอย่างนั้นใช่ไหม ที่รัก?",
  str_voice_1602181_30 = "การลงทุนที่ชาญฉลาด",
  str_voice_1602181_31 = "พันธมิตรของเราสามารถไปได้ไกลยิ่งขึ้น",
  str_voice_1602181_32 = "กิลด์มีความยินดีต้อนรับคุณเสมอ",
  str_voice_1602181_33 = "คุณลงทุนในตัวฉันแล้วนะ",
  str_voice_1602181_34 = "เปิดร้านแล้ว.",
  str_voice_1602181_35 = "ฉันได้ยินเสียงของเงิน!",
  str_voice_1602181_36 = "วางกลยุทธ์!",
  str_voice_1602181_37 = "การโจมตีอันเฉียบขาด",
  str_voice_1602181_38 = "ตอนนี้นี่เป็นของฉันแล้ว!",
  str_voice_1602181_39 = "คว้าโอกาสทุกอย่าง!",
  str_voice_1602181_40 = "ชัยชนะที่แหวกแนว!",
  str_voice_1602181_41 = "เรามารวยด้วยกันเถอะ",
  str_voice_1602181_42 = "ขอบคุณที่อุดหนุน!",
  str_voice_1602181_43 = "ฉันคำนวณผิดตอนก่อนหน้านี้หรือเปล่า...?",
  str_voice_1602181_44 = "กิลด์เหนือเมฆมีเฟอร์นิเจอร์สวยงามหลากหลายประเภท บางอย่างอาจจะดูเหมาะสมกับที่นี่มาก",
  str_voice_1602181_45 = "ให้ฉันเหรอ? ขอบคุณนะ!",
  str_voice_1602181_46 = "คุณใช้เงินอย่างคุ้มค่า!",
  str_voice_1602181_47 = "คุณไม่ได้ตามหาบางอย่างใช่ไหม",
  str_voice_1602181_48 = "ฉันจะแน่นอนตอบแทนความใจกว้างของคุณ",
  str_voice_1602181_49 = "ฉันไม่ค่อยขยายความเก่งของตัวเอง แต่หลังจากที่ฉันสร้างธุรกิจขนาดใหญ่จากที่เป็นอะไรไม่ได้ ฉันควรถูกพิจารณาว่าเป็นหนึ่งในผู้ประกอบการที่ประสบความสำเร็จที่สุดในอัมบราตัน",
  str_voice_1602181_50 = "มีเหตุผลจริงๆที่จะต้องพูดถึงอดีตที่ซ่อมแซมไม่ได้หรือไม่? ในฐานะลูกค้าที่มีค่าของฉัน คุณคือสิ่งที่สำคัญที่สุดที่นี่และตอนนี้ คุณไม่เห็นด้วยหรือไม่?",
  str_voice_1602181_51 = "ที่รักของฉัน การไหลเวียนของเงินก็เหมือนกับการไหลเวียนของเลือด - การไหลเวียนที่มีประสิทธิภาพจะส่งความกระจ่างใสให้กับสังคม นั่นคือ กิลด์เหนือเมฆคืออวัยวะที่รับผิดชอบในการขับเคลื่อนโลกสู่ความเจริญรุ่งเรือง!",
  str_voice_1602181_52 = "Alchemy Stars",
  str_voice_1602181_53 = "สวัสดีลูกค้าที่รักของฉัน",
  str_voice_1602181_54 = "อรุณสวัสดิ์จ้ะ ที่รัก",
  str_voice_1602181_55 = "มาเยี่ยมชมกิลด์เหนือเมฆกันเถอะ คุณจะไปหรือไม่?",
  str_voice_1602181_56 = "นอนหลับหรือยังน่ะ ที่รัก",
  str_voice_1602181_57 = "สุขสันต์วันปีใหม่ คนรักของฉัน กิลด์เหนือเมฆได้เพิ่มปีทางธุรกิจเข้าไปในประวัติศาสตร์อีกปี และเช่นเดียวกับมิตรภาพของเรา",
  str_voice_1602191_1 = "คุณบอกว่าสไตล์การเล่นหมากรุกของฉันเปลี่ยนไปหรือ? ตรงไปตรงมา, ตากล้า, และรุนแรง... นี่เป็นสไตล์ของฉันเสมอ แม้ว่ามันจะถูกฝังฝังในแชโดว์มาหลายปีแล้ว",
  str_voice_1602191_2 = "การสิ้นเปลืองความหลงใหลทั้งหมดเป็นความผิดพลาดที่พบบ่อยในวัยรุ่น และฉันก็ไม่ใช่ข้อยกเว้น การซ่อนความแข็งแกร่งที่แท้จริงเป็นกลยุทธ์ที่จำเป็น",
  str_voice_1602191_3 = "ฉันไม่ยินยอมที่จะมองแผลเป็นเหรียญตราแห่งเกียรติยศ แผลใหม่ที่หายดีบนแผลเก่าๆ มันกลายเป็นเกราะของฉัน... อีกส่วนหนึ่งที่ทำให้ฉันเป็นฉันเองจริงๆ",
  str_voice_1602191_4 = "ระเบียงเสียงกระซิบที่เต็มไปด้วยกับดัก ที่แม้แต่เงาของตัวเองต้องเดินอย่างระมัดระวัง มันเป็นเกมที่ชั่วร้ายและไร้ความหมาย แต่การชนะก็ยังทำให้รู้สึกตื่นเต้นไม่น้อย",
  str_voice_1602191_5 = "ความสามารถในการทำให้ผู้อื่นหวาดกลัวนั้นเป็นพลังที่น่าประทับใจ ไม่มีใครปฏิเสธได้ว่าลักษณะภายนอกธรรมชาติของฉันได้ทำให้ฉันมีประโยชน์มากมาย",
  str_voice_1602191_6 = "เมื่อรอยแผลของคนหนึ่งถูกเปิดเผยในแสงกลางวัน พลังของเขาจะพุ่งขึ้นมาที่ผิวพรรณภายใต้สายตาของผู้อื่น และเงา... ไม่ควรปิดบังความจริงจากตัวเองเช่นกัน",
  str_voice_1602191_7 = "คุณชอบสูทและรองเท้าที่คุณเห็นในตู้เสื้อผ้าของฉันไหม? เสื้อผ้าที่มีเสน่ห์นั้นทำหน้าที่เป็นการปลอมตัวที่สมบูรณ์แบบ ทำให้ฉันสามารถกลายเป็นเงาที่แท้จริง...",
  str_voice_1602191_8 = "ฉันมีขวดไวน์ในคอลเลกชันของฉันเยอะมากที่อายุเท่ากับคุณ ถ้าไม่ใช่ที่มากกว่า แต่ยังเร็วเกินไปสำหรับคุณที่จะลอง แต่ฉันจะแน่นอนเปิดขวดหนึ่งให้คุณเมื่อคุณบรรลุนิติภาวะ.",
  str_voice_1602191_9 = "การเล่นหมากรุกของคุณนั้นคล้ายกับเพื่อนเก่าของผม ในตอนนั้น ผมไม่สามารถช่วยเขาได้... ผมไม่ยอมให้คุณต้องเผชิญกับโชคชะตาที่เหมือนกัน",
  str_voice_1602191_10 = "ฮ่าๆ การหลงใหลในความคิดเป็นสิ่งที่ดี แต่การฝันกลางวันก็ไม่ใช่นะ",
  str_voice_1602191_11 = "ทุกแผลเป็นบนร่างกายของฉันคือดวงตา และฉันจะใช้แต่ละดวงเพื่อช่วยคุณดูแลโลกนี้",
  str_voice_1602191_12 = "คุณธรรมและการเปลี่ยนแปลงเป็นสิ่งที่ต้องได้รับผ่านการต่อสู้ คุณควรรู้แล้วว่าหลักการนี้ยังใช้ได้แม้ในโลกที่ไม่มีอิคลิพไซท์",
  str_voice_1602191_13 = "มีเด็กๆ ในโลกนี้ที่มีความสามารถพิเศษแต่อยู่ในสภาพที่ไม่สามารถควบคุมได้ ฉันไม่ต้องการให้พวกเขาประสบประสบการณ์เดียวกับที่ฉันเคยประสบในอดีต ถ้าคุณอายุน้อยลงหลายปี ฉันยินดีที่จะรับคุณเข้ามาด้วย แม้ว่าฉันคิดว่ามันอาจจะยังไม่สายเกินไปสำหรับสิ่งนั้น",
  str_voice_1602191_14 = "ผู้ที่รักษาความสงบเรียบร้อยไม่จำเป็นต้องรู้เรื่องลับที่สกปรกในการสร้างความสงบเรียบร้อยนั้น แค่ทำต่อไป และแชโดว์จะดูแลการเดินทางไกลของคุณ",
  str_voice_1602191_15 = "ขอพรสิ, แล้วฉันจะช่วยให้ความปรารถนาของคุณเป็นจริง",
  str_voice_1602191_16 = "คิดอย่างรอบคอบเสมอก่อนที่จะลงมือทำ และ... อย่าเปิดเผยมือของคุณได้ง่ายๆ",
  str_voice_1602191_17 = "เด็กน้อย คุณควรจะทำตัวเองอบอุ่นด้วยแสงอาทิตย์ยามเช้าทุกครั้งที่ได้โอกาส สุดท้ายแล้ว นี่คือวัตถุประสงค์ของภารกิจของฉันในแชโดว์",
  str_voice_1602191_18 = "คุณไม่พักวันนี้หรือ? คุณต้องการเรียนรู้เพิ่มเติมเกี่ยวกับเหตุการณ์ที่วุ่นวายในอดีตหรือไม่?",
  str_voice_1602191_19 = "อืม... คุณยังตื่นอยู่เหรอ? ขอโทษนะ แผลเหล่านี้มักจะแสดงอาการชัดเจนในช่วงเวลานี้ของคืน",
  str_voice_1602191_20 = "ฉันจะทำให้ Umbraton มีความมั่นคงและระเบียบเรียบร้อยมากขึ้น ไม่ว่าราคาที่ต้องจ่ายจะเป็นอย่างไร",
  str_voice_1602191_21 = "อาจเป็นเพราะองค์ราชินีที่ทุกคนเห็นนอร์ธแลนด์เป็นที่หลบภัย เพราะเธอได้รับมรดกและรักษาการปกครองที่บริสุทธิ์และเรียบร้อย",
  str_voice_1602191_22 = "เงามืดจะคอยเฝ้ามองเจ้า",
  str_voice_1602191_23 = "การป้องกันอิคลิพไซท์มักไม่จำเป็นต้องคิดมาก ฉันรับรองว่ามันสามารถเป็นวิธีที่ดีในการบรรเทาความเครียด",
  str_voice_1602191_24 = "เบเธล... เธอไม่เหมือนฉันเลย ซึ่งเป็นเหตุผลว่าทำไมเธอถึงยืนอยู่เหนือแชโดว์ได้ มันเป็นสิ่งที่ดี.",
  str_voice_1602191_25 = "เฮ้, ลีโอนาบางครั้งทำให้ฉันนึกถึงตัวเองเมื่อยังเป็นวัยรุ่น ความมั่นใจที่อยู่ภายในเธอนั้นแม้กระทั่งยังแรงกว่าของฉันเอง",
  str_voice_1602191_26 = "ไม่มีใครชอบการแพ้ และฉันก็ไม่ต่างหาก—ไม่ว่าจะเป็นในหมากรุกหรือชีวิต",
  str_voice_1602191_27 = "เมื่อคุณจริงจังรวมตัวเป็นหนึ่งกับเงามืด คุณจะรู้สึกว่าตัวเองมีความอดทนมากขึ้นอย่างรวดเร็วเมื่อเทียบกับที่ผ่านมา",
  str_voice_1602191_28 = "คุณควรเรียนรู้วิธีสร้างพื้นที่ซ่อนเร้นสำหรับตัวเองบนยานโคลอสซัส ที่แม้ฉันเองยังหาไม่เจอ",
  str_voice_1602191_29 = "ฮูม, ฉันคิดว่าฉันควรแสดงความยินดีกับคุณ ตอนนี้คุณเข้าใจแล้วว่าเงามืดเกิดขึ้นในความวุ่นวายที่ลึกลับ และไม่มีทางจะหลุดพ้นจากมันได้จริงๆ",
  str_voice_1602191_30 = "เงามืดไม่มีขีดจำกัด",
  str_voice_1602191_31 = "รางวัลที่เหมาะสมสำหรับราคาที่จ่ายไป",
  str_voice_1602191_32 = "เงากำลังลึกลับมากขึ้น",
  str_voice_1602191_33 = "คำสัญญาของเงามืดนั้นเป็นนิรันดร์",
  str_voice_1602191_34 = "ได้เวลาเริ่มเดินหน้าแล้ว",
  str_voice_1602191_35 = "แผลเป็นของฉันกำลังเผา",
  str_voice_1602191_36 = "ฉันจะแสดงให้พวกเขาเห็นทั้งหมด",
  str_voice_1602191_37 = "มองฉันสิ—!",
  str_voice_1602191_38 = "การทำลายล้างสร้างชีวิตใหม่!",
  str_voice_1602191_39 = "ฮราาาาา—!",
  str_voice_1602191_40 = "มองขึ้นไป!",
  str_voice_1602191_41 = "ตามฉันมา",
  str_voice_1602191_42 = "พวกเขาควรรู้ว่าอะไรรอพวกเขาอยู่",
  str_voice_1602191_43 = "เพียงแค่เพิ่มแผลเป็นเข้าไปในร่างกายของฉันเท่านั้น",
  str_voice_1602191_44 = "อืมม? ทุกครั้งที่ฉันเข้าไปในโคลอสซัสของคุณ ฉันสังเกตเห็นการเปลี่ยนแปลงใหม่ ๆ",
  str_voice_1602191_45 = "รสนิยมของคุณ... อืมม, ดีกว่าของฉันเมื่อก่อนนะ",
  str_voice_1602191_46 = "คุณรู้จริงวิธีการดูแลคนอื่น",
  str_voice_1602191_47 = "ฉันสามารถเติมแก้วนิทรรศการด้วยของขวัญเหล่านี้ทั้งหมดได้",
  str_voice_1602191_48 = "คุณรู้จักฉันดีกว่าคนร่วมงานของฉัน",
  str_voice_1602191_49 = "เมื่อระเบียบเก่าของ Umbraton ยังมีอยู่ เด็กที่มีลักษณะที่ดูเหมือนปีศาจจะไม่มีความหวังในการได้รับการดูแลที่เอื้อเฟื้อ แม้แต่ในส่วนที่มืดมิดของเมือง",
  str_voice_1602191_50 = "เราทุกคนสวมหน้ากากที่แตกต่างกัน อีสต์วานที่คุณเห็นตอนนี้ไม่ใช่อะไรมากกว่าคนที่ฉันต้องการให้คุณเห็น",
  str_voice_1602191_51 = "คุณต้องการที่จะคืนความเป็นระเบียบให้กับความวุ่นวายหรือ? แล้วคุณต้องกลายเป็นส่วนหนึ่งของความวุ่นวายนั้นก่อน",
  str_voice_1602191_52 = "Alchemy Stars",
  str_voice_1602191_53 = "เพื่อนของฉัน.",
  str_voice_1602191_54 = "อรุณสวัสดิ์",
  str_voice_1602191_55 = "คุณควรพักผ่อนนะ",
  str_voice_1602191_56 = "ถูกปกคลุมด้วยความมืดของคืน",
  str_voice_1602191_57 = "ยกแก้วขึ้นสูง, เพราะแม้แต่แชโดว์ก็ฉลองมาถึงปีใหม่",
  str_voice_1502201_1 = "อูว่า! ม-ม-มาจากที่ไหน?! ข-ข-ขอรบกวนยืนห่างอย่างน้อยยี่สิบเมตรเมื่อฉันยุ่งกับงาน และอย่าลืมไอ ขู่คอ หรือกระทืบเท้าเมื่อคุณมาถึง!",
  str_voice_1502201_2 = "เอิ่ม, ฉันสามารถลองชิมเค้กชิ้นนี้ได้มั้ย? แค่ชิมเล็ก ๆ... ว้าว! ลายจานนี้เหมือนกับที่ฉันอ่านในหนังสือเกี่ยวกับ Caelestites! แว่นขยายของฉันอยู่ที่ไหนนะ?!",
  str_voice_1502201_3 = "\"การประเมินของเก่าเป็นงานที่ต้องใช้สมองมาก ดังนั้นนักประเมินจึงต้องรับประทานอาหารมากกว่าผู้ที่ผลิตของปลอม!\" นั่นเป็นคำพูดจากหนังสือที่ชื่อว่า \"บทนำเรื่องการประเมิน\" หืม? คุณรู้ได้ไงว่าผมเป็นคนเขียน?",
  str_voice_1502201_4 = "ว้าว! Lumina ของฉันแข็งแกร่งขึ้นขนาดนั้นเลยเหรอ? มันเกือบจะเป็นไปได้นะ ดีที่ฉันไม่ได้ทำลายภาพวาดโบราณของฉัน!",
  str_voice_1502201_5 = "พลัง... ฉันรู้สึกถึงพลังมากมายที่พลุ่งพล่านอยู่ในตัวฉัน! ฉันเดาว่าฉันอาจจะเดินเข้าไปในห้องที่เต็มไปด้วยคนได้แล้วนะ! รอสักครู่... ไม่เป็นไร ฉันคงเพียงแค่จินตนาการเอง",
  str_voice_1502201_6 = "คุณคิดว่าฉันก็แข็งแกร่งขึ้นเช่นกันใช่ไหม PlayerName? ฉันรู้ว่าการที่ฉันกินของหวานเยอะๆ ไม่ได้ทำให้ฉันเจ็บ! นี่ ฉันจะแบ่งขนมของฉันให้คุณส่วนหนึ่ง... หรืออาจจะเป็นสี่ส่วนหนึ่ง? คุณไม่มีปัญหาใช่ไหม?",
  str_voice_1502201_7 = "กรอบไม้สนที่มีล็อคปรับได้ ทำด้วยแบบแกนน่อนโบราณ มันดีมาก... หืม? อ๊าก! ไม่...ไม่ใช่อะไร ฉันแค่กำลังหากรอบที่ดีที่สุดให้กับภาพเหมือนของคุณ! อะไรนะ? คุณยังไม่เคยมีภาพเหมือนเลยเหรอ? ฉัน...ฉันสามารถแนะนำศิลปินที่ดีให้คุณ ถ้าคุณต้องการนะ!",
  str_voice_1502201_8 = "คุณมาเล่นกับฉันเสมอนะ PlayerName... อะไรนะ? ฉ-ฉ-ฉันไม่เคยรู้สึกว่าคุณน่ารำคาญเลย! ฉันมีความสุขทุกครั้งที่ได้เจอคุณ และคุณยินดีที่จะมาเล่นกับฉันเมื่อไหร่ก็ได้... ไม่-ไม่ใช่ว่าคุณต้องมาหรืออะไรนะ! ถ้าคุณไม่มีเวลาสำหรับฉันก็ไม่เป็นไร...",
  str_voice_1502201_9 = "ฉันเคยกลัวคนแปลกหน้ามาก ก่อนที่ฉันจะพบกับคุณ... บางครั้งฉันชอบคิดว่าถ้าฉันมีพี่ชาย คงจะเหมือนคุณ...",
  str_voice_1502201_10 = "ไม่มีทางเธอจะหลับตอนนี้ใช่ไหม? เมื่อวานนี้เธอไม่ได้นอนหรือเปล่า?",
  str_voice_1502201_11 = "ที่นี่สว่างจัด ฉันคิดว่าฉันจะละลายไป... หืม? คุณต้องการให้ฉันคอยดูประตูให้หรอ? ค-ค่อย! ฉันจะคอยสังเกตคนที่แอบอ้างว่าเป็นคนดี... หรืออย่างน้อยฉันจะพยายามทำให้ดีที่สุด.",
  str_voice_1502201_12 = "ว้าว, คุณจริงจังหรือ? สถาบันศิลปะต้องการเพิ่มฉันเข้าไปในรายชื่อผู้ประเมินที่ลงทะเบียน และพวกเขาต้องการให้ฉันให้ความคิดเห็นเชิงเ专ชาในศาล?! ไม่...ไม่...ไม่ได้, ฉันทำไม่ได้ ยกเว้น... ยกเว้นคุณไปกับฉัน! ฉันขอโทษ, ฉันขอร้องมากเกินไปจากคุณหรือไม่?",
  str_voice_1502201_13 = "คุณอยากช่วยฉันย้ายของเก่าบ้างหรือเปล่า? ขอบคุณนะ! โอ้ ตัวนั้นหนักไปหรือเปล่า? ไม่ต้องห่วง ฉันจะดูแลมันเอง! ค-คุณควรทานน้ำตาลเพิ่มเติมเพื่อเพิ่มพลังงานบ้างนะ.",
  str_voice_1502201_14 = "*หายใจหอบ* วันนี้ฉันกินขนมได้แค่ 37 ชิ้นเท่านั้น ฉันหิวจนหัวเริ่มมึน ฉันไม่คิดว่าฉันจะทนได้นานแค่ไหน...",
  str_voice_1502201_15 = "สุขสันต์วันเกิดนะ! ค-คุณไม่จำเป็นต้องเชิญฉันไปปาร์ตี้วันเกิดของคุณ แต่ฉันก็ไม่รังเกียจถ้าคุณส่งชิ้นเค้กมาที่ห้องฉัน... น-นั่นจะโอเคไหมคะ?",
  str_voice_1502201_16 = "สวัสดีค่ะ! ฉันมักจะหวั่นไหวเมื่อมีคนเดินอยู่รอบ ๆ มากมาย แต่คุณดูเหมือนจะไม่เคยรำคาญเลย ความลับของคุณคืออะไรคะ?",
  str_voice_1502201_17 = "สวัสดีค่ำ... หืม? เช้าแล้วเหรอ? ฮิฮิ, เวลาผ่านไปเร็วจริงๆ เมื่อฉันทำงานอยู่ข้างๆ คุณ เพราะฉันรู้สึกสบายใจมาก",
  str_voice_1502201_18 = "นี่กลางคืนแล้วเหรอ? ไม่ต้องห่วง, ฉันยังทำงานได้อยู่... อยากอยู่ดึกกับฉันมั้ย?",
  str_voice_1502201_19 = "ฉันยังไม่รู้สึกเหนื่อยเลย แต่คุณควรไปนอนเร็วๆนี้ อะไรนะ? ฉันจะไม่โตถ้าฉันไม่ได้นอนพอหรอ? โอ้ นั่นเป็นเหตุผลว่าทำไมฉันถึง...",
  str_voice_1502201_20 = "ประวัติศาสตร์ของ Umbraton มันซับซ้อนจริงๆ มีเรื่องราวมากมายที่ซ้อนทับกันเหมือนแหล่งขุดเจาะโบราณ... ฉัน...ฉันก็ชอบเรื่องแบบนี้จริงๆ",
  str_voice_1502201_21 = "ฉันเดาว่าสินค้าปลอมเยอะมากที่ไหลเข้ามาในลูโมโพลิส! และนั่นก็เพราะ... ผู้ประเมินที่อยู่ที่นั่นไม่ค่อยมีทักษะ และลูกค้าของพวกเขาก็แค่แสร้งทำเป็นที่สนใจศิลปะเท่านั้นเอง",
  str_voice_1502201_22 = "เงามืดกำลังเฝ้ามองคุณ... และในฐานะผู้ประเมิน ฉันก็เช่นกัน!",
  str_voice_1502201_23 = "อิคลิพไซท์ไม่ใช่สิ่งมีชีวิตจริง ๆ แต่เป็นสิ่งจำลองประเภทหนึ่ง... อูววว, ไม่, ไม่, ฉันไม่ได้มีหลักฐานที่จะสนับสนุนความคิดเห็นของฉัน ค-คงเรียกว่าสัญชาตญาณ... ฉันคิด...",
  str_voice_1502201_24 = "เฮ้! มาพบกับเพื่อนใหม่ของฉันสิ มาจากหลงโจวเลยนะ! ดูสีทาที่เหมือนเพชรนี้สิ... หืม? \"แค่เก้าอี้ฝีมือจากไม้ศรัทธา\"? แน่นอนว่ามันคือ แล้วมันจะเป็นไงล่ะ?",
  str_voice_1502201_25 = "อัลลัวราเป็นคนสะสมที่ดีที่สุดในอัมบราตันทั้งหมด เธอมีรสนิยมที่ดีเยี่ยมและมีสายตาที่สมบูรณ์แบบสำหรับคุณภาพ ดังนั้นไม่มีทางที่ของสะสมของเธอจะเป็นของปลอม!",
  str_voice_1502201_26 = "พิพิธภัณฑ์มีสมบัติใหม่ที่จัดแสดง?! สุดยอดเลย! เราจะไปดูมันเมื่อไหร่? พรุ่งนี้? หรืออาจจะ... มาดูมันวันนี้กันเถอะ!",
  str_voice_1502201_27 = "ฉ-ฉ-ฉันคุยกับสามคนต่างๆวันนี้แล้ว ดังนั้นฉันไม่มีแรงเหลือที่จะสังสรรค์อีกแล้ว!",
  str_voice_1502201_28 = "โคลอสซัสคือสรุปของวัฒนธรรมเคเลสไทต์! รูปร่างของมัน, สีของมัน, และลายของมัน... คุณต้องให้ฉันอยู่ที่นี่และศึกษามัน!",
  str_voice_1502201_29 = "ย-ย-ยินดีที่ได้พบคุณ ฉันชื่อเวอร์จิล และฉันชอบของเก่า งั้นลาก่อน... รอสักครู่, เสื้อผ้าของคุณมาจาก Eraveil! คุณต้องเป็น Caelestite ที่ออกมาจากพื้นดินเมื่อสักครู่นี่แหละ!",
  str_voice_1502201_30 = "เปิดเผยความจริงทั้งหมด!",
  str_voice_1502201_31 = "ตอนนี้ฉันมองเห็นได้ชัดเจนขึ้น",
  str_voice_1502201_32 = "ภูมิปัญญาโบราณอยู่กับฉันเสมอ",
  str_voice_1502201_33 = "ความเท็จไม่สามารถหลอกลวงฉันได้!",
  str_voice_1502201_34 = "เอ้อ! คนเยอะจัง!",
  str_voice_1502201_35 = "เติมระดับน้ำตาลแล้ว!",
  str_voice_1502201_36 = "ด-ดูใกล้ๆหน่อยนะ",
  str_voice_1502201_37 = "ของปลอมไม่มีทางหลอกผ่านฉันได้...!",
  str_voice_1502201_38 = "ฉันได้ตรวจจับข้อบกพร่องอย่างน้อยเจ็ดข้อ",
  str_voice_1502201_39 = "แสดงสีที่แท้จริงของคุณ!",
  str_voice_1502201_40 = "ไม่มีอะไรรอดสายตาของฉันไปได้",
  str_voice_1502201_41 = "ฉันควรจะนำคนเยอะๆ แบบนี้จริงๆ หรือ?",
  str_voice_1502201_42 = "ที่นี่มีแต่สินค้าที่มีข้อบกพร่องเท่านั้น",
  str_voice_1502201_43 = "พลังของฉัน... ไม่ใช่ของจริงหรือ?",
  str_voice_1502201_44 = "คุณหมายความว่า... ฉันสามารถศึกษาโคลอสซัสเมื่อไหร่ก็ได้หรือ?! ฉ-ฉันฝันรึเปล่า?!",
  str_voice_1502201_45 = "ของขวัญเหรอ? ฉันคิดว่าคุณต้องการให้ฉันประเมินสิ่งของ...",
  str_voice_1502201_46 = "ว้าว... นี่จะต้องเป็นส่วนหนึ่งของโบราณวัตถุที่ฉันยึดครองมากที่สุดแล้ว!",
  str_voice_1502201_47 = "ขอบคุณ! ดูเหมือนว่าของเก่าไม่ใช่สิ่งดีๆเดียวในโลกนะ!",
  str_voice_1502201_48 = "ว้าว! คุณรู้จริงๆว่าฉันชอบอะไรแล้วนะ!",
  str_voice_1502201_49 = "ฉัน...ฉันไม่ใช่ \"ผู้ประเมินอัจฉริยะ\" หรืออะไรที่คล้ายกัน ในเวลาที่ฉันยังไม่เข้าใจเรื่องเหล่านี้ ฉันเพียงแค่ใช้เวลาส่วนใหญ่ในการมองภาพวาดเก่าและของเก่า หลังจากนั้น ฉันก็เรียนรู้วิธีการแยกแยะอย่างเป็นธรรมชาติ",
  str_voice_1502201_50 = "ทำไมฉันถึงทำงานในวัยที่ยังเยาว์อย่างนี้หรือ? ถ้าจะพูดตรงๆ ก็เพราะฉันไม่สามารถทนที่จะสูญเ失 \"เพื่อน\" ของเก่าของฉัน...",
  str_voice_1502201_51 = "บางคนที่ทำการปลอมภาพวาดนั้น ถึงแม้จะวาดได้ดีกว่าศิลปินต้นฉบับเลย ธีมที่กล้าหาญ การผสมผสานสีที่สวยงาม และความรู้สึกซับซ้อนที่พวกเขาปลุกปล้ำ... โอ้! ข-ขอโทษนะ ฉันเริ่มพูดเพ้อไปอีกแล้ว.",
  str_voice_1502201_52 = "A-Alchemy Stars...!",
  str_voice_1502201_53 = "PlayerName!",
  str_voice_1502201_54 = "อุวะ, เช้าอีกแล้ว...",
  str_voice_1502201_55 = "สวัสดียามบ่ายค่ะ! น-นั่นแหละ ทั้งหมด.",
  str_voice_1502201_56 = "สายัณห์สวัสดิ์!",
  str_voice_1502201_57 = "โอ้ มันเป็นปีใหม่แล้วเหรอ? สุขสันต์วันปีใหม่นะ! รอสักครู่... ปกติงานฉลองปีใหม่มักมีคนเยอะๆ ใช่มั้ย? แต่ถ้าเธออยู่ที่นั่น ฉันคิดว่าฉันจะรับมันได้! มาเถอะ...!",
  str_voice_1602211_1 = "เพื่อให้แน่ใจว่าฉันปฏิบัติตามคำแนะนำของระบบประเภทของคุณได้อย่างถูกต้อง ฉันต้องถามคำถาม โดยการตอบคำถามของฉันตามความคาดหวังของคุณ ฉันหวังว่าจะสามารถเพิ่มประสิทธิภาพในการสนทนาของเรา",
  str_voice_1602211_2 = "นักวิทยาศาสตร์ต้องตระหนักเสมอถึงขีดจำกัดของปัญญาปราชญ์ และควรมุ่งหาความรู้สึกที่สูงขึ้นผ่านการรู้สึกต่อสิ่งแวดล้อม แค่นั้นเองความรู้ของเราจึงจะทันกับโลกที่กำลังเสื่อมโทรมอย่างรวดเร็ว",
  str_voice_1602211_3 = "ฉันได้พบกับ Bool ไม่ใช่เพราะโชคชะตา แต่เพียงแค่บังเอิญเท่านั้น คนทั่วไปมักจะสร้างสมมุติฐานเกี่ยวกับฉันทำให้ฉันดูแปลกประหลาดมากกว่าที่ฉันเป็นจริง... แต่ไม่เป็นไร ฉันยินดีกับความแปลกประหลาดของฉันเอง!",
  str_voice_1602211_4 = "หืม? ในฐานะนักวิทยาศาสตร์ การวิจัยคือการแสวงหาที่ยิ่งใหญ่และสูงส่งที่สุดของฉัน! ค่าใช้จ่าย คุณค่า ความประยุกต์... ฉันไม่สนใจเรื่องเหล่านั้นเลย",
  str_voice_1602211_5 = "บูลสามารถรับรู้เสียงดนตรีผ่านการมองเห็น และเปลี่ยนสีผ่านเสียง! นี่คือปรากฏการณ์ที่เรียกว่า \"สังขารวิญญาณ\" ที่เฉพาะออโรเรียนเท่านั้นที่สามารถทำได้ มันน่าทึ่งจริง ๆ!",
  str_voice_1602211_6 = "ในอดีต ฉันมีความยากลำบากในการเข้าใจผู้อื่น และพวกเขาก็มีความยากลำบากในการเข้าใจฉัน ซึ่งเป็นเหตุผลที่ฉันเลือกที่จะอยู่อย่างสันโดษจากโลก แต่หลังจากที่ฉันตัดตัวเองออกจากผู้อื่น เราก็เริ่มเข้าใจกัน...",
  str_voice_1602211_7 = "เหตุผลที่ฉันยังคงศึกษาเกี่ยวกับปัญญาประดิษฐ์โบราณ? ฮืม... ฉันคิดว่ามันมาจากความอยากรู้อยากเห็นของฉันต่อวัฒนธรรมโบราณและอนาคตของออโรเรียน ตอนนี้เป็นคิวของคุณแล้ว",
  str_voice_1602211_8 = "โอ้ หยุดมาที่ห้องพยาบาลบ้างสำหรับการตรวจระบบทางเดินอาหารนะ ระบบย่อยอาหารของคุณคงเสียหายหลังจากที่อยู่ในอากาศนานเท่านั้น...",
  str_voice_1602211_9 = "ในช่วงเวลาที่อันตราย ความเชื่อที่ลึกซึ้งที่สุดของเรามักจะอยู่ที่ด้านหน้าของใจเรา ดังนั้นเมื่อคุณบอกว่าคุณต้องการปกป้องทุกอย่าง... อย่างไรก็ตาม ฉันไม่ได้รู้สึกประหลาดใจอย่างพิเศษ",
  str_voice_1602211_10 = "ถ้าอารมณ์ถูกจำแนกเป็นหนึ่งในสามประเภท คือ สุข, เศร้า, และไม่แคร์... การจำแนกเหล่านี้สามารถใช้เพื่ออธิบายความสัมพันธ์ระหว่างภาษาการเขียนโปรแกรมและอิคลิปเซียนได้หรือไม่?",
  str_voice_1602211_11 = "บูลตื่นเต้นอย่างไม่สามารถควบคุมได้หลังจากได้ยินว่าคุณต้องการผู้ช่วย ฉันไม่ค่อยสามารถทำงานร่วมกับคนอื่นได้ดี แต่บูลเป็นคนที่สามารถทำงานเป็นทีมได้ดี ดังนั้นคุณสองคนสามารถคุยกันได้! หึ? หลับอีกแล้ว...?",
  str_voice_1602211_12 = "ลองจินตนาการถึงยุคที่เทคโนโลยีครองเมือง ที่นั่น ความจำน่าจะมีค่าเท่ากับข้อมูลที่ถูกบันทึกไว้ ความรู้คือพลังเสมอ ยิ่งคุณได้รับความรู้มากขึ้น คุณก็ยิ่งแข็งแกร่งขึ้น",
  str_voice_1602211_13 = "ประวัติศาสตร์ไม่ได้เป็นความจริงเสมอไป และวัฒนธรรมไม่ได้สร้างขึ้นจากข้อมูลดิบ แม้เครื่องจักรนั้นจะบันทึกข้อมูลเพียงพอเพื่อที่จะได้ความรู้ทั่วถึง \"อัจฉริยะ\" ก็ไม่ได้หมายความว่าเราจะปฏิบัติตามทางที่มันทำนายไว้",
  str_voice_1602211_14 = "ในการต่อสู้ แทนที่จะเน้นเกินไปในพิธีกรรมที่จำเป็นในการเปิดใช้งาน Luminatics เราควรที่จะศึกษาธรรมชาติของ Lumina มากกว่า ในโปรแกรมของฉัน การเปิดใช้งาน Luminatics ต้องการเพียงแค่บรรทัดโค้ดที่ไม่เด่นเท่านั้น",
  str_voice_1602211_15 = "วันเกิดฉันเหรอ? ถ้าไม่เร่ง เราฉลองวันพรุ่งนี้ก็ได้นะ",
  str_voice_1602211_16 = "คิดว่าทำงานและออกกำลังกายในเวลาเดียวกันยากหรือไม่? คุณจะไม่รู้จนกว่าคุณจะลอง!",
  str_voice_1602211_17 = "แก้วกาแฟนี้จะเปลี่ยนสีตามอารมณ์ของฉัน ดูเหมือนว่าฉันนอนหลับดีเมื่อคืนนี้!",
  str_voice_1602211_18 = "รหัสที่สวยงามจริงๆ! โอ้ ถ้าคุณสามารถเห็นคุณค่าของมันได้น่ะสิ!",
  str_voice_1602211_19 = "เวลาถูกกำหนดภายใน คุณรู้ว่าฉันหมายถึงอะไรเมื่อฉันบอกว่ายังเช้าอยู่ใช่ไหม",
  str_voice_1602211_20 = "เครื่องจักรและหลายเมืองใต้ดินที่สร้างรอบ ๆ มัน... มันเป็นปาฏิหาริย์ที่ Illumina ยังมีอยู่ในปัจจุบัน",
  str_voice_1602211_21 = "พวกมันไม่ใช่เรื่องง่าย... ออโรเรียนต้องไม่มีอะไรสำหรับสิ่งที่สามารถสร้างสิ่งแบบนี้ได้",
  str_voice_1602211_22 = "ใช่ใช่ ขออิลลูมินาจงเจิดจำรัส ฉันไม่เชื่อว่าฉันยังต้องพูดเรื่องแบบนี้อีก",
  str_voice_1602211_23 = "เอาจริง ๆ แล้วชาวออโรเรียนยังไม่เคยชนะอิคลิพไซท์... ฮ่าฮ่าฮ่าฮ่า...",
  str_voice_1602211_24 = "อืม... นั่นคงจะเป็น Bool สินะ นอกจากการขาดความเข้าใจทั้งหมด เราก็ใกล้เคียงกันเท่าที่จะเป็นไปได้",
  str_voice_1602211_25 = "จอยซ์, ฉันคิดว่า... แต่ฉันไม่ได้ยินจากเขามาเกินครึ่งปีแล้ว คุณอยากรู้อะไรบ้าง?",
  str_voice_1602211_26 = "หนวกหูหรอ? แต่คุณไม่คิดว่าเสียงฮัมมิ่งนั้นช่วยให้หลับได้ง่ายขึ้นหรือไม่?",
  str_voice_1602211_27 = "ใครตัดสินใจว่านักวิทยาศาสตร์ทุกคนควรจะเป็นคนบ้าที่น่าเบื่อ หัวล้าน และไม่เคยอาบน้ำ? มันทำให้ฉันรำคาญแค่คิดถึงเรื่องนี้!",
  str_voice_1602211_28 = "พวกเขาบอกว่าโครงสร้างของโคลอสซัสได้รับแ inspiration จากมังกรโบราณ นี่เป็นไปได้กับภายในของพวกเขาหรือไม่?",
  str_voice_1602211_29 = "รออัปเดตมาเต็มทั้งห้าวัน... แล้วมันก็เป็นแบบนี้?! หืม? คุณไม่เห็นหรอว่าฉันยุ่งอยู่นะ–โอ้! ถึงเวลาออกกำลังกายแล้ว! ดังนั้น คุณต้องการอะไรล่ะ?",
  str_voice_1602211_30 = "ว้าว... ฉันเลเวลอัปได้ในไม่กี่เวลา!",
  str_voice_1602211_31 = "ระบบใหม่นี้ใช้ได้เลยนะครับ!",
  str_voice_1602211_32 = "มาสิ, เร็วขึ้นนิดเดียวก็พอ!",
  str_voice_1602211_33 = "แม้กระทั่ง Bool ยังยอมรับว่าคุณฉลาด!",
  str_voice_1602211_34 = "Bool ก็รอไม่ไหวเหมือนกัน!",
  str_voice_1602211_35 = "เตรียมตัวเริ่มโปรแกรม!",
  str_voice_1602211_36 = "สร้างกระบวนการสำเร็จ!",
  str_voice_1602211_37 = "เริ่มต้นโปรแกรม!",
  str_voice_1602211_38 = "เพิ่มความเร็วโปรแกรม!",
  str_voice_1602211_39 = "คำสั่งกระโดด!",
  str_voice_1602211_40 = "กำลังเขียนทับข้อมูล!",
  str_voice_1602211_41 = "ฮ่าฮ่าฮ่า... ปล่อยให้เราเถอะ!",
  str_voice_1602211_42 = "ข้อมูลถูกบันทึกแล้ว",
  str_voice_1602211_43 = "กำลังค้นหาไฟล์ที่หายไป",
  str_voice_1602211_44 = "อืม... ฮะ? อ๊ะ, Bool ทักทายครับ.",
  str_voice_1602211_45 = "ฉัน เอ่อ... ไม่มีอะไรจะให้คุณเลยนะ",
  str_voice_1602211_46 = "ว้าว...! เธอนี่ยอดอัจฉริยะจริงๆ!",
  str_voice_1602211_47 = "ขอบคุณ นำมันไปวางในลิ้นชักของฉันเถอะ",
  str_voice_1602211_48 = "ความรู้สึกของความตื่นเต้นนี้... มันยอดเยี่ยมจริง ๆ!",
  str_voice_1602211_49 = "ฉันเคยพึ่งพาเพียงแค่เหตุผลในการวิเคราะห์และคำนวณทุกอย่าง จึงทำให้คนเริ่มเรียกฉันว่า \"หุ่นยนต์\" แต่หลังจากที่ใช้สมองในทางนั้นมานาน การหยุดนั้นไม่ง่ายเลย",
  str_voice_1602211_50 = "ครอบครัวของฉัน... พวกเขาเห็นจะกังวลกับฉันที่ดูดซับข้อมูลมากมายในวัยที่ยังเล็กน้อย แต่ฉันรู้ว่าฉันจัดการได้ มันเป็นธรรมชาติของฉันอยู่แล้วเสียอีก",
  str_voice_1602211_51 = "ในตอนแรก ฉันไม่ค่อยเข้าใจพฤติกรรมของ Bool ฉันคิดว่า \"การนวด\" ของมันเป็นแค่การแสดงความรัก แต่ไม่นานฉันก็รู้ว่า Bool กำลังพยายามสื่อสารกับฉัน",
  str_voice_1602211_52 = "โอ้, Alchemy Stars.",
  str_voice_1602211_53 = "โอ๊ะ จริงด้วยแฮะ...",
  str_voice_1602211_54 = "ฉันรู้สึกดีหลังจากคืนที่ผ่านมา!",
  str_voice_1602211_55 = "พักบ่ายหรือเปล่า?",
  str_voice_1602211_56 = "คืนคือเปลเล่นของปัญญา!",
  str_voice_1602211_57 = "อีกปีนึงเนอะ... สุขสันต์วันปีใหม่ค่ะ",
  str_voice_1600024_1 = "เมื่อฉันออกจากภูเขาเมฆา ยายของฉันได้มอบชุดสวยงามของตระกูลซากุระให้ฉัน หวังว่าความคิดของคนของเราจะคอยคอยบริเวณฉัน...",
  str_voice_1600024_2 = "ถ้าฉันต้องทำลายผนึกในวันหนึ่ง ฉันขออธิษฐานว่าคุณจะอยู่ข้างๆฉันเพื่อเป็นพยานให้ดู",
  str_voice_1600024_3 = "เธอเห็นมั้ย? ไม่ต้องกลัวนะ แผลเป็นที่อยู่ใต้ผ้าพันนี้และสิ่งที่พวกมันแทนที่ ทั้งหมดนั้นเป็นเรื่องของอดีตแล้ว",
  str_voice_1600024_10 = "รบกวนหรือ? ไม่เลย ฉันเลือกที่จะมาที่นี่กับคุณ ที่สงบสุขนี้และฟังเสียงลม...",
  str_voice_1600024_11 = "ตราบใดที่ฉันยังอยู่ข้างๆ คุณ ฉันจะปกป้องคุณจากความชั่วร้าย... ฉันสาบานในนามที่เคารพของตระกูลซากุระและซาคาเอะ",
  str_voice_1600024_12 = "จนกว่าฉันจะแข็งแรงพอที่จะกลับไปที่ Cloud Island ฉันขอขอบคุณที่มีสถานที่อื่นๆที่ฉันเรียกว่าบ้าน เช่น อิลลูมินา... หรือที่ใดที่คุณอยู่",
  str_voice_1600024_13 = "คุณเป็นนักรบที่กล้าหาญและเป็นเพื่อนที่ไว้ใจได้ ในช่วงเวลาที่เรารู้จักกัน ฉันได้ยืนยันสิ่งนี้ด้วยทุกส่วนของตัวฉัน",
  str_voice_1600024_14 = "คนสุดท้ายของซากุระและซาเคะ และเคเลสไทต์คนสุดท้าย... เราจะไม่เคยเหงาถ้าเรายืนด้วยกันใช่ไหม?",
  str_voice_1600024_16 = "ฉันจะอยู่ตรงนี้เสมอ ถ้าคุณต้องการจะมาเจอฉันเมื่อไหร่ก็ได้นะ",
  str_voice_1600024_17 = "อรุณสวัสดิ์ ฉันไม่ได้ปลุกคุณใช่ไหม... ขอโทษนะคะ.",
  str_voice_1600024_18 = "ฉันกำลังจะทานอาหารแห้งในคืนนี้... โอ้ นี่ไม่ใช่ฉันปฏิเสธข้อเสนอของคุณนะ! แต่ถ้าคุณได้วางแผนไว้แล้ว ก็จะเป็นการหยาบคายถ้าฉันปฏิเสธ",
  str_voice_1600024_19 = "มือของคุณเย็นเล็กน้อย... อย่าลืมรักษาอุณหภูมิให้อบอุ่นในเวลากลางคืนนะ",
  str_voice_1600024_35 = "ดาบซาคาเอะสั่น",
  str_voice_1600024_36 = "ซากุระ ให้ฉันยืมพลังของคุณสักหน่อย!",
  str_voice_1600024_37 = "อย่ากลัวศัตรู—!",
  str_voice_1600024_38 = "กระจายและล้ำหน้า—!",
  str_voice_1600024_39 = "ฮ่าห์!",
  str_voice_1600024_40 = "กระจายตัว!",
  str_voice_1600024_44 = "ไม่ต้องห่วง ฉันได้ปรับตัวเข้ากับการอยู่ที่นี่มานานแล้ว",
  str_voice_1600024_58 = "อรุณสวัสดิ์",
  str_voice_1600024_59 = "สวัสดีตอนเช้า. ฉันไม่ได้ปลุกคุณใช่ไหม",
  str_voice_1600024_60 = "อยากมาฝึกฝนตอนเช้ากันหรือไม่?",
  str_voice_1600024_61 = "การทำสมาธิในตอนเช้าเป็นสิ่งจำเป็นสำหรับการบรรลุสติปัญญา",
  str_voice_1600024_62 = "สายัณห์สวัสดิ์ คุณกำลังพักผ่อนหรือเปล่า",
  str_voice_1600024_63 = "คุณมีแผนสำหรับวันพรุ่งนี้หรือไม่?",
  str_voice_1600024_64 = "ขอโทษนะ แต่ที่นี่มีชาไหมครับ?",
  str_voice_1600024_65 = "การทำงานอยู่ที่โต๊ะทั้งวันจริง ๆ แล้วทำให้คอและไหล่ของฉันเครียด...",
  str_voice_1600024_66 = "ราตรีสวัสดิ์ ขอให้กลิ่นหอมของดอกซากุระช่วยสะเทือนให้คุณหลับฝันดี",
  str_voice_1600024_67 = "ขอบคุณสำหรับเครื่องมือลับคมดาบเหล่านี้",
  str_voice_1600024_68 = "คุณสามารถบอกฉันเพิ่มเติมเกี่ยวกับวินเดเลียนได้ไหม?",
  str_voice_1600024_69 = "ดอกซากุระบานสะพรั่งบนเถ้าของอดีต",
  str_voice_1600024_70 = "ฉันสงสัยว่าคุณย่าและซันคิเป็นอย่างไรบ้างนะ?",
  str_voice_1600024_71 = "เจ็บปวดใจมากที่ต้องบอก แต่ฉันเคยมีสามเนียงภูเขาเมฆาที่หนักมาก...",
  str_voice_1500994_1 = "นาวิเกเตอร์... โอ้, ฉันควรเรียกคุณว่า \"นายน้อย\" เมื่อคุณสวมชุดนี้ใช่ไหม?",
  str_voice_1500994_2 = "ปิ่นผมหลงโจวมีคมแหลม แต่กลับเป็นสัญลักษณ์ของเสน่ห์เมื่อประดับบนผม",
  str_voice_1500994_3 = "ดาบเป็นเพียงอาวุธ; วัตถุประสงค์ของมันถูกกำหนดโดยผู้ที่ใช้มัน ดาบเวทมนตร์ของฉันถูกใช้เพื่อปกป้องเมือง และปกป้องคุณ",
  str_voice_1500994_10 = "ไม่มีคราบเปื้อนบนแขน... และขอบไม่ขาด. นี่ดีมาก.",
  str_voice_1500994_11 = "อาเรีย ทหารรับจ้าง ตอนนี้กำลังดูแลอยู่ที่ Twin Pavilions Bay ชุดที่ฉันใส่อยู่... ควรทำให้ฉันสามารถเทียบเคียงกับคุณได้",
  str_voice_1500994_12 = "พวกเขาบอกว่าผ้าไหมสามารถระบายอากาศได้ ฉันไม่รู้ว่ามันหมายถึงอะไรจนกว่าฉันจะได้สวมเสื้อผ้าที่ทำจากผ้าไหม",
  str_voice_1500994_13 = "ดาบเวทมนตร์ได้ปกป้องฉันมาตลอดเวลา ฉันรู้ดี ฉันแค่ไม่คาดคิดว่าจะมีความผูกพันแบบนี้",
  str_voice_1500994_14 = "หากได้ชุดที่เหมาะสมมากขึ้นและมีความเข้าใจที่ลึกซึ้งในดาบเวทมนตร์ ฉันจะสามารถช่วยเหลือคุณในการต่อสู้ได้ดียิ่งขึ้น ขอบคุณล่วงหน้าสำหรับความอดทนของคุณ",
  str_voice_1500994_16 = "... งานของฉันวันนี้หรือ? คือการอยู่ด้วยคุณและให้บริการคุณ มีอะไรที่ฉันสามารถช่วยคุณได้ไหม?",
  str_voice_1500994_17 = "สวัสดีตอนเช้า มันเป็นฝันสำหรับฉันที่จะได้รู้สึกถึงแสงแดดบนผิวหนังของฉันที่เปลือยเปล่า",
  str_voice_1500994_18 = "งานของคุณเสร็จแล้วหรือ? คุณจะไปพักผ่อนที่ไหนหลังจากนี้? ฉันจะคอยดูแลคุณนะ",
  str_voice_1500994_19 = "ชุดคลุมกันลมที่ขายใน Twin Pavilions Bay นั้นเบาและกันความเย็นดี เรากำลังออมเงินเพื่อซื้อให้คุณ...",
  str_voice_1500994_35 = "ดาบเวทมนตร์กำลังสั่นสะเทือน",
  str_voice_1500994_36 = "ดาบเต้นรำเพื่อคุณ",
  str_voice_1500994_37 = "รวมพลังทั้งหมด, ดาบเวทมนตร์!",
  str_voice_1500994_38 = "ช่วยฉันเอาชนะด้วยดาบเวทมนตร์!",
  str_voice_1500994_39 = "โจมตี!",
  str_voice_1500994_40 = "หนามโจมตี!",
  str_voice_1500994_44 = "ฉันฝึกทักษะการสนทนาที่ Twin Pavilions Bay แต่ฉันไม่รู้ว่าฉันได้พัฒนาขึ้นหรือไม่...",
  str_voice_1500994_58 = "ดาบเวทมนตร์ปกป้องฉัน และฉันจะใช้มันปกป้องคนอื่นๆ",
  str_voice_1500994_59 = "ฉันไม่เคยคิดว่าดอกไม้บนหนามจะสวยเท่าดอกฟูจิเลยครับ",
  str_voice_1500994_60 = "คนลองโจวบอกว่าดาบใหญ่ๆ มักจะไม่คม แต่ดาบเวทมนตร์นี้คมและมีหนาม",
  str_voice_1500994_61 = "สูตรยาของหมอเยาวชนคนนั้นมีประสิทธิภาพจริงๆ ถึงแม้จะไม่สามารถทำลายคาถา ฉันก็ยังขอบคุณอย่างยิ่ง",
  str_voice_1500994_62 = "ฉันจะไม่ลืมเจตนาของบรรพบุรุษที่สร้างดาบนี้ขึ้นมา...",
  str_voice_1500994_63 = "ฉันสามารถปีนผนัง, ควงดาบ, และเคลื่อนไหวได้สะดวกในชุดนี้... และมันยังสวยงามอีกด้วย.",
  str_voice_1500994_64 = "ฉันควรเรียนรู้การเย็บผ้าและตัดเสื้อที่เหมาะสมให้คุณหรือไม่คะ?",
  str_voice_1500994_65 = "หืม, ทุกคนคิดว่าฉันเป็นคนหลงไหลในเสื้อคลุมหรือ?",
  str_voice_1500994_66 = "ไม่เป็นไร ถึงแม้คำสาปนั้นไม่สามารถถูกทำลาย... ฉันก็ยังจะทำทุกอย่างเพื่อรอดชีวิต!",
  str_voice_1500994_67 = "มีหลายคนที่ฉันอยากจะตอบแทน อย่างเช่น นางสาว Xuan Ji, นางสาว Dantang, และคุณ...",
  str_voice_1500994_68 = "ใช่ ตั้งแต่นี้ไป ฉันจะเป็นนักดาบเวทมนตร์ และยังเป็นอาเรียของคุณด้วย",
  str_voice_1500994_69 = "ฉันได้มาถึงที่ทำภารกิจใหม่แล้ว ตอนนี้ฉันต้องยืนยันเป้าหมาย",
  str_voice_1500994_70 = "คุณต้องการจะบอกอะไรฉันบ้างหรือครับ, ดาบเวทมนตร์?",
  str_voice_1500994_71 = "ฉันจะไม่ทำให้ดาบเวทมนตร์ผิดหวัง!",
  str_voice_1500994_72 = "ฉันควรจะซื้อของฝากอะไรจากท้องถิ่นมาให้เพื่อนๆ ที่อัมบราตันและบนยักษ์ใหญ่ดีนะ?",
  str_voice_1500994_73 = "ชุดนี้เบามาก! ฉันอยากจะเคลื่อนไหวไปรอบ ๆ ในมันอีกบ้าง.",
  str_voice_1500994_74 = "คุณรู้สึกถึงความอาฆาตในสิ่งแวดล้อมของเราด้วยไหม ดาบเวทมนตร์?",
  str_voice_1500994_75 = "เฮ้! ฮ่า!",
  str_voice_1500994_76 = "ฉันสัมผัสได้ถึงบางสิ่ง!",
  str_voice_1602231_1 = "ฉันเข้าใจแล้ว ดังนั้นคุณคือผู้ดูแลสัตว์ในตำนานนี้ใช่ไหม? คุณอาจจะได้ยินเสียงนับไม่ถ้วนทุกวัน แต่เสียงของสัตว์ตัวนี้จะเป็นสิ่งที่สำคัญที่สุดเสมอ",
  str_voice_1602231_2 = "ฉันใช้เวลาส่วนใหญ่ในการอยู่ในท้องทะเลลึกลึก ที่นั่นคุณสามารถค้นพบถ้ำที่สร้างขึ้นโดยคนโบราณ ภายในถ้ำนั้นเย็นสบาย แม้ว่าจะดูมีรอยเหี่ยวชีวิตบ้าง",
  str_voice_1602231_3 = "มีสิ่งบางอย่างในทะเลที่สามารถทำให้เรือทำงานผิดพลาดและแม้กระทั่งจม... ชาวออโรเรียนนั้นแอบแ fragile มันเป็นเรื่องยุ่งยากเสมอทุกครั้งที่ต้องเก็บกวาดพวกเขาทุกคนเมื่อเกิดเหตุการณ์แบบนั้น",
  str_voice_1602231_4 = "ใช่ ฉันรู้ว่าฉันดูเหมือนเป็นราชินีแห่งมังกรที่สวมเครื่องประดับหรูหรานี้... แต่ฉันสวมมันเพราะว่ามันไม่สะดวกที่จะต้องติดตามสกุลเงินหลากหลายที่คุณใช้บนผิวดิน ด้วยของเล่นทองและเงินที่ฉันมีอยู่ ฉันมักจะมีเงินเพียงพอกับตัวฉันในเวลาใดก็ได้",
  str_voice_1602231_5 = "ฉันตื่นขึ้นแล้วพบว่ามีสิ่งเปลี่ยนแปลงมากมาย ไม่ใช่เรื่องแปลกใหม่ที่โลกจะเปลี่ยนแปลงขณะที่ฉันหลับ แต่ครั้งนี้ สิ่งที่เปลี่ยนแปลงมาจริง ๆ... คุณคิดว่าคุณสามารถพาฉันเที่ยวรอบได้ไหม?",
  str_voice_1602231_6 = "ฉันเชื่อว่าคุณสบายดีใช่ไหม, คนรุ่นใหม่ PlayerName มานั่งลงและบอกฉันทุกอย่างเกี่ยวกับปัญหาของแผ่นดินต่างประเทศนี้.",
  str_voice_1602231_7 = "เกล็ดของฉันจะไม่ทำให้คุณถูกขีดข่วน! ลองสัมผัสด้วยตัวคุณเองถ้าคุณไม่เชื่อฉัน!",
  str_voice_1602231_8 = "คุณอยากดูฉันเต้นไหม? คุณสามารถมาดูได้ แต่อย่าหัวเราะล้อเล่นนะ! มันเป็นการเต้นที่เก่ามาก–หลายพันปีเลยทีเดียวนะครับ.",
  str_voice_1602231_9 = "ฉันคือผู้ปกป้องที่ยิ่งใหญ่ ผู้พิทักษ์แห่งทะเลตะวันตก หญิงสาวแห่งพระคุณมังกร ศักดิ์สิทธิ์มังกรที่ทรงคุณค่าและดูแลคลื่นทะเล ฉันสามารถทำให้เรือของคุณผ่านไปได้อย่างปลอดภัย หลีกเลี่ยงอันตรายจากความลึกลับที่อันตราย และเปลี่ยนทุกๆ ความหายนะเป็นความสุข... ฉันสัญญา.",
  str_voice_1602231_10 = "ถูกพระเจ้าอวยพรด้วยพรหมลิขิต สาวมังกรนำความสุขมาให้กับโลกเมื่อเธอลงมายังโลก คลื่นของมหาสมุทรกว้างใหญ่เป็นความลึกลับ ดูเหมือนว่าถูกปกคลุมด้วยควัน สาวมังกร ของขวัญจากสวรรค์ นำพรมาให้กับทุกคนอย่างไม่นับถือ ดังเดือนอ่อนที่เติบโตขึ้นเรื่อย ๆ หรือดวงอาทิตย์ที่สว่างขึ้นเรื่อย ๆ",
  str_voice_1602231_11 = "ตกลงแล้ว ฉันกำลังจะไป! คุณอยากจะเผชิญเวลาด้วยฉัน... หรือมีสิ่งสำคัญที่คุณอยากจะถามจาก Benevolent Dragon Divinity หรือไม่?",
  str_voice_1602231_12 = "คุณคนที่มาจากฝั่งตะวันตกนั้นดูเหมือนจะปรากฏตัวทั่วทุกที่ โดยการแสดงโชว์แบบอัสตราน! ฉันยังสังเกตเห็นการเพิ่มขึ้นของเครื่องมือเล็กๆ ที่คุณทุกคนนั้นหลงไหล ฉันสงสัยว่าเราจะสามารถทำซ้ำอาคารสูงๆ จากอดีตที่ยิ่งใหญ่นั้นเมื่อไหร่...",
  str_voice_1602231_13 = "การเต้นรำ Dragon Maiden บนท้องทะเลที่วุ่นวาย? ใช่ ฉันเคยเห็นมัน! พวกเขาขอให้เด็กหญิงสวยๆเต้นบนเวทีในฐานะฉัน! ... แต่จริงๆแล้ว ฉันไม่ค่อยเป็นคนที่ชอบเต้นรำเท่าไหร่นัก",
  str_voice_1602231_14 = "ฉันไม่ค่อยสนใจจักรพรรดิ Zhao จริงๆ แล้วฉันรู้สึกเสียใจให้เขา - ถูกคนในรัฐบาลทั้งหลายรังเกียจเขาอยู่เสมอ ทหารยามวิ่งไปวิ่งมารอบตัวเขาทั้งวันทั้งคืน... ชีวิตแบบนั้นคืออะไร?",
  str_voice_1602231_15 = "ในอดีต ไม่ใช่เรื่องแปลกที่ชาวสังกัดที่ฉันนับถือจะอวยพรวันเกิดฉัน วันนี้ฉันได้โอกาสที่จะอวยพรวันเกิดให้คนอื่น นี่เป็นเรื่องที่ยอดเยี่ยมจริง ๆ!",
  str_voice_1602231_16 = "คุณกำลังเขียนอะไรที่นั่น? ให้ฉันดูหน่อย... หืม... ฉันไม่เข้าใจเลย!",
  str_voice_1602231_17 = "อืม, เธอตื่นเช้าจัง... ฉันอยากนอนต่อ... ไม่ต้องห่วง, คราวนี้ไม่ใช่หลายศตวรรษนะ...",
  str_voice_1602231_18 = "คุณคงจะหิวแล้วนะ คนรุ่นใหม่ PlayerName! อยากจะมาแบ่งกินอาหารที่ฉันเตรียมไว้บ้างมั้ย?",
  str_voice_1602231_19 = "นี่ดึกแล้วแต่เธอยังวางแผนจะออกไปนอกบ้านหรอ? หืม... ชีวิตแน่นอนไม่ง่ายสำหรับสิ่งมีชีวิตที่ยากจนเช่นเธอนะ",
  str_voice_1602231_20 = "ฉันเคยบอกคุณว่าหลงโจวได้ชื่อมาอย่างไรหรือไม่? ฉันเคย...? โอเค แล้วก็...",
  str_voice_1602231_21 = "เรื่องราวของอีราเวลน่ะทำให้ฉันเศร้าอย่างลึกซึ้ง แต่ฉันเชื่อว่าเรายังไม่ได้ยินเรื่องราวสุดท้ายของชาวเคเลสไทต์ ดังนั้น โปรดอย่าไปยึดติดอดีตเฉย ๆ",
  str_voice_1602231_22 = "ได้รับพรจากสวรรค์! หลงโจว!",
  str_voice_1602231_23 = "แม้ว่าพวกเขาจะดูดุดันจากภายนอกที่น่ากลัว แต่เมื่อเผชิญหน้ากับพลังที่แท้จริง วิญญาณชั่วร้ายจะสลายไปในครั้งแรกที่ถูกโจมตี",
  str_voice_1602231_24 = "คุณเคยพบกับเพื่อนคู่แค้นที่มีชื่อเสียงอื่น ๆ หรือไม่? แม้ว่าคุณจะไม่เคยพบก็ตาม ฉันแน่ใจว่าเราจะไปเจอพวกเขาในอนาคตอันใกล้นี้แน่นอน",
  str_voice_1602231_25 = "มังกรเป็นญาติห่างๆ ของฉัน, ปลางูเป็นญาติห่างๆ ของมังกร, และยูเอบายเป็นญาติห่างๆ ของปลางู... นั่นทำให้เธอเป็นญาติห่างๆ ของญาติห่างๆ ของญาติห่างๆ ของฉันหรือไม่?",
  str_voice_1602231_26 = "ฉันชอบนอน, ประกบฟองสบู่, นับเรือ, ทานของอร่อยๆ... และอีกหลายอย่างที่ใหม่สำหรับฉัน!",
  str_voice_1602231_27 = "การเกิด, การตาย, ความเจ็บป่วย, ความแก่, ชื่อเสียงและความร่ำรวย... บางสิ่งฉันไม่สามารถควบคุมได้ แต่ผู้ติดตามของฉันยังขอให้ฉันทำเหล่านั้นเสมอ",
  str_voice_1602231_28 = "ฉันได้ยินเสียงของสิ่งมีชีวิตโบราณ... สัตว์ยิ่งใหญ่ของ Eraveil คุณต้องการจะบอกอะไรฉันหรือ? คุณต้องการพูดถึงความรุ่งโรจน์ในอดีต หรือเพื่อนที่ยังอยู่ในปัจจุบันหรือ?",
  str_voice_1602231_29 = "โค้งต่อหน้าฉัน ผู้ติดตามของฉัน... อ๊ะ นั่นแค่คำพูดที่แสดงออกมาเท่านั้น ฉันไม่ได้หมายความว่าคุณต้องคุกเข่าลง! ฉันได้ห่างหายไปนาน แต่ยังคงรู้สึกอ embarrassed ทุกครั้งที่เห็นคนที่ฉันรู้จักทำแบบนั้น...",
  str_voice_1602231_30 = "อีกเครื่องบรรณาการหนึ่งให้ฉันเหรอ?",
  str_voice_1602231_31 = "ความรู้แจ้งจงเป็นของฉัน",
  str_voice_1602231_32 = "กอดรับการเกิดใหม่",
  str_voice_1602231_33 = "เมดมังกรกลับมาแล้ว",
  str_voice_1602231_34 = "คุณต้องการอะไร?",
  str_voice_1602231_35 = "จงเชื่อฟังพระประณามของเมดมังกร",
  str_voice_1602231_36 = "ให้ฉันนำทางให้เถิด!",
  str_voice_1602231_37 = "พระเจ้าทรงประสงค์—เปลี่ยนแปลง!",
  str_voice_1602231_38 = "ความมุ่งมั่นของมังกรที่เร่ร่อน—ฟ้าคำรน!",
  str_voice_1602231_39 = "จงสงบสุขนะ ทะเลที่วุ่นวาย!",
  str_voice_1602231_40 = "เกล็ดสีทอง ยังคงคลื่น!",
  str_voice_1602231_41 = "สัมผัสพรจากมังกร!",
  str_voice_1602231_42 = "คุณทุกคนออกจากเรือมาถึงฝั่งอย่างปลอดภัยหรือยัง? ฉันรู้ว่าเราจะทำได้!",
  str_voice_1602231_43 = "มีวันที่สั้นและยาว ดวงจันทร์มีระยะเวลาของการเสื่อมและเติบโต ไม่เป็นไรนะ",
  str_voice_1602231_44 = "ดีใจที่ฉันดูเหมือน Aurorian ไม่เช่นนั้นฉันอาจจะไม่สามารถผสมผสานได้บนเรือนี้",
  str_voice_1602231_45 = "ว้าว... อันนี้กินได้รึเปล่าน่ะ?",
  str_voice_1602231_46 = "เธอน่ารักจริง ๆ นะ! ฉันชอบมาก!",
  str_voice_1602231_47 = "สมบัติหายากแบบนี้นะ! ขอให้มาเรื่อย ๆ นะ!",
  str_voice_1602231_48 = "โอ้, สิ่งนี้ทำให้ฉันรู้สึกดีมาก! ฉันสัญญาว่าจะทะนุถนอมมันไปตลอดไป!",
  str_voice_1602231_49 = "ทุกสิ่งในหลงโจวล้วนมาจากพระเจ้าแรกเริ่ม ในฐานะญาติใกล้ของผู้สร้างที่ยิ่งใหญ่ ฉันไม่เห็นความแตกต่างระหว่างออโรเรียน, อสูร, หรือแม้กระทั่งนกและสัตว์เดรัจฉาน",
  str_voice_1602231_50 = "ออโรเรียนและอสูรเคยอยู่ร่วมกันอย่างสามัคคี ในปีแรกๆ ของ Longzhou ออโรเรียนขึ้นอยู่กับอสูรที่มีอำนาจมาก และได้สรรเสริญพวกเขาเป็นสัญลักษณ์ที่นับถือ ในขณะเดียวกัน อสูรได้ให้ออโรเรียนเจริญรุ่งเรืองในแผ่นดินแห้งแล้งนั้นและสร้างชาติแรกของพวกเขา",
  str_voice_1602231_51 = "ฉันใช้เวลามากมายในการหลับในความลึกของมหาสมุทร โดยเฉพาะอย่างยิ่งในการช่วยเหลือผู้ที่อยู่ในภาวะจะถูกคลื่นกลืนกลายเป็นครั้งคราว อย่างไรก็ตาม ชาว Aurorian ที่อาศัยอยู่บนชายฝั่งได้สร้างวัดในนามของฉันและได้สักการะฉันเป็นเทพี... วิธีเดียวที่ฉันสามารถสร้างความน่าเชื่อถือให้กับฉายาที่พวกเขาให้ฉันคือการทำทุกอย่างที่ฉันสามารถเพื่อปกป้องและช่วยเหลือพวกเขาเมื่อไรก็ตามที่ฉันสามารถทำได้.",
  str_voice_1602231_52 = "Alchemy Stars",
  str_voice_1602231_53 = "เยาวชน PlayerName!",
  str_voice_1602231_54 = "อ๊ะ... เช้าจังเลย...",
  str_voice_1602231_55 = "บนฝั่งมีอะไรสนุก ๆ ให้ทำมั้ย?",
  str_voice_1602231_56 = "ดึกขนาดนี้แล้ว คุณต้องการพรจากฉันเพื่อช่วยให้คุณหลับไหม?",
  str_voice_1602231_57 = "ถึงแม้ฉันจะเคยเห็นการเริ่มต้นของปีใหม่อย่างไม่นับจำนวน แต่นี่คือครั้งแรกที่ฉันได้ใช้เวลาในวันปีใหม่กับคุณ! คุณต้องการพรประเภทไหน? ฉันสามารถมอบพรของมังกรศักดิ์สิทธิ์ให้คุณได้นะ",
  str_voice_1502241_1 = "ถ้าคุณเจอเพื่อนรักที่ยุ่งยากในการเดินทางรอบ ๆ หลงโจว แค่บอกฉัน แล้วฉันจะดูแลพวกมันให้คุณ",
  str_voice_1502241_2 = "คุณต้องระวังนักต้มตุ๋นที่กำลังมองหาเหยื่อง่ายๆ คุณรู้ว่าฉันหมายถึงคนแบบไหน - คนที่พูดเรื่องกรรม, หยินหยาง, โชคดีและทั้งหมด แต่ไม่ทำอะไรเพื่อคุณเลย... ฉันกำลังพูดถึงใคร? อืม, ไม่มีใครเฉพาะเจาะจงเลย.",
  str_voice_1502241_3 = "คุณจะได้ยินเรื่องราวที่แปลกประหลาดเกี่ยวกับอสูรในชนบทของหลงโจว ฉันคิดว่าส่วนใหญ่ของเรื่องราวนั้นเป็นเรื่องโกหก แต่อย่างไรก็ตาม ส่วนใหญ่ของอสูรมีสิ่งที่ดีกว่าที่จะทำมากกว่าบางสิ่งที่คนกล่าวหาพวกเขา",
  str_voice_1502241_4 = "นี่คืออาดิง ตัวเล็กที่ฉันมักจะเลือกให้ลงสนามต่อสู้ ฉันต้องเลือกมันลงสนามเสมอ... มิฉะนั้นมันจะได้ฝึกการชนหัวอย่างไรล่ะ?",
  str_voice_1502241_5 = "ฉัน? นักฝึก? ฉันเดาว่านั่นคือสิ่งที่คุณเรียกมันในต่างประเทศ แน่นอนฉันชอบที่จะเป็นนักฝึกอสูร มันแน่นอนง่ายกว่าการสอนออโรเรียน",
  str_voice_1502241_6 = "ตัวปีศาจเล็กๆ อย่างอาห์ดิงจำเป็นต้องฝึกฝนนานเพื่อที่จะสามารถเปลี่ยนร่างเป็นออโรเรียน นานแค่ไหนหรือ? มันจะต้องใช้เวลาอย่างน้อยหลายร้อยปีนะ",
  str_voice_1502241_7 = "แม้ว่าคุณจะไม่มีความสามารถพิเศษในการใช้ลูมินาติกส์ ไม่ต้องให้สิ่งนั้นทำให้คุณเสียใจ คุณมีสุขภาพดี ร่างกายแข็งแรง ว่องไว และมือเร็ว ความสามารถเหล่านี้ถ้าคุณฝึกฝนอย่างต่อเนื่อง แน่นอนว่าคุณจะสามารถทำให้ตัวเองประสบความสำเร็จในวันหนึ่ง!",
  str_voice_1502241_8 = "ฉันไม่ได้มีความสามารถพิเศษ แต่เทคนิคศิลปะการต่อสู้ที่ฉันพัฒนามาเป็นเวลาหลายปีนั้นมีพลังมาก!",
  str_voice_1502241_9 = "อยากมาฝึกซ้อมกับอาดิงและคนอื่น ๆ หรือเปล่า? ฮ่า คุณไม่จำเป็นต้องตบเลย—แค่เอาพวกเขาขึ้นแล้วทิ้งพวกเขาออกไป!",
  str_voice_1502241_10 = "ขอโทษค่ะ อาดิงกับคนอื่น ๆ รบกวนคุณหรือไม่? ฉันจะบอกให้สัตว์เล็ก ๆ นั้นเงียบหน่อยนะคะ",
  str_voice_1502241_11 = "มีอะไรที่ฉันสามารถช่วยคุณได้...? คุณแค่อยากเลี้ยงเจ้าปีศาจเล็กๆ? ไปเถอะ พวกมันไม่กัด... แค่ว่ามันร้อนไปหน่อยเมื่อสัมผัส.",
  str_voice_1502241_12 = "ดังนั้น คุณไม่มีอะไรเหมือนอสูรในทวีปของคุณ เพียงแค่สัตว์ประหลาดที่สามารถใช้คาถาพลังงานและออโรเรียนที่มีหัวสัตว์ที่ไม่สามารถใช้คาถาพลังงานได้ดีเท่าไหร่... ถ้าฉันมีโอกาส ฉันอยากจะเห็นพวกเขา.",
  str_voice_1502241_13 = "หนังสือนิทานมักพูดถึงการฝึกฝนของอสูรเพื่อ \"เกินกว่าจุดสูงสุด\" มีความจริงบ้างในนี้ - \"เกินกว่าจุดสูงสุด\" หมายถึงการที่อสูรเรียนรู้วิธีควบคุมความสามารถของตนเองโดยไม่ทำลายตัวเองในกระบวนการ",
  str_voice_1502241_14 = "ฉันเคยอ่านว่าการศึกษาไม่รู้จักชั้นชั้น และอาจารย์ของฉันยังสอนฉันว่าทุกสิ่งที่มีชีวิตนั้นเท่าเทียมกัน ฉันเห็นด้วยกับหลักการนี้ - ไม่ว่าจะเป็นข้าราชการชั้นสูงหรือปีศาจน้อย คนดีควรได้รับรางวัล และคนชั่วควรถูกลงโทษ",
  str_voice_1502241_15 = "นี่คือของขวัญวันเกิดเล็กๆ ที่ฉันเตรียมให้คุณ! ของขวัญอื่นๆ นั้นหรือ? อ๋อ ดิ้งและคนอื่นๆ รวบรวมมันให้คุณ แค่จำไว้ว่าอย่ากินดิบนะ.",
  str_voice_1502241_16 = "ดูท้องฟ้าที่สมบูรณ์แบบนั้นสิ ดวงอาทิตย์กำลังส่องแสงอย่างสว่างสด! ปีศาจเล่นงานที่หวังจะมาก่อความวุ่นวายน่าจะไม่ค่อยเลือกเวลาแบบนี้มาทำความร้ายเลย",
  str_voice_1502241_17 = "สวัสดิ์ตอนเช้า! กำลังย้ายของบ้างหรือเปล่า? ฉันช่วยได้นะ อาดิงและคนอื่น ๆ ก็ยังสามารถช่วยหิ้วได้บ้างเหมือนกันนะ",
  str_voice_1502241_18 = "คุณมีโอกาสเจอกับวิญญาณชั่วร้ายหลังพระอาทิตย์ตกมากกว่าในช่วงกลางวัน",
  str_voice_1502241_19 = "Fiendlings ที่ยังไม่ได้เปลี่ยนร่างเป็น Aurorian มักจะกระทำตามสัญชาตญาณ ดังนั้นตอนกลางคืนเป็นเวลาที่พวกมันมีความกระฉับกระเฉงมากที่สุด",
  str_voice_1502241_20 = "หลงโจวเป็นแดนของยอดเขาที่สูงล้ำและมหาสมุทรที่กว้างใหญ่ และเป็นบ้านของเพื่อนรักมากกว่าที่คุณจะนับได้ในชีวิตเดียว",
  str_voice_1502241_21 = "ฉันได้ยินว่าสายพันธุ์ที่มีลักษณะคล้ายกับอสูรไม่ใช่เรื่องแปลกในทวีปของคุณ... จริงๆ แบบนี้หรือไม่?",
  str_voice_1502241_22 = "การกำจัดปีศาจและขับไล่วิญญาณชั่วร้าย นี่คือที่ที่ฝีมือของฉันโดดเด่น.",
  str_voice_1502241_23 = "อสูรมีความไวต่ออาร่าของวิญญาณชั่วร้ายมากกว่าออโรเรียน พวกเขาต้องเป็นอย่างนั้น มิฉะนั้นพวกเขาอาจจะกลายเป็นอาหารของวิญญาณชั่วร้ายได้",
  str_voice_1502241_24 = "เมื่ออาดิงสามารถครอบครองเฮดบัตต์เหล็กของเขาได้สุดท้าย ฉันจะต้องเริ่มคิดว่าควรจะสอนเขาอะไรต่อไป...",
  str_voice_1502241_25 = "คุณสามารถบอกได้ทันทีว่าปีศาจร้ายที่มีวัฒนธรรมเช่น Liqing ต้องได้รับการสอนจากอาจารย์ที่มีความสามารถอย่างมาก",
  str_voice_1502241_26 = "ต้องการแหนมากมั้ยครับเพื่อน?",
  str_voice_1502241_27 = "คนรวยคนหนึ่งเคยยืนยันว่าฉันต้องช่วยแมวของเขาล้ำขอบฟ้า ฉันบอกเขาว่าแมวของเขาเป็นแค่แมว ไม่ใช่ปีศาจเล็ก ๆ แต่เขาไม่ฟัง",
  str_voice_1502241_28 = "ฉันได้เดินทางไกลและเห็นสิ่งแปลกประหลาดมามากมาย แต่ฉันไม่เคยเห็นอะไรแบบนี้มาก่อน",
  str_voice_1502241_29 = "ลูโอะ ซง ยินดีให้บริการ—นักบวชผู้พเนจรจากภูเขา และเป็นผู้ที่ได้รับการฝึกในการสื่อสารกับปีศาจ นี่คืออาดิง และเหล่านี้คือเพื่อนร่วมทางของเขา",
  str_voice_1502241_30 = "การเพิ่มความแข็งแกร่งให้กับร่างกายควรเป็นสิ่งที่คุณให้ความสำคัญเป็นอันดับแรกเสมอ",
  str_voice_1502241_31 = "ถ้าเสื้อคลุมเหมาะ...",
  str_voice_1502241_32 = "ไม่เคยเป็นอันตรายที่จะห่อตรายางรางวัลเพิ่มเติมไว้บ้าง",
  str_voice_1502241_33 = "คุณไม่มีวิญญาณจากยันต์มากเกินไปเลย",
  str_voice_1502241_34 = "ตอนนี้, ใครที่ทำให้เกิดปัญหาที่นี่?",
  str_voice_1502241_35 = "นี่คือโอกาสของฉัน!",
  str_voice_1502241_36 = "อ๊ะ ดิง, ถึงเวลาของเราที่จะส่องแสงแล้ว.",
  str_voice_1502241_37 = "สวรรค์ไม่รอคอยใคร! สิ่งชั่วร้าย จงถูกชำระล้าง!",
  str_voice_1502241_38 = "เฮดบัตต์เหล็ก, พร้อมที่จะโจมตี!",
  str_voice_1502241_39 = "เฮดบัตต์อัคคีเผาไหม้!",
  str_voice_1502241_40 = "อ๊ะ ดิง! โจมตีตอนนี้!",
  str_voice_1502241_41 = "ชิ. การสังเกตคือกุญแจสู่ชัยชนะ",
  str_voice_1502241_42 = "เยี่ยม! และยังมีเวลาดื่มชาอยู่",
  str_voice_1502241_43 = "วิ่งไป! ฉันจะถ่วงพวกมันไว้",
  str_voice_1502241_44 = "อ๊ะ ดิง คุณควรรู้ดีว่าไม่ควรไปสอดรู้สอดเห็นในบ้านของคนอื่นนะ",
  str_voice_1502241_45 = "ขอบคุณมากค่ะ มีโอกาสที่สิ่งนี้อาจจะมีประโยชน์นะคะ",
  str_voice_1502241_46 = "สิ่งนี้อาจจะมีประโยชน์... แถม อาดิงก็ชอบมันจริงๆนะ",
  str_voice_1502241_47 = "ฉันยินดีที่จะรับมัน และฉันจะแน่นอนจะตอบแทนคุณในไม่ช้านี้",
  str_voice_1502241_48 = "ว้าว... คุณพบสิ่งสวยงามนี้ที่ไหน? เราไม่รอได้ที่จะได้ยินเรื่องราวทั้งหมดเลย!",
  str_voice_1502241_49 = "ฉันเติบโตขึ้นในวัด เมื่อฉันยังเป็นเด็ก พ่อแม่ของฉันคิดว่าการถูกผีเข้าสิงเป็นสาเหตุของการเจริญเติบโตที่ไม่สมบูรณ์ของฉัน แต่จริงๆ แล้วไม่ใช่เช่นนั้น",
  str_voice_1502241_50 = "ลูกศิษย์ชั้นสูงบนภูเขาไม่ได้สอนฉันมากนัก ในตอนที่ต้องเลือกระหว่างการเรียนรู้การทำตรายันกระดาษและการฝึกฝนศิลปะการต่อสู้ ฉันเลือกศิลปะการต่อสู้อย่างเป็นธรรมชาติ",
  str_voice_1502241_51 = "หลังจากลงจากภูเขา ฉันหาเลี้ยงชีพโดยปราบอสูรให้กับผู้ที่ขอ ในช่วงเวลานี้ฉันได้พบกับอาห์ดิงและสอนเขาว่าอย่าเหยียบทับพืชผลด้วยเท้าที่ร้อนของเขา รวมถึงเคล็ดลับการรอดชีวิตอื่น ๆ บ้าง",
  str_voice_1502241_52 = "Alchemy Stars",
  str_voice_1502241_53 = "ฉันมาแล้ว",
  str_voice_1502241_54 = "สวัสดีตอนเช้า คุณทานข้าวรึยังคะ?",
  str_voice_1502241_55 = "ขอบคุณที่อดทนกับอาดิงนะครับ",
  str_voice_1502241_56 = "ไว้เจอกัน ถ้าคุณว่างก็มาหาฉันนะ",
  str_voice_1502241_57 = "สวัสดีปีใหม่! ไม่ว่าคุณจะมาจากที่ไหน หรือคุณเป็นชาวออโรเรียนหรือไม่ ไม่ใช่เรื่องดีเหรอที่เรามาที่นี่รวมตัวกันแบบนี้?",
  str_voice_1701073_1 = "แปลก... ฉันมีฝันที่โหดร้ายมาเรื่อยๆ และมันชัดมาก อะไรนะ? คุณหมายความว่า ฝันที่ฉันเห็นอาจจะไม่ใช่ฝัน แต่เป็นความทรงจำที่ฉันลืมไปหรือ?",
  str_voice_1701073_2 = "อาดราส... นี่คือชื่อของฉันเหรอ? และคุณช่วยฉันค้นหามันอีกครั้ง ฉันควรจะบอกว่า... ขอบคุณนะ.",
  str_voice_1701073_3 = "สปิริตนักสู้ของ Silent Hunter ไม่มีวันถูกดับ ไม่ว่าจะเกิดอะไรขึ้น",
  str_voice_1701073_10 = "อ่อนเพลียจนพูดไม่ได้หรือ? คุณคงจะหิวมาก มีแป้งอยู่ไหม? ฉันยังจำวิธีทำขนมปังได้ และมันก็ดีไม่แพ้ขนมปังที่นี่เลย คุณอยากลองชิมไหม?",
  str_voice_1701073_11 = "ยินดีรับใช้ค่ะ",
  str_voice_1701073_12 = "ภัยคุกคามที่ใหญ่ที่สุดต่อโลกยังไม่ได้เปลี่ยนแปลง... ไม่ใช่หรอก ฉันไม่ได้พูดถึงอิคลิพไซท์",
  str_voice_1701073_13 = "การปกป้องผู้คนเป็นจุดมุ่งหมายในชีวิตของฉัน แม้จะมีความเศร้าในอดีต ฉันจะไม่ยอมแพ้",
  str_voice_1701073_14 = "คุณรู้จักกลิ่นของข้าวสาลีที่โตเต็มที่หรือไม่? กลิ่นที่หวานและเบา ๆ ซึ่งทะลุจมูกในความร้อน มันเป็นความรู้สึกที่ฉันไม่สามารถฝันถึงได้อีกต่อไป",
  str_voice_1701073_16 = "อย่าประมาทแม้ว่าอิคลิพไซท์จะไม่ปรากฏตัว การปกป้องคุณคือหน้าที่สำคัญของฉันในตอนนี้ PlayerName",
  str_voice_1701073_17 = "อรุณสวัสดิ์! มาเผชิญหน้ากับวันใหม่ในสภาพจิตใจที่สดใสกับฉันสิ!",
  str_voice_1701073_18 = "ต้องระวังมากขึ้นเมื่อคืนลงมา แต่นั่นเป็นหน้าที่ของฉัน ส่วนคุณ หน้าที่ของคุณคือการพักผ่อนให้เต็มที่",
  str_voice_1701073_19 = "ฝันดีนะ แม้แต่ฝันร้ายยังไม่กล้าเข้ามาเมื่อฉันยืนเฝ้ารักษา",
  str_voice_1701073_35 = "มาที่ฉัน!",
  str_voice_1701073_36 = "อย่าพยายามหยุดฉัน!",
  str_voice_1701073_37 = "พยายามหนีหรือ? ลองอีกครั้งสิ!",
  str_voice_1701073_38 = "ยอมแพ้เรามาสายเกินไปแล้ว!",
  str_voice_1701073_39 = "มาสู้กัน!",
  str_voice_1701073_40 = "บุก!",
  str_voice_1701073_44 = "จะปลูกข้าวสาลีที่นี่ได้ไหมนะ?",
  str_voice_1701073_58 = "อิคลิพไซท์ไม่ใช่อะไรมากกว่าสัตว์ที่มีกำลังแต่ขาดสมอง",
  str_voice_1701073_59 = "อย่าทิ้งช่องโหว่ให้ใครได้รับประโยชน์",
  str_voice_1701073_60 = "ไม่มีความเสียใจในชีวิต",
  str_voice_1701073_61 = "รักษาคนที่คุณรักด้วยความเอื้อเฟื้อ อย่ามีสิ่งที่เสียใจ.",
  str_voice_1701073_62 = "อมตะคือการลงโทษของฉัน",
  str_voice_1701073_63 = "ความบ้าคลั่นเคยเป็นข้ออ้างของฉัน",
  str_voice_1701073_64 = "อาจจะยังไม่สามารถปกป้องทุกคนด้วยตัวเองได้ แต่ตอนนี้ฉันมีคุณแล้ว",
  str_voice_1701073_65 = "ร่องรอยของบ้านเกิดของฉันได้ถูกลบล้างจากแผ่นดินนี้แล้ว...",
  str_voice_1701073_66 = "เวลาจะรักษาบาดแผลทุกอย่าง ฉันเป็นแค่อาดราสตอนนี้",
  str_voice_1701073_67 = "ฉันเคยสาบานในโบสถ์มาก่อน",
  str_voice_1701073_68 = "ฉันไม่สามารถมาสายในวันสำคัญที่สุดได้!",
  str_voice_1701073_69 = "อย่าทำให้ฉันกังวลนะ มาร์เซลาที่รัก...",
  str_voice_1701073_70 = "มันเป็นเพราะฉันหรือเปล่า? ทำไมทุกคนถึงมองฉันแบบนั้นล่ะ?",
  str_voice_1701073_71 = "ฉัน... ไม่มีประโยชน์สำหรับใครเลยใช่ไหม...?",
  str_voice_1701073_72 = "การมีมาร์เซลาอยู่ข้างๆฉันก็เพียงพอแล้ว",
  str_voice_1701073_73 = "ทำไมถึงเป็นแบบนี้ไปได้? ไม่, ไม่...",
  str_voice_1701073_74 = "อย่าเข้ามาใกล้! ปล่อยฉันไป... ปล่อยฉันออกไป!",
  str_voice_1701073_75 = "ไปที่ไหนต่อดี? ที่ไหนคือแผนการเดินทางของฉัน?",
  str_voice_1701073_76 = "หนึ่ง สอง สาม... สี่!",
  str_voice_1701073_77 = "ว่ายังไง",
  str_voice_1701073_78 = "มีอะไรผิดป่ะ? ไม่ต้องห่วงนะ ฉันจะจัดการเอง!",
  str_voice_1600264_1 = "ชุดของฉันจะลุกเป็นไฟเมื่อยาหมดอายุ คุณจะตามรอยไฟที่เหลือมาหาฉันไหม?",
  str_voice_1600264_2 = "คุณต้องการที่จะดื่มยานั้นด้วยหรือ? ไม่นะ ฉันชอบคุณในแบบที่คุณเป็นตอนนี้",
  str_voice_1600264_3 = "คุณต้องการอยู่ในลิมโบกับฉันหรือไม่? จับมือฉันเถอะ แล้วปล่อยให้ความหวังของเราเผาไหม้สว่าง!",
  str_voice_1600264_10 = "อย่าไป! ไม่งั้น เมื่อคุณกลับมา อาจจะมีแต่เถ้าถ่านที่เหลือ...",
  str_voice_1600264_11 = "ไม่มีจุดประสงค์ในการมีอยู่ แต่คุณทำให้ฉันอยู่ที่นี่และทำให้มันมีความหมาย... *หืด*",
  str_voice_1600264_12 = "คุณชอบแสงริบหรี่ที่น่าสงสารหรือเปลวไฟที่กลืนกินทุกอย่าง...? รอสักครู่! ถ้าคำตอบของคุณไม่ถูกต้อง ยานั้นจะไม่ทำงานอีกต่อไป",
  str_voice_1600264_13 = "วันสิ้นโลกหรือ? ฉันไม่สนใจเรื่องพวกนั้น... ทุกอย่างจะจบลงในที่สุด ดังนั้นเราควรจะมีความเป็นอิสระมากขึ้นบ้าง",
  str_voice_1600264_14 = "ถ้าคุณสามารถทนต่อหัวใจที่ร้อนแรงและความมุ่งมั่นที่ลุกโชนได้ ฉันไม่มีปัญหาที่จะให้มันแก่คุณ ไม่ ฉันยังไม่ได้ดื่มยามากเกินไป...",
  str_voice_1600264_16 = "ยินดีต้อนรับสู่อีกหนึ่งวันที่ว่างเปล่า! มาทำให้มันมีความหมายกันเถอะ ใช่ไหมล่ะ?",
  str_voice_1600264_17 = "คุณจะงีบต่อหรือไม่ หรือฉันควรจะสร้างฝันให้คุณ?",
  str_voice_1600264_18 = "เวลาทานอาหารเย็นหรือ? มากกว่าอาหาร ฉันสนใจในคนที่ถือจานอยู่หน้าฉันมากกว่า",
  str_voice_1600264_19 = "โอย, ฉันดื่มยาแล้วฉันกลายเป็นคนใหม่, แต่ทำไมหน้าอกฉันยังเจ็บอยู่? (สะอื้น) โอ้, ช่วยฉันด้วย...",
  str_voice_1600264_35 = "ประตูสู่ Limbo ได้ถูกเปิดแล้ว!",
  str_voice_1600264_36 = "จับมือฉันให้แน่น—",
  str_voice_1600264_37 = "เราจะไปถึงปลายทางแห่งนรกด้วยกัน",
  str_voice_1600264_38 = "มาเดินทางไปสู่สุดขอบโลกด้วยกันเถอะ",
  str_voice_1600264_39 = "วัลแคน!",
  str_voice_1600264_40 = "ลิมโบ้กำลังลุกโชติช่วง!",
  str_voice_1600264_44 = "ฉันสามารถรอจนถึงสิ้นสุดของเวลากับคุณที่นี่ได้ไหม?",
  str_voice_1600264_58 = "อรุณสวัสดิ์! ฉันกำลังทำอย่างที่สุดเพื่อเพิ่มความกระปรี้กระเปร่าให้ตัวเอง.",
  str_voice_1600264_59 = "คุณได้เห็นพระอาทิตย์ขึ้นเช้านี้ไหม?",
  str_voice_1600264_60 = "คุณมาหาฉันได้ไหม",
  str_voice_1600264_61 = "(หาว) อืมม...",
  str_voice_1600264_62 = "ราตรีสวัสดิ์...",
  str_voice_1600264_63 = "จะเข้านอนแล้วหรือ?",
  str_voice_1600264_64 = "อีกวัน, อีกพระอาทิตย์ลับฟ้า...",
  str_voice_1600264_65 = "\"คาดหวังในวันพรุ่งนี้\"? แสดงให้ฉันเห็น...",
  str_voice_1600264_66 = "ฉันรู้สึกเจ็บในหน้าอกอีกครั้ง...",
  str_voice_1600264_67 = "ฉันซื้อของขวัญให้เธอเป็นการขอโทษ...",
  str_voice_1600264_68 = "คุณจำได้ไหมว่าพ่อแม่คุณหน้าตาเป็นอย่างไร?",
  str_voice_1600264_69 = "รู้สึกสบายกว่าที่จะอยู่ใน Colossus ของคุณ มากกว่าในบาร์เรลป้องกันการระเบิดครับ",
  str_voice_1600264_70 = "มีหนังสือคาถาที่ดีที่คุณแนะนำไหม?",
  str_voice_1600264_71 = "ยาใหม่น่าจะพร้อมในไม่ช้า!",
  str_voice_1602251_1 = "แม้ว่านอร์ธแลนด์จะกว้างใหญ่ขนาดไหน ก็ไม่มีใครที่จะเป็นภัยต่อองค์ราชินีจริง ๆ แต่ในฐานะทหารยามของเธอ ฉันจะยังทำหน้าที่ปกป้องเธออย่างเต็มที่",
  str_voice_1602251_2 = "การอยู่ในป่าและซ่อนตัวในหิมะเป็นสัญชาตญาณของฉัน แต่เมื่อคืนมืดลง ฉันจะปีนขึ้นยอดไม้ที่สูงที่สุดและเผยตัวต่อทัศนียภาพที่กว้างใหญ่ของนอร์ธแลนด์",
  str_voice_1602251_3 = "ฉันชอบดูคนที่สไลด์บนหิมะโดยไม่รู้ตัว พวกเขามักจะตื่นตระหนกและฉันก็หยุดไม่ได้ที่จะขำจากที่ซ่อนอยู่ คุณเข้าใจความตลกของฉันไหม?",
  str_voice_1602251_4 = "เลือดแห่งนอร์ธแลนด์ไหลอยู่ในเส้นเลือดของฉัน ดังนั้นเมื่อฉันเดินบนหิมะด้วยเท้าเปล่า ฉันไม่รู้สึกหนาวแต่รู้สึกถึงพลังของแผ่นดินแทน",
  str_voice_1602251_5 = "คุณอาจจะรู้ได้ว่าฉันเป็นนักล่าที่ดี ไม่ว่าจะไล่ล่าหรือหลบซ่อน ฉันสามารถจับโอกาสที่ดีที่สุดและทำให้เหยื่อของฉันเสียชีวิตได้เสมอ!",
  str_voice_1602251_6 = "คุณเคยเห็นประภาคารแล้วใช่ไหม? คนแก่บอกว่าประภาคารและสามต้นไม้โบราณในนอร์ธแลนด์มีความเชื่อมโยงกัน แต่เธอเพียงแค่มองไปที่ทิศทางไกลๆ และไม่ตอบอะไรเมื่อฉันถามเธอเกี่ยวกับสิ่งนี้",
  str_voice_1602251_7 = "คุณวิ่งช้าจริงๆ ฉันอาจจะต้องแบกคุณไว้บนหลังเลย! ไม่ต้องห่วง, ในฐานะองครักษ์ขององค์ราชินี มันเป็นหน้าที่ของฉันที่จะดูแลเพื่อนของเธอด้วย!",
  str_voice_1602251_8 = "การโหยหวนที่ฟ้าคือวิธีที่เราแสดงความสุขและความเศร้า... คุณสามารถบอกความแตกต่างได้หรือไม่? ถ้างั้น ทำไมคุณไม่ลองโหยหวนสองสามครั้งให้ฉันฟังดูล่ะ?",
  str_voice_1602251_9 = "ฉันชอบมองเห็นแสงออโรร่าจากเผ่าพันธุ์มากกว่าที่พระราชวังฤดูหนาว ที่อยู่ใกล้แดนแดนนั้นทำให้ฉันรู้สึกเหมือนมันเป็นของฉันเพียงผู้เดียว คุณอยากจะมาดูมันกับฉันไหม?",
  str_voice_1602251_10 = "เคยมีช่วงเวลาที่ฉันไม่สามารถจับกระต่ายได้ แม้ฉันจะพยายามอย่างหนัก และมันยังมองกลับมาเหมือนกำลังล้อเลียนฉัน! ภายหลังฉันจึงรู้ว่ามันเป็นของคุณโนวิโอ...",
  str_voice_1602251_11 = "คุณกำลังพยายามจ้างฉันเป็นยามที่นี่หรือ? ยกเลิกความคิดนั้นทันทีเถอะ! โอ้ คุณแค่อยากให้ฉันเป็นแขกรับเชิญ? นั่นก็ดี ฉันไม่มีปัญหากับสิ่งนั้น.",
  str_voice_1602251_12 = "สวัสดีเพื่อนๆ ในป่า อยากเล่นเกมกันไหม? อ้าว ทำไมถึงวิ่งหนีไปล่ะ? ฉันแค่ล้อเล่น...",
  str_voice_1602251_13 = "ชู้, เห็นไอ้หนุ่มเจ้าเล่ห์ข้างหลังหินนั้นไหม? มาทำให้มันตกใจกันที่สาม! หนึ่ง - เฮ้ย, ทำไมคุณไม่ปฏิบัติตามแผนของฉันล่ะ?!",
  str_voice_1602251_14 = "เราเชื่อว่าทุกอย่างมีจิตวิญญาณ ดังนั้นเรามีตำนานที่น่าทึ่งมากมายในนอร์ธแลนด์ คุณเคยได้ยินตำนานเรื่องสามต้นสนหรือยัง? มันเกี่ยวข้องกับการกำเนิดของนอร์ธแลนด์เ supposedly",
  str_voice_1602251_15 = "สุขสันต์วันเกิด! ตามประเพณีของเผ่าพันธุ์ เราต้องขอแสดงความยินดีกับริ้วรอยใหม่ของคุณด้วยนะ",
  str_voice_1602251_16 = "สมเด็จพระราชินีไม่อยู่วันนี้ ดังนั้นเธอให้ฉันหยุดวันนี้ คุณคิดว่าเราควรทำอะไรดีคะ?",
  str_voice_1602251_17 = "ว้าว, ฉันเพิ่งสังเกตว่ามีชั้นของน้ำแข็งบนตัวฉัน ฉันต้องทำตัวให้ดูดีก่อนที่จะไปพบพระบาทสมเด็จพระเจ้าอยู่หัว!",
  str_voice_1602251_18 = "ฉัน...ฉันกำลังไล่ตามชาว Aurorian ที่วิ่งเร็วที่สุดใน Northland! ฉันต้องจับเขาได้ไม่ว่าอะไรจะเกิดขึ้น!",
  str_voice_1602251_19 = "คนที่มักอ้างว่าตัวเองยุ่งหรือเหนื่อยเสมอ ไม่รู้ว่าพวกเขาพลาดวิวทิวทัศน์สวยงามเท่าไหร่",
  str_voice_1602251_20 = "โลกนอกจากนอร์ธแลนด์อาจจะมีเหตุการณ์เยอะแยะ แต่ฉันยังคงชอบความเรียบง่ายและความเสรีที่นี่มากกว่า",
  str_voice_1602251_21 = "โง่, บอกเพื่อนของคุณที่มีสิ่งแปลกๆ อยู่บนตัวให้อยู่ห่างจากคนแก่นะ!",
  str_voice_1602251_22 = "เมื่อเหมันต์ผันผ่าน เราจักกำเนิดใหม่อีกครั้ง",
  str_voice_1602251_23 = "พวกเขาได้เอาสิ่งมีค่าไปจากฉัน... ดังนั้นฉันเข้าใจคุณ พวกเราจะไปเอาคืนมาด้วยกัน!",
  str_voice_1602251_24 = "องค์ราชินีมีพลังอย่างยิ่ง การเป็นองครักษ์ของเธอคือความภาคภูมิใจที่ยิ่งใหญ่ที่สุดของฉัน",
  str_voice_1602251_25 = "บางครั้ง ฉันต้องต่อสู้กับตัวเองอย่างหนักเพื่อไม่เรียกผู้ใหญ่ว่า \"ย่า\" มันเป็นแค่ความรู้สึกที่ฉันได้จากพวกเขา",
  str_voice_1602251_26 = "การปีนต้นไม้, การล่าสัตว์, การวิ่งผ่านหิมะ... มีเพื่อนคุณชอบทำสิ่งเหล่านี้หรือไม่?",
  str_voice_1602251_27 = "คนแปลกหน้าที่บุกรุกเข้ามาในเผ่าของฉัน ควรได้รับมากกว่าแค่การโดนตี!",
  str_voice_1602251_28 = "ทุกอย่างที่นี่ดูอบอุ่นและสบาย แต่ยังขาดความเป็นธรรมชาติแบบป่าเถื่อนอยู่บ้างนะ",
  str_voice_1602251_29 = "ฉันคือเทียเร่, การ์ดของราชินีแห่งนอร์ธแลนด์ และผู้นำของเผ่าหมาป่าหิมะ ขอเตือนว่า นอร์ธแลนด์ไม่ใช่สนามเด็กเล่น และเผ่าของเราไม่ใช่สถานที่ที่คุณสามารถเข้าไปได้ตามความสะดวก!",
  str_voice_1602251_30 = "นี่คือความรู้สึกของพลังแห่งธรรมชาติใช่ไหม?",
  str_voice_1602251_31 = "ฉันรู้สึกใจร้อนจังเลยนะ!",
  str_voice_1602251_32 = "ฉันคือผู้คุ้มครองขององค์ราชินี!",
  str_voice_1602251_33 = "ฉันคือผู้พิทักษ์แห่งนอร์ธแลนด์!",
  str_voice_1602251_34 = "เทียเร่, พร้อมรับบัญชาค่ะ!",
  str_voice_1602251_35 = "เต็มพลังแล้ว!",
  str_voice_1602251_36 = "ตามฉันมานะ!",
  str_voice_1602251_37 = "เพื่อความสงบสุขในนอร์ธแลนด์!",
  str_voice_1602251_38 = "โจมตี, พลังแห่งธรรมชาติ!",
  str_voice_1602251_39 = "พวกแกหนีไม่พ้นหรอก!",
  str_voice_1602251_40 = "อิคลิพไซท์งี่เง่า!",
  str_voice_1602251_41 = "ฉันจะปกป้องคุณค่ะ!",
  str_voice_1602251_42 = "สมเด็จพระราชินีจะดีใจมาก!",
  str_voice_1602251_43 = "อย่าบอกสมเด็จย่าในช่วงเวลานี้นะ",
  str_voice_1602251_44 = "ไม่ใช่ฉันนะ! เอ่อ, ฉันหมายความว่า, ฉันไม่ได้ยินเสียงอะไรแปลกๆเลย.",
  str_voice_1602251_45 = "นี่ใช้ทำอะไรล่ะ?",
  str_voice_1602251_46 = "ชอบมาก!",
  str_voice_1602251_47 = "คุณมีของเล็ก ๆ น้อย ๆ เยอะจริง ๆ นะ!",
  str_voice_1602251_48 = "ฉันรักมันมากๆ!",
  str_voice_1602251_49 = "ฉันเกิดในเผ่าชายแดนและโตที่นี่กับยายและสุนัขหิมะ ส่วนพ่อแม่ของฉัน ฉันรู้แค่ว่าพวกเขาเป็นทหารยามนอร์ธแลนด์ที่ยอดเยี่ยม",
  str_voice_1602251_50 = "ราชินีช่วยฉันรอดจากหิมะถล่มและซ่อมหอกของฉัน ฉันจึงตัดสินใจที่จะรับใช้องค์ราชินีโดยไม่มีเงื่อนไขตั้งแต่จุดนั้นเป็นต้นไป",
  str_voice_1602251_51 = "ฉันยังจำคืนนั้นได้ ฉันและผู้ใหญ่ยังคงอยู่เงียบๆ ในถ้ำท่ามกลางเสียงคำรามของสุนัขจิ้งจอก ฉันยังไม่เข้าใจว่าความหมายของการปกป้องคืออะไรในตอนนั้น",
  str_voice_1602251_52 = "Alchemy Stars",
  str_voice_1602251_53 = "ตอนนี้...",
  str_voice_1602251_54 = "อรุณสวัสดิ์",
  str_voice_1602251_55 = "สวัสดียามบ่าย",
  str_voice_1602251_56 = "ราตรีสวัสดิ์",
  str_voice_1602251_57 = "สวัสดีปีใหม่ ขอให้นอร์ธแลนด์และราชินีคอยดูแลคุณต่อไป",
  str_voice_1202261_1 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_2 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_3 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_4 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_5 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_6 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_7 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_8 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_9 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_10 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_11 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_12 = "คริ๊ก! คริ๊ก!",
  str_voice_1202261_13 = "คริ๊ก! คริ๊ก!",
